<?php
/**
 * Template Name: Usuario POS 2
 */

// 🔥 增加PHP执行时间和内存限制（Hostinger共享主机默认值太低）
@set_time_limit(120);
@ini_set('max_execution_time', '120');
@ini_set('memory_limit', '512M');

// 🔥 权限检查必须在 get_header() 之前，避免HTML输出冲突
// Bloquear acceso a usuarios no autenticados
if (!is_user_logged_in()) {
    wp_redirect(home_url('/'));
    exit;
}

// Verificar roles permitidos - Allow all logged-in users to create orders
$user = wp_get_current_user();
// Allow broader access: any user with edit_posts capability, administrator role, or shop_manager role
if (!current_user_can('edit_posts') && !in_array('administrator', $user->roles) && !in_array('shop_manager', $user->roles)) {
    wp_logout();
    wp_redirect(home_url('/?denied=1'));
    exit;
}

// 权限验证通过后，再加载页面头部
get_header();

if (isset($_POST['guardar_ajustes_pos']) && check_admin_referer('guardar_ajustes_pos')) {
  $nuevo_valor = floatval($_POST['pos_initial_amount']);
  update_option('pos_initial_amount', $nuevo_valor);
  wp_redirect(add_query_arg('ajuste_guardado', '1', wp_get_referer()));
  exit;
}

// Check if user is a shop manager or administrator
$is_shop_manager = in_array('shop_manager', $user->roles);
$is_administrator = in_array('administrator', $user->roles);

// 🔥【2026-04-07】shop_manager 权限相关变量必须在文件顶部声明，否则在模板字符串中使用会得到 null
// （PHP 没有变量 hoisting，使用必须晚于声明）
$_sm_show_trash_top = get_option('pos_sm_show_trash', '0') === '1';
$show_trash_icon = !$is_shop_manager || $_sm_show_trash_top;

// 检查WooCommerce是否激活
if (!function_exists('wc_get_products')) {
    wp_die('❌ WooCommerce插件未安装或未激活。POS系统需要WooCommerce支持。', 'WooCommerce Required', ['response' => 503]);
}

// Obtener categorías de productos y productos
$product_categories = get_terms('product_cat', ['hide_empty' => true]);
$products = wc_get_products(['limit' => -1, 'status' => 'publish']);

// Add tax rate data to each product using custom tax rate function
foreach ($products as $product) {
    // Use our custom tax rate function
    $tax_rate = ruiyi_get_product_tax_rate($product);

    // Store tax rate on product object for later use (use meta to avoid PHP 8.2 dynamic property deprecation)
    $product->update_meta_data('_ruiyi_tax_rate', $tax_rate);
}

// 🔥 Suplementos 分类检测
$suplementos_category = get_term_by('slug', 'suplementos', 'product_cat');
$suplementos_products = [];
$show_suplementos = false;

if ($suplementos_category) {
    // 🔥 从缓存过滤，不再重复查询数据库
    $suplementos_products = wc_get_products([
        'category' => [$suplementos_category->slug],
        'limit' => -1,
        'status' => 'publish'
    ]);

    // 过滤价格大于0的产品并添加税率
    $filtered_suplementos = [];
    foreach ($suplementos_products as $product) {
        if ($product->get_price() > 0) {
            $tax_rate = ruiyi_get_product_tax_rate($product);
            $product->update_meta_data('_ruiyi_tax_rate', $tax_rate);
            $filtered_suplementos[] = $product;
        }
    }
    $suplementos_products = $filtered_suplementos;
    $show_suplementos = count($suplementos_products) > 0;
}

// Obtener clientes
$customers = get_users(['role__in' => ['customer', 'subscriber']]);

// 获取积分汇率设置
$points_max_discount = intval(get_option('ruiyi_points_max_discount', 10)); // 最大折扣百分比，默认10%
$points_reward_rate = intval(get_option('ruiyi_points_reward_rate', 15)); // 奖励积分百分比，默认15%

// 辅助函数：获取多语言分类名称
if (!function_exists('get_multilingual_category_name')) {
function get_multilingual_category_name($category_term, $lang = null) {
  // 🔥 如果设置为使用默认分类语言，直接返回原名称
  static $use_default = null;
  if ($use_default === null) {
    $use_default = get_option('pos_category_use_default_lang', '0') === '1';
  }
  if ($use_default) {
    return $category_term->name;
  }

  if (!$lang) {
    $lang = defined('RUIYI_CURRENT_LANG') ? RUIYI_CURRENT_LANG : 'zh';
  }

  // 根据语言获取对应的翻译
  $translated_name = '';
  if ($lang === 'en') {
    $translated_name = get_term_meta($category_term->term_id, 'category_name_en', true);
  } elseif ($lang === 'es') {
    $translated_name = get_term_meta($category_term->term_id, 'category_name_es', true);
  } elseif ($lang === 'zh') {
    $translated_name = get_term_meta($category_term->term_id, 'category_name_zh', true);
  }

  // 如果翻译存在则使用翻译，否则使用原名称
  return !empty($translated_name) ? $translated_name : $category_term->name;
}
} // end function_exists

// Generar un nonce para la seguridad en las peticiones AJAX
$ajax_nonce = wp_create_nonce('ruiyi_pos_nonce');
$pos_number_of_tables = get_option('pos_tables_count', 25); // Default to 25 tables

// 🔥 获取产品每行显示数量设置
$pos_products_per_row = intval(get_option('pos_products_per_row', 6));
$pos_products_per_row = max(3, min(8, $pos_products_per_row)); // 限制范围 3-8

// 🔥 获取产品亮色模式设置（默认暗色模式）
$pos_product_light_mode = get_option('pos_product_light_mode', '0') === '1';

// 🔥 获取商店管理员产品编辑锁定设置
$pos_lock_shop_manager_edit = get_option('pos_lock_shop_manager_edit', '0') === '1';

// 🔥 获取分类自由价格产品设置（默认关闭）
$pos_category_price_product = get_option('pos_category_price_product', '0') === '1';

// 🔥 获取产品名称换行方式设置（默认按词换行）
$pos_product_name_break_all = get_option('pos_product_name_break_all', '0') === '1';

// 🔥 获取产品图片占比设置（默认50%）
$pos_product_image_ratio = intval(get_option('pos_product_image_ratio', 50));
$pos_product_image_ratio = max(30, min(100, $pos_product_image_ratio));

// 一次性更新：将旧的快捷键设置重置为新的默认值（单键）
$current_modifier = get_option('drawer_shortcut_modifier');
if ($current_modifier === false || $current_modifier === 'ctrl') {
    // 如果没有设置或者是旧的默认值'ctrl'，更新为'none'
    update_option('drawer_shortcut_modifier', 'none');
}

// 获取CLODOP配置
$clodop_config = get_clodop_config();

// 获取当前语言设置
$current_language = defined('RUIYI_CURRENT_LANG') ? RUIYI_CURRENT_LANG : 'zh';

?>

