  <!-- 拦截 CLODOP 原生 alert 弹窗 -->
  <script>
  (function() {
      var originalAlert = window.alert;
      var clodopKeywords = ['LODOP','CLodop','C-Lodop','打印控件','print control','not ready','未安装','not installed','打印服务','print service','WebSocket没准备好','WebSocket','没准备好','getLodop'];
      window.alert = function(message) {
          var isClodop = clodopKeywords.some(function(k) { return message && message.toString().toLowerCase().indexOf(k.toLowerCase()) !== -1; });
          if (isClodop) { console.warn('[CLODOP] alert blocked:', message); return; }
          return originalAlert.call(window, message);
      };
  })();
  </script>

  <!-- 🔥 生产模式：过滤调试信息，保持控制台整洁 -->
  <script>
  var POS_DEBUG = localStorage.getItem('pos_debug') === '1';
  (function() {
      if (POS_DEBUG) return; // Debug mode: let all logs through
      var _origLog = console.log;
      var _debugPatterns = [
          '[🔍', '[syncCart', '[saveTableOrderBtn]', '[quickSave', '[打印队列]',
          '[轮询厨房打印]', '[结账追踪]', '[模块切换]', '[viewTableOrder]',
          '[自动结算]', '[AA结账', '[释放桌位]', '[syncTableOrder]',
          '[POS-WS]', '[客户管理]', '[PaymentQueue]', '🔧 厨房打印',
          '[自动厨房打印]', '🖨️ [厨房打印调试',
          '📊 本次会话累计打印', '🔄 厨房打印调试', '📋 厨房打印调试',
          '[updateLockedItems', '[autoSaveTableOrder]', '[CLODOP]',
          '[自动清理]', '_kitchenPrintDebug', '[create_order-DEBUG]',
          '📦', '📤', '📥', '🔥'
      ];
      console.log = function() {
          if (arguments.length > 0) {
              var first = arguments[0];
              if (typeof first === 'string') {
                  for (var i = 0; i < _debugPatterns.length; i++) {
                      if (first.indexOf(_debugPatterns[i]) !== -1) return;
                  }
              }
          }
          _origLog.apply(console, arguments);
      };
  })();
  </script>

  <!-- 🔥 全局403错误拦截器：检测到403弹窗提示用户重新登录 -->
  <script>
  (function() {
    var _hasShown403 = false;
    var _originalFetch = window.fetch;

    function handleForceLogout() {
      if (_hasShown403) return;
      _hasShown403 = true;
      console.error('[403] <?php echo ruiyi_translate("Sesión expirada o sin permiso", "Session expired or no permission", "会话过期或无权限"); ?>');

      // 等待 Swal 加载完成（页面初期可能还没加载）
      function showLogoutPrompt() {
        if (typeof Swal === 'undefined') {
          setTimeout(showLogoutPrompt, 500);
          return;
        }
        // 关闭所有已有弹窗
        Swal.close();

        Swal.fire({
          icon: 'info',
          title: '<?php echo ruiyi_translate("Sistema actualizado", "System Updated", "系统已更新"); ?>',
          html: '<?php echo ruiyi_translate(
            "El sistema se ha actualizado. Por favor, inicie sesión de nuevo para continuar.",
            "The system has been updated. Please log in again to continue.",
            "系统已更新，请重新登录以继续使用。"
          ); ?>',
          confirmButtonText: '<?php echo ruiyi_translate("Iniciar sesión", "Log in", "重新登录"); ?>',
          confirmButtonColor: '#E84D25',
          allowOutsideClick: false,
          allowEscapeKey: false,
          showCloseButton: false
        }).then(function() {
          window.location.href = '<?php echo home_url('/'); ?>';
        });
      }

      showLogoutPrompt();
    }

    // 暴露给全局，供其他错误处理使用
    window._ruiyi403Handler = handleForceLogout;

    // 拦截 fetch 请求
    window.fetch = function() {
      return _originalFetch.apply(this, arguments).then(function(response) {
        if (response.status === 403 && !_hasShown403) {
          handleForceLogout();
        }
        return response;
      });
    };

    // 拦截 XMLHttpRequest (jQuery AJAX 等)
    var _originalXHROpen = XMLHttpRequest.prototype.open;
    var _originalXHRSend = XMLHttpRequest.prototype.send;

    XMLHttpRequest.prototype.open = function() {
      this._ruiyi_method = arguments[0];
      this._ruiyi_url = arguments[1];
      return _originalXHROpen.apply(this, arguments);
    };

    XMLHttpRequest.prototype.send = function() {
      var xhr = this;
      xhr.addEventListener('load', function() {
        if (xhr.status === 403 && !_hasShown403) {
          handleForceLogout();
        }
      });
      return _originalXHRSend.apply(this, arguments);
    };
  })();
  </script>

