          separateTicketPerCategory: <?php echo json_encode((bool)($clodop_config['separate_ticket_per_category'] ?? 0)); ?>, // 🔥 每个分类单独打印小票
          storeNameFontSize: <?php echo intval(get_option('pos_receipt_store_name_font_size', 18)); ?>, // 🔥 商店名称字体大小(pt)
          receiptProductFontSize: <?php echo intval(get_option('pos_receipt_product_font_size', 9)); ?>, // 🔥 结账小票产品字体大小(pt)
          receiptShowFullProductName: <?php echo json_encode(get_option('pos_receipt_show_full_product_name', '0') === '1'); ?>, // 🔥 小票产品名称过长时自动换行显示完整名称
          paperWidth: <?php echo intval(get_option('pos_paper_width', 80)); ?>, // 🔥 小票纸宽(mm)
          headerAlignment: <?php echo json_encode(get_option('pos_receipt_header_alignment', 'left')); ?>, // 🔥 小票抬头对齐方式
          headerSeparatorLine: <?php echo json_encode(get_option('pos_receipt_header_separator', '0') === '1'); ?>, // 🔥 抬头分隔实线
          receiptBilingual: <?php echo json_encode(get_option('pos_receipt_bilingual', '0') === '1'); ?>, // 🔥 小票产品中西双语
          receiptTaxType: <?php echo json_encode($ruiyi_receipt_tax_config['type']); ?>, // 结账小票/预结单税种
          receiptTaxLabel: <?php echo json_encode($ruiyi_receipt_tax_config['label']); ?>,
