          printDeliverySlipWithProforma: <?php echo json_encode(get_option('pos_print_delivery_slip_with_proforma', '0') === '1'); ?>, // 🔥 外送区域预结单时打印客户信息小票
          printKitchenSlipWithDeliveryProforma: <?php echo json_encode(get_option('pos_print_kitchen_slip_with_delivery_proforma', '1') === '1'); ?>, // 🔥 外送区域预结单时是否同时打印厨房小票
          enablePollingKitchenPrint: <?php echo json_encode(get_option('pos_enable_polling_kitchen_print', '1') === '1'); ?>, // 🔥 轮询检测厨房打印（用于扫码/服务员点餐）
