      };

      window.ruiyiGetReceiptTaxConfig = function ruiyiGetReceiptTaxConfig() {
          const type = window.clodopConfig?.receiptTaxType || 'iva_10';
          if (type === 'igic_7') {
              return { type: 'igic_7', label: 'IGIC', rate: 7 };
          }
          return { type: 'iva_10', label: 'IVA incluido', rate: 10 };
      };

      window.ruiyiGetReceiptTaxDisplayLabel = function ruiyiGetReceiptTaxDisplayLabel() {
          const tax = window.ruiyiGetReceiptTaxConfig();
          if (tax.type === 'igic_7') {
              return `${tax.label} ${tax.rate}%:`;
          }
          return `${tax.label} (${tax.rate}%):`;
      };

      window.ruiyiCalculateIncludedReceiptTax = function ruiyiCalculateIncludedReceiptTax(total) {
          const gross = Math.max(0, parseFloat(total) || 0);
          const tax = window.ruiyiGetReceiptTaxConfig();
          const divisor = 1 + ((parseFloat(tax.rate) || 0) / 100);
          const base = divisor > 0 ? gross / divisor : gross;
          return { base, tax: gross - base, total: gross, rate: tax.rate, label: tax.label };
      };

      // 也创建局部变量保持兼容性
      const clodopConfig = window.clodopConfig;

      // 🔥【2026-04-07】运行时同步最新打印配置：避免依赖 PHP 渲染时烘焙的旧值
      // 触发：页面加载后立即拉一次；tab 重新可见时再拉一次（用户在后台改了设置切回 POS 即生效，无需刷新）
      window.refreshClodopRuntimeConfig = async function refreshClodopRuntimeConfig(reason) {
          try {
              const _ajaxUrl = (typeof posAjaxUrl !== 'undefined' && posAjaxUrl) ? posAjaxUrl : (typeof ajaxUrl !== 'undefined' ? ajaxUrl : '/wp-admin/admin-ajax.php');
              const _nonce = (typeof posNonce !== 'undefined' && posNonce) ? posNonce : (typeof ajaxNonce !== 'undefined' ? ajaxNonce : '');
              if (!_nonce) return;
              const resp = await fetch(_ajaxUrl, {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                  body: new URLSearchParams({ action: 'ruiyi_get_clodop_runtime_config', nonce: _nonce })
              });
              const data = await resp.json();
              if (!data || !data.success || !data.data) return;
              const fresh = data.data;
              // 合并到 window.clodopConfig（仅覆盖运行时打印相关字段，不动其他字段）
              const keys = ['enabled','defaultPrinter','drawerPrinter','kitchenPrinter','categoryPrinterEnabled','separateTicketPerCategory','kitchenCopyToDefault','kitchenCategoryFilterEnabled','kitchenExcludedCategories','hasNoPrintCategories','openDrawerOnCard',
                  // 🔥【2026-04-08】小票样式相关字段（解决"预览跟实际打印不一致"）
                  'headerAlignment','storeNameFontSize','receiptProductFontSize','receiptShowFullProductName','paperWidth','headerSeparatorLine','receiptBilingual','receiptTaxType','receiptTaxLabel','receiptTaxRate','logoSize','receiptLogoWidth','receiptLogoHeight','receiptFooterPhone','receiptFooterWebsite','kitchenProductFontSize','kitchenBoldProductNumber'];
              let changed = [];
              keys.forEach(k => {
                  if (k in fresh) {
                      const before = JSON.stringify(window.clodopConfig[k]);
                      const after = JSON.stringify(fresh[k]);
                      if (before !== after) {
                          window.clodopConfig[k] = fresh[k];
                          changed.push(k);
                      }
                  }
              });
              if (changed.length > 0) {
                  console.log('[clodopConfig 同步]', reason || '', '更新字段:', changed.join(', '));
                  // 排除分类发生变化时清空产品→分类映射缓存，下次过滤会重新构建
                  if (changed.includes('kitchenExcludedCategories')) {
                      window._productCategoriesMap = null;
                  }
              }
          } catch (e) {
              console.warn('[clodopConfig 同步] 失败:', e);
          }
      };

      // 页面初次加载（DOMContentLoaded 之后 nonce/ajaxUrl 应已就绪）
      document.addEventListener('DOMContentLoaded', function() {
          setTimeout(() => window.refreshClodopRuntimeConfig('DOMContentLoaded'), 800);
      });
      // tab 重新可见时同步（用户在后台改完设置切回 POS 即生效）
      document.addEventListener('visibilitychange', function() {
          if (document.visibilityState === 'visible') {
              window.refreshClodopRuntimeConfig('visibilitychange');
          }
      });

      // 🖨️ 自动打印悬浮开关逻辑（localStorage 存储，每设备独立）
      var _autoPrintEnabled = localStorage.getItem('pos_auto_print_receipt') === '1';

      document.addEventListener('DOMContentLoaded', function initAutoPrintToggle() {
          var checkbox = document.getElementById('auto-print-checkbox');
          if (checkbox) {
              checkbox.checked = _autoPrintEnabled;
              updateAutoPrintSlider();
          }
      });

      function handleAutoPrintToggle() {
          var checkbox = document.getElementById('auto-print-checkbox');
          if (!checkbox) return;
          _autoPrintEnabled = checkbox.checked;
          localStorage.setItem('pos_auto_print_receipt', _autoPrintEnabled ? '1' : '0');
          updateAutoPrintSlider();
      }

      function updateAutoPrintSlider() {
          var slider = document.getElementById('auto-print-slider');
          if (!slider) return;
          slider.style.backgroundColor = _autoPrintEnabled ? '#10b981' : '#ccc';
          slider.innerHTML = '<span style="position:absolute; height:14px; width:14px; left:' +
              (_autoPrintEnabled ? '16px' : '2px') +
              '; bottom:2px; background:white; border-radius:50%; transition:0.3s;"></span>';
      }

      // 🔥 检查产品是否应从厨房打印中排除（延迟构建映射表，确保产品卡片已渲染）
      function isKitchenExcludedProduct(productId) {
          if (!window.clodopConfig?.kitchenCategoryFilterEnabled && !window.clodopConfig?.hasNoPrintCategories) return false;
          const excluded = window.clodopConfig.kitchenExcludedCategories || [];
          if (excluded.length === 0) return false;

          // 延迟构建产品→分类映射表（首次调用时，产品卡片已在DOM中）
          if (!window._productCategoriesMap) {
              window._productCategoriesMap = {};
              document.querySelectorAll('.product-card[data-id]').forEach(card => {
                  const id = parseInt(card.getAttribute('data-id'));
                  const cats = (card.getAttribute('data-categories') || '').split(' ').map(Number).filter(Boolean);
                  if (id && cats.length > 0) {
                      window._productCategoriesMap[id] = cats;
                  }
              });
              console.log('[厨房分类过滤] 产品分类映射表已构建, 产品数:', Object.keys(window._productCategoriesMap).length,
                  '排除分类:', JSON.stringify(excluded));
          }

          const cats = window._productCategoriesMap[productId] || [];
          if (cats.length === 0) return false;
          return cats.some(catId => excluded.includes(catId));
      }

      // 🍽️ 自助餐配置
      window.buffetConfig = {
          enabled: <?php echo json_encode(get_option('pos_buffet_enabled', '0') === '1'); ?>,
          categories: <?php echo get_option('pos_buffet_categories', '[]'); ?>,
          products: <?php echo get_option('pos_buffet_products', '[]'); ?>
      };

      // 🍽️ 判断产品是否为自助餐产品（前端辅助函数）
      window.isBuffetProduct = function(productId) {
          if (!window.buffetConfig || !window.buffetConfig.enabled) return false;
          productId = parseInt(productId);
          if (window.buffetConfig.products.includes(productId)) return true;
          // 检查产品的分类是否在自助餐分类中
          const card = document.querySelector(`.product-card[data-id="${productId}"]`);
          if (card && card.dataset.isBuffet === '1') return true;
          // 检查购物车项的分类
          if (card) {
              const cats = (card.dataset.categories || '').split(' ').map(Number).filter(Boolean);
              for (const catId of cats) {
                  if (window.buffetConfig.categories.includes(catId)) return true;
              }
          }
          return false;
      };

      // 🍽️ 自助餐开台用餐类型配置
      window.buffetMenuTypes = <?php echo get_option('pos_buffet_menu_types', '[]'); ?>;

      // 💳 支付方式排序配置
      window.paymentMethodOrder = <?php echo get_option('pos_payment_method_order', '["cash","card","bizum","mixed","cheque"]'); ?>;

      // 💳 支付方式显示/隐藏配置
      window.paymentMethodVisibility = <?php echo get_option('pos_payment_method_visibility', '{"cash":true,"card":true,"bizum":true,"mixed":true,"cheque":true}'); ?>;

      // 💳 应用支付方式排序（CSS order属性）+ 可见性控制
      window.applyPaymentMethodOrder = function(container, btnSelector, chequeSelector) {
          var order = window.paymentMethodOrder || ['cash','card','bizum','mixed','cheque'];
          var visibility = window.paymentMethodVisibility || {};
          var bizumEnabled = <?php echo (get_option('pos_bizum_enabled','0')==='1') ? 'true' : 'false'; ?>;
          // 找到按钮的父容器（grid容器）
          var gridContainer = null;
          order.forEach(function(method, index) {
              var btn = (method === 'cheque')
                  ? container.querySelector(chequeSelector)
                  : container.querySelector(btnSelector + '[data-method="' + method + '"]');
              if (btn) {
                  if (!gridContainer) gridContainer = btn.parentElement;
                  btn.style.order = index;
                  if (visibility[method] === false) {
                      btn.style.display = 'none';
                  } else {
                      btn.style.flex = '1 1 0%';
                      btn.style.minWidth = '0';
                  }
              }
          });
          // 将grid容器改为flex布局，让可见按钮自适应宽度
          if (gridContainer) {
              gridContainer.style.display = 'flex';
              gridContainer.style.gap = '0.5rem';
          }
          // 返回第一个可见支付方式（跳过隐藏的和禁用的bizum）
          for (var i = 0; i < order.length; i++) {
              if (visibility[order[i]] === false) continue;
              if (order[i] === 'bizum' && !bizumEnabled) continue;
              return order[i];
          }
          return 'cash';
      };

      // 🍽️ 根据当前时间获取自助餐时段价格
      window.getBuffetTimePeriodPrice = function(menuType) {
          const now = new Date();
          const currentMinutes = now.getHours() * 60 + now.getMinutes();
          const currentDay = now.getDay(); // 0=周日, 1=周一, ..., 6=周六
          if (menuType.time_periods && menuType.time_periods.length > 0) {
              for (const tp of menuType.time_periods) {
                  // 检查星期：days为空或未设置 → 适用所有天
                  if (tp.days && tp.days.length > 0 && !tp.days.includes(currentDay)) continue;
                  const [sh, sm] = tp.start.split(':').map(Number);
                  const [eh, em] = tp.end.split(':').map(Number);
                  const startMin = sh * 60 + sm;
                  const endMin = eh * 60 + em;
                  let match = false;
                  if (startMin <= endMin) {
                      match = currentMinutes >= startMin && currentMinutes < endMin;
                  } else {
                      match = currentMinutes >= startMin || currentMinutes < endMin;
                  }
                  if (match) {
                      return { price: parseFloat(tp.price), periodName: tp.name };
                  }
              }
          }
          return { price: parseFloat(menuType.default_price), periodName: '' };
      };

      // 🔥🔥🔥 【调试】厨房打印调试计数器
      window._kitchenPrintDebug = {
        counter: 0,
        sessionId: Date.now(),
        logs: [],
        log: function(source, orderData, printerName) {
          this.counter++;
          const logEntry = {
            count: this.counter,
            time: new Date().toISOString(),
            source: source,
            orderId: orderData?.id || 'N/A',
            tableNumber: orderData?.table_number || 'N/A',
            itemCount: orderData?.items?.length || 0,
            items: orderData?.items?.map(i => `${i.name} x${i.quantity}`).join(', ') || 'N/A',
            printer: printerName || 'N/A'
          };
          this.logs.push(logEntry);
          console.log(`%c🖨️ [厨房打印调试 #${this.counter}]`, 'background: #f59e0b; color: #000; padding: 2px 6px; border-radius: 3px;', {
            来源: source,
            订单ID: logEntry.orderId,
            桌号: logEntry.tableNumber,
            商品数量: logEntry.itemCount,
            商品详情: logEntry.items,
            打印机: logEntry.printer,
            时间: logEntry.time
          });
          // 在控制台显示累计打印次数
          console.log(`%c📊 本次会话累计打印: ${this.counter} 次`, 'background: #ef4444; color: #fff; padding: 2px 6px; border-radius: 3px;');
          // 记录最后日志时间，防止重复记录
          this._lastLogTime = Date.now();
        },
        reset: function() {
          this.counter = 0;
          this.logs = [];
          console.log('%c🔄 厨房打印调试计数器已重置', 'background: #10b981; color: #fff; padding: 2px 6px;');
        },
        showSummary: function() {
          console.log('%c📋 厨房打印调试汇总', 'background: #3b82f6; color: #fff; padding: 4px 8px; font-size: 14px;');
          console.table(this.logs);
          console.log(`总计: ${this.counter} 次打印`);
        }
      };
      console.log('%c🔧 厨房打印调试模式已启用', 'background: #8b5cf6; color: #fff; padding: 4px 8px; font-size: 12px;',
        '使用 window._kitchenPrintDebug.showSummary() 查看汇总, window._kitchenPrintDebug.reset() 重置计数');

      // 🔥 桌位调试日志系统 — 通过 WordPress option ruiyi_table_debug_enabled 启用
