      window.tableDebugLog = function(category, message, data) {
        if (!window.RUIYI_TABLE_DEBUG) return;
        var entry = {
          time: new Date().toISOString(),
          cat: category,
          msg: message,
          data: data || null
        };
        console.warn('[RUIYI-TABLE-DEBUG][' + category + '] ' + message, data || '');
        try {
          var logKey = 'ruiyi_table_debug_log';
          var logs = JSON.parse(localStorage.getItem(logKey) || '[]');
          logs.push(entry);
          if (logs.length > 500) logs.splice(0, logs.length - 500);
          localStorage.setItem(logKey, JSON.stringify(logs));
        } catch (e) { /* storage full */ }
      };

