              address: '<?php echo esc_js(get_option("pos_store_address", "")); ?>',
              phone: '<?php echo esc_js(get_option("pos_store_phone", "")); ?>',
              receiptLogo: '<?php echo esc_js(get_option("pos_receipt_logo", "")); ?>',
              receiptLogoWidth: <?php echo intval($ruiyi_receipt_logo_dimensions['width'] ?? 0); ?>,
              receiptLogoHeight: <?php echo intval($ruiyi_receipt_logo_dimensions['height'] ?? 0); ?>,
              receiptFooterPhone: <?php echo json_encode(get_option('pos_receipt_footer_phone', '')); ?>,
              receiptFooterWebsite: <?php echo json_encode(get_option('pos_receipt_footer_website', '')); ?>,
              receiptFooter: '<?php echo esc_js(get_option("pos_receipt_footer", "¡Gracias por su compra!")); ?>'
          }
      };

      // 🔥 设置桌位每行数量CSS变量
      document.documentElement.style.setProperty('--tables-per-row', window.RUIYI_POS_CONFIG.tablesPerRow || 8);
      // 🔥 设置桌位字体大小CSS变量
