  <!-- 引入 RUIYI CLODOP 集成脚本 (在配置之后加载) -->
  <script src="<?php echo get_template_directory_uri(); ?>/clodop-integration-fixed.js?v=clodop-norefresh-<?php echo time(); ?>"></script>

  <script>

      // LODOP 对象
      let LODOP = null;

      function ruiyiIsCheckoutTouchKeypadEnabled() {
          return !!(window.RUIYI_POS_CONFIG && window.RUIYI_POS_CONFIG.checkoutTouchKeypadEnabled);
      }

      function ruiyiBuildCheckoutTouchKeypadHtml() {
          if (!ruiyiIsCheckoutTouchKeypadEnabled()) return '';
          return `
              <div class="checkout-touch-keypad" aria-label="Touch numeric keypad">
                  <div class="checkout-touch-keypad-title"><?php echo ruiyi_translate('Teclado táctil', 'Touch keypad', '触屏数字键盘'); ?></div>
                  <div class="checkout-touch-keypad-grid">
                      <button type="button" class="checkout-touch-key" data-checkout-key="1">1</button>
                      <button type="button" class="checkout-touch-key" data-checkout-key="2">2</button>
                      <button type="button" class="checkout-touch-key" data-checkout-key="3">3</button>
                      <button type="button" class="checkout-touch-key" data-checkout-key="4">4</button>
                      <button type="button" class="checkout-touch-key" data-checkout-key="5">5</button>
                      <button type="button" class="checkout-touch-key" data-checkout-key="6">6</button>
                      <button type="button" class="checkout-touch-key" data-checkout-key="7">7</button>
                      <button type="button" class="checkout-touch-key" data-checkout-key="8">8</button>
                      <button type="button" class="checkout-touch-key" data-checkout-key="9">9</button>
                      <button type="button" class="checkout-touch-key action" data-checkout-key="backspace">⌫</button>
                      <button type="button" class="checkout-touch-key" data-checkout-key="0">0</button>
                      <button type="button" class="checkout-touch-key" data-checkout-key=".">.</button>
                      <button type="button" class="checkout-touch-key clear" data-checkout-key="clear">C</button>
                      <button type="button" class="checkout-touch-key confirm" data-checkout-key="ok"><?php echo ruiyi_translate('OK', 'OK', '确定'); ?></button>
                  </div>
              </div>
          `;
      }

      function ruiyiAttachCheckoutTouchKeypad(popup) {
          if (!ruiyiIsCheckoutTouchKeypadEnabled() || !popup) return;

          const amountSelector = [
              '#takeaway-received-amount',
              '#takeaway-card-received-amount',
              '#takeaway-mixed-cash-amount',
              '#takeaway-cheque-restaurante',
              '#received-amount-mesa',
              '#card-received-amount-mesa',
              '#mixed-cash-amount',
              '#table-cheque-restaurante'
          ].join(',');
          let activeInput = null;

          const isUsableInput = (input) => {
              return !!(input && !input.disabled && !input.readOnly && input.offsetParent !== null && !input.closest('.hidden'));
          };

          const getActiveInput = () => {
              if (isUsableInput(activeInput)) return activeInput;
              const inputs = Array.from(popup.querySelectorAll(amountSelector));
              activeInput = inputs.find(isUsableInput) || null;
              return activeInput;
          };

	          popup.querySelectorAll(amountSelector).forEach((input) => {
	              if (String(input.type).toLowerCase() === 'number') {
	                  input.type = 'text';
	              }
	              input.setAttribute('inputmode', 'decimal');
	              input.addEventListener('focus', () => { activeInput = input; });
	              input.addEventListener('click', () => { activeInput = input; });
	          });

          popup.querySelectorAll('.checkout-touch-key').forEach((button) => {
              button.addEventListener('click', () => {
                  const key = button.getAttribute('data-checkout-key');
                  if (key === 'ok') {
                      const confirmButton = Swal.getConfirmButton();
                      if (confirmButton && !confirmButton.disabled) confirmButton.click();
                      return;
                  }

                  const input = getActiveInput();
                  if (!input) return;

	                  let value = String(input.value || '').replace(',', '.').replace(/[^\d.]/g, '');
	                  const firstDot = value.indexOf('.');
	                  if (firstDot !== -1) {
	                      value = value.slice(0, firstDot + 1) + value.slice(firstDot + 1).replace(/\./g, '');
	                  }
	                  let nextValue = value;

                  if (key === 'clear') {
                      nextValue = '';
                  } else if (key === 'backspace') {
                      nextValue = value.slice(0, -1);
	                  } else if (key === '.') {
	                      if (value.includes('.')) return;
	                      nextValue = value ? value + '.' : '0.';
                  } else if (/^\d$/.test(key)) {
                      const candidate = value === '0' ? key : value + key;
                      const decimalPart = candidate.split('.')[1];
                      if (decimalPart && decimalPart.length > 2) return;
                      nextValue = candidate;
                  }

                  input.value = nextValue;
                  input.dispatchEvent(new Event('input', { bubbles: true }));
                  input.dispatchEvent(new Event('change', { bubbles: true }));
                  try {
                      input.focus({ preventScroll: true });
                  } catch (e) {
                      input.focus();
                  }
              });
          });
      }

      // ========================================
      // 注意: 所有CLODOP功能已迁移到 clodop-integration.js
      // 避免在这里定义冲突的函数
      // ========================================

      // 🔥 电子秤显示/隐藏切换函数 - 提前定义（全局函数）
      // 规则：
      // - 离线时强制隐藏
      // - 在线时按用户设置显示/隐藏
      function ensureScaleOfflineCard() {
          const scaleWidget = document.getElementById('scale-status-card');
          if (!scaleWidget || !scaleWidget.parentNode) return null;

          let offlineCard = document.getElementById('scale-offline-card');
          if (offlineCard) return offlineCard;

          offlineCard = document.createElement('div');
          offlineCard.id = 'scale-offline-card';
          // Similar spacing to scale widget card, but offline styling
          // 🔥 已移除：离线状态卡片太占空间，使用底部横幅代替
          offlineCard.className = 'hidden'; // 始终隐藏，不再显示此模块
          offlineCard.innerHTML = '';
          return offlineCard;
      }

      function applyScaleWidgetVisibility() {
          const scaleWidget = document.getElementById('scale-status-card');
          if (!scaleWidget) return;

          const offlineCard = ensureScaleOfflineCard();

          const wanted = window.__ruiyiScaleWidgetWanted !== undefined ? !!window.__ruiyiScaleWidgetWanted : true;
          const isOnline = navigator.onLine && window.RUIYI_POS?.isOnline !== false;
          const shouldShowScale = wanted && isOnline;
          const shouldShowOfflineCard = !isOnline; // offline card replaces scale widget when offline

          if (shouldShowScale) {
                  scaleWidget.classList.remove('hidden');
              } else {
                  scaleWidget.classList.add('hidden');
              }

          // Toggle offline card opposite to scale widget
          if (offlineCard) {
              if (shouldShowOfflineCard) {
                  offlineCard.classList.remove('hidden');
              } else {
                  offlineCard.classList.add('hidden');
              }
          }
      }

      function toggleScaleWidgetVisibility(isVisible) {
          // 记录用户偏好（离线时也保留，等回到在线再恢复显示）
          window.__ruiyiScaleWidgetWanted = !!isVisible;
          applyScaleWidgetVisibility();
      }

      // 🔥 PWA: 收银系统风格离线横幅
      function initConnectionBanner() {
          if (document.getElementById('pwa-connection-banner')) return;

          const banner = document.createElement('div');
          banner.id = 'pwa-connection-banner';
          banner.className = 'pwa-connection-banner';
          banner.innerHTML = `
              <div class="pwa-connection-banner__inner">
                  <div class="pwa-connection-banner__icon">
                      <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
                          <line x1="1" y1="1" x2="23" y2="23"></line>
                          <path d="M16.72 11.06A10.94 10.94 0 0 1 19 12.55"></path>
                          <path d="M5 12.55a10.94 10.94 0 0 1 5.17-2.39"></path>
                          <path d="M10.71 5.05A16 16 0 0 1 22.58 9"></path>
                          <path d="M1.42 9a15.91 15.91 0 0 1 4.7-2.88"></path>
                          <path d="M8.53 16.11a6 6 0 0 1 6.95 0"></path>
                          <line x1="12" y1="20" x2="12.01" y2="20"></line>
                      </svg>
                  </div>
                  <div class="pwa-connection-banner__content">
                      <div class="pwa-connection-banner__title"><?php echo ruiyi_translate('MODO OFFLINE', 'OFFLINE MODE', '离线模式'); ?></div>
                      <div class="pwa-connection-banner__desc"><?php echo ruiyi_translate('Los pedidos se sincronizarán automáticamente', 'Orders will sync automatically', '订单将在恢复连接后自动同步'); ?></div>
                  </div>
                  <div class="pwa-connection-banner__status">
                      <span class="pwa-connection-banner__dot"></span>
                  </div>
              </div>
          `;
          document.body.appendChild(banner);
      }

      function updateConnectionBanner() {
          const banner = document.getElementById('pwa-connection-banner');
          if (!banner) return;

          const isOnline = navigator.onLine && window.RUIYI_POS?.isOnline !== false;
          if (isOnline) {
              banner.classList.remove('show');
          } else {
              banner.classList.add('show');
          }
      }

      // 🔥 密码显示/隐藏切换函数
      function togglePasswordVisibility(inputId, btn) {
          const input = document.getElementById(inputId);
          const icon = btn.querySelector('i');
          if (input.type === 'password') {
              input.type = 'text';
              icon.classList.remove('fa-eye');
              icon.classList.add('fa-eye-slash');
          } else {
              input.type = 'password';
              icon.classList.remove('fa-eye-slash');
              icon.classList.add('fa-eye');
          }
      }

      // 清理pending积分交易的函数 - 提前定义
      function clearPendingPointsTransaction() {
          var ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
          var ajaxNonce = window.RUIYI_POS?.nonce || posNonce;

          fetch(ajaxUrl, {
              method: 'POST',
              headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
              body: new URLSearchParams({
                  action: 'ruiyi_clear_pending_points_transaction',
                  nonce: ajaxNonce
              })
          })
          .then(response => response.json())
          .then(data => {
              if (data.success) {
                  // 清理成功，无需显示提示
              }
          })
          .catch(error => {
              console.error('[积分清理] 清理pending积分交易失败:', error);
          });
      }

      // 🔥 【新增】验证并清理无效的离线桌位数据
      function validateAndCleanMesasEstado() {
          try {
              const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
              let hasChanges = false;
              let cleanedCount = 0;

              for (const [mesaKey, data] of Object.entries(mesasEstado)) {
                  // 检测无效数据的条件：
                  // 1. 有待同步标记但数据不完整
                  // 2. cart 和待同步数据数量严重不匹配（可能是重复累积）
                  // 3. 订单ID是临时ID但已经很久了（超过24小时）

                  const orderIdStr = data.orderId ? String(data.orderId) : '';
                  const isTempId = orderIdStr.startsWith('OFFLINE_') || orderIdStr.startsWith('PENDING_');
                  const timestamp = data.timestamp ? new Date(data.timestamp).getTime() : 0;
                  const ageHours = (Date.now() - timestamp) / (1000 * 60 * 60);

                  // 清理条件1: 临时ID超过24小时且没有待同步数据（可能是残留数据）
                  if (isTempId && ageHours > 24 && !data._pendingSync && !data._offline) {
                      console.log(`[数据清理] 🧹 清理过期临时数据: ${mesaKey}, 年龄: ${ageHours.toFixed(1)}小时`);
                      // 重置为空闲状态
                      mesasEstado[mesaKey] = {
                          estado: 'libre',
                          cart: [],
                          total: 0,
                          orderId: null,
                          timestamp: new Date().toISOString()
                      };
                      hasChanges = true;
                      cleanedCount++;
                  }

                  // 清理条件2: 检测重复数据（cart数量是待同步数量的2倍或更多）
                  const cartLength = (data.cart && Array.isArray(data.cart)) ? data.cart.length : 0;
                  const syncLength = Math.max(
                      (data._newItemsToSync && Array.isArray(data._newItemsToSync)) ? data._newItemsToSync.length : 0,
                      (data._offlineNewItems && Array.isArray(data._offlineNewItems)) ? data._offlineNewItems.length : 0
                  );

                  if (syncLength > 0 && cartLength >= syncLength * 2) {
                      console.warn(`[数据清理] ⚠️ 检测到可能的重复数据: ${mesaKey}, cart=${cartLength}, sync=${syncLength}`);
                      // 不自动清理，只记录警告
                  }
              }

              if (hasChanges) {
                  localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
                  console.log(`[数据清理] ✅ 已清理 ${cleanedCount} 个无效桌位数据`);
              }
          } catch (e) {
              console.error('[数据清理] 验证失败:', e);
          }
      }

      // 页面加载时验证桌位状态数据和清理积分交易
      document.addEventListener('DOMContentLoaded', function() {
          // CLODOP初始化已迁移到 clodop-integration.js

          // 🔥 验证并清理无效的离线桌位数据
          validateAndCleanMesasEstado();

          // 清理可能残留的pending积分交易
          clearPendingPointsTransaction();

          // 🔥 初始化电子秤模块显示状态
          const showScaleWidget = <?php echo json_encode(get_option('pos_show_scale_widget', '1') === '1'); ?>;
          // 保存用户设置（后续 online/offline 切换会用到）
          window.__ruiyiScaleWidgetWanted = showScaleWidget;
          applyScaleWidgetVisibility();

          // 🔥 PWA: Load and cache customers on page load
          if (typeof loadAndCacheCustomers === 'function') {
            setTimeout(() => {
              loadAndCacheCustomers();
            }, 2000);
            setTimeout(() => {
              loadAndCacheCustomers();
            }, 5000);
          }

          // 🔥 PWA: offline banner + online/offline hooks
          initConnectionBanner();
          updateConnectionBanner();

          window.addEventListener('online', () => {
              updateConnectionBanner();
              applyScaleWidgetVisibility();

              // Update online status
              if (window.RUIYI_POS) {
                  window.RUIYI_POS.isOnline = true;
                  window.RUIYI_POS.offlineMode = false;
              }

              // 🔥 PWA: Auto sync pending orders IMMEDIATELY when connection restored
              function triggerImmediateSyncIfAvailable() {
                  if (typeof syncPendingOrdersDirect === 'function') {
                      try {
                          syncPendingOrdersDirect();
                      } catch (error) {
                          console.error('[PWA] Direct sync failed:', error);
                          if (window.posSync && typeof window.posSync.sync === 'function') {
                              window.posSync.sync();
                          }
                      }
                  } else if (window.posSync && typeof window.posSync.sync === 'function') {
                      window.posSync.sync().then(() => {
                          refreshHistoryIfVisible();
                      }).catch(error => {
                          console.error('[PWA] posSync error:', error);
                      });
                  }
              }

              triggerImmediateSyncIfAvailable();

              // 🔥 PWA: 同步离线桌位订单到服务器
              setTimeout(() => {
                  if (typeof window.syncOfflineTableOrders === 'function') {
                      window.syncOfflineTableOrders();
                  }
              }, 2000);

              // 🔥 PWA: 同步离线锁定商品删除操作到服务器
              setTimeout(() => {
                  if (typeof window.syncOfflineLockedItemDeletions === 'function') {
                      window.syncOfflineLockedItemDeletions();
                  }
              }, 3000);

              // Background Sync as backup
              if ('serviceWorker' in navigator && 'sync' in window.ServiceWorkerRegistration.prototype) {
                  navigator.serviceWorker.ready.then(registration => {
                      registration.sync.register('sync-orders').catch(e => console.warn('[SW] sync-orders registration failed:', e.message));
                  }).catch(e => console.warn('[SW] serviceWorker.ready failed:', e.message));
              }

              // Safety sync check after 5 seconds
              setTimeout(() => {
                  if (typeof syncPendingOrdersDirect === 'function') {
                      syncPendingOrdersDirect();
                  } else if (window.posSync && typeof window.posSync.sync === 'function') {
                      window.posSync.sync();
                  }
              }, 5000);
              
              function refreshHistoryIfVisible() {
                  const historialSection = document.getElementById('historial');
                  if (historialSection && !historialSection.classList.contains('hidden')) {
                      // 🔥 PWA同步后只刷新离线待同步面板，不重新加载历史订单（用户手动刷新即可）
                      if (typeof loadOfflinePendingOrdersIntoHistory === 'function') {
                          setTimeout(() => {
                              loadOfflinePendingOrdersIntoHistory();
                          }, 500);
                      }
                  }
              }

              // 🔥 If user is viewing historial, refresh it immediately (before sync completes)
              const historialSection = document.getElementById('historial');
              if (historialSection && !historialSection.classList.contains('hidden')) {
                  if (typeof loadOfflinePendingOrdersIntoHistory === 'function') {
                      loadOfflinePendingOrdersIntoHistory();
                  }
              }
          });
          window.addEventListener('offline', () => {
              updateConnectionBanner();
              applyScaleWidgetVisibility();
          });

          // 🔥 PWA: 同步离线桌位订单到服务器
          let _isSyncingOfflineOrders = false; // 🔥 同步锁，防止并发调用
          let _lastSyncTime = 0; // 🔥 上次同步时间，用于防抖
          const SYNC_DEBOUNCE_MS = 3000; // 🔥 同步防抖时间（3秒）

          async function syncOfflineTableOrders() {
              // 🔥 修复：在函数内部获取 ajaxUrl 和 ajaxNonce，确保变量可访问
              const ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
              const ajaxNonce = window.RUIYI_POS?.nonce || '<?php echo esc_js($ajax_nonce); ?>';

              // 🔥 关键修复1：防止并发调用导致重复同步
              if (_isSyncingOfflineOrders) {
                  return;
              }

              // 🔥 关键修复：检查全局同步锁（与 pos-offline.js 共享）
              if (window._globalOfflineTableSyncInProgress) {
                  return;
              }

              // 🔥 【新增】检查 syncTableOrderToServer 是否正在运行，防止重复同步
              if (window._syncTableOrderInProgress) {
                  console.log('[PWA] syncTableOrderToServer 正在运行，跳过 syncOfflineTableOrders');
                  return;
              }

              // 🔥 关键修复2：防抖机制，防止短时间内多次调用
              const now = Date.now();
              if (now - _lastSyncTime < SYNC_DEBOUNCE_MS) {
                  return;
              }

              _isSyncingOfflineOrders = true;
              _lastSyncTime = now;

              // 🔥 设置全局同步锁
              window._globalOfflineTableSyncInProgress = true;

              try {
              // 🔥🔥🔥 关键修复3：原子性操作 - 读取、提取、清除在一个操作中完成
              // 这样即使函数被调用多次，后续调用也会发现数据已被清除
              const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');

              // 🔥 第一步：找出所有需要同步的桌位并提取数据
              const offlineTablesToSync = [];
              let hasChanges = false;

              for (const [key, data] of Object.entries(mesasEstado)) {
                  // 跳过正在同步的桌位
                  if (data._syncing) {
                      continue;
                  }

                  let itemsToSync = null;
                  let isAddition = false;

                  // 有 _offlineNewItems 的优先使用（精确同步）
                  if (data._offlineNewItems && Array.isArray(data._offlineNewItems) && data._offlineNewItems.length > 0) {
                      itemsToSync = JSON.parse(JSON.stringify(data._offlineNewItems));
                      isAddition = data._hasOnlineOrder === true;
                  }
                  // 兼容旧逻辑：如果没有 _offlineNewItems 但有 _offline 标记和 cart
                  // 🔥 【关键修复】只同步未锁定的商品，避免已锁定商品被重复创建
                  else if (data._offline === true && data.cart && Array.isArray(data.cart) && data.cart.length > 0 && !data._hasOnlineOrder) {
                      // 过滤掉已锁定的商品（这些商品已经在服务器上存在）
                      const unlockedItems = data.cart.filter(item => !item.locked);
                      if (unlockedItems.length > 0) {
                          itemsToSync = JSON.parse(JSON.stringify(unlockedItems));
                          isAddition = false;
                      } else {
                          // 如果全是锁定商品，跳过同步
                          console.log(`[PWA] ${key} 只有锁定商品，跳过离线同步`);
                          continue;
                      }
                  }

                  if (itemsToSync && itemsToSync.length > 0) {
                      // 🔥 立即清除数据并标记正在同步（原子操作）
                      delete mesasEstado[key]._offlineNewItems;
                      mesasEstado[key]._syncing = true;
                      mesasEstado[key]._syncStartTime = now;
                      hasChanges = true;

                      offlineTablesToSync.push({
                          mesaKey: key,
                          itemsToSync: itemsToSync,
                          isAddition: isAddition,
                          savedTotal: data.total,
                          originalOrderId: data.orderId
                      });
                  }
              }

              // 🔥 第二步：立即保存清除后的状态到localStorage
              if (hasChanges) {
                  localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
              }

              if (offlineTablesToSync.length === 0) {
                  return;
              }

              let syncedCount = 0;
              let failedCount = 0;

              // 🔥 第三步：使用预提取的数据进行同步（数据已在第一步清除，防止重复）
              for (const syncItem of offlineTablesToSync) {
                  const { mesaKey, itemsToSync, isAddition, savedTotal } = syncItem;
                  try {
                      // 构建请求数据
                      const formData = new URLSearchParams({
                          action: 'ruiyi_pos_create_order',
                          cart: JSON.stringify(itemsToSync),
                          table_number: mesaKey,
                          order_type: 'servir',
                          payment_method: 'Cash',
                          is_addition: isAddition ? 'true' : 'false',
                          nonce: ajaxNonce
                      });

                      // 🔥 如果是追加订单，传递现有订单ID
                      if (isAddition && syncItem.originalOrderId) {
                          formData.append('order_id', syncItem.originalOrderId);
                      }

                      const response = await fetch(ajaxUrl, {
                          method: 'POST',
                          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                          body: formData
                      });

                      if (!response.ok) {
                          throw new Error(`HTTP ${response.status}`);
                      }

                      const data = await response.json();

                      if (data.success) {
                          const orderId = data.data?.order_id || data.order_id;
                          const serverTotal = data.data?.total || data.total;
                          const serverItems = data.data?.items; // 服务器可能直接返回items
                          // 🔥🔥🔥 【2026-01-19 关键修复】始终优先使用服务器返回的总额
                          // 服务器在创建/追加订单时返回的是正确的桌位累计总额（来自WooCommerce）
                          // 之前的bug：isAddition时直接使用savedTotal，忽略了serverTotal
                          const orderTotal = serverTotal || savedTotal;

                          console.log(`[PWA-DEBUG] 📥 同步响应:`, {
                              orderId,
                              serverTotal,
                              serverItems: serverItems ? serverItems.length : 'none',
                              orderTotal,
                              isAddition,
                              fullResponse: data
                          });

                          // 更新本地状态：移除 _offline 标记，清除同步标记
                          let updatedMesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                          const originalCart = updatedMesasEstado[mesaKey]?.cart ? [...updatedMesasEstado[mesaKey].cart] : [];

                          console.log(`[PWA-DEBUG] 📦 本地原始cart:`, {
                              itemCount: originalCart.length,
                              items: originalCart.map(i => ({ name: i.name, qty: i.quantity, price: i.price }))
                          });

                          if (updatedMesasEstado[mesaKey]) {
                              updatedMesasEstado[mesaKey].orderId = orderId;
                              updatedMesasEstado[mesaKey].total = orderTotal;
                              updatedMesasEstado[mesaKey]._offline = false;
                              updatedMesasEstado[mesaKey]._pendingSync = false;
                              updatedMesasEstado[mesaKey].timestamp = new Date().toISOString();
                              updatedMesasEstado[mesaKey]._skipAutoUpdate = true;
                              // 🔥 【关键修复】清除所有同步标记，防止数据重复累积
                              delete updatedMesasEstado[mesaKey]._offlineNewItems;
                              delete updatedMesasEstado[mesaKey]._newItemsToSync;
                              delete updatedMesasEstado[mesaKey]._hasOnlineOrder;
                              delete updatedMesasEstado[mesaKey]._isAddition;
                              delete updatedMesasEstado[mesaKey]._syncing;
                              delete updatedMesasEstado[mesaKey]._syncStartTime;
                              console.log(`[PWA] ✅ 同步成功后已清除所有待同步数据: ${mesaKey}`);

                              // 🔥 如果服务器在创建订单时直接返回了items，使用服务器数据
                              if (serverItems && Array.isArray(serverItems) && serverItems.length > 0) {
                                  updatedMesasEstado[mesaKey].cart = serverItems;
                                  console.log(`[PWA-DEBUG] ✅ 使用服务器直接返回的items:`, serverItems.length);
                              } else if (!updatedMesasEstado[mesaKey].cart || updatedMesasEstado[mesaKey].cart.length === 0) {
                                  // 确保cart不为空，使用原始同步数据
                                  updatedMesasEstado[mesaKey].cart = itemsToSync;
                              }

                              // 🔥 设置保护标记，防止reloadTableOrderToCartSilently清空购物车
                              updatedMesasEstado[mesaKey]._justSynced = true;
                              updatedMesasEstado[mesaKey]._syncTimestamp = Date.now();

                              localStorage.setItem('mesas_estado', JSON.stringify(updatedMesasEstado));

                              // 🔥 设置全局同步保护标记
                              window._recentlySyncedTables = window._recentlySyncedTables || {};
                              window._recentlySyncedTables[mesaKey] = {
                                  timestamp: Date.now(),
                                  orderId: orderId,
                                  cart: itemsToSync
                              };

                              // 5秒后清除保护标记
                              setTimeout(() => {
                                  if (window._recentlySyncedTables?.[mesaKey]) {
                                      delete window._recentlySyncedTables[mesaKey];
                                  }
                              }, 5000);

                              // 🔥 同步成功后，获取服务器端完整订单数据以确保数据一致性
                              // 只有当服务器没有在创建响应中返回items时才需要额外请求
                              if (!serverItems || !Array.isArray(serverItems) || serverItems.length === 0) {
                                  try {
                                      console.log(`[PWA-DEBUG] 🔄 开始获取服务器订单详情...`);
                                      const orderResponse = await fetch(ajaxUrl, {
                                          method: 'POST',
                                          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                                          body: new URLSearchParams({
                                              action: 'ruiyi_pos_fetch_table_order',
                                              table_number: mesaKey,
                                              nonce: ajaxNonce
                                          })
                                      });
                                      const orderData = await orderResponse.json();
                                      console.log(`[PWA-DEBUG] 📥 fetch_table_order 响应:`, orderData);

                                      if (orderData.success && orderData.data?.items && Array.isArray(orderData.data.items) && orderData.data.items.length > 0) {
                                          // 使用服务器数据更新本地 cart，确保一致性
                                          updatedMesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                                          if (updatedMesasEstado[mesaKey]) {
                                              updatedMesasEstado[mesaKey].cart = orderData.data.items;
                                              updatedMesasEstado[mesaKey].total = orderData.data.total || orderTotal;
                                              updatedMesasEstado[mesaKey].orderId = orderData.data.order_id || orderId;
                                              localStorage.setItem('mesas_estado', JSON.stringify(updatedMesasEstado));
                                              console.log(`[PWA] ✅ 桌位 ${mesaKey} 本地数据已与服务器同步，商品数: ${orderData.data.items.length}`);
                                          }
                                      } else {
                                          // 服务器返回空，保留原始cart数据
                                          console.warn(`[PWA-DEBUG] ⚠️ 服务器返回空订单，保留原始cart数据`);
                                          updatedMesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                                          if (updatedMesasEstado[mesaKey] && originalCart.length > 0) {
                                              updatedMesasEstado[mesaKey].cart = originalCart;
                                              localStorage.setItem('mesas_estado', JSON.stringify(updatedMesasEstado));
                                              console.log(`[PWA-DEBUG] ✅ 已恢复原始cart数据，商品数: ${originalCart.length}`);
                                          }
                                      }
                                  } catch (fetchError) {
                                      console.warn(`[PWA] ⚠️ 获取同步后订单详情失败，保留本地数据:`, fetchError);
                                      // 确保保留原始cart
                                      updatedMesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                                      if (updatedMesasEstado[mesaKey] && originalCart.length > 0) {
                                          updatedMesasEstado[mesaKey].cart = originalCart;
                                          localStorage.setItem('mesas_estado', JSON.stringify(updatedMesasEstado));
                                      }
                                  }
                              }
                          }

                          // 标记订单为已打印（防止重复打印）
                          const printedOrders = JSON.parse(localStorage.getItem('printed_kitchen_orders') || '[]');
                          if (orderId && !printedOrders.includes(orderId)) {
                              printedOrders.push(orderId);
                              localStorage.setItem('printed_kitchen_orders', JSON.stringify(printedOrders));
                          }

                          syncedCount++;
                      } else {
                          console.error(`[PWA] ❌ 桌位 ${mesaKey} 同步失败:`, data.data?.message || '未知错误');
                          // 🔥 同步失败，恢复 _offlineNewItems 以便稍后重试
                          const failedMesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                          if (failedMesasEstado[mesaKey]) {
                              failedMesasEstado[mesaKey]._offlineNewItems = itemsToSync;
                              failedMesasEstado[mesaKey]._hasOnlineOrder = isAddition;
                              failedMesasEstado[mesaKey]._offline = true;
                              delete failedMesasEstado[mesaKey]._syncing;
                              delete failedMesasEstado[mesaKey]._syncStartTime;
                              localStorage.setItem('mesas_estado', JSON.stringify(failedMesasEstado));
                          }
                          failedCount++;
                      }
                  } catch (error) {
                      console.error(`[PWA] ❌ 桌位 ${mesaKey} 同步出错:`, error);
                      // 🔥 同步出错，恢复 _offlineNewItems 以便稍后重试
                      const errorMesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                      if (errorMesasEstado[mesaKey]) {
                          errorMesasEstado[mesaKey]._offlineNewItems = itemsToSync;
                          errorMesasEstado[mesaKey]._hasOnlineOrder = isAddition;
                          errorMesasEstado[mesaKey]._offline = true;
                          delete errorMesasEstado[mesaKey]._syncing;
                          delete errorMesasEstado[mesaKey]._syncStartTime;
                          localStorage.setItem('mesas_estado', JSON.stringify(errorMesasEstado));
                      }
                      failedCount++;
                  }
              }

              // 🔥 同步完成后刷新桌位显示（不显示通知）
              if (syncedCount > 0) {
                  // 刷新桌位显示
                  if (typeof renderizarMesas === 'function') {
                      renderizarMesas('after-offline-sync');
                  }
              }
              } finally {
                  // 🔥 释放同步锁
                  _isSyncingOfflineOrders = false;
                  // 🔥 释放全局同步锁
                  window._globalOfflineTableSyncInProgress = false;
              }
          }

          // 🔥 PWA: 同步离线锁定商品删除操作到服务器
          async function syncOfflineLockedItemDeletions() {
              // 🔥🔥🔥 关键修复：检查全局同步锁，防止与 updateLockedItemsToServer 同时运行
              // 如果 updateLockedItemsToServer 正在运行，跳过乐观删除同步（它会处理所有删除）
              if (window._updateLockedItemsSyncInProgress) {
                  console.log('[乐观删除同步] ⏸️ updateLockedItemsToServer 正在运行，跳过以避免竞态条件');
                  return { syncedCount: 0, failedCount: 0, skipped: true };
              }

              // 🔥 设置乐观删除同步锁
              window._optimisticDeleteSyncInProgress = true;

              // 🔥 修复：在函数内部获取 ajaxUrl 和 ajaxNonce，确保变量可访问
              const ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
              const ajaxNonce = window.RUIYI_POS?.nonce || '<?php echo esc_js($ajax_nonce); ?>';

              const pendingDeletions = JSON.parse(localStorage.getItem('pending_locked_item_deletions') || '[]');

              if (pendingDeletions.length === 0) {
                  console.log('[乐观删除同步] 无待同步的删除操作');
                  window._optimisticDeleteSyncInProgress = false; // 🔥 释放锁
                  return { syncedCount: 0, failedCount: 0 };
              }

              console.log('[乐观删除同步] 开始同步，待处理数量:', pendingDeletions.length);

              let syncedCount = 0;
              let failedCount = 0;
              const failedDeletions = []; // 存储失败的删除操作以便重试

              for (const deletion of pendingDeletions) {
                  try {
                      console.log('[乐观删除同步] 正在同步:', deletion);

                      const formData = new URLSearchParams({
                          action: 'ruiyi_pos_delete_locked_item',
                          product_id: deletion.product_id,
                          table_number: deletion.table_number,
                          quantity: deletion.quantity,
                          order_id: deletion.order_id,
                          item_id: deletion.item_id,
                          nonce: ajaxNonce
                      });

                      const response = await fetch(ajaxUrl, {
                          method: 'POST',
                          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                          body: formData
                      });

                      if (!response.ok) {
                          throw new Error(`HTTP ${response.status}`);
                      }

                      const data = await response.json();
                      console.log('[乐观删除同步] 服务器响应:', data);

                      if (data.success) {
                          syncedCount++;
                          console.log('[乐观删除同步] ✅ 删除成功，产品ID:', deletion.product_id);
                      } else {
                          // 如果是因为商品已不存在或订单已完成，视为成功（无需重试）
                          const errorMsg = data.data?.message || '';
                          if (errorMsg.includes('not found') || errorMsg.includes('no existe') || errorMsg.includes('已完成') || errorMsg.includes('不存在')) {
                              syncedCount++;
                              console.log('[乐观删除同步] ⚠️ 商品已不存在，视为成功');
                          } else {
                              console.error(`[乐观删除同步] ❌ 删除失败:`, data.data?.message || '未知错误');
                              failedDeletions.push(deletion);
                              failedCount++;
                          }
                      }
                  } catch (error) {
                      console.error(`[乐观删除同步] ❌ 同步出错:`, error);
                      failedDeletions.push(deletion);
                      failedCount++;
                  }
              }

              console.log(`[乐观删除同步] 同步完成 - 成功: ${syncedCount}, 失败: ${failedCount}`);

              // 更新待同步列表（只保留失败的）
              localStorage.setItem('pending_locked_item_deletions', JSON.stringify(failedDeletions));

              // 🔥🔥🔥 关键修复：同步完成后清除 _pendingServerSync 标志
              // 这样 fetchAndUpdateTableStatuses 可以正常更新桌位状态了
              if (syncedCount > 0 && failedCount === 0) {
                  const mesasEstadoToClear = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                  let cleared = false;
                  Object.keys(mesasEstadoToClear).forEach(key => {
                      if (mesasEstadoToClear[key]?._pendingServerSync) {
                          delete mesasEstadoToClear[key]._pendingServerSync;
                          cleared = true;
                          console.log(`[乐观删除同步] 🧹 清除桌位 ${key} 的 _pendingServerSync 标志`);
                      }
                  });
                  if (cleared) {
                      localStorage.setItem('mesas_estado', JSON.stringify(mesasEstadoToClear));
                  }
              }

              // 🔥 同步完成后刷新显示（不显示通知）
              if (syncedCount > 0) {
                  // 刷新桌位显示和购物车
                  if (typeof fetchAndUpdateTableStatuses === 'function') {
                      fetchAndUpdateTableStatuses();
                  }
                  if (typeof renderizarMesas === 'function') {
                      setTimeout(() => {
                          renderizarMesas('after-offline-deletion-sync');
                      }, 500);
                  }
              }

              // 🔥🔥🔥 关键：释放乐观删除同步锁
              window._optimisticDeleteSyncInProgress = false;
              console.log('[乐观删除同步] 🔓 释放同步锁');

              return { syncedCount, failedCount };
          }

          // 🔥 导出到全局，供其他脚本块调用
          window.syncOfflineLockedItemDeletions = syncOfflineLockedItemDeletions;
          window.syncOfflineTableOrders = syncOfflineTableOrders;

          // 🔥 PWA: Force sync check when page becomes visible
          document.addEventListener('visibilitychange', () => {
              if (!document.hidden && navigator.onLine) {
                  setTimeout(() => {
                      if (window.posSync && typeof window.posSync.checkAndSyncPendingOrders === 'function') {
                          window.posSync.checkAndSyncPendingOrders();
                      } else if (window.posSync && typeof window.posSync.sync === 'function') {
                          window.posSync.sync();
                      }
                  }, 1000);
              }
          });

          // 🔥 PWA: Force sync on page focus
          window.addEventListener('focus', () => {
              if (navigator.onLine) {
                  setTimeout(() => {
                      if (window.posSync && typeof window.posSync.checkAndSyncPendingOrders === 'function') {
                          window.posSync.checkAndSyncPendingOrders();
                      } else if (window.posSync && typeof window.posSync.sync === 'function') {
                          window.posSync.sync();
                      }
                  }, 1000);
              }
          });

          // 🔥 为左侧收银图标添加快速退出桌位功能
          // 🔥🔥🔥 关键修复：只有在桌位模式下才清空购物车
          const cashierLink = document.querySelector('a[href="#cajero"]');
          if (cashierLink) {
              cashierLink.addEventListener('click', function(e) {
                  // 🔥🔥🔥 检查是否在桌位模式下
                  const tableNumber = document.getElementById('table-number')?.value.trim();
                  const viewMode = sessionStorage.getItem('tableViewMode');
                  const isTableMode = tableNumber || viewMode;

                  // 只有在桌位模式下才调用退出桌位函数
                  // 快速结账/外卖模式下不清空购物车
                  if (isTableMode && typeof clearCurrentTable === 'function') {
                      clearCurrentTable();
                  }
              });
          }

          // 清理旧的快捷键设置
          const oldModifier = localStorage.getItem('drawer_shortcut_modifier');
          if (oldModifier === 'ctrl') {
              localStorage.setItem('drawer_shortcut_modifier', 'none');
          }

          // 🔥 PWA: Initialize database for offline order storage
          if (typeof posDB !== 'undefined' && posDB && typeof posDB.init === 'function') {
            posDB.init().catch(err => {
              console.warn('[PWA] Database initialization failed:', err);
            });
          }

          // 🔴 重要：检查查看模式的桌位是否已被清台（页面加载时）
          setTimeout(() => {
              const currentViewMode = typeof ruiyiGetActiveTableViewMode === 'function'
                ? ruiyiGetActiveTableViewMode()
                : JSON.parse(sessionStorage.getItem('isViewMode') || 'null');
              if (currentViewMode && currentViewMode.table) {
                  // 检查该桌位是否还存在（未被清台）
                  const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                  const tableState = mesasEstado[currentViewMode.table];

                  // 如果桌位已经是空闲状态或不存在，说明已被清台
                  if (!tableState || tableState.estado === 'libre' || !tableState.orderId) {
                      // 🔥 清空该桌位的delivery客户数据
                      if (typeof clearDeliveryCustomerData === 'function') {
                          clearDeliveryCustomerData(currentViewMode.table);
                      }

                      // 清理查看模式
                      sessionStorage.removeItem('isViewMode');
                      sessionStorage.removeItem('tableViewOrderData');

                      // 清空收银页面的购物车 - 使用syncCart确保完全清空
                      if (typeof syncCart === 'function') {
                          syncCart([]); // 使用syncCart函数确保cart和window.cart都被清空
                      } else {
                          // 回退方案：直接清空两个变量
                          if (typeof cart !== 'undefined') {
                              cart = [];
                          }
                          if (typeof window.cart !== 'undefined') {
                              window.cart = [];
                          }
                      }

                      // 清理购物车标题
                      const orderTitle = document.getElementById('cart-order-title');
                      if (orderTitle) {
                          orderTitle.innerHTML = '';
                      }

                      // 清空桌位输入框
                      const tableNumberInput = document.getElementById('table-number');
                      if (tableNumberInput) {
                          tableNumberInput.value = '';
                          // 🔥 隐藏购物车上方的桌位号显示
                          updateCurrentTableDisplay('');
                      }

                      // 重置订单类型为外卖
                      const llevarButton = document.querySelector('.order-type[data-type="llevar"]');
                      if (llevarButton) {
                          llevarButton.click();
                      }

                      // 刷新购物车显示 - 确保购物车UI更新
                      if (typeof renderCart === 'function') {
                          renderCart();
                      }

                      // 隐藏查看模式相关按钮和工具箱
                      const viewModeButtons = ['checkout-table-btn', 'toolbox-toggle-btn'];
                      viewModeButtons.forEach(btnId => {
                          const btn = document.getElementById(btnId);
                          if (btn) {
                              btn.classList.add('hidden');
                          }
                      });

                      // 更新按钮状态
                      if (typeof updateOrderButtonForType === 'function') {
                          updateOrderButtonForType('llevar');
                      }
                  }
              }
          }, 500); // 延迟执行，确保其他初始化完成

          // 🔥 页面加载时，确保有默认的订单类型（外卖模式）
          if (!sessionStorage.getItem('tipoPedidoSeleccionado')) {
              sessionStorage.setItem('tipoPedidoSeleccionado', 'llevar');
          }

          // 🔥 页面加载完成后，调用renderCart初始化按钮状态
          setTimeout(() => {
              if (typeof renderCart === 'function') {
                  renderCart();
              }

              // 🔥 调用updateAllButtonStates确保按钮状态正确
              if (typeof updateAllButtonStates === 'function') {
                  updateAllButtonStates();
              }
          }, 600);

          setTimeout(() => {
              const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
              
              // 检查是否有异常状态的桌位
              let abnormalTables = [];
              Object.keys(mesasEstado).forEach(mesaKey => {
                  const estado = mesasEstado[mesaKey];
                  if (estado.estado === 'ocupada' && (!estado.total || estado.total === 0)) {
                      abnormalTables.push(mesaKey);
                  }
              });
              
              // 如果发现异常桌位，提供清理选项
              if (abnormalTables.length > 0) {
                  
                  // 全局清理函数
                  window.cleanAbnormalTables = function() {
                      const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                      let cleaned = 0;
                      
                      abnormalTables.forEach(mesaKey => {
                          if (mesasEstado[mesaKey] && mesasEstado[mesaKey].estado === 'ocupada' && (!mesasEstado[mesaKey].total || mesasEstado[mesaKey].total === 0)) {
                              mesasEstado[mesaKey].estado = 'libre';
                              mesasEstado[mesaKey].total = 0;
                              mesasEstado[mesaKey].orderId = null;
                              cleaned++;
                          }
                      });
                      
                      localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
                      
                      // 刷新显示
                      if (typeof renderizarMesas === 'function') {
                          renderizarMesas('data-cleanup');
                      }
                  };
              }
              
              // 检查localStorage键格式混乱问题
              const keys = Object.keys(mesasEstado);
              const numericKeys = keys.filter(k => /^\d+$/.test(k));
              const prefixKeys = keys.filter(k => /^(Mesa|Table|餐桌)\s+\d+$/.test(k));
              
              if (numericKeys.length > 0 || keys.length !== prefixKeys.length) {
                  console.warn(`[键格式检查] 发现混乱的localStorage键:`, {
                      '数字键': numericKeys,
                      '前缀键': prefixKeys,
                      '其他键': keys.filter(k => !numericKeys.includes(k) && !prefixKeys.includes(k))
                  });
                  console.warn(`[键格式检查] 可输入 normalizeTableKeys() 来标准化键格式`);
                  
                  // 键格式标准化函数
                  window.normalizeTableKeys = function() {
                      const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                      const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
                      const newMesasEstado = {};
                      const newCarritos = {};
                      const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) || '餐桌';
                      
                      // 标准化mesas_estado
                      Object.keys(mesasEstado).forEach(oldKey => {
                          const tableNumber = oldKey.replace(/^(Mesa|Table|餐桌)\s*/, '');
                          const newKey = `${tablePrefix} ${tableNumber}`;
                          newMesasEstado[newKey] = mesasEstado[oldKey];
                      });
                      
                      // 标准化carritos_mesas
                      Object.keys(carritosGuardados).forEach(oldKey => {
                          const tableNumber = oldKey.replace(/^(Mesa|Table|餐桌)\s*/, '');
                          const newKey = `${tablePrefix} ${tableNumber}`;
                          newCarritos[newKey] = carritosGuardados[oldKey];
                      });
                      
                      localStorage.setItem('mesas_estado', JSON.stringify(newMesasEstado));
                      localStorage.setItem('carritos_mesas', JSON.stringify(newCarritos));
                      location.reload(); // 刷新页面应用更改
                  };
              }
          }, 1000);
      });
  </script>
