          gridTemplateColumns: {
            'tpv-products': 'repeat(6, minmax(0, 1fr))',
            'tpv-tables': 'repeat(8, minmax(0, 1fr))',
            'tpv-dashboard': 'repeat(4, minmax(0, 1fr))',
          },
          keyframes: {
            'fade-in-up': { '0%': { opacity: '0', transform: 'translateY(20px)' }, '100%': { opacity: '1', transform: 'translateY(0)' } },
            'slide-left': { '0%': { transform: 'translateX(100%)', opacity: '0' }, '100%': { transform: 'translateX(0)', opacity: '1' } },
            'slide-right': { '0%': { transform: 'translateX(-100%)', opacity: '0' }, '100%': { transform: 'translateX(0)', opacity: '1' } },
            'slide-up': { '0%': { transform: 'translateY(100%)', opacity: '0' }, '100%': { transform: 'translateY(0)', opacity: '1' } }
          },
          animation: {
            'fade-in-up': 'fade-in-up 0.6s ease-out forwards',
            'slide-left': 'slide-left 0.5s ease-out forwards',
            'slide-right': 'slide-right 0.5s ease-out forwards',
            'slide-up': 'slide-up 0.5s ease-out forwards'
          }
        }
      },
      darkMode: 'class'
    }
  </script>
  <!-- ✅ jQuery PRIMERO antes de Select2 -->
  <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
  <!-- ✅ jQuery UI for Sortable (产品拖拽排序) -->
  <link rel="stylesheet" href="https://code.jquery.com/ui/1.13.2/themes/base/jquery-ui.css">
  <script src="https://code.jquery.com/ui/1.13.2/jquery-ui.min.js"></script>
  <!-- ✅ Select2 CSS y JS -->
  <link href="https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/css/select2.min.css" rel="stylesheet" />
  <script src="https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/js/select2.min.js"></script>
  <!-- ✅ SweetAlert2 -->
  <script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>
  <!-- ✅ Toastify CSS 和 JS -->
  <link rel="stylesheet" type="text/css" href="https://cdn.jsdelivr.net/npm/toastify-js/src/toastify.min.css">
  <script src="https://cdn.jsdelivr.net/npm/toastify-js"></script>
  
  <!-- Variables globales -->
  <script>
    // 强制清除缓存和版本检查 v2.0.1
    
    // 检查当前语言cookie
    // 🔥 钱箱控制函数 - 优化版：秒开钱箱 + 离线支持
    async function abrirCajonDinero() {
      // 检查 CLODOP 是否启用
      if (!clodopConfig || !clodopConfig.enabled) {
        throw new Error('CLODOP 服务未启用,无法打开钱箱');
      }

      // 🔥 优先尝试主函数
      if (typeof clodopOpenCashDrawer === 'function') {
        const result = clodopOpenCashDrawer();
        if (result) {
          return true;
        }
        console.warn('[RUIYI POS] 主钱箱函数失败，尝试备用方案...');
      }

      // 🔥 备用方案1: 离线钱箱函数
      if (typeof openCashDrawerOffline === 'function') {
        const offlineResult = openCashDrawerOffline();
        if (offlineResult) {
          console.log('[RUIYI POS] ✅ 离线钱箱备用方案成功');
          return true;
        }
      }

      // 🔥 备用方案2: 安全获取 LODOP（避免 alert 副作用）
      if (typeof _safeGetLodop === 'function') {
        try {
          const LODOP = _safeGetLodop();
          if (LODOP) {
            const drawerPrinter = clodopConfig.drawerPrinter || clodopConfig.defaultPrinter;
            if (drawerPrinter) {
              const drawerCmd = String.fromCharCode(27, 112, 0, 128, 128);

              if (drawerPrinter.toUpperCase().startsWith('COM')) {
                LODOP.WRITE_PORT_DATA(drawerPrinter, drawerCmd);
              } else {
                LODOP.PRINT_INIT("RUIYI-钱箱控制-备用");
                LODOP.SET_PRINTER_INDEX(drawerPrinter);
                LODOP.SEND_PRINT_RAWDATA(drawerCmd);
                const drawerCmd2 = String.fromCharCode(27, 112, 1, 128, 128);
                LODOP.SEND_PRINT_RAWDATA(drawerCmd2);
              }
              console.log('[RUIYI POS] ✅ 安全获取 LODOP 钱箱成功');
              return true;
            }
          }
        } catch (e) {
          console.error('[RUIYI POS] 备用方案2失败:', e);
        }
      }

      throw new Error('钱箱命令发送失败（所有方案均失败）');
    }
    // 导出到全局作用域
    window.abrirCajonDinero = abrirCajonDinero;

    // 🔥 同步版本的开钱箱函数，供需要快速响应的场景使用（支持离线）
    function openDrawerSync() {
      // 优先使用主函数
      if (typeof clodopOpenCashDrawer === 'function') {
        const result = clodopOpenCashDrawer();
        if (result) return true;
      }

      // 备用: 离线钱箱函数
      if (typeof openCashDrawerOffline === 'function') {
        return openCashDrawerOffline();
      }

      return false;
    }
    window.openDrawerSync = openDrawerSync;

    /**
     * 🔥 用户友好的打印机/钱箱配置提示对话框
     * 用于替代所有 CLODOP 相关的错误弹窗
     */
    function showPrinterConfigDialog(customMessage = null) {
      const defaultMessage = '<?php echo ruiyi_translate(
        "El servicio de impresora necesita ser configurado. Por favor haga clic en el botón de abajo para completar la configuración.",
        "The printer service needs to be configured. Please click the button below to complete the configuration.",
        "打印服务需要配置。请点击下方按钮完成配置。"
      ); ?>';

      Swal.fire({
        icon: 'info',
        title: '<?php echo ruiyi_translate("Configuración de impresora", "Printer Configuration", "打印机配置"); ?>',
        html: `
          <div class="text-center">
            <p class="text-gray-600 mb-4">${customMessage || defaultMessage}</p>
            <div class="flex justify-center gap-3 mt-4">
              <button id="printer-config-refresh-btn" class="px-6 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors flex items-center gap-2">
                <i class="fas fa-sync-alt"></i>
                <span><?php echo ruiyi_translate("Actualizar y configurar", "Refresh and configure", "刷新完成配置"); ?></span>
              </button>
            </div>
          </div>
        `,
        showConfirmButton: false,
        showCancelButton: false,
        allowOutsideClick: true,
        didOpen: () => {
          const refreshBtn = document.getElementById('printer-config-refresh-btn');
          if (refreshBtn) {
            refreshBtn.addEventListener('click', () => {
              Swal.close();
              window.location.reload();
            });
          }
        }
      });
    }
    // 导出到全局作用域
    window.showPrinterConfigDialog = showPrinterConfigDialog;

    /**
     * 🔥 用户友好的通用错误提示对话框
     * 显示友好的错误信息和刷新按钮
     */
    function showFriendlyErrorDialog(title, message, showRefresh = true) {
      const buttons = showRefresh ? `
        <div class="flex justify-center gap-3 mt-4">
          <button id="error-refresh-btn" class="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors flex items-center gap-2">
            <i class="fas fa-sync-alt"></i>
            <span><?php echo ruiyi_translate("Actualizar página", "Refresh page", "刷新页面"); ?></span>
          </button>
        </div>
      ` : '';

      Swal.fire({
        icon: 'info',
        title: title,
        html: `
          <div class="text-center">
            <p class="text-gray-600 mb-4">${message}</p>
            ${buttons}
          </div>
        `,
        showConfirmButton: !showRefresh,
        confirmButtonText: '<?php echo ruiyi_translate("Aceptar", "OK", "确定"); ?>',
        showCancelButton: showRefresh,
        cancelButtonText: '<?php echo ruiyi_translate("Cerrar", "Close", "关闭"); ?>',
        allowOutsideClick: true,
        didOpen: () => {
          if (showRefresh) {
            const refreshBtn = document.getElementById('error-refresh-btn');
            if (refreshBtn) {
              refreshBtn.addEventListener('click', () => {
                Swal.close();
                window.location.reload();
              });
            }
          }
        }
      });
    }

    var PHP_LANG = '<?php echo defined("RUIYI_CURRENT_LANG") ? RUIYI_CURRENT_LANG : "zh"; ?>';

    function checkCurrentLanguage() {
      const cookies = document.cookie.split(';');
      for (let cookie of cookies) {
        const [name, value] = cookie.trim().split('=');
        if (name === 'ruiyi_language') {
          return value;
        }
      }
      return null;
    }

    const detectedLang = checkCurrentLanguage() || PHP_LANG;

    // 🔥 默认语言持久化（仅在没有语言cookie时设置）
    if (!checkCurrentLanguage()) {
      document.cookie = 'ruiyi_language=' + PHP_LANG + '; path=/; max-age=31536000';
      localStorage.setItem('ruiyi_pos_language', PHP_LANG);
    }

    // 🔥 resolveGlobalTableNumber 已提取到 js/modules/pos-table-resolver.js

    // Variables globales centralizadas para todo el sistema
    let cart = []; // Carrito global
    window.cart = cart; // 确保window.cart也指向同一个数组

    // 🔥 选中的购物车项索引（用于乘法功能）
    let selectedCartItemIndex = null;
    window.selectedCartItemIndex = selectedCartItemIndex;

    // 选中购物车项的函数
    function selectCartItem(index) {
      selectedCartItemIndex = index;
      window.selectedCartItemIndex = index;
      renderCart(); // 重新渲染以更新选中状态
    }
    // 🔥 暴露到全局作用域，使 onclick 属性可以访问
    window.selectCartItem = selectCartItem;

    // 清除选中状态
    function clearCartSelection() {
      selectedCartItemIndex = null;
      window.selectedCartItemIndex = null;
    }
    window.clearCartSelection = clearCartSelection;

    // 🔥 当前折扣百分比（全局变量）
    window.currentDiscountPercent = 0;

    // 🔥 更新折扣标识显示（全局函数）
    function updateDiscountBadge() {
      const discountBadge = document.getElementById('discount-badge');
      const discountPercentDisplay = document.getElementById('discount-percent-display');

      if (!discountBadge || !discountPercentDisplay) return;

      // 🔥 购物车为空时，清除折扣状态并隐藏标识
      if (!cart || cart.length === 0) {
        window.currentDiscountPercent = 0;
        discountBadge.classList.add('hidden');
        return;
      }

      if (window.currentDiscountPercent && window.currentDiscountPercent > 0) {
        // 显示折扣百分比标识
        discountPercentDisplay.textContent = `${window.currentDiscountPercent}%`;
        discountBadge.classList.remove('hidden');
      } else {
        // 隐藏折扣标识
        discountBadge.classList.add('hidden');
      }
    }
    window.updateDiscountBadge = updateDiscountBadge;

    // 同步购物车函数 - 确保cart和window.cart始终保持同步
    function syncCart(newCart = []) {
        cart = newCart;
        window.cart = cart;
        if (!cart || cart.length === 0) {
            if (typeof ruiyiSetCartTableIdentity === 'function') {
                ruiyiSetCartTableIdentity('', 'syncCart:empty');
            }
            window.cartModified = false;
        }
        // 🔥 同步后保存到localStorage（非桌位模式）
        savePosCartToStorage();
    }

    function ruiyiGetActiveTableViewMode() {
        const parseMode = (raw) => {
            if (!raw) return null;
            try {
                const parsed = JSON.parse(raw);
                return parsed && typeof parsed === 'object' ? parsed : null;
            } catch (error) {
                return null;
            }
        };
        const current = parseMode(sessionStorage.getItem('tableViewMode'));
        if (current) return current;

        const legacy = parseMode(sessionStorage.getItem('isViewMode'));
        if (legacy) {
            try {
                sessionStorage.setItem('tableViewMode', JSON.stringify(legacy));
            } catch (error) {
                // sessionStorage may be unavailable in private/error states.
            }
        }
        return legacy;
    }
    window.ruiyiGetActiveTableViewMode = ruiyiGetActiveTableViewMode;

    function ruiyiSafeResolveGlobalTableNumber(tableNumber) {
        const raw = String(tableNumber ?? '').trim();
        if (!raw) return '';
        const resolverInput = /^\d+$/.test(raw) ? `Mesa ${raw}` : raw;
        return typeof resolveGlobalTableNumber === 'function'
            ? resolveGlobalTableNumber(resolverInput)
            : raw.replace(/^(餐桌|Mesa|Table)\s*/i, '').trim();
    }
    window.ruiyiSafeResolveGlobalTableNumber = ruiyiSafeResolveGlobalTableNumber;

    function ruiyiGetTerrazaDebugInfo(tableNumber) {
        const raw = String(tableNumber ?? '').trim();
        const resolved = raw
            ? (typeof ruiyiSafeResolveGlobalTableNumber === 'function'
                ? ruiyiSafeResolveGlobalTableNumber(raw)
                : (typeof resolveGlobalTableNumber === 'function' ? resolveGlobalTableNumber(raw) : raw))
            : '';
        const mappingsRaw = window.tableCategoryMappings || {};
        const mappings = Array.isArray(mappingsRaw) ? mappingsRaw : Object.values(mappingsRaw || {});
        const normalize = (value) => String(value ?? '').replace(/\s+/g, '').toUpperCase();
        const rawNorm = normalize(raw);
        const resolvedNorm = normalize(resolved);
        const mapping = mappings.find((m) => {
            const globalNumber = normalize(m && m.global_table_number);
            const localNumber = normalize(m && m.local_table_number);
            const categoryName = normalize(m && m.category_name);
            const categoryDisplay = normalize(m && m.category_display_name);
            const displayName = normalize(m && m.display_name);
            return (resolvedNorm && globalNumber === resolvedNorm) ||
                (rawNorm && (
                    rawNorm === globalNumber ||
                    rawNorm === localNumber ||
                    rawNorm === categoryDisplay ||
                    rawNorm === displayName ||
                    rawNorm === `${categoryName}${localNumber}` ||
                    rawNorm === `${categoryDisplay}${localNumber}`
                ));
        }) || null;
        const label = [
            raw,
            resolved,
            mapping?.category_name,
            mapping?.category_display_name,
            mapping?.display_name
        ].filter(Boolean).join('|').toUpperCase();

        return {
            raw,
            resolved,
            mapping,
            isTerraza: label.includes('TERRAZA')
        };
    }

    function ruiyiLogTerrazaDebug(stage, payload = {}) {
        try {
            const tableValue = payload.table_number ||
                payload.tableNumber ||
                payload.tableNum ||
                payload.table ||
                payload.raw ||
                document.getElementById('table-number')?.value ||
                '';
            const info = ruiyiGetTerrazaDebugInfo(tableValue);
            if (!info.isTerraza) {
                return;
            }
            console.log('[TERRAZA-DEBUG] ' + stage, Object.assign({ tableDebug: info }, payload));
        } catch (error) {
            console.warn('[TERRAZA-DEBUG] log failed:', stage, error);
        }
    }
    window.ruiyiGetTerrazaDebugInfo = ruiyiGetTerrazaDebugInfo;
    window.ruiyiLogTerrazaDebug = ruiyiLogTerrazaDebug;

    // 🔥🔥🔥 收银模块购物车持久化功能 - 刷新页面保留购物车内容
    const POS_CART_STORAGE_KEY = 'pos_cashier_cart';

    // 🔥🔥🔥 关键修复：防止初始化时的空购物车覆盖已保存的数据
    // 在购物车恢复完成前，不允许保存（避免空购物车覆盖）
    let _posCartRestoreComplete = false;
    window._posCartRestoreComplete = _posCartRestoreComplete;

    /**
     * 保存购物车到localStorage（仅非桌位模式/外卖模式）
     */
    function savePosCartToStorage() {
        try {
            // 🔥🔥🔥 关键修复：在恢复完成前不保存，防止空购物车覆盖已保存的数据
            if (!_posCartRestoreComplete) {
                return;
            }

            // 🔥🔥🔥 改进判断：使用订单类型和桌位号来准确判断是否应该保存
            const tableNumber = document.getElementById('table-number')?.value.trim();
            const currentOrderType = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir';

            // 判断是否在实际的桌位模式（有桌位号且是堂食模式）
            // 外卖模式(llevar)下应该保存，即使 tableViewMode 有遗留值
            const isActualTableMode = tableNumber && currentOrderType === 'servir';

            // 桌位模式使用 mesas_estado，不使用这个持久化
            if (isActualTableMode) {
                return;
            }

            // 只保存非锁定的商品（收银模式/外卖模式的商品都是非锁定的）
            const cartToSave = cart.filter(item => !item.locked && item.quantity > 0);

            if (cartToSave.length > 0) {
                localStorage.setItem(POS_CART_STORAGE_KEY, JSON.stringify({
                    cart: cartToSave,
                    timestamp: Date.now(),
                    orderType: currentOrderType
                }));
            } else {
                // 购物车为空时清除存储
                localStorage.removeItem(POS_CART_STORAGE_KEY);
            }
        } catch (e) {
            // 保存失败静默处理
        }
    }
    window.savePosCartToStorage = savePosCartToStorage;

    /**
     * 从localStorage加载购物车（仅非桌位模式/外卖模式）
     */
    function loadPosCartFromStorage() {
        try {
            // 🔥🔥🔥 改进判断：使用订单类型和桌位号来准确判断是否应该加载
            const tableNumber = document.getElementById('table-number')?.value.trim();
            const currentOrderType = sessionStorage.getItem('tipoPedidoSeleccionado');

            // 如果有桌位号且是堂食模式，则不从这里加载
            // 外卖模式下应该加载，即使 tableViewMode 有遗留值
            const isActualTableMode = tableNumber && currentOrderType === 'servir';

            // 桌位模式不从这里加载
            if (isActualTableMode) {
                return false;
            }

            const savedData = localStorage.getItem(POS_CART_STORAGE_KEY);
            if (!savedData) {
                return false;
            }

            const { cart: savedCart, timestamp, orderType } = JSON.parse(savedData);

            // 检查数据是否过期（24小时）
            const maxAge = 24 * 60 * 60 * 1000; // 24小时
            if (Date.now() - timestamp > maxAge) {
                localStorage.removeItem(POS_CART_STORAGE_KEY);
                return false;
            }

            if (savedCart && Array.isArray(savedCart) && savedCart.length > 0) {
                // 恢复购物车
                cart = savedCart;
                window.cart = cart;

                // 恢复订单类型
                if (orderType) {
                    sessionStorage.setItem('tipoPedidoSeleccionado', orderType);
                }

                return true;
            }

            return false;
        } catch (e) {
            return false;
        }
    }
    window.loadPosCartFromStorage = loadPosCartFromStorage;

    /**
     * 清除保存的购物车数据（结账完成或手动清空时调用）
     */
    function clearPosCartStorage() {
        try {
            localStorage.removeItem(POS_CART_STORAGE_KEY);
        } catch (e) {
            // 清除失败静默处理
        }
    }
    window.clearPosCartStorage = clearPosCartStorage;

    // 🔥🔥🔥 页面加载时恢复收银购物车（非桌位模式）
    document.addEventListener('DOMContentLoaded', function() {
        // 延迟执行，确保其他初始化已完成
        setTimeout(() => {
            // 检查是否在桌位模式
            const tableNumber = document.getElementById('table-number')?.value.trim();
            const viewModeData = sessionStorage.getItem('tableViewMode');
            const isTableMode = tableNumber || viewModeData;

            if (!isTableMode) {
                // 非桌位模式：尝试从localStorage恢复购物车
                const restored = loadPosCartFromStorage();
                if (restored) {
                    // 🔥🔥🔥 关键：先设置恢复完成标志，再渲染
                    // 这样渲染时的 savePosCartToStorage 才会正常保存
                    _posCartRestoreComplete = true;
                    window._posCartRestoreComplete = true;

                    // 恢复成功，重新渲染购物车
                    if (typeof renderCart === 'function') {
                        renderCart();
                    }
                } else {
                    // 🔥 没有恢复数据，也要设置标志允许后续保存
                    _posCartRestoreComplete = true;
                    window._posCartRestoreComplete = true;
                }
            } else {
                // 🔥 桌位模式，设置标志（桌位模式有自己的持久化机制）
                _posCartRestoreComplete = true;
                window._posCartRestoreComplete = true;
            }
        }, 500); // 给其他初始化留足时间
    });

    // 🔥 PWA: Universal order submission function (handles online/offline)
    // Wait briefly for posDB to load (footer scripts). Keep this short so offline checkout is instant.
    async function waitForPosDB(maxWaitMs = 500) {
      // posDB can be loaded in footer; wait a bit if needed
      const start = Date.now();
      while (Date.now() - start < maxWaitMs) {
        if (typeof posDB !== 'undefined' && posDB) return posDB;
        if (typeof window !== 'undefined' && window.posDB) return window.posDB;
        await new Promise((r) => setTimeout(r, 100));
      }
      return null;
    }

    // 🔥 addPendingOrderFallbackIndexedDB 和 getPendingOrdersFallbackIndexedDB 已移至 pos-offline.js 模块

    function formatOfflineOrderTime(ts) {
      try {
        const d = new Date(ts || Date.now());
        return d.toLocaleString();
      } catch (e) {
        return '';
      }
    }

    async function loadOfflinePendingOrdersIntoHistory() {
      const panel = document.getElementById('offline-pending-orders-panel');
      const listEl = document.getElementById('offline-pending-orders-list');
      const emptyEl = document.getElementById('offline-pending-orders-empty');
      const countEl = document.getElementById('offline-pending-orders-count');

      if (!panel || !listEl || !emptyEl || !countEl) return;

      let pendingPayments = [];

      // 🔥 获取待同步支付（已结账但需要服务器确认的支付）- 只显示 PaymentQueue 中的条目
      try {
        if (typeof OfflineManager !== 'undefined' && OfflineManager.ensureDB) {
          const db = await OfflineManager.ensureDB();
          if (db && db.objectStoreNames.contains('pending_payments')) {
            const tx = db.transaction(['pending_payments'], 'readonly');
            const store = tx.objectStore('pending_payments');
            pendingPayments = await new Promise((resolve, reject) => {
              const getReq = store.getAll();
              getReq.onsuccess = () => resolve(getReq.result || []);
              getReq.onerror = () => reject(getReq.error);
            });
            // 只显示 pending 和 failed 状态的支付
            pendingPayments = pendingPayments.filter(p => p.status === 'pending' || p.status === 'failed');
          }
        }
      } catch (e) {
        console.warn('[Historial] Failed to read pending payments:', e);
        pendingPayments = [];
      }

      // 🔥 只统计 PaymentQueue 待同步数据
      const totalPending = pendingPayments.length;

      // Show panel if offline OR there are pending items
      const isOnline = navigator.onLine && window.RUIYI_POS?.isOnline !== false;
      if (!isOnline || totalPending > 0) {
        panel.classList.remove('hidden');
      } else {
        panel.classList.add('hidden');
        return;
      }

      countEl.textContent = String(totalPending);
      listEl.innerHTML = '';

      if (totalPending === 0) {
        emptyEl.classList.remove('hidden');
        return;
      }

      emptyEl.classList.add('hidden');

      // 🔥 显示待同步支付（PaymentQueue中的已结账订单）
      pendingPayments.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));
      pendingPayments.slice(0, 25).forEach((payment) => {
        const cartItems = payment.cartSnapshot || payment.cart || [];
        const itemsCount = Array.isArray(cartItems) ? cartItems.reduce((sum, it) => sum + (parseFloat(it.quantity) || 0), 0) : 0;

        // 🔥 修复：orderTotalAmount 是实际应付金额（已扣除折扣、餐券、公司票等）
        // 不需要再减任何抵扣，直接使用 orderTotalAmount 或 totalAmount
        // totalAmount 字段也是已扣除所有抵扣后的实际支付金额
        const finalTotal = parseFloat(payment.orderTotalAmount || payment.totalAmount || 0);
        const totalText = `€${finalTotal.toFixed(2)}`;

        const paymentMethod = payment.paymentMethod || '';
        const statusBadge = payment.status === 'failed'
          ? '<span class="ml-1 px-1.5 py-0.5 text-xs rounded bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-200"><?php echo ruiyi_translate('Error', 'Error', '失败'); ?></span>'
          : '';

        const row = document.createElement('div');
        row.className = 'bg-green-50/70 dark:bg-green-900/30 border border-green-200 dark:border-green-800 rounded-md p-3 flex items-start justify-between gap-3';
        // 🔥 修复：移除订单类型标签（外卖/桌位），只显示时间、数量、支付方式
        row.innerHTML = `
          <div class="min-w-0">
            <div class="flex items-center gap-2 flex-wrap">
              <span class="text-xs text-gray-600 dark:text-gray-300">${formatOfflineOrderTime(payment.timestamp)}</span>
              <span class="text-xs text-gray-600 dark:text-gray-300">• ${itemsCount} <?php echo ruiyi_translate('artículos', 'items', '件'); ?></span>
              ${paymentMethod ? `<span class="text-xs text-gray-600 dark:text-gray-300">• ${paymentMethod}</span>` : ''}
              ${statusBadge}
            </div>
            <div class="mt-1 text-sm text-green-800 dark:text-green-100">
              <i class="fas fa-check-circle mr-1"></i><?php echo ruiyi_translate('Pagado - pendiente sincronizar', 'Paid - pending sync', '已结账 - 等待同步'); ?>
            </div>
          </div>
          <div class="text-right flex-shrink-0">
            <div class="text-sm font-semibold text-green-700 dark:text-green-300">${totalText}</div>
          </div>
        `;
        listEl.appendChild(row);
      });
    }

    async function submitOrderUniversal(orderParams) {
      const isOnline = navigator.onLine && window.RUIYI_POS?.isOnline !== false;
      var ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
      // 🔥 使用 NonceManager 获取最新的 nonce，避免过期问题
      var ajaxNonce = (window.NonceManager && window.NonceManager.get()) || window.RUIYI_POS?.nonce || currentNonce;

      // 🔥 skipCartClear: 如果为true，保存订单后不清空购物车（用于桌位结账流程）
      const skipCartClear = orderParams.skipCartClear === true;
      // Try online submission first if online
      if (isOnline) {
        try {
          const formData = new URLSearchParams();
          formData.append('action', 'ruiyi_pos_create_order');
          formData.append('nonce', ajaxNonce);
          
          // 🍽️ 分离自助餐商品和普通商品
          // 🔥 supplements 已在弹窗关闭时合入 customName/customPrice，无需额外转换
          let regularCartItems = orderParams.cart || [];
          let buffetCartItems = [];
          if (Array.isArray(regularCartItems)) {
              buffetCartItems = regularCartItems.filter(item => item.is_buffet);
              regularCartItems = regularCartItems.filter(item => !item.is_buffet);
          }

          // Add all order parameters
          if (regularCartItems.length > 0) formData.append('cart', JSON.stringify(regularCartItems));
          if (buffetCartItems.length > 0) formData.append('buffet_items', JSON.stringify(buffetCartItems));
          if (orderParams.table_number !== undefined) formData.append('table_number', orderParams.table_number);
          if (orderParams.order_type) formData.append('order_type', orderParams.order_type);
          if (orderParams.payment_method) formData.append('payment_method', orderParams.payment_method);
          if (orderParams.tip_amount !== undefined) formData.append('tip_amount', orderParams.tip_amount);
          if (orderParams.is_addition !== undefined) formData.append('is_addition', orderParams.is_addition);
          if (orderParams.discount !== undefined) formData.append('discount', orderParams.discount);
          if (orderParams.client) formData.append('client', orderParams.client);
          if (orderParams.customer_info) formData.append('customer_info', JSON.stringify(orderParams.customer_info));
          if (orderParams.received_amount !== undefined) formData.append('received_amount', orderParams.received_amount);
          if (orderParams.change_amount !== undefined) formData.append('change_amount', orderParams.change_amount);
          if (orderParams.cash_amount !== undefined) formData.append('cash_amount', orderParams.cash_amount);
          if (orderParams.card_amount !== undefined) formData.append('card_amount', orderParams.card_amount);
          if (orderParams.cheque_restaurante_amount !== undefined && orderParams.cheque_restaurante_amount > 0) {
              formData.append('cheque_restaurante_amount', orderParams.cheque_restaurante_amount);
          }

          // 🔥 添加手动折扣信息，用于保存到订单元数据
          if (orderParams.discount_percent !== undefined && orderParams.discount_percent > 0) {
              formData.append('discount_percent', orderParams.discount_percent);
          }
          if (orderParams.discount_amount !== undefined && orderParams.discount_amount > 0) {
              formData.append('discount_amount', orderParams.discount_amount);
          }

          const response = await fetch(ajaxUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: formData
          });

          if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
          }

          const data = await response.json();
          if (data.success) {
            // 🔥 在线订单成功后执行后续操作

            // 🔥 关键修复：只有在非skipCartClear模式下才清空购物车
            // 桌位结账流程需要保留购物车数据，让商品变为锁定状态
            if (!skipCartClear) {
              // 清空购物车
              if (typeof cart !== 'undefined') {
                cart = [];
              }
              if (typeof window.cart !== 'undefined') {
                window.cart = [];
              }
              if (typeof renderCart === 'function') {
                renderCart();
              }

              // 🔥 清除收银购物车持久化存储
              if (typeof clearPosCartStorage === 'function') {
                clearPosCartStorage();
              }

              // 打开钱箱（现金/混合支付）
              const paymentMethodOnline = orderParams.payment_method;
              if ((paymentMethodOnline === 'cash' || paymentMethodOnline === 'mixed') && typeof abrirCajonDinero === 'function') {
                abrirCajonDinero().then(() => {
                }).catch(err => {
                  console.error('[PWA] 打开钱箱失败（在线）:', err);
                });
              }

              // 重置支付状态
              if (typeof resetAllPaymentStates === 'function') {
                resetAllPaymentStates('online_order_complete');
              }
            }

            return data; // Successfully submitted online
          } else {
            throw new Error(data.message || 'Order creation failed');
          }
        } catch (error) {
          console.warn('[PWA] Online submission failed, saving offline:', error);
          // Fall through to offline save
        }
      }

      // Save offline (either offline mode or online submission failed)
      const tempOrderId = 'OFFLINE_' + Date.now();
      const orderToSave = {
        id: tempOrderId,
        ...orderParams,
        timestamp: Date.now(),
        status: 'pending',
        apiUrl: ajaxUrl
      };

      try {
        // ⚡ Offline should be instant: don't wait for posDB, write directly.
        if (!isOnline) {
          await addPendingOrderFallbackIndexedDB(orderToSave);
        } else {
          // Online-but-request-failed: try posDB quickly, otherwise fallback to direct IndexedDB.
          const dbInstance =
            (typeof window !== 'undefined' && window.posDB) ? window.posDB : await waitForPosDB(500);

          if (dbInstance && typeof dbInstance.addPendingOrder === 'function') {
            if (!dbInstance.db && typeof dbInstance.init === 'function') {
              await dbInstance.init();
            }
            await dbInstance.addPendingOrder(orderToSave);
          } else {
            await addPendingOrderFallbackIndexedDB(orderToSave);
          }
        }
        // 🔥 关键修复：只有在非skipCartClear模式下才清空购物车
        // 桌位结账流程需要保留购物车数据，让商品变为锁定状态
        if (!skipCartClear) {
          // 清空购物车
          if (typeof cart !== 'undefined') {
            cart = [];
          }
          if (typeof window.cart !== 'undefined') {
            window.cart = [];
          }
          if (typeof renderCart === 'function') {
            renderCart();
          }

          // 🔥 清除收银购物车持久化存储
          if (typeof clearPosCartStorage === 'function') {
            clearPosCartStorage();
          }

          // 打开钱箱（现金/混合支付）
          const paymentMethod = orderParams.payment_method;
          if ((paymentMethod === 'cash' || paymentMethod === 'mixed') && typeof abrirCajonDinero === 'function') {
            abrirCajonDinero().then(() => {
            }).catch(err => {
            });
          }

          // 重置支付状态
          if (typeof resetAllPaymentStates === 'function') {
            resetAllPaymentStates('offline_order_complete');
          }
        }

        // Calculate total for offline order (含 supplements)
        let orderTotal = 0;
        if (orderParams.cart && Array.isArray(orderParams.cart)) {
          orderTotal = orderParams.cart.reduce((sum, item) => {
            const price = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
            return sum + (price * item.quantity);
          }, 0);
          if (orderParams.discount) {
            orderTotal -= parseFloat(orderParams.discount);
          }
        }

        // 🔥 Background Sync (if supported): sync when back online - 不阻塞，使用 setTimeout
        setTimeout(() => {
          try {
            if ('serviceWorker' in navigator && navigator.serviceWorker.controller) {
              navigator.serviceWorker.ready.then(reg => {
                if (reg && reg.sync && typeof reg.sync.register === 'function') {
                  reg.sync.register('sync-orders').catch(e => console.warn('[SW] sync-orders registration failed:', e.message));
                }
              }).catch(e => console.warn('[SW] serviceWorker.ready failed:', e.message));
            }
          } catch (e) {
            console.warn('[SW] background sync setup failed:', e.message);
          }
        }, 100);

        // 🔥 返回离线订单成功响应
        const offlineResponse = {
          success: true,
          data: {
            order_id: tempOrderId,
            total: orderTotal
          },
          offline: true,
          message: 'Order saved offline and will sync when online'
        };
        return offlineResponse;
      } catch (dbError) {
        console.error('[PWA] ❌ 离线保存失败:', dbError);
        console.error('[PWA] 错误详情:', dbError.message, dbError.stack);
        throw new Error('Failed to save order offline: ' + dbError.message);
      }
    }

    // Make function globally available
    window.submitOrderUniversal = submitOrderUniversal;
    // Expose for other handlers (history refresh, etc.)
    window.loadOfflinePendingOrdersIntoHistory = loadOfflinePendingOrdersIntoHistory;

    // Refresh historial pending list + server history when an offline order gets synced
    // 🔥 PWA同步事件：只刷新离线待同步面板，不重新加载历史订单（用户手动刷新即可）
    window.addEventListener('orderSynced', () => {
      try {
        const historialSection = document.getElementById('historial');
        if (historialSection && !historialSection.classList.contains('hidden')) {
          setTimeout(() => {
            loadOfflinePendingOrdersIntoHistory();
          }, 500);
        }
      } catch (e) {
        console.error('[PWA] Error refreshing history after sync:', e);
      }
    });

    window.addEventListener('ordersSynced', (event) => {
      try {
        const historialSection = document.getElementById('historial');
        if (historialSection && !historialSection.classList.contains('hidden')) {
          setTimeout(() => {
            loadOfflinePendingOrdersIntoHistory();
          }, 500);
        }
      } catch (error) {
        console.error('[PWA] Error refreshing history after bulk sync:', error);
      }
    });
    
    // 🔥 PWA: Immediate sync function (works without posSync)
    async function triggerImmediateSync() {
      // Try to use posSync if available
      if (window.posSync && typeof window.posSync.sync === 'function') {
        await window.posSync.sync();
        return;
      }
      
      // Fallback: Direct sync using IndexedDB and fetch
      await syncPendingOrdersDirect();
    }
    
    // 🔥 PWA: Direct sync function (doesn't require posSync)
    // Add sync lock to prevent multiple simultaneous syncs
    let syncInProgress = false;
    let lastSyncTime = 0;
    const SYNC_COOLDOWN = 2000; // 2 seconds cooldown between syncs
    
    async function syncPendingOrdersDirect() {
      // Prevent duplicate syncs
      const now = Date.now();
      if (syncInProgress) {
        return;
      }
      if (now - lastSyncTime < SYNC_COOLDOWN) {
        return;
      }
      
      syncInProgress = true;
      lastSyncTime = now;
      
      try {
        // Get pending orders directly from IndexedDB
        const pendingOrders = await getPendingOrdersDirect();
        
        if (pendingOrders.length === 0) {
          // No modals - just return silently
          return;
        }
        
        // No progress modal - sync happens silently in background
        
        let syncedCount = 0;
        let failedCount = 0;
        let offlineOrdersSynced = 0; // 🔥 统计真正的离线订单同步数量

        var ajaxUrl = window.RUIYI_POS?.ajaxUrl || window.ajaxUrl || '<?php echo esc_url(admin_url("admin-ajax.php")); ?>';
        const nonce = window.RUIYI_POS?.nonce || '<?php echo esc_js(wp_create_nonce("ruiyi_pos_nonce")); ?>';
        
        // 🔥 CRITICAL: Sort orders to sync order CREATIONS before payment COMPLETIONS
        // This ensures orders exist on server before payment completion is attempted
        const sortedOrders = pendingOrders.sort((a, b) => {
          const aHasOrderIds = a.order_ids && (Array.isArray(a.order_ids) || (typeof a.order_ids === 'string' && a.order_ids.length > 0));
          const bHasOrderIds = b.order_ids && (Array.isArray(b.order_ids) || (typeof b.order_ids === 'string' && b.order_ids.length > 0));
          
          // Order creations (no order_ids) come first
          if (!aHasOrderIds && bHasOrderIds) return -1;
          if (aHasOrderIds && !bHasOrderIds) return 1;
          
          // If both are same type, sort by timestamp (older first)
          return (a.timestamp || 0) - (b.timestamp || 0);
        });
                
        // 🔥 Track mapping of OFFLINE_ IDs to real order IDs
        const offlineIdToRealIdMap = {};
        
        for (let i = 0; i < sortedOrders.length; i++) {
          const order = sortedOrders[i];
          try {
            
            // 🔥 PWA: Check if this is a payment completion (has order_ids) or new order (has cart)
            let orderIds = order.order_ids;
            if (orderIds && typeof orderIds === 'string') {
              try {
                orderIds = JSON.parse(orderIds);
              } catch (e) {
                console.warn(`[PWA] Failed to parse order_ids:`, e);
              }
            }
            
            let result;
            
            if (orderIds && Array.isArray(orderIds) && orderIds.length > 0) {
              // 🔥 First, try to replace OFFLINE_ IDs with real IDs from the map
              orderIds = orderIds.map(id => {
                const idStr = String(id);
                if (idStr.startsWith('OFFLINE_') && offlineIdToRealIdMap[idStr]) {
                  return offlineIdToRealIdMap[idStr];
                }
                return idStr;
              });
              
              // Check if order_ids still contain OFFLINE_ IDs (orders that don't exist on server)
              const hasOfflineIds = orderIds.some(id => String(id).startsWith('OFFLINE_') || String(id).includes('OFFLINE'));
              
              if (hasOfflineIds && order.cart && Array.isArray(order.cart) && order.cart.length > 0) {                
                // Create orders first
                const createFormData = new FormData();
                createFormData.append('action', 'ruiyi_pos_create_order');
                createFormData.append('nonce', nonce);
                createFormData.append('cart', JSON.stringify(order.cart));
                createFormData.append('discount', order.discount || 0);
                createFormData.append('table_number', order.table_number || '');
                createFormData.append('client', order.client || '');
                createFormData.append('order_type', order.order_type || 'servir');
                createFormData.append('payment_method', order.payment_method || 'cash');
                
                if (order.customer_info) {
                  createFormData.append('customer_info', JSON.stringify(order.customer_info));
                }
                if (order.is_addition !== undefined) {
                  createFormData.append('is_addition', order.is_addition);
                }
                createFormData.append('offline_order', '1');
                
                const createResponse = await fetch(ajaxUrl, {
                  method: 'POST',
                  body: createFormData,
                });
                
                if (!createResponse.ok) {
                  throw new Error(`Failed to create orders: HTTP ${createResponse.status}`);
                }
                
                const createResult = await createResponse.json();
                if (!createResult.success) {
                  throw new Error(createResult.message || 'Failed to create orders');
                }
                
                // Get created order IDs
                const createdOrderIds = [];
                if (createResult.data && createResult.data.order_id) {
                  createdOrderIds.push(String(createResult.data.order_id));
                } else if (createResult.data && Array.isArray(createResult.data.orders)) {
                  createdOrderIds.push(...createResult.data.orders.map(o => String(o.id || o.order_id)));
                }
                
                if (createdOrderIds.length === 0) {
                  throw new Error('No order IDs returned from order creation');
                }
                
                orderIds = createdOrderIds; // Use real order IDs
              }
              
              // Complete payment for orders
              let formData = new FormData();
              formData.append('action', 'ruiyi_pos_complete_multiple_orders');
              formData.append('nonce', nonce);
              formData.append('order_ids', JSON.stringify(orderIds));
              formData.append('payment_method', order.payment_method || 'cash');
              formData.append('table_number', order.table_number || '');
              formData.append('order_type', order.order_type || 'servir');
              formData.append('total_amount', order.total_amount || 0);
              
              if (order.received_amount !== undefined) {
                formData.append('received_amount', order.received_amount);
              }
              if (order.change_amount !== undefined) {
                formData.append('change_amount', order.change_amount);
              }
              if (order.cash_amount !== undefined) {
                formData.append('cash_amount', order.cash_amount);
              }
              if (order.card_amount !== undefined) {
                formData.append('card_amount', order.card_amount);
              }
              if (order.company_ticket_amount !== undefined) {
                formData.append('company_ticket_amount', order.company_ticket_amount);
              }
              if (order.original_total_amount !== undefined) {
                formData.append('original_total_amount', order.original_total_amount);
              }
              if (order.ticket_change_amount !== undefined) {
                formData.append('ticket_change_amount', order.ticket_change_amount);
              }
              if (order.customer_info) {
                formData.append('customer_info', JSON.stringify(order.customer_info));
              }
              formData.append('offline_order', '1');
              
              let response = await fetch(ajaxUrl, {
                method: 'POST',
                body: formData,
              });
              
              if (!response.ok) {
                const errorText = await response.text();
                let errorJson = null;
                try {
                  errorJson = JSON.parse(errorText);
                } catch (e) {
                  // If not JSON, continue to check if we should create orders
                  console.warn(`[PWA] Payment completion failed with non-JSON error:`, errorText.substring(0, 200));
                }
                
                // 🔥 CRITICAL: Only try to create orders if order_ids contain OFFLINE_ IDs
                // If order_ids are real server IDs, don't try to create orders - the error is something else
                const hasOfflineIds = orderIds && Array.isArray(orderIds) && orderIds.some(id => 
                  String(id).startsWith('OFFLINE_') || String(id).includes('OFFLINE')
                );
                
                // Also check if error message indicates order not found (even for real IDs)
                const isOrderNotFound = errorJson?.data?.failed_orders?.some(fo => 
                  fo.reason && (fo.reason.includes('未找到') || fo.reason.includes('not found') || fo.reason.includes('找不到'))
                ) || errorJson?.data?.message?.includes('未找到') || errorJson?.data?.message?.includes('not found') || errorJson?.data?.message?.includes('找不到');
                
                // Only create orders if:
                // 1. order_ids contain OFFLINE_ IDs (orders don't exist on server), OR
                // 2. Error explicitly says "order not found" AND we have cart data
                const shouldCreateOrders = (
                  (hasOfflineIds || isOrderNotFound) && 
                  order.cart && 
                  Array.isArray(order.cart) && 
                  order.cart.length > 0
                );
                
                if (shouldCreateOrders) {
                  // Validate cart items have required fields
                  const invalidItems = order.cart.filter(item => !item.id && !item.product_id);
                  if (invalidItems.length > 0) {
                    console.error(`[PWA] ❌ Cart has ${invalidItems.length} items without id/product_id:`, invalidItems);
                    throw new Error(`Invalid cart items: ${invalidItems.length} items missing id/product_id`);
                  }
                  
                  // Create orders first
                  const createFormData = new FormData();
                  createFormData.append('action', 'ruiyi_pos_create_order');
                  createFormData.append('nonce', nonce);
                  createFormData.append('cart', JSON.stringify(order.cart));
                  // 🔥 Use discount_percent if available, otherwise use discount amount
                  const discountValue = order.discount_percent !== undefined ? order.discount_percent : (order.discount || 0);
                  createFormData.append('discount', discountValue);
                  createFormData.append('table_number', order.table_number || '');
                  createFormData.append('client', order.client || '');
                  createFormData.append('order_type', order.order_type || 'servir');
                  createFormData.append('payment_method', order.payment_method || 'cash');
                  
                  if (order.customer_info) {
                    createFormData.append('customer_info', JSON.stringify(order.customer_info));
                  }
                  if (order.is_addition !== undefined) {
                    createFormData.append('is_addition', order.is_addition);
                  }
                  createFormData.append('offline_order', '1');
                  
                  const createResponse = await fetch(ajaxUrl, {
                    method: 'POST',
                    body: createFormData,
                  });
                  
                  if (!createResponse.ok) {
                    const createErrorText = await createResponse.text();
                    console.error(`[PWA] ❌ Order creation failed:`, createResponse.status, createErrorText.substring(0, 300));
                    throw new Error(`Failed to create orders: HTTP ${createResponse.status}: ${createErrorText.substring(0, 200)}`);
                  }
                  
                  const createResult = await createResponse.json();
                  
                  if (!createResult.success) {
                    const createErrorMsg = createResult.message || createResult.data?.message || 'Failed to create orders';
                    console.error(`[PWA] ❌ Order creation failed:`, createErrorMsg);
                    throw new Error(createErrorMsg);
                  }
                  
                  // Get created order IDs
                  const createdOrderIds = [];
                  if (createResult.data && createResult.data.order_id) {
                    createdOrderIds.push(String(createResult.data.order_id));
                  } else if (createResult.data && Array.isArray(createResult.data.orders)) {
                    createdOrderIds.push(...createResult.data.orders.map(o => String(o.id || o.order_id)));
                  }
                  
                  if (createdOrderIds.length === 0) {
                    console.error(`[PWA] ❌ No order IDs returned from order creation!`);
                    console.error(`[PWA] Response data:`, createResult.data);
                    throw new Error('No order IDs returned from order creation');
                  }
                  
                  orderIds = createdOrderIds; // Use real order IDs
                  
                  // Retry payment completion with new order IDs
                  formData = new FormData();
                  formData.append('action', 'ruiyi_pos_complete_multiple_orders');
                  formData.append('nonce', nonce);
                  formData.append('order_ids', JSON.stringify(orderIds));
                  formData.append('payment_method', order.payment_method || 'cash');
                  formData.append('table_number', order.table_number || '');
                  formData.append('order_type', order.order_type || 'servir');
                  formData.append('total_amount', order.total_amount || 0);
                  
                  if (order.received_amount !== undefined) {
                    formData.append('received_amount', order.received_amount);
                  }
                  if (order.change_amount !== undefined) {
                    formData.append('change_amount', order.change_amount);
                  }
                  if (order.cash_amount !== undefined) {
                    formData.append('cash_amount', order.cash_amount);
                  }
                  if (order.card_amount !== undefined) {
                    formData.append('card_amount', order.card_amount);
                  }
                  if (order.company_ticket_amount !== undefined) {
                    formData.append('company_ticket_amount', order.company_ticket_amount);
                  }
                  if (order.original_total_amount !== undefined) {
                    formData.append('original_total_amount', order.original_total_amount);
                  }
                  if (order.ticket_change_amount !== undefined) {
                    formData.append('ticket_change_amount', order.ticket_change_amount);
                  }
                  if (order.tip_amount !== undefined) {
                    formData.append('tip_amount', order.tip_amount);
                  }
                  if (order.customer_info) {
                    formData.append('customer_info', JSON.stringify(order.customer_info));
                  }
                  formData.append('offline_order', '1');
                  
                  response = await fetch(ajaxUrl, {
                    method: 'POST',
                    body: formData,
                  });
                  
                  if (!response.ok) {
                    const retryErrorText = await response.text();
                    console.error(`[PWA] ❌ Payment completion retry failed:`, response.status, retryErrorText.substring(0, 300));
                    throw new Error(`HTTP ${response.status}: ${retryErrorText.substring(0, 200)}`);
                  }
                  
                  result = await response.json();
                } else {
                  // No cart data or not an order-not-found error - throw original error
                  throw new Error(`HTTP ${response.status}: ${errorText.substring(0, 200)}`);
                }
              } else {
                result = await response.json();
              }
            } else {
              // This is a new order creation
              if (!order.cart || !Array.isArray(order.cart) || order.cart.length === 0) {
                console.error(`[PWA] Order ${order.id} has invalid cart data and not a payment completion`);
                failedCount++;
                continue;
              }
                            
              // 🔥 For table orders created offline, payment_method should be 'pending' (not 'cash')
              // This allows the order to be created and then paid later
              const paymentMethod = (order.payment_method === 'pending' || !order.payment_method) ? 'pending' : order.payment_method;
              
              const formData = new FormData();
              formData.append('action', 'ruiyi_pos_create_order');
              formData.append('nonce', nonce);
              // 🍽️ 分离自助餐商品
              const offlineCart = order.cart || [];
              const offlineBuffet = Array.isArray(offlineCart) ? offlineCart.filter(i => i.is_buffet) : [];
              const offlineRegular = Array.isArray(offlineCart) ? offlineCart.filter(i => !i.is_buffet) : offlineCart;
              formData.append('cart', JSON.stringify(offlineRegular));
              if (offlineBuffet.length > 0) formData.append('buffet_items', JSON.stringify(offlineBuffet));
              formData.append('discount', order.discount || 0);
              formData.append('table_number', order.table_number || '');
              formData.append('client', order.client || '');
              formData.append('order_type', order.order_type || 'servir');
              formData.append('payment_method', paymentMethod);
              
              if (order.customer_info) {
                formData.append('customer_info', JSON.stringify(order.customer_info));
              }
              if (order.received_amount !== undefined) {
                formData.append('received_amount', order.received_amount);
              }
              if (order.change_amount !== undefined) {
                formData.append('change_amount', order.change_amount);
              }
              if (order.cash_amount !== undefined) {
                formData.append('cash_amount', order.cash_amount);
              }
              if (order.card_amount !== undefined) {
                formData.append('card_amount', order.card_amount);
              }
              if (order.tip_amount !== undefined) {
                formData.append('tip_amount', order.tip_amount);
              }
              if (order.is_addition !== undefined) {
                formData.append('is_addition', order.is_addition);
              }
              
              formData.append('offline_order', '1');
              
              const response = await fetch(ajaxUrl, {
                method: 'POST',
                body: formData,
              });
              
              if (!response.ok) {
                const errorText = await response.text();
                throw new Error(`HTTP ${response.status}: ${errorText.substring(0, 200)}`);
              }
              
              result = await response.json();
              
              // 🔥 If this was an order creation, map OFFLINE_ ID to real order ID
              if (result && result.success && result.data) {
                const realOrderId = result.data.order_id || (result.data.orders && result.data.orders[0]?.id);
                if (realOrderId && order.id && order.id.startsWith('OFFLINE_')) {
                  offlineIdToRealIdMap[order.id] = String(realOrderId);
                }
              }
            }
            
            if (result && result.success) {

              // 🔥 关键修复：如果是支付完成的同步（桌位订单结账），清除桌位状态
              if (order.is_payment_completion && order.table_number) {
                const tableNumber = order.table_number;
                const tableNum = resolveGlobalTableNumber(tableNumber);
                const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';

                // 🔥 全局结账保护
                if (tableNum) {
                    if (!window._recentlyCheckedOutTables) window._recentlyCheckedOutTables = {};
                    window._recentlyCheckedOutTables[tableNum] = Date.now();
                }

                // 清除 mesas_estado 中的桌位状态
                const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                const possibleKeys = [
                  `${tablePrefix} ${tableNum}`,
                  `Mesa ${tableNum}`,
                  `Table ${tableNum}`,
                  `餐桌 ${tableNum}`,
                  tableNumber
                ];

                possibleKeys.forEach(key => {
                  if (mesasEstado[key]) {
                    delete mesasEstado[key];
                  }
                });
                localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));

                // 同时清除桌位购物车
                const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
                possibleKeys.forEach(key => {
                  if (carritosGuardados[key]) {
                    delete carritosGuardados[key];
                  }
                });
                localStorage.setItem('carritos_mesas', JSON.stringify(carritosGuardados));

                // 释放桌位状态到服务器
                if (typeof releaseTableOnOrderComplete === 'function') {
                  releaseTableOnOrderComplete(tableNumber);
                }
              }

              // Delete from IndexedDB with retry
              let deleted = false;
              for (let attempt = 0; attempt < 3 && !deleted; attempt++) {
                try {
                  await deletePendingOrderDirect(order.id);
                  await new Promise(resolve => setTimeout(resolve, 200)); // Wait for deletion

                  const verifyOrders = await getPendingOrdersDirect();
                  const stillExists = verifyOrders.some(o => o.id === order.id);
                  if (!stillExists) {
                    deleted = true;
                  } else {
                    console.warn(`[PWA] Order ${order.id} still exists after deletion, retrying...`);
                  }
                } catch (deleteError) {
                  console.error(`[PWA] Delete attempt ${attempt + 1} failed:`, deleteError);
                }
              }

              syncedCount++;

              // 🔥 统计真正的离线订单（ID以OFFLINE_开头的订单）
              if (order.id && String(order.id).startsWith('OFFLINE_')) {
                offlineOrdersSynced++;
              }
            } else {
              failedCount++;
              const errorMsg = result?.message || result?.data?.message || 'Unknown error';
              console.error(`[PWA] ❌ Failed to sync order ${order.id}:`, errorMsg);
            }
          } catch (error) {
            failedCount++;
            console.error(`[PWA] ❌ Error syncing order ${order.id}:`, error.message);
            console.error(`[PWA] Error details:`, error);
          }
        }

        console.log(`[PWA] ✅ Sync complete: ${syncedCount} synced, ${failedCount} failed, ${offlineOrdersSynced} offline orders`);

        // Show notification with completed orders count (only once)
        // 🔥 关键修改：只有当有真正的离线订单（ID以OFFLINE_开头）被同步时才显示通知
        // 这样可以避免在线结账时也显示"同步完成"的提示
        // 🔥 已禁用同步通知 - 不再显示"同步完成"提示

        // Refresh history immediately after sync — 🔥 只刷新离线面板，不重载历史订单
        if (syncedCount > 0 || failedCount > 0) {
          if (typeof loadOfflinePendingOrdersIntoHistory === 'function') {
            setTimeout(() => {
              loadOfflinePendingOrdersIntoHistory();
            }, 500);
          }
          // 🔥 关键修复：刷新桌位显示，确保已清除的桌位状态正确显示
          if (typeof renderizarMesas === 'function') {
            setTimeout(() => {
              renderizarMesas('after-sync-cleanup');
            }, 1200);
          }
        }
      } catch (error) {
        console.error('[PWA] Direct sync error:', error);
        // No error modal - just log to console
      } finally {
        // Always release the lock
        syncInProgress = false;
      }
    }
    
    // 🔥 getPendingOrdersDirect 和 deletePendingOrderDirect 已移至 pos-offline.js 模块

    // Make functions globally available
    window.syncPendingOrdersDirect = syncPendingOrdersDirect;
    window.triggerImmediateSync = triggerImmediateSync;

    let selectedPaymentMethod = ''; // Método de pago seleccionado
