    let tipoPedido = sessionStorage.getItem('tipoPedidoSeleccionado') || 'llevar'; // Tipo de pedido - 默认外卖模式
    var ajaxUrl = '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
    window.ajaxUrl = ajaxUrl; // 确保在全局范围可以访问
    let currentNonce = '<?php echo esc_js($ajax_nonce); ?>'; // 🔥 使用 let 以便可以更新
    var ajaxNonce = currentNonce; // 保持向后兼容

    // 🔐 Nonce 管理器 - 解决长时间运行导致nonce过期的问题
    const NonceManager = {
      nonce: currentNonce,
      lastRefresh: Date.now(),
      refreshInterval: 6 * 60 * 60 * 1000, // 6小时刷新一次（WordPress nonce有效期约12小时）
      isRefreshing: false,
      refreshPromise: null,

      // 获取当前有效的nonce
      get() {
        return this.nonce;
      },

      // 更新nonce
      set(newNonce) {
        this.nonce = newNonce;
        currentNonce = newNonce;
        this.lastRefresh = Date.now();

        // 同步更新所有全局引用
        if (window.RUIYI_POS) {
          window.RUIYI_POS.nonce = newNonce;
        }
        if (window.ruiyi_ajax) {
          window.ruiyi_ajax.nonce = newNonce;
        }

      },

      // 检查是否需要刷新
      needsRefresh() {
        return (Date.now() - this.lastRefresh) > this.refreshInterval;
      },

      // 刷新nonce
      async refresh(force = false) {
        // 如果不需要刷新且不是强制刷新，直接返回
        if (!force && !this.needsRefresh()) {
          return this.nonce;
        }

        // 防止并发刷新
        if (this.isRefreshing) {
          return this.refreshPromise;
        }

        this.isRefreshing = true;
        this.refreshPromise = new Promise(async (resolve, reject) => {
          try {
            const response = await fetch(ajaxUrl, {
              method: 'POST',
              headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
              body: new URLSearchParams({
                action: 'ruiyi_pos_refresh_nonce'
              })
            });

            const data = await response.json();

            if (data.success && data.data && data.data.nonce) {
              this.set(data.data.nonce);
              resolve(this.nonce);
            } else {
              console.error('[NonceManager] ❌ Nonce刷新失败:', data);
              reject(new Error('Nonce refresh failed'));
            }
          } catch (error) {
            console.error('[NonceManager] ❌ Nonce刷新错误:', error);
            reject(error);
          } finally {
            this.isRefreshing = false;
            this.refreshPromise = null;
          }
        });

        return this.refreshPromise;
      },

      // 启动定时刷新
      startAutoRefresh() {
        // 每小时检查一次是否需要刷新
        setInterval(() => {
          if (this.needsRefresh() && navigator.onLine) {
            this.refresh().catch(err => {
              console.warn('[NonceManager] 自动刷新失败，将在下次请求时重试');
            });
          }
        }, 60 * 60 * 1000); // 每小时检查

        // 网络恢复时刷新
        window.addEventListener('online', () => {
          if (this.needsRefresh()) {
            setTimeout(() => {
              this.refresh().catch(e => console.warn('[NetworkRecovery] refresh failed:', e.message));
            }, 2000); // 等待2秒让网络稳定
          }
        });

      }
    };

    // 启动自动刷新
    NonceManager.startAutoRefresh();

    // 全局可访问
    window.NonceManager = NonceManager;

    // 🔐 增强的AJAX请求函数 - 自动处理nonce错误并重试
    async function ajaxWithNonceRetry(options) {
      const { url = ajaxUrl, data = {}, method = 'POST', maxRetries = 1 } = options;

      // 确保使用最新的nonce
      if (NonceManager.needsRefresh() && navigator.onLine) {
        try {
          await NonceManager.refresh();
        } catch (e) {
          console.warn('[ajaxWithNonceRetry] Nonce刷新失败，使用现有nonce');
        }
      }

      // 添加nonce到数据
      const requestData = { ...data, nonce: NonceManager.get() };

      for (let attempt = 0; attempt <= maxRetries; attempt++) {
        try {
          const response = await fetch(url, {
            method: method,
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams(requestData)
          });

          const result = await response.json();

          // 检查是否是nonce错误
          if (!result.success && result.data?.message &&
              (result.data.message.includes('nonce') ||
               result.data.message.includes('seguridad') ||
               result.data.message.includes('security'))) {

            if (attempt < maxRetries && navigator.onLine) {
              console.warn('[ajaxWithNonceRetry] Nonce错误，尝试刷新并重试...');
              await NonceManager.refresh(true);
              requestData.nonce = NonceManager.get();
              continue; // 重试
            }
          }

          return result;
        } catch (error) {
          if (attempt === maxRetries) throw error;
        }
      }
    }

