    // 辅助函数：根据当前语言获取分类名称
    function getMultilingualCategoryName(categoryId, lang = null) {
      if (!window.RUIYI_POS || !window.RUIYI_POS.categories || !Array.isArray(window.RUIYI_POS.categories)) {
        console.warn('多语言分类数据不可用');
        return '';
      }

      const category = window.RUIYI_POS.categories.find(cat => cat.id == categoryId);
      if (!category) return '';

      // 🔥 如果设置为使用默认语言，直接返回原名称
      if (window.RUIYI_POS.categoryUseDefaultLang) {
        return category.name;
      }

      if (!lang) {
        const cookieLang = getCookie('ruiyi_language');
        const htmlLang = document.documentElement.lang;
        const bodyLang = document.body.lang;
        lang = cookieLang || htmlLang || bodyLang || PHP_LANG;
      }

      // 根据语言返回对应的名称
      if (lang === 'en' && category.name_en) {
        return category.name_en;
      } else if (lang === 'es' && category.name_es) {
        return category.name_es;
      } else if (lang === 'zh' && category.name_zh) {
        return category.name_zh;
      }
      
      // 如果没有翻译，返回原始名称
      return category.name;
    }
    
    // 函数：更新分类按钮显示文本
    function updateCategoryButtonsText() {
      const categoryButtons = document.querySelectorAll('.category-btn');
      categoryButtons.forEach(button => {
        const categoryId = button.getAttribute('data-category');
        if (categoryId && categoryId !== 'all') {
          const span = button.querySelector('.category-name') || button.querySelector('span');
          if (span) {
            const multilingualName = getMultilingualCategoryName(categoryId);
            if (multilingualName) {
              span.textContent = multilingualName;
            }
          }
        }
      });
    }
    
    // 统一的按钮状态管理函数
    function updateAllButtonStates() {
      const viewMode = sessionStorage.getItem('tableViewMode');
      const isViewMode = viewMode ? JSON.parse(viewMode) : null;
      const tipoPedido = sessionStorage.getItem('tipoPedidoSeleccionado') || 'llevar'; // 默认外卖模式


      // 获取所有按钮元素
      const sendOrderBtn = document.getElementById('send-order-btn');
      const checkoutTableBtn = document.getElementById('checkout-table-btn');
      const saveTableOrderBtn = document.getElementById('save-table-order-btn');
      const openDrawerBtn = document.getElementById('open-drawer-btn');
      const toolboxToggleBtn = document.getElementById('toolbox-toggle-btn');
      const splitCheckoutBtn = document.getElementById('split-checkout-btn');
      const clearTableBtn = document.getElementById('clear-table-btn');
      const exitViewModeBtn = document.getElementById('exit-view-mode-btn');
      const switchTableBtn = document.getElementById('switch-table-btn');
      const takeAwayButton = document.querySelector('.order-type[data-type="llevar"]');
      const serveButton = document.querySelector('.order-type[data-type="servir"]');
      const reprintLastReceiptBtn = document.getElementById('reprint-last-receipt-btn');

      if (isViewMode && isViewMode.mode === 'view') {
        // ========== 查看模式 ==========

        // 🔥 新增：强制设置为堂食模式并激活堂食标签
        sessionStorage.setItem('tipoPedidoSeleccionado', 'servir');

        // 订单类型按钮：显示堂食和外卖（但外卖在查看模式下禁用）
        if (serveButton) {
          serveButton.style.display = 'flex';
          serveButton.style.visibility = 'visible';
          serveButton.classList.remove('hidden');

          // 🔥 激活堂食按钮
          serveButton.classList.add('bg-[#f7310f]', 'text-white');
          serveButton.classList.remove('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
        }
        if (takeAwayButton) {
          takeAwayButton.style.display = 'flex';
          takeAwayButton.style.visibility = 'visible';
          takeAwayButton.classList.remove('hidden');

          // 🔥 取消外卖按钮激活状态
          takeAwayButton.classList.remove('bg-[#f7310f]', 'text-white');
          takeAwayButton.classList.add('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');

          // 在查看模式下禁用外卖按钮
          takeAwayButton.disabled = true;
          takeAwayButton.style.opacity = '0.5';
          takeAwayButton.style.cursor = 'not-allowed';
        }

        // 第一个按钮：隐藏保存桌位订单按钮（查看模式下也隐藏）
        if (sendOrderBtn) {
          sendOrderBtn.classList.add('hidden');
          sendOrderBtn.style.display = 'none';
        }

        // 🔥 查看模式：保存按钮由 renderCart 控制，这里不做操作
        // 保存按钮在查看模式下也应该显示，只在外卖模式隐藏

        // 查看模式专用按钮：检查是否有锁定商品
        const hasLockedItems = cart.some(item => item.locked);
        if (hasLockedItems) {
          // 🔥 显示结账按钮
          if (checkoutTableBtn) {
            checkoutTableBtn.classList.remove('hidden', 'mt-2');
            checkoutTableBtn.dataset.tableNumber = isViewMode.table;
          }

          // 🔥 显示保存订单按钮（查看模式下也需要显示）
          if (saveTableOrderBtn) {
            saveTableOrderBtn.classList.remove('hidden');
            saveTableOrderBtn.style.display = 'flex';
          }

          // 显示开钱箱按钮
          if (openDrawerBtn) {
            openDrawerBtn.classList.remove('hidden');
          }

          // 显示工具箱按钮
          if (toolboxToggleBtn) {
            toolboxToggleBtn.classList.remove('hidden', 'mt-2');
          }

          // 🔥 新增：显示预览账单按钮（查看模式专用）
          const printPreviewBtn = document.getElementById('print-preview-bill-btn');
          if (printPreviewBtn) {
            printPreviewBtn.classList.remove('hidden');
            printPreviewBtn.dataset.tableNumber = isViewMode.table;
          }

          // 🔥 查看模式：保持第一行的 grid 布局（结账和保存按钮并排）
          const firstRow = document.getElementById('first-row-buttons');
          const secondRow = document.getElementById('second-row-buttons');
          const thirdRow = document.getElementById('third-row-buttons');

          if (firstRow) {
            firstRow.className = 'grid grid-cols-2 gap-2';
            // 移除结账按钮的顶部间距和全宽类（确保按钮并排显示）
            if (checkoutTableBtn) {
              checkoutTableBtn.classList.remove('mt-2', 'w-full');
            }
            if (saveTableOrderBtn) {
              saveTableOrderBtn.classList.remove('w-full');
            }
          }
          if (secondRow) {
            // 第二行保持全宽布局（只有开钱箱按钮）
            secondRow.className = 'w-full';
          }
          if (thirdRow) {
            // 第三行保持flex全宽布局
            thirdRow.className = 'w-full';
          }

          // 工具箱内的按钮设置dataset（由工具箱折叠管理显示）
          if (splitCheckoutBtn) {
            splitCheckoutBtn.dataset.tableNumber = isViewMode.table;
          }
          if (clearTableBtn) {
            clearTableBtn.dataset.tableNumber = isViewMode.table;
          }
          if (switchTableBtn) {
            switchTableBtn.dataset.tableNumber = isViewMode.table;
          }

          // 🔥 查看模式：隐藏打印最后小票按钮（打印桌位订单按钮已移除）
          if (reprintLastReceiptBtn) {
            reprintLastReceiptBtn.classList.add('hidden');
          }
        } else {
          // 🔥 查看模式下没有锁定商品：始终显示结账和保存按钮（让用户可以添加新产品后结账）
          const firstRow = document.getElementById('first-row-buttons');
          const secondRow = document.getElementById('second-row-buttons');

          // 始终显示结账和保存按钮（并排）
          if (firstRow) {
            firstRow.className = 'grid grid-cols-2 gap-2';
          }
          if (checkoutTableBtn) {
            checkoutTableBtn.classList.remove('hidden', 'w-full');
            checkoutTableBtn.style.display = 'flex';
            checkoutTableBtn.dataset.tableNumber = isViewMode.table;
          }
          if (saveTableOrderBtn) {
            saveTableOrderBtn.classList.remove('hidden', 'w-full');
            saveTableOrderBtn.style.display = 'flex';
          }

          // 🔥 工具箱按钮的显示由 updateProformaButtonVisibility() 控制（桌位模式下始终显示）

          if (secondRow) {
            secondRow.className = ''; // 恢复全宽
          }

          // 🔥 查看模式但无锁定商品：隐藏打印最后小票按钮（打印桌位订单按钮已移除）
          if (reprintLastReceiptBtn) {
            reprintLastReceiptBtn.classList.add('hidden');
          }
        }

      } else {
        // ========== 普通模式 ==========

        // 订单类型按钮：显示堂食和外卖
        if (serveButton) {
          serveButton.style.display = 'flex';
          serveButton.style.visibility = 'visible';
          serveButton.classList.remove('hidden');
        }
        if (takeAwayButton) {
          takeAwayButton.style.display = 'flex';
          takeAwayButton.style.visibility = 'visible';
          takeAwayButton.classList.remove('hidden');
          // 确保在普通模式下外卖按钮是启用状态
          takeAwayButton.disabled = false;
          takeAwayButton.style.opacity = '1';
          takeAwayButton.style.cursor = 'pointer';
        }

        // 普通模式：隐藏查看模式专用按钮
        // 🔥 结账按钮的显示由renderCart函数控制
        // 🔥 工具箱按钮的显示由 updateProformaButtonVisibility() 控制（桌位模式下始终显示）

        // 🔥 隐藏预览账单按钮（只在查看模式显示）
        const printPreviewBtn = document.getElementById('print-preview-bill-btn');
        if (printPreviewBtn) printPreviewBtn.classList.add('hidden');

        // 🔥 打印小票按钮显示逻辑：只在外卖模式下显示
        const tableNumber = document.getElementById('table-number')?.value.trim();
        const hasTableNumber = tableNumber !== '';

        if (reprintLastReceiptBtn) {
          if (tipoPedido === 'llevar' || !hasTableNumber) {
            // 外卖模式或无桌号：显示打印小票按钮
            reprintLastReceiptBtn.classList.remove('hidden');
          } else {
            // 堂食模式且有桌号：隐藏打印小票按钮
            reprintLastReceiptBtn.classList.add('hidden');
          }
        }

        // 🔥 普通模式：根据订单类型和桌位号调整按钮布局
        const firstRow = document.getElementById('first-row-buttons');
        const secondRow = document.getElementById('second-row-buttons');

        // 🔥 核心逻辑：保存订单按钮只在"堂食模式 + 有桌位号"时显示
        const shouldShowSaveButton = (tipoPedido === 'servir' && hasTableNumber);

        if (shouldShowSaveButton) {
          // 堂食模式 + 有桌位号：同时显示结账按钮和保存订单按钮（并排显示）
          if (firstRow) {
            firstRow.className = 'grid grid-cols-2 gap-2'; // 并排布局
          }
          if (checkoutTableBtn) {
            checkoutTableBtn.classList.remove('hidden', 'w-full');
            checkoutTableBtn.style.display = 'flex';
            // 设置桌位号到按钮的data属性
            checkoutTableBtn.dataset.tableNumber = tableNumber;
          }
          if (saveTableOrderBtn) {
            saveTableOrderBtn.classList.remove('hidden', 'w-full');
            saveTableOrderBtn.style.display = 'flex';
          }
        } else {
          // 其他所有情况：显示结账按钮（全宽），隐藏保存订单按钮
          // 包括：外卖模式、堂食模式但没有桌位号
          if (firstRow) {
            firstRow.className = 'w-full'; // 全宽布局
          }
          if (checkoutTableBtn) {
            checkoutTableBtn.classList.remove('hidden');
            checkoutTableBtn.classList.add('w-full'); // 添加全宽类
            checkoutTableBtn.style.display = 'flex';
          }
          if (saveTableOrderBtn) {
            saveTableOrderBtn.classList.add('hidden');
            saveTableOrderBtn.classList.remove('w-full'); // 移除全宽类
            saveTableOrderBtn.style.display = 'none';
          }
        }

        if (secondRow) {
          secondRow.className = ''; // 第二行全宽
        }
      }

    }
    
    // 退出查看模式函数
    function exitViewMode() {
      // 🔥 【新增】退出桌位时，如果该桌位没有已保存的订单，清空其状态
      const viewModeData = sessionStorage.getItem('tableViewMode');
      if (viewModeData) {
        try {
          const viewMode = JSON.parse(viewModeData);
          const tableNumber = viewMode.table;

          if (tableNumber) {
            const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
            const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
            const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';

            // 提取纯数字桌号
            const cleanNumber = tableNumber.toString().replace(/^(餐桌|Mesa|Table)\s*/, '');
            const mesaKey = `Mesa ${cleanNumber}`;

            const tableStatus = mesasEstado[mesaKey];

            // 只有在桌位没有已保存订单时才清空状态
            if (!tableStatus || !tableStatus.orderId) {
              // 清空桌位状态
              if (mesasEstado[mesaKey]) {
                delete mesasEstado[mesaKey];
                localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
              }

              // 清空购物车数据
              if (carritosGuardados[mesaKey]) {
                delete carritosGuardados[mesaKey];
                localStorage.setItem('carritos_mesas', JSON.stringify(carritosGuardados));
              }

              // 同步更新服务器状态为空闲
              if (typeof updateTableStatusToServer === 'function') {
                updateTableStatusToServer(cleanNumber, 'available', null, 0);
              }
            }
          }
        } catch (e) {
          console.error('[exitViewMode] 解析viewMode数据失败:', e);
        }
      }

      // 清理查看模式状态
      sessionStorage.removeItem('isViewMode');
      sessionStorage.removeItem('tableViewMode');
      sessionStorage.removeItem('tableOrderData');
      sessionStorage.removeItem('tableViewOrderData');
      sessionStorage.removeItem('fromTableModule');

      // 清空购物车 - 使用 syncCart 确保完全清空
      if (typeof syncCart === 'function') {
        syncCart([]);
      } else {
        cart = [];
        if (typeof window.cart !== 'undefined') {
          window.cart = [];
        }
      }

      // 清理购物车标题
      const orderTitle = document.getElementById('cart-order-title');
      if (orderTitle) {
        orderTitle.innerHTML = '';
      }

      // 清空桌号输入框
      const tableNumberInput = document.getElementById('table-number');
      if (tableNumberInput) {
        tableNumberInput.value = '';
        // 🔥 隐藏购物车上方的桌位号显示
        updateCurrentTableDisplay('');
      }

      // 🔥 关闭工具箱展开区域（如果Alpine.js可用）
      const cartActionsContainer = document.querySelector('.cart-actions-fixed');
      if (cartActionsContainer && window.Alpine) {
        // 使用Alpine.js的魔法属性重置toolboxOpen状态
        const alpineData = Alpine.$data(cartActionsContainer);
        if (alpineData) {
          alpineData.toolboxOpen = false;
        }
      }

      // 激活外卖模式
      const llevarButton = document.querySelector('.order-type[data-type="llevar"]');
      if (llevarButton) {
        llevarButton.click(); // 触发点击事件以激活外卖模式
      } else {
        // 备用方案：直接设置外卖模式
        sessionStorage.setItem('tipoPedidoSeleccionado', 'llevar');
        if (typeof updateOrderButtonForType === 'function') {
          updateOrderButtonForType('llevar');
        }
      }

      // 隐藏所有查看模式相关按钮和工具箱
      const viewModeButtons = ['checkout-table-btn', 'toolbox-toggle-btn'];
      viewModeButtons.forEach(btnId => {
        const btn = document.getElementById(btnId);
        if (btn) {
          btn.classList.add('hidden');
        }
      });

      // 🔥 恢复按钮容器为全宽布局
      const firstRow = document.getElementById('first-row-buttons');
      const secondRow = document.getElementById('second-row-buttons');
      if (firstRow) {
        firstRow.className = ''; // 移除网格布局，恢复全宽
      }
      if (secondRow) {
        secondRow.className = ''; // 移除网格布局，恢复全宽
      }

      // 重新渲染购物车
      if (typeof renderCart === 'function') {
        renderCart();
      }

      // 使用统一的按钮状态管理函数
      setTimeout(() => {
        if (typeof updateAllButtonStates === 'function') {
          updateAllButtonStates();
        }
        // 再次确保按钮正确显示
        if (typeof forceCorrectButtonDisplay === 'function') {
          forceCorrectButtonDisplay();
        }
      }, 100);

      // 退出桌位时刷新桌位列表
      if (typeof renderizarMesas === 'function') {
        renderizarMesas('exit-view-mode');
      }
    }

    // 显示换台选择模态窗
    function showTableSwitchModal(fromTable) {
      // 获取所有餐桌状态
      const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
      const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');

      // 🔥 收集所有桌位（包括空闲和占用的）
      const allTables = [];
      const allMappings = Object.values(tableCategoryMappings);

      // 🔥 获取源桌位的正确显示名称
      let fromTableDisplayName = fromTable;
      const fromTableNum = resolveGlobalTableNumber(fromTable);
      if (allMappings.length > 0 && fromTableNum) {
        const fromMapping = allMappings.find(m =>
          parseInt(m.global_table_number) === parseInt(fromTableNum)
        );
        if (fromMapping && (fromMapping.category_display_name || fromMapping.display_name)) {
          fromTableDisplayName = fromMapping.category_display_name || fromMapping.display_name;
        }
      }

      // 🔥 辅助函数：检查桌位状态
      function getTableStatus(mesaId, globalNumber) {
        // 检查多种可能的 key 格式
        const possibleKeys = [
          mesaId,
          `Mesa ${globalNumber}`,
          `餐桌 ${globalNumber}`,
          globalNumber.toString()
        ];

        let isOccupied = false;
        let tableTotal = 0;

        for (const key of possibleKeys) {
          // 检查购物车
          if (carritosGuardados[key] && (Array.isArray(carritosGuardados[key]) ? carritosGuardados[key].length > 0 : Object.keys(carritosGuardados[key]).length > 0)) {
            isOccupied = true;
          }
          // 检查状态
          const estado = mesasEstado[key];
          if (estado && estado.estado && estado.estado !== 'libre') {
            isOccupied = true;
            if (estado.total) {
              tableTotal = parseFloat(estado.total) || 0;
            }
          }
        }

        return { isOccupied, tableTotal };
      }

      if (allMappings.length > 0) {
        // 如果有分类映射，使用分类桌位名称
        allMappings.forEach(mapping => {
          const globalNumber = parseInt(mapping.global_table_number);
          const categoryDisplayName = mapping.category_display_name || mapping.display_name;
          const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
          const mesaId = `${tablePrefix} ${globalNumber}`;

          // 排除源桌位
          if (mesaId === fromTable || globalNumber.toString() === fromTableNum) {
            return;
          }

          const { isOccupied, tableTotal } = getTableStatus(mesaId, globalNumber);

          allTables.push({
            id: globalNumber,
            name: mesaId,
            displayName: categoryDisplayName,
            isOccupied: isOccupied,
            total: tableTotal
          });
        });
      } else {
        // 如果没有分类映射，回退到Mesa编号
        for (let i = 1; i <= numberOfTablesConfig; i++) {
          const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
          const mesaId = `${tablePrefix} ${i}`;

          // 排除源桌位
          if (mesaId === fromTable || i.toString() === fromTableNum) {
            continue;
          }

          const { isOccupied, tableTotal } = getTableStatus(mesaId, i);

          allTables.push({
            id: i,
            name: mesaId,
            displayName: mesaId,
            isOccupied: isOccupied,
            total: tableTotal
          });
        }
      }

      // 检查是否有空闲桌位
      const availableTables = allTables.filter(t => !t.isOccupied);
      if (availableTables.length === 0) {
        Swal.fire({
          icon: 'warning',
          title: '<?php echo ruiyi_translate("Sin mesas disponibles", "No tables available", "没有可用餐桌"); ?>',
          text: '<?php echo ruiyi_translate("No hay mesas libres para el cambio", "No free tables for switching", "没有空闲餐桌可以换台"); ?>'
        });
        return;
      }

      // 🔥 生成桌位选择网格HTML，显示所有桌位状态
      const tablesGrid = allTables.map(table => {
        if (table.isOccupied) {
          // 🔥 占用状态 - 橙色背景，可点击合并（拼桌）
          return `
            <button class="table-merge-option p-3 bg-orange-50 hover:bg-orange-100 border-2 border-orange-300 hover:border-orange-500 rounded-lg transition-all cursor-pointer"
                    data-table="${table.name}" data-table-id="${table.id}">
              <div class="text-center">
                <i class="fas fa-object-group text-orange-500 text-lg mb-1"></i>
                <div class="font-bold text-sm text-orange-700">${table.displayName}</div>
                <div class="text-xs text-orange-600"><?php echo ruiyi_translate("Fusionar", "Merge", "合并"); ?></div>
                ${table.total > 0 ? `<div class="text-xs text-orange-600 font-bold">€${table.total.toFixed(2)}</div>` : ''}
              </div>
            </button>
          `;
        } else {
          // 空闲状态 - 绿色背景，可点击
          return `
            <button class="table-switch-option p-3 bg-green-50 hover:bg-green-100 border-2 border-green-200 hover:border-green-400 rounded-lg transition-all"
                    data-table="${table.name}" data-table-id="${table.id}">
              <div class="text-center">
                <i class="fas fa-check-circle text-green-500 text-lg mb-1"></i>
                <div class="font-bold text-sm">${table.displayName}</div>
                <div class="text-xs text-green-600"><?php echo ruiyi_translate("Disponible", "Available", "空闲"); ?></div>
              </div>
            </button>
          `;
        }
      }).join('');
      
      Swal.fire({
        title: `<?php echo ruiyi_translate("Cambiar", "Switch", "换台"); ?> ${fromTableDisplayName}`,
        html: `
          <div class="mb-4">
            <p class="text-gray-600"><?php echo ruiyi_translate("Selecciona la mesa de destino:", "Select destination table:", "选择目标餐桌:"); ?></p>
          </div>
          <div class="grid grid-cols-4 gap-3 max-h-96 overflow-y-auto">
            ${tablesGrid}
          </div>
        `,
        width: 800,
        showConfirmButton: false,
        showCancelButton: true,
        cancelButtonText: '<?php echo ruiyi_translate("Cancelar", "Cancel", "取消"); ?>',
        didOpen: () => {
          // 添加桌位选择事件
          document.querySelectorAll('.table-switch-option').forEach(btn => {
            btn.addEventListener('click', function() {
              const toTable = this.dataset.table;
              const toTableId = this.dataset.tableId;

              // 🔥 直接执行换台，不显示二次确认弹窗
              executeTableSwitch(fromTable, toTable);
            });
          });

          // 🔥 添加合并拼桌点击事件
          document.querySelectorAll('.table-merge-option').forEach(btn => {
            btn.addEventListener('click', function() {
              const toTable = this.dataset.table;
              confirmTableMerge(fromTable, toTable);
            });
          });
        }
      });
    }

    // 🔥 确认合并拼桌
    function confirmTableMerge(fromTable, toTable) {
      // 获取显示名称用于确认提示
      const allMappings = Object.values(tableCategoryMappings || {});
      const fromNum = resolveGlobalTableNumber(fromTable);
      const toNum = resolveGlobalTableNumber(toTable);
      let fromDisplay = fromTable;
      let toDisplay = toTable;
      if (allMappings.length > 0) {
        if (fromNum) {
          const m = allMappings.find(x => parseInt(x.global_table_number) === parseInt(fromNum));
          if (m && (m.category_display_name || m.display_name)) fromDisplay = m.category_display_name || m.display_name;
        }
        if (toNum) {
          const m = allMappings.find(x => parseInt(x.global_table_number) === parseInt(toNum));
          if (m && (m.category_display_name || m.display_name)) toDisplay = m.category_display_name || m.display_name;
        }
      }

      Swal.fire({
        icon: 'question',
        title: '<?php echo ruiyi_translate("Fusionar mesas", "Merge tables", "合并拼桌"); ?>',
        html: `<?php echo ruiyi_translate("¿Fusionar los pedidos de", "Merge orders from", "将"); ?> <strong class="text-orange-600">${fromDisplay}</strong> <?php echo ruiyi_translate("con", "with", "的订单合并到"); ?> <strong class="text-orange-600">${toDisplay}</strong>?<br><span class="text-sm text-gray-500 mt-2 block"><?php echo ruiyi_translate("Los productos de ambas mesas se combinarán en la mesa destino.", "Products from both tables will be combined into the destination table.", "两个桌位的商品将合并到目标桌位。"); ?></span>`,
        showCancelButton: true,
        confirmButtonText: '<i class="fas fa-object-group mr-1"></i> <?php echo ruiyi_translate("Fusionar", "Merge", "合并"); ?>',
        cancelButtonText: '<?php echo ruiyi_translate("Cancelar", "Cancel", "取消"); ?>',
        confirmButtonColor: '#f59e0b',
        cancelButtonColor: '#6b7280'
      }).then(result => {
        if (result.isConfirmed) {
          executeTableSwitch(fromTable, toTable, true);
        }
      });
    }

    // 执行换台操作
    // 🔥 mergeMode=true 时为合并拼桌模式（目标桌位已占用时合并而非报错）
    function executeTableSwitch(fromTable, toTable, mergeMode = false) {
      // 🔥 获取正确的显示名称
      const allMappings = Object.values(tableCategoryMappings);
      const fromTableNum = resolveGlobalTableNumber(fromTable);
      const toTableNum = resolveGlobalTableNumber(toTable);

      let fromTableDisplayName = fromTable;
      let toTableDisplayName = toTable;

      if (allMappings.length > 0) {
        if (fromTableNum) {
          const fromMapping = allMappings.find(m => parseInt(m.global_table_number) === parseInt(fromTableNum));
          if (fromMapping && (fromMapping.category_display_name || fromMapping.display_name)) {
            fromTableDisplayName = fromMapping.category_display_name || fromMapping.display_name;
          }
        }
        if (toTableNum) {
          const toMapping = allMappings.find(m => parseInt(m.global_table_number) === parseInt(toTableNum));
          if (toMapping && (toMapping.category_display_name || toMapping.display_name)) {
            toTableDisplayName = toMapping.category_display_name || toMapping.display_name;
          }
        }
      }

      // 显示换台进行中提示
      Swal.fire({
        title: '<?php echo ruiyi_translate("Cambiando mesa...", "Switching table...", "正在换台..."); ?>',
        text: `${fromTableDisplayName} → ${toTableDisplayName}`,
        allowOutsideClick: false,
        didOpen: () => {
          Swal.showLoading();
        }
      });

      try {
        // 1. 验证源桌位和目标桌位状态
        const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
        const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');

        // 🔥🔥🔥 【2026-01-30 修复】验证源桌位是否占用 - 包含显示名称格式
        const possibleFromKeys = [
          fromTable,
          fromTableDisplayName,                    // 🔥 添加显示名称 (如 "COMEDOR1")
          fromTableDisplayName.toUpperCase(),      // 🔥 大写显示名称
          `Mesa ${fromTable}`,
          `餐桌 ${fromTable}`,
          `Mesa ${fromTableNum}`,
          `餐桌 ${fromTableNum}`,
          fromTableNum
        ].filter(k => k && k.trim()); // 过滤空值

        console.log('[换台] 检查源桌位, possibleFromKeys:', possibleFromKeys);

        let sourceTableData = null;
        let actualFromKey = null;

        // 🔥🔥🔥 【2026-03-14 修复】辅助函数：检查estado是否表示"占用"状态
        // 与 showTableSwitchModal 的 getTableStatus 保持一致：任何非 libre 的状态都视为占用
        function isOccupiedState(estado) {
          return estado && estado !== 'libre';
        }

        // 遍历所有可能的 key 格式查找源桌位状态
        for (const key of possibleFromKeys) {
          if (mesasEstado[key]) {
            sourceTableData = mesasEstado[key];
            actualFromKey = key;
            console.log('[换台] 找到源桌位状态, key:', key, 'estado:', sourceTableData.estado);
            break;
          }
        }

        // 如果状态中未找到或状态为libre，检查购物车数据
        if (!sourceTableData || !isOccupiedState(sourceTableData.estado)) {
          for (const key of possibleFromKeys) {
            if (carritosGuardados[key] && (Array.isArray(carritosGuardados[key]) ? carritosGuardados[key].length > 0 : Object.keys(carritosGuardados[key]).length > 0)) {
              actualFromKey = key;
              sourceTableData = { estado: 'ocupada' };
              console.log('[换台] 从购物车数据推断源桌位占用, key:', key);
              break;
            }
          }
        }

        // 🔥 如果当前 cart 有商品，直接视为源桌位占用
        if (!sourceTableData && cart.length > 0) {
          actualFromKey = fromTableDisplayName || fromTable;
          sourceTableData = { estado: 'ocupada' };
          console.log('[换台] 从当前购物车推断源桌位占用, cart.length:', cart.length);
        }

        // 🔥 如果处于查看模式，也视为有效（用户明确在操作这个桌位）
        if (!sourceTableData || !isOccupiedState(sourceTableData.estado)) {
          const viewModeData = sessionStorage.getItem('tableViewMode');
          if (viewModeData) {
            try {
              const viewMode = JSON.parse(viewModeData);
              if (viewMode.table === fromTable || viewMode.table === fromTableNum ||
                  viewMode.table === fromTableDisplayName) {
                actualFromKey = actualFromKey || fromTableDisplayName || fromTable;
                sourceTableData = { estado: 'ocupada' };
                console.log('[换台] 从查看模式推断源桌位占用');
              }
            } catch (e) {
              console.warn('[换台] viewMode parse error:', e.message);
            }
          }
        }

        if (!sourceTableData || !isOccupiedState(sourceTableData.estado)) {
          console.error('[换台] 源桌位验证失败:', { fromTable, fromTableDisplayName, possibleFromKeys, mesasEstado, sourceTableData, cartLength: cart.length });
          throw new Error('<?php echo ruiyi_translate("Mesa origen no está ocupada", "Source table is not occupied", "源桌位未被占用"); ?>');
        }

        // 使用实际找到的 key
        const effectiveFromKey = actualFromKey || fromTable;

        // 🔥 修复：验证目标桌位是否空闲 - 同样使用多种 key 格式
        const toTableNum = resolveGlobalTableNumber(toTable);
        const possibleToKeys = [
          toTable,
          `Mesa ${toTable}`,
          `餐桌 ${toTable}`,
          `Mesa ${toTableNum}`,
          `餐桌 ${toTableNum}`,
          toTableNum
        ].filter(k => k);

        let targetOccupied = false;
        let actualToKey = toTable;

        for (const key of possibleToKeys) {
          const targetMesaState = mesasEstado[key];
          const targetCarrito = carritosGuardados[key];
          if (targetCarrito && (Array.isArray(targetCarrito) ? targetCarrito.length > 0 : Object.keys(targetCarrito).length > 0)) {
            targetOccupied = true;
            break;
          }
          if (targetMesaState && targetMesaState.estado !== 'libre') {
            targetOccupied = true;
            break;
          }
          if (targetMesaState || targetCarrito) {
            actualToKey = key;
          }
        }

        // 🔥 合并模式下跳过目标空闲检查
        if (!mergeMode && targetOccupied) {
          throw new Error('<?php echo ruiyi_translate("Mesa destino no está libre", "Destination table is not free", "目标桌位不是空闲状态"); ?>');
        }

        // 🔥 快照（用于合并模式下的回滚）
        const backupSourceState = mesasEstado[effectiveFromKey] ? JSON.parse(JSON.stringify(mesasEstado[effectiveFromKey])) : null;
        const backupSourceCart = carritosGuardados[effectiveFromKey] ? JSON.parse(JSON.stringify(carritosGuardados[effectiveFromKey])) : null;
        const backupTargetState = mesasEstado[toTable] ? JSON.parse(JSON.stringify(mesasEstado[toTable])) : null;
        const backupTargetCart = carritosGuardados[toTable] ? JSON.parse(JSON.stringify(carritosGuardados[toTable])) : null;

        // 2. 数据迁移
        if (mergeMode) {
          // 🔥 合并模式：将源桌位购物车合并到目标桌位
          const sourceCart = carritosGuardados[effectiveFromKey];
          const targetCart = carritosGuardados[toTable];

          // 统一转换为数组并拼接
          const toArray = (c) => {
            if (!c) return [];
            if (Array.isArray(c)) return c;
            return Object.values(c);
          };
          const mergedCart = [...toArray(targetCart), ...toArray(sourceCart)];

          if (mergedCart.length > 0) {
            carritosGuardados[toTable] = mergedCart;
          }
          delete carritosGuardados[effectiveFromKey];

          // 目标桌位状态保持占用；删除源桌位状态
          if (!mesasEstado[toTable]) {
            mesasEstado[toTable] = { estado: 'ocupada' };
          } else {
            mesasEstado[toTable].estado = 'ocupada';
          }
          delete mesasEstado[effectiveFromKey];
        } else {
          // 原换台逻辑 - 🔥 换台后目标桌位统一设为 'ocupada'
          if (mesasEstado[effectiveFromKey]) {
            mesasEstado[toTable] = { ...mesasEstado[effectiveFromKey], estado: 'ocupada' };
            delete mesasEstado[effectiveFromKey];
          } else if (sourceTableData) {
            mesasEstado[toTable] = { ...sourceTableData, estado: 'ocupada' };
          }

          // 迁移购物车数据
          if (carritosGuardados[effectiveFromKey]) {
            carritosGuardados[toTable] = { ...carritosGuardados[effectiveFromKey] };
            delete carritosGuardados[effectiveFromKey];
          }
        }

        // 清理可能的其他 key 格式
        for (const key of possibleFromKeys) {
          if (key !== toTable) {
            delete mesasEstado[key];
            delete carritosGuardados[key];
          }
        }

        // 保存到localStorage
        localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
        localStorage.setItem('carritos_mesas', JSON.stringify(carritosGuardados));
        
        // 3. 调用服务器API更新订单桌号
        const fromTableNumber = resolveGlobalTableNumber(fromTable);
        const toTableNumber = resolveGlobalTableNumber(toTable);

        // 🔥 获取完整桌位名称（如 COMEDOR1, DOMICILIO3）用于精确匹配
        const fromTableFull = fromTableDisplayName.toUpperCase().replace(/\s+/g, '');
        const toTableFull = toTableDisplayName.toUpperCase().replace(/\s+/g, '');

        fetch(ajaxUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            action: 'switch_table_orders',
            from_table: fromTableNumber,
            to_table: toTableNumber,
            from_table_full: fromTableFull, // 🔥 传递完整桌位名
            to_table_full: toTableFull,     // 🔥 传递完整桌位名
            nonce: ajaxNonce
          })
        })
        .then(response => response.json())
        .then(data => {
          if (data.success) {

            // 4. 换台成功处理
            // 🔥🔥🔥 【2026-01-30 修复】传递完整的桌位信息，包括显示名称、全局编号和订单信息
            handleTableSwitchSuccess(fromTable, toTable, {
              fromDisplayName: fromTableDisplayName,
              toDisplayName: toTableDisplayName,
              fromGlobalNum: fromTableNumber,
              toGlobalNum: toTableNumber,
              orderTotal: data.data?.total || 0,
              orderId: data.data?.order_id || null
            });
          } else {
            throw new Error(data.data?.message || '<?php echo ruiyi_translate("Error del servidor", "Server error", "服务器错误"); ?>');
          }
        })
        .catch(error => {
          console.error('换台失败:', error);

          // 🔥 回滚本地数据
          if (mergeMode) {
            // 合并模式：从快照恢复
            if (backupSourceState) mesasEstado[effectiveFromKey] = backupSourceState;
            else delete mesasEstado[effectiveFromKey];
            if (backupSourceCart) carritosGuardados[effectiveFromKey] = backupSourceCart;
            else delete carritosGuardados[effectiveFromKey];
            if (backupTargetState) mesasEstado[toTable] = backupTargetState;
            else delete mesasEstado[toTable];
            if (backupTargetCart) carritosGuardados[toTable] = backupTargetCart;
            else delete carritosGuardados[toTable];
          } else {
            // 换台模式的原回滚逻辑
            if (mesasEstado[toTable]) {
              mesasEstado[fromTable] = { ...mesasEstado[toTable] };
              delete mesasEstado[toTable];
            }
            if (carritosGuardados[toTable]) {
              carritosGuardados[fromTable] = { ...carritosGuardados[toTable] };
              delete carritosGuardados[toTable];
            }
          }
          localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
          localStorage.setItem('carritos_mesas', JSON.stringify(carritosGuardados));

          // 显示错误
          Swal.fire({
            icon: 'error',
            title: mergeMode
              ? '<?php echo ruiyi_translate("Error al fusionar mesa", "Error merging table", "拼桌失败"); ?>'
              : '<?php echo ruiyi_translate("Error al cambiar mesa", "Error switching table", "换台失败"); ?>',
            text: error.message || '<?php echo ruiyi_translate("No se pudo completar la operación", "Could not complete the operation", "无法完成操作"); ?>'
          });
        });
        
      } catch (error) {
        console.error('换台验证失败:', error);
        Swal.fire({
          icon: 'error',
          title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
          text: error.message
        });
      }
    }
    
    // 换台成功后的处理函数
    // 🔥🔥🔥 【2026-01-30 重写】接收完整的桌位信息，包括显示名称
    function handleTableSwitchSuccess(fromTable, toTable, options = {}) {
      const {
        fromDisplayName = fromTable,
        toDisplayName = toTable,
        fromGlobalNum = resolveGlobalTableNumber(fromTable),
        toGlobalNum = resolveGlobalTableNumber(toTable),
        orderTotal = 0
      } = options;

      console.log('[换台] 开始处理换台成功:', {
        fromTable,
        toTable,
        fromDisplayName,
        toDisplayName,
        fromGlobalNum,
        toGlobalNum,
        orderTotal
      });

      // 强制更新本地桌位状态
      const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
      const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');

      // 🔥🔥🔥 构建所有可能的 key 格式，包括显示名称
      const possibleFromKeys = [
        fromTable,
        fromDisplayName,
        fromDisplayName.toUpperCase(),
        `Mesa ${fromTable}`,
        `餐桌 ${fromTable}`,
        `Mesa ${fromGlobalNum}`,
        `餐桌 ${fromGlobalNum}`,
        `MESA ${fromGlobalNum}`,
        fromGlobalNum
      ].filter(k => k && k.trim());

      const possibleToKeys = [
        toTable,
        toDisplayName,
        toDisplayName.toUpperCase(),
        `Mesa ${toTable}`,
        `餐桌 ${toTable}`,
        `Mesa ${toGlobalNum}`,
        `餐桌 ${toGlobalNum}`,
        `MESA ${toGlobalNum}`,
        toGlobalNum
      ].filter(k => k && k.trim());

      // 去重
      const uniqueFromKeys = [...new Set(possibleFromKeys)];
      const uniqueToKeys = [...new Set(possibleToKeys)];

      console.log('[换台] 将清空的原桌位 keys:', uniqueFromKeys);
      console.log('[换台] 将设置的目标桌位 keys:', uniqueToKeys);

      // 🔥🔥🔥 关键：清空所有可能的源桌位 key，确保原桌位变为空闲
      for (const key of uniqueFromKeys) {
        delete mesasEstado[key];
        delete carritosGuardados[key];
      }

      // 🔥 清空目标桌位的所有旧 key（避免重复）
      for (const key of uniqueToKeys) {
        delete mesasEstado[key];
        delete carritosGuardados[key];
      }

      // 🔥🔥🔥 使用显示名称作为新的 key
      const newTargetKey = toDisplayName;

      // 🔥 设置目标桌位的新状态（包含总额）
      mesasEstado[newTargetKey] = {
        estado: 'ocupada',
        orderId: options.orderId || null,
        total: orderTotal,
        timestamp: new Date().toISOString(),
        _skipAutoUpdate: true
      };

      localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
      localStorage.setItem('carritos_mesas', JSON.stringify(carritosGuardados));

      console.log('[换台] 状态更新完成:', {
        clearedFromKeys: uniqueFromKeys,
        newTargetKey: newTargetKey,
        targetState: mesasEstado[newTargetKey],
        allKeys: Object.keys(mesasEstado)
      });

      // 同步状态到服务器
      updateTableStatusToServer(fromGlobalNum, 'free', null, 0);
      updateTableStatusToServer(toGlobalNum, 'occupied', mesasEstado[newTargetKey].orderId, orderTotal);

      // 🔥 清空当前购物车
      cart = [];
      window.cart = [];
      if (typeof renderCart === 'function') {
        renderCart();
      }

      // 清理查看模式状态
      sessionStorage.removeItem('tableViewMode');
      sessionStorage.removeItem('tableOrderData');
      sessionStorage.removeItem('fromTableModule');
      sessionStorage.removeItem('tableViewOrderData');

      // 关闭弹窗
      Swal.close();

      // 🔥🔥🔥 【2026-01-30 修复】显示换台成功提示
      Toastify({
        text: `✅ <?php echo ruiyi_translate('Mesa cambiada', 'Table switched', '换台成功'); ?>: ${fromDisplayName} → ${toDisplayName}`,
        duration: 2000,
        gravity: "top",
        position: "center",
        style: { background: "#10b981" }
      }).showToast();

      // 🔥🔥🔥 返回桌位模块并正确渲染状态
      setTimeout(() => {
        // 返回餐桌模块
        if (typeof cambiarSeccion === 'function') {
          cambiarSeccion('mesas');
        } else {
          const mesasLink = document.querySelector('a[href="#mesas"]');
          if (mesasLink) {
            mesasLink.click();
          }
        }

        // 从服务器获取最新状态
        if (typeof fetchAndUpdateTableStatuses === 'function') {
          fetchAndUpdateTableStatuses();
        }

        // 刷新餐桌显示
        if (typeof renderizarMesas === 'function') {
          renderizarMesas('after-table-switch');
        }

        // 延迟再次刷新，确保状态正确
        setTimeout(() => {
          if (typeof fetchAndUpdateTableStatuses === 'function') {
            fetchAndUpdateTableStatuses();
          }
          if (typeof renderizarMesas === 'function') {
            renderizarMesas('final-table-switch');
          }
        }, 500);
      }, 300);
    }

    // 函数：更新所有价格显示元素（支持积分折扣）
    function updateAllPriceDisplays(originalTotal, discountedTotal, discountAmount) {
        const popup = Swal.getPopup();
        if (!popup) return;
        
        // 1. 更新支付面板中的主要价格显示 - 简化版本
        const paymentPriceElement = popup.querySelector('#payment-total-display');
        if (paymentPriceElement) {
            // 只显示最终价格，折扣后为红色
            const priceHtml = discountAmount > 0 ?
                `<div class="text-4xl font-bold text-red-600">€${discountedTotal.toFixed(2)}</div>` :
                `<div class="text-4xl font-bold text-red-600">€${discountedTotal.toFixed(2)}</div>`;
            
            paymentPriceElement.innerHTML = priceHtml;
        }
        
        // 2. 更新弹窗顶部的总金额显示 - 简化版本
        const titleElements = popup.querySelectorAll('p');
        titleElements.forEach(p => {
            if (p.innerHTML.includes('将支付总额') || p.innerHTML.includes('Total a pagar')) {
                // 只显示最终应付金额
                const totalLabel = '<?php echo ruiyi_translate("Total a pagar", "Total to pay", "将支付总额"); ?>';
                p.innerHTML = `${totalLabel} <strong class="text-xl text-red-600">€${discountedTotal.toFixed(2)}</strong>`;
            }
        });
        
        // 3. 更新现金支付的占位符
        const receivedInput = popup.querySelector('#received-amount-mesa');
        if (receivedInput) {
            // 🔥 移除 min 限制，允许输入任意金额
            receivedInput.placeholder = `€${discountedTotal.toFixed(2)}`;
        }
        
        // 4. 在积分面板中显示简洁的折扣确认
        const pointsPanel = popup.querySelector('#points-panel');
        if (pointsPanel && discountAmount > 0) {
            // 添加简洁的折扣成功提示
            let discountNotice = pointsPanel.querySelector('.discount-applied-notice');
            if (!discountNotice) {
                discountNotice = document.createElement('div');
                discountNotice.className = 'discount-applied-notice bg-green-50 border border-green-200 rounded-lg p-3 mb-4 text-center';
                discountNotice.innerHTML = `
                    <div class="flex items-center justify-center text-green-700">
                        <i class="fas fa-check-circle mr-2"></i>
                        <span class="font-semibold">积分折扣已应用 - 节省 €${discountAmount.toFixed(2)}</span>
                    </div>
                `;
                pointsPanel.insertBefore(discountNotice, pointsPanel.firstChild);
            }
        }
    }
    
    // Helper function to safely get translation strings
    function getTrans(key, defaultValue = '') {
      if (window.RUIYI_TRANS && window.RUIYI_TRANS[key]) {
        return window.RUIYI_TRANS[key];
      }
      // Default values for common keys
      const defaults = {
        table: 'Mesa',
        type: 'Tipo',
        subtotal: 'Subtotal',
        order: 'Orden',
        noTable: 'Sin mesa',
        addedToCart: 'agregado al carrito',
        forTableService: 'Para servir en mesa',
        takeaway: 'Para llevar',
        orderCreatedSuccess: 'Pedido creado con éxito',
        registeredSuccess: 'registrada correctamente',
        preparingPrint: 'Preparando impresión...',
        printError: 'Error de impresión: ',
        productRemoved: 'Producto eliminado'
      };
      return defaultValue || defaults[key] || key;
    }
    
    // 获取当前语言从cookie
    function getCurrentLanguageFromCookie() {
      const cookies = document.cookie.split(';');
      for (let cookie of cookies) {
        const [name, value] = cookie.trim().split('=');
        if (name === 'ruiyi_language') {
          return value;
        }
      }
      return PHP_LANG;
    }

    // ✅ Compatibility: some parts of POS call getCurrentLanguage()
    function getCurrentLanguage() {
      return getCurrentLanguageFromCookie();
    }
    window.getCurrentLanguage = getCurrentLanguage;

    // 通用的获取Cookie函数
    function getCookie(name) {
      const cookies = document.cookie.split(';');
      for (let cookie of cookies) {
        const [cookieName, value] = cookie.trim().split('=');
        if (cookieName === name) {
          return value;
        }
      }
      return null;
    }

    // 添加前端翻译函数
