      unknown: '<?php echo ruiyi_translate("Desconocido", "Unknown", "未知"); ?>'
    };

    // Scale Integration Config
    const scaleConfig = <?php
      if (function_exists('ruiyi_pos_get_scale_integration_config')) {
        echo json_encode(ruiyi_pos_get_scale_integration_config());
      } else {
        echo json_encode(array('enabled' => false));
      }
    ?>;

    // Ensure socket URL uses correct protocol (HTTPS -> WSS, HTTP -> WS)
    // When page is served over HTTPS, WebSocket must use WSS protocol
    if (scaleConfig.socket_url && window.location.protocol === 'https:') {
      // Convert http:// to https:// (Socket.IO will use wss:// for WebSocket)
      scaleConfig.socket_url = scaleConfig.socket_url.replace(/^http:\/\//i, 'https://');
    }

    // Scale State
    let scaleState = {
      connected: false,
      latestWeight: null,
      lastUpdatedAt: 0,
      unit: scaleConfig.weight_unit || 'kg',
      status: 'disconnected',
      lastError: null,
      preview: null,
      socket: null
    };

    // VFD Display State (uses same socket as scale)
    let vfdState = {
      connected: false,
      socket: null
    };

    // Initialize Scale Integration
    function initScaleIntegration() {
      // Check if scale widget exists
      const scaleWidget = document.getElementById('scale-status-card');
      if (!scaleWidget) {
        return;
      }

      if (!scaleConfig.enabled) {
        updateScaleConnectionUI('disabled');
        return;
      }

      if (typeof io === 'undefined') {
        updateScaleConnectionUI('error', { message: 'Socket.IO client not available' });
        return;
      }

      connectScaleSocket();
    }

    // Connect to Scale Hub via Socket.IO
    function connectScaleSocket() {
      if (!scaleConfig.socket_url) {
        updateScaleConnectionUI('error', { message: 'Scale socket URL not configured' });
        return;
      }

      try {
        if (scaleState.socket && typeof scaleState.socket.disconnect === 'function') {
          scaleState.socket.disconnect();
        }

        updateScaleConnectionUI('connecting');

        const query = Object.assign({}, scaleConfig.query || {}, {
          clientType: scaleConfig.client_type || 'pos',
          location: scaleConfig.location || 'default'
        });

        const socketOptions = {
          transports: ['websocket'],
          reconnection: true,
          reconnectionAttempts: Infinity,
          reconnectionDelay: scaleConfig.retry_ms || 2000,
          path: scaleConfig.socket_path || '/socket.io',
          query
        };

        if (scaleConfig.auth_token) {
          socketOptions.auth = Object.assign({}, scaleConfig.auth || {}, {
            token: scaleConfig.auth_token
          });
        }

        scaleState.socket = io(scaleConfig.socket_url, socketOptions);
      } catch (error) {
        updateScaleConnectionUI('error', { message: error.message || 'Scale socket error' });
        return;
      }

      scaleState.socket.on('connect', () => {
        scaleState.connected = true;
        handleScaleStatus({ status: 'connected' });
        clearScaleError();
        
        // VFD uses same socket connection
        vfdState.socket = scaleState.socket;
        vfdState.connected = true;
        
        // Force initial display update after connection
        setTimeout(() => {
          updateScaleDisplay();
        }, 100);
      });

      scaleState.socket.on('disconnect', (reason) => {
        scaleState.connected = false;
        vfdState.connected = false;
        handleScaleStatus({ status: 'disconnected', reason });
      });

      scaleState.socket.on('connect_error', (error) => {
        handleScaleError({ message: error.message || 'Connection error' });
      });

      if (scaleState.socket.io) {
        scaleState.socket.io.on('reconnect_attempt', (attemptNumber) => {
          handleScaleStatus({ status: 'connecting' });
        });
        
        scaleState.socket.io.on('reconnect', (attemptNumber) => {
          // Reconnected
        });
        
        scaleState.socket.io.on('reconnect_failed', () => {
          // Reconnection failed
        });
      }

      scaleState.socket.on('scale:status', (payload) => {
        handleScaleStatus(payload);
      });
      
      scaleState.socket.on('scale:weight', (payload) => {
        handleScaleWeight(payload);
      });
      
      scaleState.socket.on('scale:error', (payload) => {
        handleScaleError(payload);
      });
      
      // Also listen for any other potential event names
      scaleState.socket.on('weight', (payload) => {
        handleScaleWeight(payload);
      });
      
      scaleState.socket.on('data', (payload) => {
        if (payload && (payload.weight !== undefined || payload.value !== undefined)) {
          handleScaleWeight(payload);
        }
      });
    }

    // Handle Scale Status Updates
    function handleScaleStatus(payload = {}) {
      const status = payload.status || (scaleState.connected ? 'connected' : 'disconnected');
      if (payload.unit) {
        scaleState.unit = payload.unit;
      }
      scaleState.status = status;
      updateScaleConnectionUI(status, payload);
    }

    // Handle Real-time Weight Updates from Scale Hub
    function handleScaleWeight(payload = {}) {
      // Try multiple possible weight field names
      let weightCandidate = null;
      if (payload.weight !== undefined) {
        weightCandidate = payload.weight;
      } else if (payload.value !== undefined) {
        weightCandidate = payload.value;
      } else if (payload.w !== undefined) {
        weightCandidate = payload.w;
      } else if (payload.data && payload.data.weight !== undefined) {
        weightCandidate = payload.data.weight;
      }
      
      const parsedWeight = weightCandidate !== undefined && weightCandidate !== null ? parseFloat(weightCandidate) : null;

      if (payload.unit) {
        scaleState.unit = payload.unit;
      }

      if (parsedWeight === null || isNaN(parsedWeight)) {
        return;
      }

      scaleState.latestWeight = parsedWeight;
      scaleState.lastUpdatedAt = payload.timestamp ? Number(payload.timestamp) : Date.now();

      clearScaleError();
      updateScaleDisplay();
    }

    // Handle Scale Errors
    function handleScaleError(payload = {}) {
      const message = payload.message || '<?php echo esc_js(ruiyi_translate('Error de báscula detectado', 'Scale error detected', '检测到秤错误')); ?>';
      scaleState.lastError = { message, timestamp: Date.now() };
      updateScaleConnectionUI('error', payload);
      updateScaleErrorBanner(message);
    }

    // Clear Scale Error
    function clearScaleError() {
      scaleState.lastError = null;
      updateScaleErrorBanner(null);
    }

    // Send cart total to VFD display
    function sendVFDDisplay(total) {
      if (!vfdState.connected || !vfdState.socket) {
        return;
      }

      try {
        // If cart is empty, clear the display
        if (total === 0 || total === null || total === undefined) {
          vfdState.socket.emit('vfd:clear', {
            timestamp: Date.now()
          });
          return;
        }

        // Format the total for display
        const formattedTotal = `€${total.toFixed(2)}`;
        
        // Send display message to VFD hub
        vfdState.socket.emit('vfd:display', {
          text: formattedTotal,
          timestamp: Date.now()
        });
      } catch (error) {
        console.error('Error sending VFD display:', error);
      }
    }

    // Display purchase success message on VFD
    function displayVFDSuccessMessage() {
      if (!vfdState.connected || !vfdState.socket) {
        return;
      }

      try {
        // Display success message in multiple languages
        const successMessage = '<?php echo ruiyi_translate("Compra Exitosa", "Purchase Success", "购买成功"); ?>';
        
        // Send success message to VFD hub
        vfdState.socket.emit('vfd:display', {
          text: successMessage,
          timestamp: Date.now()
        });

        // Clear the message after 3 seconds and show empty display
        setTimeout(() => {
          if (vfdState.connected && vfdState.socket) {
            vfdState.socket.emit('vfd:clear', {
              timestamp: Date.now()
            });
          }
        }, 3000);
      } catch (error) {
        console.error('Error displaying VFD success message:', error);
      }
    }

    // Update Scale Error Banner
    function updateScaleErrorBanner(message) {
      const errorBanner = document.getElementById('scale-error-banner');
      if (!errorBanner) return;

      if (message) {
        errorBanner.textContent = message;
        errorBanner.classList.remove('hidden');
      } else {
        errorBanner.classList.add('hidden');
        errorBanner.textContent = '';
      }
    }

    // Update Scale Connection UI
    function updateScaleConnectionUI(status, payload = {}) {
      const statusBadge = document.getElementById('scale-status-badge');
      const card = document.getElementById('scale-status-card');

      let label;
      let badgeClass;
      switch (status) {
        case 'connected':
          label = '<?php echo esc_js(ruiyi_translate('Conectado', 'Connected', '已连接')); ?>';
          badgeClass = 'bg-green-200 text-green-700';
          break;
        case 'connecting':
          label = '<?php echo esc_js(ruiyi_translate('Conectando', 'Connecting', '连接中')); ?>';
          badgeClass = 'bg-yellow-200 text-yellow-700';
          break;
        case 'disabled':
          label = '<?php echo esc_js(ruiyi_translate('Deshabilitado', 'Disabled', '已禁用')); ?>';
          badgeClass = 'bg-gray-200 text-gray-600';
          break;
        case 'error':
          label = '<?php echo esc_js(ruiyi_translate('Error', 'Error', '错误')); ?>';
          badgeClass = 'bg-red-200 text-red-700';
          break;
        default:
          label = '<?php echo esc_js(ruiyi_translate('Desconectado', 'Disconnected', '未连接')); ?>';
          badgeClass = 'bg-gray-200 text-gray-600';
      }

      if (statusBadge) {
        statusBadge.textContent = label;
        statusBadge.className = `px-2 py-1 text-xs rounded-full ${badgeClass}`;
      }

      if (card) {
        card.classList.toggle('stale', isWeightReadingStale());
      }

      if (status !== 'error') {
        clearScaleError();
      } else if (payload.message) {
        updateScaleErrorBanner(payload.message);
      }
    }

    // Update Scale Display
    function updateScaleDisplay() {
      const weightDisplay = document.getElementById('scale-weight-display');
      const card = document.getElementById('scale-status-card');
      const weight = scaleState.latestWeight;
      const isStale = isWeightReadingStale();
      const unit = scaleState.unit || scaleConfig.weight_unit || 'kg';

      if (card) {
        card.classList.toggle('stale', isStale || weight === null);
      }

      if (weightDisplay) {
        const displayText = weight !== null
          ? formatWeight(weight) + ' ' + unit
          : `--.-- ${unit}`;
        weightDisplay.textContent = displayText;
        weightDisplay.innerHTML = displayText;
      } else {
        // Try to find it again - maybe it was added dynamically
        setTimeout(() => {
          const retryDisplay = document.getElementById('scale-weight-display');
          if (retryDisplay && weight !== null) {
            const displayText = formatWeight(weight) + ' ' + unit;
            retryDisplay.textContent = displayText;
            retryDisplay.innerHTML = displayText;
          }
        }, 100);
      }

      // 🔥 移除 lastUpdatedEl 和 pricePreviewEl 的更新逻辑（元素已删除）
    }

    // Check if Weight Reading is Stale
    function isWeightReadingStale() {
      if (!scaleConfig.enabled) {
        return true;
      }

      if (!scaleState.lastUpdatedAt) {
        return true;
      }

      const threshold = scaleConfig.stale_after_ms || 5000;
      return Date.now() - scaleState.lastUpdatedAt > threshold;
    }

    // Format Weight Display
    function formatWeight(weight) {
      const precision = Number.isInteger(scaleConfig.precision) ? scaleConfig.precision : 3;
      return weight.toFixed(precision);
    }

    // Calculate Weight Price
    function calculateWeightPrice(weightInfo, weight) {
      const unitPrice = weightInfo.unit_price_per_kg || weightInfo.unitPricePerKg || 0;
      return unitPrice * weight;
    }

    // Get Current Weight
    function getCurrentWeight() {
      if (!scaleConfig.enabled) {
        return null;
      }

      const weight = scaleState.latestWeight;
      if (weight === null || isNaN(weight)) {
        return null;
      }

      if (isWeightReadingStale()) {
        return null;
      }

      if (scaleConfig.min_weight_kg && Math.abs(weight) < scaleConfig.min_weight_kg) {
        return null;
      }

      return weight;
    }

    // Initialize scale integration when page loads
    if (scaleConfig.enabled) {
      // Check if DOM is already loaded
      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() {
          initScaleIntegration();
        });
      } else {
        // DOM is already loaded, initialize immediately
        initScaleIntegration();
      }
    }

    // Función para reproducir sonidos
    function playSound(url) {
      try {
        const audio = new Audio(url);
        audio.play();
      } catch (error) {
        console.error('Error al reproducir sonido:', error);
      }
    }
      
    // Calcular subtotal del carrito
    // 🔥 supplements 已合入 customPrice，无需单独计算
    function calculateSubtotal() {
      const rawTotal = cart.reduce((total, item) => {
        if (item.isScaleProduct && item.customPrice !== undefined && item.customPrice !== null) {
          return total + (item.customPrice * item.quantity);
        }
        const itemPrice = parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0));
        return total + (itemPrice * item.quantity);
      }, 0);
      return parseFloat(rawTotal.toFixed(2));
    }

    // ========== 🔥 本地小票生成功能 - 支持离线打印 ==========

    function ruiyiFormatReceiptInvoiceNumber(rawInvoiceNumber = '', orderId = '', orderDate = null) {
      const raw = String(rawInvoiceNumber || '').trim();
      let year = new Date().getFullYear();
      if (orderDate) {
        const parsedDate = new Date(orderDate);
        if (!Number.isNaN(parsedDate.getTime())) {
          year = parsedDate.getFullYear();
        }
      }

      let sequence = '';
      const yearMatch = raw.match(/(20\d{2}).*?(\d{1,12})(?!.*\d)/);
      if (yearMatch) {
        year = yearMatch[1];
        sequence = yearMatch[2];
      } else {
        const numberMatches = raw.match(/\d+/g);
        if (numberMatches && numberMatches.length) {
          sequence = numberMatches[numberMatches.length - 1];
        }
      }

      if (!sequence && orderId !== undefined && orderId !== null && orderId !== '') {
        const orderDigits = String(orderId).match(/\d+/g);
        if (orderDigits && orderDigits.length) {
          sequence = orderDigits[orderDigits.length - 1];
        }
      }

      sequence = String(sequence || '').replace(/\D+/g, '').replace(/^0+/, '');
      if (!sequence) {
        sequence = String(Math.floor(1 + Math.random() * 9999999));
      }

      return `${year}${sequence.padStart(7, '0')}`;
    }

    /**
     * 生成本地小票HTML（用于离线模式下的打印）
     * @param {Object} options 选项
     * @param {Array} options.cartItems 购物车商品列表
     * @param {string} options.tableDisplayName 桌位显示名称
     * @param {Object} options.paymentInfo 支付信息
     * @param {number} options.totalAmount 总金额
     * @param {number} options.originalTotal 原始金额（折扣前）
     * @param {number} options.discountAmount 折扣金额
     * @param {number} options.discountPercent 折扣百分比
     * @param {number} options.chequeAmount 抵扣券金额
     * @param {string} options.orderType 订单类型 'table' | 'takeaway'
     * @returns {string} 小票HTML
     */
    function generateLocalReceiptHtml(options) {
      const config = window.RUIYI_POS_CONFIG || {};
      const storeInfo = config.storeInfo || {};

      const {
        cartItems = [],
        tableDisplayName = '',
        paymentInfo = {},
        totalAmount = 0,
        originalTotal = 0,
        discountAmount = 0,
        discountPercent = 0,
        chequeAmount = 0,
        orderType = 'table',
        orderId = '',
        invoiceNumber = '',
        invoice_label = ''
      } = options;

      // 格式化当前时间
      const now = new Date();
      const formattedDate = now.toLocaleDateString('es-ES', {
        day: '2-digit',
        month: '2-digit',
        year: 'numeric'
      }) + ' ' + now.toLocaleTimeString('es-ES', {
        hour: '2-digit',
        minute: '2-digit'
      });

      // 🔥 生成本地发票编号（格式：年份 + 7位序号，如 20260000381）
      const fallbackLocalOrderId = String(Math.floor(1 + Math.random() * 9999999));
      const localInvoiceNumber = ruiyiFormatReceiptInvoiceNumber(invoiceNumber || invoice_label || '', orderId || fallbackLocalOrderId);

      // 生成商品列表HTML
      let itemsHtml = '';
      let subtotal = 0;

      const _bilingual = window.clodopConfig?.receiptBilingual || false;
      // 🔥 产品编号移除函数
      const _hideNum = window.RUIYI_POS_CONFIG?.hideProductNumberOnReceipt === true;
      const _removeProductNumber = (name) => {
        if (!name || !_hideNum) return name;
        return name.replace(/^\d+[A-Za-z]?\.\s*/, '') || name;
      };
      cartItems.forEach(item => {
        // 🔥 过滤0元免费产品和自助餐产品 - 不在结账小票中显示
        const itemPrice = parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : item.price) || 0;
        if (itemPrice <= 0 && (item.is_free || item.is_buffet)) return;

        // 🔥 customName 已含 supplements 名称，customPrice 已含 supplements 价格
        let itemName = item.customName || item.name || item.nombre || 'Producto';
        if (_bilingual && item.name_zh) {
          const esName = item.name_es || item.name || '';
          if (item.name_zh !== esName) { // 避免重复（如 Varios + Varios）
            const numMatch = esName.match(/^(\d+[A-Za-z]?\.\s*)/);
            if (numMatch) {
              const prefix = numMatch[1].replace(/\s+$/, '');
              const esClean = esName.substring(numMatch[0].length);
              const zhClean = item.name_zh.replace(/^\d+[A-Za-z]?\.\s*/, '');
              itemName = prefix + zhClean + esClean;
            } else {
              itemName = item.name_zh + esName;
            }
          }
        }
        // 🔥 应用产品编号隐藏设置
        itemName = _removeProductNumber(itemName);
        const quantity = parseInt(item.quantity) || 1;
        const price = itemPrice;
        const lineTotal = price * quantity;
        subtotal += lineTotal;

        const _isSupplement = item.is_supplement || false;
        const _parentItemName = item.parent_item_name || '';
        itemsHtml += `
          <tr${_isSupplement ? ' data-supplement="true" data-parent="' + escapeHtml(_parentItemName) + '"' : ''}>
            <td class="item-name">${_isSupplement ? '+ ' : ''}${escapeHtml(itemName)}</td>
            <td class="col-qty">${quantity}</td>
            <td class="col-price">${price.toFixed(2)}</td>
            <td class="col-total">${lineTotal.toFixed(2)}</td>
          </tr>
        `;
      });

      // 计算税额：所有产品都是含税价，税种/税率由设置模块控制
      const grandTotal = totalAmount || subtotal;
      const receiptTaxTotals = window.ruiyiCalculateIncludedReceiptTax(grandTotal);
      const taxAmount = receiptTaxTotals.tax;
      const subtotalWithoutTax = receiptTaxTotals.base;
      const receiptTaxLabel = window.ruiyiGetReceiptTaxDisplayLabel();

      // 🔥 生成小票Logo HTML - 确保URL有效
      let logoHtml = '';
      if (storeInfo.receiptLogo && storeInfo.receiptLogo.length > 5) {
        // 确保是完整URL
        let logoUrl = storeInfo.receiptLogo;
        if (!logoUrl.startsWith('http') && !logoUrl.startsWith('data:')) {
          logoUrl = window.location.origin + (logoUrl.startsWith('/') ? '' : '/') + logoUrl;
        }
        logoHtml = `
          <div class="receipt-logo-container">
            <img src="${escapeHtml(logoUrl)}" class="receipt-logo" alt="Logo"
                 onerror="this.style.display='none'">
          </div>
        `;
      }

      // 生成店铺信息HTML
      let storeInfoHtml = '';
      if (storeInfo.businessName) {
        storeInfoHtml += `<div class="business-name">${escapeHtml(storeInfo.businessName)}</div>`;
      }
      if (storeInfo.cifNif) {
        storeInfoHtml += `<div class="cif-nif">CIF/NIF: ${escapeHtml(storeInfo.cifNif)}</div>`;
      }
      if (storeInfo.phone) {
        storeInfoHtml += `<div class="phone">Tel: ${escapeHtml(storeInfo.phone)}</div>`;
      }
      if (storeInfo.address) {
        // 🔥 地址支持换行：将 \n 转为 <br>
        const addressLines = storeInfo.address.split('\n').map(l => escapeHtml(l.trim())).filter(l => l).join('<br>');
        storeInfoHtml += `<div class="address">${addressLines}</div>`;
      }

      // 生成折扣/抵扣信息HTML
      let discountHtml = '';
      if (discountPercent > 0 && discountAmount > 0) {
        discountHtml += `
          <tr>
            <td colspan="3" style="text-align: right; font-weight: bold;">Descuento (${discountPercent}%):</td>
            <td style="text-align: right; color: #dc2626;">-€${discountAmount.toFixed(2)}</td>
          </tr>
        `;
      }
      if (chequeAmount > 0) {
        discountHtml += `
          <tr>
            <td colspan="3" style="text-align: right; font-weight: bold;">Cheque Restaurante:</td>
            <td style="text-align: right; color: #dc2626;">-€${chequeAmount.toFixed(2)}</td>
          </tr>
        `;
      }

      // 🔥 生成支付信息HTML - 使用与在线小票一致的table格式
      let paymentHtml = '';
      const paymentMethod = paymentInfo.method || 'cash';
      const receivedAmount = parseFloat(paymentInfo.receivedAmount) || 0;
      const changeAmount = parseFloat(paymentInfo.changeAmount) || 0;
      const cashAmount = parseFloat(paymentInfo.cashAmount) || grandTotal;
      const cardAmount = parseFloat(paymentInfo.cardAmount) || 0;

      if (paymentMethod === 'cash') {
        // 现金支付：显示 Efectivo + Recibido + Cambio
        const actualCashAmount = cashAmount > 0 ? cashAmount : grandTotal;
        paymentHtml = `
          <table class="payment-details-table" style="margin-top: 3mm; font-size: 0.95em;">
	            <tr>
	              <td colspan="2" style="text-align:center; font-weight: bold;">Detalles de Pago</td>
	            </tr>
            <tr>
              <td style="text-align:left; padding-left: 5mm;">Efectivo:</td>
              <td style="text-align:right;">${actualCashAmount.toFixed(2)}€</td>
            </tr>
            ${receivedAmount > actualCashAmount + 0.01 ? `
            <tr>
              <td style="text-align:left; padding-left: 5mm; font-size: 0.9em; color: #666;">Recibido:</td>
              <td style="text-align:right; font-size: 0.9em; color: #666;">${receivedAmount.toFixed(2)}€</td>
            </tr>
            <tr>
              <td style="text-align:left; padding-left: 5mm; font-size: 0.9em; color: #666;">Cambio:</td>
              <td style="text-align:right; font-size: 0.9em; color: #666;">${changeAmount.toFixed(2)}€</td>
            </tr>
            ` : ''}
          </table>
        `;
      } else if (paymentMethod === 'card') {
        // 刷卡支付：只显示 Tarjeta
        paymentHtml = `
          <table class="payment-details-table" style="margin-top: 3mm; font-size: 0.95em;">
	            <tr>
	              <td colspan="2" style="text-align:center; font-weight: bold;">Detalles de Pago</td>
	            </tr>
            <tr>
              <td style="text-align:left; padding-left: 5mm;">Tarjeta:</td>
              <td style="text-align:right;">${grandTotal.toFixed(2)}€</td>
            </tr>
          </table>
        `;
      } else if (paymentMethod === 'mixed') {
        // 混合支付：显示 Efectivo + Tarjeta
        paymentHtml = `
          <table class="payment-details-table" style="margin-top: 3mm; font-size: 0.95em;">
	            <tr>
	              <td colspan="2" style="text-align:center; font-weight: bold;">Detalles de Pago</td>
	            </tr>
            <tr>
              <td style="text-align:left; padding-left: 5mm;">Efectivo:</td>
              <td style="text-align:right;">${cashAmount.toFixed(2)}€</td>
            </tr>
            <tr>
              <td style="text-align:left; padding-left: 5mm;">Tarjeta:</td>
              <td style="text-align:right;">${cardAmount.toFixed(2)}€</td>
            </tr>
          </table>
        `;
      }

      // 桌位或外卖标题
      const titleHtml = orderType === 'takeaway'
        ? ''
        : `<h4>${escapeHtml(tableDisplayName)}</h4>`;

      // 🔥 读取小票抬头样式配置
      const storeNameFontSize = window.clodopConfig?.storeNameFontSize || 18; // 默认18pt
      const headerAlignment = window.clodopConfig?.headerAlignment || 'left'; // 默认靠左

      // 生成完整小票HTML
      const receiptHtml = `
        <!DOCTYPE html>
        <html>
        <head>
          <meta charset="utf-8">
          <title>Ticket ${escapeHtml(tableDisplayName)}</title>
          <style>
            @media print {
              @page { size: auto; margin: 5mm 5mm 5mm 5mm; }
              body { margin: 0; padding: 0; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
            }
            body { font-family: "Courier New", "Lucida Console", monospace; width: 72mm; margin: 0 auto; padding: 5mm 4mm; box-sizing: border-box; font-size: 10pt; font-weight: normal; }
            .receipt { width: 100%; max-width: 72mm; }
            h2 { font-family: Arial, sans-serif; font-size: ${storeNameFontSize}pt; font-weight: bold; text-align: ${headerAlignment}; margin: 0 0 1mm 0; line-height: 1.15; }
            .store-info { text-align: ${headerAlignment}; max-width: 100%; }
            .store-info .business-name { font-size: 0.9em; margin-bottom: 0.4mm; font-weight: normal; line-height: 1.35; }
            .store-info .cif-nif { font-size: 0.85em; margin-bottom: 0.4mm; font-weight: normal; line-height: 1.35; }
            .store-info .phone { font-size: 0.85em; margin-bottom: 0.4mm; font-weight: normal; line-height: 1.35; }
            .store-info .address { font-size: 0.85em; margin-bottom: 0; margin-top: 0.5mm; line-height: 1.35; font-weight: normal; }
            h4 { font-size: 1.1em; font-weight: bold; text-align: ${headerAlignment}; margin: 2mm 0 1mm 0; }
            .date-line, .invoice-number, .verifactu-invoice-number { text-align: ${headerAlignment} !important; }
            .date-line { font-size: 0.8em; margin-bottom: 2mm; }
            table { width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 1em; margin-top: 3px; margin-bottom: 3px; }
            th, td { padding: 0.8mm 0.5mm; vertical-align: top; }
            th { border-bottom: 2px dashed #000; text-align: left; font-size: 1.0em; font-weight: bold; }
            td.item-name { white-space: nowrap; overflow: hidden; text-overflow: clip; text-transform: uppercase; word-break: normal; letter-spacing: normal; font-family: "Courier New", "Lucida Console", monospace; font-size: 0.8em; font-weight: normal; text-align: left; padding-left: 0; line-height: 1.25; }
            td.col-qty { text-align: center; font-weight: normal; font-size: 0.9em; padding: 0 1mm; line-height: 1.25; }
            td.col-price { text-align: right; font-weight: normal; font-size: 0.9em; padding-right: 1mm; line-height: 1.25; }
            td.col-total { text-align: right; font-weight: normal; font-size: 0.9em; line-height: 1.25; }
            .totals-table { margin-top: 2mm; }
            .totals-table td { padding: 0.6mm 0.5mm; }
            .total-row td { border-top: 2px solid #000; font-weight: bold; padding-top: 1.2mm; font-size: 1.15em; }
            .footer { text-align: center; font-size: 0.9em; margin-top: 4mm; line-height: 1.4em; }
	            hr { display: none; border: none; margin: 0; }
	            .payment-details-table tr:first-child td { border-bottom: 2px dashed #000 !important; padding-bottom: 1mm !important; }
            .receipt-logo-container { text-align: ${headerAlignment}; margin-bottom: 3mm; }
            .receipt-logo { max-width: 50mm; max-height: 20mm; display: inline-block; }
          </style>
        </head>
        <body>
          <div class="receipt">
            ${logoHtml}
            ${storeInfo.storeName ? `<h2>${escapeHtml(storeInfo.storeName).replace(/\n/g, '<br>')}</h2>` : ''}
            <div class="store-info">
              ${storeInfoHtml}
            </div>
            ${titleHtml}
            <div class="date-line">Fecha: ${formattedDate}</div>
            <div class="invoice-number" style="text-align: center; font-weight: bold; margin-bottom: 2mm;" data-invoice-number="${localInvoiceNumber}">FACTURA SIMPLIFICADA: ${localInvoiceNumber}</div>
            <hr>
            <table>
              <thead>
                <tr>
                  <th style="width: 50%;">Producto</th>
                  <th style="width: 15%; text-align:center;">Cant.</th>
                  <th style="width: 15%; text-align:right;">Precio</th>
                  <th style="width: 20%; text-align:right;">Total</th>
                </tr>
              </thead>
              <tbody>
                ${itemsHtml || '<tr><td colspan="4" style="text-align:center; padding: 5px 0;">Sin productos</td></tr>'}
              </tbody>
            </table>
            <hr>
            <table class="totals-table">
              <tr>
                <td colspan="3" style="text-align: right;">Base Imponible:</td>
                <td style="text-align: right;">${subtotalWithoutTax.toFixed(2)}€</td>
              </tr>
              <tr>
                <td colspan="3" style="text-align: right;">${receiptTaxLabel}</td>
                <td style="text-align: right;">${taxAmount.toFixed(2)}€</td>
              </tr>
              ${discountHtml}
              <tr class="total-row">
                <td colspan="3" style="text-align: right;">TOTAL:</td>
                <td style="text-align: right;">${grandTotal.toFixed(2)}€</td>
              </tr>
            </table>
            ${paymentHtml}
            <div class="footer">
              ${escapeHtml(storeInfo.receiptFooter || '¡Gracias por su compra!')}
            </div>
          </div>
        </body>
        </html>
      `;

      return receiptHtml;
    }

    /**
     * 保存本地生成的小票到localStorage
     * @param {Object} options 同generateLocalReceiptHtml的参数
     * @param {string} type 小票类型 'table_payment' | 'takeaway'
     */
    function saveLocalReceiptToStorage(options, type = 'table_payment') {
      try {
        const receiptHtml = generateLocalReceiptHtml(options);
        localStorage.setItem('lastReceiptHtml', receiptHtml);
        localStorage.setItem('lastReceiptType', type);
        localStorage.setItem('lastReceiptTimestamp', Date.now().toString());
        localStorage.removeItem('lastReceiptRequestBody');
        // // console.log('[本地小票] ✅ 已保存到localStorage，类型:', type);
        return true;
      } catch (error) {
        console.error('[本地小票] ❌ 保存失败:', error);
        return false;
      }
    }

    /**
     * HTML转义函数
     */
    function escapeHtml(text) {
      if (!text) return '';
      const div = document.createElement('div');
      div.textContent = String(text);
      return div.innerHTML;
    }

    // ========== 上一单信息显示功能 ==========

    /**
     * 保存并显示上一单信息
     * @param {Object} orderInfo 订单信息
     */
    function saveAndShowLastOrderInfo(orderInfo) {
      const { totalAmount, paymentMethod, receivedAmount, changeAmount, tableNumber, orderType, cashAmount, cardAmount, originalTotal, discountAmount, chequeAmount } = orderInfo;

      // 保存到全局变量
      window.lastOrderInfo = {
        total: parseFloat(totalAmount) || 0,
        originalTotal: parseFloat(originalTotal) || parseFloat(totalAmount) || 0, // 🔥 原价（折扣前）
        discountAmount: parseFloat(discountAmount) || 0, // 🔥 折扣金额
        chequeAmount: parseFloat(chequeAmount) || 0, // 🔥 抵扣券金额
        method: paymentMethod || 'cash',
        received: parseFloat(receivedAmount) || 0,
        change: parseFloat(changeAmount) || 0,
        cash: parseFloat(cashAmount) || 0,  // 混合支付-现金部分
        card: parseFloat(cardAmount) || 0,  // 混合支付-刷卡部分
        table: tableNumber || '',
        type: orderType || 'takeaway',
        time: new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit', second: '2-digit' })
      };

      // 更新显示
      updateLastOrderDisplay();
      // // console.log('[上一单] 已保存:', window.lastOrderInfo);

      // 🔥 以弹窗形式显示上一单信息
      showLastOrderPopup();
    }

    /**
     * 🔥 以弹窗形式显示上一单信息
     * 点击弹窗外任意区域可关闭
     */
    function showLastOrderPopup() {
      const info = window.lastOrderInfo;
      if (!info) return;

      // 🔥 检查设置：是否显示结账后的找零弹窗
      const showChangePopup = <?php echo json_encode(get_option('pos_show_change_popup', '1') === '1'); ?>;
      if (!showChangePopup) return;

      // 构建支付明细HTML
      const renderLastOrderChangeBlock = (receivedLabel, receivedAmount, changeAmount, receivedTone = 'green', receivedIcon = 'fa-hand-holding-usd') => {
        const receivedToneClasses = receivedTone === 'blue'
          ? 'bg-blue-50 border-blue-100 text-blue-700'
          : 'bg-green-50 border-green-100 text-green-700';

        return `
          <div class="mt-4 grid grid-cols-2 gap-3 max-w-md mx-auto text-left">
            <div class="rounded-xl border ${receivedToneClasses} px-4 py-3">
              <div class="text-xs font-bold text-gray-500 mb-1">
                <i class="fas ${receivedIcon} mr-1"></i>${receivedLabel}
              </div>
              <div class="text-xl font-extrabold leading-tight">€${receivedAmount.toFixed(2)}</div>
            </div>
            <div class="rounded-xl border-2 border-orange-300 bg-orange-50 px-4 py-3 shadow-sm">
              <div class="text-xs font-bold text-orange-700 mb-1">
                <i class="fas fa-coins mr-1"></i><?php echo ruiyi_translate('Cambio', 'Change', '找零'); ?>
              </div>
              <div class="text-4xl font-black leading-none text-orange-500">€${changeAmount.toFixed(2)}</div>
            </div>
          </div>
        `;
      };

      let paymentDetails = '';
      if (info.method === 'cash') {
        if (info.received > 0) {
          if (info.change > 0) {
            paymentDetails = renderLastOrderChangeBlock(
              '<?php echo ruiyi_translate('Recibido', 'Received', '收款'); ?>',
              info.received,
              info.change
            );
          } else {
            paymentDetails = `<div class="flex flex-wrap items-center justify-center gap-2 mt-3">
              <span class="bg-green-100 text-green-700 px-3 py-1.5 rounded-lg font-medium">
                <i class="fas fa-hand-holding-usd mr-1"></i><?php echo ruiyi_translate('Recibido', 'Received', '收款'); ?>: €${info.received.toFixed(2)}
              </span>
            </div>`;
          }
        }
      } else if (info.method === 'card') {
        paymentDetails = `<div class="flex items-center justify-center mt-3">
          <span class="bg-blue-100 text-blue-700 px-3 py-1.5 rounded-lg font-medium">
            <i class="fas fa-credit-card mr-1"></i><?php echo ruiyi_translate('Tarjeta', 'Card', '刷卡支付'); ?>
          </span>
        </div>`;
        if (info.received > 0 && info.change > 0) {
          paymentDetails += renderLastOrderChangeBlock(
            '<?php echo ruiyi_translate('Recibido', 'Received', '收款'); ?>',
            info.received,
            info.change,
            'blue',
            'fa-credit-card'
          );
        }
      } else if (info.method === 'mixed') {
        paymentDetails = '<div class="flex flex-wrap items-center justify-center gap-2 mt-3">';
        if (info.cash > 0) {
          paymentDetails += `<span class="bg-green-100 text-green-700 px-3 py-1.5 rounded-lg font-medium">
            <i class="fas fa-money-bill-wave mr-1"></i><?php echo ruiyi_translate('Efectivo', 'Cash', '现金'); ?>: €${info.cash.toFixed(2)}
          </span>`;
        }
        if (info.card > 0) {
          paymentDetails += `<span class="bg-blue-100 text-blue-700 px-3 py-1.5 rounded-lg font-medium">
            <i class="fas fa-credit-card mr-1"></i><?php echo ruiyi_translate('Tarjeta', 'Card', '刷卡'); ?>: €${info.card.toFixed(2)}
          </span>`;
        }
        paymentDetails += '</div>';
        if (info.change > 0) {
          paymentDetails += renderLastOrderChangeBlock(
            '<?php echo ruiyi_translate('Efectivo', 'Cash', '现金'); ?>',
            info.cash,
            info.change
          );
        }
      }

      // 显示金额（如有折扣显示原价划线）
      let totalDisplay = '';
      const hasDeductions = (info.discountAmount > 0 || info.chequeAmount > 0) && info.originalTotal > info.total;
      if (hasDeductions) {
        totalDisplay = `<span class="text-gray-400 line-through text-2xl mr-2">€${info.originalTotal.toFixed(2)}</span>
                        <span class="text-green-600 font-bold text-4xl">€${info.total.toFixed(2)}</span>`;
      } else {
        totalDisplay = `<span class="text-green-600 font-bold text-4xl">€${info.total.toFixed(2)}</span>`;
      }

      // 桌号显示（如有）
      const tableInfo = info.table ? `<div class="text-gray-500 text-sm mb-2">${info.table}</div>` : '';

      Swal.fire({
        html: `
          <div class="text-center py-2">
            <div class="text-green-500 text-6xl mb-4">
              <i class="fas fa-check-circle"></i>
            </div>
            <h2 class="text-2xl font-bold text-gray-800 mb-2"><?php echo ruiyi_translate('Pedido completado', 'Order completed', '订单完成'); ?></h2>
            ${tableInfo}
            <div class="text-gray-500 text-sm mb-4">${info.time}</div>
            <div class="mb-4">${totalDisplay}</div>
            ${paymentDetails}
            <div class="mt-6 pt-4 border-t border-gray-200">
              <p class="text-gray-400 text-xs">
                <i class="fas fa-hand-pointer mr-1"></i>
                <?php echo ruiyi_translate('Toque fuera o presione cualquier tecla para cerrar', 'Tap outside or press any key to close', '点击空白处或按任意键关闭'); ?>
              </p>
            </div>
          </div>
        `,
        showConfirmButton: false,
        allowOutsideClick: true,
        allowEscapeKey: true,
        backdrop: true,
        customClass: {
          popup: 'rounded-2xl shadow-2xl',
          container: 'last-order-popup-container'
        },
        didOpen: () => {
          // 🔥 任意键盘按键关闭弹窗（包括 Enter/Intro 键）
          // 使用 capture: true 确保在捕获阶段处理，优先于其他监听器
          window._lastOrderKeyHandler = (e) => {
            console.log('[上一单弹窗] 按键触发:', e.key);
            // 阻止默认行为和事件传播
            e.preventDefault();
            e.stopPropagation();
            e.stopImmediatePropagation();
            Swal.close();
          };
          // 使用 capture: true 在捕获阶段处理
          document.addEventListener('keydown', window._lastOrderKeyHandler, true);

          // 🔥 【增强】点击弹窗背景关闭弹窗
          window._lastOrderBackdropHandler = (e) => {
            // 点击背景区域（非弹窗内容）才关闭
            const popup = document.querySelector('.swal2-popup');
            if (popup && !popup.contains(e.target)) {
              console.log('[上一单弹窗] 点击背景关闭');
              Swal.close();
            }
          };
          const container = document.querySelector('.swal2-container');
          if (container) {
            container.addEventListener('click', window._lastOrderBackdropHandler);
          }
        },
        willClose: () => {
          // 关闭时移除事件监听
          if (window._lastOrderKeyHandler) {
            document.removeEventListener('keydown', window._lastOrderKeyHandler, true);
            window._lastOrderKeyHandler = null;
          }
          if (window._lastOrderBackdropHandler) {
            const container = document.querySelector('.swal2-container');
            if (container) {
              container.removeEventListener('click', window._lastOrderBackdropHandler);
            }
            window._lastOrderBackdropHandler = null;
          }
        }
      });
    }

    /**
     * 更新上一单显示（内部函数，更新指定元素）
     */
    function updateLastOrderDisplayForElements(containerId, totalId, timeId, detailsId) {
      const info = window.lastOrderInfo;
      if (!info) return;

      const container = document.getElementById(containerId);
      const totalEl = document.getElementById(totalId);
      const timeEl = document.getElementById(timeId);
      const detailsEl = document.getElementById(detailsId);

      if (container && totalEl) {
        container.classList.remove('hidden');

        // 🔥 【修复】如果有折扣或抵扣，显示原价（划线）和实付金额
        const hasDeductions = (info.discountAmount > 0 || info.chequeAmount > 0) && info.originalTotal > info.total;
        if (hasDeductions) {
          // 显示原价（划线）+ 实付金额
          totalEl.innerHTML = `<span class="text-gray-400 line-through text-base mr-2">€${info.originalTotal.toFixed(2)}</span><span class="text-green-600 font-bold">€${info.total.toFixed(2)}</span>`;
        } else {
          totalEl.textContent = '€' + info.total.toFixed(2);
        }

        if (timeEl) timeEl.textContent = `(${info.time})`;

        // 构建支付明细 - 突出重点：收款和找零
        let details = '';
        if (info.method === 'cash') {
          // 现金支付：显示收款和找零（如果有）
          if (info.received > 0) {
            details = `<div class="flex flex-wrap items-center gap-2">
              <span class="bg-green-100 text-green-700 px-2 py-1 rounded font-medium">
                <i class="fas fa-hand-holding-usd mr-1"></i><?php echo ruiyi_translate('Recibido', 'Received', '收款'); ?>: €${info.received.toFixed(2)}
              </span>`;
            if (info.change > 0) {
              details += `<span class="text-gray-400">→</span>
              <span class="bg-orange-100 text-orange-700 px-2 py-1 rounded font-bold">
                <i class="fas fa-coins mr-1"></i><?php echo ruiyi_translate('Cambio', 'Change', '找零'); ?>: €${info.change.toFixed(2)}
              </span>`;
            }
            details += '</div>';
          }
        } else if (info.method === 'card') {
          details = `<div class="flex items-center">
            <span class="bg-blue-100 text-blue-700 px-2 py-1 rounded font-medium">
              <i class="fas fa-credit-card mr-1"></i><?php echo ruiyi_translate('Tarjeta', 'Card', '刷卡支付'); ?>
            </span>
          </div>`;
        } else if (info.method === 'mixed') {
          // 混合支付：显示现金和刷卡金额
          details = '<div class="flex flex-wrap items-center gap-2">';
          if (info.cash > 0) {
            details += `<span class="bg-green-100 text-green-700 px-2 py-1 rounded font-medium">
              <i class="fas fa-money-bill-wave mr-1"></i><?php echo ruiyi_translate('Efectivo', 'Cash', '现金'); ?>: €${info.cash.toFixed(2)}
            </span>`;
          }
          if (info.card > 0) {
            details += `<span class="bg-blue-100 text-blue-700 px-2 py-1 rounded font-medium">
              <i class="fas fa-credit-card mr-1"></i><?php echo ruiyi_translate('Tarjeta', 'Card', '刷卡'); ?>: €${info.card.toFixed(2)}
            </span>`;
          }
          // 如果有找零也显示
          if (info.change > 0) {
            details += `<span class="text-gray-400">→</span>
            <span class="bg-orange-100 text-orange-700 px-2 py-1 rounded font-bold">
              <i class="fas fa-coins mr-1"></i><?php echo ruiyi_translate('Cambio', 'Change', '找零'); ?>: €${info.change.toFixed(2)}
            </span>`;
          }
          details += '</div>';
        }

        if (detailsEl) detailsEl.innerHTML = details;
      }
    }

    /**
     * 更新上一单显示（收银模块）
     */
    function updateLastOrderDisplay() {
      // 更新收银模块上一单显示
      updateLastOrderDisplayForElements('last-order-info', 'last-order-total', 'last-order-time', 'last-order-payment-details');
    }

    /**
     * 清除上一单信息
     */
    function clearLastOrderInfo() {
      window.lastOrderInfo = null;
      // 清除收银模块上一单显示
      const container = document.getElementById('last-order-info');
      if (container) container.classList.add('hidden');
    }

    /**
     * 🔥 仅隐藏桌位模块的上一单信息（已移除桌位模块上一单显示，保留空函数以兼容）
     */
    function hideMesasLastOrderInfo() {
      // 桌位模块上一单已移除，此函数保留以兼容现有调用
    }
    window.hideMesasLastOrderInfo = hideMesasLastOrderInfo;

    // 绑定清除按钮事件
    document.addEventListener('DOMContentLoaded', function() {
      // 收银模块清除按钮
      const clearBtn = document.getElementById('clear-last-order');
      if (clearBtn) {
        clearBtn.addEventListener('click', clearLastOrderInfo);
      }
    });

    // ========== 上一单信息显示功能结束 ==========

    // 🔥 更新预结单按钮和工具箱显示状态
    function updateProformaButtonVisibility() {
      const printProformaBtn = document.getElementById('print-proforma-new-order');  // 添加订单模式
      const printPreviewBtn = document.getElementById('print-preview-bill-btn');     // 查看模式(viewMode)
      const proformaDrawerRow = document.getElementById('proforma-drawer-row');
      const openDrawerBtn = document.getElementById('open-drawer-btn');
      const toolboxToggleBtn = document.getElementById('toolbox-toggle-btn');        // 工具箱按钮

      // 🔥 Proforma 锁定状态由 HTML disabled 属性控制，不再影响显示逻辑

      if (proformaDrawerRow && openDrawerBtn) {
        const tableNumber = document.getElementById('table-number')?.value.trim();
        const viewModeData = sessionStorage.getItem('tableViewMode');
        const isViewMode = viewModeData ? JSON.parse(viewModeData)?.mode === 'view' : false;

        // 🔥 桌位模式：根据是否是viewMode决定显示哪个按钮
        const isTableMode = !!tableNumber;

        // 🔥 按钮显示逻辑（锁定状态下按钮仍然显示，但会被禁用）
        const showNewOrderBtn = isTableMode && !isViewMode;   // 添加新订单时显示
        const showViewModeBtn = isTableMode && isViewMode;    // 查看模式时显示

        // 控制两个按钮的显示
        if (printProformaBtn) {
          printProformaBtn.classList.toggle('hidden', !showNewOrderBtn);
        }
        if (printPreviewBtn) {
          printPreviewBtn.classList.toggle('hidden', !showViewModeBtn);
        }

        // 🔥 只要有一个预结单按钮显示，就并排布局
        const shouldShowSideBySide = showNewOrderBtn || showViewModeBtn;
        if (shouldShowSideBySide) {
          // 两个按钮并排，各占一半
          proformaDrawerRow.classList.remove('grid-cols-1');
          proformaDrawerRow.classList.add('grid-cols-2');
        } else {
          // 只有开钱箱按钮，占满整行
          proformaDrawerRow.classList.remove('grid-cols-2');
          proformaDrawerRow.classList.add('grid-cols-1');
        }

        // 🔥 工具箱按钮：桌位模式下始终显示（无论是添加新订单还是viewMode）
        if (toolboxToggleBtn) {
          toolboxToggleBtn.classList.toggle('hidden', !isTableMode);
        }
      }
    }

    // 🔥 同步购物车到桌位状态（用于锁定产品数量修改后的即时同步）
    function syncCartToMesasEstado() {
      const tableNumberForSync = document.getElementById('table-number')?.value.trim();
      if (!tableNumberForSync) return;

      try {
        const mesasEstadoSync = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
        const tableNum = resolveGlobalTableNumber(tableNumberForSync);

        // 多格式查找（支持任意区域名称，只用标准前缀匹配）
        const possiblePrefixes = ['Mesa', 'Table', '餐桌'];
        let actualMesaKey = `Mesa ${tableNum}`;
        for (const prefix of possiblePrefixes) {
          const altKey = `${prefix} ${tableNum}`;
          if (mesasEstadoSync[altKey]) {
            actualMesaKey = altKey;
            break;
          }
          const altKeyNoSpace = `${prefix}${tableNum}`;
          if (mesasEstadoSync[altKeyNoSpace]) {
            actualMesaKey = altKeyNoSpace;
            break;
          }
        }

        if (mesasEstadoSync[actualMesaKey]) {
          // 🔥🔥🔥 【2026-01-31 关键修复】过滤掉数量为0的商品
          const cartToSaveFiltered = cart.filter(item => item.quantity > 0);
          // 计算新总额
          const newTotal = cartToSaveFiltered.reduce((sum, item) => {
            return sum + ((parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0))) * parseFloat(item.quantity));
          }, 0);

          mesasEstadoSync[actualMesaKey].total = parseFloat(newTotal.toFixed(2));
          mesasEstadoSync[actualMesaKey].cart = JSON.parse(JSON.stringify(cartToSaveFiltered));
          mesasEstadoSync[actualMesaKey].cart_gtn = parseInt(tableNum);
          mesasEstadoSync[actualMesaKey]._lastUpdate = Date.now();
          localStorage.setItem('mesas_estado', JSON.stringify(mesasEstadoSync));
          console.log('[syncCartToMesasEstado] 已同步购物车到桌位状态:', actualMesaKey, '总额:', newTotal.toFixed(2));
        }
      } catch (e) {
        console.warn('[syncCartToMesasEstado] 同步失败:', e);
      }
    }
    window.syncCartToMesasEstado = syncCartToMesasEstado;

    /**
     * 🔥🔥🔥 关键修复：合并购物车中的重复条目
     * 将相同产品ID和价格的条目合并，防止重复显示和同步
     */
    function consolidateCartItems() {
      if (!cart || cart.length <= 1) return;

      const consolidatedMap = new Map();
      const itemsToRemove = [];

      cart.forEach((item, index) => {
        // 创建唯一键：产品ID + 自定义价格 + 锁定状态 + 自定义名称 + 备注 + 配料
        // 🔥🔥🔥 【2026-03-30 关键修改】locked 和 unlocked 的同产品不合并
        // 🔥 有备注、配料或自定义名称的产品不与其他同产品合并
        const priceKey = item.customPrice !== undefined ? item.customPrice : item.price;
        const lockedKey = item.locked ? 'locked' : 'unlocked';
        const notesKey = item.notes ? `_n${item.notes}` : '';
        const customNameKey = item.customName ? `_cn${item.customName}` : '';
        const suppsKey = item.supplements && item.supplements.length > 0 ? `_s${item.supplements.map(s => s.id).join(',')}` : '';
        const key = `${item.id}_${priceKey}_${lockedKey}${notesKey}${customNameKey}${suppsKey}`;

        if (consolidatedMap.has(key)) {
          // 已存在相同产品且锁定状态相同，合并数量
          const existingIndex = consolidatedMap.get(key);
          const existingItem = cart[existingIndex];

          // 合并数量
          existingItem.quantity += item.quantity;

          // 如果任一条目被锁定，保留锁定状态
          if (item.locked) {
            existingItem.locked = true;
            existingItem.orderId = existingItem.orderId || item.orderId;
          }

          // 如果任一条目有修改标记，保留
          if (item.quantityModified) {
            existingItem.quantityModified = true;
          }
          if (item.isNew) {
            existingItem.isNew = true;
          }

          // 合并 addedQuantity
          if (item.addedQuantity) {
            existingItem.addedQuantity = (existingItem.addedQuantity || 0) + item.addedQuantity;
          }

          itemsToRemove.push(index);
        } else {
          consolidatedMap.set(key, index);
        }
      });

      // 从后往前删除，避免索引错位
      if (itemsToRemove.length > 0) {
        itemsToRemove.sort((a, b) => b - a);
        itemsToRemove.forEach(index => {
          cart.splice(index, 1);
        });

        // 重新校正选中索引
        if (selectedCartItemIndex >= cart.length) {
          selectedCartItemIndex = cart.length - 1;
          window.selectedCartItemIndex = selectedCartItemIndex;
        }

        // 同步到localStorage
        syncCartToMesasEstado();
      }
    }
    window.consolidateCartItems = consolidateCartItems;

    // 🔥 多语言产品名称显示辅助函数
    // supplements 名称已合入 customName，无需额外追加
    function getItemDisplayName(item) {
        if (!window.RUIYI_POS_CONFIG?.multilingualNames) return item.customName || item.name;
        const lang = window.RUIYI_POS?.currentLang || 'zh';
        switch (lang) {
            case 'zh': return item.customName || item.name_zh || item.name_es || item.name || '';
            case 'en': return item.customName || item.name_en || item.name_es || item.name || '';
            default:   return item.customName || item.name_es || item.name || '';
        }
    }

    // Renderizar el carrito (función centralizada)
    function renderCart(options = {}) {
      // 🔥 解析选项参数
      const { scrollToBottom = false } = options;

      // 🔥🔥🔥 关键：渲染前先合并重复条目
      consolidateCartItems();
      const cont = document.getElementById('cart-items');
      if (!cont) return; // 退出如果容器不存在

      // 🔥 同步全局选中索引到局部变量（确保 pos-cart.js 的更新能被读取）
      if (window.selectedCartItemIndex !== undefined) {
        selectedCartItemIndex = window.selectedCartItemIndex;
      }

      // 🔥 检查是否在查看模式
      const viewMode = sessionStorage.getItem('tableViewMode');
      const isViewMode = viewMode ? JSON.parse(viewMode) : null;

      cont.innerHTML = '';
      let lockedTotal = 0; // 已锁定产品总额
      let newTotal = 0; // 新增产品总额
      let totalQuantity = 0; // 商品总数量
      let printQueueCount = 0; // 厨房打印盒子商品数量

      // 🔥 修改：检查整个购物车是否为空（包括锁定和未锁定）
      if (cart.length === 0) {
        cont.innerHTML = `
          <div class="flex flex-col items-center justify-center py-10 bg-gray-50 rounded-lg">
            <i class="fas fa-shopping-cart text-gray-300 text-4xl mb-3"></i>
            <div class="text-gray-500 text-center"><?php echo ruiyi_translate('El carrito está vacío', 'The cart is empty', '购物车是空的'); ?></div>
            <div class="text-xs text-gray-400 mt-1"><?php echo ruiyi_translate('Añade productos para comenzar a pedir', 'Add products to start ordering', '添加商品开始点餐'); ?></div>
          </div>`;

        const subtotalElem = document.getElementById('subtotal-amount');
        if (subtotalElem) subtotalElem.textContent = `€0.00`;
        const totalElem = document.getElementById('total-amount');
        if (totalElem) totalElem.textContent = `€0.00`;

        // 🔥 购物车为空时，强制显示普通模式（simple-summary）
        const detailedSummary = document.getElementById('detailed-summary');
        const simpleSummary = document.getElementById('simple-summary');
        if (detailedSummary) detailedSummary.classList.add('hidden');
        if (simpleSummary) simpleSummary.classList.remove('hidden');

        // 🔥 更新购物车统计显示
        const cartTotalQuantityElem = document.getElementById('cart-total-quantity');
        if (cartTotalQuantityElem) cartTotalQuantityElem.textContent = '0';
        const cartTotalPriceElem = document.getElementById('cart-total-price');
        if (cartTotalPriceElem) cartTotalPriceElem.textContent = '€0.00';

        // 🔥 购物车为空时，始终显示结账按钮
        // 修改：用户要求在给桌位创建订单时也能看到结账按钮
        const checkoutBtn = document.getElementById('checkout-table-btn');
        if (checkoutBtn) {
            // 始终显示结账按钮
            checkoutBtn.classList.remove('hidden');
            checkoutBtn.style.display = 'flex';

            // 如果有桌位号，设置到按钮的data属性
            const tableNumberValue = document.getElementById('table-number')?.value.trim();
            if (tableNumberValue) {
                checkoutBtn.dataset.tableNumber = tableNumberValue;
            }
        }

        // 🔥 购物车为空时，清除折扣状态并隐藏折扣标识
        window.currentDiscountPercent = 0;
        updateDiscountBadge();

        // 🔥 购物车为空时也要处理预结单按钮显示（在return之前）
        updateProformaButtonVisibility();

        return;
      }

      // 🔥 购物车有商品时，自动隐藏上一单信息
      const lastOrderInfo = document.getElementById('last-order-info');
      if (lastOrderInfo && !lastOrderInfo.classList.contains('hidden')) {
        lastOrderInfo.classList.add('hidden');
        // // console.log('[上一单] 购物车有商品，自动隐藏');
      }

      // 🔥 控制"打印预结单"按钮显示
      updateProformaButtonVisibility();

      // 🔥🔥🔥 【2026-03-30】渲染前排序：locked 项排在前面，unlocked 项排在后面
      // 不修改原始 cart 数组的顺序，只在渲染时排序
      const sortedCartWithIndex = cart.map((item, idx) => ({ item, originalIndex: idx }))
        .sort((a, b) => {
          if (a.item.locked && !b.item.locked) return -1;  // locked 在前
          if (!a.item.locked && b.item.locked) return 1;   // unlocked 在后
          return 0;  // 同类保持原顺序
        });

      sortedCartWithIndex.forEach(({ item, originalIndex: index }) => {
        // 🔥 For scale products: use customPrice (calculated total) for total calculation
        // 🔥 For regular products: use price * quantity
        // 🔥 Display always shows original price per unit
        // 🔥 修复：使用 toFixed(2) 避免浮点数精度问题
        // 🔥 supplements 已合入 customPrice，无需额外计算
        let itemTotal;
        if (item.isScaleProduct && item.customPrice !== undefined && item.customPrice !== null) {
          itemTotal = parseFloat((item.customPrice * item.quantity).toFixed(2));
        } else {
          const itemPrice = parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0));
          itemTotal = parseFloat((itemPrice * item.quantity).toFixed(2));
        }

        // 🔥 只有数量 > 0 的商品才计入总数和总价
        if (item.quantity > 0) {
          totalQuantity += item.quantity;

          // 🍽️ 自助餐商品不计入金额总价，但计入厨房打印
          if (item.is_buffet) {
            // 自助餐只计入打印队列
            if (!item.locked) {
              printQueueCount += item.quantity;
            } else if ((item.addedQuantity || 0) > 0) {
              printQueueCount += item.addedQuantity;
            }
          } else {
            // 🔥 分别累计锁定和新增商品的总额
            if (item.locked) {
              lockedTotal += itemTotal;
              // 厨房打印盒子：锁定商品的新增数量部分
              if ((item.addedQuantity || 0) > 0 && !item.is_buffet_opening) {
                printQueueCount += item.addedQuantity;
              }
            } else {
              newTotal += itemTotal;
              // 厨房打印盒子：新添加的商品（🍽️ 开台商品不计入）
              if (!item.is_buffet_opening) {
                printQueueCount += item.quantity;
              }
            }
          }
        }

        // 🔥 根据锁定状态显示不同样式
        if (item.locked) {
          // ========== 已锁定产品：蓝色边框，可删除 ==========
          // 🔥 新布局：商品名称 - 数量显示（只读） - 价格 - 删除按钮
          // 🔥 修复：添加折扣标识显示支持
          const lockedHasDiscount = item.hasDiscount && item.discountPercent > 0;
          const lockedBorderClass = lockedHasDiscount ? 'border-green-400' : 'border-blue-400';
          const lockedBgClass = lockedHasDiscount ? 'bg-green-50' : 'bg-blue-50';

          cont.innerHTML += `
            <div class="flex items-center justify-between p-2 mb-1 rounded-lg border ${lockedBorderClass} ${lockedBgClass}">
              <!-- 1️⃣ 商品名称 + 锁定图标 + 折扣标识（🔥可点击编辑名称） -->
              <div class="flex items-center flex-1 min-w-0 mr-1">
                <i class="fas fa-lock text-blue-500 text-xs mr-1 flex-shrink-0"></i>
                ${lockedHasDiscount ? `<span class="text-xs bg-green-500 text-white px-1 rounded mr-1 flex-shrink-0">-${item.discountPercent}%</span>` : ''}
                ${item.notes ? '<span class="text-orange-500 text-xs mr-1 flex-shrink-0" title="' + (item.notes || '').replace(/"/g, '&quot;') + '">📝</span>' : ''}
                <p class="item-name font-medium text-gray-800 text-sm truncate cursor-pointer hover:bg-blue-100 px-1 rounded transition-colors"
                   title="<?php echo ruiyi_translate('Clic para editar nombre', 'Click to edit name', '点击编辑名称'); ?>"
                   data-index="${index}"
                   onclick="event.stopPropagation(); editNameInline(${index})">${getItemDisplayName(item)}</p>
              </div>

              <!-- 2️⃣ 单价（🔥可点击编辑价格，优先显示临时价，有折扣时显示原价划线） -->
              <div class="w-16 text-right mr-1 flex-shrink-0">
                ${(() => {
                  const displayPrice = item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0);
                  const hasCustomPrice = item.customPrice !== undefined && item.customPrice !== null && Math.abs(item.customPrice - (item.price || 0)) > 0.01;
                  if (lockedHasDiscount && item.originalPrice) {
                    return `<span class="text-xs text-gray-400 line-through">${parseFloat(item.originalPrice).toFixed(2)}€</span><br><span class="text-sm text-green-600 font-semibold item-unit-price cursor-pointer hover:bg-green-100 px-1 rounded transition-colors" data-index="${index}" onclick="event.stopPropagation(); editPriceInline(${index})" title="<?php echo ruiyi_translate('Clic para editar precio', 'Click to edit price', '点击编辑价格'); ?>">${parseFloat(displayPrice).toFixed(2)}€</span>`;
                  }
                  return `<span class="text-sm ${hasCustomPrice ? 'text-blue-600 font-semibold' : 'text-gray-700'} item-unit-price cursor-pointer hover:bg-blue-100 px-1 rounded transition-colors" data-index="${index}" onclick="event.stopPropagation(); editPriceInline(${index})" title="<?php echo ruiyi_translate('Clic para editar precio', 'Click to edit price', '点击编辑价格'); ?>">${parseFloat(displayPrice).toFixed(2)}€</span>`;
                })()}
              </div>

              <!-- 3️⃣ 数量加减按钮（锁定产品也可调整数量） -->
              <div class="w-20 flex items-center justify-center border ${lockedHasDiscount ? 'border-green-300' : 'border-blue-300'} rounded-md mr-1 bg-white flex-shrink-0">
                <button class="decrease-item px-1 py-1 text-gray-600 hover:text-blue-600 hover:bg-blue-50 focus:outline-none transition-colors" data-index="${index}">
                  <i class="fas fa-minus text-xs"></i>
                </button>
                <span class="quantity-display w-8 text-center text-sm font-medium text-gray-800 cursor-pointer hover:bg-blue-50 rounded transition-colors"
                      data-index="${index}"
                      onclick="event.stopPropagation(); editQuantityInline(${index})"
                      title="<?php echo ruiyi_translate('Clic para editar cantidad', 'Click to edit quantity', '点击编辑数量'); ?>">${item.quantity}</span>
                <button class="increase-item px-1 py-1 text-gray-600 hover:text-blue-600 hover:bg-blue-50 focus:outline-none transition-colors" data-index="${index}">
                  <i class="fas fa-plus text-xs"></i>
                </button>
              </div>

              <!-- 4️⃣ 金额（总价） -->
              <div class="w-16 text-right mr-1 flex-shrink-0">
                <p class="font-semibold ${lockedHasDiscount ? 'text-green-700' : 'text-blue-700'} text-sm">${itemTotal.toFixed(2)}€</p>
              </div>

              <!-- 5️⃣ Suplementos编辑 + 删除按钮 -->
              <div class="flex items-center gap-1 flex-shrink-0">
                <?php if (get_option('pos_suplementos_edit_enabled', '0') === '1' && $show_suplementos): ?>
                <button class="edit-supplements-btn text-gray-400 hover:text-green-500 focus:outline-none transition-colors" data-index="${index}" onclick="event.stopPropagation(); openSupplementsModal(${index})">
                  <i class="fas fa-pen text-sm"></i>
                </button>
                <?php endif; ?>
                <?php if ($show_trash_icon): ?>
                <button class="remove-locked-item text-gray-400 hover:text-red-500 focus:outline-none transition-colors" data-index="${index}">
                  <i class="fas fa-trash-alt text-sm"></i>
                </button>
                <?php endif; ?>
              </div>
            </div>
          `;
        } else {
          // ========== 未锁定产品：普通样式，可操作 ==========
          // 🔥 新布局：商品名称 - 数量按钮 - 价格（可编辑） - 编辑按钮
          // 🔥 数量为0时显示灰色样式
          // 🔥 修复：添加折扣标识显示支持
          const isZeroQuantity = item.quantity === 0;
          // 🔥 修复：使用已同步的 selectedCartItemIndex（在 renderCart 开始处从 window.selectedCartItemIndex 同步）
          const isSelected = selectedCartItemIndex === index;
          const unlockedHasDiscount = item.hasDiscount && item.discountPercent > 0;
          const itemBgClass = isZeroQuantity ? 'bg-gray-100 opacity-60' : (unlockedHasDiscount ? 'bg-green-50' : (isSelected ? 'bg-green-50' : ''));
          const itemBorderClass = isZeroQuantity ? 'border-gray-300' : (unlockedHasDiscount ? 'border-green-400' : (isSelected ? 'border-green-500 border-2' : 'border-gray-200'));
          const itemTextClass = isZeroQuantity ? 'text-gray-400' : 'text-gray-800';
          const hasCustomPrice = item.customPrice !== undefined && item.customPrice !== null && item.customPrice !== item.price;

          cont.innerHTML += `
            <div class="cart-item-row flex items-center justify-between p-2 mb-1 rounded-lg border ${itemBorderClass} ${itemBgClass} transition-colors cursor-pointer ${isSelected ? 'ring-2 ring-green-300' : ''}" data-item-index="${index}" onclick="selectCartItem(${index})">
              <!-- 1️⃣ 商品名称 + 折扣标识 + 自助餐标识（🔥可点击编辑名称） -->
              <div class="flex items-center flex-1 min-w-0 mr-1">
                ${item.is_buffet ? '<span class="text-xs bg-orange-500 text-white px-1 rounded mr-1 flex-shrink-0">🍽️</span>' : ''}
                ${unlockedHasDiscount ? `<span class="text-xs bg-green-500 text-white px-1 rounded mr-1 flex-shrink-0">-${item.discountPercent}%</span>` : ''}
                ${item.notes ? '<span class="text-orange-500 text-xs mr-1 flex-shrink-0" title="' + (item.notes || '').replace(/"/g, '&quot;') + '">📝</span>' : ''}
                <p class="item-name font-medium ${itemTextClass} text-sm truncate cursor-pointer hover:bg-gray-100 px-1 rounded transition-colors"
                   title="<?php echo ruiyi_translate('Clic para editar nombre', 'Click to edit name', '点击编辑名称'); ?>"
                   data-index="${index}"
                   onclick="event.stopPropagation(); editNameInline(${index})">${getItemDisplayName(item)}</p>
                ${isZeroQuantity ? '<p class="text-xs text-orange-500 ml-1"><i class="fas fa-exclamation-circle mr-1"></i><?php echo ruiyi_translate("Cantidad 0", "Quantity 0", "数量为0"); ?></p>' : ''}
              </div>

              <!-- 2️⃣ 单价（直接点击编辑，有折扣时显示原价划线） -->
              <div class="w-16 text-right mr-1 flex-shrink-0">
                ${(() => {
                  // 🔥 显示实际单价：customPrice 就是单价（不是总价）
                  const displayPrice = item.customPrice !== undefined && item.customPrice !== null
                    ? item.customPrice
                    : (item.price || 0);
                  const hasCustomPrice = item.customPrice !== undefined && item.customPrice !== null && item.customPrice !== item.price;
                  // 🔥 修复：有折扣时显示原价划线
                  if (unlockedHasDiscount && item.originalPrice) {
                    return `<span class="text-xs text-gray-400 line-through">${parseFloat(item.originalPrice).toFixed(2)}€</span><br><span class="font-semibold text-green-600 text-sm item-unit-price cursor-pointer hover:bg-green-100 px-1 py-1 rounded transition-colors" data-index="${index}" onclick="event.stopPropagation(); editPriceInline(${index})" title="<?php echo ruiyi_translate('Clic para editar', 'Click to edit', '点击编辑'); ?>">${displayPrice.toFixed(2)}€</span>`;
                  }
                  return `<span class="font-semibold ${isZeroQuantity ? 'text-gray-400' : 'text-gray-900'} text-sm item-unit-price cursor-pointer hover:bg-blue-50 px-1 py-1 rounded transition-colors ${hasCustomPrice ? 'text-blue-600' : ''}" data-index="${index}" onclick="event.stopPropagation(); editPriceInline(${index})" title="<?php echo ruiyi_translate('Clic para editar', 'Click to edit', '点击编辑'); ?>">${displayPrice.toFixed(2)}€</span>`;
                })()}
              </div>

              <!-- 3️⃣ 数量加减按钮 + 可点击编辑数量 -->
              <div class="w-20 flex items-center justify-center border border-gray-300 rounded-md mr-1 flex-shrink-0">
                <button class="decrease-item px-1 py-1 text-gray-600 hover:text-primary hover:bg-gray-100 focus:outline-none transition-colors" data-index="${index}">
                  <i class="fas fa-minus text-xs"></i>
                </button>
                <span class="quantity-display w-8 text-center text-sm font-medium ${itemTextClass} cursor-pointer hover:bg-blue-50 rounded transition-colors"
                      data-index="${index}"
                      onclick="event.stopPropagation(); editQuantityInline(${index})"
                      title="<?php echo ruiyi_translate('Clic para editar cantidad', 'Click to edit quantity', '点击编辑数量'); ?>">${item.quantity}</span>
                <button class="increase-item px-1 py-1 text-gray-600 hover:text-primary hover:bg-gray-100 focus:outline-none transition-colors" data-index="${index}">
                  <i class="fas fa-plus text-xs"></i>
                </button>
              </div>

              <!-- 4️⃣ 金额（总价，有折扣时显示绿色） -->
              <div class="w-16 text-right mr-1 flex-shrink-0">
                <span class="font-semibold ${isZeroQuantity ? 'text-gray-400' : (unlockedHasDiscount ? 'text-green-700' : 'text-gray-900')} text-sm">${itemTotal.toFixed(2)}€</span>
              </div>

              <!-- 5️⃣ Suplementos编辑 + 删除按钮 -->
              <div class="flex items-center gap-1 flex-shrink-0">
                <?php if (get_option('pos_suplementos_edit_enabled', '0') === '1' && $show_suplementos): ?>
                <button class="edit-supplements-btn text-gray-400 hover:text-green-500 focus:outline-none transition-colors" data-index="${index}" onclick="event.stopPropagation(); openSupplementsModal(${index})">
                  <i class="fas fa-pen text-sm"></i>
                </button>
                <?php endif; ?>
                <?php if ($show_trash_icon): ?>
                <button class="remove-item text-gray-400 hover:text-red-500 focus:outline-none transition-colors" data-index="${index}">
                  <i class="fas fa-trash-alt text-sm"></i>
                </button>
                <?php endif; ?>
              </div>
            </div>
          `;
        }
      });

      // 🔥 计算合计
      // 🔥 修复：使用 toFixed(2) 避免浮点数精度问题
      const grandTotal = parseFloat((lockedTotal + newTotal).toFixed(2));

      // 🔥 根据模式显示不同的金额统计
      const detailedSummary = document.getElementById('detailed-summary');
      const simpleSummary = document.getElementById('simple-summary');

      if (isViewMode && isViewMode.mode === 'view' && lockedTotal > 0) {
        // ========== 查看模式：显示详细金额（2行）==========
        if (detailedSummary) detailedSummary.classList.remove('hidden');
        if (simpleSummary) simpleSummary.classList.add('hidden');

        // 更新详细金额
        const cartTotalQuantityElem = document.getElementById('cart-total-quantity-detail');
        if (cartTotalQuantityElem) cartTotalQuantityElem.textContent = totalQuantity;
        const newItemBadgeDetail = document.getElementById('new-item-badge-detail');
        if (newItemBadgeDetail) {
          if (printQueueCount > 0) {
            newItemBadgeDetail.textContent = `(${RUIYI_POS_CONFIG.translations?.pendingPrint || '待打印'}${printQueueCount})`;
            newItemBadgeDetail.classList.remove('hidden');
          } else {
            newItemBadgeDetail.classList.add('hidden');
          }
        }

        const cartGrandTotalElem = document.getElementById('cart-grand-total');
        if (cartGrandTotalElem) cartGrandTotalElem.textContent = `€${grandTotal.toFixed(2)}`;

        const newTotalElem = document.getElementById('new-total-amount');
        if (newTotalElem) newTotalElem.textContent = `€${newTotal.toFixed(2)}`;
      } else {
        // ========== 普通模式：显示简化金额（1行）==========
        if (detailedSummary) detailedSummary.classList.add('hidden');
        if (simpleSummary) simpleSummary.classList.remove('hidden');

        const cartTotalQuantityElem = document.getElementById('cart-total-quantity');
        if (cartTotalQuantityElem) cartTotalQuantityElem.textContent = totalQuantity;
        const newItemBadge = document.getElementById('new-item-badge');
        if (newItemBadge) {
          if (printQueueCount > 0) {
            newItemBadge.textContent = `(${RUIYI_POS_CONFIG.translations?.pendingPrint || '待打印'}${printQueueCount})`;
            newItemBadge.classList.remove('hidden');
          } else {
            newItemBadge.classList.add('hidden');
          }
        }

        const cartTotalPriceElem = document.getElementById('cart-total-price');
        if (cartTotalPriceElem) cartTotalPriceElem.textContent = `€${grandTotal.toFixed(2)}`;
      }

      // 🔥 Send cart total to VFD display
      sendVFDDisplay(grandTotal);

      // 🔥 更新折扣显示标识
      updateDiscountBadge();

      // 🔥 【关键修复】实时同步购物车总额到桌位状态（解决桌位卡片金额不同步问题）
      // 只在堂食模式下且有桌位号时同步
      const orderType = sessionStorage.getItem('tipoPedidoSeleccionado');
      const tableNumberForSync = document.getElementById('table-number')?.value.trim();
      if (orderType === 'servir' && tableNumberForSync) {
        try {
          const mesasEstadoSync = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
          // 🔥 提取纯数字桌号（支持任意区域名称前缀）
          const tableNum = resolveGlobalTableNumber(tableNumberForSync);
          const mesaKeySync = `Mesa ${tableNum}`;

          // 🔥 多格式查找：支持 "Mesa X", "Table X", "餐桌 X" 等格式
          let actualMesaKey = mesaKeySync;
          if (!mesasEstadoSync[mesaKeySync]) {
            // 尝试查找其他可能的键名格式
            const possiblePrefixes = ['Mesa', 'Table', '餐桌'];
            for (const prefix of possiblePrefixes) {
              const altKey = `${prefix} ${tableNum}`;
              if (mesasEstadoSync[altKey]) {
                actualMesaKey = altKey;
                break;
              }
              // 也尝试无空格格式
              const altKeyNoSpace = `${prefix}${tableNum}`;
              if (mesasEstadoSync[altKeyNoSpace]) {
                actualMesaKey = altKeyNoSpace;
                break;
              }
            }
          }

          // 只有当桌位已存在状态时才更新（避免为空桌位创建状态）
          // 🔥 【关键修复】如果设置了跳过标志，不同步（自动保存后避免覆盖正确的总额）
          if (mesasEstadoSync[actualMesaKey] && !window._skipRenderCartTableSync) {
            // 🔥 检查金额是否有变化
            const oldTotal = mesasEstadoSync[actualMesaKey].total || 0;
            const totalChanged = Math.abs(oldTotal - grandTotal) > 0.01;

            // 🔥🔥🔥 【2026-01-31 关键修复】过滤掉数量为0的商品
            const cartToSaveFiltered = cart.filter(item => item.quantity > 0);
            // 🔥 实时更新总额和购物车数据
            mesasEstadoSync[actualMesaKey].total = grandTotal;
            mesasEstadoSync[actualMesaKey].cart = JSON.parse(JSON.stringify(cartToSaveFiltered));
            mesasEstadoSync[actualMesaKey].cart_gtn = parseInt(tableNum);
            mesasEstadoSync[actualMesaKey].discount = window.currentDiscountPercent || 0;
            mesasEstadoSync[actualMesaKey]._lastUpdate = Date.now();
            localStorage.setItem('mesas_estado', JSON.stringify(mesasEstadoSync));

            // 🔥 【2026-01-20 修复】金额变化时触发桌位卡片重新渲染
            // 使用防抖避免频繁渲染，延迟300ms
            if (totalChanged && typeof renderizarMesas === 'function') {
              clearTimeout(window._renderCartTableSyncTimeout);
              window._renderCartTableSyncTimeout = setTimeout(() => {
                renderizarMesas('cart-total-sync');
              }, 300);
            }
          } else if (window._skipRenderCartTableSync) {
          }
        } catch (e) {
          console.warn('[renderCart] 桌位状态同步失败:', e);
        }
      }

      // 🔥 结账按钮显示逻辑：始终显示结账按钮
      // 修改：用户要求在给桌位创建订单时也能看到结账按钮，可直接结账
      const checkoutBtn = document.getElementById('checkout-table-btn');
      if (checkoutBtn) {
          // 始终显示结账按钮
          checkoutBtn.classList.remove('hidden');
          checkoutBtn.style.display = 'flex';

          // 如果有桌位号，设置到按钮的data属性
          const tableNumberValue = document.getElementById('table-number')?.value.trim();
          if (tableNumberValue) {
              checkoutBtn.dataset.tableNumber = tableNumberValue;
          }
      }

      // 🔥 保存桌位订单按钮显示逻辑 - 移至updateAllButtonStates统一处理
      // 不在这里单独处理，避免冲突

      // 为新添加的按钮绑定事件
      setTimeout(() => {
        document.querySelectorAll('.decrease-item').forEach(btn => {
          btn.addEventListener('click', function(e) {
            e.stopPropagation(); // 🔥 阻止事件冒泡，避免触发选中
            const index = parseInt(this.getAttribute('data-index'));
            if (cart[index].quantity > 0) {
              cart[index].quantity -= 1;
              // 🔥 同步减少 addedQuantity（厨房打印盒子）
              if ((cart[index].addedQuantity || 0) > 0) {
                cart[index].addedQuantity -= 1;
              }
              renderCart();
              // 🔥 如果是锁定产品，标记购物车已修改，需要保存
              if (cart[index].locked) {
                window.cartModified = true;
                syncCartToMesasEstado();
              }
            }
          });
        });

        document.querySelectorAll('.increase-item').forEach(btn => {
          btn.addEventListener('click', function(e) {
            e.stopPropagation(); // 🔥 阻止事件冒泡，避免触发选中
            const index = parseInt(this.getAttribute('data-index'));
            cart[index].quantity += 1;
            // 🔥 追踪本次新增数量（用于厨房打印）
            cart[index].addedQuantity = (cart[index].addedQuantity || 0) + 1;
            renderCart();
            // 🔥 如果是锁定产品，标记购物车已修改，需要保存
            if (cart[index].locked) {
              window.cartModified = true;
              syncCartToMesasEstado();
            }
          });
        });

        document.querySelectorAll('.remove-item').forEach(btn => {
          btn.addEventListener('click', function(e) {
            e.stopPropagation(); // 🔥 阻止事件冒泡，避免触发选中
            const index = parseInt(this.getAttribute('data-index'));
            // 直接删除商品
            cart.splice(index, 1);
            // 🔥 如果删除的是选中项，清除选中状态
            if (selectedCartItemIndex === index) {
              selectedCartItemIndex = null;
              window.selectedCartItemIndex = null;
            } else if (selectedCartItemIndex > index) {
              // 如果删除的在选中项之前，调整索引
              selectedCartItemIndex--;
              window.selectedCartItemIndex--;
            }
            renderCart();

            // 🔥🔥🔥 关键修复：外卖模式下删除商品后显式保存购物车到localStorage
            // 确保刷新页面后删除的商品不会再出现
            const currentOrderType = sessionStorage.getItem('tipoPedidoSeleccionado');
            const tableNumberInput = document.getElementById('table-number')?.value.trim();
            const isLlevarMode = currentOrderType === 'llevar' && !tableNumberInput;
            if (isLlevarMode && typeof savePosCartToStorage === 'function') {
              // 外卖模式下，显式保存更新后的购物车
              savePosCartToStorage();
              console.log('[购物车保护] ✅ 外卖模式删除商品后，已更新localStorage');
            }

            // 🔥 关键修复：如果购物车已空且在桌位模式，退出桌位模式
            // 🔥 但如果是viewMode（查看已有订单模式），不自动退出，保持桌位状态
            const viewModeData = sessionStorage.getItem('tableViewMode');
            const isInTableMode = viewModeData ? JSON.parse(viewModeData) : null;
            const isViewModeActive = isInTableMode?.mode === 'view';
            if (cart.length === 0 && isInTableMode && isInTableMode.table && !isViewModeActive) {

              // 清除桌位号输入
              const tableNumberInput = document.getElementById('table-number');
              if (tableNumberInput) {
                tableNumberInput.value = '';
                if (typeof updateCurrentTableDisplay === 'function') {
                  updateCurrentTableDisplay('');
                }
              }

              // 更新 mesas_estado - 将桌位设为空闲
              const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
              const tableNumber = isInTableMode.table;
              const tableNumberOnly = String(tableNumber).replace(/^(餐桌|Mesa|Table)\s*/i, '');
              const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
              const possibleKeys = [
                `${tablePrefix} ${tableNumberOnly}`,
                `Mesa ${tableNumberOnly}`,
                `Table ${tableNumberOnly}`,
                `餐桌 ${tableNumberOnly}`,
                tableNumber
              ];

              possibleKeys.forEach(key => {
                if (mesasEstado[key]) {
                  mesasEstado[key].estado = 'libre';
                  mesasEstado[key].cart = [];
                  mesasEstado[key].total = 0;
                  mesasEstado[key].orderId = null;
                  mesasEstado[key].orderIds = [];
                  mesasEstado[key]._hasOfflineChanges = true;
                }
              });
              localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));

              // 清理查看模式状态
              sessionStorage.removeItem('isViewMode');
              sessionStorage.removeItem('tableViewMode');
              sessionStorage.removeItem('tableOrderData');
              sessionStorage.removeItem('tableViewOrderData');

              // 切换到外卖模式
              sessionStorage.setItem('tipoPedidoSeleccionado', 'llevar');

              // 更新订单类型按钮UI
              const takeawayBtn = document.querySelector('[data-type="llevar"]');
              const dineInBtn = document.querySelector('[data-type="servir"]');
              if (takeawayBtn && dineInBtn) {
                takeawayBtn.classList.add('bg-[#f7310f]', 'text-white');
                takeawayBtn.classList.remove('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
                takeawayBtn.disabled = false;
                takeawayBtn.style.opacity = '1';
                takeawayBtn.style.cursor = 'default';

                dineInBtn.classList.remove('bg-[#f7310f]', 'text-white');
                dineInBtn.classList.add('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
              }

              // 隐藏查看模式专用按钮
              const checkoutBtn = document.getElementById('checkout-table-btn');
              const toolboxBtn = document.getElementById('toolbox-toggle-btn');
              if (checkoutBtn) checkoutBtn.classList.add('hidden');
              if (toolboxBtn) toolboxBtn.classList.add('hidden');

              // 更新主按钮和所有按钮状态
              if (typeof updateOrderButtonForType === 'function') {
                updateOrderButtonForType('llevar');
              }

              // 🔥 关键修复：清除桌号后，立即更新预结单按钮和开钱箱按钮布局
              // 确保开钱箱按钮在外卖模式下显示为全宽
              if (typeof updateProformaButtonVisibility === 'function') {
                updateProformaButtonVisibility();
              }

              setTimeout(() => {
                if (typeof updateAllButtonStates === 'function') {
                  updateAllButtonStates();
                }
              }, 100);

              // 显示提示
              Toastify({
                text: `✅ <?php echo ruiyi_translate('Mesa liberada', 'Table cleared', '桌位已释放'); ?>`,
                duration: 2500,
                gravity: "top",
                position: "center",
                style: { background: "#22c55e" }
              }).showToast();

              // 🔥 优化：移除延迟，立即渲染实现秒响应
              // cambiarSeccion内部已经调用renderizarMesas，不需要重复调用
              if (typeof cambiarSeccion === 'function') {
                cambiarSeccion('mesas');
              }
            }
          });
        });

        // 🔥 Inline价格编辑功能 - 移除编辑按钮，直接点击价格编辑
        // 不需要绑定事件，使用onclick属性

        // 🔥 辅助函数：删除商品后清除桌位状态（桌位变为空闲）
        function clearTableStatusOnDelete(tableNumber) {
          if (!tableNumber) return;

          const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
          const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');

          // 提取纯数字部分
          const tableNumberOnly = String(tableNumber).replace(/^(餐桌|Mesa|Table)\s*/i, '');

          // 使用多格式查找函数找到现有的桌位数据和键名
          const existingTableResult = typeof findTableDataByNumber === 'function'
            ? findTableDataByNumber(mesasEstado, tableNumberOnly)
            : { key: null, data: null };

          // 构建可能的键名列表
          const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
          const possibleKeys = [
            existingTableResult.key,
            `${tablePrefix} ${tableNumberOnly}`,
            `Mesa ${tableNumberOnly}`,
            `Table ${tableNumberOnly}`,
            `餐桌 ${tableNumberOnly}`,
            tableNumber
          ].filter(Boolean);

          // 清除 mesas_estado 中的桌位状态
          let mesasUpdated = false;
          possibleKeys.forEach(key => {
            if (mesasEstado[key]) {
              mesasEstado[key].estado = 'libre';
              mesasEstado[key].cart = [];
              mesasEstado[key].total = 0;
              mesasEstado[key].orderId = null;
              mesasEstado[key].orderIds = [];
              mesasEstado[key].timestamp = new Date().toISOString();
              // 🔥 关键修复：清除所有离线相关标志，防止数据累积
              delete mesasEstado[key]._offline;
              delete mesasEstado[key]._offlineNewItems;
              delete mesasEstado[key]._newItemsToSync;
              delete mesasEstado[key]._pendingSync;
              delete mesasEstado[key]._hasOnlineOrder;
              delete mesasEstado[key]._hasOfflineChanges;
              delete mesasEstado[key]._skipAutoUpdate;
              delete mesasEstado[key]._syncing;
              delete mesasEstado[key]._syncStartTime;
              delete mesasEstado[key]._isAddition;
              delete mesasEstado[key]._justSynced;
              delete mesasEstado[key]._syncTimestamp;
              mesasUpdated = true;
              console.log(`[清除桌位] ✅ 已清除桌位 ${key} 的所有离线数据`);
            }
          });

          if (mesasUpdated) {
            localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
          }

          // 清除 carritos_mesas 中的购物车数据
          let carritosUpdated = false;
          possibleKeys.forEach(key => {
            if (carritosGuardados[key]) {
              delete carritosGuardados[key];
              carritosUpdated = true;
            }
          });

          if (carritosUpdated) {
            localStorage.setItem('carritos_mesas', JSON.stringify(carritosGuardados));
          }

          // 触发桌位渲染更新
          if (typeof renderizarMesas === 'function') {
            setTimeout(() => {
              renderizarMesas('after-clear-table-status');
            }, 100);
          }
        }

        // 🔥 锁定商品删除按钮事件处理器 - 直接删除，无确认弹窗
        document.querySelectorAll('.remove-locked-item').forEach(btn => {
          btn.addEventListener('click', async function(e) {
            e.stopPropagation(); // 🔥 阻止事件冒泡，避免触发选中
            const index = parseInt(this.getAttribute('data-index'));
            const item = cart[index];

            // 🔥 保存要删除的item信息，用于后续验证和临时隐藏
            const itemToDelete = {
              orderId: item.orderId,
              itemId: item.itemId,
              productId: item.id
            };

            // 🔥 修复：从查看模式状态获取桌位号，而不是从输入框获取，避免多桌位删除错误
            const viewMode = sessionStorage.getItem('tableViewMode');
            const isViewMode = viewMode ? JSON.parse(viewMode) : null;
            const tableNumber = isViewMode && isViewMode.table ? isViewMode.table : document.getElementById('table-number')?.value.trim();

            // 🔥 离线模式处理：本地删除并存储待同步的删除操作
            if (!navigator.onLine) {

              // 1. 更新 mesas_estado 中的 cart 数据（在删除前先保存完整cart）
              const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');

              // 🔥 关键修复：使用 findTableDataByNumber 多格式查找现有的桌位数据
              // 从 tableNumber 提取纯数字部分（去除所有可能的前缀）
              const tableNumberOnly = tableNumber.replace(/^(餐桌|Mesa|Table)\s*/i, '');
              // 使用多格式查找函数找到现有的桌位数据和键名
              const existingTableResult = findTableDataByNumber(mesasEstado, tableNumberOnly);
              // 如果找到现有键则使用，否则构建新键
              const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
              const mesaKey = existingTableResult.key || `${tablePrefix} ${tableNumberOnly}`;


              if (tableNumber) {
                // 🔥 关键修复：如果 mesas_estado 中没有该桌位，先创建
                if (!mesasEstado[mesaKey]) {
                  mesasEstado[mesaKey] = {
                    estado: 'ocupada',
                    timestamp: new Date().toISOString(),
                    discount: window.currentDiscountPercent || 0, // 🔥 保存折扣
                    _hasOfflineChanges: true
                  };
                }

                // 🔥 关键修复：如果 mesas_estado 中没有 cart 数据，先从当前 cart 创建
                if (!mesasEstado[mesaKey].cart || !Array.isArray(mesasEstado[mesaKey].cart)) {
                  // 🔥🔥🔥 【2026-01-31 关键修复】深拷贝当前购物车（删除前的状态），过滤掉数量为0的商品
                  mesasEstado[mesaKey].cart = JSON.parse(JSON.stringify(cart.filter(item => item.quantity > 0)));
                  mesasEstado[mesaKey].cart_gtn = parseInt(tableNumberOnly);
                }

                // 找到并删除对应的商品
                // 🔥 关键修复：mesas_estado.cart 中的商品可能没有 orderId 和 itemId
                // 优先使用 orderId+itemId+id 完全匹配，如果找不到则使用 id+name 匹配
                let cartIndex = mesasEstado[mesaKey].cart.findIndex(cartItem =>
                  cartItem.orderId === item.orderId &&
                  cartItem.itemId === item.itemId &&
                  cartItem.id === item.id
                );

                // 如果完全匹配失败，尝试用 id + name 匹配（适用于离线创建的订单）
                if (cartIndex === -1) {
                  cartIndex = mesasEstado[mesaKey].cart.findIndex(cartItem =>
                    String(cartItem.id) === String(item.id) &&
                    (cartItem.name === item.name || cartItem.name_es === item.name)
                  );
                }

                // 如果还是找不到，仅用 id 匹配（最后的兜底）
                if (cartIndex === -1) {
                  cartIndex = mesasEstado[mesaKey].cart.findIndex(cartItem =>
                    String(cartItem.id) === String(item.id)
                  );
                }

                if (cartIndex !== -1) {
                  const deletedItem = mesasEstado[mesaKey].cart[cartIndex];
                  mesasEstado[mesaKey].cart.splice(cartIndex, 1);
                } else {
                  console.warn('[删除锁定商品] ⚠️ 未在 mesas_estado.cart 中找到对应商品, item:', item);
                }

                // 更新总金额（含 supplements）
                const newTotal = mesasEstado[mesaKey].cart.reduce((sum, cartItem) => {
                  return sum + (parseFloat(cartItem.customPrice !== undefined && cartItem.customPrice !== null ? cartItem.customPrice : (cartItem.price || 0))) * (cartItem.quantity || 1);
                }, 0);
                mesasEstado[mesaKey].total = newTotal;
                mesasEstado[mesaKey].timestamp = new Date().toISOString();
                mesasEstado[mesaKey]._hasOfflineChanges = true; // 标记有离线更改

                // 🔥 关键修复：如果购物车已空，将桌位状态设为空闲
                if (mesasEstado[mesaKey].cart.length === 0) {
                  mesasEstado[mesaKey].estado = 'libre';
                  mesasEstado[mesaKey].orderId = null;
                  mesasEstado[mesaKey].orderIds = [];
                  // 清除该桌位的 carritos_mesas 数据
                  const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
                  if (carritosGuardados[mesaKey]) {
                    delete carritosGuardados[mesaKey];
                    localStorage.setItem('carritos_mesas', JSON.stringify(carritosGuardados));
                  }
                }

                localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
              }

              // 2. 从购物车中删除该商品
              // 🔥 关键修复：使用属性查找而不是索引，避免多次快速删除时索引错位
              const cartItemIndex = cart.findIndex(cartItem =>
                cartItem.orderId === item.orderId &&
                cartItem.itemId === item.itemId &&
                cartItem.id === item.id
              );
              if (cartItemIndex !== -1) {
                cart.splice(cartItemIndex, 1);
              } else {
                console.warn('[删除锁定商品] ⚠️ 购物车中未找到该商品（可能已被删除）');
              }
              renderCart();

              // 🔥 关键修复：如果购物车已空，退出桌位模式
              if (cart.length === 0) {

                // 清除桌位号输入
                const tableNumberInput = document.getElementById('table-number');
                if (tableNumberInput) {
                  tableNumberInput.value = '';
                  if (typeof updateCurrentTableDisplay === 'function') {
                    updateCurrentTableDisplay('');
                  }
                }

                // 清理查看模式状态
                sessionStorage.removeItem('isViewMode');
                sessionStorage.removeItem('tableViewMode');
                sessionStorage.removeItem('tableOrderData');
                sessionStorage.removeItem('tableViewOrderData');

                // 切换到外卖模式
                sessionStorage.setItem('tipoPedidoSeleccionado', 'llevar');

                // 更新订单类型按钮UI
                const takeawayBtn = document.querySelector('[data-type="llevar"]');
                const dineInBtn = document.querySelector('[data-type="servir"]');
                if (takeawayBtn && dineInBtn) {
                  takeawayBtn.classList.add('bg-[#f7310f]', 'text-white');
                  takeawayBtn.classList.remove('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
                  takeawayBtn.disabled = false;
                  takeawayBtn.style.opacity = '1';
                  takeawayBtn.style.cursor = 'default';

                  dineInBtn.classList.remove('bg-[#f7310f]', 'text-white');
                  dineInBtn.classList.add('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
                }

                // 隐藏查看模式专用按钮
                const checkoutBtn = document.getElementById('checkout-table-btn');
                const toolboxBtn = document.getElementById('toolbox-toggle-btn');
                if (checkoutBtn) checkoutBtn.classList.add('hidden');
                if (toolboxBtn) toolboxBtn.classList.add('hidden');

                // 更新主按钮和所有按钮状态
                if (typeof updateOrderButtonForType === 'function') {
                  updateOrderButtonForType('llevar');
                }

                // 🔥 关键修复：清除桌号后，立即更新预结单按钮和开钱箱按钮布局
                // 确保开钱箱按钮在外卖模式下显示为全宽
                if (typeof updateProformaButtonVisibility === 'function') {
                  updateProformaButtonVisibility();
                }

                setTimeout(() => {
                  if (typeof updateAllButtonStates === 'function') {
                    updateAllButtonStates();
                  }
                }, 100);

                // 显示提示
                Toastify({
                  text: `✅ <?php echo ruiyi_translate('Mesa liberada (sin conexión)', 'Table cleared (offline)', '桌位已释放（离线）'); ?>`,
                  duration: 2500,
                  gravity: "top",
                  position: "center",
                  style: { background: "#22c55e" }
                }).showToast();

                // 更新桌位显示并切换到桌位模块
                if (typeof renderizarMesas === 'function') {
                  setTimeout(() => {
                    renderizarMesas('after-offline-clear-table');
                  }, 300);
                }

                // 切换到桌位模块
                if (typeof cambiarSeccion === 'function') {
                  setTimeout(() => {
                    cambiarSeccion('mesas');
                  }, 500);
                }

                return; // 提前退出，不需要继续后续处理
              }

              // 2.5 🔥 关键修复：同步更新 sessionStorage 中的订单数据（防止重新加载时恢复已删除的商品）
              const tableViewOrderDataStr = sessionStorage.getItem('tableViewOrderData');
              if (tableViewOrderDataStr) {
                try {
                  const tableViewOrderData = JSON.parse(tableViewOrderDataStr);
                  if (tableViewOrderData.orders && Array.isArray(tableViewOrderData.orders)) {
                    // 遍历所有订单，删除对应的商品
                    tableViewOrderData.orders.forEach(order => {
                      if (order.items && Array.isArray(order.items)) {
                        // 🔥 修复：同时检查 item_id 和 order_item_id 字段（不同来源使用不同字段名）
                        const itemIdx = order.items.findIndex(orderItem =>
                          String(orderItem.product_id) === String(item.id) &&
                          (String(orderItem.item_id || orderItem.order_item_id) === String(item.itemId))
                        );
                        if (itemIdx !== -1) {
                          order.items.splice(itemIdx, 1);
                        }
                      }
                    });
                    // 移除空订单
                    tableViewOrderData.orders = tableViewOrderData.orders.filter(order =>
                      order.items && order.items.length > 0
                    );
                    // 🔥 更新订单总额
                    tableViewOrderData.orders.forEach(order => {
                      if (order.items && Array.isArray(order.items)) {
                        order.total = order.items.reduce((sum, orderItem) => {
                          return sum + (parseFloat(orderItem.total) || 0);
                        }, 0);
                      }
                    });
                    sessionStorage.setItem('tableViewOrderData', JSON.stringify(tableViewOrderData));
                  }
                } catch (e) {
                  console.warn('[删除锁定商品] 更新 tableViewOrderData 失败:', e);
                }
              }

              // 2.6 🔥 同步更新 tableOrderData（另一个可能用于加载的存储）
              const tableOrderDataStr = sessionStorage.getItem('tableOrderData');
              if (tableOrderDataStr) {
                try {
                  const tableOrderData = JSON.parse(tableOrderDataStr);
                  if (tableOrderData.orders && Array.isArray(tableOrderData.orders)) {
                    tableOrderData.orders.forEach(order => {
                      if (order.items && Array.isArray(order.items)) {
                        const itemIdx = order.items.findIndex(orderItem =>
                          String(orderItem.product_id) === String(item.id) &&
                          (String(orderItem.item_id || orderItem.order_item_id) === String(item.itemId))
                        );
                        if (itemIdx !== -1) {
                          order.items.splice(itemIdx, 1);
                        }
                      }
                    });
                    tableOrderData.orders = tableOrderData.orders.filter(order =>
                      order.items && order.items.length > 0
                    );
                    tableOrderData.orders.forEach(order => {
                      if (order.items && Array.isArray(order.items)) {
                        order.total = order.items.reduce((sum, orderItem) => {
                          return sum + (parseFloat(orderItem.total) || 0);
                        }, 0);
                      }
                    });
                    sessionStorage.setItem('tableOrderData', JSON.stringify(tableOrderData));
                  }
                } catch (e) {
                  console.warn('[删除锁定商品] 更新 tableOrderData 失败:', e);
                }
              }

              // 3. 存储待同步的删除操作
              const pendingDeletions = JSON.parse(localStorage.getItem('pending_locked_item_deletions') || '[]');
              pendingDeletions.push({
                product_id: item.id,
                table_number: tableNumber,
                quantity: item.quantity,
                order_id: item.orderId || '',
                item_id: item.itemId || '',
                timestamp: new Date().toISOString()
              });
              localStorage.setItem('pending_locked_item_deletions', JSON.stringify(pendingDeletions));

              // 4. 显示成功提示（带离线标记）
              Toastify({
                text: `✅ <?php echo ruiyi_translate('Eliminado (sin conexión)', 'Deleted (offline)', '已删除（离线）'); ?>`,
                duration: 2000,
                gravity: "top",
                position: "center",
                style: { background: "#f59e0b" }
              }).showToast();

              // 5. 更新桌位显示
              if (typeof renderizarMesas === 'function') {
                setTimeout(() => {
                  renderizarMesas('after-offline-delete-locked-item');
                }, 300);
              }

              return; // 离线模式处理完成，退出
            }

            // 🔥🔥🔥 【2026-04-10 关键修复】处理待同步订单的本地删除
            // 当 orderId 以 PENDING_ 或 OFFLINE_ 开头时，服务器还没有该订单/订单项
            // 直接从本地同步队列和购物车中移除，不发送服务器请求
            const _deleteOrderIdStr = item.orderId ? String(item.orderId) : '';
            const _deleteItemIdStr = item.itemId ? String(item.itemId) : '';
            const _isPendingOrder = _deleteOrderIdStr.startsWith('PENDING_') || _deleteOrderIdStr.startsWith('OFFLINE_');
            const _isFakeItemId = _deleteItemIdStr.startsWith('offline_item_') || !_deleteItemIdStr || _deleteItemIdStr === '0';

            if (_isPendingOrder || _isFakeItemId) {
              // 如果同步正在进行中，提示用户等待（防止删除后同步仍创建该商品）
              if (window._syncTableOrderInProgress) {
                Toastify({
                  text: `⏳ <?php echo ruiyi_translate('Sincronizando, espera...', 'Syncing, please wait...', '同步中，请稍候...'); ?>`,
                  duration: 2000,
                  gravity: "top",
                  position: "center",
                  style: { background: "#f59e0b" }
                }).showToast();
                return;
              }

              console.log('[删除锁定商品] 🔄 待同步订单本地删除:', _deleteOrderIdStr, 'itemId:', _deleteItemIdStr);

              // 1. 更新 mesas_estado：从 cart、_newItemsToSync、_offlineNewItems 中移除
              const _delMesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
              const _delTableNumOnly = tableNumber.replace(/^(餐桌|Mesa|Table)\s*/i, '');
              const _delTableResult = findTableDataByNumber(_delMesasEstado, _delTableNumOnly);
              const _delTablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
              const _delMesaKey = _delTableResult.key || `${_delTablePrefix} ${_delTableNumOnly}`;

              if (_delMesasEstado[_delMesaKey]) {
                const _matchItem = (c) => String(c.id) === String(item.id) &&
                    (c.name === item.name || c.name_es === item.name) &&
                    Math.abs(parseFloat(c.customPrice ?? c.price ?? 0) - parseFloat(item.customPrice ?? item.price ?? 0)) < 0.01;

                // 从 cart 中移除
                if (Array.isArray(_delMesasEstado[_delMesaKey].cart)) {
                  const _cidx = _delMesasEstado[_delMesaKey].cart.findIndex(_matchItem);
                  if (_cidx !== -1) _delMesasEstado[_delMesaKey].cart.splice(_cidx, 1);
                }

                // 从 _newItemsToSync 中移除
                if (Array.isArray(_delMesasEstado[_delMesaKey]._newItemsToSync)) {
                  _delMesasEstado[_delMesaKey]._newItemsToSync = _delMesasEstado[_delMesaKey]._newItemsToSync.filter(c => !_matchItem(c));
                  if (_delMesasEstado[_delMesaKey]._newItemsToSync.length === 0) delete _delMesasEstado[_delMesaKey]._newItemsToSync;
                }

                // 从 _offlineNewItems 中移除
                if (Array.isArray(_delMesasEstado[_delMesaKey]._offlineNewItems)) {
                  _delMesasEstado[_delMesaKey]._offlineNewItems = _delMesasEstado[_delMesaKey]._offlineNewItems.filter(c => !_matchItem(c));
                  if (_delMesasEstado[_delMesaKey]._offlineNewItems.length === 0) delete _delMesasEstado[_delMesaKey]._offlineNewItems;
                }

                // 更新总金额
                if (Array.isArray(_delMesasEstado[_delMesaKey].cart)) {
                  _delMesasEstado[_delMesaKey].total = _delMesasEstado[_delMesaKey].cart.reduce((sum, c) => {
                    const p = parseFloat(c.customPrice !== undefined ? c.customPrice : c.price) || 0;
                    return sum + p * (c.quantity || 1);
                  }, 0);
                }

                // 如果购物车空了，清除桌位状态
                if (!_delMesasEstado[_delMesaKey].cart || _delMesasEstado[_delMesaKey].cart.length === 0) {
                  _delMesasEstado[_delMesaKey].estado = 'libre';
                  _delMesasEstado[_delMesaKey].orderId = null;
                  _delMesasEstado[_delMesaKey]._pendingSync = false;
                  delete _delMesasEstado[_delMesaKey]._newItemsToSync;
                  delete _delMesasEstado[_delMesaKey]._offlineNewItems;
                }

                localStorage.setItem('mesas_estado', JSON.stringify(_delMesasEstado));
              }

              // 2. 从购物车中删除
              cart.splice(index, 1);
              renderCart();

              // 3. 如果购物车空了，退出桌位模式
              if (cart.length === 0) {
                const tableNumberInput = document.getElementById('table-number');
                if (tableNumberInput) {
                  tableNumberInput.value = '';
                  if (typeof updateCurrentTableDisplay === 'function') updateCurrentTableDisplay('');
                }
                sessionStorage.removeItem('isViewMode');
                sessionStorage.removeItem('tableViewMode');
                sessionStorage.removeItem('tableOrderData');
                sessionStorage.removeItem('tableViewOrderData');
                sessionStorage.setItem('tipoPedidoSeleccionado', 'llevar');
                if (typeof updateOrderButtonForType === 'function') updateOrderButtonForType('llevar');
                if (typeof updateProformaButtonVisibility === 'function') updateProformaButtonVisibility();
                setTimeout(() => { if (typeof updateAllButtonStates === 'function') updateAllButtonStates(); }, 100);
              }

              // 4. 显示成功提示
              Toastify({
                text: `✅ <?php echo ruiyi_translate('Eliminado', 'Deleted', '已删除'); ?>`,
                duration: 1500,
                gravity: "top",
                position: "center",
                style: { background: "#10b981" }
              }).showToast();

              // 5. 更新桌位显示
              if (typeof renderizarMesas === 'function') {
                setTimeout(() => renderizarMesas('after-pending-delete'), 300);
              }

              return; // 本地删除完成，退出
            }

            // 🔥🔥🔥 在线模式：实时同步删除（Synchronous Delete）
            // 先等待服务器确认删除成功，再更新UI（更安全，避免竞态条件）

            // ========== 第0步：显示删除中提示，禁用删除按钮 ==========
            const deleteBtn = e.target.closest('.delete-locked-item-btn');
            if (deleteBtn) {
              deleteBtn.disabled = true;
              deleteBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';
            }

            // 🔥🔥🔥 关键：设置删除同步锁，防止并发删除
            if (window._deletingLockedItem) {
              Toastify({
                text: `⏳ <?php echo ruiyi_translate('Espera...', 'Please wait...', '请稍候...'); ?>`,
                duration: 1500,
                gravity: "top",
                position: "center",
                style: { background: "#f59e0b" }
              }).showToast();
              if (deleteBtn) {
                deleteBtn.disabled = false;
                deleteBtn.innerHTML = '<i class="fas fa-trash-alt text-red-500"></i>';
              }
              return;
            }
            window._deletingLockedItem = true;

            try {
              // ========== 第1步：先调用服务器删除 ==========
              const ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url("admin-ajax.php")); ?>';
              const ajaxNonce = window.RUIYI_POS?.nonce || '<?php echo esc_js($ajax_nonce); ?>';

              const formData = new URLSearchParams({
                action: 'ruiyi_pos_delete_locked_item',
                product_id: item.id,
                table_number: tableNumber,
                quantity: item.quantity,
                order_id: item.orderId || '',
                item_id: item.itemId || '',
                nonce: ajaxNonce
              });

              const response = await fetch(ajaxUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: formData
              });

              if (!response.ok) {
                throw new Error(`HTTP ${response.status}`);
              }

              const data = await response.json();

              // 检查删除是否成功（或商品已不存在）
              const errorMsg = data.data?.message || '';
              const isAlreadyDeleted = errorMsg.includes('not found') || errorMsg.includes('no existe') ||
                                       errorMsg.includes('已完成') || errorMsg.includes('不存在');

              if (!data.success && !isAlreadyDeleted) {
                throw new Error(errorMsg || '删除失败');
              }

              // ========== 第2步：服务器确认后，更新本地UI ==========
              cart.splice(index, 1);
              renderCart();

              // 🔥🔥🔥 关键修复：标记购物车已修改
              window.cartModified = true;

              // ========== 第3步：更新 mesas_estado ==========
              const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
              const tableNumberOnly = tableNumber.replace(/^(餐桌|Mesa|Table)\s*/i, '');
              const existingTableResult = findTableDataByNumber(mesasEstado, tableNumberOnly);
              const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
              const mesaKey = existingTableResult.key || `${tablePrefix} ${tableNumberOnly}`;

            if (mesasEstado[mesaKey]) {
              // 如果 mesas_estado 中有 cart 数据，更新它
              if (mesasEstado[mesaKey].cart && Array.isArray(mesasEstado[mesaKey].cart)) {
                // 查找并删除对应的商品
                let cartIndex = mesasEstado[mesaKey].cart.findIndex(cartItem =>
                  cartItem.orderId === item.orderId &&
                  cartItem.itemId === item.itemId &&
                  cartItem.id === item.id
                );

                if (cartIndex === -1) {
                  cartIndex = mesasEstado[mesaKey].cart.findIndex(cartItem =>
                    String(cartItem.id) === String(item.id) &&
                    (cartItem.name === item.name || cartItem.name_es === item.name)
                  );
                }

                if (cartIndex === -1) {
                  cartIndex = mesasEstado[mesaKey].cart.findIndex(cartItem =>
                    String(cartItem.id) === String(item.id)
                  );
                }

                if (cartIndex !== -1) {
                  mesasEstado[mesaKey].cart.splice(cartIndex, 1);
                }

                // 更新总金额
                const newTotal = mesasEstado[mesaKey].cart.reduce((sum, cartItem) => {
                  const price = parseFloat(cartItem.customPrice !== undefined ? cartItem.customPrice : cartItem.price) || 0;
                  return sum + price * (cartItem.quantity || 1);
                }, 0);
                mesasEstado[mesaKey].total = newTotal;
                mesasEstado[mesaKey].timestamp = new Date().toISOString();
                mesasEstado[mesaKey]._pendingServerSync = true; // 标记需要服务器同步
              }

              // 🔥 检查是否所有锁定产品都已删除（桌位应该清空）
              const remainingLockedItems = cart.filter(cartItem => cartItem.locked);
              if (remainingLockedItems.length === 0) {

                // 更新桌位状态为空闲
                mesasEstado[mesaKey].estado = 'libre';
                mesasEstado[mesaKey].orderId = null;
                mesasEstado[mesaKey].orderIds = [];
                mesasEstado[mesaKey].cart = [];
                mesasEstado[mesaKey].total = 0;

                localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));

                // 清除该桌位的 carritos_mesas 数据
                const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
                if (carritosGuardados[mesaKey]) {
                  delete carritosGuardados[mesaKey];
                  localStorage.setItem('carritos_mesas', JSON.stringify(carritosGuardados));
                }

                // 清除购物车
                cart = [];
                renderCart();

                // 清除桌位号
                const tableNumberInput = document.getElementById('table-number');
                if (tableNumberInput) {
                  tableNumberInput.value = '';
                  updateCurrentTableDisplay('');
                }

                // 清理查看模式状态
                sessionStorage.removeItem('isViewMode');
                sessionStorage.removeItem('tableViewMode');
                sessionStorage.removeItem('tableOrderData');
                sessionStorage.removeItem('tableViewOrderData');

                // 切换到外卖模式
                sessionStorage.setItem('tipoPedidoSeleccionado', 'llevar');

                // 更新订单类型按钮UI
                const takeawayBtn = document.querySelector('[data-type="llevar"]');
                const dineInBtn = document.querySelector('[data-type="servir"]');
                if (takeawayBtn && dineInBtn) {
                  takeawayBtn.classList.add('bg-[#f7310f]', 'text-white');
                  takeawayBtn.classList.remove('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
                  takeawayBtn.disabled = false;
                  takeawayBtn.style.opacity = '1';
                  takeawayBtn.style.cursor = 'default';

                  dineInBtn.classList.remove('bg-[#f7310f]', 'text-white');
                  dineInBtn.classList.add('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
                }

                // 隐藏查看模式专用按钮
                const checkoutBtn = document.getElementById('checkout-table-btn');
                const toolboxBtn = document.getElementById('toolbox-toggle-btn');
                if (checkoutBtn) checkoutBtn.classList.add('hidden');
                if (toolboxBtn) toolboxBtn.classList.add('hidden');

                // 更新主按钮和所有按钮状态
                if (typeof updateOrderButtonForType === 'function') {
                  updateOrderButtonForType('llevar');
                }

                if (typeof updateProformaButtonVisibility === 'function') {
                  updateProformaButtonVisibility();
                }

                setTimeout(() => {
                  if (typeof updateAllButtonStates === 'function') {
                    updateAllButtonStates();
                  }
                }, 100);
              } else {
                localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
              }
            }

            // ========== 第3步：更新 sessionStorage 中的订单数据 ==========
            const tableViewOrderDataStr = sessionStorage.getItem('tableViewOrderData');
            if (tableViewOrderDataStr) {
              try {
                const tableViewOrderData = JSON.parse(tableViewOrderDataStr);
                if (tableViewOrderData.orders && Array.isArray(tableViewOrderData.orders)) {
                  tableViewOrderData.orders.forEach(order => {
                    if (order.items && Array.isArray(order.items)) {
                      const itemIdx = order.items.findIndex(orderItem =>
                        String(orderItem.product_id) === String(item.id) &&
                        (String(orderItem.item_id || orderItem.order_item_id) === String(item.itemId))
                      );
                      if (itemIdx !== -1) {
                        order.items.splice(itemIdx, 1);
                      }
                    }
                  });
                  tableViewOrderData.orders = tableViewOrderData.orders.filter(order =>
                    order.items && order.items.length > 0
                  );
                  tableViewOrderData.orders.forEach(order => {
                    if (order.items && Array.isArray(order.items)) {
                      order.total = order.items.reduce((sum, orderItem) => {
                        return sum + (parseFloat(orderItem.total) || 0);
                      }, 0);
                    }
                  });
                  sessionStorage.setItem('tableViewOrderData', JSON.stringify(tableViewOrderData));
                }
              } catch (e) {
                console.warn('[删除锁定商品] 更新 tableViewOrderData 失败:', e);
              }
            }

            const tableOrderDataStr = sessionStorage.getItem('tableOrderData');
            if (tableOrderDataStr) {
              try {
                const tableOrderData = JSON.parse(tableOrderDataStr);
                if (tableOrderData.orders && Array.isArray(tableOrderData.orders)) {
                  tableOrderData.orders.forEach(order => {
                    if (order.items && Array.isArray(order.items)) {
                      const itemIdx = order.items.findIndex(orderItem =>
                        String(orderItem.product_id) === String(item.id) &&
                        (String(orderItem.item_id || orderItem.order_item_id) === String(item.itemId))
                      );
                      if (itemIdx !== -1) {
                        order.items.splice(itemIdx, 1);
                      }
                    }
                  });
                  tableOrderData.orders = tableOrderData.orders.filter(order =>
                    order.items && order.items.length > 0
                  );
                  tableOrderData.orders.forEach(order => {
                    if (order.items && Array.isArray(order.items)) {
                      order.total = order.items.reduce((sum, orderItem) => {
                        return sum + (parseFloat(orderItem.total) || 0);
                      }, 0);
                    }
                  });
                  sessionStorage.setItem('tableOrderData', JSON.stringify(tableOrderData));
                }
              } catch (e) {
                console.warn('[删除锁定商品] 更新 tableOrderData 失败:', e);
              }
            }

            // ========== 第7步：显示成功提示 ==========
            Toastify({
              text: `✅ <?php echo ruiyi_translate('Eliminado', 'Deleted', '已删除'); ?>`,
              duration: 1500,
              gravity: "top",
              position: "center",
              style: { background: "#10b981" }
            }).showToast();

            // ========== 第8步：更新桌位显示 ==========
            if (typeof renderizarMesas === 'function') {
              setTimeout(() => {
                renderizarMesas('after-sync-delete');
              }, 300);
            }

            // ========== 第9步：刷新桌位状态 ==========
            if (typeof fetchAndUpdateTableStatuses === 'function') {
              fetchAndUpdateTableStatuses();
            }

            } catch (deleteError) {
              // ========== 删除失败处理 ==========
              console.error('[删除锁定商品] ❌ 删除失败:', deleteError);

              Toastify({
                text: `❌ <?php echo ruiyi_translate('Error al eliminar', 'Delete failed', '删除失败'); ?>: ${deleteError.message}`,
                duration: 3000,
                gravity: "top",
                position: "center",
                style: { background: "#ef4444" }
              }).showToast();

              // 恢复删除按钮
              if (deleteBtn) {
                deleteBtn.disabled = false;
                deleteBtn.innerHTML = '<i class="fas fa-trash-alt text-red-500"></i>';
              }
            } finally {
              // ========== 释放删除锁 ==========
              window._deletingLockedItem = false;

              // 恢复删除按钮（如果还没恢复）
              if (deleteBtn && deleteBtn.disabled) {
                deleteBtn.disabled = false;
                deleteBtn.innerHTML = '<i class="fas fa-trash-alt text-red-500"></i>';
              }
            }

          });
        });
      }, 0);

      // 🔥🔥🔥 关键修复：只在明确需要时才滚动到底部
      // 解决问题：修改数量时滚动条不应该移动
      if (scrollToBottom) {
        setTimeout(() => {
          const cartItemsContainer = document.getElementById('cart-items');
          if (cartItemsContainer && cart.length > 0) {
            cartItemsContainer.scrollTop = cartItemsContainer.scrollHeight;
          }
        }, 100);
      }

      // 🔥 购物车渲染完成后保存到localStorage（非桌位模式）
      savePosCartToStorage();
    }

    // 🔥 渲染桌位订单历史列表（显示购物车中的锁定产品）
    function renderTableOrders() {
      const tableOrdersContent = document.getElementById('table-orders-content');
      const tableOrdersCount = document.getElementById('table-orders-count');
      const tableOrdersToggle = document.getElementById('table-orders-toggle');
      const tableOrdersChevron = document.getElementById('table-orders-chevron');

      if (!tableOrdersContent || !tableOrdersCount) return;

      // 🔥 从购物车中获取所有锁定的产品
      const lockedProducts = cart.filter(item => item.locked);

      if (lockedProducts.length === 0) {
        tableOrdersCount.textContent = '0';
        tableOrdersContent.innerHTML = '<div class="text-center text-gray-500 text-sm py-4"><?php echo ruiyi_translate("No hay productos ordenados", "No ordered products", "暂无已下单产品"); ?></div>';
        return;
      }

      // 更新订单产品数量徽章（显示锁定产品的数量）
      const totalQuantity = lockedProducts.reduce((sum, item) => sum + item.quantity, 0);
      tableOrdersCount.textContent = totalQuantity;

      // 计算锁定产品的总金额（含 supplements）
      const totalAmount = lockedProducts.reduce((sum, item) => {
        return sum + ((parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0))) * item.quantity);
      }, 0);

      // 🔥 构建产品列表HTML（直接显示购物车中的锁定产品）
      let ordersHtml = `
        <!-- 汇总信息卡片 -->
        <div class="bg-gradient-to-r from-blue-50 to-indigo-50 border border-blue-200 rounded-lg p-3 mb-2">
          <div class="flex justify-between items-center">
            <div>
              <span class="text-sm font-semibold text-blue-800">
                <i class="fas fa-utensils mr-1"></i>
                <?php echo ruiyi_translate('Productos ordenados', 'Ordered Products', '已下单产品'); ?>: ${lockedProducts.length}
              </span>
            </div>
            <div>
              <span class="text-lg font-bold text-primary">€${totalAmount.toFixed(2)}</span>
            </div>
          </div>
        </div>

        <!-- 产品列表 -->
        <div class="space-y-1.5">
          ${lockedProducts.map(product => `
            <div class="bg-white border border-blue-100 rounded-lg p-2.5 hover:bg-blue-50 transition-colors">
              <div class="flex justify-between items-center">
                <div class="flex-1 min-w-0">
                  <div class="flex items-center mb-1">
                    <i class="fas fa-lock text-blue-500 text-xs mr-1.5"></i>
                    <p class="font-medium text-gray-800 text-sm">${product.name}</p>
                  </div>
                  <div class="flex items-center text-xs text-gray-500">
                    <span>€${parseFloat(product.price).toFixed(2)} × ${product.quantity}</span>
                    ${product.orderId ? `<span class="ml-2 text-blue-600"><i class="fas fa-receipt mr-0.5"></i>#${product.orderId}</span>` : ''}
                  </div>
                </div>
                <div class="text-right ml-2">
                  <p class="font-bold text-primary text-sm">€${(product.price * product.quantity).toFixed(2)}</p>
                </div>
              </div>
            </div>
          `).join('')}
        </div>
      `;

      tableOrdersContent.innerHTML = ordersHtml;

      // 🔥 添加折叠/展开功能
      if (tableOrdersToggle && !tableOrdersToggle.hasAttribute('data-listener')) {
        tableOrdersToggle.setAttribute('data-listener', 'true');
        tableOrdersToggle.addEventListener('click', function() {
          tableOrdersContent.classList.toggle('hidden');
          if (tableOrdersChevron) {
            tableOrdersChevron.classList.toggle('rotate-180');
          }
        });
      }

    }
    // 🔥 导出renderCart到全局，供外部模块调用
    window.renderCart = renderCart;

    // 🔥 Inline价格编辑函数 - 直接点击价格编辑
    function editPriceInline(index) {
      const item = cart[index];
      if (!item) return;

      // 获取价格元素
      const priceElement = document.querySelector(`.item-unit-price[data-index="${index}"]`);
      if (!priceElement) return;

      // 获取当前价格
      const currentPrice = item.customPrice !== undefined ? item.customPrice : item.price;

      // 保存原始HTML和值（用于取消）
      const originalHTML = priceElement.innerHTML;
      const originalPrice = currentPrice;

      // 创建输入框
      const input = document.createElement('input');
      input.type = 'number';
      input.step = '0.01';
      input.min = '0';
      input.value = currentPrice.toFixed(2);
      input.className = 'w-16 px-1 py-0.5 text-sm font-semibold text-center border-2 border-blue-500 rounded focus:outline-none focus:border-blue-600';
      input.style.cssText = 'width: 60px;';

      // 替换为输入框
      priceElement.innerHTML = '';
      priceElement.appendChild(input);
      priceElement.style.cursor = 'default';

      // 立即聚焦并选中
      input.focus();
      input.select();

      // 验证函数
      function validateAndSave() {
        const newPrice = parseFloat(input.value);

        if (isNaN(newPrice) || newPrice < 0) {
          // 验证失败：红色边框
          input.classList.remove('border-blue-500', 'border-blue-600');
          input.classList.add('border-red-500');
          input.focus();
          return false;
        }

        // 保存新价格
        cart[index].customPrice = newPrice;

        // 🔥🔥🔥 关键修复：设置购物车修改标记，触发保存订单时同步到服务器
        if (cart[index].locked) {
          window.cartModified = true;
          console.log('[editPriceInline] ✅ 锁定产品价格已修改，设置cartModified=true');
        }

        // 恢复显示
        priceElement.innerHTML = `${newPrice.toFixed(2)}€`;
        priceElement.style.cursor = 'pointer';

        // 重新渲染购物车以更新总额
        renderCart();

        // 显示成功提示
        Toastify({
          text: `✏️ <?php echo ruiyi_translate('Precio actualizado', 'Price updated', '价格已更新'); ?>: €${newPrice.toFixed(2)}`,
          duration: 1500,
          gravity: "top",
          position: "center",
          style: { background: "#4CAF50" }
        }).showToast();

        return true;
      }

      // 取消函数
      function cancel() {
        priceElement.innerHTML = originalHTML;
        priceElement.style.cursor = 'pointer';
      }

      // Enter键保存
      input.addEventListener('keydown', function(e) {
        if (e.key === 'Enter') {
          e.preventDefault();
          validateAndSave();
        } else if (e.key === 'Escape') {
          e.preventDefault();
          cancel();
        }
      });

      // 失去焦点保存
      input.addEventListener('blur', function() {
        // 短暂延迟，防止与Enter事件冲突
        setTimeout(() => {
          if (document.activeElement !== input) {
            validateAndSave();
          }
        }, 100);
      });

      // 只允许数字和小数点
      input.addEventListener('input', function(e) {
        // 移除红色边框（用户正在修正）
        if (this.classList.contains('border-red-500')) {
          this.classList.remove('border-red-500');
          this.classList.add('border-blue-500');
        }
      });
    }

    // 🔥🔥🔥 点击编辑商品名称（内联编辑）- 支持锁定和非锁定产品
    function editNameInline(index) {
      const item = cart[index];
      if (!item) return;

      // 获取名称元素
      const nameElement = document.querySelector(`.item-name[data-index="${index}"]`);
      if (!nameElement) return;

      // 获取当前名称
      const currentName = item.customName || item.name;

      // 保存原始HTML和值（用于取消）
      const originalHTML = nameElement.innerHTML;
      const originalName = currentName;

      // 创建输入框
      const input = document.createElement('input');
      input.type = 'text';
      input.value = currentName;
      input.className = 'w-full px-2 py-1 text-sm font-medium border-2 border-blue-500 rounded focus:outline-none focus:border-blue-600';
      input.style.cssText = 'min-width: 120px; max-width: 200px;';

      // 替换为输入框
      nameElement.innerHTML = '';
      nameElement.appendChild(input);
      nameElement.style.cursor = 'default';

      // 立即聚焦并选中
      input.focus();
      input.select();

      // 验证函数
      function validateAndSave() {
        const newName = input.value.trim();

        if (!newName) {
          // 验证失败：红色边框
          input.classList.remove('border-blue-500', 'border-blue-600');
          input.classList.add('border-red-500');
          input.focus();
          return false;
        }

        // 保存新名称
        cart[index].customName = newName;
        cart[index].name = newName; // 同时更新显示名称

        // 🔥🔥🔥 关键修复：设置购物车修改标记，触发保存订单时同步到服务器
        if (cart[index].locked) {
          window.cartModified = true;
          console.log('[editNameInline] ✅ 锁定产品名称已修改，设置cartModified=true');
        }

        // 恢复显示
        nameElement.innerHTML = newName;
        nameElement.style.cursor = 'pointer';

        // 重新渲染购物车
        renderCart();

        // 显示成功提示
        Toastify({
          text: `✏️ <?php echo ruiyi_translate('Nombre actualizado', 'Name updated', '名称已更新'); ?>`,
          duration: 1500,
          gravity: "top",
          position: "center",
          style: { background: "#4CAF50" }
        }).showToast();

        return true;
      }

      // 取消函数
      function cancel() {
        nameElement.innerHTML = originalHTML;
        nameElement.style.cursor = 'pointer';
      }

      // Enter键保存
      input.addEventListener('keydown', function(e) {
        if (e.key === 'Enter') {
          e.preventDefault();
          validateAndSave();
        } else if (e.key === 'Escape') {
          e.preventDefault();
          cancel();
        }
      });

      // 失去焦点保存
      input.addEventListener('blur', function() {
        // 短暂延迟，防止与Enter事件冲突
        setTimeout(() => {
          if (document.activeElement !== input) {
            validateAndSave();
          }
        }, 100);
      });

      // 移除红色边框（用户正在修正）
      input.addEventListener('input', function(e) {
        if (this.classList.contains('border-red-500')) {
          this.classList.remove('border-red-500');
          this.classList.add('border-blue-500');
        }
      });
    }
    window.editNameInline = editNameInline;

    // 🔥 点击编辑商品数量（内联编辑）
    function editQuantityInline(index) {
      const item = cart[index];
      if (!item) return;

      // 获取数量显示元素
      const quantityElements = document.querySelectorAll(`.quantity-display[data-index="${index}"]`);
      if (!quantityElements || quantityElements.length === 0) return;

      const quantityElement = quantityElements[0]; // 使用第一个匹配的元素

      // 获取当前数量
      const currentQuantity = item.quantity;

      // 保存原始HTML（用于取消）
      const originalHTML = quantityElement.innerHTML;

      // 创建输入框
      const input = document.createElement('input');
      input.type = 'number';
      input.step = '1';
      input.min = '0';
      input.max = '999';
      input.value = currentQuantity;
      input.className = 'w-full px-2 py-1 text-base font-bold text-center border-2 border-blue-500 rounded focus:outline-none focus:border-blue-600';
      input.style.cssText = 'width: 48px; font-size: 16px;';

      // 替换为输入框
      quantityElement.innerHTML = '';
      quantityElement.appendChild(input);
      quantityElement.style.cursor = 'default';

      // 立即聚焦并选中
      input.focus();
      input.select();

      // 验证并保存函数
      function validateAndSave() {
        const newQuantity = parseInt(input.value);

        if (isNaN(newQuantity) || newQuantity < 0) {
          // 验证失败：红色边框
          input.classList.remove('border-blue-500', 'border-blue-600');
          input.classList.add('border-red-500');
          input.focus();
          return false;
        }

        // 保存新数量
        const oldQuantity = cart[index].quantity;
        cart[index].quantity = newQuantity;

        // 🔥 同步调整 addedQuantity（厨房打印盒子）
        const quantityDiff = newQuantity - oldQuantity;
        if (quantityDiff < 0 && (cart[index].addedQuantity || 0) > 0) {
          cart[index].addedQuantity = Math.max(0, (cart[index].addedQuantity || 0) + quantityDiff);
        } else if (quantityDiff > 0) {
          cart[index].addedQuantity = (cart[index].addedQuantity || 0) + quantityDiff;
        }

        // 恢复显示
        quantityElement.innerHTML = newQuantity;
        quantityElement.style.cursor = 'pointer';

        // 重新渲染购物车以更新总额
        renderCart();

        // 显示成功提示
        Toastify({
          text: `✏️ <?php echo ruiyi_translate('Cantidad actualizada', 'Quantity updated', '数量已更新'); ?>: ${newQuantity}`,
          duration: 1500,
          gravity: "top",
          position: "center",
          style: { background: "#4CAF50" }
        }).showToast();

        return true;
      }

      // 取消函数
      function cancel() {
        quantityElement.innerHTML = originalHTML;
        quantityElement.style.cursor = 'pointer';
      }

      // Enter键保存
      input.addEventListener('keydown', function(e) {
        if (e.key === 'Enter') {
          e.preventDefault();
          validateAndSave();
        } else if (e.key === 'Escape') {
          e.preventDefault();
          cancel();
        }
      });

      // 失去焦点保存
      input.addEventListener('blur', function() {
        // 短暂延迟，防止与Enter事件冲突
        setTimeout(() => {
          if (document.activeElement !== input) {
            validateAndSave();
          }
        }, 100);
      });

      // 只允许整数
      input.addEventListener('input', function(e) {
        // 移除红色边框（用户正在修正）
        if (this.classList.contains('border-red-500')) {
          this.classList.remove('border-red-500');
          this.classList.add('border-blue-500');
        }

        // 移除小数点和非数字字符
        this.value = this.value.replace(/[^\d]/g, '');
      });
    }
    // 🔥 导出编辑函数到全局
    window.editPriceInline = editPriceInline;
    window.editQuantityInline = editQuantityInline;


    // Cargar carrito de una mesa
    function cargarCarritoMesa(mesa) {
      const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
      if (carritosGuardados[mesa]) {
        const carritoGuardado = carritosGuardados[mesa];
        cart = carritoGuardado.carrito;
        
        
        // 恢复订单类型
        if (carritoGuardado.order_type) {
          sessionStorage.setItem('tipoPedidoSeleccionado', carritoGuardado.order_type);
          
          // 更新UI上的订单类型按钮状态
          const orderTypeButtons = document.querySelectorAll('.order-type');
          orderTypeButtons.forEach(btn => {
            if (btn.getAttribute('data-type') === carritoGuardado.order_type) {
              btn.classList.add('bg-[#f7310f]', 'text-white');
              btn.classList.remove('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
            } else {
              btn.classList.remove('bg-[#f7310f]', 'text-white');
              btn.classList.add('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
            }
          });
        }

        renderCart();

        // 手动触发按钮更新
        const currentOrderType = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir';
        if (typeof updateOrderButtonForType === 'function') {
          updateOrderButtonForType(currentOrderType);
        }

        return true;
      }
      return false;
    }
    
    // Borrar carrito de una mesa
    function borrarCarritoMesa(mesa) {
      const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
      delete carritosGuardados[mesa];
      localStorage.setItem('carritos_mesas', JSON.stringify(carritosGuardados));
    }
    
    // Guardar carrito temporal
    function guardarCarritoEnLocal() {
      const mesa = document.getElementById('table-number')?.value.trim() || window.RUIYI_TRANS.noTable;
      const descuento = 0; // Discount functionality removed
      const pedidoTemporal = {
        mesa,
        descuento,
        carrito: cart,
        fecha: new Date().toISOString()
      };
      localStorage.setItem('pedido_temporal', JSON.stringify(pedidoTemporal));

      Toastify({
        text: `🧾 <?php echo ruiyi_translate("Carrito guardado como borrador", "Cart saved as draft", "购物车已保存为草稿"); ?>`,
        duration: 2000,
        gravity: "top",
        position: "center",
        style: { background: "#f7310f" },
      }).showToast();
    }
    
    // Borrar carrito temporal
    function borrarPedidoTemporal() {
      localStorage.removeItem('pedido_temporal');
    }

    // 🔥 检测是否有未保存的桌位订单
    function hasUnsavedTableOrder() {
      const orderType = sessionStorage.getItem('tipoPedidoSeleccionado');
      const tableNumber = document.getElementById('table-number')?.value.trim();
      const viewMode = sessionStorage.getItem('tableViewMode');
      const isViewMode = viewMode ? JSON.parse(viewMode) : null;

      // 🔥 修复：包括查看模式下的追加订单
      // 条件：堂食订单 + 有桌位号 + 购物车有未锁定且数量>0的商品
      // 注意：不再排除查看模式，因为查看模式下也可以追加产品
      const hasUnlockedItems = cart.length > 0 && cart.some(item => !item.locked && item.quantity > 0);

      // 🔥🔥🔥 关键修复：也检查锁定产品是否被修改
      // window.cartModified 在修改锁定产品数量时会被设置为 true
      const hasModifiedLockedItems = window.cartModified === true;

      return orderType === 'servir' &&
             tableNumber &&
             (hasUnlockedItems || hasModifiedLockedItems);
    }

    // 🔥🔥🔥 【2026-01-20 完全重写】静默自动保存桌位订单
    // 与手动保存按钮流程完全一致：先立即更新本地状态，后台异步同步服务器
    // 这样切换模块时不会有延迟
    async function autoSaveTableOrder(forceOptions = {}) {
      // 🔥【2026-04-07】支持 force 参数：用户显式触发的保存（结账/预结单）必须绕过 3 秒去抖
      // 兼容旧调用（无参或传字符串/布尔）：默认 force=false
      const _forceFlag = (typeof forceOptions === 'object' && forceOptions !== null)
        ? !!forceOptions.force
        : false;

      // 🔥🔥🔥【2026-04-07 关键修复】force 模式下，等待 in-flight sync 完成
      // 根因：用户快速操作时，前一次 sync 还在网络往返中，currentlySyncingItems 正包含在飞行中的商品。
      // 此时如果新一次 quickSaveTableOrder 启动，会因为 currentlySyncingItems 的去重把"在飞行中"的商品
      // 从 mergedItems 里剔除，再 OVERWRITE _newItemsToSync，导致那些商品在 mesas_estado 里消失。
      // 然后 sync1 完成时如果 _currentViewingTable 异常，那些商品也无法被加回 in-memory cart，
      // 最终用户看到部分新品丢失。等待 in-flight sync 完成可彻底消除这个 race。
      if (_forceFlag && window._syncTableOrderInProgress) {
        console.log('[autoSaveTableOrder] ⏳ force 模式 — 等待 in-flight syncTableOrderToServer 完成...');
        const _waitStart = Date.now();
        let _waitCount = 0;
        // 最多等 10 秒，避免极端情况下永久阻塞
        while (window._syncTableOrderInProgress && _waitCount < 100) {
          await new Promise(r => setTimeout(r, 100));
          _waitCount++;
        }
        const _waited = Date.now() - _waitStart;
        if (window._syncTableOrderInProgress) {
          console.error('[autoSaveTableOrder] ❌ 等待同步超时（' + _waited + 'ms），取消本次强制保存，避免打印旧桌位/旧订单');
          throw new Error('TABLE_ORDER_SYNC_TIMEOUT');
        } else {
          console.log('[autoSaveTableOrder] ✅ in-flight sync 已完成（等待 ' + _waited + 'ms），继续 save');
        }
      }

      // 🔥🔥🔥 【2026-01-22 关键修复】检查是否有支付完成标志，防止支付后重复创建订单
      if (window._paymentJustCompleted) {
        console.log('[autoSaveTableOrder] ⏭️ 支付刚完成，跳过自动保存');
        return false;
      }

      // 🔥🔥🔥 【2026-03-29 关键修复】AA金额分单进行中或正在结算时，跳过自动保存
      // 防止 AA 结账过程��� autoSave 将旧 cart 写入 mesas_estado 导致重复订单
      if (typeof amountSplitState !== 'undefined' && (amountSplitState.isActive || _amountSplitFinalizing)) {
        console.log('[autoSaveTableOrder] ⏭️ AA金额分单进行中，跳过自动保存');
        return false;
      }

      if (!hasUnsavedTableOrder()) {
        return false;
      }

      const table_number = document.getElementById('table-number')?.value.trim();
      if (!table_number) {
        return false;
      }

      // 🔥 记录保存开始时的桌位，用于异步回调中检查是否已切换
      const _autoSaveStartTable = window._currentViewingTable;

      const hasNewItems = cart && cart.length > 0 && cart.some(item => item.locked !== true && item.quantity > 0);
      const hasModifiedLockedItems = window.cartModified === true;

      // 🔥🔥🔥 详细打印购物车状态
      if (cart && cart.length > 0) {
        cart.forEach((item, idx) => {
          const price = item.customPrice !== undefined ? item.customPrice : item.price;
        });

        // 统计 Varios 产品
        const variosItems = cart.filter(item => item.isVarios || item.name === 'Varios');
        if (variosItems.length > 0) {
          variosItems.forEach((v, i) => {
            const price = v.customPrice !== undefined ? v.customPrice : v.price;
          });
        }
      }

      // 如果既没有新产品也没有修改锁定产品，直接返回
      if (!hasNewItems && !hasModifiedLockedItems) {
        return false;
      }

      // 🔥🔥🔥 关键修复：检查是否刚刚同步过，避免重复同步
      // 🔥🔥🔥 【2026-04-06 关键修复】使用 resolveGlobalTableNumber 规范化桌号
      const _autoResolvedNum = (typeof ruiyiSafeResolveGlobalTableNumber === 'function')
        ? ruiyiSafeResolveGlobalTableNumber(table_number)
        : (typeof resolveGlobalTableNumber === 'function' ? resolveGlobalTableNumber(table_number) : null);
      const _autoFallback = table_number.replace(/^(餐桌|Mesa|Table)\s*/, '');
      const tableNum = (_autoResolvedNum && /^\d+$/.test(String(_autoResolvedNum)))
        ? String(_autoResolvedNum)
        : _autoFallback;
      const mesaKey = `Mesa ${tableNum}`;
      // 🔥【2026-04-07】force 模式（用户显式点结账/预结单）跳过 3 秒去抖
      if (!_forceFlag && window._recentlySyncedTables?.[mesaKey]) {
        const syncTime = window._recentlySyncedTables[mesaKey].timestamp;
        const timeSinceSync = Date.now() - syncTime;
        if (timeSinceSync < 3000) { // 3秒内同步过
          console.log('[autoSaveTableOrder] ⏭️ 3秒去抖跳过 (mesaKey:', mesaKey, ', force:', _forceFlag, ')');
          return false;
        }
      } else if (_forceFlag) {
        console.log('[autoSaveTableOrder] ⚡ force 模式 — 绕过 3 秒去抖 (mesaKey:', mesaKey, ')');
      }

      // 🔥 厨房打印盒子：统一收集所有需要打印的商品（🍽️ 排除开台商品）
      const kitchenPrintQueue = [];
      const cashierKitchenPrintQueue = []; // 🔥 收银台厨房小票（全部产品）
      // 🔥 厨房小票多语言：根据系统语言选择产品名称
      const _kLang = window.RUIYI_POS?.currentLang || PHP_LANG || 'zh';
      function _resolveKitchenName(item) {
        if (_kLang === 'zh' && item.name_zh) return item.name_zh;
        if (_kLang === 'en' && item.name_en) return item.name_en;
        return item.name; // fallback 到默认名称（西班牙语）
      }

      // 1. 锁定商品的新增数量部分
      cart.filter(item => item.locked && (item.addedQuantity || 0) > 0 && !item.is_buffet_opening).forEach(item => {
        const printItem = {
          name: _resolveKitchenName(item),
          quantity: item.addedQuantity,
          notes: item.notes || '',
          product_id: item.id || 0
        };
        // 🔥 收银台队列：全部加入
        if (window.clodopConfig?.kitchenCategoryFilterEnabled) {
          cashierKitchenPrintQueue.push(printItem);
        }
        // 🔥 厨房队列：过滤排除分类
        if (!isKitchenExcludedProduct(item.id)) {
          kitchenPrintQueue.push(printItem);
        } else {
          if (!window.clodopConfig?.kitchenCategoryFilterEnabled) {
            kitchenPrintQueue.push(printItem);
          }
        }
      });

      // 2. 新添加的商品（未锁定，🍽️ 排除开台商品）
      cart.filter(item => !item.locked && item.quantity > 0 && !item.is_buffet_opening).forEach(item => {
        const printItem = {
          name: _resolveKitchenName(item),
          quantity: item.quantity,
          notes: item.notes || '',
          product_id: item.id || 0
        };
        // 🔥 收银台队列：全部加入
        if (window.clodopConfig?.kitchenCategoryFilterEnabled) {
          cashierKitchenPrintQueue.push(printItem);
        }
        // 🔥 厨房队列：过滤排除分类
        if (!isKitchenExcludedProduct(item.id)) {
          kitchenPrintQueue.push(printItem);
        } else {
          if (!window.clodopConfig?.kitchenCategoryFilterEnabled) {
            kitchenPrintQueue.push(printItem);
          }
        }
      });

      console.log('[autoSaveTableOrder] 🗃️ 厨房打印盒子:', kitchenPrintQueue.length, '项',
        window.clodopConfig?.kitchenCategoryFilterEnabled ? '(收银台队列:' + cashierKitchenPrintQueue.length + '项)' : '',
        '| 过滤启用:', !!window.clodopConfig?.kitchenCategoryFilterEnabled,
        '| 排除分类:', JSON.stringify(window.clodopConfig?.kitchenExcludedCategories || []));

      // 🚀 【关键】使用与手动保存完全相同的流程
      // 1. 立即更新本地状态
      let orderData = null;
      if (hasNewItems) {
        // 有新产品：调用 quickSaveTableOrder 处理
        // 🔥🔥🔥 【2026-01-20 关键修复】传入 true 跳过 renderCart()
        // 因为自动保存时购物车 UI 还在显示，renderCart() 会导致金额闪烁
        orderData = quickSaveTableOrder(true);
        if (orderData) {
          if (orderData.newItems) {
            orderData.newItems.forEach((item, i) => {
              const price = item.customPrice !== undefined ? item.customPrice : item.price;
            });
          }
        }
      } else if (hasModifiedLockedItems) {
        // 🔥🔥🔥 【2026-01-20 关键修复】只有修改锁定产品时，也需要立即更新本地状态
        // 否则切换模块后桌位会短暂显示旧状态
        const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
        if (mesasEstado[mesaKey]) {
          // 🔥🔥🔥 【2026-01-31 关键修复】过滤掉数量为0的商品
          const cartToSaveFiltered = cart.filter(item => item.quantity > 0);
          // 计算当前购物车总额（含 supplements）
          const tableTotal = cartToSaveFiltered.reduce((sum, item) => {
            return sum + ((parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0))) * item.quantity);
          }, 0);
          // 更新本地状态
          mesasEstado[mesaKey].total = tableTotal;
          mesasEstado[mesaKey].cart = JSON.parse(JSON.stringify(cartToSaveFiltered));
          mesasEstado[mesaKey].cart_gtn = parseInt(tableNum);
          mesasEstado[mesaKey].timestamp = new Date().toISOString();
          // 🔥 不再设置 _skipAutoUpdate — 服务器同步完成后走服务器路径
          // mesasEstado[mesaKey]._skipAutoUpdate = true;
          localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
        }
      }

      // 🔥🔥🔥 打印 quickSaveTableOrder 执行后的购物车状态
      if (cart && cart.length > 0) {
        cart.forEach((item, idx) => {
          const price = item.customPrice !== undefined ? item.customPrice : item.price;
        });
      }

      // 2. 显示成功提示
      Toastify({
        text: `✅ <?php echo ruiyi_translate('Pedido guardado automáticamente', 'Order auto-saved', '订单已自动保存'); ?>`,
        duration: 1500,
        gravity: "top",
        position: "center",
        style: { background: "#10b981" }
      }).showToast();

      // 🔥🔥🔥 【2026-01-20 关键修复】执行顺序与手动保存完全一致
      // 关键修复（参考手动保存 line 11600-11605）：先更新锁定商品，再添加新商品
      // 原因：
      // 1. 如果用户修改了锁定商品价格（如 6.30€→3.00€），又添加了同产品原价（6.30€）
      // 2. 如果先添加新商品，ruiyi_pos_create_order 会因 product_id+price 已存在而跳过
      // 3. 然后更新锁定商品时价格变更，新商品就丢失了
      // 4. 更重要的是：updateLockedItemsToServer 会保留不在请求列表中的产品，不会删除新添加的
      // 顺序：1. 先更新锁定商品（价格/数量变更生效）2. 再添加新商品（此时原价不重复）

      // 3. 🔥 取消乐观删除定时器（不管什么情况）
      if (window._optimisticDeleteSyncTimer) {
        clearTimeout(window._optimisticDeleteSyncTimer);
        window._optimisticDeleteSyncTimer = null;
      }

      // 4. 🔥🔥🔥 【2026-01-22 关键修复】等待服务器同步完成
      // 原问题：使用 (async () => { ... })() 立即返回，不等待同步完成
      // 导致 ensureTableOrderSaved 在同步完成前就继续执行，订单 ID 还是 PENDING_ 状态
      // 修复：将异步操作改为直接 await 执行，确保同步完成后再返回
      // 🔥🔥🔥 关键：先更新锁定商品，后添加新商品

      try {
        // 步骤1：先更新锁定产品数量/价格
        if (hasModifiedLockedItems) {
          const lockedBefore = cart.filter(item => item.locked);
          lockedBefore.forEach((item, i) => {
            const price = item.customPrice !== undefined ? item.customPrice : item.price;
            console.log(`  锁定商品[${i}]: ${item.name} | ID:${item.id} | €${price} x ${item.quantity}`);
          });

          try {
            await updateLockedItemsToServer();
            window.cartModified = false;
          } catch (e) {
            console.error('[🔍自动保存调试] ❌ 步骤1失败: updateLockedItemsToServer 错误:', e);
            throw e;
          }
        }

        // 步骤2：锁定商品更新后，再同步新商品到服务器
        if (orderData) {
          orderData.skipKitchenPrint = true; // 由统一打印盒子处理
          try {
            await syncTableOrderToServer(orderData);
            console.log('[autoSaveTableOrder] ✅ 服务器同步完成');
          } catch (e) {
            console.error('[🔍自动保存调试] ❌ 步骤2失败: syncTableOrderToServer 错误:', e);
            // 🔥🔥🔥 【2026-03-30 关键修复】同步失败时从 mesas_estado 恢复购物车
            // quickSaveTableOrder 已移除未锁定商品(line 9557)，同步失败则购物车为空
            // 导致结账时提示"没有商品"
            try {
              const mesasEstadoRecover = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
              const tableDataRecover = mesasEstadoRecover[orderData.mesaKey];
              const _recoverGtn = parseInt(orderData.mesaKey.replace(/\D/g, ''));
              if (tableDataRecover?.cart && tableDataRecover.cart.length > 0 && cart.length === 0 &&
                  (tableDataRecover.cart_gtn === undefined || tableDataRecover.cart_gtn === _recoverGtn)) {
                console.log('[autoSaveTableOrder] 🔄 从 mesas_estado 恢复购物车:', tableDataRecover.cart.length, '项');
                cart = tableDataRecover.cart.filter(item => item.quantity > 0);
                window.cart = cart;
                if (typeof ruiyiSetCartTableIdentity === 'function') {
                  ruiyiSetCartTableIdentity(orderData.table_number || _recoverGtn, 'autoSaveTableOrder:recover-after-sync-failure');
                }
                if (typeof renderCart === 'function') renderCart();
              }
            } catch (recoverErr) {
              console.error('[autoSaveTableOrder] ❌ 恢复购物车失败:', recoverErr);
            }
            throw e;
          }
        }

        // 🔥 检查用户是否已切换桌位，如已切换则跳过后续购物车操作
        if (_autoSaveStartTable && window._currentViewingTable !== _autoSaveStartTable) {
          console.warn('[autoSaveTableOrder] ⚠️ 用户已切换桌位 (' + _autoSaveStartTable + '→' + window._currentViewingTable + ')，跳过后续操作');
          return true;
        }

        // 步骤3：🔥 统一打印厨房小票（从打印盒子）
        if (kitchenPrintQueue.length > 0 && window.clodopConfig?.enabled && window.clodopConfig?.kitchenPrinter) {
          const isDeliveryForPrint = typeof isDeliveryZoneTable === 'function' ? isDeliveryZoneTable(table_number) : false;
          const isSkipZoneForPrint = typeof shouldSkipKitchenPrintForTable === 'function' ? shouldSkipKitchenPrintForTable(table_number) : false;

          if (isSkipZoneForPrint) {
            console.log('[autoSaveTableOrder] 🚫 该分区已设置跳过厨房打印，不打印');
          } else if (isDeliveryForPrint) {
            console.log('[autoSaveTableOrder] 🚚 外送区域桌位，跳过厨房打印（将在预结单时打印）');
          } else {
            const tableNum_p = table_number.replace(/^(餐桌|Mesa|Table)\s*/, '');
            const mesaKey_p = `Mesa ${tableNum_p}`;
            const mesasEstado_p = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
            const printOrderId = mesasEstado_p[mesaKey_p]?.orderId || '';

            if (printOrderId && !String(printOrderId).startsWith('PENDING_') && !String(printOrderId).startsWith('OFFLINE_')) {
              // 🔥 写入 recent_kitchen_prints 时间戳，防止轮询/storage事件重复打印
              try {
                const recentPrints = JSON.parse(localStorage.getItem('recent_kitchen_prints') || '{}');
                recentPrints[printOrderId] = Date.now();
                localStorage.setItem('recent_kitchen_prints', JSON.stringify(recentPrints));
                console.log('[autoSaveTableOrder] 🛡️ 已写入打印时间戳，防止轮询重复打印:', printOrderId);
              } catch (e) { /* localStorage write may fail in private browsing */ }

              // 获取厨房打印桌号（分类显示名称）
              let kitchenTableName = table_number;
              const tableNumForKitchen = parseInt(tableNum_p);
              if (!isNaN(tableNumForKitchen) && window.tableCategoryMappings) {
                let allMappings = Array.isArray(window.tableCategoryMappings)
                  ? window.tableCategoryMappings
                  : Object.values(window.tableCategoryMappings);
                const mapping = allMappings.find(m => parseInt(m.global_table_number) === tableNumForKitchen);
                if (mapping && mapping.category_display_name) {
                  kitchenTableName = mapping.category_display_name;
                } else if (mapping && mapping.display_name) {
                  kitchenTableName = mapping.display_name;
                }
              }

              // 🔥🔥🔥 【2026-03-25 v3】统一使用 unprinted_only API，无论是否启用分类打印机
              // 所有路径都必须经过 API 以标记已打印状态，杜绝重复打印
              try {
                console.log('[autoSaveTableOrder] 🖨️ 调用 unprinted_only API, orderId:', printOrderId);
                const response = await fetch(posAjaxUrl || ajaxUrl, {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                  body: new URLSearchParams({
                    action: 'ruiyi_pos_get_order_for_print',
                    order_id: printOrderId,
                    nonce: posNonce || ajaxNonce,
                    unprinted_only: 'true'
                  })
                });
                const apiData = await response.json();

                if (apiData.success && apiData.data && apiData.data.items && apiData.data.items.length > 0) {
                  let apiItems = apiData.data.items;
                  console.log('[autoSaveTableOrder] ✅ API返回未打印商品:', apiItems.length, '个', apiItems.map(i => i.name + ' x' + i.quantity));

                  // 🔥 分类打印机诊断日志
                  apiItems.forEach(item => {
                    console.log('[autoSaveTableOrder] 📋 分类打印机:', item.name, '| cat:', item.category_name, '| cat_printer:', item.category_printer || '(空-将用默认)');
                  });

                  const defaultPrinter = window.clodopConfig.kitchenPrinter;
                  const categoryPrinterEnabled = window.clodopConfig.categoryPrinterEnabled;
                  const separatePerCat = window.clodopConfig.separateTicketPerCategory;
                  // 🔥 API返回的商品多语言名称解析
                  function _resolveApiName(item) {
                    if (_kLang === 'zh' && item.name_zh) return item.name_zh;
                    if (_kLang === 'en' && item.name_en) return item.name_en;
                    return item.name;
                  }
                  // 🔥 过滤"不打印"分类
                  apiItems = apiItems.filter(item => item.category_printer !== '__no_print__');
                  // 🔥【2026-04-07 修复】过滤厨房排除的分类（与 cashierKitchen 路径互补：厨房不打印，前台才打印完整版）
                  if (window.clodopConfig?.kitchenCategoryFilterEnabled) {
                    const _excludedCats = (window.clodopConfig.kitchenExcludedCategories || []).map(Number);
                    if (_excludedCats.length > 0) {
                      const _beforeCount = apiItems.length;
                      apiItems = apiItems.filter(item => !_excludedCats.includes(parseInt(item.category_id)));
                      console.log('[autoSaveTableOrder] 🔥 厨房分类过滤:', _beforeCount, '→', apiItems.length, '排除:', JSON.stringify(_excludedCats));
                    }
                  }
                  if (apiItems.length === 0) {
                    console.log('[autoSaveTableOrder] ℹ️ 过滤后无可打印商品，跳过厨房打印');
                  }
                  let printJobs = [];

                  if (categoryPrinterEnabled && separatePerCat) {
                    const catGroups = {};
                    apiItems.forEach(item => {
                      const catName = item.category_name || '__uncategorized__';
                      const printer = item.category_printer || defaultPrinter;
                      if (!catGroups[catName]) catGroups[catName] = { printer: printer, items: [] };
                      catGroups[catName].items.push({ name: _resolveApiName(item), name_original: item.name || '', quantity: item.quantity, notes: item.notes || '', is_supplement: item.is_supplement || false, parent_item_name: item.parent_item_name || '' });
                    });
                    Object.keys(catGroups).forEach(cn => {
                      printJobs.push({ printer: catGroups[cn].printer, items: catGroups[cn].items, categoryLabel: cn !== '__uncategorized__' ? cn : null });
                    });
                  } else if (categoryPrinterEnabled) {
                    const printerGroups = {};
                    apiItems.forEach(item => {
                      const printer = item.category_printer || defaultPrinter;
                      if (!printerGroups[printer]) printerGroups[printer] = [];
                      printerGroups[printer].push({ name: _resolveApiName(item), name_original: item.name || '', quantity: item.quantity, notes: item.notes || '', is_supplement: item.is_supplement || false, parent_item_name: item.parent_item_name || '' });
                    });
                    Object.keys(printerGroups).forEach(pn => {
                      printJobs.push({ printer: pn, items: printerGroups[pn], categoryLabel: null });
                    });
                  } else {
                    // 未启用分类打印机 → 全部商品一张票
                    printJobs.push({ printer: defaultPrinter, items: apiItems.map(i => ({ name: _resolveApiName(i), name_original: i.name || '', quantity: i.quantity, notes: i.notes || '', is_supplement: i.is_supplement || false, parent_item_name: i.parent_item_name || '' })), categoryLabel: null });
                  }

                  console.log('[autoSaveTableOrder] 打印路由:', printJobs.length, '张小票');
                  // 🔥 合并备注：服务器订单备注 + 本地产品备注
                  const _apiNotes1 = apiData.data.notes || '';
                  const _localNotes1 = typeof window.getOrderNotes === 'function' ? window.getOrderNotes() : '';
                  const _mergedNotes1 = [_apiNotes1, _localNotes1].filter(n => n && n.trim()).join('; ');
                  printJobs.forEach((job, index) => {
                    const kitchenOrderData = {
                      id: printOrderId, table_number: kitchenTableName, order_type: 'servir',
                      items: job.items, date_created: new Date().toISOString(),
                      orderNotes: _mergedNotes1,
                      printer_group: printJobs.length > 1 ? (job.categoryLabel || job.printer) : null,
                      total_printers: printJobs.length,
                      category_label: job.categoryLabel
                    };
                    setTimeout(() => {
                      if (typeof ruiyiPrintKitchenOrder === 'function') {
                        ruiyiPrintKitchenOrder(kitchenOrderData, job.printer);
                      }
                      if (index === printJobs.length - 1 && kitchenOrderData.orderNotes && typeof window.clearOrderNotes === 'function') {
                        window.clearOrderNotes();
                      }
                    }, index * 500);
                  });
                } else {
                  console.log('[autoSaveTableOrder] ℹ️ 无未打印商品（已全部打印或API返回空），跳过打印');
                }
              } catch (err) {
                console.error('[autoSaveTableOrder] ❌ unprinted_only API 出错，回退到本地队列:', err);
                const kitchenOrderData = {
                  id: printOrderId, table_number: kitchenTableName, order_type: 'servir',
                  items: kitchenPrintQueue.map(i => ({ name: i.name, name_original: i.name || '', quantity: i.quantity, notes: i.notes || '', is_supplement: i.is_supplement || false, parent_item_name: i.parent_item_name || '' })),
                  date_created: new Date().toISOString(),
                  orderNotes: typeof window.getOrderNotes === 'function' ? window.getOrderNotes() : ''
                };
                if (typeof ruiyiPrintKitchenOrder === 'function') ruiyiPrintKitchenOrder(kitchenOrderData, window.clodopConfig.kitchenPrinter);
                if (kitchenOrderData.orderNotes && typeof window.clearOrderNotes === 'function') window.clearOrderNotes();
              }
            }
          }
        }

        // 🔥 步骤4：收银台打印机打印完整厨房小票（不过滤分类）
        if (window.clodopConfig?.kitchenCategoryFilterEnabled && window.clodopConfig?.kitchenCopyToDefault && cashierKitchenPrintQueue.length > 0 && window.clodopConfig?.enabled && window.clodopConfig?.defaultPrinter) {
          const isDeliveryForCashier = typeof isDeliveryZoneTable === 'function' ? isDeliveryZoneTable(table_number) : false;
          if (!isDeliveryForCashier) {
            const tableNumC = table_number.replace(/^(餐桌|Mesa|Table)\s*/, '');
            const mesaKeyC = `Mesa ${tableNumC}`;
            const mesasEstadoC = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
            const printOrderIdC = mesasEstadoC[mesaKeyC]?.orderId || '';

            let kitchenTableNameC = table_number;
            const tableNumForKitchenC = parseInt(tableNumC);
            if (!isNaN(tableNumForKitchenC) && window.tableCategoryMappings) {
              let allMappingsC = Array.isArray(window.tableCategoryMappings) ? window.tableCategoryMappings : Object.values(window.tableCategoryMappings);
              const mappingC = allMappingsC.find(m => parseInt(m.global_table_number) === tableNumForKitchenC);
              if (mappingC && mappingC.category_display_name) kitchenTableNameC = mappingC.category_display_name;
              else if (mappingC && mappingC.display_name) kitchenTableNameC = mappingC.display_name;
            }

            const cashierOrderData = {
              id: printOrderIdC, table_number: kitchenTableNameC, order_type: 'servir',
              items: cashierKitchenPrintQueue.map(i => ({ name: i.name, quantity: i.quantity, notes: i.notes || '' })),
              date_created: new Date().toISOString(),
              orderNotes: typeof _mergedNotes1 !== 'undefined' ? _mergedNotes1 : (typeof window.getOrderNotes === 'function' ? window.getOrderNotes() : '')
            };
            if (typeof ruiyiPrintKitchenOrder === 'function') {
              ruiyiPrintKitchenOrder(cashierOrderData, window.clodopConfig.defaultPrinter);
              console.log('[autoSaveTableOrder] ✅ 收银台厨房小票已发送到收银打印机, 商品数:', cashierKitchenPrintQueue.length);
            }
          }
        }

      } catch (e) {
        console.error('[🔍自动保存调试] ❌ 整体同步失败:', e);
        throw e;
      }

      // 🔥🔥🔥 【架构优化】服务器同步完成后，清除 _skipAutoUpdate 标记
      // 让下次进入桌位走服务器路径（single source of truth），而非本地缓存路径
      // 服务器已经是最新数据，不需要再绕道 localStorage
      try {
        const mesasEstadoCleanup = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
        if (mesasEstadoCleanup[mesaKey] && mesasEstadoCleanup[mesaKey]._skipAutoUpdate) {
          delete mesasEstadoCleanup[mesaKey]._skipAutoUpdate;
          localStorage.setItem('mesas_estado', JSON.stringify(mesasEstadoCleanup));
          console.log('[autoSaveTableOrder] 🔓 已清除 _skipAutoUpdate，下次进入桌位将从服务器加载');
        }
      } catch (e) { /* non-critical */ }

      // 清除 addedQuantity 标记
      if (kitchenPrintQueue.length > 0) {
        cart.forEach(item => { delete item.addedQuantity; });
        // 🔥🔥🔥 【2026-01-20 关键修复】自动保存时不调用 renderCart()
        // 因为用户马上要切换模块，调用 renderCart() 会导致购物车金额闪烁
      }

      return true;
    }

    // Make autoSaveTableOrder globally available for PWA compatibility
    window.autoSaveTableOrder = autoSaveTableOrder;

    // ==================== PWA 优化：快速保存桌位订单 ====================

    /**
     * 🚀 快速保存桌位订单（同步操作，立即返回）
     * 采用乐观更新策略：先更新本地状态，后台异步同步到服务器
     * @param {boolean} skipRenderCart - 是否跳过 renderCart() 调用（自动保存时使用，避免购物车金额闪烁）
     * @returns {Object|null} 返回待同步的订单数据，供后台同步使用
     */
    function quickSaveTableOrder(skipRenderCart = false) {
      // 🔥🔥🔥 【2026-01-22 关键修复】检查是否有支付完成标志，防止支付后重复创建订单
      if (window._paymentJustCompleted) {
        console.log('[quickSaveTableOrder] ⏭️ 支付刚完成，跳过保存');
        return null;
      }

      const newItems = cart.filter(item => !item.locked && item.quantity > 0);
      // 🔥 厨房打印：获取所有有 addedQuantity 的商品（包括锁定商品的新增部分，🍽️ 排除开台商品）
      // 🔥🔥🔥 【2026-02-18 关键修复】使用多语言名称，而不是始终使用西班牙语
      const _qsKitchenLang = window.RUIYI_POS?.currentLang || PHP_LANG || 'zh';
      const kitchenPrintItems = cart.filter(item => (item.addedQuantity || 0) > 0 && !item.is_buffet_opening).map(item => {
        let kitchenName = item.name;
        if (_qsKitchenLang === 'zh' && item.name_zh) kitchenName = item.name_zh;
        else if (_qsKitchenLang === 'en' && item.name_en) kitchenName = item.name_en;
        return { name: kitchenName, quantity: item.addedQuantity, notes: item.notes || '' };
      });
      const table_number = document.getElementById('table-number')?.value.trim();

      if (newItems.length === 0 || !table_number) {
        return null;
      }

      // 🔥🔥🔥 【2026-04-06 关键修复】用 resolveGlobalTableNumber 规范化桌号
      // 防止自定义名（如 "T16", "厅1"）被当作 mesaKey 的后缀导致跨桌位串单
      // 原 bug: table_number.replace(/^(餐桌|Mesa|Table)\s*/, '') 对自定义名无效
      // 例如 "T16" 经过 replace 仍是 "T16"，mesaKey 变成 "Mesa T16" 而非正确的 "Mesa 27"
      const _resolvedTableNum = (typeof ruiyiSafeResolveGlobalTableNumber === 'function')
        ? ruiyiSafeResolveGlobalTableNumber(table_number)
        : (typeof resolveGlobalTableNumber === 'function' ? resolveGlobalTableNumber(table_number) : null);
      const _fallbackStrip = table_number.replace(/^(餐桌|Mesa|Table)\s*/, '');
      // 优先使用解析后的全局编号（纯数字），失败则回退到剥离前缀
      const _normalizedTableNum = (_resolvedTableNum && /^\d+$/.test(String(_resolvedTableNum)))
        ? String(_resolvedTableNum)
        : _fallbackStrip;
      if (typeof ruiyiLogTerrazaDebug === 'function') {
        ruiyiLogTerrazaDebug('quickSaveTableOrder:resolved-table', {
          table_number,
          resolved: _resolvedTableNum,
          normalized: _normalizedTableNum,
          fallbackStrip: _fallbackStrip,
          currentViewingTable: window._currentViewingTable,
          newItems: newItems.map(item => ({
            id: item.id,
            name: item.name,
            quantity: item.quantity,
            price: item.customPrice !== undefined ? item.customPrice : item.price,
            locked: !!item.locked
          }))
        });
      }
      if (typeof ruiyiSetCartTableIdentity === 'function') {
        ruiyiSetCartTableIdentity(_normalizedTableNum, 'quickSaveTableOrder');
      }

      // 🔥🔥🔥 【2026-01-22 关键修复】检查桌位是否刚支付完成
      const tableNumEarly = _normalizedTableNum;
      const mesaKeyEarly = `Mesa ${tableNumEarly}`;
      const mesasEstadoEarly = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
      const tableDataEarly = mesasEstadoEarly[mesaKeyEarly];
      if (tableDataEarly && tableDataEarly._paymentCompleted) {
        console.log('[quickSaveTableOrder] ⏭️ 桌位刚支付完成，跳过保存:', mesaKeyEarly);
        return null;
      }

      // 🔥 检查是否在查看模式（追加订单）
      const isViewMode = typeof ruiyiGetActiveTableViewMode === 'function'
        ? ruiyiGetActiveTableViewMode()
        : (sessionStorage.getItem('tableViewMode') ? JSON.parse(sessionStorage.getItem('tableViewMode')) : null);

      // 生成临时订单ID
      const tempOrderId = 'PENDING_' + Date.now();

      // 🔥 【关键修复】只有当有真实服务器订单ID时才是"追加"模式
      // 临时ID（OFFLINE_、PENDING_开头）不算真实订单
      const mesasEstadoCheck = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
      const tableNumCheck = _normalizedTableNum;
      const mesaKeyCheck = `Mesa ${tableNumCheck}`;
      const checkTableData = mesasEstadoCheck[mesaKeyCheck] || {};
      const checkOrderIdStr = checkTableData.orderId ? String(checkTableData.orderId) : '';
      const hasRealServerOrder = checkOrderIdStr &&
                                  !checkOrderIdStr.startsWith('OFFLINE_') &&
                                  !checkOrderIdStr.startsWith('PENDING_') &&
                                  !checkTableData._offline &&
                                  !checkTableData._pendingSync;

      // 只有在查看模式且有真实服务器订单时才是追加
      const isAddition = isViewMode && isViewMode.mode === 'view' && hasRealServerOrder;
      // 计算桌位总额（含 supplements）
      const tableTotal = cart.reduce((sum, item) => {
        return sum + ((parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0))) * item.quantity);
      }, 0);

      // 立即更新本地桌位状态
      const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
      const tableNum = _normalizedTableNum;
      const mesaKey = `Mesa ${tableNum}`;
      if (typeof ruiyiLogTerrazaDebug === 'function') {
        ruiyiLogTerrazaDebug('quickSaveTableOrder:local-state-key', {
          table_number,
          tableNum,
          mesaKey,
          existingKeys: Object.keys(mesasEstado).filter(key => key.includes(tableNum) || key.toUpperCase().includes('TERRAZA')).slice(0, 20)
        });
      }

      // 清理旧格式条目
      ['餐桌', 'Table'].forEach(prefix => {
        const oldKey = `${prefix} ${tableNum}`;
        if (mesasEstado[oldKey] && oldKey !== mesaKey) {
          delete mesasEstado[oldKey];
        }
      });

      // 保留现有订单ID（如果是追加订单）
      const existingData = mesasEstado[mesaKey] || {};
      // 🔥 修复：orderId 可能是数字，需要先转为字符串再检查
      const existingOrderIdStr = existingData.orderId ? String(existingData.orderId) : '';
      const existingOrderId = existingOrderIdStr && !existingOrderIdStr.startsWith('PENDING_')
        ? existingData.orderId
        : null;

      // 🔥🔥🔥 【2026-01-19 关键修复】保存购物车数据时，将新保存的商品标记为 locked
      // 这样当用户返回桌位时，这些商品不会再次被添加到 _offlineNewItems
      // 解决了离线多次保存导致商品重复和金额错误的问题
      // 🔥 使用统一的 key 格式：parseFloat().toFixed(2) 确保价格比较一致
      // 🔥 supplements 签名用于去重区分
      const _supSig = (item) => (item.supplements && item.supplements.length > 0)
        ? '_sup:' + item.supplements.map(s => s.id).sort().join(',') : '';
      const newItemIds = new Set(newItems.map(item => `${item.id}_${item.name}_${parseFloat(item.price || 0).toFixed(2)}${_supSig(item)}`));
      // 🔥🔥🔥 【2026-01-31 关键修复】过滤掉数量为0的商品
      // 🔥🔥🔥 【2026-04-08 关键修复】对 mesas_estado.cart 去重合并
      const _dedupeMap = new Map();
      cart.filter(item => item.quantity > 0).forEach(item => {
        const key = `${item.id}_${item.name}_${parseFloat(item.price || 0).toFixed(2)}_${item.customName || ''}${_supSig(item)}`;
        const isNewlySaved = newItemIds.has(`${item.id}_${item.name}_${parseFloat(item.price || 0).toFixed(2)}${_supSig(item)}`);
        if (_dedupeMap.has(key)) {
          // 已有同 key 条目 → 累加数量（locked 项 + 新加的未锁定项合并）
          const existing = _dedupeMap.get(key);
          existing.quantity = (parseInt(existing.quantity) || 0) + (parseInt(item.quantity) || 0);
          // 保留 locked=true 和已有 orderId
          existing.locked = existing.locked || item.locked || isNewlySaved;
          if (!existing.orderId && item.orderId) existing.orderId = item.orderId;
        } else {
          _dedupeMap.set(key, {
            ...item,
            locked: item.locked || isNewlySaved,
            hasDiscount: item.hasDiscount || false,
            discountPercent: item.discountPercent || 0,
            originalPrice: item.originalPrice || item.price
          });
        }
      });
      const cartToSave = Array.from(_dedupeMap.values());

      // 🔥 【关键修复】只累积真正的新商品，不要重复添加已存在的商品
      // 之前的bug: 没有去重，导致同一商品被多次添加
      const existingNewItemsToSync = existingData._newItemsToSync || [];
      const existingOfflineNewItems = existingData._offlineNewItems || [];

      // 🔥🔥🔥 【2026-01-20 关键修复】获取正在同步的商品列表，避免重复添加
      const currentlySyncingItems = new Set(existingData._currentlySyncingItems || []);

      // 🔥 创建一个去重的商品列表
      const itemKeySet = new Set();
      const mergedItems = [];

      // 🔥【2026-04-07 关键修复】不再因 currentlySyncingItems 而丢弃商品
      // 原 bug：如果 sync 正在进行中，currentlySyncingItems 包含正在同步的商品 ID。
      // 之前的逻辑会跳过这些商品，导致 mesas_estado._newItemsToSync 被新 mergedItems 覆盖时
      // 那些"在飞行中"的商品永久消失（如果 sync 完成时 cart-add 路径也被 _currentViewingTable 检查跳过）。
      // 修复：保留它们在 mergedItems 里。重复同步由后端 dedupe 处理（同 product+price 已存在的会跳过）。

      // 先添加现有的待同步商品
      existingNewItemsToSync.forEach(item => {
        const key = `${item.id}_${item.name}_${parseFloat(item.price || 0).toFixed(2)}`;
        if (!itemKeySet.has(key)) {
          itemKeySet.add(key);
          mergedItems.push(JSON.parse(JSON.stringify(item)));
        }
      });

      // 添加 existingOfflineNewItems 中的商品
      existingOfflineNewItems.forEach(item => {
        const key = `${item.id}_${item.name}_${parseFloat(item.price || 0).toFixed(2)}`;
        if (!itemKeySet.has(key)) {
          itemKeySet.add(key);
          mergedItems.push(JSON.parse(JSON.stringify(item)));
        }
      });

      // 添加当前新商品（去重）
      newItems.forEach(item => {
        const key = `${item.id}_${item.name}_${parseFloat(item.price || 0).toFixed(2)}`;
        if (!itemKeySet.has(key)) {
          itemKeySet.add(key);
          mergedItems.push(JSON.parse(JSON.stringify(item)));
        }
      });

      console.log(`[quickSaveTableOrder] 📦 累积待同步商品: 现有 ${existingNewItemsToSync.length} + ${existingOfflineNewItems.length}, 新增 ${newItems.length}, 合并后 ${mergedItems.length}, 正在同步 ${currentlySyncingItems.size}`);

      // 🔥 【关键修复】根据当前网络状态设置 _offline 标记
      // 之前的 bug: `existingData._offline || true` 永远返回 true
      const isCurrentlyOffline = !navigator.onLine || window.RUIYI_POS?.isOnline === false;

      mesasEstado[mesaKey] = {
        estado: 'ocupada',
        orderId: existingOrderId || tempOrderId,
        timestamp: new Date().toISOString(),
        total: tableTotal,
        discount: window.currentDiscountPercent || 0,
        cart: JSON.parse(JSON.stringify(cartToSave)),
        cart_gtn: parseInt(tableNum), // 🔥 cart 身份标签：标记此 cart 属于哪个 gtn
        orderNotes: existingData.orderNotes || window.currentOrderNotes || '', // 🔥 保留订单备注
        _pendingSync: true,  // 🔥 标记待同步
        _skipAutoUpdate: true,
        _offline: isCurrentlyOffline, // 🔥🔥🔥 【关键修复】只基于当前网络状态，不继承旧值，避免同步状态异常
        // 🔥 关键修复：同时设置两个字段，确保两个同步机制都能工作
        _newItemsToSync: mergedItems,
        _offlineNewItems: mergedItems,
        _isAddition: isAddition,
        _hasOnlineOrder: existingData._hasOnlineOrder || isAddition
      };

      localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
      if (typeof ruiyiLogTerrazaDebug === 'function') {
        ruiyiLogTerrazaDebug('quickSaveTableOrder:saved-local-state', {
          table_number,
          tableNum,
          mesaKey,
          orderId: mesasEstado[mesaKey]?.orderId,
          total: mesasEstado[mesaKey]?.total,
          pendingSync: mesasEstado[mesaKey]?._pendingSync,
          offline: mesasEstado[mesaKey]?._offline,
          localCartCount: mesasEstado[mesaKey]?.cart?.length || 0,
          pendingItemCount: mesasEstado[mesaKey]?._offlineNewItems?.length || 0
        });
      }

      // 🔥【2026-04-03 修复】移除 waiter_order_created_trigger
      // POS 自身创建的订单不需要触发"新订单"通知
      // 此信号仅用于外部页面（服务员/客户）通知 POS

      // 🔥 设置跳过标志，防止 renderCart 覆盖
      window._skipRenderCartTableSync = true;

      // 🔥 保存成功后清除所有商品的 addedQuantity 标记
      cart.forEach(item => { delete item.addedQuantity; });

      // 清空未锁定商品
      cart = cart.filter(item => item.locked);

      // 🔥🔥🔥 【2026-01-20 关键修复】只有在非自动保存模式下才渲染购物车
      // 自动保存是在切换模块时触发的，此时购物车 UI 还在显示
      // 如果执行 renderCart() 会导致用户看到金额短暂闪烁（从原金额变为只有锁定商品的金额）
      // 手动保存时会立即切换到桌位模块，所以不会看到这个问题
      if (!skipRenderCart) {
        renderCart();
      }

      // 清除跳过标志
      setTimeout(() => { window._skipRenderCartTableSync = false; }, 100);

      // 返回待同步数据
      return {
        tempOrderId,
        existingOrderId,
        table_number,
        tableNum,
        mesaKey,
        newItems: JSON.parse(JSON.stringify(newItems)),
        kitchenPrintItems, // 🔥 厨房打印专用：包含锁定商品的新增部分
        tableTotal,
        isAddition
      };
    }

    /**
     * 🔥🔥🔥 确保桌位订单已保存（在结账/AA结账/预结单前调用）
     * 检查并保存以下变更：
     * 1. 新添加的未锁定商品
     * 2. 已锁定商品的数量修改
     * @returns {Promise<boolean>} 返回是否成功保存（或无需保存）
     */
    async function ensureTableOrderSaved() {
      const tableNumber = document.getElementById('table-number')?.value.trim();
      if (!tableNumber) {
        return true;
      }

      // 检查是否有未锁定的新商品
      const hasUnlockedItems = cart && cart.some(item => !item.locked && item.quantity > 0);

      // 检查是否有锁定商品（需要同步数量修改）
      const hasLockedItems = cart && cart.some(item => item.locked && item.quantity > 0);

      if (!hasUnlockedItems && !hasLockedItems) {
        return true;
      }

      try {
        // 1. 如果有未锁定商品，先保存新订单
        if (hasUnlockedItems) {
          // 调用自动保存函数
          // 🔥🔥🔥 【2026-01-22 关键修复】不再手动添加商品到购物车
          // 因为 syncTableOrderToServer (lines 9407-9442) 已经会将商品标记为 locked 并添加到购物车
          // 原问题：这里重复添加商品导致购物车有两份相同商品，显示 €3.90 而不是 €1.95
          // 🔥【2026-04-07】ensureTableOrderSaved 由结账/预结单等显式用户操作调用，必须 force
          const saveSuccess = await autoSaveTableOrder({ force: true });

          if (saveSuccess) {
            // 等待服务器完全处理订单
            await new Promise(resolve => setTimeout(resolve, 500));
          }
        }

        // 2. 同步锁定商品的数量修改到服务器
        if (hasLockedItems) {
          await updateLockedItemsToServer();

          // 等待同步完成
          await new Promise(resolve => setTimeout(resolve, 300));
        }

        return true;

      } catch (error) {
        return false;
      }
    }

    // 🔥 将函数暴露到全局作用域
    window.ensureTableOrderSaved = ensureTableOrderSaved;

    /**
     * 🔥 更新锁定产品到服务器（当用户修改锁定产品的数量时调用）
     */
    async function updateLockedItemsToServer() {
      console.log('[🔍updateLockedItems调试] ========== updateLockedItemsToServer 开始 ==========');

      const table_number = document.getElementById('table-number')?.value.trim();
      if (!table_number) {
        console.log('[🔍updateLockedItems调试] ❌ table_number 为空，返回');
        return;
      }
      console.log('[🔍updateLockedItems调试] 桌位号:', table_number);

      // 🔥🔥🔥 关键：同步前先合并重复条目
      if (typeof consolidateCartItems === 'function') {
        console.log('[🔍updateLockedItems调试] 调用 consolidateCartItems()');
        consolidateCartItems();
      }

      // 🔥🔥🔥 关键修复：设置同步锁，防止乐观删除同步同时运行
      window._updateLockedItemsSyncInProgress = true;

      // 🔥🔥🔥 关键修复：等待正在进行的乐观删除同步完成
      if (window._optimisticDeleteSyncInProgress) {
        console.log('[🔍updateLockedItems调试] ⏳ 等待乐观删除同步完成...');
        let waitCount = 0;
        const maxWait = 50; // 最多等待5秒 (50 * 100ms)
        while (window._optimisticDeleteSyncInProgress && waitCount < maxWait) {
          await new Promise(resolve => setTimeout(resolve, 100));
          waitCount++;
        }
        console.log('[🔍updateLockedItems调试] 等待完成，等待次数:', waitCount);
      }

      // 获取所有锁定的产品（已保存到订单的产品）
      // 🔥 关键修改：包含所有锁定产品，不仅仅是 quantity > 0 的
      // 这样服务器能知道哪些产品应该保留（quantity > 0），哪些应该删除（quantity = 0）
      const allLockedItems = cart.filter(item => item.locked);
      const lockedItemsWithQuantity = allLockedItems.filter(item => item.quantity > 0);

      console.log('[🔍updateLockedItems调试] 购物车总商品数:', cart?.length || 0);
      console.log('[🔍updateLockedItems调试] 锁定商品数 (allLockedItems):', allLockedItems.length);
      console.log('[🔍updateLockedItems调试] 有数量的锁定商品数 (lockedItemsWithQuantity):', lockedItemsWithQuantity.length);

      // 🔥🔥🔥 详细打印锁定商品
      if (allLockedItems.length > 0) {
        console.log('[🔍updateLockedItems调试] 锁定商品详情:');
        allLockedItems.forEach((item, idx) => {
          const price = item.customPrice !== undefined ? item.customPrice : item.price;
          console.log(`  [${idx}] ${item.name} | ID:${item.id} | €${price} x ${item.quantity} | isVarios:${item.isVarios || false}`);
        });

        // 🔥 特别检查 Varios 产品
        const variosLocked = allLockedItems.filter(item => item.isVarios || item.name === 'Varios');
        if (variosLocked.length > 0) {
          console.log('[🔍updateLockedItems调试] ⚠️ 锁定的 Varios 产品:', variosLocked.length, '个');
          variosLocked.forEach((v, i) => {
            const price = v.customPrice !== undefined ? v.customPrice : v.price;
            console.log(`  Varios锁定[${i}]: €${price} x ${v.quantity}`);
          });
        }
      }

      // 🔥🔥🔥 关键修复：检查待同步删除队列中是否有当前桌位的删除操作
      const pendingDeletionsBeforeRequest = JSON.parse(localStorage.getItem('pending_locked_item_deletions') || '[]');
      const hasPendingDeletionsForThisTable = pendingDeletionsBeforeRequest.some(deletion => {
        const deletionTable = deletion.table_number || '';
        return deletionTable === table_number ||
          ruiyiSafeResolveGlobalTableNumber(deletionTable) === ruiyiSafeResolveGlobalTableNumber(table_number);
      });

      // 如果没有任何锁定产品，检查是否有待同步的删除操作
      if (allLockedItems.length === 0) {
        if (hasPendingDeletionsForThisTable) {
          // 🔥 有待同步的删除操作，不清除队列，让 syncOfflineLockedItemDeletions 处理
          window._updateLockedItemsSyncInProgress = false; // 🔥 先释放锁
          // 🔥🔥🔥 关键修复：主动触发乐观删除同步，确保删除操作被执行
          setTimeout(() => {
            if (typeof window.syncOfflineLockedItemDeletions === 'function') {
              window.syncOfflineLockedItemDeletions().then(() => {
                if (typeof fetchAndUpdateTableStatuses === 'function') {
                  fetchAndUpdateTableStatuses();
                }
              }).catch(e => {
                // 乐观删除同步失败静默处理
              });
            }
          }, 100); // 延迟100ms确保锁已释放
        } else {
          window._updateLockedItemsSyncInProgress = false; // 🔥 释放锁
        }
        return;
      }

      // 🔥🔥🔥 有锁定产品要更新，清除当前桌位的待同步删除队列（因为我们会发送完整状态）
      if (hasPendingDeletionsForThisTable) {
        const filteredDeletionsBeforeRequest = pendingDeletionsBeforeRequest.filter(deletion => {
          const deletionTable = deletion.table_number || '';
          const isSameTable = deletionTable === table_number ||
            ruiyiSafeResolveGlobalTableNumber(deletionTable) === ruiyiSafeResolveGlobalTableNumber(table_number);
          return !isSameTable;
        });
        localStorage.setItem('pending_locked_item_deletions', JSON.stringify(filteredDeletionsBeforeRequest));
      }

      // 🔥🔥🔥 【2026-01-31 关键修复】发送所有锁定产品到服务器（包括数量为0的）
      // 原问题：只发送 quantity > 0 的商品，服务器会保留不在列表中的商品
      // 修复：发送所有锁定商品，让服务器根据 quantity=0 来删除对应的订单项
      const lockedItems = allLockedItems;

      // 从mesas_estado获取orderId
      const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');

      // 🔥 首先尝试直接使用原始桌位号查找
      let orderId = null;
      let foundKey = null;

      // 直接查找原始桌位号（如 "室内1" 或 "室内 1"）
      if (mesasEstado[table_number] && mesasEstado[table_number].orderId) {
        orderId = mesasEstado[table_number].orderId;
        foundKey = table_number;
      }

      // 如果没找到，尝试带空格的格式
      if (!orderId) {
        // 提取数字部分
        const tableNum = ruiyiSafeResolveGlobalTableNumber(table_number);

        // 多格式查找（使用标准前缀，支持任意区域名称）
        const possiblePrefixes = ['Mesa', 'Table', '餐桌'];

        for (const prefix of possiblePrefixes) {
          // 尝试带空格格式
          const keyWithSpace = `${prefix} ${tableNum}`;
          if (mesasEstado[keyWithSpace] && mesasEstado[keyWithSpace].orderId) {
            orderId = mesasEstado[keyWithSpace].orderId;
            foundKey = keyWithSpace;
            break;
          }
          // 尝试不带空格格式
          const keyNoSpace = `${prefix}${tableNum}`;
          if (mesasEstado[keyNoSpace] && mesasEstado[keyNoSpace].orderId) {
            orderId = mesasEstado[keyNoSpace].orderId;
            foundKey = keyNoSpace;
            break;
          }
        }
      }

      // 🔥 如果仍然没找到orderId，尝试从锁定产品中获取
      // 🔥 关键修复：使用 allLockedItems 而不是 lockedItems，因为当所有商品数量为0时 lockedItems 为空
      if (!orderId) {
        for (const item of allLockedItems) {
          if (item.orderId && !String(item.orderId).startsWith('OFFLINE_') && !String(item.orderId).startsWith('PENDING_')) {
            orderId = item.orderId;
            foundKey = 'item.orderId';
            break;
          }
        }
      }

      if (!orderId || String(orderId).startsWith('OFFLINE_') || String(orderId).startsWith('PENDING_')) {
        console.log('[🔍updateLockedItems调试] ❌ orderId 无效或为临时ID:', orderId);
        window._updateLockedItemsSyncInProgress = false; // 🔥 释放锁
        throw new Error('INVALID_TABLE_ORDER_ID');
      }

      console.log('[🔍updateLockedItems调试] ✅ 找到有效 orderId:', orderId, '| foundKey:', foundKey);

      // 🔥 收集所有不同的订单ID（可能来自多个订单）
      const allOrderIds = new Set();
      allOrderIds.add(orderId); // 主订单ID

      // 🔥 关键修复：从 allLockedItems 收集订单ID（包括数量为0的商品）
      for (const item of allLockedItems) {
        if (item.orderId && !String(item.orderId).startsWith('OFFLINE_') && !String(item.orderId).startsWith('PENDING_')) {
          allOrderIds.add(item.orderId);
        }
      }

      const orderIdsArray = Array.from(allOrderIds).map(id => parseInt(id)).filter(id => id > 0);
      console.log('[🔍updateLockedItems调试] 订单ID列表:', orderIdsArray);

      // 🔥🔥🔥 准备发送的数据
      const itemsToSend = lockedItems.map(item => {
        const currentQty = Math.max(0, parseInt(item.quantity || 0, 10) || 0);
        const addedQty = Math.max(0, parseInt(item.addedQuantity || 0, 10) || 0);
        return {
          product_id: item.id,
          item_id: item.itemId || item.item_id || '',
          name: item.customName || item.name,
          quantity: currentQty,
          added_quantity: addedQty,
          previous_quantity: Math.max(0, currentQty - addedQty),
          price: item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : item.price,
          custom_name: item.customName || null,
          supplements: item.supplements && item.supplements.length > 0 ? JSON.stringify(item.supplements) : null, // 🔥 保存配料数据
          original_name: item._originalName || null, // 🔥 保存原始名称（不含配料）
          original_price: item._originalPrice !== undefined ? item._originalPrice : null // 🔥 保存原始价格（不含配料）
        };
      });

      console.log('[🔍updateLockedItems调试] 📤 准备发送到服务器的商品数量:', itemsToSend.length);
      console.log('[🔍updateLockedItems调试] 📤 发送的商品详情:');
      itemsToSend.forEach((item, idx) => {
        console.log(`  发送[${idx}]: ${item.name} | ID:${item.product_id} | item_id:${item.item_id || '-'} | €${item.price} x ${item.quantity} | 新增:${item.added_quantity}`);
      });

      // 🔥 特别检查 Varios 产品
      const variosToSend = itemsToSend.filter(item => item.name === 'Varios' || item.product_id === 4598);
      if (variosToSend.length > 0) {
        console.log('[🔍updateLockedItems调试] ⚠️ 发送的 Varios 产品:', variosToSend.length, '个');
        variosToSend.forEach((v, i) => {
          console.log(`  Varios发送[${i}]: ID:${v.product_id} | €${v.price} x ${v.quantity}`);
        });
      } else {
        console.log('[🔍updateLockedItems调试] ⚠️ 没有 Varios 产品需要发送');
      }

      // 调用后端更新订单（合并到主订单，删除其他订单）
      try {
        const formData = new URLSearchParams({
          action: 'ruiyi_pos_update_order_items',
          order_id: orderId,
          all_order_ids: JSON.stringify(orderIdsArray), // 🔥 传递所有订单ID
          items: JSON.stringify(itemsToSend),
          nonce: window.RUIYI_POS?.nonce
        });

        console.log('[🔍updateLockedItems调试] 🌐 发送请求到服务器...');

        const response = await fetch(window.ajaxUrl || '<?php echo admin_url("admin-ajax.php"); ?>', {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: formData
        });

        const data = await response.json();
        console.log('[🔍updateLockedItems调试] 📥 服务器响应:', data.success ? '成功' : '失败', data);

        if (data.success) {
          // 🔥 更新本地购物车中所有锁定产品的orderId为主订单ID
          // 🔥🔥🔥 同时清除 quantityModified 标记，表示数量已同步
          cart.forEach(item => {
            if (item.locked) {
              item.orderId = orderId;
              if (item.quantityModified) {
                delete item.quantityModified;
                delete item.isNew; // 清除isNew标记，因为已同步
              }
            }
          });

          // 🔥【2026-04-07】移除 quantity===0 的锁定项（已被服务器删除）
          cart = cart.filter(item => !(item.locked && item.quantity <= 0));
          if (typeof window !== 'undefined') window.cart = cart;

          // 🔥 同步更新mesas_estado中的orderId
          if (foundKey && foundKey !== 'item.orderId') {
            try {
              const mesasEstadoUpdate = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
              if (mesasEstadoUpdate[foundKey]) {
                mesasEstadoUpdate[foundKey].orderId = orderId;
                // 清除可能存在的orders数组（多订单情况）
                delete mesasEstadoUpdate[foundKey].orders;

                // 🔥【2026-04-07】同步清理 mesas_estado 中的 q=0 项
                if (Array.isArray(mesasEstadoUpdate[foundKey].cart)) {
                  mesasEstadoUpdate[foundKey].cart = mesasEstadoUpdate[foundKey].cart.filter(it => (it.quantity || 0) > 0);
                }

                // 🔥【2026-04-07】如果所有商品都被删完，把桌位标记为 libre 并清理状态
                const remainingItems = (mesasEstadoUpdate[foundKey].cart || []).length;
                const cartHasItems = cart.some(it => it.quantity > 0);
                if (remainingItems === 0 && !cartHasItems) {
                  console.log('[updateLockedItems] 🧹 所有商品已删除，桌位 ' + foundKey + ' 标记为 libre');
                  mesasEstadoUpdate[foundKey].estado = 'libre';
                  mesasEstadoUpdate[foundKey].cart = [];
                  mesasEstadoUpdate[foundKey].total = 0;
                  delete mesasEstadoUpdate[foundKey].orderId;
                  delete mesasEstadoUpdate[foundKey].orders;
                  delete mesasEstadoUpdate[foundKey]._newItemsToSync;
                  delete mesasEstadoUpdate[foundKey]._offlineNewItems;
                  delete mesasEstadoUpdate[foundKey]._currentlySyncingItems;
                  delete mesasEstadoUpdate[foundKey]._pendingSync;
                  // 同时清理订单起始时间
                  try {
                    const KEY = 'table_order_start_times';
                    const map = JSON.parse(localStorage.getItem(KEY) || '{}');
                    if (map[foundKey]) {
                      delete map[foundKey];
                      localStorage.setItem(KEY, JSON.stringify(map));
                    }
                  } catch(e) {}
                } else {
                  // 还有剩余商品：更新 total
                  const newTotal = (mesasEstadoUpdate[foundKey].cart || []).reduce((s, i) => {
                    const p = parseFloat(i.customPrice !== undefined ? i.customPrice : (i.price || 0));
                    return s + (p * (i.quantity || 0));
                  }, 0);
                  mesasEstadoUpdate[foundKey].total = newTotal;
                }

                localStorage.setItem('mesas_estado', JSON.stringify(mesasEstadoUpdate));

                // 触发桌位重新渲染
                if (typeof renderizarMesas === 'function') {
                  setTimeout(() => renderizarMesas('after-locked-items-cleanup'), 50);
                }
              }
            } catch (e) {
              // 更新mesas_estado失败静默处理
            }
          }

          // 🔥🔥🔥 关键修复：清除待同步的删除队列，避免重复操作
          // 因为我们已经发送了完整的订单状态，所以不需要再单独删除
          const pendingDeletions = JSON.parse(localStorage.getItem('pending_locked_item_deletions') || '[]');
          if (pendingDeletions.length > 0) {
            // 过滤掉属于当前桌位的删除操作
            const filteredDeletions = pendingDeletions.filter(deletion => {
              const deletionTable = deletion.table_number || '';
              // 检查是否属于当前桌位
              const isSameTable = deletionTable === table_number ||
                ruiyiSafeResolveGlobalTableNumber(deletionTable) === ruiyiSafeResolveGlobalTableNumber(table_number);
              return !isSameTable;
            });
            localStorage.setItem('pending_locked_item_deletions', JSON.stringify(filteredDeletions));
          }
        } else {
          console.log('[🔍updateLockedItems调试] ❌ 服务器返回失败');
          throw new Error((data && data.data && data.data.message) || 'UPDATE_LOCKED_ITEMS_FAILED');
        }
      } catch (error) {
        console.error('[🔍updateLockedItems调试] ❌ 请求异常:', error);
        throw error;
      } finally {
        // 🔥🔥🔥 关键：无论成功或失败，都释放同步锁
        window._updateLockedItemsSyncInProgress = false;
        console.log('[🔍updateLockedItems调试] ========== updateLockedItemsToServer 结束 ==========');
      }
    }
    window.updateLockedItemsToServer = updateLockedItemsToServer;

    /**
     * 🔄 后台同步桌位订单到服务器（异步操作，不阻塞UI）
     * @param {Object} orderData - quickSaveTableOrder 返回的订单数据
     */
    async function syncTableOrderToServer(orderData) {
      // 🔥【2026-04-03】标记 POS 正在同步订单，WebSocket 通知在此期间静默
      window._posCreatingOrder = Date.now();
      console.log('[🔍syncTableOrder调试] ========== syncTableOrderToServer 开始 ==========');

      if (!orderData) {
        console.log('[🔍syncTableOrder调试] ❌ orderData 为空，返回');
        return;
      }

      console.log('[🔍syncTableOrder调试] orderData.mesaKey:', orderData.mesaKey);
      console.log('[🔍syncTableOrder调试] orderData.table_number:', orderData.table_number);
      console.log('[🔍syncTableOrder调试] orderData.isAddition:', orderData.isAddition);
      console.log('[🔍syncTableOrder调试] orderData.newItems 数量:', orderData.newItems?.length || 0);

      // 🔥🔥🔥 详细打印要同步的新商品
      if (orderData.newItems && orderData.newItems.length > 0) {
        console.log('[🔍syncTableOrder调试] 新商品详情:');
        orderData.newItems.forEach((item, idx) => {
          const price = item.customPrice !== undefined ? item.customPrice : item.price;
          console.log(`  新商品[${idx}]: ${item.name} | ID:${item.id} | €${price} x ${item.quantity} | isVarios:${item.isVarios || false} | customPrice:${item.customPrice} | zoneCategoryId:${item.zoneCategoryId} | basePrice:${item.basePrice} | price:${item.price}`);
        });

        // 特别检查 Varios
        const variosNew = orderData.newItems.filter(item => item.isVarios || item.name === 'Varios');
        if (variosNew.length > 0) {
          console.log('[🔍syncTableOrder调试] ⚠️ 新的 Varios 产品:', variosNew.length, '个');
          variosNew.forEach((v, i) => {
            const price = v.customPrice !== undefined ? v.customPrice : v.price;
            console.log(`  Varios新增[${i}]: €${price} x ${v.quantity}`);
          });
        }
      }

      // 🔥🔥🔥 关键：同步前先合并重复条目
      if (typeof consolidateCartItems === 'function') {
        consolidateCartItems();
      }

      const isOnline = navigator.onLine && window.RUIYI_POS?.isOnline !== false;
      if (!isOnline) {
        console.log('[🔍syncTableOrder调试] ❌ 离线状态，返回');
        throw new Error('TABLE_ORDER_SYNC_OFFLINE');
      }

      // 🔥 【关键修复】检查全局同步锁，防止与 syncOfflineTableOrders 同时运行导致重复订单
      if (window._globalOfflineTableSyncInProgress) {
        console.log('[🔍syncTableOrder调试] ❌ _globalOfflineTableSyncInProgress 锁，返回');
        throw new Error('TABLE_ORDER_GLOBAL_SYNC_IN_PROGRESS');
      }

      // 🔥 设置同步锁
      window._syncTableOrderInProgress = true;

      try {
        // 🔥🔥🔥 【2026-01-20 关键修复】不在同步开始时清除 _offlineNewItems
        // 原因：如果用户快速添加多个商品然后自动保存，会有竞态条件：
        // 1. 商品A同步开始 → 清除 _offlineNewItems
        // 2. 用户添加商品B → quickSaveTableOrder 读取 existingOfflineNewItems = []（已被清除！）
        // 3. 商品A丢失，只同步商品B
        // 解决方案：只设置 _syncing 标记，在同步成功后才清除 _offlineNewItems
        const mesasEstadoPreSync = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
        if (mesasEstadoPreSync[orderData.mesaKey]) {
          // 🔥 只设置同步中标记，不清除待同步商品列表
          mesasEstadoPreSync[orderData.mesaKey]._syncing = true;
          // 🔥 保存当前正在同步的商品ID列表，用于后续去重
          mesasEstadoPreSync[orderData.mesaKey]._currentlySyncingItems = orderData.newItems.map(item =>
            `${item.id}_${item.name}_${parseFloat(item.price || 0).toFixed(2)}`
          );
          localStorage.setItem('mesas_estado', JSON.stringify(mesasEstadoPreSync));
        }

        // 🍽️ 分离自助餐商品和普通商品
        const syncNewItems = orderData.newItems || [];
        const syncBuffetItems = syncNewItems.filter(i => i.is_buffet);
        // 🔥 supplements 已在弹窗关闭时合入 customName/customPrice，直接使用
        const syncRegularItems = syncNewItems.filter(i => !i.is_buffet);

        const formData = new URLSearchParams({
          action: 'ruiyi_pos_create_order',
          cart: JSON.stringify(syncRegularItems),
          table_number: orderData.table_number,
          order_type: 'servir',
          payment_method: 'Cash',
          is_addition: orderData.isAddition ? 'true' : 'false',
          nonce: ajaxNonce
        });
        if (syncBuffetItems.length > 0) {
          formData.append('buffet_items', JSON.stringify(syncBuffetItems));
        }
        if (typeof ruiyiLogTerrazaDebug === 'function') {
          ruiyiLogTerrazaDebug('syncTableOrderToServer:request', {
            table_number: orderData.table_number,
            tableNum: orderData.tableNum,
            mesaKey: orderData.mesaKey,
            currentViewingTable: window._currentViewingTable,
            resolved: typeof ruiyiSafeResolveGlobalTableNumber === 'function'
              ? ruiyiSafeResolveGlobalTableNumber(orderData.table_number)
              : null,
            isAddition: !!orderData.isAddition,
            regularItemCount: syncRegularItems.length,
            buffetItemCount: syncBuffetItems.length,
            items: syncRegularItems.map(item => ({
              id: item.id,
              name: item.name,
              quantity: item.quantity,
              price: item.customPrice !== undefined ? item.customPrice : item.price
            }))
          });
        }

        // 🔥 【2026-03-10 修复】附带外送客户信息到订单
        // 确保保存桌位订单时，客户电话/地址等信息也存入 WC 订单 meta
        if (typeof window.getDeliveryCustomerData === 'function') {
          const deliveryData = window.getDeliveryCustomerData(orderData.table_number);
          if (deliveryData && (deliveryData.phone || deliveryData.address)) {
            formData.append('customer_info', JSON.stringify({
              phone: deliveryData.phone || '',
              address: deliveryData.address || '',
              name: deliveryData.name || '',
              business_name: deliveryData.businessName || '',
              cif_nif: deliveryData.cifNif || '',
              notes: deliveryData.notes || ''
            }));
            console.log('[syncTableOrder] 📱 附带外送客户信息:', deliveryData.phone);
          }
        }

        console.log('[🔍syncTableOrder调试] 🌐 发送 ruiyi_pos_create_order 请求...');
        console.log('[🔍syncTableOrder调试] 📤 cart JSON (前500字符):', JSON.stringify(syncRegularItems).substring(0, 500));
        // 🔥 关键调试：检查每个商品的价格字段
        syncRegularItems.forEach((item, idx) => {
          console.log(`[🔍syncTableOrder调试] 📤 发送商品[${idx}]: ID:${item.id} | price:${item.price} | customPrice:${item.customPrice} | zoneCategoryId:${item.zoneCategoryId} | basePrice:${item.basePrice}`);
        });

        const response = await fetch(ajaxUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: formData
        });

        if (!response.ok) {
          console.error('[🔍syncTableOrder调试] ❌ HTTP 错误:', response.status);
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();
        console.log('[🔍syncTableOrder调试] 📥 服务器响应:', data.success ? '成功' : '失败');
        if (typeof ruiyiLogTerrazaDebug === 'function') {
          ruiyiLogTerrazaDebug('syncTableOrderToServer:response', {
            table_number: orderData.table_number,
            tableNum: orderData.tableNum,
            mesaKey: orderData.mesaKey,
            success: !!data.success,
            orderId: data.data?.order_id || data.order_id || null,
            total: data.data?.total || data.total || null,
            message: data.data?.message || data.message || null,
            raw: data
          });
        }

        if (data.success) {
          const realOrderId = data.data?.order_id || data.order_id;
          const orderTotal = data.data?.total || data.total || orderData.tableTotal;
          const serverItems = data.data?.items; // 服务器可能返回items
          const syncVersion = data.data?.version || data.version || (Date.now() + '_' + Math.random().toString(36).substr(2, 4));

          console.log('[🔍syncTableOrder调试] ✅ 订单创建/更新成功');
          console.log('[🔍syncTableOrder调试] realOrderId:', realOrderId);
          console.log('[🔍syncTableOrder调试] orderTotal:', orderTotal);
          console.log('[syncTableOrderToServer] 📝 使用订单批次版本号:', syncVersion);

          // 🔥 更新本地状态：用真实订单ID替换临时ID
          const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
          if (mesasEstado[orderData.mesaKey]) {
            // 🔥 保存原始cart，防止后续被意外清空
            const originalCart = mesasEstado[orderData.mesaKey].cart ? [...mesasEstado[orderData.mesaKey].cart] : orderData.newItems;

            mesasEstado[orderData.mesaKey].orderId = realOrderId;
            mesasEstado[orderData.mesaKey].total = orderTotal;

            // 🔥🔥🔥 【2026-01-20 关键修复】只从待同步列表中移除已同步的商品
            // 不要清除整个列表，因为可能有用户在同步过程中新添加的商品
            const syncedItemKeys = new Set(orderData.newItems.map(item =>
              `${item.id}_${item.name}_${parseFloat(item.price || 0).toFixed(2)}`
            ));

            // 从 _offlineNewItems 中移除已同步的商品
            if (mesasEstado[orderData.mesaKey]._offlineNewItems && Array.isArray(mesasEstado[orderData.mesaKey]._offlineNewItems)) {
              mesasEstado[orderData.mesaKey]._offlineNewItems = mesasEstado[orderData.mesaKey]._offlineNewItems.filter(item => {
                const key = `${item.id}_${item.name}_${parseFloat(item.price || 0).toFixed(2)}`;
                return !syncedItemKeys.has(key);
              });
              // 如果列表为空则删除
              if (mesasEstado[orderData.mesaKey]._offlineNewItems.length === 0) {
                delete mesasEstado[orderData.mesaKey]._offlineNewItems;
              }
            }

            // 从 _newItemsToSync 中移除已同步的商品
            if (mesasEstado[orderData.mesaKey]._newItemsToSync && Array.isArray(mesasEstado[orderData.mesaKey]._newItemsToSync)) {
              mesasEstado[orderData.mesaKey]._newItemsToSync = mesasEstado[orderData.mesaKey]._newItemsToSync.filter(item => {
                const key = `${item.id}_${item.name}_${parseFloat(item.price || 0).toFixed(2)}`;
                return !syncedItemKeys.has(key);
              });
              // 如果列表为空则删除
              if (mesasEstado[orderData.mesaKey]._newItemsToSync.length === 0) {
                delete mesasEstado[orderData.mesaKey]._newItemsToSync;
              }
            }

            // 🔥 清除正在同步的商品列表
            delete mesasEstado[orderData.mesaKey]._currentlySyncingItems;

            // 🔥 只有当没有剩余待同步商品时，才清除 _pendingSync 标记
            const hasRemainingItems = (mesasEstado[orderData.mesaKey]._offlineNewItems?.length > 0) ||
                                       (mesasEstado[orderData.mesaKey]._newItemsToSync?.length > 0);
            if (!hasRemainingItems) {
              mesasEstado[orderData.mesaKey]._pendingSync = false;
              mesasEstado[orderData.mesaKey]._offline = false;
            }

            delete mesasEstado[orderData.mesaKey]._hasOnlineOrder;
            delete mesasEstado[orderData.mesaKey]._isAddition;
            // 🔥 【2026-01-19 关键修复】同步成功后删除 _skipAutoUpdate，允许后续服务器更新
            // 修复问题：POS保存订单后，客户页面追加订单，桌位金额不更新
            delete mesasEstado[orderData.mesaKey]._skipAutoUpdate;

            // 🔥 关键修复：确保cart数据存在，使用服务器返回的items或保留原始数据
            if (serverItems && Array.isArray(serverItems) && serverItems.length > 0) {
              mesasEstado[orderData.mesaKey].cart = serverItems;
            } else if (!mesasEstado[orderData.mesaKey].cart || mesasEstado[orderData.mesaKey].cart.length === 0) {
              mesasEstado[orderData.mesaKey].cart = originalCart;
            }

            // 🔥 设置保护标记，防止reloadTableOrderToCartSilently清空购物车
            mesasEstado[orderData.mesaKey]._justSynced = true;
            mesasEstado[orderData.mesaKey]._syncTimestamp = Date.now();

            // 🔥🔥🔥 【2026-01-27 关键修复】保存版本号，与轮询机制保持一致
            // 原问题：轮询机制使用 orderId_version 格式检查是否已打印
            // syncTableOrderToServer 没有设置 version，导致轮询机制认为是新版本并触发重复打印
            mesasEstado[orderData.mesaKey].version = syncVersion;

            localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));

            // 🔥🔥🔥 关键修复：将刚同步的新商品添加回购物车并标记为锁定状态
            // 🔥 但必须检查用户是否仍在同一桌位，否则会污染新桌位的购物车
            // 🔥🔥🔥 【2026-03-29 关键修复】当 _currentViewingTable 为 null（用户已离开桌位）时也必须跳过
            // 原 bug：guard 用 `_currentViewingTable && mismatch`，null 时条件为 false，导致 else 分支将旧桌位商品 push 到 cart
            var _syncTableNumRaw = typeof ruiyiSafeResolveGlobalTableNumber === 'function'
              ? ruiyiSafeResolveGlobalTableNumber(orderData.table_number)
              : resolveGlobalTableNumber(orderData.table_number);
            var _syncTableNum = _syncTableNumRaw !== null && _syncTableNumRaw !== undefined
              ? String(_syncTableNumRaw)
              : '';
            if (!window._currentViewingTable || _syncTableNum !== window._currentViewingTable) {
              console.warn('[syncTableOrder] ⚠️ 用户已切换桌位或离开桌位 (sync:' + _syncTableNum + ' current:' + window._currentViewingTable + ')，跳过购物车更新');
            } else if (orderData.newItems && orderData.newItems.length > 0) {
              orderData.newItems.forEach(syncedItem => {
                // 🔥🔥🔥【2026-04-08 关键修复】sync 回写：使用 effective price 匹配
                // 购物车中的 locked 项保留 supplements 数组，价格是基础价
                // 🔥 supplements 已合入 customPrice，直接比较价格
                const existingIndex = cart.findIndex(c => canMergeLockedSyncedLine(c, syncedItem));

                if (existingIndex !== -1) {
                  // 🔥 匹配到已锁定项：累加数量，合并为一行
                  const addQty = parseInt(syncedItem.quantity || 1);
                  cart[existingIndex].quantity = (parseInt(cart[existingIndex].quantity) || 0) + addQty;
                  cart[existingIndex].orderId = realOrderId;
                  // 清除 addedQuantity 标记（kitchen 已打印过）
                  delete cart[existingIndex].addedQuantity;
                  console.log('[syncTableOrder] 🔁 合并新数量到已锁定项:', syncedItem.name, '+' + addQty + ' → qty=' + cart[existingIndex].quantity);
                } else {
                  // 🔥 商品不在 cart 中或非 locked：作为新 locked 条目添加
                  const lockedItem = {
                    ...syncedItem,
                    locked: true,
                    orderId: realOrderId,
                    original: true  // 标记为已同步的原始订单项
                  };
                  delete lockedItem.addedQuantity;
                  cart.push(lockedItem);
                }
              });

              // 🔥 渲染购物车以显示新添加的锁定商品
              if (typeof renderCart === 'function') {
                renderCart();
              }
            }
          }

          // 🔥 设置全局同步保护标记
          window._recentlySyncedTables = window._recentlySyncedTables || {};
          window._recentlySyncedTables[orderData.mesaKey] = {
              timestamp: Date.now(),
              orderId: realOrderId,
              cart: orderData.newItems
          };

          // 5秒后清除保护标记
          setTimeout(() => {
              if (window._recentlySyncedTables?.[orderData.mesaKey]) {
                  delete window._recentlySyncedTables[orderData.mesaKey];
              }
          }, 5000);

          // 🔥 同步桌位状态到服务器
          if (typeof updateTableStatusToServer === 'function') {
            updateTableStatusToServer(orderData.tableNum, 'occupied', realOrderId, orderTotal);
          }

          // 🔥 打印厨房小票（如果启用）— 使用 printNewTableOrderToKitchen 支持分类打印机路由
          // 🔥🔥🔥 【2026-01-31 新增】外送区域保存订单时不触发厨房打印，只有预结单才打印
          // 🔥 【2026-03-11 新增】支持设置中配置跳过厨房打印的分区
          const isDeliveryZoneForKitchen = typeof isDeliveryZoneTable === 'function' ? isDeliveryZoneTable(orderData.tableNum) : false;
          const isSkipZoneForKitchen = typeof shouldSkipKitchenPrintForTable === 'function' ? shouldSkipKitchenPrintForTable(orderData.tableNum) : false;
          if (isSkipZoneForKitchen) {
            console.log('[syncTableOrderToServer] 🚫 该分区已设置跳过厨房打印，不打印');
          } else if (isDeliveryZoneForKitchen) {
            console.log('[syncTableOrderToServer] 🚚 外送区域桌位，跳过厨房打印（将在预结单时打印）');
          }
          if (realOrderId && window.clodopConfig?.enabled && window.clodopConfig?.kitchenPrinter && !isDeliveryZoneForKitchen && !isSkipZoneForKitchen) {

            // 🔥 无论是否 skipKitchenPrint，都写入防重复标记（防止轮询/storage事件重复打印）
            const printedOrders = JSON.parse(localStorage.getItem('printed_kitchen_orders') || '[]');
            let needSave = false;
            if (!printedOrders.includes(realOrderId)) {
              printedOrders.push(realOrderId);
              needSave = true;
            }
            // 🔥🔥🔥 关键修复：同时写入 orderId_version 格式的key，与轮询机制的检查格式一致
            const versionKey = realOrderId + '_' + (syncVersion || 'v0');
            if (!printedOrders.includes(versionKey)) {
              printedOrders.push(versionKey);
              needSave = true;
            }
            const recentPrints = JSON.parse(localStorage.getItem('recent_kitchen_prints') || '{}');
            recentPrints[realOrderId] = Date.now();
            recentPrints[versionKey] = Date.now();
            localStorage.setItem('recent_kitchen_prints', JSON.stringify(recentPrints));
            if (needSave) {
              localStorage.setItem('printed_kitchen_orders', JSON.stringify(printedOrders));
            }

            if (!orderData.skipKitchenPrint) {
              // 获取分类显示名称（用于 presetDisplayName 参数）
              let kitchenTableName = null;
              const tableNumForKitchen = parseInt(orderData.tableNum);
              if (!isNaN(tableNumForKitchen) && window.tableCategoryMappings) {
                let allMappings = Array.isArray(window.tableCategoryMappings)
                  ? window.tableCategoryMappings
                  : Object.values(window.tableCategoryMappings);
                const mapping = allMappings.find(m => parseInt(m.global_table_number) === tableNumForKitchen);
                if (mapping && mapping.category_display_name) {
                  kitchenTableName = mapping.category_display_name;
                }
              }

              const isAppendForKitchen = orderData.isAddition || false;
              console.log('[syncTableOrderToServer] 🖨️ 调用 printNewTableOrderToKitchen:', {
                桌号: orderData.table_number,
                订单ID: realOrderId,
                显示名: kitchenTableName,
                是否追加: isAppendForKitchen
              });

              if (typeof printNewTableOrderToKitchen === 'function') {
                printNewTableOrderToKitchen(orderData.table_number, realOrderId, kitchenTableName, isAppendForKitchen, syncVersion);
              }
            } else {
              console.log('[syncTableOrderToServer] 🛡️ skipKitchenPrint=true，跳过打印但已写入防重复标记:', realOrderId);
            }
          }

          // 🔥 刷新桌位显示（如果在桌位模块）
          if (document.getElementById('mesas-grid') && !document.getElementById('mesas').classList.contains('hidden')) {
            if (typeof renderizarMesas === 'function') {
              renderizarMesas('after-background-sync');
            }
          }

        } else {
          throw new Error(data.message || 'Order creation failed');
        }

      } catch (error) {
        // 🔥🔥🔥 【2026-01-20 关键修复】同步失败时，恢复失败的商品到待同步列表
        // 但不覆盖用户在同步过程中新添加的商品
        try {
          const mesasEstadoRestore = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
          if (mesasEstadoRestore[orderData.mesaKey]) {
            mesasEstadoRestore[orderData.mesaKey]._pendingSync = true;

            // 获取当前的待同步商品（可能包含用户新添加的）
            const currentOfflineItems = mesasEstadoRestore[orderData.mesaKey]._offlineNewItems || [];
            const currentNewItems = mesasEstadoRestore[orderData.mesaKey]._newItemsToSync || [];

            // 合并失败的商品和当前的待同步商品（去重）
            const itemKeySet = new Set();
            const mergedItems = [];

            // 先添加失败的商品
            orderData.newItems.forEach(item => {
              const key = `${item.id}_${item.name}_${parseFloat(item.price || 0).toFixed(2)}`;
              if (!itemKeySet.has(key)) {
                itemKeySet.add(key);
                mergedItems.push(JSON.parse(JSON.stringify(item)));
              }
            });

            // 添加当前的待同步商品
            [...currentOfflineItems, ...currentNewItems].forEach(item => {
              const key = `${item.id}_${item.name}_${parseFloat(item.price || 0).toFixed(2)}`;
              if (!itemKeySet.has(key)) {
                itemKeySet.add(key);
                mergedItems.push(JSON.parse(JSON.stringify(item)));
              }
            });

            mesasEstadoRestore[orderData.mesaKey]._newItemsToSync = mergedItems;
            mesasEstadoRestore[orderData.mesaKey]._offlineNewItems = mergedItems;
            delete mesasEstadoRestore[orderData.mesaKey]._syncing;
            delete mesasEstadoRestore[orderData.mesaKey]._currentlySyncingItems;
            localStorage.setItem('mesas_estado', JSON.stringify(mesasEstadoRestore));
          }
        } catch (e) {
          // 恢复待同步标记失败静默处理
        }
        throw error;
      } finally {
        // 🔥 释放同步锁
        window._syncTableOrderInProgress = false;
        // 清除 _syncing 和 _currentlySyncingItems 标记
        try {
          const mesasEstadoFinal = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
          if (mesasEstadoFinal[orderData.mesaKey]) {
            delete mesasEstadoFinal[orderData.mesaKey]._syncing;
            delete mesasEstadoFinal[orderData.mesaKey]._currentlySyncingItems;
            localStorage.setItem('mesas_estado', JSON.stringify(mesasEstadoFinal));
          }
        } catch (e) { /* localStorage cleanup - non-critical */ }

        console.log('[🔍syncTableOrder调试] ========== syncTableOrderToServer 结束 ==========');
      }
    }

    // 🔥🔥🔥 【2026-01-19 关键修复】移除了重复的 online 事件处理程序
    // 之前这里有一个独立的 syncTableOrderToServer 调用，与 line 745-749 的 syncOfflineTableOrders 冲突
    // 两个同步处理程序同时运行导致了竞争条件：
    // 1. 数据被错误地应用到不同的桌位
    // 2. localStorage 更新相互覆盖
    // 现在只使用统一的 syncOfflineTableOrders（在 line 745-749 延迟2秒后调用）

    // 导出函数供全局使用
    window.quickSaveTableOrder = quickSaveTableOrder;
    window.syncTableOrderToServer = syncTableOrderToServer;

    // ==================== PWA 优化结束 ====================

    // 🔥 新增：合并购物车中所有重复的锁定商品
    function consolidateLockedItems() {
      const processedIndices = new Set();
      const itemsToRemove = [];

      // 遍历购物车，查找重复的锁定商品
      for (let i = 0; i < cart.length; i++) {
        if (processedIndices.has(i) || !cart[i].locked) continue;

        const baseItem = cart[i];
        const basePrice = parseFloat(baseItem.customPrice !== undefined ? baseItem.customPrice : baseItem.price);


        // 查找所有相同的锁定商品
        for (let j = i + 1; j < cart.length; j++) {
          if (processedIndices.has(j) || !cart[j].locked) continue;

          const compareItem = cart[j];
          const comparePrice = parseFloat(compareItem.customPrice !== undefined ? compareItem.customPrice : compareItem.price);

          const idMatch = baseItem.id === compareItem.id;
          const priceMatch = Math.abs(basePrice - comparePrice) < 0.01;


          // 检查是否为相同商品（ID和价格都相同）
          if (idMatch && priceMatch) {

            baseItem.quantity += compareItem.quantity;
            itemsToRemove.push(j);
            processedIndices.add(j);

          }
        }

        processedIndices.add(i);
      }

      // 从后往前删除（避免索引变化）
      if (itemsToRemove.length > 0) {
        itemsToRemove.sort((a, b) => b - a).forEach(index => {
          cart.splice(index, 1);
        });
      } else {
      }

    }

    // 🔥 新增函数：为桌位创建订单（返回Promise和订单ID）
    // 用于在结账前保存未保存的产品
    function crearPedidoMesa(tableNumber, products) {
      // 🔥【2026-04-03】标记 POS 正在创建订单，WebSocket 通知在此期间静默
      window._posCreatingOrder = Date.now();

      return new Promise((resolve, reject) => {
        if (!products || products.length === 0) {
          reject(new Error('没有产品需要保存'));
          return;
        }

        // 计算总额（含 supplements）
        const subtotal = products.reduce((sum, item) => {
          return sum + ((parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0))) * item.quantity);
        }, 0);
        const tipo_pedido = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir';

        // 🔥 PWA: Use universal order submission (handles offline/online)
        const orderParams = {
          cart: products,
          table_number: tableNumber,
          order_type: tipo_pedido,
          payment_method: 'pending',
          tip_amount: 0,
          is_addition: 'true',
          discount: 0,
          client: '',
          skipCartClear: true  // 🔥 桌位结账流程：保留购物车数据，让产品变为锁定状态
        };

        // Submit order (online or offline)
        submitOrderUniversal(orderParams)
        .then(data => {
          if (data.success) {
            // 获取订单ID
            let orderId = '';
            if (data.data && data.data.order_id) {
              orderId = data.data.order_id;
            } else if (data.order_id) {
              orderId = data.order_id;
            }

            if (!orderId) {
              reject(new Error('未能获取订单ID'));
              return;
            }

            // 🔥【2026-04-03】标记此订单为 POS 自身创建，WebSocket 通知时跳过
            if (window._posCreatedOrderIds) {
              window._posCreatedOrderIds[String(orderId)] = Date.now();
              // 清理超过60秒的旧记录
              Object.keys(window._posCreatedOrderIds).forEach(function(k) {
                if (Date.now() - window._posCreatedOrderIds[k] > 60000) delete window._posCreatedOrderIds[k];
              });
            }

            // If offline order, log it
            if (data.offline) {
            }

            // 🔥 【2026-01-21 重构】移除直接打印逻辑，统一由轮询机制触发厨房打印
            // 原因：crearPedidoMesa 直接打印 + 轮询检测到新订单再打印 = 重复打印
            // 解决方案：只让轮询机制负责打印，避免竞态条件
            // 获取版本号用于轮询检测
            const orderVersion = data.data?.version || data.version || (Date.now() + '_' + Math.floor(Math.random() * 10000));
            console.log('[crearPedidoMesa] ✅ 订单创建成功，厨房打印将由轮询机制触发:', { orderId, version: orderVersion });

            // 更新餐桌状态到服务器（仅在线订单）
            if (tableNumber && tipo_pedido === 'servir') {
              const tableNumberNumeric = tableNumber.replace(/^(餐桌|Mesa|Table)\s*/, '');
              const orderTotal = data.data?.total || subtotal;

              // 🔥 PWA: Only sync to server if online (not for offline orders)
              if (!data.offline && typeof updateTableStatusToServer === 'function') {
              updateTableStatusToServer(tableNumber, 'occupied', orderId, orderTotal);
              } else if (data.offline) {
                // For offline orders, add to sync queue
                if (typeof posDB !== 'undefined' && posDB && typeof posDB.addToSyncQueue === 'function') {
                  posDB.addToSyncQueue('table_status', {
                    tableId: tableNumberNumeric,
                    status: { estado: 'ocupada', orderId: orderId, total: orderTotal }
                  });
                }
              }

              // 🔥 关键修复：立即更新本地 mesas_estado，确保桌位模块显示正确状态
              try {
                const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                // 🔥 【关键修复】统一使用 "Mesa" 格式，与所有页面保持一致
                const mesaKey = `Mesa ${tableNumberNumeric}`;

                // 清理旧格式的条目
                ['餐桌', 'Table'].forEach(prefix => {
                  const oldKey = `${prefix} ${tableNumberNumeric}`;
                  if (mesasEstado[oldKey]) {
                    delete mesasEstado[oldKey];
                  }
                });

                // 更新或创建桌位状态
                // 🔥 【关键修复】保留已有的折扣信息，或者使用当前折扣
                const existingDiscount = mesasEstado[mesaKey]?.discount || 0;
                const currentDiscount = window.currentDiscountPercent || existingDiscount;

                mesasEstado[mesaKey] = {
                  estado: 'ocupada',
                  orderId: orderId,
                  total: orderTotal,
                  timestamp: new Date().toISOString(),
                  discount: currentDiscount, // 🔥 保存折扣百分比
                  cart: JSON.parse(JSON.stringify(products)), // 保存购物车数据
                  cart_gtn: parseInt(tableNumberNumeric), // 🔥 cart 身份标签
                  orderNotes: mesasEstado[mesaKey]?.orderNotes || window.currentOrderNotes || '', // 🔥 保留订单备注
                  version: orderVersion // 🔥 【2026-01-21 修复】保存版本号，防止 storage 事件重复打印
                };

                localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
              } catch (e) {
                console.error('[crearPedidoMesa] ❌ 更新本地桌位状态失败:', e);
              }

              // 🔥【2026-04-03 修复】移除 waiter_order_created_trigger
              // POS 自身创建的订单不需要触发"新订单"通知（避免自我通知）
              try {
                // 仅触发桌位渲染刷新，不触发"新订单"通知
              } catch (e) {
                console.error('[crearPedidoMesa] ❌ 刷新失败:', e);
              }
            }

            // 🔥 新逻辑：将新增产品合并到已有锁定商品（节省空间）
            products.forEach(savedProduct => {
              // 🔥 优先查找已有的相同锁定商品（精确匹配）
              const priceToMatch = savedProduct.customPrice !== undefined ? savedProduct.customPrice : savedProduct.price;

              const existingLockedItem = cart.find(item =>
                item.id === savedProduct.id &&
                item.locked &&
                (item.customPrice === priceToMatch ||
                 (item.customPrice === undefined && item.price === priceToMatch))
              );

              if (existingLockedItem) {
                // 🔥 找到相同的锁定商品，叠加数量
                const oldQty = existingLockedItem.quantity;
                existingLockedItem.quantity += savedProduct.quantity;

                // 🔥 关键：从购物车中移除新增商品（已合并）
                const indexToRemove = cart.findIndex(item =>
                  item.id === savedProduct.id &&
                  !item.locked &&
                  item.quantity === savedProduct.quantity
                );

                if (indexToRemove !== -1) {
                  cart.splice(indexToRemove, 1);
                }
              } else {
                // 🔥 没有相同的锁定商品，标记新增商品为锁定
                const cartItem = cart.find(item =>
                  item.id === savedProduct.id &&
                  !item.locked &&
                  item.quantity === savedProduct.quantity
                );

                if (cartItem) {
                  cartItem.locked = true;
                  cartItem.orderId = orderId;
                } else {
                  console.warn('[crearPedidoMesa] ⚠️ 未找到对应的新增商品:', savedProduct.name);
                }
              }
            });

            // 🔥 额外处理：合并购物车中所有重复的锁定商品
            consolidateLockedItems();

            // 重新渲染购物车以显示锁定状态
            renderCart();

            // 返回订单ID
            resolve(orderId);
          } else {
            const errorMsg = data.data?.message || data.message || '创建订单失败';
            reject(new Error(errorMsg));
          }
        })
        .catch(error => {
          console.error('[crearPedidoMesa] 创建订单失败:', error);
          
          // Check if error message indicates offline save was attempted
          if (error.message && error.message.includes('offline')) {
            // Try to get the offline order ID from the error or from pending orders
            console.warn('[crearPedidoMesa] 订单可能已保存离线，但无法获取订单ID');
            reject(new Error('订单保存失败，请检查网络连接'));
          } else {
          reject(error);
          }
        });
      });
    }

    // Función unificada para crear pedido
    function crearPedidoFinal() {
      // 检查是否在查看模式
      const viewMode = sessionStorage.getItem('tableViewMode');
      const isViewMode = viewMode ? JSON.parse(viewMode) : null;

      // 分离锁定和非锁定商品，并过滤掉数量为0的商品
      const lockedItems = cart.filter(item => item.locked);
      const newItems = cart.filter(item => !item.locked && item.quantity > 0);

      // 如果没有新商品要添加
      if (newItems.length === 0) {
        Swal.fire({
          icon: 'info',
          title: '<?php echo ruiyi_translate("Sin productos nuevos", "No new products", "没有新商品"); ?>',
          text: '<?php echo ruiyi_translate("No hay productos nuevos para agregar al pedido", "There are no new products to add to the order", "没有新商品可添加到订单"); ?>'
        });
        return;
      }
      
      // Calculate total (only for new items)
      // 🔥 使用customPrice字段（如果存在），否则使用原价
      const subtotal = newItems.reduce((sum, item) => {
        const itemPrice = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
        return sum + (itemPrice * item.quantity);
      }, 0);
      
      const table_number = document.getElementById('table-number')?.value.trim() || '';
      const tipo_pedido = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir';
      
      // 检查订单类型和桌位号，对于非堂食订单，如果没有选择桌位号，显示"无桌位"
      const requireTableNumber = tipo_pedido === 'servir';
      const finalTableNumber = (!requireTableNumber && !table_number) ? window.RUIYI_TRANS.noTable : table_number;
      
      // 先检查库存（只检查新商品）
      const tempCart = cart;
      cart = newItems; // 临时替换购物车只检查新商品
      checkCartStock().then(stockOk => {
        cart = tempCart; // 恢复原购物车
        
        if (!stockOk) {
          return; // 如果库存不足，结束函数
        }
        
        // 显示处理中对话框
        Swal.fire({
          title: '<?php echo ruiyi_translate("Procesando pedido...", "Processing order...", "正在处理订单..."); ?>',
          text: isViewMode ?
            '<?php echo ruiyi_translate("Agregando productos al pedido existente", "Adding products to existing order", "正在添加商品到现有订单"); ?>' :
            '<?php echo ruiyi_translate("Por favor espere mientras se crea su pedido", "Please wait while your order is being created", "请稍等，正在创建您的订单"); ?>',
          allowOutsideClick: false,
          didOpen: () => {
            Swal.showLoading();
          }
        });

        // 准备请求数据
        // Get discount and client from form if available
        const discountInput = document.getElementById('discount-input') || document.getElementById('discount');
        const discount = discountInput ? parseFloat(discountInput.value) || 0 : 0;
        const clientSelect = document.getElementById('client-select') || document.getElementById('client');
        const client = clientSelect ? clientSelect.value || '' : '';

        const orderData = {
          cart: newItems,
          table_number: finalTableNumber,
          order_type: tipo_pedido,
          payment_method: selectedPaymentMethod || 'Cash',
          tip_amount: selectedTip || 0,
          is_addition: isViewMode ? 'true' : 'false',
          discount: discount,
          client: client
        };

        // 🔥 PWA: Handle offline/online order submission
        async function submitOrderWithPWA(orderData) {
          const isOnline = navigator.onLine && window.RUIYI_POS?.isOnline !== false;
          
          // Try online submission first if online
          if (isOnline) {
            try {
        const formData = new URLSearchParams();
        formData.append('action', 'ruiyi_pos_create_order');
              // 🍽️ 分离自助餐商品
              const pwaCart = orderData.cart || [];
              const pwaBuffetItems = Array.isArray(pwaCart) ? pwaCart.filter(i => i.is_buffet) : [];
              const pwaRegularItems = Array.isArray(pwaCart) ? pwaCart.filter(i => !i.is_buffet) : pwaCart;
              formData.append('cart', JSON.stringify(pwaRegularItems));
              if (pwaBuffetItems.length > 0) formData.append('buffet_items', JSON.stringify(pwaBuffetItems));
              formData.append('table_number', orderData.table_number);
              formData.append('order_type', orderData.order_type);
              formData.append('payment_method', orderData.payment_method);
              formData.append('tip_amount', orderData.tip_amount);
              formData.append('is_addition', orderData.is_addition);
        formData.append('nonce', ajaxNonce);

              const response = await fetch(ajaxUrl, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
          },
          body: formData
              });

          if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
          }

              const data = await response.json();
              if (data.success) {
                return data; // Successfully submitted online
              } else {
                throw new Error(data.message || 'Order creation failed');
              }
            } catch (error) {
              console.warn('[PWA] Online submission failed, saving offline:', error);
              // Fall through to offline save
            }
          }

          // Save offline (either offline mode or online submission failed)
          // Use the universal handler (it waits for posDB and has IndexedDB fallback)
          return await window.submitOrderUniversal(orderData);
        }

        // Submit order (online or offline)
        submitOrderWithPWA(orderData)
        .then(data => {
          if (data.success) {
            // 关闭加载提示
            Swal.close();

            // 获取订单ID（处理不同的响应结构可能性）
            let orderId = '';
            if (data.data && data.data.order_id) {
              orderId = data.data.order_id;
            } else if (data.order_id) {
              orderId = data.order_id;
            }

            // 显示订单总额（包含折扣后）
            let orderTotal = '';
            if (data.data && data.data.total) {
              orderTotal = data.data.total;
            } else if (data.total) {
              orderTotal = data.total;
            }

            // 🔥 page-pos.php 追加订单不自动打印厨房小票
            // 将订单ID标记为"已打印"，防止轮询检测时重复打印
            // 轮询检测只为 servicio-mesa.php 和 usuario-cocina.php 创建的订单打印
            const printedOrdersAppend = JSON.parse(localStorage.getItem('printed_kitchen_orders') || '[]');
            if (!printedOrdersAppend.includes(orderId)) {
              printedOrdersAppend.push(orderId);
              localStorage.setItem('printed_kitchen_orders', JSON.stringify(printedOrdersAppend));
            }

            // 🔥 PWA: Show simple toast for offline orders (no blocking popup)
            if (data.offline) {
              Toastify({
                text: `✅ <?php echo ruiyi_translate('Completado', 'Completed', '已完成'); ?>`,
                duration: 2000,
                gravity: "top",
                position: "center",
                style: { background: "#10b981" }
              }).showToast();

              // Trigger sync if online (in case connection was restored)
              if (navigator.onLine && window.posSync) {
                setTimeout(() => {
                  window.posSync.sync();
                }, 1000);
              }
            }

            // 更新餐桌状态为占用 - 仅当实际选择了桌位且是堂食订单时
            if (table_number && tipo_pedido === 'servir') {
              // 获取所有餐桌状态
              const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');

              // 🔥 【关键修复】统一使用 "Mesa" 格式，与所有页面保持一致
              const tableNumberClean = table_number.replace(/^(餐桌|Mesa|Table)\s*/, '');
              const mesaKey = `Mesa ${tableNumberClean}`;

              // 清理旧格式的条目
              ['餐桌', 'Table'].forEach(prefix => {
                const oldKey = `${prefix} ${tableNumberClean}`;
                if (mesasEstado[oldKey]) {
                  delete mesasEstado[oldKey];
                }
              });
              
              
              
              // 计算桌位总价格（考虑是否为追加订单）
              let tableTotal = orderTotal || calculateSubtotal();
              
              // 如果是追加订单（查看模式），需要累加原有订单总价
              if (isViewMode && mesasEstado[mesaKey] && mesasEstado[mesaKey].total) {
                const previousTotal = parseFloat(mesasEstado[mesaKey].total) || 0;
                const newOrderTotal = parseFloat(orderTotal) || 0;
                tableTotal = previousTotal + newOrderTotal;
              }
              
              // 更新当前餐桌为占用状态
              // 🔥 保留已有折扣或使用当前折扣
              const existingDiscountSubmit = mesasEstado[mesaKey]?.discount || 0;
              mesasEstado[mesaKey] = {
                estado: 'ocupada',
                orderId: orderId,
                timestamp: new Date().toISOString(),
                total: tableTotal,
                discount: window.currentDiscountPercent || existingDiscountSubmit, // 🔥 保存折扣
                orderNotes: mesasEstado[mesaKey]?.orderNotes || window.currentOrderNotes || '', // 🔥 保留订单备注
                _skipAutoUpdate: true // 防止服务器状态覆盖
              };
              
              // 保存状态到本地
              localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
              
              // 🔥 PWA: Only sync to server if online (not for offline orders)
              if (!data.offline && typeof updateTableStatusToServer === 'function') {
              // 同步状态到服务器（传完整格式，函数内部会安全解析）
              updateTableStatusToServer(table_number, 'occupied', orderId, tableTotal);
              } else if (data.offline) {
                // For offline orders, add to sync queue
                if (typeof posDB !== 'undefined' && posDB && typeof posDB.addToSyncQueue === 'function') {
                  posDB.addToSyncQueue('table_status', {
                    tableId: table_number.replace(/^(餐桌|Mesa|Table)\s*/, ''),
                    status: { estado: 'ocupada', orderId: orderId, total: tableTotal }
                  });
                }
              }
              
              // 如果餐桌管理页面打开，刷新餐桌显示
              if (document.getElementById('mesas-grid') && !document.getElementById('mesas').classList.contains('hidden')) {
                renderizarMesas('order-created');
              }
              
            }

            // 清空购物车和本地存储
            if (isViewMode) {
              // 追加订单模式：只清除新添加的商品，保留锁定的商品（原有订单）
              cart = cart.filter(item => item.locked);
            } else {
              // 新订单模式：完全清空购物车
              if (table_number && tipo_pedido === 'servir') {
                borrarCarritoMesa(table_number);
              }
              borrarPedidoTemporal();
              cart = [];
            }
            renderCart();

            // 检查是否需要返回餐桌模块
            const fromTableModuleFlag = sessionStorage.getItem('fromTableModule') === 'true';

            if (isViewMode || fromTableModuleFlag) {
              // 清理会话状态
              sessionStorage.removeItem('tableViewMode');
              sessionStorage.removeItem('tableOrderData');
              sessionStorage.removeItem('fromTableModule');
              sessionStorage.removeItem('isViewMode'); // 🔥 重要：清理isViewMode状态
              sessionStorage.removeItem('tableViewOrderData'); // 🔥 清理tableViewOrderData

              // 🔥 重要：完全清空购物车（包括锁定的商品）
              if (isViewMode) {
                cart = [];
                if (table_number && tipo_pedido === 'servir') {
                  borrarCarritoMesa(table_number);
                }
                borrarPedidoTemporal();
                renderCart();
              }

              // 更新订单类型按钮状态（恢复外卖选项）
              if (typeof updateAllButtonStates === 'function') {
                updateAllButtonStates();
              }

              // 清空订单标题
              const orderTitle = document.getElementById('cart-order-title');
              if (orderTitle) {
                orderTitle.innerHTML = '';
              }

              // 清空桌位输入框
              const tableNumberInput = document.getElementById('table-number');
              if (tableNumberInput) {
                tableNumberInput.value = '';
                // 🔥 隐藏购物车上方的桌位号显示
                updateCurrentTableDisplay('');
              }

              // 判断返回目标并立即执行
              // 🔥 特殊逻辑：保存堂食订单后返回餐桌模块，方便继续为其他桌位服务
              // 🔥 优化：cambiarSeccion内部已经调用renderizarMesas，不需要重复调用
              if (tipo_pedido === 'servir' && table_number) {
                cambiarSeccion('mesas');
              } else {
                // 外卖订单返回收银模块
                cambiarSeccion('cajero');
              }
            }
            
            // 更新订单统计
            if (typeof updateOrderStats === 'function') {
              updateOrderStats();
            }
          } else {
            // 显示错误消息
            Swal.fire({
              icon: 'error',
              title: '❌ <?php echo ruiyi_translate("Error al crear pedido", "Error creating order", "创建订单时出错"); ?>',
              text: data.message || '<?php echo ruiyi_translate("Hubo un problema al procesar su pedido. Inténtelo de nuevo.", "There was a problem processing your order. Please try again.", "处理您的订单时出现问题。请重试。"); ?>',
              confirmButtonColor: '#f44336'
            });
            
            console.error('Error en la respuesta del servidor:', data);
          }
        })
        .catch(error => {
          // 网络或其他错误处理
          console.error('Error al crear pedido:', error);
          
          Swal.close();
          
          // Try to save offline as last resort
          if (typeof posDB !== 'undefined' && posDB && typeof posDB.addPendingOrder === 'function') {
            (async () => {
              try {
                if (!posDB.db) {
                  await posDB.init();
                }
                
                const tempOrderId = 'OFFLINE_' + Date.now();
                const orderToSave = {
                  id: tempOrderId,
                  cart: orderData.cart,
                  table_number: orderData.table_number,
                  order_type: orderData.order_type,
                  payment_method: orderData.payment_method,
                  tip_amount: orderData.tip_amount,
                  is_addition: orderData.is_addition,
                  discount: orderData.discount || 0,
                  client: orderData.client || '',
                  timestamp: Date.now(),
                  status: 'pending',
                  apiUrl: ajaxUrl
                };
                
                await posDB.addPendingOrder(orderToSave);

                // 🔥 简单的 Toast 提示（不弹窗）
                Toastify({
                  text: `✅ <?php echo ruiyi_translate('Completado', 'Completed', '已完成'); ?>`,
                  duration: 2000,
                  gravity: "top",
                  position: "center",
                  style: { background: "#10b981" }
                }).showToast();

                // 🔥 离线订单保存成功后：清空购物车（与在线模式一致）
                borrarPedidoTemporal();
                cart = [];
                renderCart();

                // 🔥 离线订单保存成功后：打开钱箱（现金支付时）
                if (orderData.payment_method === 'cash' || orderData.payment_method === 'mixed') {
                  try {
                    if (typeof abrirCajonDinero === 'function') {
                      await abrirCajonDinero();
                    }
                  } catch (drawerError) {
                    console.error('[离线结账] 打开钱箱失败:', drawerError);
                  }
                }

                // Trigger sync if online
                if (navigator.onLine && window.posSync) {
                  setTimeout(() => {
                    window.posSync.sync();
                  }, 1000);
                }
              } catch (dbError) {
                console.error('[PWA] Failed to save order offline in error handler:', dbError);
                Swal.fire({
                  icon: 'error',
                  title: '❌ <?php echo ruiyi_translate("Error de conexión", "Connection Error", "连接错误"); ?>',
                  text: '<?php echo ruiyi_translate("No se pudo comunicar con el servidor ni guardar localmente. Verifique su conexión a internet e inténtelo nuevamente.", "Could not communicate with the server or save locally. Please check your internet connection and try again.", "无法与服务器通信或本地保存。请检查您的网络连接并重试。"); ?>',
                  confirmButtonColor: '#f44336'
                });
              }
            })();
          } else {
          Swal.fire({
            icon: 'error',
            title: '❌ <?php echo ruiyi_translate("Error de conexión", "Connection Error", "连接错误"); ?>',
            text: '<?php echo ruiyi_translate("No se pudo comunicar con el servidor. Verifique su conexión a internet e inténtelo nuevamente.", "Could not communicate with the server. Please check your internet connection and try again.", "无法与服务器通信。请检查您的网络连接并重试。"); ?>',
            confirmButtonColor: '#f44336'
          });
          }
        });
      });
    }

