    // 添加餐桌选择弹窗功能
    function abrirSeleccionMesa() {
      // 获取当前保存的餐桌数据
      const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
      const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
      
      // 创建餐桌网格HTML
      let mesasHtml = `
        <div class="mb-4 text-gray-500 text-sm">
          <i class="fas fa-info-circle mr-1"></i> <?php echo ruiyi_translate('Selecciona una mesa para continuar', 'Select a table to continue', '选择一个餐桌来继续'); ?>
        </div>
        <div class="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-3 mt-3">
      `;
      
      // 循环生成餐桌按钮 - 使用分类显示名称
      for (let i = 1; i <= numberOfTablesConfig; i++) {
        const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
        const mesaId = `${tablePrefix} ${i}`; // 后端识别ID

        // 获取分类显示名称
        let tableDisplayName = mesaId; // 默认显示
        const tableMapping = Object.values(tableCategoryMappings).find(mapping =>
          parseInt(mapping.global_table_number) === i
        );
        if (tableMapping && tableMapping.category_display_name) {
          tableDisplayName = tableMapping.category_display_name;
        }

        let estado = '<?php echo ruiyi_translate("Libre","Free","空闲"); ?>';
        let icon = '<i class="fas fa-check-circle text-green-500 text-lg"></i>';
        let estadoClass = 'bg-green-50 border-green-200 text-green-800';
        let estadoText = '<?php echo ruiyi_translate("Libre", "Free", "空闲"); ?>';

        // 检查餐桌状态
        if (mesasEstado[mesaId]) {
          if (mesasEstado[mesaId].estado === 'ocupada') {
            estado = '<?php echo ruiyi_translate("Ocupada","Occupied","占用"); ?>';
            icon = '<i class="fas fa-users text-red-500 text-lg"></i>';
            estadoClass = 'bg-red-50 border-red-200 text-red-800';
            estadoText = '<?php echo ruiyi_translate("En uso", "In use", "使用中"); ?>';
          } else if (mesasEstado[mesaId].estado === 'solicitud_cuenta') {
            estado = 'solicitud_cuenta';
            icon = '<i class="fas fa-file-invoice-dollar text-yellow-500 text-lg"></i>';
            estadoClass = 'bg-yellow-50 border-yellow-200 text-yellow-800';
            estadoText = '<?php echo ruiyi_translate("Solicitud de cuenta", "Request for account", "请求结账"); ?>';
          }
        } else if (carritosGuardados[mesaId]) {
          estado = '<?php echo ruiyi_translate("Guardada","Saved","已保存"); ?>';
          icon = '<i class="fas fa-save text-blue-500 text-lg"></i>';
          estadoClass = 'bg-blue-50 border-blue-200 text-blue-800';
          estadoText = '<?php echo ruiyi_translate("Guardada", "Saved", "已保存"); ?>';
        }
        
        mesasHtml += `
          <button data-mesa="${mesaId}" data-estado="${estado}"
                  class="mesa-btn border-2 ${estadoClass} p-3 rounded-xl text-center transition-all transform hover:scale-105 flex flex-col items-center justify-center h-24">
            ${icon}
            <div class="font-bold mt-1">${tableDisplayName}</div>
            <div class="text-xs">${estadoText}</div>
          </button>
        `;
      }
      
      mesasHtml += '</div>';
      
      // 显示餐桌选择弹窗
      Swal.fire({
        title: '<span class="text-primary"><i class="fas fa-table mr-2"></i><?php echo ruiyi_translate("Seleccionar mesa", "Select table", "选择餐桌"); ?></span>',
        html: mesasHtml,
        showCancelButton: true,
        cancelButtonText: '<?php echo ruiyi_translate("Cancelar", "Cancel", "取消"); ?>',
        showConfirmButton: false,
        showCloseButton: true,
        width: '600px',
        customClass: {
          container: 'mesa-selector-modal',
          title: 'text-lg font-medium',
          cancelButton: 'bg-gray-200 hover:bg-gray-300 text-gray-800'
        }
      });
      
      // 绑定餐桌按钮事件
      setTimeout(() => {
        document.querySelectorAll('.mesa-btn').forEach(btn => {
          btn.addEventListener('click', function() {
            const mesaSeleccionada = this.getAttribute('data-mesa');
            const estado = this.getAttribute('data-estado');
            
            if (estado === 'ocupada' || estado === 'solicitud_cuenta') {
              Swal.fire({
                title: '<?php echo ruiyi_translate("Mesa ocupada", "Table occupied", "餐桌已被占用"); ?>',
                text: `${mesaSeleccionada} <?php echo ruiyi_translate("Actualmente en uso", "Currently in use", "目前正在使用中"); ?>. <?php echo ruiyi_translate("¿Crear nuevo pedido?", "Create new order?", "是否创建新订单?"); ?>`,
                icon: 'warning',
                showCancelButton: true,
                confirmButtonText: '<?php echo ruiyi_translate("Crear nuevo pedido", "Create new order", "创建新订单"); ?>',
                cancelButtonText: '<?php echo ruiyi_translate("Cancelar", "Cancel", "取消"); ?>'
              }).then((result) => {
                if (result.isConfirmed) {
                  cart = [];
                  document.getElementById('table-number').value = mesaSeleccionada;
                  // 🔥 更新购物车上方的桌位号显示
                  updateCurrentTableDisplay(mesaSeleccionada);
                  // 手动触发按钮更新
                  const currentOrderType = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir';
                  if (typeof updateOrderButtonForType === 'function') {
                    updateOrderButtonForType(currentOrderType);
                  }
                  // Discount functionality removed
                  renderCart();
                  Swal.close();
                }
              });
            } else if (estado === 'guardada') {
              Swal.fire({
                title: '<?php echo ruiyi_translate("Cargar pedido guardado", "Load saved order", "加载已保存的订单"); ?>?',
                text: `${mesaSeleccionada} <?php echo ruiyi_translate("Tiene un pedido guardado", "Has a saved order", "有已保存的订单"); ?>. <?php echo ruiyi_translate("¿Cargar?", "Load?", "要加载它吗?"); ?>`,
                icon: 'question',
                showCancelButton: true,
                showDenyButton: true,
                confirmButtonText: '<?php echo ruiyi_translate("Cargar pedido", "Load order", "加载订单"); ?>',
                denyButtonText: '<?php echo ruiyi_translate("Crear nuevo pedido", "Create new order", "创建新订单"); ?>',
                cancelButtonText: '<?php echo ruiyi_translate("Cancelar", "Cancel", "取消"); ?>'
              }).then((result) => {
                if (result.isConfirmed) {
                  cargarCarritoMesa(mesaSeleccionada);
                  Swal.close();
                } else if (result.isDenied) {
                  cart = [];
                  document.getElementById('table-number').value = mesaSeleccionada;
                  // 🔥 更新购物车上方的桌位号显示
                  updateCurrentTableDisplay(mesaSeleccionada);
                  // 手动触发按钮更新
                  const currentOrderType = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir';
                  if (typeof updateOrderButtonForType === 'function') {
                    updateOrderButtonForType(currentOrderType);
                  }
                  // Discount functionality removed
                  renderCart();
                  Swal.close();
                }
              });
            } else {
              // 空闲餐桌
              document.getElementById('table-number').value = mesaSeleccionada;
              // 🔥 更新购物车上方的桌位号显示
              updateCurrentTableDisplay(mesaSeleccionada);
              // 手动触发按钮更新
              const currentOrderType = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir';
              if (typeof updateOrderButtonForType === 'function') {
                updateOrderButtonForType(currentOrderType);
              }
              // Discount functionality removed
              cart = [];
              renderCart();
              
              Toastify({
                text: `✅ <?php echo ruiyi_translate("Mesa seleccionada", "Table selected", "已选择餐桌"); ?> ${mesaSeleccionada}`,
                duration: 2000,
                gravity: "top",
                position: "center",
                style: { background: "#4caf50" }
              }).showToast();
              
              Swal.close();
            }
          });
        });
      }, 0);
    }

    // Función para inicializar la configuración visual del POS
    function initPOSInterface() {
      // Activar tooltips si existen
      const tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'));
      if (typeof bootstrap !== 'undefined' && tooltipTriggerList.length > 0) {
        tooltipTriggerList.map(function (tooltipTriggerEl) {
          return new bootstrap.Tooltip(tooltipTriggerEl);
        });
      }
      
      // Agregar eventos a los botones de acciones rápidas
      const actionCards = document.querySelectorAll('.action-card');
      actionCards.forEach(card => {
        card.addEventListener('click', function(e) {
          const href = this.getAttribute('href');
          if (href && href.startsWith('#')) {
            e.preventDefault();
            const targetSection = document.getElementById(href.substring(1));
            if (targetSection) {
              // Ocultar todas las secciones
              const sections = document.querySelectorAll('main > section');
              sections.forEach(section => {
                section.classList.add('hidden');
              });
              
              // Mostrar la sección seleccionada
              targetSection.classList.remove('hidden');
              
              // Actualizar los enlaces del menú
              const menuLinks = document.querySelectorAll('.menu-link');
              menuLinks.forEach(link => {
                link.classList.remove('bg-red-600', 'text-white');
                if (link.getAttribute('href') === href) {
                  link.classList.add('bg-red-600', 'text-white');
                }
              });
            }
          }
        });
      });
      
      // 初始化收银员功能
      initCajeroFunctions();
    }

    // ========================================
    // 🔥 分区价格计算相关函数
    // ========================================

    /**
     * 获取当前选中桌位的分区ID
     * @returns {number|null} 分类ID，未选择桌位时返回null
     */
    function getCurrentTableCategoryId() {
      const tableNumber = document.getElementById('table-number')?.value.trim();
      if (!tableNumber) return null;

      const mapping = getTableMappingByTableName(tableNumber);
      return mapping ? parseInt(mapping.category_id, 10) : null;
    }

    /**
     * 根据当前分区获取产品的实际价格
     * @param {number} basePrice 基础价格
     * @param {Object} zonePrices 分区价格对象 {category_1: 1.30, category_2: 1.50}
     * @param {number|null} categoryId 分区ID（可选，不传则自动获取当前桌位分区）
     * @returns {number} 实际价格
     */
    function getProductPriceForCurrentZone(basePrice, zonePrices, categoryId = null) {
      // 如果没有分区价格设置，直接返回基础价格
      if (!zonePrices || typeof zonePrices !== 'object' || Object.keys(zonePrices).length === 0) {
        return basePrice;
      }

      // 如果没有指定分区ID，获取当前桌位的分区ID
      const targetCategoryId = categoryId !== null ? categoryId : getCurrentTableCategoryId();

      // 如果没有选择桌位（外卖/无桌位），使用基础价格
      if (targetCategoryId === null) {
        return basePrice;
      }

      // 检查是否有该分区的自定义价格
      const zoneKey = 'category_' + targetCategoryId;
      if (zonePrices[zoneKey] !== undefined && zonePrices[zoneKey] !== null && zonePrices[zoneKey] !== '') {
        return parseFloat(zonePrices[zoneKey]);
      }

      // 没有设置该分区价格，使用基础价格
      return basePrice;
    }

    /**
     * 解析产品卡片上的分区价格数据
     * @param {HTMLElement} productCard 产品卡片元素
     * @returns {Object} 分区价格对象
     */
    function parseZonePrices(productCard) {
      const zonePricesStr = productCard.getAttribute('data-zone-prices');
      if (!zonePricesStr) return {};

      try {
        return JSON.parse(zonePricesStr);
      } catch (e) {
        console.warn('Failed to parse zone prices:', e);
        return {};
      }
    }

    /**
     * 根据当前选中桌位的分区，更新所有产品卡片上显示的价格
     * @param {boolean} forceBasePrice 为true时强制显示原价（忽略分区价格）
     */
    function updateAllProductCardPrices(forceBasePrice) {
      const categoryId = forceBasePrice ? null : getCurrentTableCategoryId();

      document.querySelectorAll('.product-card[data-id]').forEach(card => {
        const priceEl = card.querySelector('.product-price');
        if (!priceEl) return;

        // 跳过自助餐产品
        if (card.getAttribute('data-is-buffet') === '1') return;

        const basePrice = parseFloat(card.getAttribute('data-price')) || 0;
        const zonePrices = parseZonePrices(card);
        const actualPrice = getProductPriceForCurrentZone(basePrice, zonePrices, categoryId);

        priceEl.textContent = '€' + actualPrice.toFixed(2);
      });
    }

    // 🔥 全局产品点击处理函数（供懒加载模块使用）
    window.handleProductClick = function(card, e) {
      handleProductCardClick(card, e || { preventDefault: () => {}, stopPropagation: () => {} });
    };

    function getCartItemEffectivePrice(item) {
      return parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0));
    }

    function getCartItemNotesKey(item) {
      return (item && item.notes ? String(item.notes).trim() : '');
    }

    function getCartItemSupplementsKey(item) {
      if (!item || !Array.isArray(item.supplements) || item.supplements.length === 0) {
        return '';
      }
      return item.supplements
        .map(s => [String(s.id || ''), String(s.name || ''), parseFloat(s.price || 0).toFixed(2)].join(':'))
        .sort()
        .join('|');
    }

    function normalizeCartCategoryIds(raw) {
      if (typeof raw === 'string') {
        raw = raw.split(/[,\s]+/);
      } else if (!Array.isArray(raw)) {
        raw = [raw];
      }
      return raw.map(function(id) {
        if (id && typeof id === 'object') {
          id = id.term_id || id.id || 0;
        }
        return parseInt(id, 10);
      }).filter(function(id) { return id > 0; });
    }

    function getCartLineModifiersKey(item) {
      return [
        item && item.customName ? String(item.customName).trim() : '',
        getCartItemNotesKey(item),
        getCartItemSupplementsKey(item)
      ].join('||');
    }

    function cartItemHasLineModifiers(item) {
      return !!(
        (item && item.customName && String(item.customName).trim()) ||
        getCartItemNotesKey(item) ||
        getCartItemSupplementsKey(item)
      );
    }

    function canMergeUnlockedCartLine(item, productId, unitPrice) {
      return item &&
        item.id === productId &&
        !item.locked &&
        !cartItemHasLineModifiers(item) &&
        Math.abs(getCartItemEffectivePrice(item) - parseFloat(unitPrice || 0)) < 0.01;
    }

    function canMergeLockedSyncedLine(existingItem, syncedItem) {
      return existingItem &&
        syncedItem &&
        existingItem.locked &&
        existingItem.id === syncedItem.id &&
        getCartLineModifiersKey(existingItem) === getCartLineModifiersKey(syncedItem) &&
        Math.abs(getCartItemEffectivePrice(existingItem) - getCartItemEffectivePrice(syncedItem)) < 0.01;
    }

    // 产品卡片点击处理逻辑（抽取为独立函数）
    function handleProductCardClick(card, e) {
      // 如果在排序模式，阻止点击事件
      if (card.classList.contains('sorting-active')) {
        e.preventDefault();
        e.stopPropagation();
        return false;
      }

      // 🔥 检查是否是分类自由价格产品
      const isCategoryPriceProduct = card.getAttribute('data-category-price-product') === '1';
      if (isCategoryPriceProduct) {
        e.preventDefault();
        e.stopPropagation();
        window.showCategoryPriceNumberpad(card);
        return false;
      }

      const id = parseInt(card.getAttribute('data-id'));
      const name = card.getAttribute('data-name'); // 多语言名称（仅用于产品卡片显示）
      const name_es = card.getAttribute('data-name-es'); // 西班牙语名称（原产品名称）
      const name_zh = card.getAttribute('data-name-zh'); // 中文名称
      const name_en = card.getAttribute('data-name-en'); // 英文名称

      // 🔥 获取基础价格和分区价格
      const basePrice = parseFloat(card.getAttribute('data-price'));
      const zonePrices = parseZonePrices(card);
      const currentCategoryId = getCurrentTableCategoryId();

      // 🔥 根据当前分区计算实际价格
      let price = getProductPriceForCurrentZone(basePrice, zonePrices, currentCategoryId);

      // 🍽️ 检查是否为自助餐产品
      const isBuffet = card.getAttribute('data-is-buffet') === '1' || (typeof window.isBuffetProduct === 'function' && window.isBuffetProduct(id));

      const taxRate = parseFloat(card.getAttribute('data-tax-rate')) || 10; // Default 10%
      const image_url = card.getAttribute('data-image');

      // Check if this is a special category product (first product only)
      const isSpecialCategory = card.getAttribute('data-special-category') === '1';
      const isFirstSpecial = card.getAttribute('data-is-first-special') === '1';

      // If it's a special category product (and first in category), show numberpad
      if (isSpecialCategory && isFirstSpecial) {
        e.preventDefault();
        e.stopPropagation();
        showNumberpad(card);
        return false;
      }

      // 🔥 Check if this is a scale product and get current weight
      const isScaleProduct = card.getAttribute('data-is-scale-product') === '1' || card.getAttribute('data-is-scale-product') === 'true';
      let weight = null;
      let calculatedTotalPrice = null;

      if (isScaleProduct && typeof scaleConfig !== 'undefined' && scaleConfig.enabled && typeof scaleState !== 'undefined' && scaleState && scaleState.latestWeight !== null) {
        weight = scaleState.latestWeight;
        // Calculate total price: price per kg * weight (only for total, not base price)
        // 🔥 修复：使用 toFixed(2) 避免浮点数精度问题
        calculatedTotalPrice = parseFloat((price * weight).toFixed(2));
      }

      // 检查是否在查看模式
      const viewMode = sessionStorage.getItem('tableViewMode');
      const isViewMode = viewMode ? JSON.parse(viewMode) : null;

      // 🔥🔥🔥 关键修复：检查商品是否已在购物车中
      // 优先查找未锁定的相同产品，如果没有则查找已锁定的
      // 修复：!item.locked 导致锁定商品被跳过，造成重复条目
      // 🔥🔥🔥 新增：如果商品名称被修改了（有customName），则不叠加，添加为新行

      // 步骤1：先查找未锁定的相同产品（可以直接增加数量）
      // 🔥 关键：如果商品有customName（名称被修改）或备注，则不叠加
      let existingItemIndex = cart.findIndex(item => canMergeUnlockedCartLine(item, id, price));

      // 🔥🔥🔥【2026-04-08】不再合并到 locked 项 — 新添加的产品作为独立未锁定行显示
      // 用户期望：新产品独立显示，便于区分"已保存"和"新添加"；保存时由 sync return 路径自动合并。
      // 之前"找不到未锁定则合并 locked"的写法已回滚。

      // 🔥 标记是否是添加新产品（用于控制滚动行为）
      let isAddingNewProduct = false;

      if (existingItemIndex !== -1) {
        // 找到未锁定的相同产品，增加数量
        cart[existingItemIndex].quantity += 1;
        // 🔥 追踪本次新增数量（用于厨房打印）
        cart[existingItemIndex].addedQuantity = (cart[existingItemIndex].addedQuantity || 0) + 1;

        // 在查看模式下，标记为新增
        if (isViewMode && cart[existingItemIndex].isNew) {
          cart[existingItemIndex].isNew = true;
        }
        // 🔥 自动选中该产品
        selectedCartItemIndex = existingItemIndex;
        window.selectedCartItemIndex = existingItemIndex;
      } else {
        // 🔥 这是添加新产品
        isAddingNewProduct = true;
        // 否则添加新商品
        const cartItem = {
          id,
          name: name_es || name, // 🔥 购物车始终使用原产品名称（西班牙语）
          name_es: name_es || name, // 西班牙语名称（用于小票打印）
          name_zh: name_zh || '', // 中文名称
          name_en: name_en || '', // 英文名称
          price: isBuffet ? 0 : price, // 🍽️ 自助餐产品价格为0
          originalPrice: price, // 🍽️ 保留原始价格
          basePrice: basePrice, // 🔥 保存基础价格
          zoneCategoryId: currentCategoryId, // 🔥 保存使用的分区ID（用于后端验证）
          quantity: 1,
          addedQuantity: 1, // 🔥 追踪本次新增数量（用于厨房打印）
          taxRate: taxRate, // Include tax rate
          image_url,
          isNew: isViewMode ? true : false, // 在查看模式下标记为新增
          locked: false, // 新添加的商品不锁定
          is_buffet: isBuffet, // 🍽️ 自助餐标记
          is_free: card.getAttribute('data-is-free') === '1', // 🔥 免费产品标记
          categoryIds: (card.getAttribute('data-categories') || '').split(' ').filter(c => c).map(Number) // 🔥 产品分类IDs（用于配料筛选）
        };

        // 🔥 分区价格：如果实际价格与基础价格不同，设置 customPrice 确保后端使用正确价格
        if (!isBuffet && currentCategoryId && price !== basePrice) {
          cartItem.customPrice = price;
        }

        // 🔥 For scale products, store weight and calculated total price in customPrice
        if (isScaleProduct && weight !== null && calculatedTotalPrice !== null) {
          cartItem.isScaleProduct = true;
          cartItem.weight = weight;
          cartItem.unitPrice = price; // Store original price per kg
          cartItem.customPrice = calculatedTotalPrice; // Store calculated total price (price * weight)
        }

        cart.push(cartItem);
        // 🔥 自动选中新添加的产品（最后一个）
        selectedCartItemIndex = cart.length - 1;
        window.selectedCartItemIndex = cart.length - 1;
      }

      // 更新购物车显示
      // 🔥🔥🔥 关键修复：只在添加新产品时才滚动到底部
      renderCart({ scrollToBottom: isAddingNewProduct });
    }

    // 收银员模块功能初始化
    function initCajeroFunctions() {
      // 🔥 使用事件委托处理产品点击（支持懒加载的产品）
      const productsContainer = document.querySelector('.products-container');
      if (productsContainer) {
        productsContainer.addEventListener('click', function(e) {
          const card = e.target.closest('.product-card');
          if (card) {
            handleProductCardClick(card, e);
          }
        });
      }

      // 🔥 Suplementos区域也使用事件委托
      const suplementosSection = document.querySelector('.suplementos-section');
      if (suplementosSection) {
        suplementosSection.addEventListener('click', function(e) {
          const card = e.target.closest('.product-card');
          if (card) {
            handleProductCardClick(card, e);
          }
        });
      }

      // 🔥 注意：产品点击事件已通过事件委托处理，不再需要直接绑定
      
      // 产品分类过滤功能
      let currentCategory = 'all';

      function normalizeProductSearchValue(value) {
        return (value || '')
          .toString()
          .toLowerCase()
          .normalize('NFD')
          .replace(/[\u0300-\u036f]/g, '')
          .trim();
      }

      function matchesProductSearchFuzzy(searchTerm, values) {
        const normalizedSearch = normalizeProductSearchValue(searchTerm);
        if (!normalizedSearch) {
          return true;
        }

        return values.some(value => {
          const normalizedValue = normalizeProductSearchValue(value);
          return normalizedValue.includes(normalizedSearch);
        });
      }

      // 产品分类过滤函数（支持搜索）
      function filterProducts() {
        const productCards = document.querySelectorAll('.product-card');
        let visibleCount = 0;
        let hiddenCount = 0;
        let zeropriceCount = 0;

        // 获取搜索关键词（使用全局变量，转小写用于不区分大小写匹配）
        const searchTerm = (window.productSearchTerm || '').toLowerCase().trim();

        productCards.forEach(card => {
          const productCategories = card.getAttribute('data-categories') || '';
          const productPrice = parseFloat(card.getAttribute('data-price') || '0');
          const productName = (card.getAttribute('data-name') || '').toLowerCase();
          const productNameEs = (card.getAttribute('data-name-es') || '').toLowerCase();
          const productNameZh = (card.getAttribute('data-name-zh') || '').toLowerCase();
          const productNameEn = (card.getAttribute('data-name-en') || '').toLowerCase();

          // CRITICAL FIX: Skip filtering for Suplementos products
          // Suplementos products should always be visible regardless of category filter
          const isInSuplementosSection = card.closest('.suplementos-section') !== null;
          if (isInSuplementosSection) {
            // 即使是Suplementos，也要检查搜索条件
            if (searchTerm) {
              const matchesSearch = matchesProductSearchFuzzy(searchTerm, [
                productName,
                productNameEs,
                productNameZh,
                productNameEn,
                card.getAttribute('data-sku') || ''
              ]);
              if (!matchesSearch) {
                card.classList.add('product-hidden');
                hiddenCount++;
                return;
              }
            }
            // Always keep Suplementos products visible (if matches search)
            card.classList.remove('product-hidden');
            card.style.display = '';  // 清除内联样式
            visibleCount++;
            return; // Skip category filtering for Suplementos
          }

          // 🔥 分类自由价格产品跳过价格检查
          const isCategoryPriceProduct = card.getAttribute('data-category-price-product') === '1';

          // 🔥 检查价格是否为0 - 自助餐、免费产品、分类自由价格产品除外
          const isFreeProduct = card.getAttribute('data-is-free') === '1';
          const isBuffetProduct = card.getAttribute('data-is-buffet') === '1';
          if (!isCategoryPriceProduct && !isFreeProduct && !isBuffetProduct && (productPrice === 0 || productPrice <= 0)) {
            card.classList.add('product-hidden');
            zeropriceCount++;
            return; // 跳过后续检查
          }

          // 检查搜索条件
          let matchesSearch = true;
          if (searchTerm) {
            matchesSearch = matchesProductSearchFuzzy(searchTerm, [
              productName,
              productNameEs,
              productNameZh,
              productNameEn,
              card.getAttribute('data-sku') || ''
            ]);
          }

          // 检查分类条件 - 使用精确匹配
          let matchesCategory = false;
          if (currentCategory === 'all') {
            matchesCategory = true;
          } else {
            // 将分类ID字符串分割成数组，然后检查是否包含当前分类
            const categoryArray = productCategories.split(' ').filter(cat => cat !== '');
            matchesCategory = categoryArray.includes(currentCategory);
          }

          // 同时满足搜索和分类条件才显示 - 使用CSS类控制（避免!important覆盖）
          if (matchesCategory && matchesSearch) {
            card.classList.remove('product-hidden');
            card.style.display = '';  // 清除内联样式，让CSS类控制
            visibleCount++;
          } else {
            card.classList.add('product-hidden');
            hiddenCount++;
          }
        });



        // 强制浏览器重新渲染
        const container = document.querySelector('.products-container');
        if (container) {
          container.style.display = 'none';
          container.offsetHeight; // 触发重排
          container.style.display = '';
        }
      }

      // 初始化分类按钮功能
      let categoryFilteringRetryCount = 0;
      const MAX_RETRY_COUNT = 10; // 最多重试10次（5秒）

      // 🔥 层级导航全局变量
      let categoryNavigationStack = []; // 导航栈：[{id, name, hasChildren, depth}, ...]
      let currentCategoryId = null;
      let categoryChildrenCache = {}; // 子分类缓存
      // 🔥 暴露到全局作用域，使其他 script 块可以访问
      window.activeCategoryIds = window.activeCategoryIds || []; // 当前选中分类及其所有子孙分类ID

      function scrollCashierProductsToTop() {
        window.requestAnimationFrame(() => {
          const productsContainer = document.querySelector('.products-container');
          if (!productsContainer) {
            return;
          }

          const scrollPanel = productsContainer.closest('.overflow-y-auto');
          if (scrollPanel) {
            scrollPanel.scrollTop = 0;
            return;
          }

          productsContainer.scrollIntoView({ block: 'start', behavior: 'auto' });
        });
      }

      function initializeCategoryFiltering() {
        // 🔥 从配置初始化 activeCategoryIds（如果尚未设置）
        if (window.activeCategoryIds.length === 0 && window.RUIYI_POS_CONFIG && window.RUIYI_POS_CONFIG.firstCategoryAllIds) {
          window.activeCategoryIds = window.RUIYI_POS_CONFIG.firstCategoryAllIds.slice(); // 使用 slice() 创建副本
        }

        const categoryButtons = document.querySelectorAll('#level-1-categories .category-btn');
        const productCards = document.querySelectorAll('.product-card');

        if (categoryButtons.length === 0 || productCards.length === 0) {
          // 🔥 检查是否在产品页面（如果不在，不需要重试）
          const productSection = document.getElementById('productos');
          if (!productSection || productSection.classList.contains('hidden')) {
            return;
          }

          // 🔥 添加重试次数限制，避免无限重试
          categoryFilteringRetryCount++;
          if (categoryFilteringRetryCount > MAX_RETRY_COUNT) {
            console.warn('[分类过滤] 重试次数已达上限，停止重试');
            return;
          }

          setTimeout(initializeCategoryFiltering, 500);
          return;
        }

        // 🔥 重置重试计数器
        categoryFilteringRetryCount = 0;

        // 🔥 初始化层级导航
        initializeCategoryHierarchy();

        // 初始化时默认选中第一个产品分类（🔥 直接设置样式，不触发 click 事件）
        const firstCategoryButton = document.querySelector('#level-1-categories .category-btn');
        if (firstCategoryButton) {
          const categoryId = parseInt(firstCategoryButton.getAttribute('data-category'));

          // 🔥 使用配置的选中颜色，而不是硬编码的颜色
          const categoryColors = window.RUIYI_POS?.categoryColors ?? {
            selected: { bg: '#E05C40', text: '#FFFFFF' }
          };
          const selectedBg = categoryColors.selected?.bg || '#E05C40';
          const selectedText = categoryColors.selected?.text || '#FFFFFF';

          // 🔥 直接设置按钮样式
          firstCategoryButton.classList.add('active-category');
          firstCategoryButton.style.backgroundColor = selectedBg;
          firstCategoryButton.style.color = selectedText;
          firstCategoryButton.style.border = '2px solid ' + selectedBg;

          // 🔥 使用预加载的分类 ID（同步，无 AJAX）
          if (window.RUIYI_POS_CONFIG && window.RUIYI_POS_CONFIG.firstCategoryAllIds) {
            window.activeCategoryIds = window.RUIYI_POS_CONFIG.firstCategoryAllIds.slice();
          } else {
            // 回退：使用同步获取
            window.activeCategoryIds = getCategoryDescendantsSync(categoryId);
          }

          // 🔥 同步过滤产品（无延迟）
          filterProductsHierarchical();
        } else {
          // 如果没有分类按钮，显示所有产品
          currentCategory = 'all';
          filterProducts();
        }

        // 更新分类按钮的多语言显示文本
        updateCategoryButtonsText();
    }

    // 🔥 初始化层级导航
    function initializeCategoryHierarchy() {
      // 绑定一级分类按钮点击
      bindCategoryButtons('#level-1-categories .category-btn');

      // 绑定返回按钮
      const backBtn = document.getElementById('back-to-parent');
      if (backBtn) {
        backBtn.addEventListener('click', navigateBack);
      }

      // 绑定面包屑首页点击
      const breadcrumbHome = document.querySelector('#category-breadcrumb .breadcrumb-item[data-category-id="0"]');
      if (breadcrumbHome) {
        breadcrumbHome.addEventListener('click', () => navigateToBreadcrumb(0));
      }
    }

    // 🔥 绑定分类按钮点击事件
    function bindCategoryButtons(selector) {
      const buttons = document.querySelectorAll(selector);

      buttons.forEach((button, index) => {
        // 移除已有的事件监听器（通过克隆）
        const newButton = button.cloneNode(true);
        button.parentNode.replaceChild(newButton, button);

        newButton.addEventListener('click', function(e) {
          e.preventDefault();
          const categoryId = parseInt(this.getAttribute('data-category'));
          const categoryNameEl = this.querySelector('.category-name') || this.querySelector('span');
          const categoryName = categoryNameEl ? categoryNameEl.textContent.trim() : '';
          const hasChildren = this.getAttribute('data-has-children') === '1';
          const depth = parseInt(this.getAttribute('data-depth')) || 1;
          // 🔥 使用配置的选中颜色
          const color = window.RUIYI_POS?.categoryColors?.selected?.bg || '#E05C40';

          handleCategoryClick(categoryId, categoryName, hasChildren, depth, color);
        });
      });
    }

    // 🔥 处理分类点击
    function handleCategoryClick(categoryId, categoryName, hasChildren, depth, color) {

      // 更新当前分类ID
      currentCategoryId = categoryId;
      currentCategory = categoryId.toString();

      // 🔥 修复：一级分类重置导航栈（不累积）
      if (depth === 1) {
        // 一级分类：只保留当前分类
        categoryNavigationStack = [{
          id: categoryId,
          name: categoryName,
          hasChildren: hasChildren,
          depth: depth,
          color: color
        }];
      } else {
        // 子分类：检查是否已在栈中
        const existingIndex = categoryNavigationStack.findIndex(item => item.id === categoryId);
        if (existingIndex >= 0) {
          categoryNavigationStack = categoryNavigationStack.slice(0, existingIndex + 1);
        } else {
          // 🔥 修复：同级子分类切换时，替换栈中同depth的项
          // 检查栈中是否已有同级分类（同depth），如果有则替换
          const sameLevelIndex = categoryNavigationStack.findIndex(item => item.depth === depth);
          if (sameLevelIndex >= 0) {
            // 替换同级分类
            categoryNavigationStack = categoryNavigationStack.slice(0, sameLevelIndex);
          }
          // 添加新分类到栈
          categoryNavigationStack.push({
            id: categoryId,
            name: categoryName,
            hasChildren: hasChildren,
            depth: depth,
            color: color
          });
        }
      }

      // 更新所有分类按钮样式
      updateAllCategoryButtonStyles(categoryId);

      // 更新面包屑
      updateBreadcrumb();

      // 如果有子分类，加载并显示；否则隐藏子分类容器
      if (hasChildren) {
        loadChildCategories(categoryId, categoryName);
      } else {
        // 🔥 无子分类 → 隐藏子分类容器（无论一级还是二级）
        hideChildCategories();
      }

      // 🔥 获取所有子孙分类ID用于产品筛选（同步，无延迟）
      const categoryIds = getCategoryDescendantsSync(categoryId);
      window.activeCategoryIds = categoryIds.map(id => parseInt(id, 10)).filter(id => !isNaN(id));
      // 🔥 立即应用过滤
      filterProductsHierarchical();
      scrollCashierProductsToTop();
      // // console.log('[分类过滤] 点击分类', categoryId, '，过滤产品使用IDs:', window.activeCategoryIds);
    }

    // 🔥 更新所有分类按钮样式
    function updateAllCategoryButtonStyles(activeCategoryId) {
      // 🔥 获取分类颜色设置
      const categoryColors = window.RUIYI_POS?.categoryColors ?? {
        selected: { bg: '#E05C40', text: '#FFFFFF' },
        unselected: { bg: '#E05C40', bgIntensity: 19, text: '#C45A3B', border: '#E05C40' }
      };
      const unselectedOpacity = window.RUIYI_POS?.categoryUnselectedOpacity ?? 1;
      // 🔥 计算背景浓度的十六进制值
      const bgIntensityHex = window.RUIYI_POS?.percentToHex?.(categoryColors.unselected.bgIntensity || 19) || '30';

      // 更新一级分类按钮
      document.querySelectorAll('#level-1-categories .category-btn').forEach(btn => {
        const btnCategoryId = parseInt(btn.getAttribute('data-category'));
        // 🔥 获取分类的自定义颜色
        const customColor = btn.getAttribute('data-custom-color') || '';

        if (btnCategoryId === activeCategoryId || categoryNavigationStack.some(item => item.id === btnCategoryId)) {
          // 激活状态 - 使用选中颜色设置（如果有自定义颜色，使用自定义颜色作为选中背景）
          btn.classList.add('active-category');
          const selectedBg = customColor || categoryColors.selected.bg;
          btn.style.backgroundColor = selectedBg;
          btn.style.color = categoryColors.selected.text;
          btn.style.border = '2px solid ' + selectedBg;
          btn.style.textShadow = 'none';
          btn.style.opacity = '1'; // 选中状态始终完全不透明
        } else {
          // 非激活状态 - 使用自定义颜色或默认未选中颜色
          btn.classList.remove('active-category');
          const unselectedBg = customColor || categoryColors.unselected.bg;
          const unselectedBorder = customColor || categoryColors.unselected.border;
          btn.style.backgroundColor = unselectedBg + bgIntensityHex;
          btn.style.color = categoryColors.unselected.text;
          btn.style.border = '2px solid ' + unselectedBorder;
          btn.style.textShadow = 'none';
          btn.style.opacity = unselectedOpacity; // 🔥 应用透明度设置
        }
      });

      // 更新子分类按钮
      const subcategoryTextColor = window.RUIYI_POS?.categoryColors?.subcategoryText || categoryColors.unselected.text;
      document.querySelectorAll('#child-categories-grid .category-btn').forEach(btn => {
        const btnCategoryId = parseInt(btn.getAttribute('data-category'));
        // 🔥 获取分类的自定义颜色
        const customColor = btn.getAttribute('data-custom-color') || '';

        if (btnCategoryId === activeCategoryId) {
          btn.classList.add('active-category');
          const selectedBg = customColor || categoryColors.selected.bg;
          btn.style.backgroundColor = selectedBg;
          btn.style.color = categoryColors.selected.text;
          btn.style.border = '2px solid ' + selectedBg;
          btn.style.textShadow = 'none';
          btn.style.opacity = '1'; // 选中状态始终完全不透明
        } else {
          // 非激活状态 - 使用自定义颜色或默认未选中颜色
          btn.classList.remove('active-category');
          const unselectedBg = customColor || categoryColors.unselected.bg;
          const unselectedBorder = customColor || categoryColors.unselected.border;
          btn.style.backgroundColor = unselectedBg + bgIntensityHex;
          btn.style.color = subcategoryTextColor;
          btn.style.border = '2px solid ' + unselectedBorder;
          btn.style.textShadow = 'none';
          btn.style.opacity = unselectedOpacity; // 🔥 应用透明度设置
        }
      });
    }

    // 🔥 加载子分类
    function loadChildCategories(parentId, parentName) {
      // 检查缓存
      if (categoryChildrenCache[parentId]) {
        renderChildCategories(categoryChildrenCache[parentId], parentName);
        return;
      }

      // AJAX获取子分类
      jQuery.ajax({
        url: ruiyi_ajax.ajax_url,
        type: 'POST',
        data: {
          action: 'ruiyi_get_child_categories',
          nonce: ruiyi_ajax.nonce,
          parent_id: parentId
        },
        success: function(response) {
          if (response.success && response.data.children) {
            // 缓存结果
            categoryChildrenCache[parentId] = response.data.children;
            renderChildCategories(response.data.children, parentName);
          }
        },
        error: function(xhr, status, error) {
          console.error('[层级导航] 加载子分类失败:', error);
        }
      });
    }

    // 🔥 渲染子分类按钮
    function renderChildCategories(children, parentName) {
      const container = document.getElementById('child-categories-container');
      const grid = document.getElementById('child-categories-grid');
      const parentNameEl = document.getElementById('current-parent-name');

      if (!container || !grid) return;

      // 设置父分类名称
      if (parentNameEl) {
        parentNameEl.textContent = '<?php echo ruiyi_translate("Subcategorías de", "Subcategories of", "子分类："); ?> ' + parentName;
      }

      // 清空现有内容
      grid.innerHTML = '';

      // 获取字体大小设置
      const fontSize = '<?php echo esc_attr(get_option('pos_category_font_size', '10')); ?>';
      const escapeHtml = (value) => String(value || '').replace(/[&<>"']/g, (char) => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#039;'
      }[char]));

      // 🔥 获取配置的颜色
      const childCategoryColors = window.RUIYI_POS?.categoryColors ?? {
        unselected: { bg: '#E05C40', bgIntensity: 19, text: '#C45A3B', border: '#E05C40' }
      };
      const childBgIntensityHex = window.RUIYI_POS?.percentToHex?.(childCategoryColors.unselected?.bgIntensity || 19) || '30';

      // 渲染子分类按钮
      children.forEach(child => {
        const btn = document.createElement('button');
        btn.setAttribute('data-category', child.term_id);
        btn.setAttribute('data-has-children', child.has_children ? '1' : '0');
        btn.setAttribute('data-depth', child.depth);
        // 🔥 添加自定义颜色属性
        btn.setAttribute('data-custom-color', child.bg_color || '');
        btn.className = 'category-btn category-card-btn px-1.5 py-2 rounded transition flex items-center justify-center text-center min-h-[45px] hover:opacity-80 relative';
        if (child.image_url) {
          btn.classList.add('category-btn-has-image');
        }

        // 🔥 使用自定义颜色或默认颜色
        const customBg = child.bg_color || '';
        const bgColor = customBg || (childCategoryColors.unselected?.bg || '#E05C40');
        const borderColor = customBg || (childCategoryColors.unselected?.border || '#E05C40');

        btn.style.backgroundColor = bgColor + childBgIntensityHex;
        btn.style.color = window.RUIYI_POS?.categoryColors?.subcategoryText || childCategoryColors.unselected?.text || '#C45A3B';
        btn.style.border = '2px solid ' + borderColor;

        // 使用多语言名称
        const displayName = child['name_<?php echo $current_language; ?>'] || child.name_es || child.name;

        const fontBoldClass = <?php echo json_encode(get_option('pos_category_font_bold', '0') === '1'); ?> ? 'font-bold' : 'font-medium';
        const imageHtml = child.image_url
          ? `<img class="category-card-image" src="${escapeHtml(child.image_url)}" alt="${escapeHtml(displayName)}" loading="lazy" decoding="async">`
          : '';
        btn.innerHTML = `
          ${imageHtml}
          <span class="category-name ${fontBoldClass} leading-tight" style="font-size: ${fontSize}px; max-width: 100%;">${escapeHtml(displayName)}</span>
          ${child.has_children ? '<i class="fas fa-chevron-right absolute right-1 top-1 text-xs opacity-70"></i>' : ''}
        `;

        grid.appendChild(btn);
      });

      // 绑定新按钮的点击事件
      bindCategoryButtons('#child-categories-grid .category-btn');

      // 显示容器
      container.classList.remove('hidden');
    }

    // 🔥 隐藏子分类
    function hideChildCategories() {
      const container = document.getElementById('child-categories-container');
      if (container) {
        container.classList.add('hidden');
      }
    }

    // 🔥 更新面包屑
    function updateBreadcrumb() {
      const breadcrumb = document.getElementById('category-breadcrumb');
      if (!breadcrumb) return;

      const nav = breadcrumb.querySelector('nav');
      if (!nav) return;

      // 保留首页按钮，移除其他面包屑项
      const homeBtn = nav.querySelector('.breadcrumb-item[data-category-id="0"]');
      nav.innerHTML = '';
      if (homeBtn) {
        nav.appendChild(homeBtn);
      }

      // 添加导航栈中的分类
      categoryNavigationStack.forEach((item, index) => {
        // 添加分隔符
        const separator = document.createElement('span');
        separator.className = 'text-gray-400';
        separator.innerHTML = '<i class="fas fa-chevron-right text-xs"></i>';
        nav.appendChild(separator);

        // 添加分类按钮
        const btn = document.createElement('button');
        btn.className = 'breadcrumb-item text-blue-600 hover:text-blue-800 transition-colors' +
                        (index === categoryNavigationStack.length - 1 ? ' font-semibold' : '');
        btn.setAttribute('data-category-id', item.id);
        btn.textContent = item.name;
        btn.addEventListener('click', () => navigateToBreadcrumb(item.id));
        nav.appendChild(btn);
      });

      // 显示/隐藏面包屑
      if (categoryNavigationStack.length > 0) {
        breadcrumb.classList.remove('hidden');
      } else {
        breadcrumb.classList.add('hidden');
      }
    }

    // 🔥 返回上一级
    function navigateBack() {
      if (categoryNavigationStack.length <= 1) {
        // 返回到首页
        navigateToBreadcrumb(0);
        return;
      }

      // 弹出当前分类
      categoryNavigationStack.pop();

      if (categoryNavigationStack.length === 0) {
        navigateToBreadcrumb(0);
        return;
      }

      // 获取上一级分类
      const parentItem = categoryNavigationStack[categoryNavigationStack.length - 1];

      // 重新点击上一级
      currentCategoryId = parentItem.id;
      currentCategory = parentItem.id.toString();

      updateAllCategoryButtonStyles(parentItem.id);
      updateBreadcrumb();

      // 如果上一级有子分类，显示它们
      if (parentItem.hasChildren) {
        loadChildCategories(parentItem.id, parentItem.name);
      } else {
        hideChildCategories();
      }

      // 🔥 筛选产品（同步，无延迟）
      const categoryIds = getCategoryDescendantsSync(parentItem.id);
      window.activeCategoryIds = categoryIds.map(id => parseInt(id, 10)).filter(id => !isNaN(id));
      filterProductsHierarchical();
      scrollCashierProductsToTop();
    }

    // 🔥 点击面包屑导航到指定分类
    function navigateToBreadcrumb(targetId) {
      if (targetId === 0) {
        // 返回首页
        categoryNavigationStack = [];
        currentCategoryId = null;
        window.activeCategoryIds = [];
        hideChildCategories();
        updateBreadcrumb();

        // 重置所有按钮样式（🔥 使用配置的未选中颜色）
        const resetColors = window.RUIYI_POS?.categoryColors ?? {
          unselected: { bg: '#E05C40', bgIntensity: 19, text: '#C45A3B', border: '#E05C40' }
        };
        const resetBgIntensityHex = window.RUIYI_POS?.percentToHex?.(resetColors.unselected?.bgIntensity || 19) || '30';
        document.querySelectorAll('#level-1-categories .category-btn').forEach(btn => {
          btn.classList.remove('active-category');
          btn.style.backgroundColor = (resetColors.unselected?.bg || '#E05C40') + resetBgIntensityHex;
          btn.style.color = resetColors.unselected?.text || '#C45A3B';
          btn.style.border = '2px solid ' + (resetColors.unselected?.border || '#E05C40');
        });

        // 点击第一个分类
        const firstBtn = document.querySelector('#level-1-categories .category-btn');
        if (firstBtn) {
          firstBtn.click();
        }
        return;
      }

      // 截断栈到目标位置
      const targetIndex = categoryNavigationStack.findIndex(item => item.id === targetId);
      if (targetIndex >= 0) {
        const targetItem = categoryNavigationStack[targetIndex];
        categoryNavigationStack = categoryNavigationStack.slice(0, targetIndex + 1);

        currentCategoryId = targetId;
        currentCategory = targetId.toString();

        updateAllCategoryButtonStyles(targetId);
        updateBreadcrumb();

        if (targetItem.hasChildren) {
          loadChildCategories(targetId, targetItem.name);
        } else {
          hideChildCategories();
        }

        // 🔥 筛选产品（同步，无延迟）
        const categoryIds = getCategoryDescendantsSync(targetId);
        window.activeCategoryIds = categoryIds.map(id => parseInt(id, 10)).filter(id => !isNaN(id));
        filterProductsHierarchical();
        scrollCashierProductsToTop();
      }
    }

    // 🔥 获取分类的所有子孙ID（同步版本，使用预加载数据）
    function getCategoryDescendantsSync(categoryId) {
      // 从预加载的映射中获取
      if (window.RUIYI_POS_CONFIG && window.RUIYI_POS_CONFIG.categoryDescendantsMap) {
        const descendants = window.RUIYI_POS_CONFIG.categoryDescendantsMap[categoryId];
        if (descendants && Array.isArray(descendants)) {
          // // console.log('[分类过滤] 同步获取分类', categoryId, '的子孙IDs:', descendants);
          return descendants;
        }
      }
      // 回退：只返回当前分类 ID
      // // console.log('[分类过滤] 未找到预加载数据，回退到单ID:', categoryId);
      return [categoryId];
    }

    // 🔥 保持兼容性的 Promise 版本（立即 resolve，无 AJAX）
    function loadCategoryDescendants(categoryId) {
      return Promise.resolve(getCategoryDescendantsSync(categoryId));
    }

    // 🔥 层级筛选产品
      function filterProductsHierarchical() {
      const productCards = document.querySelectorAll('.product-card');
      const searchTerm = document.getElementById('product-search-input')?.value.toLowerCase() || '';
      let matchCount = 0;

      // 🔥 如果有搜索词，搜索所有分类（忽略分类过滤）
      const isSearching = searchTerm.trim().length > 0;

      productCards.forEach(card => {
        // 🔥 修复：使用 data-categories 属性（空格分隔的字符串）
        const categoriesStr = card.getAttribute('data-categories') || '';
        const productCategories = categoriesStr.split(' ').filter(id => id).map(id => parseInt(id.trim()));
        const productName = (card.getAttribute('data-name') || '').toLowerCase();
        const productNameEs = (card.getAttribute('data-name-es') || '').toLowerCase();
        const productNameZh = (card.getAttribute('data-name-zh') || '').toLowerCase();
        const productNameEn = (card.getAttribute('data-name-en') || '').toLowerCase();
        const productPrice = parseFloat(card.getAttribute('data-price') || '0');

        // 🔥 价格为0的产品：自助餐和免费产品允许显示
        if (productPrice <= 0 && card.getAttribute('data-is-buffet') !== '1' && card.getAttribute('data-is-free') !== '1') {
          card.classList.add('product-hidden');
          card.style.setProperty('display', 'none', 'important');
          card.style.setProperty('visibility', 'hidden', 'important');
          return;
        }

        // 跳过Suplementos产品（特殊处理）
        const isInSuplementosSection = card.closest('.suplementos-section') !== null;
        if (isInSuplementosSection) {
          const searchMatch = matchesProductSearchFuzzy(searchTerm, [
            productName,
            productNameEs,
            productNameZh,
            productNameEn,
            card.getAttribute('data-sku') || ''
          ]);
          if (searchMatch) {
            card.classList.remove('product-hidden');
            card.style.cssText = card.style.cssText.replace(/display:\s*none\s*!important;?/gi, '').replace(/visibility:\s*hidden\s*!important;?/gi, '');
          } else {
            card.classList.add('product-hidden');
            card.style.setProperty('display', 'none', 'important');
            card.style.setProperty('visibility', 'hidden', 'important');
          }
          return;
        }

        // 🔥 搜索时忽略分类过滤，搜索所有分类
        if (isSearching) {
          const searchMatch = matchesProductSearchFuzzy(searchTerm, [
            productName,
            productNameEs,
            productNameZh,
            productNameEn,
            card.getAttribute('data-sku') || ''
          ]);
          if (searchMatch) {
            card.classList.remove('product-hidden');
            card.style.cssText = card.style.cssText.replace(/display:\s*none\s*!important;?/gi, '').replace(/visibility:\s*hidden\s*!important;?/gi, '');
            matchCount++;
          } else {
            card.classList.add('product-hidden');
            card.style.setProperty('display', 'none', 'important');
            card.style.setProperty('visibility', 'hidden', 'important');
          }
          return;
        }

        // 检查是否在活动分类中（仅在没有搜索词时）
        let categoryMatch = false;

        // 🔥 修复：当activeCategoryIds为空时，使用配置中的首个分类ID作为后备
        // 这避免了在初始化时显示所有产品的问题
        let effectiveActiveCategoryIds = window.activeCategoryIds;
        if (!effectiveActiveCategoryIds || effectiveActiveCategoryIds.length === 0) {
          // 尝试从配置中获取首个分类ID
          if (window.RUIYI_POS_CONFIG && window.RUIYI_POS_CONFIG.firstCategoryAllIds && window.RUIYI_POS_CONFIG.firstCategoryAllIds.length > 0) {
            effectiveActiveCategoryIds = window.RUIYI_POS_CONFIG.firstCategoryAllIds;
            // 同步更新全局变量
            window.activeCategoryIds = effectiveActiveCategoryIds.slice();
            // // console.log('[分类过滤] activeCategoryIds为空，使用首个分类:', effectiveActiveCategoryIds);
          } else {
            // 如果配置也为空，保持当前产品的隐藏状态（不修改）
            // 产品是否显示由PHP初始渲染决定
            const isCurrentlyHidden = card.classList.contains('product-hidden');
            categoryMatch = !isCurrentlyHidden; // 保持当前状态
            console.warn('[分类过滤] 无法确定活动分类，保持产品当前状态');
          }
        }

        // 只有在有有效分类ID时才进行过滤
        if (effectiveActiveCategoryIds && effectiveActiveCategoryIds.length > 0) {
          categoryMatch = productCategories.some(catId => effectiveActiveCategoryIds.includes(catId));
        }

        // 🔥 修复：使用 setProperty 设置 !important 样式
        if (categoryMatch) {
          card.classList.remove('product-hidden');
          // 移除隐藏样式
          card.style.cssText = card.style.cssText.replace(/display:\s*none\s*!important;?/gi, '').replace(/visibility:\s*hidden\s*!important;?/gi, '');
          matchCount++;
        } else {
          card.classList.add('product-hidden');
          card.style.setProperty('display', 'none', 'important');
          card.style.setProperty('visibility', 'hidden', 'important');
        }
      });

      // 🔥 派发分类变更事件，供懒加载器等模块使用
      const categoryEvent = new CustomEvent('categoryChanged', {
        detail: {
          category: currentCategoryId ? currentCategoryId.toString() : 'all',
          categoryIds: window.activeCategoryIds || []
        }
      });
      document.dispatchEvent(categoryEvent);
    }

    // Numberpad functionality for special category products
    let currentNumberpadProduct = null;

    function showNumberpad(productCard) {
      const productId = productCard.getAttribute('data-id');
      const productName = productCard.getAttribute('data-name-es') || productCard.getAttribute('data-name');
      const basePrice = parseFloat(productCard.getAttribute('data-price'));

      // 🔥 获取分区价格
      const zonePrices = parseZonePrices(productCard);
      const currentCategoryId = getCurrentTableCategoryId();
      const effectivePrice = getProductPriceForCurrentZone(basePrice, zonePrices, currentCategoryId);

      currentNumberpadProduct = {
        id: parseInt(productId),
        name: productName,
        price: effectivePrice, // 🔥 使用分区价格
        basePrice: basePrice, // 🔥 保存基础价格
        zoneCategoryId: currentCategoryId, // 🔥 保存分区ID
        name_es: productCard.getAttribute('data-name-es') || productName,
        name_zh: productCard.getAttribute('data-name-zh') || '',
        name_en: productCard.getAttribute('data-name-en') || '',
        taxRate: parseFloat(productCard.getAttribute('data-tax-rate')) || 10,
        image_url: productCard.getAttribute('data-image')
      };

      const modal = document.getElementById('numberpad-modal');
      const productNameEl = document.getElementById('numberpad-product-name');
      const input = document.getElementById('numberpad-input');

      if (modal && productNameEl && input) {
        productNameEl.textContent = productName;
        input.value = effectivePrice; // 🔥 显示分区价格
        modal.classList.add('show');
        setTimeout(() => {
          input.focus();
          input.select(); // Select all text for easy replacement
        }, 100);
      }
    }
    
    function hideNumberpad() {
      const modal = document.getElementById('numberpad-modal');
      if (modal) {
        modal.classList.remove('show');
      }
      currentNumberpadProduct = null;
    }

    // 🔥 分类自由价格产品 - 显示数字键盘（暴露到全局作用域）
    window.showCategoryPriceNumberpad = function(card) {
      const categoryId = card.getAttribute('data-category-id');
      const categoryName = card.getAttribute('data-category-name');

      // 使用负数ID来区分虚拟产品（避免与真实产品ID冲突）
      const virtualProductId = -parseInt(categoryId);

      currentNumberpadProduct = {
        id: virtualProductId,
        name: categoryName,
        price: 0,
        basePrice: 0,
        zoneCategoryId: null,
        name_es: categoryName,
        name_zh: categoryName,
        name_en: categoryName,
        taxRate: 10, // 默认税率
        image_url: '',
        isCategoryPriceProduct: true, // 标记为分类自由价格产品
        categoryId: categoryId
      };

      const modal = document.getElementById('numberpad-modal');
      const productNameEl = document.getElementById('numberpad-product-name');
      const input = document.getElementById('numberpad-input');

      if (modal && productNameEl && input) {
        productNameEl.textContent = categoryName;
        input.value = ''; // 默认为空，让用户输入价格
        modal.classList.add('show');
        setTimeout(() => {
          input.focus();
        }, 100);
      }
    };

    function confirmNumberpadQuantity() {
      if (!currentNumberpadProduct) return;
      
      const input = document.getElementById('numberpad-input');
      const customPrice = parseFloat(input.value) || 0;
      
      if (customPrice <= 0) {
        alert('<?php echo ruiyi_translate('价格必须大于0', 'Price must be greater than 0', '价格必须大于0'); ?>');
        return;
      }
      
      // Add to cart with custom price
      cart.push({
        id: currentNumberpadProduct.id,
        name: currentNumberpadProduct.name_es || currentNumberpadProduct.name,
        name_es: currentNumberpadProduct.name_es || currentNumberpadProduct.name,
        name_zh: currentNumberpadProduct.name_zh || '',
        name_en: currentNumberpadProduct.name_en || '',
        price: currentNumberpadProduct.price, // 🔥 分区价格
        basePrice: currentNumberpadProduct.basePrice, // 🔥 基础价格
        zoneCategoryId: currentNumberpadProduct.zoneCategoryId, // 🔥 分区ID
        customPrice: customPrice, // Custom price set by user (numberpad input)
        quantity: 1,
        addedQuantity: 1, // 🔥 追踪本次新增数量（用于厨房打印）
        taxRate: currentNumberpadProduct.taxRate,
        image_url: currentNumberpadProduct.image_url,
        isNew: false,
        locked: false
      });
      
      renderCart();
      hideNumberpad();
    }
    
    // Initialize numberpad event listeners
    function initializeNumberpad() {
      const modal = document.getElementById('numberpad-modal');
      if (!modal) return;
      
      const closeBtn = document.getElementById('numberpad-close');
      const confirmBtn = document.getElementById('numberpad-confirm');
      const clearBtn = document.getElementById('numberpad-clear');
      const numberBtns = document.querySelectorAll('.numberpad-btn[data-number]');
      const input = document.getElementById('numberpad-input');
      const overlay = modal.querySelector('.numberpad-overlay');
      
      if (closeBtn) {
        closeBtn.addEventListener('click', hideNumberpad);
      }
      
      if (overlay) {
        overlay.addEventListener('click', hideNumberpad);
      }
      
      if (confirmBtn) {
        confirmBtn.addEventListener('click', confirmNumberpadQuantity);
      }
      
      if (clearBtn) {
        clearBtn.addEventListener('click', () => {
          if (input) input.value = '0';
        });
      }
      
      numberBtns.forEach(btn => {
        btn.addEventListener('click', () => {
          if (!input) return;
          const number = btn.dataset.number;
          const currentValue = input.value.replace(/[^0-9.]/g, ''); // Remove non-numeric except decimal
          
          // Handle decimal point
          if (number === '.') {
            if (currentValue.indexOf('.') === -1) {
              // Only add decimal if there isn't one already
              input.value = currentValue === '0' || currentValue === '' ? '0.' : currentValue + '.';
            }
            return;
          }
          
          // If input is 0 or empty, replace it (but allow 0.xx)
          if (currentValue === '0' && currentValue.indexOf('.') === -1) {
            input.value = number;
          } else {
            // Allow longer prices - max 999999.99 (6 digits before decimal, 2 after)
            const newValue = currentValue + number;
            // Check decimal places (max 2 decimal places)
            const parts = newValue.split('.');
            if (parts[1] && parts[1].length > 2) {
              return; // Don't allow more than 2 decimal places
            }
            // Check total digits before decimal (max 6 digits)
            if (parts[0] && parts[0].length > 6) {
              return; // Don't allow more than 6 digits before decimal
            }
            // No upper limit on price value, just limit digits
            input.value = newValue;
          }
        });
      });
      
      if (input) {
        input.addEventListener('keydown', (e) => {
          if (e.key === 'Enter') {
            confirmNumberpadQuantity();
          }
        });
      }
    }
    
    // Initialize numberpad on page load
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', initializeNumberpad);
    } else {
      initializeNumberpad();
    }
      
      
      // 初始化
      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initializeCategoryFiltering);
      } else {
        // 给DOM一点时间完成渲染
        setTimeout(initializeCategoryFiltering, 100);
      }
      
      // 清空购物车按钮
      const clearCartBtn = document.getElementById('clear-cart');
      if (clearCartBtn) {
        clearCartBtn.addEventListener('click', function() {
          if (cart.length === 0) return;
          
          Swal.fire({
            title: '<?php echo ruiyi_translate("¿Estás seguro?", "Are you sure?", "确定要清空购物车吗?"); ?>',
            text: '<?php echo ruiyi_translate("Se eliminará todo el contenido del carrito", "All cart content will be deleted", "将清空购物车"); ?>',
            icon: 'warning',
            showCancelButton: true,
            confirmButtonText: '<?php echo ruiyi_translate("Sí, vaciar", "Yes, empty", "是，清空"); ?>',
            cancelButtonText: '<?php echo ruiyi_translate("Cancelar", "Cancel", "取消"); ?>'
          }).then((result) => {
            if (result.isConfirmed) {
              cart = [];
              // 🔥 清除折扣状态
              window.currentDiscountPercent = 0;
              updateDiscountBadge();
              // 🔥 清除选中状态
              selectedCartItemIndex = null;
              window.selectedCartItemIndex = null;

              renderCart();
              // 重置所有折扣和支付状态
              resetAllPaymentStates('clear_cart');

              // 🔥 清除收银购物车持久化存储
              if (typeof clearPosCartStorage === 'function') {
                clearPosCartStorage();
              }

              // 🔥🔥🔥 关键修复：同步空购物车到 mesas_estado，防止数据不一致
              if (typeof syncCartToMesasEstado === 'function') {
                syncCartToMesasEstado();
