                  alpineData.toolboxOpen = false;
                }
              }

              Toastify({
                text: '🗑️ <?php echo ruiyi_translate("Carrito vaciado", "Cart emptied", "购物车已清空"); ?>',
                duration: 2000,
                gravity: "top",
                position: "center",
                style: { background: "#f44336" }
              }).showToast();
            }
          });
        });
      }
      
      // 🔥 开钱箱按钮 - 优化版：秒开钱箱，无延迟
      const openDrawerBtn = document.getElementById('open-drawer-btn');
      if (openDrawerBtn) {
        openDrawerBtn.addEventListener('click', function() {
          // 检查开钱箱按钮是否被锁定
          if (window.posSettings && window.posSettings.lockDrawerButton) {
            Toastify({
              text: '🔒 <?php echo ruiyi_translate("El botón de cajón está bloqueado", "Drawer button is locked", "开钱箱按钮已被锁定"); ?>',
              duration: 2000,
              gravity: "top",
              position: "center",
              style: { background: "#f59e0b" }
            }).showToast();
            return;
          }

          // 🔥 直接同步调用，不使用async/await减少延迟
          if (typeof clodopOpenCashDrawer === 'function') {
            const success = clodopOpenCashDrawer();
            if (!success) {
              console.warn('[开钱箱] CLODOP调用返回false');
              showPrinterConfigDialog();
            }
          } else if (typeof abrirCajonDinero === 'function') {
            // 降级方案
            abrirCajonDinero().catch(err => {
              console.error('[开钱箱] 失败:', err);
              showPrinterConfigDialog();
            });
          } else {
            showPrinterConfigDialog();
          }
        });
      }

      // 保存桌位订单按钮 - 🚀 PWA优化：使用乐观更新策略
      const saveTableOrderBtn = document.getElementById('save-table-order-btn');
      if (saveTableOrderBtn) {
        saveTableOrderBtn.addEventListener('click', async function() {
          // 🔥 保存开始时记录桌位，用于异步回调中检查
          let _saveStartTable = window._currentViewingTable ? String(window._currentViewingTable) : null;
          const _saveInputTable = document.getElementById('table-number')?.value.trim();
          const _saveResolvedTableRaw = _saveInputTable
            ? (typeof ruiyiSafeResolveGlobalTableNumber === 'function'
                ? ruiyiSafeResolveGlobalTableNumber(_saveInputTable)
                : (typeof resolveGlobalTableNumber === 'function' ? resolveGlobalTableNumber(_saveInputTable) : null))
            : null;
          const _saveResolvedTable = _saveResolvedTableRaw !== null && _saveResolvedTableRaw !== undefined
            ? String(_saveResolvedTableRaw)
            : '';
          if (!_saveStartTable && _saveResolvedTable) {
            window._currentViewingTable = _saveResolvedTable;
            _saveStartTable = _saveResolvedTable;
            console.log('[saveTableOrderBtn] 🔒 恢复当前桌位上下文:', _saveResolvedTable);
          }

          // 🔥 检查购物车是否为空或只有锁定的旧商品（没有新增商品）
          const hasNewItems = cart && cart.length > 0 && cart.some(item => item.locked !== true);
          // 🔥 检查是否有锁定产品的数量被修改
          const hasModifiedLockedItems = window.cartModified === true;

          if (!cart || cart.length === 0 || (!hasNewItems && !hasModifiedLockedItems)) {
            // 退出桌位模式
            if (typeof clearCurrentTable === 'function') {
              clearCurrentTable();
            }

            // 切换到桌位模块
            if (typeof cambiarSeccion === 'function') {
              cambiarSeccion('mesas');
            } else {
              const mesasLink = document.querySelector('a[href="#mesas"]');
              if (mesasLink) {
                mesasLink.click();
              }
            }

            // 刷新桌位显示
            setTimeout(() => {
              if (typeof renderizarMesas === 'function') {
                renderizarMesas('empty-cart-return');
              }
            }, 100);

            return; // ✅ 不继续执行保存逻辑
          }

          // 🔥🔥🔥 关键修复（2024-01）：先更新锁定商品，再添加新商品
          // 原因：如果用户修改了锁定商品价格（如 6.30€→3.00€），又添加了同产品原价（6.30€）
          // 如果先添加新商品，ruiyi_pos_create_order 会因 product_id+price 已存在而跳过
          // 然后更新锁定商品时价格变更，新商品就丢失了
          // 顺序：1. 先更新锁定商品（价格/数量变更生效）2. 再添加新商品（此时原价不重复）
          // 注意：updateLockedItemsToServer 现在会保留不在请求列表中的产品，不会删除新添加的

          // 🔥 厨房打印盒子：统一收集所有需要打印的商品（🍽️ 排除开台商品）
          const kitchenPrintQueue = [];
          const cashierKitchenPrintQueue = []; // 🔥 收银台厨房小票（全部产品）
          // 🔥 厨房小票多语言：根据系统语言选择产品名称
          const _kLang2 = window.RUIYI_POS?.currentLang || PHP_LANG || 'zh';
          // 🔥🔥🔥 【2026-03-30 修复】独立定义，不引用 autoSaveTableOrder 作用域内的函数
          function _resolveKitchenName2(item) {
            if (_kLang2 === 'zh' && item.name_zh) return item.name_zh;
            if (_kLang2 === 'en' && item.name_en) return item.name_en;
            return item.name;
          }

          // 1. 锁定商品的新增数量部分
          cart.filter(item => item.locked && (item.addedQuantity || 0) > 0 && !item.is_buffet_opening).forEach(item => {
            const printItem = {
              name: _resolveKitchenName2(item),
              quantity: item.addedQuantity,
              notes: item.notes || '',
              product_id: item.id || 0
            };
            // 🔥 收银台队列：全部加入
            if (window.clodopConfig?.kitchenCategoryFilterEnabled) {
              cashierKitchenPrintQueue.push(printItem);
            }
            // 🔥 厨房队列：过滤排除分类
            if (!isKitchenExcludedProduct(item.id)) {
              kitchenPrintQueue.push(printItem);
            } else {
              // 未启用过滤时也加入厨房队列
              if (!window.clodopConfig?.kitchenCategoryFilterEnabled) {
                kitchenPrintQueue.push(printItem);
              }
            }
          });

          // 2. 新添加的商品（未锁定，🍽️ 排除开台商品）
          cart.filter(item => !item.locked && item.quantity > 0 && !item.is_buffet_opening).forEach(item => {
            const printItem = {
              name: _resolveKitchenName2(item),
              quantity: item.quantity,
              notes: item.notes || '',
              product_id: item.id || 0
            };
            // 🔥 收银台队列：全部加入
            if (window.clodopConfig?.kitchenCategoryFilterEnabled) {
              cashierKitchenPrintQueue.push(printItem);
            }
            // 🔥 厨房队列：过滤排除分类
            if (!isKitchenExcludedProduct(item.id)) {
              kitchenPrintQueue.push(printItem);
            } else {
              if (!window.clodopConfig?.kitchenCategoryFilterEnabled) {
                kitchenPrintQueue.push(printItem);
              }
            }
          });

          console.log('[saveTableOrderBtn] 🗃️ 厨房打印盒子:', kitchenPrintQueue.length, '项',
            window.clodopConfig?.kitchenCategoryFilterEnabled ? '(收银台队列:' + cashierKitchenPrintQueue.length + '项)' : '',
            '| 过滤启用:', !!window.clodopConfig?.kitchenCategoryFilterEnabled,
            '| 排除分类:', JSON.stringify(window.clodopConfig?.kitchenExcludedCategories || []));

          // 🚀 PWA优化：使用快速保存（乐观更新）
          // 1. 立即更新本地状态（只有新增产品时才调用）
          const orderData = hasNewItems ? quickSaveTableOrder() : null;
          let _saveServerSyncAlreadyDone = false;

          // 🔥🔥🔥 【2026-05-03 修复】手动保存必须等服务器确认后再离开桌位
          // 原问题：先提示"已保存"并跳回桌位页，随后才后台同步。
          // 慢网络/旧设备下，收银员马上重新进入同一桌或直接结账，会读到旧订单或 PENDING 本地数据，
          // 导致新增商品短暂消失；再次添加后，第一次后台同步又完成，最终形成重复叠加。
          Swal.fire({
            title: '<?php echo ruiyi_translate("Guardando pedido...", "Saving order...", "正在保存订单..."); ?>',
            text: '<?php echo ruiyi_translate("Por favor espere", "Please wait", "请稍候"); ?>',
            allowOutsideClick: false,
            allowEscapeKey: false,
            didOpen: () => { Swal.showLoading(); }
          });

          try {
            if (hasModifiedLockedItems) {
              if (window._optimisticDeleteSyncTimer) {
                clearTimeout(window._optimisticDeleteSyncTimer);
                window._optimisticDeleteSyncTimer = null;
              }
              await updateLockedItemsToServer();
              window.cartModified = false;
            }

            if (orderData) {
              orderData.skipKitchenPrint = true; // 由统一打印盒子处理
              await syncTableOrderToServer(orderData);
            }

            _saveServerSyncAlreadyDone = true;
            Swal.close();
          } catch (e) {
            Swal.close();
            console.error('[saveTableOrderBtn] ❌ 服务器保存失败，留在当前桌位:', e);
            try {
              if (orderData && orderData.mesaKey) {
                const mesasEstadoRecover = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                const tableDataRecover = mesasEstadoRecover[orderData.mesaKey];
                if (tableDataRecover?.cart && tableDataRecover.cart.length > 0) {
                  cart = tableDataRecover.cart.filter(item => item.quantity > 0);
                  window.cart = cart;
                  if (typeof ruiyiSetCartTableIdentity === 'function') {
                    ruiyiSetCartTableIdentity(orderData.table_number || orderData.tableNum, 'saveTableOrderBtn:recover-after-sync-failure');
                  }
                  if (typeof renderCart === 'function') renderCart();
                }
              }
            } catch (recoverErr) {
              console.error('[saveTableOrderBtn] ❌ 恢复购物车失败:', recoverErr);
            }
            Swal.fire({
              icon: 'error',
              title: '<?php echo ruiyi_translate("Error al guardar", "Save failed", "保存失败"); ?>',
              text: '<?php echo ruiyi_translate("No se pudo guardar el pedido. Inténtelo de nuevo.", "Could not save the order. Please try again.", "订单未能保存，请重试。"); ?>',
              confirmButtonColor: '#f7310f'
            });
            return;
          }

          // 2. 显示成功提示（无论是新增产品还是修改锁定产品）
          Toastify({
            text: `✅ <?php echo ruiyi_translate('Pedido guardado', 'Order saved', '订单已保存'); ?>`,
            duration: 1500,
            gravity: "top",
            position: "center",
            style: { background: "#10b981" }
          }).showToast();

          // 3. 服务器确认保存后跳转到桌位模块
          // 🔥🔥🔥 设置跳过标记，避免cambiarSeccion再次触发autoSaveTableOrder显示重复提示
          window._skipAutoSaveInCambiarSeccion = true;
          if (typeof cambiarSeccion === 'function') {
            cambiarSeccion('mesas');
          } else {
            const mesasLink = document.querySelector('a[href="#mesas"]');
            if (mesasLink) {
              mesasLink.click();
            }
          }

          // 4. 快速刷新桌位显示
          setTimeout(() => {
            if (typeof renderizarMesas === 'function') {
              renderizarMesas('after-quick-save');
            }
          }, 100);

          // 🔥🔥🔥 【2026-03-29 关键修复】保存完成后立即清除桌位标记
          // 防止后续异步回调（syncTableOrderToServer）将旧桌位商品写入 cart
          // 同时防止 handleTableSelection 触发冗余的 autoSaveTableOrder
          window._currentViewingTable = null;

          // 5. 🔥🔥🔥 关键修复：按正确顺序后台同步
          // 🔥🔥🔥 修复（2024-01）：必须先更新锁定商品，后添加新商品

          // 6. 🔥 先更新锁定产品数量/价格
          if (hasModifiedLockedItems && !_saveServerSyncAlreadyDone) {
            // 🔥🔥🔥 关键修复：取消乐观删除的后台同步定时器，避免竞态条件
            if (window._optimisticDeleteSyncTimer) {
              clearTimeout(window._optimisticDeleteSyncTimer);
              window._optimisticDeleteSyncTimer = null;
            }

            // 锁定产品被修改，调用更新订单接口
            try {
              await updateLockedItemsToServer();
            } catch (e) {
              // 锁定商品更新失败静默处理
            }
            window.cartModified = false;

            // 🔥🔥🔥 【2026-03-29 修复】只有在用户仍然查看同一桌位时才操作 cart
            if (window._currentViewingTable === _saveStartTable) {
              // 🔥 清除 addedQuantity 标记
              cart.forEach(item => { delete item.addedQuantity; });
              renderCart();
            }
          }

          // 7. 🔥 锁定商品更新后，再同步新商品到服务器
          if (orderData && !_saveServerSyncAlreadyDone) {
            orderData.skipKitchenPrint = true; // 由统一打印盒子处理
            try {
              await syncTableOrderToServer(orderData);
            } catch (e) {
              // 新商品同步失败静默处理
            }
          }

          // 8. 🔥 统一打印厨房小票（从打印盒子）
          if (kitchenPrintQueue.length > 0 && window.clodopConfig?.enabled && window.clodopConfig?.kitchenPrinter) {
            // 检查外送区域 + 设置中配置的跳过分区
            const table_number_for_print = document.getElementById('table-number')?.value.trim();
            const isDeliveryZoneForPrint = typeof isDeliveryZoneTable === 'function' ? isDeliveryZoneTable(table_number_for_print) : false;
            const isSkipZoneForPrint = typeof shouldSkipKitchenPrintForTable === 'function' ? shouldSkipKitchenPrintForTable(table_number_for_print) : false;

            if (isSkipZoneForPrint) {
              console.log('[saveTableOrderBtn] 🚫 该分区已设置跳过厨房打印，不打印');
            } else if (isDeliveryZoneForPrint) {
              console.log('[saveTableOrderBtn] 🚚 外送区域桌位，跳过厨房打印（将在预结单时打印）');
            } else {
              // 获取订单ID
              const tableNum = (table_number_for_print || '').replace(/^(餐桌|Mesa|Table)\s*/, '');
              const mesaKey = `Mesa ${tableNum}`;
              const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
              const printOrderId = mesasEstado[mesaKey]?.orderId || '';

              // 🔥 写入 recent_kitchen_prints 时间戳，防止轮询/storage事件重复打印
              if (printOrderId) {
                try {
                  const recentPrints = JSON.parse(localStorage.getItem('recent_kitchen_prints') || '{}');
                  recentPrints[printOrderId] = Date.now();
                  localStorage.setItem('recent_kitchen_prints', JSON.stringify(recentPrints));
                  console.log('[saveTableOrderBtn] 🛡️ 已写入打印时间戳，防止轮询重复打印:', printOrderId);
                } catch (e) { /* localStorage write may fail in private browsing */ }
              }

              // 获取厨房打印桌号（分类显示名称）
              let kitchenTableName = table_number_for_print;
              const tableNumForKitchen = parseInt(tableNum);
              if (!isNaN(tableNumForKitchen) && window.tableCategoryMappings) {
                let allMappings = Array.isArray(window.tableCategoryMappings)
                  ? window.tableCategoryMappings
                  : Object.values(window.tableCategoryMappings);
                const mapping = allMappings.find(m => parseInt(m.global_table_number) === tableNumForKitchen);
                if (mapping && mapping.category_display_name) {
                  kitchenTableName = mapping.category_display_name;
                } else if (mapping && mapping.display_name) {
                  kitchenTableName = mapping.display_name;
                }
              }

              // 🔥🔥🔥 【2026-03-25 v3】统一使用 unprinted_only API，无论是否启用分类打印机
              try {
                console.log('[saveTableOrderBtn] 🖨️ 调用 unprinted_only API, orderId:', printOrderId);
                const response = await fetch(posAjaxUrl || ajaxUrl, {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                  body: new URLSearchParams({
                    action: 'ruiyi_pos_get_order_for_print',
                    order_id: printOrderId,
                    nonce: posNonce || ajaxNonce,
                    unprinted_only: 'true'
                  })
                });
                const apiData = await response.json();

                if (apiData.success && apiData.data && apiData.data.items && apiData.data.items.length > 0) {
                  let apiItems = apiData.data.items;
                  console.log('[saveTableOrderBtn] ✅ API返回未打印商品:', apiItems.length, '个', apiItems.map(i => i.name + ' x' + i.quantity));

                  // 🔥 分类打印机诊断日志
                  apiItems.forEach(item => {
                    console.log('[saveTableOrderBtn] 📋 分类打印机:', item.name, '| cat:', item.category_name, '| cat_printer:', item.category_printer || '(空-将用默认)');
                  });

                  const defaultPrinter = window.clodopConfig.kitchenPrinter;
                  const categoryPrinterEnabled = window.clodopConfig.categoryPrinterEnabled;
                  const separatePerCat = window.clodopConfig.separateTicketPerCategory;
                  // 🔥 API返回的商品多语言名称解析
                  function _resolveApiName2(item) {
                    if (_kLang2 === 'zh' && item.name_zh) return item.name_zh;
                    if (_kLang2 === 'en' && item.name_en) return item.name_en;
                    return item.name;
                  }
                  // 🔥 过滤"不打印"分类
                  apiItems = apiItems.filter(item => item.category_printer !== '__no_print__');
                  // 🔥【2026-04-07 修复】过滤厨房排除的分类（与 cashierKitchen 路径互补）
                  if (window.clodopConfig?.kitchenCategoryFilterEnabled) {
                    const _excludedCats2 = (window.clodopConfig.kitchenExcludedCategories || []).map(Number);
                    if (_excludedCats2.length > 0) {
                      const _beforeCount2 = apiItems.length;
                      apiItems = apiItems.filter(item => !_excludedCats2.includes(parseInt(item.category_id)));
                      console.log('[saveTableOrderBtn] 🔥 厨房分类过滤:', _beforeCount2, '→', apiItems.length, '排除:', JSON.stringify(_excludedCats2));
                    }
                  }
                  if (apiItems.length === 0) {
                    console.log('[saveTableOrderBtn] ℹ️ 过滤后无可打印商品，跳过厨房打印');
                  }
                  let printJobs = [];

                  if (categoryPrinterEnabled && separatePerCat) {
                    const catGroups = {};
                    apiItems.forEach(item => {
                      const catName = item.category_name || '__uncategorized__';
                      const printer = item.category_printer || defaultPrinter;
                      if (!catGroups[catName]) catGroups[catName] = { printer: printer, items: [] };
                      catGroups[catName].items.push({ name: _resolveApiName2(item), quantity: item.quantity, notes: item.notes || '', is_supplement: item.is_supplement || false, parent_item_name: item.parent_item_name || '' });
                    });
                    Object.keys(catGroups).forEach(cn => {
                      printJobs.push({ printer: catGroups[cn].printer, items: catGroups[cn].items, categoryLabel: cn !== '__uncategorized__' ? cn : null });
                    });
                  } else if (categoryPrinterEnabled) {
                    const printerGroups = {};
                    apiItems.forEach(item => {
                      const printer = item.category_printer || defaultPrinter;
                      if (!printerGroups[printer]) printerGroups[printer] = [];
                      printerGroups[printer].push({ name: _resolveApiName2(item), quantity: item.quantity, notes: item.notes || '', is_supplement: item.is_supplement || false, parent_item_name: item.parent_item_name || '' });
                    });
                    Object.keys(printerGroups).forEach(pn => {
                      printJobs.push({ printer: pn, items: printerGroups[pn], categoryLabel: null });
                    });
                  } else {
                    printJobs.push({ printer: defaultPrinter, items: apiItems.map(i => ({ name: _resolveApiName2(i), quantity: i.quantity, notes: i.notes || '', is_supplement: i.is_supplement || false, parent_item_name: i.parent_item_name || '' })), categoryLabel: null });
                  }

                  console.log('[saveTableOrderBtn] 打印路由:', printJobs.length, '张小票');
                  // 🔥 合并备注：服务器订单备注 + 本地产品备注
                  const _apiNotes2 = apiData.data.notes || '';
                  const _localNotes2 = typeof window.getOrderNotes === 'function' ? window.getOrderNotes() : '';
                  const _mergedNotes2 = [_apiNotes2, _localNotes2].filter(n => n && n.trim()).join('; ');
                  printJobs.forEach((job, index) => {
                    const kitchenOrderData = {
                      id: printOrderId, table_number: kitchenTableName, order_type: 'servir',
                      items: job.items, date_created: new Date().toISOString(),
                      orderNotes: _mergedNotes2,
                      printer_group: printJobs.length > 1 ? (job.categoryLabel || job.printer) : null,
                      total_printers: printJobs.length,
                      category_label: job.categoryLabel
                    };
                    setTimeout(() => {
                      if (typeof ruiyiPrintKitchenOrder === 'function') {
                        ruiyiPrintKitchenOrder(kitchenOrderData, job.printer);
                      }
                      if (index === printJobs.length - 1 && kitchenOrderData.orderNotes && typeof window.clearOrderNotes === 'function') {
                        window.clearOrderNotes();
                      }
                    }, index * 500);
                  });
                } else {
                  console.log('[saveTableOrderBtn] ℹ️ 无未打印商品，跳过打印');
                }
              } catch (err) {
                console.error('[saveTableOrderBtn] ❌ unprinted_only API 出错，回退到本地队列:', err);
                const kitchenOrderData = {
                  id: printOrderId, table_number: kitchenTableName, order_type: 'servir',
                  items: kitchenPrintQueue.map(i => ({ name: i.name, name_original: i.name || '', quantity: i.quantity, notes: i.notes || '', is_supplement: i.is_supplement || false, parent_item_name: i.parent_item_name || '' })),
                  date_created: new Date().toISOString(),
                  orderNotes: typeof window.getOrderNotes === 'function' ? window.getOrderNotes() : ''
                };
                if (typeof ruiyiPrintKitchenOrder === 'function') ruiyiPrintKitchenOrder(kitchenOrderData, window.clodopConfig.kitchenPrinter);
                if (kitchenOrderData.orderNotes && typeof window.clearOrderNotes === 'function') window.clearOrderNotes();
              }
            }
          }

          // 🔥 9. 收银台打印机打印完整厨房小票（不过滤分类）
          console.log('[saveTableOrderBtn] 🔍 步骤9 收银台厨房小票检查:', {
            filterEnabled: !!window.clodopConfig?.kitchenCategoryFilterEnabled,
            cashierQueueLength: cashierKitchenPrintQueue.length,
            clodopEnabled: !!window.clodopConfig?.enabled,
            defaultPrinter: window.clodopConfig?.defaultPrinter || '(未设置)'
          });
          if (window.clodopConfig?.kitchenCategoryFilterEnabled && window.clodopConfig?.kitchenCopyToDefault && cashierKitchenPrintQueue.length > 0 && window.clodopConfig?.enabled && window.clodopConfig?.defaultPrinter) {
            const table_number_for_cashier = document.getElementById('table-number')?.value.trim();
            const isDeliveryForCashier = typeof isDeliveryZoneTable === 'function' ? isDeliveryZoneTable(table_number_for_cashier) : false;
            console.log('[saveTableOrderBtn] 🔍 收银台厨房小票: 桌号=', table_number_for_cashier, '外送区域=', isDeliveryForCashier);
            if (!isDeliveryForCashier) {
              const tableNumC = (table_number_for_cashier || '').replace(/^(餐桌|Mesa|Table)\s*/, '');
              const mesaKeyC = `Mesa ${tableNumC}`;
              const mesasEstadoC = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
              const printOrderIdC = mesasEstadoC[mesaKeyC]?.orderId || '';

              let kitchenTableNameC = table_number_for_cashier;
              const tableNumForKitchenC = parseInt(tableNumC);
              if (!isNaN(tableNumForKitchenC) && window.tableCategoryMappings) {
                let allMappingsC = Array.isArray(window.tableCategoryMappings) ? window.tableCategoryMappings : Object.values(window.tableCategoryMappings);
                const mappingC = allMappingsC.find(m => parseInt(m.global_table_number) === tableNumForKitchenC);
                if (mappingC && mappingC.category_display_name) kitchenTableNameC = mappingC.category_display_name;
                else if (mappingC && mappingC.display_name) kitchenTableNameC = mappingC.display_name;
              }

              const cashierOrderData = {
                id: printOrderIdC, table_number: kitchenTableNameC, order_type: 'servir',
                items: cashierKitchenPrintQueue.map(i => ({ name: i.name, quantity: i.quantity, notes: i.notes || '' })),
                date_created: new Date().toISOString(),
                orderNotes: typeof _mergedNotes2 !== 'undefined' ? _mergedNotes2 : (typeof window.getOrderNotes === 'function' ? window.getOrderNotes() : '')
              };
              if (typeof ruiyiPrintKitchenOrder === 'function') {
                ruiyiPrintKitchenOrder(cashierOrderData, window.clodopConfig.defaultPrinter);
                console.log('[saveTableOrderBtn] ✅ 收银台厨房小票已发送到收银打印机, 商品数:', cashierKitchenPrintQueue.length);
              }
            }
          }
        });
      }

      async function ruiyiReprintLastReceipt(triggerPrefix) {
        let lastReceiptHtml = localStorage.getItem('lastReceiptHtml');
        const lastReceiptType = localStorage.getItem('lastReceiptType') || 'unknown';

        if (!lastReceiptHtml) {
          Toastify({
            text: '<?php echo ruiyi_translate("No hay recibo previo para imprimir", "No previous receipt to print", "没有可打印的小票记录"); ?>',
            duration: 3000,
            gravity: "top",
            position: "center",
            style: { background: "#ff9800" }
          }).showToast();
          return;
        }

        const lastReceiptRequestBody = localStorage.getItem('lastReceiptRequestBody');
        if (lastReceiptRequestBody && typeof ajaxUrl !== 'undefined') {
          try {
            const refreshParams = new URLSearchParams(lastReceiptRequestBody);
            refreshParams.set('nonce', ajaxNonce);
            refreshParams.set('reprint_refresh', '1');
            const response = await fetch(ajaxUrl, {
              method: 'POST',
              headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
              body: refreshParams
            });
            const refreshedReceipt = await response.json();
            if (refreshedReceipt.success && refreshedReceipt.data && refreshedReceipt.data.html) {
              lastReceiptHtml = refreshedReceipt.data.html;
              localStorage.setItem('lastReceiptHtml', lastReceiptHtml);
              localStorage.setItem('lastReceiptTimestamp', Date.now().toString());
            } else {
              console.warn('[补打小票] 重新生成小票失败，使用本地缓存:', refreshedReceipt);
            }
          } catch (refreshError) {
            console.warn('[补打小票] 重新获取最新小票失败，使用本地缓存:', refreshError);
          }
        }

        try {
          if (typeof ruiyiUnifiedPrint !== 'undefined') {
            const printSuccess = ruiyiUnifiedPrint(lastReceiptHtml, triggerPrefix + lastReceiptType);
            if (!printSuccess) {
              throw new Error('CLODOP reprint failed');
            }

            Toastify({
              text: '<?php echo ruiyi_translate("Reimprimiendo último recibo", "Reprinting last receipt", "正在重新打印小票"); ?>',
              duration: 2000,
              gravity: "top",
              position: "center",
              style: { background: "#6366f1" }
            }).showToast();
          } else {
            throw new Error('<?php echo ruiyi_translate("Función de impresión no disponible", "Print function not available", "打印功能不可用"); ?>');
          }
        } catch (error) {
          console.error('重新打印失败:', error);
          showPrinterConfigDialog();
        }
      }

      // 打印最后小票按钮
      const reprintLastReceiptBtn = document.getElementById('reprint-last-receipt-btn');
      if (reprintLastReceiptBtn) {
        reprintLastReceiptBtn.addEventListener('click', function() {
          ruiyiReprintLastReceipt('reprint_');
        });
      }

      // 🔥 打印桌位订单按钮已移除

      // 🔥 桌位模块悬浮打印最后小票按钮
      const mesasPrintReceiptBtn = document.getElementById('mesas-print-receipt-btn');
      if (mesasPrintReceiptBtn) {
        mesasPrintReceiptBtn.addEventListener('click', function() {
          ruiyiReprintLastReceipt('reprint_');
        });
      }

      // 发送订单/结账按钮 - 根据订单类型执行不同操作
      const sendOrderBtn = document.getElementById('send-order-btn');
      if (sendOrderBtn) {
        sendOrderBtn.addEventListener('click', function() {
          const currentOrderType = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir';
          const buttonAction = this.getAttribute('data-action') || 'send';
          const tableNumber = document.getElementById('table-number')?.value.trim();

          if (currentOrderType === 'llevar') {
              // 外卖模式：启动结账流程
              startTakeawayCheckout();
              return;
          }

          // 堂食模式：原有的发送订单逻辑

          // 检查是否在查看模式
          const viewMode = sessionStorage.getItem('tableViewMode');
          const isViewMode = viewMode ? JSON.parse(viewMode) : null;
          
          // 分离锁定和非锁定商品
          const newItems = cart.filter(item => !item.locked);
          
          // 基本验证 - 检查是否有新商品
          if (newItems.length === 0) {
            Swal.fire({
              icon: 'info',
              title: '🛒 <?php echo ruiyi_translate("Sin productos nuevos", "No new products", "没有新商品"); ?>',
              text: isViewMode ?
                '<?php echo ruiyi_translate("Agrega nuevos productos para continuar el pedido", "Add new products to continue the order", "添加新商品以继续订单"); ?>' :
                '<?php echo ruiyi_translate("Agrega productos al carrito antes de enviar el pedido", "Add products to the cart before sending the order", "添加商品后再发送订单"); ?>',
              confirmButtonColor: '#f7310f'
            });
            return;
          }

          let tipoPedidoSeleccionado = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir';

          // 自动检测：如果没有选择桌位，自动切换为外卖模式
          if (!tableNumber && tipoPedidoSeleccionado === 'servir') {
              tipoPedidoSeleccionado = 'llevar';
              sessionStorage.setItem('tipoPedidoSeleccionado', 'llevar');

              // 更新UI按钮状态
              const takeawayBtn = document.querySelector('[data-type="llevar"]');
              const dineInBtn = document.querySelector('[data-type="servir"]');

              if (takeawayBtn && dineInBtn) {
                  takeawayBtn.classList.add('bg-[#f7310f]', 'text-white');
                  takeawayBtn.classList.remove('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
                  dineInBtn.classList.remove('bg-[#f7310f]', 'text-white');
                  dineInBtn.classList.add('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
              }

              // 显示自动切换提示
              if (typeof Toastify !== 'undefined') {
                  Toastify({
                      text: `🥡 <?php echo ruiyi_translate('Cambiado automáticamente a modo para llevar', 'Automatically switched to takeaway mode', '自动切换为外卖模式'); ?>`,
                      duration: 3000,
                      gravity: "top",
                      position: "center",
                      style: { background: "#17a2b8" }
                  }).showToast();
              }

              // 立即启动外卖结账流程，不需要继续堂食逻辑
              startTakeawayCheckout();
              return;
          }

          // 仅当订单类型是堂食(servir)时才需要桌位号
          const requireTableNumber = tipoPedidoSeleccionado === 'servir';

          // 如果是堂食但没有选择桌位号（这种情况现在不应该发生，因为上面已经自动切换了）
          if (requireTableNumber && !tableNumber) {
            Swal.fire({
              icon: 'warning',
              title: '⚠️ <?php echo ruiyi_translate("Mesa no seleccionada", "Table not selected", "未选择餐桌"); ?>',
              text: '<?php echo ruiyi_translate("Por favor, selecciona una mesa antes de enviar el pedido", "Please select a table before sending the order", "请选择餐桌后再发送订单"); ?>.',
              confirmButtonColor: '#f7310f'
            });
            return;
          }

          // 订单类型确认
          let tipoPedidoTexto = window.RUIYI_TRANS.forTableService;
          
          if (tipoPedidoSeleccionado === 'llevar') {
            tipoPedidoTexto = window.RUIYI_TRANS.takeaway;
          }

          // 计算总金额（只计算新商品）
          // 🔥 使用customPrice字段（如果存在），否则使用原价
          const subtotal = newItems.reduce((sum, item) => {
            const itemPrice = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
            return sum + (itemPrice * item.quantity);
          }, 0);
          const total = subtotal;

          // 🔥 移除确认订单弹窗，直接创建订单

          // 直接执行订单创建操作
          crearPedidoFinal();
        });
      }
      
      // 外卖结账函数
      function startTakeawayCheckout() {
          // 🔥 过滤掉数量为0的商品
          const validCartItems = cart.filter(item => item.quantity > 0);

          // 检查购物车是否为空
          if (!validCartItems || validCartItems.length === 0) {
              Swal.fire({
                  icon: 'warning',
                  title: '🛍️ <?php echo ruiyi_translate("Carrito vacío", "Cart is empty", "购物车为空"); ?>',
                  text: '<?php echo ruiyi_translate("Por favor agrega productos al carrito primero", "Please add products to cart first", "请先添加商品到购物车"); ?>',
                  confirmButtonColor: '#f7310f'
              });
              return;
          }

          // 计算总金额（含 supplements，只计算数量>0的商品）
          const totalAmount = parseFloat(validCartItems.reduce((sum, item) => {
              return sum + ((parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0))) * item.quantity);
          }, 0).toFixed(2));

          // 显示外卖结账弹窗（只传递有效商品）
          showTakeawayCheckoutModal(totalAmount, validCartItems);
      }
      
