                  </div>
              `,
	              width: ruiyiIsCheckoutTouchKeypadEnabled() ? 860 : 850,
              heightAuto: false,
              customClass: {
                  popup: 'ruiyi-takeaway-modal' + (ruiyiIsCheckoutTouchKeypadEnabled() ? ' checkout-touch-popup' : ''),
                  htmlContainer: 'ruiyi-takeaway-modal-content'
              },
              showCancelButton: true,
              confirmButtonText: '<?php echo ruiyi_translate('Confirmar checkout', 'Confirm Checkout', '确认结账'); ?>',
              cancelButtonText: '<?php echo ruiyi_translate('Cancelar', 'Cancel', '取消'); ?>',
              preConfirm: () => {
                  // 🔥 改进：通过多种方式查找选中的支付方式
                  let selectedPaymentMethod = document.querySelector('.takeaway-payment-method-btn.border-green-500, .takeaway-payment-method-btn.border-blue-500, .takeaway-payment-method-btn.border-purple-500, .takeaway-payment-method-btn.border-teal-500');

                  // 如果没找到，尝试查找任何有选中样式的按钮
                  if (!selectedPaymentMethod) {
                      selectedPaymentMethod = document.querySelector('.takeaway-payment-method-btn.bg-green-50, .takeaway-payment-method-btn.bg-blue-50, .takeaway-payment-method-btn.bg-purple-50, .takeaway-payment-method-btn.bg-teal-50');
                  }

                  // 🔥 移除支付方式验证 - 默认使用现金支付
                  let paymentMethod = 'cash'; // 默认现金支付
                  if (selectedPaymentMethod) {
                      paymentMethod = selectedPaymentMethod.getAttribute('data-method') || 'cash';
                  }

                  // 🔥 使用有效总额（考虑抵扣券后的金额）
                  const effectiveTotal = window.takeawayEffectiveTotal !== undefined ? window.takeawayEffectiveTotal : totalAmount;

                  // 处理不同支付方式的数据
                  let receivedAmount = effectiveTotal;
                  let changeAmount = 0;
                  let cashAmount = 0;
                  let cardAmount = 0;
                  let bizumAmount = 0;

                  if (paymentMethod === 'cash') {
                      // 现金支付
                      const receivedAmountInput = document.getElementById('takeaway-received-amount');
                      if (receivedAmountInput && receivedAmountInput.value) {
                          receivedAmount = parseFloat(receivedAmountInput.value) || effectiveTotal;
                          changeAmount = Math.max(0, receivedAmount - effectiveTotal);
                      }
                      cashAmount = effectiveTotal; // 🔥 修复：设置现金金额
                  } else if (paymentMethod === 'card') {
                      // 🔥 修复：刷卡支付设置cardAmount为折扣后金额
                      cardAmount = effectiveTotal;
                  } else if (paymentMethod === 'bizum') {
                      // Bizum/转账支付：和刷卡相同逻辑
                      bizumAmount = effectiveTotal;
                  } else if (paymentMethod === 'mixed') {
                      // 混合支付
                      const mixedCashInput = document.getElementById('takeaway-mixed-cash-amount');
                      const mixedCardInput = document.getElementById('takeaway-mixed-card-amount');

                      cashAmount = parseFloat(mixedCashInput?.value) || 0;
                      cardAmount = parseFloat(mixedCardInput?.value) || 0;

                      // 🔥 验证混合支付金额 - 使用有效总额（抵扣券后的金额）
                      const totalPayment = cashAmount + cardAmount;
                      if (Math.abs(totalPayment - effectiveTotal) > 0.01) {
                          Swal.showValidationMessage('<?php echo ruiyi_translate('El total del pago no coincide con el monto del pedido', 'Payment total does not match order amount', '支付总额与订单金额不匹配'); ?>');
                          return false;
                      }

                      if (cashAmount <= 0 || cardAmount <= 0) {
                          Swal.showValidationMessage('<?php echo ruiyi_translate('Los montos de efectivo y tarjeta deben ser mayores a 0', 'Both cash and card amounts must be greater than 0', '现金和刷卡金额必须都大于0'); ?>');
                          return false;
                      }
                  }

                  // 客户信息已移至历史模块开票功能
                  let customerInfo = null;

                  // 🔥 获取餐厅抵扣票金额
                  const chequeRestauranteAmount = parseFloat(document.getElementById('takeaway-cheque-restaurante')?.value) || 0;


                  return {
                      customerInfo: customerInfo,
                      paymentMethod: paymentMethod,
                      receivedAmount: receivedAmount,
                      changeAmount: changeAmount,
                      cashAmount: cashAmount,
                      cardAmount: cardAmount,
                      bizumAmount: bizumAmount,
                      chequeRestauranteAmount: chequeRestauranteAmount
                  };
              },
              didOpen: () => {
                  // 初始化支付方式选择
                  initTakeawayPaymentMethods(totalAmount);

                  // 🔥 初始化餐厅抵扣票功能
                  initTakeawayChequeRestaurante(totalAmount);

                  // 🔥 初始化触屏数字键盘
                  ruiyiAttachCheckoutTouchKeypad(Swal.getPopup());

                  // 🔥 默认选择排序后的第一个支付方式
                  const firstMethod = window.applyPaymentMethodOrder(document, '.takeaway-payment-method-btn', '#takeaway-cheque-btn');
                  setTimeout(() => {
                      const firstBtn = document.querySelector(
                          firstMethod === 'cheque' ? '#takeaway-cheque-btn' : '.takeaway-payment-method-btn[data-method="' + firstMethod + '"]'
                      );
                      if (firstBtn) firstBtn.click();
                  }, 100);

                  // 🔥 定义 INTRO 键监听器（赋值给外部变量）
                  enterKeyHandler = function(e) {
                      if (e.key === 'Enter' && !e.shiftKey && !e.ctrlKey && !e.altKey) {
                          // 🔥 防抖机制：防止200ms内重复触发
                          const now = Date.now();
                          if (now - lastEnterTime < 200) {
                              e.preventDefault();
                              e.stopPropagation();
                              e.stopImmediatePropagation();
                              return;
                          }
                          lastEnterTime = now;

                          // 🔥 强化事件阻止
                          e.preventDefault();
                          e.stopPropagation();
                          e.stopImmediatePropagation();


                          // 🔥 获取并验证确认按钮
                          const confirmButton = Swal.getConfirmButton();
                          if (!confirmButton) {
                              // console.error('[弹窗INTRO] 确认按钮未找到');
                              return;
                          }

                          const isDisabled = confirmButton.disabled || confirmButton.hasAttribute('disabled');

                          if (!isDisabled) {
                              // 使用 setTimeout 确保点击在事件循环的下一个周期执行
                              setTimeout(() => {
                                  confirmButton.click();
                              }, 10);
                          } else {
                              // console.warn('[弹窗INTRO] ⚠️ 确认按钮被禁用，无法点击');
                          }
                      }
                  };

                  // 使用捕获阶段监听，优先级更高
                  document.addEventListener('keydown', enterKeyHandler, true);
              },
              willClose: () => {
                  // 🔥 弹窗关闭前清理事件监听器
                  if (enterKeyHandler) {
                      document.removeEventListener('keydown', enterKeyHandler, true);
                      enterKeyHandler = null; // 清空引用
                  }
              },
              didClose: () => {
                  // 🔥 弹窗完全关闭后再次确保清理（双重保险）
                  if (enterKeyHandler) {
                      document.removeEventListener('keydown', enterKeyHandler, true);
                      enterKeyHandler = null; // 清空引用
                  }
                  lastEnterTime = 0; // 重置防抖时间戳
              }
          }).then((result) => {
              if (result.isConfirmed) {
                  // 处理外卖订单创建
                  processTakeawayOrder(result.value, cartItems, totalAmount);
              }
          });
      }

      // 初始化外卖结账模态窗的标签页切换
      function initTakeawayTabSwitching() {
          const tabButtons = document.querySelectorAll('.takeaway-tab-button');
          const tabPanels = document.querySelectorAll('.takeaway-tab-panel');
          
          tabButtons.forEach(button => {
              button.addEventListener('click', function() {
                  const targetTab = this.getAttribute('data-tab');
                  
                  // 更新按钮状态
                  tabButtons.forEach(btn => {
                      btn.classList.remove('text-green-600', 'border-b-2', 'border-green-500');
                      btn.classList.add('text-gray-500');
                  });
                  
                  this.classList.add('text-green-600', 'border-b-2', 'border-green-500');
                  this.classList.remove('text-gray-500');
                  
                  // 更新面板显示
                  tabPanels.forEach(panel => {
                      panel.classList.add('hidden');
                      panel.classList.remove('active');
                  });
                  
                  const targetPanel = document.getElementById(`takeaway-${targetTab}-panel`);
                  if (targetPanel) {
                      targetPanel.classList.remove('hidden');
                      targetPanel.classList.add('active');
                  }
              });
          });
      }
      
      // 初始化外卖支付方式选择
      function initTakeawayPaymentMethods(totalAmount) {
          const paymentButtons = document.querySelectorAll('.takeaway-payment-method-btn');
          const cashSection = document.getElementById('takeaway-cash-section');
          const mixedSection = document.getElementById('takeaway-mixed-section');
          const chequeSection = document.getElementById('takeaway-cheque-section');
          const receivedInput = document.getElementById('takeaway-received-amount');
          const changeCalc = document.getElementById('takeaway-change-calculation');
          const receivedDisplay = document.getElementById('takeaway-received-display');
          const changeAmount = document.getElementById('takeaway-change-amount');
          const chequeBtn = document.getElementById('takeaway-cheque-btn');

          // 🔥 刷卡找零相关元素
          const cardSectionTakeaway = document.getElementById('takeaway-card-section');
          const cardReceivedInputTakeaway = document.getElementById('takeaway-card-received-amount');
          const cardChangeCalcTakeaway = document.getElementById('takeaway-card-change-calculation');
          const cardReceivedDisplayTakeaway = document.getElementById('takeaway-card-received-display');
          const cardChangeAmountTakeaway = document.getElementById('takeaway-card-change-amount');

          // 混合支付相关元素
          const mixedCashInput = document.getElementById('takeaway-mixed-cash-amount');
          const mixedCardInput = document.getElementById('takeaway-mixed-card-amount');
          const mixedValidation = document.getElementById('takeaway-mixed-validation');
          const mixedCashDisplay = document.getElementById('takeaway-mixed-cash-display');
          const mixedCardDisplay = document.getElementById('takeaway-mixed-card-display');
          const mixedTotalDisplay = document.getElementById('takeaway-mixed-total-display');

          // 🔥 获取有效总额（考虑抵扣后的金额）
          function getEffectiveTotal() {
              return window.takeawayEffectiveTotal || totalAmount;
          }

          // 混合支付计算函数
          function calculateTakeawayMixed() {
              const effectiveTotal = getEffectiveTotal();
              const cashAmount = parseFloat(mixedCashInput.value) || 0;
              const remainingAmount = effectiveTotal - cashAmount;
              const cardAmount = Math.max(0, remainingAmount);

              // 更新刷卡金额
              mixedCardInput.value = cardAmount.toFixed(2);

              // 更新显示
              if (mixedCashDisplay) mixedCashDisplay.textContent = `€${cashAmount.toFixed(2)}`;
              if (mixedCardDisplay) mixedCardDisplay.textContent = `€${cardAmount.toFixed(2)}`;
              if (mixedTotalDisplay) mixedTotalDisplay.textContent = `€${(cashAmount + cardAmount).toFixed(2)}`;

              // 显示/隐藏验证区域
              if (mixedValidation && cashAmount > 0) {
                  mixedValidation.style.display = 'block';

                  // 检查金额是否匹配
                  const totalPayment = cashAmount + cardAmount;
                  if (Math.abs(totalPayment - effectiveTotal) < 0.01) {
                      mixedValidation.className = 'mt-3 p-3 rounded-lg bg-green-50 border border-green-200';
                  } else {
                      mixedValidation.className = 'mt-3 p-3 rounded-lg bg-red-50 border border-red-200';
                  }
              } else if (mixedValidation) {
                  mixedValidation.style.display = 'none';
              }
          }

          // 🔥 计算刷卡找零（快速结账）
          function calculateTakeawayCardChange() {
              let received = parseFloat(cardReceivedInputTakeaway.value) || 0;
              const effectiveTotal = getEffectiveTotal();
              if (received >= effectiveTotal) {
                  const change = received - effectiveTotal;
                  cardReceivedDisplayTakeaway.textContent = '€' + received.toFixed(2);
                  cardChangeAmountTakeaway.textContent = '€' + change.toFixed(2);
                  cardChangeCalcTakeaway.style.display = 'grid';
              } else {
                  cardChangeCalcTakeaway.style.display = 'none';
              }
          }

          // 🔥 Vale 按钮点击事件（切换显示抵扣券输入区域）
          if (chequeBtn) {
              chequeBtn.addEventListener('click', function() {
                  // 切换抵扣券区域显示
                  if (chequeSection) {
                      const isHidden = chequeSection.classList.contains('hidden');
                      if (isHidden) {
                          // 🔥 隐藏其他支付区域
                          if (cashSection) cashSection.classList.add('hidden');
                          if (mixedSection) mixedSection.classList.add('hidden');

                          // 🔥 重置其他支付按钮样式
                          paymentButtons.forEach(b => {
                              b.classList.remove('border-green-500', 'bg-green-50', 'border-blue-500', 'bg-blue-50', 'border-purple-500', 'bg-purple-50');
                              b.classList.add('border-gray-300');
                          });

                          chequeSection.classList.remove('hidden');
                          this.classList.add('border-orange-500', 'bg-orange-50');
                          // 聚焦到输入框
                          const chequeInput = document.getElementById('takeaway-cheque-restaurante');
                          if (chequeInput && !chequeInput.disabled) {
                              chequeInput.focus();
                          }
                      } else {
                          chequeSection.classList.add('hidden');
                          this.classList.remove('border-orange-500', 'bg-orange-50');
                          this.classList.add('border-gray-300');
                      }
                  }
              });
          }

          paymentButtons.forEach(btn => {
              btn.addEventListener('click', function() {
                  // 重置所有支付方式按钮样式（不包括 Vale 按钮）
                  paymentButtons.forEach(b => {
                      b.classList.remove('border-green-500', 'bg-green-50', 'border-blue-500', 'bg-blue-50', 'border-purple-500', 'bg-purple-50', 'border-teal-500', 'bg-teal-50');
                      b.classList.add('border-gray-300');
                  });

                  // 隐藏所有支付区域
                  if (cashSection) cashSection.classList.add('hidden');
                  if (cardSectionTakeaway) cardSectionTakeaway.classList.add('hidden');
                  if (mixedSection) mixedSection.classList.add('hidden');

                  // 🔥 隐藏抵扣券区域（无论是否已应用）
                  const chequeInput = document.getElementById('takeaway-cheque-restaurante');
                  if (chequeSection) {
                      chequeSection.classList.add('hidden');
                      // 如果抵扣券未应用，重置 Vale 按钮样式
                      if (chequeInput && !chequeInput.disabled && chequeBtn) {
                          chequeBtn.classList.remove('border-orange-500', 'bg-orange-50', 'border-green-500', 'bg-green-50');
                          chequeBtn.classList.add('border-gray-300');
                      }
                  }

                  const method = this.getAttribute('data-method');
                  const effectiveTotal = getEffectiveTotal();

                  if (method === 'cash') {
                      this.classList.add('border-green-500', 'bg-green-50');
                      cashSection.classList.remove('hidden');
                      // 🔥 更新 placeholder 为有效总额
                      if (receivedInput) {
                          receivedInput.placeholder = `€${effectiveTotal.toFixed(2)}`;
                      }
                      receivedInput.focus();
                  } else if (method === 'card') {
                      this.classList.add('border-blue-500', 'bg-blue-50');
                      // 🔥 刷卡找零功能
                      if (window.posSettings?.cardChangeEnabled && cardSectionTakeaway) {
                          cardSectionTakeaway.classList.remove('hidden');
                          if (cardReceivedInputTakeaway) {
                              cardReceivedInputTakeaway.value = '';
                              cardReceivedInputTakeaway.placeholder = `€${effectiveTotal.toFixed(2)}`;
                              cardReceivedInputTakeaway.focus();
                          }
                          calculateTakeawayCardChange();
                      }
                  } else if (method === 'bizum') {
                      this.classList.add('border-teal-500', 'bg-teal-50');
                  } else if (method === 'mixed') {
                      this.classList.add('border-purple-500', 'bg-purple-50');
                      mixedSection.classList.remove('hidden');
                      if (mixedCashInput) {
                          mixedCashInput.value = '';
                          mixedCashInput.focus();
                      }
                      calculateTakeawayMixed();
                  }
              });
          });

          // 添加混合支付输入监听器
          if (mixedCashInput) {
              mixedCashInput.addEventListener('input', calculateTakeawayMixed);

              // 🔥 外卖混合支付输入框按Enter键完成支付
              mixedCashInput.addEventListener('keydown', function(e) {
                  if (e.key === 'Enter') {
                      e.preventDefault();
                      e.stopPropagation();
                      const confirmButton = Swal.getConfirmButton();
                      if (confirmButton && !confirmButton.disabled) {
                          confirmButton.click();
                      }
                  }
              });
          }

          // 现金计算
          if (receivedInput) {
              receivedInput.addEventListener('input', function() {
                  let received = parseFloat(this.value) || 0;
                  const effectiveTotal = getEffectiveTotal();

                  const change = Math.max(0, received - effectiveTotal);

                  if (received >= effectiveTotal) {
                      changeCalc.style.display = 'grid';
                      receivedDisplay.textContent = '€' + received.toFixed(2);
                      changeAmount.textContent = '€' + change.toFixed(2);
                  } else {
                      changeCalc.style.display = 'none';
                  }
              });

              // 🔥 外卖收款金额输入框按Enter键完成支付
              receivedInput.addEventListener('keydown', function(e) {
                  if (e.key === 'Enter') {
                      e.preventDefault();
                      e.stopPropagation();
                      const confirmButton = Swal.getConfirmButton();
                      if (confirmButton && !confirmButton.disabled) {
                          confirmButton.click();
                      }
                  }
              });
          }

          // 🔥 刷卡找零输入监听器（快速结账）
          if (cardReceivedInputTakeaway) {
              cardReceivedInputTakeaway.addEventListener('input', calculateTakeawayCardChange);

              cardReceivedInputTakeaway.addEventListener('keydown', function(e) {
                  if (e.key === 'Enter') {
                      e.preventDefault();
                      e.stopPropagation();
                      const confirmButton = Swal.getConfirmButton();
                      if (confirmButton && !confirmButton.disabled) {
                          confirmButton.click();
                      }
                  }
              });
          }
      }

      // 🔥 初始化餐厅抵扣票功能 (Cheque Restaurante)
      function initTakeawayChequeRestaurante(originalTotal) {
          const chequeInput = document.getElementById('takeaway-cheque-restaurante');
          const applyBtn = document.getElementById('apply-cheque-takeaway');
          const appliedSection = document.getElementById('cheque-applied-takeaway');
          const amountDisplay = document.getElementById('cheque-amount-display-takeaway');
          const remainingDisplay = document.getElementById('takeaway-remaining-amount');
          const totalDisplay = document.getElementById('takeaway-total-display');
          const receivedInput = document.getElementById('takeaway-received-amount');

          if (!chequeInput || !applyBtn) return;

          // 存储当前有效的应付金额（用于支付计算）
          window.takeawayEffectiveTotal = originalTotal;

          applyBtn.addEventListener('click', function() {
              const chequeAmount = parseFloat(chequeInput.value) || 0;

              if (chequeAmount <= 0) {
                  Swal.fire({
                      icon: 'warning',
                      title: '<?php echo ruiyi_translate("Importe inválido", "Invalid amount", "金额无效"); ?>',
                      text: '<?php echo ruiyi_translate("Por favor ingrese un importe válido", "Please enter a valid amount", "请输入有效的抵扣金额"); ?>',
                      confirmButtonColor: '#f97316'
                  });
                  return;
              }

              if (chequeAmount > originalTotal) {
                  Swal.fire({
                      icon: 'error',
                      title: '<?php echo ruiyi_translate("Importe excedido", "Amount exceeded", "金额超出"); ?>',
                      text: '<?php echo ruiyi_translate("El importe del vale no puede superar el total del pedido", "Voucher amount cannot exceed order total", "抵扣金额不能超过订单总额"); ?>',
                      confirmButtonColor: '#f97316'
                  });
                  return;
              }

              // 计算剩余应付金额
              const remainingAmount = originalTotal - chequeAmount;

              // 更新显示
              if (amountDisplay) amountDisplay.textContent = chequeAmount.toFixed(2);
              if (remainingDisplay) remainingDisplay.textContent = '€' + remainingAmount.toFixed(2);
              if (totalDisplay) {
                  totalDisplay.innerHTML = `<span class="line-through text-gray-400 text-xl mr-2">€${originalTotal.toFixed(2)}</span><span class="text-green-600">€${remainingAmount.toFixed(2)}</span>`;
              }

              // 显示已应用区域
              if (appliedSection) appliedSection.classList.remove('hidden');

              // 更新有效总额
              window.takeawayEffectiveTotal = remainingAmount;

              // 🔥 更新现金收款输入框的 placeholder
              if (receivedInput) {
                  receivedInput.placeholder = `€${remainingAmount.toFixed(2)}`;
                  receivedInput.value = ''; // 清空已输入的值
              }

              // 🔥 更新 Vale 按钮样式为已应用状态
              const chequeBtn = document.getElementById('takeaway-cheque-btn');
              if (chequeBtn) {
                  chequeBtn.classList.remove('border-gray-300', 'hover:border-orange-500', 'hover:bg-orange-50');
                  chequeBtn.classList.add('border-green-500', 'bg-green-50');
                  chequeBtn.innerHTML = `<i class="fas fa-check-circle text-2xl mb-1 text-green-600"></i><span class="text-sm font-medium text-green-700">-€${chequeAmount.toFixed(2)}</span>`;
              }

              // 禁用输入和隐藏应用按钮，显示取消按钮
              chequeInput.disabled = true;
              applyBtn.classList.add('hidden');
              const cancelBtn = document.getElementById('cancel-cheque-takeaway');
              if (cancelBtn) cancelBtn.classList.remove('hidden');

              Toastify({
                  text: '<?php echo ruiyi_translate("Vale aplicado correctamente", "Voucher applied successfully", "抵扣票已成功应用"); ?>',
                  duration: 2000,
                  gravity: "top",
                  position: "center",
                  style: { background: "#10b981" }
              }).showToast();
          });

          // 🔥 取消抵扣票应用
          const cancelBtn = document.getElementById('cancel-cheque-takeaway');
          if (cancelBtn) {
              cancelBtn.addEventListener('click', function() {
                  // 重置输入框
                  if (chequeInput) {
                      chequeInput.value = '';
                      chequeInput.disabled = false;
                  }

                  // 隐藏取消按钮，显示应用按钮
                  this.classList.add('hidden');
                  if (applyBtn) applyBtn.classList.remove('hidden');

                  // 隐藏已应用区域
                  if (appliedSection) appliedSection.classList.add('hidden');

                  // 恢复原价显示
                  if (totalDisplay) {
                      totalDisplay.innerHTML = `€${originalTotal.toFixed(2)}`;
                  }

                  // 重置有效总额
                  window.takeawayEffectiveTotal = originalTotal;

                  // 更新现金收款输入框的 placeholder
                  if (receivedInput) {
                      receivedInput.placeholder = `€${originalTotal.toFixed(2)}`;
                      receivedInput.value = '';
                  }

                  // 重置 Vale 按钮样式
                  const chequeBtn = document.getElementById('takeaway-cheque-btn');
                  if (chequeBtn) {
                      chequeBtn.classList.remove('border-green-500', 'bg-green-50');
                      chequeBtn.classList.add('border-gray-300');
                      chequeBtn.innerHTML = `<i class="fas fa-ticket-alt text-2xl mb-1 text-orange-500"></i><span class="text-sm font-medium"><?php echo ruiyi_translate('Vale', 'Voucher', '抵扣票'); ?></span>`;
                  }

                  Toastify({
                      text: '<?php echo ruiyi_translate("Vale cancelado", "Voucher cancelled", "抵扣票已取消"); ?>',
                      duration: 2000,
                      gravity: "top",
                      position: "center",
                      style: { background: "#f97316" }
                  }).showToast();
              });
          }
      }

      // 初始化客户信息功能
      function initCustomerInfoFeatures() {
          // 🔥 自动填充 delivery 客户数据（如果存在）
          const currentTable = document.getElementById('table-number')?.value.trim();
          if (currentTable) {
              const deliveryData = getDeliveryCustomerData(currentTable);
              if (deliveryData) {
                  // 自动填充客户信息字段
                  const nameField = document.getElementById('takeaway-customer-name');
                  const phoneField = document.getElementById('takeaway-customer-phone');
                  const businessField = document.getElementById('takeaway-customer-business-name');
                  const taxField = document.getElementById('takeaway-customer-cif-nif');
                  const addressField = document.getElementById('takeaway-customer-address');
                  const postalField = document.getElementById('takeaway-customer-postal');
                  const emailField = document.getElementById('takeaway-customer-email');
                  const phoneSearchField = document.getElementById('customer-phone-search');

                  if (nameField) nameField.value = deliveryData.name || '';
                  if (phoneField) phoneField.value = deliveryData.phone || '';
                  if (businessField) businessField.value = deliveryData.business_name || '';
                  if (taxField) taxField.value = deliveryData.cif_nif || '';
                  if (addressField) addressField.value = deliveryData.address || '';
                  if (postalField) postalField.value = deliveryData.postal_code || '';
                  if (emailField) emailField.value = deliveryData.email || '';
                  if (phoneSearchField) phoneSearchField.value = deliveryData.phone || '';

              }
          }

          // 🔥 新版：电话号码自动搜索功能
          const phoneInput = document.getElementById('takeaway-customer-phone');
          const searchResults = document.getElementById('customer-search-results');
          const loadingIndicator = document.getElementById('customer-search-loading');
          let searchTimeout = null;

          if (phoneInput && searchResults) {
              // 输入时自动搜索（防抖）
              phoneInput.addEventListener('input', function() {
                  const phone = this.value.trim();

                  // 清除之前的定时器
                  if (searchTimeout) {
                      clearTimeout(searchTimeout);
                  }

                  // 隐藏搜索结果
                  searchResults.classList.add('hidden');

                  // 至少输入3位才开始搜索
                  if (phone.length < 3) {
                      return;
                  }

                  // 显示加载指示器
                  if (loadingIndicator) {
                      loadingIndicator.classList.remove('hidden');
                  }

                  // 防抖延迟搜索
                  searchTimeout = setTimeout(() => {
                      searchCustomersByPhone(phone);
                  }, 300);
              });

              // 点击其他地方隐藏搜索结果
              document.addEventListener('click', function(e) {
                  if (!phoneInput.contains(e.target) && !searchResults.contains(e.target)) {
                      searchResults.classList.add('hidden');
                  }
              });
          }

          // 🔥 搜索客户函数
          function searchCustomersByPhone(phone) {
              var ajaxUrl = window.ajaxUrl || '<?php echo admin_url('admin-ajax.php'); ?>';
              var ajaxNonce = window.RUIYI_POS?.nonce || posNonce;

              const formData = new URLSearchParams({
                  action: 'ruiyi_fuzzy_search_customers',
                  search_type: 'phone',
                  search_term: phone,
                  limit: 5,
                  nonce: ajaxNonce
              });

              fetch(ajaxUrl, {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                  body: formData
              })
              .then(response => response.json())
              .then(data => {
                  // 隐藏加载指示器
                  if (loadingIndicator) {
                      loadingIndicator.classList.add('hidden');
                  }

                  if (data.success && data.data.customers && data.data.customers.length > 0) {
                      renderCustomerSearchResults(data.data.customers);
                  } else {
                      // 没有找到结果，隐藏下拉框
                      searchResults.classList.add('hidden');
                  }
              })
              .catch(error => {
                  console.error('[客户搜索] 错误:', error);
                  if (loadingIndicator) {
                      loadingIndicator.classList.add('hidden');
                  }
                  searchResults.classList.add('hidden');
              });
          }

          // 🔥 渲染搜索结果
          function renderCustomerSearchResults(customers) {
              if (!searchResults) return;

              searchResults.innerHTML = '';

              customers.forEach(customer => {
                  const item = document.createElement('div');
                  item.className = 'px-4 py-3 hover:bg-green-50 cursor-pointer border-b border-gray-100 last:border-b-0';
                  item.innerHTML = `
                      <div class="flex justify-between items-center">
                          <div>
                              <div class="font-medium text-gray-800">${customer.name || '<?php echo ruiyi_translate('Sin nombre', 'No name', '无姓名'); ?>'}</div>
                              <div class="text-sm text-gray-500">
                                  <i class="fas fa-phone text-xs mr-1"></i>${customer.phone}
                                  ${customer.address ? '<span class="ml-2"><i class="fas fa-map-marker-alt text-xs mr-1"></i>' + customer.address.substring(0, 20) + (customer.address.length > 20 ? '...' : '') + '</span>' : ''}
                              </div>
                          </div>
                          <i class="fas fa-chevron-right text-gray-400"></i>
                      </div>
                  `;

                  // 点击选择客户
                  item.addEventListener('click', function() {
                      selectCustomer(customer);
                  });

                  searchResults.appendChild(item);
              });

              searchResults.classList.remove('hidden');
          }

          // 🔥 选择客户并填充表单
          function selectCustomer(customer) {
              document.getElementById('takeaway-customer-phone').value = customer.phone || '';
              document.getElementById('takeaway-customer-name').value = customer.name || '';
              document.getElementById('takeaway-customer-business-name').value = customer.business_name || '';
              document.getElementById('takeaway-customer-cif-nif').value = customer.cif_nif || '';
              document.getElementById('takeaway-customer-address').value = customer.address || '';
              document.getElementById('takeaway-customer-postal').value = customer.postal_code || '';
              document.getElementById('takeaway-customer-email').value = customer.email || '';

              // 隐藏搜索结果
              if (searchResults) {
                  searchResults.classList.add('hidden');
              }

              // 显示提示
              Toastify({
                  text: `✅ <?php echo ruiyi_translate('Cliente seleccionado', 'Customer selected', '已选择客户'); ?>: ${customer.name}`,
                  duration: 2000,
                  gravity: 'top',
                  position: 'center',
                  style: { background: '#10b981' }
              }).showToast();
          }
      }
      
      // 根据电话查找客户
      function findCustomerByPhone(phone) {
          const formData = new URLSearchParams({
              action: 'ruiyi_find_customer_by_phone',
              phone: phone,
              nonce: window.RUIYI_POS?.nonce || posNonce
          });
          
          fetch(window.ajaxUrl || '<?php echo admin_url('admin-ajax.php'); ?>', {
              method: 'POST',
              headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
              body: formData
          })
          .then(response => response.json())
          .then(data => {
              if (data.success && data.data.customer) {
                  const customer = data.data.customer;
                  // 填充客户信息
                  document.getElementById('takeaway-customer-name').value = customer.name;
                  document.getElementById('takeaway-customer-phone').value = customer.phone;
                  document.getElementById('takeaway-customer-business-name').value = customer.business_name || '';
                  document.getElementById('takeaway-customer-cif-nif').value = customer.cif_nif || '';
                  document.getElementById('takeaway-customer-address').value = customer.address || '';
                  document.getElementById('takeaway-customer-postal').value = customer.postal_code || '';
                  document.getElementById('takeaway-customer-email').value = customer.email || '';

                  Toastify({
                      text: `✅ 已找到客户: ${customer.name}`,
                      duration: 2000,
                      gravity: "top",
                      position: "center",
                      style: { background: "#10b981" }
                  }).showToast();
              } else {
                  // 客户不存在，清空表单并填充电话号码
                  document.getElementById('takeaway-customer-name').value = '';
                  document.getElementById('takeaway-customer-phone').value = phone;
                  document.getElementById('takeaway-customer-business-name').value = '';
                  document.getElementById('takeaway-customer-cif-nif').value = '';
                  document.getElementById('takeaway-customer-address').value = '';
                  document.getElementById('takeaway-customer-postal').value = '';
                  document.getElementById('takeaway-customer-email').value = '';

                  Toastify({
                      text: '🆕 新客户，请填写信息',
                      duration: 2000,
                      gravity: "top",
                      position: "center",
                      style: { background: "#3b82f6" }
                  }).showToast();
              }
          })
          .catch(error => {
              alert('查找客户失败: ' + error.message);
          });
      }
      
      // 使用指定购物车数据打印外卖小票（解决数据时序问题）
      // 🔥 新增参数 discountPercent：从调用方传入的折扣百分比（因为 window.currentDiscountPercent 可能已被重置）
      function printTakeawayReceiptWithData(orderId, customerInfo, cartData, paymentData, discountPercent = 0) {
          var ajaxUrl = window.ajaxUrl || '<?php echo admin_url('admin-ajax.php'); ?>';
          var ajaxNonce = window.RUIYI_POS?.nonce || posNonce;

          // 🔥 关键修复：优先使用传入的折扣百分比，如果未传入则尝试从全局变量读取
          // 这解决了 submitOrderUniversal 内部重置 window.currentDiscountPercent 的问题
          const savedDiscountPercent = discountPercent || window.currentDiscountPercent || 0;

          // 显示打印提示 - 已移除
          // Toastify({
          //     text: '<?php echo ruiyi_translate("Preparando recibo para llevar...", "Preparing takeaway receipt...", "正在准备外卖小票..."); ?>',
          //     duration: 2000,
          //     gravity: "top",
          //     position: "center",
          //     style: { background: "#2196f3" }
          // }).showToast();

          // 第一步：重新计算购物车产品的税率

          const recalculateTaxRatesFormData = new URLSearchParams();
          recalculateTaxRatesFormData.append('action', 'ruiyi_get_cart_products_tax_rates');
          recalculateTaxRatesFormData.append('cart_data', JSON.stringify(cartData));
          recalculateTaxRatesFormData.append('nonce', ajaxNonce);

          // 先获取正确的税率数据，然后生成小票
          fetch(ajaxUrl, {
              method: 'POST',
              headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
              body: recalculateTaxRatesFormData
          })
          .then(response => response.json())
          .then(taxData => {
              // 第二步：使用税率数据生成小票
              const printFormData = new URLSearchParams();
              printFormData.append('action', 'ruiyi_pos_get_table_receipt_html');
              printFormData.append('cart_data', JSON.stringify(cartData)); // 使用传递的购物车数据

              // 传递重新计算的税率数据
              if (taxData.success && taxData.data) {
                  printFormData.append('products_with_tax_rates', JSON.stringify(taxData.data));
              } else {
                  // 如果税率获取失败，仍然传递原始数据但添加警告
                  printFormData.append('cart_items', JSON.stringify(cartData));
                  console.warn('🔍 [外卖税率调试] 税率数据获取失败，使用原始购物车数据');
              }

              // 🔥 使用customPrice字段（如果存在），否则使用原价
              // 🔥 修复：使用 toFixed(2) 避免浮点数精度问题
              printFormData.append('order_total', parseFloat(cartData.reduce((sum, item) => {
                const itemPrice = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
                return sum + (itemPrice * item.quantity);
              }, 0).toFixed(2))); // 计算总金额
              printFormData.append('order_type', 'llevar'); // 外卖订单
              printFormData.append('customer_info', JSON.stringify(customerInfo)); // 客户信息
              printFormData.append('order_id_for_reference', orderId); // 仅作参考，不用于查询
              printFormData.append('order_ids_to_print', JSON.stringify([orderId])); // 添加订单ID数组用于获取QR码

              // 🔥 传递支付信息到小票生成
              if (paymentData) {
                  const paymentInfo = {
                      method: paymentData.paymentMethod || 'cash',
                      cashAmount: paymentData.cashAmount || 0,
                      cardAmount: paymentData.cardAmount || 0,
                      receivedAmount: paymentData.receivedAmount || 0,
                      changeAmount: paymentData.changeAmount || 0,
                      chequeRestauranteAmount: paymentData.chequeRestauranteAmount || 0 // 🔥 餐厅抵扣票
                  };
                  printFormData.append('payment_info', JSON.stringify(paymentInfo));

                  // 🔥 如果有餐厅抵扣票，额外传递到小票打印
                  if (paymentData && paymentData.chequeRestauranteAmount && paymentData.chequeRestauranteAmount > 0) {
                      printFormData.append('cheque_restaurante_amount', paymentData.chequeRestauranteAmount);
                  } else {
                  }
              } else {
                  console.warn('[外卖小票] ⚠️ 未传递支付数据，小票将不显示支付信息');
              }

              printFormData.append('nonce', ajaxNonce);

              // 🔥 传递手动折扣信息（百分比折扣）- 外卖订单
              // 使用函数开始时保存的折扣值，避免异步时序问题
              // 🔥 修复：使用 toFixed(2) 避免浮点数精度问题
              const manualDiscountPercent = savedDiscountPercent || 0;
              if (manualDiscountPercent > 0) {
                  const orderTotal = parseFloat(cartData.reduce((sum, item) => {
                      const itemPrice = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
                      return sum + (itemPrice * item.quantity);
                  }, 0).toFixed(2));
                  const originalSubtotal = parseFloat((orderTotal / (1 - manualDiscountPercent / 100)).toFixed(2));
                  const manualDiscountAmount = parseFloat((originalSubtotal - orderTotal).toFixed(2));
                  printFormData.append('discount_percent', manualDiscountPercent);
                  printFormData.append('discount_amount', manualDiscountAmount);
                  printFormData.append('original_subtotal', originalSubtotal);
              }

              return fetch(ajaxUrl, {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                  body: printFormData
              });
          })
          .then(response => {
              if (!response.ok) {
                  throw new Error(`打印请求失败: ${response.status}`);
              }
              return response.json();
          })
          .then(receiptData => {
              if (receiptData.success && receiptData.data && receiptData.data.html) {

                  try {
                      // 🔥 保存小票HTML到localStorage用于重新打印
                      localStorage.setItem('lastReceiptHtml', receiptData.data.html);
                      localStorage.setItem('lastReceiptType', 'takeaway');
                      localStorage.setItem('lastReceiptTimestamp', Date.now());
                      localStorage.setItem('lastReceiptRequestBody', printFormData.toString());

                      // 🖨️ 检查悬浮开关是否启用自动打印（后台开关 + 收银员开关）
                      if (_autoPrintEnabled) {
                          Toastify({
                              text: '🖨️ <?php echo ruiyi_translate("Imprimiendo recibo para llevar", "Printing takeaway receipt", "正在打印外卖小票"); ?>',
                              duration: 2000,
                              gravity: "top",
                              position: "center",
                              style: { background: "#10b981" }
                          }).showToast();

                          if (typeof ruiyiUnifiedPrint !== 'undefined') {
                              const printSuccess = ruiyiUnifiedPrint(receiptData.data.html, 'takeaway');
                              if (!printSuccess) {
                                  throw new Error('CLODOP receipt print failed');
                              }
                          } else {
                              throw new Error('ruiyiUnifiedPrint is not available');
                          }
                      }
                      
                  } catch (error) {
                      console.error('外卖小票打印错误:', error);
                      
                      // 显示错误提示
                      Toastify({
                          text: '❌ <?php echo ruiyi_translate("Error de impresión", "Print failed", "打印失败"); ?>: ' + error.message,
                          duration: 5000,
                          gravity: "top",
                          position: "center",
                          style: { background: "#ef4444" }
                      }).showToast();
                  }
              } else {
                  // API返回错误
                  Toastify({
                      text: '❌ <?php echo ruiyi_translate("Error al obtener datos del recibo", "Failed to get receipt data", "获取小票数据失败"); ?>',
                      duration: 3000,
                      gravity: "top",
                      position: "center",
                      style: { background: "#ef4444" }
                  }).showToast();
              }
          })
          .catch(error => {
              console.error('🔍 [外卖税率调试] 外卖税率重新计算或小票生成错误:', error);

              // 显示网络错误
              Toastify({
                  text: '🚫 <?php echo ruiyi_translate("Error de conexión de impresión", "Print connection error", "打印连接错误"); ?>',
                  duration: 3000,
                  gravity: "top",
                  position: "center",
                  style: { background: "#f59e0b" }
              }).showToast();
          });
      }

      // 处理外卖订单创建
      function processTakeawayOrder(checkoutData, cartItems, totalAmount) {
          var ajaxUrl = window.ajaxUrl || '<?php echo admin_url('admin-ajax.php'); ?>';
          var ajaxNonce = window.RUIYI_POS?.nonce || posNonce;

          // 🔥 关键修复：在函数最开始保存折扣信息
          // 因为 submitOrderUniversal 内部会调用 resetAllPaymentStates，
          // 这会在订单创建后立即重置 window.currentDiscountPercent
          // 所以必须在调用任何异步操作之前保存折扣值
          const savedDiscountPercentForPrint = window.currentDiscountPercent || 0;

          // 🔥 PWA: Check offline status BEFORE showing processing modal
          const isOnline = navigator.onLine && window.RUIYI_POS?.isOnline !== false;
          
          // 🔥 PWA: Use universal order submission (handles offline/online)
          // 🔥 计算折扣金额（如果有折扣）
          // 🔥 修复：使用 toFixed(2) 避免浮点数精度问题（如多出0.01）
          let discountAmount = 0;
          if (savedDiscountPercentForPrint > 0) {
              // totalAmount 是折扣后的金额，反算折扣金额
              const originalTotal = parseFloat((totalAmount / (1 - savedDiscountPercentForPrint / 100)).toFixed(2));
              discountAmount = parseFloat((originalTotal - totalAmount).toFixed(2));
          }

          const orderParams = {
              cart: cartItems,
              table_number: '', // 外卖无桌位号
              order_type: 'llevar',
              payment_method: checkoutData.paymentMethod,
              customer_info: checkoutData.customerInfo,
              discount: 0,
              client: '',
              // 🔥 添加手动折扣信息，用于保存到订单元数据
              discount_percent: savedDiscountPercentForPrint,
              discount_amount: discountAmount
          };

          // 🔥 修复bug：根据支付方式传递对应参数（与堂食逻辑一致）
          if (checkoutData.paymentMethod === 'cash') {
              // 现金支付：传递收款和找零金额
              orderParams.received_amount = checkoutData.receivedAmount || 0;
              orderParams.change_amount = checkoutData.changeAmount || 0;
              orderParams.cash_amount = totalAmount || 0; // 🔥 修复：也传递现金金额
          } else if (checkoutData.paymentMethod === 'mixed') {
              // 混合支付：传递现金和刷卡金额
              orderParams.cash_amount = checkoutData.cashAmount || 0;
              orderParams.card_amount = checkoutData.cardAmount || 0;
          } else if (checkoutData.paymentMethod === 'card') {
              // 🔥 修复：刷卡支付时传递card_amount（折扣后的金额）
              orderParams.card_amount = checkoutData.cardAmount || totalAmount || 0;
          } else if (checkoutData.paymentMethod === 'bizum') {
              // Bizum/转账支付
              orderParams.bizum_amount = checkoutData.bizumAmount || totalAmount || 0;
          }

          // 🔥 如果有餐厅抵扣票，添加到订单参数
          if (checkoutData.chequeRestauranteAmount && checkoutData.chequeRestauranteAmount > 0) {
              orderParams.cheque_restaurante_amount = checkoutData.chequeRestauranteAmount;
          } else {
          }

          // 🔥 秒结账优化：乐观式UI + 后台队列同步
          // PaymentQueue 在线时立即同步，离线时队列等待
          if (typeof PaymentQueue !== 'undefined') {
              // console.log('[秒结账] 🚀 开始乐观式外卖结账...', isOnline ? '(在线)' : '(离线)');

              // 1. 立即开钱箱（现金/混合支付）
              const openDrawerOnCardTakeaway = window.clodopConfig?.openDrawerOnCard || false;
              const paymentMethodTakeaway = checkoutData.paymentMethod;
              const shouldOpenDrawerTakeaway = paymentMethodTakeaway === 'cash' || paymentMethodTakeaway === 'mixed' || (paymentMethodTakeaway === 'card' && openDrawerOnCardTakeaway);
              if (shouldOpenDrawerTakeaway && typeof abrirCajonDinero === 'function') {
                  abrirCajonDinero().catch(err => { /* 开钱箱失败静默处理 */ });
              }

              // 2. 立即显示成功提示
              Toastify({
                  text: '✅ <?php echo ruiyi_translate("Pedido completado", "Order completed", "订单已完成"); ?>',
                  duration: 2500,
                  gravity: 'top',
                  position: 'center',
                  style: { background: 'linear-gradient(to right, #00b09b, #96c93d)' }
              }).showToast();

              // 🔥 保存上一单信息（在清空购物车前）
              // 计算原价（折扣前）和实付金额（折扣+抵扣后）
              const chequeAmountTakeaway = checkoutData.chequeRestauranteAmount || 0;
              // 🔥 【关键修复】实付金额 = 折扣后金额 - 抵扣券
              const actualPaidTakeaway = Math.max(0, totalAmount - chequeAmountTakeaway);
              // 🔥 原价 = 先加回抵扣券，再除以折扣系数
              let originalTotalTakeaway = totalAmount; // 折扣后金额
              if (savedDiscountPercentForPrint > 0) {
                originalTotalTakeaway = parseFloat((totalAmount / (1 - savedDiscountPercentForPrint / 100)).toFixed(2));
              }
              saveAndShowLastOrderInfo({
                  totalAmount: actualPaidTakeaway, // 🔥 修复：传入实付金额（扣除抵扣券后）
                  originalTotal: originalTotalTakeaway, // 🔥 原价（折扣前，不含抵扣券计算）
                  discountAmount: discountAmount || 0, // 🔥 折扣金额
                  chequeAmount: chequeAmountTakeaway, // 🔥 抵扣券金额
                  paymentMethod: paymentMethodTakeaway,
                  receivedAmount: checkoutData.receivedAmount || 0,
                  changeAmount: checkoutData.changeAmount || 0,
                  cashAmount: checkoutData.cashAmount || 0,
                  cardAmount: checkoutData.cardAmount || 0,
                  tableNumber: '',
                  orderType: 'takeaway'
              });

              // 🔥 立即保存本地小票到localStorage（支持离线模式打印）
              saveLocalReceiptToStorage({
                  cartItems: cartItems,
                  tableDisplayName: '', // 外卖无桌位
                  paymentInfo: {
                      method: paymentMethodTakeaway,
                      receivedAmount: checkoutData.receivedAmount || 0,
                      changeAmount: checkoutData.changeAmount || 0,
                      cashAmount: checkoutData.cashAmount || 0,
                      cardAmount: checkoutData.cardAmount || 0
                  },
                  totalAmount: actualPaidTakeaway,
                  originalTotal: originalTotalTakeaway,
                  discountAmount: discountAmount || 0,
                  discountPercent: savedDiscountPercentForPrint || 0,
                  chequeAmount: chequeAmountTakeaway,
                  orderType: 'takeaway'
              }, 'takeaway');

              // 3. 立即清空购物车
              cart = [];
              renderCart();

              // 🔥🔥🔥 关键修复：显式清除收银购物车持久化存储
              // 必须显式调用，因为 savePosCartToStorage 可能因 _posCartRestoreComplete=false 而跳过
              if (typeof clearPosCartStorage === 'function') {
                  clearPosCartStorage();
              }

              // 隐藏查看模式按钮和工具箱
              const viewModeBtnsTakeaway = ['checkout-table-btn', 'toolbox-toggle-btn'];
              viewModeBtnsTakeaway.forEach(btnId => {
                  const btn = document.getElementById(btnId);
                  if (btn) btn.classList.add('hidden');
              });

              const cartActionsContainerTakeaway = document.querySelector('.cart-actions-fixed');
              if (cartActionsContainerTakeaway && window.Alpine) {
                  const alpineDataTakeaway = Alpine.$data(cartActionsContainerTakeaway);
                  if (alpineDataTakeaway) alpineDataTakeaway.toolboxOpen = false;
              }

              // 重置支付状态
              resetAllPaymentStates('instant_takeaway_checkout');

              // 4. 后台队列处理服务器同步
              // 🔥 关键修复：根据支付方式正确设置cashAmount和cardAmount
              const isCashPaymentTakeaway = paymentMethodTakeaway.toLowerCase() === 'cash' || paymentMethodTakeaway.toLowerCase() === 'cod';
              const isCardPaymentTakeaway = paymentMethodTakeaway.toLowerCase() === 'card' || paymentMethodTakeaway.toLowerCase() === 'bacs';
              const isMixedPaymentTakeaway = paymentMethodTakeaway.toLowerCase() === 'mixed';
              const isBizumPaymentTakeaway = paymentMethodTakeaway.toLowerCase() === 'bizum';

              // 🔥 关键修复：计算扣除抵扣券后的实际支付金额
              // chequeAmountTakeaway 已在上方定义，直接使用
              const actualPaymentAmountTakeaway = Math.max(0, totalAmount - chequeAmountTakeaway);

              // 🔥 计算日结单应记录的总额 = 实际收款金额（现金+刷卡+Bizum，不含抵扣券）
              let takeawayCashForDaily = 0;
              let takeawayCardForDaily = 0;
              let takeawayBizumForDaily = 0;

              if (isCashPaymentTakeaway) {
                  // 现金支付：实际现金 = 总额 - 抵扣券
                  takeawayCashForDaily = checkoutData.cashAmount || actualPaymentAmountTakeaway;
              } else if (isCardPaymentTakeaway) {
                  // 刷卡支付：实际刷卡 = 总额 - 抵扣券
                  takeawayCardForDaily = checkoutData.cardAmount || actualPaymentAmountTakeaway;
              } else if (isBizumPaymentTakeaway) {
                  // Bizum/转账支付：实际Bizum = 总额 - 抵扣券
                  takeawayBizumForDaily = checkoutData.bizumAmount || actualPaymentAmountTakeaway;
              } else if (isMixedPaymentTakeaway) {
                  // 混合支付：使用用户输入的金额
                  takeawayCashForDaily = checkoutData.cashAmount || 0;
                  takeawayCardForDaily = checkoutData.cardAmount || 0;
              }

              // 🔥 supplements 已在弹窗关闭时合入 customName/customPrice，直接使用
              const takeawayPaymentData = {
                  type: 'takeaway',
                  cart: cartItems,
                  paymentMethod: paymentMethodTakeaway,
                  // 🔥 修复：日结单总额应该是实际收款金额（不含抵扣券）
                  totalAmount: takeawayCashForDaily + takeawayCardForDaily + takeawayBizumForDaily,
                  receivedAmount: checkoutData.receivedAmount || 0,
                  changeAmount: checkoutData.changeAmount || 0,
                  // 🔥 修复：使用计算后的金额
                  cashAmount: takeawayCashForDaily,
                  cardAmount: takeawayCardForDaily,
                  bizumAmount: takeawayBizumForDaily,
                  discountPercent: savedDiscountPercentForPrint || 0,
                  discountAmount: discountAmount || 0,
                  customerId: checkoutData.customerInfo?.id || null,
                  customerPhone: checkoutData.customerInfo?.phone || null,
                  customerName: checkoutData.customerInfo?.name || null,
                  chequeRestauranteAmount: chequeAmountTakeaway,
                  // 🔥 保存订单原始总额（含抵扣券），用于订单记录
                  orderTotalAmount: totalAmount,
                  timestamp: Date.now()
              };

              PaymentQueue.addPayment(takeawayPaymentData).then(queueId => {
                  // 🔥 关键修复：如果 addPayment 返回 null（IndexedDB 不可用），
                  // 直接通过 AJAX 同步到服务器，不依赖队列
                  if (!queueId && navigator.onLine) {
                      console.warn('[秒结账] IndexedDB 不可用，直接同步外卖订单到服务器');
                      PaymentQueue.syncTakeawayPayment(takeawayPaymentData).then(result => {
                          if (result && result.success) {
                              console.log('[秒结账] ✅ 外卖订单直接同步成功');
                          } else {
                              console.error('[秒结账] ❌ 外卖订单直接同步失败');
                          }
                      }).catch(err => {
                          console.error('[秒结账] ❌ 外卖订单直接同步异常:', err);
                      });
                  }
              }).catch(err => {
                  // 🔥 队列失败时也尝试直接同步
                  if (navigator.onLine) {
                      console.warn('[秒结账] addPayment 失败，直接同步外卖订单到服务器');
                      PaymentQueue.syncTakeawayPayment(takeawayPaymentData).catch(err => console.error('[PaymentQueue] syncTakeawayPayment fallback failed:', err.message));
                  }
                  Toastify({
                      text: '⚠️ <?php echo ruiyi_translate("Sincronización pendiente", "Sync pending", "同步待处理"); ?>',
                      duration: 3000,
                      gravity: 'top',
                      position: 'center',
                      style: { background: '#f97316' }
                  }).showToast();
              });

              return; // 立即返回，不执行后续阻塞代码
          }

          // 🔥 备用模式：如果PaymentQueue不可用或离线，使用原始流程
          if (isOnline) {
              // 显示加载提示 (only for online)
              Swal.fire({
                  title: '<?php echo ruiyi_translate("Procesando pedido para llevar", "Processing takeaway order", "正在处理外卖订单"); ?>',
                  text: '<?php echo ruiyi_translate("Por favor espere...", "Please wait...", "请稍候..."); ?>',
                  allowOutsideClick: false,
                  didOpen: () => { Swal.showLoading(); }
              });
          }

          // Submit order (online or offline) - 备用模式
          submitOrderUniversal(orderParams)
          .then(data => {

              // 🔥 PWA: Close processing modal only if it was shown (online)
              if (isOnline) {
                  Swal.close();
              }

              // 🔥 PWA: Handle offline orders differently
              if (data.success && data.offline) {
                  // Offline order saved - behave like online mode
                  const paymentMethod = checkoutData.paymentMethod;
                  const orderTotal = totalAmount || calcularTotalConDescuento();

                  // 🔥 保存上一单信息（在清空购物车前）
                  // 计算原价（折扣前）和实付金额
                  const chequeAmountOffline = checkoutData.chequeRestauranteAmount || 0;
                  // 🔥 【关键修复】实付金额 = 折扣后金额 - 抵扣券
                  const actualPaidOffline = Math.max(0, orderTotal - chequeAmountOffline);
                  let originalTotalOffline = orderTotal;
                  if (savedDiscountPercentForPrint > 0) {
                    originalTotalOffline = parseFloat((orderTotal / (1 - savedDiscountPercentForPrint / 100)).toFixed(2));
                  }
                  saveAndShowLastOrderInfo({
                      totalAmount: actualPaidOffline, // 🔥 修复：传入实付金额（扣除抵扣券后）
                      originalTotal: originalTotalOffline, // 🔥 原价（折扣前）
                      discountAmount: discountAmount || 0, // 🔥 折扣金额
                      chequeAmount: chequeAmountOffline, // 🔥 抵扣券金额
                      paymentMethod: paymentMethod,
                      receivedAmount: checkoutData.receivedAmount || 0,
                      changeAmount: checkoutData.changeAmount || 0,
                      cashAmount: checkoutData.cashAmount || 0,
                      cardAmount: checkoutData.cardAmount || 0,
                      tableNumber: '',
                      orderType: 'takeaway'
                  });

                  // 🔥 立即清空购物车（与在线模式一致）
                  cart = [];
                  renderCart();

                  // 🔥🔥🔥 关键修复：清除收银购物车持久化存储，防止刷新后恢复
                  if (typeof clearPosCartStorage === 'function') {
                      clearPosCartStorage();
                  }

                  // 🔥 立即打开钱箱（现金/混合支付时，与在线模式一致）
                  const isCashPayment = paymentMethod === 'cash' || paymentMethod === 'mixed';
                  if (isCashPayment && typeof abrirCajonDinero === 'function') {
                      abrirCajonDinero().then(() => {
                      }).catch(error => {
                          console.error('[离线结账] 开钱箱失败:', error);
                      });
                  }

                  // Reset payment states
                  resetAllPaymentStates('takeaway_order_complete');

                  // 🔥 简单的 Toast 提示（不弹窗）
                  Toastify({
                      text: `✅ <?php echo ruiyi_translate('Completado', 'Completed', '已完成'); ?>`,
                      duration: 2000,
                      gravity: "top",
                      position: "center",
                      style: { background: "#10b981" }
                  }).showToast();

                  // Refresh offline orders list if function exists
                  if (typeof loadOfflinePendingOrdersIntoHistory === 'function') {
                      setTimeout(() => {
                          loadOfflinePendingOrdersIntoHistory();
                      }, 500);
                  }

                  return; // Exit early for offline orders
              }
              
              if (data.success) {
                  // Online order success - continue with normal flow
                  // 保存当前购物车数据用于小票打印（在购物车清空前保存）
                  const cartDataForPrint = JSON.parse(JSON.stringify(cartItems)); // 深拷贝避免引用问题

                  // 🔥 移除外卖订单创建成功弹窗，直接执行后续操作

                  // 🔥 保存最后订单ID到localStorage
                  if (data.data.order_id) {
                      localStorage.setItem('lastOrderId', data.data.order_id);

                      // 立即打印外卖小票（无延迟）
                      // 🔥 传递之前保存的折扣百分比（因为 window.currentDiscountPercent 已被重置）
                      printTakeawayReceiptWithData(data.data.order_id, checkoutData.customerInfo || {}, cartDataForPrint, checkoutData, savedDiscountPercentForPrint);

                      // 🔥 打开钱箱 - 外卖结账完成后
                      // 根据设置决定刷卡支付是否打开钱箱
                      const paymentMethod = checkoutData.paymentMethod;
                      const openDrawerOnCard = window.clodopConfig?.openDrawerOnCard || false;
                      const shouldOpenDrawer = paymentMethod === 'cash' || paymentMethod === 'mixed' || (paymentMethod === 'card' && openDrawerOnCard);

                      if (shouldOpenDrawer) {
                          if (typeof abrirCajonDinero === 'function') {
                              abrirCajonDinero().catch(error => {
                                  console.error('[外卖结账] 自动开钱箱失败:', error);
                              });
                          }
                      } else {
                      }
                  }

                  // 🔥 Display purchase success message on VFD
                  displayVFDSuccessMessage();

                  // 🔥 保存上一单信息（在清空购物车前）
                  // 计算原价（折扣前）和实付金额
                  const chequeAmountOnline = checkoutData.chequeRestauranteAmount || 0;
                  // 🔥 【关键修复】实付金额 = 折扣后金额 - 抵扣券
                  const actualPaidOnline = Math.max(0, totalAmount - chequeAmountOnline);
                  let originalTotalOnline = totalAmount;
                  if (savedDiscountPercentForPrint > 0) {
                    originalTotalOnline = parseFloat((totalAmount / (1 - savedDiscountPercentForPrint / 100)).toFixed(2));
                  }
                  saveAndShowLastOrderInfo({
                      totalAmount: actualPaidOnline, // 🔥 修复：传入实付金额（扣除抵扣券后）
                      originalTotal: originalTotalOnline, // 🔥 原价（折扣前）
                      discountAmount: discountAmount || 0, // 🔥 折扣金额
                      chequeAmount: chequeAmountOnline, // 🔥 抵扣券金额
                      paymentMethod: paymentMethod,
                      receivedAmount: checkoutData.receivedAmount || 0,
                      changeAmount: checkoutData.changeAmount || 0,
                      cashAmount: checkoutData.cashAmount || 0,
                      cardAmount: checkoutData.cardAmount || 0,
                      tableNumber: '',
                      orderType: 'takeaway'
                  });

                  // 清空购物车
                  cart = [];
                  renderCart();

                  // 🔥🔥🔥 关键修复：清除收银购物车持久化存储，防止刷新后恢复
                  if (typeof clearPosCartStorage === 'function') {
                      clearPosCartStorage();
                  }

                  // 🔥 隐藏查看模式相关按钮和工具箱
                  const viewModeButtons = ['checkout-table-btn', 'toolbox-toggle-btn'];
                  viewModeButtons.forEach(btnId => {
                      const btn = document.getElementById(btnId);
                      if (btn) {
                          btn.classList.add('hidden');
                      }
                  });

                  // 🔥 关闭工具箱展开区域（Alpine.js）
                  const cartActionsContainer = document.querySelector('.cart-actions-fixed');
                  if (cartActionsContainer && window.Alpine) {
                      const alpineData = Alpine.$data(cartActionsContainer);
                      if (alpineData) {
                          alpineData.toolboxOpen = false;
                      }
                  }

                  // 重置所有折扣和支付状态
                  resetAllPaymentStates('takeaway_order_complete');

                  // 显示简短的成功提示（Toast而非弹窗）
                  Toastify({
                      text: `✅ 已完成结账`,
                      duration: 2000,
                      gravity: "top",
                      position: "center",
                      style: { background: "#10b981" }
                  }).showToast();
              } else {
                  // 显示错误消息
                  Swal.fire({
                      icon: 'error',
                      title: '<?php echo ruiyi_translate('Error al crear el pedido', 'Order creation failed', '订单创建失败'); ?>',
                      text: data.data.message || '<?php echo ruiyi_translate('Error desconocido', 'Unknown error', '未知错误'); ?>'
                  });
              }
          })
          .catch(error => {
              console.error('[离线结账] Promise 错误:', error);
              Swal.close();
              Swal.fire({
                  icon: 'error',
                  title: '<?php echo ruiyi_translate('Error de red', 'Network error', '网络错误'); ?>',
                  text: '<?php echo ruiyi_translate('Por favor verifica la conexión de red', 'Please check network connection', '请检查网络连接'); ?>: ' + error.message
              });
          });
      }
      
      // 打印外卖小票函数
      function printTakeawayReceipt(orderId, customerInfo) {
          var ajaxUrl = window.ajaxUrl || '<?php echo admin_url('admin-ajax.php'); ?>';
          var ajaxNonce = window.RUIYI_POS?.nonce || posNonce;
          
          // 详细调试日志
          
          // 显示打印提示 - 已移除
          // Toastify({
          //     text: '<?php echo ruiyi_translate("Preparando recibo para llevar...", "Preparing takeaway receipt...", "正在准备外卖小票..."); ?>',
          //     duration: 2000,
          //     gravity: "top",
          //     position: "center",
          //     style: { background: "#2196f3" }
          // }).showToast();
          
          // 新方案：直接传递购物车数据，不依赖订单查询
          const printFormData = new URLSearchParams();
          printFormData.append('action', 'ruiyi_pos_get_table_receipt_html');
          printFormData.append('cart_data', JSON.stringify(window.cart || [])); // 直接传递购物车数据
          printFormData.append('cart_items', JSON.stringify(window.cart || [])); // Also pass as cart_items for tax calculation
          // 🔥 使用customPrice字段（如果存在），否则使用原价
          // 🔥 修复：使用 toFixed(2) 避免浮点数精度问题
          printFormData.append('order_total', parseFloat((window.cart || []).reduce((sum, item) => {
            const itemPrice = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
            return sum + (itemPrice * item.quantity);
          }, 0).toFixed(2))); // 计算总金额
          printFormData.append('order_type', 'llevar'); // 外卖订单
          printFormData.append('customer_info', JSON.stringify(customerInfo)); // 客户信息
          printFormData.append('order_id_for_reference', orderId); // 仅作参考，不用于查询
          printFormData.append('order_ids_to_print', JSON.stringify([orderId])); // 添加订单ID数组用于获取QR码
          printFormData.append('nonce', ajaxNonce);
          
          // 发送打印请求
          fetch(ajaxUrl, {
              method: 'POST',
              headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
              body: printFormData
          })
          .then(response => {
              if (!response.ok) {
                  throw new Error(`打印请求失败: ${response.status}`);
              }
              return response.json();
          })
          .then(data => {
              if (data.success && data.data && data.data.html) {
                  try {
                      // 使用 RUIYI 统一打印函数 - 触发点：外卖订单
                      const printSuccess = ruiyiUnifiedPrint(data.data.html, 'takeaway');
                      if (!printSuccess) {
                          throw new Error('CLODOP takeaway receipt print failed');
                      }

                      // 显示成功提示
                      Toastify({
                          text: '✅ <?php echo ruiyi_translate("Recibo para llevar impreso exitosamente", "Takeaway receipt printed", "外卖小票打印成功"); ?>',
                          duration: 3000,
                          gravity: "top",
                          position: "center",
                          style: { background: "#10b981" }
                      }).showToast();

                  } catch (error) {
                      console.error('[外卖打印] 外卖打印错误:', error);

                      // 显示错误提示
                      Toastify({
                          text: '❌ <?php echo ruiyi_translate("Error de impresión", "Print failed", "打印失败"); ?>: ' + error.message,
                          duration: 3000,
                          gravity: "top",
                          position: "center",
                          style: { background: "#ef4444" }
                      }).showToast();
                  }
              } else {
                  // API返回错误
                  Toastify({
                      text: '❌ <?php echo ruiyi_translate("Error al obtener datos del recibo", "Failed to get receipt data", "获取小票数据失败"); ?>',
                      duration: 3000,
                      gravity: "top",
                      position: "center",
                      style: { background: "#ef4444" }
                  }).showToast();
              }
          })
          .catch(error => {
              console.error('打印请求错误:', error);
              
              // 显示网络错误
              Toastify({
                  text: '🚫 <?php echo ruiyi_translate("Error de conexión de impresión", "Print connection error", "打印连接错误"); ?>',
                  duration: 3000,
                  gravity: "top",
                  position: "center",
                  style: { background: "#f59e0b" }
              }).showToast();
          });
      }
      
      // 点餐类型按钮
      // 🔒 订单类型标签：禁用用户点击，仅用于显示当前模式
      const orderTypeButtons = document.querySelectorAll('.order-type');
      orderTypeButtons.forEach(button => {
        // 添加视觉提示：禁用指针事件
        button.style.pointerEvents = 'none';
        button.style.cursor = 'default';

        /* 已禁用：订单类型标签点击事件
         * 标签现在仅用于显示当前订单类型，不允许用户手动切换
         * 系统会根据以下规则自动设置：
         * - 点击收银图标：强制外卖模式
         * - 选择餐桌后：自动堂食模式
         *
        button.addEventListener('click', function() {
          orderTypeButtons.forEach(btn => {
            btn.classList.remove('bg-[#f7310f]', 'text-white');
            btn.classList.add('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
          });
          this.classList.add('bg-[#f7310f]', 'text-white');
          this.classList.remove('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
          const newTipoPedido = this.getAttribute('data-type');
          sessionStorage.setItem('tipoPedidoSeleccionado', newTipoPedido);
          updateOrderButtonForType(newTipoPedido);
        });
        */
      });
      
      // 清台按钮事件监听器
      const clearTableBtn = document.getElementById('clear-table-btn');
      if (clearTableBtn) {
        clearTableBtn.addEventListener('click', function() {
          // Check if button is disabled (for shop managers)
          if (this.disabled) {
            Swal.fire({
              icon: 'error',
              title: '<?php echo ruiyi_translate("Sin permisos", "No permission", "权限不足"); ?>',
              text: '<?php echo ruiyi_translate("No tienes permisos para limpiar mesas", "You do not have permission to clear tables", "您无权限清理桌位"); ?>',
              confirmButtonColor: '#f7310f'
            });
            return;
          }

          const tableNumber = typeof ruiyiResolveActiveTableNumber === 'function'
            ? ruiyiResolveActiveTableNumber(this.dataset.tableNumber)
            : this.dataset.tableNumber;
          if (tableNumber) {
            this.dataset.tableNumber = tableNumber;
            liberarMesa(tableNumber);
          }
        });
      }
      
      // 退出查看模式按钮事件监听器
      const exitViewModeBtn = document.getElementById('exit-view-mode-btn');
      if (exitViewModeBtn) {
        exitViewModeBtn.addEventListener('click', function() {
          if (typeof exitViewMode === 'function') {
            exitViewMode();
          } else {
            console.error('exitViewMode函数未定义');
          }
        });
      }
      
      // 换台按钮事件监听器
      const switchTableBtn = document.getElementById('switch-table-btn');
      if (switchTableBtn) {
        switchTableBtn.addEventListener('click', function() {
          // 🔥 修复：多种方式获取当前桌位号
          let fromTable = typeof ruiyiResolveActiveTableNumber === 'function'
            ? ruiyiResolveActiveTableNumber(this.dataset.tableNumber)
            : this.dataset.tableNumber;

          // 备用方案1：从 sessionStorage 的 tableViewMode 获取
          if (!fromTable) {
            const viewModeData = sessionStorage.getItem('tableViewMode');
            if (viewModeData) {
              try {
                const viewMode = JSON.parse(viewModeData);
                fromTable = viewMode.table;
              } catch (e) { /* viewModeData may be invalid JSON - fallback below handles it */ }
            }
          }

          // 备用方案2：从桌位输入框获取
          if (!fromTable) {
            const tableInput = document.getElementById('table-number');
            if (tableInput) fromTable = tableInput.value.trim();
          }

          // 备用方案3：从当前桌位名称显示获取
          if (!fromTable) {
            const tableNameEl = document.getElementById('current-table-name');
            if (tableNameEl) fromTable = tableNameEl.textContent.trim();
          }

          // // console.log('[换台] 获取到的源桌位号:', fromTable);

          if (fromTable && typeof showTableSwitchModal === 'function') {
            this.dataset.tableNumber = fromTable;
            showTableSwitchModal(fromTable);
          } else {
            console.error('[换台] 无法获取当前桌位号');
            if (typeof Toastify !== 'undefined') {
              Toastify({
                text: '<?php echo ruiyi_translate("No se pudo obtener el número de mesa", "Could not get table number", "无法获取当前桌位号"); ?>',
                duration: 3000,
                gravity: 'top',
                position: 'center',
                style: { background: '#f97316' }
              }).showToast();
            }
          }
        });
      }
      
      // Initial cart rendering
      renderCart();

      // 移除自动桌位号监听器以避免与桌位选择冲突
      // 桌位选择和订单类型改变时会通过其他机制正确更新按钮状态
      const tableNumberInput = document.getElementById('table-number');
      if (tableNumberInput) {
        // 🔒 餐桌输入框现在是只读的，不再需要input事件监听
        // 桌号只能通过点击餐桌网格设置
        /* 已禁用：手动输入监听器
        let inputTimer = null;
        tableNumberInput.addEventListener('input', function() {
          if (inputTimer) clearTimeout(inputTimer);
          inputTimer = setTimeout(() => {
            const tipoPedido = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir';
            updateOrderButtonForType(tipoPedido);
          }, 500);
        });
        */
      }

      // 初始化时检查并设置按钮状态
      setTimeout(() => {
        if (typeof updateAllButtonStates === 'function') {
          updateAllButtonStates();
        }

        // 启动按钮状态监控
        if (typeof startButtonMonitoring === 'function') {
          startButtonMonitoring();
        }

        // 立即执行一次强制按钮检查
        setTimeout(() => {
          if (typeof forceCorrectButtonDisplay === 'function') {
            forceCorrectButtonDisplay();
          }
        }, 500);
      }, 100);
      
      // 加载购物车中的移除项目事件
      document.addEventListener('click', function(e) {
        if (e.target.classList.contains('remove-item')) {
          const index = parseInt(e.target.getAttribute('data-index'));
          if (!isNaN(index) && index >= 0 && index < cart.length) {
            cart.splice(index, 1);
            renderCart();
            
            Toastify({
              text: `🗑️ ${window.RUIYI_TRANS.productRemoved}`,
              duration: 2000,
              gravity: "top",
              position: "center",
              style: { background: "#f44336" }
            }).showToast();
          }
        }
      });
      
      // 结账按钮事件监听器
      const checkoutTableBtn = document.getElementById('checkout-table-btn');
      if (checkoutTableBtn) {
        checkoutTableBtn.addEventListener('click', async function() {
          // 🔥 获取桌位号：优先从data-table-number属性，其次从输入框
          let tableNumber = typeof ruiyiResolveActiveTableNumber === 'function'
            ? ruiyiResolveActiveTableNumber(this.dataset.tableNumber)
            : this.dataset.tableNumber;
          if (!tableNumber) {
            const tableInput = document.getElementById('table-number');
            tableNumber = tableInput?.value.trim();
          }

          // 🔥 先检查是否是外卖订单或没有桌位号（两种情况都应该使用外卖结账流程）
          const currentOrderType = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir';
          if (currentOrderType === 'llevar' || !tableNumber) {
            // 外卖模式或没有桌位号：直接启动外卖结账流程
            startTakeawayCheckout();
            return;
          }
          this.dataset.tableNumber = tableNumber;

          // 🔥🔥🔥 关键修复：结账前先保存所有变更（新商品 + 锁定商品数量修改）
          const hasUnlockedItems = cart && cart.some(item => !item.locked && item.quantity > 0);
          const hasLockedItems = cart && cart.some(item => item.locked && item.quantity > 0);

          if (hasUnlockedItems || hasLockedItems) {
            // 显示保存中提示
            Swal.fire({
              title: '<?php echo ruiyi_translate("Guardando cambios...", "Saving changes...", "保存变更中..."); ?>',
              allowOutsideClick: false,
              didOpen: () => { Swal.showLoading(); }
            });

            try {
              const saveSuccess = await ensureTableOrderSaved();
              Swal.close();

              if (!saveSuccess) {
                Swal.fire({
                  icon: 'error',
                  title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
                  text: '<?php echo ruiyi_translate("Error al guardar cambios", "Failed to save changes", "保存变更失败"); ?>'
                });
                return;
              }
            } catch (error) {
              Swal.close();
              console.error('[结账] 保存变更失败:', error);
              Swal.fire({
                icon: 'error',
                title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
                text: '<?php echo ruiyi_translate("Error al guardar cambios", "Failed to save changes", "保存变更失败"); ?>'
              });
              return;
            }
          }

          // 堂食模式且有桌位号：继续桌位结账流程

          // 🔥🔥🔥 【2026-03-30 关键修复】保存后购物车可能为空（quickSaveTableOrder移除了未锁定商品）
          // 如果 syncTableOrderToServer 失败或跳过了购物车更新，需要从 mesas_estado 恢复
          // 🔥🔥🔥【2026-04-08 关键修复】原逻辑用 tableNumber.replace("餐桌|Mesa|Table")
          //   对自定义桌位名（如 "SALON 2"、"COMEDOR 1"）不生效，构造的 mesaKey 对不上
          //   mesas_estado 里实际存的 "Mesa 13" 等数字 key → 恢复失败 → cart 为空 → 弹"没有商品"
          //   修复：先用 resolveGlobalTableNumber 规范化，失败则扫描 mesas_estado 所有 key 找匹配
          if (!cart || cart.length === 0 || !cart.some(item => item.quantity > 0)) {
            const _recoverMesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
            let _recoverTableData = null;
            let _recoverMesaKey = null;

            // 1. 优先用 resolveGlobalTableNumber 规范化
            const _resolvedNum = (typeof resolveGlobalTableNumber === 'function')
              ? resolveGlobalTableNumber(tableNumber)
              : null;
            if (_resolvedNum && /^\d+$/.test(String(_resolvedNum))) {
              _recoverMesaKey = `Mesa ${_resolvedNum}`;
              _recoverTableData = _recoverMesasEstado[_recoverMesaKey];
            }

            // 2. 回退：简单前缀剥离
            if (!_recoverTableData) {
              const _recoverTableNum = tableNumber.replace(/^(餐桌|Mesa|Table)\s*/, '');
              _recoverMesaKey = `Mesa ${_recoverTableNum}`;
              _recoverTableData = _recoverMesasEstado[_recoverMesaKey];
            }

            // 3. 兜底：扫描所有 mesas_estado 条目，找 table_number 匹配的那个
            if (!_recoverTableData) {
              for (const [k, v] of Object.entries(_recoverMesasEstado)) {
                if (v && v.table_number === tableNumber) {
                  _recoverMesaKey = k;
                  _recoverTableData = v;
                  break;
                }
              }
            }

            // 4. 最后兜底：找最近更新、带 _pendingSync 或 _newItemsToSync 的条目
            if (!_recoverTableData) {
              let latest = null, latestKey = null, latestTs = 0;
              for (const [k, v] of Object.entries(_recoverMesasEstado)) {
                if (v && (v._pendingSync || (v._newItemsToSync && v._newItemsToSync.length > 0))) {
                  const ts = v.timestamp ? new Date(v.timestamp).getTime() : 0;
                  if (ts > latestTs) {
                    latestTs = ts;
                    latest = v;
                    latestKey = k;
                  }
                }
              }
              if (latest && Date.now() - latestTs < 10000) {  // 10 秒内刚写的
                _recoverMesaKey = latestKey;
                _recoverTableData = latest;
                console.log('[结账] 🔄 通过最近更新兜底定位:', latestKey);
              }
            }

            if (_recoverTableData?.cart && _recoverTableData.cart.length > 0) {
              console.log('[结账] 🔄 购物车为空，从 mesas_estado[' + _recoverMesaKey + '] 恢复:', _recoverTableData.cart.length, '项');
              cart = _recoverTableData.cart.filter(item => item.quantity > 0).map(item => ({
                ...item,
                locked: true,
                orderId: item.orderId || _recoverTableData.orderId
              }));
              if (typeof renderCart === 'function') renderCart();
            } else {
              console.warn('[结账] ⚠️ mesas_estado 恢复失败，tableNumber:', tableNumber, '可用 keys:', Object.keys(_recoverMesasEstado));
            }
          }

          // 获取桌位订单数据（查看模式下会有，普通模式下可能没有）
          const orderData = sessionStorage.getItem('tableOrderData');

          // 如果没有已有订单数据，说明是新建订单，直接处理购物车商品
          if (!orderData) {
            // 普通模式：新建订单并结账
            const newItems = cart.filter(item => !item.locked && item.quantity > 0);
            const lockedItems = cart.filter(item => item.locked && item.quantity > 0);

            // 🔥 关键修复：如果有锁定商品但没有新商品，说明订单已创建，直接进入支付
            if (newItems.length === 0 && lockedItems.length > 0) {
              // 计算总金额（包含锁定商品）
              // 🔥 修复：使用 toFixed(2) 避免浮点数精度问题
              const totalAmountLocked = parseFloat(lockedItems.reduce((sum, item) => {
                const itemPrice = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
                return sum + (itemPrice * item.quantity);
              }, 0).toFixed(2));
              // 获取订单ID列表（从锁定商品）
              let orderIdsFromLocked = [...new Set(lockedItems.map(item => item.orderId).filter(id => id))];

              // 🔥 回退机制：如果锁定商品没有orderId，尝试从localStorage获取
              if (orderIdsFromLocked.length === 0) {
                // // console.log('[结账] 锁定商品没有orderId，尝试从localStorage获取');
                const tableNumberClean = tableNumber.replace(/^(餐桌|Mesa|Table)\s*/, '');
                const mesaKey = `Mesa ${tableNumberClean}`;
                const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                const tableData = mesasEstado[mesaKey];
                if (tableData?.orderId) {
                  orderIdsFromLocked = [tableData.orderId];
                  // // console.log('[结账] 从localStorage获取到orderId:', tableData.orderId);
                } else if (tableData?.orderIds && tableData.orderIds.length > 0) {
                  orderIdsFromLocked = tableData.orderIds;
                  // // console.log('[结账] 从localStorage获取到orderIds:', tableData.orderIds);
                }
              }

              if (orderIdsFromLocked.length > 0) {
                const cartSnapshotLocked = JSON.parse(JSON.stringify(lockedItems));
                procesarPagoCompletoDeMesa(tableNumber, totalAmountLocked, orderIdsFromLocked, cartSnapshotLocked);
              } else {
                console.error('[结账] 锁定商品没有订单ID，localStorage也没有');
                Swal.fire({
                  icon: 'error',
                  title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
                  text: '<?php echo ruiyi_translate("No se encontró el ID del pedido", "Order ID not found", "未找到订单ID"); ?>'
                });
              }
              return;
            }

            if (newItems.length === 0) {
              Swal.fire({
                icon: 'info',
                title: '<?php echo ruiyi_translate("Sin productos", "No products", "没有商品"); ?>',
                text: '<?php echo ruiyi_translate("Agrega productos al carrito antes de pagar", "Add products to cart before checkout", "请先添加商品"); ?>'
              });
              return;
            }

            // 🔥 关键修复：在调用crearPedidoMesa之前计算总金额
            // 因为crearPedidoMesa->submitOrderUniversal会清空购物车
            // 🔥 修复：使用 toFixed(2) 避免浮点数精度问题
            const totalAmountBeforeSave = parseFloat(newItems.reduce((sum, item) => {
              const itemPrice = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
              return sum + (itemPrice * item.quantity);
            }, 0).toFixed(2));
            // 保存购物车副本用于离线结账
            const cartSnapshotForCheckout = JSON.parse(JSON.stringify(newItems));

            // 先创建订单
            Swal.fire({
              title: '<?php echo ruiyi_translate("Guardando pedido...", "Saving order...", "正在保存订单..."); ?>',
              text: '<?php echo ruiyi_translate("Por favor espere", "Please wait", "请稍候"); ?>',
              allowOutsideClick: false,
              didOpen: () => { Swal.showLoading(); }
            });

            crearPedidoMesa(tableNumber, newItems)
              .then(newOrderId => {
                Swal.close();

                if (newOrderId) {
                  // 🔥 使用预计算的总金额，而不是从已清空的购物车计算

                  // 调用结账处理函数，传入购物车快照用于离线结账
                  procesarPagoCompletoDeMesa(tableNumber, totalAmountBeforeSave, [newOrderId], cartSnapshotForCheckout);
                } else {
                  Swal.fire({
                    icon: 'error',
                    title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
                    text: '<?php echo ruiyi_translate("No se pudo guardar el pedido", "Could not save order", "无法保存订单"); ?>'
                  });
                }
              })
              .catch(error => {
                Swal.close();
                console.error('[结账错误]', error);
                Swal.fire({
                  icon: 'error',
                  title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
                  text: error.message || '<?php echo ruiyi_translate("Error al guardar pedido", "Error saving order", "保存订单时出错"); ?>'
                });
              });

            return;
          }

          const data = JSON.parse(orderData);
          let orderIds = data.orders.map(order => order.id || order.order_number);

          // 🔥【2026-04-07 修复】如果之前有未锁定商品（已被 ensureTableOrderSaved 自动锁定）
          // sessionStorage.tableOrderData 里的 orderIds 可能是过期的，缺少新创建订单的 ID
          // 必须从当前 cart 的 locked items 重建并合并，确保结账覆盖所有订单
          if (hasUnlockedItems) {
            const _freshOrderIds = [...new Set(
              cart.filter(i => i.locked && i.orderId).map(i => i.orderId)
            )];
            // 也叠加 localStorage 里的 orderId（兜底）
            try {
              const _tnClean = tableNumber.replace(/^(餐桌|Mesa|Table)\s*/, '');
              const _mk = `Mesa ${_tnClean}`;
              const _ms = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
              const _td = _ms[_mk];
              if (_td?.orderId && !_freshOrderIds.includes(_td.orderId)) _freshOrderIds.push(_td.orderId);
              if (Array.isArray(_td?.orderIds)) {
                _td.orderIds.forEach(oid => { if (oid && !_freshOrderIds.includes(oid)) _freshOrderIds.push(oid); });
              }
            } catch (e) {}
            // 合并新旧 orderIds 并去重（保险起见）
            const _merged = [...new Set([...orderIds, ..._freshOrderIds])];
            console.log('[结账] 🔄 自动锁定后刷新 orderIds:', orderIds, '+', _freshOrderIds, '=', _merged);
            orderIds = _merged;
          }

          // 🔥 新增：检查购物车中是否有未保存的产品（未锁定的产品）
          const unlockedProducts = cart.filter(item => !item.locked);

          if (unlockedProducts.length > 0) {
            // 有未保存的产品，需要先创建新订单保存它们

            // 🔥 关键修复：在调用crearPedidoMesa之前计算总金额并保存购物车快照
            // 因为crearPedidoMesa->submitOrderUniversal会清空购物车
            // 🔥 修复：含 supplements 价格计算
            const totalAmountBeforeSaveWithExisting = parseFloat(cart.reduce((sum, item) => {
              return sum + ((parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0))) * item.quantity);
            }, 0).toFixed(2));
            const cartSnapshotWithExisting = JSON.parse(JSON.stringify(cart.filter(item => item.quantity > 0)));

            Swal.fire({
              title: '<?php echo ruiyi_translate("Guardando productos nuevos...", "Saving new products...", "正在保存新产品..."); ?>',
              text: '<?php echo ruiyi_translate("Por favor espere", "Please wait", "请稍候"); ?>',
              allowOutsideClick: false,
              didOpen: () => { Swal.showLoading(); }
            });

            // 调用创建订单的函数保存未锁定的产品
            crearPedidoMesa(tableNumber, unlockedProducts)
              .then(newOrderId => {
                Swal.close();

                if (newOrderId) {
                  // 将新订单ID添加到订单列表中
                  orderIds.push(newOrderId);

                  // 🔥 使用预计算的总金额，而不是从已清空的购物车计算

                  // 现在调用结账处理函数，包含新旧订单，传入购物车快照
                  procesarPagoCompletoDeMesa(tableNumber, totalAmountBeforeSaveWithExisting, orderIds, cartSnapshotWithExisting);
                } else {

                  Swal.fire({
                    icon: 'error',
                    title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
                    text: '<?php echo ruiyi_translate("No se pudo guardar los productos nuevos", "Could not save new products", "无法保存新产品"); ?>'
                  });
                }
              })
              .catch(error => {
                Swal.close();

                console.error('[结账错误]', error);
                Swal.fire({
                  icon: 'error',
                  title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
                  text: error.message || '<?php echo ruiyi_translate("Error al guardar productos", "Error saving products", "保存产品时出错"); ?>'
                });
              });
          } else {
            // 没有未保存的产品，直接结账

            // 使用当前购物车的价格计算总金额，而不是使用旧的订单数据
            // 🔥 使用customPrice字段（如果存在），否则使用原价
            // 🔥 含 supplements 价格计算
            const totalAmount = parseFloat(cart.reduce((sum, item) => {
              return sum + ((parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0))) * item.quantity);
            }, 0).toFixed(2));

            // 🔥 保存购物车快照用于离线结账
            const cartSnapshotLocked = JSON.parse(JSON.stringify(cart.filter(item => item.quantity > 0)));

            // 调用结账处理函数，传入购物车快照
            procesarPagoCompletoDeMesa(tableNumber, totalAmount, orderIds, cartSnapshotLocked);
          }
        });
      }
      
      // 分单结账按钮事件监听器
      const splitCheckoutBtn = document.getElementById('split-checkout-btn');
      if (splitCheckoutBtn) {
        splitCheckoutBtn.addEventListener('click', async function() {
          let tableNumber = typeof ruiyiResolveActiveTableNumber === 'function'
            ? ruiyiResolveActiveTableNumber(this.dataset.tableNumber)
            : this.dataset.tableNumber;

          // 🔥 如果按钮的dataset没有桌号，尝试从input获取
          if (!tableNumber) {
            tableNumber = document.getElementById('table-number')?.value.trim();
          }

          // 🔥 如果还是没有，尝试从sessionStorage获取
          if (!tableNumber) {
            const viewModeData = sessionStorage.getItem('tableViewMode');
            if (viewModeData) {
              try {
                const viewMode = JSON.parse(viewModeData);
                tableNumber = viewMode.table;
              } catch (e) {
                console.error('[AA结账] 解析sessionStorage失败:', e);
              }
            }
          }

          if (!tableNumber) {
            Swal.fire({
              icon: 'error',
              title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
              text: '<?php echo ruiyi_translate("No se pudo identificar la mesa", "Could not identify the table", "无法识别桌位"); ?>'
            });
            return;
          }
          this.dataset.tableNumber = tableNumber;

          // 🔥🔥🔥 关键修复：AA结账前先保存所有变更（新商品 + 锁定商品数量修改）
          // 确保服务器数据与前端购物车一致，AA分单才能显示正确金额
          const hasUnlockedItems = cart && cart.some(item => !item.locked && item.quantity > 0);
          const hasLockedItems = cart && cart.some(item => item.locked && item.quantity > 0);

          if (hasUnlockedItems || hasLockedItems) {
            // 显示保存中提示
            Swal.fire({
              title: '<?php echo ruiyi_translate("Guardando cambios...", "Saving changes...", "保存变更中..."); ?>',
              allowOutsideClick: false,
              didOpen: () => { Swal.showLoading(); }
            });

            try {
              const saveSuccess = await ensureTableOrderSaved();
              Swal.close();

              if (!saveSuccess) {
                Swal.fire({
                  icon: 'error',
                  title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
                  text: '<?php echo ruiyi_translate("Error al guardar cambios", "Failed to save changes", "保存变更失败"); ?>'
                });
                return;
              }

              // 🔥 等待服务器完全处理订单
              await new Promise(resolve => setTimeout(resolve, 300));

            } catch (error) {
              Swal.close();
              console.error('[AA结账] 保存变更失败:', error);
              Swal.fire({
                icon: 'error',
                title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
                text: '<?php echo ruiyi_translate("Error al guardar cambios", "Failed to save changes", "保存变更失败"); ?>'
              });
              return;
            }
          }

          initiateSplitBilling(tableNumber);
        });
      }
      
      // 从会话存储中恢复订单类型
      const tipoPedido = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir';
      orderTypeButtons.forEach(button => {
        if (button.getAttribute('data-type') === tipoPedido) {
          button.classList.add('bg-[#f7310f]', 'text-white');
          button.classList.remove('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
        }
      });
      
      // 如果当前订单类型是外卖，处理餐桌号输入框
      if (tipoPedido === 'llevar') {
        const tableNumberInput = document.getElementById('table-number');
        if (tableNumberInput) {
          tableNumberInput.value = ''; // 确保是空的
          // 🔥 隐藏购物车上方的桌位号显示
          updateCurrentTableDisplay('');
          tableNumberInput.placeholder = '<?php echo ruiyi_translate("Pedido para llevar", "Takeaway order", "外卖订单"); ?>';
        }
      }
      
      // 初始化按钮显示
      updateOrderButtonForType(tipoPedido);
      
      // 更新订单按钮的显示和功能
      function updateOrderButtonForType(orderType) {
          // 检查是否在查看模式
          const viewMode = sessionStorage.getItem('tableViewMode');
          const isViewMode = viewMode ? JSON.parse(viewMode) : null;

          // 查看模式下，第一个按钮永远是发送订单，不允许改变
          if (isViewMode && isViewMode.mode === 'view') {
              return;
          }

          const orderBtnIcon = document.getElementById('order-btn-icon');
          const orderBtnText = document.getElementById('order-btn-text');
          const sendOrderBtn = document.getElementById('send-order-btn');
          const openDrawerBtn = document.getElementById('open-drawer-btn');
          const tableNumberInput = document.getElementById('table-number');

          if (!orderBtnIcon || !orderBtnText || !sendOrderBtn) {
              // console.warn('[按钮更新] 缺少关键按钮元素');
              return;
          }

          // 检查桌位号是否为空
          const tableNumber = tableNumberInput?.value.trim() || '';
          const hasTableNumber = tableNumber !== '';

          if (orderType === 'llevar' || (!hasTableNumber && orderType !== 'servir')) {
              // 外卖模式或没有桌位号：显示结账按钮
              orderBtnIcon.className = 'fas fa-credit-card mr-2';
              orderBtnText.textContent = '<?php echo ruiyi_translate('Pagar', 'Checkout', '结账'); ?>';
              sendOrderBtn.className = 'w-full bg-green-600 hover:bg-green-700 text-white font-bold px-4 py-3 rounded-lg flex items-center justify-center';
              sendOrderBtn.setAttribute('data-action', 'checkout');
              // 显示开钱箱按钮
              if (openDrawerBtn) {
                  openDrawerBtn.classList.remove('hidden');
              }
          } else if (orderType === 'servir' && hasTableNumber) {
              // 堂食模式且有桌位号：隐藏保存桌位订单按钮
              sendOrderBtn.classList.add('hidden');
              sendOrderBtn.style.display = 'none';
              // 显示开钱箱按钮
              if (openDrawerBtn) {
                  openDrawerBtn.classList.remove('hidden');
              }
          } else {
              // 默认情况：堂食模式，隐藏保存桌位订单按钮
              sendOrderBtn.classList.add('hidden');
              sendOrderBtn.style.display = 'none';
              // 显示开钱箱按钮
              if (openDrawerBtn) {
                  openDrawerBtn.classList.remove('hidden');
              }
          }
      }

      // 新增：强制按钮状态检查和修复函数
      function forceCorrectButtonDisplay() {
        const tableNumberInput = document.getElementById('table-number');
        const orderBtnIcon = document.getElementById('order-btn-icon');
        const orderBtnText = document.getElementById('order-btn-text');
        const sendOrderBtn = document.getElementById('send-order-btn');

        if (!tableNumberInput || !orderBtnIcon || !orderBtnText || !sendOrderBtn) {
          // console.warn('[强制按钮修复] 缺少关键元素');
          return false;
        }

        const tableNumber = tableNumberInput.value.trim();
        const currentOrderType = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir';
        const hasTableNumber = tableNumber !== '';

        // 强制按优先级设置：如果是堂食且有桌位号，隐藏保存桌位订单按钮
        if (currentOrderType === 'servir' && hasTableNumber) {
          // 有桌位且堂食：隐藏保存桌位订单按钮
          sendOrderBtn.classList.add('hidden');
          sendOrderBtn.style.display = 'none';
          return true;
        } else if (currentOrderType === 'llevar' || !hasTableNumber) {
          // 外卖模式或无桌位：设置结账按钮
          orderBtnIcon.className = 'fas fa-credit-card mr-2';
          orderBtnText.textContent = '<?php echo ruiyi_translate('Pagar', 'Checkout', '结账'); ?>';
          sendOrderBtn.className = 'w-full bg-green-600 hover:bg-green-700 text-white font-bold px-4 py-3 rounded-lg flex items-center justify-center';
          sendOrderBtn.setAttribute('data-action', 'checkout');
          return true;
        }

        return false;
      }

      // 全局按钮状态监控：定期检查按钮状态是否正确
      let buttonMonitorInterval = null;

      // 🔥 按钮状态监控：改为事件驱动（原 setInterval 3秒轮询）
      function checkButtonState() {
        const cajeroSection = document.getElementById('cajero');
        if (cajeroSection && !cajeroSection.classList.contains('hidden')) {
          const tableInput = document.getElementById('table-number');
          const orderBtnText = document.getElementById('order-btn-text');
          if (tableInput && orderBtnText) {
            const hasTable = tableInput.value.trim() !== '';
            const currentType = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir';
            const buttonText = orderBtnText.textContent;
            const shouldShowSave = currentType === 'servir' && hasTable;
            const isShowingSave = buttonText.includes('保存') || buttonText.includes('Save') || buttonText.includes('Guardar');
            const isShowingCheckout = buttonText.includes('结账') || buttonText.includes('Checkout') || buttonText.includes('Pagar');
            if ((shouldShowSave && !isShowingSave) || (!shouldShowSave && !isShowingCheckout)) {
              console.warn('[按钮监控] 检测到按钮状态不正确，执行修复');
              forceCorrectButtonDisplay();
            }
          }
        }
      }

      function startButtonMonitoring() {
        // 事件驱动：监听桌号变化和订单类型变化
        var tableInput = document.getElementById('table-number');
        if (tableInput) {
          tableInput.addEventListener('change', checkButtonState);
          tableInput.addEventListener('input', checkButtonState);
        }
        window.addEventListener('storage', function(e) {
          if (e.key === 'tipoPedidoSeleccionado') checkButtonState();
        });
        // 初始检查一次
        setTimeout(checkButtonState, 500);
      }

      function stopButtonMonitoring() {
        // No-op: event listeners are passive and lightweight
      }

      // 恢复暂存的购物车
      const pedidoGuardado = localStorage.getItem('pedido_temporal');
      if (pedidoGuardado) {
        try {
          const { mesa, carrito } = JSON.parse(pedidoGuardado);
          cart = carrito;
          
          const tableElem = document.getElementById('table-number');
          if (tableElem) tableElem.value = mesa;
          
          
          renderCart();
          
          Toastify({
            text: `📦 Se cargó un carrito guardado`,
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#4caf50" },
          }).showToast();
        } catch (error) {
          console.error('Error al restaurar carrito:', error);
        }
      }

      // ========================================
      // Varios 快捷输入功能初始化
      // ========================================
      initVariosQuickInput();

      // ========================================
      // 🔥 折扣功能初始化
      // ========================================
      initDiscountInput();

      // ========================================
      // 🔥 INTRO 键快捷结账功能（智能判断外卖/桌位模式）
      // ========================================

      // 防抖时间戳
      let lastGlobalEnterTime = 0;

      document.addEventListener('keydown', function(e) {
          // 只监听 Enter 键（不带修饰键）
          if (e.key !== 'Enter' || e.shiftKey || e.ctrlKey || e.altKey) {
              return;
          }

          // 检查是否在收银页面
          const cajeroSection = document.getElementById('cajero');
          if (!cajeroSection || cajeroSection.classList.contains('hidden')) {
              return;
          }

          // 🔥 增强弹窗检测 - 检查所有可能的 SweetAlert 容器
          // 🔥🔥🔥 修复：[role="dialog"] 必须排除隐藏元素（如 Wordfence 的 wordfenceBox display:none）
          const hasSwalDialog = document.querySelector('.swal2-container') ||
                              document.querySelector('.swal2-popup');
          const hasVisibleRoleDialog = (function() {
              var dialogs = document.querySelectorAll('[role="dialog"]');
              for (var i = 0; i < dialogs.length; i++) {
                  if (dialogs[i].offsetParent !== null || getComputedStyle(dialogs[i]).display !== 'none') {
                      return true;
                  }
              }
              return false;
          })();

          if (hasSwalDialog || hasVisibleRoleDialog) {
              return; // 弹窗已打开且可见，全局监听器不处理
          }

          // 🔥 增强防抖：500ms内只处理一次
          const now = Date.now();
          if (now - lastGlobalEnterTime < 500) {
              e.preventDefault();
              e.stopImmediatePropagation();
              return;
          }
          lastGlobalEnterTime = now;

          // 🔥 移除焦点检查 - 允许在任何地方按 INTRO 都触发结账
          // 特殊例外：如果焦点在客户搜索、客户信息等特定输入框中，保持原有行为
          const activeElement = document.activeElement;
          const isInSpecialInput = activeElement && (
              // 只排除多行文本框（TEXTAREA）
              activeElement.tagName === 'TEXTAREA' ||
              // 排除 SELECT 下拉框
              activeElement.tagName === 'SELECT'
              // 🔥 快捷输入框现在使用减号键，不再需要排除（可以在输入框中按Enter结账）
          );

          if (isInSpecialInput) {
              return; // 在特殊输入框中，保持原有行为
          }

          // 检查购物车是否为空
          if (!cart || cart.length === 0) {
              return;
          }


          e.preventDefault();
          e.stopPropagation();

          // 🔥 智能判断：检查是否在查看桌位模式
          const viewMode = sessionStorage.getItem('tableViewMode');
          const isViewMode = viewMode ? JSON.parse(viewMode) : null;

          if (isViewMode && isViewMode.mode === 'view' && isViewMode.table) {
              // ========== 查看桌位模式：触发桌位结账 ==========

              // 获取桌位订单数据
              const orderData = sessionStorage.getItem('tableOrderData');
              if (orderData) {
                  const data = JSON.parse(orderData);
                  let orderIds = data.orders.map(order => order.id || order.order_number);
                  const activeCheckoutTable = typeof ruiyiResolveActiveTableNumber === 'function'
                      ? ruiyiResolveActiveTableNumber(isViewMode.table)
                      : isViewMode.table;

                  // 🔥🔥🔥 【2026-01-31 关键修复】使用与结账按钮相同的保存逻辑
                  // 原问题：直接调用 crearPedidoMesa 会修改购物车对象引用，导致重复按回车时数量翻倍
                  // 解决方案：使用 ensureTableOrderSaved() 统一保存逻辑，创建新对象而非修改引用
                  const hasUnlockedItems = cart && cart.some(item => !item.locked && item.quantity > 0);
                  const hasLockedItems = cart && cart.some(item => item.locked && item.quantity > 0);

                  if (hasUnlockedItems || hasLockedItems) {
                      // 有产品需要处理

                      Swal.fire({
                          title: '<?php echo ruiyi_translate("Guardando productos...", "Saving products...", "正在保存产品..."); ?>',
                          text: '<?php echo ruiyi_translate("Por favor espere", "Please wait", "请稍候"); ?>',
                          allowOutsideClick: false,
                          didOpen: () => { Swal.showLoading(); }
                      });

                      // 🔥 使用与结账按钮相同的 ensureTableOrderSaved 函数
                      // 这个函数会正确处理商品锁定状态，避免数量翻倍问题
                      (async () => {
                          try {
                              const saveSuccess = await ensureTableOrderSaved();
                              Swal.close();

                              if (!saveSuccess) {
                                  Swal.fire({
                                      icon: 'error',
                                      title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
                                      text: '<?php echo ruiyi_translate("No se pudo guardar los productos", "Could not save products", "无法保存产品"); ?>'
                                  });
                                  return;
                              }

                              // 🔥 重新获取订单ID列表（从锁定商品和localStorage）
                              let updatedOrderIds = [];

                              // 从锁定商品获取订单ID
                              const lockedItems = cart.filter(item => item.locked && item.quantity > 0);
                              if (lockedItems.length > 0) {
                                  updatedOrderIds = [...new Set(lockedItems.map(item => item.orderId).filter(id => id))];
                              }

                              // 如果没有从购物车获取到，尝试从localStorage获取
                              if (updatedOrderIds.length === 0) {
                                  const tableData = typeof ruiyiFindPrebillMesaState === 'function'
                                      ? ruiyiFindPrebillMesaState(activeCheckoutTable)?.data
                                      : null;
                                  if (tableData?.orderId) {
                                      updatedOrderIds = [tableData.orderId];
                                  } else if (tableData?.orderIds && tableData.orderIds.length > 0) {
                                      updatedOrderIds = tableData.orderIds;
                                  }
                              }

                              // 合并原有的订单ID（如果有）
                              if (orderIds.length > 0) {
                                  updatedOrderIds = [...new Set([...orderIds, ...updatedOrderIds])];
                              }

                              // 计算总金额（包括所有产品）
                              // 🔥 使用customPrice字段（如果存在），否则使用原价
                              const totalAmount = parseFloat(cart.reduce((sum, item) => {
                                  const itemPrice = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
                                  return sum + (itemPrice * item.quantity);
                              }, 0).toFixed(2));

                              // 调用结账处理函数
                              procesarPagoCompletoDeMesa(activeCheckoutTable, totalAmount, updatedOrderIds);
                          } catch (error) {
                              Swal.close();
                              console.error('[全局INTRO错误]', error);
                              Swal.fire({
                                  icon: 'error',
                                  title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
                                  text: error.message || '<?php echo ruiyi_translate("Error al guardar productos", "Error saving products", "保存产品时出错"); ?>'
                              });
                          }
                      })();
                  } else {
                      // 没有未保存的产品，直接结账

                      // 使用当前购物车计算总金额（包括锁定和未锁定商品）
                      // 🔥 使用customPrice字段（如果存在），否则使用原价
                      // 🔥 修复：使用 toFixed(2) 避免浮点数精度问题
                      const totalAmount = parseFloat(cart.reduce((sum, item) => {
                          const itemPrice = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
                          return sum + (itemPrice * item.quantity);
                      }, 0).toFixed(2));

                      // 调用桌位结账函数
                      procesarPagoCompletoDeMesa(activeCheckoutTable, totalAmount, orderIds);
                  }
              } else {
                  // console.warn('[全局INTRO] 未找到桌位订单数据');
              }
          } else {
              // ========== 检查是否为空闲桌位创建新订单 ==========
              const tableNumberInput = document.getElementById('table-number');
              const tableNumber = tableNumberInput?.value?.trim();
              const tipoPedido = sessionStorage.getItem('tipoPedidoSeleccionado');

              if (tipoPedido === 'servir' && tableNumber) {
                  // 🔥🔥🔥 【2026-01-31 关键修复】桌位模式：使用 ensureTableOrderSaved 统一保存逻辑
                  // 原问题：直接调用 crearPedidoMesa 会修改购物车对象引用，导致重复按回车时数量翻倍
                  // 解决方案：使用 ensureTableOrderSaved() 统一保存逻辑

                  Swal.fire({
                      title: '<?php echo ruiyi_translate("Guardando pedido...", "Saving order...", "正在保存订单..."); ?>',
                      allowOutsideClick: false,
                      didOpen: () => { Swal.showLoading(); }
                  });

                  // 使用与结账按钮相同的保存逻辑
                  (async () => {
                      try {
                          const saveSuccess = await ensureTableOrderSaved();
                          Swal.close();

                          if (!saveSuccess) {
                              Swal.fire({
                                  icon: 'error',
                                  title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
                                  text: '<?php echo ruiyi_translate("No se pudo guardar el pedido", "Could not save order", "无法保存订单"); ?>'
                              });
                              return;
                          }

                          // 刷新桌位状态
                          if (typeof renderizarMesas === 'function') {
                              renderizarMesas('after-enter-key-checkout');
                          }

                          // 🔥 从localStorage获取订单ID
                          let newOrderIds = [];
                          const tableData = typeof ruiyiFindPrebillMesaState === 'function'
                              ? ruiyiFindPrebillMesaState(tableNumber)?.data
                              : null;
                          if (tableData?.orderId) {
                              newOrderIds = [tableData.orderId];
                          }

                          // 从锁定商品获取订单ID（作为备份）
                          if (newOrderIds.length === 0) {
                              const lockedItems = cart.filter(item => item.locked && item.quantity > 0);
                              if (lockedItems.length > 0) {
                                  newOrderIds = [...new Set(lockedItems.map(item => item.orderId).filter(id => id))];
                              }
                          }

                          // 计算总金额
                          const totalAmount = parseFloat(cart.reduce((sum, item) => {
                              const itemPrice = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
                              return sum + (itemPrice * item.quantity);
                          }, 0).toFixed(2));

                          // 触发堂食结账
                          procesarPagoCompletoDeMesa(tableNumber, totalAmount, newOrderIds);
                      } catch (error) {
                          Swal.close();
                          console.error('[全局INTRO错误]', error);
                          Swal.fire({
                              icon: 'error',
                              title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
                              text: error.message || '<?php echo ruiyi_translate("Error al guardar pedido", "Error saving order", "保存订单时出错"); ?>'
                          });
                      }
                  })();
              } else {
                  // ========== 外卖模式：触发外卖结账 ==========

                  // 计算总金额
                  // 🔥 使用customPrice字段（如果存在），否则使用原价
                  // 🔥 修复：使用 toFixed(2) 避免浮点数精度问题
                  const totalAmount = parseFloat(cart.reduce((sum, item) => {
                      const itemPrice = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
                      return sum + (itemPrice * item.quantity);
                  }, 0).toFixed(2));

                  // 🔥 启动外卖结账流程，自动选择现金支付
                  showTakeawayCheckoutModal(totalAmount, cart, true);
              }
          }
      });

      // ========================================
      // 🔥 ESC 键快捷保存订单功能
      // ========================================
      document.addEventListener('keydown', function(e) {
          if (e.key !== 'Escape') return;

          // 检查是否在收银页面
          const cajeroSection = document.getElementById('cajero');
          if (!cajeroSection || cajeroSection.classList.contains('hidden')) return;

          // 检查保存订单按钮是否可见（仅桌位点餐模式下可见）
          const saveBtn = document.getElementById('save-table-order-btn');
          if (!saveBtn || saveBtn.classList.contains('hidden') || saveBtn.style.display === 'none') return;

          // 检查是否有 SweetAlert 弹窗打开
          if (document.querySelector('.swal2-container') || document.querySelector('.swal2-popup')) return;

          e.preventDefault();
          e.stopPropagation();

          // 触发保存订单按钮点击
          saveBtn.click();
      });
    }

    // Varios 快捷输入功能
    function initVariosQuickInput() {
      const variosInput = document.getElementById('varios-price-input');

      if (!variosInput) {
        console.warn('Varios 输入框元素未找到，跳过初始化');
        return;
      }

      // 全局变量：Varios 产品 ID（将在页面加载时动态获取或创建）
      window.VARIOS_PRODUCT_ID = null;

      // 获取或创建 Varios 产品
      fetchOrCreateVariosProduct();

      // 输入框事件：格式化输入
      variosInput.addEventListener('input', function(e) {
        // 🔥 允许字母、数字和小数点（支持字母+数字组合，如A123, BC45）
        let value = this.value.replace(/[^0-9A-Za-z.]/g, '');

        // 确保只有一个小数点
        const parts = value.split('.');
        if (parts.length > 2) {
          value = parts[0] + '.' + parts.slice(1).join('');
        }

        // 限制小数位数为2位
        if (parts.length === 2 && parts[1].length > 2) {
          value = parts[0] + '.' + parts[1].substring(0, 2);
        }

        this.value = value;
      });

      // 输入框按键事件：[+] 添加 Varios，[-] 搜索产品编号
      variosInput.addEventListener('keydown', function(e) {
        // + 键：添加 Varios 杂项产品到购物车
        if (e.key === '+') {
          e.preventDefault();
          addVariosToCart();
        }

        // - 键（减号）：按产品编号精确搜索并添加产品
        if (e.key === '-') {
          e.preventDefault();
          searchAndAddProductByNumber();
        }

        // 🔥 / 键（斜杠）：应用折扣百分比
        if (e.key === '/') {
          e.preventDefault();
          applyDiscountFromVarios();
        }

        // 🔥 * 键（乘号）：将选中产品的数量乘以输入的数字
        if (e.key === '*') {
          e.preventDefault();
          multiplySelectedProductQuantity();
        }

        // Esc 键：清空输入框
        if (e.key === 'Escape') {
          e.preventDefault();
          this.value = '';
        }
      });

      // ========================================
      // 全局键盘监听：仅在收银页面激活
      // ========================================
      document.addEventListener('keydown', function(e) {
        // 检查是否在收银页面
        const cajeroSection = document.getElementById('cajero');
        if (!cajeroSection || cajeroSection.classList.contains('hidden')) {
          return; // 不在收银页面，不处理
        }

        // 如果当前焦点在其他输入框，不处理
        const activeElement = document.activeElement;
        if (activeElement && (
            activeElement.tagName === 'INPUT' ||
            activeElement.tagName === 'TEXTAREA' ||
            activeElement.tagName === 'SELECT'
        )) {
          return; // 用户正在任何输入框中，不干扰（包括varios-price-input）
        }

        // 如果在 SweetAlert2 弹窗中，不处理
        if (document.querySelector('.swal2-container')) {
          return;
        }

        // 🔥 数字键 0-9、字母 A-Z、a-z 或小数点（支持字母+数字组合）
        if (/^[0-9A-Za-z.]$/.test(e.key)) {
          e.preventDefault();

          // 聚焦到 Varios 输入框
          variosInput.focus();

          // 追加字符到输入框
          const currentValue = variosInput.value;
          variosInput.value = currentValue + e.key;

          // 触发 input 事件以执行格式化
          variosInput.dispatchEvent(new Event('input'));
        }

        // 只有加号键：添加到购物车（只在焦点不在任何输入框时触发）
        else if (e.key === '+') {
          e.preventDefault();
          addVariosToCart();
        }

        // 🔥 上下键：切换选中的购物车产品
        else if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
          e.preventDefault();
          navigateCartSelection(e.key === 'ArrowUp' ? 'up' : 'down');
        }
      });

      // ========================================
      // 🔥 上下键导航：切换选中的购物车产品
      // ========================================
      function navigateCartSelection(direction) {
        // 获取未锁定的产品索引列表
        const unlockedIndices = [];
        cart.forEach((item, index) => {
          if (!item.locked) {
            unlockedIndices.push(index);
          }
        });

        // 如果没有未锁定的产品，不处理
        if (unlockedIndices.length === 0) {
          return;
        }

        // 如果当前没有选中项，选中第一个或最后一个
        if (selectedCartItemIndex === null || selectedCartItemIndex === undefined) {
          if (direction === 'up') {
            // 向上：选中最后一个未锁定产品
            selectedCartItemIndex = unlockedIndices[unlockedIndices.length - 1];
          } else {
            // 向下：选中第一个未锁定产品
            selectedCartItemIndex = unlockedIndices[0];
          }
        } else {
          // 找到当前选中项在未锁定列表中的位置
          const currentPos = unlockedIndices.indexOf(selectedCartItemIndex);

          if (currentPos === -1) {
            // 当前选中的是锁定产品，重新选中第一个未锁定产品
            selectedCartItemIndex = unlockedIndices[0];
          } else {
            if (direction === 'up') {
              // 向上移动
              if (currentPos > 0) {
                selectedCartItemIndex = unlockedIndices[currentPos - 1];
              } else {
                // 已经是第一个，循环到最后一个
                selectedCartItemIndex = unlockedIndices[unlockedIndices.length - 1];
              }
            } else {
              // 向下移动
              if (currentPos < unlockedIndices.length - 1) {
                selectedCartItemIndex = unlockedIndices[currentPos + 1];
              } else {
                // 已经是最后一个，循环到第一个
                selectedCartItemIndex = unlockedIndices[0];
              }
            }
          }
        }

        window.selectedCartItemIndex = selectedCartItemIndex;

        // 更新购物车显示
        renderCart();

        // 滚动到选中的项
        setTimeout(() => {
          const selectedRow = document.querySelector(`.cart-item-row[data-item-index="${selectedCartItemIndex}"]`);
          if (selectedRow) {
            selectedRow.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
          }
        }, 50);
      }

      // ========================================
      // 🔥 乘法功能：将选中产品的数量设置为输入的数字
      // ========================================
      function multiplySelectedProductQuantity() {
        const inputValue = variosInput.value.trim();
        const multiplier = parseInt(inputValue);

        // 检查输入是否为有效数字
        if (!inputValue || isNaN(multiplier) || multiplier < 1) {
          Toastify({
            text: '⚠️ <?php echo ruiyi_translate('Por favor ingrese un número válido', 'Please enter a valid number', '请输入有效数字'); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#ff9800" }
          }).showToast();
          return;
        }

        // 检查是否有选中的产品
        if (selectedCartItemIndex === null || selectedCartItemIndex === undefined) {
          Toastify({
            text: '⚠️ <?php echo ruiyi_translate('Por favor seleccione un producto primero', 'Please select a product first', '请先选择一个产品'); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#ff9800" }
          }).showToast();
          return;
        }

        // 检查选中的产品是否存在且未锁定
        const selectedItem = cart[selectedCartItemIndex];
        if (!selectedItem) {
          Toastify({
            text: '⚠️ <?php echo ruiyi_translate('Producto no encontrado', 'Product not found', '未找到产品'); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#ff9800" }
          }).showToast();
          return;
        }

        if (selectedItem.locked) {
          Toastify({
            text: '⚠️ <?php echo ruiyi_translate('No se puede modificar producto bloqueado', 'Cannot modify locked product', '无法修改已锁定的产品'); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#ff9800" }
          }).showToast();
          return;
        }

        // 将数量设置为输入的数字
        const oldQuantity = selectedItem.quantity;
        selectedItem.quantity = multiplier;

        // 🔥 同步调整 addedQuantity（厨房打印盒子）
        const qtyDiff = multiplier - oldQuantity;
        if (qtyDiff < 0 && (selectedItem.addedQuantity || 0) > 0) {
          selectedItem.addedQuantity = Math.max(0, (selectedItem.addedQuantity || 0) + qtyDiff);
        } else if (qtyDiff > 0) {
          selectedItem.addedQuantity = (selectedItem.addedQuantity || 0) + qtyDiff;
        }

        // 更新购物车显示
        renderCart();

        // 清空输入框
        variosInput.value = '';

        // 显示成功提示
        Toastify({
          text: `✅ ${selectedItem.name} x${multiplier}`,
          duration: 1500,
          gravity: "top",
          position: "center",
          style: { background: "#4caf50" }
        }).showToast();
      }

      // ========================================
      // 添加 Varios 到购物车的函数
      // ========================================
      function addVariosToCart() {
        const priceValue = parseFloat(variosInput.value);

        // 🔥🔥🔥 【2026-01-20 修复】如果输入框为空，增加最后一个 Varios 的数量
        // 优先查找未锁定的，如果没有则查找锁定的（与 handleProductCardClick 一致）
        if (!priceValue || priceValue <= 0 || isNaN(priceValue)) {
          // 步骤1：先查找未锁定的 Varios
          let lastVarios = cart.filter(item => item.isVarios && !item.locked && !cartItemHasLineModifiers(item)).pop();
          let isLockedVarios = false;

          // 步骤2：如果没有未锁定的，查找锁定的
          if (!lastVarios) {
            lastVarios = cart.filter(item => item.isVarios && item.locked).pop();
            if (lastVarios) {
              isLockedVarios = true;
            }
          }

          if (lastVarios) {
            // 找到最后一个 Varios，增加数量
            lastVarios.quantity += 1;
            // 🔥 追踪本次新增数量（用于厨房打印）
            lastVarios.addedQuantity = (lastVarios.addedQuantity || 0) + 1;

            // 🔥🔥🔥 关键：如果是锁定商品，标记为已修改
            if (isLockedVarios) {
              lastVarios.quantityModified = true;
              lastVarios.isNew = true;
              window.cartModified = true;
              console.log('[addVariosToCart] 🔒➕ 锁定 Varios（空输入）数量已增加，标记 cartModified = true');
            }

            // 更新购物车显示
            renderCart();

            // 显示成功提示
            const displayPrice = lastVarios.customPrice !== undefined ? lastVarios.customPrice : lastVarios.price;
            Toastify({
              text: `✅ Varios €${parseFloat(displayPrice).toFixed(2)} x${lastVarios.quantity}`,
              duration: 1500,
              gravity: "top",
              position: "center",
              style: { background: "#4caf50" }
            }).showToast();

            return; // 完成操作
          } else {
            // 购物车中没有 Varios，提示输入价格
            Toastify({
              text: '⚠️ <?php echo ruiyi_translate('Por favor ingrese un precio válido', 'Please enter a valid price', '请输入有效价格'); ?>',
              duration: 2000,
              gravity: "top",
              position: "center",
              style: { background: "#ff9800" }
            }).showToast();
            variosInput.focus();
            return;
          }
        }

        // 检查 Varios 产品 ID 是否已获取
        if (!window.VARIOS_PRODUCT_ID) {
          Toastify({
            text: '⚠️ <?php echo ruiyi_translate('Producto Varios no disponible, recargando...', 'Varios product not available, reloading...', 'Varios 产品未就绪，正在重新加载...'); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#ff9800" }
          }).showToast();

          // 重新获取产品
          fetchOrCreateVariosProduct(() => {
            addVariosToCart(); // 重试
          });
          return;
        }

        // 检查是否在查看模式
        const viewMode = sessionStorage.getItem('tableViewMode');
        const isViewMode = viewMode ? JSON.parse(viewMode) : null;

        // 🔥🔥🔥 【2026-01-20 关键修复】与 handleProductCardClick 一致的逻辑
        // 1. 先查找未锁定的相同价格 Varios
        // 2. 如果没有，再查找锁定的相同价格 Varios
        // 3. 如果找到锁定的，设置 quantityModified 和 cartModified

        // 步骤1：先查找未锁定的相同价格 Varios（可以直接增加数量）
        let existingVariosIndex = cart.findIndex(item =>
          item.isVarios &&
          canMergeUnlockedCartLine(item, window.VARIOS_PRODUCT_ID, priceValue)
        );

        // 🔥🔥🔥 【2026-03-30 关键修改】不再合并到 locked 的 Varios
        // 新添加的 Varios 只在 unlocked 项中查找合并

        if (existingVariosIndex !== -1) {
          const existingVarios = cart[existingVariosIndex];
          // 相同价格的未锁定 Varios 已存在，增加数量
          existingVarios.quantity += 1;
          // 🔥 追踪本次新增数量（用于厨房打印）
          existingVarios.addedQuantity = (existingVarios.addedQuantity || 0) + 1;

          // 🔥 自动选中该产品
          selectedCartItemIndex = existingVariosIndex;
          window.selectedCartItemIndex = existingVariosIndex;
        } else {
          // 不同价格，添加新的 Varios 条目
          cart.push({
            id: window.VARIOS_PRODUCT_ID,
            name: 'Varios',
            name_es: 'Varios',
            name_zh: 'Varios',
            name_en: 'Miscellaneous',
            price: priceValue,
            quantity: 1,
            addedQuantity: 1, // 🔥 追踪本次新增数量（用于厨房打印）
            taxRate: 10, // 🔥 修复：Varios 产品使用默认 10% IVA 税率
            image_url: '', // 无图片
            isVarios: true, // 标记为 Varios 商品
            isNew: isViewMode ? true : false,
            locked: false
          });
          // 🔥 自动选中新添加的产品
          selectedCartItemIndex = cart.length - 1;
          window.selectedCartItemIndex = cart.length - 1;
        }

        // 更新购物车显示
        renderCart();

        // 清空输入框
        variosInput.value = '';

        // 显示成功提示
        Toastify({
          text: `✅ Varios €${priceValue.toFixed(2)} <?php echo ruiyi_translate('agregado al carrito', 'added to cart', '已添加到购物车'); ?>`,
          duration: 1500,
          gravity: "top",
          position: "center",
          style: { background: "#ff9800" }
        }).showToast();

      }

      // ========================================
      // 🔥 新增：按产品编号精确搜索并添加产品
      // ========================================
      function searchAndAddProductByNumber() {
        const inputValue = variosInput.value.trim();

        // 如果输入框为空，不执行任何操作
        if (!inputValue) {
          return;
        }


        // 从全局产品列表中搜索匹配的产品
        let matchedProduct = null;
        let matchedCard = null; // 🔥 保存匹配的产品卡片，用于获取区域价格

        // 🔥 策略1：优先通过SKU精确匹配（支持字母+数字组合，如A123, BC45）
        // 🔥 策略2：如果SKU未找到，回退到产品名称前缀匹配（向后兼容）

        // 检查 window.products 是否存在（假设产品列表存储在这里）
        if (window.products && Array.isArray(window.products)) {
          // 策略1：SKU精确匹配（不区分大小写）
          matchedProduct = window.products.find(product =>
            product.sku && product.sku.toLowerCase() === inputValue.toLowerCase()
          );

          // 策略2：如果SKU未找到，尝试产品名称前缀匹配
          if (!matchedProduct) {
            const searchPattern = new RegExp(`^${inputValue}\\.`, 'i');
            matchedProduct = window.products.find(product => searchPattern.test(product.name));
          }

          // 🔥 如果找到产品，尝试获取对应的产品卡片以获取区域价格
          if (matchedProduct) {
            matchedCard = document.querySelector(`.product-card[data-id="${matchedProduct.id}"]`);
          }
        }
        // 如果没有全局产品列表，尝试从当前显示的产品卡片中查找
        else {
          const productCards = document.querySelectorAll('.product-card[data-name]');
          for (let card of productCards) {
            const productSku = card.getAttribute('data-sku');
            const productName = card.getAttribute('data-name');

            // 策略1：SKU精确匹配
            if (productSku && productSku.toLowerCase() === inputValue.toLowerCase()) {
              matchedProduct = {
                id: parseInt(card.getAttribute('data-id')),
                name: productName,
                price: parseFloat(card.getAttribute('data-price')),
                image: card.getAttribute('data-image') || card.querySelector('img')?.src || '',
                sku: productSku
              };
              matchedCard = card; // 🔥 保存产品卡片
              break;
            }

            // 策略2：产品名称前缀匹配（向后兼容）
            const searchPattern = new RegExp(`^${inputValue}\\.`, 'i');
            if (searchPattern.test(productName)) {
              matchedProduct = {
                id: parseInt(card.getAttribute('data-id')),
                name: productName,
                price: parseFloat(card.getAttribute('data-price')),
                image: card.getAttribute('data-image') || card.querySelector('img')?.src || ''
              };
              matchedCard = card; // 🔥 保存产品卡片
              break;
            }
          }
        }

        // 如果找到匹配的产品
        if (matchedProduct) {

          // 🔥 应用区域定价逻辑
          const basePrice = matchedProduct.price;
          let finalPrice = basePrice;
          const currentCategoryId = getCurrentTableCategoryId();
          if (matchedCard) {
            const zonePrices = parseZonePrices(matchedCard);
            finalPrice = getProductPriceForCurrentZone(basePrice, zonePrices, currentCategoryId);
          }

          // 🔥 从产品卡片或 window.products 获取完整信息
          let name_es = matchedProduct.name;
          let name_zh = '';
          let name_en = '';
          let taxRate = 10;
          let categoryIds = normalizeCartCategoryIds(matchedProduct.categoryIds || matchedProduct.category_ids || matchedProduct.categories || matchedProduct.category_id || []);
          if (matchedCard) {
            name_es = matchedCard.getAttribute('data-name-es') || matchedProduct.name;
            name_zh = matchedCard.getAttribute('data-name-zh') || '';
            name_en = matchedCard.getAttribute('data-name-en') || '';
            taxRate = parseFloat(matchedCard.getAttribute('data-tax-rate')) || 10;
            categoryIds = normalizeCartCategoryIds(matchedCard.getAttribute('data-categories') || categoryIds);
          } else if (matchedProduct.name_es || matchedProduct.name_zh || matchedProduct.name_en) {
            name_es = matchedProduct.name_es || matchedProduct.name;
            name_zh = matchedProduct.name_zh || '';
            name_en = matchedProduct.name_en || '';
          }

          // 🔥 与产品卡片点击一致的逻辑：
          // 步骤1：先查找未锁定的相同产品（可以直接增加数量）
          let existingItemIndex = cart.findIndex(item => canMergeUnlockedCartLine(item, matchedProduct.id, finalPrice));

          // 🔥🔥🔥【2026-04-08】回滚：不再合并到 locked 项，新产品独立显示

          if (existingItemIndex !== -1) {
            // 找到未锁定的相同产品，增加数量
            cart[existingItemIndex].quantity += 1;
            // 🔥 追踪本次新增数量（用于厨房打印）
            cart[existingItemIndex].addedQuantity = (cart[existingItemIndex].addedQuantity || 0) + 1;

            // 🔥 自动选中该产品
            selectedCartItemIndex = existingItemIndex;
            window.selectedCartItemIndex = existingItemIndex;
          } else {
            // 🔥🔥🔥 【2026-03-11 关键修复】添加完整字段的购物车项，与 handleProductCardClick 一致
            const cartItem = {
              id: matchedProduct.id,
              name: name_es,
              name_es: name_es,
              name_zh: name_zh,
              name_en: name_en,
              price: finalPrice,
              originalPrice: finalPrice,
              basePrice: basePrice,
              zoneCategoryId: currentCategoryId,
              quantity: 1,
              addedQuantity: 1,
              taxRate: taxRate,
              image_url: matchedProduct.image || 'https://via.placeholder.com/40',
              isNew: false,
              locked: false,
              is_buffet: false,
              categoryIds: categoryIds
            };

            // 🔥 分区价格：设置 customPrice 确保后端使用正确价格
            if (currentCategoryId && finalPrice !== basePrice) {
              cartItem.customPrice = finalPrice;
            }

            cart.push(cartItem);
            // 🔥 自动选中新添加的产品
            selectedCartItemIndex = cart.length - 1;
            window.selectedCartItemIndex = cart.length - 1;
          }

          // 更新购物车显示
          renderCart();

          // 清空输入框
          variosInput.value = '';

          // 🔥 移除成功提示弹窗 - 静默添加产品
        } else {
          // 未找到匹配的产品
          // console.warn('[产品搜索] 未找到编号为', inputValue, '的产品');

          // 显示错误提示
          Toastify({
            text: `❌ <?php echo ruiyi_translate('Producto', 'Product', '产品'); ?> ${inputValue}.* <?php echo ruiyi_translate('no encontrado', 'not found', '未找到'); ?>`,
            duration: 3000,
            gravity: 'top',
            position: 'right',
            backgroundColor: '#ef4444',
            stopOnFocus: true
          }).showToast();

          // 清空输入框
          variosInput.value = '';
        }
      }

      // 🔥 从 Varios 输入框应用折扣百分比
      function applyDiscountFromVarios() {
        const inputValue = variosInput.value.trim();

        // 解析折扣百分比
        const discountPercent = parseFloat(inputValue) || 0;

        // 🔥 【新功能】输入 0 时移除订单折扣
        if (discountPercent === 0 || inputValue === '0') {
          // 检查购物车是否为空
          if (!cart || cart.length === 0) {
            Toastify({
              text: '<?php echo ruiyi_translate('El carrito está vacío', 'Cart is empty', '购物车为空'); ?>',
              duration: 2000,
              gravity: "top",
              position: "center",
              style: { background: "#ff9800" }
            }).showToast();
            variosInput.value = '';
            return;
          }

          // 移除所有商品的折扣
          let hadDiscount = false;
          cart.forEach(item => {
            if (item.hasDiscount || (item.customPrice !== undefined && !item.supplements?.length)) {
              hadDiscount = true;
              // 恢复原价
              if (item.originalPrice !== undefined) {
                item.price = item.originalPrice;
              }
              // 清除折扣相关属性（🔥 保留有配料的 customPrice）
              if (!item.supplements || item.supplements.length === 0) {
                delete item.customPrice;
              } else {
                // 🔥 有配料：重新计算 customPrice = 原价 + 配料总价
                var supTotal = item.supplements.reduce(function(s, sup) { return s + parseFloat(sup.price || 0); }, 0);
                item.customPrice = (item._originalPrice || item.price) + supTotal;
              }
              delete item.hasDiscount;
              delete item.discountPercent;
              delete item.originalPrice;
            }
          });

          // 重置全局折扣百分比
          window.currentDiscountPercent = 0;

          // 重新渲染购物车
          renderCart();

          // 更新折扣显示标识
          if (typeof window.updateDiscountBadge === 'function') {
            window.updateDiscountBadge();
          } else if (typeof updateDiscountBadge === 'function') {
            updateDiscountBadge();
          }

          // 清空输入框
          variosInput.value = '';

          // 显示提示
          if (hadDiscount) {
            Toastify({
              text: '<?php echo ruiyi_translate('Descuento eliminado', 'Discount removed', '已移除折扣'); ?>',
              duration: 2000,
              gravity: "top",
              position: "center",
              style: { background: "#4caf50" }
            }).showToast();
          } else {
            Toastify({
              text: '<?php echo ruiyi_translate('No hay descuento que eliminar', 'No discount to remove', '没有需要移除的折扣'); ?>',
              duration: 2000,
              gravity: "top",
              position: "center",
              style: { background: "#ff9800" }
            }).showToast();
          }
          return;
        }

        if (discountPercent < 0) {
          Toastify({
            text: '<?php echo ruiyi_translate('Ingrese un descuento válido (ej: 10)', 'Enter a valid discount (e.g. 10)', '请输入有效折扣（如：10）'); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#ff9800" }
          }).showToast();
          return;
        }

        if (discountPercent > 100) {
          Toastify({
            text: '<?php echo ruiyi_translate('El descuento no puede ser mayor al 100%', 'Discount cannot exceed 100%', '折扣不能超过100%'); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#ff9800" }
          }).showToast();
          return;
        }

        // 检查购物车是否为空
        if (!cart || cart.length === 0) {
          Toastify({
            text: '<?php echo ruiyi_translate('El carrito está vacío', 'Cart is empty', '购物车为空'); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#ff9800" }
          }).showToast();
          return;
        }

        // 计算折扣比例
        const discountMultiplier = discountPercent / 100;

        // 🔥 修复：为购物车中的所有商品应用折扣（包括锁定的商品）
        // 这是购物车总额折扣，所有商品都应该参与折扣计算
        cart.forEach(item => {
          // 保存原价（如果还没保存）
          if (!item.originalPrice) {
            item.originalPrice = item.price;
          }

          // 计算折扣后价格
          // 🔥 修复：使用 toFixed(2) 和 parseFloat 避免浮点数精度问题（如多出0.01）
          const discountedPrice = parseFloat((item.originalPrice * (1 - discountMultiplier)).toFixed(2));
          item.customPrice = discountedPrice;
          item.hasDiscount = true;
          item.discountPercent = discountPercent;
        });

        // 保存当前折扣百分比
        window.currentDiscountPercent = discountPercent;

        // 重新渲染购物车
        renderCart();

        // 🔥 更新折扣显示标识（检查函数是否存在）
        if (typeof window.updateDiscountBadge === 'function') {
          window.updateDiscountBadge();
        } else if (typeof updateDiscountBadge === 'function') {
          updateDiscountBadge();
        }

        // 显示成功提示
        Toastify({
          text: `✅ <?php echo ruiyi_translate('Descuento aplicado', 'Discount applied', '已应用折扣'); ?>: ${discountPercent}%`,
          duration: 2000,
          gravity: "top",
          position: "center",
          style: { background: "#4caf50" }
        }).showToast();

        // 清空输入框
        variosInput.value = '';
      }

      // ========================================
      // 获取或创建 Varios 产品
      // ========================================
      function fetchOrCreateVariosProduct(callback) {
        var ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
        var ajaxNonce = window.RUIYI_POS?.nonce || posNonce;

        fetch(ajaxUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            action: 'ruiyi_get_or_create_varios_product',
            nonce: ajaxNonce
          })
        })
        .then(response => response.json())
        .then(data => {
          if (data.success && data.data.product_id) {
            window.VARIOS_PRODUCT_ID = data.data.product_id;

            // 执行回调（如果提供）
            if (callback && typeof callback === 'function') {
              callback();
            }
          } else {
            // console.error('[Varios] 获取产品失败:', data.message);
          }
        })
        .catch(error => {
          // console.error('[Varios] 网络错误:', error);
        });
      }
    }

    // ========================================
    // 🔥 折扣输入框功能初始化
    // ========================================
    function initDiscountInput() {
      const discountInput = document.getElementById('discount-percent-input');

      if (!discountInput) {
        return;
      }

      // 全局变量：存储当前应用的折扣百分比
      window.currentDiscountPercent = 0;

      // 输入框格式化：只允许0-100的整数
      discountInput.addEventListener('input', function(e) {
        let value = this.value.replace(/[^0-9]/g, ''); // 只允许数字

        // 限制范围 0-100
        if (value !== '') {
          const numValue = parseInt(value);
          if (numValue > 100) {
            value = '100';
          } else if (numValue < 0) {
            value = '0';
          }
        }

        this.value = value;
      });

      // 🔥 "/" 键应用折扣（修改为斜杠键）
      discountInput.addEventListener('keydown', function(e) {
        if (e.key === '/') {
          e.preventDefault();
          applyDiscountToCart();
        }

        // Esc键取消折扣
        if (e.key === 'Escape') {
          e.preventDefault();
          this.value = '';
          removeDiscountFromCart();
        }
      });

      // 应用折扣到购物车
      function applyDiscountToCart() {
        const discountPercent = parseFloat(discountInput.value) || 0;

        if (discountPercent <= 0) {
          Toastify({
            text: '<?php echo ruiyi_translate('Ingrese un porcentaje de descuento válido', 'Please enter a valid discount percentage', '请输入有效的折扣百分比'); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#ff9800" }
          }).showToast();
          return;
        }

        if (discountPercent > 100) {
          Toastify({
            text: '<?php echo ruiyi_translate('El descuento no puede ser mayor al 100%', 'Discount cannot exceed 100%', '折扣不能超过100%'); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#ff9800" }
          }).showToast();
          return;
        }

        // 检查购物车是否为空
        if (!cart || cart.length === 0) {
          Toastify({
            text: '<?php echo ruiyi_translate('El carrito está vacío', 'Cart is empty', '购物车为空'); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#ff9800" }
          }).showToast();
          return;
        }

        // 计算折扣比例
        const discountMultiplier = discountPercent / 100;

        // 🔥 修复：为购物车中的所有商品应用折扣（包括锁定的商品）
        // 桌位结账模式下，锁定的商品也需要能够打折扣
        cart.forEach(item => {
          // 保存原价（如果还没保存）
          if (!item.originalPrice) {
            item.originalPrice = item.price;
          }

          // 计算折扣后价格
          // 🔥 修复：使用 toFixed(2) 和 parseFloat 避免浮点数精度问题（如多出0.01）
          const discountedPrice = parseFloat((item.originalPrice * (1 - discountMultiplier)).toFixed(2));
          item.customPrice = discountedPrice;
          item.hasDiscount = true;
          item.discountPercent = discountPercent;
        });

        // 保存当前折扣百分比
        window.currentDiscountPercent = discountPercent;

        // 重新渲染购物车
        renderCart();

        // 🔥 更新折扣显示标识
        updateDiscountBadge();

        // 显示成功提示
        Toastify({
          text: `✅ <?php echo ruiyi_translate('Descuento aplicado', 'Discount applied', '已应用折扣'); ?>: ${discountPercent}%`,
          duration: 2000,
          gravity: "top",
          position: "center",
          style: { background: "#4caf50" }
        }).showToast();

        // 清空输入框
        discountInput.value = '';
      }

      // 移除折扣
      function removeDiscountFromCart() {
        if (window.currentDiscountPercent === 0) {
          return;
        }

        // 恢复所有商品的原价（🔥 保留配料价格）
        cart.forEach(item => {
          if (item.hasDiscount && item.originalPrice) {
            if (item.supplements && item.supplements.length > 0) {
              // 🔥 有配料：重新计算 customPrice = 原价 + 配料总价
              var supTotal = item.supplements.reduce(function(s, sup) { return s + parseFloat(sup.price || 0); }, 0);
              item.customPrice = (item._originalPrice || item.originalPrice || item.price) + supTotal;
            } else {
              item.customPrice = undefined;
            }
            item.hasDiscount = false;
            item.discountPercent = 0;
          }
        });

        // 重置折扣百分比
        window.currentDiscountPercent = 0;

        // 重新渲染购物车
        renderCart();

        // 🔥 隐藏折扣标识
        updateDiscountBadge();

        // 显示提示
        Toastify({
          text: '❌ <?php echo ruiyi_translate('Descuento eliminado', 'Discount removed', '折扣已取消'); ?>',
          duration: 1500,
          gravity: "top",
          position: "center",
          style: { background: "#6b7280" }
        }).showToast();
      }

      // 🔥 updateDiscountBadge 函数已移至全局作用域
    }

    // 查看桌位订单功能
    // Helper function to get offline orders by table number
    async function getOfflineOrdersByTable(tableNumber) {
      return new Promise((resolve, reject) => {
        const cleanTableNumber = resolveGlobalTableNumber(tableNumber);
        const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
        const mesaKey = `Mesa ${cleanTableNumber}`;
        
        
        // Try posDB first
        if (typeof posDB !== 'undefined' && posDB && typeof posDB.getPendingOrders === 'function') {
          posDB.getPendingOrders().then(orders => {
            const tableOrders = orders.filter(order => {
              const orderTableNumber = order.table_number || '';
              const orderCleanTable = resolveGlobalTableNumber(orderTableNumber);
              return orderCleanTable === cleanTableNumber || orderTableNumber === mesaKey || orderTableNumber === tableNumber;
            });
            resolve(tableOrders);
          }).catch(() => {
            // Fallback to direct IndexedDB
            getPendingOrdersFallbackIndexedDB().then(orders => {
              const tableOrders = orders.filter(order => {
                const orderTableNumber = order.table_number || '';
                const orderCleanTable = resolveGlobalTableNumber(orderTableNumber);
                return orderCleanTable === cleanTableNumber || orderTableNumber === mesaKey || orderTableNumber === tableNumber;
              });
              resolve(tableOrders);
            }).catch(reject);
          });
        } else {
          // Fallback to direct IndexedDB
          getPendingOrdersFallbackIndexedDB().then(orders => {
            const tableOrders = orders.filter(order => {
              const orderTableNumber = order.table_number || '';
              const orderCleanTable = resolveGlobalTableNumber(orderTableNumber);
              return orderCleanTable === cleanTableNumber || orderTableNumber === mesaKey || orderTableNumber === tableNumber;
            });
            resolve(tableOrders);
          }).catch(reject);
        }
      });
    }

    // Convert offline order format to expected format
    function convertOfflineOrderToOrderData(offlineOrders) {
      const orders = offlineOrders.map(offlineOrder => {
        const items = (offlineOrder.cart || []).map(cartItem => ({
          product_id: cartItem.id || Date.now() + Math.random(),
          name: cartItem.name || 'Unknown Product',
          quantity: cartItem.quantity || 1,
          price: cartItem.customPrice || cartItem.price || 0,
          total: (cartItem.customPrice || cartItem.price || 0) * (cartItem.quantity || 1),
          original_price: cartItem.price || 0,
          image_url: cartItem.image_url || '/wp-content/themes/RUIYI_POS-Manager/assets/images/placeholder.png',
          item_id: cartItem.id || Date.now() + Math.random()
        }));

        return {
          id: offlineOrder.id,
          order_number: offlineOrder.id.replace('OFFLINE_', ''),
          items: items,
          status: offlineOrder.status || 'pending',
          timestamp: offlineOrder.timestamp || Date.now()
        };
      });

      return { orders: orders };
    }

    // 🔥🔥🔥 【2026-04-10 新增】等待桌位同步完成
    // 用于"秒挂单秒进桌位"场景：quickSaveTableOrder 设置 _pendingSync=true 后
    // 用户立即进入桌位，需要等待 syncTableOrderToServer 完成后再获取服务器真实数据
    // 避免使用 PENDING_ orderId 和假 itemId 导致删除等操作失败
    function waitForPendingSync(mesaKey, maxWaitMs) {
      return new Promise(resolve => {
        const startTime = Date.now();
        const checkInterval = setInterval(() => {
          const elapsed = Date.now() - startTime;
          const estado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
          const data = estado[mesaKey];

          // 同步完成的标志：
          // 1. _pendingSync 被清除
          // 2. orderId 变为真实ID（非 PENDING_/OFFLINE_ 开头）
          // 3. 数据被删除（桌位已释放）
          const syncDone = !data || data._pendingSync !== true ||
              (data.orderId && !String(data.orderId).startsWith('PENDING_') &&
               !String(data.orderId).startsWith('OFFLINE_'));

          // 同时检查全局同步锁是否已释放
          const syncLockReleased = !window._syncTableOrderInProgress;

          // 🔥🔥🔥 【2026-04-10 优化】快速检测同步失败：
          // 如果同步锁已释放但 _pendingSync 仍为 true，说明同步已失败，无需等满5秒
          const syncFailed = syncLockReleased && !syncDone && elapsed > 5000;

          if ((syncDone && syncLockReleased) || syncFailed || elapsed >= maxWaitMs) {
            clearInterval(checkInterval);
            if (syncFailed) {
              console.warn('[waitForPendingSync] ⚠️ 同步可能失败（锁已释放但 _pendingSync 未清除），' + elapsed + 'ms');
            } else if (elapsed >= maxWaitMs) {
              console.warn('[waitForPendingSync] ⚠️ 超时(' + maxWaitMs + 'ms)，继续获取服务器数据');
            } else {
              console.log('[waitForPendingSync] ✅ 同步完成 (' + elapsed + 'ms)');
            }
            resolve();
          }
        }, 200);
      });
    }

    // 🔥 当前正在查看的桌位全局编号（防止异步回调加载错误桌位数据）
    window._currentViewingTable = null;

    function viewTableOrder(tableNumber) {
      // 🔥 记录当前查看的桌位，异步回调会检查此值
      var resolvedTable = typeof ruiyiSafeResolveGlobalTableNumber === 'function'
        ? ruiyiSafeResolveGlobalTableNumber(tableNumber)
        : resolveGlobalTableNumber(tableNumber);
      tableDebugLog('viewTableOrder', '查看桌位订单', { rawInput: tableNumber, resolved: resolvedTable });
      if (typeof ruiyiLogTerrazaDebug === 'function') {
        ruiyiLogTerrazaDebug('viewTableOrder:start', {
          table_number: tableNumber,
          resolved: resolvedTable,
          previousCurrentViewingTable: window._currentViewingTable
        });
      }
      window._currentViewingTable = resolvedTable;

      // 🔥🔥🔥 【2026-01-30 关键修复】立即清空购物车，防止切换桌位时数据混乱
      cart = [];
      window.cart = cart;
      if (typeof ruiyiSetCartTableIdentity === 'function') {
        ruiyiSetCartTableIdentity(resolvedTable || tableNumber, 'viewTableOrder:init');
      }
      if (typeof renderCart === 'function') {
        renderCart();
      }

      // 🔥🔥🔥 【关键修复】清除该桌位的 _paymentCompleted 标记，允许追加订单
      try {
        const tableNumClear = typeof ruiyiSafeResolveGlobalTableNumber === 'function'
          ? ruiyiSafeResolveGlobalTableNumber(tableNumber)
          : resolveGlobalTableNumber(tableNumber);
        const mesaKeyClear = `Mesa ${tableNumClear}`;
        const mesasEstadoClear = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
        if (mesasEstadoClear[mesaKeyClear] && mesasEstadoClear[mesaKeyClear]._paymentCompleted) {
          delete mesasEstadoClear[mesaKeyClear]._paymentCompleted;
          delete mesasEstadoClear[mesaKeyClear]._skipAutoUpdate;
          localStorage.setItem('mesas_estado', JSON.stringify(mesasEstadoClear));
        }
        window._paymentJustCompleted = false;
      } catch (e) { /* localStorage cleanup after payment - non-critical */ }

      // 🔥 关闭工具箱展开区域（确保进入桌位时工具箱是关闭状态）
      const cartActionsContainer = document.querySelector('.cart-actions-fixed');
      if (cartActionsContainer && window.Alpine) {
        const alpineData = Alpine.$data(cartActionsContainer);
        if (alpineData) {
          alpineData.toolboxOpen = false;
        }
      }

      // 🔥 查看桌位时隐藏桌位模块的上一单信息
      if (typeof hideMesasLastOrderInfo === 'function') {
        hideMesasLastOrderInfo();
      }

      // 显示加载中
      Swal.fire({
        title: '<?php echo ruiyi_translate("Cargando...", "Loading...", "加载中..."); ?>',
        text: '<?php echo ruiyi_translate("Obteniendo información del pedido", "Getting order information", "获取订单信息"); ?>',
        allowOutsideClick: false,
        didOpen: () => {
          Swal.showLoading();
        }
      });

      // 保存查看模式信息到sessionStorage
      const _tableViewModePayload = JSON.stringify({
        table: tableNumber,
        mode: 'view',
        timestamp: Date.now()
      });
      sessionStorage.setItem('tableViewMode', _tableViewModePayload);
      sessionStorage.setItem('isViewMode', _tableViewModePayload);
      
      // Check if offline first
      const isOffline = !navigator.onLine || window.RUIYI_POS?.isOnline === false;

      // Try to load from localStorage or IndexedDB if offline
      if (isOffline) {

        // 🔥 PWA: First check localStorage for auto-saved orders
        const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');

        // 🔥 关键修复：使用多格式查找，确保能找到任何格式的键名
        // autoSaveTableOrder 使用固定 "Mesa X" 格式，但这里需要支持所有格式
        const tableNumberOnly = String(tableNumber).replace(/^(餐桌|Mesa|Table)\s*/i, '');
        const tableResult = typeof findTableDataByNumber === 'function'
          ? findTableDataByNumber(mesasEstado, tableNumberOnly)
          : { data: null, key: null };

        // 如果多格式查找找到了，使用它；否则回退到旧逻辑
        let tableStatus = tableResult.data;
        let mesaKey = tableResult.key;

        if (!tableStatus) {
          // 回退：尝试直接用当前语言前缀
          const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
          mesaKey = `Mesa ${tableNumberOnly}`;
          tableStatus = mesasEstado[mesaKey];
        }

        
        // 🔥 PWA修复：检查是否有本地缓存的购物车数据（无论在线还是离线创建）
        // 移除 _offline 强制检查，让在线创建的订单断网后也能访问
        if (tableStatus && tableStatus.cart && Array.isArray(tableStatus.cart) && tableStatus.cart.length > 0) {
          
          // Convert localStorage order to orderData format
          // 🔥 Ensure all required fields are present for order creation
          const orderData = {
            orders: [{
              id: tableStatus.orderId || 'OFFLINE_' + Date.now(),
              items: tableStatus.cart.map((item, idx) => {
                const _price = parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0));
                return {
                product_id: item.id || item.product_id || Date.now() + Math.random(),
                id: item.id || item.product_id || Date.now() + Math.random(),
                name: item.customName || item.name || '',
                name_es: item.name_es || item.name || '',
                name_zh: item.name_zh || '',
                name_en: item.name_en || '',
                quantity: item.quantity,
                price: _price,
                original_price: item._originalPrice || item.price || item.customPrice,
                total: _price * item.quantity,
                image_url: item.image_url || '/wp-content/themes/RUIYI_POS-Manager/assets/images/placeholder.png',
                item_id: item.itemId || item.item_id || `offline_item_${idx}_${Date.now()}`,
                hasDiscount: item.hasDiscount || false,
                discountPercent: item.discountPercent || 0,
                originalPrice: item.originalPrice || item.price,
                customName: item.customName || null
              };}),
              total: tableStatus.total || 0,
              status: 'processing'
            }]
          };
          
          // 🔥 Also save the original cart structure to sessionStorage for payment completion
          sessionStorage.setItem('offlineTableCart', JSON.stringify(tableStatus.cart));
          
          sessionStorage.setItem('tableOrderData', JSON.stringify(orderData));
          sessionStorage.setItem('tableOrderDataOffline', 'true');
          
          // Switch to cashier module
          const cajeroLink = document.querySelector('a[href="#cajero"]');
          if (cajeroLink) {
            document.querySelectorAll('main > section').forEach(section => {
              section.classList.add('hidden');
            });
            
            const cajeroSection = document.getElementById('cajero');
            if (cajeroSection) {
              cajeroSection.classList.remove('hidden');
            }
            
            document.querySelectorAll('.menu-link').forEach(link => {
              link.classList.remove('bg-red-600', 'text-white');
            });
            cajeroLink.classList.add('bg-red-600', 'text-white');
            
            loadTableOrderToCart(tableNumber, orderData);
            // 🔥 优化：updateAllButtonStates 已在 loadTableOrderToCart 内部调用，无需再次调用
          }

          Swal.close();

          // Show offline notification
          Toastify({
            text: `💾 <?php echo ruiyi_translate('Cargado desde caché offline', 'Loaded from offline cache', '从离线缓存加载'); ?>`,
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#6366f1" }
          }).showToast();
          return;
        }

        // If not in localStorage, try IndexedDB (for completed payments)
        getOfflineOrdersByTable(tableNumber).then(offlineOrders => {
          if (offlineOrders && offlineOrders.length > 0) {
            const orderData = convertOfflineOrderToOrderData(offlineOrders);
            sessionStorage.setItem('tableOrderData', JSON.stringify(orderData));
            sessionStorage.setItem('tableOrderDataOffline', 'true'); // Mark as offline data

            // Switch to cashier module
            const cajeroLink = document.querySelector('a[href="#cajero"]');
            if (cajeroLink) {
              document.querySelectorAll('main > section').forEach(section => {
                section.classList.add('hidden');
              });

              const cajeroSection = document.getElementById('cajero');
              if (cajeroSection) {
                cajeroSection.classList.remove('hidden');
              }

              document.querySelectorAll('.menu-link').forEach(link => {
                link.classList.remove('bg-red-600', 'text-white');
              });
              cajeroLink.classList.add('bg-red-600', 'text-white');

              loadTableOrderToCart(tableNumber, orderData);
              // 🔥 优化：updateAllButtonStates 已在 loadTableOrderToCart 内部调用，无需再次调用
            }
            
            Swal.close();
            
            // Show offline notification
            Toastify({
              text: `💾 <?php echo ruiyi_translate('Cargado desde caché offline', 'Loaded from offline cache', '从离线缓存加载'); ?>`,
              duration: 2000,
              gravity: "top",
              position: "center",
              style: { background: "#6366f1" }
            }).showToast();
          } else {
            Swal.close();
            Swal.fire({
              icon: 'info',
              title: '<?php echo ruiyi_translate("Sin pedidos offline", "No offline orders", "无离线订单"); ?>',
              text: '<?php echo ruiyi_translate("No se encontraron pedidos guardados para esta mesa", "No saved orders found for this table", "未找到此桌位的保存订单"); ?>'
            });
          }
        }).catch(error => {
          console.error('[PWA] Error loading offline orders:', error);
          Swal.close();
          Swal.fire({
            icon: 'error',
            title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
            text: '<?php echo ruiyi_translate("Error al cargar pedidos offline", "Error loading offline orders", "加载离线订单时出错"); ?>'
          });
        });
        return;
      }

      // 🔥 【关键修复】在线模式下，先检查是否有未同步的离线数据
      // 如果有 _offline: true 标记的数据，说明离线时保存的订单还未同步到服务器
      // 应该优先使用本地数据，避免服务器空数据覆盖本地离线数据
      const mesasEstadoOnline = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
      const tableNumberOnlyCheck = String(tableNumber).replace(/^(餐桌|Mesa|Table)\s*/i, '');
      const tableResultOnline = typeof findTableDataByNumber === 'function'
        ? findTableDataByNumber(mesasEstadoOnline, tableNumberOnlyCheck)
        : { data: null, key: null };

      let offlineTableStatus = tableResultOnline.data;
      if (!offlineTableStatus) {
        const tablePrefixCheck = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
        const mesaKeyCheck = `${tablePrefixCheck} ${tableNumberOnlyCheck}`;
        offlineTableStatus = mesasEstadoOnline[mesaKeyCheck] || mesasEstadoOnline[`Mesa ${tableNumberOnlyCheck}`];
      }
      if (typeof ruiyiLogTerrazaDebug === 'function') {
        ruiyiLogTerrazaDebug('viewTableOrder:local-status', {
          table_number: tableNumber,
          resolved: resolvedTable,
          tableNumberOnlyCheck,
          localKey: tableResultOnline.key || null,
          hasLocalStatus: !!offlineTableStatus,
          localOrderId: offlineTableStatus?.orderId || null,
          localTotal: offlineTableStatus?.total || null,
          pendingSync: offlineTableStatus?._pendingSync || false,
          offline: offlineTableStatus?._offline || false,
          skipAutoUpdate: offlineTableStatus?._skipAutoUpdate || false,
          localCartCount: offlineTableStatus?.cart?.length || 0,
          localKeys: Object.keys(mesasEstadoOnline).filter(key => key.includes(String(resolvedTable)) || key.toUpperCase().includes('TERRAZA')).slice(0, 20)
        });
      }

      // 🔥🔥🔥 【2026-01-20 关键修复】如果有未同步的数据，优先使用本地数据
      // 检查两种情况：
      // 1. _offline === true：离线时保存的订单还未同步到服务器
      // 2. _skipAutoUpdate === true：刚刚保存的订单（在线模式），服务器可能还没处理完成
      // 这解决了自动保存后返回桌位，新商品（如 Varios）丢失的问题
      //
      // 🔥🔥🔥 【2026-03-29 关键修复】增加 _recentlyCheckedOutTables 检查
      // 如果桌位刚刚完成结账（15秒内），即使 localStorage 有残留数据也不使用
      // 防止 AA 结账后 autoSaveTableOrder 竞态写回旧 cart 导致重复订单
      const tableNumForCheckout = resolveGlobalTableNumber(tableNumber);
      const recentlyCheckedOut = window._recentlyCheckedOutTables?.[tableNumForCheckout] &&
          (Date.now() - window._recentlyCheckedOutTables[tableNumForCheckout]) < 15000;

      // 🔥🔥🔥 【2026-04-10 关键修复】检测"在线待同步"场景
      // 当 _pendingSync=true 且在线时，不应使用本地数据（有 PENDING_ orderId 和假 itemId），
      // 而应等待同步完成后获取服务器真实数据，避免后续删除/修改操作因假ID而失败
      const _isPendingSyncOnline = offlineTableStatus?._pendingSync === true &&
          offlineTableStatus?._offline !== true;

      const hasUnsyncedLocalData = offlineTableStatus &&
          (offlineTableStatus._offline === true || (offlineTableStatus._skipAutoUpdate === true && !_isPendingSyncOnline)) &&
          offlineTableStatus.cart && Array.isArray(offlineTableStatus.cart) && offlineTableStatus.cart.length > 0 &&
          !recentlyCheckedOut;

      if (recentlyCheckedOut && offlineTableStatus?.cart?.length > 0) {
        console.warn('[viewTableOrder] 🛡️ 桌位刚刚结账（15秒内），忽略 localStorage 残留数据，使用服务器数据',
          { tableNum: tableNumForCheckout, _skipAutoUpdate: offlineTableStatus?._skipAutoUpdate });
        // 🔥 清除残留数据，防止下次进入时再次触发
        try {
          const cleanEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
          const cleanKey = tableResultOnline.key || `Mesa ${tableNumForCheckout}`;
          if (cleanEstado[cleanKey]) {
            delete cleanEstado[cleanKey];
            localStorage.setItem('mesas_estado', JSON.stringify(cleanEstado));
            console.log('[viewTableOrder] 🗑️ 已清除残留的 mesas_estado["' + cleanKey + '"]');
          }
        } catch(e) { /* localStorage cleanup - non-critical */ }
      }

      if (hasUnsyncedLocalData) {
        console.log('[viewTableOrder] 🔄 检测到未同步的本地数据，优先使用本地数据',
          { _offline: offlineTableStatus._offline, _skipAutoUpdate: offlineTableStatus._skipAutoUpdate });

        // Convert localStorage order to orderData format (same as offline mode)
        const orderDataOffline = {
          orders: [{
            id: offlineTableStatus.orderId || 'OFFLINE_' + Date.now(),
            items: offlineTableStatus.cart.map((item, idx) => {
              const _price = parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0));
              return {
              product_id: item.id || item.product_id || Date.now() + Math.random(),
              id: item.id || item.product_id || Date.now() + Math.random(),
              name: item.customName || item.name || '',
              name_es: item.name_es || item.name || '',
              name_zh: item.name_zh || '',
              name_en: item.name_en || '',
              quantity: item.quantity,
              price: _price,
              original_price: item._originalPrice || item.price || item.customPrice,
              total: _price * item.quantity,
              image_url: item.image_url || '/wp-content/themes/RUIYI_POS-Manager/assets/images/placeholder.png',
              item_id: item.itemId || item.item_id || `offline_item_${idx}_${Date.now()}`,
              hasDiscount: item.hasDiscount || false,
              discountPercent: item.discountPercent || 0,
              originalPrice: item.originalPrice || item.price,
              customName: item.customName || null,
              // 🔥 保留配料数据和分类映射
              supplements: item.supplements ? (typeof item.supplements === 'string' ? item.supplements : JSON.stringify(item.supplements)) : null,
              _originalName: item._originalName || null,
              _originalPrice: item._originalPrice !== undefined ? item._originalPrice : null,
              categoryIds: item.categoryIds || [],
              hasCustomName: !!item.customName,
              originalProductName: item._originalName || item.name_es || item.name || null,
              notes: item.notes || ''
            };}),
            total: offlineTableStatus.total || 0,
            status: 'processing'
          }]
        };

        sessionStorage.setItem('offlineTableCart', JSON.stringify(offlineTableStatus.cart));
        sessionStorage.setItem('tableOrderData', JSON.stringify(orderDataOffline));
        sessionStorage.setItem('tableOrderDataOffline', 'true');

        // Switch to cashier module
        const cajeroLinkOffline = document.querySelector('a[href="#cajero"]');
        if (cajeroLinkOffline) {
          document.querySelectorAll('main > section').forEach(section => {
            section.classList.add('hidden');
          });

          const cajeroSectionOffline = document.getElementById('cajero');
          if (cajeroSectionOffline) {
            cajeroSectionOffline.classList.remove('hidden');
          }

          document.querySelectorAll('.menu-link').forEach(link => {
            link.classList.remove('bg-red-600', 'text-white');
          });
          cajeroLinkOffline.classList.add('bg-red-600', 'text-white');

          loadTableOrderToCart(tableNumber, orderDataOffline);
        }

        Swal.close();
        return;
      }

      // 🔥 关键修复：使用带 Nonce 自动刷新重试的函数
      async function fetchTableOrdersWithRetry(tableNum, retryCount = 0) {
        // 获取最新的 nonce
        const currentNonce = (window.NonceManager && window.NonceManager.get()) || ajaxNonce;
        if (typeof ruiyiLogTerrazaDebug === 'function') {
          ruiyiLogTerrazaDebug('viewTableOrder:ajax-request', {
            table_number: tableNum,
            originalTableNumber: tableNumber,
            resolved: resolvedTable,
            retryCount,
            currentViewingTable: window._currentViewingTable
          });
        }

        const response = await fetch(ajaxUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            action: 'ruiyi_pos_get_table_orders',
            table_number: tableNum,
            nonce: currentNonce
          })
        });

        if (!response.ok) {
          // 🔥 如果是 403 错误（Nonce 验证失败），尝试刷新 Nonce 后重试
          if (response.status === 403 && retryCount < 1 && window.NonceManager) {
            console.warn('[viewTableOrder] ⚠️ Nonce 验证失败，刷新后重试...');
            try {
              await window.NonceManager.refresh(true);
              return fetchTableOrdersWithRetry(tableNum, retryCount + 1);
            } catch (e) {
              console.error('[viewTableOrder] ❌ Nonce 刷新失败:', e);
            }
          }
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();
        if (typeof ruiyiLogTerrazaDebug === 'function') {
          ruiyiLogTerrazaDebug('viewTableOrder:ajax-response', {
            table_number: tableNum,
            originalTableNumber: tableNumber,
            resolved: resolvedTable,
            retryCount,
            success: !!data.success,
            orderCount: data.data?.orders?.length || 0,
            count: data.data?.count || 0,
            tableNumberProcessed: data.data?.table_number_processed || null,
            message: data.data?.message || data.message || null,
            orders: (data.data?.orders || []).map(order => ({
              id: order.id,
              status: order.status,
              total: order.total,
              itemCount: order.items?.length || 0
            }))
          });
        }

        // 🔥 检查是否是 Nonce 错误的 JSON 响应
        if (!data.success && data.data?.message &&
            (data.data.message.includes('nonce') ||
             data.data.message.includes('Nonce') ||
             data.data.message.includes('seguridad') ||
             data.data.message.includes('安全验证'))) {
          if (retryCount < 1 && window.NonceManager) {
            console.warn('[viewTableOrder] ⚠️ Nonce 错误响应，刷新后重试...');
            await window.NonceManager.refresh(true);
            return fetchTableOrdersWithRetry(tableNum, retryCount + 1);
          }
        }

        return data;
      }

      // 🔥🔥🔥 【2026-04-10 关键修复】如果有在线待同步数据，先等待同步完成再获取服务器数据
      // 解决"秒挂单秒进桌位"竞态：用户保存订单后立即进入桌位，
      // 同步未完成时服务器无数据 → 商品显示为 PENDING_ ID → 删除等操作失败
      const _fetchAfterSync = async () => {
        if (_isPendingSyncOnline && offlineTableStatus?.cart?.length > 0) {
          const _syncMesaKey = tableResultOnline.key || `Mesa ${tableNumberOnlyCheck}`;
          console.log('[viewTableOrder] ⏳ 在线待同步中，等待同步完成...');
          Swal.update({ text: '<?php echo ruiyi_translate("Sincronizando pedido...", "Syncing order...", "同步订单中..."); ?>' });
          await waitForPendingSync(_syncMesaKey, 15000);
          console.log('[viewTableOrder] ✅ 同步等待完成，获取服务器数据');
        }
        const canonicalTableLookup = resolvedTable ? `Mesa ${resolvedTable}` : tableNumber;
        if (typeof ruiyiLogTerrazaDebug === 'function') {
          ruiyiLogTerrazaDebug('viewTableOrder:lookup-table', {
            table_number: canonicalTableLookup,
            originalTableNumber: tableNumber,
            resolved: resolvedTable,
            pendingSyncOnline: _isPendingSyncOnline,
            localKey: tableResultOnline.key || null,
            hasLocalStatus: !!offlineTableStatus,
            localOrderId: offlineTableStatus?.orderId || null
          });
        }
        return fetchTableOrdersWithRetry(canonicalTableLookup);
      };

      // Online: Get table order data from server
      _fetchAfterSync()
      .then(data => {
        tableDebugLog('viewTableOrder', '后端返回', { table: tableNumber, resolved: resolvedTable, success: data.success, orderCount: (data.data && data.data.orders) ? data.data.orders.length : 0 });
        if (data.success && data.data && data.data.orders && data.data.orders.length > 0) {
          // 🔥🔥🔥 【2026-01-31 关键修复】过滤掉已结账但待同步的订单
          // 防止网络延迟时旧订单重新出现的竞态条件漏洞
          if (typeof filterPendingPaymentOrders === 'function') {
            const originalOrders = data.data.orders;
            data.data.orders = filterPendingPaymentOrders(originalOrders);

            // 如果过滤后没有订单了，说明所有订单都已结账
            if (data.data.orders.length === 0) {
              console.log('[viewTableOrder] 🚫 所有订单都是已结账待同步，视为空桌位');
              Swal.close();
              // 清除viewMode
              sessionStorage.removeItem('tableViewMode');
              sessionStorage.removeItem('isViewMode');
              sessionStorage.removeItem('tableOrderData');
              // 跳转到收银模块创建新订单
              if (typeof cambiarSeccion === 'function') {
                cambiarSeccion('cajero');
              }
              // 设置桌位号
              const tableNumberInput = document.getElementById('table-number');
              if (tableNumberInput) {
                tableNumberInput.value = tableNumber;
                if (typeof updateCurrentTableDisplay === 'function') {
                  updateCurrentTableDisplay(tableNumber);
                }
              }
              Toastify({
                text: '<?php echo ruiyi_translate("Mesa vacía, crear nuevo pedido", "Empty table, create new order", "空桌位，创建新订单"); ?>',
                duration: 2000,
                gravity: 'top',
                position: 'center',
                style: { background: '#22c55e' }
              }).showToast();
              return;
            }
          }

          // 保存订单数据到sessionStorage
          sessionStorage.setItem('tableOrderData', JSON.stringify(data.data));
          
          // 切换到收银模块
          const cajeroLink = document.querySelector('a[href="#cajero"]');
          if (cajeroLink) {
            // 隐藏所有section
            document.querySelectorAll('main > section').forEach(section => {
              section.classList.add('hidden');
            });
            
            // 显示收银模块
            const cajeroSection = document.getElementById('cajero');
            if (cajeroSection) {
              cajeroSection.classList.remove('hidden');
            }
            
            // 更新菜单激活状态
            document.querySelectorAll('.menu-link').forEach(link => {
              link.classList.remove('bg-red-600', 'text-white');
            });
            cajeroLink.classList.add('bg-red-600', 'text-white');
            
            // 加载订单到购物车
            loadTableOrderToCart(tableNumber, data.data);
            // 🔥 优化：updateAllButtonStates 已在 loadTableOrderToCart 内部调用，无需再次调用
          }

          Swal.close();
        } else {
          // 🔥🔥🔥 【2026-04-10 关键修复】服务器返回无订单，但本地有待同步数据时，使用本地数据
          // 场景：quickSaveTableOrder 保存后 syncTableOrderToServer 失败（网络超时等），
          // 60秒后 _skipAutoUpdate 被清理，viewTableOrder 走在线获取 → 服务器无订单
          // 此时应该加载本地待同步的购物车数据，而不是显示"无订单"
          const _noOrderTableNum = resolveGlobalTableNumber(tableNumber);
          const _noOrderMesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
          const _noOrderResult = typeof findTableDataByNumber === 'function'
              ? findTableDataByNumber(_noOrderMesasEstado, _noOrderTableNum) : { data: null, key: null };
          const _noOrderData = _noOrderResult.data;

          if (_noOrderData && _noOrderData._pendingSync === true &&
              _noOrderData.cart && Array.isArray(_noOrderData.cart) && _noOrderData.cart.length > 0) {
            console.log('[viewTableOrder] 🔄 服务器无订单但本地有待同步数据，使用本地数据并重试同步');

            // 使用本地数据构建 orderData
            const _pendingOrderData = {
              orders: [{
                id: _noOrderData.orderId || 'PENDING_' + Date.now(),
                items: _noOrderData.cart.map((item, idx) => {
                  const _price = parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0));
                  return {
                  product_id: item.id || item.product_id || Date.now() + Math.random(),
                  id: item.id || item.product_id || Date.now() + Math.random(),
                  name: item.customName || item.name || '',
                  name_es: item.name_es || item.name || '',
                  name_zh: item.name_zh || '',
                  name_en: item.name_en || '',
                  quantity: item.quantity,
                  price: _price,
                  original_price: item._originalPrice || item.price || item.customPrice,
                  total: _price * item.quantity,
                  image_url: item.image_url || '/wp-content/themes/RUIYI_POS-Manager/assets/images/placeholder.png',
                  item_id: item.itemId || item.item_id || `pending_item_${idx}_${Date.now()}`,
                  customName: item.customName || null
                };}),
                total: _noOrderData.total || 0,
                status: 'processing'
              }]
            };

            sessionStorage.setItem('tableOrderData', JSON.stringify(_pendingOrderData));

            // 切换到收银模块并加载
            const cajeroLinkPending = document.querySelector('a[href="#cajero"]');
            if (cajeroLinkPending) {
              document.querySelectorAll('main > section').forEach(section => section.classList.add('hidden'));
              const cajeroSectionPending = document.getElementById('cajero');
              if (cajeroSectionPending) cajeroSectionPending.classList.remove('hidden');
              document.querySelectorAll('.menu-link').forEach(link => link.classList.remove('bg-red-600', 'text-white'));
              cajeroLinkPending.classList.add('bg-red-600', 'text-white');
              loadTableOrderToCart(tableNumber, _pendingOrderData);
            }

            Swal.close();

            // 尝试重新同步到服务器
            if (_noOrderData._newItemsToSync && _noOrderData._newItemsToSync.length > 0) {
              const _retryKey = _noOrderResult.key || `Mesa ${_noOrderTableNum}`;
              console.log('[viewTableOrder] 🔄 触发重新同步...');
              setTimeout(() => {
                if (typeof syncTableOrderToServer === 'function') {
                  syncTableOrderToServer({
                    mesaKey: _retryKey,
                    table_number: tableNumber,
                    tableNum: _noOrderTableNum,
                    newItems: _noOrderData._newItemsToSync,
                    tableTotal: _noOrderData.total || 0,
                    isAddition: false
                  });
                }
              }, 500);
            }

            return;
          }

          tableDebugLog('viewTableOrder', '⚠️ 无订单 - 将清除本地状态', { table: tableNumber, resolved: resolveGlobalTableNumber(tableNumber) });
          // 🔥 空闲桌位：清除之前设置的viewMode（因为没有订单，不是查看模式）
          sessionStorage.removeItem('tableViewMode');
          sessionStorage.removeItem('isViewMode');
          sessionStorage.removeItem('tableOrderData');

          // 🔥 关键修复：服务器确认该桌位无订单，清除本地桌位状态
          // 这修复了离线结账后桌位仍显示为占用的问题
          // 🔥 【重要】但不能清除有 _offline: true 标记的未同步离线数据！
          const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
          const tableNum = resolveGlobalTableNumber(tableNumber);
          const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';

          // 清除所有可能的桌位键格式
          const possibleKeys = [
            `${tablePrefix} ${tableNum}`,
            `Mesa ${tableNum}`,
            `Table ${tableNum}`,
            `餐桌 ${tableNum}`,
            tableNumber
          ];

          let statusCleared = false;
          possibleKeys.forEach(key => {
            if (mesasEstado[key]) {
              // 🔥 【关键保护】如果是未同步的离线数据或待同步数据，不要删除！
              // 🔥🔥🔥 【2026-04-10 修复】增加 _pendingSync 保护，防止同步失败时本地数据被清除
              if ((mesasEstado[key]._offline === true || mesasEstado[key]._pendingSync === true) &&
                  mesasEstado[key].cart && mesasEstado[key].cart.length > 0) {
                console.log('[viewTableOrder] ⚠️ 保护未同步数据，不清除:', key,
                  { _offline: mesasEstado[key]._offline, _pendingSync: mesasEstado[key]._pendingSync });
                return; // 跳过这个key，不删除
              }
              delete mesasEstado[key];
              statusCleared = true;
            }
          });

          if (statusCleared) {
            localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));

            // 同时清除桌位购物车
            const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
            possibleKeys.forEach(key => {
              if (carritosGuardados[key]) {
                delete carritosGuardados[key];
              }
            });
            localStorage.setItem('carritos_mesas', JSON.stringify(carritosGuardados));

            // 刷新桌位显示
            setTimeout(() => {
              if (typeof renderizarMesas === 'function') {
                renderizarMesas('clear-no-orders');
              }
            }, 100);
          }

          // 获取餐桌号用于开始点餐
          const tableNumberForOrder = resolveGlobalTableNumber(tableNumber);

          Swal.fire({
            icon: 'info',
            title: '<?php echo ruiyi_translate("Sin pedidos", "No orders", "无订单"); ?>',
            text: '<?php echo ruiyi_translate("Esta mesa no tiene pedidos activos", "This table has no active orders", "该桌位没有活动订单"); ?>',
            showCancelButton: true,
            showConfirmButton: false,
            cancelButtonText: '<?php echo ruiyi_translate("Cancelar", "Cancel", "取消"); ?>',
            cancelButtonColor: '#6b7280'
          });
        }
      })
      .catch(error => {
        console.error('Error loading table orders:', error);

        // 如果是403错误，由全局拦截器处理
        if (error.message && error.message.includes('403')) {
          if (typeof window._ruiyi403Handler === 'function') {
            window._ruiyi403Handler();
            return;
          }
        }

        Swal.fire({
          icon: 'info',
          title: '<?php echo ruiyi_translate("Sistema actualizado", "System Updated", "系统已更新"); ?>',
          html: '<?php echo ruiyi_translate(
            "No se pudo cargar la información. El sistema puede haberse actualizado, por favor inicie sesión de nuevo.",
            "Could not load information. The system may have been updated, please log in again.",
            "无法加载信息，系统可能已更新，请重新登录。"
          ); ?>',
          confirmButtonText: '<?php echo ruiyi_translate("Iniciar sesión", "Log in", "重新登录"); ?>',
          confirmButtonColor: '#E84D25',
          allowOutsideClick: false,
          allowEscapeKey: false
        }).then(function() {
          window.location.href = '<?php echo home_url('/'); ?>';
        });

        // Try loading from IndexedDB as fallback
        console.warn('[PWA] Online fetch failed, trying offline cache:', error);
        getOfflineOrdersByTable(tableNumber).then(offlineOrders => {
          if (offlineOrders && offlineOrders.length > 0) {
            const orderData = convertOfflineOrderToOrderData(offlineOrders);
            sessionStorage.setItem('tableOrderData', JSON.stringify(orderData));
            sessionStorage.setItem('tableOrderDataOffline', 'true');
            
            const cajeroLink = document.querySelector('a[href="#cajero"]');
            if (cajeroLink) {
              document.querySelectorAll('main > section').forEach(section => {
                section.classList.add('hidden');
              });
              
              const cajeroSection = document.getElementById('cajero');
              if (cajeroSection) {
                cajeroSection.classList.remove('hidden');
              }
              
              document.querySelectorAll('.menu-link').forEach(link => {
                link.classList.remove('bg-red-600', 'text-white');
              });
              cajeroLink.classList.add('bg-red-600', 'text-white');
              
              loadTableOrderToCart(tableNumber, orderData);
              // 🔥 优化：updateAllButtonStates 已在 loadTableOrderToCart 内部调用，无需再次调用
            }

            Swal.close();

            Toastify({
              text: `💾 <?php echo ruiyi_translate('Cargado desde caché offline', 'Loaded from offline cache', '从离线缓存加载'); ?>`,
              duration: 2000,
              gravity: "top",
              position: "center",
              style: { background: "#6366f1" }
            }).showToast();
          } else {
            console.warn('[PWA] No offline orders found for table:', tableNumber);
          }
        }).catch(offlineError => {
          console.error('[PWA] Error loading offline orders:', offlineError);
        });
      });
    }
    
    // 加载桌位订单到购物车
    function loadTableOrderToCart(tableNumber, orderData) {
      // 🔥 检查是否还在查看同一桌位
      // 🔥🔥🔥 【2026-03-29 修复】当 _currentViewingTable 为 null（用户已离开桌位）时也跳过
      var resolvedLoad = typeof ruiyiSafeResolveGlobalTableNumber === 'function'
        ? ruiyiSafeResolveGlobalTableNumber(tableNumber)
        : resolveGlobalTableNumber(tableNumber);
      if (!window._currentViewingTable || resolvedLoad !== window._currentViewingTable) {
        console.warn('[loadTableOrderToCart] ⚠️ 桌位已切换或离开 (请求:' + resolvedLoad + ' 当前:' + window._currentViewingTable + ')，跳过');
        return;
      }
      // 清空当前购物车
      cart = [];
      window.cart = cart;

      // 设置桌号
      const cleanTableNumber = typeof ruiyiSafeResolveGlobalTableNumber === 'function'
        ? ruiyiSafeResolveGlobalTableNumber(tableNumber)
        : resolveGlobalTableNumber(tableNumber);
      if (typeof ruiyiSetCartTableIdentity === 'function') {
        ruiyiSetCartTableIdentity(cleanTableNumber, 'loadTableOrderToCart');
      }
      document.getElementById('table-number').value = cleanTableNumber;
      // 🔥 更新购物车上方的桌位号显示
      updateCurrentTableDisplay(cleanTableNumber);

      // 🔥 【关键修复】恢复折扣状态 - 使用多格式key查找
      const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
      const currentPrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
      const prefixes = ['Mesa', currentPrefix, 'Table', '餐桌'];
      const uniquePrefixes = [...new Set(prefixes)];

      let tableData = null;
      for (const prefix of uniquePrefixes) {
        const keyWithSpace = `${prefix} ${cleanTableNumber}`;
        const keyNoSpace = `${prefix}${cleanTableNumber}`;
        if (mesasEstado[keyWithSpace]) {
          tableData = mesasEstado[keyWithSpace];
          break;
        }
        if (mesasEstado[keyNoSpace]) {
          tableData = mesasEstado[keyNoSpace];
          break;
        }
      }

      if (tableData && tableData.discount > 0) {
        window.currentDiscountPercent = tableData.discount;
        // console.log(`[loadTableOrderToCart] 恢复折扣状态: ${tableData.discount}%`);
        // 延迟更新折扣标识，确保DOM已加载
        setTimeout(() => {
          if (typeof updateDiscountBadge === 'function') {
            updateDiscountBadge();
          } else if (typeof window.updateDiscountBadge === 'function') {
            window.updateDiscountBadge();
          }
        }, 100);
      } else {
        // 清除之前的折扣状态
        window.currentDiscountPercent = 0;
      }

      // 手动触发按钮更新，因为readonly输入框不会触发input事件
      const currentOrderType = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir';
      if (typeof updateOrderButtonForType === 'function') {
        updateOrderButtonForType(currentOrderType);
      }
      
      // 处理所有订单
      if (orderData.orders && Array.isArray(orderData.orders)) {
        orderData.orders.forEach(order => {
          // 处理每个订单的商品
          if (order.items && Array.isArray(order.items)) {
            order.items.forEach(item => {
              // API返回的字段映射
              const itemQuantity = parseInt(item.quantity) || 1;
              const itemTotal = parseFloat(item.total) || 0;

              // 🔥 使用订单中实际支付的价格（保留自定义价格）
              // 优先使用从订单总价计算的价格，这是用户实际支付的价格
              const calculatedPrice = itemQuantity > 0 ? (itemTotal / itemQuantity) : 0;
              const itemPrice = parseFloat(item.price) || calculatedPrice;
              const originalPrice = parseFloat(item.original_price) || 0;

              // 🔥 修复：对于锁定商品，始终使用订单中的实际价格
              // 如果原价存在且与实际支付价格不同，说明有自定义价格
              const hasCustomPrice = originalPrice > 0 && Math.abs(itemPrice - originalPrice) > 0.01;


              // 🔥🔥🔥 关键修复：查找是否已存在相同商品时，必须同时检查价格！
              // 同一产品不同价格应该作为不同的购物车项
              const existingItem = cart.find(cartItem =>
                cartItem.name === item.name &&
                cartItem.locked &&
                cartItem.orderId === order.id &&
                // 🔥 关键：价格必须相同（允许0.01的误差）
                Math.abs((cartItem.customPrice || cartItem.price) - itemPrice) < 0.01
              );

              if (existingItem) {
                // 如果存在相同订单的相同锁定商品且价格相同，增加数量
                existingItem.quantity += itemQuantity;
              } else {
                // 添加新商品到购物车（标记为锁定）
                const productId = item.product_id || Date.now() + Math.random();

                // 🔥🔥🔥 【2026-02-18 关键修复】恢复多语言名称字段
                // 优先从 item 数据中获取（localStorage 路径），否则从 DOM 产品卡片查找
                let itemNameEs = item.name_es || item.name || '未知商品';
                let itemNameZh = item.name_zh || '';
                let itemNameEn = item.name_en || '';

                if (!itemNameZh && !itemNameEn) {
                  // 从 DOM 中查找产品卡片，获取多语言名称
                  const productCard = document.querySelector(`.product-card[data-id="${productId}"]`);
                  if (productCard) {
                    itemNameEs = productCard.getAttribute('data-name-es') || itemNameEs;
                    itemNameZh = productCard.getAttribute('data-name-zh') || '';
                    itemNameEn = productCard.getAttribute('data-name-en') || '';
                  }
                }

                const cartItem = {
                  id: productId,
                  name: itemNameEs, // 🔥 使用西班牙语原名作为默认 name
                  name_es: itemNameEs, // 🔥 西班牙语名称
                  name_zh: itemNameZh, // 🔥 中文名称
                  name_en: itemNameEn, // 🔥 英文名称
                  price: originalPrice > 0 ? originalPrice : itemPrice, // 保存原价（如果有的话）
                  quantity: itemQuantity,
                  image_url: item.image_url || '/wp-content/themes/RUIYI_POS-Manager/assets/images/placeholder.png', // 使用占位符图片
                  locked: true,  // 标记为锁定（已下单）
                  original: true, // 标记为原始订单项
                  orderId: order.id, // 🔥 使用订单ID而不是订单号，用于精确删除
                  orderNumber: order.order_number || order.id, // 保留订单号用于显示
                  itemId: item.item_id, // 🔥 添加订单项ID，用于精确删除
                  // 🔥 修复：始终设置customPrice为订单中的实际价格（从订单总价计算）
                  customPrice: itemPrice,
                  // 🔥 【关键修复】保留折扣信息
                  hasDiscount: item.hasDiscount || false,
                  discountPercent: item.discountPercent || 0,
                  originalPrice: item.originalPrice || originalPrice || itemPrice,
                  // 🔥 产品分类IDs（用于配料筛选）
                  categoryIds: item.categoryIds || []
                };

                // 🔥🔥🔥 关键修复：如果有自定义名称，保存到购物车项
                if (item.hasCustomName && item.customName) {
                  cartItem.customName = item.customName;
                  if (item.originalProductName) {
                    cartItem.originalProductName = item.originalProductName;
                  }
                }

                // 🔥 恢复配料数据（从服务器order item meta）
                if (item.supplements) {
                  try {
                    const supData = typeof item.supplements === 'string' ? JSON.parse(item.supplements) : item.supplements;
                    if (Array.isArray(supData) && supData.length > 0) {
                      cartItem.supplements = supData;
                      cartItem._originalName = item._originalName || item.originalProductName || itemNameEs;
                      cartItem._originalPrice = item._originalPrice !== undefined && item._originalPrice !== null
                        ? parseFloat(item._originalPrice)
                        : (originalPrice > 0 ? originalPrice : itemPrice);
                    }
                  } catch(e) { console.warn('[loadTableOrderToCart] 配料数据解析失败:', e); }
                }

                cart.push(cartItem);
              }
            });
          }
        });
      }
      
      // 添加查看模式提示 - 仅在堂食模式下显示
      const orderTitle = document.getElementById('cart-order-title');
      if (orderTitle) {
        // 获取当前订单类型
        const currentOrderType = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir';

        if (currentOrderType === 'llevar') {
          // 外卖模式：不显示查看桌位标题
          orderTitle.innerHTML = '';
        } else {
          // 堂食模式：不再显示查看桌位标题，保持简洁
          orderTitle.innerHTML = '';
        }
      }

      // 🔥 【关键修复】如果有全局折扣，重新应用折扣到所有商品
      // 这解决了从服务器加载订单时折扣属性和价格丢失的问题
      if (window.currentDiscountPercent && window.currentDiscountPercent > 0) {
        const discountMultiplier = 1 - (window.currentDiscountPercent / 100);
        cart.forEach(item => {
          // 保存原价（如果还没有）
          if (!item.originalPrice) {
            item.originalPrice = item.price;
          }
          // 🔥 【关键】计算期望的折扣价格
          // 🔥 修复：使用 toFixed(2) 避免浮点数精度问题
          const expectedDiscountedPrice = parseFloat((item.originalPrice * discountMultiplier).toFixed(2));
          // 🔥 如果 customPrice 未设置或与期望值相差太大，重新计算
          // 允许小误差（0.01）以处理浮点数精度问题
          if (item.customPrice === undefined || Math.abs(item.customPrice - expectedDiscountedPrice) > 0.01) {
            item.customPrice = expectedDiscountedPrice;
          }
          item.hasDiscount = true;
          item.discountPercent = window.currentDiscountPercent;
        });
        // console.log(`[loadTableOrderToCart] 重新应用折扣: ${window.currentDiscountPercent}%, 商品数: ${cart.length}`);
      }

      // 渲染购物车
      renderCart();

      // 🔥 优化：立即更新按钮状态，无延迟
      if (typeof updateAllButtonStates === 'function') {
        updateAllButtonStates();
      }

      // 为退出查看模式按钮添加事件监听器（使用requestAnimationFrame而非setTimeout）
      requestAnimationFrame(() => {
        const exitViewModeBtn = document.getElementById('exit-view-mode-btn');
        if (exitViewModeBtn) {
          // 移除之前的监听器（如果存在）
          exitViewModeBtn.replaceWith(exitViewModeBtn.cloneNode(true));
          const newExitBtn = document.getElementById('exit-view-mode-btn');

          newExitBtn.addEventListener('click', function() {
            if (typeof exitViewMode === 'function') {
              exitViewMode();
            } else {
              console.error('exitViewMode函数未定义');
            }
          });
        }
      });

      // 🔥 已移除：订单加载提示消息（用户不需要）
      // Toastify({
      //   text: `订单来自 ${tableNumber} 已加载`,
      //   duration: 3000,
      //   gravity: "top",
      //   position: "center",
      //   style: { background: "#3b82f6" }
      // }).showToast();
    }
    
    // 🔥 静默重新加载桌位订单到购物车（不显示加载对话框，不切换section）
    // 🔥 关键修复：保留未锁定的商品，只更新锁定的商品
    // 🔥 防止并发重载
    var _reloadingSilently = false;

    function reloadTableOrderToCartSilently(tableNumber, deletedItem = null) {
      if (_reloadingSilently) {
        console.warn('[静默重新加载] ⚠️ 已有重载在进行中，跳过');
        return Promise.resolve(null);
      }
      // 🔥 检查是否还在查看同一桌位，防止加载错误桌位数据
      // 🔥🔥🔥 【2026-03-29 修复】当 _currentViewingTable 为 null（用户已离开桌位）时也跳过
      var resolvedReload = resolveGlobalTableNumber(tableNumber);
      if (!window._currentViewingTable || resolvedReload !== window._currentViewingTable) {
        console.warn('[静默重新加载] ⚠️ 桌位已切换或离开 (请求:' + resolvedReload + ' 当前:' + window._currentViewingTable + ')，跳过');
        return Promise.resolve(null);
      }
      _reloadingSilently = true;

      return new Promise((resolve, reject) => {
        // 🔥 保存当前购物车的完整状态（包括所有锁定和未锁定商品）
        const currentCartSnapshot = JSON.parse(JSON.stringify(cart));

        // 🔥 只保留真正新添加的未锁定商品（有 addedQuantity 且不是从服务器加载的）
        const unlockedItems = cart.filter(item => !item.locked && (item.addedQuantity || 0) > 0);
        
        // 🔥 关键修复：不要提前删除商品，等待服务器确认后再更新
        // 这样可以避免购物车变空
        
        // 获取桌位订单数据（静默，不显示加载对话框）
        // 🔥 确保tableNumber格式正确（提取数字部分）
        const cleanTableNumber = resolveGlobalTableNumber(tableNumber);
        
        fetch(ajaxUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            action: 'ruiyi_pos_get_table_orders',
            table_number: cleanTableNumber,
            nonce: ajaxNonce
          })
        })
        .then(response => {
          if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
          }
          return response.json();
        })
        .then(data => {
          
          if (data.success && data.data && data.data.orders && data.data.orders.length > 0) {
            // 保存订单数据到sessionStorage
            sessionStorage.setItem('tableOrderData', JSON.stringify(data.data));
            
            // 🔥 关键修复：先保存未锁定商品，然后重新构建购物车
            // 不清空购物车，而是替换锁定的商品部分
            const newLockedItems = [];
            
            // 🔥 重新加载锁定的商品（从服务器订单）
            // 处理所有订单
            if (data.data.orders && Array.isArray(data.data.orders)) {
              data.data.orders.forEach(order => {
                // 处理每个订单的商品
                if (order.items && Array.isArray(order.items)) {
                  order.items.forEach(item => {
                    // API返回的字段映射
                    const itemQuantity = parseInt(item.quantity) || 1;
                    const itemTotal = parseFloat(item.total) || 0;

                    // 🔥 使用订单中实际支付的价格（保留自定义价格）
                    const itemPrice = parseFloat(item.price) || (itemTotal / itemQuantity);
                    const originalPrice = parseFloat(item.original_price) || itemPrice;

                    // 检查是否为自定义价格（实际价格与原价不同）
                    const hasCustomPrice = Math.abs(itemPrice - originalPrice) > 0.01;

                    // 🔥🔥🔥 关键修复：检查是否已存在相同商品（同一订单、同名称、同价格）
                    // 只有三者都相同才合并数量，否则作为不同的购物车项
                    const existingItem = newLockedItems.find(cartItem =>
                      cartItem.name === item.name &&
                      cartItem.orderId === order.id &&
                      // 🔥 关键：价格必须相同（允许0.01的误差）
                      Math.abs((cartItem.customPrice || cartItem.price) - itemPrice) < 0.01
                    );

                    if (existingItem) {
                      // 相同订单、相同名称、相同价格的商品，合并数量
                      existingItem.quantity += itemQuantity;
                    } else {
                      // 添加锁定商品到新数组
                      const cartItem = {
                        id: item.product_id || Date.now() + Math.random(),
                        name: item.name || '未知商品',
                        name_es: item.name_es || item.name || '',
                        name_zh: item.name_zh || '',
                        name_en: item.name_en || '',
                        price: originalPrice, // 保存原价
                        quantity: itemQuantity,
                        image_url: item.image_url || '/wp-content/themes/RUIYI_POS-Manager/assets/images/placeholder.png',
                        locked: true,  // 标记为锁定（已下单）
                        original: true, // 标记为原始订单项
                        orderId: order.id, // 🔥 使用订单ID而不是订单号，用于精确删除
                        orderNumber: order.order_number || order.id, // 保留订单号用于显示
                        itemId: item.item_id, // 🔥 添加订单项ID，用于精确删除
                        categoryIds: item.categoryIds || [], // 🔥 产品分类IDs（配料筛选）
                        // 🔥 始终设置customPrice为订单中的实际价格
                        customPrice: itemPrice
                      };

                      // 🔥🔥🔥 关键修复：如果有自定义名称，保存到购物车项
                      if (item.hasCustomName && item.customName) {
                        cartItem.customName = item.customName;
                        if (item.originalProductName) {
                          cartItem.originalProductName = item.originalProductName;
                        }
                      }

                      // 🔥 恢复配料数据（从服务器）
                      if (item.supplements) {
                        try {
                          const supData = typeof item.supplements === 'string' ? JSON.parse(item.supplements) : item.supplements;
                          if (Array.isArray(supData) && supData.length > 0) {
                            cartItem.supplements = supData;
                            cartItem._originalName = item._originalName || item.originalProductName || item.name;
                            cartItem._originalPrice = item._originalPrice !== undefined && item._originalPrice !== null
                              ? parseFloat(item._originalPrice) : originalPrice;
                          }
                        } catch(e) {}
                      }

                      newLockedItems.push(cartItem);
                    }
                  });
                }
              });
            }

            // 🔥🔥🔥 关键修复：从当前购物车快照中恢复配料数据到新的锁定项
            // 服务器返回的数据不包含 supplements/_originalName/_originalPrice
            // 但当前购物车可能有用户刚添加的配料信息
            newLockedItems.forEach(newItem => {
              const snapshotItem = currentCartSnapshot.find(s =>
                s.locked && s.id === newItem.id && s.orderId === newItem.orderId &&
                (s.supplements && s.supplements.length > 0)
              );
              if (snapshotItem) {
                newItem.supplements = snapshotItem.supplements;
                newItem._originalName = snapshotItem._originalName;
                newItem._originalPrice = snapshotItem._originalPrice;
                newItem.categoryIds = snapshotItem.categoryIds;
                newItem.notes = snapshotItem.notes || newItem.notes;
                console.log('[reloadSilently] 🔄 恢复配料数据:', newItem.name, 'supplements:', newItem.supplements.length);
              }
              // 🔥 恢复 categoryIds（即使没有配料）
              if (!newItem.categoryIds) {
                const catSnapshot = currentCartSnapshot.find(s => s.locked && s.id === newItem.id && s.categoryIds);
                if (catSnapshot) newItem.categoryIds = catSnapshot.categoryIds;
              }
              // 🔥 恢复多语言名称
              if (!newItem.name_zh || !newItem.name_es) {
                const langSnapshot = currentCartSnapshot.find(s => s.id === newItem.id && (s.name_zh || s.name_es));
                if (langSnapshot) {
                  newItem.name_zh = newItem.name_zh || langSnapshot.name_zh || '';
                  newItem.name_es = newItem.name_es || langSnapshot.name_es || '';
                  newItem.name_en = newItem.name_en || langSnapshot.name_en || '';
                }
              }
            });

            // 🔥 关键修复：合并时去重 — 未锁定商品如果已存在于锁定列表中则跳过
            const deduplicatedUnlocked = unlockedItems.filter(u => {
              return !newLockedItems.some(l => l.id === u.id && Math.abs((l.customPrice || l.price) - (u.customPrice || u.price)) < 0.01);
            });
            cart = [...deduplicatedUnlocked, ...newLockedItems];
            window.cart = cart;
            if (typeof ruiyiSetCartTableIdentity === 'function') {
              ruiyiSetCartTableIdentity(cleanTableNumber, 'reloadTableOrderToCartSilently:server');
            }

            // 🔥 渲染购物车
            renderCart();

            // 🔥 验证：确保购物车不为空
            if (cart.length === 0 && (unlockedItems.length > 0 || newLockedItems.length > 0)) {
              console.error('[静默重新加载] ⚠️ 警告：购物车意外为空！恢复快照');
              cart = currentCartSnapshot;
              window.cart = cart;
              if (typeof ruiyiSetCartTableIdentity === 'function') {
                ruiyiSetCartTableIdentity(cleanTableNumber, 'reloadTableOrderToCartSilently:restore-empty');
              }
              renderCart();
            }

            _reloadingSilently = false;
            resolve(data.data);
          } else {
            // 没有订单返回
            // 🔥 关键修复：检查是否是刚同步的桌位，如果是则保留原始购物车
            const mesaKey = `Mesa ${cleanTableNumber}`;
            const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
            const recentSync = window._recentlySyncedTables?.[mesaKey];
            const mesaData = mesasEstado[mesaKey];
            // 🔥🔥🔥 关键修复：将保护窗口从10秒延长到20秒
            // 适应WiFi/4G网络环境下的同步延迟
            const wasJustSynced = recentSync || (mesaData?._justSynced && (Date.now() - (mesaData._syncTimestamp || 0)) < 20000);

            if (wasJustSynced) {
                console.log('[静默重新加载] 🛡️ 桌位刚刚同步完成，保留原始购物车数据');
                // 如果有同步时保存的cart数据，使用它
                if (mesaData?.cart && Array.isArray(mesaData.cart) && mesaData.cart.length > 0) {
                    // 将本地cart数据转换为购物车格式
                    cart = mesaData.cart.map(item => ({
                        ...item,
                        locked: true,
                        original: true,
                        orderId: mesaData.orderId
                    }));
                    window.cart = cart;
                    if (typeof ruiyiSetCartTableIdentity === 'function') {
                      ruiyiSetCartTableIdentity(cleanTableNumber, 'reloadTableOrderToCartSilently:local-cache');
                    }
                    renderCart();
                    console.log('[静默重新加载] ✅ 已从本地状态恢复购物车，商品数:', cart.length);
                    resolve({ orders: [], fromLocalCache: true });
                    return;
                } else if (recentSync?.cart && Array.isArray(recentSync.cart)) {
                    // 使用全局保护中的cart
                    cart = recentSync.cart.map(item => ({
                        ...item,
                        locked: true,
                        original: true,
                        orderId: recentSync.orderId
                    }));
                    window.cart = cart;
                    if (typeof ruiyiSetCartTableIdentity === 'function') {
                      ruiyiSetCartTableIdentity(cleanTableNumber, 'reloadTableOrderToCartSilently:recent-sync');
                    }
                    renderCart();
                    console.log('[静默重新加载] ✅ 已从同步缓存恢复购物车，商品数:', cart.length);
                    resolve({ orders: [], fromLocalCache: true });
                    return;
                } else if (currentCartSnapshot.length > 0) {
                    // 恢复快照
                    cart = currentCartSnapshot;
                    window.cart = cart;
                    if (typeof ruiyiSetCartTableIdentity === 'function') {
                      ruiyiSetCartTableIdentity(cleanTableNumber, 'reloadTableOrderToCartSilently:snapshot');
                    }
                    renderCart();
                    console.log('[静默重新加载] ✅ 已从快照恢复购物车，商品数:', cart.length);
                    resolve({ orders: [], fromLocalCache: true });
                    return;
                }
            }

            // 不是刚同步的情况，正常处理
            // 🔥 如果没有订单，但之前有锁定商品，说明可能被删除了，只保留未锁定商品
            cart = unlockedItems;
            window.cart = cart;
            if (typeof ruiyiSetCartTableIdentity === 'function') {
              ruiyiSetCartTableIdentity(cleanTableNumber, 'reloadTableOrderToCartSilently:unlocked-only');
            }
            renderCart();

            // 🔥 如果购物车为空但之前有商品，记录警告
            if (cart.length === 0 && currentCartSnapshot.length > 0) {
              console.warn('[静默重新加载] ⚠️ 购物车变空，但之前有', currentCartSnapshot.length, '个商品');
            }

            _reloadingSilently = false;
            reject(new Error('No orders found'));
          }
        })
        .catch(error => {
          _reloadingSilently = false;
          console.error('[静默重新加载] 加载订单失败:', error);
          // 🔥 关键修复：如果重新加载失败，恢复购物车快照（不丢失数据）
          if (deletedItem) {
            const restoredCart = currentCartSnapshot.filter(cartItem =>
              !(cartItem.locked &&
                cartItem.orderId === deletedItem.orderId &&
                cartItem.itemId === deletedItem.itemId)
            );
            cart = restoredCart;
          } else {
            cart = currentCartSnapshot;
          }
          window.cart = cart;
          if (typeof ruiyiSetCartTableIdentity === 'function') {
            ruiyiSetCartTableIdentity(cleanTableNumber, 'reloadTableOrderToCartSilently:catch-restore');
          }
          renderCart();
          reject(error);
        });
      });
    }

    // 餐桌分类管理功能
    let currentCategoryFilter = 'all';
    let tableCategoryMappings = {};
    window.tableCategoryMappings = tableCategoryMappings; // 设置为全局变量供厨房打印使用
    
    // 加载餐桌分类
    function loadTableCategories() {
      // 使用Promise.all并行加载分类和映射
      Promise.all([
        // 加载分类
        fetch(ajaxUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            action: 'ruiyi_get_table_categories',
            nonce: ajaxNonce
          })
        }).then(r => r.json()),
        
        // 加载映射
        fetch(ajaxUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            action: 'ruiyi_get_table_mappings',
            nonce: ajaxNonce
          })
        }).then(r => r.json())
      ])
      .then(([categoriesData, mappingsData]) => {

        // 🔥 初始化 delivery 相关的全局变量
        const tableCategoriesById = {};
        const deliveryEnabledCategoryIds = new Set();

        // 处理分类数据
        if (categoriesData.success && categoriesData.data.categories) {
          renderCategoryButtons(categoriesData.data.categories);

          // 🔥 构建分类ID映射和delivery启用列表
          categoriesData.data.categories.forEach(category => {
            if (!category || !category.id) {
              return;
            }
            const numericId = parseInt(category.id, 10);
            if (isNaN(numericId)) {
              return;
            }
            tableCategoriesById[numericId] = category;
            const deliveryFlag = category.delivery_enabled === true || parseInt(category.delivery_enabled, 10) === 1;
            if (deliveryFlag) {
              deliveryEnabledCategoryIds.add(numericId);
            }
          });

          window.tableCategoriesById = tableCategoriesById;
          window.deliveryEnabledCategoryIds = deliveryEnabledCategoryIds;
        } else {
          console.error('Category data loading failed:', categoriesData);
        }

        // 处理映射数据
        if (mappingsData.success && mappingsData.data.mappings) {
          tableCategoryMappings = mappingsData.data.mappings;

          // 🔥 为每个映射添加 delivery_enabled 标志
          const mappingsArray = Array.isArray(tableCategoryMappings)
            ? tableCategoryMappings
            : Object.values(tableCategoryMappings || {});

          mappingsArray.forEach(mapping => {
            if (!mapping) return;
            const categoryId = parseInt(mapping.category_id, 10);
            const deliveryEnabled = !isNaN(categoryId) && deliveryEnabledCategoryIds.has(categoryId);
            mapping.delivery_enabled = deliveryEnabled ? 1 : 0;
          });

          window.tableCategoryMappings = tableCategoryMappings; // 同步到全局变量
        } else {
          console.error('Mapping data loading failed:', mappingsData);
        }
      })
      .catch(error => console.error('Error loading categories/mappings:', error));
    }
    
    // 加载餐桌分类映射（保留作为独立函数，但主要通过loadTableCategories调用）
    function loadTableMappings() {
      fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          action: 'ruiyi_get_table_mappings',
          nonce: ajaxNonce
        })
      })
      .then(response => response.json())
      .then(data => {
        if (data.success && data.data.mappings) {
          tableCategoryMappings = data.data.mappings;
          // 重新渲染餐桌以应用分类过滤
          if (currentCategoryFilter !== 'all') {
            renderizarMesas('category-loaded');
          }
        }
      })
      .catch(error => console.error('Error loading table mappings:', error));
    }

    // ========================================
    // 🔥 Delivery 外送功能相关函数
    // ========================================

    // Delivery 客户数据存储（使用 sessionStorage 持久化）
    const DELIVERY_STORAGE_KEY = 'ruiyi_delivery_customer_data';

    // 🔥 PWA: Get cached customers from IndexedDB
    async function getCachedCustomers() {
      try {
        if (typeof posDB !== 'undefined' && posDB && typeof posDB.getCustomers === 'function') {
          if (!posDB.db && typeof posDB.init === 'function') {
            await posDB.init();
          }
          if (posDB.db) {
            const customers = await posDB.getCustomers();
            return customers || [];
          }
        }
        
        // Fallback: direct IndexedDB access
        // 🔥 如果 IndexedDB 已标记为损坏，返回空
        if (window._indexedDBBroken) return [];
        return new Promise((resolve, reject) => {
          const request = indexedDB.open('RUIYI_POS_DB', 2); // Use version 2 to match other functions
          request.onerror = () => {
            console.error('[PWA] IndexedDB open error:', request.error);
            window._indexedDBBroken = true; // 🔥 标记损坏
            reject(request.error);
          };
          request.onupgradeneeded = (event) => {
            const db = event.target.result;
            if (!db.objectStoreNames.contains('customers')) {
              const store = db.createObjectStore('customers', { keyPath: 'id' });
              store.createIndex('email', 'email', { unique: false });
            }
          };
          request.onsuccess = () => {
            const db = request.result;
            
            // Check if store exists
            if (!db.objectStoreNames.contains('customers')) {
              console.warn('[PWA] customers store does not exist');
              resolve([]);
              return;
            }
            
            const tx = db.transaction(['customers'], 'readonly');
            const store = tx.objectStore('customers');
            const getReq = store.getAll();
            getReq.onsuccess = () => {
              const customers = getReq.result || [];
              resolve(customers);
            };
            getReq.onerror = () => {
              console.error('[PWA] Error getting customers:', getReq.error);
              reject(getReq.error);
            };
          };
        });
      } catch (error) {
        console.error('[PWA] Error getting cached customers:', error);
        return [];
      }
    }

    // 🔥 PWA: Search cached customers
    async function searchCachedCustomers(searchType, searchTerm) {
      try {
        const allCustomers = await getCachedCustomers();
        
        if (!allCustomers || allCustomers.length === 0) {
          console.warn('[PWA] No cached customers found');
          return [];
        }

        const searchLower = searchTerm.toLowerCase().trim();
        const results = [];

        for (const customer of allCustomers) {
          let matches = false;

          if (searchType === 'phone') {
            // Normalize phone numbers: remove spaces, dashes, parentheses, plus signs
            const customerPhone = (customer.phone || '').toString().replace(/[\s\-\(\)\+]/g, '').toLowerCase();
            const searchPhone = searchLower.replace(/[\s\-\(\)\+]/g, '');
            // Try both exact match and contains match
            matches = customerPhone === searchPhone || customerPhone.includes(searchPhone) || customerPhone.endsWith(searchPhone);
            if (matches) {
            }
          } else if (searchType === 'address') {
            const address = (customer.address || '').toString().toLowerCase();
            matches = address.includes(searchLower);
          }

          if (matches) {
            results.push({
              id: customer.id,
              name: customer.name || '',
              phone: customer.phone || '',
              email: customer.email || '',
              business_name: customer.business_name || '',
              cif_nif: customer.cif_nif || '',
              address: customer.address || '',
              postal_code: customer.postal_code || ''
            });
          }

          if (results.length >= 8) break;
        }

        return results;
      } catch (error) {
        console.error('[PWA] Error searching cached customers:', error);
        return [];
      }
    }

    // 🔥 PWA: Load and cache customers function
    async function loadAndCacheCustomers() {
      if (!navigator.onLine || window.RUIYI_POS?.isOnline === false) {
        return;
      }

      try {
        var ajaxUrl = window.ajaxUrl || window.RUIYI_POS?.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
        const nonce = window.RUIYI_POS?.nonce || '<?php echo esc_js(wp_create_nonce('ruiyi_pos_nonce')); ?>';
        
        if (!nonce) {
          console.warn('[PWA] No nonce available');
          return;
        }

        const formData = new FormData();
        formData.append('action', 'ruiyi_pos_get_customers');
        formData.append('nonce', nonce);

        const response = await fetch(ajaxUrl, {
          method: 'POST',
          body: formData,
        });

        if (!response.ok) {
          const errorText = await response.text();
          console.error('[PWA] HTTP error response:', errorText);
          throw new Error(`HTTP ${response.status}: ${errorText.substring(0, 200)}`);
        }

        const result = await response.json();

        if (result.success && result.data) {
          // Handle nested data structure: result.data.data or result.data
          let customers = [];
          if (Array.isArray(result.data)) {
            customers = result.data;
          } else if (result.data && Array.isArray(result.data.data)) {
            customers = result.data.data;
          } else if (result.data && typeof result.data === 'object') {
            // Try to find array in the object
            customers = result.data.data || result.data.customers || [];
          }
          
          
          if (customers.length > 0) {
            // Try posDB first
            if (typeof posDB !== 'undefined' && posDB) {
              if (!posDB.db && typeof posDB.init === 'function') {
                await posDB.init();
              }
              if (posDB.db && typeof posDB.cacheCustomers === 'function') {
                await posDB.cacheCustomers(customers);
                return;
              }
            }
            
            // Fallback: direct IndexedDB - 不指定版本号，使用现有版本
            // 🔥 如果 IndexedDB 已标记为损坏，跳过
            if (window._indexedDBBroken) return;
            const request = indexedDB.open('RUIYI_POS_DB');
            await new Promise((resolve, reject) => {
              request.onerror = () => {
                console.warn('[PWA] IndexedDB error, skipping customer cache:', request.error);
                window._indexedDBBroken = true; // 🔥 标记损坏，防止后续重试
                resolve(); // 不抛出错误，静默失败
              };
              request.onsuccess = () => {
                const db = request.result;
                // 检查 customers store 是否存在
                if (!db.objectStoreNames.contains('customers')) {
                  console.warn('[PWA] customers store not found, skipping cache');
                  db.close();
                  resolve();
                  return;
                }
                try {
                  const tx = db.transaction(['customers'], 'readwrite');
                  const store = tx.objectStore('customers');
                  store.clear().onsuccess = () => {
                    customers.forEach(c => store.put(c));
                  };
                  tx.oncomplete = () => {
                    db.close();
                    resolve();
                  };
                  tx.onerror = () => {
                    console.warn('[PWA] Transaction error:', tx.error);
                    db.close();
                    resolve();
                  };
                } catch (e) {
                  console.warn('[PWA] Error accessing customers store:', e);
                  db.close();
                  resolve();
                }
              };
            });
          } else {
            console.warn('[PWA] No customers returned from server');
          }
        } else {
          console.warn('[PWA] Failed to get customers:', result.message);
        }
      } catch (error) {
        console.error('[PWA] Error caching customers:', error);
      }
    }

    // Make functions globally available
    window.getCachedCustomers = getCachedCustomers;
    window.searchCachedCustomers = searchCachedCustomers;
    window.loadAndCacheCustomers = loadAndCacheCustomers;

    // 从 sessionStorage 加载已存储的客户数据
    function loadDeliveryCustomerDataFromStorage() {
      try {
        // 🔥 优先从 localStorage 加载（持久化），兼容旧的 sessionStorage 数据
        const stored = localStorage.getItem(DELIVERY_STORAGE_KEY);
        if (stored) {
          return JSON.parse(stored);
        }
        // 兼容：如果 localStorage 没有，尝试从旧的 sessionStorage 迁移
        const oldStored = sessionStorage.getItem(DELIVERY_STORAGE_KEY);
        if (oldStored) {
          const data = JSON.parse(oldStored);
          localStorage.setItem(DELIVERY_STORAGE_KEY, oldStored);
          sessionStorage.removeItem(DELIVERY_STORAGE_KEY);
          return data;
        }
      } catch (e) {
        console.warn('[Delivery] 加载客户数据失败:', e);
      }
      return {};
    }

    // 🔥 保存客户数据到 localStorage（持久化，刷新后保留）
    function saveDeliveryCustomerDataToStorage(data) {
      try {
        localStorage.setItem(DELIVERY_STORAGE_KEY, JSON.stringify(data));
      } catch (e) {
        console.warn('[Delivery] 保存客户数据到 localStorage 失败:', e);
      }
    }

    // 初始化时从 localStorage 加载数据
    let deliveryCustomerDataStore = loadDeliveryCustomerDataFromStorage();

    // 辅助函数：HTML转义
    function escapeHtml(text) {
      if (!text) return '';
      return String(text)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
    }

    function normalizeTableIdentifier(tableName) {
      return String(tableName || '').trim().replace(/\s+/g, '').toUpperCase();
    }

    function getAllTableMappings() {
      if (Array.isArray(tableCategoryMappings)) {
        return tableCategoryMappings;
      }
      return Object.values(tableCategoryMappings || {});
    }

    function resolveMappedGlobalTableNumber(tableName) {
      const rawName = String(tableName || '').trim();
      if (!rawName) return '';

      const canonicalMatch = rawName.match(/^(?:Mesa|餐桌|Table)\s*(\d+)$/i);
      if (canonicalMatch) {
        return canonicalMatch[1];
      }

      const normalizedInput = normalizeTableIdentifier(rawName);
      const mappingsSource = getAllTableMappings();

      for (const mapping of mappingsSource) {
        const globalTableNumber = mapping?.global_table_number;
        if (globalTableNumber === undefined || globalTableNumber === null || globalTableNumber === '') {
          continue;
        }

        const candidates = [
          mapping.category_display_name,
          mapping.display_name,
          mapping.table_name,
          mapping.table_display_name
        ].filter(Boolean);

        if (candidates.some(candidate => normalizeTableIdentifier(candidate) === normalizedInput)) {
          return String(globalTableNumber);
        }
      }

      if (/^\d+$/.test(rawName)) {
        return rawName;
      }

      return '';
    }

    // 从桌位名称中提取全局编号
    function extractGlobalTableNumber(tableName) {
      const resolvedNumber = resolveMappedGlobalTableNumber(tableName);
      if (resolvedNumber !== '') {
        const mappedNumber = parseInt(resolvedNumber, 10);
        return isNaN(mappedNumber) ? null : mappedNumber;
      }

      if (!tableName) return null;
      const match = String(tableName).match(/\d+/);
      if (!match) return null;
      const number = parseInt(match[0], 10);
      return isNaN(number) ? null : number;
    }

    function isGenericTableIdentifier(tableName) {
      const rawName = String(tableName || '').trim();
      if (!rawName) return false;
      if (/^\d+$/.test(rawName)) return true;
      return /^(?:Mesa|餐桌|Table)\s*\d+$/i.test(rawName);
    }

    function getDeliveryStorageKeys(tableName) {
      const rawName = String(tableName || '').trim();
      if (!rawName) return [];

      const keys = [];
      const normalizedName = normalizeTableIdentifier(rawName);
      const mappedGlobalNumber = resolveMappedGlobalTableNumber(rawName);

      if (mappedGlobalNumber !== '') {
        keys.push(`table_${mappedGlobalNumber}`);
      }

      if (normalizedName) {
        keys.push(`table_name_${normalizedName}`);
      }

      // 兼容旧版仅按数字存储的键，但只对纯数字/标准 Mesa X 这种不歧义输入开放回退。
      if (isGenericTableIdentifier(rawName)) {
        const legacyNumber = extractGlobalTableNumber(rawName);
        if (legacyNumber !== null) {
          keys.push(`table_${legacyNumber}`);
        }
      }

      return Array.from(new Set(keys.filter(Boolean)));
    }

    // 获取 delivery 数据的主存储键
    function getDeliveryStorageKey(tableName) {
      const keys = getDeliveryStorageKeys(tableName);
      return keys[0] || '';
    }

    // 通过桌位名称获取桌位映射
    function getTableMappingByTableName(tableName) {
      const globalNumber = extractGlobalTableNumber(tableName);
      if (globalNumber === null) return null;
      const normalizedInput = normalizeTableIdentifier(tableName);
      const mappingsSource = getAllTableMappings();

      const exactMatch = mappingsSource.find(mapping => {
        const candidates = [
          mapping.category_display_name,
          mapping.display_name,
          mapping.table_name,
          mapping.table_display_name
        ].filter(Boolean);
        return candidates.some(candidate => normalizeTableIdentifier(candidate) === normalizedInput);
      });

      if (exactMatch) {
        return exactMatch;
      }

      return mappingsSource.find(mapping => parseInt(mapping.global_table_number, 10) === globalNumber) || null;
    }

    // 通过分类ID获取分类信息
    function getCategoryInfoById(categoryId) {
      if (categoryId === null || categoryId === undefined) return null;
      const id = parseInt(categoryId, 10);
      if (isNaN(id)) return null;
      return window.tableCategoriesById ? window.tableCategoriesById[id] : null;
    }

    // 判断桌位是否需要 delivery 信息
    function isDeliveryZoneTable(tableName) {
      const mapping = getTableMappingByTableName(tableName);
      if (!mapping) return false;
      if (mapping.delivery_enabled !== undefined) {
        return !!parseInt(mapping.delivery_enabled, 10);
      }
      const categoryId = parseInt(mapping.category_id, 10);
      if (isNaN(categoryId)) {
        return false;
      }
      return window.deliveryEnabledCategoryIds ? window.deliveryEnabledCategoryIds.has(categoryId) : false;
    }

    // 🔥 判断桌位所在分区是否应跳过厨房打印（可在设置中配置）
    function shouldSkipKitchenPrintForTable(tableName) {
      const skipZones = window.clodopConfig?.kitchenSkipZoneCategories;
      if (!skipZones || !Array.isArray(skipZones) || skipZones.length === 0) {
        return false;
      }
      const mapping = getTableMappingByTableName(tableName);
      if (!mapping) return false;
      const categoryId = parseInt(mapping.category_id, 10);
      if (isNaN(categoryId)) return false;
      return skipZones.includes(categoryId);
    }

    // 获取桌位所在区域的显示名称
    function getZoneDisplayNameForTable(tableName) {
      const mapping = getTableMappingByTableName(tableName);
      if (!mapping) return '';
      const category = getCategoryInfoById(mapping.category_id);
      if (category) {
        if (category.display_name) return category.display_name;
        return category.name_es || category.name_en || category.name || '';
      }
      return mapping.category_display_name || '';
    }

    // 获取桌位的 delivery 客户数据
    function getDeliveryCustomerData(tableName) {
      const keys = getDeliveryStorageKeys(tableName);
      const primaryKey = keys[0] || '';

      for (const key of keys) {
        const data = deliveryCustomerDataStore[key] || null;
        if (data) {
          if (primaryKey && key !== primaryKey && !deliveryCustomerDataStore[primaryKey]) {
            deliveryCustomerDataStore[primaryKey] = {
              ...data,
              migratedFrom: key,
              updatedAt: data.updatedAt || new Date().toISOString()
            };
            saveDeliveryCustomerDataToStorage(deliveryCustomerDataStore);
          }
          return data;
        }
      }

      return null;
    }

    // 设置桌位的 delivery 客户数据
    function setDeliveryCustomerData(tableName, data) {
      const key = getDeliveryStorageKey(tableName);
      if (!key) return;
      deliveryCustomerDataStore[key] = {
        ...data,
        updatedAt: new Date().toISOString()
      };
     // 🔥 同步保存到 sessionStorage
      saveDeliveryCustomerDataToStorage(deliveryCustomerDataStore);
    }

    // 🔥 暴露到全局，供 fetchAndUpdateTableStatuses 跨 script 块使用
    window.setDeliveryCustomerData = setDeliveryCustomerData;
    window.getDeliveryCustomerData = getDeliveryCustomerData;

    // 清除桌位的 delivery 客户数据
    function clearDeliveryCustomerData(tableName) {
      if (!tableName) return;
      let changed = false;
      const keys = getDeliveryStorageKeys(tableName);
      keys.forEach(key => {
        if (deliveryCustomerDataStore[key]) {
          delete deliveryCustomerDataStore[key];
          changed = true;
        }
      });
      if (changed) {
        saveDeliveryCustomerDataToStorage(deliveryCustomerDataStore);
      }
    }

    // 🔥🔥🔥 【2026-01-31 新增】编辑外送桌位的客户地址
    async function editDeliveryAddress() {
      // 获取当前桌位号
      const tableInput = document.getElementById('table-number');
      const currentTable = tableInput?.value || '';

      if (!currentTable) {
        Toastify({
          text: '❌ <?php echo ruiyi_translate("No hay mesa seleccionada", "No table selected", "未选择桌位"); ?>',
          duration: 2000,
          gravity: 'top',
          position: 'center',
          style: { background: '#ef4444' }
        }).showToast();
        return;
      }

      // 获取当前客户数据
      const customerData = getDeliveryCustomerData(currentTable) || {};
      const currentAddress = customerData.address || '';
      const customerPhone = customerData.phone || '';

      // 显示编辑弹窗
      const { value: newAddress, isConfirmed } = await Swal.fire({
        title: '<?php echo ruiyi_translate("Editar dirección", "Edit address", "修改地址"); ?>',
        input: 'textarea',
        inputValue: currentAddress,
        inputPlaceholder: '<?php echo ruiyi_translate("Ingrese la nueva dirección", "Enter the new address", "请输入新地址"); ?>',
        showCancelButton: true,
        confirmButtonText: '<?php echo ruiyi_translate("Guardar", "Save", "保存"); ?>',
        cancelButtonText: '<?php echo ruiyi_translate("Cancelar", "Cancel", "取消"); ?>',
        confirmButtonColor: '#3b82f6',
        inputAttributes: {
          rows: 3
        },
        customClass: {
          input: 'text-sm'
        },
        preConfirm: (value) => {
          if (!value || !value.trim()) {
            Swal.showValidationMessage('<?php echo ruiyi_translate("La dirección no puede estar vacía", "Address cannot be empty", "地址不能为空"); ?>');
            return false;
          }
          return value.trim();
        }
      });

      if (!isConfirmed || !newAddress) return;

      // 如果地址没有变化，直接返回
      if (newAddress === currentAddress) {
        Toastify({
          text: '<?php echo ruiyi_translate("La dirección no ha cambiado", "Address has not changed", "地址未更改"); ?>',
          duration: 1500,
          gravity: 'top',
          position: 'center',
          style: { background: '#6b7280' }
        }).showToast();
        return;
      }

      // 更新本地存储
      const updatedCustomerData = {
        ...customerData,
        address: newAddress
      };
      setDeliveryCustomerData(currentTable, updatedCustomerData);

      // 更新显示
      const addressDisplay = document.getElementById('delivery-display-address');
      if (addressDisplay) {
        addressDisplay.textContent = newAddress;
      }

      // 如果有电话号码，同步更新数据库中的客户地址
      if (customerPhone) {
        try {
          const ajaxUrl = window.ajaxUrl || '<?php echo admin_url("admin-ajax.php"); ?>';
          const ajaxNonce = window.RUIYI_POS?.nonce || posNonce;

          const response = await fetch(ajaxUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams({
              action: 'ruiyi_update_customer_address',
              phone: customerPhone,
              address: newAddress,
              nonce: ajaxNonce
            })
          });

          const result = await response.json();

          if (result.success) {
            Toastify({
              text: '✅ <?php echo ruiyi_translate("Dirección actualizada", "Address updated", "地址已更新"); ?>',
              duration: 2000,
              gravity: 'top',
              position: 'center',
              style: { background: '#10b981' }
            }).showToast();
          } else {
            // 本地已更新，服务器更新失败只显示警告
            console.warn('[编辑地址] 服务器更新失败:', result.data?.message || result.message);
            Toastify({
              text: '⚠️ <?php echo ruiyi_translate("Dirección local actualizada, sincronización pendiente", "Local address updated, sync pending", "本地地址已更新，同步待处理"); ?>',
              duration: 2000,
              gravity: 'top',
              position: 'center',
              style: { background: '#f59e0b' }
            }).showToast();
          }
        } catch (error) {
          console.error('[编辑地址] 服务器请求失败:', error);
          Toastify({
            text: '⚠️ <?php echo ruiyi_translate("Dirección local actualizada, sincronización pendiente", "Local address updated, sync pending", "本地地址已更新，同步待处理"); ?>',
            duration: 2000,
            gravity: 'top',
            position: 'center',
            style: { background: '#f59e0b' }
          }).showToast();
        }
      } else {
        // 没有电话号码，只更新本地
        Toastify({
          text: '✅ <?php echo ruiyi_translate("Dirección actualizada", "Address updated", "地址已更新"); ?>',
          duration: 2000,
          gravity: 'top',
          position: 'center',
          style: { background: '#10b981' }
        }).showToast();
      }
    }

    // 创建客户信息记录
    async function createCustomerInfoRecord(customerData) {
      var ajaxUrl = window.ajaxUrl || '<?php echo admin_url('admin-ajax.php'); ?>';
      var ajaxNonce = window.RUIYI_POS?.nonce || posNonce;

      try {
        const payload = new URLSearchParams({
          action: 'ruiyi_create_customer_info',
          nonce: ajaxNonce,
          name: customerData.name || '',
          phone: customerData.phone || '',
          business_name: customerData.business_name || '',
          cif_nif: customerData.cif_nif || '',
          address: customerData.address || '',
          postal_code: customerData.postal_code || '',
          email: customerData.email || ''
        });

        const response = await fetch(ajaxUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: payload
        });

        if (!response.ok) {
          throw new Error(`HTTP ${response.status}`);
        }

        const result = await response.json();
        if (!result.success) {
          throw new Error((result.data && result.data.message) || result.message || 'Error');
        }

        return { success: true, data: result.data };
      } catch (error) {
        console.error('[DeliveryInfo] 保存客户信息失败:', error);
        return { success: false, message: error.message || 'Error' };
      }
    }

