              <input id="delivery-customer-cif-nif" type="text" class="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" value="${escapeHtml(existingData.cif_nif || '')}" placeholder="<?php echo ruiyi_translate('Opcional - para factura', 'Optional - for invoice', '可选 - 用于发票'); ?>">
            </div>
            <div class="col-span-2">
              <label class="block text-sm font-medium text-gray-700 mb-1"><?php echo ruiyi_translate('Dirección de entrega *', 'Delivery address *', '配送地址 *'); ?></label>
              <div class="autocomplete-wrapper">
                <textarea id="delivery-customer-address" class="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" rows="2" required placeholder="<?php echo ruiyi_translate('Requerido', 'Required', '必填'); ?>" autocomplete="off">${currentAddress}</textarea>
                <div id="address-autocomplete-dropdown" class="autocomplete-dropdown"></div>
              </div>
            </div>
            <!-- 隐藏邮政编码和邮箱字段 -->
            <input type="hidden" id="delivery-customer-postal" value="${escapeHtml(existingData.postal_code || '')}">
            <input type="hidden" id="delivery-customer-email" value="${escapeHtml(existingData.email || '')}">
            <div class="col-span-2">
              <label class="block text-sm font-medium text-gray-700 mb-1"><?php echo ruiyi_translate('Notas', 'Notes', '客户备注'); ?></label>
              <textarea id="delivery-customer-notes" class="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" rows="2" placeholder="<?php echo ruiyi_translate('Notas adicionales (opcional)', 'Additional notes (optional)', '附加备注（可选）'); ?>">${escapeHtml(existingData.notes || '')}</textarea>
            </div>
          </div>
        </div>
      `;

      const result = await Swal.fire({
        title: '',
        html: htmlContent,
        focusConfirm: false,
        showCancelButton: true,
        showDenyButton: false,
        showLoaderOnConfirm: true,
        confirmButtonText: `<?php echo ruiyi_translate('Guardar y continuar', 'Save and continue', '保存并继续'); ?>`,
        cancelButtonText: `<?php echo ruiyi_translate('Cancelar', 'Cancel', '取消'); ?>`,
        width: window.innerWidth < 768 ? '95%' : '600px',
        customClass: {
          popup: 'delivery-customer-modal'
        },
        preConfirm: async () => {
          const extracted = extractDeliveryFormValues();
          if (!extracted) {
            Swal.showValidationMessage(`<?php echo ruiyi_translate('Error interno del formulario', 'Internal form error', '表单错误'); ?>`);
            return false;
          }

          const { values, inputs } = extracted;

          // 🔥 验证必填字段
          if (!values.phone || !values.address) {
            Swal.showValidationMessage(`<?php echo ruiyi_translate('Por favor complete el teléfono y la dirección', 'Please enter phone and address', '请填写电话和地址'); ?>`);
            if (!values.phone) {
              inputs.phoneInput?.focus();
            } else if (!values.address) {
              inputs.addressInput?.focus();
            }
            return false;
          }

          // 🔥 如果有电话号码，检查是否存在，不存在则创建
          if (values.phone) {
            try {
              // 1. 先检查客户是否已存在
              const checkResponse = await fetch(window.ajaxUrl || '<?php echo admin_url('admin-ajax.php'); ?>', {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: new URLSearchParams({
                  action: 'ruiyi_find_customer_by_phone',
                  phone: values.phone,
                  nonce: window.RUIYI_POS?.nonce || posNonce
                })
              });

              const checkData = await checkResponse.json();

              // 2. 如果客户不存在 → 创建；如果存在 → 更新后台信息
              if (!checkData.success || !checkData.data || !checkData.data.customer) {
                // 客户不存在，创建新客户
                const saveResult = await createCustomerInfoRecord(values);
                if (saveResult.success) {
                  Toastify({
                    text: '✅ <?php echo ruiyi_translate('Nueva información de cliente guardada', 'New customer info saved', '新客户信息已保存'); ?>',
                    duration: 2000,
                    gravity: 'top',
                    position: 'center',
                    style: { background: '#10b981' }
                  }).showToast();
                }
              } else {
                // 🔥 客户已存在，更新后台信息（允许修改地址、名称等）
                const existingCustomer = checkData.data.customer;
                try {
                  const updateResponse = await fetch(window.ajaxUrl || '<?php echo admin_url('admin-ajax.php'); ?>', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                    body: new URLSearchParams({
                      action: 'ruiyi_update_customer',
                      customer_id: existingCustomer.id,
                      name: values.name || values.phone,
                      phone: values.phone,
                      business_name: values.business_name || '',
                      cif_nif: values.cif_nif || '',
                      address: values.address || '',
                      postal_code: values.postal_code || '',
                      email: values.email || '',
                      nonce: window.RUIYI_POS?.nonce || posNonce
                    })
                  });
                  const updateData = await updateResponse.json();
                  if (updateData.success) {
                    Toastify({
                      text: '✅ <?php echo ruiyi_translate('Información de cliente actualizada', 'Customer info updated', '客户信息已更新'); ?>',
                      duration: 2000,
                      gravity: 'top',
                      position: 'center',
                      style: { background: '#10b981' }
                    }).showToast();
                  }
                } catch (updateError) {
                  console.warn('[Delivery] 更新客户信息失败（继续处理）:', updateError);
                }
              }
            } catch (error) {
              console.warn('[Delivery] 检查/创建客户失败（继续处理）:', error);
            }
          }

          Swal.resetValidationMessage();
          return values;
        },
        didOpen: () => {
          const popup = Swal.getPopup();
          const existing = getDeliveryCustomerData(tableName) || {};

          const nameField = popup?.querySelector('#delivery-customer-name');
          const phoneField = popup?.querySelector('#delivery-customer-phone');
          const addressField = popup?.querySelector('#delivery-customer-address');
          const businessField = popup?.querySelector('#delivery-customer-business-name');
          const taxField = popup?.querySelector('#delivery-customer-cif-nif');
          const postalField = popup?.querySelector('#delivery-customer-postal');
          const emailField = popup?.querySelector('#delivery-customer-email');
          const notesField = popup?.querySelector('#delivery-customer-notes');

          if (nameField) nameField.value = existing.name || '';
          if (phoneField) {
            phoneField.value = existing.phone || '';
            phoneField.focus();
          }
          if (addressField) addressField.value = existing.address || '';
          if (businessField) businessField.value = existing.business_name || '';
          if (taxField) taxField.value = existing.cif_nif || '';
          if (postalField) postalField.value = existing.postal_code || '';
          if (emailField) emailField.value = existing.email || '';
          if (notesField) notesField.value = existing.notes || '';

          const addressDropdown = popup?.querySelector('#address-autocomplete-dropdown');

          // 🔥 模糊搜索防抖变量
          let addressSearchTimeout = null;
          let selectedAddressIndex = -1;
          let addressResults = [];

          // 🔥 Enter 键快捷功能状态
          let isSearching = false;
          let isCustomerLoaded = false;

          // 🔥 模糊搜索函数（支持离线缓存）
          async function fuzzySearchCustomers(searchType, searchTerm) {
            if (!searchTerm || searchTerm.length < 3) return [];

            const isOnline = navigator.onLine && window.RUIYI_POS?.isOnline !== false;
            
            // 🔥 PWA: Try cached customers first when offline
            if (!isOnline) {
              try {
                const cached = await searchCachedCustomers(searchType, searchTerm);
                if (cached && cached.length > 0) {
                  return cached;
                }
              } catch (error) {
                console.warn('[Autocomplete] Cached search failed:', error);
              }
            }

            // Try online search
            if (isOnline) {
              try {
                const response = await fetch(window.ajaxUrl || '<?php echo admin_url('admin-ajax.php'); ?>', {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                  body: new URLSearchParams({
                    action: 'ruiyi_fuzzy_search_customers',
                    search_type: searchType,
                    search_term: searchTerm,
                    limit: 8,
                    nonce: window.RUIYI_POS?.nonce || posNonce
                  })
                });

                const data = await response.json();
                return data.success ? data.data.customers : [];
              } catch (error) {
                console.warn('[Autocomplete] Online search failed, trying cache:', error);
                // Fallback to cache
                try {
                  return await searchCachedCustomers(searchType, searchTerm);
                } catch (cacheError) {
                  console.error('[Autocomplete] Cache search also failed:', cacheError);
                  return [];
                }
              }
            }

            return [];
          }

          // 🔥 渲染地址下拉列表
          function renderAddressDropdown(results) {
            addressResults = results;
            selectedAddressIndex = -1;

            if (!addressDropdown || results.length === 0) {
              if (addressDropdown) addressDropdown.classList.remove('show');
              return;
            }

            addressDropdown.innerHTML = results.map((customer, index) => `
              <div class="autocomplete-item" data-index="${index}">
                <div class="phone-number">${customer.address}</div>
                <div class="customer-info">${customer.phone || ''}${customer.name ? ' - ' + customer.name : ''}</div>
              </div>
            `).join('');

            addressDropdown.classList.add('show');

            // 点击选择
            addressDropdown.querySelectorAll('.autocomplete-item').forEach(item => {
              item.addEventListener('click', () => {
                const idx = parseInt(item.dataset.index);
                selectAddressCustomer(addressResults[idx]);
              });
            });
          }

          // 🔥 选择地址后只填充地址字段
          function selectAddressCustomer(customer) {
            if (addressField) addressField.value = customer.address || '';

            if (addressDropdown) addressDropdown.classList.remove('show');

            Toastify({
              text: '✅ <?php echo ruiyi_translate('Dirección seleccionada', 'Address selected', '已选择地址'); ?>',
              duration: 1500,
              gravity: 'top',
              position: 'center',
              style: { background: '#10b981' }
            }).showToast();
          }

          // 🔥 电话必填输入框 - 同时支持搜索客户功能
          const phoneFieldDropdown = popup?.querySelector('#phone-field-autocomplete-dropdown');
          let phoneFieldSearchTimeout = null;
          let selectedPhoneFieldIndex = -1;
          let phoneFieldResults = [];

          // 渲染电话必填输入框的下拉列表
          function renderPhoneFieldDropdown(results) {
            phoneFieldResults = results;
            selectedPhoneFieldIndex = -1;

            if (!phoneFieldDropdown || results.length === 0) {
              if (phoneFieldDropdown) phoneFieldDropdown.classList.remove('show');
              return;
            }

            phoneFieldDropdown.innerHTML = results.map((customer, index) => `
              <div class="autocomplete-item" data-index="${index}">
                <div class="phone-number">${customer.phone}</div>
                <div class="customer-info">${customer.name || ''}${customer.address ? ' - ' + customer.address.substring(0, 30) + (customer.address.length > 30 ? '...' : '') : ''}</div>
              </div>
            `).join('');

            phoneFieldDropdown.classList.add('show');

            // 点击选择
            phoneFieldDropdown.querySelectorAll('.autocomplete-item').forEach(item => {
              item.addEventListener('click', () => {
                const idx = parseInt(item.dataset.index);
                selectPhoneFieldCustomer(phoneFieldResults[idx]);
              });
            });
          }

          // 选择客户后填充所有字段
          function selectPhoneFieldCustomer(customer) {
            if (nameField) nameField.value = customer.name || '';
            if (phoneField) phoneField.value = customer.phone || '';
            if (businessField) businessField.value = customer.business_name || '';
            if (taxField) taxField.value = customer.cif_nif || '';
            if (addressField) addressField.value = customer.address || '';
            if (postalField) postalField.value = customer.postal_code || '';
            if (emailField) emailField.value = customer.email || '';

            if (phoneFieldDropdown) phoneFieldDropdown.classList.remove('show');

            // 标记客户已加载
            isCustomerLoaded = true;

            Toastify({
              text: '✅ <?php echo ruiyi_translate('Cliente seleccionado', 'Customer selected', '已选择客户'); ?>',
              duration: 1500,
              gravity: 'top',
              position: 'center',
              style: { background: '#10b981' }
            }).showToast();

            // 自动聚焦到地址字段（如果地址为空）
            if (!addressField?.value.trim()) {
              setTimeout(() => addressField?.focus(), 100);
            }
          }

          function updatePhoneFieldSelection() {
            if (!phoneFieldDropdown) return;
            phoneFieldDropdown.querySelectorAll('.autocomplete-item').forEach((item, idx) => {
              item.classList.toggle('selected', idx === selectedPhoneFieldIndex);
            });
          }

          // 为电话必填输入框添加搜索事件
          if (phoneField) {
            phoneField.addEventListener('input', (e) => {
              const value = e.target.value.trim();

              if (phoneFieldSearchTimeout) clearTimeout(phoneFieldSearchTimeout);

              if (value.length < 3) {
                if (phoneFieldDropdown) phoneFieldDropdown.classList.remove('show');
                return;
              }

              phoneFieldSearchTimeout = setTimeout(async () => {
                const results = await fuzzySearchCustomers('phone', value);
                renderPhoneFieldDropdown(results);
              }, 300);
            });

            // 键盘导航
            phoneField.addEventListener('keydown', (e) => {
              // 如果下拉框显示，处理导航
              if (phoneFieldDropdown?.classList.contains('show')) {
                if (e.key === 'ArrowDown') {
                  e.preventDefault();
                  selectedPhoneFieldIndex = Math.min(selectedPhoneFieldIndex + 1, phoneFieldResults.length - 1);
                  updatePhoneFieldSelection();
                  return;
                } else if (e.key === 'ArrowUp') {
                  e.preventDefault();
                  selectedPhoneFieldIndex = Math.max(selectedPhoneFieldIndex - 1, 0);
                  updatePhoneFieldSelection();
                  return;
                } else if (e.key === 'Enter' && phoneFieldResults.length > 0) {
                  e.preventDefault();
                  const indexToSelect = selectedPhoneFieldIndex >= 0 ? selectedPhoneFieldIndex : 0;
                  selectPhoneFieldCustomer(phoneFieldResults[indexToSelect]);
                  return;
                } else if (e.key === 'Escape') {
                  phoneFieldDropdown.classList.remove('show');
                  return;
                }
              }
            });

            // 失去焦点时隐藏下拉列表
            phoneField.addEventListener('blur', () => {
              setTimeout(() => {
                if (phoneFieldDropdown) phoneFieldDropdown.classList.remove('show');
              }, 200);
            });
          }

          // 🔥 地址输入框 - 模糊搜索
          if (addressField) {
            addressField.addEventListener('input', (e) => {
              const value = e.target.value.trim();

              if (addressSearchTimeout) clearTimeout(addressSearchTimeout);

              if (value.length < 3) {
                if (addressDropdown) addressDropdown.classList.remove('show');
                return;
              }

              addressSearchTimeout = setTimeout(async () => {
                const results = await fuzzySearchCustomers('address', value);
                renderAddressDropdown(results);
              }, 300);
            });

            // 键盘导航
            addressField.addEventListener('keydown', (e) => {
              if (!addressDropdown?.classList.contains('show')) return;

              if (e.key === 'ArrowDown') {
                e.preventDefault();
                selectedAddressIndex = Math.min(selectedAddressIndex + 1, addressResults.length - 1);
                updateAddressSelection();
              } else if (e.key === 'ArrowUp') {
                e.preventDefault();
                selectedAddressIndex = Math.max(selectedAddressIndex - 1, 0);
                updateAddressSelection();
              } else if (e.key === 'Enter' && selectedAddressIndex >= 0) {
                e.preventDefault();
                selectAddressCustomer(addressResults[selectedAddressIndex]);
              } else if (e.key === 'Escape') {
                addressDropdown.classList.remove('show');
              }
            });

            // 失去焦点时隐藏下拉列表
            addressField.addEventListener('blur', () => {
              setTimeout(() => {
                if (addressDropdown) addressDropdown.classList.remove('show');
              }, 200);
            });
          }

          function updateAddressSelection() {
            if (!addressDropdown) return;
            addressDropdown.querySelectorAll('.autocomplete-item').forEach((item, idx) => {
              item.classList.toggle('selected', idx === selectedAddressIndex);
            });
          }

          // 🔥🔥🔥 【2026-01-31 修改】电话和地址输入框的 Enter 键快捷导航
          // 需求：电话输入框按 Enter → 聚焦地址输入框（仅在没有搜索下拉框显示时）
          // 注意：如果有搜索下拉框显示，Enter 键会选择客户（由上方的 keydown 事件处理）
          if (phoneField) {
            phoneField.addEventListener('keydown', (e) => {
              if (e.key === 'Enter') {
                // 🔥 如果搜索下拉框正在显示，让上方的事件处理器处理（选择客户）
                if (phoneFieldDropdown?.classList.contains('show') && phoneFieldResults.length > 0) {
                  return; // 不处理，让上方的搜索事件处理
                }

                e.preventDefault();
                // 如果电话有内容，聚焦到地址输入框
                if (phoneField.value.trim()) {
                  if (addressField) {
                    addressField.focus();
                  }
                }
              }
            });
          }

          if (addressField) {
            // 🔥 修改现有的 keydown 事件处理，支持无自动完成下拉框时提交表单
            const originalAddressKeydown = addressField.onkeydown;
            addressField.addEventListener('keydown', (e) => {
              if (e.key === 'Enter') {
                // 如果自动完成下拉框显示且有选中项，让原有逻辑处理
                if (addressDropdown?.classList.contains('show') && selectedAddressIndex >= 0) {
                  return; // 让原有事件处理器处理
                }

                // 🔥 如果下拉框没显示或没有选中项，且地址有内容，提交表单
                if (addressField.value.trim()) {
                  e.preventDefault();
                  // 隐藏下拉框
                  if (addressDropdown) addressDropdown.classList.remove('show');
                  // 点击确认按钮
                  const confirmBtn = popup?.querySelector('.swal2-confirm');
                  if (confirmBtn) {
                    confirmBtn.click();
                  }
                }
              }
            });
          }

          // 🔥 显示/隐藏搜索加载动画
          function showSearchLoading(show) {
            const searchBtn = popup?.querySelector('#delivery-search-customer-btn');
            if (searchBtn) {
              if (show) {
                searchBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';
                searchBtn.disabled = true;
              } else {
                searchBtn.innerHTML = '<?php echo ruiyi_translate('Buscar', 'Search', '查找'); ?>';
                searchBtn.disabled = false;
              }
            }
          }

          // 原有的精确搜索功能
          const searchBtn = popup?.querySelector('#delivery-search-customer-btn');
          const searchField = phoneField;
          const phoneDropdown = phoneFieldDropdown;
          if (searchBtn && searchField) {
            const performSearch = async () => {
              const phone = searchField.value.trim();
              if (!phone) {
                Swal.showValidationMessage('<?php echo ruiyi_translate('Por favor ingrese número de teléfono', 'Please enter phone number', '请输入电话号码'); ?>');
                return;
              }
              if (phoneDropdown) phoneDropdown.classList.remove('show');

              // 🔥 显示加载动画
              isSearching = true;
              showSearchLoading(true);

              await findDeliveryCustomerByPhone(phone);

              // 🔥 隐藏加载动画
              isSearching = false;
              showSearchLoading(false);
            };

            searchBtn.addEventListener('click', performSearch);

            // 🔥 Enter 键智能处理 - 简化逻辑
            searchField.addEventListener('keypress', async (event) => {
              if (event.key === 'Enter') {
                event.preventDefault();

                // 如果正在搜索中，忽略
                if (isSearching) return;

                // 🔥 优先级1：如果必填字段已填写，直接提交（不管其他状态）
                if (phoneField?.value?.trim() && addressField?.value?.trim()) {
                  const confirmBtn = popup?.querySelector('.swal2-confirm');
                  if (confirmBtn) {
                    confirmBtn.click();
                    return;
                  }
                }

                // 🔥 优先级2：如果下拉框显示且有搜索结果，选择第一个
                if (phoneDropdown?.classList.contains('show') && phoneResults.length > 0) {
                  const indexToSelect = selectedPhoneIndex >= 0 ? selectedPhoneIndex : 0;
                  selectPhoneCustomer(phoneResults[indexToSelect]);
                  return;
                }

                // 🔥 优先级3：执行搜索
                await performSearch();
              }
            });
          }

          async function findDeliveryCustomerByPhone(phone) {
            const isOnline = navigator.onLine && window.RUIYI_POS?.isOnline !== false;
            
            // 🔥 PWA: Try cached customers first when offline
            if (!isOnline) {
              try {
                const cached = await searchCachedCustomers('phone', phone);

                if (cached && cached.length > 0) {
                  const customer = cached[0];

                  if (nameField) nameField.value = customer.name || '';
                  if (phoneField) phoneField.value = customer.phone || phone;
                  if (businessField) businessField.value = customer.business_name || '';
                  if (taxField) taxField.value = customer.cif_nif || '';
                  if (addressField) addressField.value = customer.address || '';
                  if (postalField) postalField.value = customer.postal_code || '';
                  if (emailField) emailField.value = customer.email || '';
                  if (searchField) searchField.value = customer.phone || phone;

                  // 🔥 标记客户已加载
                  isCustomerLoaded = true;

                  Toastify({
                    text: '✅ <?php echo ruiyi_translate('Cliente encontrado - Presione Enter para continuar', 'Customer found - Press Enter to continue', '找到客户 - 按 Enter 继续'); ?>',
                    duration: 2000,
                    gravity: 'top',
                    position: 'center',
                    style: { background: '#10b981' }
                  }).showToast();
                  return;
                }
              } catch (error) {
                console.warn('[Delivery] Cached search failed:', error);
              }
              
              Toastify({
                text: '<?php echo ruiyi_translate('Cliente no encontrado en caché', 'Customer not found in cache', '缓存中未找到客户'); ?>',
                duration: 2000,
                gravity: 'top',
                position: 'center',
                style: { background: '#f59e0b' }
              }).showToast();
              return;
            }

            // Try online search
            try {
              const formData = new URLSearchParams({
                action: 'ruiyi_find_customer_by_phone',
                phone: phone,
                nonce: window.RUIYI_POS?.nonce || posNonce
              });

              const response = await fetch(window.ajaxUrl || '<?php echo admin_url('admin-ajax.php'); ?>', {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: formData
              });

              const data = await response.json();

              if (data.success && data.data.customer) {
                const customer = data.data.customer;
                if (nameField) nameField.value = customer.name || '';
                if (phoneField) phoneField.value = customer.phone || phone;
                if (businessField) businessField.value = customer.business_name || '';
                if (taxField) taxField.value = customer.cif_nif || '';
                if (addressField) addressField.value = customer.address || '';
                if (postalField) postalField.value = customer.postal_code || '';
                if (emailField) emailField.value = customer.email || '';
                if (notesField) notesField.value = customer.notes || '';
                if (searchField) searchField.value = customer.phone || phone;

                // 🔥 标记客户已加载
                isCustomerLoaded = true;

                Toastify({
                  text: '✅ <?php echo ruiyi_translate('Cliente encontrado - Presione Enter para continuar', 'Customer found - Press Enter to continue', '找到客户 - 按 Enter 继续'); ?>',
                  duration: 2000,
                  gravity: 'top',
                  position: 'center',
                  style: { background: '#10b981' }
                }).showToast();
              } else {
                // 🔥 PWA: Fallback to cache if online search fails
                try {
                  const cached = await searchCachedCustomers('phone', phone);
                  if (cached && cached.length > 0) {
                    const customer = cached[0];
                    if (nameField) nameField.value = customer.name || '';
                    if (phoneField) phoneField.value = customer.phone || phone;
                    if (businessField) businessField.value = customer.business_name || '';
                    if (taxField) taxField.value = customer.cif_nif || '';
                    if (addressField) addressField.value = customer.address || '';
                    if (postalField) postalField.value = customer.postal_code || '';
                    if (emailField) emailField.value = customer.email || '';
                    if (searchField) searchField.value = customer.phone || phone;

                    // 🔥 标记客户已加载
                    isCustomerLoaded = true;

                    Toastify({
                      text: '✅ <?php echo ruiyi_translate('Cliente encontrado - Presione Enter para continuar', 'Customer found - Press Enter to continue', '找到客户 - 按 Enter 继续'); ?>',
                      duration: 2000,
                      gravity: 'top',
                      position: 'center',
                      style: { background: '#10b981' }
                    }).showToast();
                    return;
                  }
                } catch (cacheError) {
                  console.warn('[Delivery] Cache fallback failed:', cacheError);
                }

                if (phoneField) phoneField.value = phone;
                if (searchField) searchField.value = phone;

                Toastify({
                  text: '<?php echo ruiyi_translate('Cliente no encontrado - Ingrese los datos manualmente', 'Customer not found - Enter data manually', '未找到客户 - 请手动输入'); ?>',
                  duration: 2000,
                  gravity: 'top',
                  position: 'center',
                  style: { background: '#f59e0b' }
                }).showToast();
              }
            } catch (error) {
              Swal.showValidationMessage('<?php echo ruiyi_translate('Error al buscar cliente', 'Error searching customer', '查找客户失败'); ?>: ' + error.message);
            }
          }
        }
      });

      if (!result.isConfirmed || !result.value) {
        return false;
      }

      const globalNumber = extractGlobalTableNumber(tableName);
      setDeliveryCustomerData(tableName, {
        ...result.value,
        category_id: mapping ? parseInt(mapping.category_id, 10) || null : null,
        category_name: zoneName,
        table_display: tableName,
        global_number: globalNumber
      });

      Swal.close();
      return true;
    }

    // ========================================
    // 渲染分类按钮
    function renderCategoryButtons(categories) {
      const container = document.querySelector('#category-filter-container .flex-1 .flex');
      if (!container) return;

      // 清除所有现有按钮
      container.innerHTML = '';

      // 获取当前语言（优先使用cookie）
      const cookieLang = getCurrentLanguageFromCookie();
      const htmlLang = document.documentElement.lang;
      const bodyLang = document.body.lang;
      const currentLang = cookieLang || htmlLang || bodyLang || PHP_LANG;

      // 过滤分类 - 如果设置中禁用了"所有餐桌"按钮，则不显示
      const filteredCategories = showAllTablesButton ? categories : categories.filter(cat => cat.id !== 'all');

      // 添加分类按钮
      filteredCategories.forEach(category => {
        
        const button = document.createElement('button');
        button.className = 'category-filter-btn px-4 py-2 rounded-lg border-2 transition-all';
        button.setAttribute('data-category', category.id);
        
        button.style.borderColor = category.color;
        
        // 获取正确语言的分类名称
        let categoryName;
        if (category.is_system && category.id === 'all') {
          // 系统分类"所有"使用多语言支持
          const allTranslations = {
            'es': 'Todas las Mesas',
            'en': 'All Tables',
            'zh': '所有餐桌'
          };
          categoryName = allTranslations[currentLang] || getTranslation('all_tables') || 'All Tables';
        } else if (category.display_name) {
          // 使用后端提供的显示名称
          categoryName = category.display_name;
        } else {
          // 根据语言选择合适的名称字段
          const langField = 'name_' + currentLang;
          categoryName = category[langField] || category.name;
        }
        
        
        button.innerHTML = `
          <i class="${category.icon} mr-2"></i>
          <span>${categoryName}</span>
        `;
        
        // 设置默认样式
        button.style.backgroundColor = 'transparent';
        button.style.color = category.color;
        
        // 添加悬停效果
        button.addEventListener('mouseenter', function() {
          if (!this.classList.contains('active')) {
            this.style.backgroundColor = category.color + '20';
          }
        });
        
        button.addEventListener('mouseleave', function() {
          if (!this.classList.contains('active')) {
            this.style.backgroundColor = 'transparent';
          }
        });
        
        container.appendChild(button);
      });
      
      // 绑定点击事件（统一的多语言支持）
      container.querySelectorAll('.category-filter-btn').forEach(btn => {
        btn.addEventListener('click', function() {
          // 移除所有active类
          container.querySelectorAll('.category-filter-btn').forEach(b => {
            b.classList.remove('active');
            b.style.backgroundColor = 'transparent';
            const categoryId = b.getAttribute('data-category');
            
            // 恢复正常状态颜色
            if (categoryId === 'all') {
              b.style.color = '#6B7280';
            } else {
              const cat = categories.find(c => c.id == categoryId);
              if (cat) {
                b.style.color = cat.color;
              }
            }
          });
          
          // 激活当前按钮
          const selectedCategoryId = this.getAttribute('data-category');
          this.classList.add('active');
          const categoryId = this.getAttribute('data-category');
          
          if (categoryId === 'all') {
            this.style.backgroundColor = '#E5E7EB';
            this.style.color = '#374151';
          } else {
            const category = categories.find(c => c.id == categoryId);
            if (category) {
              this.style.backgroundColor = category.color;
              this.style.color = 'white';
            }
          }
          
          // 设置当前分类过滤器并重新渲染
          currentCategoryFilter = categoryId;
          
          // 添加加载动画提供即时反馈
          const mesasGrid = document.getElementById('mesas-grid');
          if (mesasGrid) {
            mesasGrid.style.opacity = '0.5';
            mesasGrid.style.transition = 'opacity 0.1s';
          }
          
          // 立即渲染
          renderizarMesas('category-filter');
          
          // 移除加载动画
          setTimeout(() => {
            if (mesasGrid) {
              mesasGrid.style.opacity = '1';
            }
          }, 100);
        });
      });

      // 自动选择第一个分类按钮（如果没有选中的按钮）
      setTimeout(() => {
        const activeBtn = container.querySelector('.category-filter-btn.active');
        if (!activeBtn) {
          const firstCategoryBtn = container.querySelector('.category-filter-btn:not([data-category="all"])') ||
                                  container.querySelector('.category-filter-btn');
          if (firstCategoryBtn) {
            firstCategoryBtn.click();
          }
        }
      }, 100);
    }

    // 初始化餐桌范围筛选器
    function initializeTableRangeFilter() {
      const totalTables = numberOfTablesConfig || 25;
      const rangeFilterContainer = document.getElementById('table-range-filter');
      const rangeButtonsContainer = document.getElementById('range-buttons-container');
      
      if (totalTables > 60 && rangeFilterContainer && rangeButtonsContainer) {
        // 显示范围筛选器
        rangeFilterContainer.classList.remove('hidden');
        
        // 计算需要的范围数量
        const rangeSize = 60;
        const rangeCount = Math.ceil(totalTables / rangeSize);
        
        // 清除现有按钮
        rangeButtonsContainer.innerHTML = '';
        
        // 创建范围按钮
        for (let i = 0; i < rangeCount; i++) {
          const startRange = i * rangeSize + 1;
          const endRange = Math.min((i + 1) * rangeSize, totalTables);
          
          const rangeButton = document.createElement('button');
          rangeButton.className = `range-filter-btn px-3 py-1 rounded-md border text-sm transition-all ${i === 0 ? 'bg-blue-500 text-white border-blue-500' : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'}`;
          rangeButton.setAttribute('data-range-start', startRange);
          rangeButton.setAttribute('data-range-end', endRange);
          rangeButton.textContent = `${startRange}-${endRange}`;
          
          // 添加点击事件
          rangeButton.addEventListener('click', function() {
            // 更新按钮状态
            document.querySelectorAll('.range-filter-btn').forEach(btn => {
              btn.classList.remove('bg-blue-500', 'text-white', 'border-blue-500');
              btn.classList.add('bg-white', 'text-gray-700', 'border-gray-300');
            });
            this.classList.remove('bg-white', 'text-gray-700', 'border-gray-300');
            this.classList.add('bg-blue-500', 'text-white', 'border-blue-500');
            
            // 设置当前范围
            window.currentTableRange = {
              start: parseInt(startRange),
              end: parseInt(endRange)
            };
            
            // 重新渲染餐桌
            renderizarMesas('range-filter');
            
          });
          
          rangeButtonsContainer.appendChild(rangeButton);
        }
        
        // 设置默认范围
        window.currentTableRange = {
          start: 1,
          end: Math.min(60, totalTables)
        };
        
      } else {
        // 隐藏范围筛选器
        if (rangeFilterContainer) {
          rangeFilterContainer.classList.add('hidden');
        }
        window.currentTableRange = null;
      }
    }

    // 餐桌管理功能 - 初始化与渲染餐桌
    function initMesasManager() {
      // 获取餐桌网格容器
      const mesasGrid = document.getElementById('mesas-grid');
      if (!mesasGrid) return;
      
      // 添加滚动容器样式 - 🔥 修复：添加 overflow-x-hidden 防止"所有餐桌"视图时横向溢出
      mesasGrid.parentElement.classList.add('overflow-x-hidden', 'overflow-y-auto', 'max-h-[calc(100vh-220px)]', 'pr-2', 'scrollbar', 'scrollbar-thin', 'scrollbar-thumb-red-500', 'scrollbar-track-gray-200', 'dark:scrollbar-track-gray-800');
      
      // 渲染餐桌 - Se llamará después cuando la función esté definida
      // renderizarMesas('initial-load'); // Movido al final del DOMContentLoaded
      
      // 注册事件监听 - 已移除手动刷新和过滤器，改用自动刷新机制
      
      // 使用事件委托为餐桌状态变更按钮添加点击事件
      mesasGrid.addEventListener('click', function(e) {
        // 检查是否点击了状态变更按钮
        if (e.target && e.target.classList && e.target.classList.contains('cambiar-estado-btn') || 
            (e.target && e.target.parentElement && e.target.parentElement.classList && e.target.parentElement.classList.contains('cambiar-estado-btn'))) {
          
          // 获取按钮元素
          const button = (e.target && e.target.classList && e.target.classList.contains('cambiar-estado-btn')) ? 
                        e.target : e.target.parentElement;
          
          // 获取餐桌ID和目标状态
          const mesa = button.getAttribute('data-mesa');
          const nuevoEstado = button.getAttribute('data-estado');
          
          // 调用状态变更函数
          if (mesa && nuevoEstado) {
            cambiarEstadoMesa(mesa, nuevoEstado);
          }
        }
    
        // 在页面的mesasGrid事件委托中添加结账按钮的事件处理
        if ((e.target && e.target.classList && e.target.classList.contains('procesar-pago')) || 
            (e.target && e.target.parentElement && e.target.parentElement.classList && e.target.parentElement.classList.contains('procesar-pago'))) {
          
          e.stopPropagation(); // 阻止事件冒泡到餐桌元素
          
          const button = (e.target && e.target.classList && e.target.classList.contains('procesar-pago')) ? 
                        e.target : e.target.parentElement;
          
          const mesa = button.getAttribute('data-mesa');
          const ordenId = button.getAttribute('data-orden');
          
          if (mesa) {
            // 获取桌位所有未结账订单的信息
            fetch(ajaxUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_get_table_orders',
                    table_number: mesa,
                    nonce: ajaxNonce
                })
            })
            .then(response => {
                if (!response.ok) {
                    throw new Error(`${response.status} ${response.statusText}`);
                }
                return response.json();
            })
            .then(data => {
                // 添加调试信息
                
                // 修复：正确访问嵌套的数据结构
                const responseData = data.data || {};
                const orders = responseData.orders || [];
                
                if (data.success && orders && Array.isArray(orders) && orders.length > 0) {
                    // 计算总金额和收集订单ID
                    let totalAdeudado = 0;
                    let orderIds = [];
                    
                    // 显示找到的订单信息
                    
                    orders.forEach(order => {
                        // 确保订单总金额是数字
                        const orderTotal = parseFloat(order.total) || 0;
                        totalAdeudado += orderTotal;
                        
                        // 确保订单ID格式正确
                        const orderId = order.order_number || order.id;
                        orderIds.push(`#${orderId}`);
                        
                    });
                    
                    
                    // 直接调用多订单支付函数
                    procesarPagoCompletoDeMesa(mesa, totalAdeudado, orderIds);
                } else {
                    // 添加更详细的错误信息
                    console.warn('没有找到待处理订单或响应格式不正确:', data);
                    if (data.success && (!responseData.orders || !Array.isArray(responseData.orders))) {
                        console.error('返回的orders数据无效:', responseData.orders);
                    }
                    
                    // 没有订单，显示提示
                    Swal.fire({
                        icon: 'info',
                        title: '<?php echo ruiyi_translate("No hay pedidos pendientes","Order Pending","没有待处理的订单"); ?>',
                        text: '<?php echo ruiyi_translate("No se encontraron pedidos pendientes para esta mesa.","No orders pending for this table.","没有找到待处理的订单"); ?>'
                    });
                }
            })
            .catch(error => {
                console.error('Error al obtener los pedidos:', error);
                Swal.fire({
                    icon: 'error',
                    title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
                    text: '<?php echo ruiyi_translate("No se pudieron obtener los pedidos. Por favor, inténtelo de nuevo.","Could not get orders. Please try again.","无法获取订单。请再试一次。"); ?>'
                });
            });
          }
        }
      });
    }

