    // 防抖渲染餐桌网格 - 防止过度刷新
    let renderMesasTimeout = null;
    let renderMesasCount = 0;
    let renderMesasLastCall = 0;

    // 初始化全局过滤器变量
    window.currentTableFilter = null;

    // 🔥【2026-04-07】桌位订单起始时间锁定：保存到独立 localStorage key（'table_order_start_times'）
    // 用 mesaId+orderId 作为键，订单 ID 不变时永远返回首次记录的时间，避免每次保存重置
    // 当桌位变 libre 或 orderId 变化时自动清除
    function _resolveOrderStartTimestamp(mesaId, estadoMesa) {
      try {
        const KEY = 'table_order_start_times';
        const map = JSON.parse(localStorage.getItem(KEY) || '{}');

        // libre 状态或无订单 → 清除该桌位的记录
        if (!estadoMesa || estadoMesa.estado === 'libre' || !estadoMesa.orderId) {
          if (map[mesaId]) {
            delete map[mesaId];
            localStorage.setItem(KEY, JSON.stringify(map));
          }
          return null;
        }

        const currentOrderId = String(estadoMesa.orderId);
        const existing = map[mesaId];

        // 已有记录且订单ID一致 → 用记录值
        if (existing && existing.orderId === currentOrderId && existing.timestamp) {
          return existing.timestamp;
        }

        // 新记录：用当前 estadoMesa.timestamp 作为起点
        const newTs = estadoMesa.timestamp || new Date().toISOString();
        map[mesaId] = { orderId: currentOrderId, timestamp: newTs };
        localStorage.setItem(KEY, JSON.stringify(map));
        return newTs;
      } catch (e) {
        return estadoMesa && estadoMesa.timestamp ? estadoMesa.timestamp : null;
      }
    }
    window._resolveOrderStartTimestamp = _resolveOrderStartTimestamp;

    function renderizarMesas(source = 'unknown') {

      const now = Date.now();
      const timeSinceLastCall = now - renderMesasLastCall;

      // 对于分类筛选、搜索、范围筛选、手动刷新和自动更新，立即执行不防抖
      // 🔥 【关键修复】添加 'waiter-order-created' 和 'after-auto-save' 到立即渲染列表
      // 这样当服务员/客户页面创建订单后，POS页面能立即显示更新
      // 🔥 优化：添加桌位相关源到立即渲染列表，避免800ms防抖延迟
      const immediateRenderSources = ['category-filter', 'range-filter', 'manual-refresh', 'initial-load', 'section-change', 'auto-update-immediate', 'payment-popup-closed', 'exit-view-mode', 'payment-processed', 'order-created', 'waiter-order-created', 'after-auto-save', 'customer-order-created', 'section-switch-to-mesas', 'after-order-creation', 'after-clear-table', 'table-freed', 'aa-checkout-complete', 'aa-checkout-complete-delayed', 'aa-checkout-final', 'aa-close-complete', 'aa-close-delayed', 'aa-close-final', 'after-offline-sync', 'after-offline-auto-save', 'cart-total-sync', 'websocket-order-created', 'zombie-cleanup'];
      if (immediateRenderSources.includes(source)) {

        // 清除任何待执行的防抖定时器
        if (renderMesasTimeout) {
          clearTimeout(renderMesasTimeout);
          renderMesasTimeout = null;
        }

        renderMesasCount++;
        renderMesasLastCall = Date.now();
        renderizarMesasActual(window.currentTableFilter);
        return;
      }
      
      // 防抖处理：其他情况1000ms内的多次调用只执行一次
      if (renderMesasTimeout) {
        clearTimeout(renderMesasTimeout);
      }
      
      renderMesasTimeout = setTimeout(() => {
        renderMesasCount++;
        renderMesasLastCall = Date.now();

        // 🔥 优化：减少 auto-update 的防抖时间，提高响应速度
        if (source === 'auto-update' && timeSinceLastCall < 5000) {
          renderMesasTimeout = setTimeout(() => {
            renderizarMesasActual(window.currentTableFilter);
            renderMesasTimeout = null;
          }, 500); // 从 3000ms 优化为 500ms
          return;
        }

        renderizarMesasActual(window.currentTableFilter);
        renderMesasTimeout = null;
      }, 800); // 从 1500ms 优化为 800ms
    }
    // 导出到全局作用域
    window.renderizarMesas = renderizarMesas;

    // 🔥 桌位订单时长定时更新（每分钟刷新一次显示）
    if (window.RUIYI_POS_CONFIG && window.RUIYI_POS_CONFIG.showTableOrderTime) {
      if (window._tableOrderTimeInterval) clearInterval(window._tableOrderTimeInterval);
      window._tableOrderTimeInterval = setInterval(() => {
        // 仅当桌位模块可见时才重新渲染，避免后台浪费
        const mesasGrid = document.getElementById('mesas-grid');
        if (mesasGrid && mesasGrid.offsetParent !== null) {
          renderizarMesas('table-time-tick');
        }
      }, 60000);
    }

    // 🔥 辅助函数：多格式查找桌位数据（支持Mesa/Table/餐桌所有格式）
    function findTableDataByNumber(mesasEstado, tableNumber) {
      // 🔥 【关键修复】优先使用 "Mesa" 前缀，因为 carrito-cliente.php 和 servicio-mesa.php 都使用这个格式
      // 然后再检查当前语言的前缀，确保跨页面数据同步正确
      const currentPrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';

      // 🔥 【修复】将 Mesa 放在最前面，确保外部页面保存的数据能被优先找到
      const prefixes = ['Mesa', currentPrefix, 'Table', '餐桌'];

      // 移除重复项
      const uniquePrefixes = [...new Set(prefixes)];

      // 🔥 【关键修复】尝试多种键名格式：有空格和无空格
      for (const prefix of uniquePrefixes) {
        // 1. 带空格格式: "Mesa 1"
        const keyWithSpace = `${prefix} ${tableNumber}`;
        if (mesasEstado[keyWithSpace]) {
          return { data: mesasEstado[keyWithSpace], key: keyWithSpace };
        }

        // 2. 无空格格式: "Mesa1"
        const keyWithoutSpace = `${prefix}${tableNumber}`;
        if (mesasEstado[keyWithoutSpace]) {
          return { data: mesasEstado[keyWithoutSpace], key: keyWithoutSpace };
        }
      }
      return { data: null, key: null };
    }

    // 🔥 辅助函数：多格式查找购物车数据
    function findCarritoByNumber(carritosGuardados, tableNumber) {
      // 🔥 【关键修复】优先使用 "Mesa" 前缀，与 findTableDataByNumber 保持一致
      const currentPrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';

      // 🔥 【修复】将 Mesa 放在最前面
      const prefixes = ['Mesa', currentPrefix, 'Table', '餐桌'];

      // 移除重复项
      const uniquePrefixes = [...new Set(prefixes)];

      // 🔥 【关键修复】尝试多种键名格式：有空格和无空格
      for (const prefix of uniquePrefixes) {
        // 1. 带空格格式: "Mesa 1"
        const keyWithSpace = `${prefix} ${tableNumber}`;
        if (carritosGuardados[keyWithSpace]) {
          return { data: carritosGuardados[keyWithSpace], key: keyWithSpace };
        }

        // 2. 无空格格式: "Mesa1"
        const keyWithoutSpace = `${prefix}${tableNumber}`;
        if (carritosGuardados[keyWithoutSpace]) {
          return { data: carritosGuardados[keyWithoutSpace], key: keyWithoutSpace };
        }
      }
      return { data: null, key: null };
    }

    // 实际渲染餐桌网格的函数
    function renderizarMesasActual(customTableFilter = null) {
        // 如果没有传入过滤器，使用全局过滤器
        if (!customTableFilter && window.currentTableFilter) {
            customTableFilter = window.currentTableFilter;
        }

      const mesasGrid = document.getElementById('mesas-grid');
      if (!mesasGrid) return;

      // 🔥 关键修复：每次渲染时都重新从 localStorage 读取最新数据
      // 这确保了即使 fetchAndUpdateTableStatuses 更新了数据，渲染时也能使用最新状态
      const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
      const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');

      // 使用DocumentFragment来批量添加DOM元素，提高性能
      const fragment = document.createDocumentFragment();
      
      // 预先收集需要显示的餐桌
      const tablesToRender = [];
      
      // 获取所有桌位的分类映射，根据分类过滤显示
      if (currentCategoryFilter === 'all') {
        // 显示所有桌位，使用分类显示名称
        const allMappings = Object.values(tableCategoryMappings);

        // 如果有分类映射，显示分类桌位名称
        if (allMappings.length > 0) {
          allMappings.forEach(mapping => {
            const globalNumber = parseInt(mapping.global_table_number);
            const categoryDisplayName = mapping.category_display_name || mapping.display_name;
            const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
            const mesaId = `${tablePrefix} ${globalNumber}`;

            // 🔥 构建餐桌数据 - 使用多格式查找
            const carritoResult = findCarritoByNumber(carritosGuardados, globalNumber);
            const estadoResult = findTableDataByNumber(mesasEstado, globalNumber);

            const tieneCarrito = !!carritoResult.data;
            const estadoMesa = estadoResult.data;
            let estado = 'libre';

            if (estadoMesa) {
              estado = estadoMesa.estado || 'libre';
            } else if (tieneCarrito) {
              estado = 'guardada';
            }

            // 应用自定义筛选函数（如果提供）
            const tableData = {
              mesaId: mesaId,
              numero: globalNumber,
              estado: estado,
              tieneCarrito: tieneCarrito,
              estadoMesa: estadoMesa
            };

            if (customTableFilter && !customTableFilter(tableData)) {
              return;
            }

            // 检查范围过滤
            if (window.currentTableRange) {
              if (globalNumber < window.currentTableRange.start || globalNumber > window.currentTableRange.end) {
                return;
              }
            }

            tablesToRender.push({
              index: globalNumber,
              mesaId: mesaId,
              displayName: categoryDisplayName, // 显示分类名称
              globalNumber: globalNumber,
              categoryId: mapping.category_id ? parseInt(mapping.category_id) : null
            });
          });
        } else {
          // 如果没有分类映射，回退到全局编号
          for (let i = 1; i <= numberOfTablesConfig; i++) {
            const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
            const mesaId = `${tablePrefix} ${i}`;

            // 🔥 使用多格式查找
            const carritoResult = findCarritoByNumber(carritosGuardados, i);
            const estadoResult = findTableDataByNumber(mesasEstado, i);

            const tieneCarrito = !!carritoResult.data;
            const estadoMesa = estadoResult.data;
            let estado = 'libre';

            if (estadoMesa) {
              estado = estadoMesa.estado || 'libre';
            } else if (tieneCarrito) {
              estado = 'guardada';
            }

            const tableData = {
              mesaId: mesaId,
              numero: i,
              estado: estado,
              tieneCarrito: tieneCarrito,
              estadoMesa: estadoMesa
            };

            if (customTableFilter && !customTableFilter(tableData)) {
              continue;
            }

            if (window.currentTableRange) {
              if (i < window.currentTableRange.start || i > window.currentTableRange.end) {
                continue;
              }
            }

            tablesToRender.push({
              index: i,
              mesaId: mesaId,
              displayName: mesaId,
              globalNumber: i
            });
          }
        }
      } else {
        // 显示特定分类的桌位，使用分类显示名称
        const categoryTables = Object.values(tableCategoryMappings).filter(mapping =>
          mapping.category_id == currentCategoryFilter
        );

        categoryTables.forEach(mapping => {
          const globalNumber = parseInt(mapping.global_table_number);
          const categoryDisplayName = mapping.category_display_name || mapping.display_name;

          // 使用全局编号作为后端识别ID，但显示分类名称
          const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
          const mesaId = `${tablePrefix} ${globalNumber}`; // 后端使用全局编号

          // 🔥 构建餐桌数据 - 使用多格式查找
          const carritoResult = findCarritoByNumber(carritosGuardados, globalNumber);
          const estadoResult = findTableDataByNumber(mesasEstado, globalNumber);

          const tieneCarrito = !!carritoResult.data;
          const estadoMesa = estadoResult.data;
          let estado = 'libre';

          if (estadoMesa) {
            estado = estadoMesa.estado || 'libre';
          } else if (tieneCarrito) {
            estado = 'guardada';
          }

          // 应用自定义筛选函数（如果提供）
          const tableData = {
            mesaId: mesaId,
            numero: globalNumber,
            estado: estado,
            tieneCarrito: tieneCarrito,
            estadoMesa: estadoMesa
          };

          if (customTableFilter && !customTableFilter(tableData)) {
            return;
          }

          tablesToRender.push({
            index: globalNumber,
            mesaId: mesaId, // 后端识别用全局编号
            displayName: categoryDisplayName, // 前端显示用分类名称
            globalNumber: globalNumber
          });
        });
      }

      // 渲染收集到的餐桌
      tablesToRender.forEach(({ index, mesaId, displayName, globalNumber }) => {
        // 🔥 使用多格式查找桌位数据
        const carritoResult = findCarritoByNumber(carritosGuardados, globalNumber);
        const estadoResult = findTableDataByNumber(mesasEstado, globalNumber);

        const tieneCarrito = !!carritoResult.data;
        const estadoMesa = estadoResult.data;

        // 🔥【cart 身份验证】如果 cart 不属于本桌位（cart_gtn 不匹配），丢弃被污染的 cart
        if (estadoMesa && estadoMesa.cart && estadoMesa.cart_gtn !== undefined && estadoMesa.cart_gtn !== globalNumber) {
          estadoMesa.cart = null;
        }

        // 确定餐桌状态
        let estado = 'libre';
        let estadoInfo = '';
        let estadoTime = '';
        let estadoTotal = '';
        let estadoTimeHtml = '';
        let estadoClasses = {};
        
        // 定义不同状态的样式和图标
        if (estadoMesa) {
          if (estadoMesa.estado === 'solicitud_cuenta') {
            estado = 'solicitud_cuenta';
            estadoClasses = {
              icon: '<i class="fas fa-receipt text-yellow-500 text-2xl"></i>',
              label: '<?php echo ruiyi_translate("Solicitud Cuenta", "Account Request", "请求结账"); ?>',
              bg: 'bg-gradient-to-br from-yellow-50 to-yellow-100 dark:from-yellow-900/80 dark:to-yellow-800/60',
              border: 'border-yellow-300 dark:border-yellow-700',
              text: 'text-yellow-800 dark:text-yellow-200',
              shadow: 'shadow-yellow-200 dark:shadow-yellow-900/30'
            };
            
            // 格式化订单信息
            if (estadoMesa.orderId) {
              const orderText = (window.RUIYI_TRANS && window.RUIYI_TRANS.order) ? window.RUIYI_TRANS.order : 'Orden';
              estadoInfo = `<div class="text-xs text-gray-600 dark:text-gray-400">${orderText} #${estadoMesa.orderId}</div>`;
            }
            
            // 时间显示已移除
            
            // 格式化金额信息
            if (estadoMesa.total) {
              estadoTotal = `€${parseFloat(estadoMesa.total).toFixed(2)}`;
            }
          } else if (estadoMesa.estado === 'liquidando') {
            estado = 'liquidando';
            // 🔥 获取自定义结算中颜色（背景+字体）
            const customSettlingColor = window.RUIYI_POS?.tableColors?.settling || '#ff540a';
            const customSettlingTextColor = window.RUIYI_POS?.tableColors?.settlingText || '#ffffff';
            estadoClasses = {
              icon: '<i class="fas fa-file-invoice text-2xl" style="color: ' + customSettlingTextColor + '"></i>',
              label: '<?php echo ruiyi_translate("Liquidando", "Settling", "结算中"); ?>',
              bg: '',
              customBg: customSettlingColor,
              customText: customSettlingTextColor,
              border: 'border-2 border-orange-400 dark:border-orange-600',
              text: '',
              shadow: 'shadow-orange-200 dark:shadow-orange-900/30'
            };

            // 🔥【2026-04-03】使用 total 字段（权威数据），不从 cart 计算
            let liquidandoTotal = 0;
            if (estadoMesa.total !== undefined && estadoMesa.total !== null && estadoMesa.total !== '') {
              liquidandoTotal = parseFloat(estadoMesa.total) || 0;
            } else if (estadoMesa.cart && Array.isArray(estadoMesa.cart) && estadoMesa.cart.length > 0) {
              liquidandoTotal = estadoMesa.cart.reduce((sum, item) => {
                const price = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
                return sum + (price * item.quantity);
              }, 0);
            }
            if (liquidandoTotal > 0) {
              const discountBadge = (estadoMesa.discount && estadoMesa.discount > 0)
                ? `<span class="discount-badge text-xs bg-red-500 text-white px-1 rounded ml-1">-${estadoMesa.discount}%</span>`
                : '';
              estadoTotal = `€${liquidandoTotal.toFixed(2)}${discountBadge}`;
            }

            // 🔥【2026-04-07】结算中状态也显示桌位订单时长（使用锁定起始时间）
            const _lockedStartTs2 = _resolveOrderStartTimestamp(mesaId, estadoMesa);
            if (window.RUIYI_POS_CONFIG && window.RUIYI_POS_CONFIG.showTableOrderTime && _lockedStartTs2) {
              const orderTimeMs2 = new Date(_lockedStartTs2).getTime();
              if (!isNaN(orderTimeMs2) && orderTimeMs2 > 0) {
                const elapsedMs2 = Date.now() - orderTimeMs2;
                if (elapsedMs2 >= 0) {
                  const totalMinutes2 = Math.floor(elapsedMs2 / 60000);
                  const hours2 = Math.floor(totalMinutes2 / 60);
                  const minutes2 = totalMinutes2 % 60;
                  const timeText2 = hours2 > 0 ? `${hours2}h ${minutes2}m` : `${minutes2}m`;
                  const _customTimeColor2 = window.RUIYI_POS?.tableColors?.timeText || '#6b7280';
                  estadoTimeHtml = `<div class="table-order-time text-xs mt-1" style="color:${_customTimeColor2}"><i class="far fa-clock mr-1"></i>${timeText2}</div>`;
                }
              }
            }
          } else if (estadoMesa.estado === 'preparando') {
            estado = 'preparando';
            estadoClasses = {
              icon: '<i class="fas fa-soup-can-ladle text-blue-500 text-2xl"></i>',
              label: '<?php echo ruiyi_translate("Preparando", "Preparing", "准备中"); ?>',
              bg: 'bg-gradient-to-br from-blue-50 to-blue-100 dark:from-blue-900/80 dark:to-blue-800/60',
              border: 'border-blue-300 dark:border-blue-700',
              text: 'text-blue-800 dark:text-blue-200',
              shadow: 'shadow-blue-200 dark:shadow-blue-900/30'
            };
            
            // 格式化订单信息
            if (estadoMesa.orderId) {
              const orderText = (window.RUIYI_TRANS && window.RUIYI_TRANS.order) ? window.RUIYI_TRANS.order : 'Orden';
              estadoInfo = `<div class="text-xs text-gray-600 dark:text-gray-400">${orderText} #${estadoMesa.orderId}</div>`;
            }
            
            // 时间显示已移除
            
            // 格式化金额信息
            if (estadoMesa.total) {
              estadoTotal = `€${parseFloat(estadoMesa.total).toFixed(2)}`;
            }
          } else if (estadoMesa.estado === 'ocupada') {
            estado = 'ocupada';
            // 🔥 获取自定义占用颜色（背景+字体）
            const customOccupiedColor = window.RUIYI_POS?.tableColors?.occupied || '#f75050';
            const customOccupiedTextColor = window.RUIYI_POS?.tableColors?.occupiedText || '#ffffff';
            estadoClasses = {
              icon: '<i class="fas fa-users text-2xl" style="color: ' + customOccupiedTextColor + '"></i>',
              label: '<?php echo ruiyi_translate("Ocupada", "Occupied", "占用"); ?>',
              bg: '', // 使用自定义颜色替代Tailwind类
              customBg: customOccupiedColor,
              customText: customOccupiedTextColor,
              border: 'border-red-300 dark:border-red-700',
              text: '', // 使用自定义字体颜色
              shadow: 'shadow-red-200 dark:shadow-red-900/30'
            };
            
            // 格式化订单信息
            if (estadoMesa.orderId) {
              const orderText = (window.RUIYI_TRANS && window.RUIYI_TRANS.order) ? window.RUIYI_TRANS.order : 'Orden';
              estadoInfo = `<div class="text-xs text-gray-600 dark:text-gray-400">${orderText} #${estadoMesa.orderId}</div>`;
            }

            // 🔥 桌位订单时长显示（根据设置开关决定是否展示）
            // 🔥【2026-04-07】使用锁定的订单起始时间，避免每次保存重置
            const _lockedStartTs = _resolveOrderStartTimestamp(mesaId, estadoMesa);
            if (window.RUIYI_POS_CONFIG && window.RUIYI_POS_CONFIG.showTableOrderTime && _lockedStartTs) {
              const orderTimeMs = new Date(_lockedStartTs).getTime();
              if (!isNaN(orderTimeMs) && orderTimeMs > 0) {
                const elapsedMs = Date.now() - orderTimeMs;
                if (elapsedMs >= 0) {
                  const totalMinutes = Math.floor(elapsedMs / 60000);
                  const hours = Math.floor(totalMinutes / 60);
                  const minutes = totalMinutes % 60;
                  const timeText = hours > 0 ? `${hours}h ${minutes}m` : `${minutes}m`;
                  const _customTimeColor = window.RUIYI_POS?.tableColors?.timeText || '#6b7280';
                  estadoTimeHtml = `<div class="table-order-time text-xs mt-1" style="color:${_customTimeColor}"><i class="far fa-clock mr-1"></i>${timeText}</div>`;
                }
              }
            }

            // 🔥 格式化金额信息 - 显示桌位总金额
            // 🔥【2026-04-03 关键修复】桌位卡片始终使用 total 字段显示价格
            // total 来自服务器（权威数据），不会因 cart 跨桌污染而显示错误
            // cart 仅在进入桌位时用于恢复购物车，不再用于卡片价格计算
            let totalValue = 0;

            if (estadoMesa.total !== undefined && estadoMesa.total !== null && estadoMesa.total !== '') {
              totalValue = parseFloat(estadoMesa.total) || 0;
              // 🔥 DEBUG: 检测 cart 和 total 不一致
              if (estadoMesa.cart && Array.isArray(estadoMesa.cart) && estadoMesa.cart.length > 0) {
                const _cartCalc = estadoMesa.cart.reduce((s, i) => s + (parseFloat(i.customPrice !== undefined ? i.customPrice : (i.price||0)) * i.quantity), 0);
                if (Math.abs(_cartCalc - totalValue) > 0.5) {
                  console.warn(`[渲染DEBUG] ⚠️ 桌位 ${mesaId} (gtn ${globalNumber}): total=${totalValue} cart计算=${_cartCalc.toFixed(2)} → 使用total（权威数据）`);
                }
              }
            } else if (estadoMesa.cart && Array.isArray(estadoMesa.cart) && estadoMesa.cart.length > 0) {
              // Fallback: 没有 total 时从 cart 计算（离线订单场景）
              totalValue = estadoMesa.cart.reduce((sum, item) => {
                const price = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
                return sum + (price * item.quantity);
              }, 0);
            }

            if (totalValue > 0) {
              // 🔥 如果有折扣，添加折扣标识
              const discountBadge = (estadoMesa.discount && estadoMesa.discount > 0)
                ? `<span class="discount-badge text-xs bg-red-500 text-white px-1 rounded ml-1">-${estadoMesa.discount}%</span>`
                : '';
              estadoTotal = `€${totalValue.toFixed(2)}${discountBadge}`;
            } else {
              console.warn(`[餐桌渲染] ⚠️ 桌位 ${mesaId} 总额为0或未设置`, estadoMesa);
            }
          } else if (estadoMesa.estado === 'libre') { // <-- 添加这个条件判断
            estado = 'libre';
            // 🔥 获取自定义空闲颜色（背景+字体）
            const customFreeColor1 = window.RUIYI_POS?.tableColors?.free || '#2d9551';
            const customFreeTextColor1 = window.RUIYI_POS?.tableColors?.freeText || '#ffffff';
            estadoClasses = {
              icon: '<i class="fas fa-check-circle text-2xl" style="color: ' + customFreeTextColor1 + '"></i>',
              label: '<?php echo ruiyi_translate("Libre", "Free", "空闲"); ?>',
              bg: '', // 使用自定义颜色替代Tailwind类
              customBg: customFreeColor1,
              customText: customFreeTextColor1,
              border: 'border-2 border-green-400 dark:border-green-600',
              text: '', // 使用自定义字体颜色
              shadow: 'shadow-green-200 dark:shadow-green-900/30'
            };
            // 对于 libre 状态，清空其他信息
            estadoInfo = '';
            estadoTime = '';
            estadoTotal = '';
          } else {
            // 如果状态未知或为空，也默认为 libre
            estado = 'libre';
            // 🔥 获取自定义空闲颜色（背景+字体）
            const customFreeColor2 = window.RUIYI_POS?.tableColors?.free || '#2d9551';
            const customFreeTextColor2 = window.RUIYI_POS?.tableColors?.freeText || '#ffffff';
            estadoClasses = {
              icon: '<i class="fas fa-check-circle text-2xl" style="color: ' + customFreeTextColor2 + '"></i>',
              label: '<?php echo ruiyi_translate("Libre", "Free", "空闲"); ?>',
              bg: '', // 使用自定义颜色替代Tailwind类
              customBg: customFreeColor2,
              customText: customFreeTextColor2,
              border: 'border-2 border-green-400 dark:border-green-600',
              text: '', // 使用自定义字体颜色
              shadow: 'shadow-green-200 dark:shadow-green-900/30'
            };
          }
        } else if (tieneCarrito) {
          estado = 'pendiente';
          estadoClasses = {
            icon: '<i class="fas fa-shopping-basket text-amber-500 text-2xl"></i>',
            label: '<?php echo ruiyi_translate("Pendiente", "Pending", "待处理"); ?>',
            bg: 'bg-gradient-to-br from-amber-50 to-amber-100 dark:from-amber-900/80 dark:to-amber-800/60',
            border: 'border-amber-300 dark:border-amber-700',
            text: 'text-amber-800 dark:text-amber-200',
            shadow: 'shadow-amber-200 dark:shadow-amber-900/30'
          };
          
          const carrito = carritoResult.data;
          // 计算购物车中的商品数量
          const itemCount = carrito && carrito.carrito ? carrito.carrito.length : 0;
          
          estadoInfo = `${itemCount} <?php echo ruiyi_translate("artículos", "items", "项目"); ?>`;
          
          // 时间显示已移除
          
          // 计算购物车总金额（含 supplements）
          if (carrito.carrito && carrito.carrito.length > 0) {
            const subtotal = carrito.carrito.reduce((sum, item) => {
              const price = parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0));
              return sum + (price * item.quantity);
            }, 0);
            const total = subtotal - (carrito.descuento || 0);
            estadoTotal = `€${total.toFixed(2)}`;
          }
        } else {
          // 自由状态 - 添加更明显的边框
          // 🔥 获取自定义空闲颜色（背景+字体）
          const customFreeColor3 = window.RUIYI_POS?.tableColors?.free || '#2d9551';
          const customFreeTextColor3 = window.RUIYI_POS?.tableColors?.freeText || '#ffffff';
          estadoClasses = {
            icon: '<i class="fas fa-check-circle text-2xl" style="color: ' + customFreeTextColor3 + '"></i>',
            label: '<?php echo ruiyi_translate("Libre", "Free", "空闲"); ?>',
            bg: '', // 使用自定义颜色替代Tailwind类
            customBg: customFreeColor3,
            customText: customFreeTextColor3,
            border: 'border-2 border-green-400 dark:border-green-600',
            text: '', // 使用自定义字体颜色
            shadow: 'shadow-green-200 dark:shadow-green-900/30'
          };
        }

        // 获取该桌位所有未结账订单的合并价格 - 使用AJAX实时获取
        let totalMesaHtml = '';
        
        // 使用临时变量存储AJAX异步加载的数据ID，后续异步更新
        const mesaDataId = `mesa-total-${index}`;
        
        const mesaElement = document.createElement('div');
        mesaElement.className = `mesa-item relative ${estadoClasses.bg} ${estadoClasses.border} ${estadoClasses.text} border rounded-lg p-1 shadow-sm hover:shadow-md transition-all cursor-pointer`;
        // 🔥 如果有自定义背景颜色，应用内联样式
        if (estadoClasses.customBg) {
          mesaElement.style.backgroundColor = estadoClasses.customBg;
        }
        // 🔥 如果有自定义字体颜色，应用内联样式
        if (estadoClasses.customText) {
          mesaElement.style.color = estadoClasses.customText;
        }
        mesaElement.setAttribute('data-mesa', mesaId);
        mesaElement.setAttribute('data-estado', estado);
        
        // 获取显示名称：分类过滤时显示分类名称，全部显示时显示Mesa编号
        const tableDisplayName = displayName || mesaId;

        // 🔥 桌位名称分行显示处理
        const nameSplitEnabled = window.RUIYI_POS_CONFIG?.tableNameSplit || false;
        let tableNameHtml = escapeHtml(tableDisplayName);
        if (nameSplitEnabled && tableDisplayName) {
          // 将名称拆分为文字前缀和数字后缀
          const splitMatch = tableDisplayName.match(/^([a-zA-Z\u4e00-\u9fff]+[\s\-]*?)(\d+)$/);
          if (splitMatch && splitMatch[1]) {
            const zonePart = splitMatch[1].trim();
            const numberPart = splitMatch[2];
            tableNameHtml = `<span class="table-zone-name block">${escapeHtml(zonePart)}</span><span class="table-zone-number block">${numberPart}</span>`;
          }
        }

        // 🔥 获取该桌位的 delivery 客户数据
        const deliveryCustomerData = getDeliveryCustomerData(mesaId);
        // 🔥 只在桌位非空闲状态时显示电话号码
        const isTableOccupied = estado !== 'libre';
        const deliveryPhoneColor = window.RUIYI_POS?.tableColors?.deliveryPhoneText || '#2563eb';
        const customerPhoneHtml = isTableOccupied && deliveryCustomerData && deliveryCustomerData.phone
          ? `<div class="text-xs mt-1 flex items-center justify-center gap-1" style="color:${deliveryPhoneColor}">
              <i class="fas fa-phone text-xs"></i>
              <span>${escapeHtml(deliveryCustomerData.phone)}</span>
            </div>`
          : '';

        // 根据状态决定布局
        if (estado === 'ocupada' || estado === 'solicitud_cuenta' || estado === 'liquidando') {
          // 占用状态/结算中 - 紧凑布局，移除图标
          // 🔥 如果有自定义文字颜色，使用inherit继承父容器颜色；否则使用默认颜色
          const hasCustomTextColor = estadoClasses.customText;
          const statusColorClass = hasCustomTextColor ? '' : 'text-yellow-600';
          const priceColorClass = hasCustomTextColor ? '' : (estado === 'ocupada' ? 'text-red-600' : 'text-yellow-700');
          const statusLabelHtml = (estado === 'ocupada' && window.RUIYI_POS_CONFIG?.showOccupiedTableStatus === false)
            ? ''
            : `<p class="table-status text-xs ${statusColorClass}">${estadoClasses.label}</p>`;
          mesaElement.innerHTML = `
            <div class="text-center h-full flex flex-col justify-center p-1">
              <h4 class="table-name text-xs font-bold">${tableNameHtml}</h4>
              ${statusLabelHtml}
              ${estadoTotal ? `<div id="${mesaDataId}" class="table-price text-xs font-semibold ${priceColorClass} flex items-center justify-center mt-1">
                ${estadoTotal}
              </div>` : ''}
              ${estadoTimeHtml}
              ${customerPhoneHtml}
            </div>
          `;
        } else if (tieneCarrito) {
          // 有购物车但未占用 - 紧凑布局，移除图标
          mesaElement.innerHTML = `
            <div class="text-center h-full flex flex-col justify-center p-1">
              <h4 class="table-name text-xs font-bold">${tableNameHtml}</h4>
              <p class="table-status text-xs text-amber-600">${estadoClasses.label}</p>
              ${estadoTotal ? `<p class="table-price text-xs font-semibold text-amber-700">${estadoTotal}</p>` : ''}
              ${customerPhoneHtml}
            </div>
          `;
        } else {
          // 空闲状态 - 紧凑布局，移除图标
          mesaElement.innerHTML = `
            <div class="text-center h-full flex flex-col justify-center p-1">
              <h4 class="table-name text-xs font-bold mb-1">${tableNameHtml}</h4>
              <p class="table-status text-xs">${estadoClasses.label}</p>
              ${customerPhoneHtml}
            </div>
          `;
        }
        
        // 🍽️ 自助餐开台弹窗 — 输入各类就餐人数
        async function showBuffetOpenTablePopup(tableName) {
            const menuTypes = window.buffetMenuTypes || [];
            if (!menuTypes.length) return { confirmed: true, items: [] };

            // 🌐 多语言翻译
            const lang = (typeof getCurrentLanguageFromCookie === 'function') ? getCurrentLanguageFromCookie() : (PHP_LANG || 'zh');
            const t18n = {
                title:   lang === 'zh' ? '开台' : (lang === 'en' ? 'Open Table' : 'Abrir Mesa'),
                subtitle: lang === 'zh' ? '设置就餐人数开始点餐' : (lang === 'en' ? 'Set number of guests to start' : 'Configurar comensales para empezar'),
                confirm: lang === 'zh' ? '确认开台' : (lang === 'en' ? 'Confirm' : 'Confirmar'),
                cancel:  lang === 'zh' ? '取消' : (lang === 'en' ? 'Cancel' : 'Cancelar'),
            };

            const now = new Date();
            const timeStr = now.getHours().toString().padStart(2,'0') + ':' + now.getMinutes().toString().padStart(2,'0');
            const dayNames = lang === 'zh'
                ? ['周日','周一','周二','周三','周四','周五','周六']
                : (lang === 'en' ? ['Sun','Mon','Tue','Wed','Thu','Fri','Sat']
                : ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb']);
            const dayStr = dayNames[now.getDay()];

            const typesWithPrice = menuTypes.map((mt, idx) => {
                const info = window.getBuffetTimePeriodPrice(mt);
                return { ...mt, currentPrice: info.price, periodName: info.periodName, idx };
            });

            const periodLabel = typesWithPrice.find(t => t.periodName)?.periodName || '';

            let rowsHtml = typesWithPrice.map(t => `
                <div onclick="buffetQtyChange(${t.idx},1)" style="display:flex;align-items:center;justify-content:space-between;padding:18px 20px;background:#F5F4F1;border-radius:16px;cursor:pointer;user-select:none;transition:background 0.15s;"
                    onmouseover="this.style.background='#EEEDE9'" onmouseout="this.style.background='#F5F4F1'">
                    <div style="display:flex;flex-direction:column;gap:4px;flex:1;min-width:0;">
                        <div style="font-weight:600;font-size:15px;color:#1A1918;font-family:system-ui,-apple-system,sans-serif;">${t.name}</div>
                        <div style="font-size:12px;color:#9C9B99;font-family:system-ui,-apple-system,sans-serif;">€${t.currentPrice.toFixed(2)}${t.periodName ? ' /' + t.periodName : ''}</div>
                    </div>
                    <div style="display:flex;align-items:center;gap:12px;flex-shrink:0;" onclick="event.stopPropagation()">
                        <button type="button" onclick="buffetQtyChange(${t.idx},-1)" style="width:34px;height:34px;border-radius:50%;border:1px solid #E5E4E1;background:#FFFFFF;font-size:18px;cursor:pointer;display:flex;align-items:center;justify-content:center;color:#6D6C6A;line-height:1;">−</button>
                        <input type="number" id="buffet_qty_${t.idx}" value="0" min="0" max="99"
                            onchange="buffetQtyValidate(${t.idx})" onclick="event.stopPropagation()"
                            style="width:32px;text-align:center;font-size:20px;font-weight:700;color:#1A1918;border:none;background:transparent;font-family:system-ui,-apple-system,sans-serif;-moz-appearance:textfield;" />
                        <button type="button" onclick="buffetQtyChange(${t.idx},1)" style="width:34px;height:34px;border-radius:50%;border:none;background:#E84D25;font-size:18px;cursor:pointer;display:flex;align-items:center;justify-content:center;color:#FFFFFF;line-height:1;">+</button>
                    </div>
                </div>
            `).join('');

            // 辅助函数挂到 window
            window.buffetQtyChange = function(idx, delta) {
                const inp = document.getElementById('buffet_qty_' + idx);
                if (!inp) return;
                let v = parseInt(inp.value) || 0;
                v = Math.max(0, Math.min(99, v + delta));
                inp.value = v;
            };
            window.buffetQtyValidate = function(idx) {
                const inp = document.getElementById('buffet_qty_' + idx);
                if (!inp) return;
                let v = parseInt(inp.value) || 0;
                inp.value = Math.max(0, Math.min(99, v));
            };

            const result = await Swal.fire({
                html: `
                    <div style="margin:-20px -20px 0;">
                        <!-- Header -->
                        <div style="display:flex;align-items:center;justify-content:space-between;padding:20px 24px;border-bottom:1px solid #E5E4E1;">
                            <div style="display:flex;align-items:center;gap:12px;">
                                <div style="width:40px;height:40px;border-radius:12px;background:#FFF5F3;display:flex;align-items:center;justify-content:center;">
                                    <span style="color:#E84D25;font-size:20px;">🍽</span>
                                </div>
                                <div>
                                    <div style="font-weight:700;font-size:16px;color:#1A1918;font-family:system-ui,-apple-system,sans-serif;">${t18n.title} · ${tableName}</div>
                                    <div style="font-size:12px;color:#9C9B99;font-family:system-ui,-apple-system,sans-serif;">${t18n.subtitle}</div>
                                </div>
                            </div>
                            <button type="button" onclick="Swal.close()" style="width:32px;height:32px;border-radius:50%;background:#F5F4F1;border:none;cursor:pointer;display:flex;align-items:center;justify-content:center;color:#6D6C6A;font-size:16px;">✕</button>
                        </div>
                        <!-- Body -->
                        <div style="padding:24px;max-height:60vh;overflow-y:auto;">
                            <div style="display:flex;align-items:center;gap:8px;margin-bottom:24px;">
                                <span style="color:#9C9B99;font-size:14px;">🕐</span>
                                <span style="font-size:13px;color:#9C9B99;font-family:system-ui,-apple-system,sans-serif;">${dayStr} ${timeStr}${periodLabel ? ' — ' + periodLabel : ''}</span>
                            </div>
                            <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:12px;">
                                ${rowsHtml}
                            </div>
                        </div>
                        <!-- Footer -->
                        <div style="display:flex;justify-content:flex-end;gap:12px;padding:16px 24px 24px;border-top:1px solid #E5E4E1;">
                            <button type="button" onclick="Swal.close()" style="height:44px;padding:0 24px;border-radius:12px;background:#F5F4F1;border:none;cursor:pointer;font-size:14px;font-weight:500;color:#6D6C6A;font-family:system-ui,-apple-system,sans-serif;">${t18n.cancel}</button>
                            <button type="button" id="buffet-confirm-btn" style="height:44px;padding:0 28px;border-radius:12px;background:#E84D25;border:none;cursor:pointer;font-size:14px;font-weight:600;color:#FFFFFF;font-family:system-ui,-apple-system,sans-serif;display:flex;align-items:center;gap:8px;box-shadow:0 4px 12px rgba(232,77,37,0.19);">
                                <span style="font-size:16px;">✓</span> ${t18n.confirm}
                            </button>
                        </div>
                    </div>
                `,
                showConfirmButton: false,
                showCancelButton: false,
                showCloseButton: false,
                width: '860px',
                padding: 0,
                background: '#FFFFFF',
                customClass: { popup: 'buffet-open-table-popup' },
                didOpen: () => {
                    const popup = Swal.getPopup();
                    if (popup) popup.style.borderRadius = '24px';
                    document.getElementById('buffet-confirm-btn')?.addEventListener('click', () => {
                        Swal.clickConfirm();
                    });
                },
                preConfirm: () => {
                    const items = [];
                    typesWithPrice.forEach(t => {
                        const qty = parseInt(document.getElementById('buffet_qty_' + t.idx)?.value) || 0;
                        if (qty > 0) {
                            items.push({
                                product_id: t.product_id,
                                type_name: t.name,
                                quantity: qty,
                                price: t.currentPrice,
                                period_name: t.periodName
                            });
                        }
                    });
                    return items;
                }
            });

            if (result.isConfirmed) {
                return { confirmed: true, items: result.value || [] };
            }
            return { confirmed: false, items: [] };
        }

        // 🍽️ 将开台商品添加到购物车
        function addBuffetOpenTableItemsToCart(items) {
            items.forEach(item => {
                // 尝试从DOM获取产品信息
                const card = document.querySelector(`.product-card[data-id="${item.product_id}"]`);
                const name_es = card?.dataset.nameEs || card?.dataset.name || item.type_name;
                const name_zh = card?.dataset.nameZh || '';
                const name_en = card?.dataset.nameEn || '';
                const taxRate = card ? parseFloat(card.dataset.taxRate || 0) : 0;
                const image_url = card?.dataset.imageUrl || card?.querySelector('img')?.src || '';

                const cartItem = {
                    id: item.product_id,
                    name: name_es,
                    name_es: name_es,
                    name_zh: name_zh,
                    name_en: name_en,
                    price: item.price,
                    originalPrice: item.price,
                    basePrice: item.price,
                    customPrice: item.price,
                    quantity: item.quantity,
                    addedQuantity: 0, // 🍽️ 开台商品不触发厨房打印
                    taxRate: taxRate,
                    image_url: image_url,
                    is_buffet: false,
                    is_buffet_opening: true,
                    locked: false,
                    isNew: false
                };
                cart.push(cartItem);
            });
            selectedCartItemIndex = cart.length - 1;
            window.selectedCartItemIndex = cart.length - 1;
            renderCart({ scrollToBottom: true });
        }

        // 添加触摸和点击事件处理
        let touchStartX, touchStartY, touchStartTime;
        let touchMoved = false;

        // 统一的桌位选择处理函数
        async function handleTableSelection(e, element) {
          // 如果点击的是按钮，不处理
          if ((e.target && e.target.classList && (
                e.target.classList.contains('liberar-mesa') ||
                e.target.classList.contains('procesar-pago') ||
                e.target.classList.contains('ver-mesa') ||
                e.target.classList.contains('split-billing-mesa') ||
                e.target.classList.contains('table-kitchen-print-btn'))) ||
              (e.target && e.target.parentElement && e.target.parentElement.classList && (
                e.target.parentElement.classList.contains('liberar-mesa') ||
                e.target.parentElement.classList.contains('procesar-pago') ||
                e.target.parentElement.classList.contains('ver-mesa') ||
                e.target.parentElement.classList.contains('split-billing-mesa') ||
                e.target.parentElement.classList.contains('table-kitchen-print-btn')))) {
            return;
          }

          const mesaSeleccionada = element.getAttribute('data-mesa');
          const estadoMesa = element.getAttribute('data-estado');

          // 🔥 点击桌位时隐藏桌位模块的上一单信息
          if (typeof hideMesasLastOrderInfo === 'function') {
            hideMesasLastOrderInfo();
          }

          // 🔥 选择新桌位前，自动保存当前桌位的未保存订单
          const currentTable = document.getElementById('table-number')?.value.trim();
          if (currentTable && currentTable !== mesaSeleccionada) {
            await autoSaveTableOrder();
          }
          
          // 如果桌位是占用状态或结算中状态，直接调用查看功能
          if (estadoMesa === 'ocupada' || estadoMesa === 'solicitud_cuenta' || estadoMesa === 'liquidando') {
            viewTableOrder(mesaSeleccionada);
            return;
          }

          // 🔥 检查是否是 delivery 区域，如果是则先弹出客户信息输入框
          if (isDeliveryZoneTable(mesaSeleccionada)) {
            const proceed = await promptDeliveryCustomerInfo(mesaSeleccionada);
            if (!proceed) {
              return;
            }
          }

          // 🍽️ 自助餐开台：空闲桌位 + 自助餐模式 + 非外送区域 → 弹窗输入就餐人数
          if (window.buffetConfig && window.buffetConfig.enabled &&
              !isDeliveryZoneTable(mesaSeleccionada) &&
              estadoMesa !== 'ocupada' && estadoMesa !== 'solicitud_cuenta') {
            const buffetResult = await showBuffetOpenTablePopup(mesaSeleccionada);
            if (!buffetResult.confirmed) return;
            handleTableSelectionConfirmed(mesaSeleccionada, estadoMesa);
            if (buffetResult.items.length > 0) {
              setTimeout(() => addBuffetOpenTableItemsToCart(buffetResult.items), 100);
            }
            return;
          }

          // 直接确认选择桌位，跳过确认弹窗
          handleTableSelectionConfirmed(mesaSeleccionada, estadoMesa);
        }
        
        // 触摸开始
        mesaElement.addEventListener('touchstart', function(e) {
          if (e.touches.length === 1) {
            touchStartX = e.touches[0].clientX;
            touchStartY = e.touches[0].clientY;
            touchStartTime = Date.now();
            touchMoved = false;
          }
        }, { passive: true });
        
        // 触摸移动
        mesaElement.addEventListener('touchmove', function(e) {
          if (e.touches.length === 1 && touchStartX && touchStartY) {
            const touchX = e.touches[0].clientX;
            const touchY = e.touches[0].clientY;
            const deltaX = Math.abs(touchX - touchStartX);
            const deltaY = Math.abs(touchY - touchStartY);
            
            // 如果移动距离超过10px，标记为移动
            if (deltaX > 10 || deltaY > 10) {
              touchMoved = true;
            }
          }
        }, { passive: true });
        
        // 触摸结束
        mesaElement.addEventListener('touchend', function(e) {
          if (touchStartTime) {
            const touchDuration = Date.now() - touchStartTime;
            
            // 只有在没有移动且时间短于800ms时才视为点击
            if (!touchMoved && touchDuration < 800 && touchDuration > 100) {
              e.preventDefault(); // 防止触发click事件
              handleTableSelection(e, this);
            }
          }
          
          // 重置触摸状态
          touchStartX = touchStartY = touchStartTime = null;
          touchMoved = false;
        });
        
        // 添加点击事件（用于非触屏设备）
        mesaElement.addEventListener('click', function(e) {
          // 检查是否是触摸触发的点击事件（通过detail属性判断）
          if (e.detail === 0 && touchStartTime) {
            return; // 如果是触摸触发的点击事件，则忽略
          }
          handleTableSelection(e, this);
        });
        
        // 添加查看按钮事件
        mesaElement.querySelector('.ver-mesa')?.addEventListener('click', function(e) {
          e.stopPropagation();
          const mesa = this.closest('.mesa-item').getAttribute('data-mesa');
          // 调用查看桌位订单功能
          viewTableOrder(mesa);
        });
        
        // 添加释放按钮事件
        mesaElement.querySelector('.liberar-mesa')?.addEventListener('click', function(e) {
          e.stopPropagation();
          const mesa = this.closest('.mesa-item').getAttribute('data-mesa');
          liberarMesa(mesa);
        });
        
        // 添加分单按钮事件 (统一版本)
        const splitButton = mesaElement.querySelector('.split-billing-mesa');
        if (splitButton) {
          
          // 添加悬停效果来确认按钮可点击
          splitButton.addEventListener('mouseenter', function() {
            this.style.transform = 'scale(1.05)';
          });
          
          splitButton.addEventListener('mouseleave', function() {
            this.style.transform = 'scale(1)';
          });
          
          // 主点击事件
          splitButton.addEventListener('click', function(e) {
            
            e.stopPropagation();
            e.preventDefault();
            e.stopImmediatePropagation();
            
            
            const mesa = this.getAttribute('data-mesa');
            
            // 确保函数存在并调用
            if (typeof initiateSplitBilling === 'function') {
              try {
                initiateSplitBilling(mesa);
              } catch (error) {
              }
            } else {
            }
            
            return false;
          }, true);
          
        } else {
        }
        
        // 将元素添加到fragment而不是直接添加到DOM
        fragment.appendChild(mesaElement);

        // 🔥 性能优化：移除单桌位AJAX请求
        // 桌位金额现在完全依赖 localStorage.mesas_estado（由 fetchAndUpdateTableStatuses 每30秒批量更新）
        // 这将 N个桌位 = N次请求 优化为 所有桌位 = 1次批量请求/30秒
      });
      
      // 清空网格
      mesasGrid.innerHTML = '';

      // 🔥 按区域分组显示：在"所有桌位"视图中，按分类分组并添加区域标题
      const groupByZone = window.RUIYI_POS_CONFIG?.tableGroupByZone && currentCategoryFilter === 'all';

      if (groupByZone && tablesToRender.length > 0 && tablesToRender.some(t => t.categoryId)) {
        // 按 categoryId 分组
        const zoneGroups = {};
        const zoneOrder = [];
        tablesToRender.forEach((table, idx) => {
          const catId = table.categoryId || 0;
          if (!zoneGroups[catId]) {
            zoneGroups[catId] = [];
            zoneOrder.push(catId);
          }
          zoneGroups[catId].push(idx);
        });

        // 获取 fragment 中的所有元素（按 tablesToRender 顺序）
        const allElements = Array.from(fragment.children);

        zoneOrder.forEach((catId, zoneIdx) => {
          // 添加区域标题分隔
          const categoryInfo = catId ? getCategoryInfoById(catId) : null;
          const zoneName = categoryInfo
            ? (categoryInfo.display_name || categoryInfo.name_es || categoryInfo.name_en || categoryInfo.name || '')
            : '';

          if (zoneName) {
            const headerEl = document.createElement('div');
            headerEl.className = 'col-span-full';
            headerEl.innerHTML = `
              <div class="flex items-center ${zoneIdx > 0 ? 'mt-4' : ''} mb-2">
                <div class="h-px flex-1 bg-gray-300"></div>
                <span class="px-3 text-sm font-bold text-gray-500 uppercase tracking-wider flex items-center gap-2">
                  <i class="fas fa-map-marker-alt text-xs"></i>${escapeHtml(zoneName)}
                </span>
                <div class="h-px flex-1 bg-gray-300"></div>
              </div>
            `;
            mesasGrid.appendChild(headerEl);
          }

          // 添加该分区的桌位
          zoneGroups[catId].forEach(idx => {
            if (allElements[idx]) {
              mesasGrid.appendChild(allElements[idx]);
            }
          });
        });
      } else {
        // 默认：一次性添加所有元素
        mesasGrid.appendChild(fragment);
      }

      // 如果没有餐桌显示空状态提示
      if (tablesToRender.length === 0 && currentCategoryFilter !== 'all') {
        mesasGrid.innerHTML = `
          <div class="col-span-full text-center py-8 text-gray-500">
            <i class="fas fa-filter text-4xl mb-3"></i>
            <p>${getTranslation('no_category_tables', 'No hay mesas en esta categoría')}</p>
          </div>
        `;
      }
      
      // 不再重复调用过滤函数，避免无限循环渲染导致闪烁
      // 过滤器已通过 window.currentTableFilter 传递给渲染函数
    }

    // 增强版刷新功能：自动检测和清理异常桌位状态
    function refreshTablesWithAutoCleanup() {
      
      // 显示进度提示
      Swal.fire({
        title: '<?php echo ruiyi_translate("Verificar estado de mesa", "Checking table status", "检测桌位状态"); ?>',
        text: '<?php echo ruiyi_translate("Verificando estado de pedidos de todas las mesas...", "Verifying order status for all tables...", "正在验证所有桌位的订单状态..."); ?>',
        allowOutsideClick: false,
        didOpen: () => {
          Swal.showLoading();
        }
      });
      
      // 调用批量状态检测API
      fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          action: 'ruiyi_batch_check_table_status',
          nonce: ajaxNonce
        })
      })
      .then(response => response.json())
      .then(data => {
        if (data.success) {
          const results = data.data;
          
          // 处理需要清理的异常桌位
          if (results.abnormal_tables && results.abnormal_tables.length > 0) {
            cleanupAbnormalTables(results.abnormal_tables, results.table_status_map);
          } else {
            Swal.fire({
              icon: 'success',
              title: '✅ <?php echo ruiyi_translate("Estado Normal", "Status Normal", "状态正常"); ?>',
              text: '<?php echo ruiyi_translate("Todos los estados de mesa coinciden con pedidos reales", "All table statuses match actual orders", "所有桌位状态与实际订单一致"); ?>',
              timer: 2000,
              showConfirmButton: false
            });
          }
          
          // 最后刷新桌位显示
          if (typeof renderizarMesas === 'function') {
            renderizarMesas('auto-cleanup-refresh');
          }
          
        } else {
          console.error('[自动清理] 检测失败:', data.message);
          Swal.fire({
            icon: 'error',
            title: '❌ <?php echo ruiyi_translate("Detección Fallida", "Detection Failed", "检测失败"); ?>',
            text: data.message || '<?php echo ruiyi_translate("No se puede detectar el estado de la mesa", "Unable to detect table status", "无法检测桌位状态"); ?>'
          });
        }
      })
      .catch(error => {
        console.error('[自动清理] 网络错误:', error);
        Swal.fire({
          icon: 'error',
          title: '❌ <?php echo ruiyi_translate("Error de Red", "Network Error", "网络错误"); ?>',
          text: '<?php echo ruiyi_translate("No se puede conectar al servidor", "Unable to connect to server", "无法连接到服务器"); ?>'
        });
      });
    }

    // 清理异常桌位状态
    function cleanupAbnormalTables(abnormalTables, tableStatusMap) {
      
      Swal.fire({
        icon: 'warning',
        title: '🔍 <?php echo ruiyi_translate("Estado Anormal Detectado", "Abnormal Status Detected", "发现异常状态"); ?>',
        html: `
          <p><?php echo ruiyi_translate("Encontrado", "Found", "发现"); ?> <strong>${abnormalTables.length}</strong> <?php echo ruiyi_translate("mesas que muestran ocupado pero sin pedidos reales", "tables showing occupied but no actual orders", "个桌位显示为占用但无实际订单"); ?>:</p>
          <div class="text-left mt-3 max-h-32 overflow-y-auto">
            ${abnormalTables.map(table => `<div class="text-sm">• ${table}</div>`).join('')}
          </div>
        `,
        showCancelButton: true,
        confirmButtonText: '<?php echo ruiyi_translate("Limpieza Automática", "Auto Clean", "自动清理"); ?>',
        cancelButtonText: '<?php echo ruiyi_translate("Cancelar", "Cancel", "取消"); ?>',
        confirmButtonColor: '#10b981'
      }).then((result) => {
        if (result.isConfirmed) {
          executeAutoCleanup(abnormalTables, tableStatusMap);
        } else {
          // 用户取消，只刷新显示
          if (typeof renderizarMesas === 'function') {
            renderizarMesas('manual-refresh');
          }
        }
      });
    }

    // 执行自动清理
    function executeAutoCleanup(abnormalTables, tableStatusMap) {
      
      // 显示清理进度
      Swal.fire({
        title: '🧹 <?php echo ruiyi_translate("Limpiando", "Cleaning", "正在清理"); ?>',
        text: `<?php echo ruiyi_translate("Limpiando", "Cleaning", "正在清理"); ?> ${abnormalTables.length} <?php echo ruiyi_translate("mesas anormales", "abnormal tables", "个异常桌位"); ?>...`,
        allowOutsideClick: false,
        didOpen: () => {
          Swal.showLoading();
        }
      });
      
      const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
      let cleanedCount = 0;

      abnormalTables.forEach(tableDisplayName => {
        // 🔥 【关键修复】统一使用 "Mesa" 格式
        const tableNumber = resolveGlobalTableNumber(tableDisplayName);
        const mesaKey = `Mesa ${tableNumber}`;

        // 清理旧格式的条目
        ['餐桌', 'Table'].forEach(prefix => {
          const oldKey = `${prefix} ${tableNumber}`;
          if (mesasEstado[oldKey]) {
            delete mesasEstado[oldKey];
          }
        });
        
        // 更新localStorage状态
        mesasEstado[mesaKey] = {
          estado: 'libre',
          orderId: null,
          total: 0,
          orderCount: 0,
          timestamp: new Date().toISOString(),
          _cleanedUp: true // 标记为已清理
        };
        
        cleanedCount++;
        
        // 同步状态到服务器
        const numericTableNumber = resolveGlobalTableNumber(tableNumber);
        updateTableStatusToServer(numericTableNumber, 'available', null, 0);
      });
      
      // 保存更新的状态
      localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
      
      // 显示清理结果
      Swal.fire({
        icon: 'success',
        title: '✅ <?php echo ruiyi_translate("Limpieza Completa", "Cleanup Complete", "清理完成"); ?>',
        text: `<?php echo ruiyi_translate("Limpiado", "Cleaned", "已清理"); ?> ${cleanedCount} <?php echo ruiyi_translate("mesas anormales", "abnormal tables", "个异常桌位"); ?>`,
        timer: 3000,
        showConfirmButton: false
      });
      
      // 刷新桌位显示
      setTimeout(() => {
        if (typeof renderizarMesas === 'function') {
          renderizarMesas('post-cleanup-refresh');
        }
      }, 500);
    }

    // 异步加载桌位总金额
    function loadTableTotalAmount(tableId, elementId) {
      // 获取显示元素
      const totalElement = document.getElementById(elementId);
      if (!totalElement) return;

      // 🔥 离线模式：跳过AJAX请求，保留已从localStorage渲染的数据
      if (!navigator.onLine) {
        return;
      }

      // 🔥 预检查：在发送请求前先检查桌位状态
      const mesasEstadoPreCheck = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
      const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';

      // 标准化桌位键：提取纯数字桌号，统一为 "Mesa X" 格式（支持任意区域名称）
      const mesaKeyPreCheck = `Mesa ${resolveGlobalTableNumber(tableId)}`;

      const preCheckState = mesasEstadoPreCheck[mesaKeyPreCheck];

      // 如果桌位已经是空闲状态，完全跳过AJAX请求
      if (preCheckState && preCheckState.estado === 'libre') {
        totalElement.innerHTML = ``; // 清空显示
        return;
      }

      // 发送异步请求获取该桌位所有未结账订单
      fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          action: 'ruiyi_pos_get_table_orders',
          table_number: tableId,
          nonce: ajaxNonce
        })
      })
      .then(response => {
        if (!response.ok) {
          throw new Error(`Network error: ${response.status}`);
        }
        return response.json();
      })
      .then(data => {
        if (data.success) {
          // 获取嵌套数据结构
          const responseData = data.data || {};
          const backendOrders = responseData.orders || [];

          if (backendOrders.length > 0) {
            // 计算所有订单总金额
            let totalAmount = 0;
            backendOrders.forEach(order => {
              totalAmount += parseFloat(order.total);
            });

            // 🔥 双重检查：在更新状态前再次检查桌位是否已被清台
            const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
            const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';

            // 标准化桌位键：提取纯数字桌号，统一为 "Mesa X" 格式（支持任意区域名称）
            const mesaKey = `Mesa ${resolveGlobalTableNumber(tableId)}`;

            // 🔥 关键修复：检查当前桌位是否已经是空闲状态
            // 如果桌位已经被标记为空闲（说明已结账/清台），不要覆盖状态
            const currentState = mesasEstado[mesaKey];
            const isCurrentlyFree = currentState && currentState.estado === 'libre';

            if (isCurrentlyFree) {
              // 桌位已经空闲，不更新状态，避免覆盖正确的空闲状态
              totalElement.innerHTML = ``; // 清空显示
              return;
            }

            // 更新显示（仅价格，无图标）
            totalElement.innerHTML = `€${totalAmount.toFixed(2)}`;

            if (!mesasEstado[mesaKey]) {
              mesasEstado[mesaKey] = {};
            }
            // 保存第一个订单的ID和其他信息
            mesasEstado[mesaKey].orderId = backendOrders[0].order_number || backendOrders[0].id;
            mesasEstado[mesaKey].estado = 'ocupada';
            mesasEstado[mesaKey].total = totalAmount;
            mesasEstado[mesaKey].orderCount = backendOrders.length;
            mesasEstado[mesaKey].timestamp = new Date().toISOString();
            // 添加标志，避免触发auto-update循环
            mesasEstado[mesaKey]._skipAutoUpdate = true;
            localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
          } else {
            // 无订单 - 清除总计显示并更新状态为空闲
            totalElement.innerHTML = ``;
            
            // 更新餐桌状态为空闲，因为没有待支付订单 - 使用统一的桌位键格式
            const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
            const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
            
            // 标准化桌位键：提取纯数字桌号，统一为 "Mesa X" 格式（支持任意区域名称）
            const mesaKey = `Mesa ${resolveGlobalTableNumber(tableId)}`;


            if (!mesasEstado[mesaKey]) {
              mesasEstado[mesaKey] = {};
            }
            mesasEstado[mesaKey].estado = 'libre';
            mesasEstado[mesaKey].orderId = null;
            mesasEstado[mesaKey].total = 0;
            mesasEstado[mesaKey].orderCount = 0;
            mesasEstado[mesaKey].timestamp = new Date().toISOString();
            // 添加标志，避免触发auto-update循环
            mesasEstado[mesaKey]._skipAutoUpdate = true;
            localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
            
            // 立即更新当前桌位的显示状态，避免等待下次渲染
            const mesaElement = document.querySelector(`[data-mesa="${mesaKey}"]`);
            
            if (mesaElement) {
              // 更新背景色为空闲状态
              const oldClasses = mesaElement.className;
              // 🔥 移除旧的背景色类
              mesaElement.className = mesaElement.className.replace(/bg-red-100|bg-pink-100|bg-red-200|bg-green-100/, '');
              mesaElement.className = mesaElement.className.replace(/border-red-300|border-pink-300/, 'border-green-300');
              // 移除旧的文字颜色类
              mesaElement.className = mesaElement.className.replace(/text-red-700|text-pink-700|text-red-800/, '');
              // 🔥 应用自定义空闲颜色（背景+字体）
              const customFreeColorUpdate = window.RUIYI_POS?.tableColors?.free || '#2d9551';
              const customFreeTextColorUpdate = window.RUIYI_POS?.tableColors?.freeText || '#ffffff';
              mesaElement.style.backgroundColor = customFreeColorUpdate;
              mesaElement.style.color = customFreeTextColorUpdate;
              mesaElement.setAttribute('data-estado', 'libre');
            } else {
              console.warn(`[UI更新失败] 未找到桌位元素: data-mesa="${mesaKey}"`);
            }
            
            // 注释：移除此处的刷新调用，避免过度渲染
            // 状态更新会通过其他机制反映到UI中
          }
        } else {
          // API错误 - 清除总计显示
          totalElement.innerHTML = ``;
        }
      })
      .catch(error => {
        console.error('Error fetching table total:', error);
        // 🔥 离线修复：如果是网络错误（离线模式），不要清除已从localStorage渲染的总额
        // 只有在线时才清除显示，离线时保留已有的正确数据
        if (navigator.onLine) {
          totalElement.innerHTML = ``;
        } else {
        }
      });
    }

    // 切换显示的页面区域
    async function cambiarSeccion(seccionId) {
      if (seccionId === 'mesas' && window.RUIYI_POS_CONFIG && window.RUIYI_POS_CONFIG.hideTablesModule) {
        seccionId = 'cajero';
      }

      // 🔥🔥🔥 关键修复：如果是AA分单结账后的跳转，跳过同步操作
      // AA分单结账后服务器已经正确更新了订单，本地数据可能不同步，同步会导致数据错误
      if (window._skipSyncAfterSplitBilling) {
        delete window._skipSyncAfterSplitBilling;
        // 直接跳到显示目标页面，跳过同步
      } else if (window._skipAutoSaveInCambiarSeccion) {
        // 🔥🔥🔥 关键修复：保存按钮已经处理了保存，跳过重复的autoSaveTableOrder
        delete window._skipAutoSaveInCambiarSeccion;
        // 直接跳到显示目标页面，跳过同步
      } else {
        // 🔥🔥🔥 【2026-01-20 关键修复】不使用 await 等待自动保存
        // autoSaveTableOrder 内部调用 quickSaveTableOrder 立即更新本地状态
        // 然后后台异步同步服务器，不需要等待
        // 这样切换模块时立即响应，无延迟
        autoSaveTableOrder();
        // 注意：autoSaveTableOrder 内部已经处理了 updateLockedItemsToServer（异步不等待）
        // 不需要再次调用
      }

      // 🔥🔥🔥 关键修复：切换模块前，确保快速结账/外卖模式购物车已保存到localStorage
      // 这样用户从其他模块返回时可以恢复购物车
      // 🔥 修正判断：只要没有桌位号，就应该保存购物车（不管订单类型）
      const tableNumberBeforeSwitch = document.getElementById('table-number')?.value.trim();
      const viewModeBeforeSwitch = sessionStorage.getItem('tableViewMode');
      // 非桌位模式：没有桌位号 且 不在查看桌位订单模式
      const isNonTableModeBeforeSwitch = !tableNumberBeforeSwitch && !viewModeBeforeSwitch;
      if (isNonTableModeBeforeSwitch && typeof savePosCartToStorage === 'function') {
        savePosCartToStorage();
        console.log('[模块切换] ✅ 快速结账模式：切换前已保存购物车到localStorage');
      }

      // 🔥 切换离开桌位模块时，隐藏桌位模块的上一单信息
      if (seccionId !== 'mesas' && typeof hideMesasLastOrderInfo === 'function') {
        hideMesasLastOrderInfo();
      }

      // 隐藏所有页面
      const secciones = document.querySelectorAll('main > section');
      secciones.forEach(seccion => seccion.classList.add('hidden'));
      
      // 显示目标页面
      const seccionDestino = document.getElementById(seccionId);
      if (seccionDestino) {
        seccionDestino.classList.remove('hidden');
      }
      
      // 更新侧边栏选中状态
      const menuLinks = document.querySelectorAll('.menu-link');
      menuLinks.forEach(link => {
        link.classList.remove('bg-red-600', 'text-white');
        if (link.getAttribute('href') === `#${seccionId}`) {
          link.classList.add('bg-red-600', 'text-white');
        }
      });

      // 🔥 Historial: 已移至统一入口（showSection），避免重复加载
      
      // 🔥 已移除页面刷新：切换到餐桌模块时不再刷新页面
      // 改为使用AJAX更新桌位状态，提供更流畅的用户体验
      if (seccionId === 'mesas') {

        // 保存当前section
        sessionStorage.setItem('ruiyi_active_section', 'mesas');

        // 🔥 优化：移除延迟，立即渲染桌位状态实现秒渲染
        if (typeof renderizarMesas === 'function') {
          renderizarMesas('section-switch-to-mesas');
        }

        // 继续执行后续代码（不return）
      }

      // 其他模块的原有逻辑保持不变
      if (seccionId === 'mesas_old_logic') {
          // 加载分类（如果还没加载）
        if (document.querySelectorAll('#category-filter-container .category-filter-btn').length <= 1) {
          loadTableCategories();
        }

        // 🔥 方案：先渲染基础状态，然后异步加载完整订单数据
        // 立即渲染一次（使用现有localStorage数据）
        if (typeof renderizarMesas === 'function') {
          renderizarMesas('section-change');
        }

        // 然后从服务器获取最新状态并更新
        if (typeof fetchAndUpdateTableStatuses === 'function') {
          // 延迟一点调用，避免阻塞初始渲染
          setTimeout(() => {
            fetchAndUpdateTableStatuses();
          }, 100);
        }
      }
      
      // 如果切换到收银模块，更新按钮状态
      if (seccionId === 'cajero') {
        // 🔥 确保工具箱是关闭状态（无论任何情况返回收银页面）
        const cartActionsContainer = document.querySelector('.cart-actions-fixed');
        if (cartActionsContainer && window.Alpine) {
          const alpineData = Alpine.$data(cartActionsContainer);
          if (alpineData) {
            alpineData.toolboxOpen = false;
          }
        }

        // 🔥🔥🔥 关键修复：快速结账/外卖模式下切换模块后恢复购物车
        const tableNumberInput = document.getElementById('table-number')?.value.trim();
        // 🔥🔥🔥 修复：使用正确的sessionStorage键 'tableViewMode'
        const currentViewMode = JSON.parse(sessionStorage.getItem('tableViewMode') || 'null');
        // 🔥🔥🔥 关键修正：只检查桌位号，不检查 tableViewMode
        // 因为 tableViewMode 可能有遗留值，但如果没有桌位号就不应该阻止恢复
        const isNonTableMode = !tableNumberInput;

        // 如果是快速结账模式（没有桌位号），尝试从localStorage恢复购物车
        if (isNonTableMode) {
          // 检查当前购物车是否为空
          const currentCartEmpty = !cart || cart.length === 0;
          if (currentCartEmpty && typeof loadPosCartFromStorage === 'function') {
            const restored = loadPosCartFromStorage();
            if (restored) {
              console.log('[模块切换] ✅ 快速结账模式：已从localStorage恢复购物车');
              // 确保恢复完成标志已设置
              if (typeof window._posCartRestoreComplete !== 'undefined') {
                window._posCartRestoreComplete = true;
              }
              // 🔥 清理 tableViewMode 遗留值
              if (currentViewMode) {
                sessionStorage.removeItem('tableViewMode');
                sessionStorage.removeItem('isViewMode');
                sessionStorage.removeItem('tableViewOrderData');
              }
              // 刷新购物车显示
              if (typeof renderCart === 'function') {
                setTimeout(() => {
                  renderCart();
                }, 50);
              }
            }
          }
        }

        // 🔴 重要：检查查看模式的桌位是否已被清台
        // 注意：currentViewMode 已在上面定义
        // 🔥🔥🔥 关键修复：只有在真正的桌位模式下（有桌位号）才检查清台状态
        // 避免快速结账模式下因 tableViewMode 遗留值而错误清空购物车
        const actualTableNumber = document.getElementById('table-number')?.value.trim();
        if (currentViewMode && currentViewMode.table && actualTableNumber) {
          // 检查该桌位是否还存在（未被清台）
          const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
          const tableState = mesasEstado[currentViewMode.table];

          // 如果桌位已经是空闲状态或不存在，说明已被清台
          if (!tableState || tableState.estado === 'libre' || !tableState.orderId) {
            // 清理查看模式
            sessionStorage.removeItem('isViewMode');
            sessionStorage.removeItem('tableViewOrderData');

            // 清空收银页面的购物车 - 使用syncCart确保完全清空
            if (typeof syncCart === 'function') {
              syncCart([]); // 使用syncCart函数确保cart和window.cart都被清空
            } else {
              // 回退方案：直接清空两个变量
              if (typeof cart !== 'undefined') {
                cart = [];
              }
              if (typeof window.cart !== 'undefined') {
                window.cart = [];
              }
            }

            // 清理购物车标题
            const orderTitle = document.getElementById('cart-order-title');
            if (orderTitle) {
              orderTitle.innerHTML = '';
            }

            // 清空桌位输入框
            const tableNumberInputToClear = document.getElementById('table-number');
            if (tableNumberInputToClear) {
              tableNumberInputToClear.value = '';
            }

            // 重置订单类型为外卖
            const llevarButton = document.querySelector('.order-type[data-type="llevar"]');
            if (llevarButton) {
              setTimeout(() => {
                llevarButton.click();
              }, 100);
            }

            // 刷新购物车显示 - 确保购物车UI更新
            if (typeof renderCart === 'function') {
              setTimeout(() => {
                renderCart();
              }, 150);
            }

            // 隐藏查看模式相关按钮和工具箱
            const viewModeButtons = ['checkout-table-btn', 'toolbox-toggle-btn'];
            setTimeout(() => {
              viewModeButtons.forEach(btnId => {
                const btn = document.getElementById(btnId);
                if (btn) {
                  btn.classList.add('hidden');
                }
              });
            }, 200);
          }
        } else if (currentViewMode && !actualTableNumber) {
          // 🔥🔥🔥 如果有 tableViewMode 遗留值但没有桌位号，清理遗留状态
          sessionStorage.removeItem('tableViewMode');
          sessionStorage.removeItem('isViewMode');
          sessionStorage.removeItem('tableViewOrderData');
        }

        // 使用更长的延迟确保DOM完全加载，并添加重试机制
        const updateButtonsWithRetry = (attempt = 0) => {
          const maxAttempts = 5;
          const tableNumberInput = document.getElementById('table-number');
          const sendOrderBtn = document.getElementById('send-order-btn');

          // 检查关键元素是否存在
          if (!tableNumberInput || !sendOrderBtn) {
            if (attempt < maxAttempts) {
              setTimeout(() => updateButtonsWithRetry(attempt + 1), 100 * (attempt + 1));
              return;
            } else {
              return;
            }
          }

          // 执行按钮状态更新
          if (typeof updateAllButtonStates === 'function') {
            updateAllButtonStates();
          }

          // 特别检查桌位号并强制更新按钮
          const tableNumber = tableNumberInput.value.trim();
          const currentOrderType = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir';

          if (typeof updateOrderButtonForType === 'function') {
            updateOrderButtonForType(currentOrderType);

            // 使用新的强制按钮修复函数
            setTimeout(() => {
              if (typeof forceCorrectButtonDisplay === 'function') {
                forceCorrectButtonDisplay();
              }
            }, 100);
          }
        };

        setTimeout(() => updateButtonsWithRetry(), 300);
      }
    }

    // 查看餐桌详情
    function verDetallesMesa(mesa) {
      // 1. 从 localStorage 获取当前桌位状态和已保存的购物车 (和现在一样)
      const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
      const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
      const estadoMesaLocal = mesasEstado[mesa] || null; // 单个已提交订单信息
      const carritoLocal = carritosGuardados[mesa] || null; // 单个本地保存的购物车

      // 显示一个加载提示，因为我们要发起AJAX请求
      Swal.fire({
          title: `<?php echo ruiyi_translate("Consultando mesa", "Checking table", "查询桌位中"); ?> ${mesa}...`,
          allowOutsideClick: false,
          didOpen: () => {
              Swal.showLoading();
          }
      });

      // 2. 新增：发起AJAX请求获取该桌位所有未结账订单
      fetch(ajaxUrl, { // ajaxUrl 需要在全局或此作用域定义
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
              action: 'ruiyi_pos_get_table_orders',
              table_number: mesa,
              nonce: ajaxNonce // ajaxNonce 需要在全局或此作用域定义
          })
      })
      .then(response => {
          if (!response.ok) {
              throw new Error(`<?php echo ruiyi_translate("Error de red o servidor:", "Network or server error:", "网络或服务器错误："); ?> ${response.status}`);
          }
          return response.json();
      })
      .then(data => {
          Swal.close(); // 关闭加载提示

          if (data.success) {
              // 正确获取嵌套数据结构
              const responseData = data.data || {};
              const backendOrders = responseData.orders || []; // 从后端获取的该桌位所有未结账订单
              let totalAdeudadoBackend = 0;
              let orderIdsBackend = [];
              let htmlListadoPedidosBackend = '';

              if (backendOrders.length > 0) {
                  backendOrders.forEach(order => {
                      totalAdeudadoBackend += parseFloat(order.total);
                      orderIdsBackend.push(`#${order.order_number || order.id}`);
                      htmlListadoPedidosBackend += `<li class="text-xs mb-1">Pedido #${order.order_number || order.id} - €${parseFloat(order.total).toFixed(2)} (${order.status_name || order.status})</li>`;
                  });

                  // 🔥 保存订单数据到 sessionStorage 用于购物车显示
                  sessionStorage.setItem('tableOrdersData', JSON.stringify({
                      tableName: mesa,
                      orders: backendOrders,
                      totalAmount: totalAdeudadoBackend,
                      orderCount: backendOrders.length
                  }));

                  // 更新 localStorage 中的订单信息
                  const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                  if (!mesasEstado[mesa]) {
                      mesasEstado[mesa] = {};
                  }
                  // 保存第一个订单的ID作为主要订单ID
                  mesasEstado[mesa].orderId = backendOrders[0].order_number || backendOrders[0].id;
                  mesasEstado[mesa].estado = 'ocupada';
                  mesasEstado[mesa].total = totalAdeudadoBackend;
                  mesasEstado[mesa].orderCount = backendOrders.length;
                  mesasEstado[mesa].timestamp = new Date().toISOString();
                  localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
              }

              // 3. 整合信息并构建弹窗内容
              let tituloPrincipal = `${mesa}`;
              let detallesHtml = '<div class="text-left">';
              let icono = 'info';
              let esMesaOcupadaConPedidos = backendOrders.length > 0;
              let showDeny = esMesaOcupadaConPedidos; // Mostrar "Pagar Todo" si hay pedidos en backend
              let confirmButtonTextDefault = '<?php echo ruiyi_translate("Cerrar", "Close", "关闭"); ?>'; // Botón por defecto si no hay acciones primarias

              if (esMesaOcupadaConPedidos) {
                  icono = 'warning'; 
                  tituloPrincipal += ` - <?php echo ruiyi_translate("Pendiente de Pago", "Payment Pending", "待支付"); ?> (€${totalAdeudadoBackend.toFixed(2)})`;
                  
                  detallesHtml += `
                      <div class="flex justify-between items-center mb-2">
                          <span class="bg-red-100 text-red-800 px-2 py-1 rounded-full text-xs font-medium">
                              <?php echo ruiyi_translate("Mesa Ocupada", "Table Occupied", "餐桌占用中"); ?>
                          </span>
                          <span class="text-sm text-gray-700 dark:text-gray-300">
                              <?php echo ruiyi_translate("Total Adeudado:", "Total Due:", "应付总额:"); ?> 
                              <strong class="text-red-600 dark:text-red-400 text-lg">€${totalAdeudadoBackend.toFixed(2)}</strong>
                          </span>
                      </div>
                      <div class="mb-3 p-2 bg-gray-50 dark:bg-gray-700 rounded-md">
                          <p class="text-xs font-semibold text-gray-600 dark:text-gray-400 mb-1"><?php echo ruiyi_translate("Pedidos Pendientes en esta Mesa:", "Pending Orders at this Table:", "此餐桌待处理订单："); ?></p>
                          <ul class="list-disc list-inside pl-1 max-h-32 overflow-y-auto">${htmlListadoPedidosBackend}</ul>
                      </div>
                  `;
                  confirmButtonTextDefault = '<?php echo ruiyi_translate("Agregar Productos", "Add Products", "添加商品"); ?>';

              } else if (carritoLocal) {
                  // Lógica para mostrar carritoLocal guardado (si no hay pedidos en backend)
                  let productosHtml = '<div class="mt-3 border-t pt-3"><h4 class="font-semibold text-sm mb-1 text-gray-700 dark:text-gray-300"><?php echo ruiyi_translate("Carrito Local Guardado:", "Local Saved Cart:", "本地已保存购物车："); ?></h4><ul class="text-xs text-gray-600 dark:text-gray-400 list-disc list-inside">';
                  carritoLocal.carrito.forEach(item => {
                      const _price = parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0));
                      const _displayName = item.customName || item.name;
                      productosHtml += `<li>${_displayName} x ${item.quantity} - €${(_price * item.quantity).toFixed(2)}</li>`;
                  });
                  productosHtml += '</ul></div>';
                  const subtotal = carritoLocal.carrito.reduce((sum, item) => {
                      const _price = parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0));
                      return sum + (_price * item.quantity);
                  }, 0);
                  const descuento = carritoLocal.descuento || 0;
                  const totalLocal = subtotal - descuento;
                  tituloPrincipal = `${mesa} - <?php echo ruiyi_translate("Carrito Guardado", "Saved Cart", "已保存购物车"); ?> (€${totalLocal.toFixed(2)})`;
                  detallesHtml += `
                      <div class="flex justify-between items-center mb-2">
                          <span class="bg-yellow-100 text-yellow-800 px-2 py-1 rounded-full text-xs font-medium">
                              <?php echo ruiyi_translate("Carrito Local", "Local Cart", "本地购物车"); ?>
                          </span>
                          <span class="text-sm text-gray-700 dark:text-gray-300">
                              <?php echo ruiyi_translate("Total Carrito:", "Cart Total:", "购物车总额:"); ?>
                              <strong class="text-yellow-600 dark:text-yellow-400 text-lg">€${totalLocal.toFixed(2)}</strong>
                          </span>
                      </div>
                      ${productosHtml}
                  `;
                  confirmButtonTextDefault = '<?php echo ruiyi_translate("Editar Carrito", "Edit Cart", "编辑购物车"); ?>';
                  showDeny = false; // No mostrar "Pagar Todo" para carritos locales no enviados

              } else {
                  // Mesa completamente libre
                  tituloPrincipal = `${mesa} - <?php echo ruiyi_translate("Disponible", "Available", "可用"); ?>`;
                  detallesHtml += `<p class="text-center py-4 text-gray-600 dark:text-gray-400"><?php echo ruiyi_translate("Esta mesa está libre. ¿Desea crear un nuevo pedido?", "This table is free. Would you like to create a new order?", "此餐桌空闲。您想创建新订单吗？"); ?></p>`;
                  icono = 'success';
                  confirmButtonTextDefault = '<?php echo ruiyi_translate("Crear Pedido", "Create Order", "创建订单"); ?>';
                  showDeny = false;
              }
              detallesHtml += '</div>'; // Cierre de text-left

              // 4. Mostrar el SweetAlert2 con la información integrada
              Swal.fire({
                  title: tituloPrincipal,
                  html: detallesHtml,
                  icon: icono,
                  showCancelButton: true,
                  confirmButtonText: confirmButtonTextDefault,
                  cancelButtonText: '<?php echo ruiyi_translate("Cerrar", "Close", "关闭"); ?>',
                  showDenyButton: showDeny,
                  denyButtonText: `<?php echo ruiyi_translate("Pagar Todo", "Pay All", "支付全部"); ?> (€${totalAdeudadoBackend.toFixed(2)})`,
                  denyButtonColor: '#3085d6', 
                  confirmButtonColor: (esMesaOcupadaConPedidos || !carritoLocal && !esMesaOcupadaConPedidos) ? '#4caf50' : '#E67E22' , // Verde para "Agregar/Crear", Naranja para "Editar Carrito"
                  width: '500px',
                  customClass: {
                    htmlContainer: 'text-sm'
                  }
              }).then(result => {
                  if (result.isConfirmed) {
                      // Lógica para "Agregar Productos" / "Crear Pedido" / "Editar Carrito"
                      window.mesaSeleccionadaParaPedido = { id: mesa, nombre: mesa };
                      
                      if (carritoLocal && !esMesaOcupadaConPedidos) { // Si es "Editar Carrito Local"
                          // Cargar el carrito local para edición
                          cargarCarritoMesa(mesa); // Asegúrate que esta función exista y cargue el carrito en 'cart' y actualice UI
                      } else {
                          // Para "Agregar Productos" (a una mesa con pedidos backend) o "Crear Pedido" (mesa libre)
                          if (typeof cart !== 'undefined' && Array.isArray(cart)) {
                              cart = []; 
                              if (typeof renderCart === 'function') renderCart();
                          }
                      }
                      if (typeof cambiarSeccion === 'function') {
                          cambiarSeccion('cajero');

                          // 确保按钮状态正确
                          setTimeout(() => {
                              if (typeof forceCorrectButtonDisplay === 'function') {
                                  forceCorrectButtonDisplay();
                              }
                          }, 600);
                      }

                  } else if (result.isDenied && esMesaOcupadaConPedidos) {
                      // Lógica para "Pagar Todo"
                      procesarPagoCompletoDeMesa(mesa, totalAdeudadoBackend, orderIdsBackend);
                  }
              });

          } else {
              // Error al obtener pedidos del backend
              Swal.fire({
                  icon: 'error',
                  title: '<?php echo ruiyi_translate("Error de Datos", "Data Error", "数据错误"); ?>',
                  text: data.message || '<?php echo ruiyi_translate("No se pudieron obtener los detalles completos de la mesa desde el servidor.", "Could not get complete table details from server.", "无法从服务器获取完整的桌位详情。"); ?>',
              });
          }
      })
      .catch(error => {
          Swal.close();
          console.error('Error en verDetallesMesa (fetch):', error);
          Swal.fire({
              icon: 'error',
              title: '<?php echo ruiyi_translate("Error de Comunicación", "Communication Error", "通讯错误"); ?>',
              text: error.message || '<?php echo ruiyi_translate("No se pudo conectar con el servidor para obtener detalles de la mesa.", "Could not connect to the server to get table details.", "无法连接服务器获取桌位详情。"); ?>'
          });
      });
    }

