                                <div id="change-calculation-mesa" class="checkout-change-summary mt-3" style="display: none;">
                                    <div class="checkout-change-box">
                                        <span class="checkout-change-label"><?php echo ruiyi_translate('Recibido', 'Received', '已收'); ?></span>
                                        <span id="received-display-mesa" class="checkout-received-value">€0.00</span>
