            `,
            confirmButtonText: '<?php echo ruiyi_translate('Completar pago', 'Complete payment', '完成支付'); ?>',
            confirmButtonColor: '#4caf50',
            showCancelButton: true,
            cancelButtonText: '<?php echo ruiyi_translate('Cancelar', 'Cancel', '取消'); ?>',
            width: ruiyiIsCheckoutTouchKeypadEnabled() ? '780px' : '500px',
            didOpen: () => {
                ruiyiAttachCheckoutTouchKeypad(Swal.getPopup());

                // 初始化价格状态跟踪
                let currentOriginalTotal = totalAdeudado;
                let currentDiscountAmount = 0;
                let hasDiscountApplied = false;

                // 🔥 自动填充 delivery 客户数据（如果存在）
                const currentTable = document.getElementById('table-number')?.value.trim();
                if (currentTable) {
                    const deliveryData = getDeliveryCustomerData(currentTable);
                    if (deliveryData) {
                        // // console.log('[桌位结账] 🔥 自动填充外送客户数据:', deliveryData);
                        // 🔥 修复：使用 Swal.getPopup().querySelector() 而不是 document.getElementById()
                        // 因为表单字段在 Swal 弹窗内部
                        const popup = Swal.getPopup();
                        const nameField = popup.querySelector('#table-customer-name');
                        const phoneField = popup.querySelector('#table-customer-phone');
                        const businessField = popup.querySelector('#table-customer-business-name');
                        const taxField = popup.querySelector('#table-customer-cif-nif');
                        const addressField = popup.querySelector('#table-customer-address');
                        const postalField = popup.querySelector('#table-customer-postal');
                        const emailField = popup.querySelector('#table-customer-email');
                        const notesField = popup.querySelector('#table-customer-notes');
                        const phoneSearchField = popup.querySelector('#table-customer-phone-search');

                        if (nameField) nameField.value = deliveryData.name || '';
                        if (phoneField) phoneField.value = deliveryData.phone || '';
                        if (businessField) businessField.value = deliveryData.business_name || '';
                        if (taxField) taxField.value = deliveryData.cif_nif || '';
                        if (addressField) addressField.value = deliveryData.address || '';
                        if (postalField) postalField.value = deliveryData.postal_code || '';
                        if (emailField) emailField.value = deliveryData.email || '';
                        if (notesField) notesField.value = deliveryData.notes || '';
                        if (phoneSearchField) phoneSearchField.value = deliveryData.phone || '';

                        // // console.log('[桌位结账] ✅ 外送客户数据已填充到表单');
                    }
                }

                // 🔥 自动选择排序后的第一个支付方式
                const firstMethod = window.applyPaymentMethodOrder(Swal.getPopup(), '.payment-method-btn-mesa', '#table-cheque-btn');
                setTimeout(() => {
                    const firstBtn = Swal.getPopup().querySelector(
                        firstMethod === 'cheque' ? '#table-cheque-btn' : '.payment-method-btn-mesa[data-method="' + firstMethod + '"]'
                    );
                    if (firstBtn) firstBtn.click();
                }, 100);

                // 标签切换功能
                const tabButtons = Swal.getPopup().querySelectorAll('.tab-button');
                const tabPanels = Swal.getPopup().querySelectorAll('.tab-panel');
                
                tabButtons.forEach(button => {
                    button.addEventListener('click', () => {
                        // 移除所有活动状态
                        tabButtons.forEach(btn => {
                            btn.classList.remove('text-green-600', 'border-b-2', 'border-green-500');
                            btn.classList.add('text-gray-500');
                        });
                        tabPanels.forEach(panel => panel.classList.add('hidden'));
                        
                        // 添加当前标签的活动状态
                        button.classList.remove('text-gray-500');
                        button.classList.add('text-green-600', 'border-b-2', 'border-green-500');
                        
                        // 显示对应面板
                        const targetPanel = Swal.getPopup().querySelector(`#${button.dataset.tab}-panel`);
                        targetPanel.classList.remove('hidden');
                        
                        // 当切换到支付标签时，确保价格显示正确
                        if (button.dataset.tab === 'payment' && hasDiscountApplied) {
                            updateAllPriceDisplays(currentOriginalTotal, totalAdeudado, currentDiscountAmount);
                        }
                    });
                });

                // 支付方式选择功能
                const paymentBtns = Swal.getPopup().querySelectorAll('.payment-method-btn-mesa');
                const cashSection = Swal.getPopup().querySelector('#cash-payment-section-mesa');
                const mixedSection = Swal.getPopup().querySelector('#mixed-payment-section-mesa');
                const cardSection = Swal.getPopup().querySelector('#card-payment-section-mesa');
                const receivedInput = Swal.getPopup().querySelector('#received-amount-mesa');
                const changeCalc = Swal.getPopup().querySelector('#change-calculation-mesa');
                const receivedDisplay = Swal.getPopup().querySelector('#received-display-mesa');
                const changeAmountDisplay = Swal.getPopup().querySelector('#change-amount-mesa');

                // 🔥 刷卡找零相关元素
                const cardReceivedInput = Swal.getPopup().querySelector('#card-received-amount-mesa');
                const cardChangeCalc = Swal.getPopup().querySelector('#card-change-calculation-mesa');
                const cardReceivedDisplay = Swal.getPopup().querySelector('#card-received-display-mesa');
                const cardChangeAmountDisplay = Swal.getPopup().querySelector('#card-change-amount-mesa');
                
                // 混合支付相关元素
                const mixedCashInput = Swal.getPopup().querySelector('#mixed-cash-amount');
                const mixedCardInput = Swal.getPopup().querySelector('#mixed-card-amount');
                const mixedValidation = Swal.getPopup().querySelector('#mixed-payment-validation');
                const mixedCashDisplay = Swal.getPopup().querySelector('#mixed-cash-display');
                const mixedCardDisplay = Swal.getPopup().querySelector('#mixed-card-display');
                const mixedTotalDisplay = Swal.getPopup().querySelector('#mixed-total-display');
                
                // 公司钱票抵扣相关元素
                const toggleTicketBtn = Swal.getPopup().querySelector('#toggle-company-ticket-btn');
                const ticketInputArea = Swal.getPopup().querySelector('#company-ticket-input-area');
                const companyTicketInput = Swal.getPopup().querySelector('#company-ticket-amount-mesa');
                const applyTicketBtn = Swal.getPopup().querySelector('#apply-company-ticket-btn');
                const ticketSummary = Swal.getPopup().querySelector('#company-ticket-summary');
                const appliedTicketAmount = Swal.getPopup().querySelector('#applied-ticket-amount');
                const ticketChangeDisplay = Swal.getPopup().querySelector('#company-ticket-change-display');
                const ticketChangeAmount = Swal.getPopup().querySelector('#ticket-change-amount');
                const paymentTotalDisplay = Swal.getPopup().querySelector('#payment-total-display');
                
                let metodoPagoMesa = '';

                // 计算找零
                function calculateChangeMesa() {
                    let received = parseFloat(receivedInput.value) || 0;

                    if (received >= totalAdeudado) {
                        const change = received - totalAdeudado;
                        receivedDisplay.textContent = `€${received.toFixed(2)}`;
                        changeAmountDisplay.textContent = `€${change.toFixed(2)}`;
                        changeCalc.style.display = 'grid';
                    } else {
                        changeCalc.style.display = 'none';
                    }
                }

                // 🔥 计算刷卡找零
                function calculateCardChangeMesa() {
                    let received = parseFloat(cardReceivedInput.value) || 0;
                    if (received >= totalAdeudado) {
                        const change = received - totalAdeudado;
                        cardReceivedDisplay.textContent = `€${received.toFixed(2)}`;
                        cardChangeAmountDisplay.textContent = `€${change.toFixed(2)}`;
                        cardChangeCalc.style.display = 'grid';
                    } else {
                        cardChangeCalc.style.display = 'none';
                    }
                }

                // 支付方式按钮事件
                // 混合支付计算函数
                function calculateMixedPayment() {
                    const cashAmount = parseFloat(mixedCashInput.value) || 0;
                    const remainingAmount = totalAdeudado - cashAmount;
                    const cardAmount = Math.max(0, remainingAmount);
                    
                    // 更新刷卡金额输入框
                    mixedCardInput.value = cardAmount.toFixed(2);
                    
                    // 更新验证显示
                    if (mixedCashDisplay) mixedCashDisplay.textContent = `€${cashAmount.toFixed(2)}`;
                    if (mixedCardDisplay) mixedCardDisplay.textContent = `€${cardAmount.toFixed(2)}`;
                    if (mixedTotalDisplay) mixedTotalDisplay.textContent = `€${(cashAmount + cardAmount).toFixed(2)}`;
                    
                    // 显示/隐藏验证区域
                    if (cashAmount > 0 && mixedValidation) {
                        mixedValidation.style.display = 'block';
                        
                        // 检查金额是否匹配
                        const totalPayment = cashAmount + cardAmount;
                        if (Math.abs(totalPayment - totalAdeudado) < 0.01) {
                            mixedValidation.className = 'mt-3 p-3 rounded-lg bg-green-50 border border-green-200';
                        } else {
                            mixedValidation.className = 'mt-3 p-3 rounded-lg bg-red-50 border border-red-200';
                        }
                    } else if (mixedValidation) {
                        mixedValidation.style.display = 'none';
                    }
                }
                
                // 初始化公司钱票抵扣变量
                originalTotalAmount = totalAdeudado;
                
                // 公司钱票抵扣函数
                function applyCompanyTicket() {
                    const ticketAmount = parseFloat(companyTicketInput.value) || 0;
                    if (ticketAmount <= 0) {
                        Swal.showValidationMessage('<?php echo ruiyi_translate('Por favor ingrese un monto válido', 'Please enter a valid amount', '请输入有效金额'); ?>');
                        return;
                    }
                    
                    // 应用抵扣（允许超额，支持找零）
                    appliedCompanyTicket = ticketAmount;
                    const remaining = originalTotalAmount - ticketAmount;
                    totalAdeudado = Math.max(0, remaining);
                    
                    
                    // 更新界面显示
                    if (paymentTotalDisplay) {
                        paymentTotalDisplay.textContent = `€${totalAdeudado.toFixed(2)}`;
                    }
                    
                    // 处理找零显示
                    if (remaining < 0) {
                        // 需要找零
                        const changeAmount = Math.abs(remaining);
                        
                        // 重新查找元素，确保DOM已加载
                        const ticketChangeAmountElement = Swal.getPopup().querySelector('#ticket-change-amount');
                        const ticketChangeDisplayElement = Swal.getPopup().querySelector('#company-ticket-change-display');
                        
                        if (ticketChangeAmountElement) {
                            ticketChangeAmountElement.textContent = `€${changeAmount.toFixed(2)}`;
                        } else {
                            console.error('找零金额元素未找到: #ticket-change-amount');
                        }
                        
                        if (ticketChangeDisplayElement) {
                            ticketChangeDisplayElement.style.display = 'block';
                            ticketChangeDisplayElement.style.opacity = '1';
                            ticketChangeDisplayElement.style.visibility = 'visible';
                            
                            // 高亮找零区域，确保用户注意到
                            ticketChangeDisplayElement.style.border = '2px solid #16a34a';
                            setTimeout(() => {
                                ticketChangeDisplayElement.style.border = '';
                            }, 3000);
                        } else {
                            console.error('找零显示元素未找到: #company-ticket-change-display');
                        }
                    } else {
                        // 隐藏找零显示
                        const ticketChangeDisplayElement = Swal.getPopup().querySelector('#company-ticket-change-display');
                        if (ticketChangeDisplayElement) {
                            ticketChangeDisplayElement.style.display = 'none';
                        }
                    }
                    
                    // 显示抵扣摘要区域
                    if (ticketSummary) {
                        ticketSummary.style.display = 'block';
                    }
                    
                    // 设置抵扣金额显示
                    if (appliedTicketAmount) {
                        appliedTicketAmount.textContent = `€${ticketAmount.toFixed(2)}`;
                    }
                    
                    // 隐藏输入区域，显示应用成功
                    if (ticketInputArea) {
                        ticketInputArea.style.display = 'none';
                    }
                    
                    if (toggleTicketBtn) {
                        toggleTicketBtn.textContent = '<?php echo ruiyi_translate('Aplicado', 'Applied', '已抵扣'); ?>';
