                    }
                    
                    // 清除所有支付方式选择状态，让用户重新选择
                    paymentBtns.forEach(btn => {
                        btn.classList.remove('border-green-500', 'bg-green-50', 'border-blue-500', 'bg-blue-50', 'border-purple-500', 'bg-purple-50', 'border-teal-500', 'bg-teal-50');
                    });

                    // 隐藏所有支付界面 - 使用 classList 而不是 style.display
                    if (cashSection) cashSection.classList.add('hidden');
                    if (mixedSection) mixedSection.classList.add('hidden');
                    
                    metodoPagoMesa = ''; // 重置支付方式选择
                    
                    // 如果公司钱票完全覆盖了订单金额，准备完成支付  
                    if (totalAdeudado <= 0) {
                        // 计算找零金额
                        const changeAmount = Math.abs(remaining);
                        
                        // 设置支付方式为公司钱票，让用户点击确认完成支付
                        metodoPagoMesa = 'company_ticket_only';
                        
                    }
                }

                paymentBtns.forEach(btn => {
                    btn.addEventListener('click', () => {
                        metodoPagoMesa = btn.dataset.method;
                        paymentBtns.forEach(b => b.classList.remove('border-green-500', 'bg-green-50', 'border-blue-500', 'bg-blue-50', 'border-purple-500', 'bg-purple-50', 'border-teal-500', 'bg-teal-50'));

                        // 隐藏所有支付界面 - 使用 classList 而不是 style.display 来正确覆盖 hidden 类
                        if (cashSection) cashSection.classList.add('hidden');
                        if (cardSection) cardSection.classList.add('hidden');
                        if (mixedSection) mixedSection.classList.add('hidden');

                        // 🔥 隐藏抵扣券区域（无论是否已应用）
                        const tableChequeInputCheck = Swal.getPopup().querySelector('#table-cheque-restaurante');
                        const tableChequeSecCheck = Swal.getPopup().querySelector('#table-cheque-section');
                        const tableChequeBtnCheck = Swal.getPopup().querySelector('#table-cheque-btn');
                        if (tableChequeSecCheck) {
                            tableChequeSecCheck.classList.add('hidden');
                            // 如果抵扣券未应用，重置 Vale 按钮样式
                            if (tableChequeInputCheck && !tableChequeInputCheck.disabled && tableChequeBtnCheck) {
                                tableChequeBtnCheck.classList.remove('border-orange-500', 'bg-orange-50', 'border-green-500', 'bg-green-50');
                                tableChequeBtnCheck.classList.add('border-gray-300');
                            }
                        }

                        if (metodoPagoMesa === 'cash') {
                            btn.classList.add('border-green-500', 'bg-green-50');
                            if (cashSection) cashSection.classList.remove('hidden');
                            if (receivedInput) {
                                // 🔥 现金输入框默认为空，不预填金额
                                receivedInput.value = '';
                                receivedInput.placeholder = `€${totalAdeudado.toFixed(2)}`;
                                receivedInput.focus();
                            }
                            calculateChangeMesa();
                        } else if (metodoPagoMesa === 'card') {
                            btn.classList.add('border-blue-500', 'bg-blue-50');
                            // 🔥 刷卡找零功能
