                                if (cardReceivedInput) {
                                    cardReceivedInput.value = '';
                                    cardReceivedInput.placeholder = `€${totalAdeudado.toFixed(2)}`;
                                    cardReceivedInput.focus();
                                }
                                calculateCardChangeMesa();
                            }
                        } else if (metodoPagoMesa === 'bizum') {
                            btn.classList.add('border-teal-500', 'bg-teal-50');
                            // Bizum/转账支付无需额外界面
                        } else if (metodoPagoMesa === 'mixed') {
                            btn.classList.add('border-purple-500', 'bg-purple-50');
                            if (mixedSection) mixedSection.classList.remove('hidden');

                            // 初始化混合支付
                            if (mixedCashInput) {
                                mixedCashInput.value = '';
                                mixedCashInput.focus();
                            }
                            calculateMixedPayment();
                        }
                    });
                });
                
                // 添加混合支付输入监听器
                if (mixedCashInput) {
                    mixedCashInput.addEventListener('input', calculateMixedPayment);

                    // 🔥 混合支付现金输入框按Enter键完成支付
                    mixedCashInput.addEventListener('keydown', function(e) {
                        if (e.key === 'Enter') {
                            e.preventDefault();
                            e.stopPropagation();
                            const confirmButton = Swal.getConfirmButton();
                            if (confirmButton && !confirmButton.disabled) {
                                confirmButton.click();
                            }
                        }
                    });
                }

                // 添加公司钱票事件监听器
                if (toggleTicketBtn) {
                    toggleTicketBtn.addEventListener('click', () => {
                        if (ticketInputArea) {
                            ticketInputArea.style.display = 'block';
                        }
                        if (companyTicketInput) {
