                        }
                    });
                }
                
                if (applyTicketBtn) {
                    applyTicketBtn.addEventListener('click', applyCompanyTicket);
                }

                receivedInput.addEventListener('input', calculateChangeMesa);

                // 🔥🔥🔥 关键修复：在收款金额输入框按Enter键直接完成支付
                receivedInput.addEventListener('keydown', function(e) {
                    if (e.key === 'Enter') {
                        e.preventDefault();
                        e.stopPropagation();

                        // 获取确认按钮并点击
                        const confirmButton = Swal.getConfirmButton();
                        if (confirmButton && !confirmButton.disabled) {
                            confirmButton.click();
                        }
                    }
                });

                // 🔥 刷卡找零输入监听器
                if (cardReceivedInput) {
                    cardReceivedInput.addEventListener('input', calculateCardChangeMesa);

                    cardReceivedInput.addEventListener('keydown', function(e) {
                        if (e.key === 'Enter') {
                            e.preventDefault();
                            e.stopPropagation();
                            const confirmButton = Swal.getConfirmButton();
                            if (confirmButton && !confirmButton.disabled) {
                                confirmButton.click();
                            }
                        }
                    });
                }

                // 🔥 Vale 按钮点击事件（切换显示抵扣券输入区域）- 桌位
                const tableChequeBtn = Swal.getPopup().querySelector('#table-cheque-btn');
                const tableChequeSection = Swal.getPopup().querySelector('#table-cheque-section');

                if (tableChequeBtn && tableChequeSection) {
                    tableChequeBtn.addEventListener('click', function() {
                        const isHidden = tableChequeSection.classList.contains('hidden');
                        if (isHidden) {
                            // 🔥 隐藏其他支付区域
                            if (cashSection) cashSection.classList.add('hidden');
                            if (mixedSection) mixedSection.classList.add('hidden');

                            // 🔥 重置其他支付按钮样式
                            paymentBtns.forEach(b => {
                                b.classList.remove('border-green-500', 'bg-green-50', 'border-blue-500', 'bg-blue-50', 'border-purple-500', 'bg-purple-50');
                                b.classList.add('border-gray-300');
                            });

                            tableChequeSection.classList.remove('hidden');
                            this.classList.add('border-orange-500', 'bg-orange-50');
                            // 聚焦到输入框
                            const chequeInput = Swal.getPopup().querySelector('#table-cheque-restaurante');
                            if (chequeInput && !chequeInput.disabled) {
                                chequeInput.focus();
                            }
                        } else {
                            tableChequeSection.classList.add('hidden');
                            this.classList.remove('border-orange-500', 'bg-orange-50');
                            this.classList.add('border-gray-300');
                        }
                    });
                }

                // 🔥 餐厅抵扣票 (Cheque Restaurante) 初始化 - 桌位
                const tableChequeInput = Swal.getPopup().querySelector('#table-cheque-restaurante');
                const applyTableChequeBtn = Swal.getPopup().querySelector('#apply-cheque-table');
                const tableChequApplied = Swal.getPopup().querySelector('#cheque-applied-table');
                const tableChequeAmountDisplay = Swal.getPopup().querySelector('#cheque-amount-display-table');
                const tableRemainingDisplay = Swal.getPopup().querySelector('#table-remaining-amount');

                // 存储原始总额用于Cheque Restaurante计算
                const tableOriginalTotalForCheque = totalAdeudado;
                window.tableChequeRestauranteAmount = 0;

                if (applyTableChequeBtn && tableChequeInput) {
                    applyTableChequeBtn.addEventListener('click', function() {
                        const chequeAmount = parseFloat(tableChequeInput.value) || 0;

                        if (chequeAmount <= 0) {
                            Toastify({
                                text: '<?php echo ruiyi_translate("Por favor ingrese un importe válido", "Please enter a valid amount", "请输入有效的抵扣金额"); ?>',
                                duration: 2000,
                                gravity: "top",
                                position: "center",
                                style: { background: "#f97316" }
                            }).showToast();
                            return;
                        }

                        if (chequeAmount > tableOriginalTotalForCheque) {
                            Toastify({
                                text: '<?php echo ruiyi_translate("El importe no puede superar el total", "Amount cannot exceed total", "抵扣金额不能超过总额"); ?>',
                                duration: 2000,
                                gravity: "top",
                                position: "center",
                                style: { background: "#ef4444" }
                            }).showToast();
                            return;
                        }

                        // 保存抵扣金额
                        window.tableChequeRestauranteAmount = chequeAmount;

                        // 计算剩余应付金额
                        const remainingAmount = tableOriginalTotalForCheque - chequeAmount;

                        // 🔥 更新 totalAdeudado 为抵扣后的金额
                        totalAdeudado = remainingAmount;

                        // 更新显示
                        if (tableChequeAmountDisplay) tableChequeAmountDisplay.textContent = chequeAmount.toFixed(2);
                        if (tableRemainingDisplay) tableRemainingDisplay.textContent = '€' + remainingAmount.toFixed(2);

                        // 更新顶部总额显示
                        if (paymentTotalDisplay) {
                            paymentTotalDisplay.innerHTML = `<span class="line-through text-gray-400 text-xl mr-2">€${tableOriginalTotalForCheque.toFixed(2)}</span><span class="text-green-600">€${remainingAmount.toFixed(2)}</span>`;
                        }

                        // 🔥 更新现金收款输入框的 placeholder
                        if (receivedInput) {
                            receivedInput.placeholder = `€${remainingAmount.toFixed(2)}`;
                            receivedInput.value = ''; // 清空已输入的值
                        }

                        // 🔥 更新 Vale 按钮样式为已应用状态
                        if (tableChequeBtn) {
                            tableChequeBtn.classList.remove('border-gray-300', 'hover:border-orange-500', 'hover:bg-orange-50', 'border-orange-500', 'bg-orange-50');
                            tableChequeBtn.classList.add('border-green-500', 'bg-green-50');
                            tableChequeBtn.innerHTML = `<i class="fas fa-check-circle text-xl mb-1 text-green-600"></i><span class="text-sm font-medium text-green-700">-€${chequeAmount.toFixed(2)}</span>`;
                        }

                        // 显示已应用区域
                        if (tableChequApplied) tableChequApplied.classList.remove('hidden');

                        // 禁用输入和隐藏应用按钮，显示取消按钮
                        tableChequeInput.disabled = true;
                        applyTableChequeBtn.classList.add('hidden');
                        const cancelTableChequeBtn = Swal.getPopup().querySelector('#cancel-cheque-table');
                        if (cancelTableChequeBtn) cancelTableChequeBtn.classList.remove('hidden');

                        // 🔥 重新计算混合支付（如果当前是混合支付模式）
                        if (metodoPagoMesa === 'mixed') {
                            calculateMixedPayment();
                        }

                        Toastify({
                            text: '<?php echo ruiyi_translate("Vale aplicado correctamente", "Voucher applied successfully", "抵扣票已成功应用"); ?>',
                            duration: 2000,
                            gravity: "top",
                            position: "center",
                            style: { background: "#10b981" }
                        }).showToast();
                    });

                    // 🔥 抵扣票输入框按Enter键直接应用
                    tableChequeInput.addEventListener('keydown', function(e) {
                        if (e.key === 'Enter') {
                            e.preventDefault();
                            e.stopPropagation();
                            applyTableChequeBtn.click();
                        }
                    });
                }

                // 🔥 取消抵扣票应用 - 桌位
                const cancelTableChequeBtn = Swal.getPopup().querySelector('#cancel-cheque-table');
                if (cancelTableChequeBtn) {
                    cancelTableChequeBtn.addEventListener('click', function() {
                        const paymentTotalDisplay = Swal.getPopup().querySelector('#payment-total-display');
                        const tableChequeBtn = Swal.getPopup().querySelector('#table-cheque-btn');
                        const receivedInput = Swal.getPopup().querySelector('#received-amount');

                        // 重置输入框
                        if (tableChequeInput) {
                            tableChequeInput.value = '';
                            tableChequeInput.disabled = false;
                        }

                        // 隐藏取消按钮，显示应用按钮
                        this.classList.add('hidden');
                        applyTableChequeBtn.classList.remove('hidden');

                        // 隐藏已应用区域
                        if (tableChequApplied) tableChequApplied.classList.add('hidden');

                        // 恢复原价显示
                        if (paymentTotalDisplay) {
                            paymentTotalDisplay.innerHTML = `€${tableOriginalTotalForCheque.toFixed(2)}`;
                        }

                        // 重置 totalAdeudado
                        totalAdeudado = tableOriginalTotalForCheque;

                        // 重置抵扣金额
                        window.tableChequeRestauranteAmount = 0;

                        // 更新现金收款输入框的 placeholder
                        if (receivedInput) {
                            receivedInput.placeholder = `€${tableOriginalTotalForCheque.toFixed(2)}`;
                            receivedInput.value = '';
                        }

                        // 重置 Vale 按钮样式
                        if (tableChequeBtn) {
                            tableChequeBtn.classList.remove('border-green-500', 'bg-green-50');
                            tableChequeBtn.classList.add('border-gray-300');
                            tableChequeBtn.innerHTML = `<i class="fas fa-ticket-alt text-xl mb-1 text-orange-500"></i><span class="text-sm font-medium"><?php echo ruiyi_translate('Vale', 'Voucher', '抵扣票'); ?></span>`;
                        }

                        // 🔥 重新计算混合支付（如果当前是混合支付模式）
                        if (metodoPagoMesa === 'mixed') {
                            calculateMixedPayment();
                        }

                        Toastify({
                            text: '<?php echo ruiyi_translate("Vale cancelado", "Voucher cancelled", "抵扣票已取消"); ?>',
                            duration: 2000,
                            gravity: "top",
                            position: "center",
                            style: { background: "#f97316" }
                        }).showToast();
                    });
                }

                // 用户验证功能
                function verifyUserShortcode(shortcode, type) {
                    const formData = new URLSearchParams({
                        action: 'ruiyi_lookup_user_by_shortcode',
                        shortcode: shortcode,
                        nonce: window.RUIYI_POS.nonce
                    });

                    fetch(ajaxUrl, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                        body: formData
                    })
                    .then(response => response.json())
                    .then(data => {
                        if (data.success) {
                            verifiedUser = data.data;
                            
                            // 更新用户信息显示
                            const userInfo = type === 'points' ? 
                                Swal.getPopup().querySelector('#points-user-info') :
                                Swal.getPopup().querySelector('#reward-user-info');
                            const userOperation = type === 'points' ?
                                Swal.getPopup().querySelector('#points-operation') :
                                Swal.getPopup().querySelector('#reward-operation');
                            const displayName = type === 'points' ?
                                Swal.getPopup().querySelector('#user-display-name') :
                                Swal.getPopup().querySelector('#reward-user-display-name');
                            const pointsDisplay = type === 'points' ?
                                Swal.getPopup().querySelector('#user-points') :
                                Swal.getPopup().querySelector('#reward-user-points');
                            
                            // 显示用户信息
                            displayName.textContent = verifiedUser.display_name;
                            pointsDisplay.textContent = verifiedUser.points;
                            userInfo.classList.remove('hidden');
                            userOperation.classList.remove('hidden');
                            
                                                        // 如果是积分折扣面板，设置最大折扣金额
                            if (type === 'points') {
                                const maxDiscountDisplay = Swal.getPopup().querySelector('#max-discount-amount');
                                const pointsNeededDisplay = Swal.getPopup().querySelector('#points-needed');
                                const pointsStatusDisplay = Swal.getPopup().querySelector('#points-status');
                                const applyDiscountBtn = Swal.getPopup().querySelector('#apply-points-discount');
                                
                                // 计算最大可用积分和折扣
                                const maxDiscount = totalAdeudado * (window.RUIYI_POS.points_max_discount / 100); // 使用后台设置的最大折扣率
                                const maxPointsNeeded = Math.floor(maxDiscount * 100); // 1积分=0.01欧元
                                const availablePoints = Math.min(verifiedUser.points, maxPointsNeeded);
                                const userHasEnoughPoints = verifiedUser.points >= maxPointsNeeded;
                                
                                // 更新显示
                                maxDiscountDisplay.textContent = `€${maxDiscount.toFixed(2)}`;
                                pointsNeededDisplay.textContent = maxPointsNeeded;
                                
                                // 更新积分状态显示
                                if (userHasEnoughPoints) {
                                    pointsStatusDisplay.textContent = '<?php echo ruiyi_translate('Suficientes puntos', 'Sufficient points', '积分充足'); ?>';
                                    pointsStatusDisplay.className = 'text-sm font-medium text-green-600';
                                    applyDiscountBtn.disabled = false;
                                    applyDiscountBtn.className = 'w-full py-3 px-4 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors';
                                } else {
                                    const shortfall = maxPointsNeeded - verifiedUser.points;
                                    pointsStatusDisplay.textContent = '<?php echo ruiyi_translate('Puntos insuficientes', 'Insufficient points', '积分不足'); ?>' + ` (${shortfall})`;
                                    pointsStatusDisplay.className = 'text-sm font-medium text-red-600';
                                    applyDiscountBtn.disabled = true;
                                    applyDiscountBtn.className = 'w-full py-3 px-4 bg-gray-400 text-white rounded-lg cursor-not-allowed';
                                    applyDiscountBtn.textContent = '<?php echo ruiyi_translate('Puntos insuficientes', 'Insufficient points', '积分不足'); ?>';
                                }
                                
                                // 积分折扣按钮事件  
                                if (userHasEnoughPoints) {
                                    applyDiscountBtn.addEventListener('click', () => {
                                        // 再次检查积分是否足够
                                        if (!userHasEnoughPoints) {
                                            const shortfall = maxPointsNeeded - verifiedUser.points;
                                            Swal.showValidationMessage(`<?php echo ruiyi_translate('Puntos de usuario insuficientes', 'Insufficient user points', '用户积分不足'); ?>。<?php echo ruiyi_translate('Necesita', 'Need', '需要'); ?> ${maxPointsNeeded} <?php echo ruiyi_translate('puntos, actualmente solo tiene', 'points, currently only have', '积分，当前仅有'); ?> ${verifiedUser.points} <?php echo ruiyi_translate('puntos, faltan', 'points, short of', '积分，还差'); ?> ${shortfall} <?php echo ruiyi_translate('puntos', 'points', '积分'); ?>。`);
                                            return;
                                        }

                                    const pointsToUse = maxPointsNeeded;
                                    const discount = maxDiscount;
                                    
                                    // 发送请求扣除用户积分
                                    const formData = new URLSearchParams({
                                        action: 'ruiyi_apply_points_discount',
                                        user_id: verifiedUser.user_id,
                                        points: pointsToUse,
                                        order_total: totalAdeudado,
                                        discount_amount: maxDiscount, // 添加折扣金额参数
                                        nonce: ajaxNonce
                                    });

                                    fetch(ajaxUrl, {
                                        method: 'POST',
                                        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                                        body: formData
                                    })
                                    .then(response => response.json())
                                    .then(data => {
                                        if (data.success) {
                                            // 计算原价和折扣价
                                            const originalTotal = totalAdeudado;
                                            const discountedTotal = totalAdeudado - discount;
                                            
                                            // 更新订单总金额和状态跟踪
                                            totalAdeudado = discountedTotal;
                                            currentOriginalTotal = originalTotal;
                                            currentDiscountAmount = discount;
                                            hasDiscountApplied = true;
                                            
                                            
                                            // 禁用按钮，防止重复使用
                                            applyDiscountBtn.disabled = true;
                                            applyDiscountBtn.classList.add('bg-gray-400');
                                            applyDiscountBtn.textContent = '<?php echo ruiyi_translate('Ya se ha utilizado el descuento de puntos', 'Points discount already used', '已使用积分折扣'); ?>';
                                            
                                            // 更新所有相关的价格显示元素
                                            updateAllPriceDisplays(originalTotal, discountedTotal, discount);
                                            
                                            // 显示折扣成功提示
                                            showToast(`<?php echo ruiyi_translate('Descuento aplicado', 'Discount applied', '折扣已应用'); ?>：€${discount.toFixed(2)}`, 'success');
                                            
                                            // 更新显示的用户积分
                                            const userPointsDisplay = Swal.getPopup().querySelector('#user-points');
                                            userPointsDisplay.textContent = data.data.new_points;
                                            
                                            // 更新状态显示
                                            pointsStatusDisplay.textContent = '<?php echo ruiyi_translate('Descuento aplicado', 'Discount applied', '折扣已应用'); ?>';
                                            pointsStatusDisplay.className = 'text-sm font-medium text-green-600';
                                        } else {
                                            // 处理具体的错误类型
                                            let errorMessage = '';
                                            if (data.message && data.message.includes('insufficient') || data.message && data.message.includes('积分不足')) {
                                                errorMessage = `<?php echo ruiyi_translate('Puntos de usuario insuficientes', 'Insufficient user points', '用户积分不足'); ?>。<?php echo ruiyi_translate('Necesita', 'Need', '需要'); ?> ${maxPointsNeeded} <?php echo ruiyi_translate('puntos para descuento', 'points for discount', '积分进行折扣'); ?>。`;
                                            } else {
                                                errorMessage = '<?php echo ruiyi_translate('Error al deducir puntos', 'Points deduction failed', '积分扣除失败'); ?>：' + (data.message || '<?php echo ruiyi_translate('Error de procesamiento del servidor, por favor reintente', 'Server processing error, please retry', '服务器处理错误，请重试'); ?>');
                                            }
                                            Swal.showValidationMessage(errorMessage);
                                        }
                                    })
                                    .catch(error => {
                                        console.error('<?php echo ruiyi_translate('Error al aplicar el descuento de puntos', 'Error applying points discount', '积分扣除失败'); ?>:', error);
                                        Swal.showValidationMessage('<?php echo ruiyi_translate('Error de conexión de red, por favor verifique la red y reintente', 'Network connection error, please check network and retry', '网络连接错误，请检查网络后重试'); ?>');
                                    });
                                });
                                }
                            }
                            
                                                        // 如果是积分奖励面板，设置奖励积分和按钮事件
                            if (type === 'reward') {
                                const rewardPointsDisplay = Swal.getPopup().querySelector('#reward-points');
                                const applyRewardBtn = Swal.getPopup().querySelector('#apply-points-reward');
                                const rewardPoints = Math.floor(totalAdeudado * (window.RUIYI_POS.points_reward_rate / 100) * 100); // 奖励积分 = 消费金额 × 奖励比例 × 100
                                
                                rewardPointsDisplay.textContent = rewardPoints;
                                
                                // 积分奖励按钮事件
                                applyRewardBtn.addEventListener('click', () => {
                                    const rewardPoints = Math.floor(totalAdeudado * (window.RUIYI_POS.points_reward_rate / 100) * 100); // 奖励积分 = 消费金额 × 奖励比例 × 100
                                    
                                    // 发送请求添加用户积分
                                    const formData = new URLSearchParams({
                                        action: 'ruiyi_reward_points',
                                        user_id: verifiedUser.user_id,
                                        points: rewardPoints,
                                        order_total: totalAdeudado,
                                        nonce: ajaxNonce
                                    });

                                    fetch(ajaxUrl, {
                                        method: 'POST',
                                        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                                        body: formData
                                    })
                                    .then(response => response.json())
                                    .then(data => {
                                        if (data.success) {
                                            // 禁用按钮，防止重复使用
                                            applyRewardBtn.disabled = true;
                                            applyRewardBtn.classList.add('bg-gray-400');
                                            applyRewardBtn.textContent = '<?php echo ruiyi_translate("Recompensa de puntos obtenida", "Points reward obtained", "已获得积分奖励"); ?>';
                                            
                                            // 更新显示的用户积分
                                            const userPointsDisplay = Swal.getPopup().querySelector('#reward-user-points');
                                            userPointsDisplay.textContent = data.data.new_points;
                                        } else {
                                            Swal.showValidationMessage(window.RUIYI_TRANS.pointsRewardFailed + (data.message || window.RUIYI_TRANS.unknownError));
                                        }
                                    })
                                    .catch(error => {
                                        console.error('积分奖励失败:', error);
                                        Swal.showValidationMessage(window.RUIYI_TRANS.pointsRewardFailed + error.message);
                                    });
                                });
                            }
                            
                            // 隐藏验证区域
                            const verifyArea = type === 'points' ?
                                Swal.getPopup().querySelector('#points-user-verify') :
                                Swal.getPopup().querySelector('#reward-user-verify');
                            verifyArea.classList.add('hidden');
                        } else {
                            Swal.showValidationMessage(window.RUIYI_TRANS.userVerificationFailed + (data.message || window.RUIYI_TRANS.userNotFound));
                        }
                    })
                    .catch(error => {
                        console.error('验证用户失败:', error);
                        Swal.showValidationMessage(window.RUIYI_TRANS.verificationFailed + error.message);
                    });
                }

                // 绑定验证按钮事件
                const verifyPointsBtn = Swal.getPopup().querySelector('#verify-shortcode');
                const verifyRewardBtn = Swal.getPopup().querySelector('#verify-reward-shortcode');

                if (verifyPointsBtn) {
                    verifyPointsBtn.addEventListener('click', () => {
                        const shortcode = Swal.getPopup().querySelector('#user-shortcode').value;
                        if (shortcode.length === 4) {
                            verifyUserShortcode(shortcode, 'points');
                        } else {
                            Swal.showValidationMessage('<?php echo ruiyi_translate('Por favor, ingrese 4 dígitos', 'Please enter 4 digits', '请输入4位短码'); ?>');
                        }
                    });
                }

                if (verifyRewardBtn) {
                    verifyRewardBtn.addEventListener('click', () => {
                        const shortcode = Swal.getPopup().querySelector('#reward-user-shortcode').value;
                        if (shortcode.length === 4) {
                            verifyUserShortcode(shortcode, 'reward');
                        } else {
                            Swal.showValidationMessage('<?php echo ruiyi_translate('Por favor, ingrese 4 dígitos', 'Please enter 4 digits', '请输入4位短码'); ?>');
                        }
                    });
                }

                // 🔥 新版：电话号码自动搜索功能（桌位结账）
                const tablePhoneInput = Swal.getPopup().querySelector('#table-customer-phone');
                const tableSearchResults = Swal.getPopup().querySelector('#table-customer-search-results');
                const tableLoadingIndicator = Swal.getPopup().querySelector('#table-customer-search-loading');
                let tableSearchTimeout = null;

                if (tablePhoneInput && tableSearchResults) {
                    // 输入时自动搜索（防抖）
                    tablePhoneInput.addEventListener('input', function() {
                        const phone = this.value.trim();

                        // 清除之前的定时器
                        if (tableSearchTimeout) {
                            clearTimeout(tableSearchTimeout);
                        }

                        // 隐藏搜索结果
                        tableSearchResults.classList.add('hidden');

                        // 至少输入3位才开始搜索
                        if (phone.length < 3) {
                            return;
                        }

                        // 显示加载指示器
                        if (tableLoadingIndicator) {
                            tableLoadingIndicator.classList.remove('hidden');
                        }

                        // 防抖延迟搜索
                        tableSearchTimeout = setTimeout(() => {
                            searchTableCustomersByPhone(phone);
                        }, 300);
                    });

                    // 点击其他地方隐藏搜索结果
                    Swal.getPopup().addEventListener('click', function(e) {
                        if (!tablePhoneInput.contains(e.target) && !tableSearchResults.contains(e.target)) {
                            tableSearchResults.classList.add('hidden');
                        }
                    });
                }

                // 🔥 搜索客户函数（桌位结账）
                function searchTableCustomersByPhone(phone) {
                    var ajaxUrl = window.ajaxUrl || '<?php echo admin_url('admin-ajax.php'); ?>';
                    var ajaxNonce = window.RUIYI_POS?.nonce || posNonce;

                    const formData = new URLSearchParams({
                        action: 'ruiyi_fuzzy_search_customers',
                        search_type: 'phone',
                        search_term: phone,
                        limit: 5,
                        nonce: ajaxNonce
                    });

                    fetch(ajaxUrl, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                        body: formData
                    })
                    .then(response => response.json())
                    .then(data => {
                        // 隐藏加载指示器
                        if (tableLoadingIndicator) {
                            tableLoadingIndicator.classList.add('hidden');
                        }

                        if (data.success && data.data.customers && data.data.customers.length > 0) {
                            renderTableCustomerSearchResults(data.data.customers);
                        } else {
                            // 没有找到结果，隐藏下拉框
                            tableSearchResults.classList.add('hidden');
                        }
                    })
                    .catch(error => {
                        console.error('[桌位客户搜索] 错误:', error);
                        if (tableLoadingIndicator) {
                            tableLoadingIndicator.classList.add('hidden');
                        }
                        tableSearchResults.classList.add('hidden');
                    });
                }

                // 🔥 渲染搜索结果（桌位结账）
                function renderTableCustomerSearchResults(customers) {
                    if (!tableSearchResults) return;

                    tableSearchResults.innerHTML = '';

                    customers.forEach(customer => {
                        const item = document.createElement('div');
                        item.className = 'px-4 py-3 hover:bg-green-50 cursor-pointer border-b border-gray-100 last:border-b-0';
                        item.innerHTML = `
                            <div class="flex justify-between items-center">
                                <div>
                                    <div class="font-medium text-gray-800">${customer.name || '<?php echo ruiyi_translate('Sin nombre', 'No name', '无姓名'); ?>'}</div>
                                    <div class="text-sm text-gray-500">
                                        <i class="fas fa-phone text-xs mr-1"></i>${customer.phone}
                                        ${customer.address ? '<span class="ml-2"><i class="fas fa-map-marker-alt text-xs mr-1"></i>' + customer.address.substring(0, 20) + (customer.address.length > 20 ? '...' : '') + '</span>' : ''}
                                    </div>
                                </div>
                                <i class="fas fa-chevron-right text-gray-400"></i>
                            </div>
                        `;

                        // 点击选择客户
                        item.addEventListener('click', function() {
                            selectTableCustomer(customer);
                        });

                        tableSearchResults.appendChild(item);
                    });

                    tableSearchResults.classList.remove('hidden');
                }

                // 🔥 选择客户并填充表单（桌位结账）
                function selectTableCustomer(customer) {
                    Swal.getPopup().querySelector('#table-customer-phone').value = customer.phone || '';
                    Swal.getPopup().querySelector('#table-customer-name').value = customer.name || '';
                    Swal.getPopup().querySelector('#table-customer-business-name').value = customer.business_name || '';
                    Swal.getPopup().querySelector('#table-customer-cif-nif').value = customer.cif_nif || '';
                    Swal.getPopup().querySelector('#table-customer-address').value = customer.address || '';
                    Swal.getPopup().querySelector('#table-customer-postal').value = customer.postal_code || '';
                    Swal.getPopup().querySelector('#table-customer-email').value = customer.email || '';
                    const notesEl = Swal.getPopup().querySelector('#table-customer-notes');
                    if (notesEl) notesEl.value = '';

                    // 隐藏搜索结果
                    if (tableSearchResults) {
                        tableSearchResults.classList.add('hidden');
                    }

                    // 显示提示
                    Toastify({
                        text: `✅ <?php echo ruiyi_translate('Cliente seleccionado', 'Customer selected', '已选择客户'); ?>: ${customer.name}`,
                        duration: 2000,
                        gravity: 'top',
                        position: 'center',
                        style: { background: '#10b981' }
                    }).showToast();
                }

                // 🔥 桌位结账弹窗：添加 INTRO 键监听器
                tableEnterKeyHandler = function(e) {
                    if (e.key === 'Enter' && !e.shiftKey && !e.ctrlKey && !e.altKey) {
                        // 防抖机制
                        const now = Date.now();
                        if (now - tableLastEnterTime < 200) {
                            e.preventDefault();
                            e.stopPropagation();
                            e.stopImmediatePropagation();
                            return;
                        }
                        tableLastEnterTime = now;

                        // 排除积分、奖励和客户信息面板的输入框
                        const activeElement = document.activeElement;
                        const isInPointsInput = activeElement && (
                            activeElement.id === 'user-shortcode' ||
                            activeElement.id === 'reward-user-shortcode' ||
                            activeElement.id === 'table-customer-phone-search' ||
                            activeElement.id === 'table-customer-name' ||
                            activeElement.id === 'table-customer-phone' ||
                            activeElement.id === 'table-customer-business-name' ||
                            activeElement.id === 'table-customer-cif-nif' ||
                            activeElement.id === 'table-customer-address' ||
                            activeElement.id === 'table-customer-postal' ||
                            activeElement.id === 'table-customer-email'
                        );

                        if (isInPointsInput) {
                            return; // 在这些输入框中，保持原有行为
                        }

                        // 强化事件阻止
                        e.preventDefault();
                        e.stopPropagation();
                        e.stopImmediatePropagation();


                        // 获取并验证确认按钮
                        const confirmButton = Swal.getConfirmButton();
                        if (!confirmButton) {
                            console.error('[桌位弹窗INTRO] 完成支付按钮未找到');
                            return;
                        }

                        const isDisabled = confirmButton.disabled || confirmButton.hasAttribute('disabled');

                        if (!isDisabled) {
                            setTimeout(() => {
                                confirmButton.click();
                            }, 10);
                        } else {
                            console.warn('[桌位弹窗INTRO] ⚠️ 完成支付按钮被禁用');
                        }
                    }
                };

                // 注册监听器（捕获阶段）
                document.addEventListener('keydown', tableEnterKeyHandler, true);
            },
            willClose: () => {
                // 清理事件监听器
                if (tableEnterKeyHandler) {
                    document.removeEventListener('keydown', tableEnterKeyHandler, true);
                    tableEnterKeyHandler = null;
                }
            },
            didClose: () => {
                // 最终清理
                if (tableEnterKeyHandler) {
                    document.removeEventListener('keydown', tableEnterKeyHandler, true);
                    tableEnterKeyHandler = null;
                }
                tableLastEnterTime = 0;

                // 🔥 关键修复：弹窗关闭后刷新桌位列表，确保显示最新状态
                if (typeof renderizarMesas === 'function') {
                    renderizarMesas('payment-popup-closed');
                }
            },
            preConfirm: async () => {
                // 查找选中的支付方式按钮（支持多种颜色状态）
                const selectedPaymentBtn = Swal.getPopup().querySelector('.payment-method-btn-mesa.border-green-500') ||
                                          Swal.getPopup().querySelector('.payment-method-btn-mesa.border-blue-500') ||
                                          Swal.getPopup().querySelector('.payment-method-btn-mesa.border-purple-500') ||
                                          Swal.getPopup().querySelector('.payment-method-btn-mesa.border-teal-500');
                const metodoPago = selectedPaymentBtn?.dataset.method;
                if (!metodoPago) {
                    Swal.showValidationMessage('<?php echo ruiyi_translate('Por favor, seleccione el método de pago', 'Please select payment method', '请选择支付方式'); ?>');
                    return false;
                }

                // 获取积分使用情况
                const pointsSlider = Swal.getPopup().querySelector('#points-slider');
                const usedPoints = pointsSlider && !pointsSlider.closest('.tab-panel').classList.contains('hidden') ?
                    parseInt(pointsSlider.value) : 0;

                // 获取积分奖励情况
                const rewardPoints = verifiedUser && !Swal.getPopup().querySelector('#reward-panel').classList.contains('hidden') ?
                    Math.floor(totalAdeudado * (window.RUIYI_POS.points_reward_rate / 100) * 100) : 0;

                // 🔥 获取客户信息（可选）
                const customerName = Swal.getPopup().querySelector('#table-customer-name')?.value.trim() || '';
                const customerPhone = Swal.getPopup().querySelector('#table-customer-phone')?.value.trim() || '';
                let customerInfo = null;

                // 🔥 修复：先获取存储的外送客户数据
                const currentTableForCustomer = document.getElementById('table-number')?.value.trim();
                let storedDeliveryData = null;
                if (typeof getDeliveryCustomerData === 'function' && currentTableForCustomer) {
                    storedDeliveryData = getDeliveryCustomerData(currentTableForCustomer);
                }

                // 🔥 关键修复：合并表单数据和存储数据，表单数据优先（如果非空），否则用存储数据
                // 这样即使表单只填了姓名和电话，也能从存储中获取business_name、cif_nif、notes
                const formBusinessName = Swal.getPopup().querySelector('#table-customer-business-name')?.value.trim() || '';
                const formCifNif = Swal.getPopup().querySelector('#table-customer-cif-nif')?.value.trim() || '';
                const formAddress = Swal.getPopup().querySelector('#table-customer-address')?.value.trim() || '';
                const formPostalCode = Swal.getPopup().querySelector('#table-customer-postal')?.value.trim() || '';
                const formEmail = Swal.getPopup().querySelector('#table-customer-email')?.value.trim() || '';
                const formNotes = Swal.getPopup().querySelector('#table-customer-notes')?.value.trim() || '';

                if (customerName || customerPhone || (storedDeliveryData && (storedDeliveryData.name || storedDeliveryData.phone))) {
                    // 合并表单数据和存储数据：表单非空则用表单，否则用存储
                    customerInfo = {
                        name: customerName || (storedDeliveryData?.name || ''),
                        phone: customerPhone || (storedDeliveryData?.phone || ''),
                        business_name: formBusinessName || (storedDeliveryData?.business_name || ''),
                        cif_nif: formCifNif || (storedDeliveryData?.cif_nif || ''),
                        address: formAddress || (storedDeliveryData?.address || ''),
                        postal_code: formPostalCode || (storedDeliveryData?.postal_code || ''),
                        email: formEmail || (storedDeliveryData?.email || ''),
                        notes: formNotes || (storedDeliveryData?.notes || '')
                    };
                }

                if (customerInfo) {

                    // 🔥 如果有客户电话号码，检查是否存在，不存在则创建
                    // 🔥 修复：使用 customerInfo.phone 而不是表单变量 customerPhone
                    if (customerInfo.phone) {
                        try {
                            // 1. 先检查客户是否已存在
                            const checkResponse = await fetch(window.ajaxUrl || '<?php echo admin_url('admin-ajax.php'); ?>', {
                                method: 'POST',
                                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                                body: new URLSearchParams({
                                    action: 'ruiyi_find_customer_by_phone',
                                    phone: customerInfo.phone,  // 🔥 修复：使用 customerInfo.phone
                                    nonce: window.RUIYI_POS?.nonce || posNonce
                                })
                            });

                            const checkData = await checkResponse.json();

                            // 2. 如果客户不存在，创建新客户
                            if (!checkData.success || !checkData.data || !checkData.data.customer) {
                                const saveResult = await createCustomerInfoRecord(customerInfo);
                                // 创建客户失败也继续支付
                            }
                        } catch (error) {
                            // 检查/创建客户失败静默处理，继续支付
                        }
                    }
                }

                if (metodoPago === 'cash') {
                    const receivedAmount = parseFloat(Swal.getPopup().querySelector('#received-amount-mesa').value);
                    // 🔥 移除收款金额验证 - 允许任何金额（包括小于应付金额的情况）
                    return {
                        paymentMethod: metodoPago,
                        receivedAmount: receivedAmount,
                        changeAmount: receivedAmount - totalAdeudado,
                        companyTicketAmount: appliedCompanyTicket,
                        chequeRestauranteAmount: window.tableChequeRestauranteAmount || 0, // 🔥 餐厅抵扣票
                        usedPoints: usedPoints,
                        rewardPoints: rewardPoints,
                        userId: verifiedUser?.user_id,
                        totalAmount: totalAdeudado,
                        originalTotalAmount: originalTotalAmount,
                        customerInfo: customerInfo // 🔥 添加客户信息
                    };
                }

                if (metodoPago === 'mixed') {
                    const cashAmount = parseFloat(Swal.getPopup().querySelector('#mixed-cash-amount').value) || 0;
                    const cardAmount = parseFloat(Swal.getPopup().querySelector('#mixed-card-amount').value) || 0;
                    const totalPayment = cashAmount + cardAmount;

                    // 验证混合支付金额
                    if (cashAmount <= 0 || cardAmount <= 0) {
                        Swal.showValidationMessage('<?php echo ruiyi_translate('Los montos de efectivo y tarjeta deben ser mayores a 0', 'Both cash and card amounts must be greater than 0', '现金和刷卡金额必须都大于0'); ?>');
                        return false;
                    }

                    if (Math.abs(totalPayment - totalAdeudado) > 0.01) {
                        Swal.showValidationMessage('<?php echo ruiyi_translate('El total del pago no coincide con el monto del pedido', 'Payment total does not match order amount', '支付总额与订单金额不匹配'); ?>');
                        return false;
                    }

                    return {
                        paymentMethod: 'mixed',
                        cashAmount: cashAmount,
                        cardAmount: cardAmount,
                        companyTicketAmount: appliedCompanyTicket,
                        chequeRestauranteAmount: window.tableChequeRestauranteAmount || 0, // 🔥 餐厅抵扣票
                        totalAmount: totalPayment,
                        usedPoints: usedPoints,
                        rewardPoints: rewardPoints,
                        userId: verifiedUser?.user_id,
                        originalTotalAmount: originalTotalAmount,
                        customerInfo: customerInfo // 🔥 添加客户信息
                    };
                }

                // 🔥 修复bug：处理卡支付（card）的情况 - 此处metodoPago应该是'card'
                if (metodoPago === 'card') {
                    return {
                        paymentMethod: metodoPago,  // 确保使用正确的 'card' 值
                        cardAmount: totalAdeudado, // 🔥 修复：添加cardAmount以便小票正确显示折扣后的刷卡金额
                        companyTicketAmount: appliedCompanyTicket,
                        chequeRestauranteAmount: window.tableChequeRestauranteAmount || 0, // 🔥 餐厅抵扣票
                        usedPoints: usedPoints,
                        rewardPoints: rewardPoints,
                        userId: verifiedUser?.user_id,
                        totalAmount: totalAdeudado,
                        originalTotalAmount: originalTotalAmount,
                        customerInfo: customerInfo // 🔥 添加客户信息
                    };
                }

                // Bizum/转账支付
                if (metodoPago === 'bizum') {
                    return {
                        paymentMethod: metodoPago,
                        bizumAmount: totalAdeudado,
                        companyTicketAmount: appliedCompanyTicket,
                        chequeRestauranteAmount: window.tableChequeRestauranteAmount || 0,
                        usedPoints: usedPoints,
                        rewardPoints: rewardPoints,
                        userId: verifiedUser?.user_id,
                        totalAmount: totalAdeudado,
                        originalTotalAmount: originalTotalAmount,
                        customerInfo: customerInfo
                    };
                }

                // 计算找零金额（如果有公司钱票抵扣的话）
                const ticketChangeAmount = appliedCompanyTicket > originalTotalAmount ?
                    appliedCompanyTicket - originalTotalAmount : 0;

                return {
                    paymentMethod: metodoPago,
                    companyTicketAmount: appliedCompanyTicket,
                    chequeRestauranteAmount: window.tableChequeRestauranteAmount || 0, // 🔥 餐厅抵扣票
                    ticketChangeAmount: ticketChangeAmount,
                    usedPoints: usedPoints,
                    rewardPoints: rewardPoints,
                    userId: verifiedUser?.user_id,
                    totalAmount: totalAdeudado,
                    originalTotalAmount: originalTotalAmount,
                    customerInfo: customerInfo // 🔥 添加客户信息
                };
            },
            showCancelButton: true,
            confirmButtonText: '<?php echo ruiyi_translate("Completar Pago", "Complete Payment", "完成支付"); ?>',
            cancelButtonText: '<?php echo ruiyi_translate("Cancelar", "Cancel", "取消"); ?>',
            confirmButtonColor: '#059669',
            width: window.innerWidth < 768 ? '95%' : (ruiyiIsCheckoutTouchKeypadEnabled() ? '860px' : '600px'),
            customClass: {
                popup: 'payment-modal-responsive' + (ruiyiIsCheckoutTouchKeypadEnabled() ? ' checkout-touch-popup' : ''),
                container: 'payment-modal-container'
            }
            }).then(result => {
        if (result.isConfirmed) {
            const paymentDetails = result.value;
            
            // 如果有验证过的用户，在完成支付后刷新其短码
            if (verifiedUser) {
                
                const formData = new URLSearchParams({
                    action: 'ruiyi_refresh_shortcode',
                    user_id: verifiedUser.user_id,
                    nonce: window.RUIYI_POS.nonce
                });
                

                fetch(ajaxUrl, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                    body: formData
                })
                .then(response => {
                    if (!response.ok) {
                        throw new Error(`HTTP error! status: ${response.status}`);
                    }
                    return response.json();
                })
                .then(data => {
                    if (data.success && data.data) {
                    } else {
                        console.error('更新用户短码失败:', data.message || '未知错误', '完整响应:', data);
                    }
                })
                .catch(error => {
                    console.error('更新用户短码时出错:', error);
                });
            } else {
            }

            // 🔥 关键修复：将 cartSnapshot 添加到 paymentDetails 中传递给 finalizarMultiplesPedidos
            paymentDetails.cartSnapshot = cartSnapshot;
            finalizarMultiplesPedidos(mesa, orderIds, paymentDetails.paymentMethod, paymentDetails);
        }
    });
    }

    // 保留订单函数 - 将订单保存为稍后支付

    // 多订单结账函数 - 处理桌位的所有未结账订单
    // 公司钱票全局变量（在函数外部定义以避免作用域问题）
    let appliedCompanyTicket = 0;
    let originalTotalAmount = 0;

    function finalizarMultiplesPedidos(mesa, orderIds, metodoPago, paymentDetails) {
        // 🔥 关键修复：从 paymentDetails 中获取 cartSnapshot
        // 这解决了 crearPedidoMesa 清空购物车后，离线结账无法获取商品数据的问题
        let localCartSnapshot;
        const cartSnapshotFromDetails = paymentDetails?.cartSnapshot;

        if (cartSnapshotFromDetails && Array.isArray(cartSnapshotFromDetails) && cartSnapshotFromDetails.length > 0) {
          localCartSnapshot = JSON.parse(JSON.stringify(cartSnapshotFromDetails.filter(item => item.quantity > 0)));
        } else {
          // 🔥 回退：从当前购物车创建快照
          localCartSnapshot = JSON.parse(JSON.stringify(cart.filter(item => item.quantity > 0)));
        }

        // If cart is empty or has no items, try loading from localStorage
        if (localCartSnapshot.length === 0) {
          const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
          const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
          // 标准化桌位键：提取纯数字桌号，统一为 "Mesa X" 格式（支持任意区域名称）
          const mesaKey = `Mesa ${resolveGlobalTableNumber(mesa)}`;

          const tableStatus = mesasEstado[mesaKey];
          if (tableStatus && tableStatus.cart && Array.isArray(tableStatus.cart) && tableStatus.cart.length > 0) {
            localCartSnapshot = JSON.parse(JSON.stringify(tableStatus.cart.filter(item => item.quantity > 0)));
          } else {
            // Try sessionStorage as fallback
            const offlineCart = sessionStorage.getItem('offlineTableCart');
            if (offlineCart) {
              try {
                const parsedCart = JSON.parse(offlineCart);
                if (Array.isArray(parsedCart) && parsedCart.length > 0) {
                  localCartSnapshot = JSON.parse(JSON.stringify(parsedCart.filter(item => item.quantity > 0)));
                }
              } catch (e) {
                console.error('[桌位结账] Failed to parse offlineTableCart:', e);
              }
            }
          }
        }

        // 🔥 使用本地计算的购物车快照
        const internalCartSnapshot = localCartSnapshot;

        // 🔥 Validate cart snapshot has required fields
        if (internalCartSnapshot.length === 0) {
          console.error('[桌位结账] ❌ Cart snapshot is empty! Cannot complete payment.');
          Swal.fire({
            icon: 'error',
            title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
            text: '<?php echo ruiyi_translate("No se encontraron productos en el pedido.", "No products found in order.", "订单中未找到商品。"); ?>',
            confirmButtonColor: '#f44336'
          });
          return;
        }

        // 获取ajaxUrl和nonce
        var ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
        var ajaxNonce = window.RUIYI_POS?.nonce;

        // 🔥 PWA: Check offline status
        const isOnline = navigator.onLine && window.RUIYI_POS?.isOnline !== false;

        // 判断是否使用了公司钱票（提前定义）
        const hasCompanyTicket = paymentDetails.companyTicketAmount && paymentDetails.companyTicketAmount > 0;

        // 🔥 【关键修复】区分两种金额：
        // 1. totalAmount - 用于传递给后端的total_amount（折扣后的实际支付金额）
        // 2. receiptAmount - 用于小票显示（如果有公司钱票则显示原价）
        const totalAmount = parseFloat(paymentDetails.totalAmount || 0); // 折扣后的实际支付金额
        const receiptAmount = paymentDetails.originalTotalAmount || totalAmount; // 小票显示金额
        
        // 桌位结账必须等待服务器确认，避免前端先释放桌位但 WooCommerce 仍 processing。
        const useOptimisticTableCheckout = false;
        if (useOptimisticTableCheckout && typeof PaymentQueue !== 'undefined') {
          // // console.log('[秒结账] 🚀 开始乐观式桌位结账...', isOnline ? '(在线)' : '(离线)');

          // 🔥 先处理订单ID（在使用前定义）
          const processedOrderIdsInstant = orderIds.map(id => {
            if (typeof id === 'string') {
              return id.replace(/[^0-9]/g, '');
            }
            return id;
          }).filter(id => id);

          if (processedOrderIdsInstant.length === 0) {
            Swal.fire({
              icon: 'error',
              title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
              text: '<?php echo ruiyi_translate("No se encontraron IDs de pedidos válidos.", "No valid order IDs found.", "未找到有效的订单ID。"); ?>',
              confirmButtonColor: '#f44336'
            });
            return;
          }

          // 🔥 保存折扣百分比（在使用前定义）
          const discountPercentInstant = window.currentDiscountPercent || 0;

          // 🔥 获取桌位显示名称（用于小票打印）
          let tableDisplayNameInstant = `Mesa ${mesa}`; // 默认值
          if (window.tableCategoryMappings) {
            const globalNum = parseInt(mesa.toString().match(/\d+/)?.[0] || mesa);
            let allMappings = [];
            if (Array.isArray(window.tableCategoryMappings)) {
              allMappings = window.tableCategoryMappings;
            } else {
              allMappings = Object.values(window.tableCategoryMappings);
            }
            const mapping = allMappings.find(m => parseInt(m.global_table_number) === globalNum);
            if (mapping && mapping.category_display_name) {
              tableDisplayNameInstant = mapping.category_display_name;
            }
          }
          // // console.log('[秒结账] 桌位显示名称:', tableDisplayNameInstant);

          // 1. 立即开钱箱（现金/混合支付）
          const openDrawerOnCardInstant = window.clodopConfig?.openDrawerOnCard || false;
          const shouldOpenDrawerInstant = metodoPago === 'cash' || metodoPago === 'mixed' || (metodoPago === 'card' && openDrawerOnCardInstant);
          if (shouldOpenDrawerInstant && typeof abrirCajonDinero === 'function') {
            abrirCajonDinero().catch(err => { /* 开钱箱失败静默处理 */ });
          }

          // 2. 立即显示成功提示
          Toastify({
            text: '✅ <?php echo ruiyi_translate("Pago completado", "Payment completed", "结账成功"); ?>',
            duration: 2500,
            gravity: 'top',
            position: 'center',
            style: { background: 'linear-gradient(to right, #00b09b, #96c93d)' }
          }).showToast();

          // 🔥 保存上一单信息（在清空购物车前）
          // 🔥 【重要】桌位结账中 totalAmount 已经是扣除抵扣券后的金额（即 totalAdeudado）
          // 不需要再次扣除抵扣券！
          const chequeAmountTable = paymentDetails.chequeRestauranteAmount || 0;
          saveAndShowLastOrderInfo({
            totalAmount: totalAmount, // 🔥 桌位结账：totalAmount 已是实付金额（扣除抵扣券后）
            originalTotal: paymentDetails.originalTotalAmount || (totalAmount + chequeAmountTable), // 🔥 原价（抵扣前）
            discountAmount: paymentDetails.discountAmount || 0, // 🔥 折扣金额
            chequeAmount: chequeAmountTable, // 🔥 抵扣券金额
            paymentMethod: metodoPago,
            receivedAmount: paymentDetails.receivedAmount || 0,
            changeAmount: paymentDetails.changeAmount || 0,
            cashAmount: paymentDetails.cashAmount || 0,
            cardAmount: paymentDetails.cardAmount || 0,
            tableNumber: tableDisplayNameInstant || `Mesa ${mesa}`,
            orderType: 'table'
          });

          // 🔥 立即保存本地小票到localStorage（支持离线模式打印）
          saveLocalReceiptToStorage({
            cartItems: internalCartSnapshot,
            tableDisplayName: tableDisplayNameInstant || `Mesa ${mesa}`,
            paymentInfo: {
              method: metodoPago,
              receivedAmount: paymentDetails.receivedAmount || 0,
              changeAmount: paymentDetails.changeAmount || 0,
              cashAmount: paymentDetails.cashAmount || 0,
              cardAmount: paymentDetails.cardAmount || 0
            },
            totalAmount: totalAmount,
            originalTotal: paymentDetails.originalTotalAmount || (totalAmount + chequeAmountTable),
            discountAmount: paymentDetails.discountAmount || 0,
            discountPercent: discountPercentInstant,
            chequeAmount: chequeAmountTable,
            orderType: 'table'
          }, 'table_payment');

          // 🔥🔥🔥 【2026-01-22 关键修复】设置支付完成标志，防止后续的 autoSaveTableOrder 重复创建订单
          window._paymentJustCompleted = true;
          // 3秒后清除标志（足够时间让所有异步操作完成）
          setTimeout(() => { window._paymentJustCompleted = false; }, 3000);

          // 🔥🔥🔥 【2026-01-31 关键修复】记录已结账订单ID，防止网络延迟时旧订单重新出现
          // 在清理本地状态之前记录，这样即使 PaymentQueue 同步很慢，再次进入桌位时也能过滤掉这些订单
          if (typeof addPendingPaymentOrderIds === 'function') {
            addPendingPaymentOrderIds(processedOrderIdsInstant, mesa);
          }

          // 3. 立即清理本地状态
          cart = [];
          renderCart();
          resetAllPaymentStates('instant_checkout');

          const tableNumberInputInstant = document.getElementById('table-number');
          if (tableNumberInputInstant) {
            tableNumberInputInstant.value = '';
            updateCurrentTableDisplay('');
          }

          // 清理查看模式
          sessionStorage.removeItem('tableViewMode');
          sessionStorage.removeItem('tableOrderData');
          sessionStorage.removeItem('isViewMode');
          sessionStorage.removeItem('tableViewOrderData');

          // 清理桌位状态
          limpiarEstadoLocalMesa(mesa);
          releaseTableOnOrderComplete(mesa);

          // 4. 立即返回桌位模块
          if (typeof exitViewMode === 'function') {
            exitViewMode();
          }
          // 🔥🔥🔥 【2026-01-22 关键修复】设置跳过标志，防止 cambiarSeccion 触发重复的 autoSaveTableOrder
          // 支付完成后桌位已清理，不需要再保存订单
          window._skipAutoSaveInCambiarSeccion = true;
          if (typeof cambiarSeccion === 'function') {
            cambiarSeccion('mesas');
          }
          renderizarMesas('payment-processed');

          // 5. 后台队列处理服务器同步
          // 🔥 关键修复：根据支付方式正确设置cashAmount和cardAmount
          const isCashPaymentTable = metodoPago.toLowerCase() === 'cash' || metodoPago.toLowerCase() === 'cod';
          const isCardPaymentTable = metodoPago.toLowerCase() === 'card' || metodoPago.toLowerCase() === 'bacs';
          const isMixedPaymentTable = metodoPago.toLowerCase() === 'mixed';
          const isBizumPaymentTable = metodoPago.toLowerCase() === 'bizum';

          // 🔥 获取抵扣券和公司票金额（仅用于传递给后端记录，不再用于扣除计算）
          // chequeAmountTable 已在上方定义，直接使用
          const companyTicketAmountTable = paymentDetails.companyTicketAmount || 0;

          // 🔥 【关键修复】totalAmount 已经是扣除抵扣券后的实际应付金额
          // 因为 totalAdeudado = originalTotal - chequeAmount（在结账弹窗中已计算）
          // 所以不需要再次扣除抵扣券！
          // 日结单应记录的金额 = totalAmount（即 totalAdeudado，已扣除抵扣券）

          let tableCashForDaily = 0;
          let tableCardForDaily = 0;
          let tableBizumForDaily = 0;

          if (isCashPaymentTable) {
              // 🔥 【关键修复】现金支付：直接使用 totalAmount（已扣除抵扣券的实际应付金额）
              tableCashForDaily = totalAmount;
          } else if (isCardPaymentTable) {
              // 🔥 【关键修复】刷卡支付：直接使用 totalAmount（已扣除抵扣券的实际应付金额）
              tableCardForDaily = totalAmount;
          } else if (isBizumPaymentTable) {
              // Bizum/转账支付：直接使用 totalAmount
              tableBizumForDaily = totalAmount;
          } else if (isMixedPaymentTable) {
              // 混合支付：使用用户输入的金额（这些金额已经是正确的）
              tableCashForDaily = paymentDetails.cashAmount || 0;
              tableCardForDaily = paymentDetails.cardAmount || 0;
          }

          // 🔥 计算折扣金额（用于小票显示）
          let discountAmountInstant = 0;
          if (discountPercentInstant > 0) {
            // 订单总额（折后）= totalAmount，原价 = totalAmount / (1 - discountPercent/100)
            const originalTotalBeforeDiscount = totalAmount / (1 - discountPercentInstant / 100);
            discountAmountInstant = parseFloat((originalTotalBeforeDiscount - totalAmount).toFixed(2));
          }

          const paymentDataForQueue = {
            type: 'table',
            orderIds: processedOrderIdsInstant,
            tableNumber: mesa,
            tableDisplayName: tableDisplayNameInstant, // 🔥 修复：添加桌位显示名称用于小票打印
            paymentMethod: metodoPago,
            // 🔥 修复：日结单总额应该是实际收款金额（不含抵扣券）
            totalAmount: tableCashForDaily + tableCardForDaily + tableBizumForDaily,
            receivedAmount: paymentDetails.receivedAmount || 0,
            changeAmount: paymentDetails.changeAmount || 0,
            // 🔥 修复：使用计算后的金额
            cashAmount: tableCashForDaily,
            cardAmount: tableCardForDaily,
            bizumAmount: tableBizumForDaily,
            discountPercent: discountPercentInstant,
            discountAmount: discountAmountInstant, // 🔥 修复：添加折扣金额用于小票显示
            customerId: paymentDetails.customerInfo?.id || null,
            customerPhone: paymentDetails.customerInfo?.phone || null,
            customerName: paymentDetails.customerInfo?.name || null,
            customerAddress: paymentDetails.customerInfo?.address || null, // 🔥 添加客户地址（外送订单需要）
            // 🔥 关键修复：传递完整的客户信息对象（包含 business_name, cif_nif, notes 等）
            customerInfo: paymentDetails.customerInfo || null,
            chequeRestauranteAmount: chequeAmountTable,
            hasCompanyTicket: hasCompanyTicket,
            companyTicketAmount: companyTicketAmountTable,
            // 🔥 保存订单原始总额（含抵扣券），用于订单记录
            orderTotalAmount: totalAmount,
            originalTotalAmount: paymentDetails.originalTotalAmount || totalAmount,
            ticketChangeAmount: paymentDetails.ticketChangeAmount || 0,
            cartSnapshot: internalCartSnapshot,
            timestamp: Date.now()
          };

          PaymentQueue.addPayment(paymentDataForQueue).then(queueId => {
            // 🔥 关键修复：如果 addPayment 返回 null（IndexedDB 不可用），
            // 直接通过 AJAX 同步到服务器，不依赖队列
            if (!queueId && navigator.onLine) {
                console.warn('[秒结账] IndexedDB 不可用，直接同步桌位订单到服务器');
                PaymentQueue.syncTablePayment(paymentDataForQueue).then(result => {
                    if (result && result.success) {
                        console.log('[秒结账] ✅ 桌位订单直接同步成功');
                    } else {
                        console.error('[秒结账] ❌ 桌位订单直接同步失败');
                    }
                }).catch(err => {
                    console.error('[秒结账] ❌ 桌位订单直接同步异常:', err);
                });
            }
          }).catch(err => {
            // 🔥 队列失败时也尝试直接同步
            if (navigator.onLine) {
                console.warn('[秒结账] addPayment 失败，直接同步桌位订单到服务器');
                PaymentQueue.syncTablePayment(paymentDataForQueue).catch(err => console.error('[PaymentQueue] syncTablePayment fallback failed:', err.message));
            }
            // 如果队列失败，显示警告但不阻止用户
            Toastify({
              text: '⚠️ <?php echo ruiyi_translate("Sincronización pendiente", "Sync pending", "同步待处理"); ?>',
              duration: 3000,
              gravity: 'top',
              position: 'center',
              style: { background: '#f97316' }
            }).showToast();
          });

          return; // 立即返回，不执行后续阻塞代码
        }

        // 🔥 备用模式：如果PaymentQueue不可用或离线，使用原始流程
        if (isOnline) {
          Swal.fire({
              title: '<?php echo ruiyi_translate("Procesando pago de múltiples pedidos...", "Processing payment for multiple orders...", "正在处理多个订单的支付..."); ?>',
              text: '<?php echo ruiyi_translate("Por favor espere.", "Please wait.", "请稍候。"); ?>',
              allowOutsideClick: false,
              didOpen: () => { Swal.showLoading(); }
          });
        }

        const processedOrderIds = orderIds.map(id => {
            if (typeof id === 'string') {
                const cleanId = id.replace(/[^0-9]/g, '');
                return cleanId;
            }
            return id;
        }).filter(id => id);

        if (processedOrderIds.length === 0) {
            console.error('错误: 处理后没有有效的订单ID!');
            Swal.fire({
                icon: 'error',
                title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
                text: '<?php echo ruiyi_translate("No se encontraron IDs de pedidos válidos.", "No valid order IDs found.", "未找到有效的订单ID。"); ?>',
                confirmButtonColor: '#f44336'
            });
            return;
        }

        
        const currentOrderType = sessionStorage.getItem('tipoPedidoSeleccionado') || 'servir'; // Get order type

        // hasCompanyTicket已在函数开始处定义，无需重复定义

        // 🔥 关键修复：所有支付方式统一使用同一个后端处理函数
        // 'ruiyi_pos_complete_multiple_orders' 函数会正确合并订单并保存支付信息
        let requestData = {
            action: hasCompanyTicket ? 'ruiyi_pos_process_order_with_company_ticket' : 'ruiyi_pos_complete_multiple_orders',
            order_ids: JSON.stringify(processedOrderIds),
            payment_method: metodoPago,
            table_number: mesa,
            order_type: currentOrderType,
            total_amount: totalAmount,
            nonce: ajaxNonce
        };
        
        // 🔥 【关键修复】添加支付方式特定的参数 - 使用折扣后的金额
        if (metodoPago === 'cash') {
            requestData.received_amount = paymentDetails.receivedAmount || 0;
            requestData.change_amount = paymentDetails.changeAmount || 0;
            // 🔥 修复：使用 totalAmount（折扣后金额）
            requestData.cash_amount = totalAmount;
        } else if (metodoPago === 'mixed') {
            // 🔥 修复：混合支付使用 paymentDetails 中的金额，这些应该已经是折扣后的
            requestData.cash_amount = parseFloat(paymentDetails.cashAmount || 0);
            requestData.card_amount = parseFloat(paymentDetails.cardAmount || 0);
            // 🔥 额外验证：如果混合支付的总额不等于 totalAmount，记录警告
            const mixedTotal = requestData.cash_amount + requestData.card_amount;
            if (Math.abs(mixedTotal - totalAmount) > 0.05) {
                console.warn(`[结账] ⚠️ 混合支付金额不匹配 - 现金+刷卡: €${mixedTotal.toFixed(2)}, 应付: €${totalAmount.toFixed(2)}`);
            }
        } else if (metodoPago === 'card') {
            // 🔥 修复：刷卡支付使用 totalAmount（折扣后金额）
            requestData.card_amount = totalAmount;
        }
        
        // 如果有公司钱票抵扣，添加相关参数
        if (hasCompanyTicket) {
            requestData.company_ticket_amount = paymentDetails.companyTicketAmount;
            requestData.original_total_amount = paymentDetails.originalTotalAmount;
            if (paymentDetails.ticketChangeAmount && paymentDetails.ticketChangeAmount > 0) {
                requestData.ticket_change_amount = paymentDetails.ticketChangeAmount;
            }
        }

        // 🔥 如果有餐厅抵扣票，添加到请求数据中
        if (paymentDetails.chequeRestauranteAmount && paymentDetails.chequeRestauranteAmount > 0) {
            requestData.cheque_restaurante_amount = paymentDetails.chequeRestauranteAmount;
        }

        // 🔥 添加手动折扣信息
        // totalAmount 是折扣后的金额，需要反推原价来计算折扣金额
        // 🔥 修复：使用 toFixed(2) 避免浮点数精度问题（如多出0.01）
        const discountPercentTable = window.currentDiscountPercent || 0;
        if (discountPercentTable > 0) {
            // 🔥 正确公式：原价 = 折扣后价格 / (1 - 折扣百分比/100)
            const originalTotal = parseFloat((totalAmount / (1 - discountPercentTable / 100)).toFixed(2));
            const calculatedDiscountAmount = parseFloat((originalTotal - totalAmount).toFixed(2));
            requestData.discount_percent = discountPercentTable;
            requestData.discount_amount = calculatedDiscountAmount > 0 ? calculatedDiscountAmount : 0;
        }

        // 🔥 如果有客户信息，添加到请求数据中
        if (paymentDetails.customerInfo) {
            requestData.customer_info = JSON.stringify(paymentDetails.customerInfo);
        }

        // 🔥 PWA: Handle offline payment completion
        if (!isOnline) {
          Swal.fire({
            icon: 'warning',
            title: '<?php echo ruiyi_translate("Conexión requerida", "Connection required", "需要联网确认"); ?>',
            text: '<?php echo ruiyi_translate("Para cerrar una mesa, el servidor debe confirmar el pago. Revise la red e inténtelo de nuevo.", "To close a table, the server must confirm the payment. Check the network and try again.", "桌位结账必须等服务器确认完成。请恢复网络后重试。"); ?>',
            confirmButtonColor: '#f59e0b'
          });
          return;
          
          // Calculate discount amount from discount percent
          // 🔥 【关键修复】正确计算折扣金额
          // cartSubtotal 是折扣后的总额（使用customPrice计算），需要反推原价
          // 🔥 修复：使用 toFixed(2) 避免浮点数精度问题（如多出0.01）
          let discountAmount = 0;
          let discountPercent = window.currentDiscountPercent || 0;
          if (discountPercent > 0) {
            const cartSubtotal = parseFloat(internalCartSnapshot.reduce((sum, item) => {
              const price = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
              return sum + (price * item.quantity);
            }, 0).toFixed(2));
            // 🔥 正确公式：原价 = 折扣后价格 / (1 - 折扣百分比/100)
            const originalTotal = parseFloat((cartSubtotal / (1 - discountPercent / 100)).toFixed(2));
            discountAmount = parseFloat((originalTotal - cartSubtotal).toFixed(2));
          }

          // Get client value
          const clientSelect = document.getElementById('client-select') || document.getElementById('client');
          const client = clientSelect ? (clientSelect.value || '') : '';

          // Determine if this is an addition (view mode means adding to existing orders)
          const isViewMode = typeof ruiyiGetActiveTableViewMode === 'function'
            ? ruiyiGetActiveTableViewMode()
            : JSON.parse(sessionStorage.getItem('isViewMode') || 'null');
          const isAddition = (isViewMode && isViewMode.mode === 'view') ? 'true' : 'false';

          // 🔥 Ensure cart items have all required fields for order creation
          const validatedCart = internalCartSnapshot.map(item => {
            const validatedItem = {
              id: item.id || item.product_id || Date.now() + Math.random(),
              product_id: item.product_id || item.id || Date.now() + Math.random(),
              name: item.name || 'Unknown Product',
              quantity: parseInt(item.quantity) || 1,
              price: parseFloat(item.price) || 0,
              customPrice: item.customPrice !== undefined ? parseFloat(item.customPrice) : undefined,
              image_url: item.image_url || '/wp-content/themes/RUIYI_POS-Manager/assets/images/placeholder.png'
            };
            // Only include customPrice if it's different from price
            if (validatedItem.customPrice === validatedItem.price) {
              delete validatedItem.customPrice;
            }
            return validatedItem;
          });

          // Save payment completion as pending order
          const tempOrderId = 'OFFLINE_' + Date.now();
          const orderToSave = {
            id: tempOrderId,
            order_ids: processedOrderIds,
            table_number: mesa,
            order_type: currentOrderType,
            payment_method: metodoPago,
            total_amount: totalAmount,
            cart: validatedCart, // Use validated cart with all required fields
            customer_info: paymentDetails.customerInfo || null,
            discount: discountAmount, // Discount amount (calculated)
            discount_percent: discountPercent, // Discount percent (for reference)
            client: client, // Add client
            is_addition: isAddition, // Add is_addition flag
            is_payment_completion: true, // 🔥 【关键修复】标记为支付完成，同步时会清除桌位状态
            timestamp: Date.now(),
            status: 'pending',
            apiUrl: ajaxUrl
          };
          
          // Add payment-specific parameters
          if (metodoPago === 'cash') {
            orderToSave.received_amount = paymentDetails.receivedAmount || 0;
            orderToSave.change_amount = paymentDetails.changeAmount || 0;
          } else if (metodoPago === 'mixed') {
            orderToSave.cash_amount = paymentDetails.cashAmount || 0;
            orderToSave.card_amount = paymentDetails.cardAmount || 0;
          }
          
          // Add tip amount if available
          if (paymentDetails.tipAmount !== undefined) {
            orderToSave.tip_amount = paymentDetails.tipAmount;
          } else if (window.selectedTip !== undefined) {
            orderToSave.tip_amount = window.selectedTip || 0;
          }
          
          // Add company ticket info if applicable
          if (hasCompanyTicket) {
            orderToSave.company_ticket_amount = paymentDetails.companyTicketAmount;
            orderToSave.original_total_amount = paymentDetails.originalTotalAmount;
            if (paymentDetails.ticketChangeAmount && paymentDetails.ticketChangeAmount > 0) {
              orderToSave.ticket_change_amount = paymentDetails.ticketChangeAmount;
            }
          }

          // 🔥 Add cheque restaurante info if applicable
          if (paymentDetails.chequeRestauranteAmount && paymentDetails.chequeRestauranteAmount > 0) {
            orderToSave.cheque_restaurante_amount = paymentDetails.chequeRestauranteAmount;
          }

          // 🔥 关键修复：在保存到IndexedDB之前先清理桌位状态，防止重复同步
          // 这样即使sync在保存后立即触发，也不会重复创建订单

          // 清理桌位状态（使用多格式查找）
          const mesasEstadoPreClear = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
          const tableNumberOnlyPreClear = mesa.replace(/^(餐桌|Mesa|Table)\s*/i, '');
          const tablePrefixPreClear = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';

          // 查找并清除所有可能的桌位键名
          const prefixesPreClear = [tablePrefixPreClear, 'Mesa', 'Table', '餐桌'];
          const uniquePrefixesPreClear = [...new Set(prefixesPreClear)];
          uniquePrefixesPreClear.forEach(prefix => {
            const keyWithSpace = `${prefix} ${tableNumberOnlyPreClear}`;
            const keyWithoutSpace = `${prefix}${tableNumberOnlyPreClear}`;
            if (mesasEstadoPreClear[keyWithSpace]) {
              mesasEstadoPreClear[keyWithSpace] = {
                estado: 'libre',
                orderId: null,
                total: 0,
                timestamp: new Date().toISOString(),
                _skipAutoUpdate: true, // 🔥 【关键修复】防止被服务器状态覆盖
                _paymentCompleted: true // 🔥 标记支付已完成
              };
            }
            if (mesasEstadoPreClear[keyWithoutSpace]) {
              mesasEstadoPreClear[keyWithoutSpace] = {
                estado: 'libre',
                orderId: null,
                total: 0,
                timestamp: new Date().toISOString(),
                _skipAutoUpdate: true, // 🔥 【关键修复】防止被服务器状态覆盖
                _paymentCompleted: true // 🔥 标记支付已完成
              };
            }
          });
          localStorage.setItem('mesas_estado', JSON.stringify(mesasEstadoPreClear));

          // 清除购物车数据（保存前）
          const carritosGuardadosPreClear = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
          uniquePrefixesPreClear.forEach(prefix => {
            const keyWithSpace = `${prefix} ${tableNumberOnlyPreClear}`;
            const keyWithoutSpace = `${prefix}${tableNumberOnlyPreClear}`;
            delete carritosGuardadosPreClear[keyWithSpace];
            delete carritosGuardadosPreClear[keyWithoutSpace];
          });
          localStorage.setItem('carritos_mesas', JSON.stringify(carritosGuardadosPreClear));

          // Save to IndexedDB
          addPendingOrderFallbackIndexedDB(orderToSave).then(() => {

            Swal.close();

            // 🔥 离线支付完成：跳过弹窗，直接清理并返回桌位模块

            // 🔥🔥🔥 【2026-01-22 关键修复】设置支付完成标志
            window._paymentJustCompleted = true;
            setTimeout(() => { window._paymentJustCompleted = false; }, 3000);

            // Clear cart and reset UI
            syncCart([]);
            if (typeof renderCart === 'function') renderCart();
            resetAllPaymentStates('multiple_order_complete');

            const tableNumberInput = document.getElementById('table-number');
            if (tableNumberInput) {
              tableNumberInput.value = '';
              updateCurrentTableDisplay('');
            }

            sessionStorage.removeItem('tableViewMode');
            sessionStorage.removeItem('tableOrderData');
            sessionStorage.removeItem('tableViewOrderData');
            sessionStorage.removeItem('isViewMode');

            // 4. 返回桌位模块
            // 🔥🔥🔥 【2026-01-22 关键修复】设置跳过标志，防止 cambiarSeccion 触发重复的 autoSaveTableOrder
            window._skipAutoSaveInCambiarSeccion = true;
            if (typeof cambiarSeccion === 'function') {
              cambiarSeccion('mesas');
            }

            // 5. 显示简短的成功提示（toast风格，不阻塞）
            if (typeof Swal !== 'undefined') {
              Swal.fire({
                icon: 'success',
                title: '<?php echo ruiyi_translate('Guardado', 'Saved', '已保存'); ?>',
                text: '<?php echo ruiyi_translate('Pago guardado offline', 'Payment saved offline', '离线支付已保存'); ?>',
                timer: 1500,
                showConfirmButton: false,
                position: 'top-end',
                toast: true
              });
            }

            // 6. Refresh pending orders list
            if (typeof loadOfflinePendingOrdersIntoHistory === 'function') {
              setTimeout(() => {
                loadOfflinePendingOrdersIntoHistory();
              }, 500);
            }
          }).catch(error => {
            console.error('[PWA] Error saving offline payment:', error);
            Swal.fire({
              icon: 'error',
              title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
              text: '<?php echo ruiyi_translate("No se pudo guardar el pago offline. Por favor, inténtelo de nuevo.", "Could not save payment offline. Please try again.", "无法保存离线支付，请重试。"); ?>',
              confirmButtonColor: '#f44336'
            });
          });
          
          return; // Exit early for offline mode
        }
        
        const formData = new URLSearchParams(requestData);

        // 🔥 【关键修复】添加请求超时控制，防止网络不稳定时无限期挂起
        const paymentController = new AbortController();
        const paymentTimeoutId = setTimeout(() => {
            console.warn('[支付请求] 30秒超时，中止请求');
            paymentController.abort();
        }, 30000); // 30秒超时

        fetch(ajaxUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: formData,
            signal: paymentController.signal  // 🔥 超时控制
        })
        .then(response => {
            clearTimeout(paymentTimeoutId);  // 🔥 清除超时定时器
            if (!response.ok) {
                throw new Error(`<?php echo ruiyi_translate("Error de servidor:", "Server error:", "服务器错误："); ?> ${response.status}`);
            }
            return response.json();
        })
        .then(data => {
            if (data.success) {
                const responseData = data.data || {};
                const processedOrdersFromResponse = Array.isArray(responseData.processed_orders) ? responseData.processed_orders : [];
                const totalProcessed = Number.isFinite(Number(responseData.total_processed))
                    ? Number(responseData.total_processed)
                    : processedOrdersFromResponse.length;
                const failedOrders = Array.isArray(responseData.failed_orders) ? responseData.failed_orders : [];
                if (failedOrders.length > 0 || totalProcessed < processedOrderIds.length) {
                    throw new Error('<?php echo ruiyi_translate("El servidor no confirmó todos los pedidos. No se cerrará la mesa.", "The server did not confirm every order. The table will not be closed.", "服务器没有确认所有订单结账完成，桌位不会被释放。"); ?>');
                }
                
                // 重新定义hasCompanyTicket变量供模板字符串使用
                const hasCompanyTicketInCallback = paymentDetails.companyTicketAmount && paymentDetails.companyTicketAmount > 0;

                // 🔥 移除支付完成弹窗，直接执行后续操作

                // 🔥 关闭加载弹窗
                Swal.close();

                // 🔥 Display purchase success message on VFD
                displayVFDSuccessMessage();

                // 🔥 保存上一单信息（在清空购物车前）
                // 获取桌位显示名称
                let tableDisplayNameBackup = `Mesa ${mesa}`;
                if (window.tableCategoryMappings) {
                    const globalNum = parseInt(mesa.toString().match(/\d+/)?.[0] || mesa);
                    let allMappings = Array.isArray(window.tableCategoryMappings) ? window.tableCategoryMappings : Object.values(window.tableCategoryMappings);
                    const mapping = allMappings.find(m => parseInt(m.global_table_number) === globalNum);
                    if (mapping && mapping.category_display_name) {
                        tableDisplayNameBackup = mapping.category_display_name;
                    }
                }
                // 🔥 【重要】桌位结账中 totalAmount 已经是扣除抵扣券后的金额
                // 不需要再次扣除抵扣券！
                const chequeAmountTableBackup = paymentDetails.chequeRestauranteAmount || 0;
                saveAndShowLastOrderInfo({
                    totalAmount: totalAmount, // 🔥 桌位结账：totalAmount 已是实付金额（扣除抵扣券后）
                    originalTotal: paymentDetails.originalTotalAmount || (totalAmount + chequeAmountTableBackup), // 🔥 原价（抵扣前）
                    discountAmount: paymentDetails.discountAmount || 0, // 🔥 折扣金额
                    chequeAmount: chequeAmountTableBackup, // 🔥 抵扣券金额
                    paymentMethod: metodoPago,
                    receivedAmount: paymentDetails.receivedAmount || 0,
                    changeAmount: paymentDetails.changeAmount || 0,
                    cashAmount: paymentDetails.cashAmount || 0,
                    cardAmount: paymentDetails.cardAmount || 0,
                    tableNumber: tableDisplayNameBackup,
                    orderType: 'table'
                });

                // 🔥🔥🔥 【2026-01-22 关键修复】设置支付完成标志
                window._paymentJustCompleted = true;
                setTimeout(() => { window._paymentJustCompleted = false; }, 3000);

                // 清空购物车
                syncCart([]);
                if (typeof renderCart === 'function') renderCart();

                // 🔥 隐藏查看模式相关按钮和工具箱
                const viewModeButtons = ['checkout-table-btn', 'toolbox-toggle-btn'];
                viewModeButtons.forEach(btnId => {
                    const btn = document.getElementById(btnId);
                    if (btn) {
                        btn.classList.add('hidden');
                    }
                });

                // 🔥 关闭工具箱展开区域（Alpine.js）
                const cartActionsContainer = document.querySelector('.cart-actions-fixed');
                if (cartActionsContainer && window.Alpine) {
                    const alpineData = Alpine.$data(cartActionsContainer);
                    if (alpineData) {
                        alpineData.toolboxOpen = false;
                    }
                }

                // 清空桌号输入框
                const tableNumberInput = document.getElementById('table-number');
                if (tableNumberInput) {
                    tableNumberInput.value = '';
                    // 🔥 隐藏购物车上方的桌位号显示
                    updateCurrentTableDisplay('');
                }

                // 🔥 关键修复：使用AJAX调用前捕获的折扣信息（discountPercentTable），而不是重新读取
                // 因为window.currentDiscountPercent可能在AJAX过程中被重置
                const savedDiscountPercent = discountPercentTable || 0;

                // 重置所有折扣和支付状态
                resetAllPaymentStates('multiple_order_complete');

                // 清空查看模式信息
                sessionStorage.removeItem('tableViewMode');
                sessionStorage.removeItem('tableOrderData');
                sessionStorage.removeItem('isViewMode');
                sessionStorage.removeItem('tableViewOrderData');

                // 🔥 切换到外卖模式
                sessionStorage.setItem('tipoPedidoSeleccionado', 'llevar');

                // 🔥 更新订单类型按钮UI状态
                const takeawayBtn = document.querySelector('[data-type="llevar"]');
                const dineInBtn = document.querySelector('[data-type="servir"]');
                if (takeawayBtn && dineInBtn) {
                    takeawayBtn.classList.add('bg-[#f7310f]', 'text-white');
                    takeawayBtn.classList.remove('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');

                    dineInBtn.classList.remove('bg-[#f7310f]', 'text-white');
                    dineInBtn.classList.add('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
                }

                // 更新订单类型按钮状态（恢复外卖选项）
                if (typeof updateAllButtonStates === 'function') {
                    updateAllButtonStates();
                }

                // 清空订单标题
                const orderTitle = document.getElementById('cart-order-title');
                if (orderTitle) {
                    orderTitle.innerHTML = '';
                }

                limpiarEstadoLocalMesa(mesa);

                // 释放桌位状态 - 确保桌位被标记为可用
                releaseTableOnOrderComplete(mesa);

                // 在打印小票前，重新计算订单产品的税率

                // 🔥 关键修复：如果有合并订单ID，使用它；否则使用原始订单IDs
                const orderIdsForReceipt = responseData.merged_order_id
                    ? [responseData.merged_order_id]
                    : processedOrderIds;

                // 获取订单产品的分类税率
                const recalculateTaxRatesFormData = new URLSearchParams();
                recalculateTaxRatesFormData.append('action', 'ruiyi_get_order_products_tax_rates');
                recalculateTaxRatesFormData.append('order_ids', JSON.stringify(orderIdsForReceipt));
                recalculateTaxRatesFormData.append('nonce', ajaxNonce);

                // 先获取正确的税率数据，然后生成小票
                fetch(ajaxUrl, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                    body: recalculateTaxRatesFormData
                })
                .then(response => response.json())
                .then(taxData => {
                    // Nuevo código: Obtener HTML del ticket vía AJAX y luego imprimir
                    const printTicketFormData = new URLSearchParams();
                    printTicketFormData.append('action', 'ruiyi_pos_get_table_receipt_html');
                    printTicketFormData.append('table', mesa);
                    printTicketFormData.append('order_ids_to_print', JSON.stringify(orderIdsForReceipt));

                    // 🔥 关键修复：使用之前保存的购物车快照（包含 customPrice）
                    printTicketFormData.append('cart_data', JSON.stringify(internalCartSnapshot));

                    // 🔥 修复：使用 originalTotalAmount（抵扣券应用前的金额）作为小票的 order_total
                    // originalTotalAmount 是在支付弹窗打开时保存的原始金额（可能已包含折扣，但不包含抵扣券）
                    // PHP 会从这个金额中减去抵扣券来计算最终应付金额
                    // 例如：原价€38.65，抵扣券€20，PHP显示：小计€38.65 - 抵扣券€20 = 最终€18.65
                    const orderTotalForReceipt = paymentDetails.originalTotalAmount || totalAmount;
                    printTicketFormData.append('order_total', orderTotalForReceipt);

                    // 🔥 传递完整的桌位显示名称（包含分区信息）
                    if (window.tableCategoryMappings && mesa) {
                        const globalNumberMatch = mesa.toString().match(/\d+/);
                        if (globalNumberMatch) {
                            const globalNum = parseInt(globalNumberMatch[0]);
                            let allMappings = [];
                            if (Array.isArray(window.tableCategoryMappings)) {
                                allMappings = window.tableCategoryMappings;
                            } else {
                                allMappings = Object.values(window.tableCategoryMappings);
                            }
                            const mapping = allMappings.find(m => parseInt(m.global_table_number) === globalNum);
                            if (mapping && mapping.category_display_name) {
                                printTicketFormData.append('table_display_name', mapping.category_display_name);
                            }
                        }
                    }

                    // 传递重新计算的税率数据
                    if (taxData.success && taxData.data) {
                        printTicketFormData.append('products_with_tax_rates', JSON.stringify(taxData.data));
                    }

                    // 🔥 如果是合并订单，传递合并订单信息
                    if (responseData.merged_order_id) {
                        printTicketFormData.append('merged_order_id', responseData.merged_order_id);
                        printTicketFormData.append('original_order_numbers', responseData.original_order_numbers || '');
                    }

                    printTicketFormData.append('nonce', ajaxNonce);

                    // 传递折扣后的最终金额到小票打印，确保积分折扣正确显示
                    const hasPointsDiscount = paymentDetails && paymentDetails.usedPoints > 0;
                    if (hasPointsDiscount) {
                        // 如果使用了积分折扣，传递折扣后的金额
                        const pointsDiscount = paymentDetails.originalTotalAmount - paymentDetails.totalAmount;
                        printTicketFormData.append('final_total', paymentDetails.totalAmount);
                        printTicketFormData.append('points_discount_amount', pointsDiscount);
                        printTicketFormData.append('points_used_total', paymentDetails.usedPoints);
                    } else {
                        // 没有积分折扣时使用原始金额
                        printTicketFormData.append('final_total', totalAmount);
                    }

                    // 🔥 传递手动折扣信息（百分比折扣）
                    // 使用之前保存的折扣百分比（在resetAllPaymentStates之前保存的）
                    const manualDiscountPercent = savedDiscountPercent || 0;
                    if (manualDiscountPercent > 0) {
                        // 🔥 使用 orderTotalForReceipt（抵扣前金额）计算折扣
                        // orderTotalForReceipt 是折扣后但抵扣券前的金额
                        // 例如：原价€500，15%折扣后€425（orderTotalForReceipt），抵扣券后€325
                        const originalSubtotal = orderTotalForReceipt / (1 - manualDiscountPercent / 100);
                        const manualDiscountAmount = originalSubtotal - orderTotalForReceipt;
                        printTicketFormData.append('discount_percent', manualDiscountPercent);
                        printTicketFormData.append('discount_amount', manualDiscountAmount);
                        printTicketFormData.append('original_subtotal', originalSubtotal);
                    }

                    // 🔥 传递客户信息到小票打印
                    if (paymentDetails.customerInfo) {
                        printTicketFormData.append('customer_info', JSON.stringify(paymentDetails.customerInfo));
                    }

                    // 🔥 传递支付详情到小票打印
                    const paymentInfo = {
                        method: metodoPago,
                        cashAmount: paymentDetails.cashAmount || 0,
                        cardAmount: paymentDetails.cardAmount || 0,
                        receivedAmount: paymentDetails.receivedAmount || 0,
                        changeAmount: paymentDetails.changeAmount || 0,
                        chequeRestauranteAmount: paymentDetails.chequeRestauranteAmount || 0 // 🔥 餐厅抵扣票
                    };
                    printTicketFormData.append('payment_info', JSON.stringify(paymentInfo));

                    // 🔥 如果有餐厅抵扣票，额外传递到小票打印
                    if (paymentDetails.chequeRestauranteAmount && paymentDetails.chequeRestauranteAmount > 0) {
                        printTicketFormData.append('cheque_restaurante_amount', paymentDetails.chequeRestauranteAmount);
                    }

                    return fetch(ajaxUrl, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                        body: printTicketFormData
                    });
                })
                .then(printResponse => {
                    if (!printResponse.ok) {
                        throw new Error(`Error HTTP al obtener ticket: ${printResponse.status}`);
                    }
                    return printResponse.json();
                })
                .then(receiptData => {
                    if (receiptData.success && receiptData.data.html) {
                      // 🔥 保存小票HTML到localStorage用于重新打印
                      localStorage.setItem('lastReceiptHtml', receiptData.data.html);
                      localStorage.setItem('lastReceiptType', 'table_payment');
                      localStorage.setItem('lastReceiptTimestamp', Date.now());
                      localStorage.setItem('lastReceiptRequestBody', printTicketFormData.toString());

                        // 🖨️ 检查悬浮开关是否启用自动打印（后台开关 + 收银员开关）
                        if (_autoPrintEnabled) {
                            const printSuccess = ruiyiUnifiedPrint(receiptData.data.html, 'table_payment');
                            if (!printSuccess) {
                                console.warn('[堂食结账] CLODOP小票打印失败，已阻止浏览器打印回退');
                            }
                        }

                        // 🔥 打开钱箱 - 堂食结账完成后
                        // 根据设置决定刷卡支付是否打开钱箱
                        const openDrawerOnCardTable = window.clodopConfig?.openDrawerOnCard || false;
                        const shouldOpenDrawerTable = metodoPago === 'cash' || metodoPago === 'mixed' || (metodoPago === 'card' && openDrawerOnCardTable);

                        if (shouldOpenDrawerTable) {
                            if (typeof abrirCajonDinero === 'function') {
                                abrirCajonDinero().catch(error => {
                                    // 自动开钱箱失败静默处理
                                });
                            }
                        } else {
                        }

                    } else {
                        // 🔥 使用用户友好的打印机配置提示
                        showPrinterConfigDialog();
                    }

                    // 🔥 打印完成后返回桌位模块并切换到外卖模式
                    // 🔥 桌位结账后始终返回桌位模块
                    setTimeout(() => {
                        // 先退出查看模式，切换到外卖模式
                        if (typeof exitViewMode === 'function') {
                            exitViewMode();
                        }
                        // 🔥🔥🔥 【2026-01-22 关键修复】设置跳过标志，防止 cambiarSeccion 触发重复的 autoSaveTableOrder
                        window._skipAutoSaveInCambiarSeccion = true;
                        // 🔥 始终跳转到桌位模块（桌位结账后）
                        if (typeof cambiarSeccion === 'function') {
                            cambiarSeccion('mesas');
                        } else {
                            // 备用方案：直接点击桌位导航
                            const mesasLink = document.querySelector('a[href="#mesas"]');
                            if (mesasLink) {
                                mesasLink.click();
                            }
                        }

                        // 🔥 显示成功提示（toast风格，不阻塞）
                        if (typeof Swal !== 'undefined') {
                            Swal.fire({
                                icon: 'success',
                                title: '<?php echo ruiyi_translate('Pago completado', 'Payment completed', '支付完成'); ?>',
                                timer: 2000,
                                showConfirmButton: false,
                                position: 'top-end',
                                toast: true
                            });
                        }
                    }, 500); // 短暂延迟以确保打印任务已发送
                })
                .catch(error => {
                    console.error('🔍 [税率调试] 税率获取或小票生成错误:', error);
                    // 🔥 使用用户友好的打印机配置提示
                    showPrinterConfigDialog();

                    // 🔥 即使打印失败，也返回桌位模块
                    setTimeout(() => {
                        // 先退出查看模式，切换到外卖模式
                        if (typeof exitViewMode === 'function') {
                            exitViewMode();
                        }
                        // 🔥🔥🔥 【2026-01-22 关键修复】设置跳过标志，防止 cambiarSeccion 触发重复的 autoSaveTableOrder
                        window._skipAutoSaveInCambiarSeccion = true;
                        // 🔥 始终跳转到桌位模块（桌位结账后）
                        if (typeof cambiarSeccion === 'function') {
                            cambiarSeccion('mesas');
                        } else {
                            const mesasLink = document.querySelector('a[href="#mesas"]');
                            if (mesasLink) {
                                mesasLink.click();
                            }
                        }
                    }, 500);
                });

                renderizarMesas('payment-processed'); // Actualizar UI de mesas
                
            } else {
                const errorMsg = (data.data && data.data.message) ? data.data.message :
                                '<?php echo ruiyi_translate("Error al procesar el pago.", "Error processing payment.", "处理支付时出错。"); ?>';
                throw new Error(errorMsg);
            }
        })
        .catch(error => {
            clearTimeout(paymentTimeoutId);  // 🔥 清除超时定时器
            console.error('Error al finalizar múltiples pedidos:', error);
            window._paymentJustCompleted = false;
            Swal.fire({
                icon: 'error',
                title: '<?php echo ruiyi_translate("Pago no confirmado", "Payment not confirmed", "结账未确认"); ?>',
                html: `<div class="text-left">
                    <p class="mb-2"><?php echo ruiyi_translate("El servidor no confirmó que el pago se haya completado.", "The server did not confirm that the payment was completed.", "服务器没有确认结账完成。"); ?></p>
                    <p class="text-sm text-gray-600"><?php echo ruiyi_translate("La mesa no se liberará. Revise la conexión e inténtelo de nuevo.", "The table will not be released. Check the connection and try again.", "桌位不会被释放，请检查网络后重试。"); ?></p>
                    ${error && error.message ? `<p class="text-xs text-red-600 mt-3">${error.message}</p>` : ''}
                </div>`,
                confirmButtonText: '<?php echo ruiyi_translate("Entendido", "OK", "知道了"); ?>',
                confirmButtonColor: '#f44336'
            });
            return;
            console.warn('[PWA] Online payment failed, trying to save offline:', error);
            
            // 🔥 PWA: Try to save offline as fallback
            const tempOrderId = 'OFFLINE_' + Date.now();
            const orderToSave = {
              id: tempOrderId,
              order_ids: processedOrderIds,
              table_number: mesa,
              order_type: currentOrderType,
              payment_method: metodoPago,
              total_amount: totalAmount,
              cart: internalCartSnapshot, // Include cart snapshot for reference
              customer_info: paymentDetails.customerInfo || null,
              is_payment_completion: true, // 🔥 【关键修复】标记为支付完成，同步时会清除桌位状态
              timestamp: Date.now(),
              status: 'pending',
              apiUrl: ajaxUrl
            };
            
            // Add payment-specific parameters
            if (metodoPago === 'cash') {
              orderToSave.received_amount = paymentDetails.receivedAmount || 0;
              orderToSave.change_amount = paymentDetails.changeAmount || 0;
            } else if (metodoPago === 'mixed') {
              orderToSave.cash_amount = paymentDetails.cashAmount || 0;
              orderToSave.card_amount = paymentDetails.cardAmount || 0;
            }
            
            // Add company ticket info if applicable
            if (hasCompanyTicket) {
              orderToSave.company_ticket_amount = paymentDetails.companyTicketAmount;
              orderToSave.original_total_amount = paymentDetails.originalTotalAmount;
              if (paymentDetails.ticketChangeAmount && paymentDetails.ticketChangeAmount > 0) {
                orderToSave.ticket_change_amount = paymentDetails.ticketChangeAmount;
              }
            }

            // 🔥 关键修复：在保存到IndexedDB之前先清理桌位状态，防止重复同步

            // 清理桌位状态（使用多格式查找）
            const mesasEstadoNetErr = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
            const tableNumberOnlyNetErr = mesa.replace(/^(餐桌|Mesa|Table)\s*/i, '');
            const tablePrefixNetErr = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';

            // 查找并清除所有可能的桌位键名
            const prefixesNetErr = [tablePrefixNetErr, 'Mesa', 'Table', '餐桌'];
            const uniquePrefixesNetErr = [...new Set(prefixesNetErr)];
            uniquePrefixesNetErr.forEach(prefix => {
              const keyWithSpace = `${prefix} ${tableNumberOnlyNetErr}`;
              const keyWithoutSpace = `${prefix}${tableNumberOnlyNetErr}`;
              if (mesasEstadoNetErr[keyWithSpace]) {
                mesasEstadoNetErr[keyWithSpace] = {
                  estado: 'libre',
                  orderId: null,
                  total: 0,
                  timestamp: new Date().toISOString(),
                  _skipAutoUpdate: true, // 🔥 【关键修复】防止被服务器状态覆盖
                  _paymentCompleted: true // 🔥 标记支付已完成
                };
              }
              if (mesasEstadoNetErr[keyWithoutSpace]) {
                mesasEstadoNetErr[keyWithoutSpace] = {
                  estado: 'libre',
                  orderId: null,
                  total: 0,
                  timestamp: new Date().toISOString(),
                  _skipAutoUpdate: true, // 🔥 【关键修复】防止被服务器状态覆盖
                  _paymentCompleted: true // 🔥 标记支付已完成
                };
              }
            });
            localStorage.setItem('mesas_estado', JSON.stringify(mesasEstadoNetErr));

            // 清除购物车数据（保存前）
            const carritosGuardadosNetErr = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
            uniquePrefixesNetErr.forEach(prefix => {
              const keyWithSpace = `${prefix} ${tableNumberOnlyNetErr}`;
              const keyWithoutSpace = `${prefix}${tableNumberOnlyNetErr}`;
              delete carritosGuardadosNetErr[keyWithSpace];
              delete carritosGuardadosNetErr[keyWithoutSpace];
            });
            localStorage.setItem('carritos_mesas', JSON.stringify(carritosGuardadosNetErr));

            // Save to IndexedDB
            addPendingOrderFallbackIndexedDB(orderToSave).then(() => {

              Swal.close();

              // 🔥 离线支付完成：跳过弹窗，直接清理并返回桌位模块

              // 🔥🔥🔥 【2026-01-22 关键修复】设置支付完成标志
              window._paymentJustCompleted = true;
              setTimeout(() => { window._paymentJustCompleted = false; }, 3000);

              // Clear cart and reset UI
              syncCart([]);
              if (typeof renderCart === 'function') renderCart();
              resetAllPaymentStates('multiple_order_complete');

              const tableNumberInput = document.getElementById('table-number');
              if (tableNumberInput) {
                tableNumberInput.value = '';
                updateCurrentTableDisplay('');
              }

              sessionStorage.removeItem('tableViewMode');
              sessionStorage.removeItem('tableOrderData');
              sessionStorage.removeItem('tableViewOrderData');
              sessionStorage.removeItem('isViewMode');

              // 4. 返回桌位模块
              // 🔥🔥🔥 【2026-01-22 关键修复】设置跳过标志，防止 cambiarSeccion 触发重复的 autoSaveTableOrder
              window._skipAutoSaveInCambiarSeccion = true;
              if (typeof cambiarSeccion === 'function') {
                cambiarSeccion('mesas');
              }

              // 5. 显示简短的成功提示（toast风格，不阻塞）
              if (typeof Swal !== 'undefined') {
                Swal.fire({
                  icon: 'success',
                  title: '<?php echo ruiyi_translate('Guardado', 'Saved', '已保存'); ?>',
                  text: '<?php echo ruiyi_translate('Pago guardado offline', 'Payment saved offline', '离线支付已保存'); ?>',
                  timer: 1500,
                  showConfirmButton: false,
                  position: 'top-end',
                  toast: true
                });
              }

              // 6. Refresh pending orders list
              if (typeof loadOfflinePendingOrdersIntoHistory === 'function') {
                setTimeout(() => {
                  loadOfflinePendingOrdersIntoHistory();
                }, 500);
              }
            }).catch(offlineError => {
              console.error('[PWA] Error saving offline payment:', offlineError);
              Swal.fire({
                icon: 'error',
                title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
                text: error.message || '<?php echo ruiyi_translate("No se pudo completar el pago. Por favor, inténtelo de nuevo.", "Could not complete the payment. Please try again.", "无法完成支付，请重试。"); ?>',
                confirmButtonColor: '#f44336'
              });
            });
        });
    }

    // 🔥🔥🔥 ==================== 已结账订单追踪机制 ====================
    // 【2026-01-31 新增】解决结账后网络延迟导致旧订单重新出现的竞态条件漏洞
    // 原理：结账时记录订单ID，查询时过滤掉这些订单，同步成功后清理记录

    /**
     * 添加订单ID到"已结账但待同步"列表
     * @param {Array|string} orderIds - 订单ID或订单ID数组
     * @param {string} tableNumber - 桌位号（用于调试）
     */
    function addPendingPaymentOrderIds(orderIds, tableNumber = '') {
      try {
        const ids = Array.isArray(orderIds) ? orderIds : [orderIds];
        const validIds = ids.filter(id => id && !String(id).includes('OFFLINE_') && !String(id).includes('PENDING_'));

        if (validIds.length === 0) return;

        const pendingPayments = JSON.parse(localStorage.getItem('pending_payment_order_ids') || '{}');
        const now = Date.now();

        validIds.forEach(id => {
          const idStr = String(id).replace(/[^0-9]/g, '');
          if (idStr) {
            pendingPayments[idStr] = {
              timestamp: now,
              tableNumber: tableNumber,
              expireAt: now + 10 * 60 * 1000  // 10分钟后过期
            };
          }
        });

        localStorage.setItem('pending_payment_order_ids', JSON.stringify(pendingPayments));
        console.log('[结账追踪] ✅ 已记录待同步订单:', validIds, '桌位:', tableNumber);
      } catch (e) {
        console.error('[结账追踪] ❌ 记录订单失败:', e);
      }
    }

    /**
     * 检查订单ID是否在"已结账但待同步"列表中
     * @param {string|number} orderId - 订单ID
     * @returns {boolean} - 是否在待同步列表中
     */
    function isPendingPaymentOrderId(orderId) {
      try {
        if (!orderId) return false;
        const idStr = String(orderId).replace(/[^0-9]/g, '');
        if (!idStr) return false;

        const pendingPayments = JSON.parse(localStorage.getItem('pending_payment_order_ids') || '{}');
        const record = pendingPayments[idStr];

        if (!record) return false;

        // 检查是否过期
        if (Date.now() > record.expireAt) {
          // 已过期，删除记录
          delete pendingPayments[idStr];
          localStorage.setItem('pending_payment_order_ids', JSON.stringify(pendingPayments));
          return false;
        }

        return true;
      } catch (e) {
        console.error('[结账追踪] ❌ 检查订单失败:', e);
        return false;
      }
    }

    /**
     * 从"已结账但待同步"列表中移除订单ID（同步成功后调用）
     * @param {Array|string} orderIds - 订单ID或订单ID数组
     */
    function removePendingPaymentOrderIds(orderIds) {
      try {
        const ids = Array.isArray(orderIds) ? orderIds : [orderIds];
        const pendingPayments = JSON.parse(localStorage.getItem('pending_payment_order_ids') || '{}');
        let changed = false;

        ids.forEach(id => {
          const idStr = String(id).replace(/[^0-9]/g, '');
          if (idStr && pendingPayments[idStr]) {
            delete pendingPayments[idStr];
            changed = true;
          }
        });

        if (changed) {
          localStorage.setItem('pending_payment_order_ids', JSON.stringify(pendingPayments));
          console.log('[结账追踪] ✅ 已清理已同步订单:', ids);
        }
      } catch (e) {
        console.error('[结账追踪] ❌ 清理订单失败:', e);
      }
    }

    /**
     * 清理过期的待同步记录（自动清理机制）
     */
    function cleanExpiredPendingPayments() {
      try {
        const pendingPayments = JSON.parse(localStorage.getItem('pending_payment_order_ids') || '{}');
        const now = Date.now();
        let changed = false;

        Object.keys(pendingPayments).forEach(id => {
          if (now > pendingPayments[id].expireAt) {
            delete pendingPayments[id];
            changed = true;
          }
        });

        if (changed) {
          localStorage.setItem('pending_payment_order_ids', JSON.stringify(pendingPayments));
          console.log('[结账追踪] 🧹 已清理过期记录');
        }
      } catch (e) {
        console.error('[结账追踪] ❌ 清理过期记录失败:', e);
      }
    }

    /**
     * 过滤掉已结账但待同步的订单
     * @param {Array} orders - 服务器返回的订单数组
     * @returns {Array} - 过滤后的订单数组
     */
    function filterPendingPaymentOrders(orders) {
      if (!orders || !Array.isArray(orders)) return orders;

      // 先清理过期记录
      cleanExpiredPendingPayments();

      const filteredOrders = orders.filter(order => {
        const orderId = order.id || order.order_id;
        if (isPendingPaymentOrderId(orderId)) {
          console.log('[结账追踪] 🚫 过滤已结账订单:', orderId);
          return false;
        }
        return true;
      });

      if (filteredOrders.length < orders.length) {
        console.log('[结账追踪] 📊 过滤结果: 原始', orders.length, '个订单 → 过滤后', filteredOrders.length, '个订单');
      }

      return filteredOrders;
    }

    // 暴露到全局（供 PaymentQueue 使用）
    window.addPendingPaymentOrderIds = addPendingPaymentOrderIds;
    window.removePendingPaymentOrderIds = removePendingPaymentOrderIds;
    window.filterPendingPaymentOrders = filterPendingPaymentOrders;

    // 🔥🔥🔥 ==================== 已结账订单追踪机制 END ====================

    // 清理桌位的本地状态
    function limpiarEstadoLocalMesa(mesa) {
        // 🔥🔥🔥 【2026-01-22 关键修复】标准化桌位键格式
        // 解决键格式不一致导致的清理失败问题
        // quickSaveTableOrder 使用 "Mesa X" 格式，必须保持一致
        const tableNum = typeof ruiyiSafeResolveGlobalTableNumber === 'function'
            ? ruiyiSafeResolveGlobalTableNumber(mesa)
            : resolveGlobalTableNumber(mesa);
        const standardKey = `Mesa ${tableNum}`;

        // 🔥 全局结账保护：标记此桌位刚刚结账，防止轮询将其重新标记为占用
        if (!window._recentlyCheckedOutTables) window._recentlyCheckedOutTables = {};
        window._recentlyCheckedOutTables[tableNum] = Date.now();

        // 更新桌位状态为空闲，而不是删除
        const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');

        // 🔥 清理所有可能的键格式（确保完全清理，支持任意区域名称）
        const possibleKeys = [
            standardKey,
            mesa,
            `餐桌 ${tableNum}`,
            `Table ${tableNum}`
        ];
        // Use resolveGlobalTableNumber for safe matching (no regex guessing)
        Object.keys(mesasEstado).forEach(key => {
            if (possibleKeys.includes(key)) return;
            const keyResolved = resolveGlobalTableNumber(key);
            if (keyResolved && keyResolved === tableNum) {
                possibleKeys.push(key);
            }
        });

        possibleKeys.forEach(key => {
            if (mesasEstado[key]) {
                mesasEstado[key] = {
                    estado: 'libre',
                    orderId: null,
                    total: 0,
                    timestamp: new Date().toISOString(),
                    _skipAutoUpdate: true,     // 🔥 【关键修复】防止被服务器状态覆盖
                    _paymentCompleted: true    // 🔥 【关键修复】标记支付已完成
                };
            }
        });

        // 确保标准键存在
        mesasEstado[standardKey] = {
            estado: 'libre',
            orderId: null,
            total: 0,
            timestamp: new Date().toISOString(),
            _skipAutoUpdate: true,
            _paymentCompleted: true
        };

        localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));

        // 清除购物车数据 - 🔥 使用所有可能的键格式
        const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
        let carritosChanged = false;
        possibleKeys.forEach(key => {
            if (carritosGuardados[key]) {
                delete carritosGuardados[key];
                carritosChanged = true;
            }
        });
        if (carritosChanged) {
            localStorage.setItem('carritos_mesas', JSON.stringify(carritosGuardados));
        }

        // 🔴 重要：如果当前收银页面正在查看该桌位，清理收银页面状态
        const currentViewMode = typeof ruiyiGetActiveTableViewMode === 'function'
          ? ruiyiGetActiveTableViewMode()
          : JSON.parse(sessionStorage.getItem('isViewMode') || 'null');
        const currentTableInInput = document.getElementById('table-number')?.value;
        const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';

        // 检查是否需要清理收银页面 - 🔥 使用所有可能的键格式
        const shouldClearCashier = (
          // 查看模式下查看的是该桌位（检查所有可能的键格式）
          (currentViewMode && (
            possibleKeys.some(key => currentViewMode.table === key) ||
            ruiyiSafeResolveGlobalTableNumber(currentViewMode.table) === tableNum
          )) ||
          // 或者当前收银页面的桌位输入框显示的是该桌位
          possibleKeys.some(key => currentTableInInput === key) ||
          // 或者桌位输入框只包含数字（桌位编号）
          (currentTableInInput === tableNum)
        );

        if (shouldClearCashier) {
          // 清空收银页面的购物车 - 使用syncCart确保完全清空
          if (typeof syncCart === 'function') {
            syncCart([]); // 使用syncCart函数确保cart和window.cart都被清空
          } else {
            // 回退方案：直接清空两个变量
            if (typeof cart !== 'undefined') {
              cart = [];
            }
            if (typeof window.cart !== 'undefined') {
              window.cart = [];
            }
          }

          // 退出查看模式
          if (currentViewMode) {
            sessionStorage.removeItem('isViewMode');
            sessionStorage.removeItem('tableViewMode');
            sessionStorage.removeItem('tableViewOrderData');
          }

          // 清理购物车标题
          const orderTitle = document.getElementById('cart-order-title');
          if (orderTitle) {
            orderTitle.innerHTML = '';
          }

          // 清空桌位输入框
          const tableNumberInput = document.getElementById('table-number');
          if (tableNumberInput) {
            tableNumberInput.value = '';
          }

          // 重置订单类型为外卖
          const llevarButton = document.querySelector('.order-type[data-type="llevar"]');
          if (llevarButton) {
            llevarButton.click();
          }

          // 刷新购物车显示 - 确保购物车UI更新
          if (typeof renderCart === 'function') {
            renderCart();
          }

          // 隐藏查看模式相关按钮和工具箱
          const viewModeButtons = ['checkout-table-btn', 'toolbox-toggle-btn'];
          viewModeButtons.forEach(btnId => {
            const btn = document.getElementById(btnId);
            if (btn) {
              btn.classList.add('hidden');
            }
          });

          // 更新按钮状态
          if (typeof updateOrderButtonForType === 'function') {
            updateOrderButtonForType('llevar');
          }
        }
    }

    // 释放餐桌
    function liberarMesa(mesa) {
      // 检查餐桌状态
      const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
      const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
      
      let mensaje = '';
      let iconoTipo = 'warning';
      
      // 根据餐桌状态显示不同的提示
      if (mesasEstado[mesa] && mesasEstado[mesa].estado === 'ocupada') {
        // 有活跃订单
        mensaje = `<?php echo ruiyi_translate("Esta mesa está ocupada con la orden","This table is occupied with the order","此桌位被订单占用"); ?> #${mesasEstado[mesa].orderId || 'N/A'}. <?php echo ruiyi_translate("¿Está seguro que desea liberarla?","Are you sure you want to free it?","您确定要释放它吗？"); ?> <?php echo ruiyi_translate("Esta acción liberará la mesa y cancelará automáticamente la orden asociada en el sistema.","This action will free the table and automatically cancel the associated order in the system.","此操作将释放餐桌并自动取消系统中的关联订单。"); ?>`;
        iconoTipo = 'warning';
      } else if (carritosGuardados[mesa]) {
        // 有保存的购物车
        mensaje = `<?php echo ruiyi_translate("¿Está seguro que desea liberar","Are you sure you want to free","您确定要释放"); ?> ${mesa}? <?php echo ruiyi_translate("Se eliminará el pedido guardado y no podrá recuperarse.","The saved order will be deleted and cannot be recovered.","已保存的订单将被删除，无法恢复。"); ?>`;
        iconoTipo = 'warning';
      } else {
        // 餐桌已经是空闲状态
        Swal.fire({
          title: '<?php echo ruiyi_translate("Mesa ya está libre","Table is already free","桌位已空闲"); ?>',
          text: `<?php echo ruiyi_translate("La mesa","The table","桌位"); ?> ${mesa} <?php echo ruiyi_translate("ya está disponible.","is already available.","已可用。"); ?>`,
          icon: 'info',
          confirmButtonColor: '#3085d6'
        });
        return;
      }
      
      // 显示确认对话框
      Swal.fire({
        title: '<?php echo ruiyi_translate("Liberar Mesa","Free Table","释放餐桌"); ?>',
        text: mensaje,
        icon: iconoTipo,
        showCancelButton: true,
        confirmButtonText: '<?php echo ruiyi_translate("Sí, liberar","Yes, free","是，释放"); ?>',
        cancelButtonText: '<?php echo ruiyi_translate("Cancelar","Cancel","取消"); ?>',
        confirmButtonColor: '#f44336',
        cancelButtonColor: '#3085d6'
      }).then((result) => {
        if (result.isConfirmed) {
          // 如果餐桌有关联的订单，取消该桌位的所有订单
          if (mesasEstado[mesa] && mesasEstado[mesa].orderId) {
            // 调用取消桌位所有订单的AJAX请求
            const formData = new FormData();
            formData.append('action', 'ruiyi_pos_cancel_table_orders');
            formData.append('table_number', mesa);
            formData.append('nonce', ajaxNonce);
            
            fetch('<?php echo admin_url('admin-ajax.php'); ?>', {
              method: 'POST',
              body: formData
            })
            .then(response => response.json())
            .then(data => {
              if (data.success) {
                const cancelledCount = data.data.total_orders || 0;
                const totalAmount = data.data.total_amount || 0;
                const detailedMessage = data.data.detailed_message || '';
                
                
                if (cancelledCount > 0) {
                  Toastify({
                    text: detailedMessage || `✅ <?php echo ruiyi_translate("Se cancelaron","Cancelled","已取消"); ?> ${cancelledCount} <?php echo ruiyi_translate("órdenes de la mesa","orders from table","个订单"); ?> ${mesa}`,
                    duration: 4000,
                    gravity: "top",
                    position: "center",
                    style: { background: "#4caf50" }
                  }).showToast();
                } else {
                  // 显示没有找到订单的消息
                  Toastify({
                    text: detailedMessage || `ℹ️ <?php echo ruiyi_translate("No había órdenes pendientes para la mesa","No pending orders for table","该桌没有待处理订单"); ?> ${mesa}`,
                    duration: 3000,
                    gravity: "top",
                    position: "center",
                    style: { background: "#2196f3" }
                  }).showToast();
                }
                
                // 订单取消成功后，继续清除餐桌状态
                liberarMesaFinal(mesa, mesasEstado, carritosGuardados);
              } else {
                console.error('取消订单失败:', data.data ? data.data.message : '未知错误');
                // 即使取消订单失败，也继续释放餐桌（但显示警告）
                Toastify({
                  text: `⚠️ <?php echo ruiyi_translate("Advertencia: No se pudieron cancelar todas las órdenes","Warning: Could not cancel all orders","警告：无法取消所有订单"); ?>`,
                  duration: 4000,
                  gravity: "top",
                  position: "center",
                  style: { background: "#ff9800" }
                }).showToast();
                liberarMesaFinal(mesa, mesasEstado, carritosGuardados);
              }
            })
            .catch(error => {
              console.error('取消订单请求失败:', error);
              // 请求失败时也继续释放餐桌
              Toastify({
                text: `⚠️ <?php echo ruiyi_translate("Error al cancelar las órdenes","Error canceling orders","取消订单时出错"); ?>`,
                duration: 4000,
                gravity: "top",
                position: "center",
                style: { background: "#ff9800" }
              }).showToast();
              liberarMesaFinal(mesa, mesasEstado, carritosGuardados);
            });
          } else {
            // 没有关联订单，直接释放餐桌
            liberarMesaFinal(mesa, mesasEstado, carritosGuardados);
          }
        }
      });
    }

    // 最终释放餐桌的函数（在取消订单之后调用）
    function liberarMesaFinal(mesa, mesasEstado, carritosGuardados) {
      // 更新餐桌状态为空闲，而不是删除
      mesasEstado[mesa] = {
        estado: 'libre',
        orderId: null,
        total: 0,
        timestamp: new Date().toISOString()
      };
      localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));

      // 清除购物车数据
      if (carritosGuardados[mesa]) {
        delete carritosGuardados[mesa];
        localStorage.setItem('carritos_mesas', JSON.stringify(carritosGuardados));
      }

      // 🔴 重要：如果当前收银页面正在查看该桌位，清理收银页面状态
      const currentViewMode = typeof ruiyiGetActiveTableViewMode === 'function'
        ? ruiyiGetActiveTableViewMode()
        : JSON.parse(sessionStorage.getItem('isViewMode') || 'null');
      const currentTableInInput = document.getElementById('table-number')?.value;
      const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';

      // 检查是否需要清理收银页面
      const shouldClearCashier = (
        // 查看模式下查看的是该桌位
        (currentViewMode && (
          currentViewMode.table === mesa ||
          ruiyiSafeResolveGlobalTableNumber(currentViewMode.table) === ruiyiSafeResolveGlobalTableNumber(mesa)
        )) ||
        // 或者当前收银页面的桌位输入框显示的是该桌位
        (currentTableInInput === mesa) ||
        (currentTableInInput === mesa.replace(tablePrefix + ' ', ''))
      );

      if (shouldClearCashier) {
        // 清空收银页面的购物车 - 使用syncCart确保完全清空
        if (typeof syncCart === 'function') {
          syncCart([]); // 使用syncCart函数确保cart和window.cart都被清空
        } else {
          // 回退方案：直接清空两个变量
          if (typeof cart !== 'undefined') {
            cart = [];
          }
          if (typeof window.cart !== 'undefined') {
            window.cart = [];
          }
        }

        // 退出查看模式
        if (currentViewMode) {
          sessionStorage.removeItem('isViewMode');
          sessionStorage.removeItem('tableViewMode');
          sessionStorage.removeItem('tableViewOrderData');
        }

        // 清理购物车标题
        const orderTitle = document.getElementById('cart-order-title');
        if (orderTitle) {
          orderTitle.innerHTML = '';
        }

        // 清空桌位输入框
        const tableNumberInput = document.getElementById('table-number');
        if (tableNumberInput) {
          tableNumberInput.value = '';
        }

        // 重置订单类型为外卖
        const llevarButton = document.querySelector('.order-type[data-type="llevar"]');
        if (llevarButton) {
          llevarButton.click();
        }

        // 刷新购物车显示 - 确保购物车UI更新
        if (typeof renderCart === 'function') {
          renderCart();
        }

        // 隐藏查看模式相关按钮和工具箱
        const viewModeButtons = ['checkout-table-btn', 'toolbox-toggle-btn'];
        viewModeButtons.forEach(btnId => {
          const btn = document.getElementById(btnId);
          if (btn) {
            btn.classList.add('hidden');
          }
        });

        // 🔥 关闭工具箱展开区域（Alpine.js）
        const cartActionsContainer = document.querySelector('.cart-actions-fixed');
        if (cartActionsContainer && window.Alpine) {
          const alpineData = Alpine.$data(cartActionsContainer);
          if (alpineData) {
            alpineData.toolboxOpen = false;
          }
        }

        // 更新按钮状态
        if (typeof updateOrderButtonForType === 'function') {
          updateOrderButtonForType('llevar');
        }
      }

      // 发送服务器更新请求，确保服务器端也标记为空闲
      const tableNumber = mesa.replace(tablePrefix + ' ', '');
      const formData = new URLSearchParams();
      formData.append('action', 'update_table_status');
      formData.append('table_id', tableNumber);
      formData.append('status', 'available');
      formData.append('nonce', window.RUIYI_POS?.nonce || posNonce);
      formData.append('is_pos', 'yes');

      fetch('<?php echo admin_url("admin-ajax.php"); ?>', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: formData
      })
      .then(response => response.json())
      .then(data => {
        if (data.success) {
        } else {
          console.error('服务器端更新失败:', data);
        }
      })
      .catch(error => {
        console.error('更新服务器端桌位状态时出错:', error);
      });

      // 刷新餐桌显示
      renderizarMesas('table-freed');

      // 显示成功消息
      Toastify({
        text: `✅ <?php echo ruiyi_translate("Mesa liberada","Table freed","餐桌已释放"); ?> ${mesa}`,
        duration: 2000,
        gravity: "top",
        position: "center",
        style: { background: "#4caf50" }
      }).showToast();

      // 🔥 清台后返回桌位模块
      // 清理查看模式状态
      sessionStorage.removeItem('tableViewMode');
      sessionStorage.removeItem('tableOrderData');

      // 延迟跳转，让用户看到成功消息
      setTimeout(() => {
        // 🔥 返回桌位模块
        if (typeof cambiarSeccion === 'function') {
          cambiarSeccion('mesas');
        } else {
          // 备用方案：直接点击桌位导航
          const mesasLink = document.querySelector('a[href="#mesas"]');
          if (mesasLink) {
            mesasLink.click();
          }
        }
      }, 1500);
    }

    // 过滤餐桌 - 统一渲染系统版本
    function filtrarMesas() {
      const filtro = document.getElementById('mesa-filter').value;
      const mesasGrid = document.getElementById('mesas-grid');
      
      
      // 创建筛选函数
      let customFilter = null;
      
      if (filtro === 'occupied') {
        customFilter = (tableData) => {
          return tableData.estado === 'ocupada' ||
                 tableData.estado === 'solicitud_cuenta' ||
                 tableData.estado === 'guardada';
        };
      } else if (filtro === 'free') {
        customFilter = (tableData) => {
          return tableData.estado === 'libre';
        };
      } else {
          // 如果是 'all'，清空过滤器
          customFilter = null;
      }
      
      // 添加淡出效果
      mesasGrid.style.opacity = '0.5';
      
      // 使用防抖的渲染函数，避免过度渲染导致的闪烁
      // 将过滤器传递给渲染系统
      window.currentTableFilter = customFilter;
      
      // 使用防抖渲染，使用category-filter来立即执行
      renderizarMesas('category-filter');
      
      // 恢复透明度
      setTimeout(() => {
        mesasGrid.style.opacity = '1';
      }, 100);
    }


    // 配置暗黑模式
    const toggleDarkBtn = document.getElementById('toggle-dark');
    if (toggleDarkBtn) {
      // 检查本地存储中的主题偏好
      const isDarkMode = localStorage.getItem('darkMode') === 'true';
      
      // 应用存储的主题设置
      if (isDarkMode) {
        document.documentElement.classList.add('dark');
        toggleDarkBtn.querySelector('i').classList.remove('fa-moon');
        toggleDarkBtn.querySelector('i').classList.add('fa-sun');
      }
      
      // 添加切换事件
      toggleDarkBtn.addEventListener('click', function() {
        const isDark = document.documentElement.classList.toggle('dark');
        localStorage.setItem('darkMode', isDark);
        
        // 更新图标
        const icon = this.querySelector('i');
        if (isDark) {
          icon.classList.remove('fa-moon');
          icon.classList.add('fa-sun');
        } else {
          icon.classList.remove('fa-sun');
          icon.classList.add('fa-moon');
        }
        
        Toastify({
          text: isDark ? '🌙 Modo oscuro activado' : '☀️ Modo claro activado',
          duration: 2000,
          gravity: "top",
          position: "center",
          style: { background: "#4a5568" }
        }).showToast();
      });
    }


    
    // 确认选择桌位后的处理函数
    function handleTableSelectionConfirmed(mesaSeleccionada, estadoMesa) {
      // 🔥 关闭工具箱展开区域（确保进入桌位时工具箱是关闭状态）
      const cartActionsContainer = document.querySelector('.cart-actions-fixed');
      if (cartActionsContainer && window.Alpine) {
        const alpineData = Alpine.$data(cartActionsContainer);
        if (alpineData) {
          alpineData.toolboxOpen = false;
        }
      }

      const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
      const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');

      // 🔥🔥🔥 【关键修复】清除该桌位的 _paymentCompleted 标记
      // 原因：结账后 limpiarEstadoLocalMesa 设置 _paymentCompleted=true，防止自动保存创建重复订单
      // 但如果用户主动选择桌位开始新订单，该保护应立即解除，否则 quickSaveTableOrder 会返回 null
      const tableNumForClear = resolveGlobalTableNumber(mesaSeleccionada);
      const mesaKeyForClear = `Mesa ${tableNumForClear}`;
      if (mesasEstado[mesaKeyForClear] && mesasEstado[mesaKeyForClear]._paymentCompleted) {
        delete mesasEstado[mesaKeyForClear]._paymentCompleted;
        delete mesasEstado[mesaKeyForClear]._skipAutoUpdate;
        localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
      }
      // 同时清除全局支付完成标记
      window._paymentJustCompleted = false;

      // 清理之前的查看模式（如果存在）
      sessionStorage.removeItem('tableViewMode');
      sessionStorage.removeItem('tableOrderData');

      // 更新订单类型按钮状态（恢复外卖选项）
      setTimeout(() => {
        if (typeof updateAllButtonStates === 'function') {
          updateAllButtonStates();
        }
      }, 100);

      // 设置标记：从餐桌模块选择的新订单
      sessionStorage.setItem('fromTableModule', 'true');
      
      // 先设置桌位号，然后强制更新按钮状态
      // 🔥🔥🔥 【2026-04-06 关键修复】使用解析后的全局编号，防止自定义名"T16"等写入输入框
      // 导致下游 quickSaveTableOrder/syncTableOrderToServer 发送错误的 table_number
      const resolvedSelection = (typeof resolveGlobalTableNumber === 'function')
        ? resolveGlobalTableNumber(mesaSeleccionada)
        : mesaSeleccionada;
      const tableNumberInput = document.getElementById('table-number');
      if (tableNumberInput) {
        tableNumberInput.value = resolvedSelection;
        // 🔥 更新购物车上方的桌位号显示（仍用原始名，保留自定义显示）
        updateCurrentTableDisplay(mesaSeleccionada);
      }

      // 🔥 新增：强制设置为堂食模式并更新UI
      sessionStorage.setItem('tipoPedidoSeleccionado', 'servir');

      // 立即更新订单类型按钮UI
      const updateOrderTypeButtonsUI = () => {
        const takeawayBtn = document.querySelector('[data-type="llevar"]');
        const dineInBtn = document.querySelector('[data-type="servir"]');

        if (takeawayBtn && dineInBtn) {
          // 激活堂食按钮
          dineInBtn.classList.add('bg-[#f7310f]', 'text-white');
          dineInBtn.classList.remove('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');

          // 取消外卖按钮
          takeawayBtn.classList.remove('bg-[#f7310f]', 'text-white');
          takeawayBtn.classList.add('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
        }
      };

      // 立即强制更新按钮状态
      const forceButtonUpdate = () => {
        const actualTableNumber = tableNumberInput?.value.trim();

        // 更新订单类型标签UI
        updateOrderTypeButtonsUI();

        // 更新主按钮为"保存桌位订单"
        const sendOrderBtn = document.getElementById('send-order-btn');
        const orderBtnIcon = document.getElementById('order-btn-icon');
        const orderBtnText = document.getElementById('order-btn-text');

        if (sendOrderBtn && orderBtnIcon && orderBtnText && actualTableNumber) {
          // 堂食且有桌位号：强制设置为保存桌位订单（全宽）
          orderBtnIcon.className = 'fas fa-save mr-2';
          orderBtnText.textContent = '<?php echo ruiyi_translate('Guardar Pedido', 'Save Order', '保存订单'); ?>';
          sendOrderBtn.className = 'w-full bg-primary hover:bg-red-600 text-white font-bold px-4 py-3 rounded-lg flex items-center justify-center shadow-sm transition-all';
          sendOrderBtn.setAttribute('data-action', 'send');
        }
      };

      // 立即执行第一次更新
      forceButtonUpdate();

      // 优化延迟时间：只保留一个短延迟确保section切换完成
      setTimeout(forceButtonUpdate, 100);

      const tieneCarrito = carritosGuardados[mesaSeleccionada] ? true : false;
      const estado = estadoMesa || 'libre';
      
      // 如果有保存的订单，询问是否加载
      if (tieneCarrito) {
        Swal.fire({
          title: `<?php echo ruiyi_translate("¿Cargar", "Load", "加载"); ?> ${mesaSeleccionada}?`,
          text: '<?php echo ruiyi_translate("Esta mesa tiene un pedido guardado. ¿Desea cargarlo?", "This table has a saved order. Do you want to load it?", "此桌位有已保存的订单。是否加载？"); ?>',
          icon: 'question',
          showCancelButton: true,
          confirmButtonText: '<?php echo ruiyi_translate("Sí, cargar", "Yes, load", "是，加载"); ?>',
          cancelButtonText: '<?php echo ruiyi_translate("No, nueva orden", "No, new order", "否，新订单"); ?>'
        }).then((result) => {
          if (result.isConfirmed) {
            cargarCarritoMesa(mesaSeleccionada);
          } else {
            // 清空购物车开始新订单
            cart = [];
            renderCart();
            // 重置所有折扣和支付状态
            resetAllPaymentStates('new_table_order');
            // 清空订单标题
            const orderTitle = document.getElementById('cart-order-title');
            if (orderTitle) {
              orderTitle.innerHTML = '';
            }
          }
          
          // 切换到收银页面
          cambiarSeccion('cajero');

          // 在页面切换完成后确保按钮状态正确
          setTimeout(() => {
            if (typeof forceCorrectButtonDisplay === 'function') {
              forceCorrectButtonDisplay();
            }
          }, 800);
        });
      } else if (estado === 'ocupada') {
        // 餐桌已占用，显示订单信息
        Swal.fire({
          title: `${mesaSeleccionada} - <?php echo ruiyi_translate("Ocupada","Occupied","占用"); ?>`,
          text: `<?php echo ruiyi_translate("Esta mesa está ocupada con la orden","This table is occupied with the order","此桌位被订单占用"); ?> #${mesasEstado[mesaSeleccionada]?.orderId || 'N/A'}. <?php echo ruiyi_translate("¿Desea agregar productos?","Do you want to add products?","您想添加商品吗？"); ?>`,
          icon: 'info',
          showCancelButton: true,
          confirmButtonText: '<?php echo ruiyi_translate("Agregar productos","Add products","添加商品"); ?>',
          cancelButtonText: '<?php echo ruiyi_translate("Cancelar","Cancel","取消"); ?>'
        }).then(result => {
          if (result.isConfirmed) {
            // **修复：对于占用桌位的追加订单，应该调用viewTableOrder来正确设置查看模式**
            viewTableOrder(mesaSeleccionada);
          }
        });
      } else {
        // 直接切换到收银页面，清空购物车开始新订单
        cart = [];
        renderCart();
        // 重置所有折扣和支付状态
        resetAllPaymentStates('direct_table_switch');
        // 清空订单标题
        const orderTitle = document.getElementById('cart-order-title');
        if (orderTitle) {
          orderTitle.innerHTML = '';
        }
        cambiarSeccion('cajero');

        // 确保按钮状态正确
        setTimeout(() => {
          if (typeof forceCorrectButtonDisplay === 'function') {
            forceCorrectButtonDisplay();
          }
        }, 600);
      }
    }

    /**
     * 更新购物车上方的桌位号显示
     * @param {string} tableNumber - 桌位号（如: "1", "TERRAZA 1"等）
     */
    function updateCurrentTableDisplay(tableNumber) {
      const displayDiv = document.getElementById('current-table-display');
      const tableName = document.getElementById('current-table-name');

      if (!displayDiv || !tableName) return;

      if (!tableNumber || tableNumber.trim() === '') {
        // 如果没有桌位号，隐藏显示区域
        displayDiv.classList.add('hidden');
        tableName.textContent = '';
        return;
      }

      // 查找完整的桌位名称（包含分类信息）
      let displayName = tableNumber;

      // 尝试从桌位映射中获取完整的分类显示名称
      if (window.tableCategoryMappings) {
        // 提取数字部分
        const tableNum = parseInt(tableNumber.match(/\d+/)?.[0]);

        if (!isNaN(tableNum)) {
          // tableCategoryMappings 可能是对象或数组
          const mappings = Array.isArray(window.tableCategoryMappings)
            ? window.tableCategoryMappings
            : Object.values(window.tableCategoryMappings);

          const mapping = mappings.find(m =>
            parseInt(m.global_table_number) === tableNum
          );

          if (mapping && mapping.category_display_name) {
            displayName = mapping.category_display_name;
          }
        }
      }

      // 更新显示
      tableName.textContent = displayName;
      displayDiv.classList.remove('hidden');

      // 🔥 更新 delivery 客户信息显示
      updateDeliveryCustomerInfoDisplay(tableNumber);

      // 🔥 根据桌位分区更新产品卡片显示价格
      updateAllProductCardPrices();

    }

    /**
     * 更新 delivery 客户信息显示
     */
    function updateDeliveryCustomerInfoDisplay(tableNumber) {
      const infoDisplay = document.getElementById('delivery-customer-info-display');
      const phoneDisplay = document.getElementById('delivery-display-phone');
      const addressDisplay = document.getElementById('delivery-display-address');

      if (!infoDisplay || !phoneDisplay || !addressDisplay) return;

      // 获取客户信息
      const customerData = getDeliveryCustomerData(tableNumber);

      if (customerData && (customerData.phone || customerData.address)) {
        // 显示客户信息
        phoneDisplay.textContent = customerData.phone || '-';
        addressDisplay.textContent = customerData.address || '-';
        infoDisplay.classList.remove('hidden');
      } else {
        // 隐藏客户信息区域
        phoneDisplay.textContent = '';
        addressDisplay.textContent = '';
        infoDisplay.classList.add('hidden');
      }
    }

    /**
     * 显示购物车商品列表弹窗
     */
    function showCartItemsModal() {
      if (!cart || cart.length === 0) {
        Toastify({
          text: '<?php echo ruiyi_translate("El carrito está vacío", "Cart is empty", "购物车是空的"); ?>',
          duration: 2000,
          gravity: "top",
          position: "center",
          style: { background: "#ff9800" }
        }).showToast();
        return;
      }

      // 分离锁定和未锁定商品
      const lockedItems = cart.filter(item => item.locked);
      const unlockedItems = cart.filter(item => !item.locked);

      // 计算总额（含 supplements）
      const lockedTotal = parseFloat(lockedItems.reduce((sum, item) => {
        return sum + ((parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0))) * item.quantity);
      }, 0).toFixed(2));
      const unlockedTotal = parseFloat(unlockedItems.reduce((sum, item) => {
        return sum + ((parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0))) * item.quantity);
      }, 0).toFixed(2));
      const grandTotal = parseFloat((lockedTotal + unlockedTotal).toFixed(2));

      // 构建商品列表HTML
      let itemsHtml = '';

      // 已锁定商品列表
      if (lockedItems.length > 0) {
        itemsHtml += `
          <div class="mb-4">
            <h4 class="text-sm font-semibold text-blue-700 mb-2 flex items-center">
              <i class="fas fa-lock mr-2"></i>
              <?php echo ruiyi_translate('Productos Ordenados', 'Ordered Products', '已下单产品'); ?>
            </h4>
            <div class="space-y-1">
              ${lockedItems.map(item => {
                const displayPrice = parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0));
                return `
                <div class="flex justify-between items-center p-2 bg-blue-50 border border-blue-200 rounded">
                  <div class="flex-1">
                    <p class="font-medium text-gray-800 text-sm">${item.name}</p>
                    <p class="text-xs text-gray-600">${item.quantity} x ${displayPrice.toFixed(2)}€</p>
                  </div>
                  <p class="font-bold text-blue-700">${(displayPrice * item.quantity).toFixed(2)}€</p>
                </div>
              `}).join('')}
            </div>
            <div class="mt-2 pt-2 border-t border-blue-200 flex justify-between items-center">
              <span class="text-sm font-semibold text-gray-700"><?php echo ruiyi_translate('Subtotal Ordenado', 'Ordered Subtotal', '已下单小计'); ?>:</span>
              <span class="text-base font-bold text-blue-700">${lockedTotal.toFixed(2)}€</span>
            </div>
          </div>
        `;
      }

      // 未锁定商品列表
      if (unlockedItems.length > 0) {
        itemsHtml += `
          <div class="mb-4">
            <h4 class="text-sm font-semibold text-green-700 mb-2 flex items-center">
              <i class="fas fa-shopping-cart mr-2"></i>
              <?php echo ruiyi_translate('Nuevos Productos', 'New Products', '新增产品'); ?>
            </h4>
            <div class="space-y-1">
              ${unlockedItems.map(item => {
                const displayPrice = parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0));
                return `
                <div class="flex justify-between items-center p-2 bg-green-50 border border-green-200 rounded">
                  <div class="flex-1">
                    <p class="font-medium text-gray-800 text-sm">${item.name}</p>
                    <p class="text-xs text-gray-600">${item.quantity} x ${displayPrice.toFixed(2)}€</p>
                  </div>
                  <p class="font-bold text-green-700">${(displayPrice * item.quantity).toFixed(2)}€</p>
                </div>
              `}).join('')}
            </div>
            <div class="mt-2 pt-2 border-t border-green-200 flex justify-between items-center">
              <span class="text-sm font-semibold text-gray-700"><?php echo ruiyi_translate('Subtotal Nuevo', 'New Subtotal', '新增小计'); ?>:</span>
              <span class="text-base font-bold text-green-700">${unlockedTotal.toFixed(2)}€</span>
            </div>
          </div>
        `;
      }

      // 显示弹窗
      Swal.fire({
        title: `<i class="fas fa-receipt mr-2"></i><?php echo ruiyi_translate('Detalles del Pedido', 'Order Details', '订单详情'); ?>`,
        html: `
          <div class="text-left max-h-96 overflow-y-auto">
            ${itemsHtml}
            <div class="bg-gradient-to-r from-orange-50 to-red-50 p-3 rounded-lg">
              <div class="flex justify-between items-center">
                <span class="text-base font-bold text-gray-800"><?php echo ruiyi_translate('Total General', 'Grand Total', '总计'); ?>:</span>
                <span class="text-2xl font-bold text-primary">${grandTotal.toFixed(2)}€</span>
              </div>
            </div>
          </div>
        `,
        width: 600,
        confirmButtonText: '<?php echo ruiyi_translate('Cerrar', 'Close', '关闭'); ?>',
        confirmButtonColor: '#3b82f6',
        customClass: {
          popup: 'cart-items-modal'
        }
      });
    }

    /**
     * 清除当前桌位显示
     */
    function clearCurrentTable() {
      // 🔥 清除当前桌位标记
      window._currentViewingTable = null;

      // 清空桌位输入框
      const tableInput = document.getElementById('table-number');
      if (tableInput) {
        tableInput.value = '';
      }

      // 隐藏显示区域
      updateCurrentTableDisplay('');

      // 清空购物车
      cart = [];
      renderCart();

      // 重置所有状态
      resetAllPaymentStates('clear_table');

      // 清空订单标题
      const orderTitle = document.getElementById('cart-order-title');
      if (orderTitle) {
        orderTitle.innerHTML = '';
      }

      // 🔥 清理查看模式状态
      sessionStorage.removeItem('isViewMode');
      sessionStorage.removeItem('tableViewMode');
      sessionStorage.removeItem('tableOrderData');
      sessionStorage.removeItem('tableViewOrderData');
      sessionStorage.removeItem('fromTableModule');

      // 🔥 隐藏查看模式专用按钮
      const checkoutTableBtn = document.getElementById('checkout-table-btn');
      const toolboxToggleBtn = document.getElementById('toolbox-toggle-btn');
      if (checkoutTableBtn) checkoutTableBtn.classList.add('hidden');
      if (toolboxToggleBtn) toolboxToggleBtn.classList.add('hidden');

      // 🔥 关闭工具箱展开区域（Alpine.js）
      const cartActionsContainer = document.querySelector('.cart-actions-fixed');
      if (cartActionsContainer && window.Alpine) {
        const alpineData = Alpine.$data(cartActionsContainer);
        if (alpineData) {
          alpineData.toolboxOpen = false;
        }
      }

      // 🔥 切换到外卖模式
      sessionStorage.setItem('tipoPedidoSeleccionado', 'llevar');

      // 🔥 更新订单类型按钮UI
      const takeawayBtn = document.querySelector('[data-type="llevar"]');
      const dineInBtn = document.querySelector('[data-type="servir"]');
      if (takeawayBtn && dineInBtn) {
        // 激活外卖按钮
        takeawayBtn.classList.add('bg-[#f7310f]', 'text-white');
        takeawayBtn.classList.remove('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
        takeawayBtn.disabled = false;
        takeawayBtn.style.opacity = '1';
        takeawayBtn.style.cursor = 'default';

        // 取消堂食按钮
        dineInBtn.classList.remove('bg-[#f7310f]', 'text-white');
        dineInBtn.classList.add('bg-white', 'text-[#f7310f]', 'border', 'border-[#f7310f]');
      }

      // 🔥 显示打印小票按钮（普通模式必须显示）
      const reprintLastReceiptBtn = document.getElementById('reprint-last-receipt-btn');
      if (reprintLastReceiptBtn) {
        reprintLastReceiptBtn.classList.remove('hidden');
      }

      // 🔥 更新主按钮为外卖结账模式
      if (typeof updateOrderButtonForType === 'function') {
        updateOrderButtonForType('llevar');
      }

      // 🔥 更新所有按钮状态
      setTimeout(() => {
        if (typeof updateAllButtonStates === 'function') {
          updateAllButtonStates();
        }
      }, 100);
    }

    // 显示提示消息
    function showToast(message, type = 'info') {
      let bgColor = '#2196f3'; // 默认蓝色
      
      if (type === 'success') {
        bgColor = '#4caf50'; // 绿色
      } else if (type === 'error') {
        bgColor = '#f44336'; // 红色
      } else if (type === 'warning') {
        bgColor = '#ff9800'; // 橙色
      }
      
      Toastify({
        text: message,
        duration: 3000,
        gravity: "top",
        position: "center",
        backgroundColor: bgColor
      }).showToast();
    }

    // 更新总计金额显示
    function updateTotals(subtotal) {
      const total = subtotal;
      
      // 更新小计显示
      const subtotalElem = document.getElementById('subtotal-amount');
      if (subtotalElem) {
        subtotalElem.textContent = `€${subtotal.toFixed(2)}`;
      }
      
      // 更新总计显示
      const totalElem = document.getElementById('total-amount');
      if (totalElem) {
        totalElem.textContent = `€${total.toFixed(2)}`;
      }
    }

    // 改变餐桌状态
    function cambiarEstadoMesa(mesa, nuevoEstado) {
      // 获取当前餐桌状态
      const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
      
      // 检查餐桌是否已有状态
      if (!mesasEstado[mesa]) {
        Toastify({
          text: `⚠️ <?php echo ruiyi_translate("La mesa", "The table", "餐桌"); ?> ${mesa} <?php echo ruiyi_translate("no tiene una orden activa", "does not have an active order", "没有活动订单"); ?>`,
          duration: 3000,
          gravity: "top",
          position: "center",
          style: { background: "#ff9800" }
        }).showToast();
        return;
      }
      
      // 更新状态
      mesasEstado[mesa].estado = nuevoEstado;
      // 添加状态更新时间戳
      mesasEstado[mesa].lastUpdate = new Date().toISOString();
      
      // 保存更新后的状态
      localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
      
      // 刷新餐桌显示
      renderizarMesas('status-changed');
      
      // 显示通知
      let mensaje = '';
      let color = '';
      
      switch (nuevoEstado) {
        case 'solicitud_cuenta':
          mensaje = `🧾 <?php echo ruiyi_translate("Mesa", "Table", "餐桌"); ?> ${mesa} <?php echo ruiyi_translate("marcada para solicitud de cuenta", "marked for account request", "标记为请求结账"); ?>`;
          color = "#ff9800"; // 黄色
          break;
        case 'preparando':
          mensaje = `🍳 <?php echo ruiyi_translate("Mesa", "Table", "餐桌"); ?> ${mesa} <?php echo ruiyi_translate("marcada como preparando", "marked as preparing", "标记为准备中"); ?>`;
          color = "#2196f3"; // 蓝色
          break;
        case 'ocupada':
        default:
          mensaje = `🍽️ <?php echo ruiyi_translate("Mesa", "Table", "餐桌"); ?> ${mesa} <?php echo ruiyi_translate("marcada como ocupada", "marked as occupied", "标记为已占用"); ?>`;
          color = "#f44336"; // 红色
          break;
      }
      
      Toastify({
        text: mensaje,
        duration: 2000,
        gravity: "top",
        position: "center",
        backgroundColor: color
      }).showToast();
    }

    // 订单打印功能
    function printOrder(orderId) {
      // 显示打印提示
      Toastify({
        text: "正在准备订单打印...",
        duration: 2000,
        gravity: "top",
        position: "center",
        style: { background: "#2196f3" }
      }).showToast();
      
      // 结账小票统一获取HTML后交给 C-Lodop，避免 impresion.php/window.print 旧链路。
      jQuery.ajax({
        url: '<?php echo admin_url("admin-ajax.php"); ?>',
        type: 'POST',
        data: {
          action: 'ruiyi_pos_print_order',
          order_id: orderId,
          security: '<?php echo wp_create_nonce("pos-print-order"); ?>'
        },
        success: function(response) {
          if (response.success) {
            // 使用 RUIYI 统一打印函数
            const printSuccess = ruiyiUnifiedPrint(response.data.html, 'order_complete_ajax');
            if (!printSuccess) {
              Toastify({
                text: "<?php echo ruiyi_translate("Error al imprimir con CLODOP", "CLODOP print failed", "CLODOP打印失败"); ?>",
                duration: 3000,
                gravity: "top",
                position: "center",
                style: { background: "#f44336" }
              }).showToast();
              return;
            }
            
            // 显示成功消息
            Toastify({
              text: "<?php echo ruiyi_translate("Ticket generado correctamente", "Ticket generated correctly", "小票生成成功"); ?>",
              duration: 3000,
              gravity: "top",
              position: "center",
              style: { background: "#4caf50" }
            }).showToast();
          } else {
            // 显示错误消息
            Toastify({
              text: "<?php echo ruiyi_translate("Error al generar ticket", "Error generating ticket", "生成小票时出错"); ?>: " + response.data.message,
              duration: 3000,
              gravity: "top",
              position: "center",
              style: { background: "#f44336" }
            }).showToast();
          }
        },
        error: function(xhr, status, error) {
          console.error('Error en la impresión:', error);
          
          // 显示错误消息
          Toastify({
            text: window.RUIYI_TRANS.printError,
            duration: 3000,
            gravity: "top",
            position: "center",
            style: { background: "#f44336" }
          }).showToast();
        }
      });
    }
  </script>
</head>

