<style>
/* 打印机图标容器 */
.clodop-icon-wrapper {
  position: relative;
  width: 80px; height: 80px;
  margin: 0 auto 36px;
  display: flex; align-items: center; justify-content: center;
}
.clodop-icon-svg {
  width: 36px; height: 36px; color: #3b82f6;
  position: relative; z-index: 2;
  filter: drop-shadow(0 0 6px rgba(59,130,246,0.25));
}
.clodop-icon-ring {
  position: absolute; inset: 0;
  border: 2px solid rgba(59,130,246,0.15);
  border-top-color: #3b82f6;
  border-radius: 50%;
  animation: clodop-spin 1.2s linear infinite;
}
.clodop-icon-ring-2 {
  inset: -8px;
  border-color: rgba(59,130,246,0.06);
  border-top-color: rgba(59,130,246,0.2);
  animation-duration: 2.4s;
  animation-direction: reverse;
}
@keyframes clodop-spin { to { transform: rotate(360deg); } }

/* 图标成功状态 */
.clodop-icon-success .clodop-icon-svg { color: #10b981; filter: drop-shadow(0 0 12px rgba(16,185,129,0.5)); }
.clodop-icon-success .clodop-icon-ring { border-color: rgba(16,185,129,0.2); border-top-color: #10b981; animation: none; border-color: #10b981; }
.clodop-icon-success .clodop-icon-ring-2 { border-color: rgba(16,185,129,0.1); animation: none; }

/* 标题/消息文字淡入动画 */
.clodop-title-anim, .clodop-msg-anim {
  transition: opacity 0.4s ease, transform 0.4s ease;
}
.clodop-text-fade { opacity: 0; transform: translateY(6px); }

/* 进度条 */
.clodop-progress-bar-wrapper {
  width: 100%; height: 3px; background: #e2e8f0;
  border-radius: 3px; overflow: hidden; margin-bottom: 20px;
}
.clodop-progress-bar {
  height: 100%; background: linear-gradient(90deg, #3b82f6, #6366f1);
  border-radius: 3px; transition: width 0.6s ease;
  box-shadow: 0 0 6px rgba(59,130,246,0.25);
}
.clodop-progress-bar.done {
  background: linear-gradient(90deg, #10b981, #34d399);
  box-shadow: 0 0 6px rgba(16,185,129,0.25);
}

/* 步骤指示器 */
.clodop-steps {
  display: flex; align-items: center; justify-content: center; gap: 0; margin: 0 auto;
}
.clodop-step {
  width: 12px; height: 12px; display: flex; align-items: center; justify-content: center;
}
.clodop-step-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: #cbd5e1; transition: all 0.4s ease;
}
.clodop-step.active .clodop-step-dot {
  background: #3b82f6; box-shadow: 0 0 8px rgba(59,130,246,0.5);
  animation: clodop-dot-pulse 1.5s ease-in-out infinite;
}
.clodop-step.done .clodop-step-dot {
  background: #10b981; box-shadow: 0 0 6px rgba(16,185,129,0.4);
  animation: none;
}
.clodop-step-line {
  width: 40px; height: 2px; background: #e2e8f0; position: relative; overflow: hidden;
}
.clodop-step-line-fill {
  position: absolute; top: 0; left: 0; height: 100%; width: 0%;
  background: #3b82f6; transition: width 0.5s ease;
}
.clodop-step-line-fill.done {
  width: 100%; background: #10b981;
}
@keyframes clodop-dot-pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.3); }
}

/* 状态圆点动画 */
.clodop-status-dot-anim {
  width: 8px; height: 8px; border-radius: 50%; background: #f59e0b;
  animation: clodop-status-blink 1.5s ease-in-out infinite;
  transition: background 0.3s ease;
}
.clodop-status-dot-anim.connected { background: #10b981; animation: none; }
@keyframes clodop-status-blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}

/* 背景粒子 */
.clodop-bg-particles { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.clodop-particle {
  position: absolute; width: 6px; height: 6px; border-radius: 50%;
  background: rgba(59,130,246,0.1);
  animation: clodop-float 8s ease-in-out infinite;
}
@keyframes clodop-float {
  0%, 100% { transform: translateY(0) scale(1); opacity: 0.2; }
  50% { transform: translateY(-30px) scale(1.5); opacity: 0.5; }
}

/* 语言按钮 */
#clodop-lang-switch button:hover { border-color: #94a3b8; color: #475569; }
#clodop-lang-switch button.active { border-color: #3b82f6; color: #3b82f6; background: rgba(59,130,246,0.08); }
@keyframes clodop-fade-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
#clodop-retry-btn:hover { background: #2563eb; transform: translateY(-1px); box-shadow: 0 4px 12px rgba(59,130,246,0.3); }
</style>

<script>
(function(){
  var lang = (document.cookie.match(/ruiyi_language=(\w+)/)||[])[1] || '<?php echo defined("RUIYI_CURRENT_LANG") ? RUIYI_CURRENT_LANG : "zh"; ?>';

  // 多语言步骤文本 [title, description]
  var steps = {
    zh: [
      ['正在初始化系统', '加载收银系统核心模块...'],
      ['正在加载打印模块', '初始化打印组件...'],
      ['搜索打印机中，请稍等', '请确保打印机开关已开启'],
      ['正在检测打印机', '正在搜索可用打印机，请确保打印机已开启...'],
      ['正在验证通信通道', '确保打印服务完全就绪...'],
      ['系统就绪', '打印机已就绪，正在进入收银系统...']
    ],
    en: [
      ['Initializing System', 'Loading POS system core modules...'],
      ['Loading Print Module', 'Initializing print components...'],
      ['Searching for Printer, Please Wait', 'Please make sure the printer is turned on.'],
      ['Detecting Printers', 'Searching for available printers, please ensure the printer is turned on...'],
      ['Verifying Connection', 'Ensuring print service is fully ready...'],
      ['System Ready', 'Printer is ready, entering POS system...']
    ],
    es: [
      ['Inicializando Sistema', 'Cargando m\u00f3dulos del sistema POS...'],
      ['Cargando M\u00f3dulo de Impresi\u00f3n', 'Inicializando componentes de impresi\u00f3n...'],
      ['Buscando Impresora, Espere', 'Aseg\u00farese de que la impresora est\u00e9 encendida.'],
      ['Detectando Impresoras', 'Buscando impresoras disponibles, aseg\u00farese de que la impresora est\u00e9 encendida...'],
      ['Verificando Conexi\u00f3n', 'Asegurando que el servicio de impresi\u00f3n est\u00e9 listo...'],
      ['Sistema Listo', 'Impresora lista, entrando al sistema POS...']
    ]
  };

  var statusTexts = {
    zh: { searching: '搜索服务中...', connecting: '正在连接...', detecting: '检测打印机中...', verifying: '验证通道中...', ready: '已就绪', printerFound: '已检测到打印机: ' },
    en: { searching: 'Searching...', connecting: 'Connecting...', detecting: 'Detecting printers...', verifying: 'Verifying...', ready: 'Ready', printerFound: 'Printer found: ' },
    es: { searching: 'Buscando...', connecting: 'Conectando...', detecting: 'Detectando impresoras...', verifying: 'Verificando...', ready: 'Listo', printerFound: 'Impresora encontrada: ' }
  };

  var currentStep = 0;
  var progressValues = [5, 15, 35, 60, 80, 100]; // 每步进度（6步）

  function getStepTexts() { return steps[lang] || steps['es']; }
  function getStatusTexts() { return statusTexts[lang] || statusTexts['es']; }

  function applyLang(code) {
    lang = code;
    var btns = document.querySelectorAll('#clodop-lang-switch button');
    for (var i = 0; i < btns.length; i++) {
      btns[i].classList.toggle('active', btns[i].getAttribute('data-lang') === lang);
    }
    document.cookie = 'ruiyi_language=' + lang + ';path=/;max-age=31536000';
    // 重新应用当前步骤的文本
    setStep(currentStep, true);
  }

  function setStep(stepIndex, immediate) {
    currentStep = stepIndex;
    var s = getStepTexts();
    var st = getStatusTexts();
    if (stepIndex >= s.length) stepIndex = s.length - 1;

    var titleEl = document.getElementById('clodop-loading-title');
    var msgEl = document.getElementById('clodop-loading-msg');
    var progressEl = document.getElementById('clodop-progress-bar');
    var statusTextEl = document.getElementById('clodop-status-text');
    var statusDotEl = document.getElementById('clodop-status-dot');

    if (!titleEl) return;

    // 文字淡出 → 更新 → 淡入
    if (!immediate) {
      titleEl.classList.add('clodop-text-fade');
      msgEl.classList.add('clodop-text-fade');
      setTimeout(function() {
        titleEl.textContent = s[stepIndex][0];
        msgEl.textContent = s[stepIndex][1];
        titleEl.classList.remove('clodop-text-fade');
        msgEl.classList.remove('clodop-text-fade');
      }, 300);
    } else {
      titleEl.textContent = s[stepIndex][0];
      msgEl.textContent = s[stepIndex][1];
    }

    // 更新进度条
    progressEl.style.width = progressValues[stepIndex] + '%';
    if (stepIndex === 5) progressEl.classList.add('done');

    // 更新步骤指示器
    var allSteps = document.querySelectorAll('.clodop-step');
    var allLines = document.querySelectorAll('.clodop-step-line-fill');
    allSteps.forEach(function(el, i) {
      el.classList.remove('active', 'done');
      if (i < stepIndex) el.classList.add('done');
      else if (i === stepIndex) el.classList.add('active');
    });
    allLines.forEach(function(el, i) {
      if (i < stepIndex) el.classList.add('done');
      else el.classList.remove('done');
    });

    // 更新状态文本
    if (stepIndex <= 2) { statusTextEl.textContent = st.searching; statusDotEl.className = 'clodop-status-dot-anim'; }
    else if (stepIndex === 3) { statusTextEl.textContent = st.detecting; statusDotEl.className = 'clodop-status-dot-anim'; }
    else if (stepIndex === 4) { statusTextEl.textContent = st.verifying; statusDotEl.className = 'clodop-status-dot-anim'; }
    else { statusTextEl.textContent = st.ready; statusDotEl.className = 'clodop-status-dot-anim connected'; }
  }

  // 初始化
  setStep(0, true);

  window._clodopSwitchLang = function(code) { applyLang(code); };

  // 全局接口供 clodop-integration-fixed.js 使用
  // === 超时按钮多语言 ===
  var timeoutTexts = {
    zh: {
      hint: 'CLodop打印服务尚未启动，系统正在持续检测中，请确保CLodop已安装并运行。',
      retry: '重新尝试连接'
    },
    en: {
      hint: 'CLodop print service not yet started. System is continuously detecting. Please ensure CLodop is installed and running.',
      retry: 'Retry Connection'
    },
    es: {
      hint: 'El servicio de impresión CLodop aún no se ha iniciado. El sistema sigue detectando. Asegúrese de que CLodop esté instalado y en ejecución.',
      retry: 'Reintentar conexión'
    }
  };

  function getTimeoutTexts() { return timeoutTexts[lang] || timeoutTexts['es']; }

  function updateTimeoutButtonTexts() {
    var tt = getTimeoutTexts();
    var hintEl = document.getElementById('clodop-timeout-hint');
    var retrySpan = document.querySelector('#clodop-retry-btn span');
    if (hintEl) hintEl.textContent = tt.hint;
    if (retrySpan) retrySpan.textContent = tt.retry;
  }

  // === 30秒超时：显示按钮 + 再30秒自动刷新 ===
  var _clodopTimeoutTimer = null;
  var _clodopAutoReloadTimer = null;
  var _clodopConnected = false;

  function clearAllTimers() {
    clearTimeout(_clodopTimeoutTimer);
    clearTimeout(_clodopAutoReloadTimer);
  }

  function startTimeoutTimer() {
    clearAllTimers();
    _clodopTimeoutTimer = setTimeout(function() {
      if (_clodopConnected) return;
      // 显示提示信息和重试按钮（轮询会持续在后台运行，不再自动刷新）
      var actionsEl = document.getElementById('clodop-timeout-actions');
      if (actionsEl) {
        updateTimeoutButtonTexts();
        actionsEl.style.display = 'block';
      }
    }, 30000);
  }

  // === 重试连接 → 直接刷新页面 ===
  window._clodopRetryConnection = function() {
    location.reload();
  };

  window._clodopLoading = {
    show: function() {
      var el = document.getElementById('clodop-loading-screen');
      el.style.display = 'block';
      el.style.opacity = '1';
      _clodopConnected = false;
      // 隐藏按钮（页面刚加载时）
      var actionsEl = document.getElementById('clodop-timeout-actions');
      if (actionsEl) actionsEl.style.display = 'none';
      startTimeoutTimer();
    },
    hide: function() {
      _clodopConnected = true;
      clearAllTimers();
      var el = document.getElementById('clodop-loading-screen');
      el.style.transition = 'opacity 0.6s ease';
      el.style.opacity = '0';
      setTimeout(function(){ el.style.display = 'none'; }, 600);
    },
    setStep: function(idx) { setStep(idx, false); },
    setConnected: function(printerName) {
      _clodopConnected = true;
      clearAllTimers();
      var iw = document.querySelector('.clodop-icon-wrapper');
      if (iw) iw.classList.add('clodop-icon-success');
      setStep(5, false);
      // 隐藏超时按钮（如果已显示）
      var actionsEl = document.getElementById('clodop-timeout-actions');
      if (actionsEl) actionsEl.style.display = 'none';
      // 显示检测到的打印机名称
      if (printerName) {
        var st = getStatusTexts();
        setTimeout(function() {
          var statusTextEl = document.getElementById('clodop-status-text');
          if (statusTextEl) statusTextEl.textContent = st.printerFound + printerName;
        }, 400);
      }
    },
    setStatusText: function(text) {
      var el = document.getElementById('clodop-status-text');
      if (el) el.textContent = text;
    },
    getStepTexts: function() { return getStepTexts(); },
    getStatusTexts: function() { return getStatusTexts(); },
    lang: function() { return lang; }
  };

  // 语言切换时也更新超时按钮文本
  var _origApplyLang = applyLang;
  applyLang = function(code) {
    _origApplyLang(code);
    var actionsEl = document.getElementById('clodop-timeout-actions');
    if (actionsEl && actionsEl.style.display !== 'none') {
      updateTimeoutButtonTexts();
    }
  };
})();
</script>

