                  <!-- 一级分类按钮 -->
                  <div id="level-1-categories" class="grid grid-cols-<?php echo intval(get_option('pos_category_columns_count', '5')); ?> gap-2 categories-container">
                    <?php
                    // 只获取顶层分类（parent=0）
                    $categories = get_terms([
                      'taxonomy' => 'product_cat',
                      'hide_empty' => false,
                      'parent' => 0,
                      'orderby' => 'name',
                      'order' => 'ASC',
                    ]);

                    // 按 sort_order 排序一级分类
                    $categories_with_order = [];
                    foreach ($categories as $category) {
                      if (in_array($category->slug, ['uncategorized', 'suplementos'])) continue;
                      $sort_order = get_term_meta($category->term_id, 'category_sort_order', true);
                      $category->sort_order = $sort_order !== '' ? intval($sort_order) : 999;
                      $categories_with_order[] = $category;
                    }
                    usort($categories_with_order, function($a, $b) {
                      return $a->sort_order - $b->sort_order;
                    });

                    // 🔥 存储第一个分类ID及其所有子分类ID（用于初始产品过滤）
                    $first_category_id = !empty($categories_with_order) ? $categories_with_order[0]->term_id : 0;
                    $first_category_all_ids = array($first_category_id);
                    if ($first_category_id > 0) {
                      $first_cat_descendants = get_term_children($first_category_id, 'product_cat');
                      if (!is_wp_error($first_cat_descendants)) {
                        $first_category_all_ids = array_merge($first_category_all_ids, $first_cat_descendants);
                      }
                    }

                    // 🔥 预加载所有分类的子分类ID映射（用于同步分类过滤，避免AJAX调用）
                    $category_descendants_map = array();
                    foreach ($categories_with_order as $cat) {
                      $cat_id = $cat->term_id;
                      $descendants = array($cat_id);
                      $all_children = get_term_children($cat_id, 'product_cat');
                      if (!is_wp_error($all_children) && !empty($all_children)) {
                        $descendants = array_merge($descendants, $all_children);
                      }
                      $category_descendants_map[$cat_id] = array_map('intval', $descendants);

                      // 同时为每个子分类也创建映射
                      if (!is_wp_error($all_children)) {
                        foreach ($all_children as $child_id) {
                          if (!isset($category_descendants_map[$child_id])) {
                            $child_descendants = array($child_id);
                            $grandchildren = get_term_children($child_id, 'product_cat');
                            if (!is_wp_error($grandchildren) && !empty($grandchildren)) {
                              $child_descendants = array_merge($child_descendants, $grandchildren);
                            }
                            $category_descendants_map[$child_id] = array_map('intval', $child_descendants);
                          }
                        }
                      }
                    }

                    // 🔥 获取全局分类颜色设置
                    $global_unselected_bg = get_option('pos_category_unselected_bg', '#E05C40');
                    $global_unselected_text = get_option('pos_category_unselected_text', '#C45A3B');
                    $global_unselected_border = get_option('pos_category_unselected_border', '#E05C40');
                    $global_unselected_opacity = get_option('pos_category_unselected_opacity', '100') / 100;
                    // 🔥 获取背景浓度设置并转换为十六进制
                    $bg_intensity_percent = intval(get_option('pos_category_unselected_bg_intensity', '19'));
                    $bg_intensity_hex = str_pad(dechex(round($bg_intensity_percent / 100 * 255)), 2, '0', STR_PAD_LEFT);

                    foreach ($categories_with_order as $category) :
                      // 检查是否有子分类
                      $child_terms = get_term_children($category->term_id, 'product_cat');
                      $has_children = false;
                      if (!is_wp_error($child_terms) && !empty($child_terms)) {
                          foreach ($child_terms as $child_id) {
                              $child_term = get_term($child_id, 'product_cat');
                              if ($child_term && !in_array($child_term->slug, ['uncategorized', 'suplementos']) && $child_term->parent == $category->term_id) {
                                  $has_children = true;
                                  break;
                              }
                          }
                      }

                      // 🔥 获取分类的自定义背景颜色
                      $category_custom_bg = get_term_meta($category->term_id, '_ruiyi_category_bg_color', true);
                      $category_bg_color = !empty($category_custom_bg) ? $category_custom_bg : $global_unselected_bg;
                      $category_border_color = !empty($category_custom_bg) ? $category_custom_bg : $global_unselected_border;
                      $category_image_url = function_exists('ruiyi_get_product_category_image_url') ? ruiyi_get_product_category_image_url($category->term_id, 'thumbnail') : '';
                    ?>
                      <button data-category="<?php echo esc_attr($category->term_id); ?>"
                              data-has-children="<?php echo $has_children ? '1' : '0'; ?>"
                              data-depth="1"
                              data-custom-color="<?php echo esc_attr($category_custom_bg); ?>"
                              class="category-btn category-card-btn<?php echo $category_image_url ? ' category-btn-has-image' : ''; ?> px-1.5 py-2 rounded transition flex items-center justify-center text-center min-h-[45px] hover:opacity-80"
                              style="background-color: <?php echo esc_attr($category_bg_color . $bg_intensity_hex); ?>; color: <?php echo esc_attr($global_unselected_text); ?>; border: 2px solid <?php echo esc_attr($category_border_color); ?>; opacity: <?php echo esc_attr($global_unselected_opacity); ?>;">
                        <?php if (!empty($category_image_url)) : ?>
                          <img class="category-card-image" src="<?php echo esc_url($category_image_url); ?>" alt="<?php echo esc_attr(get_multilingual_category_name($category)); ?>" loading="lazy" decoding="async">
                        <?php endif; ?>
                        <span class="category-name <?php echo get_option('pos_category_font_bold', '0') === '1' ? 'font-bold' : 'font-medium'; ?> leading-tight" style="font-size: <?php echo esc_attr(get_option('pos_category_font_size', '10')); ?>px; max-width: 100%;"><?php echo esc_html(get_multilingual_category_name($category)); ?></span>
                      </button>
                    <?php endforeach; ?>
                  </div>

                  <!-- 子分类容器（动态显示） -->
                  <div id="child-categories-container" class="hidden mt-3 pt-3 border-t border-gray-200">
                    <!-- 隐藏子分类标题和返回按钮 -->
                    <div class="flex items-center justify-between mb-2" style="display: none !important;">
                      <h3 id="current-parent-name" class="text-sm font-semibold text-gray-700"></h3>
                      <button id="back-to-parent" class="flex items-center gap-1 text-blue-600 hover:text-blue-800 text-sm transition-colors">
                        <i class="fas fa-arrow-left text-xs"></i>
                        <span><?php echo ruiyi_translate('Volver', 'Back', '返回'); ?></span>
                      </button>
                    </div>
                    <div id="child-categories-grid" class="grid grid-cols-<?php echo intval(get_option('pos_category_columns_count', '5')); ?> gap-2 overflow-y-auto scrollbar scrollbar-thin" style="max-height: 200px;">
                      <!-- 子分类按钮动态插入 -->
                    </div>
                  </div>

                </div>

                <!-- Lista de Productos -->
                <div class="bg-white shadow rounded-lg p-4 flex-1 overflow-y-auto custom-scrollbar">
                    <div class="flex justify-between items-center mb-3">
                      <h2 class="text-lg font-semibold text-gray-800"><?php echo ruiyi_translate('Elegir plato', 'Choose dish', '选择菜品'); ?></h2>

                      <div class="flex items-center gap-3">
                        <!-- 产品搜索输入框 -->
                        <div class="relative">
                          <input type="text" id="product-search-input"
                                 class="w-64 px-3 py-1.5 border border-gray-300 rounded-md text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                                 placeholder="<?php echo ruiyi_translate('Buscar producto...', 'Search product...', '搜索产品...'); ?>">
                          <button type="button" id="clear-product-search" class="absolute right-2 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600 hidden">
                            <i class="fas fa-times text-sm"></i>
                          </button>
                        </div>

                        <?php if ($is_administrator || $is_shop_manager): ?>
                        <!-- 产品排序按钮 - 仅管理员和店长可见 -->
                        <button id="toggle-product-sort" class="px-3 py-1.5 bg-blue-500 text-white rounded-md hover:bg-blue-600 transition-colors text-sm flex items-center gap-2">
                          <i class="fas fa-sort"></i>
                          <span><?php echo ruiyi_translate('Ordenar Productos', 'Sort Products', '产品排序'); ?></span>
                        </button>
                        <?php endif; ?>
                      </div>
                    </div>
                    <div class="grid gap-1 products-container" style="grid-template-columns: repeat(<?php echo $pos_products_per_row; ?>, 1fr);">
                    <?php
                    // Obtener todos los productos con orden personalizado
                    // 首先确保所有产品都有排序值
                    $check_args = array(
                      'post_type' => 'product',
                      'posts_per_page' => -1,
                      'post_status' => 'publish',
                      'meta_query' => array(
                        'relation' => 'OR',
                        array(
                          'key' => '_ruiyi_product_sort_order',
                          'compare' => 'NOT EXISTS'
                        ),
                        array(
                          'key' => '_ruiyi_product_sort_order',
                          'value' => '',
                          'compare' => '='
                        )
                      )
                    );
                    $check_products = new WP_Query($check_args);
                    if ($check_products->have_posts()) {
                      while ($check_products->have_posts()) {
                        $check_products->the_post();
                        $product_id = get_the_ID();
                        update_post_meta($product_id, '_ruiyi_product_sort_order', $product_id);
                      }
                      wp_reset_postdata();
                    }

                    // 🔥 产品加载：加载所有产品以确保分类过滤正常工作
                    // 注意：如果产品数量超过500个，可能需要考虑性能优化
                    $initial_products_limit = -1; // -1 表示加载所有产品

                    // 先获取产品总数
                    $count_args = array(
                      'post_type' => 'product',
                      'posts_per_page' => -1,
                      'post_status' => 'publish',
                      'fields' => 'ids'
                    );
                    $total_products_count = count(get_posts($count_args));

                    // 现在查询首屏产品
                    // 🔥 简化查询：不使用 meta_query 避免重复，改用 PHP 排序
                    $args = array(
                      'post_type' => 'product',
                      'posts_per_page' => $initial_products_limit,
                      'post_status' => 'publish',
                      'orderby' => 'ID',
                      'order' => 'ASC'
                    );

                    $products = new WP_Query($args);

                    // 🔥 收集所有产品并在 PHP 中排序（避免 SQL JOIN 导致的重复）
                    $all_products_data = array();
                    if ($products->have_posts()) {
                      while ($products->have_posts()) {
                        $products->the_post();
                        $pid = get_the_ID();
                        $sort_order = get_post_meta($pid, '_ruiyi_product_sort_order', true);
                        $all_products_data[$pid] = array(
                          'id' => $pid,
                          'sort_order' => $sort_order !== '' ? intval($sort_order) : $pid
                        );
                      }
                      wp_reset_postdata();
                    }

                    // 按 sort_order 排序
                    uasort($all_products_data, function($a, $b) {
                      return $a['sort_order'] - $b['sort_order'];
                    });

                    // 获取排序后的产品ID列表
                    $sorted_product_ids = array_keys($all_products_data);

                    // 输出懒加载初始状态到JS
                    // 🔥 修复：当 $initial_products_limit = -1 时，表示加载所有产品，不需要懒加载更多
                    $actual_initial_loaded = ($initial_products_limit === -1) ? $total_products_count : min($initial_products_limit, $total_products_count);
                    $has_more = ($initial_products_limit !== -1) && ($total_products_count > $initial_products_limit);
                    echo '<script>
                      window.RUIYI_POS_CONFIG = window.RUIYI_POS_CONFIG || {};
                      window.RUIYI_POS_CONFIG.totalProducts = ' . intval($total_products_count) . ';
                      window.RUIYI_POS_CONFIG.initialProductsLoaded = ' . intval($actual_initial_loaded) . ';
                      window.RUIYI_POS_CONFIG.hasMoreProducts = ' . ($has_more ? 'true' : 'false') . ';
                      window.RUIYI_POS_CONFIG.firstCategoryId = ' . intval($first_category_id) . ';
                      window.RUIYI_POS_CONFIG.firstCategoryAllIds = ' . json_encode(array_map('intval', $first_category_all_ids)) . ';
                      window.RUIYI_POS_CONFIG.categoryDescendantsMap = ' . json_encode($category_descendants_map) . ';
                    </script>';

                    // Track first product in each special category
                    $first_special_products = array(); // category_id => product_id

                    // 🔥 使用排序后的产品ID列表渲染（已经去重）
                    $rendered_count = 0;
                    $visible_count = 0; // 可见产品计数
                    $hidden_count = 0;  // 隐藏产品计数

                    // 🔥 确保 first_category_all_ids 变量可用（如果之前未设置则重新获取）
                    if (!isset($first_category_all_ids) || empty($first_category_all_ids)) {
                      // 重新获取第一个分类
                      $temp_categories = get_terms([
                        'taxonomy' => 'product_cat',
                        'hide_empty' => false,
                        'parent' => 0,
                        'orderby' => 'name',
                        'order' => 'ASC',
                      ]);
                      $temp_cats_ordered = [];
                      foreach ($temp_categories as $cat) {
                        if (in_array($cat->slug, ['uncategorized', 'suplementos'])) continue;
                        $so = get_term_meta($cat->term_id, 'category_sort_order', true);
                        $cat->sort_order = $so !== '' ? intval($so) : 999;
                        $temp_cats_ordered[] = $cat;
                      }
                      usort($temp_cats_ordered, function($a, $b) { return $a->sort_order - $b->sort_order; });

                      $first_category_id = !empty($temp_cats_ordered) ? $temp_cats_ordered[0]->term_id : 0;
                      $first_category_all_ids = array($first_category_id);
                      if ($first_category_id > 0) {
                        $desc = get_term_children($first_category_id, 'product_cat');
                        if (!is_wp_error($desc)) {
                          $first_category_all_ids = array_merge($first_category_all_ids, $desc);
                        }
                      }
                    }

                    // 🔥 分类自由价格产品功能：为每个分类生成一个虚拟产品卡片
                    if ($pos_category_price_product) :
                      // 获取所有分类（不包括suplementos和uncategorized）
                      $all_cats_for_price = get_terms([
                        'taxonomy' => 'product_cat',
                        'hide_empty' => false,
                        'exclude' => array_filter([
                          get_term_by('slug', 'uncategorized', 'product_cat') ? get_term_by('slug', 'uncategorized', 'product_cat')->term_id : 0,
                          get_term_by('slug', 'suplementos', 'product_cat') ? get_term_by('slug', 'suplementos', 'product_cat')->term_id : 0,
                        ])
                      ]);

                      if ($all_cats_for_price && !is_wp_error($all_cats_for_price)) :
                        foreach ($all_cats_for_price as $cat_for_price) :
                          // 🔥 固定使用深绿色背景
                          $cat_color = '#059669'; // 深绿色

                          // 获取多语言分类名称
                          $cat_display_name = function_exists('get_multilingual_category_name')
                            ? get_multilingual_category_name($cat_for_price)
                            : $cat_for_price->name;

                          // 判断是否属于第一个分类（用于初始显示/隐藏）
                          $cat_belongs_to_first = in_array($cat_for_price->term_id, array_map('intval', $first_category_all_ids));
                          $cat_initial_hidden = !$cat_belongs_to_first;
                          $cat_initial_style = $cat_initial_hidden
                            ? 'display: none !important; visibility: hidden !important; background: ' . esc_attr($cat_color) . ';'
                            : 'background: ' . esc_attr($cat_color) . ';';
                          $cat_border_class = $pos_product_light_mode ? 'border-gray-300' : 'border-gray-600';
                    ?>
                      <!-- 🔥 分类自由价格产品: <?php echo esc_html($cat_for_price->name); ?> -->
                      <div class="product-card <?php echo $cat_initial_hidden ? 'product-hidden' : ''; ?> group cursor-pointer rounded-lg overflow-hidden shadow-md hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1 border <?php echo $cat_border_class; ?> flex flex-col category-price-product"
                          style="<?php echo $cat_initial_style; ?>"
                          data-category-price-product="1"
                          data-category-id="<?php echo esc_attr($cat_for_price->term_id); ?>"
                          data-category-name="<?php echo esc_attr($cat_display_name); ?>"
                          data-categories="<?php echo esc_attr($cat_for_price->term_id); ?>">

                        <!-- 🔥 简化样式：只显示分类名称 -->
                        <div class="w-full h-full flex items-center justify-center p-2">
                          <h3 class="font-bold text-white text-center leading-tight"><?php echo esc_html($cat_display_name); ?></h3>
                        </div>
                      </div>
                    <?php
                        endforeach;
                      endif;
                    endif;
                    ?>

                    <?php if (!empty($sorted_product_ids)) :
                      foreach ($sorted_product_ids as $product_id) :
                        $product = wc_get_product($product_id);
                        if (!$product) continue;
                        $rendered_count++;
                        $product_price = $product->get_price(); // 使用产品原始价格（基础价格）

                        // 🔥 获取分区价格
                        $zone_prices = get_post_meta($product_id, '_ruiyi_zone_prices', true);
                        if (!is_array($zone_prices)) {
                            $zone_prices = array();
                        }
                        
                        // 跳过价格为负数的产品（允许价格为0的免费产品或赠品）
                        if (floatval($product_price) < 0) {
                            continue;
                        }
                        
                        $product_image = wp_get_attachment_image_src(get_post_thumbnail_id($product_id), 'medium');
                        $image_url = $product_image ? $product_image[0] : ruiyi_get_placeholder_image();

                        // Obtener categorías
                        $terms = get_the_terms($product_id, 'product_cat');
                        $category_ids = [];
                        $is_special_category = false;
                        $special_category_id = null;
                        if ($terms && !is_wp_error($terms)) {
                          foreach ($terms as $term) {
                            $category_ids[] = $term->term_id;
                            // Check if this category is a special category (shows numberpad)
                            if (function_exists('ruiyi_get_product_special_category_status')) {
                              $is_special_category = ruiyi_get_product_special_category_status($product_id);
                              if ($is_special_category) {
                                $special_category_id = $term->term_id;
                                break;
                              }
                            } else {
                              // Fallback: check directly
                              $show_numberpad = get_term_meta($term->term_id, 'show_numberpad', true);
                              if ($show_numberpad === '1' || $show_numberpad === true || $show_numberpad === 1 || $show_numberpad === 'yes') {
                                $is_special_category = true;
                                $special_category_id = $term->term_id;
                                break;
                              }
                            }
                          }
                        }
                        $category_ids_str = implode(' ', $category_ids);

                        // 🔥 检查产品是否属于第一个分类（用于初始隐藏）
                        $belongs_to_first_category = false;
                        if (!empty($first_category_all_ids) && !empty($category_ids)) {
                          foreach ($category_ids as $cat_id) {
                            if (in_array(intval($cat_id), array_map('intval', $first_category_all_ids))) {
                              $belongs_to_first_category = true;
                              break;
                            }
                          }
                        }
                        // 🔥 调试前10个产品的分类匹配情况
                        if ($rendered_count <= 10) {
                          echo '<!-- DEBUG Product ' . $product_id . ': categories=[' . implode(',', $category_ids) . '], first_cat_ids=[' . implode(',', $first_category_all_ids) . '], belongs=' . ($belongs_to_first_category ? 'YES' : 'NO') . ' -->';
                        }

                        // Check if this is the first product in this special category
                        $is_first_in_category = false;
                        $category_name_for_first = '';
                        if ($is_special_category && $special_category_id) {
                          if (!isset($first_special_products[$special_category_id])) {
                            $first_special_products[$special_category_id] = $product_id;
                            $is_first_in_category = true;
                            // Get category name for the first product
                            $category_term = get_term($special_category_id, 'product_cat');
                            if ($category_term && !is_wp_error($category_term)) {
                              $category_name_for_first = get_multilingual_category_name($category_term);
                            }
                          }
                        }
    
                        // Stock information
                        $stock_quantity = $product->get_stock_quantity();
                        $stock_status = $product->get_stock_status();
                        $managing_stock = $product->managing_stock();
                        $stock_display_text = '';
    
                        if ($managing_stock) {
                            if ($stock_quantity > 0) {
                                // Translators: %s is the stock quantity
                                $stock_display_text = $stock_quantity . ' ' . ruiyi_translate('Bowls available', 'Bowls available', '份可用');
                            } else {
                                $stock_display_text = ruiyi_translate('Out of stock', 'Out of stock', '缺货');
                            }
                        } elseif ($stock_status === 'instock') {
                            $stock_display_text = ruiyi_translate('In stock', 'In stock', '有货');
                        } else {
                            $stock_display_text = ruiyi_translate('Out of stock', 'Out of stock', '缺货');
                        }
                    ?>
                      <?php
                        // 🔥 多语言产品名称：根据当前语言显示对应名称
                        $current_lang = defined('RUIYI_CURRENT_LANG') ? RUIYI_CURRENT_LANG : 'zh';
                        $multilingual_display = $product->get_name();
                        if ($current_lang === 'zh') {
                            $zh_name = get_post_meta($product->get_id(), '_product_name_zh', true);
                            if (!empty($zh_name)) $multilingual_display = $zh_name;
                        } elseif ($current_lang === 'en') {
                            $en_name = get_post_meta($product->get_id(), '_product_name_en', true);
                            if (!empty($en_name)) $multilingual_display = $en_name;
                        }

                        // If this is the first product in a special category, use category name instead
                        $display_name = $is_first_in_category && !empty($category_name_for_first) ? $category_name_for_first : $multilingual_display;

                        // 🔥 检查产品是否有真实图片（非占位图）
                        $has_real_image = $product_image && $image_url && $image_url !== ruiyi_get_placeholder_image();
                      ?>
                      <?php
                      // Check if this is a scale product
                      $is_scale_product = function_exists('ruiyi_is_scale_product') ? ruiyi_is_scale_product($product->get_id()) : false;

                      // 🔥 获取时价标签设置
                      $is_market_price = get_post_meta($product->get_id(), '_ruiyi_market_price', true) === 'yes';

                      // 获取产品自定义颜色
                      $product_color_raw = get_post_meta($product->get_id(), '_ruiyi_product_color', true);
                      $has_custom_color = !empty($product_color_raw); // 🔥 标记是否有自定义颜色
                      $product_color = $has_custom_color ? $product_color_raw : '#1e293b'; // 默认深蓝灰色
                      // 计算渐变色（稍微亮一点的颜色作为起始色）
                      $product_color_light = $product_color; // 可以用JS处理或保持相同

                      // 🔥 获取产品价格显示设置（默认不显示）
                      $show_product_price = get_option('pos_show_product_price', '0') === '1';
                      // 🔥 获取双语名称显示设置（默认不显示）
                      $show_bilingual_name = get_option('pos_show_bilingual_name', '0') === '1';
                      $product_name_es = $product->get_name(); // 西语原始名称
                      $product_name_zh = get_post_meta($product->get_id(), '_product_name_zh', true); // 中文名称
                      // 🔥 获取产品价格字体大小设置（默认12px）
                      $product_price_font_size = get_option('pos_product_price_font_size', '12');
                      // 🔥 获取产品名称字体大小设置（默认12px）
                      $product_name_font_size = get_option('pos_product_font_size', '12');
                      ?>
                      <?php
                        // 🔥 确定初始显示状态
                        // 🔥 免费产品（price=0且非自助餐）允许显示
                        $is_free_product = floatval($product_price) <= 0 && !(function_exists('ruiyi_is_buffet_product') && ruiyi_is_buffet_product($product->get_id()));
                        $initial_hidden = !$belongs_to_first_category;
                        if ($initial_hidden) {
                          $hidden_count++;
                        } else {
                          $visible_count++;
                        }
                        // 🔥 亮色模式使用浅色边框
                        $border_class = $pos_product_light_mode ? 'border-gray-300' : 'border-gray-600';
                        // 🔥 有自定义颜色的产品添加 has-custom-color 类，用于 CSS 设置白色文字
                        $custom_color_class = $has_custom_color ? ' has-custom-color' : '';
                        // 🔥 有图片的产品添加 has-image 类，用于CSS调整间距
                        $image_class = $has_real_image ? ' has-image' : '';
                        $initial_class = $initial_hidden ? 'product-card product-hidden group cursor-pointer rounded-lg overflow-hidden shadow-md hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1 border ' . $border_class . ' flex flex-col relative' . $custom_color_class . $image_class : 'product-card group cursor-pointer rounded-lg overflow-hidden shadow-md hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1 border ' . $border_class . ' flex flex-col relative' . $custom_color_class . $image_class;
                        // 🔥 亮色模式：没有自定义颜色的产品使用白色背景，有自定义颜色的保留原色
                        if ($pos_product_light_mode && !$has_custom_color) {
                            // 亮色模式 + 无自定义颜色 = 白色背景
                            $initial_style = $initial_hidden ? 'display: none !important; visibility: hidden !important; background: #ffffff;' : 'background: #ffffff;';
                        } else {
                            // 暗色模式 或 有自定义颜色 = 使用产品颜色
                            $initial_style = $initial_hidden ? 'display: none !important; visibility: hidden !important; background: linear-gradient(to bottom, ' . esc_attr($product_color) . 'dd, ' . esc_attr($product_color) . ');' : 'background: linear-gradient(to bottom, ' . esc_attr($product_color) . 'dd, ' . esc_attr($product_color) . ');';
                        }
                      ?>
                      <div class="<?php echo esc_attr($initial_class); ?>"
                          style="<?php echo esc_attr($initial_style); ?>"
                          data-id="<?php echo esc_attr($product->get_id()); ?>"
                          data-name="<?php echo esc_attr($display_name); ?>"
                          data-name-es="<?php echo esc_attr($product->get_name()); ?>"
                          data-name-zh="<?php echo esc_attr(get_post_meta($product->get_id(), '_product_name_zh', true)); ?>"
                          data-name-en="<?php echo esc_attr(get_post_meta($product->get_id(), '_product_name_en', true)); ?>"
                          data-sku="<?php echo esc_attr($product->get_sku()); ?>"
                          data-price="<?php echo esc_attr($product_price); ?>"
                          data-zone-prices="<?php echo esc_attr(json_encode($zone_prices)); ?>"
                          data-tax-rate="<?php echo esc_attr($product->get_meta('_ruiyi_tax_rate') ?: 10); ?>"
                          data-image="<?php echo esc_attr($image_url); ?>"
                          data-categories="<?php echo esc_attr(implode(' ', $category_ids)); ?>"
                          data-special-category="<?php echo $is_special_category ? '1' : '0'; ?>"
                          data-is-first-special="<?php echo $is_first_in_category ? '1' : '0'; ?>"
                          data-is-scale-product="<?php echo $is_scale_product ? '1' : '0'; ?>"
                          data-is-buffet="<?php echo (function_exists('ruiyi_is_buffet_product') && ruiyi_is_buffet_product($product->get_id())) ? '1' : '0'; ?>"
                          data-is-free="<?php echo $is_free_product ? '1' : '0'; ?>"
                          data-product-color="<?php echo esc_attr($product_color); ?>">

                        <?php if ($is_first_in_category): ?>
                        <!-- Special Category Badge - Only on first product -->
                        <div class="absolute top-2 right-2 bg-purple-600 text-white text-xs px-2 py-1 rounded-full z-10 font-bold flex items-center gap-1 shadow-lg">
                          <i class="fas fa-keyboard text-[10px]"></i>
                          <span><?php echo ruiyi_translate('Número', 'Number', '数字'); ?></span>
                        </div>
                        <?php endif; ?>

                        <?php if ($is_market_price): ?>
                        <!-- 🔥 时价标签 -->
                        <div class="market-price-badge">
                          <i class="fas fa-chart-line" style="font-size: 9px; margin-right: 3px;"></i><?php echo ruiyi_translate('Precio de mercado', 'Market Price', '时价'); ?>
                        </div>
                        <?php endif; ?>

                        <?php
