          <!-- 添加内联脚本 -->
          <script>
            // 设置选项卡切换函数
            function switchSettingsTab(tabName) {
              // 更新所有选项卡按钮样式
              document.querySelectorAll('.settings-tab-btn').forEach(btn => {
                const btnTab = btn.dataset.tab;
                if (btnTab === tabName) {
                  // 激活状态
                  btn.classList.remove('bg-gray-200', 'text-gray-700', 'dark:bg-gray-700', 'dark:text-gray-300');
                  btn.classList.add('bg-blue-600', 'text-white');
                } else {
                  // 非激活状态
                  btn.classList.remove('bg-blue-600', 'text-white');
                  btn.classList.add('bg-gray-200', 'text-gray-700', 'dark:bg-gray-700', 'dark:text-gray-300');
                }
              });

              // 隐藏所有内容区域
              document.querySelectorAll('.settings-content').forEach(content => {
                content.classList.add('hidden');
              });

              // 显示对应内容
              const contentElement = document.getElementById(tabName + '-settings');
              if (contentElement) {
                contentElement.classList.remove('hidden');
              } else {
                console.error('找不到内容元素:', tabName + '-settings');
              }

              // 🔥 客户管理和产品多语言tab不需要全局保存按钮（使用AJAX保存）
              const globalSaveBtn = document.getElementById('global-save-button-container');
              if (globalSaveBtn) {
                if (tabName === 'customer' || tabName === 'multilingual' || tabName === 'productsort' || tabName === 'zonepricing') {
                  globalSaveBtn.style.display = 'none';
                } else {
                  globalSaveBtn.style.display = '';
                }
              }

              // 🔥 产品排序 tab AJAX 延迟加载
              if (tabName === 'productsort') {
                var psContainer = document.getElementById('productsort-settings');
                if (psContainer && psContainer.dataset.loaded === '0') {
                  psContainer.dataset.loaded = 'loading';
                  var _ajaxUrl = window.ajaxUrl || (window.RUIYI_POS_CONFIG?.homeUrl + '/wp-admin/admin-ajax.php');
                  var _nonce = window.RUIYI_POS_CONFIG?.ajaxNonce || currentNonce;
                  fetch(_ajaxUrl, {
                    method: 'POST',
                    headers: {'Content-Type': 'application/x-www-form-urlencoded'},
                    body: 'action=ruiyi_pos_load_productsort_tab&nonce=' + encodeURIComponent(_nonce)
                  }).then(function(r) { return r.json(); }).then(function(res) {
                    if (res.success && res.data && res.data.html) {
                      psContainer.innerHTML = res.data.html;
                      // Execute inline scripts from loaded HTML
                      psContainer.querySelectorAll('script').forEach(function(oldScript) {
                        var newScript = document.createElement('script');
                        newScript.textContent = oldScript.textContent;
                        oldScript.parentNode.replaceChild(newScript, oldScript);
                      });
                      psContainer.dataset.loaded = '1';
                    }
                  }).catch(function(err) {
                    console.error('[productsort] Failed to load tab:', err);
                    psContainer.innerHTML = '<p class="text-red-500 p-6 text-center"><i class="fas fa-exclamation-triangle mr-2"></i>Load failed. Please refresh the page.</p>';
                  });
                }
              }
            }

            // 页面加载时默认显示店铺信息选项卡
            document.addEventListener('DOMContentLoaded', function() {
              // 确保ajustes部分可见时才初始化
              const ajustesSection = document.getElementById('ajustes');
              if (ajustesSection && !ajustesSection.classList.contains('hidden')) {
                switchSettingsTab('store');
              }

              // 监听hash变化，当跳转到ajustes部分时初始化
              window.addEventListener('hashchange', function() {
                if (location.hash === '#ajustes') {
                  setTimeout(() => switchSettingsTab('store'), 100);
                }
              });
            });
          </script>

