                          <label class="inline-flex items-center cursor-pointer px-2 py-1 rounded-md text-xs border transition-colors <?php echo $is_checked ? 'bg-purple-100 border-purple-400 text-purple-700 dark:bg-purple-900/30 dark:border-purple-500 dark:text-purple-300' : 'bg-white border-gray-200 text-gray-600 hover:border-purple-300 dark:bg-gray-600 dark:border-gray-500 dark:text-gray-300'; ?>"
                                 onclick="toggleSupCatLabel(this)">
                            <input type="checkbox" name="sup_cat_map[<?php echo $sp_id; ?>][]" value="<?php echo $cat->term_id; ?>"
                                   <?php checked($is_checked); ?> class="hidden sup-cat-cb" data-sup-id="<?php echo $sp_id; ?>">
