                    <input type="hidden" name="pos_supplement_category_map" id="pos_supplement_category_map_input" value="">
                    <script>
                    // 保存时收集映射数据
                    document.addEventListener('DOMContentLoaded', function() {
                      var form = document.querySelector('form');
                      if (form) form.addEventListener('submit', function() {
                        var map = {};
                        document.querySelectorAll('.sup-cat-cb').forEach(function(cb) {
                          var sid = cb.dataset.supId;
                          if (!map[sid]) map[sid] = [];
                          if (cb.checked) map[sid].push(parseInt(cb.value));
                        });
                        document.getElementById('pos_supplement_category_map_input').value = JSON.stringify(map);
                      });
                    });
                    function toggleSupCatLabel(label) {
                      var cb = label.querySelector('input[type=checkbox]');
                      setTimeout(function() {
                        if (cb.checked) {
                          label.className = label.className.replace(/bg-white border-gray-200 text-gray-600|dark:bg-gray-600 dark:border-gray-500 dark:text-gray-300/g, '');
                          label.classList.add('bg-purple-100','border-purple-400','text-purple-700','dark:bg-purple-900/30','dark:border-purple-500','dark:text-purple-300');
                        } else {
                          label.className = label.className.replace(/bg-purple-100 border-purple-400 text-purple-700|dark:bg-purple-900\/30 dark:border-purple-500 dark:text-purple-300/g, '');
                          label.classList.add('bg-white','border-gray-200','text-gray-600','dark:bg-gray-600','dark:border-gray-500','dark:text-gray-300');
                        }
                        // 更新提示
                        var sid = cb.dataset.supId;
                        var count = document.querySelectorAll('.sup-cat-cb[data-sup-id="'+sid+'"]:checked').length;
                        var hint = document.querySelector('.sup-cat-hint-'+sid);
                        if (hint) hint.textContent = count === 0 ? '<?php echo esc_js(ruiyi_translate("Todas las categorías", "All categories", "所有分类")); ?>' : count + ' <?php echo esc_js(ruiyi_translate("categorías", "categories", "个分类")); ?>';
                      }, 10);
                    }
                    </script>
                  </div>
                </div>
