                        $table_categories = function_exists('ruiyi_get_table_categories') ? ruiyi_get_table_categories() : [];
                        $skip_kitchen_zones = json_decode(get_option('pos_kitchen_skip_zone_categories', '[]'), true) ?: [];
                        if (!empty($table_categories)) {
                            foreach ($table_categories as $cat) {
                                $cat_id = intval($cat['id'] ?? $cat['term_id'] ?? 0);
                                $cat_name = $cat['name'] ?? $cat['display_name'] ?? ('Zone ' . $cat_id);
                                if ($cat_id <= 0) continue;
                                $is_checked = in_array($cat_id, $skip_kitchen_zones) ? 'checked' : '';
                                echo '<label class="flex items-center gap-2 p-2 bg-white dark:bg-gray-600 rounded border border-gray-200 dark:border-gray-500 cursor-pointer hover:bg-red-50 dark:hover:bg-gray-500 transition-colors">';
                                echo '<input type="checkbox" class="kitchen-skip-zone-cb w-4 h-4 text-red-600 bg-gray-100 border-gray-300 rounded focus:ring-red-500 dark:bg-gray-700 dark:border-gray-600" value="' . esc_attr($cat_id) . '" ' . $is_checked . '>';
                                echo '<span class="text-sm text-gray-700 dark:text-gray-300">' . esc_html($cat_name) . '</span>';
                                echo '</label>';
                            }
                        } else {
                            echo '<p class="text-xs text-gray-400 col-span-full">' . ruiyi_translate('No hay zonas configuradas', 'No zones configured', '暂无已配置的分区') . '</p>';
                        }
                        ?>
