                      <input type="hidden" name="pos_kitchen_skip_zone_categories" id="kitchen_skip_zone_categories_input"
                             value="<?php echo esc_attr(get_option('pos_kitchen_skip_zone_categories', '[]')); ?>">
                      <script>
                      (function() {
                        function updateSkipZones() {
                          const cbs = document.querySelectorAll('.kitchen-skip-zone-cb');
                          const zones = [];
                          cbs.forEach(cb => { if (cb.checked) zones.push(parseInt(cb.value)); });
                          document.getElementById('kitchen_skip_zone_categories_input').value = JSON.stringify(zones);
                        }
                        document.querySelectorAll('.kitchen-skip-zone-cb').forEach(cb => {
                          cb.addEventListener('change', updateSkipZones);
                        });
                        updateSkipZones();
                      })();
                      </script>
