                      <input type="hidden" name="pos_quick_note_templates" id="pos_quick_note_templates"
                             value="<?php echo esc_attr(get_option('pos_quick_note_templates', '[]')); ?>">
                      <div class="flex gap-2 mb-3">
                        <input type="text" id="quick_note_new_input"
                               class="flex-1 px-3 py-2 text-sm border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300 focus:ring-2 focus:ring-amber-300 focus:border-amber-400"
                               placeholder="<?php echo esc_attr(ruiyi_translate('Ej: Sin picante', 'e.g. No spicy', '例如：不要辣')); ?>">
