                        ]);
                        foreach ($quick_notes_list as $note):
                          $note_text = is_array($note) ? ($note['text'] ?? '') : $note;
                          $note_cats = is_array($note) && isset($note['categories']) && is_array($note['categories'])
                              ? array_values(array_map('intval', $note['categories']))
                              : array();
                          if ($note_text === '') continue;
                        ?>
                        <div class="quick-note-tag p-3 rounded-lg bg-white dark:bg-gray-800 border border-amber-200 dark:border-amber-700 w-full"
                             data-note-text="<?php echo esc_attr($note_text); ?>"
                             data-note-categories="<?php echo esc_attr(json_encode($note_cats)); ?>">
                          <div class="flex items-center justify-between gap-2 mb-2">
                            <span class="inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-medium bg-amber-100 text-amber-800 border border-amber-300 dark:bg-amber-900 dark:text-amber-200 dark:border-amber-700">
                              <?php echo esc_html($note_text); ?>
                            </span>
                            <button type="button" onclick="removeQuickNoteTemplate(this.closest('.quick-note-tag'))" class="text-amber-600 hover:text-red-500 dark:text-amber-400 dark:hover:text-red-400">&times;</button>
                          </div>
                          <div class="flex flex-wrap gap-1.5">
                            <?php foreach ($quick_note_categories as $cat):
                              $checked = in_array((int)$cat->term_id, $note_cats, true);
                            ?>
                            <label class="quick-note-cat-label inline-flex items-center cursor-pointer px-2 py-1 rounded-md text-xs border transition-colors <?php echo $checked ? 'bg-amber-100 border-amber-400 text-amber-800 dark:bg-amber-900/30 dark:border-amber-500 dark:text-amber-200' : 'bg-gray-50 border-gray-200 text-gray-600 hover:border-amber-300 dark:bg-gray-700 dark:border-gray-600 dark:text-gray-300'; ?>">
                              <input type="checkbox" class="hidden quick-note-cat-cb" value="<?php echo esc_attr($cat->term_id); ?>" <?php checked($checked); ?> onchange="updateQuickNoteTemplatesHidden(); refreshQuickNoteCategoryLabel(this.parentElement);">
                              <?php echo esc_html($cat->name); ?>
                            </label>
                            <?php endforeach; ?>
                          </div>
                          <p class="quick-note-cat-hint text-xs text-gray-400 mt-2"></p>
                        </div>
                        <?php endforeach; ?>
                      </div>
                    </div>
                    <script>
                    function escapeQuickNoteHtml(text) {
                        var div = document.createElement('div');
                        div.textContent = text || '';
                        return div.innerHTML;
                    }
                    function getQuickNoteCategoryOptionsHtml(selectedIds) {
                        var categories = <?php echo wp_json_encode(array_map(function($cat) {
                            return ['id' => (int)$cat->term_id, 'name' => $cat->name];
                        }, is_array($quick_note_categories) ? $quick_note_categories : [])); ?>;
                        selectedIds = selectedIds || [];
                        return categories.map(function(cat) {
                            var checked = selectedIds.indexOf(parseInt(cat.id, 10)) !== -1;
                            var activeClass = checked
                                ? 'bg-amber-100 border-amber-400 text-amber-800 dark:bg-amber-900/30 dark:border-amber-500 dark:text-amber-200'
                                : 'bg-gray-50 border-gray-200 text-gray-600 hover:border-amber-300 dark:bg-gray-700 dark:border-gray-600 dark:text-gray-300';
                            return '<label class="quick-note-cat-label inline-flex items-center cursor-pointer px-2 py-1 rounded-md text-xs border transition-colors ' + activeClass + '">' +
                                '<input type="checkbox" class="hidden quick-note-cat-cb" value="' + cat.id + '" ' + (checked ? 'checked' : '') + ' onchange="updateQuickNoteTemplatesHidden(); refreshQuickNoteCategoryLabel(this.parentElement);">' +
                                escapeQuickNoteHtml(cat.name) +
                                '</label>';
                        }).join('');
                    }
                    function refreshQuickNoteCategoryLabel(label) {
                        if (!label) return;
                        var cb = label.querySelector('.quick-note-cat-cb');
                        label.className = 'quick-note-cat-label inline-flex items-center cursor-pointer px-2 py-1 rounded-md text-xs border transition-colors ' + (cb && cb.checked
                            ? 'bg-amber-100 border-amber-400 text-amber-800 dark:bg-amber-900/30 dark:border-amber-500 dark:text-amber-200'
                            : 'bg-gray-50 border-gray-200 text-gray-600 hover:border-amber-300 dark:bg-gray-700 dark:border-gray-600 dark:text-gray-300');
                        updateQuickNoteHints();
                    }
                    function updateQuickNoteHints() {
                        document.querySelectorAll('.quick-note-tag').forEach(function(tag) {
                            var count = tag.querySelectorAll('.quick-note-cat-cb:checked').length;
                            var hint = tag.querySelector('.quick-note-cat-hint');
                            if (hint) {
                                hint.textContent = count === 0
                                    ? '<?php echo esc_js(ruiyi_translate("Todas las categorías", "All categories", "所有分类")); ?>'
                                    : count + ' <?php echo esc_js(ruiyi_translate("categorías", "categories", "个分类")); ?>';
                            }
                        });
                    }
                    function collectQuickNoteTemplates() {
                        return Array.from(document.querySelectorAll('.quick-note-tag')).map(function(tag) {
                            return {
                                text: tag.dataset.noteText || '',
                                categories: Array.from(tag.querySelectorAll('.quick-note-cat-cb:checked')).map(function(cb) {
                                    return parseInt(cb.value, 10);
                                }).filter(function(id) { return id > 0; })
                            };
                        }).filter(function(item) { return item.text; });
                    }
                    function updateQuickNoteTemplatesHidden() {
                        var hidden = document.getElementById('pos_quick_note_templates');
                        if (hidden) hidden.value = JSON.stringify(collectQuickNoteTemplates());
                    }
                    function addQuickNoteTemplate() {
                        var input = document.getElementById('quick_note_new_input');
                        var text = input.value.trim();
                        if (!text) return;
                        var hidden = document.getElementById('pos_quick_note_templates');
                        var list = collectQuickNoteTemplates();
                        if (list.some(function(item) { return item.text === text; })) { input.value = ''; return; }
                        var container = document.getElementById('quick_note_tags_container');
                        var tag = document.createElement('div');
                        tag.className = 'quick-note-tag p-3 rounded-lg bg-white dark:bg-gray-800 border border-amber-200 dark:border-amber-700 w-full';
                        tag.dataset.noteText = text;
                        tag.dataset.noteCategories = '[]';
                        tag.innerHTML =
                            '<div class="flex items-center justify-between gap-2 mb-2">' +
                                '<span class="inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-medium bg-amber-100 text-amber-800 border border-amber-300 dark:bg-amber-900 dark:text-amber-200 dark:border-amber-700">' + escapeQuickNoteHtml(text) + '</span>' +
                                '<button type="button" onclick="removeQuickNoteTemplate(this.parentElement.parentElement)" class="text-amber-600 hover:text-red-500 dark:text-amber-400 dark:hover:text-red-400">&times;</button>' +
                            '</div>' +
                            '<div class="flex flex-wrap gap-1.5">' + getQuickNoteCategoryOptionsHtml([]) + '</div>' +
                            '<p class="quick-note-cat-hint text-xs text-gray-400 mt-2"></p>';
                        container.appendChild(tag);
                        input.value = '';
                        updateQuickNoteTemplatesHidden();
                        updateQuickNoteHints();
                    }
                    function removeQuickNoteTemplate(tagEl) {
                        tagEl.remove();
                        updateQuickNoteTemplatesHidden();
                    }
                    document.getElementById('quick_note_new_input').addEventListener('keydown', function(e) {
                        if (e.key === 'Enter') { e.preventDefault(); addQuickNoteTemplate(); }
                    });
                    document.addEventListener('DOMContentLoaded', function() {
                        updateQuickNoteTemplatesHidden();
                        updateQuickNoteHints();
                    });
                    </script>

                    <!-- 🍽️ 自助餐模式设置 -->
                    <div class="mt-6 pt-6 border-t border-gray-200 dark:border-gray-600">
                      <h4 class="text-lg font-semibold text-gray-800 dark:text-white mb-4">
                        <i class="fas fa-utensils mr-2 text-orange-500"></i>
                        <?php echo ruiyi_translate('Modo Buffet', 'Buffet Mode', '自助餐模式'); ?>
                      </h4>

                      <!-- 🔥 自助餐 hidden inputs（必须在主表单内，不能在弹窗里） -->
                      <input type="hidden" name="pos_buffet_categories" id="pos_buffet_categories_form"
                             value="<?php echo esc_attr(get_option('pos_buffet_categories', '[]')); ?>">
                      <input type="hidden" name="pos_buffet_products" id="pos_buffet_products_form"
                             value="<?php echo esc_attr(get_option('pos_buffet_products', '[]')); ?>">
                      <input type="hidden" name="pos_buffet_menu_types" id="pos_buffet_menu_types_form"
                             value="<?php echo esc_attr(get_option('pos_buffet_menu_types', '[]')); ?>">

