              <script>
              (function() {
                const nonce = '<?php echo wp_create_nonce("ruiyi_pos_nonce"); ?>';
                const ajaxUrl = '<?php echo admin_url("admin-ajax.php"); ?>';
                let supplementsList = [];

                // i18n
                const suppI18n = {
                  edit: '<?php echo esc_js(ruiyi_translate("Editar", "Edit", "编辑")); ?>',
                  delete: '<?php echo esc_js(ruiyi_translate("Eliminar", "Delete", "删除")); ?>',
                  save: '<?php echo esc_js(ruiyi_translate("Guardar", "Save", "保存")); ?>',
                  cancel: '<?php echo esc_js(ruiyi_translate("Cancelar", "Cancel", "取消")); ?>',
                  confirmDelete: '<?php echo esc_js(ruiyi_translate("¿Eliminar este ingrediente?", "Delete this topping?", "删除此配料？")); ?>',
                  noSupplements: '<?php echo esc_js(ruiyi_translate("No hay ingredientes configurados. Añade uno arriba.", "No toppings configured. Add one above.", "暂无配料。请在上方添加。")); ?>',
                  nameRequired: '<?php echo esc_js(ruiyi_translate("El nombre es requerido", "Name is required", "名称不能为空")); ?>',
                  priceRequired: '<?php echo esc_js(ruiyi_translate("El precio debe ser mayor que 0", "Price must be greater than 0", "价格必须大于0")); ?>',
                };

                function renderSupplements() {
                  const container = document.getElementById('supplements-list');
                  if (supplementsList.length === 0) {
                    container.innerHTML = '<div class="text-center text-gray-400 py-4">' + suppI18n.noSupplements + '</div>';
                    return;
                  }
                  container.innerHTML = supplementsList.map(s => `
                    <div class="flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-700 rounded-lg" id="supp-row-${s.id}">
                      <div class="flex items-center gap-3 flex-1">
                        <span class="text-sm font-medium text-gray-800 dark:text-white" id="supp-name-${s.id}">${escHtml(s.name)}</span>
                        <span class="text-sm font-semibold text-orange-600">€${parseFloat(s.price).toFixed(2)}</span>
                      </div>
                      <div class="flex gap-2">
                        <button type="button" onclick="editSupplement(${s.id})"
                                class="px-3 py-1 text-xs bg-blue-100 text-blue-700 hover:bg-blue-200 rounded-lg transition-colors">
                          <i class="fas fa-pen mr-1"></i>${suppI18n.edit}
                        </button>
                        <button type="button" onclick="deleteSupplement(${s.id})"
                                class="px-3 py-1 text-xs bg-red-100 text-red-700 hover:bg-red-200 rounded-lg transition-colors">
                          <i class="fas fa-trash mr-1"></i>${suppI18n.delete}
                        </button>
                      </div>
                    </div>
                  `).join('');
                }

                function escHtml(str) {
                  const d = document.createElement('div');
                  d.textContent = str;
                  return d.innerHTML;
                }

                window.loadSupplements = function() {
                  fetch(ajaxUrl, {
                    method: 'POST',
                    headers: {'Content-Type': 'application/x-www-form-urlencoded'},
                    body: new URLSearchParams({ action: 'ruiyi_pos_get_supplements', nonce: nonce })
                  })
                  .then(r => r.json())
                  .then(data => {
                    if (data.success) {
                      supplementsList = data.data.supplements || [];
                      renderSupplements();
                    }
                  })
                  .catch(() => {
                    document.getElementById('supplements-list').innerHTML = '<div class="text-center text-red-400 py-4">Error loading supplements</div>';
                  });
                };

                window.addNewSupplement = function() {
                  const nameEl = document.getElementById('supplement-name-input');
                  const priceEl = document.getElementById('supplement-price-input');
                  const name = nameEl.value.trim();
                  const price = parseFloat(priceEl.value);

                  if (!name) { nameEl.focus(); showNotice(suppI18n.nameRequired, 'error'); return; }
                  if (!price || price <= 0) { priceEl.focus(); showNotice(suppI18n.priceRequired, 'error'); return; }

                  fetch(ajaxUrl, {
                    method: 'POST',
                    headers: {'Content-Type': 'application/x-www-form-urlencoded'},
                    body: new URLSearchParams({ action: 'ruiyi_pos_create_supplement', nonce: nonce, name: name, price: price })
                  })
                  .then(r => r.json())
                  .then(data => {
                    if (data.success) {
                      supplementsList.push(data.data.supplement);
                      renderSupplements();
                      nameEl.value = '';
                      priceEl.value = '';
                      nameEl.focus();
                      if (typeof Swal !== 'undefined') {
                        Swal.fire({ icon:'success', title: data.data.message, timer:1500, showConfirmButton:false });
                      }
                    } else {
                      showNotice(data.data.message || 'Error', 'error');
                    }
                  });
                };

                window.editSupplement = function(id) {
                  const s = supplementsList.find(x => x.id === id);
                  if (!s) return;
                  const row = document.getElementById('supp-row-' + id);
                  row.innerHTML = `
                    <div class="flex items-center gap-2 flex-1">
                      <input type="text" id="supp-edit-name-${id}" value="${escHtml(s.name)}"
                             class="flex-1 px-2 py-1 border border-gray-300 dark:border-gray-600 rounded text-sm bg-white dark:bg-gray-600 dark:text-white">
                      <input type="number" id="supp-edit-price-${id}" value="${s.price}" step="0.01" min="0.01"
                             class="w-24 px-2 py-1 border border-gray-300 dark:border-gray-600 rounded text-sm bg-white dark:bg-gray-600 dark:text-white">
                    </div>
                    <div class="flex gap-2 ml-2">
                      <button type="button" onclick="saveSupplement(${id})"
                              class="px-3 py-1 text-xs bg-green-100 text-green-700 hover:bg-green-200 rounded-lg transition-colors">
                        <i class="fas fa-check mr-1"></i>${suppI18n.save}
                      </button>
                      <button type="button" onclick="renderSupplements()"
                              class="px-3 py-1 text-xs bg-gray-100 text-gray-700 hover:bg-gray-200 rounded-lg transition-colors">
                        ${suppI18n.cancel}
                      </button>
                    </div>
                  `;
                  // renderSupplements needs to be global for cancel
                  window.renderSupplements = renderSupplements;
                };

                window.saveSupplement = function(id) {
                  const name = document.getElementById('supp-edit-name-' + id).value.trim();
                  const price = parseFloat(document.getElementById('supp-edit-price-' + id).value);
                  if (!name) { showNotice(suppI18n.nameRequired, 'error'); return; }
                  if (!price || price <= 0) { showNotice(suppI18n.priceRequired, 'error'); return; }

                  fetch(ajaxUrl, {
                    method: 'POST',
                    headers: {'Content-Type': 'application/x-www-form-urlencoded'},
                    body: new URLSearchParams({ action: 'ruiyi_pos_update_supplement', nonce: nonce, product_id: id, name: name, price: price })
                  })
                  .then(r => r.json())
                  .then(data => {
                    if (data.success) {
                      const idx = supplementsList.findIndex(x => x.id === id);
                      if (idx >= 0) supplementsList[idx] = data.data.supplement;
                      renderSupplements();
                      if (typeof Swal !== 'undefined') {
                        Swal.fire({ icon:'success', title: data.data.message, timer:1500, showConfirmButton:false });
                      }
                    } else {
                      showNotice(data.data.message || 'Error', 'error');
                    }
                  });
                };

                window.deleteSupplement = function(id) {
                  if (typeof Swal !== 'undefined') {
                    Swal.fire({
                      title: suppI18n.confirmDelete,
                      icon: 'warning',
                      showCancelButton: true,
                      confirmButtonColor: '#ef4444',
                      cancelButtonColor: '#6b7280',
                      confirmButtonText: suppI18n.delete,
                      cancelButtonText: suppI18n.cancel
                    }).then(result => {
                      if (result.isConfirmed) doDelete(id);
                    });
                  } else {
                    if (confirm(suppI18n.confirmDelete)) doDelete(id);
                  }
                };

                function doDelete(id) {
                  fetch(ajaxUrl, {
                    method: 'POST',
                    headers: {'Content-Type': 'application/x-www-form-urlencoded'},
                    body: new URLSearchParams({ action: 'ruiyi_pos_delete_supplement', nonce: nonce, product_id: id })
                  })
                  .then(r => r.json())
                  .then(data => {
                    if (data.success) {
                      supplementsList = supplementsList.filter(x => x.id !== id);
                      renderSupplements();
                    } else {
                      showNotice(data.data.message || 'Error', 'error');
                    }
                  });
                }

                function showNotice(msg, type) {
                  if (typeof Swal !== 'undefined') {
                    Swal.fire({ icon: type === 'error' ? 'error' : 'info', title: msg, timer: 2000, showConfirmButton: false });
                  } else {
                    alert(msg);
                  }
                }

                // Auto-load when qrorder tab becomes visible
                const origSwitch = window.switchSettingsTab;
                window.switchSettingsTab = function(tabName) {
                  if (typeof origSwitch === 'function') origSwitch(tabName);
                  if (tabName === 'qrorder') loadSupplements();
                };
                // Also load if already on qrorder tab
                if (!document.getElementById('qrorder-settings')?.classList.contains('hidden')) {
                  loadSupplements();
                }
              })();
              </script>
              <!-- End 配料管理 -->

            </div><!-- end qrorder-settings -->
            <!-- End Tab: 扫码点餐 -->

            <!-- ==================== Tab 4: 钱箱设置 ==================== -->
            <div id="drawer-settings" class="settings-content hidden space-y-6">

                <!-- 钱箱基本设置 -->
