                    </div>

                    <!-- 日结单结算模式 -->
                    <?php $current_settlement_mode = get_option('pos_settlement_mode', 'manual'); ?>
                    <div class="p-4 bg-gray-50 dark:bg-gray-700 rounded-lg">
                      <div class="flex items-center justify-between">
                        <div class="flex-1">
                          <p class="text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                            <i class="fas fa-clock mr-2 text-blue-500"></i>
                            <?php echo ruiyi_translate('Cierre diario automático', 'Auto daily settlement', '自动日结单'); ?>
                          </p>
                          <p class="text-xs text-gray-500 dark:text-gray-400">
                            <?php echo ruiyi_translate(
                              'Activar estadísticas automáticas del cierre diario basadas en pedidos',
                              'Enable automatic daily settlement statistics based on orders',
                              '开启后，系统将根据订单自动统计日结单和月结单数据'
                            ); ?>
                          </p>
                        </div>
                        <label class="relative inline-flex items-center cursor-pointer">
                          <input type="checkbox" name="pos_settlement_mode_auto" value="1"
                                 id="settlement-mode-toggle"
                                 <?php echo $current_settlement_mode === 'auto' ? 'checked' : ''; ?>
                                 class="sr-only peer">
                          <input type="hidden" name="pos_settlement_mode" id="settlement-mode-hidden"
                                 value="<?php echo esc_attr($current_settlement_mode); ?>">
                          <div class="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 dark:peer-focus:ring-blue-800 rounded-full peer dark:bg-gray-600 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all dark:border-gray-600 peer-checked:bg-blue-600"></div>
