                  <!-- 保存按钮区域 -->
                  <div class="mt-4 flex items-center justify-between">
                    <span id="multilingual-name-status" class="text-sm text-gray-500 dark:text-gray-400"></span>
                    <button type="button" onclick="saveProductNames()" id="save-product-names-btn"
                            class="px-5 py-2.5 bg-indigo-500 text-white rounded-lg text-sm font-medium hover:bg-indigo-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-md" disabled>
                      <i class="fas fa-save mr-1.5"></i>
                      <?php echo ruiyi_translate('Guardar nombres', 'Save names', '保存名称修改'); ?>
                    </button>
                  </div>
                </div>
              </div>

              <script>
              (function() {
                // 多语言名称编辑器数据
                let nameEditorProducts = []; // 🔥 数据延迟加载（AJAX）减少页面加载时间

                const changedProducts = {};

                function escapeAttr(str) {
                  return String(str || '').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/'/g,'&#39;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
                }

                window.renderProductNameEditor = function(filter) {
                  const tbody = document.getElementById('multilingual-name-tbody');
                  tbody.innerHTML = '';
                  const query = (filter || '').toLowerCase();

                  nameEditorProducts.forEach(p => {
                    if (query && !p.name_es.toLowerCase().includes(query) &&
                        !p.name_zh.toLowerCase().includes(query) &&
                        !p.name_en.toLowerCase().includes(query) &&
                        !String(p.id).includes(query)) {
                      return;
                    }

                    const row = document.createElement('tr');
                    row.className = 'border-b border-gray-100 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-750';
                    row.dataset.productId = p.id;

                    const changed = changedProducts[p.id];
                    const esVal = changed?.name_es ?? p.name_es;
                    const zhVal = changed?.name_zh ?? p.name_zh;
                    const enVal = changed?.name_en ?? p.name_en;

                    row.innerHTML = `
                      <td class="px-3 py-1.5 text-xs text-gray-400">${p.id}</td>
                      <td class="px-3 py-1.5">${p.image ? '<img src="' + p.image + '" class="w-8 h-8 rounded object-cover">' : '<div class="w-8 h-8 rounded bg-gray-200 flex items-center justify-center"><i class="fas fa-image text-gray-400 text-xs"></i></div>'}</td>
                      <td class="px-2 py-1.5"><input type="text" value="${escapeAttr(esVal)}" data-field="name_es" data-id="${p.id}" data-original="${escapeAttr(p.name_es)}" class="w-full px-2 py-1.5 border border-gray-200 dark:border-gray-600 rounded text-sm bg-white dark:bg-gray-700 text-gray-800 dark:text-white focus:ring-1 focus:ring-indigo-300" oninput="trackNameChange(${p.id},'name_es',this.value,this.dataset.original)"></td>
                      <td class="px-2 py-1.5"><input type="text" value="${escapeAttr(zhVal)}" data-field="name_zh" data-id="${p.id}" data-original="${escapeAttr(p.name_zh)}" class="w-full px-2 py-1.5 border border-gray-200 dark:border-gray-600 rounded text-sm bg-white dark:bg-gray-700 text-gray-800 dark:text-white focus:ring-1 focus:ring-indigo-300" oninput="trackNameChange(${p.id},'name_zh',this.value,this.dataset.original)"></td>
                      <td class="px-2 py-1.5"><input type="text" value="${escapeAttr(enVal)}" data-field="name_en" data-id="${p.id}" data-original="${escapeAttr(p.name_en)}" class="w-full px-2 py-1.5 border border-gray-200 dark:border-gray-600 rounded text-sm bg-white dark:bg-gray-700 text-gray-800 dark:text-white focus:ring-1 focus:ring-indigo-300" oninput="trackNameChange(${p.id},'name_en',this.value,this.dataset.original)"></td>
                    `;
                    tbody.appendChild(row);
                  });
                };

                window.filterProductNameEditor = function(query) {
                  renderProductNameEditor(query);
                };

                window.trackNameChange = function(productId, field, value, original) {
                  if (!changedProducts[productId]) {
                    const p = nameEditorProducts.find(x => x.id === productId);
                    changedProducts[productId] = { id: productId, name_es: p.name_es, name_zh: p.name_zh, name_en: p.name_en };
                  }
                  changedProducts[productId][field] = value;

                  const p = nameEditorProducts.find(x => x.id === productId);
                  if (changedProducts[productId].name_es === p.name_es &&
                      changedProducts[productId].name_zh === p.name_zh &&
                      changedProducts[productId].name_en === p.name_en) {
                    delete changedProducts[productId];
                  }

                  const btn = document.getElementById('save-product-names-btn');
                  const count = Object.keys(changedProducts).length;
                  btn.disabled = count === 0;
                  document.getElementById('multilingual-name-status').textContent = count > 0
                    ? '<?php echo ruiyi_translate("Productos modificados", "Products modified", "已修改产品"); ?>: ' + count
                    : '';
                };

                window.saveProductNames = function() {
                  const products = Object.values(changedProducts);
                  if (products.length === 0) return;

                  const btn = document.getElementById('save-product-names-btn');
                  const statusEl = document.getElementById('multilingual-name-status');
                  btn.disabled = true;
                  btn.innerHTML = '<i class="fas fa-spinner fa-spin mr-1"></i><?php echo ruiyi_translate("Guardando...", "Saving...", "保存中..."); ?>';

                  fetch(window.RUIYI_POS_CONFIG.homeUrl + '/wp-admin/admin-ajax.php', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                    body: 'action=ruiyi_save_product_names&nonce=' + encodeURIComponent(window.RUIYI_POS_CONFIG.ajaxNonce || '<?php echo esc_js($ajax_nonce); ?>') + '&products=' + encodeURIComponent(JSON.stringify(products))
                  })
                  .then(r => r.json())
                  .then(res => {
                    if (res.success) {
                      products.forEach(changed => {
                        const p = nameEditorProducts.find(x => x.id === changed.id);
                        if (p) { p.name_es = changed.name_es; p.name_zh = changed.name_zh; p.name_en = changed.name_en; }
                      });
                      Object.keys(changedProducts).forEach(k => delete changedProducts[k]);
                      statusEl.textContent = '<?php echo ruiyi_translate("¡Guardado exitosamente!", "Saved successfully!", "保存成功！"); ?>';
                      statusEl.className = 'text-sm text-green-600 font-medium';
                      setTimeout(() => { statusEl.textContent = ''; statusEl.className = 'text-sm text-gray-500 dark:text-gray-400'; }, 3000);
                      // Re-render to update lock states for newly saved ZH names
                      renderProductNameEditor();
                    } else {
                      statusEl.textContent = '<?php echo ruiyi_translate("Error al guardar", "Save error", "保存失败"); ?>: ' + (res.data?.message || '');
                      statusEl.className = 'text-sm text-red-500';
                    }
                    btn.disabled = Object.keys(changedProducts).length === 0;
                    btn.innerHTML = '<i class="fas fa-save mr-1.5"></i><?php echo ruiyi_translate("Guardar nombres", "Save names", "保存名称修改"); ?>';
                  })
                  .catch(err => {
                    statusEl.textContent = '<?php echo ruiyi_translate("Error de red", "Network error", "网络错误"); ?>';
                    statusEl.className = 'text-sm text-red-500';
                    btn.disabled = false;
                    btn.innerHTML = '<i class="fas fa-save mr-1.5"></i><?php echo ruiyi_translate("Guardar nombres", "Save names", "保存名称修改"); ?>';
                  });
                };

                // Excel 导出模板
                window.exportProductNamesExcel = function() {
                  const ajaxUrl = window.RUIYI_POS_CONFIG.homeUrl + '/wp-admin/admin-ajax.php';
                  const nonce = window.RUIYI_POS_CONFIG.ajaxNonce || '<?php echo esc_js($ajax_nonce); ?>';
                  window.location.href = ajaxUrl + '?action=ruiyi_export_product_names_xlsx&nonce=' + encodeURIComponent(nonce);
                };

                // Excel 上传处理
                window.handleProductNamesExcelUpload = function(input) {
                  const file = input.files[0];
                  if (!file) return;

                  // 验证文件类型
                  const ext = file.name.split('.').pop().toLowerCase();
                  if (ext !== 'xlsx' && ext !== 'csv') {
                    Toastify({ text: '<?php echo ruiyi_translate("Solo se permiten archivos .xlsx o .csv", "Only .xlsx or .csv files allowed", "仅支持 .xlsx 或 .csv 文件"); ?>', duration: 3000, gravity: 'top', position: 'center', backgroundColor: '#ef4444' }).showToast();
                    input.value = '';
                    return;
                  }

                  // 验证文件大小 (5MB)
                  if (file.size > 5 * 1024 * 1024) {
                    Toastify({ text: '<?php echo ruiyi_translate("Archivo demasiado grande (máx 5MB)", "File too large (max 5MB)", "文件过大（最大 5MB）"); ?>', duration: 3000, gravity: 'top', position: 'center', backgroundColor: '#ef4444' }).showToast();
                    input.value = '';
                    return;
                  }

                  const btn = document.getElementById('upload-excel-product-names-btn');
                  const originalHTML = btn.innerHTML;
                  btn.disabled = true;
                  btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> <?php echo ruiyi_translate("Subiendo...", "Uploading...", "上传中..."); ?>';

                  const formData = new FormData();
                  formData.append('action', 'ruiyi_import_product_names_xlsx');
                  formData.append('nonce', window.RUIYI_POS_CONFIG.ajaxNonce || '<?php echo esc_js($ajax_nonce); ?>');
                  formData.append('file', file);

                  fetch(window.RUIYI_POS_CONFIG.homeUrl + '/wp-admin/admin-ajax.php', {
                    method: 'POST',
                    body: formData
                  })
                  .then(r => r.json())
                  .then(res => {
                    if (res.success) {
                      const data = res.data;
                      // 更新内存数据
                      if (data.products && Array.isArray(data.products)) {
                        data.products.forEach(updated => {
                          const p = nameEditorProducts.find(x => x.id === updated.id);
                          if (p) {
                            p.name_es = updated.name_es;
                            p.name_zh = updated.name_zh;
                            p.name_en = updated.name_en;
                          }
                        });
                      }
                      // 清除未保存的手动修改（已被Excel覆盖的部分）
                      Object.keys(changedProducts).forEach(k => delete changedProducts[k]);
                      document.getElementById('save-product-names-btn').disabled = true;
                      document.getElementById('multilingual-name-status').textContent = '';
                      // 重新渲染表格
                      renderProductNameEditor();
                      Toastify({
                        text: '<?php echo ruiyi_translate("Actualización exitosa", "Updated successfully", "成功更新"); ?> ' + (data.updated || 0) + ' <?php echo ruiyi_translate("productos", "products", "个产品"); ?>' + (data.skipped ? ' (<?php echo ruiyi_translate("omitidos", "skipped", "跳过"); ?>: ' + data.skipped + ')' : ''),
                        duration: 4000, gravity: 'top', position: 'center', backgroundColor: '#22c55e'
                      }).showToast();
                    } else {
                      Toastify({ text: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>: ' + (res.data?.message || '<?php echo ruiyi_translate("Error desconocido", "Unknown error", "未知错误"); ?>'), duration: 4000, gravity: 'top', position: 'center', backgroundColor: '#ef4444' }).showToast();
                    }
                  })
                  .catch(err => {
                    Toastify({ text: '<?php echo ruiyi_translate("Error de red", "Network error", "网络错误"); ?>', duration: 3000, gravity: 'top', position: 'center', backgroundColor: '#ef4444' }).showToast();
                  })
                  .finally(() => {
                    btn.disabled = false;
                    btn.innerHTML = originalHTML;
                    input.value = '';
                  });
                };

                // 首次切换到此tab时AJAX加载数据并渲染
                const observer = new MutationObserver(function(mutations) {
                  mutations.forEach(function(m) {
                    if (m.target.id === 'multilingual-settings' && !m.target.classList.contains('hidden')) {
                      observer.disconnect();
                      if (nameEditorProducts.length === 0) {
                        var _ajaxUrl = window.ajaxUrl || (window.RUIYI_POS_CONFIG?.homeUrl + '/wp-admin/admin-ajax.php');
                        var _nonce = window.RUIYI_POS_CONFIG?.ajaxNonce || currentNonce;
                        fetch(_ajaxUrl, {
                          method: 'POST',
                          headers: {'Content-Type': 'application/x-www-form-urlencoded'},
                          body: 'action=ruiyi_pos_get_multilingual_products&nonce=' + encodeURIComponent(_nonce)
                        }).then(function(r) { return r.json(); }).then(function(res) {
                          if (res.success && res.data) {
                            nameEditorProducts = res.data;
                            renderProductNameEditor();
                          }
                        }).catch(function(err) { console.error('[multilingual] Failed to load products:', err); });
                      } else {
                        renderProductNameEditor();
                      }
                    }
                  });
                });
                const multilingualDiv = document.getElementById('multilingual-settings');
                if (multilingualDiv) {
                  observer.observe(multilingualDiv, { attributes: true, attributeFilter: ['class'] });
                }
              })();
              </script>

            <!-- ===== 分类多语言名称编辑器 ===== -->
            <div class="mt-8 border-t border-gray-200 dark:border-gray-700 pt-8">
              <div class="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg p-6 shadow-sm">
                <h3 class="text-xl font-semibold text-gray-800 dark:text-white mb-2 flex items-center">
                  <i class="fas fa-folder-open mr-2 text-amber-600"></i>
                  <?php echo ruiyi_translate('Nombres de categorías multilingüe', 'Multilingual category names', '分类多语言名称'); ?>
                </h3>
                <p class="text-sm text-gray-500 dark:text-gray-400 mb-6">
                  <?php echo ruiyi_translate(
                    'Edite los nombres de categorías en diferentes idiomas. Los nombres se mostrarán según el idioma actual del sistema.',
                    'Edit category names in different languages. Names will be displayed based on the current system language.',
                    '编辑分类的多语言名称。系统将根据当前语言自动显示对应的分类名称。'
                  ); ?>
                </p>

                <!-- Excel 批量操作区 -->
                <div class="mb-4 flex items-center gap-3 p-3 bg-gradient-to-r from-amber-50 to-orange-50 dark:from-gray-700 dark:to-gray-700 rounded-lg border border-amber-200 dark:border-gray-600">
                  <i class="fas fa-file-excel text-amber-600 dark:text-amber-400 text-lg"></i>
                  <span class="text-sm text-gray-600 dark:text-gray-300 mr-auto">
                    <?php echo ruiyi_translate(
                      'Excel lote: Descargar plantilla → Editar → Subir',
                      'Excel batch: Download template → Edit → Upload',
                      'Excel 批量编辑：下载模板 → 编辑 → 上传'
                    ); ?>
                  </span>
                  <button type="button" onclick="exportCategoryNamesExcel()"
                          class="px-3 py-1.5 bg-amber-500 text-white rounded-lg text-xs font-medium hover:bg-amber-600 transition-colors shadow-sm flex items-center gap-1.5">
                    <i class="fas fa-download"></i>
                    <?php echo ruiyi_translate('Exportar plantilla', 'Export template', '导出模板'); ?>
                  </button>
                  <button type="button" onclick="document.getElementById('excel-upload-category-names').click()"
                          id="upload-excel-category-names-btn"
                          class="px-3 py-1.5 bg-blue-500 text-white rounded-lg text-xs font-medium hover:bg-blue-600 transition-colors shadow-sm flex items-center gap-1.5">
                    <i class="fas fa-upload"></i>
                    <?php echo ruiyi_translate('Subir Excel', 'Upload Excel', '上传 Excel'); ?>
                  </button>
                  <input type="file" id="excel-upload-category-names" accept=".xlsx,.csv" class="hidden" onchange="handleCategoryNamesExcelUpload(this)">
                </div>

                <!-- 搜索框 -->
                <div class="mb-4">
                  <input type="text" id="multilingual-category-name-search"
                         placeholder="<?php echo ruiyi_translate('Buscar categorías por nombre o ID...', 'Search categories by name or ID...', '按名称或ID搜索分类...'); ?>"
                         class="w-full px-4 py-2.5 border border-gray-300 dark:border-gray-600 rounded-lg text-sm bg-white dark:bg-gray-700 text-gray-800 dark:text-white focus:ring-2 focus:ring-amber-300 focus:border-amber-400"
                         oninput="filterCategoryNameEditor(this.value)">
                </div>

                <!-- 分类表格 -->
                <div class="overflow-x-auto max-h-[400px] overflow-y-auto border border-gray-200 dark:border-gray-600 rounded-lg">
                  <table class="w-full text-sm" id="multilingual-category-name-table">
                    <thead class="bg-gray-100 dark:bg-gray-700 sticky top-0 z-10">
                      <tr>
                        <th class="px-3 py-2.5 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 w-14">ID</th>
                        <th class="px-3 py-2.5 text-left text-xs font-semibold text-gray-600 dark:text-gray-300">
                          <span class="inline-flex items-center"><i class="fas fa-tag mr-1.5 text-gray-400"></i><?php echo ruiyi_translate('Por defecto', 'Default', '默认名称'); ?></span>
                        </th>
                        <th class="px-3 py-2.5 text-left text-xs font-semibold text-gray-600 dark:text-gray-300">
                          <span class="inline-flex items-center"><span class="fi fi-es mr-1.5 rounded" style="font-size:14px;"></span><?php echo ruiyi_translate('Español (ES)', 'Spanish (ES)', '西班牙语 (ES)'); ?></span>
                        </th>
                        <th class="px-3 py-2.5 text-left text-xs font-semibold text-gray-600 dark:text-gray-300">
                          <span class="inline-flex items-center"><span class="mr-1.5">🇬🇧</span><?php echo ruiyi_translate('Inglés (EN)', 'English (EN)', '英语 (EN)'); ?></span>
                        </th>
                        <th class="px-3 py-2.5 text-left text-xs font-semibold text-gray-600 dark:text-gray-300">
                          <span class="inline-flex items-center"><span class="mr-1.5">🇨🇳</span><?php echo ruiyi_translate('Chino (ZH)', 'Chinese (ZH)', '中文 (ZH)'); ?></span>
                        </th>
                      </tr>
                    </thead>
                    <tbody id="multilingual-category-name-tbody">
                    </tbody>
                  </table>
                </div>

                <!-- 保存按钮区域 -->
                <div class="mt-4 flex items-center justify-between">
                  <span id="multilingual-category-name-status" class="text-sm text-gray-500 dark:text-gray-400"></span>
                  <button type="button" onclick="saveCategoryNames()" id="save-category-names-btn"
                          class="px-5 py-2.5 bg-amber-500 text-white rounded-lg text-sm font-medium hover:bg-amber-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-md" disabled>
                    <i class="fas fa-save mr-1.5"></i>
                    <?php echo ruiyi_translate('Guardar nombres', 'Save names', '保存名称修改'); ?>
                  </button>
                </div>
              </div>

              <script>
              (function() {
                // 分类多语言名称编辑器数据
                let nameEditorCategories = []; // 🔥 数据延迟加载（AJAX）减少页面加载时间

                const changedCategories = {};

                function escapeAttrCat(str) {
                  return String(str || '').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/'/g,'&#39;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
                }

                window.renderCategoryNameEditor = function(filter) {
                  const tbody = document.getElementById('multilingual-category-name-tbody');
                  tbody.innerHTML = '';
                  const query = (filter || '').toLowerCase();

                  nameEditorCategories.forEach(c => {
                    if (query && !c.name_default.toLowerCase().includes(query) &&
                        !c.name_es.toLowerCase().includes(query) &&
                        !c.name_zh.toLowerCase().includes(query) &&
                        !c.name_en.toLowerCase().includes(query) &&
                        !String(c.id).includes(query)) {
                      return;
                    }

                    const row = document.createElement('tr');
                    row.className = 'border-b border-gray-100 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-750';
                    row.dataset.categoryId = c.id;

                    const changed = changedCategories[c.id];
                    const defVal = changed?.name_default ?? c.name_default;
                    const esVal = changed?.name_es ?? c.name_es;
                    const enVal = changed?.name_en ?? c.name_en;
                    const zhVal = changed?.name_zh ?? c.name_zh;

                    const inputCls = 'w-full px-2 py-1.5 border border-gray-200 dark:border-gray-600 rounded text-sm bg-white dark:bg-gray-700 text-gray-800 dark:text-white focus:ring-1 focus:ring-amber-300';

                    row.innerHTML = `
                      <td class="px-3 py-1.5 text-xs text-gray-400">${c.id}</td>
                      <td class="px-2 py-1.5"><input type="text" value="${escapeAttrCat(defVal)}" data-field="name_default" data-id="${c.id}" data-original="${escapeAttrCat(c.name_default)}" class="${inputCls}" oninput="trackCategoryChange(${c.id},'name_default',this.value,this.dataset.original)" placeholder=""></td>
                      <td class="px-2 py-1.5"><input type="text" value="${escapeAttrCat(esVal)}" data-field="name_es" data-id="${c.id}" data-original="${escapeAttrCat(c.name_es)}" class="${inputCls}" oninput="trackCategoryChange(${c.id},'name_es',this.value,this.dataset.original)" placeholder="${escapeAttrCat(defVal)}"></td>
                      <td class="px-2 py-1.5"><input type="text" value="${escapeAttrCat(enVal)}" data-field="name_en" data-id="${c.id}" data-original="${escapeAttrCat(c.name_en)}" class="${inputCls}" oninput="trackCategoryChange(${c.id},'name_en',this.value,this.dataset.original)" placeholder="${escapeAttrCat(defVal)}"></td>
                      <td class="px-2 py-1.5"><input type="text" value="${escapeAttrCat(zhVal)}" data-field="name_zh" data-id="${c.id}" data-original="${escapeAttrCat(c.name_zh)}" class="${inputCls}" oninput="trackCategoryChange(${c.id},'name_zh',this.value,this.dataset.original)" placeholder="${escapeAttrCat(defVal)}"></td>
                    `;

                    tbody.appendChild(row);
                  });
                };

                window.filterCategoryNameEditor = function(query) {
                  renderCategoryNameEditor(query);
                };

                window.trackCategoryChange = function(categoryId, field, value, original) {
                  if (!changedCategories[categoryId]) {
                    const c = nameEditorCategories.find(x => x.id === categoryId);
                    changedCategories[categoryId] = { id: categoryId, name_default: c.name_default, name_es: c.name_es, name_en: c.name_en, name_zh: c.name_zh };
                  }
                  changedCategories[categoryId][field] = value;

                  const c = nameEditorCategories.find(x => x.id === categoryId);
                  if (changedCategories[categoryId].name_default === c.name_default &&
                      changedCategories[categoryId].name_es === c.name_es &&
                      changedCategories[categoryId].name_en === c.name_en &&
                      changedCategories[categoryId].name_zh === c.name_zh) {
                    delete changedCategories[categoryId];
                  }

                  const btn = document.getElementById('save-category-names-btn');
                  const count = Object.keys(changedCategories).length;
                  btn.disabled = count === 0;
                  document.getElementById('multilingual-category-name-status').textContent = count > 0
                    ? '<?php echo ruiyi_translate("Categorías modificadas", "Categories modified", "已修改分类"); ?>: ' + count
                    : '';
                };

                window.saveCategoryNames = function() {
                  const categories = Object.values(changedCategories);
                  if (categories.length === 0) return;

                  const btn = document.getElementById('save-category-names-btn');
                  const statusEl = document.getElementById('multilingual-category-name-status');
                  btn.disabled = true;
                  btn.innerHTML = '<i class="fas fa-spinner fa-spin mr-1"></i><?php echo ruiyi_translate("Guardando...", "Saving...", "保存中..."); ?>';

                  fetch(window.RUIYI_POS_CONFIG.homeUrl + '/wp-admin/admin-ajax.php', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                    body: 'action=ruiyi_save_category_names&nonce=' + encodeURIComponent(window.RUIYI_POS_CONFIG.ajaxNonce || '<?php echo esc_js($ajax_nonce); ?>') + '&categories=' + encodeURIComponent(JSON.stringify(categories))
                  })
                  .then(r => r.json())
                  .then(res => {
                    if (res.success) {
                      categories.forEach(changed => {
                        const c = nameEditorCategories.find(x => x.id === changed.id);
                        if (c) { c.name_es = changed.name_es; c.name_zh = changed.name_zh; c.name_en = changed.name_en; }
                      });
                      Object.keys(changedCategories).forEach(k => delete changedCategories[k]);
                      statusEl.textContent = '<?php echo ruiyi_translate("¡Guardado exitosamente!", "Saved successfully!", "保存成功！"); ?>';
                      statusEl.className = 'text-sm text-green-600 font-medium';
                      setTimeout(() => { statusEl.textContent = ''; statusEl.className = 'text-sm text-gray-500 dark:text-gray-400'; }, 3000);
                      renderCategoryNameEditor();
                    } else {
                      statusEl.textContent = '<?php echo ruiyi_translate("Error al guardar", "Save error", "保存失败"); ?>: ' + (res.data?.message || '');
                      statusEl.className = 'text-sm text-red-500';
                    }
                    btn.disabled = Object.keys(changedCategories).length === 0;
                    btn.innerHTML = '<i class="fas fa-save mr-1.5"></i><?php echo ruiyi_translate("Guardar nombres", "Save names", "保存名称修改"); ?>';
                  })
                  .catch(err => {
                    statusEl.textContent = '<?php echo ruiyi_translate("Error de red", "Network error", "网络错误"); ?>';
                    statusEl.className = 'text-sm text-red-500';
                    btn.disabled = false;
                    btn.innerHTML = '<i class="fas fa-save mr-1.5"></i><?php echo ruiyi_translate("Guardar nombres", "Save names", "保存名称修改"); ?>';
                  });
                };

                // Excel 导出分类模板
                window.exportCategoryNamesExcel = function() {
                  const ajaxUrl = window.RUIYI_POS_CONFIG.homeUrl + '/wp-admin/admin-ajax.php';
                  const nonce = window.RUIYI_POS_CONFIG.ajaxNonce || '<?php echo esc_js($ajax_nonce); ?>';
                  window.location.href = ajaxUrl + '?action=ruiyi_export_category_names_xlsx&nonce=' + encodeURIComponent(nonce);
                };

                // Excel 上传分类处理
                window.handleCategoryNamesExcelUpload = function(input) {
                  const file = input.files[0];
                  if (!file) return;

                  const ext = file.name.split('.').pop().toLowerCase();
                  if (ext !== 'xlsx' && ext !== 'csv') {
                    Toastify({ text: '<?php echo ruiyi_translate("Solo se permiten archivos .xlsx o .csv", "Only .xlsx or .csv files allowed", "仅支持 .xlsx 或 .csv 文件"); ?>', duration: 3000, gravity: 'top', position: 'center', backgroundColor: '#ef4444' }).showToast();
                    input.value = '';
                    return;
                  }

                  if (file.size > 5 * 1024 * 1024) {
                    Toastify({ text: '<?php echo ruiyi_translate("Archivo demasiado grande (máx 5MB)", "File too large (max 5MB)", "文件过大（最大 5MB）"); ?>', duration: 3000, gravity: 'top', position: 'center', backgroundColor: '#ef4444' }).showToast();
                    input.value = '';
                    return;
                  }

                  const btn = document.getElementById('upload-excel-category-names-btn');
                  const originalHTML = btn.innerHTML;
                  btn.disabled = true;
                  btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> <?php echo ruiyi_translate("Subiendo...", "Uploading...", "上传中..."); ?>';

                  const formData = new FormData();
                  formData.append('action', 'ruiyi_import_category_names_xlsx');
                  formData.append('nonce', window.RUIYI_POS_CONFIG.ajaxNonce || '<?php echo esc_js($ajax_nonce); ?>');
                  formData.append('file', file);

                  fetch(window.RUIYI_POS_CONFIG.homeUrl + '/wp-admin/admin-ajax.php', {
                    method: 'POST',
                    body: formData
                  })
                  .then(r => r.json())
                  .then(res => {
                    if (res.success) {
                      const data = res.data;
                      if (data.categories && Array.isArray(data.categories)) {
                        data.categories.forEach(updated => {
                          const c = nameEditorCategories.find(x => x.id === updated.id);
                          if (c) {
                            c.name_es = updated.name_es;
                            c.name_zh = updated.name_zh;
                            c.name_en = updated.name_en;
                          }
                        });
                      }
                      Object.keys(changedCategories).forEach(k => delete changedCategories[k]);
                      document.getElementById('save-category-names-btn').disabled = true;
                      document.getElementById('multilingual-category-name-status').textContent = '';
                      renderCategoryNameEditor();
                      Toastify({
                        text: '<?php echo ruiyi_translate("Actualización exitosa", "Updated successfully", "成功更新"); ?> ' + (data.updated || 0) + ' <?php echo ruiyi_translate("categorías", "categories", "个分类"); ?>' + (data.skipped ? ' (<?php echo ruiyi_translate("omitidos", "skipped", "跳过"); ?>: ' + data.skipped + ')' : ''),
                        duration: 4000, gravity: 'top', position: 'center', backgroundColor: '#22c55e'
                      }).showToast();
                    } else {
                      Toastify({ text: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>: ' + (res.data?.message || '<?php echo ruiyi_translate("Error desconocido", "Unknown error", "未知错误"); ?>'), duration: 4000, gravity: 'top', position: 'center', backgroundColor: '#ef4444' }).showToast();
                    }
                  })
                  .catch(err => {
                    Toastify({ text: '<?php echo ruiyi_translate("Error de red", "Network error", "网络错误"); ?>', duration: 3000, gravity: 'top', position: 'center', backgroundColor: '#ef4444' }).showToast();
                  })
                  .finally(() => {
                    btn.disabled = false;
                    btn.innerHTML = originalHTML;
                    input.value = '';
                  });
                };

                // 首次切换到此tab时AJAX加载分类数据并渲染
                const catObserver = new MutationObserver(function(mutations) {
                  mutations.forEach(function(m) {
                    if (m.target.id === 'multilingual-settings' && !m.target.classList.contains('hidden')) {
                      catObserver.disconnect();
                      if (nameEditorCategories.length === 0) {
                        var _ajaxUrl = window.ajaxUrl || (window.RUIYI_POS_CONFIG?.homeUrl + '/wp-admin/admin-ajax.php');
                        var _nonce = window.RUIYI_POS_CONFIG?.ajaxNonce || currentNonce;
                        fetch(_ajaxUrl, {
                          method: 'POST',
                          headers: {'Content-Type': 'application/x-www-form-urlencoded'},
                          body: 'action=ruiyi_pos_get_multilingual_categories&nonce=' + encodeURIComponent(_nonce)
                        }).then(function(r) { return r.json(); }).then(function(res) {
                          if (res.success && res.data) {
                            nameEditorCategories = res.data;
                            renderCategoryNameEditor();
                          }
                        }).catch(function(err) { console.error('[multilingual] Failed to load categories:', err); });
                      } else {
                        renderCategoryNameEditor();
                      }
                    }
                  });
                });
                const multilingualDivCat = document.getElementById('multilingual-settings');
                if (multilingualDivCat) {
                  catObserver.observe(multilingualDivCat, { attributes: true, attributeFilter: ['class'] });
                }
              })();
              </script>
            </div>
            <!-- ===== End 分类多语言名称编辑器 ===== -->

            </div>
            <!-- End Tab 7: 产品多语言 -->

            <!-- ==================== Tab: 产品排序 ==================== -->
            <div id="productsort-settings" class="settings-content hidden space-y-6" data-loaded="0">
                <!-- 🔥 延迟加载：产品排序内容通过 AJAX 按需加载 -->
                <div id="productsort-placeholder" class="flex items-center justify-center p-16">
                  <div class="text-center">
                    <i class="fas fa-spinner fa-spin text-3xl text-purple-400 mb-3"></i>
                    <p class="text-sm text-gray-500 dark:text-gray-400"><?php echo ruiyi_translate('Cargando ordenación de productos...', 'Loading product sorting...', '加载产品排序中...'); ?></p>
                  </div>
                </div>
            </div>
            <!-- End Tab: 产品排序 (AJAX loaded) -->

            <?php if (false): // 🔥 原始产品排序代码已移至 inc/settings-tab-productsort.php，通过 AJAX 按需加载 ?>
            <?php
                $sort_all_cats = get_terms(['taxonomy' => 'product_cat', 'hide_empty' => true]);
                $sort_saved_order = json_decode(get_option('pos_customer_product_order', '{}'), true);
                if (!is_array($sort_saved_order)) $sort_saved_order = [];
                $sort_current_lang = defined('RUIYI_CURRENT_LANG') ? RUIYI_CURRENT_LANG : 'zh';
                $sort_cat_products = [];
                if (!empty($sort_all_cats) && !is_wp_error($sort_all_cats)) {
                    foreach ($sort_all_cats as $scat) {
                        $prods = wc_get_products(['status' => 'publish', 'limit' => -1, 'category' => [$scat->slug]]);
                        $cat_prod_list = [];
                        foreach ($prods as $sp) {
                            $sort_display_name = $sp->get_name();
                            if ($sort_current_lang === 'zh') {
                                $zh = get_post_meta($sp->get_id(), '_product_name_zh', true);
                                if (!empty($zh)) $sort_display_name = $zh;
                            } elseif ($sort_current_lang === 'en') {
                                $en = get_post_meta($sp->get_id(), '_product_name_en', true);
                                if (!empty($en)) $sort_display_name = $en;
                            }
                            $cat_prod_list[] = [
                                'id' => $sp->get_id(),
                                'name' => $sort_display_name,
                                'image' => wp_get_attachment_url($sp->get_image_id()) ?: '',
                            ];
                        }
                        if (isset($sort_saved_order[$scat->term_id])) {
                            $order_map = array_flip($sort_saved_order[$scat->term_id]);
                            usort($cat_prod_list, function($a, $b) use ($order_map) {
                                $pa = isset($order_map[$a['id']]) ? $order_map[$a['id']] : 9999;
                                $pb = isset($order_map[$b['id']]) ? $order_map[$b['id']] : 9999;
                                return $pa - $pb;
                            });
                        }
                        $sort_cat_products[$scat->term_id] = $cat_prod_list;
                    }
                }
                ?>
                <?php
                // 🔥 读取已保存的分类排序
                $saved_cat_order = json_decode(get_option('pos_customer_category_order', '[]'), true);
                if (!is_array($saved_cat_order)) $saved_cat_order = [];
                // 按已保存顺序排列分类
                $sorted_cats_for_display = [];
                if (!empty($sort_all_cats) && !is_wp_error($sort_all_cats)) {
                    if (!empty($saved_cat_order)) {
                        $cat_map = [];
                        foreach ($sort_all_cats as $sc) $cat_map[$sc->term_id] = $sc;
                        foreach ($saved_cat_order as $cid) {
                            if (isset($cat_map[$cid])) {
                                $sorted_cats_for_display[] = $cat_map[$cid];
                                unset($cat_map[$cid]);
                            }
                        }
                        foreach ($cat_map as $sc) $sorted_cats_for_display[] = $sc;
                    } else {
                        $sorted_cats_for_display = is_array($sort_all_cats) ? $sort_all_cats : [];
                    }
                }
                ?>
