                                    <span class="text-xs text-gray-400 dark:text-gray-500 flex-shrink-0">#<?php echo esc_html($sp['id']); ?></span>
                                  </li>
                                <?php endforeach; ?>
                              <?php else: ?>
                                <li class="text-sm text-gray-400 dark:text-gray-500 p-2"><?php echo ruiyi_translate('No hay productos en esta categoría', 'No products in this category', '该分类下没有产品'); ?></li>
                              <?php endif; ?>
