                <script>
                function switchSortCat(catId, btn) {
                    document.querySelectorAll('.sort-cat-tab').forEach(t => {
                        t.classList.remove('bg-purple-600', 'text-white');
                        t.classList.add('bg-gray-100', 'dark:bg-gray-700', 'text-gray-600', 'dark:text-gray-300');
                    });
                    btn.classList.remove('bg-gray-100', 'dark:bg-gray-700', 'text-gray-600', 'dark:text-gray-300');
                    btn.classList.add('bg-purple-600', 'text-white');
                    document.querySelectorAll('.sort-cat-panel').forEach(p => p.classList.add('hidden'));
                    const panel = document.querySelector('.sort-cat-panel[data-cat-id="' + catId + '"]');
                    if (panel) panel.classList.remove('hidden');
