                        ul.querySelectorAll('li[data-product-id]').forEach(li => {
                            ids.push(parseInt(li.getAttribute('data-product-id')));
                        });
                        if (ids.length > 0) {
                            data[catId] = ids;
                        }
                    });
                    document.getElementById('pos_customer_product_order').value = JSON.stringify(data);
                }

                function updateCatSortOrderInput() {
                    const ids = [];
                    document.querySelectorAll('#sortCategoryList li[data-cat-id]').forEach(li => {
                        ids.push(parseInt(li.getAttribute('data-cat-id')));
                    });
                    document.getElementById('pos_customer_category_order').value = JSON.stringify(ids);
                }

                $(function() {
                    $('.sort-product-list').sortable({
                        handle: 'span:first-child',
                        placeholder: 'bg-purple-100 dark:bg-purple-900 rounded-lg p-2 mb-1',
                        tolerance: 'pointer',
                        update: function() {
                            updateSortOrderInput();
