                    }).disableSelection();

                    $('#sortCategoryList').sortable({
                        handle: 'span:first-child',
                        placeholder: 'bg-indigo-100 dark:bg-indigo-900 rounded-lg p-3 mb-1',
                        tolerance: 'pointer',
                        update: function() {
                            updateCatSortOrderInput();
                        }
                    }).disableSelection();
                });
                </script>
