                    <span id="zone-pricing-status" class="text-sm text-gray-500 dark:text-gray-400"></span>
                    <button type="button" onclick="saveZonePrices()" id="save-zone-prices-btn"
                            class="px-5 py-2.5 bg-amber-500 text-white rounded-lg text-sm font-medium hover:bg-amber-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-md" disabled>
                      <i class="fas fa-save mr-1.5"></i>
                      <?php echo ruiyi_translate('Guardar precios', 'Save prices', '保存分区价格'); ?>
                    </button>
                  </div>

                  <?php endif; ?>
                </div>
              </div>

              <?php if (!empty($zp_categories)): ?>
              <script>
              (function() {
                let zpProducts = []; // 🔥 数据通过 AJAX 延迟加载
                const zpCategories = <?php echo json_encode($zp_categories_data); ?>;
                const zpChanged = {};

                function escAttr(str) {
                  return String(str || '').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/'/g,'&#39;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
                }

                window.renderZonePricingEditor = function(filter) {
                  const tbody = document.getElementById('zone-pricing-tbody');
                  tbody.innerHTML = '';
                  const query = (filter || '').toLowerCase();

                  zpProducts.forEach(p => {
                    if (query && !p.name.toLowerCase().includes(query) && !String(p.id).includes(query)) return;

                    const changed = zpChanged[p.id];
                    const baseVal = changed?.regular_price ?? p.regular_price;

                    let cells = `
                      <td class="px-3 py-1.5 text-xs text-gray-400">${p.id}</td>
                      <td class="px-3 py-1.5">${p.image ? '<img src="' + p.image + '" class="w-8 h-8 rounded object-cover">' : '<div class="w-8 h-8 rounded bg-gray-200 dark:bg-gray-600 flex items-center justify-center"><i class="fas fa-image text-gray-400 text-xs"></i></div>'}</td>
                      <td class="px-3 py-1.5 text-sm text-gray-700 dark:text-gray-200 font-medium">${escAttr(p.name)}</td>
                      <td class="px-2 py-1.5">
                        <input type="number" step="0.01" min="0" value="${escAttr(baseVal)}"
                               data-id="${p.id}" data-field="regular_price" data-original="${escAttr(p.regular_price)}"
                               class="w-full px-2 py-1.5 border border-gray-200 dark:border-gray-600 rounded text-sm bg-white dark:bg-gray-700 text-gray-800 dark:text-white focus:ring-1 focus:ring-amber-300"
                               oninput="trackZonePriceChange(${p.id},'regular_price',this.value,this.dataset.original)">
                      </td>`;

                    zpCategories.forEach(cat => {
                      const zoneKey = 'category_' + cat.id;
                      const zoneVal = changed?.zone_prices?.[zoneKey] ?? (p.zone_prices[zoneKey] ?? '');
                      const origVal = p.zone_prices[zoneKey] ?? '';
                      cells += `
                        <td class="px-2 py-1.5">
                          <input type="number" step="0.01" min="0" value="${escAttr(zoneVal)}"
                                 placeholder="${escAttr(baseVal)}"
                                 data-id="${p.id}" data-field="zone_${zoneKey}" data-zone-key="${zoneKey}" data-original="${escAttr(origVal)}"
                                 class="w-full px-2 py-1.5 border border-gray-200 dark:border-gray-600 rounded text-sm bg-white dark:bg-gray-700 text-gray-800 dark:text-white focus:ring-1 focus:ring-amber-300"
                                 oninput="trackZonePriceChange(${p.id},'zone_${zoneKey}',this.value,'${escAttr(origVal)}')">
                        </td>`;
                    });

                    const row = document.createElement('tr');
                    row.className = 'border-b border-gray-100 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-750';
                    row.dataset.productId = p.id;
                    row.innerHTML = cells;
                    tbody.appendChild(row);
                  });
                };

                window.filterZonePricingEditor = function(query) {
                  renderZonePricingEditor(query);
                };

                window.trackZonePriceChange = function(productId, field, value, original) {
                  const p = zpProducts.find(x => x.id === productId);
                  if (!p) return;

                  if (!zpChanged[productId]) {
                    zpChanged[productId] = {
                      id: productId,
                      regular_price: p.regular_price,
                      zone_prices: Object.assign({}, p.zone_prices)
                    };
                  }

                  if (field === 'regular_price') {
                    zpChanged[productId].regular_price = value;
                    // 更新该产品所有分区价格输入框的 placeholder
                    document.querySelectorAll('#zone-pricing-tbody tr[data-product-id="' + productId + '"] input[data-zone-key]').forEach(inp => {
                      inp.placeholder = value || '0';
                    });
                  } else if (field.startsWith('zone_')) {
                    const zoneKey = field.replace('zone_', '');
                    if (value === '' || value === null) {
                      delete zpChanged[productId].zone_prices[zoneKey];
                    } else {
                      zpChanged[productId].zone_prices[zoneKey] = value;
                    }
                  }

                  // 检查是否有实际变化
                  const c = zpChanged[productId];
                  let hasChanges = false;
                  if (String(c.regular_price) !== String(p.regular_price)) hasChanges = true;

                  if (!hasChanges) {
                    const origZones = p.zone_prices || {};
                    const newZones = c.zone_prices || {};
                    const allKeys = new Set([...Object.keys(origZones), ...Object.keys(newZones)]);
                    for (const k of allKeys) {
                      if (String(origZones[k] ?? '') !== String(newZones[k] ?? '')) {
                        hasChanges = true;
                        break;
                      }
                    }
                  }

                  if (!hasChanges) {
                    delete zpChanged[productId];
                  }

                  const btn = document.getElementById('save-zone-prices-btn');
                  const count = Object.keys(zpChanged).length;
                  btn.disabled = count === 0;
                  document.getElementById('zone-pricing-status').textContent = count > 0
                    ? '<?php echo ruiyi_translate("Productos modificados", "Products modified", "已修改产品"); ?>: ' + count
                    : '';
                };

                window.saveZonePrices = function() {
                  const products = Object.values(zpChanged);
                  if (products.length === 0) return;

                  const btn = document.getElementById('save-zone-prices-btn');
                  const statusEl = document.getElementById('zone-pricing-status');
                  btn.disabled = true;
                  btn.innerHTML = '<i class="fas fa-spinner fa-spin mr-1"></i><?php echo ruiyi_translate("Guardando...", "Saving...", "保存中..."); ?>';

                  fetch(window.RUIYI_POS_CONFIG.homeUrl + '/wp-admin/admin-ajax.php', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                    body: 'action=ruiyi_batch_update_zone_prices&nonce=' + encodeURIComponent(window.RUIYI_POS_CONFIG.ajaxNonce || '<?php echo esc_js($ajax_nonce); ?>') + '&products=' + encodeURIComponent(JSON.stringify(products))
                  })
                  .then(r => r.json())
                  .then(res => {
                    if (res.success) {
                      products.forEach(changed => {
                        const p = zpProducts.find(x => x.id === changed.id);
                        if (p) {
                          p.regular_price = changed.regular_price;
                          p.zone_prices = Object.assign({}, changed.zone_prices);
                        }
                      });
                      Object.keys(zpChanged).forEach(k => delete zpChanged[k]);
                      statusEl.textContent = '<?php echo ruiyi_translate("¡Guardado exitosamente!", "Saved successfully!", "保存成功！"); ?>';
                      statusEl.className = 'text-sm text-green-600 font-medium';
                      setTimeout(() => { statusEl.textContent = ''; statusEl.className = 'text-sm text-gray-500 dark:text-gray-400'; }, 3000);
                      btn.innerHTML = '<i class="fas fa-save mr-1.5"></i><?php echo ruiyi_translate("Guardar precios", "Save prices", "保存分区价格"); ?>';
                      btn.disabled = true;
                      renderZonePricingEditor(document.getElementById('zone-pricing-search')?.value || '');
                    } else {
                      statusEl.textContent = '<?php echo ruiyi_translate("Error al guardar", "Save error", "保存失败"); ?>: ' + (res.data?.message || '');
                      statusEl.className = 'text-sm text-red-500';
                      btn.innerHTML = '<i class="fas fa-save mr-1.5"></i><?php echo ruiyi_translate("Guardar precios", "Save prices", "保存分区价格"); ?>';
                      btn.disabled = false;
                    }
                  })
                  .catch(err => {
                    statusEl.textContent = '<?php echo ruiyi_translate("Error de red", "Network error", "网络错误"); ?>';
                    statusEl.className = 'text-sm text-red-500';
                    btn.innerHTML = '<i class="fas fa-save mr-1.5"></i><?php echo ruiyi_translate("Guardar precios", "Save prices", "保存分区价格"); ?>';
                    btn.disabled = false;
                  });
                };

                // Excel 导出
                window.exportZonePricesExcel = function() {
                  const ajaxUrl = window.RUIYI_POS_CONFIG.homeUrl + '/wp-admin/admin-ajax.php';
                  const nonce = window.RUIYI_POS_CONFIG.ajaxNonce || '<?php echo esc_js($ajax_nonce); ?>';
                  window.location.href = ajaxUrl + '?action=ruiyi_export_zone_prices_xlsx&nonce=' + encodeURIComponent(nonce);
                };

                // Excel 导入
                window.handleZonePricesExcelUpload = function(input) {
                  const file = input.files[0];
                  if (!file) return;

                  const ext = file.name.split('.').pop().toLowerCase();
                  if (ext !== 'xlsx' && ext !== 'csv') {
                    Toastify({ text: '<?php echo ruiyi_translate("Solo se permiten archivos .xlsx o .csv", "Only .xlsx or .csv files allowed", "仅支持 .xlsx 或 .csv 文件"); ?>', duration: 3000, gravity: 'top', position: 'center', backgroundColor: '#ef4444' }).showToast();
                    input.value = '';
                    return;
                  }

                  if (file.size > 5 * 1024 * 1024) {
                    Toastify({ text: '<?php echo ruiyi_translate("Archivo demasiado grande (máx 5MB)", "File too large (max 5MB)", "文件过大（最大 5MB）"); ?>', duration: 3000, gravity: 'top', position: 'center', backgroundColor: '#ef4444' }).showToast();
                    input.value = '';
                    return;
                  }

                  const btn = document.getElementById('upload-excel-zone-prices-btn');
                  const originalHTML = btn.innerHTML;
                  btn.disabled = true;
                  btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> <?php echo ruiyi_translate("Subiendo...", "Uploading...", "上传中..."); ?>';

                  const formData = new FormData();
                  formData.append('action', 'ruiyi_import_zone_prices_xlsx');
                  formData.append('nonce', window.RUIYI_POS_CONFIG.ajaxNonce || '<?php echo esc_js($ajax_nonce); ?>');
                  formData.append('file', file);

                  fetch(window.RUIYI_POS_CONFIG.homeUrl + '/wp-admin/admin-ajax.php', {
                    method: 'POST',
                    body: formData
                  })
                  .then(r => r.json())
                  .then(res => {
                    if (res.success) {
                      const data = res.data;
                      // 更新内存数据
                      if (data.products && Array.isArray(data.products)) {
                        data.products.forEach(updated => {
                          const p = zpProducts.find(x => x.id === updated.id);
                          if (p) {
                            p.regular_price = updated.regular_price;
                            p.zone_prices = updated.zone_prices || {};
                          }
                        });
                      }
                      // 清除手动修改
                      Object.keys(zpChanged).forEach(k => delete zpChanged[k]);
                      document.getElementById('save-zone-prices-btn').disabled = true;
                      document.getElementById('zone-pricing-status').textContent = '';
                      // 重新渲染
                      renderZonePricingEditor(document.getElementById('zone-pricing-search')?.value || '');
                      Toastify({
                        text: '<?php echo ruiyi_translate("Actualización exitosa", "Updated successfully", "成功更新"); ?> ' + (data.updated || 0) + ' <?php echo ruiyi_translate("productos", "products", "个产品"); ?>' + (data.skipped ? ' (<?php echo ruiyi_translate("omitidos", "skipped", "跳过"); ?>: ' + data.skipped + ')' : ''),
                        duration: 4000, gravity: 'top', position: 'center', backgroundColor: '#22c55e'
                      }).showToast();
                    } else {
                      Toastify({ text: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>: ' + (res.data?.message || ''), duration: 4000, gravity: 'top', position: 'center', backgroundColor: '#ef4444' }).showToast();
                    }
                  })
                  .catch(err => {
                    Toastify({ text: '<?php echo ruiyi_translate("Error de red", "Network error", "网络错误"); ?>', duration: 3000, gravity: 'top', position: 'center', backgroundColor: '#ef4444' }).showToast();
                  })
                  .finally(() => {
                    btn.disabled = false;
                    btn.innerHTML = originalHTML;
                    input.value = '';
                  });
                };

                // 🔥 延迟加载：观察 tab 可见时 AJAX 加载产品数据
                var _zpLoaded = false;
                var zpObserver = new MutationObserver(function(mutations) {
                  mutations.forEach(function(m) {
                    if (m.target.id === 'zonepricing-settings' && !m.target.classList.contains('hidden') && !_zpLoaded) {
                      _zpLoaded = true;
                      zpObserver.disconnect();
                      var _ajaxUrl = window.ajaxUrl || (window.RUIYI_POS_CONFIG?.homeUrl + '/wp-admin/admin-ajax.php');
                      var _nonce = window.RUIYI_POS_CONFIG?.ajaxNonce || currentNonce;
                      fetch(_ajaxUrl, {
                        method: 'POST',
                        headers: {'Content-Type': 'application/x-www-form-urlencoded'},
                        body: 'action=ruiyi_pos_get_zonepricing_products&nonce=' + encodeURIComponent(_nonce)
                      }).then(function(r) { return r.json(); }).then(function(res) {
                        if (res.success && res.data) {
                          zpProducts = res.data;
                          renderZonePricingEditor();
                        }
                      }).catch(function(err) { console.error('[zonepricing] Failed to load products:', err); });
                    }
                  });
                });
                var zpDiv = document.getElementById('zonepricing-settings');
                if (zpDiv) zpObserver.observe(zpDiv, { attributes: true, attributeFilter: ['class'] });
              })();
              </script>
              <?php endif; ?>
            </div>
            <!-- End Tab: 产品分区价格 -->

            <!-- 🔥 全局保存按钮 - 保存所有设置 -->
            <div id="global-save-button-container" class="bg-white dark:bg-gray-900 border-t border-gray-200 dark:border-gray-700 p-4 mt-6 -mx-6 -mb-6 rounded-b-xl">
              <div class="flex justify-end">
                <button type="submit" class="bg-primary hover:bg-red-700 text-white px-6 py-3 rounded-lg flex items-center font-medium transition-colors shadow-md">
                  <i class="fas fa-save mr-2"></i> <?php echo ruiyi_translate("Guardar Todos los Ajustes", "Save All Settings", "保存所有设置"); ?>
                </button>
              </div>
            </div>

            </form>
            <!-- 🔥 End 统一表单 -->

            <!-- 🔥 设置预览 JavaScript 函数 -->
            <script>
            // 分类未选中透明度预览函数
            function updateCategoryOpacityPreview(value) {
                const opacityValue = parseFloat(value) / 100;
                document.getElementById('category-unselected-opacity-display').textContent = value + '%';
                // 更新未选中分类预览的透明度
                const unselectedPreviews = document.querySelectorAll('#category-preview-unselected-1, #category-preview-unselected-2, #category-preview-unselected-3');
                unselectedPreviews.forEach(el => {
                    el.style.opacity = opacityValue;
                });
            }

            // 🔥 分类按钮颜色预览函数
            function updateCategoryColorPreview() {
                // 获取所有颜色值
                const selectedBg = document.getElementById('category-selected-bg').value;
                const selectedText = document.getElementById('category-selected-text').value;
                const unselectedBg = document.getElementById('category-unselected-bg').value;
                const unselectedText = document.getElementById('category-unselected-text').value;
                const unselectedBorder = document.getElementById('category-unselected-border').value;
                const opacityRange = document.getElementById('category-unselected-opacity-range');
                const opacity = opacityRange ? parseFloat(opacityRange.value) / 100 : 1;

                // 🔥 获取背景浓度并转换为十六进制
                const intensitySlider = document.getElementById('category-unselected-bg-intensity');
                const intensityPercent = intensitySlider ? parseInt(intensitySlider.value) : 19;
                const intensityHex = Math.round(intensityPercent / 100 * 255).toString(16).padStart(2, '0');

                // 更新选中状态预览
                const selectedPreview = document.getElementById('category-preview-selected');
                if (selectedPreview) {
                    selectedPreview.style.backgroundColor = selectedBg;
                    selectedPreview.style.color = selectedText;
                    selectedPreview.style.borderColor = selectedBg;
                }

                // 更新未选中状态预览
                const unselectedPreviews = document.querySelectorAll('#category-preview-unselected-1, #category-preview-unselected-2, #category-preview-unselected-3');
                unselectedPreviews.forEach(el => {
                    el.style.backgroundColor = unselectedBg + intensityHex;
                    el.style.color = unselectedText;
                    el.style.borderColor = unselectedBorder;
                    el.style.opacity = opacity;
                });
            }

            // 按钮颜色预览函数
            function updateButtonPreview(type, color) {
                const previewBtn = document.getElementById('btn-preview-' + type);
                if (previewBtn) {
                    previewBtn.style.backgroundColor = color;
                }
            }
            </script>

