                        <tbody id="bulk-upload-preview-tbody"></tbody>
                      </table>
                    </div>
                  </div>

                  <!-- 进度条 -->
                  <div id="bulk-upload-progress" style="display:none; margin-bottom:16px;">
                    <div style="display:flex; justify-content:space-between; font-size:12px; color:#6b7280; margin-bottom:4px;">
                      <span id="bulk-upload-progress-text"><?php echo ruiyi_translate('Importando...', 'Importing...', '导入中...'); ?></span>
                      <span id="bulk-upload-progress-percent">0%</span>
                    </div>
                    <div style="width:100%; height:8px; background:#e5e7eb; border-radius:4px; overflow:hidden;">
                      <div id="bulk-upload-progress-bar" style="width:0%; height:100%; background:#10b981; border-radius:4px; transition:width 0.3s;"></div>
                    </div>
                  </div>

                  <!-- 结果 -->
                  <div id="bulk-upload-result" style="display:none; padding:12px; border-radius:8px; font-size:13px;"></div>
                </div>

                <!-- 弹窗底部 -->
                <div style="padding:12px 24px; border-top:1px solid #e5e7eb; display:flex; justify-content:flex-end; gap:12px;">
                  <button type="button" onclick="closeBulkUploadModal()"
                          style="padding:8px 20px; background:#6b7280; color:white; border:none; border-radius:6px; font-size:13px; cursor:pointer;">
                    <?php echo ruiyi_translate('Cerrar', 'Close', '关闭'); ?>
                  </button>
                  <button type="button" id="bulk-upload-start-btn" onclick="startBulkUpload()" disabled
                          style="padding:8px 20px; background:#10b981; color:white; border:none; border-radius:6px; font-size:13px; cursor:pointer; opacity:0.5; display:flex; align-items:center; gap:6px;">
                    <i class="fas fa-upload"></i>
                    <?php echo ruiyi_translate('Iniciar importación', 'Start import', '开始导入'); ?>
                  </button>
                </div>
              </div>
            </div>

            <script src="https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js"></script>
            <script>
            // 🔥 批量导入客户 - JS逻辑
            var _bulkCustomers = [];

            document.getElementById('bulk-upload-customer-btn').addEventListener('click', function() {
                var m = document.getElementById('bulk-upload-customer-modal');
                m.style.display = 'flex';
                // 重置状态
                clearBulkUploadFile();
                document.getElementById('bulk-upload-progress').style.display = 'none';
                document.getElementById('bulk-upload-result').style.display = 'none';
                document.getElementById('bulk-upload-start-btn').disabled = true;
                document.getElementById('bulk-upload-start-btn').style.opacity = '0.5';
            });

            function closeBulkUploadModal() {
                document.getElementById('bulk-upload-customer-modal').style.display = 'none';
            }

            function clearBulkUploadFile() {
                _bulkCustomers = [];
                document.getElementById('bulk-upload-file-input').value = '';
                document.getElementById('bulk-upload-filename').textContent = '<?php echo ruiyi_translate("Haz clic o arrastra un archivo Excel aquí", "Click or drag an Excel file here", "点击或拖拽Excel文件到此处"); ?>';
                document.getElementById('bulk-upload-preview').style.display = 'none';
                document.getElementById('bulk-upload-start-btn').disabled = true;
                document.getElementById('bulk-upload-start-btn').style.opacity = '0.5';
                document.getElementById('bulk-upload-dropzone').style.display = 'block';
            }

            function downloadCustomerTemplate() {
                var wb = XLSX.utils.book_new();
                var data = [
                    ['<?php echo ruiyi_translate("Teléfono", "Phone", "电话"); ?>', '<?php echo ruiyi_translate("Empresa", "Business", "公司"); ?>', 'CIF/NIF', '<?php echo ruiyi_translate("Dirección", "Address", "地址"); ?>', '<?php echo ruiyi_translate("Código Postal", "Postal Code", "邮编"); ?>', '<?php echo ruiyi_translate("Email", "Email", "邮箱"); ?>'],
                    ['612345678', 'Empresa ABC S.L.', 'B12345678', 'Calle Mayor 10, Madrid', '28001', 'cliente@ejemplo.com'],
                    ['698765432', '', '', 'Av. Diagonal 200, Barcelona', '08018', '']
                ];
                var ws = XLSX.utils.aoa_to_sheet(data);
                ws['!cols'] = [{wch:14},{wch:22},{wch:12},{wch:35},{wch:8},{wch:22}];
                XLSX.utils.book_append_sheet(wb, ws, 'Clientes');
                XLSX.writeFile(wb, 'plantilla_clientes.xlsx');
            }

            // 列名映射：多语言识别
            var _colMap = {
                phone: ['电话','teléfono','telefono','phone','tel','手机','móvil','movil','mobile'],
                name: ['姓名','nombre','name','客户','cliente','customer','名称'],
                business_name: ['公司','empresa','business','company','商号','razón social','razon social'],
                cif_nif: ['cif','nif','cif/nif','cifnif','税号','ruc','vat'],
                address: ['地址','dirección','direccion','address','addr','domicilio'],
                postal_code: ['邮编','código postal','codigo postal','postal','cp','zip','postal code','zipcode'],
                email: ['邮箱','email','correo','e-mail','correo electrónico','correo electronico']
            };

            function matchColumn(header) {
                var h = (header || '').toString().toLowerCase().trim();
                for (var field in _colMap) {
                    for (var i = 0; i < _colMap[field].length; i++) {
                        if (h === _colMap[field][i]) return field;
                    }
                }
                return null;
            }

            function normalizeBulkCustomerPhone(value) {
                var phone = String(value || '').trim();
                var lowered = phone.toLowerCase();
                if (['', '-', '—', '--', 'n/a', 'na', 'null', 'undefined', 'sin telefono', 'sin teléfono'].indexOf(lowered) !== -1) {
                    return '';
                }
                return phone;
            }

            function hasBulkCustomerIdentity(c) {
                return !!(c.phone || c.business_name || c.cif_nif || c.address || c.postal_code || c.email);
            }

            function handleBulkUploadFile(file) {
                if (!file) return;
                var ext = file.name.split('.').pop().toLowerCase();
                if (['xlsx','xls','csv'].indexOf(ext) === -1) {
                    Swal.fire('<?php echo ruiyi_translate("Error","Error","错误"); ?>',
                              '<?php echo ruiyi_translate("Solo se aceptan archivos .xlsx, .xls o .csv","Only .xlsx, .xls or .csv files are accepted","仅支持 .xlsx、.xls 或 .csv 文件"); ?>',
                              'error');
                    return;
                }

                document.getElementById('bulk-upload-filename').textContent = file.name;

                var reader = new FileReader();
                reader.onload = function(e) {
                    try {
                        var wb = XLSX.read(e.target.result, {type:'array'});
                        var ws = wb.Sheets[wb.SheetNames[0]];
                        var rows = XLSX.utils.sheet_to_json(ws, {defval:''});

                        if (rows.length === 0) {
                            Swal.fire('<?php echo ruiyi_translate("Archivo vacío","Empty file","文件为空"); ?>',
                                      '<?php echo ruiyi_translate("No se encontraron datos en el archivo","No data found in the file","文件中没有找到数据"); ?>',
                                      'warning');
                            return;
                        }

                        // 识别列映射
                        var headers = Object.keys(rows[0]);
                        var mapping = {};
                        headers.forEach(function(h) {
                            var field = matchColumn(h);
                            if (field) mapping[h] = field;
                        });

                        // 检查是否有电话列
                        var hasPhone = Object.values(mapping).indexOf('phone') !== -1;
                        if (!hasPhone) {
                            // 尝试用第一列作为电话
                            if (headers.length > 0) {
                                mapping[headers[0]] = 'phone';
                                hasPhone = true;
                            }
                        }

                        if (!hasPhone) {
                            Swal.fire('<?php echo ruiyi_translate("Error","Error","错误"); ?>',
                                      '<?php echo ruiyi_translate("No se encontró la columna de teléfono","Phone column not found","未找到电话列"); ?>',
                                      'error');
                            return;
                        }

                        // 解析数据
                        _bulkCustomers = [];
                        rows.forEach(function(row) {
                            var c = {};
                            for (var h in mapping) {
                                c[mapping[h]] = String(row[h] || '').trim();
                            }
                            c.phone = normalizeBulkCustomerPhone(c.phone);
                            if (hasBulkCustomerIdentity(c)) {
                                _bulkCustomers.push(c);
                            }
                        });

                        if (_bulkCustomers.length === 0) {
                            Swal.fire('<?php echo ruiyi_translate("Sin datos válidos","No valid data","无有效数据"); ?>',
                                      '<?php echo ruiyi_translate("No se encontraron filas con datos de cliente válidos","No rows with valid customer data found","没有找到包含有效客户信息的行"); ?>',
                                      'warning');
                            return;
                        }

                        // 显示预览
                        var tbody = document.getElementById('bulk-upload-preview-tbody');
                        tbody.innerHTML = '';
                        var showCount = Math.min(_bulkCustomers.length, 50);
                        for (var i = 0; i < showCount; i++) {
                            var c = _bulkCustomers[i];
                            var tr = document.createElement('tr');
                            tr.style.borderBottom = '1px solid #f3f4f6';
                            tr.innerHTML = '<td style="padding:5px 10px; color:#6b7280;">' + (i+1) + '</td>' +
                                '<td style="padding:5px 10px; font-weight:500;">' + escapeHtml(c.phone || '-') + '</td>' +
                                '<td style="padding:5px 10px;">' + escapeHtml(c.business_name || '-') + '</td>' +
                                '<td style="padding:5px 10px; max-width:200px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">' + escapeHtml(c.address || '-') + '</td>';
                            tbody.appendChild(tr);
                        }
                        if (_bulkCustomers.length > 50) {
                            var tr2 = document.createElement('tr');
                            tr2.innerHTML = '<td colspan="4" style="padding:6px 10px; text-align:center; color:#9ca3af; font-style:italic;">... <?php echo ruiyi_translate("y","and","还有"); ?> ' + (_bulkCustomers.length - 50) + ' <?php echo ruiyi_translate("más","more","条更多"); ?></td>';
                            tbody.appendChild(tr2);
                        }

                        document.getElementById('bulk-upload-preview-count').textContent =
                            '<?php echo ruiyi_translate("Total: ","Total: ","共 "); ?>' + _bulkCustomers.length + ' <?php echo ruiyi_translate(" clientes"," customers","位客户"); ?>';
                        document.getElementById('bulk-upload-preview').style.display = 'block';
                        document.getElementById('bulk-upload-start-btn').disabled = false;
                        document.getElementById('bulk-upload-start-btn').style.opacity = '1';
                        document.getElementById('bulk-upload-dropzone').style.display = 'none';

                    } catch(err) {
                        console.error('Excel parse error:', err);
                        Swal.fire('<?php echo ruiyi_translate("Error al leer","Read error","读取错误"); ?>',
                                  err.message, 'error');
                    }
                };
                reader.readAsArrayBuffer(file);
            }

            async function startBulkUpload() {
                if (_bulkCustomers.length === 0) return;

                var btn = document.getElementById('bulk-upload-start-btn');
                btn.disabled = true;
                btn.style.opacity = '0.5';

                var progressDiv = document.getElementById('bulk-upload-progress');
                var progressBar = document.getElementById('bulk-upload-progress-bar');
                var progressText = document.getElementById('bulk-upload-progress-text');
                var progressPercent = document.getElementById('bulk-upload-progress-percent');
                var resultDiv = document.getElementById('bulk-upload-result');
                progressDiv.style.display = 'block';
                resultDiv.style.display = 'none';

                var total = _bulkCustomers.length;
                var success = 0, failed = 0, updated = 0;
                var errors = [];

                for (var i = 0; i < total; i++) {
                    var c = _bulkCustomers[i];
                    var pct = Math.round(((i + 1) / total) * 100);
                    progressBar.style.width = pct + '%';
                    progressPercent.textContent = pct + '%';
                    progressText.textContent = '<?php echo ruiyi_translate("Importando","Importing","正在导入"); ?> ' + (i+1) + '/' + total + '...';

                    try {
                        var formData = new FormData();
                        formData.append('action', 'ruiyi_create_customer_info');
                        formData.append('nonce', ajaxNonce);
                        formData.append('phone', c.phone);
                        formData.append('name', c.phone || c.business_name || c.cif_nif || c.address || '');
                        formData.append('business_name', c.business_name || '');
                        formData.append('cif_nif', c.cif_nif || '');
                        formData.append('address', c.address || '');
                        formData.append('postal_code', c.postal_code || '');
                        formData.append('email', c.email || '');

                        var resp = await fetch(ajaxUrl, {method:'POST', body:formData});
                        var json = await resp.json();
                        if (json.success) {
                            success++;
                        } else {
                            failed++;
                            errors.push((c.phone || c.business_name || c.cif_nif || '-') + ': ' + (json.data?.message || 'Unknown error'));
                        }
                    } catch(err) {
                        failed++;
                        errors.push((c.phone || c.business_name || c.cif_nif || '-') + ': ' + err.message);
                    }
                }

                // 显示结果
                progressDiv.style.display = 'none';
                var isAllSuccess = failed === 0;
                resultDiv.style.display = 'block';
                resultDiv.style.background = isAllSuccess ? '#f0fdf4' : '#fef2f2';
                resultDiv.style.border = '1px solid ' + (isAllSuccess ? '#bbf7d0' : '#fecaca');
                resultDiv.style.color = isAllSuccess ? '#166534' : '#991b1b';

                var html = '<p style="font-weight:600; margin:0 0 6px 0;">' +
                    '<i class="fas ' + (isAllSuccess ? 'fa-check-circle' : 'fa-exclamation-triangle') + ' mr-1"></i> ' +
                    '<?php echo ruiyi_translate("Importación completada","Import completed","导入完成"); ?></p>';
                html += '<p style="margin:0; font-size:12px;">';
                html += '<?php echo ruiyi_translate("Éxito: ","Success: ","成功："); ?><b>' + success + '</b>';
                if (failed > 0) {
                    html += ' &nbsp;|&nbsp; <?php echo ruiyi_translate("Error: ","Failed: ","失败："); ?><b style="color:#dc2626;">' + failed + '</b>';
                }
                html += ' &nbsp;|&nbsp; <?php echo ruiyi_translate("Total: ","Total: ","总计："); ?><b>' + total + '</b>';
                html += '</p>';
                if (errors.length > 0 && errors.length <= 10) {
                    html += '<details style="margin-top:8px;"><summary style="cursor:pointer; font-size:11px; color:#6b7280;"><?php echo ruiyi_translate("Ver errores","View errors","查看错误"); ?></summary>';
                    html += '<ul style="font-size:11px; margin:4px 0 0 16px; padding:0; color:#6b7280;">';
                    errors.forEach(function(e) { html += '<li>' + escapeHtml(e) + '</li>'; });
                    html += '</ul></details>';
                }
                resultDiv.innerHTML = html;

                // 刷新客户列表
                if (success > 0 && typeof loadCustomerList === 'function') {
                    loadCustomerList();
                } else if (success > 0) {
                    var refreshBtn = document.getElementById('customer-refresh-btn');
                    if (refreshBtn) refreshBtn.click();
                }
            }
            </script>

          </div> <!-- Cierre del div.grid principal de Ajustes -->
        </section> <!-- Fin Sección Ajustes -->

      </div>
    </main>
  </div>
</div>

<script>
// 全局变量定义 - 供此脚本块中的所有函数使用
// Use the global ajaxUrl/ajaxNonce defined earlier (avoid redefinition)
var ajaxUrl = window.ajaxUrl;
var ajaxNonce = window.RUIYI_POS?.nonce || currentNonce;
var voidOrderPassword = window.voidOrderPassword || '<?php echo esc_js(get_option('pos_void_order_password', '')); ?>';

// 🔥 HTML转义函数（用于开票等功能）
function escapeHtml(text) {
  if (!text) return '';
  const div = document.createElement('div');
  div.textContent = String(text);
  return div.innerHTML;
}

// Windows 7 专属模块：强制刷新页面
function forceRefreshPage() {
  location.reload(true);
}

// 切换账户：退出当前登录并回到登录页
function switchAccount() {
  Swal.fire({
    title: '<?php echo ruiyi_translate("¿Cambiar de cuenta?", "Switch account?", "切换账户？"); ?>',
    text: '<?php echo ruiyi_translate("Se cerrará la sesión actual y volverá a la página de inicio de sesión.", "The current session will be logged out and return to the login page.", "当前账户将退出登录，并返回登录页面。"); ?>',
    icon: 'question',
    showCancelButton: true,
    confirmButtonText: '<?php echo ruiyi_translate("Sí, cambiar cuenta", "Yes, switch account", "是的，切换账户"); ?>',
    cancelButtonText: '<?php echo ruiyi_translate("Cancelar", "Cancel", "取消"); ?>',
    confirmButtonColor: '#f44336'
  }).then((result) => {
    if (result.isConfirmed) {
      // 注销当前会话后回到登录页
      Swal.fire({
        title: '<?php echo ruiyi_translate("Cambiando cuenta...", "Switching account...", "正在切换账户..."); ?>',
        text: '<?php echo ruiyi_translate("Por favor espere", "Please wait", "请稍候"); ?>',
        allowOutsideClick: false,
        didOpen: () => { Swal.showLoading(); }
      });

      // 🔥 使用 AJAX 调用登出，然后手动跳转
      fetch('<?php echo admin_url('admin-ajax.php'); ?>', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          action: 'ruiyi_logout_user',
          nonce: '<?php echo wp_create_nonce('ruiyi_logout_nonce'); ?>'
        })
      })
      .then(() => {
        window.location.href = '<?php echo home_url('/'); ?>';
      })
      .catch(error => {
        console.error('切换账户失败:', error);
        window.location.href = '<?php echo home_url('/'); ?>';
      });
    }
  });
}

// 关闭程序：关闭当前窗口/标签页，但不注销账户
function closeApplication() {
  Swal.fire({
    title: '<?php echo ruiyi_translate("¿Cerrar aplicación?", "Close application?", "关闭应用程序？"); ?>',
    text: '<?php echo ruiyi_translate("Se intentará cerrar esta página sin cerrar la sesión de la cuenta actual.", "This page will be closed without logging out the current account.", "将尝试直接关闭当前页面，不会退出当前账户。"); ?>',
    icon: 'question',
    showCancelButton: true,
    confirmButtonText: '<?php echo ruiyi_translate("Sí, cerrar", "Yes, close", "是的，关闭"); ?>',
    cancelButtonText: '<?php echo ruiyi_translate("Cancelar", "Cancel", "取消"); ?>',
    confirmButtonColor: '#f44336'
  }).then((result) => {
    if (result.isConfirmed) {
      const isStandalonePWA = window.matchMedia && window.matchMedia('(display-mode: standalone)').matches;
      const isLikelyScriptOpened = !!window.opener || window.history.length <= 1;

      function showManualClosePrompt() {
        const isMac = /Mac|iPhone|iPad|iPod/i.test(navigator.platform || navigator.userAgent);
        const shortcutText = isMac ? 'Cmd + W' : 'Ctrl + W';

        Swal.fire({
          icon: 'info',
          title: '<?php echo ruiyi_translate("Cierre manual requerido", "Manual close required", "需要手动关闭"); ?>',
          html: '<?php echo ruiyi_translate(
            "El navegador ha bloqueado el cierre automático de esta pestaña.<br>Use el atajo <strong>%shortcut%</strong> para cerrarla manualmente.",
            "The browser blocked automatic closing of this tab.<br>Use <strong>%shortcut%</strong> to close it manually.",
            "浏览器阻止了自动关闭当前标签页。<br>请使用快捷键 <strong>%shortcut%</strong> 手动关闭。"
          ); ?>'.replace('%shortcut%', shortcutText),
          confirmButtonText: '<?php echo ruiyi_translate("Entendido", "Understood", "了解"); ?>',
          confirmButtonColor: '#3085d6'
        });
      }

      function tryCloseWindow() {
        // 1. 直接关闭
        try { window.close(); } catch (e) {}

        // 2. 以 self 重开后关闭
        try {
          const selfWindow = window.open(window.location.href, '_self');
          if (selfWindow) {
            selfWindow.close();
          }
        } catch (e) {}

        // 3. 切到 about:blank 后再关闭
        try {
          window.open('about:blank', '_self');
          window.close();
        } catch (e) {}

        // 4. iframe 场景
        try {
          if (window.parent && window.parent !== window) {
            window.parent.close();
          }
        } catch (e) {}
      }

      // 尝试多种方式关闭窗口/标签页
      try {
        // 普通标签页大概率会被浏览器拦截，但 PWA 独立窗口 / 脚本打开窗口仍有机会成功
        tryCloseWindow();

        setTimeout(tryCloseWindow, 120);
        setTimeout(tryCloseWindow, 300);

        // 如果上述方法都失败，显示提示
        setTimeout(() => {
          if (!window.closed) {
            // PWA / 脚本打开窗口理论上应能关闭；普通浏览器标签页则明确告知是浏览器限制
            if (isStandalonePWA || isLikelyScriptOpened) {
              showManualClosePrompt();
              return;
            }

            showManualClosePrompt();
          }
        }, 1000);

      } catch (error) {
        console.error('无法关闭窗口:', error);
        showManualClosePrompt();
      }
    }
  });
}

// 打开后台管理面板函数

// 侧边栏折叠/展开功能（恢复原有逻辑）
function toggleSidebar() {
  const sidebar = document.getElementById('sidebar');
  const main = document.querySelector('main');

  if (!sidebar || !main) return;

  // 切换折叠状态
  const isCollapsed = sidebar.classList.contains('sidebar-collapsed');

  if (isCollapsed) {
    // 展开侧边栏
    sidebar.classList.remove('sidebar-collapsed');
    main.classList.remove('content-collapsed');
    localStorage.setItem('sidebar-collapsed', 'false');

    // 显示提示
    Toastify({
      text: '<?php echo ruiyi_translate("菜单已展开", "Menu expanded", "菜单已展开"); ?>',
      duration: 1000,
      gravity: "top",
      position: "left",
      style: { background: "#4caf50" }
    }).showToast();
  } else {
    // 折叠侧边栏
    sidebar.classList.add('sidebar-collapsed');
    main.classList.add('content-collapsed');
    localStorage.setItem('sidebar-collapsed', 'true');

    // 显示提示
    Toastify({
      text: '<?php echo ruiyi_translate("菜单已折叠", "Menu collapsed", "菜单已折叠"); ?>',
      duration: 1000,
      gravity: "top",
      position: "left",
      style: { background: "#2196f3" }
    }).showToast();
  }

  // 添加轻微延迟以确保动画完成
  setTimeout(() => {
    // 如果有需要重新计算的组件，在这里触发
    if (typeof renderizarMesas === 'function') {
      const mesasSection = document.getElementById('mesas');
      if (mesasSection && !mesasSection.classList.contains('hidden')) {
        renderizarMesas('sidebar-toggle');
      }
    }
  }, 350);
}

// 初始化侧边栏状态（🔥 默认展开）
function initSidebarState() {
  const sidebar = document.getElementById('sidebar');
  const main = document.querySelector('main');
  const sidebarToggle = document.getElementById('sidebar-toggle');

  // 🔥 默认展开状态
  if (sidebar && main) {
    sidebar.classList.remove('sidebar-collapsed');
    main.classList.remove('content-collapsed');
    // 不再强制设置 localStorage，让用户的偏好保持
  }

  // 绑定折叠按钮事件
  if (sidebarToggle) {
    sidebarToggle.addEventListener('click', toggleSidebar);
  }

  // 为桌面端添加快捷键支持 (可选)
  document.addEventListener('keydown', function(e) {
    // Ctrl + B 切换侧边栏
    if (e.ctrlKey && e.key === 'b') {
      e.preventDefault();
      toggleSidebar();
    }
  });
}

// 时钟功能已移除（首页删除后不再需要）

// Función para inicializar el sistema de atajos de teclado
function initializeKeyboardShortcuts() {
    // Obtener valores guardados en WordPress (desde PHP)
    const wpModifier = '<?php echo esc_js(get_option('drawer_shortcut_modifier', 'none')); ?>';
    const wpKey = '<?php echo esc_js(get_option('drawer_shortcut_key', 'F1')); ?>';

    // Cargar configuración de atajos desde localStorage o usar valores de WordPress
    let modifier = localStorage.getItem('drawer_shortcut_modifier');
    let key = localStorage.getItem('drawer_shortcut_key');

    // Si no hay valores en localStorage, usar los de WordPress
    if (!modifier) {
        modifier = wpModifier;
        localStorage.setItem('drawer_shortcut_modifier', modifier);
    }
    if (!key) {
        key = wpKey;
        localStorage.setItem('drawer_shortcut_key', key);
    }

    // Migración de configuración antigua: si la configuración es 'ctrl', cambiarla a 'none'
    if (modifier === 'ctrl') {
        modifier = 'none';
        localStorage.setItem('drawer_shortcut_modifier', modifier);
    }

    // Sincronizar valores en los selectores de configuración
    const modifierSelect = document.getElementById('drawer_shortcut_modifier');
    const keyInput = document.getElementById('drawer_shortcut_key');

    if (modifierSelect) {
        modifierSelect.value = modifier;
        // 根据修饰符显示/隐藏"+"符号
        updatePlusSignVisibility(modifier);
    }
    if (keyInput) {
        keyInput.value = key;
    }

    // 函数：根据修饰符显示/隐藏"+"符号
    function updatePlusSignVisibility(selectedModifier) {
        const plusSign = document.getElementById('shortcut-plus-sign');
        if (plusSign) {
            if (selectedModifier === 'none') {
                plusSign.style.display = 'none';
            } else {
                plusSign.style.display = 'inline';
            }
        }
    }

    // Función para verificar si se presionó el modificador correcto
    function checkModifier(event, modifier) {
        // Si el modificador es 'none', solo verificar que no se presione ningún modificador
        if (modifier === 'none') {
            return !event.ctrlKey && !event.altKey && !event.shiftKey && !event.metaKey;
        }

        switch(modifier) {
            case 'ctrl':
                return event.ctrlKey && !event.altKey && !event.shiftKey;
            case 'alt':
                return event.altKey && !event.ctrlKey && !event.shiftKey;
            case 'shift':
                return event.shiftKey && !event.ctrlKey && !event.altKey;
            case 'ctrl+alt':
                return event.ctrlKey && event.altKey && !event.shiftKey;
            case 'ctrl+shift':
                return event.ctrlKey && event.shiftKey && !event.altKey;
            default:
                return false;
        }
    }

    // Escuchar eventos de teclado globalmente
    document.addEventListener('keydown', async function(event) {
        // Ignorar si el usuario está escribiendo en un input o textarea
        if (event.target.tagName === 'INPUT' || event.target.tagName === 'TEXTAREA' || event.target.tagName === 'SELECT') {
            return;
        }

        // Verificar si se presionó el atajo para abrir el cajón
        let keyMatch = false;
        if (key === 'ENTER' && event.key === 'Enter') {
            keyMatch = true;
        } else if (/^F([1-9]|1[0-2])$/i.test(key) && event.key.toUpperCase() === key.toUpperCase()) {
            keyMatch = true;
        } else if (event.key.toUpperCase() === key.toUpperCase()) {
            keyMatch = true;
        }

        if (checkModifier(event, modifier) && keyMatch) {
            event.preventDefault();

            // 🔥 检查开钱箱按钮是否被锁定
            if (window.posSettings && window.posSettings.lockDrawerButton) {
                Toastify({
                    text: '🔒 <?php echo ruiyi_translate("El cajón está bloqueado", "Drawer is locked", "钱箱已被锁定"); ?>',
                    duration: 2000,
                    gravity: "top",
                    position: "center",
                    style: { background: "#f59e0b" }
                }).showToast();
                return;
            }

            // Verificar que estamos en la sección de cajero
            const cajeroSection = document.getElementById('cajero');
            if (cajeroSection && !cajeroSection.classList.contains('hidden')) {
                // Intentar abrir el cajón
                if (typeof window.abrirCajonDinero === 'function') {
                    try {
                        await window.abrirCajonDinero();
                        // 成功时不显示弹窗，静默执行
                    } catch (error) {
                        console.error('Error al abrir cajón con atajo:', error);
                    }
                }
            }
        }
    });

    // Configurar el botón de prueba en ajustes
    const testButton = document.getElementById('test-drawer-shortcut');
    if (testButton) {
        testButton.addEventListener('click', async function() {
            try {
                if (typeof window.abrirCajonDinero === 'function') {
                    await window.abrirCajonDinero();
                }
                // 成功时不显示弹窗，静默执行
            } catch (error) {
                // 🔥 使用用户友好的打印机配置提示
                if (typeof window.showPrinterConfigDialog === 'function') {
                    window.showPrinterConfigDialog();
                }
            }
        });
    }

    // Guardar cambios de configuración de atajos cuando se modifiquen
    // modifierSelect and keyInput variables are already declared above, reusing them

    if (modifierSelect) {
        modifierSelect.addEventListener('change', function() {
            localStorage.setItem('drawer_shortcut_modifier', this.value);
            // 更新"+"符号的显示
            updatePlusSignVisibility(this.value);
        });
    }

    if (keyInput) {
        // Hacer el campo de solo lectura y capturar teclas mediante keydown
        keyInput.addEventListener('click', function() {
            this.value = '';
            this.placeholder = '<?php echo ruiyi_translate("Presiona una tecla...", "Press a key...", "按下一个键..."); ?>';
        });

        keyInput.addEventListener('keydown', function(e) {
            e.preventDefault();

            let keyValue = '';

            // Manejar tecla Enter
            if (e.key === 'Enter') {
                keyValue = 'ENTER';
            }
            // Manejar teclas de función F1-F12
            else if (/^F([1-9]|1[0-2])$/i.test(e.key)) {
                keyValue = e.key.toUpperCase();
            }
            // Manejar letras y números
            else if (e.key.length === 1 && /[a-zA-Z0-9]/.test(e.key)) {
                keyValue = e.key.toUpperCase();
            }
            // Ignorar otras teclas especiales
            else {
                return;
            }

            this.value = keyValue;
            localStorage.setItem('drawer_shortcut_key', keyValue);
            this.blur(); // Quitar el foco del campo
        });

        // Restaurar placeholder cuando pierde el foco sin valor
        keyInput.addEventListener('blur', function() {
            if (!this.value) {
                this.placeholder = 'F1';
            }
        });
    }

    // Mostrar el atajo actual en la interfaz
    const openDrawerBtn = document.getElementById('open-drawer-btn');
    if (openDrawerBtn) {
        let shortcutText = '';
        let displayKey = key === 'ENTER' ? 'Enter' : key;
        if (modifier === 'none') {
            shortcutText = `(${displayKey})`;
        } else {
            shortcutText = `(${modifier.replace('+', '+')}+${displayKey})`;
        }
        const btnText = openDrawerBtn.querySelector('span');
        if (btnText && !btnText.textContent.includes('(')) {
            btnText.textContent += ' ' + shortcutText;
        }
    }
}

window.ruiyiBillingModulePassword = <?php echo wp_json_encode((string) get_option('pos_billing_module_password', '')); ?>;
window.ruiyiRequireBillingModulePassword = async function() {
    const configuredPassword = String(window.ruiyiBillingModulePassword || '').trim();
    if (!configuredPassword) {
        return true;
    }

    const result = await Swal.fire({
        title: <?php echo wp_json_encode(ruiyi_translate('Acceso a facturación', 'Billing access', '账单访问验证')); ?>,
        input: 'password',
        inputLabel: <?php echo wp_json_encode(ruiyi_translate('Ingrese la contraseña de facturación', 'Enter the billing password', '请输入账单密码')); ?>,
        inputPlaceholder: <?php echo wp_json_encode(ruiyi_translate('Contraseña', 'Password', '密码')); ?>,
        showCancelButton: true,
        confirmButtonText: <?php echo wp_json_encode(ruiyi_translate('Entrar', 'Enter', '进入')); ?>,
        cancelButtonText: <?php echo wp_json_encode(ruiyi_translate('Cancelar', 'Cancel', '取消')); ?>,
        confirmButtonColor: '#2563eb',
        allowOutsideClick: false,
        preConfirm: (value) => {
            if (String(value || '') !== configuredPassword) {
                Swal.showValidationMessage(<?php echo wp_json_encode(ruiyi_translate('Contraseña incorrecta', 'Incorrect password', '密码错误')); ?>);
                return false;
            }
            return true;
        }
    });

    return result.isConfirmed;
};

// Mostrar la sección de inicio por defecto y configurar navegación
document.addEventListener('DOMContentLoaded', function() {
    // 初始化侧边栏折叠功能
    initSidebarState();

    const hideTablesModule = !!(window.RUIYI_POS_CONFIG && window.RUIYI_POS_CONFIG.hideTablesModule);

    // 🔥 检查是否需要在刷新后跳转到桌位模块（来自AA分单保存）
    const redirectToTables = sessionStorage.getItem('redirectToTablesAfterReload');
    if (redirectToTables === 'true' && !hideTablesModule) {
        sessionStorage.removeItem('redirectToTablesAfterReload');
        console.log('[DOMContentLoaded] 检测到redirectToTablesAfterReload标记，将跳转到桌位模块');

        // 🔥🔥🔥 关键修复：设置标志，让cambiarSeccion跳过同步操作
        // AA分单结账后，服务器已正确更新订单，本地数据可能不同步，同步会导致数据错误
        window._skipSyncAfterSplitBilling = true;

        // 🔥 清空本地状态，避免旧数据干扰
        if (typeof cart !== 'undefined') {
            cart.length = 0;
        }
        const tableInput = document.getElementById('table-number');
        if (tableInput) {
            tableInput.value = '';
        }

        // 延迟执行以确保页面完全加载
        setTimeout(function() {
            if (typeof cambiarSeccion === 'function') {
                cambiarSeccion('mesas');
            }
        }, 100);
    } else if (redirectToTables === 'true') {
        sessionStorage.removeItem('redirectToTablesAfterReload');
    }

    // Ocultar todas las secciones
    const sections = document.querySelectorAll('main > section');
    sections.forEach(section => section.classList.add('hidden'));

    // Inmediatamente inicializar la UI de atajos de teclado
    setTimeout(() => {
        const modifierSelect = document.getElementById('drawer_shortcut_modifier');
        const plusSign = document.getElementById('shortcut-plus-sign');

        if (modifierSelect && plusSign) {
            // Forzar valor por defecto si aún muestra 'ctrl'
            if (modifierSelect.value === 'ctrl' || !modifierSelect.value) {
                modifierSelect.value = 'none';
            }

            // Inmediatamente ocultar el "+" si es 'none'
            if (modifierSelect.value === 'none') {
                plusSign.style.display = 'none';
            } else {
                plusSign.style.display = 'inline';
            }
        }
    }, 100);

    // Inicializar sistema de atajos de teclado
    initializeKeyboardShortcuts();

    // 初始化订单类型按钮状态
    setTimeout(() => {
      if (typeof updateAllButtonStates === 'function') {
        updateAllButtonStates();
      }
    }, 1000);
    
    // Check if user is shop manager or administrator (passed from PHP)
    const isShopManager = <?php echo $is_shop_manager ? 'true' : 'false'; ?>;
    const isAdministrator = <?php echo $is_administrator ? 'true' : 'false'; ?>;
    
    // 🔥 Determine default section from config
    let defaultSection = (window.RUIYI_POS_CONFIG && window.RUIYI_POS_CONFIG.defaultModule) || 'cajero';
    if (hideTablesModule && defaultSection === 'mesas') {
        defaultSection = 'cajero';
    }
    let defaultHash = '#' + defaultSection;

    // Show the appropriate default section
    const defaultSectionElement = document.getElementById(defaultSection);
    if (defaultSectionElement) {
        defaultSectionElement.classList.remove('hidden');

        // Si la sección por defecto es mesas, renderizar las mesas
        if (defaultSection === 'mesas' && typeof renderizarMesas === 'function') {
            setTimeout(() => {
                renderizarMesas('initial-load');
            }, 500); // Pequeño delay para asegurar que todo esté cargado
        }
    }

    // Configurar la navegación entre secciones
    const menuLinks = document.querySelectorAll('.menu-link');
    menuLinks.forEach(link => {
        // Desactivar todos los enlaces primero
        link.classList.remove('bg-red-600', 'text-white');

        // Activar el enlace por defecto según el rol
        if (link.getAttribute('href') === defaultHash) {
            link.classList.add('bg-red-600', 'text-white');
        }

        // Agregar evento de clic para cambiar entre secciones
        link.addEventListener('click', async function(e) {
            if (this.getAttribute('href').startsWith('#')) {
                e.preventDefault();
                const sectionId = this.getAttribute('href').substring(1);

                if (sectionId === 'cierre-diario') {
                    const isOnline = navigator.onLine && window.RUIYI_POS?.isOnline !== false;
                    if (!isOnline) {
                        Swal.fire({
                            icon: 'info',
                            title: <?php echo wp_json_encode(ruiyi_translate('Sin conexión', 'Offline', '当前离线')); ?>,
                            html: `
                              <div class="text-center">
                                <i class="fas fa-wifi-slash text-5xl text-gray-400 mb-4"></i>
                                <p class="text-gray-600 mb-2"><?php echo ruiyi_translate("Esta función requiere conexión a Internet", "This feature requires Internet connection", "该功能需要网络连接"); ?></p>
                                <p class="text-gray-500 text-sm"><?php echo ruiyi_translate("Por favor, conéctese a Internet para acceder al módulo de facturación", "Please connect to the Internet to access the billing module", "请连接网络后访问账单模块"); ?></p>
                              </div>
                            `,
                            confirmButtonText: <?php echo wp_json_encode(ruiyi_translate('Entendido', 'Got it', '知道了')); ?>,
                            confirmButtonColor: '#3b82f6'
                        });
                        return;
                    }

                    if (typeof window.ruiyiRequireBillingModulePassword === 'function') {
                        const canAccessBilling = await window.ruiyiRequireBillingModulePassword();
                        if (!canAccessBilling) {
                            return;
                        }
                    }
                }

                // 🔥 在切换前自动保存未保存的桌位订单
                // 🔥🔥🔥 【2026-01-20 关键修复】autoSaveTableOrder 内部已经处理了 updateLockedItemsToServer
                // 不要在这里再次调用 updateLockedItemsToServer，否则会导致竞态条件：
                // 1. autoSaveTableOrder 启动 syncTableOrderToServer 添加新 Varios
                // 2. autoSaveTableOrder 返回（但异步操作还在进行中）
                // 3. 这里的 updateLockedItemsToServer 被调用，发送不包含新 Varios 的锁定商品列表
                // 4. 服务器收到 update_order_items，删除了"多余"的新 Varios
                if (typeof window.autoSaveTableOrder === 'function') {
                    await window.autoSaveTableOrder();
                }

                // Desactivar todos los enlaces
                menuLinks.forEach(l => {
                    l.classList.remove('bg-red-600', 'text-white');
                });

                // Activar el enlace actual
                this.classList.add('bg-red-600', 'text-white');

                // 🔥 修改：点击收银图标时的智能处理
                if (sectionId === 'cajero') {
                    // 🔥 确保工具箱是关闭状态
                    const cartActionsContainer = document.querySelector('.cart-actions-fixed');
                    if (cartActionsContainer && window.Alpine) {
                        const alpineData = Alpine.$data(cartActionsContainer);
                        if (alpineData) {
                            alpineData.toolboxOpen = false;
                        }
                    }

                    // 检查是否在查看模式
                    const viewMode = sessionStorage.getItem('tableViewMode');
                    const isViewMode = viewMode ? JSON.parse(viewMode) : null;

                    if (isViewMode && isViewMode.mode === 'view') {
                        // ========== 查看模式下点击收银图标 ==========

                        // 1. 清除查看模式标记
                        sessionStorage.removeItem('tableViewMode');
                        sessionStorage.removeItem('tableOrderData');

                        // 2. 清空购物车
                        if (typeof cart !== 'undefined') {
                            cart = [];
                            if (typeof renderCart === 'function') {
                                renderCart();
                            }
                        }

                        // 3. 清空桌位号
                        const tableNumberInput = document.getElementById('table-number');
                        if (tableNumberInput) {
                            tableNumberInput.value = '';
                        }

                        // 4. 强制设置为外卖模式
                        sessionStorage.setItem('tipoPedidoSeleccionado', 'llevar');

                        // 5. 立即更新UI（减少延迟：150ms → 0ms）
                        const takeawayBtn = document.querySelector('[data-type="llevar"]');
                        const dineInBtn = document.querySelector('[data-type="servir"]');

                        if (takeawayBtn && dineInBtn) {
                            // 激活外卖按钮
