                        if (typeof loadOrderHistory === 'function') {
                            loadOrderHistory(); // 不传 forceRefresh，已加载过则使用缓存
                        }

                        // 离线待同步订单 + PWA 自动同步 — 仅首次进入时执行
                        if (!window._historyOfflineLoaded) {
                            window._historyOfflineLoaded = true;
                            if (typeof loadOfflinePendingOrdersIntoHistory === 'function') {
                                try {
                                    loadOfflinePendingOrdersIntoHistory();
                                } catch (e) {
                                    console.warn('[Historial] Failed to load offline pending orders:', e);
                                }
                            }
                            if (navigator.onLine && window.RUIYI_POS?.isOnline !== false) {
                                setTimeout(() => {
                                    if (window.posSync && typeof window.posSync.sync === 'function') {
                                        window.posSync.sync().then(() => {
                                            if (typeof loadOfflinePendingOrdersIntoHistory === 'function') {
                                                setTimeout(() => loadOfflinePendingOrdersIntoHistory(), 1000);
                                            }
                                        }).catch(error => {
                                            console.error('[Historial] Auto-sync failed:', error);
                                        });
                                    }
                                }, 2000);
                            }
                        }
                    }

                    if (sectionId === 'cierre-diario' && String(window.ruiyiBillingModulePassword || '').trim()) {
                        setTimeout(() => {
                            if (typeof loadDailySummaryData === 'function') {
                                loadDailySummaryData();
                            }
                        }, 300);
                    }
                }
            }
        });
    });
    
