});

// ========== 日历日期选择器组件 ==========

window.HistoryCalendar = (() => {
  let currentYear, currentMonth;
  let selectedStart = null; // Date | null
  let selectedEnd = null;   // Date | null
  let isOpen = false;
  // 保存打开日历前的选择状态（用于取消时恢复）
  let savedStart = null;
  let savedEnd = null;

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  function init() {
    const now = new Date();
    currentYear = now.getFullYear();
    currentMonth = now.getMonth();

    // 🔥 默认选中今天日期，只加载当天订单（提升加载速度）
    selectedStart = new Date(today);
    selectedEnd = new Date(today);
    updateTriggerLabel();

    // 阻止日历面板内部点击冒泡（防止 selectDay 重绘 innerHTML 后 DOM 脱离导致误关闭）
    const dropdown = document.getElementById('history-calendar-dropdown');
    if (dropdown) {
      dropdown.addEventListener('click', (e) => e.stopPropagation());
    }
    // 点击日历外部关闭
    document.addEventListener('click', (e) => {
      const trigger = document.getElementById('history-calendar-trigger');
      if (isOpen && trigger && !trigger.contains(e.target)) {
        doCancel();
      }
    });
  }

  function formatDate(d) {
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  }

  function formatShort(d) {
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${m}-${day}`;
  }

  function isSameDay(a, b) {
    return a && b && a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
  }

  function render() {
    const grid = document.getElementById('history-calendar-grid');
    const title = document.getElementById('history-calendar-title');
    if (!grid || !title) return;

    title.textContent = `${currentYear}年 ${currentMonth + 1}月`;

    // 计算当月第一天是周几（0=周日，调整为周一起始）
    const firstDay = new Date(currentYear, currentMonth, 1);
    let startDow = firstDay.getDay(); // 0=Sun
    startDow = startDow === 0 ? 6 : startDow - 1; // 转为 Mon=0

    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

    let html = '';

    // 上月空白填充
    for (let i = 0; i < startDow; i++) {
      html += '<div class="h-9"></div>';
    }

    for (let day = 1; day <= daysInMonth; day++) {
      const d = new Date(currentYear, currentMonth, day);
      d.setHours(0, 0, 0, 0);

      const isToday = isSameDay(d, today);
      const isStart = isSameDay(d, selectedStart);
      const isEnd = isSameDay(d, selectedEnd);
      const isSelected = isStart || isEnd;

      let inRange = false;
      if (selectedStart && selectedEnd) {
        inRange = d > selectedStart && d < selectedEnd;
      }

      // 构建样式
      let cellClasses = 'h-9 flex items-center justify-center text-sm cursor-pointer transition-colors relative';
      let textClasses = 'w-8 h-8 flex items-center justify-center rounded-full transition-colors';

      if (isSelected) {
        textClasses += ' bg-blue-600 text-white font-semibold';
      } else if (inRange) {
        cellClasses += ' bg-blue-100 dark:bg-blue-900/30';
        textClasses += ' text-gray-700 dark:text-gray-200';
      } else {
        textClasses += ' hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-200';
      }

      if (isToday && !isSelected) {
        textClasses += ' font-bold !text-blue-600 dark:!text-blue-400 underline';
      }

      // 范围背景条（连接效果）
      let rangeBg = '';
      if (selectedStart && selectedEnd) {
        if (isStart && !isSameDay(selectedStart, selectedEnd)) {
          rangeBg = '<div class="absolute inset-y-0 left-1/2 right-0 bg-blue-100 dark:bg-blue-900/30"></div>';
        } else if (isEnd && !isSameDay(selectedStart, selectedEnd)) {
          rangeBg = '<div class="absolute inset-y-0 left-0 right-1/2 bg-blue-100 dark:bg-blue-900/30"></div>';
        }
      }

      html += `<div class="${cellClasses}" onclick="HistoryCalendar.selectDay(${day})">${rangeBg}<span class="${textClasses} relative z-10">${day}</span></div>`;
    }

    grid.innerHTML = html;
  }

  function updateTriggerLabel() {
    const label = document.getElementById('history-calendar-label');
    const clearBtn = document.getElementById('history-calendar-clear-btn');
    if (!label) return;

    if (selectedStart && selectedEnd && !isSameDay(selectedStart, selectedEnd)) {
      label.textContent = `${formatShort(selectedStart)} ~ ${formatShort(selectedEnd)}`;
      if (clearBtn) clearBtn.classList.remove('hidden');
    } else if (selectedStart) {
      label.textContent = formatShort(selectedStart);
      if (clearBtn) clearBtn.classList.remove('hidden');
    } else {
      label.textContent = '<?php echo ruiyi_translate("Seleccionar fecha", "Select date", "选择日期"); ?>';
      if (clearBtn) clearBtn.classList.add('hidden');
    }
  }

  function open() {
    const dropdown = document.getElementById('history-calendar-dropdown');
    if (!dropdown) return;
    // 保存当前状态（用于取消恢复）
    savedStart = selectedStart;
    savedEnd = selectedEnd;
    dropdown.classList.remove('hidden');
    isOpen = true;
    render();
  }

  function close() {
    const dropdown = document.getElementById('history-calendar-dropdown');
    if (dropdown) dropdown.classList.add('hidden');
    isOpen = false;
  }

  function doCancel() {
    selectedStart = savedStart;
    selectedEnd = savedEnd;
    close();
  }

  // 初始化
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

  return {
    toggle() {
      if (isOpen) { close(); } else { open(); }
    },

    selectDay(day) {
      const d = new Date(currentYear, currentMonth, day);
      d.setHours(0, 0, 0, 0);

      if (!selectedStart || (selectedStart && selectedEnd)) {
        // 第一次点击 或 已有完整范围时重新选择
        selectedStart = d;
        selectedEnd = null;
      } else {
        // 第二次点击
        if (d >= selectedStart) {
          selectedEnd = d;
        } else {
          selectedEnd = selectedStart;
          selectedStart = d;
        }
      }
      render();
    },

    prevMonth() {
      currentMonth--;
      if (currentMonth < 0) { currentMonth = 11; currentYear--; }
      render();
    },

    nextMonth() {
      currentMonth++;
      if (currentMonth > 11) { currentMonth = 0; currentYear++; }
      render();
    },

    goToday() {
      const now = new Date();
      currentYear = now.getFullYear();
      currentMonth = now.getMonth();
      const todayCopy = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      todayCopy.setHours(0, 0, 0, 0);
      selectedStart = todayCopy;
      selectedEnd = todayCopy;
      render();
    },

    apply() {
      // 单击了一天但未选第二天 → 视为单日选择
      if (selectedStart && !selectedEnd) {
        selectedEnd = selectedStart;
      }
      updateTriggerLabel();
      close();
      loadOrderHistory(true);
    },

    cancel() {
      doCancel();
    },

    clear() {
      selectedStart = null;
      selectedEnd = null;
      const phoneInput = document.getElementById('history-phone-filter');
      if (phoneInput) phoneInput.value = '';
      updateTriggerLabel();
      close();
      loadOrderHistory(true);
    },

    getDateRange() {
      let dateFrom = '';
      let dateTo = '';
      if (selectedStart) {
        dateFrom = formatDate(selectedStart);
      }
      if (selectedEnd) {
        dateTo = formatDate(selectedEnd);
      } else if (selectedStart) {
        dateTo = dateFrom; // 单日
      }
      return { dateFrom, dateTo };
    }
  };
})();

// ========== 分页管理器 ==========

window.OrderPagination = (() => {
  const PAGE_SIZE = 30;
  let allOrders = [];
  let currentPage = 1;
  let totalPages = 1;

  function update() {
    const paginationEl = document.getElementById('order-history-pagination');
    const pageInfo = document.getElementById('order-history-page-info');
    const pageNum = document.getElementById('order-history-page-num');
    const prevBtn = document.getElementById('order-history-prev-btn');
    const nextBtn = document.getElementById('order-history-next-btn');

    if (totalPages <= 1) {
      if (paginationEl) paginationEl.classList.add('hidden');
      return;
    }

    if (paginationEl) paginationEl.classList.remove('hidden');
    if (pageInfo) {
      const start = (currentPage - 1) * PAGE_SIZE + 1;
      const end = Math.min(currentPage * PAGE_SIZE, allOrders.length);
      pageInfo.textContent = `<?php echo ruiyi_translate('Mostrando', 'Showing', '显示'); ?> ${start}-${end} / ${allOrders.length} <?php echo ruiyi_translate('pedidos', 'orders', '条订单'); ?>`;
    }
    if (pageNum) pageNum.textContent = `${currentPage} / ${totalPages}`;
    if (prevBtn) prevBtn.disabled = currentPage <= 1;
    if (nextBtn) nextBtn.disabled = currentPage >= totalPages;
  }

  function showPage() {
    const start = (currentPage - 1) * PAGE_SIZE;
    const pageOrders = allOrders.slice(start, start + PAGE_SIZE);
    renderOrderHistory(pageOrders);
    update();
    // 滚动回列表顶部
    const listContainer = document.getElementById('order-history-list');
    if (listContainer) listContainer.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  return {
    setOrders(orders) {
      allOrders = orders || [];
      totalPages = Math.max(1, Math.ceil(allOrders.length / PAGE_SIZE));
      currentPage = 1;
      showPage();
    },

    prev() {
      if (currentPage > 1) { currentPage--; showPage(); }
    },

    next() {
      if (currentPage < totalPages) { currentPage++; showPage(); }
    },

    hide() {
      const paginationEl = document.getElementById('order-history-pagination');
      if (paginationEl) paginationEl.classList.add('hidden');
    }
  };
})();

// ========== 历史订单模块功能 ==========

// 🔥 全局订单数据缓存（用于离线开票）
window._historyOrdersCache = {};
// 🔥 历史订单已加载标志 + 缓存的订单列表（避免重复AJAX请求）
window._historyOrdersLoaded = false;
window._historyOrdersListCache = null;
window._historyOrdersDateKey = ''; // 记录缓存对应的日期筛选条件

// 加载历史订单（forceRefresh=true 时强制从服务器重新加载）
function loadOrderHistory(forceRefresh) {
  const orderList = document.getElementById('order-history-list');
  if (!orderList) return;

  // 获取当前日期筛选条件
  const { dateFrom, dateTo } = HistoryCalendar.getDateRange();
  const phoneFilter = (document.getElementById('history-phone-filter')?.value || '').trim();
  const paymentFilter = (document.getElementById('history-payment-filter')?.value || '').trim();
  const currentDateKey = dateFrom + '|' + dateTo + '|' + phoneFilter + '|' + paymentFilter;

  // 🔥 如果已加载且筛选条件未变，直接使用缓存（除非强制刷新）
  if (!forceRefresh && window._historyOrdersLoaded && window._historyOrdersListCache && currentDateKey === window._historyOrdersDateKey) {
    console.log('[历史订单] 使用缓存数据，跳过AJAX请求');
    OrderPagination.setOrders(window._historyOrdersListCache);
    return;
  }

  // 隐藏分页控件
  OrderPagination.hide();

  // 显示加载中
  orderList.innerHTML = `
    <div class="text-center py-12">
      <i class="fas fa-spinner fa-spin text-4xl text-blue-600 mb-3"></i>
      <p class="text-gray-600"><?php echo ruiyi_translate('Cargando pedidos...', 'Loading orders...', '加载订单中...'); ?></p>
    </div>
  `;

  // 同步到隐藏 input（供 printAccountStatement 等函数使用）
  const dateFromInput = document.getElementById('history-date-from');
  const dateToInput = document.getElementById('history-date-to');
  if (dateFromInput) dateFromInput.value = dateFrom;
  if (dateToInput) dateToInput.value = dateTo;

  // 只显示已完成状态的订单
  const status = 'completed';

  console.log('[历史订单] 从服务器加载...', forceRefresh ? '(强制刷新)' : '(首次加载)');

  // 发送AJAX请求
  fetch(ajaxUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      action: 'ruiyi_pos_get_order_history',
      date_from: dateFrom,
      date_to: dateTo,
      phone: phoneFilter,
      payment_method: paymentFilter,
      status: status,
      nonce: ajaxNonce
    })
  })
  .then(response => response.json())
  .then(data => {
    if (data.success && data.data.orders && data.data.orders.length > 0) {
      // 缓存全部订单数据供开票功能使用
      data.data.orders.forEach(order => {
        window._historyOrdersCache[order.id] = order;
      });
      // 🔥 缓存订单列表 + 标记已加载
      window._historyOrdersListCache = data.data.orders;
      window._historyOrdersDateKey = currentDateKey;
      window._historyOrdersLoaded = true;
      // 通过分页管理器显示（每页30条）
      OrderPagination.setOrders(data.data.orders);
    } else {
      // 🔥 空结果也标记为已加载（避免重复请求空数据）
      window._historyOrdersListCache = [];
      window._historyOrdersDateKey = currentDateKey;
      window._historyOrdersLoaded = true;
      orderList.innerHTML = `
        <div class="text-center py-12 text-gray-500">
          <i class="fas fa-inbox text-5xl mb-3 opacity-50"></i>
          <p><?php echo ruiyi_translate('No se encontraron pedidos', 'No orders found', '未找到订单'); ?></p>
        </div>
      `;
    }
  })
  .catch(error => {
    console.error('Error loading order history:', error);
    orderList.innerHTML = `
      <div class="text-center py-12 text-red-500">
        <i class="fas fa-exclamation-triangle text-5xl mb-3"></i>
        <p><?php echo ruiyi_translate('Error al cargar pedidos', 'Error loading orders', '加载订单失败'); ?></p>
      </div>
    `;
  });
}

// 渲染历史订单列表（接收当前页的订单数据）
function renderOrderHistory(orders) {
  const orderList = document.getElementById('order-history-list');
  if (!orderList || !orders || orders.length === 0) {
    orderList.innerHTML = `
      <div class="text-center py-12 text-gray-500">
        <i class="fas fa-inbox text-5xl mb-3 opacity-50"></i>
        <p><?php echo ruiyi_translate('No hay pedidos para mostrar', 'No orders to display', '暂无订单'); ?></p>
      </div>
    `;
    return;
  }

  const _T = (window.RUIYI_POS_CONFIG || {}).translations || {};
  const statusNames = {
    'completed': _T.statusCompleted || order?.status_name || '已完成',
    'processing': _T.statusProcessing || order?.status_name || '处理中',
    'pending': _T.statusPending || order?.status_name || '待处理',
    'cancelled': _T.statusCancelled || order?.status_name || '已取消',
    'refunded': _T.statusRefunded || order?.status_name || '已退款'
  };

  orderList.innerHTML = orders.map((order, index) => {
    const statusColors = {
      'completed': 'bg-green-100 text-green-800 border-green-300',
      'processing': 'bg-blue-100 text-blue-800 border-blue-300',
      'pending': 'bg-yellow-100 text-yellow-800 border-yellow-300',
      'cancelled': 'bg-red-100 text-red-800 border-red-300'
    };

    const statusColor = statusColors[order.status] || 'bg-gray-100 text-gray-800 border-gray-300';

    // 🔥 构建发票号码显示（如果有）
    const invoiceLabel = order.invoice_label
      ? ruiyiFormatReceiptInvoiceNumber(order.invoice_label, order.id, order.date)
      : '';
    const invoiceHtml = invoiceLabel
      ? `<span class="px-2 py-1 bg-blue-50 text-blue-700 rounded text-xs font-mono border border-blue-200">
           <i class="fas fa-file-invoice mr-1"></i>${invoiceLabel}
         </span>`
      : '';

    // 🔥 构建支付方式标签
    const paymentMethod = (order.payment_method || '').toLowerCase();
    let paymentBadgeHtml = '';
    if (paymentMethod) {
      let paymentIcon = 'fa-money-bill-wave';
      let paymentColor = 'bg-green-50 text-green-700 border-green-200';
      let paymentText = '';

      if (paymentMethod === 'cash' || paymentMethod === 'efectivo' || paymentMethod === 'cod') {
        paymentIcon = 'fa-money-bill-wave';
        paymentColor = 'bg-green-50 text-green-700 border-green-200';
        paymentText = '<?php echo ruiyi_translate("Efectivo", "Cash", "现金"); ?>';
      } else if (paymentMethod === 'card' || paymentMethod === 'tarjeta' || paymentMethod === 'bacs') {
        paymentIcon = 'fa-credit-card';
        paymentColor = 'bg-purple-50 text-purple-700 border-purple-200';
        paymentText = '<?php echo ruiyi_translate("Tarjeta", "Card", "刷卡"); ?>';
      } else if (paymentMethod === 'mixed' || paymentMethod === 'mixto') {
        paymentIcon = 'fa-coins';
        paymentColor = 'bg-amber-50 text-amber-700 border-amber-200';
        paymentText = '<?php echo ruiyi_translate("Mixto", "Mixed", "现金+刷卡"); ?>';
      } else if (paymentMethod === 'bizum') {
        paymentIcon = 'fa-exchange-alt';
        paymentColor = 'bg-teal-50 text-teal-700 border-teal-200';
        paymentText = '<?php echo ruiyi_translate("Bizum", "Bizum", "转账/bizum"); ?>';
      } else if (paymentMethod === 'cheque') {
        paymentIcon = 'fa-money-check-alt';
        paymentColor = 'bg-sky-50 text-sky-700 border-sky-200';
        paymentText = '<?php echo ruiyi_translate("Cheque", "Cheque", "支票"); ?>';
      } else if (paymentMethod === 'company_ticket') {
        paymentIcon = 'fa-ticket-alt';
        paymentColor = 'bg-indigo-50 text-indigo-700 border-indigo-200';
        paymentText = '<?php echo ruiyi_translate("Ticket Empresa", "Company Ticket", "公司钱票"); ?>';
      } else {
        // 其他支付方式
        paymentText = paymentMethod;
      }

      if (paymentText) {
        paymentBadgeHtml = `<span class="px-2 py-1 ${paymentColor} rounded text-xs font-medium border">
           <i class="fas ${paymentIcon} mr-1"></i>${paymentText}
         </span>`;
      }
    }

    // 🔥 构建桌位标签
    // 🔥🔥🔥 【2026-03-30 修复】始终用 tableCategoryMappings 将全局编号映射为自定义显示名称
    // 后端可能返回 table_display_name="餐桌 4"（回退值），前端必须再次用映射覆盖
    let tableName = '';
    const _htRaw = order.table_display_name || order.table_number || '';
    if (_htRaw && window.tableCategoryMappings) {
      const _htNum = parseInt(String(_htRaw).replace(/^(餐桌|Mesa|Table)\s*/i, ''));
      if (!isNaN(_htNum)) {
        const _htMappings = Array.isArray(window.tableCategoryMappings)
          ? window.tableCategoryMappings : Object.values(window.tableCategoryMappings);
        const _htMap = _htMappings.find(m => m && parseInt(m.global_table_number) === _htNum);
        if (_htMap) {
          tableName = _htMap.category_display_name || (_htMap.category_name ? _htMap.category_name + ' ' + _htMap.local_table_number : '') || _htMap.display_name || '';
        }
      }
    }
    if (!tableName) tableName = _htRaw;
    let tableBadgeHtml = '';
    if (tableName) {
      tableBadgeHtml = `<span class="px-2 py-1 bg-orange-50 text-orange-700 rounded text-xs font-medium border border-orange-200">
           <i class="fas fa-chair mr-1"></i>${tableName}
         </span>`;
    }

    // 构建商品列表HTML
    const itemsHtml = order.items && order.items.length > 0
      ? order.items.map(item => `
          <div class="flex justify-between items-center py-2 px-3 bg-gray-50 dark:bg-gray-700 rounded">
            <span class="text-sm text-gray-700 dark:text-gray-300">${item.name} x${item.quantity}</span>
            <span class="text-sm font-semibold text-gray-900 dark:text-white">€${item.total}</span>
          </div>
        `).join('')
      : '<p class="text-sm text-gray-500 text-center py-2"><?php echo ruiyi_translate("Sin productos", "No products", "无商品"); ?></p>';

    return `
      <div class="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
        <!-- 订单头部 - 可点击展开 -->
        <div class="p-4 cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-750 transition-colors" onclick="toggleOrderDetails(${index})">
          <div class="flex justify-between items-center">
            <!-- 订单信息 -->
            <div class="flex items-center gap-3 flex-1 flex-wrap">
              <span class="px-3 py-1 ${statusColor} rounded-full text-xs font-medium border">
                ${statusNames[order.status] || order.status_name}
              </span>
              ${invoiceHtml}
              ${paymentBadgeHtml}
              ${tableBadgeHtml}
              <div class="flex items-center text-sm text-gray-600 dark:text-gray-400">
                <i class="fas fa-calendar-alt mr-2 text-gray-400"></i>
                ${order.date} ${order.time}
              </div>
            </div>

            <!-- 金额和操作按钮 -->
            <div class="flex items-center gap-3">
              <div class="text-2xl font-bold text-green-600">
                €${order.total}
              </div>
              <!-- 🔥 查看订单按钮 (新增) -->
              <button onclick="event.stopPropagation(); viewOrderDetails(${order.id})"
                      class="px-3 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-medium transition-colors flex items-center gap-1"
                      title="<?php echo ruiyi_translate('Ver detalles del pedido', 'View order details', '查看订单详情'); ?>">
                <i class="fas fa-eye"></i>
                <span><?php echo ruiyi_translate('Ver', 'View', '查看'); ?></span>
              </button>
              <!-- 🔥 打印按钮 -->
              <button onclick="event.stopPropagation(); printHistoryOrder(${order.id})"
                      class="px-3 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg text-sm font-medium transition-colors flex items-center gap-1"
                      title="<?php echo ruiyi_translate('Imprimir recibo', 'Print receipt', '打印小票'); ?>">
                <i class="fas fa-print"></i>
                <span><?php echo ruiyi_translate('Imprimir', 'Print', '打印'); ?></span>
              </button>
              <!-- 🔥 开票按钮 - 从缓存获取订单数据支持离线打印 -->
              <button onclick="event.stopPropagation(); openInvoiceModalWithCache(${order.id}, '${order.total}')"
                      class="px-3 py-2 bg-orange-500 hover:bg-orange-600 text-white rounded-lg text-sm font-medium transition-colors flex items-center gap-1"
                      title="<?php echo ruiyi_translate('Emitir factura', 'Issue invoice', '开票'); ?>">
                <i class="fas fa-file-invoice"></i>
                <span><?php echo ruiyi_translate('Factura', 'Invoice', '开票'); ?></span>
              </button>
              <!-- 🔥 PDF发票下载按钮 -->
              <button onclick="event.stopPropagation(); openPdfInvoiceModal(${order.id}, '${order.total}')"
                      class="px-3 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg text-sm font-medium transition-colors flex items-center gap-1"
                      title="<?php echo ruiyi_translate('Descargar factura PDF', 'Download PDF invoice', '下载PDF发票'); ?>">
                <i class="fas fa-file-pdf"></i>
                <span>PDF</span>
              </button>
              <!-- 🔥 作废按钮 - 仅对已完成订单显示，并根据设置决定是否启用 -->
              ${(order.status === 'completed' && window.voidOrderEnabled) ? `
              <button onclick="event.stopPropagation(); voidOrder(${order.id}, '${order.total}', '${order.payment_method || ''}')"
                      class="px-3 py-2 bg-red-500 hover:bg-red-600 text-white rounded-lg text-sm font-medium transition-colors flex items-center gap-1"
                      title="<?php echo ruiyi_translate('Anular pedido', 'Void order', '作废订单'); ?>">
                <i class="fas fa-ban"></i>
                <span><?php echo ruiyi_translate('Anular', 'Void', '作废'); ?></span>
              </button>
              ` : ''}
              <!-- 展开/收起图标 -->
              <i id="order-chevron-${index}" class="fas fa-chevron-down text-gray-400 transition-transform duration-200"></i>
            </div>
          </div>
        </div>

        <!-- 订单详情 - 默认隐藏 -->
        <div id="order-details-${index}" class="hidden border-t border-gray-200 dark:border-gray-600">
          <div class="p-4 bg-gray-50 dark:bg-gray-750">
            <!-- 商品列表 -->
            <div class="mb-3">
              <h4 class="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2 flex items-center">
                <i class="fas fa-list mr-2 text-blue-600"></i>
                <?php echo ruiyi_translate('Productos', 'Products', '商品明细'); ?>
              </h4>
              <div class="space-y-1">
                ${itemsHtml}
              </div>
            </div>

            <!-- 订单信息 - 支付方式和桌号已移除 -->
            <!-- 已按用户要求隐藏支付方式和桌号信息 -->
          </div>
        </div>
      </div>
    `;
  }).join('');
}

// 切换订单详情显示
function toggleOrderDetails(index) {
  const detailsDiv = document.getElementById(`order-details-${index}`);
  const chevronIcon = document.getElementById(`order-chevron-${index}`);

  if (!detailsDiv || !chevronIcon) return;

  // 切换显示/隐藏
  if (detailsDiv.classList.contains('hidden')) {
    detailsDiv.classList.remove('hidden');
    chevronIcon.classList.add('rotate-180');
  } else {
    detailsDiv.classList.add('hidden');
    chevronIcon.classList.remove('rotate-180');
  }
}

// 筛选历史订单
function filterOrderHistory() {
  loadOrderHistory(true);
}

// 🔥🔥🔥 打印对账单功能 - 批量打印指定日期范围内的所有订单摘要
function printAccountStatement() {
  // 获取日期范围
  const today = new Date().toISOString().split('T')[0];
  const dateFrom = document.getElementById('history-date-from')?.value || today;
  const dateTo = document.getElementById('history-date-to')?.value || today;

  // 显示加载中
  Swal.fire({
    title: '<?php echo ruiyi_translate("Cargando pedidos...", "Loading orders...", "加载订单中..."); ?>',
    allowOutsideClick: false,
    didOpen: () => {
      Swal.showLoading();
    }
  });

  // 获取订单数据
  fetch(ajaxUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      action: 'ruiyi_pos_get_order_history',
      date_from: dateFrom,
      date_to: dateTo,
      status: 'completed',
      nonce: ajaxNonce
    })
  })
  .then(response => response.json())
  .then(data => {
    Swal.close();

    if (!data.success || !data.data.orders || data.data.orders.length === 0) {
      Swal.fire({
        icon: 'info',
        title: '<?php echo ruiyi_translate("Sin pedidos", "No orders", "无订单"); ?>',
        text: '<?php echo ruiyi_translate("No hay pedidos en el rango de fechas seleccionado", "No orders in the selected date range", "所选日期范围内没有订单"); ?>'
      });
      return;
    }

    // 生成并打印对账单
    generateAndPrintStatement(data.data.orders, dateFrom, dateTo);
  })
  .catch(error => {
    Swal.close();
    console.error('Error loading orders for statement:', error);
    Swal.fire({
      icon: 'error',
      title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
      text: '<?php echo ruiyi_translate("Error al cargar pedidos", "Error loading orders", "加载订单失败"); ?>'
    });
  });
}

// 🔥 生成并打印对账单（使用 CLODOP 直接打印）
function generateAndPrintStatement(orders, dateFrom, dateTo) {
  const config = window.RUIYI_POS_CONFIG || {};
  const storeInfo = config.storeInfo || {};

  // 获取支付方式显示文本（西班牙语）
  function getPaymentMethodText(method) {
    const m = (method || '').toLowerCase();
    if (m === 'cash' || m === 'efectivo' || m === 'cod') {
      return 'Efectivo';
    } else if (m === 'card' || m === 'tarjeta' || m === 'bacs') {
      return 'Tarjeta';
    } else if (m === 'mixed' || m === 'mixto') {
      return 'Mixto';
    }
    return method || '-';
  }

  // 计算统计信息
  let totalAmount = 0;
  let cashTotal = 0;
  let cardTotal = 0;
  let mixedTotal = 0;
  let cashCount = 0;
  let cardCount = 0;
  let mixedCount = 0;

  orders.forEach(order => {
    const amount = parseFloat(order.total) || 0;
    totalAmount += amount;
    const method = (order.payment_method || '').toLowerCase();
    if (method === 'cash' || method === 'efectivo' || method === 'cod') {
      cashTotal += amount;
      cashCount++;
    } else if (method === 'card' || method === 'tarjeta' || method === 'bacs') {
      cardTotal += amount;
      cardCount++;
    } else if (method === 'mixed' || method === 'mixto') {
      mixedTotal += amount;
      mixedCount++;
    }
  });

  // 🔥 从含税总额反算，税种/税率跟小票设置保持一致
  const totalTaxResult = window.ruiyiCalculateIncludedReceiptTax(totalAmount);
  const totalSubtotal = totalTaxResult.base;
  const totalTax = totalTaxResult.tax;

  // 🔥🔥🔥 检查 CLODOP 是否可用
  const clodopReady = window.clodopConfig?.enabled && typeof RUIYI_LODOP !== 'undefined' && RUIYI_LODOP && window.clodopConfig?.defaultPrinter;

  if (clodopReady) {
    // 使用 CLODOP 直接打印
    printStatementWithClodop(orders, dateFrom, dateTo, storeInfo, getPaymentMethodText, {
      totalAmount, totalSubtotal, totalTax,
      cashTotal, cardTotal, mixedTotal,
      cashCount, cardCount, mixedCount
    });
  } else {
    // 降级：浏览器打印
    printStatementWithBrowser(orders, dateFrom, dateTo, storeInfo, getPaymentMethodText, {
      totalAmount, totalSubtotal, totalTax,
      cashTotal, cardTotal, mixedTotal,
      cashCount, cardCount, mixedCount
    });
  }
}

// 🔥🔥🔥 使用 CLODOP 打印对账单（80mm小票，左对齐，大字体）
function printStatementWithClodop(orders, dateFrom, dateTo, storeInfo, getPaymentMethodText, stats) {
  try {
    console.log('[对账单] 开始 CLODOP 打印，订单数:', orders.length);

    // 设置Lodop注册号
    RUIYI_LODOP.SET_LICENSES("","D615C875005D74B88EC9E2585C79798E9CA","","");
    RUIYI_LODOP.PRINT_INIT("RUIYI-POS-AccountStatement");
    RUIYI_LODOP.SET_PRINT_PAGESIZE(3, "80mm", 0, ""); // 80mm宽度，高度自适应
    RUIYI_LODOP.SET_PRINTER_INDEX(window.clodopConfig.defaultPrinter);

    let y = 3; // 起始位置 (mm) - 始终保持整数
    const W = "72mm"; // 可用宽度（80mm - 左右边距4mm*2）

    // 辅助函数：添加文本行（确保y为整数，默认左对齐）
    function addText(yPos, left, width, height, text, fontSize, bold) {
      RUIYI_LODOP.ADD_PRINT_TEXT(Math.round(yPos) + "mm", left, width, height, text);
      RUIYI_LODOP.SET_PRINT_STYLEA(0, "FontName", "Arial");
      RUIYI_LODOP.SET_PRINT_STYLEA(0, "FontSize", fontSize || 10);
      if (bold) RUIYI_LODOP.SET_PRINT_STYLEA(0, "Bold", 1);
      RUIYI_LODOP.SET_PRINT_STYLEA(0, "Alignment", 1); // 始终左对齐
    }

    // 辅助函数：添加一行（标签: 值）格式
    function addLine(yPos, text, fontSize, bold) {
      addText(yPos, "4mm", W, "5mm", text, fontSize || 10, bold);
    }

    // 🔥 1. Logo（靠左显示）
    const logoUrl = storeInfo.receiptLogo || '';
    if (logoUrl && logoUrl.length > 5) {
      const logoSize = window.clodopConfig?.logoSize || 35;
      let effectiveUrl = logoUrl;
      if (logoUrl.startsWith('//')) effectiveUrl = 'https:' + logoUrl;

      if (typeof LogoCache !== 'undefined' && LogoCache.getLogoUrl) {
        effectiveUrl = LogoCache.getLogoUrl(effectiveUrl) || effectiveUrl;
      }

      const logoHeight = Math.round(logoSize * 0.36);
      if (effectiveUrl.startsWith('data:')) {
        const logoHtml = `<div style="text-align:left;"><img src="${effectiveUrl}" style="width:${logoSize}mm;height:auto;"></div>`;
        RUIYI_LODOP.ADD_PRINT_HTM(y + "mm", "4mm", W, logoHeight + "mm", logoHtml);
      } else {
        RUIYI_LODOP.ADD_PRINT_IMAGE(y + "mm", "4mm", logoSize + "mm", logoHeight + "mm", `<img src="${effectiveUrl}">`);
        RUIYI_LODOP.SET_PRINT_STYLEA(0, "Stretch", 2);
      }
      y += logoHeight + 2;
    }

    // 🔥 2. 店铺名称
    if (storeInfo.storeName) {
      addLine(y, storeInfo.storeName, 14, true);
      y += 6;
    }

    // 🔥 3. 商户名称
    if (storeInfo.businessName) {
      addLine(y, storeInfo.businessName, 11, false);
      y += 5;
    }

    // 🔥 4. CIF/NIF
    if (storeInfo.cifNif) {
      addLine(y, "CIF/NIF: " + storeInfo.cifNif, 10, false);
      y += 4;
    }

    // 🔥 5. 电话
    if (storeInfo.phone) {
      addLine(y, "Tel: " + storeInfo.phone, 10, false);
      y += 4;
    }

    // 🔥 6. 地址
    if (storeInfo.address) {
      addText(y, "4mm", W, "10mm", storeInfo.address, 10, false);
      RUIYI_LODOP.SET_PRINT_STYLEA(0, "WordWrap", 1);
      y += 8;
    }

    // 🔥 7. 分隔线
    y += 2;
    addLine(y, "================================", 10, false);
    y += 5;

    // 辅助函数：日期格式转换为 DD-MM-YYYY
    function formatDateDMY(dateStr) {
      if (!dateStr) return '';
      // 尝试解析各种日期格式
      const parts = dateStr.split(/[-\/\.]/);
      if (parts.length === 3) {
        // 如果是 YYYY-MM-DD 格式
        if (parts[0].length === 4) {
          return `${parts[2]}-${parts[1]}-${parts[0]}`;
        }
        // 如果已经是 DD-MM-YYYY 格式
        if (parts[2].length === 4) {
          return dateStr.replace(/[\/\.]/g, '-');
        }
      }
      return dateStr; // 无法解析则返回原值
    }

    // 🔥 8. 标题
    addLine(y, "RESUMEN DE PEDIDOS", 14, true);
    y += 6;

    // 🔥 9. 日期范围（DD-MM-YYYY 格式）
    const fromDMY = formatDateDMY(dateFrom);
    const toDMY = formatDateDMY(dateTo);
    const dateRangeText = fromDMY === toDMY ? `Fecha: ${fromDMY}` : `Periodo: ${fromDMY} ~ ${toDMY}`;
    addLine(y, dateRangeText, 11, false);
    y += 5;

    // 🔥 10. 表头分隔线
    addLine(y, "--------------------------------", 10, false);
    y += 5;

    // 🔥 11. 订单列表（全部左对齐，字体加大）
    orders.forEach((order, index) => {
      const method = (order.payment_method || '').toLowerCase();
      const total = parseFloat(order.total) || 0;
      const taxResult = window.ruiyiCalculateIncludedReceiptTax(total);
      const subtotal = taxResult.base;
      const tax = taxResult.tax;

      // 订单编号和日期（DD-MM-YYYY 格式）
      const formattedDate = formatDateDMY(order.date);
      addLine(y, `#${index + 1}  ${formattedDate} ${order.time || ''}`, 11, true);
      y += 5;

      // Base
      addLine(y, `  Base: €${subtotal.toFixed(2)}`, 10, false);
      y += 4;

      // 税费
      addLine(y, `  ${window.ruiyiGetReceiptTaxDisplayLabel().replace(':', '')}: €${tax.toFixed(2)}`, 10, false);
      y += 4;

      // Total
      addLine(y, `  Total: €${total.toFixed(2)}`, 11, true);
      y += 5;

      // 支付方式
      addLine(y, `  Pago: ${getPaymentMethodText(order.payment_method)}`, 10, false);
      y += 4;

      // 支付详情
      if (method === 'cash' || method === 'efectivo' || method === 'cod') {
        const received = parseFloat(order.received_amount) || 0;
        const change = parseFloat(order.change_amount) || 0;
        if (received > 0) {
          addLine(y, `  Recibido: €${received.toFixed(2)} / Cambio: €${change.toFixed(2)}`, 9, false);
          y += 4;
        }
      } else if (method === 'mixed' || method === 'mixto') {
        const cashAmt = parseFloat(order.cash_amount) || 0;
        const cardAmt = parseFloat(order.card_amount) || 0;
        addLine(y, `  Efectivo: €${cashAmt.toFixed(2)} / Tarjeta: €${cardAmt.toFixed(2)}`, 9, false);
        y += 4;
      }

      // 订单之间的小分隔线
      addLine(y, "- - - - - - - - - - - - - - - -", 9, false);
      y += 4;
    });

    // 🔥 12. 统计分隔线
    y += 2;
    addLine(y, "================================", 10, false);
    y += 5;

    // 🔥 13. 统计信息（全部左对齐）
    addLine(y, `Total Pedidos: ${orders.length}`, 11, false);
    y += 5;

    addLine(y, `Base Imponible: €${stats.totalSubtotal.toFixed(2)}`, 11, false);
    y += 5;

    addLine(y, `${window.ruiyiGetReceiptTaxDisplayLabel().replace(':', '')}: €${stats.totalTax.toFixed(2)}`, 11, false);
    y += 5;

    if (stats.cashCount > 0) {
      addLine(y, `Efectivo (${stats.cashCount}): €${stats.cashTotal.toFixed(2)}`, 11, false);
      y += 5;
    }

    if (stats.cardCount > 0) {
      addLine(y, `Tarjeta (${stats.cardCount}): €${stats.cardTotal.toFixed(2)}`, 11, false);
      y += 5;
    }

    if (stats.mixedCount > 0) {
      addLine(y, `Mixto (${stats.mixedCount}): €${stats.mixedTotal.toFixed(2)}`, 11, false);
      y += 5;
    }

    // 分隔线
    addLine(y, "--------------------------------", 10, false);
    y += 4;

    // 总计（大字体加粗）
    addLine(y, `TOTAL: €${stats.totalAmount.toFixed(2)}`, 16, true);
    y += 8;

    // 🔥 14. 生成时间
    y += 2;
    addLine(y, `Generado: ${new Date().toLocaleString()}`, 9, false);
    y += 6;

    // 🔥 15. 执行打印
    RUIYI_LODOP.PRINT();

    console.log('[对账单] CLODOP 打印任务已发送');

    Toastify({
      text: '✅ Resumen enviado a impresora',
      duration: 2000,
      gravity: "top",
      position: "center",
      style: { background: "#10b981" }
    }).showToast();

  } catch (error) {
    console.error('[对账单] CLODOP 打印失败:', error);
    // 降级到浏览器打印
    printStatementWithBrowser(orders, dateFrom, dateTo, storeInfo, getPaymentMethodText, stats);
  }
}

// 🔥 浏览器打印对账单（降级方案）
function printStatementWithBrowser(orders, dateFrom, dateTo, storeInfo, getPaymentMethodText, stats) {
  // 辅助函数：转义HTML
  function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  // 生成店铺信息HTML
  let storeInfoHtml = '';
  if (storeInfo.receiptLogo && storeInfo.receiptLogo.length > 5) {
    let logoUrl = storeInfo.receiptLogo;
    if (logoUrl.startsWith('//')) {
      logoUrl = 'https:' + logoUrl;
    }
    storeInfoHtml += `<div style="text-align: center; margin-bottom: 10px;"><img src="${logoUrl}" style="max-width: 150px; max-height: 60px;" alt="Logo"></div>`;
  }
  if (storeInfo.storeName) {
    storeInfoHtml += `<div style="font-size: 18px; font-weight: bold; text-align: center; margin-bottom: 5px;">${escapeHtml(storeInfo.storeName).replace(/\n/g, '<br>')}</div>`;
  }
  if (storeInfo.businessName) {
    storeInfoHtml += `<div style="font-size: 12px; text-align: center;">${escapeHtml(storeInfo.businessName)}</div>`;
  }
  if (storeInfo.cifNif) {
    storeInfoHtml += `<div style="font-size: 12px; text-align: center;">CIF/NIF: ${escapeHtml(storeInfo.cifNif)}</div>`;
  }
  if (storeInfo.phone) {
    storeInfoHtml += `<div style="font-size: 12px; text-align: center;">Tel: ${escapeHtml(storeInfo.phone)}</div>`;
  }
  if (storeInfo.address) {
    storeInfoHtml += `<div style="font-size: 12px; text-align: center;">${escapeHtml(storeInfo.address)}</div>`;
  }

  // 生成订单列表HTML（包含详细支付信息）
  let ordersHtml = orders.map((order, index) => {
    const method = (order.payment_method || '').toLowerCase();
    const total = parseFloat(order.total) || 0;
    // 🔥 从含税总额反算，税种/税率跟小票设置保持一致
    const taxResult = window.ruiyiCalculateIncludedReceiptTax(total);
    const subtotal = taxResult.base;
    const tax = taxResult.tax;

    // 构建支付详情
    let paymentDetails = '';
    if (method === 'cash' || method === 'efectivo' || method === 'cod') {
      // 现金支付：显示收款和找零
      const received = parseFloat(order.received_amount) || 0;
      const change = parseFloat(order.change_amount) || 0;
      if (received > 0) {
        paymentDetails = `<div class="payment-detail">Recibido: €${received.toFixed(2)} / Cambio: €${change.toFixed(2)}</div>`;
      }
    } else if (method === 'mixed' || method === 'mixto') {
      // 混合支付：显示现金和刷卡金额
      const cashAmt = parseFloat(order.cash_amount) || 0;
      const cardAmt = parseFloat(order.card_amount) || 0;
      paymentDetails = `<div class="payment-detail">Efectivo: €${cashAmt.toFixed(2)} / Tarjeta: €${cardAmt.toFixed(2)}</div>`;
    }

    return `
      <div class="order-item">
        <div class="order-header">
          <span class="order-num">#${index + 1}</span>
          <span class="order-date">${order.date} ${order.time || ''}</span>
        </div>
        <div class="order-details">
          <div class="detail-row">
            <span>Base:</span>
            <span>€${subtotal.toFixed(2)}</span>
          </div>
          <div class="detail-row">
            <span>${window.ruiyiGetReceiptTaxDisplayLabel()}</span>
            <span>€${tax.toFixed(2)}</span>
          </div>
          <div class="detail-row total-row">
            <span>Total:</span>
            <span>€${total.toFixed(2)}</span>
          </div>
          <div class="detail-row payment-row">
            <span>Pago:</span>
            <span>${getPaymentMethodText(order.payment_method)}</span>
          </div>
          ${paymentDetails}
        </div>
      </div>
    `;
  }).join('');

  // 生成完整的打印HTML
  const printHtml = `
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="UTF-8">
      <title>Resumen de Pedidos</title>
      <style>
        @media print {
          body { margin: 0; padding: 10px; }
          .no-print { display: none !important; }
        }
        body {
          font-family: 'Courier New', monospace;
          font-size: 12px;
          max-width: 80mm;
          margin: 0 auto;
          padding: 10px;
        }
        .header {
          text-align: center;
          border-bottom: 2px dashed #000;
          padding-bottom: 10px;
          margin-bottom: 10px;
        }
        .title {
          font-size: 16px;
          font-weight: bold;
          margin: 10px 0;
          text-align: center;
        }
        .date-range {
          font-size: 14px;
          text-align: center;
          margin: 8px 0;
          padding: 5px;
          background: #f0f0f0;
        }
        .orders-list {
          margin: 10px 0;
        }
        .order-item {
          border: 1px solid #ccc;
          margin-bottom: 8px;
          padding: 8px;
          background: #fafafa;
        }
        .order-header {
          display: flex;
          justify-content: space-between;
          font-weight: bold;
          border-bottom: 1px dashed #999;
          padding-bottom: 5px;
          margin-bottom: 5px;
        }
        .order-num {
          color: #333;
        }
        .order-date {
          color: #666;
          font-size: 11px;
        }
        .order-details {
          font-size: 11px;
        }
        .detail-row {
          display: flex;
          justify-content: space-between;
          padding: 2px 0;
        }
        .total-row {
          font-weight: bold;
          border-top: 1px solid #ddd;
          margin-top: 3px;
          padding-top: 3px;
        }
        .payment-row {
          color: #0066cc;
        }
        .payment-detail {
          font-size: 10px;
          color: #666;
          font-style: italic;
          text-align: right;
          margin-top: 2px;
        }
        .summary {
          border-top: 2px dashed #000;
          padding-top: 10px;
          margin-top: 10px;
        }
        .summary-row {
          display: flex;
          justify-content: space-between;
          padding: 4px 0;
          font-size: 12px;
        }
        .summary-row.total {
          font-size: 16px;
          font-weight: bold;
          border-top: 1px solid #000;
          margin-top: 5px;
          padding-top: 8px;
        }
        .footer {
          text-align: center;
          margin-top: 15px;
          font-size: 11px;
          color: #666;
        }
        .print-btn {
          display: block;
          width: 100%;
          padding: 10px;
          background: #4CAF50;
          color: white;
          border: none;
          border-radius: 5px;
          font-size: 14px;
          cursor: pointer;
          margin: 15px 0;
        }
        .print-btn:hover {
          background: #45a049;
        }
      </style>
    </head>
    <body>
      <div class="header">
        ${storeInfoHtml}
      </div>

      <div class="title">RESUMEN DE PEDIDOS</div>

      <div class="date-range">
        ${dateFrom === dateTo
          ? `Fecha: ${dateFrom}`
          : `${dateFrom} ~ ${dateTo}`
        }
      </div>

      <div class="orders-list">
        ${ordersHtml}
      </div>

      <div class="summary">
        <div class="summary-row">
          <span>Total Pedidos:</span>
          <span>${orders.length}</span>
        </div>
        <div class="summary-row">
          <span>Base Imponible:</span>
          <span>€${stats.totalSubtotal.toFixed(2)}</span>
        </div>
        <div class="summary-row">
          <span>${window.ruiyiGetReceiptTaxDisplayLabel()}</span>
          <span>€${stats.totalTax.toFixed(2)}</span>
        </div>
        ${stats.cashCount > 0 ? `
        <div class="summary-row">
          <span>Efectivo (${stats.cashCount}):</span>
          <span>€${stats.cashTotal.toFixed(2)}</span>
        </div>
        ` : ''}
        ${stats.cardCount > 0 ? `
        <div class="summary-row">
          <span>Tarjeta (${stats.cardCount}):</span>
          <span>€${stats.cardTotal.toFixed(2)}</span>
        </div>
        ` : ''}
        ${stats.mixedCount > 0 ? `
        <div class="summary-row">
          <span>Mixto (${stats.mixedCount}):</span>
          <span>€${stats.mixedTotal.toFixed(2)}</span>
        </div>
        ` : ''}
        <div class="summary-row total">
          <span>TOTAL:</span>
          <span>€${stats.totalAmount.toFixed(2)}</span>
        </div>
      </div>

      <div class="footer">
        Generado: ${new Date().toLocaleString()}
      </div>

      <button class="print-btn no-print" onclick="window.print(); return false;">
        Imprimir
      </button>
    </body>
    </html>
  `;

  // 打开打印窗口
  const printWindow = window.open('', '_blank', 'width=400,height=600');
  if (printWindow) {
    printWindow.document.write(printHtml);
    printWindow.document.close();
    // 自动触发打印
    printWindow.onload = function() {
      setTimeout(() => {
        printWindow.print();
      }, 300);
    };
  } else {
    Swal.fire({
      icon: 'warning',
      title: 'Ventana bloqueada',
      text: 'Por favor permita las ventanas emergentes para imprimir'
    });
  }
}

// 🔥 作废订单功能（带密码验证）
function voidOrder(orderId, orderTotal, paymentMethod) {
  // 🔥 如果设置了密码，先验证密码
  if (voidOrderPassword && voidOrderPassword.length > 0) {
    Swal.fire({
      title: '<?php echo ruiyi_translate('Verificación de contraseña', 'Password Verification', '密码验证'); ?>',
      html: `
        <p class="text-gray-600 mb-4"><?php echo ruiyi_translate('Por favor ingrese la contraseña para anular el pedido', 'Please enter password to void order', '请输入作废密码'); ?></p>
        <input type="password" id="void-password-input" class="swal2-input" placeholder="<?php echo ruiyi_translate('Contraseña', 'Password', '密码'); ?>" autocomplete="off">
      `,
      icon: 'lock',
      showCancelButton: true,
      confirmButtonColor: '#dc2626',
      cancelButtonColor: '#6b7280',
      confirmButtonText: '<?php echo ruiyi_translate('Verificar', 'Verify', '验证'); ?>',
      cancelButtonText: '<?php echo ruiyi_translate('Cancelar', 'Cancel', '取消'); ?>',
      preConfirm: () => {
        const password = document.getElementById('void-password-input').value;
        if (!password) {
          Swal.showValidationMessage('<?php echo ruiyi_translate('Por favor ingrese la contraseña', 'Please enter password', '请输入密码'); ?>');
          return false;
        }
        return password;
      },
      didOpen: () => {
        // 自动聚焦到密码输入框
        document.getElementById('void-password-input').focus();
      }
    }).then((result) => {
      if (result.isConfirmed) {
        const enteredPassword = result.value;
        // 验证密码
        if (enteredPassword === voidOrderPassword) {
          // 密码正确，执行作废确认
          confirmAndVoidOrder(orderId, orderTotal, paymentMethod);
        } else {
          // 密码错误
          Swal.fire({
            icon: 'error',
            title: '<?php echo ruiyi_translate('Contraseña incorrecta', 'Incorrect password', '密码错误'); ?>',
            text: '<?php echo ruiyi_translate('La contraseña ingresada no es correcta', 'The entered password is incorrect', '输入的密码不正确'); ?>'
          });
        }
      }
    });
  } else {
    // 没有设置密码，直接执行作废确认
    confirmAndVoidOrder(orderId, orderTotal, paymentMethod);
  }
}

// 🔥 确认并执行作废订单
function confirmAndVoidOrder(orderId, orderTotal, paymentMethod) {
  Swal.fire({
    title: '<?php echo ruiyi_translate('¿Anular este pedido?', 'Void this order?', '确定要作废此订单吗？'); ?>',
    html: `
      <p class="text-gray-600 mb-2"><?php echo ruiyi_translate('El pedido será cancelado y se actualizará el cierre diario.', 'The order will be cancelled and daily summary will be updated.', '订单将被取消，日结单数据将被更新。'); ?></p>
      <p class="text-lg font-bold text-red-600"><?php echo ruiyi_translate('Pedido', 'Order', '订单'); ?> #${orderId} - €${orderTotal}</p>
    `,
    icon: 'warning',
    showCancelButton: true,
    confirmButtonColor: '#dc2626',
    cancelButtonColor: '#6b7280',
    confirmButtonText: '<?php echo ruiyi_translate('Sí, anular', 'Yes, void it', '是，作废'); ?>',
    cancelButtonText: '<?php echo ruiyi_translate('Cancelar', 'Cancel', '取消'); ?>'
  }).then((result) => {
    if (result.isConfirmed) {
      // 显示处理中
      Swal.fire({
        title: '<?php echo ruiyi_translate('Procesando...', 'Processing...', '处理中...'); ?>',
        text: '<?php echo ruiyi_translate('Anulando pedido', 'Voiding order', '正在作废订单'); ?>',
        allowOutsideClick: false,
        didOpen: () => {
          Swal.showLoading();
        }
      });

      // 调用后端API作废订单
      fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          action: 'ruiyi_void_order',
          order_id: orderId,
          nonce: ajaxNonce
        })
      })
      .then(response => response.json())
      .then(data => {
        Swal.close(); // 🔥 关闭loading弹窗

        if (data.success) {
          // 🔥 直接刷新历史订单列表，不显示成功弹窗
          loadOrderHistory(true);

          // 🔥 如果日结单模块可见，刷新日结单数据
          const cuentasSection = document.getElementById('cuentas');
          if (cuentasSection && !cuentasSection.classList.contains('hidden')) {
            if (typeof loadDailySummary === 'function') {
              loadDailySummary();
            }
          }
        } else {
          throw new Error(data.data?.message || '<?php echo ruiyi_translate('Error al anular el pedido', 'Failed to void order', '作废订单失败'); ?>');
        }
      })
      .catch(error => {
        console.error('作废订单失败:', error);
        Swal.fire({
          icon: 'error',
          title: '<?php echo ruiyi_translate('Error', 'Error', '错误'); ?>',
          text: error.message
        });
      });
    }
  });
}

// 打印历史订单（带二维码）
function printHistoryOrder(orderId) {
  Toastify({
    text: '<?php echo ruiyi_translate('Preparando impresión...', 'Preparing print...', '准备打印...'); ?>',
    duration: 2000,
    gravity: "top",
    position: "center",
    style: { background: "#2196f3" }
  }).showToast();

  // 调用后端API获取带二维码的小票HTML
  fetch(ajaxUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      action: 'ruiyi_pos_get_order_receipt_with_qr',
      order_id: orderId,
      nonce: ajaxNonce
    })
  })
  .then(response => response.json())
  .then(data => {
    if (data.success && data.data && data.data.html) {
      // 使用统一打印函数
      if (typeof ruiyiUnifiedPrint !== 'undefined') {
        const printSuccess = ruiyiUnifiedPrint(data.data.html, 'history_reprint');
        if (!printSuccess) {
          throw new Error('CLODOP history receipt print failed');
        }

        Toastify({
          text: '<?php echo ruiyi_translate('Imprimiendo pedido', 'Printing order', '正在打印订单'); ?> #' + orderId,
          duration: 2000,
          gravity: "top",
          position: "center",
          style: { background: "#10b981" }
        }).showToast();
      } else {
        throw new Error('<?php echo ruiyi_translate('Función de impresión no disponible', 'Print function not available', '打印功能不可用'); ?>');
      }
    } else {
      throw new Error(data.data?.message || '<?php echo ruiyi_translate('Error al obtener recibo', 'Failed to get receipt', '获取小票失败'); ?>');
    }
  })
  .catch(error => {
    console.error('打印历史订单失败:', error);
    // 🔥 使用用户友好的打印机配置提示
    showPrinterConfigDialog();
  });
}

// 查看订单详情
function viewOrderDetails(orderId) {
  Swal.fire({
    title: '<?php echo ruiyi_translate('Cargando detalles...', 'Loading details...', '加载详情...'); ?>',
    allowOutsideClick: false,
    didOpen: () => { Swal.showLoading(); }
  });

  fetch(ajaxUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      action: 'ruiyi_pos_get_order_details',
      order_id: orderId,
      nonce: ajaxNonce
    })
  })
  .then(response => response.json())
  .then(data => {
    // 🔥 调试：查看完整返回数据

    if (data.success && data.data) {
      // 🔥 后端返回 {success: true, data: {...}}
      const order = data.data;


      // 🔥 安全检查：确保 items 是数组
      if (!order.items || !Array.isArray(order.items)) {
        console.warn('[订单详情] items 不是数组，设置为空数组');
        order.items = [];
      }

      // 🔥 准备支付明细显示
      let paymentDetailsHtml = '';
      if (order.payment_details) {
        const pd = order.payment_details;
        let paymentMethodText = '';


        // 🔥 修复：优先检查是否有现金和刷卡金额（混合支付）
        const hasCash = pd.cash_amount && parseFloat(pd.cash_amount) > 0;
        const hasCard = pd.card_amount && parseFloat(pd.card_amount) > 0;

        if (hasCash && hasCard) {
          // 混合支付 - 详细显示现金和刷卡
          paymentMethodText = `
            <div class="bg-blue-50 p-3 rounded-lg">
              <div class="font-semibold text-blue-800 mb-3"><?php echo ruiyi_translate('Pago Mixto', 'Mixed Payment', '混合支付'); ?>: €${parseFloat(order.total).toFixed(2)}</div>
              <div class="space-y-2 text-sm">
                <div class="flex justify-between items-center">
                  <span><i class="fas fa-money-bill-wave text-green-600 mr-2"></i><?php echo ruiyi_translate('Efectivo', 'Cash', '现金'); ?>:</span>
                  <span class="font-bold text-green-700">€${parseFloat(pd.cash_amount).toFixed(2)}</span>
                </div>
                <div class="flex justify-between items-center">
                  <span><i class="fas fa-credit-card text-blue-600 mr-2"></i><?php echo ruiyi_translate('Tarjeta', 'Card', '刷卡'); ?>:</span>
                  <span class="font-bold text-blue-700">€${parseFloat(pd.card_amount).toFixed(2)}</span>
                </div>
              </div>
            </div>
          `;
        } else if (hasCash && !hasCard) {
          // 现金支付 - 显示实收和找零
          const receivedAmt = pd.received_amount ? parseFloat(pd.received_amount) : parseFloat(order.total);
          const changeAmt = pd.change_amount ? parseFloat(pd.change_amount) : 0;

          paymentMethodText = `
            <div class="bg-green-50 p-3 rounded-lg">
              <div class="space-y-2 text-sm">
                <div class="flex justify-between items-center">
                  <span><i class="fas fa-money-bill-wave text-green-600 mr-2"></i><?php echo ruiyi_translate('Efectivo', 'Cash', '现金'); ?>:</span>
                  <span class="font-bold text-green-700">€${parseFloat(order.total).toFixed(2)}</span>
                </div>
                ${receivedAmt > parseFloat(order.total) ? `
                  <div class="flex justify-between items-center text-xs">
                    <span><?php echo ruiyi_translate('Recibido', 'Received', '实收'); ?>:</span>
                    <span>€${receivedAmt.toFixed(2)}</span>
                  </div>
                  <div class="flex justify-between items-center text-xs">
                    <span><?php echo ruiyi_translate('Cambio', 'Change', '找零'); ?>:</span>
                    <span class="font-bold">€${changeAmt.toFixed(2)}</span>
                  </div>
                ` : ''}
              </div>
            </div>
          `;
        } else if (!hasCash && hasCard) {
          // 刷卡支付
          paymentMethodText = `
            <div class="bg-blue-50 p-3 rounded-lg">
              <div class="flex justify-between items-center">
                <span><i class="fas fa-credit-card text-blue-600 mr-2"></i><?php echo ruiyi_translate('Tarjeta', 'Card', '刷卡'); ?>:</span>
                <span class="font-bold text-blue-700">€${parseFloat(order.total).toFixed(2)}</span>
              </div>
            </div>
          `;
        } else {
          // 没有具体金额数据，显示支付方式名称
          const methodName = pd.method === 'bacs' ? '<?php echo ruiyi_translate('Efectivo', 'Cash', '现金'); ?>' :
                            pd.method === 'mixed' ? '<?php echo ruiyi_translate('Pago Mixto', 'Mixed Payment', '混合支付'); ?>' :
                            pd.method === 'card' ? '<?php echo ruiyi_translate('Tarjeta', 'Card', '刷卡'); ?>' :
                            (pd.method || order.payment_method || '<?php echo ruiyi_translate('No especificado', 'Not specified', '未指定'); ?>');

          paymentMethodText = `
            <div class="text-sm bg-gray-50 p-3 rounded-lg">
              <div class="flex justify-between items-center">
                <strong><?php echo ruiyi_translate('Método', 'Method', '方式'); ?>:</strong>
                <span>${methodName} - €${parseFloat(order.total).toFixed(2)}</span>
              </div>
              <div class="text-xs text-orange-600 mt-2">
                <i class="fas fa-exclamation-triangle mr-1"></i>
                <?php echo ruiyi_translate('Detalles de pago no disponibles', 'Payment details not available', '支付明细不可用'); ?>
              </div>
            </div>
          `;
        }

        paymentDetailsHtml = `
          <div class="border-t mt-3 pt-3">
            <h4 class="font-semibold mb-2 flex items-center">
              <i class="fas fa-wallet mr-2 text-green-600"></i>
              <?php echo ruiyi_translate('Detalles de Pago', 'Payment Details', '支付明细'); ?>
            </h4>
            ${paymentMethodText}
          </div>
        `;
      } else {
        // 如果没有支付明细数据，显示支付方式
        paymentDetailsHtml = `
          <div class="border-t mt-3 pt-3">
            <h4 class="font-semibold mb-2 flex items-center">
              <i class="fas fa-wallet mr-2 text-green-600"></i>
              <?php echo ruiyi_translate('Detalles de Pago', 'Payment Details', '支付明细'); ?>
            </h4>
            <div class="text-sm text-gray-600">${order.payment_method || '<?php echo ruiyi_translate('No especificado', 'Not specified', '未指定'); ?>'}</div>
          </div>
        `;
      }

      // 🔥 准备费用/抵扣券显示
      let feesHtml = '';

      // 🔥 【新增】检查是否有手动折扣元数据（即使没有费用项也显示）
      const hasDiscountMeta = order.discount_percent && parseFloat(order.discount_percent) > 0;
      const discountPercent = hasDiscountMeta ? parseFloat(order.discount_percent) : 0;
      const discountAmount = order.discount_amount ? parseFloat(order.discount_amount) : 0;

      // 🔥 检查折扣是否已经在fees中显示（避免重复显示）
      let discountAlreadyInFees = false;
      if (order.fees && Array.isArray(order.fees)) {
        discountAlreadyInFees = order.fees.some(fee =>
          (fee.name && fee.name.toLowerCase().includes('descuento')) ||
          (fee.type === 'discount') ||
          (fee.amount < 0 && Math.abs(fee.amount - discountAmount) < 0.05)
        );
      }

      if (order.fees && Array.isArray(order.fees) && order.fees.length > 0) {

        const feesContent = order.fees.map(fee => {
          const isDiscount = fee.type === 'discount' || fee.amount < 0;
          const feeAmount = Math.abs(parseFloat(fee.amount));
          const amountDisplay = isDiscount ? `-€${feeAmount.toFixed(2)}` : `€${feeAmount.toFixed(2)}`;
          const colorClass = isDiscount ? 'text-red-600' : 'text-green-600';
          const iconClass = isDiscount ? 'fa-ticket-alt' : 'fa-plus-circle';

          return `
            <div class="flex justify-between items-center py-1">
              <span class="text-sm"><i class="fas ${iconClass} mr-2 ${colorClass}"></i>${fee.name}</span>
              <span class="font-bold ${colorClass}">${amountDisplay}</span>
            </div>
          `;
        }).join('');

        feesHtml = `
          <div class="border-t mt-3 pt-3">
            <h4 class="font-semibold mb-2 flex items-center">
              <i class="fas fa-receipt mr-2 text-purple-600"></i>
              <?php echo ruiyi_translate('Descuentos y Cargos', 'Discounts & Charges', '折扣与费用'); ?>
            </h4>
            <div class="bg-purple-50 p-3 rounded-lg">
              ${feesContent}
            </div>
          </div>
        `;
      } else if (hasDiscountMeta && !discountAlreadyInFees) {
        // 🔥 【新增】如果有折扣元数据但没有费用项，单独显示折扣信息
        feesHtml = `
          <div class="border-t mt-3 pt-3">
            <h4 class="font-semibold mb-2 flex items-center">
              <i class="fas fa-percentage mr-2 text-orange-500"></i>
              <?php echo ruiyi_translate('Descuento Aplicado', 'Applied Discount', '已应用折扣'); ?>
            </h4>
            <div class="bg-orange-50 p-3 rounded-lg">
              <div class="flex justify-between items-center py-1">
                <span class="text-sm"><i class="fas fa-tag mr-2 text-orange-600"></i><?php echo ruiyi_translate('Descuento', 'Discount', '折扣'); ?> ${discountPercent}%</span>
                <span class="font-bold text-orange-600">-€${discountAmount.toFixed(2)}</span>
              </div>
            </div>
          </div>
        `;
      }

      Swal.fire({
        title: `<?php echo ruiyi_translate('Detalles del Pedido', 'Order Details', '订单详情'); ?>`,
        html: `
          <div class="order-details-popup-wrapper" style="display: flex; flex-direction: column; max-height: 65vh;">
            <!-- 可滚动的内容区域 -->
            <div class="text-left" style="flex: 1; overflow-y: auto; padding-right: 4px;">
              <div class="grid grid-cols-2 gap-3 mb-4 text-sm">
                <div><strong><?php echo ruiyi_translate('Fecha', 'Date', '日期'); ?>:</strong> ${order.date}</div>
                <div><strong><?php echo ruiyi_translate('Total', 'Total', '总计'); ?>:</strong> <span class="text-green-600 font-bold">€${order.total}</span></div>
                ${order.table_number ? `<div class="col-span-2"><strong><?php echo ruiyi_translate('Mesa', 'Table', '桌号'); ?>:</strong> <span class="bg-yellow-100 text-yellow-800 px-2 py-0.5 rounded text-sm font-medium">${(() => {
                  // 🔥 将原始桌位号映射为分类显示名称
                  const rawTableNum = order.table_number;
                  const tableNumOnly = parseInt(String(rawTableNum).replace(/^(餐桌|Mesa|Table)\s*/i, ''));
                  if (!isNaN(tableNumOnly) && window.tableCategoryMappings) {
                    const allMappings = Array.isArray(window.tableCategoryMappings)
                      ? window.tableCategoryMappings
                      : Object.values(window.tableCategoryMappings);
                    const mapping = allMappings.find(m => m && parseInt(m.global_table_number) === tableNumOnly);
                    if (mapping && mapping.category_display_name) {
                      return mapping.category_display_name;
                    }
                  }
                  return rawTableNum;
                })()}</span></div>` : ''}
              </div>

              ${order.customer_info && (order.customer_info.phone || order.customer_info.name || order.customer_info.address) ? `
              <div class="border-t pt-3 mb-3">
                <h4 class="font-semibold mb-2 flex items-center">
                  <i class="fas fa-user mr-2 text-purple-600"></i>
                  <?php echo ruiyi_translate('Información del Cliente', 'Customer Information', '客户信息'); ?>
                </h4>
                <div class="bg-purple-50 p-3 rounded-lg text-sm space-y-1">
                  ${order.customer_info.name ? `<div><i class="fas fa-user text-purple-500 mr-2 w-4"></i><strong><?php echo ruiyi_translate('Nombre', 'Name', '姓名'); ?>:</strong> ${order.customer_info.name}</div>` : ''}
                  ${order.customer_info.phone ? `<div><i class="fas fa-phone text-purple-500 mr-2 w-4"></i><strong><?php echo ruiyi_translate('Teléfono', 'Phone', '电话'); ?>:</strong> ${order.customer_info.phone}</div>` : ''}
                  ${order.customer_info.address ? `<div><i class="fas fa-map-marker-alt text-purple-500 mr-2 w-4"></i><strong><?php echo ruiyi_translate('Dirección', 'Address', '地址'); ?>:</strong> ${order.customer_info.address}</div>` : ''}
                  ${order.customer_info.postal_code ? `<div><i class="fas fa-mail-bulk text-purple-500 mr-2 w-4"></i><strong><?php echo ruiyi_translate('Código Postal', 'Postal Code', '邮编'); ?>:</strong> ${order.customer_info.postal_code}</div>` : ''}
