// 🔥 PDF发票下载 - AJAX调用后端生成PDF并触发浏览器下载
function downloadPdfInvoice(orderId, customerData) {
  Swal.fire({
    title: '<?php echo ruiyi_translate('Generando PDF...', 'Generating PDF...', '正在生成PDF...'); ?>',
    html: '<?php echo ruiyi_translate('Por favor espere mientras se genera la factura PDF', 'Please wait while the PDF invoice is being generated', '请稍候，正在生成PDF发票'); ?>',
    allowOutsideClick: false,
    didOpen: () => { Swal.showLoading(); }
  });

  const ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url("admin-ajax.php")); ?>';
  const nonce = window.RUIYI_POS?.nonce || ajaxNonce || '<?php echo esc_js(wp_create_nonce("ruiyi_pos_nonce")); ?>';

  fetch(ajaxUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      action: 'ruiyi_generate_pdf_invoice',
      order_id: orderId,
      customer_name: customerData.customerName,
      company_name: customerData.companyName,
      address: customerData.address,
      city: customerData.city,
      state: customerData.state,
      postcode: customerData.postcode,
      tax_id: customerData.taxId,
      notes: customerData.notes,
      nonce: nonce
    })
  })
  .then(response => response.json())
  .then(data => {
    Swal.close();

    if (data.success && data.data && data.data.pdf_base64) {
      // 将base64转为Blob并触发下载
      const byteCharacters = atob(data.data.pdf_base64);
      const byteNumbers = new Array(byteCharacters.length);
      for (let i = 0; i < byteCharacters.length; i++) {
        byteNumbers[i] = byteCharacters.charCodeAt(i);
      }
      const byteArray = new Uint8Array(byteNumbers);
      const blob = new Blob([byteArray], { type: 'application/pdf' });

      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = data.data.filename || `factura-${orderId}.pdf`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(url);

      Toastify({
        text: '<?php echo ruiyi_translate('Factura PDF descargada correctamente', 'PDF invoice downloaded successfully', 'PDF发票下载成功'); ?>',
        duration: 3000,
        gravity: "top",
        position: "center",
        style: { background: "#16a34a" }
      }).showToast();
    } else {
      throw new Error(data.data?.message || '<?php echo ruiyi_translate('Error al generar factura PDF', 'Error generating PDF invoice', '生成PDF发票失败'); ?>');
    }
  })
  .catch(error => {
    Swal.close();
    console.error('[PDF发票] 下载失败:', error);
    Swal.fire({
      icon: 'error',
      title: '<?php echo ruiyi_translate('Error', 'Error', '错误'); ?>',
      text: error.message || '<?php echo ruiyi_translate('Error al descargar la factura PDF', 'Error downloading PDF invoice', '下载PDF发票失败'); ?>'
    });
  });
}

// 初始化电话号码自动搜索
function initInvoicePhoneAutocomplete() {
  // 🔥 为电话、公司名称、税号三个字段都添加自动搜索
  const fields = [
    { input: 'invoice-customer-phone', dropdown: 'invoice-phone-dropdown', searchType: 'phone' },
    { input: 'invoice-company-name', dropdown: 'invoice-company-dropdown', searchType: 'company' },
    { input: 'invoice-tax-id', dropdown: 'invoice-tax-dropdown', searchType: 'tax_id' }
  ];

  fields.forEach(field => {
    const inputEl = document.getElementById(field.input);
    const dropdownEl = document.getElementById(field.dropdown);
    if (!inputEl || !dropdownEl) return;

    let searchTimeout = null;

    // 输入时搜索
    inputEl.addEventListener('input', (e) => {
      const searchTerm = e.target.value.trim();
      if (searchTimeout) clearTimeout(searchTimeout);

      if (searchTerm.length < 2) {
        dropdownEl.classList.remove('show');
        return;
      }

      searchTimeout = setTimeout(async () => {
        const results = await fuzzySearchInvoiceCustomers(searchTerm, field.searchType);
        renderInvoicePhoneDropdown(results, dropdownEl);
      }, 300);
    });

    // 点击外部关闭下拉
    document.addEventListener('click', (e) => {
      if (!inputEl.contains(e.target) && !dropdownEl.contains(e.target)) {
        dropdownEl.classList.remove('show');
      }
    });

    // 键盘导航
    inputEl.addEventListener('keydown', (e) => {
      if (!dropdownEl.classList.contains('show')) return;

      const items = dropdownEl.querySelectorAll('.invoice-autocomplete-item');
      let currentIndex = Array.from(items).findIndex(item => item.classList.contains('selected'));

      if (e.key === 'ArrowDown') {
        e.preventDefault();
        currentIndex = (currentIndex + 1) % items.length;
        items.forEach((item, idx) => item.classList.toggle('selected', idx === currentIndex));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        currentIndex = currentIndex <= 0 ? items.length - 1 : currentIndex - 1;
        items.forEach((item, idx) => item.classList.toggle('selected', idx === currentIndex));
      } else if (e.key === 'Enter' && currentIndex >= 0) {
        e.preventDefault();
        selectInvoiceCustomer(invoicePhoneResults[currentIndex]);
        dropdownEl.classList.remove('show');
      } else if (e.key === 'Escape') {
        dropdownEl.classList.remove('show');
      }
    });
  });
}

// 模糊搜索客户（支持 phone/company/tax_id 搜索类型）
async function fuzzySearchInvoiceCustomers(searchTerm, searchType = 'phone') {
  try {
    const response = await fetch(ajaxUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        action: 'ruiyi_fuzzy_search_customers',
        search_type: searchType,
        search_term: searchTerm,
        limit: 8,
        nonce: ajaxNonce
      })
    });

    const data = await response.json();
    return data.success ? data.data.customers : [];
  } catch (error) {
    console.error('[Invoice Autocomplete] 搜索失败:', error);
    return [];
  }
}

// 渲染电话号码下拉列表
function renderInvoicePhoneDropdown(results, dropdown) {
  invoicePhoneResults = results;

  if (results.length === 0) {
    dropdown.classList.remove('show');
    return;
  }

  dropdown.innerHTML = results.map((customer, index) => {
    const parts = [];
    if (customer.phone) parts.push(customer.phone);
    if (customer.name) parts.push(customer.name);
    if (customer.business_name) parts.push(customer.business_name);
    if (customer.cif_nif) parts.push('NIF: ' + customer.cif_nif);
    const mainText = parts[0] || '';
    const subText = parts.slice(1).join(' · ');
    return `<div class="invoice-autocomplete-item" data-index="${index}">
      <div class="phone-number">${mainText}</div>
      <div class="customer-info">${subText}</div>
    </div>`;
  }).join('');

  dropdown.classList.add('show');

  // 点击选择
  dropdown.querySelectorAll('.invoice-autocomplete-item').forEach(item => {
    item.addEventListener('click', () => {
      const idx = parseInt(item.dataset.index);
      selectInvoiceCustomer(invoicePhoneResults[idx]);
      dropdown.classList.remove('show');
    });
  });
}

// 选择客户后填充表单
function selectInvoiceCustomer(customer) {
  if (!customer) return;

  const phoneField = document.getElementById('invoice-customer-phone');
  const companyField = document.getElementById('invoice-company-name');
  const taxField = document.getElementById('invoice-tax-id');
  const addressField = document.getElementById('invoice-address');

  if (phoneField) phoneField.value = customer.phone || '';
  if (companyField) companyField.value = customer.business_name || customer.company_name || '';
  if (taxField) taxField.value = customer.cif_nif || customer.tax_id || '';
  if (addressField) addressField.value = customer.address || '';

  Toastify({
    text: '<?php echo ruiyi_translate('Cliente seleccionado', 'Customer selected', '已选择客户'); ?>',
    duration: 1500,
    gravity: "top",
    position: "center",
    style: { background: "#10b981" }
  }).showToast();
}

// 🔥 离线发票HTML生成函数
function generateInvoiceHTMLOffline(orderData, customerData) {
  const config = window.RUIYI_POS_CONFIG || {};
  const storeInfo = config.storeInfo || {};

  // 店铺信息
  const storeName = storeInfo.storeName || '<?php echo esc_js(get_bloginfo("name")); ?>';
  const businessName = storeInfo.businessName || '';
  const cifNif = storeInfo.cifNif || '';
  const storeAddress = storeInfo.address || '';
  const storePhone = storeInfo.phone || '';
  const receiptLogo = storeInfo.receiptLogo || '';

  // 订单信息
  const orderId = orderData.id || 'OFFLINE';
  const orderTotal = parseFloat(orderData.total) || 0;
  const orderDate = orderData.date || new Date().toLocaleDateString();
  const orderTime = orderData.time || new Date().toLocaleTimeString();
  const items = orderData.items || [];

  // 发票号码 - 离线模式使用年份+订单ID或时间戳
  const currentYear = new Date().getFullYear();
  const invoiceNumber = ruiyiFormatReceiptInvoiceNumber(orderData.invoice_label || '', orderId, orderData.date);

  // 客户信息
  const customerName = customerData.name || '';
  const customerPhone = customerData.phone || '';
  const companyName = customerData.company_name || '';
  const taxId = customerData.tax_id || '';
  const address = customerData.address || '';
  const notes = customerData.notes || '';
  const headerAlignment = window.clodopConfig?.headerAlignment || 'left';
  const storeNameFontSize = window.clodopConfig?.storeNameFontSize || 18;

  // 生成商品列表HTML
  const _bilingual2 = window.clodopConfig?.receiptBilingual || false;
  let itemsHtml = '';
  let subtotal = 0;
  items.forEach(item => {
    const itemTotal = parseFloat(item.total) || 0;
    const qty = parseInt(item.quantity) || 1;
    const unitPrice = (itemTotal / qty).toFixed(2);
    subtotal += itemTotal;
    let _iName = item.name || '';
    if (_bilingual2 && item.name_zh) {
      const _esN = item.name_es || item.name || '';
      const numMatch2 = _esN.match(/^(\d+[A-Za-z]?\.\s*)/);
      if (numMatch2) {
        const prefix2 = numMatch2[1].replace(/\s+$/, '');
        const esClean2 = _esN.substring(numMatch2[0].length);
        const zhClean2 = item.name_zh.replace(/^\d+[A-Za-z]?\.\s*/, '');
        _iName = prefix2 + zhClean2 + esClean2;
      } else {
        _iName = item.name_zh + _esN;
      }
    }
    itemsHtml += `
      <tr>
        <td class="item-name">${escapeHtml(_iName.toUpperCase())}</td>
        <td class="col-qty">${qty}</td>
        <td class="col-price">€${unitPrice}</td>
        <td class="col-total">€${itemTotal.toFixed(2)}</td>
      </tr>
    `;
  });

  // 简化税费计算：所有产品都是含税价，税种/税率由设置模块控制
  const receiptTax = window.ruiyiCalculateIncludedReceiptTax(orderTotal);
  const totalBeforeTax = receiptTax.base;
  const taxAmount = receiptTax.tax;
  const receiptTaxLabel = window.ruiyiGetReceiptTaxDisplayLabel();

  // 生成发票HTML
  const html = `
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="utf-8">
      <title>Factura #${orderId}</title>
      <style>
        body { font-family: "Courier New", "Lucida Console", monospace; width: 72mm; margin: 0 auto; padding: 5mm 4mm; box-sizing: border-box; font-size: 10pt; font-weight: normal; }
        .receipt { width: 100%; max-width: 72mm; }
        h2 { font-size: ${storeNameFontSize}pt; font-weight: bold; text-align: ${headerAlignment}; margin: 0 0 1mm 0; line-height: 1.15; }
        .store-info { text-align: ${headerAlignment}; }
        .store-info .business-name { font-size: 0.9em; margin-bottom: 0.4mm; line-height: 1.35; font-weight: normal; }
        .store-info .cif-nif { font-size: 0.85em; margin-bottom: 0.4mm; line-height: 1.35; font-weight: normal; }
        .store-info .phone { font-size: 0.85em; margin-bottom: 0.4mm; line-height: 1.35; font-weight: normal; }
        .store-info .address { font-size: 0.85em; margin-bottom: 0; margin-top: 0.5mm; line-height: 1.35; font-weight: normal; }
        .date-line, .verifactu-invoice-number, .invoice-number { text-align: ${headerAlignment} !important; }
        .date-line { font-size: 0.8em; margin-bottom: 2mm; }
        table { width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 1em; margin-top: 3px; margin-bottom: 3px; }
        th, td { padding: 0.8mm 0.5mm; vertical-align: top; }
        th { border-bottom: 2px dashed #000; text-align: left; font-weight: bold; }
        td.item-name { white-space: nowrap; overflow: hidden; text-overflow: clip; text-transform: uppercase; word-break: normal; letter-spacing: normal; font-family: "Courier New", "Lucida Console", monospace; font-size: 0.8em; font-weight: normal; text-align: left; line-height: 1.25; }
        td.col-qty { text-align: center; font-weight: normal; font-size: 0.9em; line-height: 1.25; }
        td.col-price { text-align: right; font-weight: normal; font-size: 0.9em; line-height: 1.25; }
        td.col-total { text-align: right; font-weight: normal; font-size: 0.9em; line-height: 1.25; }
        .totals-table { margin-top: 2mm; }
        .totals-table td { padding: 0.6mm 0.5mm; }
        .total-row td { border-top: 2px solid #000; font-weight: bold; padding-top: 1.2mm; font-size: 1.15em; }
        .customer-info { text-align: ${headerAlignment}; border: 1px solid #ccc; padding: 2mm; margin: 2mm 0; background: #fafafa; font-size: 0.85em; }
        .customer-info-title { font-weight: bold; border-bottom: 1px solid #ddd; padding-bottom: 1mm; margin-bottom: 1mm; }
        .footer { text-align: center; font-size: 0.9em; margin-top: 4mm; line-height: 1.4em; }
        hr { border: none; border-top: 2px dashed #000; margin: 2.5mm 0; }
        .receipt-logo-container { text-align: ${headerAlignment}; margin-bottom: 3mm; }
        .receipt-logo { max-width: 50mm; max-height: 20mm; display: inline-block; }
        .offline-badge { text-align: center; background: #fef3c7; color: #92400e; padding: 2mm; margin-bottom: 2mm; font-size: 0.8em; border-radius: 2mm; }
      </style>
    </head>
    <body>
      <div class="receipt">
        ${receiptLogo ? `<div class="receipt-logo-container"><img src="${receiptLogo}" class="receipt-logo" alt="Logo"></div>` : ''}

        <h2>${escapeHtml(storeName).replace(/\n/g, '<br>')}</h2>

        <div class="store-info">
          ${businessName ? `<div class="business-name">${escapeHtml(businessName)}</div>` : ''}
          ${cifNif ? `<div class="cif-nif">CIF/NIF: ${escapeHtml(cifNif)}</div>` : ''}
          ${storePhone ? `<div class="phone">Tel: ${escapeHtml(storePhone)}</div>` : ''}
          ${storeAddress ? `<div class="address">${escapeHtml(storeAddress)}</div>` : ''}
        </div>

        <div class="date-line">Fecha: ${orderDate} ${orderTime}</div>

        <div class="verifactu-invoice-number" style="text-align: center; font-weight: bold;">
          FACTURA SIMPLIFICADA: ${escapeHtml(invoiceNumber)}
        </div>

        <div class="customer-info">
          <div class="customer-info-title"><?php echo ruiyi_translate('Datos del Cliente', 'Customer Details', '客户信息'); ?></div>
          ${customerName ? `<div>Cliente: ${escapeHtml(customerName)}</div>` : ''}
          ${customerPhone ? `<div>Teléfono: ${escapeHtml(customerPhone)}</div>` : ''}
          ${companyName ? `<div>Nombre del Negocio: ${escapeHtml(companyName)}</div>` : ''}
          ${taxId ? `<div>CIF/NIF: ${escapeHtml(taxId)}</div>` : ''}
          ${address ? `<div>Dirección: ${escapeHtml(address)}</div>` : ''}
        </div>

        <hr>

        <table>
          <thead>
            <tr>
              <th style="text-align: left;">Artículo</th>
              <th style="text-align: center;">Ud.</th>
              <th style="text-align: right;">P.U.</th>
              <th style="text-align: right;">Total</th>
            </tr>
          </thead>
          <tbody>
            ${itemsHtml}
          </tbody>
        </table>

        <hr>

        <table class="totals-table">
          <tr>
            <td>Base Imponible:</td>
            <td style="text-align: right;">${totalBeforeTax.toFixed(2)}€</td>
          </tr>
          <tr>
            <td>${receiptTaxLabel}</td>
            <td style="text-align: right;">${taxAmount.toFixed(2)}€</td>
          </tr>
          <tr class="total-row">
            <td>TOTAL:</td>
            <td style="text-align: right;">${orderTotal.toFixed(2)}€</td>
          </tr>
        </table>

        ${notes ? `<div style="margin-top: 2mm; padding: 2mm; background: #fff3cd; font-size: 0.8em;"><strong>Notas:</strong> ${escapeHtml(notes)}</div>` : ''}

        <div class="footer">
          <p>Gracias por su visita</p>
          <p style="font-size: 0.75em; color: #666;">Impreso: ${new Date().toLocaleString()}</p>
        </div>
      </div>
    </body>
    </html>
  `;

  return html;
}

// 打印发票
function printInvoice(orderId, customerData) {
  // 🔥 检测是否离线
  const isOnline = navigator.onLine && window.RUIYI_POS?.isOnline !== false;

  if (!isOnline) {
    // 🔥 离线模式：使用本地生成的发票HTML直接打印
    console.log('[开票] 离线模式 - 使用本地生成发票');

    if (!currentInvoiceOrderData) {
      Swal.fire({
        icon: 'error',
        title: '<?php echo ruiyi_translate('Error', 'Error', '错误'); ?>',
        text: '<?php echo ruiyi_translate('Datos del pedido no disponibles', 'Order data not available', '订单数据不可用'); ?>'
      });
      return;
    }

    try {
      // 生成离线发票HTML
      const invoiceHtml = generateInvoiceHTMLOffline(currentInvoiceOrderData, customerData);

      // 使用CLODOP打印
      if (typeof ruiyiUnifiedPrint === 'function') {
        ruiyiUnifiedPrint(invoiceHtml, 'invoice_offline');

        Toastify({
          text: '<?php echo ruiyi_translate('Factura enviada a impresora (offline)', 'Invoice sent to printer (offline)', '发票已发送到打印机（离线模式）'); ?>',
          duration: 3000,
          gravity: "top",
          position: "center",
          style: { background: "#10b981" }
        }).showToast();
      } else {
        // 备用：浏览器打印
        const printWindow = window.open('', '_blank');
        if (printWindow) {
          printWindow.document.write(invoiceHtml);
          printWindow.document.close();
          printWindow.print();
        }
      }
    } catch (error) {
      console.error('[开票] 离线打印发票失败:', error);
      Swal.fire({
        icon: 'error',
        title: '<?php echo ruiyi_translate('Error', 'Error', '错误'); ?>',
        text: error.message
      });
    }
    return;
  }

  // 🔥 在线模式：调用后端API
  Swal.fire({
    title: '<?php echo ruiyi_translate('Generando factura...', 'Generating invoice...', '生成发票中...'); ?>',
    allowOutsideClick: false,
    didOpen: () => { Swal.showLoading(); }
  });

  // 调用后端API生成并打印发票
  fetch(ajaxUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      action: 'ruiyi_print_invoice',
      order_id: orderId,
      customer_name: customerData.name,
      customer_phone: customerData.phone,
      company_name: customerData.company_name,
      tax_id: customerData.tax_id,
      address: customerData.address,
      notes: customerData.notes,
      nonce: ajaxNonce
    })
  })
  .then(response => response.json())
  .then(data => {
    Swal.close();

    if (data.success && data.data && data.data.receipt_html) {
      // 使用统一打印函数（和打印历史订单一样）
      if (typeof ruiyiUnifiedPrint !== 'undefined') {
        ruiyiUnifiedPrint(data.data.receipt_html, 'invoice_print');

        Toastify({
          text: '<?php echo ruiyi_translate('Factura enviada a impresora', 'Invoice sent to printer', '发票已发送到打印机'); ?>',
          duration: 3000,
          gravity: "top",
          position: "center",
          style: { background: "#10b981" }
        }).showToast();

        // 打印发票时输入的客户信息会在后端同步到客户管理；这里刷新列表，避免用户看到旧数据。
        if (window.customerManagement && typeof window.customerManagement.loadCustomers === 'function') {
          window.customerManagement.loadCustomers();
        }

        // 刷新订单列表
        if (typeof loadOrderHistory === 'function') {
          loadOrderHistory(true);
        }
      } else {
        throw new Error('<?php echo ruiyi_translate('Función de impresión no disponible', 'Print function not available', '打印功能不可用'); ?>');
      }
    } else {
      throw new Error(data.data?.message || '<?php echo ruiyi_translate('Error al generar factura', 'Error generating invoice', '生成发票失败'); ?>');
    }
  })
  .catch(error => {
    Swal.close();
    console.error('打印发票失败:', error);
    Swal.fire({
      icon: 'error',
      title: '<?php echo ruiyi_translate('Error', 'Error', '错误'); ?>',
      text: error.message
    });
  });
}

