// Función para inicializar la sección de ajustes
function initSettingsSection() {

  // 🔥 修复：不再隐藏打印选项卡，用户需要在设置中配置自动打印
  // const printTab = document.getElementById('print-tab');
  const paymentTab = document.getElementById('payment-tab');

  // 🔥 保留打印选项卡显示，只隐藏支付方式选项卡
  // if (printTab) {
  //   printTab.style.display = 'none';
  // }

  if (paymentTab) {
    paymentTab.style.display = 'none';
  }

  // 初始化快捷键设置的"+"符号显示
  const modifierSelect = document.getElementById('drawer_shortcut_modifier');
  if (modifierSelect) {
      // 强制设置为'none'如果当前值是'ctrl'或空
      if (!modifierSelect.value || modifierSelect.value === 'ctrl') {
          modifierSelect.value = 'none';
      }

      // 初始设置"+"符号的显示状态
      const currentModifier = modifierSelect.value || 'none';
      updatePlusSignVisibility(currentModifier);

      // 监听修饰符选择变化
      modifierSelect.addEventListener('change', function() {
          updatePlusSignVisibility(this.value);
      });
  }

  // 函数：根据修饰符显示/隐藏"+"符号
  function updatePlusSignVisibility(selectedModifier) {
      const plusSign = document.getElementById('shortcut-plus-sign');
      if (plusSign) {
          if (selectedModifier === 'none') {
              plusSign.style.display = 'none';
          } else {
              plusSign.style.display = 'inline';
          }
      }
  }

  // 🔥 分类列数滑块实时更新
  const categoryColumnsRange = document.getElementById('category-columns-range');
  const categoryColumnsDisplay = document.getElementById('category-columns-display');

  if (categoryColumnsRange && categoryColumnsDisplay) {
      // 实时更新数字显示
      categoryColumnsRange.addEventListener('input', function() {
          categoryColumnsDisplay.textContent = this.value;
      });
  }

  // 🔥 分类字体大小滑块实时更新
  const categoryFontSizeRange = document.getElementById('category-font-size-range');
  const categoryFontSizeDisplay = document.getElementById('category-font-size-display');

  if (categoryFontSizeRange && categoryFontSizeDisplay) {
      // 实时更新数字显示
      categoryFontSizeRange.addEventListener('input', function() {
          categoryFontSizeDisplay.textContent = this.value + 'px';
      });
  }

  // 🔥 产品每行数量滑块实时更新
  const productsPerRowRange = document.getElementById('products-per-row-range');
  const productsPerRowDisplay = document.getElementById('products-per-row-display');

  if (productsPerRowRange && productsPerRowDisplay) {
      // 实时更新数字显示
      productsPerRowRange.addEventListener('input', function() {
          productsPerRowDisplay.textContent = this.value;
      });
  }

  // 🔥 界面显示选项卡 - 分类列数滑块
  const categoryColumnsRangeDisplay = document.getElementById('category-columns-range-display');
  const categoryColumnsDisplayTab = document.getElementById('category-columns-display-tab');

  if (categoryColumnsRangeDisplay && categoryColumnsDisplayTab) {
      categoryColumnsRangeDisplay.addEventListener('input', function() {
          categoryColumnsDisplayTab.textContent = this.value;
      });
  }

  // 🔥 界面显示选项卡 - 桌位每行数量滑块
  const tablesPerRowRange = document.getElementById('tables-per-row-range');
  const tablesPerRowDisplay = document.getElementById('tables-per-row-display');

  if (tablesPerRowRange && tablesPerRowDisplay) {
      tablesPerRowRange.addEventListener('input', function() {
          const value = parseInt(this.value);
          tablesPerRowDisplay.textContent = value;
          // 🔥 更新全局配置
          window.RUIYI_POS_CONFIG = window.RUIYI_POS_CONFIG || {};
          window.RUIYI_POS_CONFIG.tablesPerRow = value;
          // 🔥 实时更新CSS变量，立即生效
          document.documentElement.style.setProperty('--tables-per-row', value);
      });
  }

  // 🔥 界面显示选项卡 - 桌位字体大小滑块
  const tableFontSizeRange = document.getElementById('table-font-size-range');
  const tableFontSizeDisplay = document.getElementById('table-font-size-display');

  if (tableFontSizeRange && tableFontSizeDisplay) {
      tableFontSizeRange.addEventListener('input', function() {
          const value = parseInt(this.value);
          tableFontSizeDisplay.textContent = value + 'px';
          // 🔥 更新全局配置
          window.RUIYI_POS_CONFIG = window.RUIYI_POS_CONFIG || {};
          window.RUIYI_POS_CONFIG.tableFontSize = value;
          // 🔥 实时更新CSS变量，立即生效
          document.documentElement.style.setProperty('--table-font-size', value + 'px');
      });
  }

  // 🔥 日结单模式开关
  const settlementToggle = document.getElementById('settlement-mode-toggle');
  const settlementHidden = document.getElementById('settlement-mode-hidden');
  if (settlementToggle && settlementHidden) {
    settlementToggle.addEventListener('change', function() {
      const isAuto = this.checked;
      settlementHidden.value = isAuto ? 'auto' : 'manual';
      // 同步第二个开关
      const toggle2 = document.getElementById('settlement-mode-toggle-2');
      if (toggle2) toggle2.checked = isAuto;
    });
  }
  // 第二个开关同步到第一个
  const settlementToggle2 = document.getElementById('settlement-mode-toggle-2');
  if (settlementToggle2) {
    settlementToggle2.addEventListener('change', function() {
      const isAuto = this.checked;
      if (settlementHidden) settlementHidden.value = isAuto ? 'auto' : 'manual';
      if (settlementToggle) settlementToggle.checked = isAuto;
    });
  }

  // 🔥 界面显示选项卡 - 产品每行数量滑块
  const productsPerRowRangeDisplay = document.getElementById('products-per-row-range-display');
  const productsPerRowDisplayTab = document.getElementById('products-per-row-display-tab');

  if (productsPerRowRangeDisplay && productsPerRowDisplayTab) {
