  // 🔥 界面显示选项卡 - 分类字体大小滑块
  const categoryFontSizeRangeDisplay = document.getElementById('category-font-size-range-display');
  const categoryFontSizeDisplayTab = document.getElementById('category-font-size-display-tab');

  if (categoryFontSizeRangeDisplay && categoryFontSizeDisplayTab) {
