  }

  // 🔥 界面显示选项卡 - 分类字体加粗开关
  const categoryBoldToggle = document.getElementById('category-bold-toggle');
  if (categoryBoldToggle) {
      categoryBoldToggle.addEventListener('change', function() {
          const isBold = this.checked;
          const weight = isBold ? '700' : '500';
          const className = isBold ? 'font-bold' : 'font-medium';
          // 实时更新加粗预览
          document.querySelectorAll('[id^="category-bold-preview-"]').forEach(el => {
