  // 🔥 界面显示选项卡 - 产品名称字体大小滑块
  const productNameFontSizeRange = document.getElementById('product-name-font-size-range');
  const productNameFontSizeDisplay = document.getElementById('product-name-font-size-display');

  if (productNameFontSizeRange && productNameFontSizeDisplay) {
