  const priceFontSizeDisplay = document.getElementById('product-price-font-size-display');
  const pricePreview = document.getElementById('price-preview');

  if (priceFontSizeRange && priceFontSizeDisplay) {
      priceFontSizeRange.addEventListener('input', function() {
          const size = this.value;
          priceFontSizeDisplay.textContent = size + 'px';
          // 实时更新预览
          if (pricePreview) {
              pricePreview.style.fontSize = size + 'px';
          }
          // 🔥 更新CSS变量，确保覆盖!important规则
          document.documentElement.style.setProperty('--product-price-font-size', size + 'px');
      });
  }

  // 🔥 界面显示选项卡 - 产品图片高度滑块
  const productImageRatioRange = document.getElementById('product-image-ratio-range');
  const productImageRatioDisplay = document.getElementById('product-image-ratio-display');

  if (productImageRatioRange && productImageRatioDisplay) {
      productImageRatioRange.addEventListener('input', function() {
          const ratio = this.value;
          productImageRatioDisplay.textContent = ratio + '%';
          // 🔥 更新CSS变量，实时调整有图片产品卡片中图片的占比
          document.documentElement.style.setProperty('--product-image-ratio', ratio + '%');
      });
  }

  // 🔥 产品亮色/暗色模式切换预览
  const productLightModeToggle = document.getElementById('pos-product-light-mode-toggle');
  const productModePreview = document.getElementById('product-mode-preview');
  const productModePreviewName = document.getElementById('product-mode-preview-name');

  if (productLightModeToggle && productModePreview) {
      productLightModeToggle.addEventListener('change', function() {
          const isLightMode = this.checked;
          if (isLightMode) {
              // 亮色模式：白色背景，黑色产品名称，价格保持黄色
              productModePreview.classList.remove('bg-gray-800');
              productModePreview.classList.add('bg-white', 'border', 'border-gray-300');
              if (productModePreviewName) {
                  productModePreviewName.classList.remove('text-white');
                  productModePreviewName.classList.add('text-gray-800');
              }
          } else {
              // 暗色模式：深色背景，白色产品名称，价格保持黄色
              productModePreview.classList.remove('bg-white', 'border', 'border-gray-300');
              productModePreview.classList.add('bg-gray-800');
              if (productModePreviewName) {
                  productModePreviewName.classList.remove('text-gray-800');
                  productModePreviewName.classList.add('text-white');
              }
          }
      });
  }

  // 🔥 桌位状态颜色选择器（背景色+字体颜色）
  function initTableColorPickers() {
    const colorTypes = ['free', 'occupied', 'settling'];

    colorTypes.forEach(type => {
      // 背景颜色
      const bgColorInput = document.getElementById(`table-color-${type}`);
      const bgTextInput = document.getElementById(`table-color-${type}-text`);
      // 字体颜色
      const textColorInput = document.getElementById(`table-text-color-${type}`);
      const textColorTextInput = document.getElementById(`table-text-color-${type}-text`);
      // 预览
      const preview = document.getElementById(`table-color-${type}-preview`);

      // 背景颜色选择器
      if (bgColorInput && bgTextInput && preview) {
        bgColorInput.addEventListener('input', function() {
          bgTextInput.value = this.value;
          preview.style.backgroundColor = this.value;
        });

        bgTextInput.addEventListener('input', function() {
          if (/^#[0-9A-Fa-f]{6}$/.test(this.value)) {
            bgColorInput.value = this.value;
            preview.style.backgroundColor = this.value;
          }
        });

        bgTextInput.addEventListener('blur', function() {
          if (!/^#[0-9A-Fa-f]{6}$/.test(this.value)) {
            this.value = bgColorInput.value;
          }
        });
      }

      // 字体颜色选择器
      if (textColorInput && textColorTextInput && preview) {
        textColorInput.addEventListener('input', function() {
          textColorTextInput.value = this.value;
          preview.style.color = this.value;
        });

        textColorTextInput.addEventListener('input', function() {
          if (/^#[0-9A-Fa-f]{6}$/.test(this.value)) {
            textColorInput.value = this.value;
            preview.style.color = this.value;
          }
        });

        textColorTextInput.addEventListener('blur', function() {
          if (!/^#[0-9A-Fa-f]{6}$/.test(this.value)) {
            this.value = textColorInput.value;
          }
        });
      }
    });
  }

  // 重置桌位颜色（背景+字体）
  window.resetTableColorFull = function(type, defaultBgColor, defaultTextColor) {
    const bgColorInput = document.getElementById(`table-color-${type}`);
    const bgTextInput = document.getElementById(`table-color-${type}-text`);
    const textColorInput = document.getElementById(`table-text-color-${type}`);
    const textColorTextInput = document.getElementById(`table-text-color-${type}-text`);
    const preview = document.getElementById(`table-color-${type}-preview`);

    if (bgColorInput && bgTextInput) {
      bgColorInput.value = defaultBgColor;
      bgTextInput.value = defaultBgColor;
    }
    if (textColorInput && textColorTextInput) {
      textColorInput.value = defaultTextColor;
      textColorTextInput.value = defaultTextColor;
    }
    if (preview) {
      preview.style.backgroundColor = defaultBgColor;
      preview.style.color = defaultTextColor;
    }
  };

  // 初始化颜色选择器
  initTableColorPickers();

  // ====== 🔥 桌位分区管理 ======
  (function() {
    const ajaxUrlZone = '<?php echo admin_url("admin-ajax.php"); ?>';
    const nonceZone = '<?php echo wp_create_nonce("ruiyi_pos_nonce"); ?>';
    const existingCustomNames = <?php echo json_encode(get_option('pos_custom_table_names', new stdClass())); ?>;
    let zoneData = { categories: [], mappings: [] };

    // HTML转义辅助
    function escHtml(str) {
      const d = document.createElement('div');
      d.textContent = str || '';
      return d.innerHTML;
    }

    // 翻译辅助
    const ZT = {
      tables: '<?php echo ruiyi_translate("mesas", "tables", "桌位"); ?>',
      tableName: '<?php echo ruiyi_translate("Nombre de mesa", "Table name", "桌位名称"); ?>',
      default: '<?php echo ruiyi_translate("Por defecto", "Default", "默认"); ?>',
      expand: '<?php echo ruiyi_translate("Expandir", "Expand", "展开"); ?>',
      collapse: '<?php echo ruiyi_translate("Contraer", "Collapse", "收起"); ?>',
      delete: '<?php echo ruiyi_translate("Eliminar", "Delete", "删除"); ?>',
      confirmDeleteZone: '<?php echo ruiyi_translate("¿Eliminar esta zona y todas sus mesas?", "Delete this zone and all its tables?", "确认删除该分区及其所有桌位？"); ?>',
      createZone: '<?php echo ruiyi_translate("Crear Zona", "Create Zone", "创建分区"); ?>',
      zoneName: '<?php echo ruiyi_translate("Nombre de zona", "Zone name", "分区名称"); ?>',
      zoneNameEs: '<?php echo ruiyi_translate("Nombre (ES)", "Name (ES)", "名称(西)"); ?>',
      zoneNameEn: '<?php echo ruiyi_translate("Nombre (EN)", "Name (EN)", "名称(英)"); ?>',
      zoneNameZh: '<?php echo ruiyi_translate("Nombre (ZH)", "Name (ZH)", "名称(中)"); ?>',
      tableCount: '<?php echo ruiyi_translate("Número de mesas", "Number of tables", "桌位数量"); ?>',
      color: '<?php echo ruiyi_translate("Color", "Color", "颜色"); ?>',
      delivery: '<?php echo ruiyi_translate("Zona de entrega", "Delivery zone", "外送区域"); ?>',
      saved: '<?php echo ruiyi_translate("Guardado", "Saved", "已保存"); ?>',
      saving: '<?php echo ruiyi_translate("Guardando...", "Saving...", "保存中..."); ?>',
      error: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
      cancel: '<?php echo ruiyi_translate("Cancelar", "Cancel", "取消"); ?>',
      create: '<?php echo ruiyi_translate("Crear", "Create", "创建"); ?>',
      addTables: '<?php echo ruiyi_translate("Añadir mesas", "Add tables", "添加桌位"); ?>',
      removeTables: '<?php echo ruiyi_translate("Quitar mesas", "Remove tables", "减少桌位"); ?>',
    };

    // 加载分区和映射数据
    window.loadZoneManagement = function() {
      const container = document.getElementById('zone-management-list');
      if (!container) return;

      Promise.all([
        fetch(ajaxUrlZone, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({ action: 'ruiyi_get_table_categories', nonce: nonceZone })
        }).then(r => r.json()),
        fetch(ajaxUrlZone, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({ action: 'ruiyi_get_table_mappings', nonce: nonceZone })
        }).then(r => r.json())
      ]).then(([catRes, mapRes]) => {
        const categories = (catRes.success && catRes.data.categories) ? catRes.data.categories.filter(c => c.id !== 'all') : [];
        const mappings = (mapRes.success && mapRes.data.mappings) ? (Array.isArray(mapRes.data.mappings) ? mapRes.data.mappings : Object.values(mapRes.data.mappings)) : [];
        zoneData = { categories, mappings };
        renderZoneList(container, categories, mappings);
      }).catch(err => {
        console.error('Zone management load error:', err);
        container.innerHTML = '<p class="text-red-500 text-sm">Error loading zones</p>';
      });
    };

    function renderZoneList(container, categories, mappings) {
      if (categories.length === 0) {
        container.innerHTML = `<div class="text-center py-8 text-gray-400 dark:text-gray-500">
          <i class="fas fa-inbox text-3xl mb-2"></i>
          <p class="text-sm"><?php echo ruiyi_translate('No hay zonas configuradas. Cree una zona para empezar.', 'No zones configured. Create a zone to get started.', '暂无分区，请创建一个分区。'); ?></p>
        </div>`;
        document.getElementById('zone-save-bar')?.classList.add('hidden');
        return;
      }

      let html = '';
      categories.forEach(cat => {
        const catMappings = mappings.filter(m => parseInt(m.category_id) === parseInt(cat.id));
        const tableCount = catMappings.length;
        const catColor = cat.color || '#6B7280';
        const catName = cat.display_name || cat.name;
        const isDelivery = parseInt(cat.delivery_enabled) === 1;

        html += `<div class="border border-gray-200 dark:border-gray-600 rounded-lg overflow-hidden" data-zone-id="${cat.id}">
          <div class="flex items-center justify-between px-4 py-3 bg-gray-50 dark:bg-gray-700 cursor-pointer" onclick="toggleZoneTables(${cat.id})">
            <div class="flex items-center gap-3">
              <span class="w-4 h-4 rounded-full inline-block" style="background-color: ${catColor}"></span>
              <span class="font-medium text-gray-800 dark:text-gray-200">${escHtml(catName)}</span>
              ${isDelivery ? '<span class="text-xs bg-yellow-100 text-yellow-700 px-2 py-0.5 rounded">' + ZT.delivery + '</span>' : ''}
              <span class="text-xs text-gray-500">${tableCount} ${ZT.tables}</span>
            </div>
            <div class="flex items-center gap-2">
              <button type="button" onclick="event.stopPropagation(); addTablesToZone(${cat.id})" title="${ZT.addTables}"
                      class="px-2 py-1 text-xs bg-green-100 hover:bg-green-200 text-green-700 rounded transition-colors">
                <i class="fas fa-plus"></i>
              </button>
              <button type="button" onclick="event.stopPropagation(); removeTablesFromZone(${cat.id})" title="${ZT.removeTables}"
                      class="px-2 py-1 text-xs bg-orange-100 hover:bg-orange-200 text-orange-700 rounded transition-colors">
                <i class="fas fa-minus"></i>
              </button>
              <button type="button" onclick="event.stopPropagation(); deleteZone(${cat.id}, '${escHtml(catName).replace(/'/g, "&#39;")}')" title="${ZT.delete}"
                      class="px-2 py-1 text-xs bg-red-100 hover:bg-red-200 text-red-700 rounded transition-colors">
                <i class="fas fa-trash"></i>
              </button>
              <i class="fas fa-chevron-down text-gray-400 transition-transform zone-chevron" id="zone-chevron-${cat.id}"></i>
            </div>
          </div>
          <div class="hidden px-4 py-3 bg-white dark:bg-gray-800 border-t border-gray-200 dark:border-gray-600" id="zone-tables-${cat.id}">
            ${renderZoneTables(cat, catMappings)}
          </div>
        </div>`;
      });

      container.innerHTML = html;

      // Show save bar if any categories have tables
      const hasTables = mappings.length > 0;
      document.getElementById('zone-save-bar')?.classList.toggle('hidden', !hasTables);
    }

    function renderZoneTables(category, catMappings) {
      if (catMappings.length === 0) {
        return `<p class="text-sm text-gray-400 py-2"><?php echo ruiyi_translate('No hay mesas en esta zona', 'No tables in this zone', '该分区暂无桌位'); ?></p>`;
      }

      // Sort by table_number_in_category
      catMappings.sort((a, b) => parseInt(a.table_number_in_category) - parseInt(b.table_number_in_category));

      const catName = category.display_name || category.name;
      let html = '<div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2">';
      catMappings.forEach(mapping => {
        const catId = mapping.category_id;
        const tNum = mapping.table_number_in_category;
        const key = catId + '_' + tNum;
        const defaultName = mapping.category_display_name || (catName + tNum);
        const customName = existingCustomNames[key] || '';
        const displayPlaceholder = defaultName;

        html += `<div class="flex items-center gap-2 p-2 bg-gray-50 dark:bg-gray-700 rounded">
          <span class="text-xs text-gray-500 w-6 text-center font-mono">${tNum}</span>
          <input type="text" class="flex-1 px-2 py-1 text-sm border border-gray-300 dark:border-gray-600 rounded bg-white dark:bg-gray-800 dark:text-gray-200 custom-table-name-input"
                 data-key="${escHtml(key)}" data-default="${escHtml(defaultName)}"
                 placeholder="${escHtml(displayPlaceholder)}" value="${escHtml(customName)}"
                 oninput="onCustomNameInput()">
        </div>`;
      });
      html += '</div>';
      return html;
    }

    window.toggleZoneTables = function(catId) {
      const el = document.getElementById('zone-tables-' + catId);
      const chevron = document.getElementById('zone-chevron-' + catId);
      if (el) {
        el.classList.toggle('hidden');
        chevron?.classList.toggle('rotate-180');
      }
    };

    window.showCreateZoneDialog = function() {
      Swal.fire({
        title: ZT.createZone,
        html: `<div class="text-left space-y-3">
          <div>
            <label class="block text-sm font-medium mb-1">${ZT.zoneNameEs} *</label>
            <input id="swal-zone-name-es" class="w-full px-3 py-2 border rounded" placeholder="Ej: Comedor">
          </div>
          <div>
            <label class="block text-sm font-medium mb-1">${ZT.zoneNameEn}</label>
            <input id="swal-zone-name-en" class="w-full px-3 py-2 border rounded" placeholder="Eg: Dining Room">
          </div>
          <div>
            <label class="block text-sm font-medium mb-1">${ZT.zoneNameZh}</label>
            <input id="swal-zone-name-zh" class="w-full px-3 py-2 border rounded" placeholder="例: 用餐区">
          </div>
          <div>
            <label class="block text-sm font-medium mb-1">${ZT.tableCount} *</label>
            <input id="swal-zone-table-count" type="number" min="1" max="50" value="5" class="w-full px-3 py-2 border rounded">
          </div>
          <div>
            <label class="block text-sm font-medium mb-1">${ZT.color}</label>
            <input id="swal-zone-color" type="color" value="#3B82F6" class="w-12 h-8 rounded cursor-pointer">
          </div>
          <div class="flex items-center gap-2">
            <input id="swal-zone-delivery" type="checkbox" class="w-4 h-4">
            <label class="text-sm">${ZT.delivery}</label>
          </div>
        </div>`,
        showCancelButton: true,
        confirmButtonText: ZT.create,
        cancelButtonText: ZT.cancel,
        confirmButtonColor: '#059669',
        preConfirm: () => {
          const nameEs = document.getElementById('swal-zone-name-es').value.trim();
          const tableCount = parseInt(document.getElementById('swal-zone-table-count').value) || 0;
          if (!nameEs) { Swal.showValidationMessage(ZT.zoneName + ' (ES) required'); return false; }
          if (tableCount < 1 || tableCount > 50) { Swal.showValidationMessage(ZT.tableCount + ': 1-50'); return false; }
          return {
            name: nameEs,
            name_es: nameEs,
            name_en: document.getElementById('swal-zone-name-en').value.trim(),
            name_zh: document.getElementById('swal-zone-name-zh').value.trim(),
            table_count: tableCount,
            color: document.getElementById('swal-zone-color').value,
            delivery_enabled: document.getElementById('swal-zone-delivery').checked ? 1 : 0
          };
        }
      }).then(result => {
        if (!result.isConfirmed) return;
        const d = result.value;
        // Create category
        fetch(ajaxUrlZone, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            action: 'ruiyi_create_category',
            nonce: nonceZone,
            name: d.name, name_es: d.name_es, name_en: d.name_en, name_zh: d.name_zh,
            color: d.color, icon: 'fas fa-th',
            sort_order: zoneData.categories.length + 1,
            delivery_enabled: d.delivery_enabled
          })
        }).then(r => r.json()).then(res => {
          if (res.success) {
            // Add tables to the new category
            const newCatId = res.data.category?.id || res.data.category_id;
            return fetch(ajaxUrlZone, {
              method: 'POST',
              headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
              body: new URLSearchParams({
                action: 'ruiyi_add_tables_to_category',
                nonce: nonceZone,
                category_id: newCatId,
                table_count: d.table_count
              })
            }).then(r => r.json());
          } else {
            throw new Error(res.data?.message || 'Failed to create zone');
          }
        }).then(() => {
          Toastify({ text: '✅ ' + ZT.saved, duration: 2000, gravity: 'top', position: 'center', style: { background: '#059669' } }).showToast();
          loadZoneManagement();
          // Reload table category mappings in main POS
          if (typeof loadTableCategories === 'function') loadTableCategories();
        }).catch(err => {
          Swal.fire(ZT.error, err.message, 'error');
        });
      });
    };

    window.addTablesToZone = function(catId) {
      Swal.fire({
        title: ZT.addTables,
        input: 'number',
        inputAttributes: { min: 1, max: 50 },
        inputValue: 1,
        showCancelButton: true,
        confirmButtonText: ZT.create,
        cancelButtonText: ZT.cancel,
        confirmButtonColor: '#059669'
      }).then(result => {
        if (!result.isConfirmed) return;
        const count = parseInt(result.value) || 1;
        fetch(ajaxUrlZone, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            action: 'ruiyi_add_tables_to_category',
            nonce: nonceZone,
            category_id: catId,
            table_count: count
          })
        }).then(r => r.json()).then(res => {
          if (res.success) {
            Toastify({ text: '✅ ' + ZT.saved, duration: 2000, gravity: 'top', position: 'center', style: { background: '#059669' } }).showToast();
            loadZoneManagement();
            if (typeof loadTableCategories === 'function') loadTableCategories();
          } else {
            Swal.fire(ZT.error, res.data?.message || 'Failed', 'error');
          }
        });
      });
    };

    window.removeTablesFromZone = function(catId) {
      const catMappings = zoneData.mappings.filter(m => parseInt(m.category_id) === catId);
      if (catMappings.length === 0) return;

      Swal.fire({
        title: ZT.removeTables,
        input: 'number',
        inputAttributes: { min: 1, max: catMappings.length },
        inputValue: 1,
        showCancelButton: true,
        confirmButtonText: ZT.delete,
        cancelButtonText: ZT.cancel,
        confirmButtonColor: '#dc2626'
      }).then(result => {
        if (!result.isConfirmed) return;
        const removeCount = Math.min(parseInt(result.value) || 1, catMappings.length);
        const targetCount = catMappings.length - removeCount;
        fetch(ajaxUrlZone, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            action: 'ruiyi_set_category_table_count',
            nonce: nonceZone,
            category_id: catId,
            target_count: targetCount
          })
        }).then(r => r.json()).then(res => {
          if (res.success) {
            Toastify({ text: '✅ ' + ZT.saved, duration: 2000, gravity: 'top', position: 'center', style: { background: '#059669' } }).showToast();
            loadZoneManagement();
            if (typeof loadTableCategories === 'function') loadTableCategories();
          } else {
            Swal.fire(ZT.error, res.data?.message || 'Failed', 'error');
          }
        });
      });
    };

    window.deleteZone = function(catId, catName) {
      Swal.fire({
        title: ZT.confirmDeleteZone,
        text: catName,
        icon: 'warning',
        showCancelButton: true,
        confirmButtonText: ZT.delete,
        cancelButtonText: ZT.cancel,
        confirmButtonColor: '#dc2626'
      }).then(result => {
        if (!result.isConfirmed) return;
        fetch(ajaxUrlZone, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            action: 'ruiyi_delete_category',
            nonce: nonceZone,
            category_id: catId
          })
        }).then(r => r.json()).then(res => {
          if (res.success) {
            // Clean up custom names for this zone and persist to server
            let hadCustomNames = false;
            Object.keys(existingCustomNames).forEach(key => {
              if (key.startsWith(catId + '_')) { delete existingCustomNames[key]; hadCustomNames = true; }
            });
            if (hadCustomNames) {
              fetch(ajaxUrlZone, {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: new URLSearchParams({ action: 'ruiyi_save_custom_table_names', nonce: nonceZone, custom_names: JSON.stringify(existingCustomNames) })
              }).catch(() => {});
            }
            Toastify({ text: '✅ ' + ZT.saved, duration: 2000, gravity: 'top', position: 'center', style: { background: '#059669' } }).showToast();
            loadZoneManagement();
            if (typeof loadTableCategories === 'function') loadTableCategories();
          } else {
            Swal.fire(ZT.error, res.data?.message || 'Failed', 'error');
          }
        });
      });
    };

    window.onCustomNameInput = function() {
      // Just mark that there are unsaved changes
      const saveBar = document.getElementById('zone-save-bar');
      if (saveBar) saveBar.classList.remove('hidden');
    };

    window.saveCustomTableNames = function() {
      const inputs = document.querySelectorAll('.custom-table-name-input');
      const names = {};
      inputs.forEach(input => {
        const key = input.dataset.key;
        const val = input.value.trim();
        if (val) names[key] = val;
      });

      const btn = document.getElementById('btn-save-custom-names');
      if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin mr-1"></i>' + ZT.saving; }

      fetch(ajaxUrlZone, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          action: 'ruiyi_save_custom_table_names',
          nonce: nonceZone,
          custom_names: JSON.stringify(names)
        })
      }).then(r => r.json()).then(res => {
        if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-save mr-1"></i><?php echo ruiyi_translate("Guardar nombres personalizados", "Save custom names", "保存自定义名称"); ?>'; }
        if (res.success) {
          // Update local cache
          Object.keys(existingCustomNames).forEach(k => delete existingCustomNames[k]);
          Object.assign(existingCustomNames, names);
          Toastify({ text: '✅ ' + ZT.saved, duration: 2000, gravity: 'top', position: 'center', style: { background: '#059669' } }).showToast();
          // Reload mappings so POS picks up new names
          if (typeof loadTableCategories === 'function') loadTableCategories();
        } else {
          Swal.fire(ZT.error, res.data?.message || 'Failed to save', 'error');
        }
      }).catch(err => {
        if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-save mr-1"></i><?php echo ruiyi_translate("Guardar nombres personalizados", "Save custom names", "保存自定义名称"); ?>'; }
        Swal.fire(ZT.error, err.message, 'error');
      });
    };

    // Auto-load when display settings tab is shown
    const displayTabBtn = document.getElementById('display-tab');
    if (displayTabBtn) {
      displayTabBtn.addEventListener('click', function() {
        setTimeout(loadZoneManagement, 100);
      });
    }
  })();

  // Verificar si hay mensaje de configuración guardada
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.has('settings_saved')) {
      Toastify({
      text: "✅ <?php echo ruiyi_translate("La configuración se ha guardado correctamente", "The configuration has been saved correctly", "配置已保存成功"); ?>",
      duration: 3000,
        gravity: "top",
        position: "center",
      style: {
        background: "#4CAF50"
      }
      }).showToast();
      
    // Limpiar la URL para evitar mostrar el mensaje al recargar
    const newUrl = window.location.pathname + window.location.hash;
    window.history.replaceState({}, document.title, newUrl);
  }
  
  // Configurar pestañas de ajustes
  const settingsTabs = document.querySelectorAll('.settings-tab-btn');
  const settingsContents = document.querySelectorAll('.settings-content');
  
  if (settingsTabs && settingsContents) {
    settingsTabs.forEach(tab => {
      tab.addEventListener('click', function() {
        // Desactivar所有的 pestañas
        settingsTabs.forEach(t => {
          t.classList.remove('border-primary', 'text-primary');
          t.classList.add('border-transparent', 'text-gray-500', 'dark:text-gray-400');
        });
        
        // Activar la pestaña actual
        this.classList.add('border-primary', 'text-primary');
        this.classList.remove('border-transparent', 'text-gray-500', 'dark:text-gray-400');
        
        // Ocultar todos los contenidos
        settingsContents.forEach(content => {
          content.classList.add('hidden');
        });
        
        // 修复：正确映射ID关系
        let contentId = '';

        if (this.id === 'general-tab') {
          contentId = 'general-settings';
        } else if (this.id === 'users-tab') {
          contentId = 'users-settings';
        } else {
          // 备用方案：尝试常规替换
          contentId = this.id.replace('-tab', '-settings');
        }
        
        const contentElement = document.getElementById(contentId);
        if (contentElement) {
          contentElement.classList.remove('hidden');
        } else {
          console.error("找不到对应的内容区域:", contentId);
        }
      });
    });
    
    // 初始化时保证General选项卡处于激活状态
    const generalTab = document.getElementById('general-tab');
    if(generalTab) {
      generalTab.click();
    }
  }
  
  // Validar formularios antes de enviarlos
  const generalSettingsForm = document.getElementById('general-settings-form');
  if (generalSettingsForm) {
    generalSettingsForm.addEventListener('submit', function(e) {
      // Sincronizar valores de atajos desde localStorage al formulario
      const modifierSelect = document.getElementById('drawer_shortcut_modifier');
      const keyInput = document.getElementById('drawer_shortcut_key');

      if (modifierSelect && keyInput) {
        // Obtener valores de localStorage
        const savedModifier = localStorage.getItem('drawer_shortcut_modifier');
        const savedKey = localStorage.getItem('drawer_shortcut_key');

        // Actualizar valores en el formulario si existen en localStorage
        if (savedModifier) {
          modifierSelect.value = savedModifier;
        }
        if (savedKey) {
          keyInput.value = savedKey;
        }
      }

      // Mostrar indicador de guardado
      Toastify({
        text: "<?php echo ruiyi_translate("Guardando configuración", "Saving configuration", "保存配置"); ?>...",
        duration: 2000,
        gravity: "top",
        position: "center",
        style: {
          background: "#3b82f6"
        }
      }).showToast();

      // Recargar página después de guardar para aplicar cambios de atajos
      setTimeout(() => {
        window.location.reload();
      }, 2500);
    });
  }
  
  // 🔥 统一表单提交处理
  const unifiedSettingsForm = document.getElementById('unified-settings-form');
  if (unifiedSettingsForm) {
    unifiedSettingsForm.addEventListener('submit', function(e) {
      // Mostrar indicador de guardado
      Toastify({
        text: "<?php echo ruiyi_translate("Guardando todos los ajustes", "Saving all settings", "保存所有设置"); ?>...",
        duration: 3000,
        gravity: "top",
        position: "center",
        style: {
          background: "#3b82f6"
        }
      }).showToast();
    });
  }

  // Logo上传功能 - 使用文件上传方式
  const logoFileInput = document.getElementById('receipt-logo-file-input');
  const removeLogoBtn = document.getElementById('remove-receipt-logo-btn');
  const logoPreview = document.getElementById('receipt-logo-preview');
  const logoInput = document.getElementById('pos_receipt_logo');

  if (logoFileInput) {
    logoFileInput.addEventListener('change', async function(e) {
      const file = e.target.files[0];
      if (!file) return;

      // 验证文件类型
      const allowedTypes = ['image/png', 'image/jpeg', 'image/gif', 'image/webp'];
      if (!allowedTypes.includes(file.type)) {
        Toastify({
          text: '<?php echo ruiyi_translate("Solo se permiten imágenes PNG, JPG, GIF o WebP", "Only PNG, JPG, GIF or WebP images allowed", "只允许PNG、JPG、GIF或WebP格式的图片"); ?>',
          duration: 3000,
          gravity: "top",
          position: "center",
          style: { background: "#ef4444" }
        }).showToast();
        return;
      }

      // 验证文件大小 (最大5MB，保留更高分辨率原图以提升热敏打印清晰度)
      if (file.size > 5 * 1024 * 1024) {
        Toastify({
          text: '<?php echo ruiyi_translate("El archivo es demasiado grande (máx 5MB)", "File is too large (max 5MB)", "文件太大（最大5MB）"); ?>',
          duration: 3000,
          gravity: "top",
          position: "center",
          style: { background: "#ef4444" }
        }).showToast();
        return;
      }

      // 显示上传中状态
      logoPreview.innerHTML = '<i class="fas fa-spinner fa-spin text-blue-500"></i>';

      try {
        // 使用FormData上传文件
        const formData = new FormData();
        formData.append('action', 'ruiyi_upload_receipt_logo');
        formData.append('logo_file', file);
        formData.append('nonce', ajaxNonce);

        const response = await fetch(ajaxUrl, {
          method: 'POST',
          body: formData
        });

        const result = await response.json();

        if (result.success && result.data.url) {
          logoInput.value = result.data.url;
          logoPreview.innerHTML = `<img src="${result.data.url}" class="max-w-full max-h-full object-contain">`;
          removeLogoBtn.classList.remove('hidden');
          const logoWidth = parseInt(result.data.width || 0, 10) || 0;
          const logoHeight = parseInt(result.data.height || 0, 10) || 0;
          if (window.clodopConfig) {
            window.clodopConfig.receiptLogoWidth = logoWidth;
            window.clodopConfig.receiptLogoHeight = logoHeight;
          }
          if (window.RUIYI_POS_CONFIG?.storeInfo) {
            window.RUIYI_POS_CONFIG.storeInfo.receiptLogo = result.data.url;
            window.RUIYI_POS_CONFIG.storeInfo.receiptLogoWidth = logoWidth;
            window.RUIYI_POS_CONFIG.storeInfo.receiptLogoHeight = logoHeight;
          }
          if (window.LogoCache?.clear) {
            window.LogoCache.clear();
          }
          if (window.LogoCache?.cacheLogoAsBase64) {
            await window.LogoCache.cacheLogoAsBase64(result.data.url);
          }
          if (typeof updateReceiptPreview === 'function') updateReceiptPreview();

          Toastify({
            text: '<?php echo ruiyi_translate("Logo subido correctamente. Recuerda guardar la configuración.", "Logo uploaded successfully. Remember to save settings.", "Logo上传成功，请记得保存设置。"); ?>',
            duration: 3000,
            gravity: "top",
            position: "center",
            style: { background: "#22c55e" }
          }).showToast();
        } else {
          throw new Error(result.data?.message || 'Upload failed');
        }
      } catch (error) {
        console.error('Logo upload error:', error);
        logoPreview.innerHTML = `<span class="text-gray-400 dark:text-gray-500 text-xs"><?php echo ruiyi_translate("Sin Logo", "No Logo", "无Logo"); ?></span>`;

        Toastify({
          text: '<?php echo ruiyi_translate("Error al subir el logo", "Error uploading logo", "上传Logo失败"); ?>: ' + error.message,
          duration: 3000,
          gravity: "top",
          position: "center",
          style: { background: "#ef4444" }
        }).showToast();
      }

      // 清空文件输入以便重新选择同一文件
      logoFileInput.value = '';
    });
  }

  if (removeLogoBtn) {
    removeLogoBtn.addEventListener('click', function() {
      logoInput.value = '';
      logoPreview.innerHTML = `<span class="text-gray-400 dark:text-gray-500 text-xs"><?php echo ruiyi_translate("Sin Logo", "No Logo", "无Logo"); ?></span>`;
      removeLogoBtn.classList.add('hidden');
      if (window.clodopConfig) {
        window.clodopConfig.receiptLogoWidth = 0;
        window.clodopConfig.receiptLogoHeight = 0;
      }
      if (window.RUIYI_POS_CONFIG?.storeInfo) {
        window.RUIYI_POS_CONFIG.storeInfo.receiptLogo = '';
        window.RUIYI_POS_CONFIG.storeInfo.receiptLogoWidth = 0;
        window.RUIYI_POS_CONFIG.storeInfo.receiptLogoHeight = 0;
      }
      if (window.LogoCache?.clear) {
        window.LogoCache.clear();
      }
      if (typeof updateReceiptPreview === 'function') updateReceiptPreview();

      Toastify({
        text: '<?php echo ruiyi_translate("Logo eliminado. Recuerda guardar la configuración.", "Logo removed. Remember to save settings.", "Logo已删除，请记得保存设置。"); ?>',
        duration: 3000,
        gravity: "top",
        position: "center",
        style: { background: "#f97316" }
      }).showToast();
    });
  }

  // 🔥 小票抬头预览功能
  function updateReceiptPreview() {
    const storeNameEl = document.getElementById('store_name');
    const businessNameEl = document.getElementById('store_business_name');
    const cifNifEl = document.getElementById('store_cif_nif');
    const phoneEl = document.getElementById('store_phone');
    const addressEl = document.getElementById('store_address');
    const fontSizeEl = document.getElementById('pos_receipt_store_name_font_size');
    const alignmentEl = document.querySelector('input[name="pos_receipt_header_alignment"]:checked');
    const logoUrlEl = document.getElementById('pos_receipt_logo');

    if (!storeNameEl) return; // 不在设置页面

    const storeName = storeNameEl.value || '';
    const businessName = businessNameEl ? businessNameEl.value : '';
    const cifNif = cifNifEl ? cifNifEl.value : '';
    const phone = phoneEl ? phoneEl.value : '';
    const address = addressEl ? addressEl.value : '';
    const fontSize = fontSizeEl ? fontSizeEl.value : '18';
    const alignment = alignmentEl ? alignmentEl.value : 'left';
    const logoUrl = logoUrlEl ? logoUrlEl.value : '';

    // 预览容器
    const previewContainer = document.getElementById('receipt-header-preview');
    if (!previewContainer) return;

    // Logo预览
    const previewLogo = document.getElementById('preview-logo');
    if (previewLogo) {
      if (logoUrl && logoUrl.length > 5) {
        previewLogo.innerHTML = `<img src="${logoUrl}" style="max-width: 150px; max-height: 50px; display: inline-block;" alt="Logo">`;
        previewLogo.style.display = 'block';
      } else {
        previewLogo.innerHTML = '';
        previewLogo.style.display = 'none';
      }
      previewLogo.style.textAlign = alignment;
    }

    // 店名预览 (支持多行)
    const previewStoreName = document.getElementById('preview-store-name');
    if (previewStoreName) {
      const escaped = storeName.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
      previewStoreName.innerHTML = escaped.replace(/\n/g, '<br>');
      previewStoreName.style.fontSize = fontSize + 'pt';
      previewStoreName.style.textAlign = alignment;
      previewStoreName.style.display = storeName ? 'block' : 'none';
    }

    // 公司名称
    const previewBizName = document.getElementById('preview-business-name');
    if (previewBizName) {
      previewBizName.textContent = businessName;
      previewBizName.style.textAlign = alignment;
      previewBizName.style.display = businessName ? 'block' : 'none';
    }

    // CIF/NIF
    const previewCif = document.getElementById('preview-cif-nif');
    if (previewCif) {
      previewCif.textContent = cifNif ? 'CIF/NIF: ' + cifNif : '';
      previewCif.style.textAlign = alignment;
      previewCif.style.display = cifNif ? 'block' : 'none';
    }

    // 电话
    const previewPhone = document.getElementById('preview-phone');
    if (previewPhone) {
      previewPhone.textContent = phone ? 'Tel: ' + phone : '';
      previewPhone.style.textAlign = alignment;
      previewPhone.style.display = phone ? 'block' : 'none';
    }

    // 地址
    const previewAddress = document.getElementById('preview-address');
    if (previewAddress) {
      previewAddress.textContent = address;
      previewAddress.style.textAlign = alignment;
      previewAddress.style.display = address ? 'block' : 'none';
    }
  }

  // 绑定事件监听器
  const previewFields = ['store_name', 'store_business_name', 'store_cif_nif', 'store_phone', 'store_address'];
  previewFields.forEach(function(id) {
    const el = document.getElementById(id);
    if (el) el.addEventListener('input', updateReceiptPreview);
  });

  const fontSizeSlider = document.getElementById('pos_receipt_store_name_font_size');
  if (fontSizeSlider) fontSizeSlider.addEventListener('input', updateReceiptPreview);

  const logoSizeSlider = document.getElementById('pos_receipt_logo_size');
  if (logoSizeSlider) logoSizeSlider.addEventListener('input', updateReceiptPreview);

  document.querySelectorAll('input[name="pos_receipt_header_alignment"]').forEach(function(radio) {
    radio.addEventListener('change', updateReceiptPreview);
  });

  // 🔥【2026-04-08】修复点击抬头对齐方式时，整个设置模块滚到顶部的 bug
  // 根因：radio 用了 Tailwind 的 .sr-only 类（position:absolute; clip:rect(0,0,0,0)），
  //   把 input 元素放到 containing block 的顶部位置（约 y=1330）。
  //   label 被点击触发 input 隐式 focus 时，浏览器自动 scrollIntoView 把 radio 的真实位置
  //   带到可见区 → main scroll 容器跳到 ~589 → 整个设置模块的内容看起来整体上移。
  //
  // 之前用 focus event listener 恢复 scrollTop 不生效，原因：
  //   1) sr-only input 被 label click 触发 focus 时，focus event 不会同步 fire
  //   2) 浏览器的 auto-scroll 是在 focus 调用内部同步发生的，比 listener 还早
  //
  // 真正的修复：移除 sr-only 类，用 inline style 把 radio 定位到 label 内部中心点，
  //   这样 radio 的真实 DOM 位置就在 label 当前可见位置 → 浏览器不需要 scroll。
  document.querySelectorAll('input[name="pos_receipt_header_alignment"]').forEach(function(radio) {
    radio.classList.remove('sr-only');
    radio.style.cssText = 'position:absolute; opacity:0; width:1px; height:1px; pointer-events:none; left:50%; top:50%; margin:0; padding:0;';
    // 父 label 设为 relative 以便 absolute 子元素相对于 label 定位
    var _lblEl = radio.closest('label');
    if (_lblEl && getComputedStyle(_lblEl).position === 'static') {
      _lblEl.style.position = 'relative';
    }
  });

  // 分隔线开关
  const separatorToggle = document.getElementById('pos_receipt_header_separator');
  if (separatorToggle) {
    separatorToggle.addEventListener('change', function() {
      const line = document.getElementById('preview-separator-line');
      if (line) line.style.display = this.checked ? 'block' : 'none';
    });
  }

  // Logo变化时也更新预览 (MutationObserver监听hidden input值变化)
  const logoHiddenInput = document.getElementById('pos_receipt_logo');
  if (logoHiddenInput) {
    const logoObserver = new MutationObserver(updateReceiptPreview);
    logoObserver.observe(logoHiddenInput, { attributes: true, attributeFilter: ['value'] });
    // 也监听直接的值变化
    logoHiddenInput.addEventListener('change', updateReceiptPreview);
  }

  // 初始化预览
  updateReceiptPreview();

  // 测试打印功能已移除 - 改用浏览器原生打印
}

