// 已移除loadSalesChart和renderSalesChart函数

document.addEventListener('DOMContentLoaded', function() {
    // Dashboard功能已移除
    
    
    // 初始化设置部分
    if (typeof initSettingsSection === 'function') {
        try {
            initSettingsSection();
        } catch (e) {
            console.warn('Error executing initSettingsSection:', e);
        }
    } else {
        console.warn('initSettingsSection function is not defined, skipping call.');
    }
    
    // Smooth scroll for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function (e) {
            const href = this.getAttribute('href');
            if (href === '#') return; // 跳过空锚点
            
            e.preventDefault();
            const target = document.querySelector(href);
            if (target) {
                target.scrollIntoView({
                    behavior: 'smooth'
                });
            }
        });
    });

    // Sidebar Toggler
    const sidenavToggler = document.getElementById('sidenav-toggler');
    const sidenav = document.getElementById('sidenav-main');
    const body = document.getElementsByTagName('body')[0];
    const className = 'g-sidenav-pinned';

    if (sidenavToggler && sidenav) {
        sidenavToggler.addEventListener('click', function() {
            if (body.classList.contains(className)) {
                body.classList.remove(className);
            } else {
                body.classList.add(className);
            }
        });
    }
});

// 检查购物车中产品的库存
function checkCartStock() {
  // 如果购物车为空，直接返回成功
  if (cart.length === 0) {
    return Promise.resolve(true);
  }
  
  // 显示加载中提示
  Swal.fire({
    title: 'Verificando stock...',
    text: 'Comprobando disponibilidad de productos',
    allowOutsideClick: false,
    didOpen: () => {
      Swal.showLoading();
    }
  });
  
  // 使用AJAX检查库存
  var ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
  var ajaxNonce = window.RUIYI_POS?.nonce || posNonce;
  const formData = new URLSearchParams();
  formData.append('action', 'ruiyi_check_product_stock');
  formData.append('nonce', ajaxNonce);
  formData.append('cart', JSON.stringify(cart));
  
  return fetch(ajaxUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: formData
  })
  .then(response => {
    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }
    return response.json();
  })
  .then(data => {
    // 关闭加载提示
    Swal.close();
    
    if (data.success) {
      // 库存充足
      return true;
    } else {
      // 添加缺货商品信息
      let stockHtml = '<div class="text-left">';
      
      // 格式化错误消息
      stockHtml += '<p class="mb-3">' + (data.data.message || '<?php echo ruiyi_translate("Los siguientes productos tienen problemas de inventario:", "The following products have inventory issues:", "以下产品存在库存问题:"); ?>') + '</p>';
      
      // 添加缺货商品信息
      if (data.data.out_of_stock && data.data.out_of_stock.length > 0) {
        stockHtml += '<div class="mb-3">';
        stockHtml += '<h4 class="text-red-600 font-bold mb-2"><?php echo ruiyi_translate("Productos agotados:", "Out of stock products:", "商品缺货:"); ?></h4>';
        stockHtml += '<ul class="list-disc pl-5">';
        data.data.out_of_stock.forEach(item => {
          stockHtml += `<li class="mb-1"><span class="font-semibold">${item.name}</span>: ${item.error}</li>`;
        });
        stockHtml += '</ul></div>';
      }
      
      // 添加库存不足商品信息
      if (data.data.insufficient_stock && data.data.insufficient_stock.length > 0) {
        stockHtml += '<div class="mb-3">';
        stockHtml += '<h4 class="text-orange-600 font-bold mb-2"><?php echo ruiyi_translate("Productos con stock insuficiente:", "Products with insufficient stock:", "库存不足商品:"); ?></h4>';
        stockHtml += '<ul class="list-disc pl-5">';
        data.data.insufficient_stock.forEach(item => {
          stockHtml += `<li class="mb-1">
            <span class="font-semibold">${item.name}</span>:
            <span class="text-orange-600"><?php echo ruiyi_translate("Necesario", "Required", "需要"); ?> ${item.requested}</span>,
            <span class="text-green-600"><?php echo ruiyi_translate("Disponible", "Available", "库存"); ?> ${item.available}</span>
          </li>`;
        });
        stockHtml += '</ul></div>';
      }
      
      stockHtml += '</div>';
      
      // 显示错误信息
      Swal.fire({
        icon: 'warning',
        title: '<?php echo ruiyi_translate("Problema de inventario", "Inventory Issue", "库存问题"); ?>',
        html: stockHtml,
        confirmButtonColor: '#f7310f',
        confirmButtonText: '<?php echo ruiyi_translate("Entendido", "Understood", "我知道了"); ?>'
      });
      
      return false;
    }
  })
  .catch(error => {
    // 关闭加载提示
    Swal.close();
    
    console.error('Error checking stock:', error);
    Swal.fire({
      icon: 'error',
      title: '连接错误',
      text: '无法验证库存状态，请重试。',
      confirmButtonColor: '#f7310f'
    });
    return false;
  });
}



// 在文档加载完成后添加 Tailwind 滚动条相关样式
