<!-- 添加JavaScript来处理弹窗和数据加载 -->
<script>
// 全局变量定义
// Use the global ajaxUrl/ajaxNonce defined earlier (avoid redefinition)
var ajaxUrl = window.ajaxUrl;
var ajaxNonce = window.RUIYI_POS?.nonce || currentNonce;

document.addEventListener('DOMContentLoaded', function() {
  // 获取弹窗和按钮元素
  const productosModal = document.getElementById('productos-modal');
  const verProductosBtn = document.getElementById('ver-todos-productos');
  const closeProductosBtn = document.getElementById('close-productos-modal');
  
  // 产品弹窗事件处理
  if (verProductosBtn) {
    verProductosBtn.addEventListener('click', function(e) {
      e.preventDefault();
      productosModal.classList.remove('hidden');
      loadAllProducts();
    });
  }
  
  if (closeProductosBtn) {
    closeProductosBtn.addEventListener('click', function() {
      productosModal.classList.add('hidden');
    });
  }
  
  // 点击弹窗外部区域关闭弹窗
  window.addEventListener('click', function(e) {
    if (e.target === productosModal) {
      productosModal.classList.add('hidden');
    }
  });
  
  
  // 加载所有产品数据
  function loadAllProducts() {
    const productosList = document.getElementById('productos-list');
    if (!productosList) return;
    
    productosList.innerHTML = '<tr><td colspan="6" class="px-6 py-4 text-center text-gray-500">Cargando productos...</td></tr>';
    
    // 使用AJAX获取产品数据
    fetch(ajaxUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: new URLSearchParams({
        'action': 'ruiyi_pos_get_all_products',
        'nonce': ajaxNonce
      })
    })
    .then(response => response.json())
    .then(data => {
      if (data.success && data.data.products) {
        // 清空加载提示
        productosList.innerHTML = '';
        
        // 添加产品行
        data.data.products.forEach(product => {
          const row = document.createElement('tr');
          row.className = 'hover:bg-gray-50';
          
          // 生成产品单元格
          row.innerHTML = `
            <td class="px-6 py-4 whitespace-nowrap">
              <div class="flex items-center">
                <div class="flex-shrink-0 h-10 w-10 rounded-md overflow-hidden">
                  <img src="${product.image || 'https://via.placeholder.com/40'}" alt="${product.name}" class="h-10 w-10 object-cover">
                </div>
                <div class="ml-4">
                  <div class="text-sm font-medium text-gray-900">${product.name}</div>
                  <div class="text-sm text-gray-500">${product.sku || 'Sin SKU'}</div>
                </div>
              </div>
            </td>
            <td class="px-6 py-4 whitespace-nowrap">
              <div class="text-sm text-gray-900 font-semibold">${product.price_html || `€${product.price}`}</div>
              ${product.regular_price !== product.price ?
                `<div class="text-xs text-gray-500 line-through">€${product.regular_price}</div>` : ''}
            </td>
            <td class="px-6 py-4 whitespace-nowrap">
              <div class="text-sm text-gray-900">${product.categories.join(', ') || 'Sin categoría'}</div>
            </td>
            <td class="px-6 py-4 whitespace-nowrap">
              ${product.stock_status === 'instock' ?
                `<span class="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-green-100 text-green-800">
                  ${product.stock_quantity !== null ? product.stock_quantity : 'En stock'}
                </span>` :
                `<span class="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-red-100 text-red-800">
                  Agotado
                </span>`}
            </td>
            <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
              ${product.total_sales || 0} unidades
            </td>
            <td class="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
              <button class="add-to-cart-btn text-blue-600 hover:text-blue-900 mr-3" data-id="${product.id}">
                <i class="fas fa-cart-plus mr-1"></i> Añadir
              </button>
              <button class="view-product-btn text-green-600 hover:text-green-900" data-id="${product.id}">
                <i class="fas fa-eye mr-1"></i> Ver
              </button>
            </td>
          `;
          
          productosList.appendChild(row);
        });
        
        // 添加"添加到购物车"按钮事件
        document.querySelectorAll('.add-to-cart-btn').forEach(btn => {
          btn.addEventListener('click', function() {
            const productId = this.getAttribute('data-id');
            const product = data.data.products.find(p => p.id == productId);
            
            if (product) {
              // 查找购物车中是否已有该商品（只在未锁定项中查找）
              const productPrice = parseFloat(product.price);
              const existingItemIndex = cart.findIndex(item => {
                if (typeof canMergeUnlockedCartLine === 'function') {
                  return canMergeUnlockedCartLine(item, parseInt(productId), productPrice);
                }
                return item.id === parseInt(productId) &&
                  !item.locked &&
                  !item.customName &&
                  !(item.notes && String(item.notes).trim()) &&
                  (!item.supplements || item.supplements.length === 0);
              });

              if (existingItemIndex !== -1) {
                // 如果已存在未锁定的，增加数量
                cart[existingItemIndex].quantity += 1;
                // 🔥 追踪本次新增数量（用于厨房打印）
                cart[existingItemIndex].addedQuantity = (cart[existingItemIndex].addedQuantity || 0) + 1;
              } else {
                // 否则添加新商品
                cart.push({
                  id: parseInt(productId),
                  name: product.name,
                  price: productPrice,
                  quantity: 1,
                  addedQuantity: 1, // 🔥 追踪本次新增数量（用于厨房打印）
                  image_url: product.image || 'https://via.placeholder.com/40'
                });
              }

              // 更新购物车显示
              if (typeof renderCart === 'function') {
                renderCart();
              }
            }
          });
        });
      } else {
        productosList.innerHTML = '<tr><td colspan="6" class="px-6 py-4 text-center text-red-500">Error al cargar productos</td></tr>';
      }
    })
    .catch(error => {
      console.error('Error fetching products:', error);
      productosList.innerHTML = '<tr><td colspan="6" class="px-6 py-4 text-center text-red-500">Error de conexión</td></tr>';
    });
  }
});
</script>

<!-- 添加PHP处理Ajax请求 -->
<?php
// 添加获取所有产品的Ajax处理函数
add_action('wp_ajax_ruiyi_pos_get_all_products', 'ruiyi_pos_get_all_products');
add_action('wp_ajax_nopriv_ruiyi_pos_get_all_products', 'ruiyi_pos_get_all_products');

function ruiyi_pos_get_all_products() {
  // 验证nonce
  check_ajax_referer('ruiyi_pos_nonce', 'nonce');

  // 获取所有产品
  $args = array(
    'post_type' => 'product',
    'posts_per_page' => -1,
    'post_status' => 'publish',
  );
  
  $products_query = new WP_Query($args);
  $products = array();
  
  if ($products_query->have_posts()) {
    while ($products_query->have_posts()) {
      $products_query->the_post();
      $product = wc_get_product(get_the_ID());
      
      // 获取产品分类
      $categories = array();
      $terms = get_the_terms(get_the_ID(), 'product_cat');
      if ($terms && !is_wp_error($terms)) {
        foreach ($terms as $term) {
          $categories[] = $term->name;
        }
      }
      
      // 产品图片
      $image_id = $product->get_image_id();
      $image_url = $image_id ? wp_get_attachment_image_url($image_id, 'thumbnail') : ruiyi_get_placeholder_image();
      
      // 构建产品数据 - 使用产品原始价格
      $products[] = array(
        'id' => $product->get_id(),
        'name' => $product->get_name(),
        'sku' => $product->get_sku(),
        'price' => $product->get_price(), // 使用产品原始价格
        'regular_price' => $product->get_regular_price(),
        'price_html' => $product->get_price_html(),
        'stock_quantity' => $product->get_stock_quantity(),
        'stock_status' => $product->get_stock_status(),
        'categories' => $categories,
        'image' => $image_url,
        'total_sales' => get_post_meta($product->get_id(), 'total_sales', true)
      );
    }
    
    wp_reset_postdata();
  }
  
  wp_send_json_success(array('products' => $products));
  wp_die();
}
?>

