<script>
// 这个脚本用于实时更新POS界面的桌位状态

// WordPress AJAX URL 和 Nonce (需要在PHP中定义并传递下来)
// 🔥 使用 NonceManager 获取最新的 nonce，避免过期问题
const posAjaxUrl = '<?php echo esc_js(admin_url('admin-ajax.php')); ?>';
window.posAjaxUrl = posAjaxUrl; // 🔥 暴露给外部 JS 模块
// 🔥 使用 getter 函数确保始终获取最新的 nonce
function getPosNonce() {
  return (window.NonceManager && window.NonceManager.get()) || window.RUIYI_POS?.nonce || '<?php echo esc_js($ajax_nonce); ?>';
}
window.getPosNonce = getPosNonce; // 🔥 暴露给外部 JS 模块
const posNonce = getPosNonce(); // 保持向后兼容，但建议使用 getPosNonce()

// 🔥 厨房打印队列系统已提取到 js/modules/pos-kitchen-print.js
// ===== 原代码 (已提取到外部文件，下方代码被跳过) =====
if (false) { // DISABLED: code moved to js/modules/pos-kitchen-print.js
// 所有打印触发点（WebSocket / Storage / Polling）统一入口
// 解决快速连续订单时打印丢失的问题：
//   1. 使用版本级去重（orderId_version），避免同桌追加订单被误拦截
//   2. 打印入队不受 storage 防抖限制
//   3. 同桌合并：同一 orderId 的多个版本在收集窗口内合并为一次打印
//   4. 收集窗口：500ms 延迟启动处理，让几乎同时到达的事件有机会合并
//   5. 队列顺序处理，每个任务间隔 2 秒，防止并发打印指令互相干扰
window._kitchenPrintQueue = [];
window._kitchenPrintProcessing = false;
window._kitchenPrintCollectionTimer = null;

/**
 * 将厨房打印请求加入队列
 * @param {string} tableNumber - 桌号（如 "Mesa 3" 或 "3"）
 * @param {number|string} orderId - 订单ID
 * @param {string} version - 订单版本号
 * @param {string|null} presetDisplayName - 预设显示名称
 * @param {boolean} isAppendOrder - 是否为追加订单
 */
function enqueueKitchenPrint(tableNumber, orderId, version, presetDisplayName, isAppendOrder) {
    const printKey = orderId + '_' + (version || 'v0');

    // 队列内去重（完全相同的版本）
    if (window._kitchenPrintQueue.some(j => j.printKey === printKey)) {
        console.log('[打印队列] ⏭️ 队列中已存在:', printKey);
        return;
    }

    // 检查是否已打印过此版本
    const printedOrders = JSON.parse(localStorage.getItem('printed_kitchen_orders') || '[]');
    if (printedOrders.includes(printKey)) {
        console.log('[打印队列] ⏭️ 已打印过:', printKey);
        return;
    }

    // 🔥 同桌合并：如果队列中已有同一 orderId 的待打印任务，替换为最新版本
    // 场景：两台设备同时提交到 comedor2，V1 和 V2 几乎同时入队
    // 合并后只发送一次打印请求，服务端会返回所有批次的新商品
    const existingIndex = window._kitchenPrintQueue.findIndex(j => String(j.orderId) === String(orderId));
    if (existingIndex !== -1) {
        const oldJob = window._kitchenPrintQueue[existingIndex];
        console.log('[打印队列] 🔄 同桌合并:', oldJob.printKey, '→', printKey);
        window._kitchenPrintQueue[existingIndex] = {
            tableNumber, orderId, version, presetDisplayName,
            isAppendOrder: true, // 合并后始终用追加模式，获取所有新商品
            printKey,
            enqueuedAt: Date.now()
        };
        // 标记新版本为已打印
        printedOrders.push(printKey);
        localStorage.setItem('printed_kitchen_orders', JSON.stringify(printedOrders));
        // 写入 recent_kitchen_prints
        try {
            const rp = JSON.parse(localStorage.getItem('recent_kitchen_prints') || '{}');
            rp[printKey] = Date.now();
            localStorage.setItem('recent_kitchen_prints', JSON.stringify(rp));
        } catch(e) {}
        return;
    }

    // 正常入队
    window._kitchenPrintQueue.push({
        tableNumber, orderId, version, presetDisplayName, isAppendOrder, printKey,
        enqueuedAt: Date.now()
    });

    console.log('[打印队列] ➕ 入队:', printKey, '桌号:', tableNumber, '追加:', isAppendOrder, '队列长度:', window._kitchenPrintQueue.length);

    // 提前标记为已打印，防止其他触发点（WebSocket/Storage/Polling）重复入队
    printedOrders.push(printKey);
    if (!isAppendOrder && !printedOrders.includes(String(orderId))) {
        printedOrders.push(String(orderId));
    }
    localStorage.setItem('printed_kitchen_orders', JSON.stringify(printedOrders));

    // 写入 recent_kitchen_prints（使用版本key）
    try {
        const rp = JSON.parse(localStorage.getItem('recent_kitchen_prints') || '{}');
        rp[printKey] = Date.now();
        localStorage.setItem('recent_kitchen_prints', JSON.stringify(rp));
    } catch(e) {}

    // 🔥 使用收集窗口调度处理（而非立即处理）
    scheduleQueueProcessing();
}

/**
 * 调度队列处理：500ms 收集窗口
 * 让几乎同时到达的多个事件有机会合并，再统一处理
 */
function scheduleQueueProcessing() {
    // 如果队列正在处理中，新任务会被 while 循环自动拾取，无需调度
    if (window._kitchenPrintProcessing) return;

    // 重置收集窗口计时器（每次新入队都重新等 500ms）
    if (window._kitchenPrintCollectionTimer) {
        clearTimeout(window._kitchenPrintCollectionTimer);
    }
    window._kitchenPrintCollectionTimer = setTimeout(() => {
        window._kitchenPrintCollectionTimer = null;
        processKitchenPrintQueue();
    }, 500);
}

/**
 * 顺序处理打印队列，每个打印任务之间有 2 秒间隔
 */
async function processKitchenPrintQueue() {
    if (window._kitchenPrintProcessing) return;
    if (window._kitchenPrintQueue.length === 0) return;

    window._kitchenPrintProcessing = true;
    console.log('[打印队列] 🚀 开始处理队列, 待打印:', window._kitchenPrintQueue.length);

    while (window._kitchenPrintQueue.length > 0) {
        const job = window._kitchenPrintQueue.shift();

        console.log('[打印队列] 🖨️ 正在打印:', job.printKey, '桌号:', job.tableNumber, '剩余:', window._kitchenPrintQueue.length);

        try {
            await new Promise((resolve) => {
                try {
                    printNewTableOrderToKitchen(job.tableNumber, job.orderId, job.presetDisplayName, job.isAppendOrder, job.version);
                } catch(err) {
                    console.error('[打印队列] ❌ 打印调用出错:', job.printKey, err);
                }
                // 给 fetch 请求 + C-LODOP 打印指令留出足够时间（2秒）
                setTimeout(resolve, 2000);
            });
        } catch(err) {
            console.error('[打印队列] ❌ 处理出错:', err);
        }
    }

    window._kitchenPrintProcessing = false;
    console.log('[打印队列] ✅ 队列处理完成');
}

/**
 * 🔥 当检测到新订单时自动打印厨房小票
 * 支持按产品分类分组到不同打印机
 * @param {string|number} tableNumber - 桌号（全局编号或mesaId）
 * @param {number} orderId - 订单ID
 * @param {string} presetDisplayName - 可选的预设显示名称（如 "室内1"）
 * @param {boolean} isAppendOrder - 【2026-01-21 新增】是否为追加订单（只打印新添加的商品）
 * @param {string} orderVersion - 订单本次新增批次版本号
 */
function printNewTableOrderToKitchen(tableNumber, orderId, presetDisplayName, isAppendOrder = false, orderVersion = '') {
    const T0 = performance.now();
    const currentLang = getCurrentLanguage ? getCurrentLanguage() : 'unknown';

    // 🔥🔥🔥 【2026-01-31 新增】外送区域保存订单时不触发厨房打印，只有预结单才打印
    // 🔥 【2026-03-11 新增】支持设置中配置跳过厨房打印的分区
    const isDeliveryZoneForAutoPrint = typeof isDeliveryZoneTable === 'function' ? isDeliveryZoneTable(tableNumber) : false;
    const isSkipZoneForAutoPrint = typeof shouldSkipKitchenPrintForTable === 'function' ? shouldSkipKitchenPrintForTable(tableNumber) : false;
    if (isSkipZoneForAutoPrint) {
        console.log('[自动厨房打印] 🚫 该分区已设置跳过厨房打印，不打印:', tableNumber);
        return;
    }
    if (isDeliveryZoneForAutoPrint) {
        console.log('[自动厨房打印] 🚚 外送区域桌位，跳过自动厨房打印（将在预结单时打印）:', tableNumber);
        return;
    }

    // 检查CLODOP是否可用
    if (!window.clodopConfig || !window.clodopConfig.enabled ||
        !window.clodopConfig.kitchenPrinter) {
        console.warn('[自动厨房打印] CLODOP未配置或厨房打印机未设置，跳过打印');
        return;
    }

    const T1 = performance.now();

    // 🔥🔥🔥 【2026-03-25 全新机制】始终使用 unprinted_only 模式
    // 服务端通过 WC 订单行项 _kitchen_printed meta 跟踪已打印状态
    // 不再依赖前端 isAppendOrder 检测，彻底杜绝重复打印
    const requestParams = {
        action: 'ruiyi_pos_get_order_for_print',
        order_id: orderId,
        nonce: posNonce,
        version: orderVersion || '',
        unprinted_only: 'true'
    };
    console.log('[厨房打印] 📝 使用 unprinted_only 模式：只获取未打印的商品');

    // 获取订单详情
    fetch(posAjaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams(requestParams)
    })
    .then(response => response.json())
    .then(data => {
        const T2 = performance.now();

        if (data.success && data.data) {

            const T3 = performance.now();

            // 🔥 查找完整的桌号（包含分类名称）
            let fullTableName = presetDisplayName || tableNumber; // 优先使用预设的显示名称

            // 🔥 如果没有预设显示名称，从桌位映射中查找
            if (!presetDisplayName && window.tableCategoryMappings) {
                // 🔥 【修复】从 "Mesa 5" 格式中提取数字部分
                const tableNum = parseInt(resolveGlobalTableNumber(tableNumber));

                if (!isNaN(tableNum) && tableNum > 0) {
                    // tableCategoryMappings 可能是对象或数组
                    let allMappings = [];
                    if (Array.isArray(window.tableCategoryMappings)) {
                        allMappings = window.tableCategoryMappings;
                    } else {
                        allMappings = Object.values(window.tableCategoryMappings);
                    }

                    // 查找匹配的映射
                    const mapping = allMappings.find(m => parseInt(m.global_table_number) === tableNum);

                    console.log('[厨房打印] 桌位映射查找:', {
                        原始桌号: tableNumber,
                        提取数字: tableNum,
                        找到映射: !!mapping,
                        分类显示名: mapping?.category_display_name,
                        映射总数: allMappings.length
                    });

                    if (mapping && mapping.category_display_name) {
                        fullTableName = mapping.category_display_name;
                    } else if (mapping && mapping.display_name) {
                        fullTableName = mapping.display_name;
                    }
                }
            }

            const T4 = performance.now();

            const items = data.data.items;

            // 🔥 厨房小票多语言：根据系统当前语言选择产品名称
            const kitchenLang = window.RUIYI_POS?.currentLang || PHP_LANG || 'zh';
            function getKitchenItemName(item) {
              if (kitchenLang === 'zh' && item.name_zh) return item.name_zh;
              if (kitchenLang === 'en' && item.name_en) return item.name_en;
              return item.name; // fallback 到默认名称（西班牙语）
            }

            // 🔥🔥🔥 【2026-02-12 关键修复】服务端返回空商品列表 → 跳过打印（新商品已被消费）
            if (!items || items.length === 0) {
                console.log('[自动厨房打印] ℹ️ 服务端返回空商品列表，跳过打印（新商品已被前一次打印消费）', {
                    orderId: orderId,
                    no_new_items: data.data.no_new_items || false
                });
                return;
            }

            // 🔥 保存完整列表用于收银台打印
            const allItems = [...items];

            // 🔥 分类打印机诊断日志
            items.forEach(item => {
                console.log('[printNewTableOrderToKitchen] 📋 分类打印机:', item.name, '| cat:', item.category_name, '| cat_printer:', item.category_printer || '(空-将用默认)');
            });

            // 🔥 过滤厨房打印项
            let filteredItems = items;
            if (window.clodopConfig?.kitchenCategoryFilterEnabled) {
                const excluded = window.clodopConfig.kitchenExcludedCategories || [];
                if (excluded.length > 0) {
                    filteredItems = items.filter(item => !excluded.includes(item.category_id));
                    console.log('[自动厨房打印] 🔥 分类过滤: 全部', items.length, '项 → 过滤后', filteredItems.length, '项');
                }
            }

            // 🔥【2026-04-04】过滤"不打印"分类：category_printer === "__no_print__" 的商品跳过
            filteredItems = filteredItems.filter(item => {
                if (item.category_printer === '__no_print__') {
                    console.log('[厨房打印] 🚫 跳过不打印分类:', item.name, '| 分类:', item.category_name);
                    return false;
                }
                return true;
            });

            const categoryPrinterEnabled = data.data.category_printer_enabled && window.clodopConfig.categoryPrinterEnabled;

            // 🔥 按分类打印机分组打印
            if (categoryPrinterEnabled) {
                const defaultPrinter = window.clodopConfig.kitchenPrinter;
                const separatePerCategory = window.clodopConfig.separateTicketPerCategory;

                // 🔥🔥🔥 【2026-02-08 新增】按分类分开打印模式
                // 启用后：按 category_name 分组，每个分类一张独立小票（即使同一打印机）
                // 未启用：按 printer 分组，同一打印机的所有分类合并为一张小票
                let printJobs = []; // { printer, items, categoryLabel }

                if (separatePerCategory) {
                    // 按分类名分组
                    const categoryGroups = {};
                    filteredItems.forEach(item => {
                        const catKey = item.category_name || '__uncategorized__';
                        if (!categoryGroups[catKey]) {
                            categoryGroups[catKey] = { printer: item.category_printer || defaultPrinter, items: [] };
                        }
                        categoryGroups[catKey].items.push({
                            name: getKitchenItemName(item), name_original: item.name || '', quantity: item.quantity,
                            category_name: item.category_name || '', notes: item.notes || '',
                            is_supplement: item.is_supplement || false, parent_item_name: item.parent_item_name || ''
                        });
                    });
                    Object.keys(categoryGroups).forEach(catName => {
                        printJobs.push({
                            printer: categoryGroups[catName].printer,
                            items: categoryGroups[catName].items,
                            categoryLabel: catName !== '__uncategorized__' ? catName : null
                        });
                    });
                    console.log('[自动厨房打印] 按分类分开打印模式，分类数:', printJobs.length);
                } else {
                    // 按打印机分组（原有逻辑）
                    const printerGroups = {};
                    filteredItems.forEach(item => {
                        const printer = item.category_printer || defaultPrinter;
                        if (!printerGroups[printer]) printerGroups[printer] = [];
                        printerGroups[printer].push({
                            name: getKitchenItemName(item), name_original: item.name || '', quantity: item.quantity,
                            category_name: item.category_name || '', notes: item.notes || '',
                            is_supplement: item.is_supplement || false, parent_item_name: item.parent_item_name || ''
                        });
                    });
                    Object.keys(printerGroups).forEach(printerName => {
                        printJobs.push({ printer: printerName, items: printerGroups[printerName], categoryLabel: null });
                    });
                    console.log('[自动厨房打印] 分类打印机模式，打印机数量:', printJobs.length);
                }

                let printedCount = 0;

                printJobs.forEach((job, index) => {
                    const kitchenOrderData = {
                        id: orderId,
                        table_number: fullTableName,
                        order_type: 'servir',
                        items: job.items,
                        date_created: data.data.date_created,
                        notes: data.data.notes || '',
                        orderNotes: data.data.notes || (typeof window.getOrderNotes === 'function' ? window.getOrderNotes() : ''),
                        printer_group: printJobs.length > 1 ? (job.categoryLabel || job.printer) : null,
                        total_printers: printJobs.length,
                        category_label: job.categoryLabel // 🔥 分类标签，可用于小票抬头显示
                    };

                    setTimeout(() => {
                        if (typeof ruiyiPrintKitchenOrder !== 'undefined') {
                            if (window._kitchenPrintDebug) {
                                window._kitchenPrintDebug.log('printNewTableOrderToKitchen (分类打印机)', kitchenOrderData, job.printer);
                            }
                            ruiyiPrintKitchenOrder(kitchenOrderData, job.printer);
                            const label = job.categoryLabel ? `[${job.categoryLabel}]` : '';
                            console.log(`[自动厨房打印] ✅ 已发送到打印机: ${job.printer} ${label}, 商品数: ${job.items.length}`);

                            if (index === printJobs.length - 1 && kitchenOrderData.orderNotes && typeof window.clearOrderNotes === 'function') {
                                console.log('[printNewTableOrderToKitchen] 🗑️ 清空订单备注，防止重复打印');
                                window.clearOrderNotes();
                            }
                        }
                    }, index * 500);

                    printedCount++;
                });

                // 显示成功通知
                if (printedCount > 0) {
                    const ticketText = separatePerCategory
                        ? `${printedCount}张分类小票`
                        : (printedCount > 1 ? `${printedCount}台打印机` : '厨房');
                    Toastify({
                        text: `🍴 ${fullTableName} 新订单已发送${ticketText}`,
                        duration: 3000,
                        gravity: "top",
                        position: "right",
                        style: { background: "#10b981" }
                    }).showToast();
                }

            } else {
                // 🔥 原有逻辑：所有商品发送到同一打印机（使用过滤后的列表）
                const kitchenOrderData = {
                    id: orderId,
                    table_number: fullTableName,
                    order_type: 'servir',
                    items: filteredItems.map(item => ({ name: getKitchenItemName(item), name_original: item.name || '', quantity: item.quantity, notes: item.notes || '', is_supplement: item.is_supplement || false, parent_item_name: item.parent_item_name || '' })), // 🔥 包含产品备注 + 多语言名称 + 配料标记 + 原始名称
                    date_created: data.data.date_created,
                    notes: data.data.notes || '',
                    orderNotes: data.data.notes || (typeof window.getOrderNotes === 'function' ? window.getOrderNotes() : '')
                };

                const T5 = performance.now();

                // 调用厨房打印函数
                if (typeof ruiyiPrintKitchenOrder !== 'undefined') {
                    // 🔥 调试日志
                    if (window._kitchenPrintDebug) {
                        window._kitchenPrintDebug.log('printNewTableOrderToKitchen (单一打印机)', kitchenOrderData, window.clodopConfig.kitchenPrinter);
                    }
                    ruiyiPrintKitchenOrder(kitchenOrderData, window.clodopConfig.kitchenPrinter);

                    // 🔥 打印厨房小票后清空订单备注，防止重复打印
                    if (kitchenOrderData.orderNotes && typeof window.clearOrderNotes === 'function') {
                        console.log('[printNewTableOrderToKitchen] 🗑️ 清空订单备注，防止重复打印');
                        window.clearOrderNotes();
                    }

                    const T6 = performance.now();

                    // 显示成功通知
                    Toastify({
                        text: `🍴 ${fullTableName} 新订单已发送厨房`,
                        duration: 3000,
                        gravity: "top",
                        position: "right",
                        style: { background: "#10b981" }
                    }).showToast();

                } else {
                    console.error('[自动厨房打印] ❌ ruiyiPrintKitchenOrder 函数未定义');
                }
            }

            // 🔥 收银台打印机打印完整厨房小票（不过滤分类）
            if (window.clodopConfig?.kitchenCategoryFilterEnabled && allItems.length > 0 && window.clodopConfig?.defaultPrinter) {
                const cashierOrderData = {
                    id: orderId,
                    table_number: fullTableName,
                    order_type: 'servir',
                    items: allItems.map(item => ({ name: getKitchenItemName(item), name_original: item.name || '', quantity: item.quantity, notes: item.notes || '', is_supplement: item.is_supplement || false, parent_item_name: item.parent_item_name || '' })),
                    date_created: data.data.date_created,
                    orderNotes: data.data.notes || ''
                };
                if (typeof ruiyiPrintKitchenOrder !== 'undefined') {
                    ruiyiPrintKitchenOrder(cashierOrderData, window.clodopConfig.defaultPrinter);
                    console.log('[自动厨房打印] ✅ 收银台厨房小票已发送到收银打印机, 商品数:', allItems.length);
                }
            }
        } else {
            console.error('[自动厨房打印] ❌ 获取订单详情失败:', data.data?.message);
        }
    })
    .catch(error => {
        console.error('[自动厨房打印] ❌ 请求错误:', error);
    });
}

} // END DISABLED kitchen print block

/**
 * 获取最新的桌位状态并更新界面显示
 * 🔧 优化：添加防抖机制，防止请求风暴
 * 🔥 修复：将最小间隔从10秒缩短到3秒，配合快速轮询
 */
let _fetchTableStatusLoading = false;  // 正在加载标志
let _lastFetchTableStatusTime = 0;     // 上次请求时间
const _MIN_FETCH_INTERVAL = 3000;      // 🔥 最小请求间隔3秒（配合5秒快速轮询）

// 🔥 全局已结账桌位追踪器：防止轮询将刚结账的桌位重新标记为占用
// key = 桌号数字, value = 结账时间戳
window._recentlyCheckedOutTables = window._recentlyCheckedOutTables || {};
let _fetchTableStatusErrors = 0;       // 连续错误计数
const _MAX_FETCH_ERRORS = 5;           // 最大连续错误数

function fetchAndUpdateTableStatuses() {
    // 防抖检查：如果正在加载，跳过
    if (_fetchTableStatusLoading) {
        return;
    }

    // 防抖检查：如果距离上次请求太短，跳过
    const now = Date.now();
    if (now - _lastFetchTableStatusTime < _MIN_FETCH_INTERVAL) {
        return;
    }

    // 错误熔断：如果连续错误太多，暂停请求
    if (_fetchTableStatusErrors >= _MAX_FETCH_ERRORS) {
        setTimeout(() => { _fetchTableStatusErrors = 0; }, 30000);
        return;
    }

    _fetchTableStatusLoading = true;
    _lastFetchTableStatusTime = now;

    const data = new URLSearchParams();
    data.append('action', 'get_tables_status');
    data.append('nonce', posNonce);

    fetch(posAjaxUrl, {
        method: 'POST',
        body: data
    })
    .then(response => {
        if (!response.ok) {
            throw new Error('Network response was not ok ' + response.statusText);
        }
        return response.json();
    })
    .then(result => {
        // 注意：现在期望收到的是 tables_updates 数组
        if (result.success && result.data && Array.isArray(result.data.tables_updates)) {
            const updates = result.data.tables_updates;

            if (updates.length > 0) {
                const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                let needsRender = false;
                const nowTimestamp = Date.now(); // 获取当前时间戳用于比较

                // 🔥 【关键修复】清理过期的_skipAutoUpdate和_paymentCompleted标志（60秒后过期）
                Object.keys(mesasEstado).forEach(mesaId => {
                    const skipTimestamp = new Date(mesasEstado[mesaId].timestamp).getTime();
                    const isExpired = !isNaN(skipTimestamp) && nowTimestamp - skipTimestamp > 60000;
                    if (isExpired) {
                        if (mesasEstado[mesaId]._skipAutoUpdate) {
                            delete mesasEstado[mesaId]._skipAutoUpdate;
                        }
                        if (mesasEstado[mesaId]._paymentCompleted) {
                            delete mesasEstado[mesaId]._paymentCompleted;
                        }
                        // 🔥 如果是已结账的libre条目且保护已过期，删除整个条目（恢复为无数据=libre）
                        if (mesasEstado[mesaId].estado === 'libre' && !mesasEstado[mesaId].orderId) {
                            delete mesasEstado[mesaId];
                        }
                    }
                });

                updates.forEach(update => {
                    // 🔥 【关键修复】服务器返回的 update.number 已经是 gtn（全局编号）
                    // 不能再通过 resolveGlobalTableNumber 解析，否则裸整数 "1" 会被
                    // display_name "1"（DOMICILIO）截胡，返回 gtn 11 而非 1
                    const rawNumber = String(update.number);
                    const numericOnly = /^\d+$/.test(rawNumber) ? rawNumber : resolveGlobalTableNumber(rawNumber);
                    if (!numericOnly) return; // 无法提取数字，跳过

                    const mesaIdMesa = `Mesa ${numericOnly}`;
                    const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
                    const mesaIdLocal = `${tablePrefix} ${numericOnly}`;

                    // 🔥 优先检查 "Mesa X" 格式（来自其他页面的数据）
                    let mesaId = mesaIdMesa;
                    let currentData = mesasEstado[mesaIdMesa];

                    // 如果 "Mesa X" 没有数据，检查当前语言格式
                    if (!currentData && mesaIdLocal !== mesaIdMesa) {
                        currentData = mesasEstado[mesaIdLocal];
                        if (currentData) {
                            mesaId = mesaIdLocal;
                        }
                    }

                    // 🔥 关键修复：如果还是找不到，搜索所有包含该桌号的键名
                    // 这解决了分类显示名称（如"室内1"）与标准格式不匹配的问题
                    if (!currentData) {
                        for (const key of Object.keys(mesasEstado)) {
                            const keyResolved = resolveGlobalTableNumber(key);
                            if (keyResolved && keyResolved === numericOnly && mesasEstado[key].cart) {
                                currentData = mesasEstado[key];
                                mesaId = key;
                                break;
                            }
                        }
                    }
                    const updateTimestamp = update.timestamp * 1000; // PHP时间戳转为JS毫秒

                    // 🔥 【关键修复】改进订单ID检测逻辑
                    // 原逻辑bug：当本地orderId为null时，即使服务器有新订单也不会触发更新
                    // 新逻辑：服务器有订单且（本地无订单 或 订单ID不同）= 需要更新
                    const serverHasOrder = !!update.orderId;
                    const localHasOrder = !!(currentData && currentData.orderId);
                    // 🔥 修复：使用 String() 统一类型后比较，防止 number vs string 类型不匹配
                    const orderIdChanged = serverHasOrder && (!localHasOrder || String(currentData.orderId) !== String(update.orderId));

                    // 🔥 【关键修复】改进版本号检测逻辑
                    // 原逻辑bug：当本地version为null时，服务器有version也不会触发更新
                    // 新逻辑：服务器有版本且（本地无版本 或 版本不同）= 需要更新
                    const serverHasVersion = !!update.version;
                    const localHasVersion = !!(currentData && currentData.version);
                    const versionChanged = serverHasVersion && (!localHasVersion || update.version !== currentData.version);

                    // 🔥 【新增】状态变化检测
                    // 当桌位从空闲变为占用时，应该立即更新
                    const localStatus = currentData?.estado || 'libre';
                    const serverStatus = update.status === 'ocupada' ? 'ocupada' : (update.status === 'occupied' ? 'ocupada' : 'libre');
                    const statusChanged = localStatus !== serverStatus;

                    // 🔥 【新增】金额变化检测
                    // 当服务器返回的金额与本地金额不同时，应该更新（例如客户追加订单）
                    const serverTotal = update.total ? parseFloat(update.total) : 0;
                    const localTotal = currentData?.total ? parseFloat(currentData.total) : 0;
                    const totalChanged = serverTotal > 0 && Math.abs(serverTotal - localTotal) > 0.01;

                    // 检查是否应用更新：
                    // 1. 跳过有_skipAutoUpdate标志的桌位（短暂保护刚更新的数据）
                    // 2. 跳过有未同步离线数据的桌位（_offlineNewItems有数据）
                    // 3. 如果本地没有该桌位数据
                    // 4. 或者订单ID发生变化（新订单/不同订单）
                    // 5. 或者版本号发生变化
                    // 6. 或者状态发生变化（如从空闲变为占用）
                    // 7. 或者服务器的更新时间戳比本地存储的时间戳新
                    let shouldUpdate = false;

                    // 🔥 全局结账保护：如果桌位刚刚结账（15秒内），且服务器返回占用状态，跳过更新
                    // 这防止了PaymentQueue异步处理期间轮询将已结账桌位重新标记为占用
                    const checkedOutTime = window._recentlyCheckedOutTables?.[numericOnly];
                    if (checkedOutTime && (Date.now() - checkedOutTime) < 15000) {
                        if (update.status === 'ocupada' || update.status === 'occupied') {
                            // 桌位刚结账，服务器可能还没更新，跳过此次占用状态写入
                            shouldUpdate = false;
                            // 直接进入下一个桌位的处理
                            return;
                        }
                    }

                    // 🔥 清理过期的全局结账追踪（超过60秒的条目）
                    if (window._recentlyCheckedOutTables) {
                        Object.keys(window._recentlyCheckedOutTables).forEach(tNum => {
                            if (Date.now() - window._recentlyCheckedOutTables[tNum] > 60000) {
                                delete window._recentlyCheckedOutTables[tNum];
                            }
                        });
                    }

                    // 检查是否有真正未同步的离线数据
                    const hasRealUnsyncedData = currentData &&
                                                currentData._offlineNewItems &&
                                                Array.isArray(currentData._offlineNewItems) &&
                                                currentData._offlineNewItems.length > 0;

                    // 如果桌位标记为跳过自动更新，则不更新
                    if (currentData && currentData._skipAutoUpdate) {
                        shouldUpdate = false;
                    } else if (currentData && currentData._pendingServerSync) {
                        shouldUpdate = false;
                     } else if (currentData && currentData._syncing) {
                        shouldUpdate = false;
                    } else if (currentData && currentData._pendingSync) {
                        shouldUpdate = false;
                    } else if (currentData && currentData._paymentCompleted && currentData.estado === 'libre') {
                        shouldUpdate = false;
                    // 单纯的 _offline 标志不应该永久阻止服务器更新
                    } else if (hasRealUnsyncedData) {
                        shouldUpdate = false;
                    } else if (!currentData || !currentData.timestamp) {
                        shouldUpdate = true;
                    } else if (orderIdChanged) {
                        shouldUpdate = true;
                    } else if (versionChanged) {
                        shouldUpdate = true;
                    } else if (statusChanged) {
                        shouldUpdate = true;
                    } else if (totalChanged) {
                        // 🔥 【新增】金额变化更新 - 客户追加订单时触发
                        shouldUpdate = true;
                    } else {
                        const localTimestamp = new Date(currentData.timestamp).getTime();
                        if (!isNaN(localTimestamp) && updateTimestamp > localTimestamp) {
                            shouldUpdate = true;
                        }
                    }

                    if (shouldUpdate) {
                        // 转换从服务器收到的状态为本地渲染函数期望的状态
                        let statusToStore = update.status;
                        if (statusToStore === 'occupied') {
                            statusToStore = 'ocupada';
                        } else if (statusToStore === 'free') {
                            statusToStore = 'libre';
                        }

                        // 🔥 预结单结算中状态保护：如果本地标记为liquidando且服务器状态是ocupada，保留liquidando
                        if (window.posSettings?.proformaSettlingStatus && currentData?.estado === 'liquidando' && statusToStore === 'ocupada') {
                            statusToStore = 'liquidando';
                        }

                        // 🔥 防御性编程：优先使用服务器订单ID，如果为空则使用本地订单ID兜底
                        const effectiveOrderId = update.orderId || currentData?.orderId;
                        const hasOrderId = !!effectiveOrderId;

                        // 🔥 防止重复打印：智能检测打印状态
                        // 【修复】区分新订单和追加订单：
                        // - 新订单：检查纯 orderId 是否已打印（兼容POS创建的订单）
                        // - 追加订单：检查 orderId + version 组合是否已打印
                        const printedOrders = JSON.parse(localStorage.getItem('printed_kitchen_orders') || '[]');
                        const printKeyWithVersion = effectiveOrderId + '_' + (update.version || 'v0');

                        // 🔥 检测是否为追加订单（版本变化 + 订单ID相同 + 本地已有该订单）
                        const isAppendOrder = versionChanged && !orderIdChanged && effectiveOrderId && localHasOrder;

                        // 🔥 智能判断是否已打印：
                        // - 追加订单：只检查 orderId + version 组合（允许同一订单的新版本触发打印）
                        // - 新订单：检查纯 orderId 或 orderId + version（兼容两种记录格式）
                        let alreadyPrinted = false;
                        if (isAppendOrder) {
                            // 追加订单：只检查版本组合key
                            alreadyPrinted = printedOrders.includes(printKeyWithVersion);
                        } else {
                            // 新订单：检查纯orderId（兼容旧记录）或版本组合key
                            alreadyPrinted = effectiveOrderId && (
                                printedOrders.includes(effectiveOrderId) ||
                                printedOrders.includes(printKeyWithVersion)
                            );
                        }

                        // 🔥 使用 "Mesa X" 格式作为存储键，与渲染逻辑保持一致
                        const finalMesaId = mesaIdMesa;

                        // 清理可能冲突的旧格式条目（包括双前缀zombie如 "Mesa Mesa 3"）
                        ['餐桌', 'Table'].forEach(prefix => {
                            const oldKey = `${prefix} ${numericOnly}`;
                            if (mesasEstado[oldKey] && oldKey !== finalMesaId) {
                                delete mesasEstado[oldKey];
                            }
                        });
                        // 清理双前缀zombie: "Mesa Mesa 3" 等
                        const doublePrefix = `Mesa ${rawNumber}`;
                        if (doublePrefix !== finalMesaId && mesasEstado[doublePrefix]) {
                            delete mesasEstado[doublePrefix];
                        }

                        // 🔥【2026-04-03 关键修复】cart 身份验证 + 金额验证
                        let preservedCart = currentData?.cart || null;

                        // 🔥【防御层1】cart_gtn 身份验证：cart 不属于本桌位则丢弃
                        if (preservedCart && currentData?.cart_gtn !== undefined && String(currentData.cart_gtn) !== numericOnly) {
                            preservedCart = null;
                        }

                        // 🔥【防御层2】金额验证：cart 总额与服务器 total 不匹配则丢弃
                        if (preservedCart && Array.isArray(preservedCart) && preservedCart.length > 0 && update.total > 0) {
                            const cartTotal = preservedCart.reduce((sum, item) => {
                                const price = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
                                return sum + (price * (item.quantity || 1));
                            }, 0);
                            const serverTotal = parseFloat(update.total);
                            // 🔥 cart 和 total 不匹配 → cart 被污染，丢弃
                            if (Math.abs(cartTotal - serverTotal) > 0.5) {
                                preservedCart = null;
                            }
                        }

                        // 🔥 只保留真正需要同步的离线数据（有未同步的新增商品）
                        const hasUnsyncedItems = currentData?._offlineNewItems &&
                                                 Array.isArray(currentData._offlineNewItems) &&
                                                 currentData._offlineNewItems.length > 0;
                        const preservedOfflineNewItems = hasUnsyncedItems ? currentData._offlineNewItems : null;
                        const preservedHasOnlineOrder = hasUnsyncedItems ? (currentData?._hasOnlineOrder || false) : false;

                        // 🔥 关键修复：在线模式下始终使用服务器总额
                        // 服务器返回的总额是从WooCommerce订单计算的，是权威数据
                        let effectiveTotal;
                        if (update.total && update.total > 0) {
                            // 服务器有总额：使用服务器总额（权威数据）
                            effectiveTotal = update.total;
                        } else if (hasUnsyncedItems && currentData?.total > 0) {
                            // 有未同步离线数据且服务器无总额：保留本地总额
                            effectiveTotal = currentData.total;
                        } else {
                            // 兜底：0
                            effectiveTotal = 0;
                        }

                        // 🔥 【关键修复】保留折扣信息
                        const preservedDiscount = currentData?.discount || 0;

                        tableDebugLog('polling', '轮询更新桌位', { mesaId: finalMesaId, oldStatus: mesasEstado[finalMesaId] ? mesasEstado[finalMesaId].estado : 'none', newStatus: statusToStore, orderId: update.order_id });
                        mesasEstado[finalMesaId] = {
                            estado: statusToStore,
                            orderId: effectiveOrderId, // 使用有效订单ID
                            timestamp: new Date(updateTimestamp).toISOString(),
                            total: effectiveTotal,
                            discount: preservedDiscount, // 🔥 保留折扣信息
                            version: update.version || (Date.now() + '_0000'), // 保存版本号
                            // 🔥 PWA离线支持：保留本地cart数据，断网后仍可访问
                            cart: preservedCart,
                            cart_gtn: preservedCart ? parseInt(numericOnly) : undefined,
                            // 🔥 只保留真正需要同步的离线数据
                            ...(preservedOfflineNewItems && { _offlineNewItems: preservedOfflineNewItems }),
                            ...(preservedHasOnlineOrder && { _hasOnlineOrder: preservedHasOnlineOrder }),
                            // 🔥 关键修复：在线模式下不再保留 _offline 标志
                            // 只有当有未同步数据时才标记
                            ...(hasUnsyncedItems && { _offline: true })
                        };

                        // 🔥 如果找到的键名与 finalMesaId 不同，需要迁移数据并删除旧键
                        if (mesaId && mesaId !== finalMesaId && mesasEstado[mesaId]) {
                            delete mesasEstado[mesaId];
                        }

                        needsRender = true;

                        // 🔥 轮询检测：检测到其他页面（servicio-mesa.php / usuario-cocina.php / carrito-cliente.php）创建的新订单或追加订单时自动打印厨房小票
                        // 【修复】追加订单也需要打印：isAppendOrder 检测版本变化（同一订单ID但版本不同）

                        // 🔥 轮询厨房打印检测（入队机制）
                        // 只要 CLODOP 已配置且有厨房打印机，就自动触发
                        var _pollCanPrint = window.clodopConfig?.enabled && window.clodopConfig?.kitchenPrinter;
                        if (_pollCanPrint &&
                            hasOrderId && statusToStore === 'ocupada' && !alreadyPrinted) {
                            console.log('[轮询厨房打印] 加入打印队列:', {
                                桌号: mesaIdMesa,
                                订单ID: effectiveOrderId,
                                版本: update.version,
                                是否追加订单: isAppendOrder
                            });
                            if (typeof enqueueKitchenPrint === 'function') {
                                enqueueKitchenPrint(mesaIdMesa, effectiveOrderId, update.version, null, isAppendOrder);
                            }
                        }
                    }

                    // 🔥 【2026-03-10 修复】从服务器恢复外送客户信息（电话、地址等）
                    // ⚠️ 此逻辑放在 shouldUpdate 判断之外，确保即使桌位数据没有变化，
                    // 也能在本地 delivery 数据丢失时（如退出登录/清缓存后）从 WC 订单恢复
                    if (update.customer_info && typeof window.setDeliveryCustomerData === 'function') {
                        const existingData = typeof window.getDeliveryCustomerData === 'function'
                            ? window.getDeliveryCustomerData(mesaIdMesa) : null;
                        if (!existingData) {
                            const ci = update.customer_info;
                            window.setDeliveryCustomerData(mesaIdMesa, {
                                phone: ci.phone || '',
                                address: ci.address || '',
                                name: ci.name || '',
                                businessName: ci.business_name || '',
                                cifNif: ci.cif_nif || '',
                                notes: ci.notes || ''
                            });
                            console.log('[轮询] 🔄 从服务器恢复外送客户数据:', mesaIdMesa, update.customer_info);
                            needsRender = true;
                        }
                    }
                });

                // 注意：客户端僵尸清理已移除（服务端 ruiyi_get_tables_status 已包含可靠的僵尸验证逻辑）
                // 客户端清理依赖轮询数据的完整性，但 ruiyi_pos_live_table_statuses 可能因
                // 其他页面刷新而短暂不一致，导致误删有效桌位。

                if (needsRender) {
                    localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));

                    // 🔥 强制立即渲染桌位，使用明确的source参数绕过防抖延迟
                    if (typeof renderizarMesas === 'function') {
                        renderizarMesas('auto-update-immediate');
                    } else {
                        console.warn('renderizarMesas 函数未定义，无法刷新桌位视图。');
                    }
                }
            } else {
                // 服务器返回空数组 — 不再自动清理本地桌位
                // 服务端已在 ruiyi_get_tables_status 中验证真实订单
                // 空响应可能是 ruiyi_pos_live_table_statuses 短暂不一致，不应删除本地有效数据
            }
        }
    })
    .then(() => {
        _fetchTableStatusLoading = false;
        _fetchTableStatusErrors = 0;
    })
    .catch(error => {
        _fetchTableStatusLoading = false;
        _fetchTableStatusErrors++;
    });
}

/**
 * (可选) 简单的状态文本翻译示例，你需要根据需要扩展
 */
function translateTableStatus(status) {
    const statusMap = {
        'free': '空闲',
        'occupied': '占用',
        'ordering': '点餐中',
        'ordered': '已下单',
        'paid': '已结账',
        'reserved': '预定',
        'needs-cleaning': '待清理'
    };
    return statusMap[status.toLowerCase()] || status; // 如果没有匹配，返回原始状态
}


/**
 * 当用户选择桌位进入收银页面时更新桌位状态
 */
function updateTableStatusOnSelect(tableNumber, status = 'ordering') {
    
    // 立即更新本地状态显示
    updateLocalTableStatus(tableNumber, status);
    
    // 发送到服务器更新
    const formData = new URLSearchParams();
    formData.append('action', 'update_table_status');
    const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
    formData.append('table_id', tableNumber.replace(tablePrefix + ' ', '')); // 只发送数字
    formData.append('status', status === 'ordering' ? 'occupied' : status);
    formData.append('nonce', posNonce);
    formData.append('is_pos', 'yes'); // 标记为POS请求
    
    fetch(posAjaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: formData
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
        } else {
            console.error('桌位状态同步失败:', data.message);
        }
    })
    .catch(error => {
        console.error('桌位状态同步出错:', error);
    });
}

/**
 * 立即更新本地桌位状态显示
 */
function updateLocalTableStatus(tableNumber, status) {
    const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');

    // 更新本地状态 - 确保'libre'和'available'都映射为'libre'
    let localStatus = status;
    if (status === 'ordering') {
        localStatus = 'ocupada';
    } else if (status === 'available' || status === 'libre') {
        localStatus = 'libre';
    }

    // 如果状态是'libre'（释放桌位），删除所有可能匹配的键
    if (localStatus === 'libre') {
        const tableNumeric = resolveGlobalTableNumber(tableNumber);
        // 🔥🔥🔥 【2026-01-19 关键修复】提取桌号前缀，避免不同桌位类型被错误删除
        // 例如：释放 COMEDOR2 时不应删除 DOMICILIO2 的数据
        // Get prefix via mapping, not regex (avoids "9.5" -> prefix "9.")
        let tablePrefix = '';
        const _mappings = window.tableCategoryMappings;
        if (_mappings) {
            const _allM = Array.isArray(_mappings) ? _mappings : Object.values(_mappings);
            const _mapping = _allM.find(m => String(m.global_table_number) === String(tableNumeric));
            if (_mapping) {
                tablePrefix = (_mapping.category_name || '').toUpperCase().trim();
            }
        }
        if (!tablePrefix) {
            const _prefixMatch = tableNumber.toString().match(/^(Mesa|餐桌|Table|桌)\s*/i);
            tablePrefix = _prefixMatch ? _prefixMatch[1].toUpperCase().trim() : '';
        }

        // 定义通用前缀列表（这些前缀之间可以互相匹配）
        const genericPrefixes = ['', 'MESA', 'MESA ', '餐桌', '餐桌 ', 'TABLE', 'TABLE ', '桌'];
        const isGenericSearch = genericPrefixes.includes(tablePrefix);

        // 尝试删除各种可能的键名格式
        // 🔥 修复：如果条目有 _paymentCompleted 标志，保留而不删除（防止轮询将刚结账桌位重新标记为占用）
        Object.keys(mesasEstado).forEach(key => {
            // 🔥 保护已结账的条目：不删除带有 _paymentCompleted 的条目
            if (mesasEstado[key] && mesasEstado[key]._paymentCompleted) {
                return; // 跳过，保留保护标志
            }

            // 精确匹配（最高优先级）
            if (key === tableNumber) {
                delete mesasEstado[key];
                return;
            }

            // 🔥 提取候选键的前缀和数字
            const keyNumeric = resolveGlobalTableNumber(key);
            let keyPrefix = '';
            if (_mappings) {
                const _allM2 = Array.isArray(_mappings) ? _mappings : Object.values(_mappings);
                const _keyMapping = _allM2.find(m => String(m.global_table_number) === String(keyNumeric));
                if (_keyMapping) {
                    keyPrefix = (_keyMapping.category_name || '').toUpperCase().trim();
                }
            }
            if (!keyPrefix) {
                const _kPrefixMatch = key.match(/^(Mesa|餐桌|Table|桌)\s*/i);
                keyPrefix = _kPrefixMatch ? _kPrefixMatch[1].toUpperCase().trim() : '';
            }
            const isGenericCandidate = genericPrefixes.includes(keyPrefix);

            // 数字必须匹配
            if (tableNumeric && keyNumeric === tableNumeric) {
                // 🔥 前缀匹配规则：
                // 1. 前缀完全相同（COMEDOR == COMEDOR）
                // 2. 都是通用前缀（Mesa 1 可以匹配 餐桌 1）
                const prefixMatch = (tablePrefix === keyPrefix) ||
                                    (isGenericSearch && isGenericCandidate);

                if (prefixMatch) {
                    delete mesasEstado[key];
                }
            }
        });
    } else {
        // 设置状态
        const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table + ' ' : 'Mesa ';
        const tableKey = tableNumber.startsWith(tablePrefix) ? tableNumber : `${tablePrefix}${tableNumber}`;

        mesasEstado[tableKey] = {
            estado: localStatus,
            timestamp: new Date().toISOString(),
            orderId: null,
            total: 0
        };
    }

    localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));

    // 立即重新渲染桌位显示
    if (typeof renderizarMesas === 'function') {
        renderizarMesas('update-local-status');
    }
}

/**
 * 当订单完成时释放桌位状态
 */
function releaseTableOnOrderComplete(tableNumber) {

    // 立即更新本地状态为可用
    updateLocalTableStatus(tableNumber, 'libre');

    // 提取纯数字桌号
    const numericTableNumber = typeof ruiyiSafeResolveGlobalTableNumber === 'function'
        ? ruiyiSafeResolveGlobalTableNumber(tableNumber)
        : resolveGlobalTableNumber(tableNumber);

    if (!numericTableNumber) {
        console.warn('[释放桌位] 无法从桌位名称提取数字:', tableNumber);
        return;
    }

    // 发送到服务器更新
    const formData = new URLSearchParams();
    formData.append('action', 'update_table_status');
    formData.append('table_id', numericTableNumber);
    formData.append('status', 'available');
    formData.append('nonce', posNonce);
    formData.append('is_pos', 'yes');


    fetch(posAjaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: formData
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
        } else {
            console.error('[释放桌位] 服务器更新失败:', data);
        }
    })
    .catch(error => {
        console.error('[释放桌位] 出错:', error);
    });
}

/**
 * 同步桌位状态到服务器（用于订单创建时）
 */
function updateTableStatusToServer(tableNumber, status, orderId = null, total = null) {
    
    // 构建请求数据
    const formData = new URLSearchParams();
    formData.append('action', 'update_table_status');
    
    // 确保只发送数字桌号
    // 裸整数包装为 "Mesa X" 格式，避免被 display_name 截胡
    // 例如：裸 "1" 会匹配 DOMICILIO display_name "1" (gtn 11)，
    // 但 "Mesa 1" 正确返回 gtn 1
    let _safeInput = String(tableNumber).trim();
    if (/^\d+$/.test(_safeInput)) {
        _safeInput = 'Mesa ' + _safeInput;
    }
    const numericTableNumber = resolveGlobalTableNumber(_safeInput);
    formData.append('table_id', numericTableNumber);
    
    // 状态映射：确保发送正确的状态值
    let serverStatus = status;
    if (status === 'ordering') {
        serverStatus = 'occupied';
    } else if (status === 'free' || status === 'libre') {
        serverStatus = 'available';
    }
    formData.append('status', serverStatus);
    formData.append('nonce', posNonce);
    formData.append('is_pos', 'yes'); // 标记为POS请求
    
    // 如果有订单ID和总额，也发送到服务器
    if (orderId) {
        formData.append('order_id', orderId);
    }
    if (total) {
        formData.append('total', total);
    }
    
    // 发送AJAX请求
    fetch(posAjaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: formData
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            
            // 同步成功后，立即刷新桌位显示以显示最新的订单信息
            if (typeof fetchAndUpdateTableStatuses === 'function') {
                fetchAndUpdateTableStatuses();
            }
            
            // 如果在桌位管理页面，也刷新桌位网格显示
            if (document.getElementById('mesas-grid') && !document.getElementById('mesas').classList.contains('hidden')) {
                setTimeout(() => {
                    renderizarMesas('interval-update');
                }, 500);
            }
            
        } else {
            console.error('桌位状态同步失败 - 完整响应:', data);
        }
    })
    .catch(error => {
        console.error('桌位状态同步网络错误:', error);
    });
}

