        didOpen: () => {
            // 按产品分单点击事件
            document.getElementById('split-by-product-option').onclick = () => {
                Swal.close();
                initiateSplitBillingByProduct(tableNumber);
            };
            // 按金额分单点击事件
            document.getElementById('split-by-amount-option').onclick = () => {
                Swal.close();
                initiateSplitBillingByAmount(tableNumber);
            };
        }
    });
}

// 按产品分单 - 原有逻辑
function initiateSplitBillingByProduct(tableNumber) {

    // 🔥 确保tableNumber有效，如果没有则从sessionStorage获取
    let effectiveTableNumber = tableNumber;
    if (!effectiveTableNumber) {
        const viewModeData = sessionStorage.getItem('tableViewMode');
        if (viewModeData) {
            try {
                const viewMode = JSON.parse(viewModeData);
                effectiveTableNumber = viewMode.table;
            } catch (e) {
                console.error('[初始化分单] 解析sessionStorage失败:', e);
            }
        }
    }


    // 重置分单状态 - 使用Object.assign保持与SplitBillingManager.state的引用
    Object.assign(splitBillingState, {
        tableNumber: effectiveTableNumber,
        originalOrders: [],
        originalOrderIds: [],
        splitOrders: [],
        completedSplits: [],
        totalSplits: 0,
        allCompleted: false,
        isActive: true,
        selectedSplitId: null
    });


    // 获取餐桌订单数据
    fetchTableOrdersForSplitBilling(effectiveTableNumber);
}

function getAASplitPossibleTableKeys(tableNumber) {
    const rawTable = (tableNumber || '').toString().trim();
    const resolvedTable = rawTable && typeof resolveGlobalTableNumber === 'function'
        ? resolveGlobalTableNumber(rawTable)
        : rawTable;
    const currentPrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';

    return Array.from(new Set([
        rawTable,
        resolvedTable,
        `Mesa ${resolvedTable}`,
        `Mesa${resolvedTable}`,
        `Table ${resolvedTable}`,
        `Table${resolvedTable}`,
        `餐桌 ${resolvedTable}`,
        `餐桌${resolvedTable}`,
        `${currentPrefix} ${resolvedTable}`,
        `${currentPrefix}${resolvedTable}`
    ].filter(Boolean)));
}

function findAASplitTableState(tableNumber, stateMap) {
    if (!stateMap || typeof stateMap !== 'object') {
        return { key: '', data: null, keys: [] };
    }

    const possibleKeys = getAASplitPossibleTableKeys(tableNumber);
    for (const key of possibleKeys) {
        if (stateMap[key]) {
            return { key, data: stateMap[key], keys: possibleKeys };
        }
    }

    const resolvedTable = tableNumber && typeof resolveGlobalTableNumber === 'function'
        ? resolveGlobalTableNumber(tableNumber)
        : '';

    if (resolvedTable) {
        for (const key of Object.keys(stateMap)) {
            if (possibleKeys.includes(key)) {
                continue;
            }
            const keyResolved = typeof resolveGlobalTableNumber === 'function'
                ? resolveGlobalTableNumber(key)
                : '';
            if (keyResolved && keyResolved === resolvedTable) {
                return { key, data: stateMap[key], keys: possibleKeys };
            }
        }
    }

    return { key: '', data: null, keys: possibleKeys };
}

// 获取餐桌订单数据用于分单
function fetchTableOrdersForSplitBilling(tableNumber) {
    var ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
    var ajaxNonce = window.RUIYI_POS?.nonce;
    
    Swal.fire({
        title: '<?php echo ruiyi_translate("Cargando datos del pedido...", "Loading order data...", "获取订单数据..."); ?>',
        text: '<?php echo ruiyi_translate("Por favor espere", "Please wait", "请稍候"); ?>',
        allowOutsideClick: false,
        didOpen: () => { Swal.showLoading(); }
    });
    
    const formData = new URLSearchParams({
        action: 'ruiyi_pos_get_table_orders_for_split',
        table_number: tableNumber,
        nonce: ajaxNonce
    });
    
    fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: formData
    })
    .then(response => response.json())
    .then(data => {
        Swal.close();
        if (data.success && data.data.orders && data.data.orders.length > 0) {
            splitBillingState.originalOrders = data.data.orders;
            showSplitBillingModal(data.data);
        } else {
            Swal.fire({
                icon: 'warning',
                title: '<?php echo ruiyi_translate("No se encontraron pedidos", "No orders found", "没有找到订单"); ?>',
                text: '<?php echo ruiyi_translate("No hay órdenes disponibles para dividir en esta mesa", "No orders available for splitting at this table", "该桌位没有可分单的订单"); ?>'
            });
        }
    })
    .catch(error => {
        Swal.close();
        Swal.fire({
            icon: 'error',
            title: '<?php echo ruiyi_translate("Error al cargar datos", "Failed to load data", "获取数据失败"); ?>',
            text: '<?php echo ruiyi_translate("No se pueden cargar los datos del pedido, por favor intente de nuevo", "Unable to load order data, please try again", "无法获取订单数据，请重试"); ?>'
        });
    });
}

// 显示AA结账模态窗口
function showSplitBillingModal(tableData) {

    // 准备产品列表 - 只处理当前餐桌的订单
    // 每个产品按数量拆分成单独的项目，便于逐个分配
    const allProducts = [];
    if (tableData.orders && Array.isArray(tableData.orders)) {
        tableData.orders.forEach(order => {

            if (order.items && Array.isArray(order.items)) {
                order.items.forEach(item => {
                    const qty = parseInt(item.quantity || 1);
                    const unitPrice = parseFloat(item.price || 0);
                    // 将每个产品按数量拆分成单独的项目
                    for (let i = 0; i < qty; i++) {
                        allProducts.push({
                            id: `product_${order.id}_${item.product_id}_${i}_${Math.floor(Math.random() * 10000)}`,
                            orderId: order.id,
                            product_id: item.product_id, // 🔥 修复：使用正确的字段名product_id
                            item_id: item.item_id,       // 🔥 修复：保存WooCommerce订单项ID
                            name: item.name,
                            price: unitPrice,
                            quantity: 1,
                            total: unitPrice,
                            assigned: false,
                            splitOrderId: null,
                            completedCheckout: false
                        });
                    }
                });
            }
        });
    }
    
    
    // 🔥 获取原始订单ID - 从多个来源合并（支持多订单情况）
    const originalOrderIds = [];

    // 来源1：从锁定的购物车商品中提取
    if (window.cart && Array.isArray(window.cart)) {
        window.cart.forEach(item => {
            if (item.locked && item.orderId && !originalOrderIds.includes(item.orderId)) {
                originalOrderIds.push(item.orderId);
            }
        });
        if (originalOrderIds.length > 0) {
            console.log('[showSplitBillingModal] 从购物车提取订单ID:', originalOrderIds.slice());
        }
    }

    // 来源2：始终从tableData.orders提取并合并（不再是条件判断）
    if (tableData.orders && Array.isArray(tableData.orders)) {
        tableData.orders.forEach(order => {
            if (order.id && !originalOrderIds.includes(order.id)) {
                originalOrderIds.push(order.id);
            }
        });
        console.log('[showSplitBillingModal] 从tableData.orders提取订单ID，当前合计:', originalOrderIds.slice());
    }

    // 来源3：从localStorage的mesas_estado获取并合并
    try {
        const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
        const tableStateResult = findAASplitTableState(tableData.table_number, mesasEstado);
        const tableState = tableStateResult.data;

        // 提取单个orderId
        if (tableState && tableState.orderId && !originalOrderIds.includes(tableState.orderId)) {
            originalOrderIds.push(tableState.orderId);
            console.log('[showSplitBillingModal] 从mesas_estado提取orderId:', tableState.orderId, 'key:', tableStateResult.key);
        }

        // 🔥 提取orderIds数组（支持多订单）
        if (tableState && tableState.orderIds && Array.isArray(tableState.orderIds)) {
            tableState.orderIds.forEach(orderId => {
                if (orderId && !originalOrderIds.includes(orderId)) {
                    originalOrderIds.push(orderId);
                }
            });
            console.log('[showSplitBillingModal] 从mesas_estado.orderIds合并:', tableState.orderIds);
        }
    } catch (e) {
        console.error('[showSplitBillingModal] 解析mesas_estado失败:', e);
    }

    console.log('[showSplitBillingModal] 最终originalOrderIds (支持多订单):', originalOrderIds, '共', originalOrderIds.length, '个订单');

    // 将原始订单ID存储到splitBillingState中
    splitBillingState.originalOrderIds = originalOrderIds;


    // 🔥 强制确保tableNumber正确设置
    // 优先级：tableData.table_number > splitBillingState.tableNumber > sessionStorage
    let effectiveTableNumber = tableData.table_number || splitBillingState.tableNumber;

    // 如果还是没有，尝试从sessionStorage获取
    if (!effectiveTableNumber) {
        const viewModeData = sessionStorage.getItem('tableViewMode');
        if (viewModeData) {
            try {
                const viewMode = JSON.parse(viewModeData);
                effectiveTableNumber = viewMode.table;
            } catch (e) {
                console.error('[分单初始化] 解析sessionStorage失败:', e);
            }
        }
    }

    if (effectiveTableNumber) {
        splitBillingState.tableNumber = effectiveTableNumber;
    } else {
        console.error('[分单初始化] ✗ 无法获取桌号！');
    }


    splitBillingState.originalOrders = tableData.orders;

    // 尝试恢复已存在的分单状态（使用splitBillingState中的tableNumber）
    const savedState = loadSplitBillingState(splitBillingState.tableNumber);


    if (savedState && savedState.splitOrders && savedState.splitOrders.length > 0) {
        // 恢复已保存的分单状态，并合并原始订单ID
        splitBillingState.splitOrders = savedState.splitOrders;
        splitBillingState.completedSplits = savedState.completedSplits || [];
        splitBillingState.totalSplits = savedState.totalSplits;
        splitBillingState.selectedSplitId = savedState.selectedSplitId;
        splitBillingState.isActive = true;


        // 🔥 合并原始订单ID（支持多订单）
        if (savedState.originalOrderIds && savedState.originalOrderIds.length > 0) {
            const mergedIds = [...new Set([...originalOrderIds, ...savedState.originalOrderIds])];
            splitBillingState.originalOrderIds = mergedIds;
            console.log('[showSplitBillingModal] 合并savedState订单ID，最终:', mergedIds);
        }

        // 恢复产品分配状态
        splitBillingState.splitOrders.forEach((splitOrder, index) => {
            const isCompletedSplit = splitBillingState.completedSplits.includes(splitOrder.id);

            splitOrder.products.forEach(splitProduct => {
                const matchingProduct = allProducts.find(p =>
                    p.name === splitProduct.name &&
                    p.price === splitProduct.price &&
                    !p.assigned
                );
                if (matchingProduct) {
                    matchingProduct.assigned = true;
                    matchingProduct.splitOrderId = splitOrder.id;
                    // 标记属于已完成分单的产品
                    matchingProduct.completedCheckout = isCompletedSplit;
                } else {
                    console.warn(`[分单恢复] ⚠️ 找不到匹配产品:`, splitProduct.name, splitProduct.price);
                }
            });
        });

    } else {
        // 创建新的分单状态
        const firstSplit = createSplitOrder(1);
        splitBillingState.splitOrders = [firstSplit];
        splitBillingState.totalSplits = 1;
        splitBillingState.selectedSplitId = firstSplit.id;
        splitBillingState.completedSplits = [];
    }
    
    const modalHtml = `
        <div id="split-billing-modal" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center" style="z-index: 999999 !important;">
            <div class="bg-white rounded-lg shadow-xl w-11/12 h-5/6 max-w-7xl flex flex-col" style="z-index: 999999 !important;">
                <!-- Modal Header -->
                <div class="bg-orange-600 text-white p-4 rounded-t-lg">
                    <h2 class="text-xl font-bold text-center">
                        <i class="fas fa-users mr-2"></i>
                        <?php echo ruiyi_translate('Checkout AA', 'AA Checkout', 'AA结账'); ?>
                    </h2>
                </div>
                
                <!-- Modal Body -->
                <div class="flex-1 flex overflow-hidden">
                    <!-- Left Panel - Available Products -->
                    <div class="w-1/2 border-r border-gray-300 p-4 overflow-y-auto">
                        <h3 class="text-lg font-semibold mb-3 text-gray-800">
                            <i class="fas fa-list mr-2 text-blue-600"></i>
                            <?php echo ruiyi_translate('Productos disponibles', 'Available Products', '可分配产品'); ?>
                        </h3>
                        <div id="available-products-list" class="space-y-2">
                            ${allProducts.map(product => `
                                <div class="product-item bg-gray-50 p-3 rounded-lg border-2 border-transparent hover:border-blue-300 cursor-pointer transition-all"
                                    data-product-id="${product.id}">
                                    <div class="flex justify-between items-center">
                                        <div class="flex-1">
                                            <h4 class="font-medium text-gray-800">${product.name}</h4>
                                            <p class="text-sm text-gray-600">${product.quantity}x €${product.price.toFixed(2)} = €${product.total.toFixed(2)}</p>
                                        </div>
                                        <div class="ml-2">
                                            <i class="fas fa-plus-circle text-green-600 text-lg"></i>
                                        </div>
                                    </div>
                                </div>
                            `).join('')}
                        </div>
                    </div>
                    
                    <!-- Right Panel - Split Orders -->
                    <div class="w-1/2 p-4 overflow-y-auto">
                        <div class="flex justify-between items-center mb-3">
                            <h3 class="text-lg font-semibold text-gray-800">
                                <i class="fas fa-receipt mr-2 text-orange-600"></i>
                                <?php echo ruiyi_translate('Órdenes divididas', 'Split Orders', '分单订单'); ?>
                            </h3>
                            <button onclick="addNewSplitOrder()" class="bg-orange-600 hover:bg-orange-700 text-white px-3 py-1 rounded text-sm">
                                <i class="fas fa-plus mr-1"></i> <?php echo ruiyi_translate('Agregar división', 'Add Split', '新增分单'); ?>
                            </button>
                        </div>
                        <div id="split-orders-container" class="space-y-3">
                            <!-- Split orders will be populated here -->
                        </div>
                    </div>
                </div>
                
                <!-- Modal Footer - 简化布局 -->
                <div class="p-3 border-t border-gray-300 bg-gray-50 rounded-b-lg">
                    <div class="flex flex-wrap items-center justify-between gap-2">
                        <!-- 左侧：提示信息 -->
                        <div class="flex-1 min-w-0">
                            <div class="text-xs text-gray-600 bg-blue-50 px-2 py-1 rounded border border-blue-200 truncate">
                                <i class="fas fa-info-circle text-blue-600 mr-1"></i>
                                <?php echo ruiyi_translate('Seleccione un subpedido y agregue productos, luego haga clic en el botón de pago para ese subpedido', 'Select a split order, add products, then click its checkout button', '选择分单并添加产品，然后点击该分单的结账按钮'); ?>
                            </div>
                        </div>
                        <!-- 右侧：保存/关闭按钮 -->
                        <div class="flex items-center gap-2 flex-shrink-0">
                            <button id="aa-save-table-order-btn" onclick="saveTableOrderAndReturn()" class="bg-blue-500 hover:bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center whitespace-nowrap">
                                <i class="fas fa-save mr-1"></i>
                                <?php echo ruiyi_translate('Guardar mesa', 'Save Table Order', '保存桌位订单'); ?>
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    `;
    
    // 添加到页面
    document.body.insertAdjacentHTML('beforeend', modalHtml);

    // 存储产品数据到全局变量以供其他函数使用
    window.splitBillingProducts = allProducts;

    // 🔥 修复：根据保存的已完成产品ID标记产品状态
    if (splitBillingState.completedProductIds && splitBillingState.completedProductIds.length > 0) {
        console.log('[showSplitBillingModal] 恢复已完成产品状态，IDs:', splitBillingState.completedProductIds);
        window.splitBillingProducts.forEach(product => {
            if (splitBillingState.completedProductIds.includes(product.id)) {
                product.completedCheckout = true;
                product.assigned = true; // 已完成的产品也标记为已分配
            }
        });
    }

    // 渲染分单订单
    renderSplitOrders();

    // 更新所有产品项UI状态（显示已完成结账的产品为锁定状态）
    updateAllProductItemsUI();

    // 🔥 修复：初始化时更新保存按钮状态
    setTimeout(() => {
        updateSaveTableOrderButton();
    }, 50);

    // 添加产品点击事件委托
    const productsList = document.getElementById('available-products-list');
    if (productsList) {
        productsList.addEventListener('click', function(e) {
            const productItem = e.target.closest('.product-item');
            if (productItem) {
                const productId = productItem.getAttribute('data-product-id');
                if (productId) {
                    selectProduct(productId);
                }
            }
        });
    }

}

// 渲染分单订单列表
function renderSplitOrders() {
    const container = document.getElementById('split-orders-container');
    if (!container) return;


    // 检查是否还有未分配的产品
    const hasUnassignedProducts = window.splitBillingProducts &&
        window.splitBillingProducts.some(p => !p.assigned);


    container.innerHTML = splitBillingState.splitOrders.map((splitOrder, index) => {
        const splitNumber = index + 1;
        const splitTotal = splitOrder.products.reduce((sum, product) => sum + product.total, 0);
        const isSelected = splitBillingState.selectedSplitId === splitOrder.id;
        const hasProducts = splitOrder.products.length > 0;
        const isCompleted = splitBillingState.completedSplits.includes(splitOrder.id);

        // 分单状态样式
        let statusClass;
        if (isCompleted) {
            statusClass = 'bg-gradient-to-r from-green-100 to-green-200 border-green-400 border-2 opacity-75';
        } else if (isSelected) {
            statusClass = 'bg-gradient-to-r from-orange-100 to-orange-200 border-orange-400 border-3';
        } else {
            statusClass = 'bg-orange-50 border-orange-200 border-2';
        }

        // 🔥 修改：允许部分结账 - 只要分单有产品就可以结账
        const canCheckout = hasProducts;

        return `
            <div class="split-order-item ${statusClass} rounded-lg p-3 cursor-pointer transition-all duration-200 hover:shadow-md"
                data-split-id="${splitOrder.id}" onclick="selectSplitOrder('${splitOrder.id}')">
                <div class="flex justify-between items-center mb-2">
                    <h4 class="font-semibold ${isCompleted ? 'text-green-800' : 'text-orange-800'} flex items-center">
                        <i class="fas fa-receipt mr-1"></i>
                        <?php echo ruiyi_translate('División', 'Split', '分单'); ?> ${splitNumber}
                        ${isCompleted ? '<i class="fas fa-check-circle text-green-600 ml-2"></i>' : ''}
                        ${isSelected && !isCompleted ? '<i class="fas fa-arrow-left text-orange-600 ml-2"></i>' : ''}
