                    <div class="text-right flex items-center gap-2">
                        <span class="text-lg font-bold ${isCompleted ? 'text-green-600' : 'text-orange-600'}">€${splitTotal.toFixed(2)}</span>
                        ${hasProducts && !isCompleted ? `
                            <button onclick="removeSplitOrder('${splitOrder.id}'); event.stopPropagation();" class="text-red-500 hover:text-red-700 p-1">
                                <i class="fas fa-trash text-sm"></i>
                            </button>
                        ` : ''}
                    </div>
                </div>

                <div class="split-products space-y-1">
                    ${!hasProducts ? `
                        <p class="text-sm text-gray-500 italic text-center py-2">
                            ${isSelected ?
                                '<?php echo ruiyi_translate("Haga clic en los productos de la izquierda para agregar a esta división", "Click products on the left to add to this split", "点击左侧产品添加到此分单"); ?>' :
                                '<?php echo ruiyi_translate("Haga clic para seleccionar esta división", "Click to select this split", "点击选择此分单"); ?>'
                            }
                        </p>
                    ` : splitOrder.products.map(product => `
                        <div class="bg-white p-2 rounded border flex justify-between items-center ${isCompleted ? 'opacity-75' : ''}">
                            <div>
                                <span class="font-medium text-sm">${product.name}</span>
                                <span class="text-xs text-gray-600 ml-2">${product.quantity}x €${product.price.toFixed(2)}</span>
                            </div>
                            ${isCompleted ? `
                                <span class="text-gray-400 text-sm"><i class="fas fa-lock"></i></span>
                            ` : `
                                <button onclick="removeProductFromSplit('${splitOrder.id}', '${product.id}'); event.stopPropagation();" class="text-red-500 hover:text-red-700 text-sm">
                                    <i class="fas fa-times"></i>
                                </button>
                            `}
                        </div>
                    `).join('')}
                </div>

                <!-- 结账按钮或完成状态 -->
                ${isCompleted ? `
                    <div class="mt-3 pt-2 border-t border-green-300">
                        <div class="w-full bg-green-600 text-white font-bold py-2 px-4 rounded-lg flex items-center justify-center">
                            <i class="fas fa-check-circle mr-2"></i>
                            <?php echo ruiyi_translate('Checkout Completado', 'Checkout Completed', '已完成结账'); ?>
                        </div>
                        <!-- 🔥 打印分单小票按钮 -->
                        <button onclick="printSplitOrderReceipt('${splitOrder.id}'); event.stopPropagation();"
                                class="w-full mt-2 bg-blue-500 hover:bg-blue-600 text-white font-bold py-2 px-4 rounded-lg flex items-center justify-center transition-all">
                            <i class="fas fa-print mr-2"></i>
                            <?php echo ruiyi_translate('Imprimir Ticket', 'Print Receipt', '打印分单小票'); ?>
                        </button>
                    </div>
                ` : (hasProducts ? `
                    <div class="mt-3 pt-2 border-t border-orange-300">
                        ${canCheckout ? `
                            <button onclick="checkoutSingleSplit('${splitOrder.id}'); event.stopPropagation();"
                                    class="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-2 px-4 rounded-lg flex items-center justify-center transition-all">
                                <i class="fas fa-credit-card mr-2"></i>
                                <?php echo ruiyi_translate('Pagar Este Artículo', 'Pay This Item', '支付此项'); ?>
                            </button>
                        ` : `
                            <button disabled
                                    class="w-full bg-gray-400 text-white font-bold py-2 px-4 rounded-lg flex items-center justify-center cursor-not-allowed opacity-70"
                                    title="<?php echo ruiyi_translate('Debe asignar todos los productos primero', 'Must assign all products first', '必须先分配完所有产品'); ?>">
                                <i class="fas fa-lock mr-2"></i>
                                <?php echo ruiyi_translate('Pagar Este Artículo', 'Pay This Item', '支付此项'); ?>
                            </button>
                        `}
                        <button onclick="printSplitPreBill('${splitOrder.id}'); event.stopPropagation();"
                                class="w-full mt-2 bg-purple-500 hover:bg-purple-600 text-white font-bold py-2 px-4 rounded-lg flex items-center justify-center transition-all">
                            <i class="fas fa-print mr-2"></i>
                            <?php echo ruiyi_translate('Imprimir Pre-Cuenta', 'Print Pre-Bill', '打印预结单'); ?>
                        </button>
                    </div>
                ` : '')}
            </div>
        `;
    }).join('');
}

// 选择分单
function selectSplitOrder(splitId) {

    // 🔥🔥🔥 防止选中已完成结账的分单
    if (splitBillingState.completedSplits && splitBillingState.completedSplits.includes(splitId)) {
        console.log('[分单] 该分单已完成结账，不能选中:', splitId);
        Toastify({
            text: '<?php echo ruiyi_translate("Esta división ya está pagada", "This split is already paid", "该分单已完成结账"); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#f59e0b" }
        }).showToast();
        return;
    }

    if (splitBillingState.selectedSplitId !== splitId) {
        splitBillingState.selectedSplitId = splitId;

        // 重新渲染分单列表以更新选中状态
        renderSplitOrders();
    }
}

// 选择产品进行分配（简化版）
function selectProduct(productId) {

    if (!window.splitBillingProducts) {
        console.error('window.splitBillingProducts未定义');
        return;
    }

    const product = window.splitBillingProducts.find(p => p.id === productId);

    if (!product) {
        console.error('未找到产品，ID:', productId);
        return;
    }

    if (product.assigned) {
        return;
    }

    // 检查是否有选中的分单
    if (!splitBillingState.selectedSplitId) {
        alert('<?php echo ruiyi_translate("Por favor seleccione primero una división", "Please select a split order first", "请先选择一个分单"); ?>');
        return;
    }

    // 🔥🔥🔥 修复：检查选中的分单是否已完成结账
    let targetSplitId = splitBillingState.selectedSplitId;
    if (splitBillingState.completedSplits && splitBillingState.completedSplits.includes(targetSplitId)) {
        // 选中的分单已完成结账，自动切换到下一个未完成的分单
        const nextUncompletedSplit = splitBillingState.splitOrders.find(s =>
            !splitBillingState.completedSplits.includes(s.id)
        );

        if (nextUncompletedSplit) {
            targetSplitId = nextUncompletedSplit.id;
            splitBillingState.selectedSplitId = targetSplitId;
            renderSplitOrders(); // 更新UI显示新选中的分单
            console.log('[分单] 自动切换到未完成分单:', targetSplitId);
        } else {
            // 所有分单都已完成结账
            alert('<?php echo ruiyi_translate("Todas las divisiones ya están pagadas", "All splits are already paid", "所有分单都已完成结账"); ?>');
            return;
        }
    }

    // 直接分配到目标分单
    assignProductToSplit(productId, targetSplitId);
}

// 将产品分配到分单
function assignProductToSplit(productId, splitOrderId) {

    const product = window.splitBillingProducts.find(p => p.id === productId);
    const splitOrder = splitBillingState.splitOrders.find(s => s.id === splitOrderId);

    // 🔥🔥🔥 安全检查：禁止向已完成结账的分单添加产品
    if (splitBillingState.completedSplits && splitBillingState.completedSplits.includes(splitOrderId)) {
        console.warn('[分单] 尝试向已完成结账的分单添加产品，已阻止:', splitOrderId);
        return;
    }

    if (!product || !splitOrder || product.assigned) {
        console.error('分配失败：', {
            product: !!product,
            splitOrder: !!splitOrder,
            assigned: product?.assigned
        });
        return;
    }
    
    // 标记产品为已分配
    product.assigned = true;
    product.splitOrderId = splitOrderId;
    
    // 添加到分单中
    splitOrder.products.push(product);
    splitOrder.total = splitOrder.products.reduce((sum, p) => sum + p.total, 0);
    
    
    // 保存状态到localStorage
    saveSplitBillingState();
    
    // 更新UI
    updateProductItemUI(productId);
    renderSplitOrders();
    updateAssignedCount();
}

// 从分单中移除产品
function removeProductFromSplit(splitOrderId, productId) {
    const product = window.splitBillingProducts.find(p => p.id === productId);
    const splitOrder = splitBillingState.splitOrders.find(s => s.id === splitOrderId);
    
    if (!product || !splitOrder) return;
    
    // 从分单中移除
    splitOrder.products = splitOrder.products.filter(p => p.id !== productId);
    splitOrder.total = splitOrder.products.reduce((sum, p) => sum + p.total, 0);
    
    // 标记产品为未分配
    product.assigned = false;
    product.splitOrderId = null;
    
    // 保存状态到localStorage
    saveSplitBillingState();
    
    // 更新UI
    updateProductItemUI(productId);
    renderSplitOrders();
    updateAssignedCount();
}

// 🔥🔥🔥 打印分单小票
function printSplitOrderReceipt(splitOrderId) {
    console.log('[打印分单小票] 开始打印，分单ID:', splitOrderId);

    const splitOrder = splitBillingState.splitOrders.find(s => s.id === splitOrderId);
    if (!splitOrder) {
        console.error('[打印分单小票] 未找到分单:', splitOrderId);
        Toastify({
            text: '<?php echo ruiyi_translate("División no encontrada", "Split not found", "未找到分单"); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#ef4444" }
        }).showToast();
        return;
    }

    // 检查分单是否已完成结账
    if (!splitBillingState.completedSplits.includes(splitOrderId)) {
        console.warn('[打印分单小票] 分单尚未完成结账');
        Toastify({
            text: '<?php echo ruiyi_translate("La división no está pagada", "Split not paid yet", "分单尚未结账"); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#f59e0b" }
        }).showToast();
        return;
    }

    // 显示打印中提示
    Toastify({
        text: '<?php echo ruiyi_translate("Imprimiendo ticket...", "Printing receipt...", "正在打印小票..."); ?>',
        duration: 2000,
        gravity: "top",
        position: "center",
        style: { background: "#3b82f6" }
    }).showToast();

    // 计算分单总额
    const splitTotal = splitOrder.products.reduce((sum, p) => sum + (p.total || (p.price * (p.quantity || 1))), 0);

    // 获取分单编号
    const splitNumber = splitBillingState.splitOrders.findIndex(s => s.id === splitOrderId) + 1;

    // 准备分单数据
    const splitOrderData = {
        splitNumber: splitNumber,
        products: splitOrder.products.map(p => ({
            name: p.name,
            quantity: p.quantity || 1,
            price: p.price,
            total: p.total || (p.price * (p.quantity || 1))
        })),
        total: splitTotal,
        originalTotal: splitOrder.paymentDetails?.originalTotal || splitTotal,
        discountAmount: splitOrder.paymentDetails?.discountAmount || 0,
        pointsUsed: splitOrder.paymentDetails?.pointsUsed || 0,
        paymentMethod: splitOrder.paymentMethod || 'cash',
        cashAmount: splitOrder.paymentDetails?.cashAmount || 0,
        cardAmount: splitOrder.paymentDetails?.cardAmount || 0,
        woocommerce_order_id: splitOrder.wooOrderId || null
    };

    console.log('[打印分单小票] 分单数据:', splitOrderData);

    // 调用后端获取小票HTML
    const ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
    const ajaxNonce = window.RUIYI_POS?.nonce;

    const formData = new URLSearchParams({
        action: 'ruiyi_pos_get_split_receipt_html',
        table_number: splitBillingState.tableNumber || '',
        split_order_data: JSON.stringify(splitOrderData),
        nonce: ajaxNonce
    });

    fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: formData
    })
    .then(response => response.json())
    .then(data => {
        console.log('[打印分单小票] 后端返回:', data);

        if (data.success && data.data && data.data.html) {
            // 使用CLODOP打印
            if (typeof ruiyiUnifiedPrint === 'function') {
                const printSuccess = ruiyiUnifiedPrint(data.data.html, 'split_receipt_' + splitNumber);
                if (!printSuccess) {
                    throw new Error('CLODOP split receipt print failed');
                }
                console.log('[打印分单小票] ✅ 已调用 ruiyiUnifiedPrint');

                Toastify({
                    text: '<?php echo ruiyi_translate("Ticket enviado a impresora", "Receipt sent to printer", "小票已发送到打印机"); ?>',
                    duration: 2000,
                    gravity: "top",
                    position: "center",
                    style: { background: "#10b981" }
                }).showToast();
            } else {
                throw new Error('ruiyiUnifiedPrint is not available');
            }
        } else {
            console.error('[打印分单小票] 获取小票HTML失败:', data);
            Toastify({
                text: '<?php echo ruiyi_translate("Error al obtener el ticket", "Error getting receipt", "获取小票失败"); ?>',
                duration: 2000,
                gravity: "top",
                position: "center",
                style: { background: "#ef4444" }
            }).showToast();
        }
    })
    .catch(error => {
        console.error('[打印分单小票] 请求失败:', error);
        Toastify({
            text: '<?php echo ruiyi_translate("Error de conexión", "Connection error", "连接错误"); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#ef4444" }
        }).showToast();
    });
}

// 打印分单预结单（Pre-Bill / Proforma）
function printSplitPreBill(splitOrderId) {
    console.log('[分单预结单] 开始打印，分单ID:', splitOrderId);

    const splitOrder = splitBillingState.splitOrders.find(s => s.id === splitOrderId);
    if (!splitOrder || splitOrder.products.length === 0) {
        Toastify({
            text: '<?php echo ruiyi_translate("No hay productos en esta división", "No products in this split", "此分单没有产品"); ?>',
            duration: 2000, gravity: "top", position: "center",
            style: { background: "#ef4444" }
        }).showToast();
        return;
    }

    // 显示打印中提示
    Toastify({
        text: '<?php echo ruiyi_translate("Imprimiendo pre-cuenta...", "Printing pre-bill...", "正在打印预结单..."); ?>',
        duration: 2000, gravity: "top", position: "center",
        style: { background: "#9333ea" }
    }).showToast();

    // 获取分单编号和总额
    const splitNumber = splitBillingState.splitOrders.findIndex(s => s.id === splitOrderId) + 1;
    const splitTotal = splitOrder.products.reduce((sum, p) => sum + (p.total || (p.price * (p.quantity || 1))), 0);

    // 获取桌位显示名称
    let tableDisplayName = splitBillingState.tableNumber || '';
    const tableNumClean = tableDisplayName.toString().replace(/^(餐桌|Mesa|Table|桌位)\s*/i, '').trim();
    const globalNum = parseInt(tableNumClean);
    if (window.tableCategoryMappings && !isNaN(globalNum)) {
        const allMappings = Array.isArray(window.tableCategoryMappings)
            ? window.tableCategoryMappings
            : Object.values(window.tableCategoryMappings);
        const mapping = allMappings.find(m => parseInt(m.global_table_number) === globalNum);
        if (mapping && mapping.category_display_name) {
            tableDisplayName = mapping.category_display_name;
        }
    }

    // 获取店铺信息
    const storeInfo = window.RUIYI_POS_CONFIG?.storeInfo || {};
    const escapeHtml = (str) => {
        if (!str) return '';
        return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    };

    // 格式化当前时间
    const now = new Date();
    const formattedDate = now.toLocaleDateString('es-ES', { day: '2-digit', month: '2-digit', year: 'numeric' })
        + ' ' + now.toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' });
    const headerAlignment = window.clodopConfig?.headerAlignment || 'left';
    const storeNameFontSize = window.clodopConfig?.storeNameFontSize || 18;

    // Logo HTML
    let logoHtml = '';
    if (storeInfo.receiptLogo && storeInfo.receiptLogo.length > 5) {
        let logoUrl = storeInfo.receiptLogo;
        if (!logoUrl.startsWith('http') && !logoUrl.startsWith('data:')) {
            logoUrl = window.location.origin + (logoUrl.startsWith('/') ? '' : '/') + logoUrl;
        }
        logoHtml = `<div style="text-align:${headerAlignment};margin-bottom:3mm;"><img src="${escapeHtml(logoUrl)}" style="max-width:50mm;max-height:20mm;" alt="Logo" onerror="this.style.display='none'"></div>`;
    }

    // 店铺信息
    let storeInfoHtml = '';
    if (storeInfo.businessName) storeInfoHtml += `<div style="font-size:0.8em;line-height:1.35;margin-bottom:0.4mm;font-weight:normal;">${escapeHtml(storeInfo.businessName)}</div>`;
    if (storeInfo.cifNif) storeInfoHtml += `<div style="font-size:0.8em;line-height:1.35;margin-bottom:0.4mm;font-weight:normal;">CIF/NIF: ${escapeHtml(storeInfo.cifNif)}</div>`;
    if (storeInfo.address) storeInfoHtml += `<div style="font-size:0.8em;line-height:1.35;margin-bottom:0.4mm;font-weight:normal;">${escapeHtml(storeInfo.address)}</div>`;
    if (storeInfo.phone) storeInfoHtml += `<div style="font-size:0.8em;line-height:1.35;margin-bottom:0.4mm;font-weight:normal;">Tel: ${escapeHtml(storeInfo.phone)}</div>`;

    // 产品编号处理
    const removeProductNumber = (name) => {
        if (!name) return name;
        if (window.RUIYI_POS_CONFIG?.hideProductNumberOnReceipt !== true) return name;
        return name.replace(/^\d+[A-Za-z]?\.\s*/, '') || name;
    };

    // 生成商品列表HTML
    const _bilingual = window.clodopConfig?.receiptBilingual || false;
    let itemsHtml = '';
    splitOrder.products.forEach(p => {
        let itemName = p.name || 'Producto';
        if (_bilingual && p.name_zh) {
            const numMatch = itemName.match(/^(\d+[A-Za-z]?\.\s*)/);
            if (numMatch) {
                const prefix = numMatch[1].replace(/\s+$/, '');
                const esClean = itemName.substring(numMatch[0].length);
                const zhClean = p.name_zh.replace(/^\d+[A-Za-z]?\.\s*/, '');
                itemName = prefix + zhClean + esClean;
            }
        }
        itemName = removeProductNumber(itemName);
        const qty = p.quantity || 1;
        const price = parseFloat(p.price || 0);
        const itemTotal = p.total || (price * qty);
        itemsHtml += `<tr>
            <td class="item-name" style="white-space:nowrap;overflow:hidden;text-overflow:clip;text-transform:uppercase;word-break:normal;letter-spacing:normal;font-family:'Courier New','Lucida Console',monospace;font-size:0.8em;font-weight:normal;line-height:1.25;text-align:left;padding:0.8mm 0.5mm;">${escapeHtml(itemName.toUpperCase())}</td>
            <td style="text-align:center;font-weight:normal;font-size:0.9em;line-height:1.25;padding:0.8mm 0.5mm;">${qty}</td>
            <td style="text-align:right;font-weight:normal;font-size:0.9em;line-height:1.25;padding:0.8mm 0.5mm;">€${price.toFixed(2)}</td>
            <td style="text-align:right;font-weight:normal;font-size:0.9em;line-height:1.25;padding:0.8mm 0.5mm;">€${parseFloat(itemTotal).toFixed(2)}</td>
        </tr>`;
    });

    // 计算税额：所有产品都是含税价，税种/税率由设置模块控制
    const receiptTaxTotals = window.ruiyiCalculateIncludedReceiptTax(splitTotal);
    const subtotalWithoutTax = receiptTaxTotals.base;
    const taxAmount = receiptTaxTotals.tax;
    const receiptTaxLabel = window.ruiyiGetReceiptTaxDisplayLabel();

    // 生成预结单HTML
    const preBillHtml = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Pre-Cuenta ${escapeHtml(tableDisplayName)} - <?php echo ruiyi_translate('División', 'Split', '分单'); ?> ${splitNumber}</title>
  <style>
    @media print { @page { size: auto; margin: 5mm; } body { margin: 0; padding: 0; } }
	    body { font-family: "Courier New", "Lucida Console", monospace; width: 72mm; margin: 0 auto; padding: 5mm 4mm; box-sizing: border-box; font-size: 10pt; font-weight: normal; }
    .receipt { width: 100%; max-width: 72mm; }
    h2 { font-size: ${storeNameFontSize}pt; font-weight: bold; text-align: ${headerAlignment}; margin: 0 0 1mm 0; line-height: 1.15; }
    h4 { font-size: 1.1em; font-weight: bold; text-align: ${headerAlignment}; margin: 2mm 0 1mm 0; }
    .date-line, .invoice-number, .verifactu-invoice-number { text-align: ${headerAlignment} !important; }
    table { width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 1em; margin: 3px 0; }
    th { border-bottom: 2px dashed #000; text-align: left; font-weight: bold; padding: 0.8mm 0.5mm; }
    hr { border: none; border-top: 2px dashed #000; margin: 2.5mm 0; }
  </style>
</head>
<body>
  <div class="receipt">
    ${logoHtml}
    ${storeInfo.storeName ? `<h2>${escapeHtml(storeInfo.storeName).replace(/\n/g, '<br>')}</h2>` : ''}
    <div style="text-align:${headerAlignment};">${storeInfoHtml}</div>
    <h4>${escapeHtml(tableDisplayName)}</h4>
    <div class="date-line" style="font-size:0.8em;">Fecha: ${formattedDate}</div>
    <div style="text-align:center;font-weight:bold;font-size:1.2em;margin:3mm 0;padding:2mm 0;border-top:3px dashed #000;border-bottom:3px dashed #000;">
        PROFORMA
    </div>
    <hr>
    <table>
      <thead>
        <tr>
          <th style="width:50%;">Producto</th>
          <th style="width:15%;text-align:center;">Cant.</th>
          <th style="width:15%;text-align:right;">Precio</th>
          <th style="width:20%;text-align:right;">Total</th>
        </tr>
      </thead>
      <tbody>${itemsHtml}</tbody>
    </table>
    <hr>
    <table style="margin-top:2mm;">
      <tr><td colspan="3" style="text-align:right;padding:0.6mm 0.5mm;">Base Imponible:</td><td style="text-align:right;padding:0.6mm 0.5mm;">${subtotalWithoutTax.toFixed(2)}€</td></tr>
      <tr><td colspan="3" style="text-align:right;padding:0.6mm 0.5mm;">${receiptTaxLabel}</td><td style="text-align:right;padding:0.6mm 0.5mm;">${taxAmount.toFixed(2)}€</td></tr>
      <tr><td colspan="3" style="text-align:right;border-top:1px solid #333;font-weight:bold;padding-top:1.2mm;font-size:1.15em;">TOTAL:</td><td style="text-align:right;border-top:1px solid #333;font-weight:bold;padding-top:1.2mm;font-size:1.15em;">${splitTotal.toFixed(2)}€</td></tr>
    </table>
  </div>
</body>
</html>`;

    // 使用CLODOP打印
    if (typeof ruiyiUnifiedPrint === 'function') {
        const printSuccess = ruiyiUnifiedPrint(preBillHtml, 'split_prebill_' + splitNumber);
        if (!printSuccess) {
            Toastify({
                text: '<?php echo ruiyi_translate("Error al imprimir pre-cuenta", "Error printing pre-bill", "预结单打印失败"); ?>',
                duration: 2000, gravity: "top", position: "center",
                style: { background: "#ef4444" }
            }).showToast();
            return;
        }
        console.log('[分单预结单] ✅ 已发送到打印机');
        Toastify({
            text: '<?php echo ruiyi_translate("Pre-cuenta enviada a impresora", "Pre-bill sent to printer", "预结单已发送到打印机"); ?>',
            duration: 2000, gravity: "top", position: "center",
            style: { background: "#10b981" }
        }).showToast();
    } else {
        Toastify({
            text: '<?php echo ruiyi_translate("Función de impresión no disponible", "Print function not available", "打印功能不可用"); ?>',
            duration: 2000, gravity: "top", position: "center",
            style: { background: "#ef4444" }
        }).showToast();
    }
}

// 单独AA结账
function checkoutSingleSplit(splitOrderId) {
    
    const splitOrder = splitBillingState.splitOrders.find(s => s.id === splitOrderId);
    if (!splitOrder) {
        return;
    }
    
    if (splitOrder.products.length === 0) {
        alert('<?php echo ruiyi_translate("Esta división no tiene productos", "This split has no products", "此分单没有产品"); ?>');
        return;
    }
    
    // 保存当前状态到localStorage
    saveSplitBillingState();
    
    // 关闭分单模态窗口
    closeSplitBillingModal();
    
    // 直接处理单个分单的支付
    const splitNumber = splitBillingState.splitOrders.findIndex(s => s.id === splitOrderId) + 1;
    const totalSplits = splitBillingState.splitOrders.length;
    
    showSplitOrderPaymentDialog(splitOrder, splitNumber, totalSplits, () => {
        // 支付完成后的回调
        console.log('[AA结账回调] 支付完成，开始处理');

        // 标记当前分单为已完成
        if (!splitBillingState.completedSplits.includes(splitOrderId)) {
            splitBillingState.completedSplits.push(splitOrderId);
        }

        // 🔥 修复：记录已完成结账的产品ID到 splitBillingState（不依赖 window.splitBillingProducts）
        if (!splitBillingState.completedProductIds) {
            splitBillingState.completedProductIds = [];
        }
        splitOrder.products.forEach(splitProduct => {
            if (!splitBillingState.completedProductIds.includes(splitProduct.id)) {
                splitBillingState.completedProductIds.push(splitProduct.id);
            }
        });
        console.log('[AA结账回调-v4] 已完成产品IDs:', splitBillingState.completedProductIds);

        // 🔥 关键修复：更新 window.splitBillingProducts 中对应产品的 completedCheckout 状态
        if (window.splitBillingProducts && Array.isArray(window.splitBillingProducts)) {
            splitOrder.products.forEach(splitProduct => {
                // 按名称和价格匹配
                const matchingProducts = window.splitBillingProducts.filter(p =>
                    p.name === splitProduct.name &&
                    Math.abs(p.price - splitProduct.price) < 0.01 &&
                    !p.completedCheckout
                );
                // 标记第一个匹配的产品为已完成
                if (matchingProducts.length > 0) {
                    matchingProducts[0].completedCheckout = true;
                    matchingProducts[0].assigned = true;
                    console.log('[AA结账回调-v4] ✓ 标记产品为已完成:', splitProduct.name);
                }
            });
        }

        // 更新分单状态并保存
        saveSplitBillingState();

        // 🔥 检测逻辑 v5：关键修复 - 必须比较原始总产品数
        let allProductsPaid = false;
        let detectionMethod = '';

        // 🔥 首先获取原始产品总数（这是核心数据）
        let totalOriginalProducts = 0;

        // 来源1：从 window.splitBillingProducts 获取（最可靠）
        if (window.splitBillingProducts && window.splitBillingProducts.length > 0) {
            totalOriginalProducts = window.splitBillingProducts.length;
        }
        // 来源2：从 originalOrders 计算
        else if (splitBillingState.originalOrders && Array.isArray(splitBillingState.originalOrders)) {
            splitBillingState.originalOrders.forEach(order => {
                if (order.items && Array.isArray(order.items)) {
                    order.items.forEach(item => {
                        totalOriginalProducts += parseInt(item.quantity || 1);
                    });
                }
            });
        }

        // 计算分单中的产品数据
        const remainingSplits = splitBillingState.splitOrders.filter(s =>
            s.products.length > 0 && !splitBillingState.completedSplits.includes(s.id)
        );
        const totalSplitProducts = splitBillingState.splitOrders.reduce((sum, s) => sum + s.products.length, 0);
        const completedSplitProducts = splitBillingState.splitOrders
            .filter(s => splitBillingState.completedSplits.includes(s.id))
            .reduce((sum, s) => sum + s.products.length, 0);

        // 计算已完成结账的产品数（从 window.splitBillingProducts）
        let paidProductsCount = 0;
        if (window.splitBillingProducts && window.splitBillingProducts.length > 0) {
            paidProductsCount = window.splitBillingProducts.filter(p => p.completedCheckout).length;
        }

        console.log('[AA结账回调-v5] 检测数据:');
        console.log('  - 🔥 原始产品总数:', totalOriginalProducts);
        console.log('  - 分单总产品数:', totalSplitProducts);
        console.log('  - 已完成分单产品数:', completedSplitProducts);
        console.log('  - splitBillingProducts已付款数:', paidProductsCount);
        console.log('  - 剩余未支付分单:', remainingSplits.length);
        console.log('  - splitOrders数量:', splitBillingState.splitOrders.length);
        console.log('  - completedSplits:', JSON.stringify(splitBillingState.completedSplits));

        // ===== 核心判断：已付款产品数 === 原始产品总数 =====
        // 🔥 修复：只有当已完成结账的产品数等于原始产品总数时，才认为全部结账完成

        // 方法1：基于 window.splitBillingProducts 的 completedCheckout 状态（最准确）
        if (totalOriginalProducts > 0 && paidProductsCount === totalOriginalProducts) {
            allProductsPaid = true;
            detectionMethod = 'splitBillingProducts';
            console.log('[AA结账回调-v5] ✅ 方法1通过: paidProductsCount(' + paidProductsCount + ') === totalOriginalProducts(' + totalOriginalProducts + ')');
        }

        // 方法2：基于分单产品数（需要同时满足：分单产品数=原始总数 且 已完成分单产品数=分单产品数）
        if (!allProductsPaid && totalOriginalProducts > 0) {
            if (totalSplitProducts === totalOriginalProducts && completedSplitProducts === totalSplitProducts) {
                allProductsPaid = true;
                detectionMethod = 'splitOrders';
                console.log('[AA结账回调-v5] ✅ 方法2通过: 分单产品(' + totalSplitProducts + ') === 原始产品(' + totalOriginalProducts + ') 且 已完成(' + completedSplitProducts + ')');
            }
        }

        // 方法3：基于 completedProductIds 数量
        if (!allProductsPaid && splitBillingState.completedProductIds && splitBillingState.completedProductIds.length > 0) {
            if (totalOriginalProducts > 0 && splitBillingState.completedProductIds.length >= totalOriginalProducts) {
                allProductsPaid = true;
                detectionMethod = 'completedProductIds';
                console.log('[AA结账回调-v5] ✅ 方法3通过: completedProductIds(' + splitBillingState.completedProductIds.length + ') >= 原始产品(' + totalOriginalProducts + ')');
            }
        }

        // 🔥🔥🔥 方法4（关键修复）：基于已完成分单数 - 只有当所有产品都在分单中且都已完成时才触发
        // 注意：如果有产品未分配到分单，不应该触发此方法
        let allSplitsCompletedButProductsRemain = false;
        if (!allProductsPaid && splitBillingState.splitOrders && splitBillingState.splitOrders.length > 0) {
            const nonEmptySplits = splitBillingState.splitOrders.filter(s => s.products && s.products.length > 0);
            const completedCount = splitBillingState.completedSplits ? splitBillingState.completedSplits.length : 0;

            // 检查是否所有分单都已完成
            const allSplitsCompleted = nonEmptySplits.length > 0 && remainingSplits.length === 0 && completedCount >= nonEmptySplits.length;

            if (allSplitsCompleted) {
                // 🔥 关键检查：分单中的产品数是否等于原始产品总数
                if (totalSplitProducts === totalOriginalProducts) {
                    // 所有产品都在分单中，且都已支付
                    allProductsPaid = true;
                    detectionMethod = 'allSplitsCompleted';
                    console.log('[AA结账回调-v5] ✅ 方法4通过: 所有产品都在分单中且已完成 (分单产品:' + totalSplitProducts + ', 原始产品:' + totalOriginalProducts + ')');
                } else {
                    // 🔥🔥🔥 部分结账：有产品未分配到分单
                    allSplitsCompletedButProductsRemain = true;
                    console.log('[AA结账回调-v5] ⚠️ 部分结账: 所有分单已完成但有产品未分配 (分单产品:' + totalSplitProducts + ', 原始产品:' + totalOriginalProducts + ', 剩余:' + (totalOriginalProducts - totalSplitProducts) + ')');
                }
            }
        }

        console.log('[AA结账回调-v5] allProductsPaid:', allProductsPaid, '检测方法:', detectionMethod || '未通过任何检测', 'allSplitsCompletedButProductsRemain:', allSplitsCompletedButProductsRemain);

        // 🔥🔥🔥 修复：所有产品结账后不再自动关闭，而是返回AA弹窗让用户可以打印小票
        // 用户需要点击"关闭桌位订单"按钮才会真正关闭弹窗并返回桌位模块
        if (allProductsPaid) {
            console.log('[AA结账回调-v6] ✅ 所有产品已结账，标记完成并返回AA弹窗（等待用户点击关闭按钮）');

            // 标记所有分单已完成
            splitBillingState.allCompleted = true;
            saveSplitBillingState();

            // 🔥🔥🔥 关键修复：检查所有分单的支付方式，如果包含现金则打开钱箱
            let hasAnyCashPayment = false;
            if (splitBillingState.splitOrders && splitBillingState.splitOrders.length > 0) {
                splitBillingState.splitOrders.forEach(split => {
                    // 检查 paymentMethod
                    if (split.paymentMethod === 'cash' || split.paymentMethod === 'mixed') {
                        hasAnyCashPayment = true;
                    }
                    // 检查 paymentDetails
                    if (split.paymentDetails) {
                        if (split.paymentDetails.cashAmount > 0 || split.paymentDetails.paymentMethod === 'cash' || split.paymentDetails.paymentMethod === 'mixed') {
                            hasAnyCashPayment = true;
                        }
                    }
                });
            }

            console.log('[AA结账回调-v5] 检测现金支付:', hasAnyCashPayment);

            if (hasAnyCashPayment) {
                console.log('[AA结账回调-v5] 🔥 检测到现金支付，尝试打开钱箱...');
                try {
                    if (typeof clodopOpenCashDrawer === 'function') {
                        clodopOpenCashDrawer();
                        console.log('[AA结账回调-v5] ✅ 已调用 clodopOpenCashDrawer');
                    } else if (typeof abrirCajonDinero === 'function') {
                        abrirCajonDinero();
                        console.log('[AA结账回调-v5] ✅ 已调用 abrirCajonDinero');
                    } else {
                        console.warn('[AA结账回调-v5] ⚠️ 未找到钱箱函数');
                    }
                } catch (error) {
                    console.error('[AA结账回调-v5] 打开钱箱失败:', error);
                }
            }

            Toastify({
                text: '<?php echo ruiyi_translate("Todos los pagos completados, haga clic en cerrar para finalizar", "All payments completed, click close to finish", "所有结账已完成，点击关闭按钮完成结算"); ?>',
                duration: 3000,
                gravity: "top",
                position: "center",
                style: { background: "#10b981" }
            }).showToast();

            // 🔥🔥🔥 修改：不再自动关闭，而是返回AA弹窗让用户可以打印小票
            // 用户点击"关闭桌位订单"按钮后才真正关闭弹窗
            setTimeout(() => {
                // 重新打开分单弹窗
                let reopenTableNumber = splitBillingState.tableNumber;
                if (!reopenTableNumber) {
                    const viewModeData = sessionStorage.getItem('tableViewMode');
                    if (viewModeData) {
                        try {
                            const viewMode = JSON.parse(viewModeData);
                            reopenTableNumber = viewMode.table;
                            splitBillingState.tableNumber = reopenTableNumber;
                        } catch (e) {
                            console.error('[AA结账回调-v6] 解析sessionStorage失败:', e);
                        }
                    }
                }
                console.log('[AA结账回调-v6] 所有产品已付款，返回AA弹窗，桌号:', reopenTableNumber);

                showSplitBillingModal({
                    table_number: reopenTableNumber,
                    orders: splitBillingState.originalOrders
                });

                // 更新保存按钮显示为"关闭桌位订单"
                setTimeout(() => {
                    updateSaveTableOrderButton();
                    console.log('[AA结账回调-v6] 已更新按钮为关闭桌位订单');
                }, 100);
            }, 300);

            return; // 🔥 重要：直接返回，不执行下面的清理代码
        }

        // ========== 以下代码只在有未完成分单时执行（已废弃，但保留以防万一） ==========
        // 实际上这段代码不会被执行，因为上面的return已经返回了
        if (false) { // 🔥 废弃代码块开始
            const ajaxUrl_unused = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
            const ajaxNonce_unused = window.RUIYI_POS?.nonce;
            const savedTableNumber_unused = splitBillingState.tableNumber;

            // 🔥 获取所有原订单IDs（支持多订单情况）
            let originalOrderIds = [];

            // 来源1：splitBillingState.originalOrderIds
            if (splitBillingState.originalOrderIds && splitBillingState.originalOrderIds.length > 0) {
                originalOrderIds = [...splitBillingState.originalOrderIds];
            }

            // 来源2：splitBillingState.originalOrders
            if (splitBillingState.originalOrders && splitBillingState.originalOrders.length > 0) {
                const orderIdsFromOrders = splitBillingState.originalOrders.map(o => o.id).filter(id => id);
                orderIdsFromOrders.forEach(id => {
                    if (!originalOrderIds.includes(id)) {
                        originalOrderIds.push(id);
                    }
                });
            }

            // 来源3：从购物车中提取
            if (window.cart && Array.isArray(window.cart)) {
                window.cart.forEach(item => {
                    if (item.locked && item.orderId && !originalOrderIds.includes(item.orderId)) {
                        originalOrderIds.push(item.orderId);
                    }
                });
            }

            // 来源4：从localStorage mesas_estado中提取
            try {
                const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                const tableKey = savedTableNumber ? savedTableNumber.toString().replace(/^餐桌\s*/, '') : '';
                if (tableKey && mesasEstado[tableKey]) {
                    if (mesasEstado[tableKey].orderId && !originalOrderIds.includes(mesasEstado[tableKey].orderId)) {
                        originalOrderIds.push(mesasEstado[tableKey].orderId);
                    }
                    // 检查是否有多个订单
                    if (mesasEstado[tableKey].orderIds && Array.isArray(mesasEstado[tableKey].orderIds)) {
                        mesasEstado[tableKey].orderIds.forEach(id => {
                            if (id && !originalOrderIds.includes(id)) {
                                originalOrderIds.push(id);
                            }
                        });
                    }
                }
            } catch (e) {
                console.error('[AA结账回调] 获取mesas_estado失败:', e);
            }

            console.log('[AA结账回调] 原订单IDs (多来源合并):', originalOrderIds);

            if (originalOrderIds.length > 0) {
                const formData = new URLSearchParams({
                    action: 'ruiyi_pos_save_partial_aa_checkout',
                    table_number: savedTableNumber,
                    original_order_ids: JSON.stringify(originalOrderIds),
                    remaining_products: JSON.stringify([]), // 空数组，表示没有剩余产品
                    completed_payments: JSON.stringify([]),
                    nonce: ajaxNonce
                });

                fetch(ajaxUrl, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                    body: formData
                })
                .then(response => response.json())
                .then(data => {
                    console.log('[AA结账回调] 后端保存结果:', data);
                })
                .catch(error => {
                    console.error('[AA结账回调] 后端保存失败:', error);
                });
            }

            // 🔥 清理分单状态
            clearSplitBillingState(splitBillingState.tableNumber);

            // 🔥 彻底清空该桌位的localStorage数据（设置为空闲状态）
            const clearedTableNumber = splitBillingState.tableNumber;

            // 🔥 提取桌号数字部分
            let tableNumeric = '';
            if (clearedTableNumber) {
                tableNumeric = resolveGlobalTableNumber(clearedTableNumber);
            }

            console.log('[AA结账回调-v5] 清理桌位状态，原桌号:', clearedTableNumber, '数字:', tableNumeric);

            // 🔥 全局结账保护：标记此桌位刚刚结账
            if (tableNumeric) {
                if (!window._recentlyCheckedOutTables) window._recentlyCheckedOutTables = {};
                window._recentlyCheckedOutTables[tableNumeric] = Date.now();
            }

            try {
                // 🔥 清理 mesas_estado - 设置为空闲状态（保留保护标志）
                const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                const allPossibleKeys = [
                    tableNumeric,
                    `Mesa ${tableNumeric}`,
                    `Mesa${tableNumeric}`,
                    `Table ${tableNumeric}`,
                    `Table${tableNumeric}`,
                    `餐桌 ${tableNumeric}`,
                    `餐桌${tableNumeric}`,
                    `室内${tableNumeric}`,
                    `室内 ${tableNumeric}`,
                    clearedTableNumber // 原始格式
                ];

                // 🔥 修复：设置为libre+保护标志（而非删除），防止轮询重新写入ocupada
                let clearedKeys = [];
                allPossibleKeys.forEach(key => {
                    if (key && mesasEstado[key]) {
                        mesasEstado[key] = {
                            estado: 'libre',
                            orderId: null,
                            total: 0,
                            timestamp: new Date().toISOString(),
                            _paymentCompleted: true,
                            _skipAutoUpdate: true
                        };
                        clearedKeys.push(key);
                    }
                });

                // 确保标准键存在
                const standardKey = `Mesa ${tableNumeric}`;
                if (!mesasEstado[standardKey]) {
                    mesasEstado[standardKey] = {
                        estado: 'libre',
                        orderId: null,
                        total: 0,
                        timestamp: new Date().toISOString(),
                        _paymentCompleted: true,
                        _skipAutoUpdate: true
                    };
                }

                localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
                console.log('[AA结账回调-v5] ✓ 已清理mesas_estado中的键为libre:', clearedKeys);

                // 🔥 同时清理 carritos_mesas
                const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
                let deletedCarritoKeys = [];
                allPossibleKeys.forEach(key => {
                    if (key && carritosGuardados[key]) {
                        delete carritosGuardados[key];
                        deletedCarritoKeys.push(key);
                    }
                });
                localStorage.setItem('carritos_mesas', JSON.stringify(carritosGuardados));
                if (deletedCarritoKeys.length > 0) {
                    console.log('[AA结账回调-v5] ✓ 已删除carritos_mesas中的键:', deletedCarritoKeys);
                }

            } catch (e) {
                console.error('[AA结账回调] 清空localStorage失败:', e);
            }

            // 🔥 清理全局桌位状态缓存
            if (window.tableStatuses && tableNumeric) {
                window.tableStatuses[tableNumeric] = {
                    status: 'available',
                    order_id: null,
                    total: 0
                };
                console.log('[AA结账回调-v5] ✓ 已更新window.tableStatuses');
            }

            // 🔥 清理 window.mesasEstadoCache（如果存在）
            if (window.mesasEstadoCache) {
                const allCacheKeys = [
                    tableNumeric,
                    `Mesa ${tableNumeric}`,
                    `餐桌 ${tableNumeric}`,
                    clearedTableNumber
                ];
                allCacheKeys.forEach(key => {
                    if (key && window.mesasEstadoCache[key]) {
                        delete window.mesasEstadoCache[key];
                    }
                });
            }

            // 重置分单状态
            splitBillingState.isActive = false;
            splitBillingState.allCompleted = false;
            splitBillingState.splitOrders = [];
            splitBillingState.completedSplits = [];
            splitBillingState.completedProductIds = [];
            splitBillingState.originalOrderIds = [];

            // 清空购物车
            if (typeof syncCart === 'function') {
                syncCart([]);
            } else {
                window.cart = [];
            }

            // 清除桌位视图模式
            sessionStorage.removeItem('tableViewMode');

            // 🔥 立即切换到桌位模块（使用正确的方法）
            console.log('[AA结账回调-v5] 正在切换到桌位模块...');

            setTimeout(() => {
                // 方法1：使用 cambiarSeccion 函数（主要方法）
                if (typeof cambiarSeccion === 'function') {
                    console.log('[AA结账回调-v5] 使用 cambiarSeccion 切换');
                    cambiarSeccion('mesas');
                }
                // 方法2：点击导航链接（备选方法）
                else {
                    const mesasLink = document.querySelector('a[href="#mesas"]');
                    if (mesasLink) {
                        console.log('[AA结账回调-v5] 点击 mesas 链接');
                        mesasLink.click();
                    } else {
                        console.warn('[AA结账回调-v5] 未找到桌位导航链接');
                    }
                }

                // 🔥 强制从后端获取最新状态并刷新UI
                setTimeout(() => {
                    console.log('[AA结账回调-v5] 开始刷新桌位状态...');

                    // 🔥 首先从后端获取最新状态（这会更新localStorage）
                    if (typeof fetchAndUpdateTableStatuses === 'function') {
                        console.log('[AA结账回调-v5] 调用 fetchAndUpdateTableStatuses 获取后端最新状态');
                        fetchAndUpdateTableStatuses();
                    }

                    // 🔥 延迟后渲染桌位卡片（等待后端数据返回）
                    setTimeout(() => {
                        if (typeof renderizarMesas === 'function') {
                            console.log('[AA结账回调-v5] 调用 renderizarMesas 刷新桌位显示');
                            renderizarMesas('aa-checkout-complete');
                        }
                    }, 300);

                    // 🔥 再次延迟刷新确保UI完全更新
                    setTimeout(() => {
                        if (typeof fetchAndUpdateTableStatuses === 'function') {
                            fetchAndUpdateTableStatuses();
                        }
                        setTimeout(() => {
                            if (typeof renderizarMesas === 'function') {
                                renderizarMesas('aa-checkout-complete-delayed');
                            }
                        }, 200);
                    }, 800);

                    // 🔥 最后一次兜底刷新
                    setTimeout(() => {
                        if (typeof renderizarMesas === 'function') {
                            renderizarMesas('aa-checkout-final');
                        }
                    }, 1500);
                }, 200);
            }, 300);

            // return; // 已废弃
        } // 🔥 关闭 if (false) 废弃代码块

        // 🔥🔥🔥 关键修复：当所有已创建的分单完成但还有产品未分配时，
        // 不应该自动触发"部分结账"，而是返回分单弹窗让用户继续操作
        // （用户可以创建更多分单，或者通过其他方式处理剩余产品）
        // allSplitsCompletedButProductsRemain 的情况会落到下面的默认处理中

        // 🔥 还有未完成的分单，或者所有分单已完成但有产品未分配，返回分单弹窗
        Toastify({
            text: '<?php echo ruiyi_translate("División completada", "Split completed", "分单已完成"); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#10b981" }
        }).showToast();

        // 直接重新打开分单界面
        setTimeout(() => {
            // 🔥 确保桌号正确
            let reopenTableNumber = splitBillingState.tableNumber;
            if (!reopenTableNumber) {
                const viewModeData = sessionStorage.getItem('tableViewMode');
                if (viewModeData) {
                    try {
                        const viewMode = JSON.parse(viewModeData);
                        reopenTableNumber = viewMode.table;
                        splitBillingState.tableNumber = reopenTableNumber;
                    } catch (e) {
                        console.error('[AA结账回调] 解析sessionStorage失败:', e);
                    }
                }
            }
            console.log('[AA结账回调] 重新打开分单弹窗，桌号:', reopenTableNumber);

            showSplitBillingModal({
                table_number: reopenTableNumber,
                orders: splitBillingState.originalOrders
            });

            // 🔥 重新打开弹窗后，更新保存按钮显示状态
            setTimeout(() => {
                updateSaveTableOrderButton();
                console.log('[AA结账回调] 已更新保存按钮状态');

                // 🔥🔥🔥 自动选中下一个未完成结账的分单
                if (splitBillingState.completedSplits && splitBillingState.completedSplits.length > 0) {
                    const nextUncompletedSplit = splitBillingState.splitOrders.find(s =>
                        !splitBillingState.completedSplits.includes(s.id)
                    );
                    if (nextUncompletedSplit && splitBillingState.selectedSplitId !== nextUncompletedSplit.id) {
                        splitBillingState.selectedSplitId = nextUncompletedSplit.id;
                        renderSplitOrders();
                        console.log('[AA结账回调] 已自动选中下一个未完成分单:', nextUncompletedSplit.id);
                    }
                }
            }, 100);
        }, 300);
    });
}

// 添加新的分单
function addNewSplitOrder() {
    const newIndex = splitBillingState.splitOrders.length + 1;
    const newSplit = createSplitOrder(newIndex);
    
    splitBillingState.splitOrders.push(newSplit);
    splitBillingState.totalSplits = splitBillingState.splitOrders.length;
    
    // 如果这是第一个分单或者当前没有选中的分单，则选中新分单
    if (!splitBillingState.selectedSplitId || splitBillingState.splitOrders.length === 1) {
        splitBillingState.selectedSplitId = newSplit.id;
    }
    
    // 保存状态到localStorage
    saveSplitBillingState();
    
    renderSplitOrders();
}

// 删除分单
function removeSplitOrder(splitOrderId) {
    if (splitBillingState.splitOrders.length <= 1) {
        Swal.fire({
            icon: 'warning',
            title: '<?php echo ruiyi_translate('No se puede eliminar', 'Cannot Delete', '不能删除'); ?>',
            text: '<?php echo ruiyi_translate('Debe mantener al menos una división', 'At least one split order must remain', '至少需要保留一个分单'); ?>'
        });
        return;
    }
    
    const splitOrder = splitBillingState.splitOrders.find(s => s.id === splitOrderId);
    if (!splitOrder) return;
    
    // 将分单中的产品返回到未分配状态
    splitOrder.products.forEach(product => {
        const originalProduct = window.splitBillingProducts.find(p => p.id === product.id);
        if (originalProduct) {
            originalProduct.assigned = false;
            originalProduct.splitOrderId = null;
        }
    });
    
    // 删除分单
    splitBillingState.splitOrders = splitBillingState.splitOrders.filter(s => s.id !== splitOrderId);
    splitBillingState.totalSplits = splitBillingState.splitOrders.length;
    
    // 重新编号分单ID
    const oldSelectedId = splitBillingState.selectedSplitId;
    splitBillingState.splitOrders.forEach((split, index) => {
        const oldId = split.id;
        split.id = `split_${splitBillingState.tableNumber}_${index + 1}`;
        
        // 如果删除的是选中的分单，更新选中状态
        if (oldSelectedId === splitOrderId && splitBillingState.splitOrders.length > 0) {
            splitBillingState.selectedSplitId = splitBillingState.splitOrders[0].id;
        }
    });
    
    // 保存状态到localStorage
    saveSplitBillingState();
    
    // 更新UI
    updateAllProductItemsUI();
    renderSplitOrders();
    updateAssignedCount();
}

// 更新产品项UI状态
function updateProductItemUI(productId) {

    const productElement = document.querySelector(`[data-product-id="${productId}"]`);
    const product = window.splitBillingProducts.find(p => p.id === productId);


    if (!productElement || !product) {
        return;
    }

    // 🔥 修改：已完成结账的产品 - 直接隐藏，从左侧列表移除显示
    if (product.completedCheckout) {
        productElement.style.display = 'none';
        productElement.classList.add('product-paid-hidden');
        return; // 直接返回，不需要其他处理
    } else if (product.assigned) {
        productElement.classList.add('bg-green-100', 'border-green-300');
        productElement.classList.remove('bg-gray-50', 'border-transparent', 'cursor-pointer', 'hover:border-blue-300', 'bg-gray-200', 'border-gray-400', 'opacity-60');
        productElement.style.pointerEvents = '';
        const iconElement = productElement.querySelector('.fa-plus-circle, .fa-check-circle, .fa-lock');
        if (iconElement) {
            iconElement.className = 'fas fa-check-circle text-green-600 text-lg';
        }
    } else {
        productElement.classList.remove('bg-green-100', 'border-green-300', 'bg-gray-200', 'border-gray-400', 'opacity-60');
        productElement.classList.add('bg-gray-50', 'border-transparent', 'cursor-pointer', 'hover:border-blue-300');
        productElement.style.pointerEvents = '';
        const iconElement = productElement.querySelector('.fa-check-circle, .fa-plus-circle, .fa-lock');
        if (iconElement) {
            iconElement.className = 'fas fa-plus-circle text-green-600 text-lg';
        }
    }
}

// 更新所有产品项UI状态
function updateAllProductItemsUI() {
    window.splitBillingProducts.forEach(product => {
        updateProductItemUI(product.id);
    });
}

// 更新已分配计数
function updateAssignedCount() {
    if (!window.splitBillingProducts) {
        console.error('updateAssignedCount: window.splitBillingProducts未定义');
        return;
    }
    
    const assignedCount = window.splitBillingProducts.filter(p => p.assigned).length;
    const countElement = document.getElementById('assigned-count');
    
    
    if (countElement) {
        countElement.textContent = assignedCount;
    } else {
        console.error('未找到assigned-count元素');
    }
}

// 取消AA结账 - 直接退出，不需要确认弹窗
function cancelSplitBilling() {
    // 清理分单状态
    clearSplitBillingState(splitBillingState.tableNumber);

    // 重置内存中的分单状态
    splitBillingState.isActive = false;
    splitBillingState.allCompleted = false;
    splitBillingState.splitOrders = [];
    splitBillingState.completedSplits = [];
    splitBillingState.originalOrderIds = [];

    // 关闭分单模态窗口
    closeSplitBillingModal();
}

// 🔥 AA弹窗中的保存/关闭按钮 - 根据是否有已完成分单动态更新文字
function updateSaveTableOrderButton() {
    // 🔥 使用AA弹窗专用的按钮ID，避免与主收银界面的按钮冲突
    const btn = document.getElementById('aa-save-table-order-btn');
    if (!btn) {
        console.log('[updateSaveTableOrderButton] 未找到AA弹窗按钮');
        return;
    }

    // 检查是否有已完成的分单
    const hasCompletedSplits = splitBillingState.completedSplits && splitBillingState.completedSplits.length > 0;

    console.log('[updateSaveTableOrderButton] 检查状态 - 已完成分单:', splitBillingState.completedSplits?.length || 0, 'allCompleted:', splitBillingState.allCompleted);

    if (hasCompletedSplits) {
        // 🔥 有已完成的分单，按钮变为"关闭桌位订单"
        btn.innerHTML = '<i class="fas fa-times-circle mr-1"></i><?php echo ruiyi_translate("Cerrar mesa", "Close Table Order", "关闭桌位订单"); ?>';
        btn.classList.remove('bg-blue-500', 'hover:bg-blue-600');
        btn.classList.add('bg-red-500', 'hover:bg-red-600');
        console.log('[updateSaveTableOrderButton] ✅ 已更新为关闭按钮（红色）');
    } else {
        // 没有已完成的分单，显示"保存桌位订单"
        btn.innerHTML = '<i class="fas fa-save mr-1"></i><?php echo ruiyi_translate("Guardar mesa", "Save Table Order", "保存桌位订单"); ?>';
        btn.classList.remove('bg-red-500', 'hover:bg-red-600');
        btn.classList.add('bg-blue-500', 'hover:bg-blue-600');
        console.log('[updateSaveTableOrderButton] 显示保存按钮（蓝色）');
    }
}

// 🔥 新增：保存桌位订单并返回收银模块
function saveTableOrderAndReturn() {
    var ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
    var ajaxNonce = window.RUIYI_POS?.nonce;

    // 🔥 确保工具箱是关闭状态
    const cartActionsContainer = document.querySelector('.cart-actions-fixed');
    if (cartActionsContainer && window.Alpine) {
        const alpineData = Alpine.$data(cartActionsContainer);
        if (alpineData) {
            alpineData.toolboxOpen = false;
        }
    }

    // 🔥 首先检查是否有已完成的分单
    const hasCompletedSplits = splitBillingState.completedSplits && splitBillingState.completedSplits.length > 0;

    console.log('[saveTableOrderAndReturn] 已完成分单数量:', splitBillingState.completedSplits?.length || 0);

    // 🔥 如果没有已完成的分单，直接关闭弹窗
    if (!hasCompletedSplits) {
        console.log('[saveTableOrderAndReturn] 没有已完成的分单，直接关闭弹窗');
        // 清理分单状态
        clearSplitBillingState(splitBillingState.tableNumber);

        // 重置内存中的分单状态
        splitBillingState.isActive = false;
        splitBillingState.allCompleted = false;
        splitBillingState.splitOrders = [];
        splitBillingState.completedSplits = [];
        splitBillingState.completedProductIds = [];
        splitBillingState.originalOrderIds = [];

        // 关闭分单模态窗口
        closeSplitBillingModal();

        // 显示关闭提示
        Toastify({
            text: '<?php echo ruiyi_translate("Ventana cerrada", "Modal closed", "弹窗已关闭"); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#6b7280" }
        }).showToast();
        return;
    }

    // 获取未付款的产品（需要保留在桌位上）
    const remainingProducts = window.splitBillingProducts ?
        window.splitBillingProducts.filter(p => !p.completedCheckout) : [];

    console.log('[saveTableOrderAndReturn] 剩余未付款产品数量:', remainingProducts.length);

    // 获取已完成结账的分单支付信息（用于生成WooCommerce订单）
    const completedPayments = [];
    splitBillingState.splitOrders.forEach((splitOrder, index) => {
        if (splitBillingState.completedSplits.includes(splitOrder.id)) {
            completedPayments.push({
                splitId: splitOrder.id,
                splitNumber: index + 1,
                products: splitOrder.products,
                paymentDetails: splitOrder.paymentDetails,
                paymentMethod: splitOrder.paymentMethod
            });
        }
    });

    // 🔥 验证必需数据
    const tableNumber = splitBillingState.tableNumber;
    let originalOrderIds = splitBillingState.originalOrderIds ||
        (splitBillingState.originalOrders ? splitBillingState.originalOrders.map(o => o.id) : []);

    // 🔥 如果originalOrderIds仍然为空，尝试从其他来源获取
    if (!originalOrderIds || originalOrderIds.length === 0) {
        // 尝试从splitBillingState.originalOrders获取
        if (splitBillingState.originalOrders && splitBillingState.originalOrders.length > 0) {
            originalOrderIds = splitBillingState.originalOrders.map(o => o.id).filter(id => id);
            console.log('[saveTableOrderAndReturn] 从originalOrders提取IDs:', originalOrderIds);
        }
    }

    // 🔥 再次尝试从mesas_estado获取
    if (!originalOrderIds || originalOrderIds.length === 0) {
        try {
            const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
            const tableStateResult = findAASplitTableState(tableNumber, mesasEstado);
            const tableState = tableStateResult.data;
            if (tableState && tableState.orderId) {
                originalOrderIds = [tableState.orderId];
                console.log('[saveTableOrderAndReturn] 从mesas_estado提取orderId:', tableState.orderId, 'key:', tableStateResult.key);
            }
        } catch (e) {
            console.error('[saveTableOrderAndReturn] 解析mesas_estado失败:', e);
        }
    }

    console.log('[saveTableOrderAndReturn] 桌号:', tableNumber);
    console.log('[saveTableOrderAndReturn] 原订单IDs:', originalOrderIds);

    if (!tableNumber || !originalOrderIds || originalOrderIds.length === 0) {
        console.error('[saveTableOrderAndReturn] 缺少必要数据');
        Swal.fire({
            icon: 'error',
            title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
            text: '<?php echo ruiyi_translate("Faltan datos necesarios", "Missing required data", "缺少必要数据"); ?>'
        });
        return;
    }

    Swal.fire({
        title: '<?php echo ruiyi_translate("Guardando...", "Saving...", "保存中..."); ?>',
        text: '<?php echo ruiyi_translate("Actualizando el pedido de la mesa", "Updating table order", "正在更新桌位订单"); ?>',
        allowOutsideClick: false,
        didOpen: () => { Swal.showLoading(); }
    });

    // 调用后端保存部分结账
    const formData = new URLSearchParams({
        action: 'ruiyi_pos_save_partial_aa_checkout',
        table_number: tableNumber,
        original_order_ids: JSON.stringify(originalOrderIds),
        remaining_products: JSON.stringify(remainingProducts),
        completed_payments: JSON.stringify(completedPayments),
        nonce: ajaxNonce
    });

    fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: formData
    })
    .then(response => response.json())
    .then(data => {
        Swal.close();

        if (data.success) {
            // 清理分单状态
            clearSplitBillingState(splitBillingState.tableNumber);

            // 重置内存中的分单状态
            splitBillingState.isActive = false;
            splitBillingState.allCompleted = false;
            splitBillingState.splitOrders = [];
            splitBillingState.completedSplits = [];
            splitBillingState.completedProductIds = [];
            splitBillingState.originalOrderIds = [];

            // 关闭分单模态窗口
            closeSplitBillingModal();

            // 显示成功提示
            Toastify({
                text: '<?php echo ruiyi_translate("Pedido de mesa actualizado", "Table order updated", "桌位订单已更新"); ?>',
                duration: 3000,
                gravity: "top",
                position: "center",
                style: { background: "#10b981" }
            }).showToast();

            // 🔥 根据是否有剩余产品决定下一步操作
            const savedTableNumber = tableNumber;
            const hasRemainingProducts = remainingProducts && remainingProducts.length > 0;

            console.log('[saveTableOrderAndReturn] 剩余产品数量:', remainingProducts?.length || 0);

            if (hasRemainingProducts) {
                // 🔥 有剩余产品：更新数据后刷新页面，然后跳转到桌位模块
                console.log('[saveTableOrderAndReturn] 有剩余产品，准备刷新页面并跳转到桌位模块');

                // 🔥🔥🔥 关键修复：使用服务器返回的带有新item_id的数据
                const serverUpdatedItems = data.data?.updated_items || [];
                const serverOrderId = data.data?.order_id || originalOrderIds[0];

                // 将服务器返回的数据转换为购物车格式（包含正确的item_id）
                let updatedCartItems;
                if (serverUpdatedItems.length > 0) {
                    // 使用服务器返回的数据（包含新的item_id）
                    updatedCartItems = serverUpdatedItems.map(p => ({
                        id: p.product_id,
                        name: p.name,
                        price: parseFloat(p.price),
                        quantity: parseFloat(p.quantity) || 1,
                        locked: true,
                        orderId: p.order_id || serverOrderId,
                        itemId: p.item_id
                    }));
                } else {
                    // 回退：使用原始剩余产品数据
                    updatedCartItems = remainingProducts.map(p => ({
                        id: p.product_id || p.id,
                        name: p.name,
                        price: parseFloat(p.price),
                        quantity: parseFloat(p.quantity) || 1,
                        locked: true,
                        orderId: serverOrderId
                    }));
                }

                const newTotal = updatedCartItems.reduce((sum, item) => {
                    return sum + (parseFloat(item.price) * parseFloat(item.quantity));
                }, 0);

                // 🔥 更新localStorage中的mesas_estado
                try {
                    const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
                    const tableStateResult = findAASplitTableState(savedTableNumber, mesasEstado);
                    const resolvedTableNumber = savedTableNumber && typeof resolveGlobalTableNumber === 'function'
                        ? resolveGlobalTableNumber(savedTableNumber)
                        : savedTableNumber;
                    const tableKey = tableStateResult.key || (resolvedTableNumber ? `Mesa ${resolvedTableNumber}` : '');

                    if (tableKey) {
                        if (!mesasEstado[tableKey]) {
                            mesasEstado[tableKey] = {};
                        }
                        mesasEstado[tableKey].cart = updatedCartItems;
                        mesasEstado[tableKey].total = newTotal;
                        mesasEstado[tableKey].orderId = serverOrderId;
                        mesasEstado[tableKey].estado = 'ocupada';
                        if (resolvedTableNumber) {
                            mesasEstado[tableKey].cart_gtn = parseInt(resolvedTableNumber, 10);
                        }
                        localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
                        console.log('[saveTableOrderAndReturn] 已更新mesas_estado:', tableKey, '候选keys:', tableStateResult.keys);
                    }
                } catch (e) {
                    console.error('[saveTableOrderAndReturn] 更新mesas_estado失败:', e);
                }

                // 🔥 设置标记：刷新后跳转到桌位模块
                sessionStorage.setItem('redirectToTablesAfterReload', 'true');
                // 清除桌位视图模式，避免进入桌位收银页面
                sessionStorage.removeItem('tableViewMode');

                // 🔥 刷新页面
                window.location.reload();

            } else {
                // 🔥 没有剩余产品（全部已结账）：清空桌位状态并返回桌位模块
                console.log('[saveTableOrderAndReturn] 所有产品已结账，返回桌位模块');

                // 🔥🔥🔥 彻底清空该桌位的localStorage数据
                const clearedTableNumber = savedTableNumber;
                let tableNumeric = '';
                if (clearedTableNumber) {
                    tableNumeric = resolveGlobalTableNumber(clearedTableNumber);
                }

                console.log('[saveTableOrderAndReturn] 清理桌位状态，原桌号:', clearedTableNumber, '数字:', tableNumeric);

                try {
                    // 🔥 清理 mesas_estado - 删除所有可能的键格式
                    const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');

                    // 🔥 获取当前语言的桌位前缀
                    const currentPrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';

                    const allPossibleKeys = [
                        tableNumeric,
                        `Mesa ${tableNumeric}`,
                        `Mesa${tableNumeric}`,
                        `Table ${tableNumeric}`,
                        `Table${tableNumeric}`,
                        `餐桌 ${tableNumeric}`,
                        `餐桌${tableNumeric}`,
                        `室内${tableNumeric}`,
                        `室内 ${tableNumeric}`,
                        `${currentPrefix} ${tableNumeric}`,
                        `${currentPrefix}${tableNumeric}`,
                        clearedTableNumber // 原始格式
                    ];

                    let deletedKeys = [];
                    allPossibleKeys.forEach(key => {
                        if (key && mesasEstado[key]) {
                            delete mesasEstado[key];
                            deletedKeys.push(key);
                        }
                    });

                    localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
                    console.log('[saveTableOrderAndReturn] ✓ 已删除mesas_estado中的键:', deletedKeys);

                    // 🔥 同时清理 carritos_mesas
                    const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
                    let deletedCarritoKeys = [];
                    allPossibleKeys.forEach(key => {
                        if (key && carritosGuardados[key]) {
                            delete carritosGuardados[key];
                            deletedCarritoKeys.push(key);
                        }
                    });
                    localStorage.setItem('carritos_mesas', JSON.stringify(carritosGuardados));
                    if (deletedCarritoKeys.length > 0) {
                        console.log('[saveTableOrderAndReturn] ✓ 已删除carritos_mesas中的键:', deletedCarritoKeys);
                    }

                } catch (e) {
                    console.error('[saveTableOrderAndReturn] 清空localStorage失败:', e);
                }

                // 🔥 清理全局桌位状态缓存
                if (window.tableStatuses && tableNumeric) {
                    window.tableStatuses[tableNumeric] = {
                        status: 'available',
                        order_id: null,
                        total: 0
                    };
                    console.log('[saveTableOrderAndReturn] ✓ 已更新window.tableStatuses');
                }

                // 🔥 清理 window.mesasEstadoCache（如果存在）
                if (window.mesasEstadoCache) {
                    const currentPrefixCache = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
                    const allCacheKeys = [
                        tableNumeric,
                        `Mesa ${tableNumeric}`,
                        `Mesa${tableNumeric}`,
                        `餐桌 ${tableNumeric}`,
                        `餐桌${tableNumeric}`,
                        `室内${tableNumeric}`,
                        `室内 ${tableNumeric}`,
                        `${currentPrefixCache} ${tableNumeric}`,
                        `${currentPrefixCache}${tableNumeric}`,
                        clearedTableNumber
                    ];
                    allCacheKeys.forEach(key => {
                        if (key && window.mesasEstadoCache[key]) {
                            delete window.mesasEstadoCache[key];
                        }
                    });
                    console.log('[saveTableOrderAndReturn] ✓ 已清理mesasEstadoCache');
                }

                // 清空购物车
                if (typeof syncCart === 'function') {
                    syncCart([]);
                } else {
                    window.cart = [];
                }

                // 清除桌位视图模式
                sessionStorage.removeItem('tableViewMode');

                // 🔥 切换到桌位模块（使用正确的方法）
                if (typeof cambiarSeccion === 'function') {
                    cambiarSeccion('mesas');
                } else {
                    // 备选方案：点击桌位导航链接
                    const mesasLink = document.querySelector('a[href="#mesas"]');
                    if (mesasLink) {
                        mesasLink.click();
                    } else {
                        // 最后的备选：刷新页面
                        window.location.reload();
                    }
                }

                // 🔥🔥🔥 强制刷新桌位状态 - 先渲染再从后端获取
                setTimeout(() => {
                    console.log('[saveTableOrderAndReturn] 开始刷新桌位状态...');

                    // 🔥 首先立即渲染（使用已清理的localStorage数据）
                    if (typeof renderizarMesas === 'function') {
                        console.log('[saveTableOrderAndReturn] 第一次渲染 (本地数据已清理)');
                        renderizarMesas('aa-close-complete');
                    }

                    // 🔥 然后从后端获取最新状态并再次渲染
                    setTimeout(() => {
                        if (typeof fetchAndUpdateTableStatuses === 'function') {
                            console.log('[saveTableOrderAndReturn] 从后端获取最新状态');
                            fetchAndUpdateTableStatuses();
                        }

                        // 延迟后再次渲染（使用后端数据）
                        setTimeout(() => {
                            if (typeof renderizarMesas === 'function') {
                                console.log('[saveTableOrderAndReturn] 第二次渲染 (后端数据)');
                                renderizarMesas('aa-close-delayed');
                            }
                        }, 500);
                    }, 300);

                    // 🔥 最后一次兜底刷新
                    setTimeout(() => {
                        if (typeof fetchAndUpdateTableStatuses === 'function') {
                            fetchAndUpdateTableStatuses();
                        }
                        setTimeout(() => {
                            if (typeof renderizarMesas === 'function') {
                                renderizarMesas('aa-close-final');
                            }
                        }, 300);
                    }, 2000);
                }, 100);
            }

        } else {
            Swal.fire({
                icon: 'error',
                title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
                text: data.data?.message || '<?php echo ruiyi_translate("Error al guardar", "Failed to save", "保存失败"); ?>'
            });
        }
    })
    .catch(error => {
        Swal.close();
        console.error('[保存桌位订单] 请求失败:', error);
        Swal.fire({
            icon: 'error',
            title: '<?php echo ruiyi_translate("Error de conexión", "Connection Error", "连接错误"); ?>',
            text: error.message
        });
    });
}

// 关闭AA结账模态窗口
function closeSplitBillingModal() {
    const modal = document.getElementById('split-billing-modal');
    if (modal) {
        modal.remove();
    }
    
    // 保存状态到localStorage（在关闭前保存当前状态）
    if (splitBillingState.isActive && splitBillingState.tableNumber && splitBillingState.splitOrders.length > 0) {
        saveSplitBillingState();
    }
    
    // 只清理临时UI状态，保留分单核心数据
    window.splitBillingProducts = null;
}

// 开始AA结账流程
function startSplitBillingCheckout() {
    // 检查是否所有产品都已分配 - 必须分配完所有产品才能结账
    const unassignedProducts = window.splitBillingProducts.filter(p => !p.assigned);

    if (unassignedProducts.length > 0) {
        // 强制阻止结账，必须先分配完所有产品
        Swal.fire({
            icon: 'error',
            title: '<?php echo ruiyi_translate('No se puede continuar', 'Cannot Proceed', '无法继续'); ?>',
            html: `<div>
                <p><?php echo ruiyi_translate('Debe asignar todos los productos antes de continuar con el pago.', 'You must assign all products before proceeding to checkout.', '必须分配完所有产品才能进行结账。'); ?></p>
                <p class="mt-2 font-semibold"><?php echo ruiyi_translate('Productos sin asignar:', 'Unassigned products:', '未分配产品:'); ?> ${unassignedProducts.length}</p>
            </div>`,
            confirmButtonText: '<?php echo ruiyi_translate('Entendido', 'Got it', '知道了'); ?>',
            confirmButtonColor: '#ef4444'
        });
        return;
    }

    proceedWithSplitCheckout();
}

// 执行AA结账
function proceedWithSplitCheckout() {
    // 过滤掉空的分单
    const nonEmptySplits = splitBillingState.splitOrders.filter(split => split.products.length > 0);
    
    if (nonEmptySplits.length === 0) {
        Swal.fire({
            icon: 'warning',
            title: '<?php echo ruiyi_translate('No hay elementos de AA checkout', 'No AA Checkout Items', '没有AA结账项目'); ?>',
            text: '<?php echo ruiyi_translate('Por favor asigne primero productos a los elementos de AA checkout', 'Please assign products to AA checkout items first', '请先分配产品到AA结账项目中'); ?>'
        });
        return;
    }
    
    // 关闭分单模态窗口
    closeSplitBillingModal();
    
    // 开始逐个处理分单结账
    processSplitOrderSequentially(nonEmptySplits, 0);
}

// 逐个处理AA结账
function processSplitOrderSequentially(splitOrders, currentIndex) {
    if (currentIndex >= splitOrders.length) {
        // 所有分单处理完成
        handleAllSplitsCompleted();
        return;
    }
    
    const currentSplit = splitOrders[currentIndex];
    const splitNumber = currentIndex + 1;
    const totalSplits = splitOrders.length;
    
    showSplitOrderPaymentDialog(currentSplit, splitNumber, totalSplits, () => {
        // 当前分单支付完成，继续下一个
        processSplitOrderSequentially(splitOrders, currentIndex + 1);
    });
}

