        cancelButtonText: '<?php echo ruiyi_translate("Cancelar", "Cancel", "取消"); ?>',
        confirmButtonColor: '#10b981',
        cancelButtonColor: '#6b7280',
        width: '650px',
        customClass: {
            popup: 'swal2-popup-aa-checkout',
            htmlContainer: 'swal2-html-container-aa'
        },
        preConfirm: () => {
            // 验证支付方式已选择
            const selectedMethod = document.querySelector('.split-payment-method-btn.border-green-500, .split-payment-method-btn.border-blue-500, .split-payment-method-btn.border-purple-500');
            if (!selectedMethod) {
                Swal.showValidationMessage('<?php echo ruiyi_translate("Por favor seleccione un método de pago", "Please select a payment method", "请选择支付方式"); ?>');
                return false;
            }
            return true;
