        didOpen: (popup) => {
            // 支付方式选择
            popup.querySelectorAll('.split-payment-method-btn').forEach(btn => {
                btn.addEventListener('click', function() {
                    popup.querySelectorAll('.split-payment-method-btn').forEach(b => {
                        b.classList.remove('border-green-500', 'bg-green-50', 'border-blue-500', 'bg-blue-50', 'border-purple-500', 'bg-purple-50');
                        b.classList.add('border-gray-300');
                    });
                    const method = this.dataset.method;
                    if (method === 'cash') {
                        this.classList.add('border-green-500', 'bg-green-50');
                        popup.querySelector('#split-cash-section').classList.remove('hidden');
                        popup.querySelector('#split-mixed-payment-section').classList.add('hidden');
                    } else if (method === 'card') {
                        this.classList.add('border-blue-500', 'bg-blue-50');
                        popup.querySelector('#split-cash-section').classList.add('hidden');
                        popup.querySelector('#split-mixed-payment-section').classList.add('hidden');
                    } else if (method === 'mixed') {
                        this.classList.add('border-purple-500', 'bg-purple-50');
                        popup.querySelector('#split-cash-section').classList.add('hidden');
                        popup.querySelector('#split-mixed-payment-section').classList.remove('hidden');
                        // 初始化混合支付
                        const mixedCardInput = popup.querySelector('#split-mixed-card-amount');
                        if (mixedCardInput) mixedCardInput.value = splitTotal.toFixed(2);
                    }
                });
            });

            // 现金输入计算找零
            const receivedInput = popup.querySelector('#split-received-amount');
            if (receivedInput) {
                receivedInput.addEventListener('input', function() {
                    const received = parseFloat(this.value) || 0;
                    const currentTotal = splitOriginalTotal - splitCurrentDiscountAmount;
                    const change = received - currentTotal;
                    popup.querySelector('#split-change-calculation').style.display = 'block';
                    popup.querySelector('#split-received-display').textContent = '€' + received.toFixed(2);
                    popup.querySelector('#split-change-amount').textContent = '€' + Math.max(0, change).toFixed(2);
                });

                // 🔥 分单收款输入框按Enter键完成支付
                receivedInput.addEventListener('keydown', function(e) {
                    if (e.key === 'Enter') {
                        e.preventDefault();
                        e.stopPropagation();
                        const confirmButton = Swal.getConfirmButton();
                        if (confirmButton && !confirmButton.disabled) {
                            confirmButton.click();
                        }
                    }
                });
            }

            // 混合支付现金输入
            const mixedCashInput = popup.querySelector('#split-mixed-cash-amount');
            if (mixedCashInput) {
                mixedCashInput.addEventListener('input', function() {
                    const cashAmount = parseFloat(this.value) || 0;
                    const currentTotal = splitOriginalTotal - splitCurrentDiscountAmount;
                    const cardAmount = Math.max(0, currentTotal - cashAmount);
                    popup.querySelector('#split-mixed-card-amount').value = cardAmount.toFixed(2);
                    popup.querySelector('#split-mixed-payment-validation').style.display = 'block';
                    popup.querySelector('#split-mixed-cash-display').textContent = '€' + cashAmount.toFixed(2);
                    popup.querySelector('#split-mixed-card-display').textContent = '€' + cardAmount.toFixed(2);
                    popup.querySelector('#split-mixed-total-display').textContent = '€' + (cashAmount + cardAmount).toFixed(2);
                });

                // 🔥 分单混合支付输入框按Enter键完成支付
                mixedCashInput.addEventListener('keydown', function(e) {
                    if (e.key === 'Enter') {
                        e.preventDefault();
                        e.stopPropagation();
                        const confirmButton = Swal.getConfirmButton();
                        if (confirmButton && !confirmButton.disabled) {
                            confirmButton.click();
                        }
                    }
                });
            }
        }
    }).then((result) => {
        if (result.isConfirmed) {
            // 获取支付方式
            let paymentMethod = 'cash';
            let cashAmount = 0;
            let cardAmount = 0;
            const finalTotal = splitOriginalTotal - splitCurrentDiscountAmount;

            const selectedBtn = document.querySelector('.split-payment-method-btn.border-green-500, .split-payment-method-btn.border-blue-500, .split-payment-method-btn.border-purple-500');
            if (selectedBtn) {
                paymentMethod = selectedBtn.dataset.method;
                if (paymentMethod === 'cash') {
                    cashAmount = finalTotal;
                } else if (paymentMethod === 'card') {
                    cardAmount = finalTotal;
                } else if (paymentMethod === 'mixed') {
                    cashAmount = parseFloat(document.querySelector('#split-mixed-cash-amount')?.value) || 0;
                    cardAmount = finalTotal - cashAmount;
                }
            }

            // 处理分单支付
            processSplitOrderPayment(splitOrder, {
                paymentMethod,
                cashAmount,
                cardAmount,
                totalAmount: finalTotal,
                discountAmount: splitCurrentDiscountAmount,
                pointsUsed: splitPointsUsed,
                rewardUserId: splitRewardUserId,
                verifiedUserId: splitVerifiedUser?.user_id
            }, onComplete);
        }
    });
}

// 处理分单支付 - 🔥 修改：立即创建WooCommerce订单
function processSplitOrderPayment(splitOrder, paymentData, onComplete) {
    var ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
    var ajaxNonce = window.RUIYI_POS?.nonce;

    // 在分单对象中记录支付信息
    const splitOrderIndex = splitBillingState.splitOrders.findIndex(s => s.id === splitOrder.id);
    if (splitOrderIndex !== -1) {
        splitBillingState.splitOrders[splitOrderIndex].status = 'paid';
        splitBillingState.splitOrders[splitOrderIndex].paymentMethod = paymentData.paymentMethod;
        splitBillingState.splitOrders[splitOrderIndex].paymentDetails = {
            cashAmount: paymentData.cashAmount || 0,
            cardAmount: paymentData.cardAmount || 0,
            totalAmount: paymentData.totalAmount || 0,
            discountAmount: paymentData.discountAmount || 0,
            pointsUsed: paymentData.pointsUsed || 0,
            rewardUserId: paymentData.rewardUserId || null,
            verifiedUserId: paymentData.verifiedUserId || null,
            paidAt: new Date().toISOString()
        };

        // 如果有积分折扣用户，保存到分单状态
        if (paymentData.verifiedUserId) {
            splitBillingState.splitOrders[splitOrderIndex].discountUserId = paymentData.verifiedUserId;
        }
        if (paymentData.rewardUserId) {
            splitBillingState.splitOrders[splitOrderIndex].rewardUserId = paymentData.rewardUserId;
        }

        // 保存状态
        saveSplitBillingState();

        // 🔥 新增：立即创建WooCommerce订单
        const splitNumber = splitOrderIndex + 1;
        console.log('[processSplitOrderPayment] 开始创建WooCommerce订单，分单:', splitNumber);

        const formData = new URLSearchParams({
            action: 'ruiyi_pos_create_single_split_order',
            table_number: splitBillingState.tableNumber,
            split_number: splitNumber,
            products: JSON.stringify(splitOrder.products),
            payment_method: paymentData.paymentMethod,
            cash_amount: (paymentData.cashAmount || 0).toFixed(2),
            card_amount: (paymentData.cardAmount || 0).toFixed(2),
            total_amount: (paymentData.totalAmount || 0).toFixed(2),
            discount_amount: (paymentData.discountAmount || 0).toFixed(2),
            points_used: paymentData.pointsUsed || 0,
            nonce: ajaxNonce
        });

        fetch(ajaxUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: formData
        })
        .then(response => response.json())
        .then(data => {
            if (data.success) {
                console.log('[processSplitOrderPayment] WooCommerce订单创建成功:', data.data.order_id);
                // 保存订单ID到分单状态
                splitBillingState.splitOrders[splitOrderIndex].wooOrderId = data.data.order_id;
                saveSplitBillingState();
            } else {
                console.error('[processSplitOrderPayment] 订单创建失败:', data.data?.message);
            }
        })
        .catch(error => {
            console.error('[processSplitOrderPayment] 订单创建请求失败:', error);
        });

        // 如果支付方式包含现金，打开钱箱
        const shouldOpenDrawer = paymentData.paymentMethod === 'cash' ||
                                 paymentData.paymentMethod === 'mixed' ||
                                 (paymentData.cashAmount && paymentData.cashAmount > 0);

        console.log('[processSplitOrderPayment] 钱箱检测 - 支付方式:', paymentData.paymentMethod, '现金金额:', paymentData.cashAmount, '应开钱箱:', shouldOpenDrawer);

        if (shouldOpenDrawer) {
            console.log('[processSplitOrderPayment] 🔥 尝试打开钱箱...');
            try {
                if (typeof clodopOpenCashDrawer === 'function') {
                    clodopOpenCashDrawer();
                    console.log('[processSplitOrderPayment] ✅ 已调用 clodopOpenCashDrawer');
                } else if (typeof abrirCajonDinero === 'function') {
                    abrirCajonDinero();
                    console.log('[processSplitOrderPayment] ✅ 已调用 abrirCajonDinero');
                } else {
                    console.warn('[processSplitOrderPayment] ⚠️ 未找到钱箱函数');
                }
            } catch (error) {
                console.error('[processSplitOrderPayment] 打开钱箱失败:', error);
            }
        }
    }

    // 调用完成回调
    if (typeof onComplete === 'function') {
        onComplete();
    }
}

// 处理所有分单完成 - 抵扣模式：汇总支付信息并对原订单一次性结账
function handleAllSplitsCompleted() {
    var ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
    var ajaxNonce = window.RUIYI_POS?.nonce;


    // 汇总所有分单的支付信息
    let totalCashAmount = 0;
    let totalCardAmount = 0;
    let totalDiscountAmount = 0;
    let totalPointsUsed = 0;
    let paymentDetails = [];
    let usersNeedingShortcodeUpdate = new Set();

    splitBillingState.splitOrders.forEach((splitOrder, index) => {
        if (splitOrder.paymentDetails) {
            const details = splitOrder.paymentDetails;
            totalCashAmount += details.cashAmount || 0;
            totalCardAmount += details.cardAmount || 0;
            totalDiscountAmount += details.discountAmount || 0;
            totalPointsUsed += details.pointsUsed || 0;

            paymentDetails.push({
                splitId: splitOrder.id,
                splitNumber: index + 1,
                paymentMethod: splitOrder.paymentMethod,
                cashAmount: details.cashAmount || 0,
                cardAmount: details.cardAmount || 0,
                totalAmount: details.totalAmount || 0,
                discountAmount: details.discountAmount || 0,
                pointsUsed: details.pointsUsed || 0,
                verifiedUserId: details.verifiedUserId,
                rewardUserId: details.rewardUserId
            });

            // 收集需要更新短码的用户
            if (details.verifiedUserId) usersNeedingShortcodeUpdate.add(details.verifiedUserId);
            if (details.rewardUserId) usersNeedingShortcodeUpdate.add(details.rewardUserId);
        }
    });

    // 计算总金额
    const totalAmount = totalCashAmount + totalCardAmount;

    // 确定主要支付方式
    let mainPaymentMethod = 'cash';
    if (totalCardAmount > 0 && totalCashAmount > 0) {
        mainPaymentMethod = 'mixed';
    } else if (totalCardAmount > 0) {
        mainPaymentMethod = 'card';
    }

    Swal.fire({
        title: '<?php echo ruiyi_translate("Procesando pago...", "Processing payment...", "正在处理支付..."); ?>',
        text: '<?php echo ruiyi_translate("Completando el pago del pedido original", "Completing original order payment", "正在完成原订单支付"); ?>',
        allowOutsideClick: false,
        didOpen: () => { Swal.showLoading(); }
    });

    // 获取原始订单ID
    const originalOrderIds = splitBillingState.originalOrderIds && splitBillingState.originalOrderIds.length > 0
        ? splitBillingState.originalOrderIds
        : splitBillingState.originalOrders.map(order => order.id);

    // 调用后端完成原订单结账
    const formData = new URLSearchParams({
        action: 'ruiyi_pos_complete_aa_checkout',
        table_number: splitBillingState.tableNumber,
        original_order_ids: JSON.stringify(originalOrderIds),
        payment_method: mainPaymentMethod,
        cash_amount: totalCashAmount.toFixed(2),
        card_amount: totalCardAmount.toFixed(2),
        total_amount: totalAmount.toFixed(2),
        discount_amount: totalDiscountAmount.toFixed(2),
        points_used: totalPointsUsed,
        split_count: splitBillingState.splitOrders.length,
        payment_details: JSON.stringify(paymentDetails),
        nonce: ajaxNonce
    });

    fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: formData
    })
    .then(response => response.json())
    .then(data => {
        Swal.close();

        if (data.success) {

            // 🔥 获取小票HTML并保存到localStorage，以便"打印结账小票"按钮可以打印
            const receiptFormData = new URLSearchParams({
                action: 'ruiyi_pos_get_table_receipt_html',
                table: splitBillingState.tableNumber,
                order_ids_to_print: JSON.stringify(originalOrderIds),
                order_total: totalAmount.toFixed(2),
                is_aa_checkout: '1',
                aa_split_count: splitBillingState.splitOrders.length,
                payment_method: mainPaymentMethod,
                cash_amount: totalCashAmount.toFixed(2),
                card_amount: totalCardAmount.toFixed(2),
                nonce: ajaxNonce
            });

            // 传递桌位显示名称
            if (window.tableCategoryMappings && splitBillingState.tableNumber) {
                const globalNum = parseInt(resolveGlobalTableNumber(splitBillingState.tableNumber), 10);
                if (globalNum) {
                    let allMappings = [];
                    if (Array.isArray(window.tableCategoryMappings)) {
                        allMappings = window.tableCategoryMappings;
                    } else {
                        allMappings = Object.values(window.tableCategoryMappings);
                    }
                    const mapping = allMappings.find(m => parseInt(m.global_table_number) === globalNum);
                    if (mapping && mapping.category_display_name) {
                        receiptFormData.append('table_display_name', mapping.category_display_name);
                    }
                }
            }

            // 获取小票HTML并保存
            fetch(ajaxUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: receiptFormData
            })
            .then(response => response.json())
            .then(receiptData => {
                if (receiptData.success && receiptData.data.html) {
                    // 保存小票HTML到localStorage用于重新打印
                    localStorage.setItem('lastReceiptHtml', receiptData.data.html);
                    localStorage.setItem('lastReceiptType', 'aa_checkout');
                    localStorage.setItem('lastReceiptTimestamp', Date.now());
                    localStorage.setItem('lastReceiptRequestBody', receiptFormData.toString());
                }
            })
            .catch(error => {
                console.error('[AA结账] 获取小票HTML失败:', error);
            });

            // 更新需要刷新短码的用户
            usersNeedingShortcodeUpdate.forEach(userId => {
                const formData = new URLSearchParams({
                    action: 'ruiyi_refresh_shortcode',
                    user_id: userId,
                    nonce: window.RUIYI_POS.nonce
                });
                fetch(window.ajaxUrl, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                    body: formData
                }).catch(error => console.error(`更新用户${userId}短码时出错:`, error));
            });

            // 🔥🔥🔥 关键修复：如果支付方式包含现金，打开钱箱
            const shouldOpenDrawer = mainPaymentMethod === 'cash' ||
                                     mainPaymentMethod === 'mixed' ||
                                     (totalCashAmount && totalCashAmount > 0);

            if (shouldOpenDrawer) {
                try {
                    if (typeof clodopOpenCashDrawer === 'function') {
                        clodopOpenCashDrawer();
                    } else if (typeof abrirCajonDinero === 'function') {
                        abrirCajonDinero();
                    }
                } catch (error) {
                    console.error('[AA结账] 打开钱箱失败:', error);
                }
            }

            // 显示简短成功提示
            Toastify({
                text: `✅ <?php echo ruiyi_translate("AA Checkout completado", "AA Checkout completed", "AA结账完成"); ?>`,
                duration: 2000,
                gravity: "top",
                position: "center",
                style: { background: "#10b981" }
            }).showToast();

            // 直接清理状态并返回桌位模块
            cleanupAfterAACheckout();
        } else {
            Swal.fire({
                icon: 'error',
                title: '<?php echo ruiyi_translate("Error de pago", "Payment Error", "支付错误"); ?>',
                text: data.data?.message || '<?php echo ruiyi_translate("No se pudo completar el pago", "Could not complete payment", "无法完成支付"); ?>'
            });
        }
    })
    .catch(error => {
        Swal.close();
        console.error('[AA抵扣模式] 结账失败:', error);
        Swal.fire({
            icon: 'error',
            title: '<?php echo ruiyi_translate("Error de conexión", "Connection Error", "连接错误"); ?>',
            text: '<?php echo ruiyi_translate("Error de red, por favor intente de nuevo", "Network error, please try again", "网络错误，请重试"); ?>'
        });
    });
}

// AA结账完成后的清理函数
function cleanupAfterAACheckout() {
    const tableNumber = splitBillingState.tableNumber;

    // 🔥 全局结账保护：标记此桌位刚刚结账
    if (tableNumber) {
        const tableNum = resolveGlobalTableNumber(tableNumber);
        if (tableNum) {
            if (!window._recentlyCheckedOutTables) window._recentlyCheckedOutTables = {};
            window._recentlyCheckedOutTables[tableNum] = Date.now();
        }
    }

    // 清理localStorage中的分单状态
    clearSplitBillingState(tableNumber);

    // 清空收银购物车
    cart = [];
    if (typeof window.cart !== 'undefined') {
        window.cart = [];
    }

    // 清理localStorage中的购物车数据
    localStorage.removeItem(`cart_${tableNumber}`);

    const splitPossibleKeys = getAASplitPossibleTableKeys(tableNumber);

    // 清理carritos_mesas中该桌位的数据 - 统一候选键匹配
    const carritosGuardados = JSON.parse(localStorage.getItem('carritos_mesas') || '{}');
    const tableNumeric = resolveGlobalTableNumber(tableNumber);
    Object.keys(carritosGuardados).forEach(key => {
        if (splitPossibleKeys.includes(key)) {
            delete carritosGuardados[key];
            return;
        }

        const keyNumeric = resolveGlobalTableNumber(key);
        if (tableNumeric && keyNumeric === tableNumeric) {
            delete carritosGuardados[key];
        }
    });
    localStorage.setItem('carritos_mesas', JSON.stringify(carritosGuardados));

    // 清除该桌位的 delivery 客户数据
    if (typeof clearDeliveryCustomerData === 'function') {
        clearDeliveryCustomerData(tableNumber);
    }

    // 重新渲染购物车
    if (typeof renderCart === 'function') {
        renderCart();
    }

    // 只隐藏普通结账按钮，不隐藏AA结账按钮（AA结账按钮始终可见）
    const checkoutBtn = document.getElementById('checkout-table-btn');
    if (checkoutBtn) checkoutBtn.classList.add('hidden');

    // 注意：不隐藏 split-checkout-btn (AA结账按钮)

    // 清除订单标题显示
    const orderTitle = document.getElementById('cart-order-title');
    if (orderTitle) orderTitle.innerHTML = '';

    // 清理餐桌状态 - 设置为libre+保护标志（而非删除）
    const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
    const libreState = {
        estado: 'libre',
        orderId: null,
        total: 0,
        timestamp: new Date().toISOString(),
        _paymentCompleted: true,
        _skipAutoUpdate: true
    };
    let matchedMesaState = false;
    Object.keys(mesasEstado).forEach(key => {
        if (splitPossibleKeys.includes(key)) {
            mesasEstado[key] = { ...libreState };
            matchedMesaState = true;
            return;
        }

        const keyNumeric = resolveGlobalTableNumber(key);
        if (tableNumeric && keyNumeric === tableNumeric) {
            mesasEstado[key] = { ...libreState };
            matchedMesaState = true;
        }
    });
    if (!matchedMesaState && tableNumeric) {
        mesasEstado[`Mesa ${tableNumeric}`] = { ...libreState };
    }
    localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));

    // 清除查看模式状态
    sessionStorage.removeItem('isViewMode');
    sessionStorage.removeItem('tableViewOrderData');
    sessionStorage.removeItem('tableOrderData');

    // 清空桌位输入框
    const tableNumberInput = document.getElementById('table-number');
    if (tableNumberInput) {
        tableNumberInput.value = '';
    }

    // 重置分单状态
    splitBillingState.isActive = false;
    splitBillingState.allCompleted = true;
    splitBillingState.splitOrders = [];
    splitBillingState.completedSplits = [];
    splitBillingState.originalOrderIds = [];

    // 关闭工具箱（将AA结账和换台按钮收回工具箱内）
    const cartActionsContainer = document.querySelector('.cart-actions-fixed');
    if (cartActionsContainer) {
        const alpineData = Alpine.$data(cartActionsContainer);
        if (alpineData) {
            alpineData.toolboxOpen = false;
        }
    }


    // 释放桌位并刷新
    setTimeout(() => {
        if (typeof releaseTableOnOrderComplete === 'function') {
            releaseTableOnOrderComplete(tableNumber);
        }

        // AA结账完成后强制切换到餐桌模块
        if (typeof cambiarSeccion === 'function') {
            cambiarSeccion('mesas');
        }

        // 刷新桌位状态
        setTimeout(() => {
            if (typeof fetchAndUpdateTableStatuses === 'function') {
                fetchAndUpdateTableStatuses();
            }
            setTimeout(() => {
                if (typeof renderizarMesas === 'function') {
                    renderizarMesas('manual-refresh');
                }
            }, 300);
        }, 500);
    }, 300);
}

// AA结账打印总单
function printAACheckoutReceipt(orderIds, tableNumber, paymentInfo) {

    var ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
    var ajaxNonce = window.RUIYI_POS?.nonce;

    // 调用后端获取小票HTML
    const formData = new URLSearchParams({
        action: 'ruiyi_pos_get_table_receipt_html',
        table: tableNumber,
        order_ids_to_print: JSON.stringify(orderIds),
        order_total: paymentInfo.totalAmount,
        is_aa_checkout: '1',
        aa_split_count: paymentInfo.splitCount,
        aa_cash_amount: paymentInfo.totalCashAmount,
        aa_card_amount: paymentInfo.totalCardAmount,
        aa_payment_method: paymentInfo.paymentMethod,
        nonce: ajaxNonce
    });

    // 如果有积分折扣信息
    if (paymentInfo.totalDiscountAmount > 0) {
        formData.append('points_discount_amount', paymentInfo.totalDiscountAmount);
        formData.append('points_used_total', paymentInfo.totalPointsUsed);
        formData.append('final_total', paymentInfo.totalAmount);
    }

    // 传递桌位显示名称
    if (window.tableCategoryMappings && tableNumber) {
        const globalNumberMatch = tableNumber.toString().match(/\d+/);
        if (globalNumberMatch) {
            const globalNum = parseInt(globalNumberMatch[0]);
            let allMappings = [];
            if (Array.isArray(window.tableCategoryMappings)) {
                allMappings = window.tableCategoryMappings;
            } else {
                allMappings = Object.values(window.tableCategoryMappings);
            }
            const mapping = allMappings.find(m => parseInt(m.global_table_number) === globalNum);
            if (mapping && mapping.category_display_name) {
                formData.append('table_display_name', mapping.category_display_name);
            }
        }
    }

    fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: formData
    })
    .then(response => response.json())
    .then(data => {
        if (data.success && data.data && data.data.html) {

            // 检查是否启用CLODOP打印
            if (window.clodopConfig && window.clodopConfig.enabled && typeof getLodop === 'function') {
                try {
                    const LODOP = getLodop();
                    if (LODOP && LODOP.VERSION) {
                        const defaultPrinter = window.clodopConfig.defaultPrinter || '';

                        LODOP.SET_LICENSES("","D615C875005D74B88EC9E2585C79798E9CA","","");
                        LODOP.PRINT_INIT("AA结账总单");
                        LODOP.SET_PRINT_PAGESIZE(3, "80mm", 0, "");

                        if (defaultPrinter) {
                            LODOP.SET_PRINTER_INDEX(defaultPrinter);
                        }

                        LODOP.ADD_PRINT_HTM(0, 0, "100%", "BottomMargin:0mm", data.data.html);
                        LODOP.PRINT();


                        Toastify({
                            text: '<?php echo ruiyi_translate("Imprimiendo ticket de AA checkout", "Printing AA checkout receipt", "正在打印AA结账小票"); ?>',
                            duration: 2000,
                            gravity: "top",
                            position: "center",
                            style: { background: "#10b981" }
                        }).showToast();
                    } else {
                        console.warn('[AA抵扣模式] CLODOP未连接，跳过打印');
                    }
                } catch (error) {
                    console.error('[AA抵扣模式] 打印错误:', error);
                }
            } else {
            }
        } else {
            console.error('[AA抵扣模式] 获取小票HTML失败:', data);
        }
    })
    .catch(error => {
        console.error('[AA抵扣模式] 获取小票HTML请求失败:', error);
    });
}

// ========== AA结账 - 按金额分单功能 ==========

// 金额分单状态管理
let amountSplitState = {
    tableNumber: null,
    totalAmount: 0,
    originalOrderIds: [],
    originalOrders: [],
    splits: [], // [{id, amount, paid: false, paymentMethod: null, paymentDetails: null}]
    isActive: false
};

// 🔥 请求ID，防止异步竞态导致错误桌位数据
var _amountSplitRequestId = 0;

// 初始化按金额分单
function initiateSplitBillingByAmount(tableNumber) {
    // 🔥 递增请求ID，旧请求的回调会被忽略
    _amountSplitRequestId++;

    // 重置金额分单状态
    amountSplitState = {
        tableNumber: tableNumber,
        totalAmount: 0,
        originalOrderIds: [],
        originalOrders: [],
        splits: [],
        isActive: true
    };

    // 获取餐桌订单数据
    fetchTableOrdersForAmountSplit(tableNumber, _amountSplitRequestId);
}

// 获取餐桌订单数据用于金额分单
function fetchTableOrdersForAmountSplit(tableNumber, requestId) {
    var ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
    var ajaxNonce = window.RUIYI_POS?.nonce;

    Swal.fire({
        title: '<?php echo ruiyi_translate("Cargando datos del pedido...", "Loading order data...", "获取订单数据..."); ?>',
        text: '<?php echo ruiyi_translate("Por favor espere", "Please wait", "请稍候"); ?>',
        allowOutsideClick: false,
        didOpen: () => { Swal.showLoading(); }
    });

    const formData = new URLSearchParams({
        action: 'ruiyi_pos_get_table_orders_for_split',
        table_number: tableNumber,
        nonce: ajaxNonce
    });

    fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: formData
    })
    .then(response => response.json())
    .then(data => {
        Swal.close();

        // 🔥 检查请求是否过期（用户可能已切换到其他桌位）
        if (requestId !== _amountSplitRequestId) {
            console.warn('[AA金额分单] ⚠️ 忽略过期请求，当前请求ID:', _amountSplitRequestId, '收到:', requestId);
            return;
        }

        if (data.success && data.data.orders && data.data.orders.length > 0) {
            // 计算总金额
            let totalAmount = 0;
            const originalOrderIds = [];
            data.data.orders.forEach(order => {
                totalAmount += parseFloat(order.total || 0);
                originalOrderIds.push(order.id);
            });

            amountSplitState.totalAmount = totalAmount;
            amountSplitState.originalOrderIds = originalOrderIds;
            amountSplitState.originalOrders = data.data.orders;
            amountSplitState.tableNumber = data.data.table_number;

            // 默认创建2个分单，平均分配
            amountSplitState.splits = [
                { id: 'amount_split_1', amount: (totalAmount / 2).toFixed(2), paid: false, paymentMethod: null, paymentDetails: null },
                { id: 'amount_split_2', amount: (totalAmount / 2).toFixed(2), paid: false, paymentMethod: null, paymentDetails: null }
            ];

            showAmountSplitModal();
        } else {
            Swal.fire({
                icon: 'warning',
                title: '<?php echo ruiyi_translate("No se encontraron pedidos", "No orders found", "没有找到订单"); ?>',
                text: '<?php echo ruiyi_translate("No hay órdenes disponibles para dividir en esta mesa", "No orders available for splitting at this table", "该桌位没有可分单的订单"); ?>'
            });
        }
    })
    .catch(error => {
        Swal.close();
        Swal.fire({
            icon: 'error',
            title: '<?php echo ruiyi_translate("Error al cargar datos", "Failed to load data", "获取数据失败"); ?>',
            text: error.message
        });
    });
}

