// 渲染分单列表 - 紧凑卡片式布局
function renderAmountSplitsList() {
    return amountSplitState.splits.map((split, index) => {
        const isPaid = split.paid;
        return `
            <div class="border-2 ${isPaid ? 'border-green-400 bg-green-50' : 'border-gray-200 bg-white hover:border-blue-300'} rounded-xl p-4 transition-all relative">
                <!-- 删除按钮 - 右上角 -->
                ${!isPaid && amountSplitState.splits.length > 1 ? `
                    <button onclick="removeAmountSplit('${split.id}')" class="absolute top-2 right-2 text-red-400 hover:text-red-600 p-1" title="<?php echo ruiyi_translate('Eliminar', 'Delete', '删除'); ?>">
                        <i class="fas fa-times-circle text-lg"></i>
                    </button>
                ` : ''}

                <!-- 标题 -->
                <div class="text-center mb-3">
                    <div class="flex items-center justify-center">
                        ${isPaid ? '<i class="fas fa-check-circle text-green-500 mr-2 text-lg"></i>' : '<i class="fas fa-receipt text-blue-500 mr-2 text-lg"></i>'}
                        <span class="font-bold text-gray-800 text-lg"><?php echo ruiyi_translate('Cuenta', 'Bill', '分单'); ?> ${index + 1}</span>
                    </div>
                    ${isPaid ? '<span class="inline-block mt-1 text-xs bg-green-500 text-white px-3 py-1 rounded-full"><?php echo ruiyi_translate('Pagado', 'Paid', '已付'); ?></span>' : ''}
                </div>

                <!-- 金额输入 -->
                <div class="flex items-center justify-center gap-1 mb-3">
                    <span class="text-gray-500 text-xl">€</span>
                    <input type="number"
                           id="amount-input-${split.id}"
                           value="${split.amount}"
                           step="0.01"
                           min="0"
                           ${isPaid ? 'disabled' : ''}
                           onchange="updateSplitAmount('${split.id}', this.value)"
                           class="w-28 border-2 ${isPaid ? 'border-green-300 bg-green-100' : 'border-gray-300'} rounded-lg px-2 py-2 text-xl font-bold text-center focus:ring-2 focus:ring-blue-500 focus:border-blue-500 ${isPaid ? 'cursor-not-allowed' : ''}"
                    />
                </div>

                <!-- 结账按钮或已付状态 -->
                ${!isPaid ? `
                    <button onclick="checkoutAmountSplit('${split.id}')"
                            class="w-full bg-green-500 hover:bg-green-600 text-white py-2.5 rounded-lg font-medium transition-colors text-sm ${parseFloat(split.amount) <= 0 ? 'opacity-50 cursor-not-allowed' : ''}"
                            ${parseFloat(split.amount) <= 0 ? 'disabled' : ''}>
                        <i class="fas fa-cash-register mr-1"></i><?php echo ruiyi_translate('Cobrar', 'Checkout', '结账'); ?>
                    </button>
                ` : `
                    <div class="text-center text-green-600 text-sm py-2 bg-green-100 rounded-lg">
                        <i class="fas fa-check mr-1"></i>
                        ${split.paymentMethod === 'cash' ? '<?php echo ruiyi_translate('Efectivo', 'Cash', '现金'); ?>' :
                          split.paymentMethod === 'card' ? '<?php echo ruiyi_translate('Tarjeta', 'Card', '刷卡'); ?>' :
                          '<?php echo ruiyi_translate('Mixto', 'Mixed', '混合支付'); ?>'}
                    </div>
                `}
            </div>
        `;
    }).join('');
}

// 添加新分单
function addAmountSplit() {
    const newId = 'amount_split_' + (amountSplitState.splits.length + 1) + '_' + Date.now();
    amountSplitState.splits.push({
        id: newId,
        amount: '0.00',
        paid: false,
        paymentMethod: null,
        paymentDetails: null
    });
    refreshAmountSplitUI();
}

// 删除分单
function removeAmountSplit(splitId) {
    const split = amountSplitState.splits.find(s => s.id === splitId);
    if (split && split.paid) {
        Toastify({
            text: '<?php echo ruiyi_translate("No se puede eliminar una cuenta pagada", "Cannot delete a paid bill", "无法删除已付款的分单"); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#ef4444" }
        }).showToast();
        return;
    }

    amountSplitState.splits = amountSplitState.splits.filter(s => s.id !== splitId);
    refreshAmountSplitUI();
}

// 平均分配金额
function distributeAmountEvenly() {
    const unpaidSplits = amountSplitState.splits.filter(s => !s.paid);
    if (unpaidSplits.length === 0) {
        Toastify({
            text: '<?php echo ruiyi_translate("Todas las cuentas están pagadas", "All bills are paid", "所有分单都已付款"); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#f59e0b" }
        }).showToast();
        return;
    }

    // 计算已支付金额
    const paidAmount = amountSplitState.splits.filter(s => s.paid).reduce((sum, s) => sum + parseFloat(s.amount), 0);
    const remainingTotal = amountSplitState.totalAmount - paidAmount;
    const amountPerSplit = remainingTotal / unpaidSplits.length;

    unpaidSplits.forEach(split => {
        split.amount = amountPerSplit.toFixed(2);
    });

    refreshAmountSplitUI();
}

// 更新分单金额
function updateSplitAmount(splitId, value) {
    const split = amountSplitState.splits.find(s => s.id === splitId);
    if (split && !split.paid) {
        split.amount = parseFloat(value || 0).toFixed(2);
        refreshAmountSplitUI();
    }
}

// 计算已分配金额
function calculateAllocatedAmount() {
    return amountSplitState.splits.reduce((sum, s) => sum + parseFloat(s.amount || 0), 0);
}

// 计算剩余金额
function calculateRemainingAmount() {
    return amountSplitState.totalAmount - calculateAllocatedAmount();
}

// 刷新金额分单UI
function refreshAmountSplitUI() {
    const container = document.getElementById('amount-splits-container');
    if (container) {
        container.innerHTML = renderAmountSplitsList();
    }

    // 更新统计信息
    const allocatedEl = document.getElementById('amount-allocated');
    const remainingEl = document.getElementById('amount-remaining');

    if (allocatedEl) allocatedEl.textContent = '€' + calculateAllocatedAmount().toFixed(2);
    if (remainingEl) {
        const remaining = calculateRemainingAmount();
        remainingEl.textContent = '€' + remaining.toFixed(2);
        remainingEl.className = 'font-medium ' + (Math.abs(remaining) < 0.01 ? 'text-green-600' : 'text-orange-600');
    }
}

// 金额分单结账
function checkoutAmountSplit(splitId) {
    const split = amountSplitState.splits.find(s => s.id === splitId);
    if (!split || split.paid) return;

    const amount = parseFloat(split.amount);
    if (amount <= 0) {
        Toastify({
            text: '<?php echo ruiyi_translate("El importe debe ser mayor que 0", "Amount must be greater than 0", "金额必须大于0"); ?>',
            duration: 2000,
            gravity: "top",
            position: "center",
            style: { background: "#ef4444" }
        }).showToast();
        return;
    }

    // 显示支付方式选择弹窗
    Swal.fire({
        title: `<?php echo ruiyi_translate('Cobrar', 'Checkout', '结账'); ?> €${amount.toFixed(2)}`,
        html: `
            <div class="grid grid-cols-3 gap-3 p-2">
                <div id="pay-cash-option" class="cursor-pointer p-4 border-2 border-gray-200 rounded-xl hover:border-green-500 hover:bg-green-50 transition-all">
                    <div class="text-center">
                        <i class="fas fa-money-bill-wave text-3xl text-green-500 mb-2"></i>
                        <div class="font-medium"><?php echo ruiyi_translate('Efectivo', 'Cash', '现金'); ?></div>
                    </div>
                </div>
                <div id="pay-card-option" class="cursor-pointer p-4 border-2 border-gray-200 rounded-xl hover:border-blue-500 hover:bg-blue-50 transition-all">
                    <div class="text-center">
                        <i class="fas fa-credit-card text-3xl text-blue-500 mb-2"></i>
                        <div class="font-medium"><?php echo ruiyi_translate('Tarjeta', 'Card', '刷卡'); ?></div>
                    </div>
                </div>
                <div id="pay-mixed-option" class="cursor-pointer p-4 border-2 border-gray-200 rounded-xl hover:border-purple-500 hover:bg-purple-50 transition-all">
                    <div class="text-center">
                        <i class="fas fa-coins text-3xl text-purple-500 mb-2"></i>
                        <div class="font-medium"><?php echo ruiyi_translate('Mixto', 'Mixed', '混合'); ?></div>
                    </div>
                </div>
            </div>
        `,
        showConfirmButton: false,
        showCancelButton: true,
        cancelButtonText: '<?php echo ruiyi_translate('Cancelar', 'Cancel', '取消'); ?>',
        width: '500px',
        didOpen: () => {
            document.getElementById('pay-cash-option').onclick = () => {
                Swal.close();
                processAmountSplitCashPayment(splitId, amount);
            };
            document.getElementById('pay-card-option').onclick = () => {
                Swal.close();
                processAmountSplitCardPayment(splitId, amount);
            };
            document.getElementById('pay-mixed-option').onclick = () => {
                Swal.close();
                processAmountSplitMixedPayment(splitId, amount);
            };
        }
    });
}

// 处理现金支付
function processAmountSplitCashPayment(splitId, amount) {
    Swal.fire({
        title: `<?php echo ruiyi_translate('Pago en Efectivo', 'Cash Payment', '现金支付'); ?>`,
        html: `
            <div class="text-center mb-4">
                <div class="text-gray-600"><?php echo ruiyi_translate('A cobrar', 'To collect', '应收'); ?>:</div>
                <div class="text-3xl font-bold text-green-600">€${amount.toFixed(2)}</div>
            </div>
            <div class="mb-4">
                <label class="block text-sm text-gray-600 mb-1"><?php echo ruiyi_translate('Efectivo Recibido', 'Cash Received', '实收金额'); ?>:</label>
                <input type="number" id="cash-received" value="${amount.toFixed(2)}" step="0.01" min="0"
                       class="w-full border border-gray-300 rounded-lg px-4 py-3 text-xl text-center font-medium focus:ring-2 focus:ring-green-500"
                       oninput="updateCashChangeRealtime(${amount})">
            </div>
            <div class="bg-yellow-50 border border-yellow-200 rounded-lg p-3">
                <div class="text-sm text-gray-600"><?php echo ruiyi_translate('Cambio', 'Change', '找零'); ?>:</div>
                <div id="cash-change" class="text-2xl font-bold text-yellow-600">€0.00</div>
            </div>
        `,
        confirmButtonText: `<i class="fas fa-check mr-2"></i><?php echo ruiyi_translate('Confirmar Pago', 'Confirm Payment', '确认支付'); ?>`,
        confirmButtonColor: '#10b981',
        showCancelButton: true,
        cancelButtonText: '<?php echo ruiyi_translate('Cancelar', 'Cancel', '取消'); ?>',
        didOpen: () => {
            document.getElementById('cash-received').focus();
            document.getElementById('cash-received').select();
            // 初始化找零显示
            updateCashChangeRealtime(amount);
        },
        preConfirm: () => {
            const received = parseFloat(document.getElementById('cash-received').value);
            if (received < amount) {
                Swal.showValidationMessage('<?php echo ruiyi_translate('El efectivo recibido debe ser mayor o igual al importe', 'Cash received must be greater than or equal to the amount', '实收金额必须大于或等于应收金额'); ?>');
                return false;
            }
            return { received: received, change: received - amount };
        }
    }).then((result) => {
        if (result.isConfirmed) {
            completeAmountSplitPayment(splitId, 'cash', {
                amount: amount,
                received: result.value.received,
                change: result.value.change
            });
        }
    });
}

// 实时更新找零显示
function updateCashChangeRealtime(amount) {
    const receivedInput = document.getElementById('cash-received');
    const changeDisplay = document.getElementById('cash-change');
    if (!receivedInput || !changeDisplay) return;

    const received = parseFloat(receivedInput.value) || 0;
    const change = Math.max(0, received - amount);
    changeDisplay.textContent = '€' + change.toFixed(2);
}

