                const cardAmount = Math.max(0, amount - cashAmount);
                cardInput.value = cardAmount.toFixed(2);
                cashDisplay.textContent = '€' + cashAmount.toFixed(2);
                cardDisplay.textContent = '€' + cardAmount.toFixed(2);
