    // ========================================
    // 保存日结单到月结单
    // ========================================
    function saveDailyToMonthly(data) {
      var ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
      var ajaxNonce = window.RUIYI_POS?.nonce || posNonce;

      // 显示加载状态
      Swal.fire({
        title: '<?php echo ruiyi_translate("Guardando...", "Saving...", "保存中..."); ?>',
        allowOutsideClick: false,
        didOpen: () => {
          Swal.showLoading();
        }
      });

      fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          action: 'ruiyi_save_daily_to_monthly',
          nonce: ajaxNonce
        })
      })
      .then(res => res.json())
      .then(response => {
        if (response.success) {

          // 关闭加载提示
          Swal.close();

          // 先打印日结单
          printDailySummaryWithCLODOP(data);

          // 显示成功提示
          Toastify({
            text: '<?php echo ruiyi_translate("Datos guardados en resumen mensual", "Data saved to monthly summary", "数据已保存到月结单"); ?>',
            duration: 3000,
            gravity: "top",
            position: "center",
            style: { background: "#10b981" }
          }).showToast();

          // 重新加载日结单数据（显示为0）
          setTimeout(() => {
            loadDailySummaryData();
          }, 2000);
        } else {
          // 🔥 使用用户友好的提示（无数据保存等情况）
          Swal.fire({
            icon: 'info',
            title: '<?php echo ruiyi_translate("Aviso", "Notice", "提示"); ?>',
