        showFriendlyErrorDialog(
          '<?php echo ruiyi_translate("Error de conexión", "Connection error", "连接错误"); ?>',
          '<?php echo ruiyi_translate("No se pudo conectar con el servidor. Por favor verifique su conexión e intente de nuevo.", "Could not connect to server. Please check your connection and try again.", "无法连接服务器，请检查网络连接后重试。"); ?>'
        );
      });
    }

    // ========================================
    // 账单管理 - Tab切换功能
    // ========================================
    const tabButtons = document.querySelectorAll('.billing-tab');
    const tabContents = document.querySelectorAll('.billing-tab-content');

    tabButtons.forEach(button => {
      button.addEventListener('click', function() {
        const tabId = this.id;

        // 移除所有激活状态
        tabButtons.forEach(btn => {
          btn.classList.remove('border-primary', 'text-primary');
          btn.classList.add('border-transparent', 'text-gray-500', 'dark:text-gray-400');
        });

        // 添加当前激活状态
        this.classList.remove('border-transparent', 'text-gray-500', 'dark:text-gray-400');
        this.classList.add('border-primary', 'text-primary');

        // 隐藏所有内容
        tabContents.forEach(content => {
          content.classList.add('hidden');
        });

        // 显示对应内容
        if (tabId === 'tab-daily-summary') {
          document.getElementById('daily-summary-tab-content').classList.remove('hidden');
          // 加载日结单数据
          if (!dailySummaryData) {
            loadDailySummaryData();
          }
        } else if (tabId === 'tab-monthly-summary') {
          document.getElementById('monthly-summary-tab-content').classList.remove('hidden');
          // 设置默认月份为当前月
          const monthSelector = document.getElementById('monthly-month-selector');
          if (monthSelector) {
            const today = new Date();
            const currentMonth = today.getFullYear() + '-' + String(today.getMonth() + 1).padStart(2, '0');
            if (!monthSelector.value) {
              monthSelector.value = currentMonth;
            }
            // 🔥 首次打开时自动加载当前月份数据
            if (!monthlySummaryData) {
              loadMonthlySummary('', '', monthSelector.value || currentMonth);
            }
          }
        } else if (tabId === 'tab-settlement-history') {
          document.getElementById('settlement-history-tab-content').classList.remove('hidden');
          // 首次打开时自动加载历史日结单
          if (!settlementHistoryLoaded) {
            loadSettlementHistory();
          }
        }
      });
    });

    // ========================================
    // 月结单功能
    // ========================================
    let monthlySummaryData = null; // 存储月结单数据
    let monthlyCurrentPage = 1; // 当前页码
    const monthlyPageSize = 50; // 每页显示条数

    // 加载月结单数据
    document.getElementById('load-monthly-summary')?.addEventListener('click', function() {
      const fromDate = document.getElementById('monthly-from-date').value;
      const toDate = document.getElementById('monthly-to-date').value;
      const month = document.getElementById('monthly-month-selector').value;

      loadMonthlySummary(fromDate, toDate, month);
    });

    // 重置筛选条件
    document.getElementById('reset-monthly-filters')?.addEventListener('click', function() {
      document.getElementById('monthly-from-date').value = '';
      document.getElementById('monthly-to-date').value = '';
      const today = new Date();
      const currentMonth = today.getFullYear() + '-' + String(today.getMonth() + 1).padStart(2, '0');
      document.getElementById('monthly-month-selector').value = currentMonth;

      // 自动加载当前月数据
      loadMonthlySummary('', '', currentMonth);
    });

    // 月份选择器改变时自动清空日期范围
    document.getElementById('monthly-month-selector')?.addEventListener('change', function() {
      if (this.value) {
        document.getElementById('monthly-from-date').value = '';
        document.getElementById('monthly-to-date').value = '';
      }
    });

    // 日期范围改变时自动清空月份选择
    document.getElementById('monthly-from-date')?.addEventListener('change', function() {
      if (this.value) {
        document.getElementById('monthly-month-selector').value = '';
      }
    });
    document.getElementById('monthly-to-date')?.addEventListener('change', function() {
      if (this.value) {
        document.getElementById('monthly-month-selector').value = '';
      }
    });

    function loadMonthlySummary(fromDate, toDate, month) {
      var ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
      var ajaxNonce = window.RUIYI_POS?.nonce || posNonce;

      // 显示加载状态
      document.getElementById('monthly-summary-loading').classList.remove('hidden');
      document.getElementById('monthly-summary-stats').classList.add('hidden');
      document.getElementById('monthly-summary-table-container').classList.add('hidden');
      document.getElementById('monthly-no-data').classList.add('hidden');

      fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          action: 'ruiyi_get_monthly_summary',
          nonce: ajaxNonce,
          from_date: fromDate,
          to_date: toDate,
          month: month
        })
      })
      .then(res => res.json())
      .then(response => {
        document.getElementById('monthly-summary-loading').classList.add('hidden');

        if (response.success) {
          monthlySummaryData = response.data;
          displayMonthlySummary(response.data);
        } else {
          Swal.fire({
            icon: 'error',
            title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
            text: response.data?.message || '<?php echo ruiyi_translate("No se pudieron cargar los datos", "Could not load data", "无法加载数据"); ?>'
          });
        }
      })
      .catch(error => {
        document.getElementById('monthly-summary-loading').classList.add('hidden');
        console.error('[月结单] 加载失败:', error);
        Swal.fire({
          icon: 'error',
          title: '<?php echo ruiyi_translate("Error de conexión", "Connection error", "连接错误"); ?>',
          text: error.message
        });
      });
    }

    function displayMonthlySummary(data) {
      const { records, summary } = data;

      if (!records || records.length === 0) {
        document.getElementById('monthly-no-data').classList.remove('hidden');
        document.getElementById('monthly-pagination')?.classList.add('hidden');
        return;
      }

      // 显示统计汇总 - 🔥 修复字段名并添加空值检查
      const total = parseFloat(summary?.total || 0);
      const card = parseFloat(summary?.card || 0);
      const cash = parseFloat(summary?.cash || 0);
      const bizum = parseFloat(summary?.bizum || 0);

      document.getElementById('monthly-period-total').textContent = '€' + total.toFixed(2);
      document.getElementById('monthly-period-card').textContent = '€' + card.toFixed(2);
      document.getElementById('monthly-period-cash').textContent = '€' + cash.toFixed(2);
      const monthlyBizumEl = document.getElementById('monthly-period-bizum');
      if (monthlyBizumEl) monthlyBizumEl.textContent = '€' + bizum.toFixed(2);
      document.getElementById('monthly-summary-stats').classList.remove('hidden');

      // 🔥 重置到第一页
      monthlyCurrentPage = 1;

      // 🔥 渲染当前页数据
      renderMonthlyPage(records);

      document.getElementById('monthly-summary-table-container').classList.remove('hidden');
    }

    // 🔥 渲染指定页的月结单数据
    function renderMonthlyPage(records) {
      const tableBody = document.getElementById('monthly-summary-list');
      tableBody.innerHTML = '';

      // 计算分页信息
      const totalRecords = records.length;
      const totalPages = Math.ceil(totalRecords / monthlyPageSize);
      const startIndex = (monthlyCurrentPage - 1) * monthlyPageSize;
      const endIndex = Math.min(startIndex + monthlyPageSize, totalRecords);

      // 获取当前页的记录
      const pageRecords = records.slice(startIndex, endIndex);

      const bizumEnabled = <?php echo (get_option('pos_bizum_enabled', '0') === '1') ? 'true' : 'false'; ?>;
      pageRecords.forEach(record => {
        const row = document.createElement('tr');
        const recordTotal = parseFloat(record.total_amount || 0);
        const recordCash = parseFloat(record.cash_amount || 0);
        const recordCard = parseFloat(record.card_amount || 0);
        const recordBizum = parseFloat(record.bizum_amount || 0);

        // 格式化结算时间显示
        let dateDisplay = record.date || '-';
        if (record.settlement_datetime) {
          // 🔥 格式：DD-MM-YYYY HH:MM（保留准确时间）
          const settlementParts = record.settlement_datetime.split(' ');
          if (settlementParts.length === 2) {
            const datePart = settlementParts[0].split('-');
            const timePart = settlementParts[1].substring(0, 5); // 取 HH:MM
            if (datePart.length === 3) {
              // 格式：DD-MM-YYYY HH:MM
              dateDisplay = `${datePart[2]}-${datePart[1]}-${datePart[0]} ${timePart}`;
            }
          }
        }

        // 🔥 格式化时段显示（开始时间 - 结束时间）
        let periodDisplay = '-';
        if (record.period_start && record.period_end) {
          // 格式化开始时间
          const startParts = record.period_start.split(' ');
          const endParts = record.period_end.split(' ');
          if (startParts.length === 2 && endParts.length === 2) {
            const startDate = startParts[0].split('-');
            const startTime = startParts[1].substring(0, 5);
            const endDate = endParts[0].split('-');
            const endTime = endParts[1].substring(0, 5);
            // 格式：DD/MM HH:MM - DD/MM HH:MM
            if (startDate.length === 3 && endDate.length === 3) {
              periodDisplay = `${startDate[2]}/${startDate[1]} ${startTime} - ${endDate[2]}/${endDate[1]} ${endTime}`;
            }
          }
        }

        row.innerHTML = `
          <td class="px-6 py-4 text-sm text-gray-900 dark:text-gray-100">${dateDisplay}</td>
          <td class="px-6 py-4 text-sm text-gray-600 dark:text-gray-400 text-xs">${periodDisplay}</td>
          <td class="px-6 py-4 text-sm text-right font-semibold text-gray-900 dark:text-gray-100">€${recordTotal.toFixed(2)}</td>
          <td class="px-6 py-4 text-sm text-right text-gray-900 dark:text-gray-100">€${recordCash.toFixed(2)}</td>
          <td class="px-6 py-4 text-sm text-right text-gray-900 dark:text-gray-100">€${recordCard.toFixed(2)}</td>
          ${bizumEnabled ? `<td class="px-6 py-4 text-sm text-right text-gray-900 dark:text-gray-100">€${recordBizum.toFixed(2)}</td>` : ''}
        `;
        tableBody.appendChild(row);
      });

      // 🔥 更新分页信息
      updateMonthlyPagination(totalRecords, totalPages, startIndex + 1, endIndex);
    }

    // 🔥 更新分页控件状态
    function updateMonthlyPagination(totalRecords, totalPages, showingFrom, showingTo) {
      document.getElementById('monthly-showing-from').textContent = showingFrom;
      document.getElementById('monthly-showing-to').textContent = showingTo;
      document.getElementById('monthly-total-records').textContent = totalRecords;
      document.getElementById('monthly-current-page').textContent = monthlyCurrentPage;
      document.getElementById('monthly-total-pages').textContent = totalPages;

      // 更新按钮状态
      const prevBtn = document.getElementById('monthly-prev-page');
      const nextBtn = document.getElementById('monthly-next-page');

      if (prevBtn) {
        prevBtn.disabled = monthlyCurrentPage <= 1;
      }
      if (nextBtn) {
        nextBtn.disabled = monthlyCurrentPage >= totalPages;
      }

      // 如果只有一页，隐藏分页控件
      const paginationEl = document.getElementById('monthly-pagination');
      if (paginationEl) {
        if (totalPages <= 1) {
          paginationEl.classList.add('hidden');
        } else {
          paginationEl.classList.remove('hidden');
        }
      }
    }

    // 🔥 分页按钮事件
    document.getElementById('monthly-prev-page')?.addEventListener('click', function() {
      if (monthlyCurrentPage > 1 && monthlySummaryData?.records) {
        monthlyCurrentPage--;
        renderMonthlyPage(monthlySummaryData.records);
      }
    });

    document.getElementById('monthly-next-page')?.addEventListener('click', function() {
      if (monthlySummaryData?.records) {
        const totalPages = Math.ceil(monthlySummaryData.records.length / monthlyPageSize);
        if (monthlyCurrentPage < totalPages) {
          monthlyCurrentPage++;
          renderMonthlyPage(monthlySummaryData.records);
        }
      }
    });

    // 查看单日详情
    function viewDailySummaryDetail(date) {
      if (!monthlySummaryData || !monthlySummaryData.records) return;

      const record = monthlySummaryData.records.find(r => r.date === date);
      if (!record) return;

      // 🔥 确保数值字段有默认值
      const totalAmount = parseFloat(record.total_amount) || 0;
      const cashAmount = parseFloat(record.cash_amount) || 0;
      const cardAmount = parseFloat(record.card_amount) || 0;

      // 格式化结算时间和时段信息
      let settlementInfo = '';
      if (record.settlement_datetime) {
        settlementInfo += `<p><strong><?php echo ruiyi_translate("Hora de cierre", "Settlement time", "结单时间"); ?>:</strong> ${record.settlement_datetime}</p>`;
      }
      if (record.period_start && record.period_end) {
        settlementInfo += `<p><strong><?php echo ruiyi_translate("Período de facturación", "Billing period", "结算时段"); ?>:</strong><br/>${record.period_start} - ${record.period_end}</p>`;
      }

      let categoriesHtml = '';
      if (record.categories_data && record.categories_data.length > 0) {
        categoriesHtml = '<table class="min-w-full mt-4"><thead><tr><th class="text-left">Categoría</th><th class="text-right">Total</th></tr></thead><tbody>';
        record.categories_data.forEach(cat => {
          // 🔥 确保分类金额有默认值
          const catTotal = parseFloat(cat.total) || 0;
          categoriesHtml += `<tr><td class="py-2">${cat.name}</td><td class="text-right">€${catTotal.toFixed(2)}</td></tr>`;
        });
        categoriesHtml += '</tbody></table>';
      }

      Swal.fire({
        title: '<?php echo ruiyi_translate("Detalle del día", "Daily detail", "日结详情"); ?>: ' + date,
        html: `
          <div class="text-left">
            <p><strong><?php echo ruiyi_translate("Fecha de negocio", "Business date", "营业日期"); ?>:</strong> ${record.date}</p>
            ${settlementInfo}
            <hr class="my-4" />
            <p><strong><?php echo ruiyi_translate("Total", "Total", "总计"); ?>:</strong> €${totalAmount.toFixed(2)}</p>
            <p><strong><?php echo ruiyi_translate("Efectivo", "Cash", "现金"); ?>:</strong> €${cashAmount.toFixed(2)}</p>
            <p><strong><?php echo ruiyi_translate("Tarjeta", "Card", "刷卡"); ?>:</strong> €${cardAmount.toFixed(2)}</p>
            ${categoriesHtml}
          </div>
        `,
        width: 600,
        confirmButtonText: '<?php echo ruiyi_translate("Cerrar", "Close", "关闭"); ?>'
      });
    }

    // 打印月结单
    document.getElementById('print-monthly-summary')?.addEventListener('click', function() {
      if (!monthlySummaryData || !monthlySummaryData.records || monthlySummaryData.records.length === 0) {
        Swal.fire({
          icon: 'warning',
          title: '<?php echo ruiyi_translate("Sin datos", "No data", "无数据"); ?>',
          text: '<?php echo ruiyi_translate("No hay datos para imprimir", "No data to print", "没有可打印的数据"); ?>'
        });
        return;
      }

      printMonthlySummary(monthlySummaryData);
    });

    function printMonthlySummary(data) {
      // 检查CLODOP是否可用
      if (typeof getLodop === 'undefined') {
        // 🔥 使用用户友好的打印机配置提示
        showPrinterConfigDialog();
        return;
      }

      // 🔥 数据验证和默认值处理
      if (!data || !data.summary) {
        Swal.fire({
          icon: 'info',
          title: '<?php echo ruiyi_translate("Aviso", "Notice", "提示"); ?>',
          text: '<?php echo ruiyi_translate("No hay datos para imprimir", "No data to print", "暂无数据可打印"); ?>',
          confirmButtonColor: '#3b82f6'
        });
        return;
      }

      // 🔥 修复：确保所有数值字段都有默认值，优先使用后端返回的字段名（total, card, cash）
      const summary = {
        total_amount: parseFloat(data.summary.total) || parseFloat(data.summary.total_amount) || 0,
        total_card: parseFloat(data.summary.card) || parseFloat(data.summary.total_card) || 0,
        total_cash: parseFloat(data.summary.cash) || parseFloat(data.summary.total_cash) || 0,
        total_bizum: parseFloat(data.summary.bizum) || parseFloat(data.summary.total_bizum) || 0,
        count: parseInt(data.summary.count) || 0
      };

      // 🔥 调试：记录读取到的数据

      const records = data.records || [];
      const filters = data.filters || {};

      try {
        const LODOP = getLodop();
        if (!LODOP || !LODOP.VERSION) {
          throw new Error('CLODOP service not connected');
        }

        const defaultPrinter = window.clodopConfig?.defaultPrinter || '';

        LODOP.SET_LICENSES("","D615C875005D74B88EC9E2585C79798E9CA","","");
        LODOP.PRINT_INIT("Resumen mensual");
        LODOP.SET_PRINT_PAGESIZE(3, "80mm", 0, "");

        if (defaultPrinter) {
          LODOP.SET_PRINTER_INDEX(defaultPrinter);
        }

        let y = 5;
        let elementIndex = 0;

        // 店铺名称
        LODOP.ADD_PRINT_TEXT(y + "mm", "0mm", "80mm", "10mm", <?php echo json_encode(str_replace(array("\r\n", "\n", "\r"), " ", get_option('pos_store_name', get_bloginfo('name')))); ?>);
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 16);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 2);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Alignment", 1);
        elementIndex++;
        y += 12;

        // 月结单标题
        LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "8mm", "RESUMEN MENSUAL");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 14);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Alignment", 1);
        elementIndex++;
        y += 10;

        // 期间信息
        let periodText = '';
        if (filters.month) {
          periodText = 'Mes: ' + filters.month;
        } else if (filters.from_date && filters.to_date) {
          periodText = filters.from_date + ' a ' + filters.to_date;
        } else if (filters.from_date) {
          periodText = 'Desde: ' + filters.from_date;
        } else if (filters.to_date) {
          periodText = 'Hasta: ' + filters.to_date;
        }

        LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", periodText);
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 10);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Alignment", 1);
        elementIndex++;
        y += 7;

        // 分隔线
        LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "3mm", "================================");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 9);
        elementIndex++;
        y += 5;

        // 🔥 汇总统计 - 欧元符号放在数字后面
        LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "6mm", "TOTAL PERIODO: " + summary.total_amount.toFixed(2) + " €");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 12);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Alignment", 1);
        elementIndex++;
        y += 8;

        LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "Tarjeta: " + summary.total_card.toFixed(2) + " €");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 10);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Alignment", 1);
        elementIndex++;
        y += 6;

        LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "Efectivo: " + summary.total_cash.toFixed(2) + " €");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 10);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Alignment", 1);
        elementIndex++;
        y += 6;

        // Bizum/转账金额（如果有）
        if (summary.total_bizum > 0) {
          LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "Transferencia: " + summary.total_bizum.toFixed(2) + " €");
          LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
          LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 10);
          LODOP.SET_PRINT_STYLEA(elementIndex, "Alignment", 1);
          elementIndex++;
          y += 6;
        }
        y += 4;

        const formatMonthlySummaryDate = (record) => {
          const rawDate = record.business_date || record.date || record.settlement_date || record.period_start || record.settlement_datetime || '';
          const dateText = String(rawDate || '').trim();
          const matchIso = dateText.match(/(\d{4})-(\d{2})-(\d{2})/);
          if (matchIso) {
            return `${matchIso[3]}-${matchIso[2]}`;
          }
          const matchSpanish = dateText.match(/(\d{2})[\/-](\d{2})[\/-](\d{4})/);
          if (matchSpanish) {
            return `${matchSpanish[1]}-${matchSpanish[2]}`;
          }
          return dateText || '--';
        };

        const formatMonthlySummaryAmount = (value) => {
          return (parseFloat(value) || 0).toFixed(2) + " €";
        };

        // 每日明细
        LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "DETALLE POR DIA");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 10);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Alignment", 1);
        elementIndex++;
        y += 6;

        LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "12mm", "5mm", "Fecha");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 9);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Alignment", 1);
        elementIndex++;
        LODOP.ADD_PRINT_TEXT(y + "mm", "15mm", "21mm", "5mm", "Efectivo");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 9);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Alignment", 3);
        elementIndex++;
        LODOP.ADD_PRINT_TEXT(y + "mm", "38mm", "18mm", "5mm", "Tarjeta");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 9);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Alignment", 3);
        elementIndex++;
        LODOP.ADD_PRINT_TEXT(y + "mm", "58mm", "18mm", "5mm", "Total");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 9);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Alignment", 3);
        elementIndex++;
        y += 6;

        records.forEach(record => {
          LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "12mm", "5mm", formatMonthlySummaryDate(record));
          LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
          LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 9);
          LODOP.SET_PRINT_STYLEA(elementIndex, "Alignment", 1);
          elementIndex++;

          LODOP.ADD_PRINT_TEXT(y + "mm", "15mm", "21mm", "5mm", formatMonthlySummaryAmount(record.cash_amount));
          LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
          LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 9);
          LODOP.SET_PRINT_STYLEA(elementIndex, "Alignment", 3);
          elementIndex++;

          LODOP.ADD_PRINT_TEXT(y + "mm", "38mm", "18mm", "5mm", formatMonthlySummaryAmount(record.card_amount));
          LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
          LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 9);
          LODOP.SET_PRINT_STYLEA(elementIndex, "Alignment", 3);
          elementIndex++;

          LODOP.ADD_PRINT_TEXT(y + "mm", "58mm", "18mm", "5mm", formatMonthlySummaryAmount(record.total_amount));
          LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
          LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 9);
          LODOP.SET_PRINT_STYLEA(elementIndex, "Alignment", 3);
          elementIndex++;
          y += 6;
        });

        y += 3;

        // 打印时间
        const printTime = new Date().toLocaleString();
        LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "Impreso: " + printTime);
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", "Arial");
        LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 8);
        LODOP.SET_PRINT_STYLEA(elementIndex, "Alignment", 1);

        // 执行打印
        LODOP.PRINT();

        Toastify({
          text: '<?php echo ruiyi_translate("Imprimiendo resumen mensual...", "Printing monthly summary...", "正在打印月结单..."); ?>',
          duration: 2000,
          gravity: "top",
          position: "center",
          style: { background: "#10b981" }
        }).showToast();

      } catch (error) {
        console.error('CLODOP打印错误:', error);
        // 🔥 使用用户友好的打印机配置提示
        showPrinterConfigDialog();
      }
    }

    // ========================================
    // 🔥 历史日结单功能
    // ========================================
    let settlementHistoryLoaded = false;
    let settlementHistoryData = [];

    // 加载历史日结单列表
    document.getElementById('load-settlement-history')?.addEventListener('click', function() {
      const fromDate = document.getElementById('history-from-date').value;
      const toDate = document.getElementById('history-to-date').value;
      loadSettlementHistory(fromDate, toDate);
    });

    // 重置筛选条件
    document.getElementById('reset-history-filters')?.addEventListener('click', function() {
      document.getElementById('history-from-date').value = '';
      document.getElementById('history-to-date').value = '';
      loadSettlementHistory();
    });

    function loadSettlementHistory(fromDate = '', toDate = '') {
      var ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
      var ajaxNonce = window.RUIYI_POS?.nonce || posNonce;

      // 显示加载状态
      document.getElementById('settlement-history-loading')?.classList.remove('hidden');
      document.getElementById('settlement-history-content')?.classList.add('hidden');
      document.getElementById('settlement-history-no-data')?.classList.add('hidden');

      fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          action: 'ruiyi_get_daily_settlement_history',
          nonce: ajaxNonce,
          from_date: fromDate,
          to_date: toDate
        })
      })
      .then(res => res.json())
      .then(response => {
        document.getElementById('settlement-history-loading')?.classList.add('hidden');

        if (response.success && response.data.history) {
          settlementHistoryData = response.data.history;
          settlementHistoryLoaded = true;

          if (settlementHistoryData.length > 0) {
            renderSettlementHistory(settlementHistoryData);
            document.getElementById('settlement-history-content')?.classList.remove('hidden');
          } else {
            document.getElementById('settlement-history-no-data')?.classList.remove('hidden');
          }
        } else {
          document.getElementById('settlement-history-no-data')?.classList.remove('hidden');
        }
      })
      .catch(error => {
        console.error('[历史日结单] 加载失败:', error);
        document.getElementById('settlement-history-loading')?.classList.add('hidden');
        document.getElementById('settlement-history-no-data')?.classList.remove('hidden');
      });
    }

    function renderSettlementHistory(history) {
      const tableBody = document.getElementById('settlement-history-list');
      if (!tableBody) return;

      tableBody.innerHTML = '';

      history.forEach(record => {
        const row = document.createElement('tr');
        row.className = 'hover:bg-gray-50 dark:hover:bg-gray-700';

        // 格式化日期显示
        const businessDate = record.business_date || '-';

        // 🔥 格式化时段显示（开始时间 - 结束时间）
        let periodDisplay = '-';
        if (record.period_start && record.period_end) {
          const startParts = record.period_start.split(' ');
          const endParts = record.period_end.split(' ');
          if (startParts.length === 2 && endParts.length === 2) {
            const startDate = startParts[0].split('-');
            const startTime = startParts[1].substring(0, 5);
            const endDate = endParts[0].split('-');
            const endTime = endParts[1].substring(0, 5);
            // 格式：DD/MM HH:MM - DD/MM HH:MM
            if (startDate.length === 3 && endDate.length === 3) {
              periodDisplay = `${startDate[2]}/${startDate[1]} ${startTime} - ${endDate[2]}/${endDate[1]} ${endTime}`;
            }
          }
        }

        // 格式化结算时间
        let settlementTime = '-';
        if (record.settlement_datetime) {
          const parts = record.settlement_datetime.split(' ');
          if (parts.length === 2) {
            settlementTime = parts[1].substring(0, 5); // 取 HH:MM
          }
        }

        // 🔥 结算类型标识
        const settlementTypeBadge = record.settlement_type === 'auto'
          ? '<span class="ml-2 px-1.5 py-0.5 text-xs bg-blue-100 text-blue-600 dark:bg-blue-900 dark:text-blue-300 rounded"><?php echo ruiyi_translate("Auto", "Auto", "自动"); ?></span>'
          : '';

        const total = parseFloat(record.total_amount || 0).toFixed(2);
        const cash = parseFloat(record.cash_amount || 0).toFixed(2);
        const card = parseFloat(record.card_amount || 0).toFixed(2);

        row.innerHTML = `
          <td class="px-4 py-3 text-sm text-gray-900 dark:text-gray-100">${businessDate}${settlementTypeBadge}</td>
          <td class="px-4 py-3 text-sm text-gray-600 dark:text-gray-400 text-xs">${periodDisplay}</td>
          <td class="px-4 py-3 text-sm text-gray-900 dark:text-gray-100">${settlementTime}</td>
          <td class="px-4 py-3 text-sm text-right font-semibold text-green-600 dark:text-green-400">€${total}</td>
          <td class="px-4 py-3 text-sm text-right text-yellow-600 dark:text-yellow-400">€${cash}</td>
          <td class="px-4 py-3 text-sm text-right text-blue-600 dark:text-blue-400">€${card}</td>
          <td class="px-4 py-3 text-center">
            <button onclick="reprintSettlement('${record.id}')" class="px-3 py-1 bg-indigo-600 hover:bg-indigo-700 text-white text-sm rounded-md transition-colors">
              <i class="fas fa-print mr-1"></i>
              <?php echo ruiyi_translate('Reimprimir', 'Reprint', '重新打印'); ?>
            </button>
          </td>
        `;
        tableBody.appendChild(row);
      });
    }

    // 重新打印历史日结单
    function reprintSettlement(settlementId) {
      var ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
      var ajaxNonce = window.RUIYI_POS?.nonce || posNonce;

      Swal.fire({
        title: '<?php echo ruiyi_translate("Cargando datos...", "Loading data...", "加载数据中..."); ?>',
        allowOutsideClick: false,
        didOpen: () => { Swal.showLoading(); }
      });

      fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          action: 'ruiyi_get_daily_settlement_detail',
          nonce: ajaxNonce,
          settlement_id: settlementId
        })
      })
      .then(res => res.json())
      .then(response => {
        Swal.close();

        if (response.success && response.data.settlement) {
          const settlement = response.data.settlement;

          // 构建与日结单打印函数兼容的数据格式
          const printData = {
            total_amount: settlement.total_amount,
            cash_amount: settlement.cash_amount,
            card_amount: settlement.card_amount,
            starting_cash: settlement.starting_cash || 0, // 🔥 添加启始现金
            products: settlement.products || [],
            transactions: settlement.transactions || [],
            start_date: settlement.business_date,
            settlement_datetime: settlement.settlement_datetime,
            period_start: settlement.period_start,
            period_end: settlement.period_end,
            start_datetime: settlement.period_start, // 🔥 用于打印显示
            end_datetime: settlement.period_end,     // 🔥 用于打印显示
            is_reprint: true // 标记为重新打印
          };

          // 调用现有的日结单打印函数
          if (typeof printDailySummaryWithCLODOP === 'function') {
            printDailySummaryWithCLODOP(printData);

            Toastify({
              text: '<?php echo ruiyi_translate("Reimprimiendo cierre diario...", "Reprinting daily settlement...", "正在重新打印日结单..."); ?>',
              duration: 2000,
              gravity: "top",
              position: "center",
              style: { background: "#10b981" }
            }).showToast();
          } else {
            Swal.fire({
              icon: 'error',
              title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
              text: '<?php echo ruiyi_translate("Función de impresión no disponible", "Print function not available", "打印功能不可用"); ?>'
            });
          }
        } else {
          Swal.fire({
            icon: 'error',
            title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
            text: response.data?.message || '<?php echo ruiyi_translate("No se pudo obtener los datos", "Could not get data", "无法获取数据"); ?>'
          });
        }
      })
      .catch(error => {
        Swal.close();
        console.error('[历史日结单] 获取详情失败:', error);
        Swal.fire({
          icon: 'error',
          title: '<?php echo ruiyi_translate("Error de conexión", "Connection error", "连接错误"); ?>',
          text: error.message
        });
      });
    }

  </script>

