            <!-- 统一保存按钮 -->
            <button id="save-all-categories-btn" class="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2" disabled>
