              <?php echo ruiyi_translate('Guardar Cambios', 'Save Changes', '保存更改'); ?>
            </button>
          </div>

          <div id="edit-category-list" class="space-y-2">
            <?php
            // 使用树形结构显示分类
            $category_tree = ruiyi_get_category_tree(0, 1, 3);

            function render_category_tree_for_edit($categories, $depth = 1) {
              foreach ($categories as $cat) {
                $indent = ($depth - 1) * 24; // 每层缩进24px
                $depth_colors = [
                  1 => 'bg-blue-50 border-blue-200',
                  2 => 'bg-green-50 border-green-200',
                  3 => 'bg-yellow-50 border-yellow-200',
                ];
                $bg_class = $depth_colors[$depth] ?? 'bg-gray-50 border-gray-200';
                $depth_labels = [
                  1 => ruiyi_translate('Nivel 1', 'Level 1', '一级'),
                  2 => ruiyi_translate('Nivel 2', 'Level 2', '二级'),
                  3 => ruiyi_translate('Nivel 3', 'Level 3', '三级'),
                ];
                $depth_label = $depth_labels[$depth] ?? '';

                // 🔥 获取分类的自定义背景颜色
                $category_bg_color = get_term_meta($cat['term_id'], '_ruiyi_category_bg_color', true);
                if (empty($category_bg_color)) {
                  $category_bg_color = ''; // 空值表示使用全局默认颜色
                }

                echo '<div class="category-edit-item flex items-center gap-3 p-3 rounded-lg border ' . $bg_class . '"
                      data-category-id="' . esc_attr($cat['term_id']) . '"
                      data-depth="' . esc_attr($depth) . '"
                      data-has-children="' . ($cat['has_children'] ? '1' : '0') . '"
                      data-sort-order="' . esc_attr($cat['sort_order']) . '"
                      style="margin-left: ' . $indent . 'px;">';

                if ($depth == 1) {
                  echo '<button type="button" class="category-drag-handle text-gray-400 hover:text-blue-600 cursor-move p-2 rounded-lg hover:bg-white/70 transition-colors"
                         draggable="true"
                         title="' . ruiyi_translate('Arrastrar para ordenar', 'Drag to reorder', '拖动调整顺序') . '">
                         <i class="fas fa-grip-vertical"></i>
                       </button>';
                } else {
                  echo '<span class="w-8 shrink-0"></span>';
                }

                // 层级指示器
                echo '<span class="text-xs font-medium px-2 py-1 rounded ' .
                     ($depth == 1 ? 'bg-blue-100 text-blue-700' :
                     ($depth == 2 ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700')) . '">' .
                     $depth_label . '</span>';

                // 一级分类显示排序输入框
                if ($depth == 1) {
                  $sort_order_value = $cat['sort_order'] == 999 ? '' : $cat['sort_order'];
                  echo '<input type="number" value="' . esc_attr($sort_order_value) . '"
                         class="w-16 px-2 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-center category-sort-input"
                         data-original-sort="' . esc_attr($sort_order_value) . '"
                         placeholder="#"
                         min="1"
                         title="' . ruiyi_translate('Orden de visualización', 'Display order', '显示顺序') . '">';
                }

                // 🔥 颜色选择器（仅一级分类显示）
                if ($depth == 1) {
                  $default_color = get_option('pos_category_unselected_bg', '#E05C40');
                  $display_color = !empty($category_bg_color) ? $category_bg_color : $default_color;
                  echo '<div class="flex items-center gap-1" title="' . ruiyi_translate('Color de fondo', 'Background color', '背景颜色') . '">';
                  echo '<input type="color" value="' . esc_attr($display_color) . '"
                         class="w-10 h-10 cursor-pointer rounded border border-gray-300 category-color-input"
                         data-original-color="' . esc_attr($category_bg_color) . '"
                         style="padding: 2px;">';
                  // 重置颜色按钮
                  echo '<button type="button" class="reset-color-btn text-gray-400 hover:text-gray-600 p-1" title="' . ruiyi_translate('Restablecer color predeterminado', 'Reset to default color', '重置为默认颜色') . '"' . (empty($category_bg_color) ? ' style="visibility: hidden;"' : '') . '>';
                  echo '<i class="fas fa-undo text-xs"></i>';
                  echo '</button>';
                  echo '</div>';
                }

                $category_image_id = isset($cat['image_id']) ? absint($cat['image_id']) : 0;
                $category_image_url = !empty($cat['image_url']) ? $cat['image_url'] : (function_exists('ruiyi_get_product_category_image_url') ? ruiyi_get_product_category_image_url($cat['term_id'], 'thumbnail') : '');
                echo '<div class="category-image-editor flex items-center gap-2" title="' . esc_attr(ruiyi_translate('Imagen de categoría', 'Category image', '分类图片')) . '">';
                echo '<input type="hidden" class="category-image-id-input" value="' . esc_attr($category_image_id) . '" data-original-image-id="' . esc_attr($category_image_id) . '">';
                echo '<div class="category-image-preview w-12 h-12 rounded-lg border border-gray-300 bg-white overflow-hidden flex items-center justify-center shrink-0">';
                if (!empty($category_image_url)) {
                  echo '<img src="' . esc_url($category_image_url) . '" alt="' . esc_attr($cat['name']) . '" class="w-full h-full object-cover">';
                } else {
                  echo '<i class="fas fa-image text-gray-300"></i>';
                }
                echo '</div>';
                echo '<div class="flex flex-col gap-1 shrink-0">';
                echo '<button type="button" class="category-image-upload-btn px-2 py-1 text-xs bg-blue-500 text-white rounded hover:bg-blue-600 transition-colors">' . ruiyi_translate('Subir', 'Upload', '上传') . '</button>';
                echo '<button type="button" class="category-image-remove-btn px-2 py-1 text-xs bg-gray-500 text-white rounded hover:bg-gray-600 transition-colors' . (empty($category_image_url) ? ' hidden' : '') . '">' . ruiyi_translate('Quitar', 'Remove', '移除') . '</button>';
                echo '</div>';
                echo '</div>';

                // 分类名称输入框
                echo '<input type="text" value="' . esc_attr($cat['name']) . '"
                       class="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent category-name-input"
                       data-original-name="' . esc_attr($cat['name']) . '">';

                // 删除按钮
                echo '<button class="delete-category-btn px-3 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors text-sm">';
                echo ruiyi_translate('Eliminar', 'Delete', '删除');
                echo '</button>';

                echo '</div>';

                // 递归渲染子分类
                if (!empty($cat['children'])) {
                  render_category_tree_for_edit($cat['children'], $depth + 1);
                }
              }
            }

            render_category_tree_for_edit($category_tree);
            ?>
          </div>
        </div>
      </div>
    </div>
  </div>
</div>

