<script>
  // Wait for DOM to be ready
  document.addEventListener('DOMContentLoaded', function() {
    // F5 Key Listener - 根据设置决定是否启用
    document.addEventListener('keydown', function(e) {
      // 检查是否按下F5键
      if (e.key === 'F5' || (e.keyCode === 116)) {
        // 🔥 如果F5快捷键功能未启用，允许默认行为（刷新页面）
        if (typeof f5ShortcutEnabled === 'undefined' || !f5ShortcutEnabled) {
          return; // 不阻止默认行为，允许页面刷新
        }

        // 🔥 如果锁定商店管理员产品编辑功能启用，且当前用户是商店管理员，则不响应F5
        const config = window.RUIYI_POS_CONFIG || {};
        if (config.lockShopManagerEdit && config.isShopManager && !config.isAdministrator) {
          e.preventDefault(); // 阻止刷新
          console.log('[F5] 商店管理员产品编辑已锁定，F5无效');
          return; // 不打开产品管理面板
        }

        // F5快捷键功能启用时，阻止刷新并打开产品管理面板
        e.preventDefault();
        const modal = document.getElementById('product-management-modal');
        if (modal) {
          modal.classList.remove('hidden');
          // Focus first tab
          const firstTab = document.querySelector('.tab-button[data-tab="add-product"]');
          if (firstTab) {
            firstTab.click();
          }
        }
      }
    });

    // Modal Close Button
    const closeBtn = document.getElementById('close-product-modal');
    if (closeBtn) {
      closeBtn.addEventListener('click', function() {
        const modal = document.getElementById('product-management-modal');
        if (modal) {
          modal.classList.add('hidden');
        }
      });
    }

    // Close modal when clicking outside
    const modal = document.getElementById('product-management-modal');
    if (modal) {
      modal.addEventListener('click', function(e) {
        if (e.target === this) {
          this.classList.add('hidden');
        }
      });
    }

    // Tab Switching
    document.querySelectorAll('.tab-button').forEach(button => {
      button.addEventListener('click', function() {
        const tabName = this.getAttribute('data-tab');

        // Update tab buttons
        document.querySelectorAll('.tab-button').forEach(btn => {
          btn.classList.remove('active');
          btn.classList.add('text-gray-500');
          btn.classList.remove('text-gray-700');
        });
        this.classList.add('active');
        this.classList.remove('text-gray-500');
        this.classList.add('text-gray-700');

        // Update tab content
        document.querySelectorAll('.tab-content').forEach(content => {
          content.classList.add('hidden');
        });
        const tabContent = document.getElementById('tab-' + tabName);
        if (tabContent) {
          tabContent.classList.remove('hidden');
        }

        // Load products if Edit Product tab is selected
        if (tabName === 'edit-product') {
          // 进入编辑产品页面时自动选择第一个分类，但不自动选择产品
          loadProductsByCategory();
        }
      });
    });

    // Reset edit product tab to initial state (no selection)
    function resetEditProductTab() {
      // 取消所有分类选中状态
      document.querySelectorAll('.category-item').forEach(item => {
        item.classList.remove('selected');
      });
      // 清空产品列表
      const tbody = document.getElementById('products-table-body');
      if (tbody) {
        tbody.innerHTML = '<tr><td colspan="3" class="border border-gray-300 px-4 py-2 text-center text-gray-500"><?php echo ruiyi_translate("Seleccione una categoría", "Select a category", "请选择一个分类"); ?></td></tr>';
      }
      // 隐藏编辑表单
      const editFormContainer = document.getElementById('edit-product-form-container');
      if (editFormContainer) {
        editFormContainer.classList.add('hidden');
      }
    }

    // Load products by category
    function loadProductsByCategory(categoryId = null) {
      if (!categoryId) {
        // 如果没有传入categoryId，自动选择第一个分类
        const firstCategory = document.querySelector('.category-item');
        if (firstCategory) {
          categoryId = firstCategory.getAttribute('data-category-id');
          // 设置选中样式
          document.querySelectorAll('.category-item').forEach(i => {
            i.classList.remove('selected', 'bg-pink-100', 'border-pink-300');
            i.classList.add('bg-gray-50', 'border-gray-200');
          });
          firstCategory.classList.add('selected', 'bg-pink-100', 'border-pink-300');
          firstCategory.classList.remove('bg-gray-50', 'border-gray-200');
        } else {
          return;
        }
      }

      var ajaxUrl = '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
      const nonce = '<?php echo esc_js($ajax_nonce); ?>';

      fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          action: 'ruiyi_get_products_by_category',
          category_id: categoryId,
          nonce: nonce
        })
      })
      .then(response => response.json())
      .then(data => {
        if (data.success) {
          const tbody = document.getElementById('products-table-body');
          if (tbody) {
            tbody.innerHTML = '';

            if (data.data.products.length > 0) {
              data.data.products.forEach((product, index) => {
                const row = document.createElement('tr');
                row.className = ''; // 不自动选中任何产品
                row.setAttribute('data-product-id', product.id);
                // 根据当前语言显示产品名称
                const lang = window.RUIYI_POS?.currentLang || PHP_LANG || 'zh';
                let displayName = product.name;
                if (lang === 'zh' && product.name_zh) displayName = product.name_zh;
                else if (lang === 'en' && product.name_en) displayName = product.name_en;
                let displayCatName = product.category_name;
                if (lang === 'zh' && product.category_name_zh) displayCatName = product.category_name_zh;
                else if (lang === 'en' && product.category_name_en) displayCatName = product.category_name_en;
                row.innerHTML = `
                  <td class="border border-gray-300 px-4 py-2">${displayName}</td>
                  <td class="border border-gray-300 px-4 py-2">€${parseFloat(product.price).toFixed(2)}</td>
                  <td class="border border-gray-300 px-4 py-2">${displayCatName}</td>
                `;
                row.addEventListener('click', function() {
                  document.querySelectorAll('#products-table tbody tr').forEach(r => r.classList.remove('selected'));
                  this.classList.add('selected');

                  // Load product data for editing
                  loadProductForEdit(product.id);
                });
                tbody.appendChild(row);
              });

              // 不自动选择第一个产品，隐藏编辑表单等待用户选择
              const editFormContainer = document.getElementById('edit-product-form-container');
              const productsTableContainer = document.getElementById('products-table-container');
              if (editFormContainer) {
                editFormContainer.classList.add('hidden');
              }
              if (productsTableContainer) {
                productsTableContainer.classList.remove('hidden');
              }
            } else {
              tbody.innerHTML = '<tr><td colspan="3" class="border border-gray-300 px-4 py-2 text-center text-gray-500"><?php echo ruiyi_translate("No hay productos en esta categoría", "No products in this category", "此分类下没有产品"); ?></td></tr>';
              // Hide edit form when no products
              const editFormContainer2 = document.getElementById('edit-product-form-container');
              const productsTableContainer2 = document.getElementById('products-table-container');
              if (editFormContainer2) {
                editFormContainer2.classList.add('hidden');
              }
              if (productsTableContainer2) {
                productsTableContainer2.classList.remove('hidden');
              }
            }
          }
        }
      })
      .catch(error => {
        console.error('Error loading products:', error);
      });
    }

    // Load product data for editing
    function loadProductForEdit(productId) {
      var ajaxUrl = '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
      const nonce = '<?php echo esc_js($ajax_nonce); ?>';

      fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          action: 'get_product_data',
          product_id: productId,
          nonce: nonce
        })
      })
      .then(response => response.json())
      .then(data => {
        if (data.success && data.data) {
          const product = data.data;

          // Set form values
          const productIdInput = document.getElementById('edit-product-id');
          const productNameInput = document.getElementById('edit-product-name');
          const productPriceInput = document.getElementById('edit-product-price');
          const productCategoryInput = document.getElementById('edit-product-category');
          const productColorInput = document.getElementById('edit-product-color');
          const productImageIdInput = document.getElementById('edit-product-image-id');
          const productImageImg = document.getElementById('edit-product-image-img');
          const productImagePlaceholder = document.getElementById('edit-product-image-placeholder');
          const removeImageBtn = document.getElementById('edit-product-remove-image-btn');

          if (productIdInput) {
            productIdInput.value = product.id || '';
          }

          if (productNameInput) {
            productNameInput.value = product.name || '';
          }

          // 设置多语言名称
          const productNameZhInput = document.getElementById('edit-product-name-zh');
          const productNameEnInput = document.getElementById('edit-product-name-en');
          if (productNameZhInput) {
            productNameZhInput.value = product.name_zh || '';
          }
          if (productNameEnInput) {
            productNameEnInput.value = product.name_en || '';
          }

          if (productPriceInput) {
            // Use price, fallback to regular_price, then 0
            const price = product.price || product.regular_price || 0;
            const priceValue = parseFloat(price);
            productPriceInput.value = isNaN(priceValue) ? 0 : priceValue;
          }

          if (productCategoryInput) {
            productCategoryInput.value = product.category_id || '';
          }

          // Set product color
          if (productColorInput) {
            productColorInput.value = product.color || '';
          }


          // Set product image
          if (productImageIdInput) {
            productImageIdInput.value = product.image_id || '';
          }

          if (product.image_url && productImageImg && productImagePlaceholder) {
            productImageImg.src = product.image_url;
            productImageImg.classList.remove('hidden');
            productImagePlaceholder.classList.add('hidden');
            if (removeImageBtn) removeImageBtn.classList.remove('hidden');
          } else {
            if (productImageImg) {
              productImageImg.src = '';
              productImageImg.classList.add('hidden');
            }
            if (productImagePlaceholder) productImagePlaceholder.classList.remove('hidden');
            if (removeImageBtn) removeImageBtn.classList.add('hidden');
          }

          // 设置分区价格
          const zonePriceInputs = document.querySelectorAll('#edit-product-zone-prices .zone-price-input');
          zonePriceInputs.forEach(input => {
            const zoneKey = input.getAttribute('data-zone-key');
            if (product.zone_prices && product.zone_prices[zoneKey] !== undefined && product.zone_prices[zoneKey] !== '') {
              input.value = product.zone_prices[zoneKey];
            } else {
              input.value = ''; // 清空，让placeholder显示
            }
          });

          // 设置时价复选框
          const marketPriceCheckbox = document.getElementById('edit-product-market-price');
          if (marketPriceCheckbox) {
            marketPriceCheckbox.checked = product.market_price === 'yes' || product.market_price === true || product.market_price === '1';
          }

          // 设置过敏原复选框
          const allergenCheckboxes = document.querySelectorAll('#edit-product-allergens input[type="checkbox"]');
          const productAllergens = product.allergens || [];
          allergenCheckboxes.forEach(checkbox => {
            checkbox.checked = productAllergens.includes(checkbox.value);
          });

          // 更新过敏原已选数量显示
          const allergensSelectedCount = document.getElementById('allergens-selected-count');
          if (allergensSelectedCount) {
            const checkedCount = productAllergens.length;
            allergensSelectedCount.textContent = checkedCount > 0 ? '(' + checkedCount + ' <?php echo ruiyi_translate("seleccionados", "selected", "已选"); ?>)' : '';
          }

          // 重置过敏原区域为收起状态
          const allergensContainer = document.getElementById('edit-product-allergens');
          const allergensToggleIcon = document.getElementById('allergens-toggle-icon');
          if (allergensContainer) {
            allergensContainer.classList.add('hidden');
          }
          if (allergensToggleIcon) {
            allergensToggleIcon.classList.remove('rotate-180');
          }

          // Show edit form and hide product table
          const editFormContainer = document.getElementById('edit-product-form-container');
          const productsTableContainer = document.getElementById('products-table-container');
          if (editFormContainer) {
            editFormContainer.classList.remove('hidden');
          }
          if (productsTableContainer) {
            productsTableContainer.classList.add('hidden');
          }
        } else {
          console.error('Failed to load product data:', data);
          alert('<?php echo ruiyi_translate("Error al cargar los datos del producto", "Error loading product data", "加载产品数据时出错"); ?>');
        }
      })
      .catch(error => {
        console.error('Error loading product data:', error);
        alert('<?php echo ruiyi_translate("Error al cargar los datos del producto", "Error loading product data", "加载产品数据时出错"); ?>');
      });
    }

    // Category click handler
    document.querySelectorAll('.category-item').forEach(item => {
      item.addEventListener('click', function() {
        document.querySelectorAll('.category-item').forEach(i => {
          i.classList.remove('selected', 'bg-pink-100', 'border-pink-300');
          i.classList.add('bg-gray-50', 'border-gray-200');
        });
        this.classList.add('selected', 'bg-pink-100', 'border-pink-300');
        this.classList.remove('bg-gray-50', 'border-gray-200');

        const categoryId = this.getAttribute('data-category-id');
        loadProductsByCategory(categoryId);

        // Hide edit form and show product table when switching categories
        const editFormContainer = document.getElementById('edit-product-form-container');
        const productsTableContainer = document.getElementById('products-table-container');
        if (editFormContainer) {
          editFormContainer.classList.add('hidden');
        }
        if (productsTableContainer) {
          productsTableContainer.classList.remove('hidden');
        }
      });
    });

    // Edit Product Form Submit
    const editProductForm = document.getElementById('edit-product-form');
    if (editProductForm) {
      editProductForm.addEventListener('submit', function(e) {
        e.preventDefault();

        const productId = document.getElementById('edit-product-id').value;
        const productName = document.getElementById('edit-product-name').value.trim();
        const productNameZh = document.getElementById('edit-product-name-zh').value.trim();
        const productNameEn = document.getElementById('edit-product-name-en').value.trim();
        const productPrice = document.getElementById('edit-product-price').value;
        const productCategory = document.getElementById('edit-product-category').value;
        const productColor = document.getElementById('edit-product-color').value;
        const productImageId = document.getElementById('edit-product-image-id').value;
        const marketPrice = document.getElementById('edit-product-market-price').checked ? 'yes' : 'no';

        // 收集过敏原数据
        const allergens = [];
        document.querySelectorAll('#edit-product-allergens input[type="checkbox"]:checked').forEach(checkbox => {
          allergens.push(checkbox.value);
        });

        // 收集分区价格数据
        const zonePrices = {};
        document.querySelectorAll('#edit-product-zone-prices .zone-price-input').forEach(input => {
          const zoneKey = input.getAttribute('data-zone-key');
          const value = input.value.trim();
          if (zoneKey && value !== '') {
            zonePrices[zoneKey] = value;
          }
        });

        if (!productName || !productPrice || !productCategory) {
          alert('<?php echo ruiyi_translate("Por favor complete todos los campos", "Please fill in all fields", "请填写所有字段"); ?>');
          return;
        }

        var ajaxUrl = '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
        const nonce = '<?php echo esc_js($ajax_nonce); ?>';

        fetch(ajaxUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            action: 'update_product_data',
            product_id: productId,
            product_name: productName,
            product_name_zh: productNameZh,
            product_name_en: productNameEn,
            product_price: productPrice,
            product_category: productCategory,
            product_color: productColor,
            product_image_id: productImageId,
            zone_prices: JSON.stringify(zonePrices),
            market_price: marketPrice,
            allergens: JSON.stringify(allergens),
            nonce: nonce
          })
        })
        .then(response => response.json())
        .then(data => {
          if (data.success) {
            // 显示保存成功提示（不使用浏览器弹窗）
            showEditProductToast('<?php echo ruiyi_translate("Producto actualizado exitosamente", "Product updated successfully", "产品更新成功"); ?>', 'success');
            // Reload products for current category
            const selectedCategory = document.querySelector('.category-item.selected');
            if (selectedCategory) {
              const categoryId = selectedCategory.getAttribute('data-category-id');
              loadProductsByCategory(categoryId);
            }
          } else {
            showEditProductToast(data.data?.message || '<?php echo ruiyi_translate("Error al actualizar el producto", "Error updating product", "更新产品时出错"); ?>', 'error');
          }
        })
        .catch(error => {
          console.error('Error:', error);
          showEditProductToast('<?php echo ruiyi_translate("Error al actualizar el producto", "Error updating product", "更新产品时出错"); ?>', 'error');
        });
      });
    }

    // Allergens Toggle Functionality
    const allergensToggleBtn = document.getElementById('allergens-toggle-btn');
    const allergensContainer = document.getElementById('edit-product-allergens');
    const allergensToggleIcon = document.getElementById('allergens-toggle-icon');
    const allergensSelectedCount = document.getElementById('allergens-selected-count');

    if (allergensToggleBtn && allergensContainer) {
      allergensToggleBtn.addEventListener('click', function() {
        allergensContainer.classList.toggle('hidden');
        if (allergensToggleIcon) {
          allergensToggleIcon.classList.toggle('rotate-180');
        }
      });

      // Update selected count when checkboxes change
      function updateAllergensCount() {
        const checkedCount = allergensContainer.querySelectorAll('input[type="checkbox"]:checked').length;
        if (allergensSelectedCount) {
          allergensSelectedCount.textContent = checkedCount > 0 ? '(' + checkedCount + ' <?php echo ruiyi_translate("seleccionados", "selected", "已选"); ?>)' : '';
        }
      }

      // Add change listeners to allergen checkboxes
      allergensContainer.querySelectorAll('input[type="checkbox"]').forEach(checkbox => {
        checkbox.addEventListener('change', updateAllergensCount);
      });
    }

    // Cancel Edit Button
    const cancelEditBtn = document.getElementById('cancel-edit-product');
    if (cancelEditBtn) {
      cancelEditBtn.addEventListener('click', function() {
        const editFormContainer = document.getElementById('edit-product-form-container');
        const productsTableContainer = document.getElementById('products-table-container');
        if (editFormContainer) {
          editFormContainer.classList.add('hidden');
        }
        if (productsTableContainer) {
          productsTableContainer.classList.remove('hidden');
        }
        // Clear form
        document.getElementById('edit-product-form').reset();
        // Reset image preview
        const productImageImg = document.getElementById('edit-product-image-img');
        const productImagePlaceholder = document.getElementById('edit-product-image-placeholder');
        const removeImageBtn = document.getElementById('edit-product-remove-image-btn');
        if (productImageImg) {
          productImageImg.src = '';
          productImageImg.classList.add('hidden');
        }
        if (productImagePlaceholder) productImagePlaceholder.classList.remove('hidden');
        if (removeImageBtn) removeImageBtn.classList.add('hidden');
      });
    }

    // 🔥 上一个/下一个产品切换
    function navigateProduct(direction) {
      const currentProductId = document.getElementById('edit-product-id').value;
      const allRows = Array.from(document.querySelectorAll('#products-table tbody tr[data-product-id]'));
      if (allRows.length === 0) return;

      const currentIndex = allRows.findIndex(row => row.getAttribute('data-product-id') === currentProductId);
      const newIndex = (currentIndex + direction + allRows.length) % allRows.length;
      const targetRow = allRows[newIndex];

      allRows.forEach(r => r.classList.remove('selected'));
      targetRow.classList.add('selected');
      loadProductForEdit(targetRow.getAttribute('data-product-id'));
    }

    const prevProductBtn = document.getElementById('prev-product-btn');
    if (prevProductBtn) {
      prevProductBtn.addEventListener('click', () => navigateProduct(-1));
    }

    const nextProductBtn = document.getElementById('next-product-btn');
    if (nextProductBtn) {
      nextProductBtn.addEventListener('click', () => navigateProduct(1));
    }

    // 🔥 保存成功/失败提示（替代浏览器弹窗）
    function showEditProductToast(message, type) {
      // 移除已有的 toast
      const existing = document.getElementById('edit-product-toast');
      if (existing) existing.remove();

      const toast = document.createElement('div');
      toast.id = 'edit-product-toast';
      const bgColor = type === 'success' ? 'bg-green-500' : 'bg-red-500';
      const icon = type === 'success' ? 'fa-check-circle' : 'fa-exclamation-circle';
      toast.className = `fixed top-6 left-1/2 -translate-x-1/2 ${bgColor} text-white px-6 py-3 rounded-lg shadow-lg z-[10001] flex items-center gap-2 text-sm transition-opacity duration-300`;
      toast.innerHTML = `<i class="fas ${icon}"></i><span>${message}</span>`;
      document.body.appendChild(toast);

      setTimeout(() => {
        toast.style.opacity = '0';
        setTimeout(() => toast.remove(), 300);
      }, 2000);
    }

    // Upload Product Image Button
    const uploadImageBtn = document.getElementById('edit-product-upload-btn');
    if (uploadImageBtn) {
      uploadImageBtn.addEventListener('click', function() {
        // Create file input dynamically
        const fileInput = document.createElement('input');
        fileInput.type = 'file';
        fileInput.accept = 'image/*';
        fileInput.style.display = 'none';
        document.body.appendChild(fileInput);

        fileInput.addEventListener('change', function() {
          if (this.files && this.files[0]) {
            const file = this.files[0];
            const formData = new FormData();
            formData.append('action', 'ruiyi_upload_product_image');
            formData.append('image', file);
            formData.append('nonce', '<?php echo esc_js($ajax_nonce); ?>');

            // Show uploading indicator
            uploadImageBtn.disabled = true;
            uploadImageBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> <?php echo ruiyi_translate("Subiendo...", "Uploading...", "上传中..."); ?>';

            fetch('<?php echo esc_url(admin_url('admin-ajax.php')); ?>', {
              method: 'POST',
              body: formData
            })
            .then(response => response.json())
            .then(data => {
              if (data.success) {
                // Update image preview
                const productImageImg = document.getElementById('edit-product-image-img');
                const productImagePlaceholder = document.getElementById('edit-product-image-placeholder');
                const productImageIdInput = document.getElementById('edit-product-image-id');
                const removeImageBtn = document.getElementById('edit-product-remove-image-btn');

                if (productImageImg) {
                  productImageImg.src = data.data.url;
                  productImageImg.classList.remove('hidden');
                }
                if (productImagePlaceholder) productImagePlaceholder.classList.add('hidden');
                if (productImageIdInput) productImageIdInput.value = data.data.id;
                if (removeImageBtn) removeImageBtn.classList.remove('hidden');
              } else {
                alert(data.data?.message || '<?php echo ruiyi_translate("Error al subir la imagen", "Error uploading image", "上传图片时出错"); ?>');
              }
            })
            .catch(error => {
              console.error('Error:', error);
              alert('<?php echo ruiyi_translate("Error al subir la imagen", "Error uploading image", "上传图片时出错"); ?>');
            })
            .finally(() => {
              uploadImageBtn.disabled = false;
              uploadImageBtn.innerHTML = '<i class="fas fa-upload"></i> <?php echo ruiyi_translate("Subir", "Upload", "上传"); ?>';
              document.body.removeChild(fileInput);
            });
          }
        });

        fileInput.click();
      });
    }

    // Remove Product Image Button
    const removeImageBtn = document.getElementById('edit-product-remove-image-btn');
    if (removeImageBtn) {
      removeImageBtn.addEventListener('click', function() {
        const productImageImg = document.getElementById('edit-product-image-img');
        const productImagePlaceholder = document.getElementById('edit-product-image-placeholder');
        const productImageIdInput = document.getElementById('edit-product-image-id');

        if (productImageImg) {
          productImageImg.src = '';
          productImageImg.classList.add('hidden');
        }
        if (productImagePlaceholder) productImagePlaceholder.classList.remove('hidden');
        if (productImageIdInput) productImageIdInput.value = '';
        this.classList.add('hidden');
      });
    }

    // Delete Product Button
    const deleteProductBtn = document.getElementById('delete-product-btn');
    if (deleteProductBtn) {
      deleteProductBtn.addEventListener('click', function() {
        const productId = document.getElementById('edit-product-id').value;
        const productName = document.getElementById('edit-product-name').value;

        if (!productId) {
          alert('<?php echo ruiyi_translate("No hay producto seleccionado", "No product selected", "未选择产品"); ?>');
          return;
        }

        if (!confirm('<?php echo ruiyi_translate("¿Estás seguro de que quieres eliminar este producto?", "Are you sure you want to delete this product?", "确定要删除此产品吗?"); ?>\n\n' + productName)) {
          return;
        }

        var ajaxUrl = '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
        const nonce = '<?php echo esc_js($ajax_nonce); ?>';

        fetch(ajaxUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            action: 'ruiyi_delete_product',
            product_id: productId,
            nonce: nonce
          })
        })
        .then(response => response.json())
        .then(data => {
          if (data.success) {
            alert('<?php echo ruiyi_translate("Producto eliminado exitosamente", "Product deleted successfully", "产品删除成功"); ?>');
            // Hide edit form and show product table
            const editFormContainer = document.getElementById('edit-product-form-container');
            const productsTableContainer = document.getElementById('products-table-container');
            if (editFormContainer) {
              editFormContainer.classList.add('hidden');
            }
            if (productsTableContainer) {
              productsTableContainer.classList.remove('hidden');
            }
            // Reload products for current category
            const selectedCategory = document.querySelector('.category-item.selected');
            if (selectedCategory) {
              const categoryId = selectedCategory.getAttribute('data-category-id');
              loadProductsByCategory(categoryId);
            }
          } else {
            alert(data.data?.message || '<?php echo ruiyi_translate("Error al eliminar el producto", "Error deleting product", "删除产品时出错"); ?>');
          }
        })
        .catch(error => {
          console.error('Error:', error);
          alert('<?php echo ruiyi_translate("Error al eliminar el producto", "Error deleting product", "删除产品时出错"); ?>');
        });
      });
    }

    // Add Product Form - Product Name Check
    let productNameExists = false;
    let productNameCheckTimeout = null;
    const productNameInput = document.getElementById('new-product-name');
    const productNameCheckStatus = document.getElementById('product-name-check-status');
    const productNameChecking = document.getElementById('product-name-checking');
    const productNameExistsEl = document.getElementById('product-name-exists');
    const productNameAvailable = document.getElementById('product-name-available');
    const addProductSubmitBtn = document.querySelector('#add-product-form button[type="submit"]');

    function hideAllProductNameStatus() {
      if (productNameChecking) productNameChecking.classList.add('hidden');
      if (productNameExistsEl) productNameExistsEl.classList.add('hidden');
      if (productNameAvailable) productNameAvailable.classList.add('hidden');
    }

    function checkProductNameExists(name) {
      if (!name || name.length < 1) {
        productNameCheckStatus.classList.add('hidden');
        hideAllProductNameStatus();
        productNameExists = false;
        if (addProductSubmitBtn) {
          addProductSubmitBtn.disabled = false;
          addProductSubmitBtn.classList.remove('opacity-50', 'cursor-not-allowed');
        }
        return;
      }

      // Show checking status
      productNameCheckStatus.classList.remove('hidden');
      hideAllProductNameStatus();
      productNameChecking.classList.remove('hidden');

      var ajaxUrl = '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
      const nonce = '<?php echo esc_js($ajax_nonce); ?>';

      fetch(ajaxUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          action: 'ruiyi_check_product_name_exists',
          product_name: name,
          nonce: nonce
        })
      })
      .then(response => response.json())
      .then(data => {
        hideAllProductNameStatus();
        if (data.success && data.data.exists) {
          productNameExists = true;
          productNameExistsEl.classList.remove('hidden');
          productNameInput.classList.add('border-red-500');
          productNameInput.classList.remove('border-gray-300', 'border-green-500');
          if (addProductSubmitBtn) {
            addProductSubmitBtn.disabled = true;
            addProductSubmitBtn.classList.add('opacity-50', 'cursor-not-allowed');
          }
        } else {
          productNameExists = false;
          productNameAvailable.classList.remove('hidden');
          productNameInput.classList.add('border-green-500');
          productNameInput.classList.remove('border-gray-300', 'border-red-500');
          if (addProductSubmitBtn) {
            addProductSubmitBtn.disabled = false;
            addProductSubmitBtn.classList.remove('opacity-50', 'cursor-not-allowed');
          }
        }
      })
      .catch(error => {
        console.error('Error checking product name:', error);
        hideAllProductNameStatus();
        productNameCheckStatus.classList.add('hidden');
        productNameExists = false;
        productNameInput.classList.remove('border-red-500', 'border-green-500');
        productNameInput.classList.add('border-gray-300');
      });
    }

    if (productNameInput) {
      productNameInput.addEventListener('input', function() {
        const name = this.value.trim();

        // Clear previous timeout (debounce)
        if (productNameCheckTimeout) {
          clearTimeout(productNameCheckTimeout);
        }

        // Reset styles immediately
        productNameInput.classList.remove('border-red-500', 'border-green-500');
        productNameInput.classList.add('border-gray-300');

        // Debounce: wait 500ms after user stops typing
        productNameCheckTimeout = setTimeout(() => {
          checkProductNameExists(name);
        }, 500);
      });

      // Also check on blur (when user leaves the field)
      productNameInput.addEventListener('blur', function() {
        const name = this.value.trim();
        if (name) {
          if (productNameCheckTimeout) {
            clearTimeout(productNameCheckTimeout);
          }
          checkProductNameExists(name);
        }
      });
    }

    // Add Product Form
    const addProductForm = document.getElementById('add-product-form');
    if (addProductForm) {
      addProductForm.addEventListener('submit', function(e) {
        e.preventDefault();

        const productName = document.getElementById('new-product-name').value.trim();
        const productPrice = document.getElementById('new-product-price').value;
        const productCategory = document.getElementById('new-product-category').value;

        // Check if product name already exists
        if (productNameExists) {
          alert('<?php echo ruiyi_translate("Ya existe un producto con este nombre. Por favor use otro nombre.", "A product with this name already exists. Please use a different name.", "已存在同名产品，请使用其他名称。"); ?>');
          return;
        }

        // 允许价格为0的产品（例如免费产品或赠品）
        if (!productName || productPrice === '' || productPrice === null || !productCategory) {
          alert('<?php echo ruiyi_translate("Por favor complete todos los campos", "Please fill in all fields", "请填写所有字段"); ?>');
          return;
        }

        var ajaxUrl = '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
        const nonce = '<?php echo esc_js($ajax_nonce); ?>';

        fetch(ajaxUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            action: 'ruiyi_create_product',
            product_name: productName,
            product_price: productPrice,
            product_category: productCategory,
            nonce: nonce
          })
        })
        .then(response => response.json())
        .then(data => {
          if (data.success) {
            alert('<?php echo ruiyi_translate("Producto creado exitosamente", "Product created successfully", "产品创建成功"); ?>');
            addProductForm.reset();
            // Reset product name check status
            productNameExists = false;
            if (productNameCheckStatus) productNameCheckStatus.classList.add('hidden');
            hideAllProductNameStatus();
            if (productNameInput) {
              productNameInput.classList.remove('border-red-500', 'border-green-500');
              productNameInput.classList.add('border-gray-300');
            }
            if (addProductSubmitBtn) {
              addProductSubmitBtn.disabled = false;
              addProductSubmitBtn.classList.remove('opacity-50', 'cursor-not-allowed');
            }
            // Refresh category dropdown
            location.reload();
          } else {
            alert(data.data?.message || '<?php echo ruiyi_translate("Error al crear el producto", "Error creating product", "创建产品时出错"); ?>');
          }
        })
        .catch(error => {
          console.error('Error:', error);
          alert('<?php echo ruiyi_translate("Error al crear el producto", "Error creating product", "创建产品时出错"); ?>');
        });
      });
    }

    // Add Category Form (支持多级分类)
    const addCategoryForm = document.getElementById('add-category-form');
    if (addCategoryForm) {
      // 父分类选择器变化时更新层级提示
      const parentSelect = document.getElementById('new-category-parent');
      const levelHint = document.getElementById('category-level-hint');
      if (parentSelect && levelHint) {
        parentSelect.addEventListener('change', function() {
          const selectedOption = this.options[this.selectedIndex];
          const parentDepth = parseInt(selectedOption.getAttribute('data-depth')) || 0;
          const newDepth = parentDepth + 1;
          const levelTexts = {
            1: '<?php echo ruiyi_translate("Creará una categoría de nivel 1", "Will create a level 1 category", "将创建一级分类"); ?>',
            2: '<?php echo ruiyi_translate("Creará una categoría de nivel 2 (máximo)", "Will create a level 2 category (maximum)", "将创建二级分类（最大层级）"); ?>'
          };
          levelHint.textContent = levelTexts[newDepth] || levelTexts[1];
          if (newDepth === 2) {
            levelHint.classList.add('text-orange-500');
            levelHint.classList.remove('text-gray-500');
          } else {
            levelHint.classList.remove('text-orange-500');
            levelHint.classList.add('text-gray-500');
          }
        });
      }

      addCategoryForm.addEventListener('submit', function(e) {
        e.preventDefault();

        const categoryName = document.getElementById('new-category-name').value.trim();
        const parentId = document.getElementById('new-category-parent')?.value || '0';
        const nameEn = document.getElementById('new-category-name-en')?.value.trim() || '';
        const nameZh = document.getElementById('new-category-name-zh')?.value.trim() || '';

        if (!categoryName) {
          alert('<?php echo ruiyi_translate("Por favor ingrese el nombre de la categoría", "Please enter category name", "请输入分类名称"); ?>');
          return;
        }

        var ajaxUrl = '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
        const nonce = '<?php echo esc_js($ajax_nonce); ?>';

        fetch(ajaxUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({
            action: 'ruiyi_create_product_category',
            category_name: categoryName,
            parent_id: parentId,
            name_es: categoryName,
            name_en: nameEn,
            name_zh: nameZh,
            nonce: nonce
          })
        })
        .then(response => response.json())
        .then(data => {
          if (data.success) {
            const depthText = data.data.depth === 1 ? '<?php echo ruiyi_translate("nivel 1", "level 1", "一级"); ?>' :
                             '<?php echo ruiyi_translate("nivel 2", "level 2", "二级"); ?>';
            alert('<?php echo ruiyi_translate("Categoría creada exitosamente", "Category created successfully", "分类创建成功"); ?> (' + depthText + ')');
            addCategoryForm.reset();
            // 重置层级提示
            if (levelHint) {
              levelHint.textContent = '<?php echo ruiyi_translate("Creará una categoría de nivel 1", "Will create a level 1 category", "将创建一级分类"); ?>';
              levelHint.classList.remove('text-orange-500');
              levelHint.classList.add('text-gray-500');
            }
            // Refresh page to show new category
            location.reload();
          } else {
            alert(data.data?.message || '<?php echo ruiyi_translate("Error al crear la categoría", "Error creating category", "创建分类时出错"); ?>');
          }
        })
        .catch(error => {
          console.error('Error:', error);
          alert('<?php echo ruiyi_translate("Error al crear la categoría", "Error creating category", "创建分类时出错"); ?>');
        });
      });
    }

    // ESC Key Listener - Close modal
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape' || e.keyCode === 27) {
        const modal = document.getElementById('product-management-modal');
        if (modal && !modal.classList.contains('hidden')) {
          modal.classList.add('hidden');
        }
      }
    });

    // Edit Category functionality
    const editCategoryList = document.getElementById('edit-category-list');
    const saveAllCategoriesBtn = document.getElementById('save-all-categories-btn');

    if (editCategoryList && saveAllCategoriesBtn) {
      // 检查是否有任何分类被修改
      function checkAnyChanges() {
        const categoryItems = editCategoryList.querySelectorAll('.category-edit-item');
        let hasAnyChanges = false;

        categoryItems.forEach(item => {
          const nameInput = item.querySelector('.category-name-input');
          const sortInput = item.querySelector('.category-sort-input');
          const colorInput = item.querySelector('.category-color-input'); // 🔥 颜色输入
          const imageInput = item.querySelector('.category-image-id-input');

          const originalName = nameInput.getAttribute('data-original-name');
          const newName = nameInput.value.trim();

          let itemModified = false;

          if (newName && newName !== originalName) {
            itemModified = true;
          }

          if (sortInput) {
            const originalSort = sortInput.getAttribute('data-original-sort');
            const newSort = sortInput.value.trim();
            if (newSort !== originalSort) {
              itemModified = true;
            }
          }

          // 🔥 检查颜色是否被修改
          if (colorInput) {
            const originalColor = colorInput.getAttribute('data-original-color') || '';
            const newColor = colorInput.value;
            const defaultColor = '<?php echo esc_js(get_option('pos_category_unselected_bg', '#E05C40')); ?>';
            // 如果原本没有自定义颜色，且新颜色与默认颜色不同，则认为修改了
            // 如果原本有自定义颜色，且新颜色与原颜色不同，则认为修改了
            if (originalColor === '' && newColor.toLowerCase() !== defaultColor.toLowerCase()) {
              itemModified = true;
            } else if (originalColor !== '' && newColor.toLowerCase() !== originalColor.toLowerCase()) {
              itemModified = true;
            }
          }

          if (imageInput) {
            const originalImageId = imageInput.getAttribute('data-original-image-id') || '';
            const newImageId = imageInput.value || '';
            if (newImageId !== originalImageId) {
              itemModified = true;
            }
          }

          if (itemModified) {
            hasAnyChanges = true;
            item.classList.add('ring-2', 'ring-blue-400');
          } else {
            item.classList.remove('ring-2', 'ring-blue-400');
          }
        });

        saveAllCategoriesBtn.disabled = !hasAnyChanges;
      }

      // 监听输入变化
      editCategoryList.addEventListener('input', function(e) {
        if (e.target.classList.contains('category-name-input') || e.target.classList.contains('category-sort-input') || e.target.classList.contains('category-color-input')) {
          checkAnyChanges();
        }
      });

      // 🔥 监听颜色选择器变化
      editCategoryList.addEventListener('change', function(e) {
        if (e.target.classList.contains('category-color-input')) {
          checkAnyChanges();
          // 显示重置按钮
          const resetBtn = e.target.parentElement.querySelector('.reset-color-btn');
          if (resetBtn) {
            resetBtn.style.visibility = 'visible';
          }
        }
      });

      // 🔥 重置颜色按钮点击事件
      editCategoryList.addEventListener('click', function(e) {
        if (e.target.closest('.reset-color-btn')) {
          const btn = e.target.closest('.reset-color-btn');
          const colorInput = btn.parentElement.querySelector('.category-color-input');
          if (colorInput) {
            const defaultColor = '<?php echo esc_js(get_option('pos_category_unselected_bg', '#E05C40')); ?>';
            colorInput.value = defaultColor;
            colorInput.setAttribute('data-original-color', ''); // 标记为使用默认颜色
            btn.style.visibility = 'hidden';
            checkAnyChanges();
          }
        }
      });

      function updateCategoryImagePreview(editor, imageId, imageUrl) {
        if (!editor) return;
        const input = editor.querySelector('.category-image-id-input');
        const preview = editor.querySelector('.category-image-preview');
        const removeBtn = editor.querySelector('.category-image-remove-btn');

        if (input) {
          input.value = imageId || '';
        }

        if (preview) {
          if (imageUrl) {
            preview.innerHTML = `<img src="${imageUrl}" alt="" class="w-full h-full object-cover">`;
          } else {
            preview.innerHTML = '<i class="fas fa-image text-gray-300"></i>';
          }
        }

        if (removeBtn) {
          removeBtn.classList.toggle('hidden', !imageUrl);
        }

        checkAnyChanges();
      }

      function uploadCategoryImage(editor, uploadBtn) {
        const fileInput = document.createElement('input');
        fileInput.type = 'file';
        fileInput.accept = 'image/*';
        fileInput.style.display = 'none';
        document.body.appendChild(fileInput);

        fileInput.addEventListener('change', function() {
          if (!this.files || !this.files[0]) {
            document.body.removeChild(fileInput);
            return;
          }

          const formData = new FormData();
          formData.append('action', 'ruiyi_upload_product_image');
          formData.append('image', this.files[0]);
          formData.append('nonce', '<?php echo esc_js($ajax_nonce); ?>');

          const originalHtml = uploadBtn.innerHTML;
          uploadBtn.disabled = true;
          uploadBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';

          fetch('<?php echo esc_url(admin_url('admin-ajax.php')); ?>', {
            method: 'POST',
            body: formData
          })
          .then(response => response.json())
          .then(data => {
            if (data.success) {
              updateCategoryImagePreview(editor, data.data.id, data.data.url);
            } else {
              alert(data.data?.message || '<?php echo ruiyi_translate("Error al subir la imagen", "Error uploading image", "上传图片时出错"); ?>');
            }
          })
          .catch(error => {
            console.error('Error uploading category image:', error);
            alert('<?php echo ruiyi_translate("Error al subir la imagen", "Error uploading image", "上传图片时出错"); ?>');
          })
          .finally(() => {
            uploadBtn.disabled = false;
            uploadBtn.innerHTML = originalHtml;
            document.body.removeChild(fileInput);
          });
        });

        fileInput.click();
      }

      editCategoryList.addEventListener('click', function(e) {
        const uploadBtn = e.target.closest('.category-image-upload-btn');
        if (uploadBtn) {
          const editor = uploadBtn.closest('.category-image-editor');
          uploadCategoryImage(editor, uploadBtn);
          return;
        }

        const removeBtn = e.target.closest('.category-image-remove-btn');
        if (removeBtn) {
          const editor = removeBtn.closest('.category-image-editor');
          updateCategoryImagePreview(editor, '', '');
        }
      });

      let draggedCategoryItem = null;

      function getCategoryBlock(item) {
        const block = [];
        if (!item) return block;

        const baseDepth = parseInt(item.getAttribute('data-depth') || '1', 10);
        let current = item;

        while (current && current.classList && current.classList.contains('category-edit-item')) {
          const currentDepth = parseInt(current.getAttribute('data-depth') || '1', 10);
          if (current !== item && currentDepth <= baseDepth) {
            break;
          }
          block.push(current);
          current = current.nextElementSibling;
        }

        return block;
      }

      function clearCategoryDropMarkers() {
        editCategoryList.querySelectorAll('.category-drop-before, .category-drop-after, .category-drop-target').forEach(item => {
          item.classList.remove('category-drop-before', 'category-drop-after', 'category-drop-target');
        });
      }

      function normalizeTopLevelCategorySortInputs() {
        const topLevelItems = editCategoryList.querySelectorAll('.category-edit-item[data-depth="1"]');
        topLevelItems.forEach((item, index) => {
          const sortInput = item.querySelector('.category-sort-input');
          if (sortInput) {
            sortInput.value = String(index + 1);
            item.setAttribute('data-sort-order', String(index + 1));
            item.classList.add('category-drag-saved-pending');
          }
        });
        checkAnyChanges();
      }

      editCategoryList.addEventListener('dragstart', function(e) {
        const handle = e.target.closest('.category-drag-handle');
        const item = handle ? handle.closest('.category-edit-item[data-depth="1"]') : null;

        if (!handle || !item) {
          e.preventDefault();
          return;
        }

        draggedCategoryItem = item;
        editCategoryList.classList.add('category-drag-active');
        getCategoryBlock(item).forEach(blockItem => blockItem.classList.add('category-dragging'));

        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('text/plain', item.getAttribute('data-category-id'));
      });

      editCategoryList.addEventListener('dragover', function(e) {
        if (!draggedCategoryItem) return;

        const target = e.target.closest('.category-edit-item[data-depth="1"]');
        if (!target || target === draggedCategoryItem) return;

        e.preventDefault();
        clearCategoryDropMarkers();

        const rect = target.getBoundingClientRect();
        const insertAfter = e.clientY > rect.top + rect.height / 2;
        target.classList.add('category-drop-target', insertAfter ? 'category-drop-after' : 'category-drop-before');
      });

      editCategoryList.addEventListener('drop', function(e) {
        if (!draggedCategoryItem) return;

        const target = e.target.closest('.category-edit-item[data-depth="1"]');
        if (!target || target === draggedCategoryItem) return;

        e.preventDefault();

        const targetRect = target.getBoundingClientRect();
        const insertAfter = e.clientY > targetRect.top + targetRect.height / 2;
        const draggedBlock = getCategoryBlock(draggedCategoryItem);
        const targetBlock = getCategoryBlock(target);

        if (targetBlock.includes(draggedCategoryItem)) {
          return;
        }

        const fragment = document.createDocumentFragment();
        draggedBlock.forEach(blockItem => fragment.appendChild(blockItem));

        if (insertAfter) {
          const afterTargetBlock = targetBlock[targetBlock.length - 1].nextElementSibling;
          editCategoryList.insertBefore(fragment, afterTargetBlock);
        } else {
          editCategoryList.insertBefore(fragment, target);
        }

        normalizeTopLevelCategorySortInputs();
      });

      editCategoryList.addEventListener('dragend', function() {
        if (draggedCategoryItem) {
          getCategoryBlock(draggedCategoryItem).forEach(blockItem => blockItem.classList.remove('category-dragging'));
        }
        draggedCategoryItem = null;
        editCategoryList.classList.remove('category-drag-active');
        clearCategoryDropMarkers();
      });

      // 统一保存所有修改的分类
      saveAllCategoriesBtn.addEventListener('click', async function() {
        const categoryItems = editCategoryList.querySelectorAll('.category-edit-item');
        const modifiedCategories = [];
        const defaultColor = '<?php echo esc_js(get_option('pos_category_unselected_bg', '#E05C40')); ?>';

        // 收集所有被修改的分类
        categoryItems.forEach(item => {
          const nameInput = item.querySelector('.category-name-input');
          const sortInput = item.querySelector('.category-sort-input');
          const colorInput = item.querySelector('.category-color-input'); // 🔥 颜色输入
          const imageInput = item.querySelector('.category-image-id-input');

          const originalName = nameInput.getAttribute('data-original-name');
          const newName = nameInput.value.trim();

          let isModified = newName && newName !== originalName;
          let newSort = null;
          let newColor = null;
          let colorModified = false;
          let newImageId = null;
          let imageModified = false;

          if (sortInput) {
            const originalSort = sortInput.getAttribute('data-original-sort');
            newSort = sortInput.value.trim();
            if (newSort !== originalSort) {
              isModified = true;
            }
          }

          // 🔥 检查颜色是否修改
          if (colorInput) {
            const originalColor = colorInput.getAttribute('data-original-color') || '';
            const currentColor = colorInput.value;
            // 如果颜色与默认颜色相同，保存为空（使用默认）
            if (currentColor.toLowerCase() === defaultColor.toLowerCase()) {
              newColor = ''; // 使用默认颜色
            } else {
              newColor = currentColor;
            }
            // 检查是否修改
            if (originalColor === '' && newColor !== '') {
              colorModified = true;
            } else if (originalColor !== '' && newColor.toLowerCase() !== originalColor.toLowerCase()) {
              colorModified = true;
            } else if (originalColor !== '' && newColor === '') {
              colorModified = true; // 从自定义改为默认
            }
          }

          if (imageInput) {
            const originalImageId = imageInput.getAttribute('data-original-image-id') || '';
            newImageId = imageInput.value || '';
            if (newImageId !== originalImageId) {
              imageModified = true;
            }
          }

          if (isModified || colorModified || imageModified) {
            modifiedCategories.push({
              term_id: item.getAttribute('data-category-id'),
              category_name: newName,
              sort_order: newSort,
              bg_color: newColor, // 🔥 添加颜色
              image_id: newImageId
            });
          }
        });

        if (modifiedCategories.length === 0) {
          return;
        }

        // 验证所有分类名称不为空
        for (const cat of modifiedCategories) {
          if (!cat.category_name) {
            alert('<?php echo ruiyi_translate("El nombre de la categoría no puede estar vacío", "Category name cannot be empty", "分类名称不能为空"); ?>');
            return;
          }
        }

        saveAllCategoriesBtn.disabled = true;
        saveAllCategoriesBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> <?php echo ruiyi_translate("Guardando...", "Saving...", "保存中..."); ?>';

        var ajaxUrl = '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
        const nonce = '<?php echo esc_js($ajax_nonce); ?>';

        let successCount = 0;
        let errorCount = 0;

        // 依次保存每个修改的分类
        for (const cat of modifiedCategories) {
          try {
            const params = {
              action: 'ruiyi_update_product_category',
              term_id: cat.term_id,
              category_name: cat.category_name,
              nonce: nonce
            };

            if (cat.sort_order !== null) {
              params.sort_order = cat.sort_order;
            }

            // 🔥 添加颜色参数
            if (cat.bg_color !== null && cat.bg_color !== undefined) {
              params.bg_color = cat.bg_color;
            }

            if (cat.image_id !== null && cat.image_id !== undefined) {
              params.image_id = cat.image_id;
            }

            const response = await fetch(ajaxUrl, {
              method: 'POST',
              headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
              body: new URLSearchParams(params)
            });

            const data = await response.json();

            if (data.success) {
              successCount++;
            } else {
              errorCount++;
              console.error('Error updating category:', cat.term_id, data);
            }
          } catch (error) {
            errorCount++;
            console.error('Error:', error);
          }
        }

        if (errorCount === 0) {
          alert('<?php echo ruiyi_translate("Todas las categorías han sido actualizadas exitosamente", "All categories have been updated successfully", "所有分类已成功更新"); ?>');
          location.reload();
        } else {
          alert(`<?php echo ruiyi_translate("Actualización completada", "Update completed", "更新完成"); ?>: ${successCount} <?php echo ruiyi_translate("éxitos", "successes", "成功"); ?>, ${errorCount} <?php echo ruiyi_translate("errores", "errors", "失败"); ?>`);
          location.reload();
        }
      });

      // Delete category (支持多级分类)
      editCategoryList.addEventListener('click', function(e) {
        if (e.target.classList.contains('delete-category-btn')) {
          const btn = e.target;
          const categoryItem = btn.closest('.category-edit-item');
          const categoryId = categoryItem.getAttribute('data-category-id');
          const categoryName = categoryItem.querySelector('.category-name-input').value;
          const hasChildren = categoryItem.getAttribute('data-has-children') === '1';

          // 如果有子分类，询问删除方式
          let cascade = false;
          if (hasChildren) {
            const deleteOption = confirm(
              '<?php echo ruiyi_translate("Esta categoría tiene subcategorías.", "This category has subcategories.", "此分类有子分类。"); ?>\n\n' +
              '<?php echo ruiyi_translate("Haga clic en Aceptar para eliminar todas las subcategorías también.", "Click OK to delete all subcategories as well.", "点击确定将同时删除所有子分类。"); ?>\n' +
              '<?php echo ruiyi_translate("Haga clic en Cancelar para mover las subcategorías al nivel superior.", "Click Cancel to move subcategories to parent level.", "点击取消将把子分类移至上一级。"); ?>'
            );
            cascade = deleteOption;
          }

          const confirmMessage = hasChildren
            ? (cascade
              ? '<?php echo ruiyi_translate("¿Confirma eliminar esta categoría y TODAS sus subcategorías?", "Confirm delete this category and ALL subcategories?", "确认删除此分类及其所有子分类？"); ?>'
              : '<?php echo ruiyi_translate("¿Confirma eliminar esta categoría? Las subcategorías se moverán al nivel superior.", "Confirm delete this category? Subcategories will be moved to parent level.", "确认删除此分类？子分类将移至上一级。"); ?>')
            : '<?php echo ruiyi_translate("¿Está seguro de que desea eliminar la categoría", "Are you sure you want to delete the category", "确定要删除分类"); ?> "' + categoryName + '"?';

          if (!confirm(confirmMessage)) {
            return;
          }

          btn.disabled = true;
          btn.textContent = '<?php echo ruiyi_translate("Eliminando...", "Deleting...", "删除中..."); ?>';

          var ajaxUrl = '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
          const nonce = '<?php echo esc_js($ajax_nonce); ?>';

          fetch(ajaxUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams({
              action: 'ruiyi_delete_product_category',
              term_id: categoryId,
              cascade: cascade ? 'true' : 'false',
              nonce: nonce
            })
          })
          .then(response => response.json())
          .then(data => {
            if (data.success) {
              alert('<?php echo ruiyi_translate("Categoría eliminada exitosamente", "Category deleted successfully", "分类删除成功"); ?>');
              // Refresh page to update category lists
              location.reload();
            } else {
              alert(data.data?.message || '<?php echo ruiyi_translate("Error al eliminar la categoría", "Error deleting category", "删除分类时出错"); ?>');
              btn.disabled = false;
              btn.textContent = '<?php echo ruiyi_translate("Eliminar", "Delete", "删除"); ?>';
            }
          })
          .catch(error => {
            console.error('Error:', error);
            alert('<?php echo ruiyi_translate("Error al eliminar la categoría", "Error deleting category", "删除分类时出错"); ?>');
            btn.disabled = false;
            btn.textContent = '<?php echo ruiyi_translate("Eliminar", "Delete", "删除"); ?>';
          });
        }
      });
    }
  });
</script>

