</div>

<!-- 🔥 产品备注功能脚本（新版：每个产品单独备注） -->
<script>
(function() {
  'use strict';

  const cashierQuickNoteTemplates = <?php echo wp_json_encode(json_decode(get_option('pos_quick_note_templates', '[]'), true) ?: array()); ?>;

  function normalizeCashierIdList(raw) {
    if (typeof raw === 'string') {
      raw = raw.split(/[,\s]+/);
    } else if (!Array.isArray(raw)) {
      raw = [raw];
    }
    return raw.map(function(id) {
      if (id && typeof id === 'object') {
        id = id.term_id || id.id || id.category_id || 0;
      }
      return parseInt(id, 10);
    }).filter(function(id) { return id > 0; });
  }

  function normalizeCashierQuickNote(template) {
    if (template && typeof template === 'object') {
      return {
        text: String(template.text || '').trim(),
        categories: normalizeCashierIdList(template.categories || [])
      };
    }
    return {
      text: String(template || '').trim(),
      categories: []
    };
  }

  function getCashierQuickNotesForItem(item) {
    const itemCats = normalizeCashierIdList(item.categoryIds || item.category_ids || item.categories || item.category_id || []);
    return (cashierQuickNoteTemplates || [])
      .map(normalizeCashierQuickNote)
      .filter(function(note) {
        if (!note.text) return false;
        if (note.categories.length === 0) return true;
        if (itemCats.length === 0) return false;
        return note.categories.some(function(catId) { return itemCats.indexOf(catId) >= 0; });
      });
  }

  function escapeCashierQuickNote(text) {
    return String(text || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  function appendCashierQuickNote(note) {
    const input = document.getElementById('single-item-note-input');
    if (!input) return;
    const current = input.value.trim();
    input.value = current ? current + ', ' + note : note;
    input.focus();
  }

  window.appendCashierQuickNote = appendCashierQuickNote;

  // 显示产品备注 Modal（显示新商品列表）
  window.showOrderNotesModal = function() {
    const modal = document.getElementById('order-notes-modal');
    if (!modal) return;

    // 显示列表视图，隐藏编辑视图
    document.getElementById('product-notes-list-view').classList.remove('hidden');
    document.getElementById('single-item-note-view').classList.add('hidden');
    document.getElementById('order-notes-modal-title').textContent = '<?php echo ruiyi_translate("Notas de Productos", "Product Notes", "产品备注"); ?>';

    // 渲染新商品列表
    renderNewItemsList();

    modal.classList.remove('hidden');
  };

  // 渲染新商品列表（包括新添加的商品和已锁定商品的新增数量部分）
  function renderNewItemsList() {
    const listContainer = document.getElementById('new-items-notes-list');
    const noItemsMessage = document.getElementById('no-new-items-message');

    if (!listContainer || typeof cart === 'undefined') return;

    // 🔥 获取所有会打印到厨房的商品：
    // 1. 未锁定的商品（新添加的）
    // 2. 已锁定商品中有新增数量的部分（addedQuantity > 0）
    const kitchenItems = [];

    cart.forEach((item, cartIndex) => {
      if (!item.locked && item.quantity > 0) {
        // 未锁定的新商品
        kitchenItems.push({
          ...item,
          cartIndex: cartIndex,
          displayQuantity: item.quantity,
          isLocked: false
        });
      } else if (item.locked && (item.addedQuantity || 0) > 0) {
        // 已锁定商品的新增数量部分
        kitchenItems.push({
          ...item,
          cartIndex: cartIndex,
          displayQuantity: item.addedQuantity,
          isLocked: true
        });
      }
    });

    if (kitchenItems.length === 0) {
      listContainer.innerHTML = '';
      noItemsMessage?.classList.remove('hidden');
      updateNotesCount();
      return;
    }

    noItemsMessage?.classList.add('hidden');

    // 渲染商品列表
    listContainer.innerHTML = kitchenItems.map((item) => {
      const hasNotes = item.notes && item.notes.trim();
      const notePreview = hasNotes ? item.notes.substring(0, 30) + (item.notes.length > 30 ? '...' : '') : '';
      const lockIcon = item.isLocked ? '<i class="fas fa-lock text-blue-500 text-xs mr-1"></i>' : '';
      const bgColor = item.isLocked
        ? (hasNotes ? 'border-orange-300 bg-orange-50' : 'border-blue-200 bg-blue-50')
        : (hasNotes ? 'border-orange-300 bg-orange-50' : 'border-gray-200');

      return `
        <div class="flex items-center justify-between p-3 rounded-lg border ${bgColor}">
          <div class="flex-1 min-w-0 mr-3">
            <div class="flex items-center gap-2">
              ${lockIcon}
              <span class="font-medium text-gray-800 truncate">${item.name}</span>
              <span class="text-sm ${item.isLocked ? 'text-blue-600 font-semibold' : 'text-gray-500'}">x${item.displayQuantity}${item.isLocked ? ' <?php echo ruiyi_translate("(nuevo)", "(new)", "(新增)"); ?>' : ''}</span>
            </div>
            ${hasNotes ? `<p class="text-xs text-orange-600 mt-1 truncate"><i class="fas fa-comment-alt mr-1"></i>${notePreview}</p>` : ''}
          </div>
          <button onclick="openItemNoteEditor(${item.cartIndex})"
                  class="flex-shrink-0 px-3 py-2 rounded-lg transition-colors ${hasNotes ? 'bg-orange-500 text-white hover:bg-orange-600' : 'bg-gray-200 text-gray-600 hover:bg-gray-300'}">
            <i class="${hasNotes ? 'fas' : 'far'} fa-comment-alt mr-1"></i>
            ${hasNotes ? '<?php echo ruiyi_translate("Editar", "Edit", "编辑"); ?>' : '<?php echo ruiyi_translate("Añadir", "Add", "添加"); ?>'}
          </button>
        </div>
      `;
    }).join('');

    updateNotesCount();
  }

  // 打开单个商品备注编辑器
  window.openItemNoteEditor = function(cartIndex) {
    const item = cart[cartIndex];
    if (!item) return;

    // 切换到编辑视图
    document.getElementById('product-notes-list-view').classList.add('hidden');
    document.getElementById('single-item-note-view').classList.remove('hidden');
    document.getElementById('order-notes-modal-title').textContent = '<?php echo ruiyi_translate("Editar Nota", "Edit Note", "编辑备注"); ?>';

    // 🔥 显示正确的数量：锁定商品显示新增数量，未锁定商品显示总数量
    const displayQuantity = item.locked ? (item.addedQuantity || 0) : item.quantity;
    const quantityLabel = item.locked ? ` x${displayQuantity} <?php echo ruiyi_translate("(nuevo)", "(new)", "(新增)"); ?>` : ` x${displayQuantity}`;

    // 填充数据
    document.getElementById('editing-item-name').textContent = item.name + quantityLabel;
    document.getElementById('single-item-note-input').value = item.notes || '';
    document.getElementById('editing-item-index').value = cartIndex;

    const quickWrap = document.getElementById('cashier-note-quick-buttons');
    const quickList = document.getElementById('cashier-note-quick-buttons-list');
    const quickNotes = getCashierQuickNotesForItem(item);
    if (quickWrap && quickList && quickNotes.length > 0) {
      quickList.innerHTML = quickNotes.map(function(note) {
        return '<button type="button" onclick="appendCashierQuickNote(this.textContent.trim())" ' +
          'class="px-3 py-1 rounded-full border border-orange-200 bg-orange-50 text-orange-700 text-xs font-medium hover:bg-orange-100 transition-colors">' +
          escapeCashierQuickNote(note.text) +
          '</button>';
      }).join('');
      quickWrap.classList.remove('hidden');
    } else if (quickWrap && quickList) {
      quickList.innerHTML = '';
      quickWrap.classList.add('hidden');
    }

    // 聚焦输入框
    document.getElementById('single-item-note-input').focus();
  };

  // 返回商品列表
  window.backToProductList = function() {
    document.getElementById('product-notes-list-view').classList.remove('hidden');
    document.getElementById('single-item-note-view').classList.add('hidden');
    document.getElementById('order-notes-modal-title').textContent = '<?php echo ruiyi_translate("Notas de Productos", "Product Notes", "产品备注"); ?>';
  };

  // 保存单个商品备注
  window.saveSingleItemNote = function() {
    const cartIndex = parseInt(document.getElementById('editing-item-index').value);
    const notes = document.getElementById('single-item-note-input').value.trim();

    if (cart[cartIndex]) {
      cart[cartIndex].notes = notes;

      // 🔥 如果是锁定商品，标记购物车已修改
      if (cart[cartIndex].locked) {
        window.cartModified = true;
      }

      // 同步到桌位状态
      if (typeof syncCartToMesasEstado === 'function') {
        syncCartToMesasEstado();
      }

      // 更新购物车显示
      if (typeof renderCart === 'function') {
        renderCart();
      }

      // 显示提示
      Toastify({
        text: notes ? '<?php echo ruiyi_translate("Nota guardada", "Note saved", "备注已保存"); ?>' : '<?php echo ruiyi_translate("Nota eliminada", "Note removed", "备注已删除"); ?>',
        duration: 1500,
        gravity: "bottom",
        position: "center",
        style: { background: "#f97316" }
      }).showToast();
    }

    // 返回列表视图
    backToProductList();
    renderNewItemsList();
  };

  // 清空单个商品备注输入
  window.clearSingleItemNote = function() {
    document.getElementById('single-item-note-input').value = '';
  };

  // 关闭订单备注 Modal
  window.closeOrderNotesModal = function() {
    const modal = document.getElementById('order-notes-modal');
    if (modal) {
      modal.classList.add('hidden');
    }
  };

  // 🔥 辅助函数：获取所有会打印到厨房的商品（新商品 + 锁定商品新增部分）
  function getKitchenItems() {
    if (typeof cart === 'undefined') return [];

    const items = [];
    cart.forEach((item, cartIndex) => {
      if (!item.locked && item.quantity > 0) {
        // 未锁定的新商品
        items.push({ ...item, cartIndex, displayQuantity: item.quantity, isLocked: false });
      } else if (item.locked && (item.addedQuantity || 0) > 0) {
        // 已锁定商品的新增数量部分
        items.push({ ...item, cartIndex, displayQuantity: item.addedQuantity, isLocked: true });
      }
    });
    return items;
  }

  // 保存并关闭（同步所有备注）
  window.closeAndSaveAllNotes = function() {
    // 同步到桌位状态
    if (typeof syncCartToMesasEstado === 'function') {
      syncCartToMesasEstado();
    }

    // 更新购物车显示
    if (typeof renderCart === 'function') {
      renderCart();
    }

    closeOrderNotesModal();

    // 统计有备注的商品数量（包括新商品和锁定商品的新增部分）
    const kitchenItems = getKitchenItems();
    const itemsWithNotes = kitchenItems.filter(item => item.notes && item.notes.trim()).length;

    Toastify({
      text: `<?php echo ruiyi_translate("Guardado", "Saved", "已保存"); ?> - ${itemsWithNotes} <?php echo ruiyi_translate("productos con notas", "products with notes", "个商品有备注"); ?>`,
      duration: 2000,
      gravity: "bottom",
      position: "center",
      style: { background: "#22c55e" }
    }).showToast();
  };

  // 更新备注数量显示
  function updateNotesCount() {
    const countElem = document.getElementById('items-with-notes-count');
    if (!countElem) return;

    const kitchenItems = getKitchenItems();
    const itemsWithNotes = kitchenItems.filter(item => item.notes && item.notes.trim()).length;
    countElem.textContent = itemsWithNotes;
  }

  // 更新备注按钮样式（有备注时高亮显示）
  window.updateOrderNotesButton = function() {
    const btn = document.getElementById('order-notes-btn');
    if (!btn) return;

    const kitchenItems = getKitchenItems();
    const itemsWithNotes = kitchenItems.filter(item => item.notes && item.notes.trim()).length;

    if (itemsWithNotes > 0) {
      btn.classList.remove('text-gray-400');
      btn.classList.add('text-orange-500', 'bg-orange-50');
      btn.title = `${itemsWithNotes} <?php echo ruiyi_translate("productos con notas", "products with notes", "个商品有备注"); ?>`;
    } else {
      btn.classList.add('text-gray-400');
      btn.classList.remove('text-orange-500', 'bg-orange-50');
      btn.title = '<?php echo ruiyi_translate("Notas de productos", "Product notes", "产品备注"); ?>';
    }
  };

  // 获取所有产品备注（供打印等模块使用）- 兼容旧接口
  window.getOrderNotes = function() {
    const kitchenItems = getKitchenItems();
    const notesArray = kitchenItems
      .filter(item => item.notes && item.notes.trim())
      .map(item => `${item.name}: ${item.notes}`);

    return notesArray.join('; ');
  };

  // 清除所有产品备注（结账后调用）
  window.clearOrderNotesAfterCheckout = function() {
    if (typeof cart !== 'undefined') {
      cart.forEach(item => {
        // 清除所有会打印到厨房的商品的备注
        if (!item.locked || (item.addedQuantity || 0) > 0) {
          item.notes = '';
        }
      });
    }
    updateOrderNotesButton();
  };

  // 监听桌位切换，更新按钮状态
  window.addEventListener('tableChanged', function() {
    setTimeout(updateOrderNotesButton, 100);
  });

  // 页面加载时初始化
  document.addEventListener('DOMContentLoaded', function() {
    setTimeout(updateOrderNotesButton, 500);
  });

  // 点击模态框外部关闭
  document.getElementById('order-notes-modal')?.addEventListener('click', function(e) {
    if (e.target === this) {
      closeOrderNotesModal();
    }
  });

  // ESC键关闭
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
      const modal = document.getElementById('order-notes-modal');
      if (modal && !modal.classList.contains('hidden')) {
        // 如果在编辑视图，先返回列表
        if (!document.getElementById('single-item-note-view').classList.contains('hidden')) {
          backToProductList();
        } else {
          closeOrderNotesModal();
        }
      }
    }
  });
})();
</script>

<!-- 产品搜索功能初始化脚本 -->
<script>
(function() {
  // 全局搜索变量
  window.productSearchTerm = '';

  function normalizeProductSearchValue(value) {
    return (value || '')
      .toString()
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .trim();
  }

  function matchesProductSearchFuzzy(searchTerm, values) {
    const normalizedSearch = normalizeProductSearchValue(searchTerm);
    if (!normalizedSearch) {
      return true;
    }

    return values.some(value => {
      const normalizedValue = normalizeProductSearchValue(value);
      return normalizedValue.includes(normalizedSearch);
    });
  }

  // 显示所有产品（价格>0的，且尊重当前分类过滤）
  function showAllProducts() {
    const productCards = document.querySelectorAll('.product-card');
    productCards.forEach(card => {
      const productPrice = parseFloat(card.getAttribute('data-price') || '0');

      // 🔥 价格为0的产品：自助餐和免费产品允许显示
      if (productPrice <= 0 && card.getAttribute('data-is-buffet') !== '1' && card.getAttribute('data-is-free') !== '1') {
        card.classList.add('product-hidden');
        card.style.setProperty('display', 'none', 'important');
        card.style.setProperty('visibility', 'hidden', 'important');
        return;
      }

      // 🔥 检查分类过滤 - 使用全局 window.activeCategoryIds
      // 🔥 修复：当activeCategoryIds为空时，使用配置中的首个分类ID作为后备
      let effectiveActiveCategoryIds = window.activeCategoryIds;
      if (!effectiveActiveCategoryIds || effectiveActiveCategoryIds.length === 0) {
        if (window.RUIYI_POS_CONFIG && window.RUIYI_POS_CONFIG.firstCategoryAllIds && window.RUIYI_POS_CONFIG.firstCategoryAllIds.length > 0) {
          effectiveActiveCategoryIds = window.RUIYI_POS_CONFIG.firstCategoryAllIds;
        }
      }

      if (effectiveActiveCategoryIds && effectiveActiveCategoryIds.length > 0) {
        const categoriesStr = card.getAttribute('data-categories') || '';
        const productCategories = categoriesStr.split(' ').filter(id => id).map(id => parseInt(id.trim()));
        const categoryMatch = productCategories.some(catId => effectiveActiveCategoryIds.includes(catId));

        if (!categoryMatch) {
          card.classList.add('product-hidden');
          card.style.setProperty('display', 'none', 'important');
          card.style.setProperty('visibility', 'hidden', 'important');
          return;
        }
      } else {
        // 如果无法确定分类，保持产品当前状态
        const isCurrentlyHidden = card.classList.contains('product-hidden');
        if (isCurrentlyHidden) {
          return; // 保持隐藏
        }
      }

      card.classList.remove('product-hidden');
      // 移除隐藏样式
      card.style.cssText = card.style.cssText.replace(/display:\s*none\s*!important;?/gi, '').replace(/visibility:\s*hidden\s*!important;?/gi, '');
    });
  }

  // 产品搜索过滤函数（搜索时忽略分类过滤，搜索所有分类）
  function searchFilterProducts() {
    const productCards = document.querySelectorAll('.product-card');
    const searchTerm = window.productSearchTerm.toLowerCase().trim();

    if (!searchTerm) {
      // 如果搜索词为空，显示当前分类的所有产品
      showAllProducts();
      return;
    }

    // 🔥 有搜索词时，搜索所有分类的产品（忽略分类过滤）
    let visibleCount = 0;
    productCards.forEach(card => {
      const productName = (card.getAttribute('data-name') || '').toLowerCase();
      const productNameEs = (card.getAttribute('data-name-es') || '').toLowerCase();
      const productNameZh = (card.getAttribute('data-name-zh') || '').toLowerCase();
      const productNameEn = (card.getAttribute('data-name-en') || '').toLowerCase();
      const productPrice = parseFloat(card.getAttribute('data-price') || '0');

      // 🔥 价格为0的产品：自助餐和免费产品允许显示
      if (productPrice <= 0 && card.getAttribute('data-is-buffet') !== '1' && card.getAttribute('data-is-free') !== '1') {
        card.classList.add('product-hidden');
        card.style.setProperty('display', 'none', 'important');
        card.style.setProperty('visibility', 'hidden', 'important');
        return;
      }

      // 检查是否匹配搜索词（支持多语言名称匹配）
      const matchesSearch = matchesProductSearchFuzzy(searchTerm, [
        productName,
        productNameEs,
        productNameZh,
        productNameEn,
        card.getAttribute('data-sku') || ''
      ]);

      // 🔥 搜索时只检查搜索词匹配，忽略分类过滤
      if (matchesSearch) {
        card.classList.remove('product-hidden');
        // 移除隐藏样式
        card.style.cssText = card.style.cssText.replace(/display:\s*none\s*!important;?/gi, '').replace(/visibility:\s*hidden\s*!important;?/gi, '');
        visibleCount++;
      } else {
        card.classList.add('product-hidden');
        card.style.setProperty('display', 'none', 'important');
        card.style.setProperty('visibility', 'hidden', 'important');
      }
    });

  }

  // DOM加载完成后初始化
  document.addEventListener('DOMContentLoaded', function() {
    const searchInput = document.getElementById('product-search-input');
    const clearBtn = document.getElementById('clear-product-search');

    if (searchInput) {
      // 输入事件 - 实时搜索
      searchInput.addEventListener('input', function() {
        window.productSearchTerm = this.value;
        searchFilterProducts();

        // 显示/隐藏清除按钮
        if (clearBtn) {
          clearBtn.classList.toggle('hidden', !this.value.trim());
        }
      });

      // 回车键
      searchInput.addEventListener('keydown', function(e) {
        if (e.key === 'Enter') {
          e.preventDefault();
        }
        if (e.key === 'Escape') {
          this.value = '';
          window.productSearchTerm = '';
          searchFilterProducts();
          if (clearBtn) clearBtn.classList.add('hidden');
        }
      });
    }

    // 清除按钮
    if (clearBtn) {
      clearBtn.addEventListener('click', function() {
        const input = document.getElementById('product-search-input');
        if (input) {
          input.value = '';
          window.productSearchTerm = '';
          searchFilterProducts();
        }
        this.classList.add('hidden');
      });
    }
  });
})();

// 🔥 桌位模块开钱箱按钮事件
document.addEventListener('DOMContentLoaded', function() {
  const mesasOpenDrawerBtn = document.getElementById('mesas-open-drawer-btn');
  if (mesasOpenDrawerBtn) {
    mesasOpenDrawerBtn.addEventListener('click', async function() {
      if (this.disabled) {
        Toastify({
          text: '🔒 <?php echo ruiyi_translate("El cajón está bloqueado", "Drawer is locked", "钱箱已被锁定"); ?>',
          duration: 2000,
          gravity: "top",
          position: "center",
          style: { background: "#f59e0b" }
        }).showToast();
        return;
      }
      try {
        const success = await abrirCajonDinero();
        if (success) {
          Toastify({
            text: '✅ <?php echo ruiyi_translate('Cajón abierto', 'Drawer opened', '钱箱已打开'); ?>',
            duration: 1500,
            gravity: "top",
            position: "center",
            style: { background: "#10b981" }
          }).showToast();
        }
      } catch (error) {
        // 🔥 使用用户友好的打印机配置提示
        showPrinterConfigDialog();
      }
    });
  }

  // F1 快捷键
  document.addEventListener('keydown', function(e) {
    if (e.key === 'F1') {
      e.preventDefault();
      const mesasSection = document.getElementById('mesas');
      if (mesasSection && !mesasSection.classList.contains('hidden')) {
        const btn = document.getElementById('mesas-open-drawer-btn');
        if (btn && !btn.disabled) {
          btn.click();
        }
      }
    }
  });
});

// 🔥 预览账单按钮事件监听器
document.addEventListener('DOMContentLoaded', function() {
  const printPreviewBtn = document.getElementById('print-preview-bill-btn');

  if (printPreviewBtn) {
    printPreviewBtn.addEventListener('click', async function() {
      const buttonTableNumber = this.dataset.tableNumber;
      const tableNumber = ruiyiResolveActivePrebillTableNumber(buttonTableNumber);

      if (!tableNumber) {
        Toastify({
          text: '<?php echo ruiyi_translate('No se ha seleccionado mesa', 'No table selected', '未选择桌位'); ?>',
          duration: 2000,
          gravity: "top",
          position: "center",
          style: { background: "#ff9800" }
        }).showToast();
        return;
      }

      // 🔥🔥🔥 关键修复：预结单前先保存所有变更（新商品 + 锁定商品数量修改）
      const hasUnlockedItems = cart && cart.some(item => !item.locked && item.quantity > 0);
      const hasLockedItems = cart && cart.some(item => item.locked && item.quantity > 0);

      if (hasUnlockedItems || hasLockedItems) {
        // 显示保存中提示
        Swal.fire({
          title: '<?php echo ruiyi_translate("Guardando cambios...", "Saving changes...", "保存变更中..."); ?>',
          allowOutsideClick: false,
          didOpen: () => { Swal.showLoading(); }
        });

        try {
          const saveSuccess = await ensureTableOrderSaved();
          Swal.close();

          if (!saveSuccess) {
            Swal.fire({
              icon: 'error',
              title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
              text: '<?php echo ruiyi_translate("Error al guardar cambios", "Failed to save changes", "保存变更失败"); ?>'
            });
            return;
          }
        } catch (error) {
          Swal.close();
          console.error('[预结单] 保存变更失败:', error);
          Swal.fire({
            icon: 'error',
            title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
            text: '<?php echo ruiyi_translate("Error al guardar cambios", "Failed to save changes", "保存变更失败"); ?>'
          });
          return;
        }
      }

      // 🔥🔥🔥 【2026-03-30 关键修复】保存后购物车可能为空，从 mesas_estado 恢复
      if (!cart || cart.length === 0 || !cart.some(item => item.quantity > 0)) {
        const _pvTableData = ruiyiFindPrebillMesaState(tableNumber)?.data;
        if (_pvTableData?.cart && _pvTableData.cart.length > 0) {
          console.log('[预结单-view] 🔄 购物车为空，从 mesas_estado 恢复:', _pvTableData.cart.length, '项');
          cart = _pvTableData.cart.filter(item => item.quantity > 0).map(item => ({
            ...item,
            locked: true,
            orderId: item.orderId || _pvTableData.orderId
          }));
          window.cart = cart;
          ruiyiSetCartTableIdentity(tableNumber, 'prebill-click:restore-view');
          if (typeof renderCart === 'function') renderCart();
        }
      }

      this.dataset.tableNumber = tableNumber;
      printPreviewBill(tableNumber);
    });
  }
});

// 🔥 打印预结单并锁定产品（用于桌位添加新订单时）
async function printProformaAndLockProducts() {
    // 获取桌位号
    const tableNumber = document.getElementById('table-number')?.value.trim();

    // 检查是否在桌位模式
    if (!tableNumber) {
        Swal.fire({
            icon: 'warning',
            title: '<?php echo ruiyi_translate("Sin mesa", "No table", "未选择桌位"); ?>',
            text: '<?php echo ruiyi_translate("Seleccione una mesa primero", "Select a table first", "请先选择一个桌位"); ?>',
            timer: 2000,
            showConfirmButton: false
        });
        return;
    }

    // 检查购物车是否有产品
    if (cart.length === 0) {
        Swal.fire({
            icon: 'warning',
            title: '<?php echo ruiyi_translate("Carrito vacío", "Empty cart", "购物车为空"); ?>',
            text: '<?php echo ruiyi_translate("Añada productos primero", "Add products first", "请先添加产品"); ?>',
            timer: 2000,
            showConfirmButton: false
        });
        return;
    }

    // 检查是否有未锁定的产品
    const hasUnlockedItems = cart.some(item => !item.locked);
    if (!hasUnlockedItems) {
        // 所有产品已锁定，直接打印预结单
        printPreviewBill(tableNumber);
        return;
    }

    // 显示处理中
    Swal.fire({
        title: '<?php echo ruiyi_translate("Procesando...", "Processing...", "处理中..."); ?>',
        html: '<?php echo ruiyi_translate("Guardando y generando proforma", "Saving and generating proforma", "保存并生成预结单"); ?>',
        allowOutsideClick: false,
        didOpen: () => { Swal.showLoading(); }
    });

    try {
        // 🔥 保存新商品的副本（因为autoSaveTableOrder会清除它们）
        const newItemsCopy = cart.filter(item => !item.locked && item.quantity > 0)
            .map(item => JSON.parse(JSON.stringify(item)));

        // 1. 调用自动保存函数（会保存到服务器、打印厨房小票、然后清除未锁定商品）
        // 🔥🔥🔥 【2026-01-27 关键修复】syncTableOrderToServer 内部已经将商品添加回购物车并标记为锁定
        // 不需要再手动添加 newItemsCopy，否则会导致购物车商品重复（双倍）
        // 🔥【2026-04-07】force=true 绕过 3 秒去抖（用户显式触发，必须立即保存）
        const saveSuccess = await autoSaveTableOrder({ force: true });
        // // console.log('[预结单] 保存结果:', saveSuccess);

        // 🔥🔥🔥 【2026-03-30 关键修复】保存后购物车可能为空，从 mesas_estado 恢复
        if (!cart || cart.length === 0 || !cart.some(item => item.quantity > 0)) {
            const _pfTableData = ruiyiFindPrebillMesaState(tableNumber)?.data;
            if (_pfTableData?.cart && _pfTableData.cart.length > 0) {
                console.log('[预结单] 🔄 购物车为空，从 mesas_estado 恢复:', _pfTableData.cart.length, '项');
                cart = _pfTableData.cart.filter(item => item.quantity > 0).map(item => ({
                    ...item,
                    locked: true,
                    orderId: item.orderId || _pfTableData.orderId
                }));
                window.cart = cart;
                ruiyiSetCartTableIdentity(tableNumber, 'printProformaAndLockProducts:restore');
            }
        }

        if (saveSuccess) {
            // 🔥🔥🔥 【2026-01-27 修复】不再手动添加商品，syncTableOrderToServer 已处理
            // 原问题：syncTableOrderToServer (line 9403-9427) 已将商品添加回cart，
            //         这里又 push newItemsCopy 导致商品重复

            // 3. 重新渲染购物车（显示锁定状态）
            renderCart();

            // 4. 关闭处理中提示
            Swal.close();

            // 5. 打印预结单
            printPreviewBill(tableNumber);

            // // console.log('[预结单] 预结单打印完成');
        } else {
            // 保存失败或没有新商品
            Swal.close();
            // 如果没有新商品但有锁定商品，也打印预结单
            if (cart.some(item => item.locked)) {
                printPreviewBill(tableNumber);
            }
        }

    } catch (error) {
        console.error('[预结单] 处理失败:', error);
        Swal.fire({
            icon: 'error',
            title: '<?php echo ruiyi_translate("Error", "Error", "错误"); ?>',
            text: error.message || '<?php echo ruiyi_translate("Error al procesar", "Processing error", "处理失败"); ?>',
            timer: 3000,
            showConfirmButton: false
        });
    }
}

// 🔥 生成本地预结单HTML（离线模式使用）
function generateLocalProformaHtml(cartItems, tableDisplayName, total, isDeliveryZone = false) {
  const storeInfo = window.RUIYI_POS_CONFIG?.storeInfo || {};

  // 转义HTML特殊字符
  const escapeHtml = (str) => {
    if (!str) return '';
    return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  };

  // 格式化当前时间
  const now = new Date();
  const formattedDate = now.toLocaleDateString('es-ES', {
    day: '2-digit', month: '2-digit', year: 'numeric'
  }) + ' ' + now.toLocaleTimeString('es-ES', {
    hour: '2-digit', minute: '2-digit'
  });

  // 生成Logo HTML
  let logoHtml = '';
  if (storeInfo.receiptLogo && storeInfo.receiptLogo.length > 5) {
    let logoUrl = storeInfo.receiptLogo;
    if (!logoUrl.startsWith('http') && !logoUrl.startsWith('data:')) {
      logoUrl = window.location.origin + (logoUrl.startsWith('/') ? '' : '/') + logoUrl;
    }
    logoHtml = `<div class="receipt-logo-container"><img src="${escapeHtml(logoUrl)}" class="receipt-logo" alt="Logo" onerror="this.style.display='none'"></div>`;
  }

  // 生成店铺信息
  let storeInfoHtml = '';
  if (storeInfo.businessName) storeInfoHtml += `<div class="business-name">${escapeHtml(storeInfo.businessName)}</div>`;
  if (storeInfo.cifNif) storeInfoHtml += `<div class="cif-nif">CIF/NIF: ${escapeHtml(storeInfo.cifNif)}</div>`;
  if (storeInfo.address) {
    const _addrLines = storeInfo.address.split('\n').map(l => escapeHtml(l.trim())).filter(l => l).join('<br>');
    storeInfoHtml += `<div class="address">${_addrLines}</div>`;
  }
  if (storeInfo.phone) storeInfoHtml += `<div class="phone">Tel: ${escapeHtml(storeInfo.phone)}</div>`;

  // 🔥 产品名称处理函数（移除编号前缀，如果设置开启）
  // 注意：此函数仅用于PROFORMA预结单，外送区域例外在此处适用
  const removeProductNumber = (name) => {
    if (!name) return name;
    const hideNumber = window.RUIYI_POS_CONFIG?.hideProductNumberOnReceipt === true;
    if (!hideNumber) return name;
    // 🔥 外送区域例外：如果是外送区域PROFORMA且开启了外送区域显示编号设置，则不隐藏
    const showOnDeliveryZone = window.RUIYI_POS_CONFIG?.showProductNumberOnTakeaway === true;
    if (isDeliveryZone && showOnDeliveryZone) {
      return name; // 外送区域预结单且设置为显示编号，返回原始名称
    }
    // 正则匹配: 数字 + 可选字母 + 点号 + 可选空格
    const regex = /^\d+[A-Za-z]?\.\s*/;
    return name.replace(regex, '') || name;
  };

  // 生成商品列表
  const _bilingual3 = window.clodopConfig?.receiptBilingual || false;
  let itemsHtml = '';
  cartItems.forEach(item => {
    // 🔥 过滤0元免费产品和自助餐产品 - 不在预结单中显示
    const _itemPrice = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
    if (_itemPrice <= 0 && (item.is_free || item.is_buffet)) return;

    // 🔥 customName 已含 supplements 名称，customPrice 已含 supplements 价格
    let itemName = item.customName || item.name || 'Producto';
    // 🔥 中西双语
    if (_bilingual3 && item.name_zh) {
      const _esN = item.name_es || item.name || '';
      const numMatch3 = _esN.match(/^(\d+[A-Za-z]?\.\s*)/);
      if (numMatch3) {
        const prefix3 = numMatch3[1].replace(/\s+$/, '');
        const esClean3 = _esN.substring(numMatch3[0].length);
        const zhClean3 = item.name_zh.replace(/^\d+[A-Za-z]?\.\s*/, '');
        itemName = prefix3 + zhClean3 + esClean3;
      } else {
        itemName = item.name_zh + _esN;
      }
    }
    // 🔥 根据设置决定是否移除产品编号
    itemName = removeProductNumber(itemName);
    const qty = item.quantity || 1;
    const price = parseFloat(item.customPrice !== undefined ? item.customPrice : (item.price || 0));
    const itemTotal = price * qty;
    itemsHtml += `<tr>
      <td class="item-name">${escapeHtml(itemName)}</td>
      <td class="col-qty">${qty}</td>
      <td class="col-price">€${price.toFixed(2)}</td>
      <td class="col-total">€${itemTotal.toFixed(2)}</td>
    </tr>`;
  });

  // 计算税额：所有产品都是含税价，税种/税率由设置模块控制
  const receiptTaxTotals = window.ruiyiCalculateIncludedReceiptTax(total);
  const subtotalWithoutTax = receiptTaxTotals.base;
  const taxAmount = receiptTaxTotals.tax;
  const receiptTaxLabel = window.ruiyiGetReceiptTaxDisplayLabel();
  const headerAlignment = window.clodopConfig?.headerAlignment || 'left';
  const storeNameFontSize = window.clodopConfig?.storeNameFontSize || 18;

  return `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Pre-Cuenta ${escapeHtml(tableDisplayName)}</title>
  <style>
    @media print { @page { size: auto; margin: 5mm; } body { margin: 0; padding: 0; } }
    body { font-family: "Courier New", "Lucida Console", monospace; width: 72mm; margin: 0 auto; padding: 5mm 4mm; box-sizing: border-box; font-size: 10pt; font-weight: normal; }
    .receipt { width: 100%; max-width: 72mm; }
    h2 { font-size: ${storeNameFontSize}pt; font-weight: bold; text-align: ${headerAlignment}; margin: 0 0 1mm 0; line-height: 1.15; }
    .store-info { text-align: ${headerAlignment}; }
	    .store-info div { font-size: 0.8em; margin-bottom: 0.4mm; line-height: 1.35; font-weight: normal; }
    h4 { font-size: 1.1em; font-weight: bold; text-align: ${headerAlignment}; margin: 2mm 0 1mm 0; }
    .date-line, .invoice-number, .verifactu-invoice-number { text-align: ${headerAlignment} !important; }
    .date-line { font-size: 0.8em; margin-bottom: 2mm; }
	    .proforma-notice { text-align: center; font-weight: bold; font-size: 1.2em; margin: 1mm 0 1.5mm 0; padding: 0 0 1mm 0; border-top: none; border-bottom: 2px dashed #000; }
	    table { width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 1em; margin: 3px 0; }
	    th, td { padding: 0.8mm 0.5mm; vertical-align: top; }
	    th { border-bottom: none; text-align: left; font-weight: bold; }
	    td.item-name { white-space: nowrap; overflow: hidden; text-overflow: clip; text-transform: uppercase; word-break: normal; letter-spacing: normal; font-family: "Courier New", "Lucida Console", monospace; font-size: 0.8em; font-weight: normal; text-align: left; line-height: 1.25; }
    td.col-qty { text-align: center; font-weight: normal; font-size: 0.9em; line-height: 1.25; }
    td.col-price, td.col-total { text-align: right; font-weight: normal; font-size: 0.9em; line-height: 1.25; }
    .totals-table { margin-top: 2mm; }
    .totals-table td { padding: 0.6mm 0.5mm; }
	    .total-row td { border-top: 2px solid #000; font-weight: bold; padding-top: 1.2mm; font-size: 1.15em; }
	    hr { display: none; border: none; margin: 0; }
    .receipt-logo-container { text-align: ${headerAlignment}; margin-bottom: 3mm; }
    .receipt-logo { max-width: 50mm; max-height: 20mm; display: inline-block; }
    .footer { text-align: center; font-size: 0.85em; margin-top: 4mm; font-style: italic; }
  </style>
</head>
<body>
  <div class="receipt">
    ${logoHtml}
    ${storeInfo.storeName ? `<h2>${escapeHtml(storeInfo.storeName).replace(/\n/g, '<br>')}</h2>` : ''}
    <div class="store-info">${storeInfoHtml}</div>
    <h4>${escapeHtml(tableDisplayName)}</h4>
    <div class="date-line">Fecha: ${formattedDate}</div>
	    <div class="proforma-marker" data-is-delivery-zone="${isDeliveryZone ? 'true' : 'false'}" style="text-align: center; font-weight: bold; font-size: 1.2em; margin: 1mm 0 1.5mm 0; padding: 0 0 1mm 0; border-top: none; border-bottom: 2px dashed #000;">PROFORMA</div>
    <hr>
    <table>
      <thead>
        <tr>
          <th style="width: 50%;">Producto</th>
          <th style="width: 15%; text-align:center;">Cant.</th>
          <th style="width: 15%; text-align:right;">Precio</th>
          <th style="width: 20%; text-align:right;">Total</th>
        </tr>
      </thead>
      <tbody>${itemsHtml || '<tr><td colspan="4" style="text-align:center;">Sin productos</td></tr>'}</tbody>
    </table>
    <hr>
    <table class="totals-table">
      <tr><td colspan="3" style="text-align: right;">Base Imponible:</td><td style="text-align: right;">${subtotalWithoutTax.toFixed(2)}€</td></tr>
      <tr><td colspan="3" style="text-align: right;">${receiptTaxLabel}</td><td style="text-align: right;">${taxAmount.toFixed(2)}€</td></tr>
      <tr class="total-row"><td colspan="3" style="text-align: right;">TOTAL:</td><td style="text-align: right;">${total.toFixed(2)}€</td></tr>
    </table>
    <div class="footer">Este documento no es una factura<br>This is not an invoice</div>
  </div>
</body>
</html>`;
}

function ruiyiPrebillString(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

function ruiyiResolvePrebillGlobalNumber(value) {
  const raw = ruiyiPrebillString(value);
  if (!raw) return '';
  const internalMesaMatch = raw.match(/^(?:Mesa|餐桌|Table|桌位)\s*(\d+)$/i);
  if (internalMesaMatch) return internalMesaMatch[1];
  if (/^\d+$/.test(raw)) return raw;
  try {
    if (typeof resolveGlobalTableNumber === 'function') {
      const resolved = resolveGlobalTableNumber(raw);
      if (resolved !== undefined && resolved !== null && String(resolved).trim() !== '') {
        return String(resolved).trim();
      }
    }
  } catch (error) {
    console.warn('[预结单] resolveGlobalTableNumber 失败:', error);
  }
  const match = raw.match(/\d+/g);
  return match ? match[match.length - 1] : raw.replace(/^(餐桌|Mesa|Table|桌位)\s*/i, '').trim();
}

function ruiyiResolveActiveTableNumber(fallbackTableNumber, options = {}) {
  const fallback = ruiyiPrebillString(fallbackTableNumber);
  const preferFallback = options && options.preferFallback === true;
  const inputTable = ruiyiPrebillString(document.getElementById('table-number')?.value);
  let viewTable = '';
  try {
    const viewMode = typeof ruiyiGetActiveTableViewMode === 'function'
      ? ruiyiGetActiveTableViewMode()
      : JSON.parse(sessionStorage.getItem('isViewMode') || 'null');
    viewTable = ruiyiPrebillString(viewMode?.table);
  } catch (error) {
    viewTable = '';
  }

  let currentViewingTable = '';
  if (window._currentViewingTable !== undefined && window._currentViewingTable !== null && window._currentViewingTable !== '') {
    currentViewingTable = `Mesa ${window._currentViewingTable}`;
  }

  const selected = preferFallback
    ? (fallback || inputTable || viewTable || currentViewingTable)
    : (inputTable || viewTable || fallback || currentViewingTable);
  const selectedGlobal = ruiyiResolvePrebillGlobalNumber(selected);
  const fallbackGlobal = ruiyiResolvePrebillGlobalNumber(fallback);
  if (selected && fallback && selectedGlobal && fallbackGlobal && selectedGlobal !== fallbackGlobal) {
    console.warn(preferFallback ? '[桌位] 当前桌位状态与按钮桌位不一致，已使用按钮桌位:' : '[桌位] 按钮桌位与当前桌位不一致，已使用当前桌位:', {
      buttonTable: fallback,
      activeTable: selected,
      buttonGlobal: fallbackGlobal,
      activeGlobal: selectedGlobal,
      preferFallback
    });
  }

  return selected;
}

function ruiyiResolveActivePrebillTableNumber(fallbackTableNumber) {
  return ruiyiResolveActiveTableNumber(fallbackTableNumber, { preferFallback: true });
}

function ruiyiSetCartTableIdentity(tableNumber, source = '') {
  const globalNumber = ruiyiResolvePrebillGlobalNumber(tableNumber);
  window._ruiyiCurrentCartTableGlobal = globalNumber || '';
  window._ruiyiCurrentCartTableSource = source || '';
}

function ruiyiGetCartTableIdentity() {
  const globalNumber = window._ruiyiCurrentCartTableGlobal !== undefined &&
    window._ruiyiCurrentCartTableGlobal !== null
    ? String(window._ruiyiCurrentCartTableGlobal).trim()
    : '';
  return {
    globalNumber,
    source: window._ruiyiCurrentCartTableSource || ''
  };
}

function ruiyiGetPrebillLinePrice(item) {
  if (!item) return 0;
  const rawPrice = item.customPrice !== undefined && item.customPrice !== null && item.customPrice !== ''
    ? item.customPrice
    : (item.price !== undefined && item.price !== null ? item.price : 0);
  const price = parseFloat(rawPrice);
  return Number.isFinite(price) ? price : 0;
}

function ruiyiClonePrebillCart(items) {
  if (!Array.isArray(items)) return [];
  return items
    .filter(item => item && parseInt(item.quantity || 0, 10) > 0)
    .map(item => {
      const cloned = JSON.parse(JSON.stringify(item));
      cloned.quantity = parseInt(cloned.quantity || 0, 10);
      return cloned;
    });
}

function ruiyiPrebillCartTotal(items) {
  const total = ruiyiClonePrebillCart(items).reduce((sum, item) => {
    return sum + (ruiyiGetPrebillLinePrice(item) * item.quantity);
  }, 0);
  return parseFloat(total.toFixed(2));
}

function ruiyiPrebillCartSignature(items) {
  return ruiyiClonePrebillCart(items).map(item => {
    const productId = item.id ?? item.product_id ?? item.productId ?? '';
    const name = (item.name || item.product_name || '').toString().trim();
    const price = ruiyiGetPrebillLinePrice(item).toFixed(2);
    const qty = parseInt(item.quantity || 0, 10);
    const note = (item.notes || item.note || item.observations || '').toString().trim();
    return `${productId}|${name}|${price}|${qty}|${note}`;
  }).join(';;');
}

function ruiyiPrebillResolveKeyGlobalNumber(key) {
  const rawKey = ruiyiPrebillString(key);
  if (!rawKey) return '';
  const internalMesaMatch = rawKey.match(/^(?:Mesa|餐桌|Table|桌位)\s*(\d+)$/i);
  if (internalMesaMatch) return internalMesaMatch[1];
  if (/^\d+$/.test(rawKey)) return rawKey;
  try {
    if (typeof resolveGlobalTableNumber === 'function') {
      const resolved = resolveGlobalTableNumber(rawKey);
      if (resolved !== undefined && resolved !== null && String(resolved).trim() !== '') {
        return String(resolved).trim();
      }
    }
  } catch (error) {
    console.warn('[预结单] resolveGlobalTableNumber key 失败:', { key: rawKey, error });
  }
  return ruiyiResolvePrebillGlobalNumber(rawKey);
}

function ruiyiPrebillStateBelongsToTable(key, data, requestedGlobal, allowCandidateKeyFallback = false) {
  if (!data || !Array.isArray(data.cart)) return false;

  const stateGtn = data.cart_gtn !== undefined && data.cart_gtn !== null ? String(data.cart_gtn) : '';
  if (stateGtn && requestedGlobal && stateGtn !== requestedGlobal) {
    return false;
  }

  const keyGtn = ruiyiPrebillResolveKeyGlobalNumber(key);
  if (keyGtn && requestedGlobal) {
    return keyGtn === requestedGlobal;
  }

  return allowCandidateKeyFallback && !stateGtn;
}

function ruiyiFindPrebillMesaState(tableNumber) {
  try {
    const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
    const numericOnly = ruiyiResolvePrebillGlobalNumber(tableNumber);
    const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
    const candidates = [
      String(tableNumber || ''),
      `Mesa ${numericOnly}`,
      `Mesa${numericOnly}`,
      `${tablePrefix} ${numericOnly}`,
      `${tablePrefix}${numericOnly}`
    ];

    for (const key of candidates) {
      if (key && mesasEstado[key] && Array.isArray(mesasEstado[key].cart)) {
        if (ruiyiPrebillStateBelongsToTable(key, mesasEstado[key], numericOnly, true)) {
          return { key, data: mesasEstado[key] };
        }
        console.warn('[预结单] 跳过不属于当前桌位的缓存快照:', {
          requestedGlobal: numericOnly,
          key,
          cartGtn: mesasEstado[key]?.cart_gtn
        });
      }
    }

    for (const [key, data] of Object.entries(mesasEstado)) {
      if (!data || !Array.isArray(data.cart)) continue;
      if (ruiyiPrebillStateBelongsToTable(key, data, numericOnly, false)) {
        return { key, data };
      }
    }
  } catch (error) {
    console.warn('[预结单] 读取 mesas_estado 失败:', error);
  }
  return null;
}

function ruiyiBuildPrebillSnapshot(tableNumber) {
  const liveCart = (typeof cart !== 'undefined' && Array.isArray(cart))
    ? cart
    : (Array.isArray(window.cart) ? window.cart : []);
  const currentCart = ruiyiClonePrebillCart(liveCart);
  const stateMatch = ruiyiFindPrebillMesaState(tableNumber);
  const stateCart = ruiyiClonePrebillCart(stateMatch?.data?.cart || []);
  const currentTotal = ruiyiPrebillCartTotal(currentCart);
  const stateTotal = ruiyiPrebillCartTotal(stateCart);
  const hasUnsavedCurrentItems = currentCart.some(item => !item.locked);
  const hasModifiedCurrentItems = window.cartModified === true ||
    currentCart.some(item => item.quantityModified || item.addedQuantity || item.isNew);
  const requestedGlobal = ruiyiResolvePrebillGlobalNumber(tableNumber);
  const inputGlobal = ruiyiResolvePrebillGlobalNumber(document.getElementById('table-number')?.value || tableNumber);
  const currentViewingGlobal = window._currentViewingTable !== undefined && window._currentViewingTable !== null && window._currentViewingTable !== ''
    ? String(window._currentViewingTable)
    : '';
  const stateGtn = stateMatch?.data?.cart_gtn !== undefined && stateMatch?.data?.cart_gtn !== null
    ? String(stateMatch.data.cart_gtn)
    : '';
  const cartIdentity = ruiyiGetCartTableIdentity();
  const stateMatchesRequestedTable = stateCart.length > 0 && (!stateGtn || stateGtn === requestedGlobal);
  const inputMatchesRequested = !inputGlobal || inputGlobal === requestedGlobal;
  const currentViewMatchesRequested = !currentViewingGlobal || currentViewingGlobal === requestedGlobal;
  const currentViewMismatch = currentViewingGlobal && requestedGlobal && currentViewingGlobal !== requestedGlobal;
  const liveCartIdentityMatchesRequested = currentCart.length > 0 &&
    cartIdentity.globalNumber &&
    requestedGlobal &&
    cartIdentity.globalNumber === requestedGlobal;
  const liveCartIdentityMismatch = currentCart.length > 0 &&
    cartIdentity.globalNumber &&
    requestedGlobal &&
    cartIdentity.globalNumber !== requestedGlobal;
  const cartsDiffer = stateCart.length > 0 && ruiyiPrebillCartSignature(currentCart) !== ruiyiPrebillCartSignature(stateCart);
  const liveCartMatchesRequestedContext = inputMatchesRequested &&
    currentViewMatchesRequested &&
    !currentViewMismatch &&
    liveCartIdentityMatchesRequested;

  let selectedCart = liveCartIdentityMatchesRequested ? currentCart : [];
  let source = liveCartIdentityMatchesRequested ? 'cart:current-table-live' : 'cart:untrusted-empty';

  if (currentCart.length > 0 && !liveCartIdentityMatchesRequested) {
    console.warn('[预结单] 实时 cart 未通过桌位身份校验，禁止直接打印旧购物车:', {
      requestedGlobal,
      cartIdentity,
      liveCartIdentityMismatch,
      inputGlobal,
      currentViewingGlobal,
      currentItems: currentCart.length,
      currentTotal
    });
  }

  if (stateMatchesRequestedTable && stateCart.length > 0) {
    const canTrustLiveCart = liveCartMatchesRequestedContext && (hasUnsavedCurrentItems || hasModifiedCurrentItems || cartsDiffer);

    if (!canTrustLiveCart && (!liveCartMatchesRequestedContext || currentCart.length === 0 || cartsDiffer || currentViewMismatch)) {
      selectedCart = stateCart;
      source = stateMatch?.key ? `mesas_estado:${stateMatch.key}:table-bound` : 'mesas_estado:table-bound';
      console.warn('[预结单] 检测到实时 cart 与当前桌位状态不一致，已使用当前桌位 mesas_estado 快照:', {
        requestedGlobal,
        inputGlobal,
        currentViewingGlobal,
        stateGtn,
        currentItems: currentCart.length,
        stateItems: stateCart.length,
        currentTotal,
        stateTotal,
        cartsDiffer,
        hasUnsavedCurrentItems,
        hasModifiedCurrentItems,
        cartIdentity
      });
    } else if (canTrustLiveCart) {
      selectedCart = currentCart;
      source = 'cart:current-table-live';
    }
  }

  if (source === 'cart:current-table-live' && stateCart.length > 0) {
    const stateLooksNewer = stateTotal > currentTotal + 0.01 || stateCart.length > currentCart.length;
    const cartLooksTemporarilyCleared = !hasUnsavedCurrentItems && currentCart.length < stateCart.length;
    if (!hasUnsavedCurrentItems && !hasModifiedCurrentItems && (stateLooksNewer || cartLooksTemporarilyCleared || currentCart.length === 0)) {
      selectedCart = stateCart;
      source = stateMatch?.key ? `mesas_estado:${stateMatch.key}` : 'mesas_estado';
    }
  }

  const cartData = ruiyiClonePrebillCart(selectedCart);
  const proformaCartData = cartData.filter(item => {
    const price = ruiyiGetPrebillLinePrice(item);
    return !((item.is_free || item.is_buffet) && price <= 0);
  });
  const total = ruiyiPrebillCartTotal(proformaCartData);

  console.log('[预结单] 使用打印快照:', {
    source,
    cartItems: cartData.length,
    proformaItems: proformaCartData.length,
    currentTotal,
    stateTotal,
    total,
    requestedGlobal,
    inputGlobal,
    currentViewingGlobal,
    stateGtn,
    cartIdentity
  });

  return { cartData, proformaCartData, total, source };
}

// 🔥 打印预览账单函数
function printPreviewBill(tableNumber) {
  const requestedTableNumber = tableNumber;
  tableNumber = ruiyiResolveActivePrebillTableNumber(tableNumber);
  if (!tableNumber) {
    Swal.fire({
      icon: 'warning',
      title: '<?php echo ruiyi_translate("Sin mesa", "No table", "未选择桌位"); ?>',
      text: '<?php echo ruiyi_translate("Seleccione una mesa primero", "Select a table first", "请先选择一个桌位"); ?>',
      timer: 2000,
      showConfirmButton: false
    });
    return;
  }

  const prebillPrintToken = Date.now() + '-' + Math.random().toString(36).slice(2, 8);
  window._ruiyiActivePrebillPrintToken = prebillPrintToken;
  if (requestedTableNumber && requestedTableNumber !== tableNumber) {
    console.warn('[预结单] printPreviewBill 已修正桌位:', { requestedTableNumber, activeTableNumber: tableNumber });
  }

  // 🔥 检测离线状态
  const isOnline = navigator.onLine && window.RUIYI_POS?.isOnline !== false;

  // 显示加载提示
  Toastify({
    text: '<?php echo ruiyi_translate('Generando pre-cuenta...', 'Generating preview bill...', '生成预览账单...'); ?>',
    duration: 2000,
    gravity: "top",
    position: "center",
    style: { background: "#9333ea" }
  }).showToast();

  // 获取预结单冻结快照：避免保存订单过程中 cart 被临时清空/回写导致金额不一致
  const prebillSnapshot = ruiyiBuildPrebillSnapshot(tableNumber);
  const cartData = prebillSnapshot.cartData;

  if (cartData.length === 0) {
    Swal.fire({
      icon: 'warning',
      title: '<?php echo ruiyi_translate('Carrito vacío', 'Empty cart', '购物车为空'); ?>',
      text: '<?php echo ruiyi_translate('No hay productos para imprimir', 'No products to print', '没有商品可打印'); ?>'
    });
    return;
  }

  // 🔥 预结单：排除免费产品和自助餐产品（价格为0且标记为is_free/is_buffet的产品不在预结单中显示）
  // 厨房小票仍使用完整的cartData（厨房需要知道做什么菜）
  const proformaCartData = prebillSnapshot.proformaCartData;
  const total = prebillSnapshot.total;

  // 🔥 获取桌位显示名称（从映射数据查找，确保包含分区信息）
  let tableDisplayName = `Mesa ${tableNumber}`; // 默认值

  // 🔥 关键：先提取纯数字（移除"餐桌"、"Mesa"、"Table"等前缀）
  const tableNumberClean = ruiyiResolvePrebillGlobalNumber(tableNumber);
  const globalNum = parseInt(tableNumberClean, 10);


  // 🔥 从 window.tableCategoryMappings 查找正确的分类显示名称
  if (window.tableCategoryMappings && !isNaN(globalNum)) {
    // 确保是数组格式
    let allMappings = [];
    if (Array.isArray(window.tableCategoryMappings)) {
      allMappings = window.tableCategoryMappings;
    } else {
      allMappings = Object.values(window.tableCategoryMappings);
    }

    // 根据全局编号查找映射
    const mapping = allMappings.find(m =>
      parseInt(m.global_table_number) === globalNum
    );

    if (mapping && mapping.category_display_name) {
      tableDisplayName = mapping.category_display_name;
    } else {
      console.warn('[预览账单] ⚠️ 未找到桌位映射，使用默认名称');
    }
  } else {
    console.warn('[预览账单] ⚠️ window.tableCategoryMappings 不存在或桌号无效');
  }

  // 🔥 获取当前桌位的客户信息（用于外送订单）
  let customerInfo = null;

  // 尝试从 sessionStorage 获取当前视图模式
  const currentViewMode = typeof ruiyiGetActiveTableViewMode === 'function'
    ? ruiyiGetActiveTableViewMode()
    : JSON.parse(sessionStorage.getItem('isViewMode') || 'null');

  // 获取桌位显示名称（用于查找 delivery 客户数据）
  let tableNameForCustomer = tableDisplayName;
  if (currentViewMode && currentViewMode.table) {
    tableNameForCustomer = currentViewMode.table;
  }


  // 🔥 尝试获取 delivery 客户数据 - 尝试多种方式
  if (typeof getDeliveryCustomerData === 'function') {
    console.log('[预览账单] 开始查找客户数据，桌号:', tableNumber, '全局编号:', globalNum, '显示名称:', tableNameForCustomer);

    // 方式1：使用桌位显示名称
    customerInfo = getDeliveryCustomerData(tableNameForCustomer);
    if (customerInfo) console.log('[预览账单] 方式1成功（显示名称）');

    // 方式2：如果没找到，尝试使用原始桌号
    if (!customerInfo && tableNumber) {
      customerInfo = getDeliveryCustomerData(tableNumber.toString());
      if (customerInfo) console.log('[预览账单] 方式2成功（原始桌号）');
    }

    // 方式3：如果没找到，尝试直接使用全局编号格式 "table_X"
    if (!customerInfo && !isNaN(globalNum) && typeof deliveryCustomerDataStore !== 'undefined') {
      const storageKey = `table_${globalNum}`;
      customerInfo = deliveryCustomerDataStore[storageKey] || null;
      if (customerInfo) console.log('[预览账单] 方式3成功（直接key）');
    }

    // 方式4：如果没找到，尝试使用 #table-number 输入框的值
    if (!customerInfo) {
      const tableInputValue = document.getElementById('table-number')?.value.trim();
      if (tableInputValue) {
        customerInfo = getDeliveryCustomerData(tableInputValue);
        if (customerInfo) console.log('[预览账单] 方式4成功（输入框值）');
      }
    }

    if (customerInfo) {
      console.log('[预览账单] ✅ 找到客户数据:', JSON.stringify(customerInfo));
    } else {
      console.warn('[预览账单] ⚠️ 未找到客户数据');
      // 调试：列出所有存储的客户数据
      if (typeof deliveryCustomerDataStore !== 'undefined') {
      }
    }
  } else {
    console.warn('[预览账单] ⚠️ getDeliveryCustomerData 函数不可用');
  }

  // 🔥 离线模式：使用本地生成的预结单HTML
  if (!isOnline) {
    // // console.log('[预览账单] 🔴 离线模式 - 使用本地生成预结单');

    try {
      // 🔥 检查桌位是否属于外送区域（如 DOMICILIO）- 只有外送区域才例外显示产品编号
      // 注意：必须使用原始桌号(tableNumber)而不是显示名称(tableDisplayName)，因为isDeliveryZoneTable需要提取全局桌号
      const isDeliveryZone = typeof isDeliveryZoneTable === 'function' ? isDeliveryZoneTable(tableNumber) : false;
      const proformaHtml = generateLocalProformaHtml(proformaCartData, tableDisplayName, total, isDeliveryZone);

      if (typeof ruiyiUnifiedPrint !== 'undefined') {
        if (window._ruiyiActivePrebillPrintToken !== prebillPrintToken) {
          console.warn('[预结单] 已有新的预结单打印请求，跳过当前离线打印:', tableNumber);
          return;
        }
        const printSuccess = ruiyiUnifiedPrint(proformaHtml, 'preview_bill');
        if (!printSuccess) {
          throw new Error('<?php echo ruiyi_translate('Error al imprimir pre-cuenta con CLODOP', 'CLODOP pre-bill print failed', 'CLODOP预结单打印失败'); ?>');
        }

        Toastify({
          text: '✅ <?php echo ruiyi_translate('Pre-cuenta impresa (offline)', 'Preview bill printed (offline)', '预览账单已打印 (离线)'); ?>',
          duration: 2000,
          gravity: "top",
          position: "center",
          style: { background: "#f59e0b" }  // 橙色表示离线
        }).showToast();

        // 🔥 预结单后标记桌位为"结算中"状态（离线模式）
        if (window.posSettings?.proformaSettlingStatus) {
          try {
            const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
            // 🔥 关键：提取纯数字，用"Mesa X"格式匹配fetchAndUpdateTableStatuses的存储格式
            const numericOnly = resolveGlobalTableNumber(tableNumber);
            const mesaKeyMesa = `Mesa ${numericOnly}`;
            const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
            const mesaKeyLocal = `${tablePrefix} ${numericOnly}`;
            const mesaKey = mesasEstado[mesaKeyMesa] ? mesaKeyMesa : (mesasEstado[mesaKeyLocal] ? mesaKeyLocal : mesaKeyMesa);
            if (mesasEstado[mesaKey]) {
              mesasEstado[mesaKey].estado = 'liquidando';
            } else {
              mesasEstado[mesaKey] = { estado: 'liquidando', total: total, cart: cartData, cart_gtn: parseInt(numericOnly) };
            }
            localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
            console.log('[预结单] ✅ 桌位', mesaKey, '已标记为结算中（离线模式）');
            if (typeof renderizarMesas === 'function') {
              renderizarMesas('proforma-settling');
            }
          } catch(e) {
            console.warn('[预结单] 设置结算中状态失败（离线模式）:', e);
          }
        }

        // 🔥 外送区域：额外打印客户信息小票
        if (isDeliveryZone && window.clodopConfig?.printDeliverySlipWithProforma && customerInfo) {
          console.log('[预览账单] 🚚 外送区域检测到，准备打印客户信息小票');

          // 第二张：外送客户信息小票（延迟500ms）
          setTimeout(() => {
            if (window._ruiyiActivePrebillPrintToken !== prebillPrintToken) {
              console.warn('[预结单] 外送小票延迟打印已过期，跳过:', tableNumber);
              return;
            }
            if (typeof window.ruiyiPrintDeliverySlip === 'function') {
              window.ruiyiPrintDeliverySlip({
                address: customerInfo.address || customerInfo.direccion || '',
                phone: customerInfo.phone || customerInfo.telefono || '',
                total: total,
                tableName: tableDisplayName,
                orderNumber: null,
                datetime: new Date().toLocaleString('es-ES', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' })
              });
              console.log('[预览账单] ✅ 外送小票已打印');
            } else {
              console.warn('[预览账单] ⚠️ ruiyiPrintDeliverySlip 函数不可用');
            }
          }, 500);

          if (window.clodopConfig?.printKitchenSlipWithDeliveryProforma) {
            // 第三张：厨房样式商品清单小票（延迟1000ms）- 发送到收银打印机
            setTimeout(() => {
              if (window._ruiyiActivePrebillPrintToken !== prebillPrintToken) {
                console.warn('[预结单] 收银厨房小票延迟打印已过期，跳过:', tableNumber);
                return;
              }
              if (typeof ruiyiPrintKitchenOrder === 'function' && window.clodopConfig?.defaultPrinter) {
                // 🔥🔥🔥 调试：记录cartData详情
                console.log('[预览账单-调试] cartData 商品列表:', cartData.map(item => ({
                  name: item.name,
                  quantity: item.quantity,
                  id: item.id
                })));

                let deliveryKitchenCartData = cartData;
                if (window.clodopConfig?.kitchenCategoryFilterEnabled) {
                  deliveryKitchenCartData = cartData.filter(item => !isKitchenExcludedProduct(item.id));
                  console.log('[预览账单] 🔥 收银厨房小票同步厨房分类过滤: 全部', cartData.length, '项 → 过滤后', deliveryKitchenCartData.length, '项');
                }

                if (deliveryKitchenCartData.length === 0) {
                  console.log('[预览账单] ℹ️ 过滤后无商品需要打印收银厨房小票，跳过');
                  return;
                }

                const consolidatedItemsMap = new Map();
                deliveryKitchenCartData.forEach(item => {
                  const key = item.name;
                  if (consolidatedItemsMap.has(key)) {
                    const existing = consolidatedItemsMap.get(key);
                    existing.quantity += item.quantity;
                    if (item.notes && !existing.notes.includes(item.notes)) {
                      existing.notes = existing.notes ? `${existing.notes}, ${item.notes}` : item.notes;
                    }
                  } else {
                    consolidatedItemsMap.set(key, {
                      name: item.name,
                      quantity: item.quantity,
                      notes: item.notes || ''
                    });
                  }
                });
                const consolidatedItems = Array.from(consolidatedItemsMap.values());
                console.log('[预览账单-调试] 合并后的商品列表:', JSON.stringify(consolidatedItems));

                const kitchenStyleData = {
                  id: 'PROFORMA-' + Date.now(),
                  table_number: tableDisplayName,
                  order_type: 'servir',
                  items: consolidatedItems,
                  date_created: new Date().toISOString(),
                  orderNotes: typeof window.getOrderNotes === 'function' ? window.getOrderNotes() : '',
                  customerInfo: customerInfo ? {
                    phone: customerInfo.phone || customerInfo.telefono || '',
                    address: customerInfo.address || customerInfo.direccion || ''
                  } : null
                };
                console.log('[预览账单-调试] kitchenStyleData.items:', JSON.stringify(kitchenStyleData.items));
                console.log('[预览账单-调试] kitchenStyleData.customerInfo:', kitchenStyleData.customerInfo);
                ruiyiPrintKitchenOrder(kitchenStyleData, window.clodopConfig.defaultPrinter);
                console.log('[预览账单] ✅ 厨房样式商品小票已打印（收银打印机）');
              } else {
                console.warn('[预览账单] ⚠️ ruiyiPrintKitchenOrder 函数或收银打印机不可用');
              }
            }, 1000);

            // 第四张：厨房样式商品清单小票（延迟1500ms）- 发送到厨房打印机
            setTimeout(() => {
              if (window._ruiyiActivePrebillPrintToken !== prebillPrintToken) {
                console.warn('[预结单] 厨房小票延迟打印已过期，跳过:', tableNumber);
                return;
              }
              if (typeof ruiyiPrintKitchenOrder === 'function' && window.clodopConfig?.kitchenPrinter) {
                let kitchenCartData = cartData;
                if (window.clodopConfig?.kitchenCategoryFilterEnabled) {
                  kitchenCartData = cartData.filter(item => !isKitchenExcludedProduct(item.id));
                  console.log('[预览账单] 🔥 厨房打印分类过滤: 全部', cartData.length, '项 → 过滤后', kitchenCartData.length, '项');
                }

                if (kitchenCartData.length === 0) {
                  console.log('[预览账单] ℹ️ 过滤后无商品需要厨房打印，跳过');
                } else {
                  const consolidatedItemsMap = new Map();
                  kitchenCartData.forEach(item => {
                    const key = item.name;
                    if (consolidatedItemsMap.has(key)) {
                      const existing = consolidatedItemsMap.get(key);
                      existing.quantity += item.quantity;
                      if (item.notes && !existing.notes.includes(item.notes)) {
                        existing.notes = existing.notes ? `${existing.notes}, ${item.notes}` : item.notes;
                      }
                    } else {
                      consolidatedItemsMap.set(key, {
                        name: item.name,
                        quantity: item.quantity,
                        notes: item.notes || ''
                      });
                    }
                  });
                  const consolidatedItems = Array.from(consolidatedItemsMap.values());

                  const kitchenStyleData = {
                    id: 'PROFORMA-KITCHEN-' + Date.now(),
                    table_number: tableDisplayName,
                    order_type: 'servir',
                    items: consolidatedItems,
                    date_created: new Date().toISOString(),
                    orderNotes: typeof window.getOrderNotes === 'function' ? window.getOrderNotes() : '',
                    customerInfo: customerInfo ? {
                      phone: customerInfo.phone || customerInfo.telefono || '',
                      address: customerInfo.address || customerInfo.direccion || ''
                    } : null
                  };
                  ruiyiPrintKitchenOrder(kitchenStyleData, window.clodopConfig.kitchenPrinter);
                  console.log('[预览账单] ✅ 厨房样式商品小票已打印（厨房打印机）');

                  if (kitchenStyleData.orderNotes && typeof window.clearOrderNotes === 'function') {
                    console.log('[预览账单-离线] 🗑️ 清空订单备注，防止重复打印');
                    window.clearOrderNotes();
                  }
                }
              } else {
                console.warn('[预览账单] ⚠️ ruiyiPrintKitchenOrder 函数或厨房打印机不可用');
              }
            }, 1500);
          } else {
            console.log('[预览账单] ⏭️ 已关闭“预结单时打印外送厨房小票”，跳过厨房小票打印');
          }
        }
      } else {
        throw new Error('<?php echo ruiyi_translate('Función de impresión no disponible', 'Print function not available', '打印功能不可用'); ?>');
      }
    } catch (error) {
      console.error('[预览账单] 离线打印失败:', error);
      Swal.fire({
        icon: 'error',
        title: '<?php echo ruiyi_translate('Error', 'Error', '错误'); ?>',
        text: error.message
      });
    }
    return; // 离线模式直接返回，不调用后端
  }

  // 🔥 检查桌位是否属于外送区域（如 DOMICILIO）- 只有外送区域才例外显示产品编号
  // 注意：必须使用原始桌号(tableNumber)而不是显示名称(tableDisplayName)，因为isDeliveryZoneTable需要提取全局桌号
  const isDeliveryZone = typeof isDeliveryZoneTable === 'function' ? isDeliveryZoneTable(tableNumber) : false;
  console.log('[预览账单] 🔍 外送区域检测:', { tableNumber, isDeliveryZone, 显示名称: tableDisplayName });

  // 调用后端生成预览小票 HTML
  const requestParams = {
    action: 'ruiyi_pos_get_preview_bill_html',
    table: tableNumber,
    table_display_name: tableDisplayName,
    cart_data: JSON.stringify(proformaCartData),
    order_total: total.toFixed(2),
    is_preview: 'true',
    is_delivery_zone: isDeliveryZone ? 'true' : 'false', // 🔥 传递外送区域标识（只有外送区域才例外）
    nonce: ajaxNonce
  };

  // 🔥 如果有客户信息，添加到请求参数
  if (customerInfo) {
    requestParams.customer_info = JSON.stringify(customerInfo);
  }

  fetch(ajaxUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(requestParams)
  })
  .then(response => response.json())
  .then(data => {
    if (window._ruiyiActivePrebillPrintToken !== prebillPrintToken) {
      console.warn('[预结单] 已有新的预结单打印请求，跳过过期响应:', tableNumber);
      return;
    }
    if (data.success && data.data && data.data.html) {
      // 使用统一打印函数
      if (typeof ruiyiUnifiedPrint !== 'undefined') {
        const printSuccess = ruiyiUnifiedPrint(data.data.html, 'preview_bill');
        if (!printSuccess) {
          throw new Error('<?php echo ruiyi_translate('Error al imprimir pre-cuenta con CLODOP', 'CLODOP pre-bill print failed', 'CLODOP预结单打印失败'); ?>');
        }

        Toastify({
          text: '✅ <?php echo ruiyi_translate('Pre-cuenta impresa', 'Preview bill printed', '预览账单已打印'); ?>',
          duration: 2000,
          gravity: "top",
          position: "center",
          style: { background: "#10b981" }
        }).showToast();

        // 🔥 预结单后标记桌位为"结算中"状态
        if (window.posSettings?.proformaSettlingStatus) {
          try {
            const mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');
            // 🔥 关键：提取纯数字，用"Mesa X"格式匹配fetchAndUpdateTableStatuses的存储格式
            const numericOnly = resolveGlobalTableNumber(tableNumber);
            const mesaKeyMesa = `Mesa ${numericOnly}`;
            const tablePrefix = (window.RUIYI_TRANS && window.RUIYI_TRANS.table) ? window.RUIYI_TRANS.table : 'Mesa';
            const mesaKeyLocal = `${tablePrefix} ${numericOnly}`;
            // 优先查找"Mesa X"格式，其次查找本地语言格式
            const mesaKey = mesasEstado[mesaKeyMesa] ? mesaKeyMesa : (mesasEstado[mesaKeyLocal] ? mesaKeyLocal : mesaKeyMesa);
            if (mesasEstado[mesaKey]) {
              mesasEstado[mesaKey].estado = 'liquidando';
            } else {
              mesasEstado[mesaKey] = { estado: 'liquidando', total: total, cart: cartData, cart_gtn: parseInt(numericOnly) };
            }
            localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
            console.log('[预结单] ✅ 桌位', mesaKey, '已标记为结算中');
            if (typeof renderizarMesas === 'function') {
              renderizarMesas('proforma-settling');
            }
          } catch(e) {
            console.warn('[预结单] 设置结算中状态失败:', e);
          }
        }

        // 🔥 外送区域：额外打印客户信息小票
        if (isDeliveryZone && window.clodopConfig?.printDeliverySlipWithProforma && customerInfo) {
          console.log('[预览账单] 🚚 外送区域检测到，准备打印客户信息小票 (在线模式)');

          // 第二张：外送客户信息小票（延迟500ms）
          setTimeout(() => {
            if (window._ruiyiActivePrebillPrintToken !== prebillPrintToken) {
              console.warn('[预结单] 外送小票延迟打印已过期，跳过:', tableNumber);
              return;
            }
            if (typeof window.ruiyiPrintDeliverySlip === 'function') {
              window.ruiyiPrintDeliverySlip({
                address: customerInfo.address || customerInfo.direccion || '',
                phone: customerInfo.phone || customerInfo.telefono || '',
                total: total,
                tableName: tableDisplayName,
                orderNumber: data.data.order_id || null,
                datetime: new Date().toLocaleString('es-ES', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' })
              });
              console.log('[预览账单] ✅ 外送小票已打印 (在线模式)');
            } else {
              console.warn('[预览账单] ⚠️ ruiyiPrintDeliverySlip 函数不可用');
            }
          }, 500);

          if (window.clodopConfig?.printKitchenSlipWithDeliveryProforma) {
            // 第三张：厨房样式商品清单小票（延迟1000ms）- 发送到收银打印机
            setTimeout(() => {
              if (window._ruiyiActivePrebillPrintToken !== prebillPrintToken) {
                console.warn('[预结单] 收银厨房小票延迟打印已过期，跳过:', tableNumber);
                return;
              }
              if (typeof ruiyiPrintKitchenOrder === 'function' && window.clodopConfig?.defaultPrinter) {
                console.log('[预览账单-调试-在线] cartData 商品列表:', cartData.map(item => ({
                  name: item.name,
                  quantity: item.quantity,
                  id: item.id
                })));

                let deliveryKitchenCartData = cartData;
                if (window.clodopConfig?.kitchenCategoryFilterEnabled) {
                  deliveryKitchenCartData = cartData.filter(item => !isKitchenExcludedProduct(item.id));
                  console.log('[预览账单] 🔥 收银厨房小票同步厨房分类过滤(在线): 全部', cartData.length, '项 → 过滤后', deliveryKitchenCartData.length, '项');
                }

                if (deliveryKitchenCartData.length === 0) {
                  console.log('[预览账单] ℹ️ 过滤后无商品需要打印收银厨房小票，跳过(在线模式)');
                  return;
                }

                const consolidatedItemsMap = new Map();
                deliveryKitchenCartData.forEach(item => {
                  const key = item.name;
                  if (consolidatedItemsMap.has(key)) {
                    const existing = consolidatedItemsMap.get(key);
                    existing.quantity += item.quantity;
                    if (item.notes && !existing.notes.includes(item.notes)) {
                      existing.notes = existing.notes ? `${existing.notes}, ${item.notes}` : item.notes;
                    }
                  } else {
                    consolidatedItemsMap.set(key, {
                      name: item.name,
                      quantity: item.quantity,
                      notes: item.notes || ''
                    });
                  }
                });
                const consolidatedItems = Array.from(consolidatedItemsMap.values());
                console.log('[预览账单-调试-在线] 合并后的商品列表:', JSON.stringify(consolidatedItems));

                const kitchenStyleData = {
                  id: data.data.order_id || ('PROFORMA-' + Date.now()),
                  table_number: tableDisplayName,
                  order_type: 'servir',
                  items: consolidatedItems,
                  date_created: new Date().toISOString(),
                  orderNotes: typeof window.getOrderNotes === 'function' ? window.getOrderNotes() : '',
                  customerInfo: customerInfo ? {
                    phone: customerInfo.phone || customerInfo.telefono || '',
                    address: customerInfo.address || customerInfo.direccion || ''
                  } : null
                };
                console.log('[预览账单-调试-在线] kitchenStyleData.items:', JSON.stringify(kitchenStyleData.items));
                console.log('[预览账单-调试-在线] kitchenStyleData.customerInfo:', kitchenStyleData.customerInfo);
                ruiyiPrintKitchenOrder(kitchenStyleData, window.clodopConfig.defaultPrinter);
                console.log('[预览账单] ✅ 厨房样式商品小票已打印（收银打印机）(在线模式)');
              } else {
                console.warn('[预览账单] ⚠️ ruiyiPrintKitchenOrder 函数或收银打印机不可用');
              }
            }, 1000);

            // 第四张：厨房样式商品清单小票（延迟1500ms）- 发送到厨房打印机
            setTimeout(() => {
              if (window._ruiyiActivePrebillPrintToken !== prebillPrintToken) {
                console.warn('[预结单] 厨房小票延迟打印已过期，跳过:', tableNumber);
                return;
              }
              if (typeof ruiyiPrintKitchenOrder === 'function' && window.clodopConfig?.kitchenPrinter) {
                let kitchenCartData = cartData;
                if (window.clodopConfig?.kitchenCategoryFilterEnabled) {
                  kitchenCartData = cartData.filter(item => !isKitchenExcludedProduct(item.id));
                  console.log('[预览账单] 🔥 厨房打印分类过滤(在线): 全部', cartData.length, '项 → 过滤后', kitchenCartData.length, '项');
                }

                if (kitchenCartData.length === 0) {
                  console.log('[预览账单] ℹ️ 过滤后无商品需要厨房打印，跳过(在线模式)');
                } else {
                  const consolidatedItemsMap = new Map();
                  kitchenCartData.forEach(item => {
                    const key = item.name;
                    if (consolidatedItemsMap.has(key)) {
                      const existing = consolidatedItemsMap.get(key);
                      existing.quantity += item.quantity;
                      if (item.notes && !existing.notes.includes(item.notes)) {
                        existing.notes = existing.notes ? `${existing.notes}, ${item.notes}` : item.notes;
                      }
                    } else {
                      consolidatedItemsMap.set(key, {
                        name: item.name,
                        quantity: item.quantity,
                        notes: item.notes || ''
                      });
                    }
                  });
                  const consolidatedItems = Array.from(consolidatedItemsMap.values());

                  const kitchenStyleData = {
                    id: (data.data.order_id || 'PROFORMA') + '-KITCHEN-' + Date.now(),
                    table_number: tableDisplayName,
                    order_type: 'servir',
                    items: consolidatedItems,
                    date_created: new Date().toISOString(),
                    orderNotes: typeof window.getOrderNotes === 'function' ? window.getOrderNotes() : '',
                    customerInfo: customerInfo ? {
                      phone: customerInfo.phone || customerInfo.telefono || '',
                      address: customerInfo.address || customerInfo.direccion || ''
                    } : null
                  };
                  ruiyiPrintKitchenOrder(kitchenStyleData, window.clodopConfig.kitchenPrinter);
                  console.log('[预览账单] ✅ 厨房样式商品小票已打印（厨房打印机）(在线模式)');

                  if (kitchenStyleData.orderNotes && typeof window.clearOrderNotes === 'function') {
                    console.log('[预览账单-在线] 🗑️ 清空订单备注，防止重复打印');
                    window.clearOrderNotes();
                  }
                }
              } else {
                console.warn('[预览账单] ⚠️ ruiyiPrintKitchenOrder 函数或厨房打印机不可用');
              }
            }, 1500);
          } else {
            console.log('[预览账单] ⏭️ 已关闭“预结单时打印外送厨房小票”，跳过厨房小票打印 (在线模式)');
          }
        }
      } else {
        throw new Error('<?php echo ruiyi_translate('Función de impresión no disponible', 'Print function not available', '打印功能不可用'); ?>');
      }
    } else {
      throw new Error(data.data?.message || '<?php echo ruiyi_translate('Error al generar pre-cuenta', 'Failed to generate preview bill', '生成预览账单失败'); ?>');
    }
  })
  .catch(error => {
    console.error('[预览账单] 打印失败:', error);
    Swal.fire({
      icon: 'error',
      title: '<?php echo ruiyi_translate('Error', 'Error', '错误'); ?>',
      text: error.message
    });
  });
}

// ==================== 🔥 客户管理模块 ====================
(function() {
  'use strict';

  // AJAX URL和Nonce
  const ajaxUrl = window.ajaxUrl || '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';
  const posNonce = window.posNonce || '<?php echo wp_create_nonce('ruiyi_pos_nonce'); ?>';

  // 客户管理状态
  const customerState = {
    currentPage: 1,
    perPage: 50,  // 每页最多显示50条
    totalPages: 1,
    totalCustomers: 0,
    searchTerm: '',
    customers: [],
    isLoading: false
  };

  // 初始化客户管理模块
  function initCustomerManagement() {
    console.log('[客户管理] 初始化客户管理模块');

    // 绑定事件
    bindCustomerEvents();

    // 监听设置选项卡切换
    const customerTab = document.getElementById('customer-tab');
    if (customerTab) {
      customerTab.addEventListener('click', function() {
        // 延迟加载客户数据
        setTimeout(() => {
          if (customerState.customers.length === 0) {
            loadCustomers();
          }
        }, 100);
      });
    }
  }

  // 绑定客户管理事件
  function bindCustomerEvents() {
    // 搜索按钮
    const searchBtn = document.getElementById('customer-search-btn');
    if (searchBtn) {
      searchBtn.addEventListener('click', function() {
        const searchInput = document.getElementById('customer-search-input');
        customerState.searchTerm = searchInput ? searchInput.value.trim() : '';
        customerState.currentPage = 1;
        loadCustomers();
      });
    }

    // 搜索输入框回车
    const searchInput = document.getElementById('customer-search-input');
    if (searchInput) {
      searchInput.addEventListener('keypress', function(e) {
        if (e.key === 'Enter') {
          e.preventDefault();
          customerState.searchTerm = this.value.trim();
          customerState.currentPage = 1;
          loadCustomers();
        }
      });
    }

    // 刷新按钮
    const refreshBtn = document.getElementById('customer-refresh-btn');
    if (refreshBtn) {
      refreshBtn.addEventListener('click', function() {
        customerState.searchTerm = '';
        const searchInput = document.getElementById('customer-search-input');
        if (searchInput) searchInput.value = '';
        customerState.currentPage = 1;
        loadCustomers();
      });
    }

    // 添加客户按钮
    const addBtn = document.getElementById('add-new-customer-btn');
    if (addBtn) {
      addBtn.addEventListener('click', function() {
        openCustomerModal(null);
      });
    }

    // 分页按钮
    const prevBtn = document.getElementById('customer-prev-page');
    const nextBtn = document.getElementById('customer-next-page');

    if (prevBtn) {
      prevBtn.addEventListener('click', function() {
        if (customerState.currentPage > 1) {
          customerState.currentPage--;
          loadCustomers();
        }
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener('click', function() {
        if (customerState.currentPage < customerState.totalPages) {
          customerState.currentPage++;
          loadCustomers();
        }
      });
    }

    // 模态框事件
    const closeBtn = document.getElementById('close-customer-modal');
    const cancelBtn = document.getElementById('cancel-customer-btn');
    const saveBtn = document.getElementById('save-customer-btn');
    const deleteBtn = document.getElementById('delete-customer-btn');
    const modal = document.getElementById('customer-edit-modal');

    if (closeBtn) {
      closeBtn.addEventListener('click', closeCustomerModal);
    }

    if (cancelBtn) {
      cancelBtn.addEventListener('click', closeCustomerModal);
    }

    if (saveBtn) {
      saveBtn.addEventListener('click', saveCustomer);
    }

    if (deleteBtn) {
      deleteBtn.addEventListener('click', deleteCustomer);
    }

    // 点击模态框背景关闭
    if (modal) {
      modal.addEventListener('click', function(e) {
        if (e.target === this) {
          closeCustomerModal();
        }
      });
    }
  }

  // 加载客户数据
  function loadCustomers() {
    if (customerState.isLoading) return;
    customerState.isLoading = true;

    const tableBody = document.getElementById('customer-list-table-body');
    const countDisplay = document.getElementById('customer-count-display');

    // 显示加载状态
    if (tableBody) {
      tableBody.innerHTML = `
        <tr>
          <td colspan="5" class="px-4 py-8 text-center text-gray-500 dark:text-gray-400">
            <i class="fas fa-spinner fa-spin mr-2"></i>
            <?php echo ruiyi_translate('Cargando clientes...', 'Loading customers...', '正在加载客户数据...'); ?>
          </td>
        </tr>
      `;
    }

    const formData = new FormData();
    formData.append('action', 'ruiyi_get_all_customers');
    formData.append('nonce', posNonce);
    formData.append('page', customerState.currentPage);
    formData.append('per_page', customerState.perPage);
    formData.append('search', customerState.searchTerm);

    fetch(ajaxUrl, {
      method: 'POST',
      body: formData
    })
    .then(response => response.json())
    .then(data => {
      customerState.isLoading = false;

      if (data.success) {
        customerState.customers = data.data.customers;
        customerState.totalPages = data.data.total_pages;
        customerState.totalCustomers = data.data.total;

        renderCustomerList();
        updatePagination();

        // 更新统计显示
        if (countDisplay) {
          const start = (customerState.currentPage - 1) * customerState.perPage + 1;
          const end = Math.min(customerState.currentPage * customerState.perPage, customerState.totalCustomers);
          const rangeText = customerState.totalCustomers > 0 ? `${start}-${end} / ` : '';
          const searchText = customerState.searchTerm ? ` (<?php echo ruiyi_translate('búsqueda', 'search', '搜索'); ?>: "${customerState.searchTerm}")` : '';
          countDisplay.textContent = `${rangeText}<?php echo ruiyi_translate('Total', 'Total', '共'); ?> ${customerState.totalCustomers} <?php echo ruiyi_translate('clientes', 'customers', '位客户'); ?>${searchText}`;
        }
      } else {
        console.error('[客户管理] 加载失败:', data.data?.message);
        if (tableBody) {
          tableBody.innerHTML = `
            <tr>
              <td colspan="5" class="px-4 py-8 text-center text-red-500">
                <i class="fas fa-exclamation-circle mr-2"></i>
                ${data.data?.message || '<?php echo ruiyi_translate('Error al cargar', 'Load error', '加载失败'); ?>'}
              </td>
            </tr>
          `;
        }
      }
    })
    .catch(error => {
      customerState.isLoading = false;
      console.error('[客户管理] 请求失败:', error);
      if (tableBody) {
        tableBody.innerHTML = `
          <tr>
            <td colspan="5" class="px-4 py-8 text-center text-red-500">
              <i class="fas fa-exclamation-circle mr-2"></i>
              <?php echo ruiyi_translate('Error de red', 'Network error', '网络错误'); ?>
            </td>
          </tr>
        `;
      }
    });
  }

  // 渲染客户列表
  function renderCustomerList() {
    const tableBody = document.getElementById('customer-list-table-body');
    if (!tableBody) return;

    if (customerState.customers.length === 0) {
      tableBody.innerHTML = `
        <tr>
          <td colspan="5" class="px-4 py-8 text-center text-gray-500 dark:text-gray-400">
            <i class="fas fa-users mr-2"></i>
            <?php echo ruiyi_translate('No hay clientes registrados', 'No customers registered', '暂无客户数据'); ?>
          </td>
        </tr>
      `;
      return;
    }

    let html = '';
    customerState.customers.forEach(customer => {
      const address = customer.address ?
        (customer.address.length > 30 ? customer.address.substring(0, 30) + '...' : customer.address) : '-';

      // 🔥 移除姓名列，电话作为主要标识
      html += `
        <tr class="hover:bg-gray-50 dark:hover:bg-gray-700 cursor-pointer transition-colors"
            onclick="window.customerManagement.editCustomer(${customer.id})">
          <td class="px-4 py-3 whitespace-nowrap">
            <div class="font-medium text-gray-900 dark:text-white">${escapeHtml(customer.phone || '-')}</div>
          </td>
          <td class="px-4 py-3 whitespace-nowrap text-gray-600 dark:text-gray-300">
            ${escapeHtml(customer.business_name || '-')}
          </td>
          <td class="px-4 py-3 whitespace-nowrap text-gray-600 dark:text-gray-300">
            ${escapeHtml(customer.cif_nif || '-')}
          </td>
          <td class="px-4 py-3 text-gray-600 dark:text-gray-300" title="${escapeHtml(customer.address || '')}">
            ${escapeHtml(address)}
          </td>
          <td class="px-4 py-3 whitespace-nowrap text-right">
            <button onclick="event.stopPropagation(); window.customerManagement.editCustomer(${customer.id})"
                    class="text-blue-600 hover:text-blue-800 dark:text-blue-400 mr-2" title="<?php echo ruiyi_translate('Editar', 'Edit', '编辑'); ?>">
              <i class="fas fa-edit"></i>
            </button>
            <button onclick="event.stopPropagation(); window.customerManagement.confirmDelete(${customer.id}, '${escapeHtml(customer.phone || '')}')"
                    class="text-red-600 hover:text-red-800 dark:text-red-400" title="<?php echo ruiyi_translate('Eliminar', 'Delete', '删除'); ?>">
              <i class="fas fa-trash"></i>
            </button>
          </td>
        </tr>
      `;
    });

    tableBody.innerHTML = html;
  }

  // 更新分页
  function updatePagination() {
    const prevBtn = document.getElementById('customer-prev-page');
    const nextBtn = document.getElementById('customer-next-page');
    const pageInfo = document.getElementById('customer-page-info');

    if (prevBtn) {
      prevBtn.disabled = customerState.currentPage <= 1;
    }

    if (nextBtn) {
      nextBtn.disabled = customerState.currentPage >= customerState.totalPages;
    }

    if (pageInfo) {
      if (customerState.totalPages > 1) {
        pageInfo.textContent = `${customerState.currentPage} / ${customerState.totalPages}`;
      } else {
        pageInfo.textContent = '';
      }
    }
  }

  // 打开客户编辑模态框
  function openCustomerModal(customer) {
    const modal = document.getElementById('customer-edit-modal');
    const title = document.getElementById('customer-modal-title');
    const deleteBtn = document.getElementById('delete-customer-btn');

    if (!modal) return;

    // 清空表单
    document.getElementById('edit-customer-id').value = customer ? customer.id : '';
    document.getElementById('edit-customer-name').value = customer ? customer.name : '';
    document.getElementById('edit-customer-phone').value = customer ? customer.phone : '';
    document.getElementById('edit-customer-business').value = customer ? customer.business_name : '';
    document.getElementById('edit-customer-cif').value = customer ? customer.cif_nif : '';
    document.getElementById('edit-customer-address').value = customer ? customer.address : '';
    document.getElementById('edit-customer-postal').value = customer ? customer.postal_code : '';
    document.getElementById('edit-customer-email').value = customer ? customer.email : '';

    if (customer) {
      // 编辑模式
      title.textContent = '<?php echo ruiyi_translate('Editar Cliente', 'Edit Customer', '编辑客户'); ?>';
      deleteBtn.classList.remove('hidden');
    } else {
      // 新增模式
      title.textContent = '<?php echo ruiyi_translate('Añadir Cliente', 'Add Customer', '添加客户'); ?>';
      deleteBtn.classList.add('hidden');
    }

    modal.classList.remove('hidden');
  }

  // 关闭客户编辑模态框
  function closeCustomerModal() {
    const modal = document.getElementById('customer-edit-modal');
    if (modal) {
      modal.classList.add('hidden');
    }
  }

  // 编辑客户
  function editCustomer(customerId) {
    // 确保ID类型一致（转为数字比较）
    const targetId = parseInt(customerId);
    const customer = customerState.customers.find(c => parseInt(c.id) === targetId);

    if (customer) {
      openCustomerModal(customer);
    } else {
      // 如果在当前列表中找不到，从服务器获取
      console.log('[客户管理] 从服务器获取客户:', targetId);
      fetchCustomerById(targetId);
    }
  }

  // 从服务器获取单个客户数据
  function fetchCustomerById(customerId) {
    const formData = new FormData();
    formData.append('action', 'ruiyi_get_customer_by_id');
    formData.append('nonce', posNonce);
    formData.append('customer_id', customerId);

    fetch(ajaxUrl, {
      method: 'POST',
      body: formData
    })
    .then(response => response.json())
    .then(data => {
      if (data.success && data.data.customer) {
        openCustomerModal(data.data.customer);
      } else {
        Swal.fire({
          icon: 'error',
          title: '<?php echo ruiyi_translate('Error', 'Error', '错误'); ?>',
          text: data.data?.message || '<?php echo ruiyi_translate('Cliente no encontrado', 'Customer not found', '未找到该客户'); ?>'
        });
      }
    })
    .catch(error => {
      console.error('[客户管理] 获取客户失败:', error);
      Swal.fire({
        icon: 'error',
        title: '<?php echo ruiyi_translate('Error', 'Error', '错误'); ?>',
        text: '<?php echo ruiyi_translate('Error de red', 'Network error', '网络错误'); ?>'
      });
    });
  }

  // 保存客户
  function saveCustomer() {
    const customerId = document.getElementById('edit-customer-id').value;
    const phone = document.getElementById('edit-customer-phone').value.trim();
    const businessName = document.getElementById('edit-customer-business').value.trim();
    const cifNif = document.getElementById('edit-customer-cif').value.trim();
    const address = document.getElementById('edit-customer-address').value.trim();
    const postalCode = document.getElementById('edit-customer-postal').value.trim();
    const email = document.getElementById('edit-customer-email').value.trim();

    if (!phone && !businessName && !cifNif && !address && !email) {
      Swal.fire({
        icon: 'warning',
        title: '<?php echo ruiyi_translate('Campo requerido', 'Required field', '必填字段'); ?>',
        text: '<?php echo ruiyi_translate('Introduce al menos un dato del cliente', 'Enter at least one customer field', '请至少输入一项客户信息'); ?>'
      });
      return;
    }

    const formData = new FormData();
    formData.append('nonce', posNonce);
    formData.append('name', phone || businessName || cifNif || address);
    formData.append('phone', phone);
    formData.append('business_name', businessName);
    formData.append('cif_nif', cifNif);
    formData.append('address', address);
    formData.append('postal_code', postalCode);
    formData.append('email', email);

    if (customerId) {
      // 更新现有客户
      formData.append('action', 'ruiyi_update_customer');
      formData.append('customer_id', customerId);
    } else {
      // 创建新客户
      formData.append('action', 'ruiyi_create_customer_info');
    }

    // 显示保存中状态
    const saveBtn = document.getElementById('save-customer-btn');
    const originalText = saveBtn.innerHTML;
    saveBtn.innerHTML = '<i class="fas fa-spinner fa-spin mr-2"></i><?php echo ruiyi_translate('Guardando...', 'Saving...', '保存中...'); ?>';
    saveBtn.disabled = true;

    fetch(ajaxUrl, {
      method: 'POST',
      body: formData
    })
    .then(response => response.json())
    .then(data => {
      saveBtn.innerHTML = originalText;
      saveBtn.disabled = false;

      if (data.success) {
        closeCustomerModal();
        loadCustomers();

        Toastify({
          text: '✅ <?php echo ruiyi_translate('Cliente guardado', 'Customer saved', '客户已保存'); ?>',
          duration: 2000,
          gravity: "top",
          position: "center",
          style: { background: "#10b981" }
        }).showToast();
      } else {
        Swal.fire({
          icon: 'error',
          title: '<?php echo ruiyi_translate('Error', 'Error', '错误'); ?>',
          text: data.data?.message || '<?php echo ruiyi_translate('Error al guardar', 'Save error', '保存失败'); ?>'
        });
      }
    })
    .catch(error => {
      saveBtn.innerHTML = originalText;
      saveBtn.disabled = false;
      console.error('[客户管理] 保存失败:', error);
      Swal.fire({
        icon: 'error',
        title: '<?php echo ruiyi_translate('Error', 'Error', '错误'); ?>',
        text: '<?php echo ruiyi_translate('Error de red', 'Network error', '网络错误'); ?>'
      });
    });
  }

  // 确认删除客户
  function confirmDelete(customerId, customerName) {
    Swal.fire({
      title: '<?php echo ruiyi_translate('¿Eliminar cliente?', 'Delete customer?', '确认删除客户？'); ?>',
      text: `<?php echo ruiyi_translate('¿Estás seguro de eliminar a', 'Are you sure you want to delete', '确定要删除'); ?> "${customerName}"?`,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#dc2626',
      cancelButtonColor: '#6b7280',
      confirmButtonText: '<?php echo ruiyi_translate('Sí, eliminar', 'Yes, delete', '确认删除'); ?>',
      cancelButtonText: '<?php echo ruiyi_translate('Cancelar', 'Cancel', '取消'); ?>'
    }).then((result) => {
      if (result.isConfirmed) {
        performDelete(customerId);
      }
    });
  }

  // 执行删除
  function performDelete(customerId) {
    const formData = new FormData();
    formData.append('action', 'ruiyi_delete_customer');
    formData.append('nonce', posNonce);
    formData.append('customer_id', customerId);

    fetch(ajaxUrl, {
      method: 'POST',
      body: formData
    })
    .then(response => response.json())
    .then(data => {
      if (data.success) {
        closeCustomerModal();
        loadCustomers();

        Toastify({
          text: '✅ <?php echo ruiyi_translate('Cliente eliminado', 'Customer deleted', '客户已删除'); ?>',
          duration: 2000,
          gravity: "top",
          position: "center",
          style: { background: "#10b981" }
        }).showToast();
      } else {
        Swal.fire({
          icon: 'error',
          title: '<?php echo ruiyi_translate('Error', 'Error', '错误'); ?>',
          text: data.data?.message || '<?php echo ruiyi_translate('Error al eliminar', 'Delete error', '删除失败'); ?>'
        });
      }
    })
    .catch(error => {
      console.error('[客户管理] 删除失败:', error);
      Swal.fire({
        icon: 'error',
        title: '<?php echo ruiyi_translate('Error', 'Error', '错误'); ?>',
        text: '<?php echo ruiyi_translate('Error de red', 'Network error', '网络错误'); ?>'
      });
    });
  }

  // 从模态框删除客户按钮
  function deleteCustomer() {
    const customerId = document.getElementById('edit-customer-id').value;
    const customerPhone = document.getElementById('edit-customer-phone').value; // 🔥 使用电话作为标识
    if (customerId) {
      confirmDelete(parseInt(customerId), customerPhone);
    }
  }

  // HTML转义
  function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  // 初始化
  document.addEventListener('DOMContentLoaded', initCustomerManagement);

  // 暴露给全局
  window.customerManagement = {
    loadCustomers: loadCustomers,
    editCustomer: editCustomer,
    confirmDelete: confirmDelete
  };

})();
// ==================== End 客户管理模块 ====================

</script>

