<!-- 🔥🔥🔥 WebSocket 正式版：pos-hub 持久连接，接收用户扫码点餐实时推送 -->
<script>
(function() {
  'use strict';

  // 确保 Socket.IO 已加载（兼容电子秤已加载的情况）
  if (typeof io === 'undefined') {
    var s = document.createElement('script');
    s.src = 'https://cdn.socket.io/4.7.5/socket.io.min.js';
    s.onload = function() { console.log('[POS-WS] Socket.IO 库已动态加载'); _initPosHub(); };
    document.head.appendChild(s);
  } else {
    _initPosHub();
  }

  function _initPosHub() {
    if (typeof io === 'undefined') { console.error('[POS-WS] Socket.IO 不可用'); return; }

    var POS_HUB_URL = 'https://srv985735.hstgr.cloud';

    var posSocket = io(POS_HUB_URL + '/pos-tables', {
      path: '/pos-hub/socket.io/',
      transports: ['websocket', 'polling'],
      query: { clientType: 'pos', site_id: '<?php echo get_current_blog_id(); ?>' },
      reconnection: true,
      reconnectionAttempts: Infinity,
      reconnectionDelay: 1000,
      reconnectionDelayMax: 30000,
      randomizationFactor: 0.5,
      timeout: 10000
    });

    // ── 连接状态指示器 ─────────────────────────
    function updateWsStatus(status) {
      var el = document.getElementById('pos-ws-status');
      if (!el) {
        el = document.createElement('div');
        el.id = 'pos-ws-status';
        el.style.cssText = 'position:fixed;bottom:10px;right:10px;z-index:9999;padding:4px 10px;border-radius:12px;font-size:11px;opacity:0.8;pointer-events:none;transition:all 0.3s;';
        document.body.appendChild(el);
      }
      if (status === 'connected') {
        el.textContent = 'WS \u2713'; el.style.background = '#22c55e'; el.style.color = '#fff';
        setTimeout(function() { el.style.opacity = '0.3'; }, 3000);
      } else if (status === 'reconnecting') {
        el.style.opacity = '0.8'; el.textContent = 'WS ...'; el.style.background = '#f59e0b'; el.style.color = '#fff';
      } else {
        el.style.opacity = '0.8'; el.textContent = 'WS \u2717'; el.style.background = '#ef4444'; el.style.color = '#fff';
      }
    }

    posSocket.on('connect', function() {
      console.log('[POS-WS] ✅ 已连接, socketId:', posSocket.id);
      updateWsStatus('connected');
    });

    // ── 核心：处理用户扫码点餐的订单推送 ─────────
    var CURRENT_SITE_ID = '<?php echo get_current_blog_id(); ?>';

    // 🔥 去重集合：同一 orderId+version 只处理一次（防止 WS + HTTP push 双重触发）
    var _wsNotifiedOrders = {};
    // 🔥 POS 自身创建的订单 ID 集合（不显示通知）
    window._posCreatedOrderIds = window._posCreatedOrderIds || {};

    posSocket.on('order:created', function(data) {
      console.log('[POS-WS] 🔔 收到订单通知:', data);

      // 🔥 多站点隔离：仅处理本站点的订单事件（无site_id的事件也拒绝）
      if (!data.site_id || String(data.site_id) !== CURRENT_SITE_ID) {
        console.log('[POS-WS] 跳过非本站点的订单, site_id:', data.site_id, '当前站点:', CURRENT_SITE_ID);
        return;
      }

      // 🔥【2026-04-03】去重：同一订单只通知一次（WS 和 HTTP push 都会触发 order:created）
      var _dedupeKey = String(data.orderId) + '_' + (data.version || '');
      if (_wsNotifiedOrders[_dedupeKey]) {
        console.log('[POS-WS] ⏭️ 跳过重复通知:', _dedupeKey);
        return;
      }
      _wsNotifiedOrders[_dedupeKey] = Date.now();
      // 清理超过60秒的旧记录
      Object.keys(_wsNotifiedOrders).forEach(function(k) {
        if (Date.now() - _wsNotifiedOrders[k] > 60000) delete _wsNotifiedOrders[k];
      });

      // 🔥【2026-04-03】过滤 POS 自身创建的订单 — 不需要通知自己
      // 方式1: orderId 精确匹配
      if (window._posCreatedOrderIds && window._posCreatedOrderIds[String(data.orderId)]) {
        console.log('[POS-WS] ⏭️ 跳过 POS 自身创建的订单通知(ID匹配):', data.orderId);
        delete window._posCreatedOrderIds[String(data.orderId)];
        return;
      }
      // 方式2: 时间窗口 — POS 在过去10秒内发起了创建订单请求
      if (window._posCreatingOrder && (Date.now() - window._posCreatingOrder) < 10000) {
        console.log('[POS-WS] ⏭️ 跳过 POS 自身创建的订单通知(时间窗口):', data.orderId);
        return;
      }

      try {
        var mesasEstado = JSON.parse(localStorage.getItem('mesas_estado') || '{}');

        // 标准化桌号格式为 "Mesa X"
        var tableRaw = data.table || '';
        var tableNumeric = resolveGlobalTableNumber(tableRaw);
        var mesaKey = 'Mesa ' + tableNumeric;

        if (!tableNumeric || !data.orderId) {
          console.warn('[POS-WS] 数据不完整，跳过:', data);
          return;
        }

        // 🔥🔥🔥 【2026-03-29 关键修复】如果桌位刚刚结账（15秒内），忽略 order:created 事件
        // 防止 AA 结账后 POS-Hub 广播的合并订单事件将桌位重新标记为 ocupada
        var checkedOutAt = window._recentlyCheckedOutTables && window._recentlyCheckedOutTables[tableNumeric];
        if (checkedOutAt && (Date.now() - checkedOutAt) < 15000) {
          console.warn('[POS-WS] 🛡️ 桌位', mesaKey, '刚结账（' + Math.round((Date.now() - checkedOutAt)/1000) + '秒前），忽略 order:created 事件');
          return;
        }

        // 检测是否为追加订单
        var existingData = mesasEstado[mesaKey] || {};
        // 🔥 修复：使用 String() 统一类型后比较，防止 number vs string 类型不匹配导致误判
        var isAppendOrder = existingData.orderId && String(existingData.orderId) === String(data.orderId)
          && existingData.version && data.version
          && String(existingData.version) !== String(data.version);
        // 服务端明确标记 is_merged 时始终按追加处理。
        // localStorage 可能因刷新、无痕、超时恢复而缺少旧桌位状态，不能因此改走整单未打印扫描。
        if (!isAppendOrder && data.is_merged) {
          isAppendOrder = true;
        }

        // ── 1. 打印去重检查 ──────────────────
        var printedOrders = JSON.parse(localStorage.getItem('printed_kitchen_orders') || '[]');
        var printKeyWithVersion = data.orderId + '_' + (data.version || 'v0');
        var alreadyPrinted = printedOrders.indexOf(printKeyWithVersion) !== -1;

        // ── 2. 更新 mesas_estado ─────────────
        mesasEstado[mesaKey] = {
          estado: 'ocupada',
          orderId: data.orderId,
          timestamp: new Date().toISOString(),
          total: data.total || 0,
          version: data.version || (Date.now() + '_0000'),
          orderCount: data.is_merged ? ((existingData.orderCount || 0) + 1) : 1,
          last_updated: Date.now(),
          _skipAutoUpdate: true  // 防止下一次轮询覆盖这条新鲜数据
        };
        localStorage.setItem('mesas_estado', JSON.stringify(mesasEstado));
        console.log('[POS-WS] 已更新 mesas_estado:', mesaKey);

        // ── 3. 立即刷新桌位 UI ──────────────
        if (typeof renderizarMesas === 'function') {
          renderizarMesas('websocket-order-created');
        }

        // ── 4. 厨房打印（入队）──────────
        // WebSocket order:created 是明确的新订单信号，只要 CLODOP 已配置就应触发打印
        // 不依赖 enablePollingKitchenPrint（该设置仅控制轮询路径）
        var _canPrint = window.clodopConfig && window.clodopConfig.enabled && window.clodopConfig.kitchenPrinter;
        console.log('[POS-WS] 🖨️ 打印检查:', {
            clodopEnabled: !!(window.clodopConfig && window.clodopConfig.enabled),
            kitchenPrinter: window.clodopConfig?.kitchenPrinter || '(未设置)',
            alreadyPrinted: alreadyPrinted,
            printKey: printKeyWithVersion,
            canPrint: _canPrint && !alreadyPrinted
        });
        if (_canPrint && !alreadyPrinted) {
          console.log('[POS-WS] 🖨️ 加入打印队列:', mesaKey, '#' + data.orderId, isAppendOrder ? '(追加)' : '(新订单)');
          if (typeof enqueueKitchenPrint === 'function') {
            enqueueKitchenPrint(mesaKey, data.orderId, data.version, null, isAppendOrder || false);
          }
        }

        // ── 5. Toast 通知（不阻塞操作）──────
        if (typeof Toastify !== 'undefined') {
          Toastify({
            text: (data.is_merged ? '📦 追加订单' : '🔔 新订单') + ' - ' + mesaKey + ' #' + data.orderId + ' €' + (data.total || 0),
            duration: 5000,
            gravity: 'top',
            position: 'right',
            style: {
              background: data.is_merged
                ? 'linear-gradient(to right, #f59e0b, #d97706)'
                : 'linear-gradient(to right, #22c55e, #16a34a)',
              fontWeight: 'bold',
              fontSize: '14px',
              borderRadius: '8px',
              boxShadow: '0 4px 12px rgba(0,0,0,0.15)'
            }
          }).showToast();
        }

      } catch (err) {
        console.error('[POS-WS] 处理 order:created 出错:', err);
      }
    });

    // 🍽️ 自助餐仅厨房打印（无WC订单，由客户/服务员页面发送）
    posSocket.on('buffet:kitchen_print', function(data) {
      console.log('[POS-WS] 🍽️ 收到自助餐厨房打印请求:', data);

      if (!data.site_id || String(data.site_id) !== CURRENT_SITE_ID) return;
      if (!data.items || !data.items.length || !data.table) return;

      try {
        var tableRaw = data.table || '';
        var tableNumeric = resolveGlobalTableNumber(tableRaw);
        var mesaKey = 'Mesa ' + tableNumeric;

        // 直接将自助餐商品加入厨房打印队列
        if (window.clodopConfig && window.clodopConfig.enabled && window.clodopConfig.kitchenPrinter
            && typeof enqueueKitchenPrint === 'function') {
          // 存储临时打印数据到 localStorage 供打印函数读取
          var printData = {
            items: data.items.map(function(item) {
              return {
                name: item.name || 'Buffet',
                quantity: item.quantity || 1,
                notes: item.notes || '',
                is_buffet: true
              };
            }),
            table: mesaKey,
            timestamp: Date.now()
          };
          // 使用特殊key存储，打印函数可以读取
          localStorage.setItem('buffet_direct_print_' + tableNumeric, JSON.stringify(printData));
          enqueueKitchenPrint(mesaKey, 'buffet_' + Date.now(), 'direct_' + Date.now(), null, false);
          console.log('[POS-WS] 🖨️ 自助餐商品已加入打印队列:', mesaKey, data.items.length + '个商品');
        }

        // Toast 通知
        if (typeof Toastify !== 'undefined') {
          Toastify({
            text: '🍽️ 自助餐厨房打印 - ' + mesaKey + ' (' + data.items.length + '个商品)',
            duration: 4000,
            gravity: 'top',
            position: 'right',
            style: {
              background: 'linear-gradient(to right, #f59e0b, #d97706)',
              fontWeight: 'bold',
              fontSize: '14px',
              borderRadius: '8px',
              boxShadow: '0 4px 12px rgba(0,0,0,0.15)'
            }
          }).showToast();
        }
      } catch (err) {
        console.error('[POS-WS] 处理 buffet:kitchen_print 出错:', err);
      }
    });

    // ── 连接事件 ─────────────────────────────
    posSocket.on('connect_error', function(err) {
      console.warn('[POS-WS] ❌ 连接失败:', err.message);
      updateWsStatus('disconnected');
    });

    posSocket.on('disconnect', function(reason) {
      console.warn('[POS-WS] 🔌 连接断开:', reason);
      updateWsStatus('disconnected');
    });

    posSocket.io.on('reconnect_attempt', function(attempt) {
      console.log('[POS-WS] 重连尝试 #' + attempt);
      updateWsStatus('reconnecting');
    });

    posSocket.io.on('reconnect', function(attempt) {
      console.log('[POS-WS] ✅ 重连成功 (第' + attempt + '次尝试)');
      updateWsStatus('connected');
      // 重连后立即补一次轮询，捕获断线期间可能遗漏的更新
      if (typeof fetchAndUpdateTableStatuses === 'function') {
        setTimeout(fetchAndUpdateTableStatuses, 500);
      }
    });

    posSocket.io.on('reconnect_failed', function() {
      console.error('[POS-WS] ❌ 重连彻底失败');
      updateWsStatus('disconnected');
    });

    // 暴露到全局方便调试
    window._posHubSocket = posSocket;
    console.log('[POS-WS] 🚀 WebSocket 监听已启动，等待用户扫码点餐通知...');
  }
})();
</script>

<script>
// 清理每日刷新后 URL 中的 _refresh 参数
if (window.location.search.includes('_refresh=')) {
    var cleanUrl = window.location.href.replace(/[?&]_refresh=\d+/, '').replace(/\?$/, '');
    window.history.replaceState({}, '', cleanUrl);
}
