        <div class="grid grid-cols-3 gap-3">
          <?php
            $sup_cat_map_modal = json_decode(get_option('pos_supplement_category_map', '{}'), true);
            if (!is_array($sup_cat_map_modal)) $sup_cat_map_modal = [];
          ?>
          <?php foreach ($suplementos_products as $sup_product):
            $sup_id = $sup_product->get_id();
            $sup_name = $sup_product->get_name();
            $sup_name_zh = get_post_meta($sup_id, '_product_name_zh', true);
            $sup_name_en = get_post_meta($sup_id, '_product_name_en', true);
            $sup_price = $sup_product->get_price();
            $sup_mapped_cats = isset($sup_cat_map_modal[$sup_id]) ? array_values(array_map('intval', (array)$sup_cat_map_modal[$sup_id])) : [];
          ?>
          <button type="button"
                  class="supplement-option flex flex-col items-center justify-center p-3 rounded-xl border-2 border-gray-200 dark:border-gray-600 hover:border-green-400 hover:bg-green-50 dark:hover:bg-green-900/20 transition-all text-center"
                  data-sup-id="<?php echo esc_attr($sup_id); ?>"
                  data-sup-name="<?php echo esc_attr($sup_name); ?>"
                  data-sup-name-zh="<?php echo esc_attr($sup_name_zh); ?>"
                  data-sup-name-en="<?php echo esc_attr($sup_name_en); ?>"
                  data-sup-price="<?php echo esc_attr($sup_price); ?>"
                  data-sup-categories="<?php echo esc_attr(json_encode($sup_mapped_cats)); ?>"
                  onclick="toggleSupplement(this)">
            <span class="font-medium text-sm text-gray-800 dark:text-gray-200 leading-tight"><?php echo esc_html($sup_name); ?></span>
            <?php if ($sup_name_zh): ?>
            <span class="text-xs text-gray-500 dark:text-gray-400 mt-0.5"><?php echo esc_html($sup_name_zh); ?></span>
            <?php endif; ?>
            <span class="text-green-600 font-bold text-sm mt-1">+<?php echo esc_html(number_format((float)$sup_price, 2)); ?>€</span>
          </button>
          <?php endforeach; ?>
        </div>
      </div>
      <!-- Footer -->
      <div class="px-6 py-4 border-t border-gray-200 dark:border-gray-700 flex items-center justify-between">
        <div id="supplements-modal-total" class="text-sm text-gray-600 dark:text-gray-400"></div>
        <button onclick="closeSupplementsModal()" class="px-6 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg font-medium transition-colors">
          <?php echo ruiyi_translate('Confirmar', 'Confirm', '确认'); ?>
        </button>
      </div>
    </div>
  </div>
</div>

<script>
(function() {
    var supplementsModalIndex = null;

    function getCartItemCategoryIds(item) {
        var raw = item.categoryIds || item.category_ids || item.categories || item.category_id || [];
        if (typeof raw === 'string') {
            raw = raw.split(/[,\s]+/);
        } else if (!Array.isArray(raw)) {
            raw = [raw];
        }
        return raw.map(function(id) { return parseInt(id, 10); }).filter(function(id) { return id > 0; });
    }

    function normalizeSupplementCategoryIds(raw) {
        if (typeof raw === 'string') {
            try { raw = JSON.parse(raw || '[]'); } catch(e) { raw = raw.split(/[,\s]+/); }
        }
        if (!Array.isArray(raw)) raw = [];
        return raw.map(function(id) { return parseInt(id, 10); }).filter(function(id) { return id > 0; });
    }

    window.openSupplementsModal = function(cartIndex) {
        var modal = document.getElementById('supplements-modal');
        if (!modal || !cart[cartIndex]) return;
        supplementsModalIndex = cartIndex;
        var item = cart[cartIndex];

        // 显示当前产品原始名称（不含 supplements）
        // _originalName 保存不带 supplements 的名称
        var baseName = item._originalName || item.name || '';
        document.getElementById('supplements-modal-item-name').textContent = baseName;

        // 初始化 supplements 数组
        if (!item.supplements) item.supplements = [];

        // 🔥 按分类筛选并更新已选中状态
        var itemCats = getCartItemCategoryIds(item);
        var buttons = modal.querySelectorAll('.supplement-option');
        var visibleCount = 0;
        buttons.forEach(function(btn) {
            var supId = btn.getAttribute('data-sup-id');
            // 🔥 分类筛选：如果配料有指定分类，则只在产品属于该分类时显示
            var supCats = normalizeSupplementCategoryIds(btn.getAttribute('data-sup-categories') || '[]');
            if (supCats.length > 0) {
                var hasMatch = itemCats.length > 0 && supCats.some(function(c) { return itemCats.indexOf(c) >= 0; });
                btn.style.display = hasMatch ? '' : 'none';
            } else {
                btn.style.display = ''; // 没有分类限制 → 对所有产品显示
            }
            if (btn.style.display !== 'none') visibleCount++;
            var isSelected = item.supplements.some(function(s) { return String(s.id) === String(supId); });
            if (isSelected) {
                btn.classList.add('border-green-500', 'bg-green-50', 'dark:bg-green-900/30', 'ring-2', 'ring-green-300');
                btn.classList.remove('border-gray-200', 'dark:border-gray-600');
            } else {
                btn.classList.remove('border-green-500', 'bg-green-50', 'dark:bg-green-900/30', 'ring-2', 'ring-green-300');
                btn.classList.add('border-gray-200', 'dark:border-gray-600');
            }
        });

        var grid = modal.querySelector('.supplement-option') ? modal.querySelector('.supplement-option').parentElement : null;
        var empty = modal.querySelector('.supplement-empty-message');
        if (!empty && grid) {
            empty = document.createElement('div');
            empty.className = 'supplement-empty-message col-span-3 text-center text-sm text-gray-400 py-6 hidden';
            empty.textContent = '<?php echo esc_js(ruiyi_translate("No hay suplementos para esta categoría", "No supplements for this category", "此分类没有可用 Suplementos")); ?>';
            grid.appendChild(empty);
        }
        if (empty) empty.classList.toggle('hidden', visibleCount > 0);

        updateSupplementsModalTotal();
        modal.classList.remove('hidden');
    };

    window.closeSupplementsModal = function(e) {
        if (e && e.target !== e.currentTarget) return;
        // 🔥 关闭前将 supplements 合入 customName 和 customPrice
        if (supplementsModalIndex !== null && cart[supplementsModalIndex]) {
            var item = cart[supplementsModalIndex];
            var sups = item.supplements || [];
            // 保存原始名称和价格（首次）
            // 🔥 对于锁定产品，使用 customPrice（实际订单价格，可能含分区价）作为基础价
            if (!item._originalName) item._originalName = item.name || '';
            if (item._originalPrice === undefined) {
                item._originalPrice = parseFloat(item.customPrice !== undefined && item.customPrice !== null ? item.customPrice : (item.price || 0));
            }

            if (sups.length > 0) {
                var supTotal = sups.reduce(function(s, sup) { return s + parseFloat(sup.price || 0); }, 0);
                var supNames = ' + ' + sups.map(function(s) { return s.name; }).join(' + ');
                item.customName = item._originalName + supNames;
                item.customPrice = item._originalPrice + supTotal;
            } else {
                // 移除所有 supplements 时还原
                delete item.customName;
                delete item.customPrice;
            }
            // 🔥 锁定产品修改配料后，标记购物车已修改，确保保存订单时同步到服务器
            if (item.locked) {
                window.cartModified = true;
            }
        }
        var modal = document.getElementById('supplements-modal');
        if (modal) modal.classList.add('hidden');
        supplementsModalIndex = null;
        renderCart();
    };

    window.toggleSupplement = function(btn) {
        if (supplementsModalIndex === null || !cart[supplementsModalIndex]) return;
        var item = cart[supplementsModalIndex];
        if (!item.supplements) item.supplements = [];

        var supId = btn.getAttribute('data-sup-id');
        var supPrice = parseFloat(btn.getAttribute('data-sup-price') || 0);

        // 获取多语言名称
        var lang = (window.RUIYI_POS?.currentLang) || 'zh';
        var supName;
        switch (lang) {
            case 'zh': supName = btn.getAttribute('data-sup-name-zh') || btn.getAttribute('data-sup-name'); break;
            case 'en': supName = btn.getAttribute('data-sup-name-en') || btn.getAttribute('data-sup-name'); break;
            default:   supName = btn.getAttribute('data-sup-name'); break;
        }

        var existingIndex = -1;
        for (var i = 0; i < item.supplements.length; i++) {
            if (String(item.supplements[i].id) === String(supId)) {
                existingIndex = i;
                break;
            }
        }

        if (existingIndex >= 0) {
            // 移除
            item.supplements.splice(existingIndex, 1);
            btn.classList.remove('border-green-500', 'bg-green-50', 'dark:bg-green-900/30', 'ring-2', 'ring-green-300');
            btn.classList.add('border-gray-200', 'dark:border-gray-600');
        } else {
            // 添加
            item.supplements.push({ id: supId, name: supName, price: supPrice });
            btn.classList.add('border-green-500', 'bg-green-50', 'dark:bg-green-900/30', 'ring-2', 'ring-green-300');
            btn.classList.remove('border-gray-200', 'dark:border-gray-600');
        }

        updateSupplementsModalTotal();
    };

    function updateSupplementsModalTotal() {
        var el = document.getElementById('supplements-modal-total');
        if (!el || supplementsModalIndex === null || !cart[supplementsModalIndex]) return;
        var item = cart[supplementsModalIndex];
        var sups = item.supplements || [];
        if (sups.length === 0) {
            el.textContent = '<?php echo ruiyi_translate("Sin suplementos", "No supplements", "未添加 suplemento"); ?>';
        } else {
            var total = sups.reduce(function(sum, s) { return sum + parseFloat(s.price || 0); }, 0);
            el.innerHTML = '<i class="fas fa-check-circle text-green-500 mr-1"></i>' + sups.length + ' suplemento(s): <strong>+' + total.toFixed(2) + '€</strong>';
        }
    }
})();
</script>
<?php endif; ?>

<?php wp_footer(); ?>

</body>
</html>
